import type ItemBase from './ItemBase';

export type IOrderDirection =
    | 'ascending'
    | 'descending';

export type IItemOrderHash = string;

/**
 * Structure used to sort the items once loaded.
 */
export interface IItemOrder<LocalType extends ItemBase> {
    /**
     * Hash that can be used to uniquely identify this sorting order.
     * This hash is used for caching in the ItemSource implementation.
     */
    readonly hash: IItemOrderHash;
    readonly direction: IOrderDirection;

    /**
     * Sorts the items inplace using the sorting order.
     * @param items to be sorted inplace.
     */
    sortItems(items: LocalType[]): void;
}

export function compareStrings(a: string, b: string): number {
    return a.localeCompare(b);
}

export function compareValues<T>(a: T, b: T): number {
    if (a === b) {
        return 0;
    }
    return a < b ? -1 : 1;
}

export type ComparatorFn<LocalType extends ItemBase> = (a: LocalType, b: LocalType) => number;

export type IComparatorMap<LocalType extends ItemBase, IOrderField extends string> = {
    [key in IOrderField]: ComparatorFn<LocalType>;
}

function reverseComparator<LocalType extends ItemBase>(comparator: ComparatorFn<LocalType>) {
    return (a: LocalType, b: LocalType) => -comparator(a, b);
}

class ItemOrder<LocalType extends ItemBase, IOrderField> implements IItemOrder<LocalType> {
    constructor(
        readonly direction: IOrderDirection,
        readonly field: IOrderField,
        readonly comparator: ComparatorFn<LocalType>) {
    }

    get hash(): IItemOrderHash {
        return this.direction + ':' + this.field;
    }

    sortItems(items: LocalType[]): void {
        items.sort(this.comparator);
    }
}

export function createItemOrderFactory<LocalType extends ItemBase, IOrderField extends string>(
    comparatorMap: IComparatorMap<LocalType, IOrderField>) {

    return class extends ItemOrder<LocalType, IOrderField> {
        constructor(direction: IOrderDirection, field: IOrderField) {
            let comparator = comparatorMap[field];
            if (direction === 'descending') {
                comparator = reverseComparator(comparator);
            }
            super(direction, field, comparator);
        }
    };
}
