import type { Action } from '../../models/Action';

import { extractGroupId } from '../../utils/PathUtils';
import type { ExecuteResult } from '../Operation';
import Operation, { validatesOperation } from '../Operation';
import type LocalDriver from '.';

export default class MoveCopyGroupOperation extends Operation<LocalDriver> {
    private get action() {
        return this._actions[0];
    }

    supportsAction(action: Action) {
        return [ 'moveGroup', 'copyGroup', 'dependent' ].includes(action.name as string);
    }

    addAction(action: Action) {
        if (!this.supportsAction(action)) {
            return false;
        }

        const lastAction = this._actions[this._actions.length - 1];

        if (!lastAction && action.name !== 'dependent') {
            return super.addAction(action);
        }

        if (action.name !== 'dependent') {
            return false;
        }

        return super.addAction(action);
    }

    @validatesOperation
    async execute(): Promise<ExecuteResult> {
        const isMove = this.action.name === 'moveGroup';

        const sourceId = this._library.id;
        const targetLibrary = this.action.link?.library;
        const targetId = targetLibrary?.id;
        const groupId = extractGroupId(this.action.path as string);

        const response = await this._driver.fetch(`/libraries/${targetId}/groups`, {
            method: 'POST',
            headers: {
                'If-Match': targetLibrary?.etag as string
            },
            body: JSON.stringify({
                [isMove ? 'self' : 'source']: {
                    id: sourceId,
                    group_id: groupId,
                    include_contents: this.action.flags?.includeElements,
                    etag: this._library.etag
                }
            })
        });
        const newGroupData = await response.json();
        let linkedActions: Action[];
        let actions: Action[];

        if (targetLibrary === this._library) {
            linkedActions = [];
            actions = this._actions.map(action => {
                if (action.name !== 'dependent') {
                    return action;
                }
                return {
                    ...action,
                    data: newGroupData,
                    originalAction: action
                };
            });
        } else {
            actions = this._actions;
            linkedActions = this._actions.map(action => ({
                ...action.link,
                data: newGroupData,
                originalAction: action.link
            })) as Action[];
        }

        // If this operation succeeds, we wait for the change notification to update the target library.
        // This operation is only performed optimistically on the source library for now. The reason for this
        // is that the moveGroup/copyGroup APIs do not provide us the feedback needed to display and reconcile
        // the optimistic state on that target library. This may change in the future.

        // The result of this is that there will be a lag between when the elements disappear from one library
        // and appear in the other. This is considered an acceptable compromise in the short-term.

        // linkedEtag intentionally left blank, because we are relying on the pull to update the library to the
        // correct state.
        return { actions, etag: response.headers.get('Source-ETag') as string, linkedActions };
    }
}
