import type { LibraryData } from '../interface/LibraryModel';
import type { ISAMObject } from '../core/ISAMObject';
import { NotFound } from '../core/PropertyUpdater';

/**
 * These utility functions are for the LibraryUpdater.
 *
 * class ShareableItem uses _shareFlagsAreDirty to decide when
 * to lazy load all of {  _isShared, _isSharedWithYouAsset,
 * _isPublicLink, _directCollaboratorCount } with a service
 * call to an Invitation Service endpoint.
 *
 * Melville uses the same endpoint to initialize its internal
 * data, and when a Melville request includes selector='collaboration',
 * the response will include collaboration data.
 *
 * Due to Melville re-arranging the data, a Melville Collaborator
 * is not the same data as an Invitation Service Collaborator,
 * so class Library cannot use the data to set ShareableItem._collaborationArray.
 *
 * But there is enough equivalent data for LibraryUpdater
 * to update all of the above properties and clear their dirty flag
 * when the optional collaboration data is present. When it's absent,
 * these getters return NotFound, so the ShareableItem properties
 * will be untouched by the update.
 */
export function getLibraryIsShared(value: Partial<LibraryData>): boolean | typeof NotFound {
    if (value.collaboration) {
        // CollaborationContext._handleBatchRequest() injects isDirect:true
        // into Invitation Service Collaborator's being constructed for
        // directCollaborators.

        // DbLibraryCollaborationData.getFilteredCollaborators()
        // ( in Melville source ) sets inheritanceType:'DIRECT' for the
        // same condition.
        //
        // So the below handling of Melville Data is equivalent to
        // ShareableItem._setCollaboratorData()'s handling of
        // Invitation Service Data.

        const collaborators = value.collaboration.collaborators;

        return collaborators.some((collaborator) => {
            return (collaborator.inheritanceType === 'DIRECT');
        });
    }

    // When the response omits collaboration[], don't set ShareableItem properties
    return NotFound;
}

export function getLibraryIsSharedWithYouAsset(value: Partial<LibraryData>, dest: ISAMObject): boolean | typeof NotFound {
    if (value.collaboration) {
        // See above comment in getLibraryIsShared() to explain
        // collaborator.inheritanceType.
        //
        // Collaborator.imsUserId return this.id for imsUser's,
        // and this._additionalData?.linkedIdentity otherwise.
        //
        // DbLibraryCollaboratorData.getCollaborator() ( in Melville source )
        // returns an imsUser's id, or additionalData.linkedIdentity
        // for an Address Book Contact's.
        //
        // DbLibraryCollaborationData.getFilteredCollaborators() filters
        // the list to only be imsUser's or Address Book Contact.
        //
        // So the below handling of Melville Data is equivalent to
        // ShareableItem._setCollaboratorData()'s handling of
        // Invitation Service Data.

        const currentUser = dest._core._environment.getValue('USER_ID');
        const collaborators = value.collaboration.collaborators;

        return collaborators.some((collaborator) => {
            return (collaborator.inheritanceType === 'DIRECT') && (collaborator.collaborator === currentUser);
        });
    }

    // When the response omits collaboration[], don't set ShareableItem properties
    return NotFound;
}

// If the library is shared with you, we still want to know if it's public.
export function getLibraryIsPublicLink(value: Partial<LibraryData>): boolean | typeof NotFound {
    if (value.collaboration) {
        // Melville's already determined if the library has a public link.

        return !!value.collaboration.public;
    }

    // When the response omits collaboration[], don't set ShareableItem properties
    return NotFound;
}

export function getLibraryDirectCollaboratorCount(value: Partial<LibraryData>): number | typeof NotFound {
    if (value.collaboration) {
        // See above comment in getLibraryIsShared() to explain
        // collaborator.inheritanceType, but this should be
        // equivalent to ShareableItem._setCollaboratorData(),
        // as we are counting the number of direct collaborators.

        const collaborators = value.collaboration.collaborators;

        return collaborators.filter((collaborator) => (collaborator.inheritanceType === 'DIRECT')).length;
    }

    // When the response omits collaboration[], don't set ShareableItem properties
    return NotFound;
}

export function getLibraryShareFlagsAreDirty(value: Partial<LibraryData>): boolean | typeof NotFound {
    if (value.collaboration) {
        // If we've updated the properties (with the above methods),
        // then we need to clear the dirty flag as well.
        return false;
    }

    // When the response omits collaboration[], don't set ShareableItem properties
    return NotFound;
}

