export interface ICollaboratorSources {
    collaboratorPool: ItemPool<Collaborator>,
    collaboratorSource: ItemSource<CollaboratorConfig>,
    invitedCollaboratorPool: ItemPool<InvitedCollaborator>,
    invitedCollaboratorSource: ItemSource<InvitedCollaboratorConfig>
}

export type AssetToCollaborator = {
    id: string;
    collaborator: Collaborator;
}

export default class CollaborationContext implements ISAMObject {

    private _collaboratorSourceMap = new Map<string, ICollaboratorSources>();
    private _invitationInterface = new InvitationInterface(this._core);
    private _collaboratorsByAssetIDPool = new ItemPool<CollaboratorsByAssetID>(this._core, 'collaboratorsByAssetID');
    private _accessConfirmedIDs = new Set<string>();
    private _addressBookPool = new ItemPool<AddressBook>(this._core, 'addressBook');
    // Note: presuming that AddressBookContact is unique to an AddressBook
    private _addressBookContactPoolMap = new Map<string, ItemPool<AddressBookContact>>();
    private _peopleGraphInterface = new PeopleGraphInterface(this._core);
    // Map of access request pools per asset, since access requests are asset-specific
    private _accessRequestPoolMap = new Map<string, ItemPool<AccessRequestItem>>();

    /**
     * @package -- for use in SAM.js only
     */
    readonly _collaboratorRequestQueue: BatchOperationQueue<ShareableItem>;

    constructor(readonly _core: ISAMCorePrivate) {
        this._collaboratorRequestQueue = new BatchOperationQueue<ShareableItem>(this._handleBatchRequest);
    }

    /**
     * @package -- for use in SAM.js only
     */
    public _onONSNotification(event: ONSAssetChangeEvent): void {
        const changedAssets = event.changedAssets;
        changedAssets.forEach((assetInfo, assetId) => {
            const foundAssetSources = this._collaboratorSourceMap.get(assetId);
            const changedResources = assetInfo.changedResources;

            if (!foundAssetSources || !changedResources || !changedResources.includes('api:ac/policy')) {
                return;
            }

            // Refresh the sources
            const collaboratorSource = foundAssetSources.collaboratorSource;
            collaboratorSource.setNeedsRefresh();
            const invitedCollaboratorSource = foundAssetSources.invitedCollaboratorSource;
            invitedCollaboratorSource.setNeedsRefresh();
        });
    }

    private _handleBatchRequest = async (items: Set<ShareableItem>): Promise<void> => {
        const assetMap = new Map([ ...items ].map(item => [ item.id, item ]));
        const batchInvitationResponse: IInvitationShareBatchResponse = await this._invitationInterface.getCollaboratorListForUrns([ ...assetMap.keys() ]);
        const results: IInvitationShareBatchResponseItem[] = batchInvitationResponse.result;
        results.forEach((result: IInvitationShareBatchResponseItem) => {
            const assetId = result.urn;
            const asset = assetMap.get(assetId);
            if (!asset) {
                return;
            }
            if (result.statusCode !== 200) {
                // Reject the item promise so that the item can be fetched again later.
                this._collaboratorRequestQueue.rejectItemPromise(asset);
                return;
            }

            const sources = this._getCollaboratorSources(assetId);
            const invitationResponse: IInvitationShareResponse = JSON.parse(result.response);

            // Add the assetId, isDirect and canDiscover to the returned data.
            const collaboratorsWithAssetIds: IComputedInvitationCollaborator[] = invitationResponse.collaborators.map(
                (collaboratorData: IInvitationCollaborator) => {
                    const isDirectCollaborator = invitationResponse.directCollaborators?.find(
                        (collaborator: IInvitationCollaborator) => collaborator.id === collaboratorData.id
                    );
                    return {
                        ...collaboratorData,
                        assetID: assetId,
                        isDirect: !!isDirectCollaborator,
                        canDiscover: isDirectCollaborator?.canDiscover ?? false
                    };
                }
            );

            const collaboratorUpdateSession = sources.collaboratorPool.createUpdateSession();
            const collaborators = CollaboratorUpdater.updateRemoteItems(collaboratorUpdateSession, collaboratorsWithAssetIds);
            collaboratorUpdateSession.commit();

            asset._setCollaboratorData(collaborators, invitationResponse.collaborationModel);
        });
    };

    /**
     * For use-cases where we want to immediately fetch collaborators but using the batch system
     * instead of the collaborator listing.
     */
    private async _getCollaboratorsNow(asset: ShareableItem): Promise<void> {
        await this._collaboratorRequestQueue.enqueue(asset);
        await this._collaboratorRequestQueue._processNow();
        if (LazyLoadManager.hasManager(asset, SharedCollaboratorChangedEvent)) {
            LazyLoadManager.updatedExternally(asset, SharedCollaboratorChangedEvent);
        } else {
            // SAM.cpp doesn't have LazyLoadManager
            asset.dispatch(SharedCollaboratorChangedEvent);
        }
    }

    /**
     * get a list of Collaborators
     * @param assetsIDs list of assetIDs (including from Teams and Spaces, not just AdobeAssets)
     */
    /**
     * @deprecated -- will be removed on or after 2024-10-01
     *  Use {@link ShareableItem.collaboratorArray} instead.
     */
    getCollaboratorsForAssets(assetsIDs: string[]): CollaboratorsByAssetIDSource {
        oneTimeWarning('getCollaboratorsForAssets',
            'This method is deprecated and will be removed. Use ShareableItem.collaboratorArray instead.');
        const loader = new CollaboratorsByAssetIDLoader(this._collaboratorsByAssetIDPool, this._invitationInterface, assetsIDs);
        const source = new ItemSource<CollaboratorsByAssetIDConfig>(this._collaboratorsByAssetIDPool, [ loader ], new EverythingFilter());
        return source;
    }

    /**
     * Get's all the ItemSources for Collaborators and InvitedCollaborators.
     * @note ItemPools for collaborators can't be shared between assets because they may have different roles per asset.
     * @note This no longer stores and returns WeakRefs due to how we have to update the collaborators, it causes
     * the refs to be reclaimed before we are able to update the collaborators with new information and causes
     * new item pools to be created everytime.
     * @package used internally only
     */
    _getCollaboratorSources(assetID: string): ICollaboratorSources {
        const sources = this._collaboratorSourceMap.get(assetID);
        if (sources) {
            return sources;
        }

        // We cannot share the pools for Collaborator/InvitedCollaborator objects between
        // assets as they might have different roles for the same IDs.
        const collaboratorPool = new ItemPool<Collaborator>(this._core, 'collaborator');
        const collaboratorLoader = new CollaboratorLoader(collaboratorPool, this._invitationInterface, assetID);
        const collaboratorSource = new ItemSource<CollaboratorConfig>(collaboratorPool, [ collaboratorLoader ], new EverythingFilter());

        const invitedCollaboratorPool = new ItemPool<InvitedCollaborator>(this._core, 'invitedCollaborator');
        const invitedCollaboratorLoader = new InvitedCollaboratorLoader(invitedCollaboratorPool, this._invitationInterface, assetID);
        const invitedCollaboratorSource = new ItemSource<InvitedCollaboratorConfig>(invitedCollaboratorPool, [ invitedCollaboratorLoader ], new EverythingFilter());

        const collaboratorSources = { collaboratorPool, collaboratorSource, invitedCollaboratorPool, invitedCollaboratorSource };
        this._collaboratorSourceMap.set(assetID, collaboratorSources);
        return collaboratorSources;
    }

    /**
     * Get the collaborator source for an asset.
     *
     * @note these are no longer deprecated since Modern ShareSheet needs to make use of them
     * and this is temporary until GraphQL is implemented. We don't want to re-invent the wheel.
     *
     *
     * @param assetID The asset ID to get the collaborators for.
     * @returns The collaborator source for the asset.
     */
    public getCollaborators(assetID: string): CollaboratorSource {
        return this._getCollaboratorSources(assetID).collaboratorSource;
    }

    /**
     * Get the invited collaborator source for an asset.
     *
     *
     * @param assetID The asset ID to get the invited collaborators for.
     * @returns The invited collaborator source for the asset.
     */
    public getInvitedCollaborators(assetID: string): InvitedCollaboratorSource {
        return this._getCollaboratorSources(assetID).invitedCollaboratorSource;
    }

    /**
     * @deprecated -- will be renamed for internal use on or after 2024-10-01.
     *   Use {@link ShareableItem.removeCollaborator} instead
     */
    async removeCollaborator(assetID: string, collaborator: Collaborator): Promise<void> {
        oneTimeWarning('CollaborationContext.removeCollaborator',
            'This method is deprecated and will be removed on or after 2024-10-01. Use ShareableItem.removeCollaborator instead.');
        return this._removeCollaborator(assetID, collaborator);
    }

    /**
     * Removes the provided Collaborator and updates the ItemPools.
     *
     * This eventually performs a PATCH request to the invitations service and removes the provided invited
     * collaborator.
     *
     * @package -- for use in SAM.js only
     *
     * @throws If the request is not successful, an error is thrown.
     *
     * @param assetID
     * @param collaborator {Collaborator}
     */
    async _removeCollaborator(assetID: string, collaborator: Collaborator): Promise<void> {
        const response = await this._invitationInterface.modifyCollaborators(
            assetID,
            {
                collaborators: [ { id: collaborator.id, action: 'remove' } ]
            }
        );

        const collaboratorResponse = response.collaborators?.find((c) => c.id === collaborator.id);
        if (!collaboratorResponse) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Collaborator patch request unsuccessful');
        }

        if (collaboratorResponse.statusCode !== 200) {
            throw SAMError.createWithRepositoryCode(
                collaboratorResponse.statusCode,
                collaboratorResponse.errorSubcode ?? '',
                collaboratorResponse.statusText,
                response._bulkRequestId
            );
        }

        const { collaboratorPool } = this._getCollaboratorSources(assetID);
        const updateSession = collaboratorPool.createUpdateSession();
        updateSession.queueDiscardedItem(collaborator);

        // If the current user is being removed from the collaboration list, remove the asset from accessConfirmedIDs
        // in case the user is re-invited to the asset and needs to confirm access again.
        if (collaborator.isCurrentUser) {
            this._accessConfirmedIDs.delete(assetID);
        }
        updateSession.commit();
    }

    /**
     * Removes the provided InvitedCollaborator and updates the ItemPools.
     *
     * This eventually performs a PATCH request to the invitations service and removes the provided invited
     * collaborator.
     *
     * @throws If the request is not successful, an error is thrown.
     *
     * @param assetID
     * @param invitedCollaborator {InvitedCollaborator}
     */
    /**
     * @deprecated -- will be removed on or after 2025-01-01.
     */
    async removeInvitedCollaborator(assetID: string, invitedCollaborator: InvitedCollaborator): Promise<void> {
        oneTimeWarning('CollaborationContext.removeInvitedCollaborator',
            'This method is deprecated and will be removed on or after 2025-01-01.');
        const response = await this._invitationInterface.modifyCollaborators(
            assetID,
            {
                invitations: [ { id: invitedCollaborator.id, action: 'remove' } ]
            }
        );

        const collaboratorResponse = response.invitations?.find((c) => c.id === invitedCollaborator.id);
        if (!collaboratorResponse) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'InvitedCollaborator patch request unsuccessful');
        }

        if (collaboratorResponse.statusCode !== 200) {
            throw SAMError.createWithRepositoryCode(
                collaboratorResponse.statusCode,
                collaboratorResponse.errorSubcode ?? '',
                collaboratorResponse.statusText,
                response._bulkRequestId
            );
        }

        const { invitedCollaboratorPool } = this._getCollaboratorSources(assetID);
        const updateSession = invitedCollaboratorPool.createUpdateSession();
        updateSession.queueDiscardedItem(invitedCollaborator);
        updateSession.commit();
    }

    /**
     * Used by ShareableItem and SAMCpp.ts patches
     *
     * @package -- only for use inside SAM.js
     */
    async _removeCurrentUserFromCollaborationList(asset: ShareableItem): Promise<void> {
        // If collaborator array isn't loaded or needs refresh, load it immediately
        if (!asset._isCollaboratorDataLoaded) {
            await this._getCollaboratorsNow(asset);
        }
        const collaborator = asset.collaboratorArray.find(c => c.isCurrentUser);
        if (!collaborator) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, `Current user is not a collaborator on ${asset.id}`);
        }
        await this._removeCollaborator(asset.id, collaborator);
        // _removeCollaborator() will remove the Collaborator from the pools, but it also needs to be removed from the
        // collaboratorArray, and the collaboration flags need to be re-calculated, and collaboration event listeners
        // notified.
        if (asset.collaboratorArray.includes(collaborator)) {
            const updatedCollaborators = asset.collaboratorArray.filter(c => c !== collaborator);
            asset._setCollaboratorData(updatedCollaborators);
            if (LazyLoadManager.hasManager(asset, SharedCollaboratorChangedEvent)) {
                LazyLoadManager.updatedExternally(asset, SharedCollaboratorChangedEvent);
            } else {
                // SAM.cpp doesn't have LazyLoadManager
                asset.dispatch(SharedCollaboratorChangedEvent);
            }
        }
    }

    /**
     * @deprecated -- do not use, it does not work for users who were invited via an address book contact,
     * and may break for all use cases in the future. Instead, use
     * {@link ShareableItem.removeCurrentUserFromCollaborationList}. Will be removed on or after 2024-10-01.
     *
     *  https://jira.corp.adobe.com/browse/SAM-3564
     */
    removeCurrentUserFromCollaborationList(assetID: string): Promise<void> {
        oneTimeWarning('removeCurrentUserFromCollaborationList/getCollaborator',
            'This method does not work correctly and will be removed. Use'
            + ' ShareableItem.removeCurrentUserFromCollaboratorList() insstead.');
        const collaborator = this.getCollaborator(assetID);
        return this._removeCollaborator(assetID, collaborator);
    }

    /**
     * @deprecated -- Do not use, it does not work unless collaborator data is already loaded, and the Collaborator
     * representing the current user was NOT invited via an address book contact. The Collaborator it returns in most
     * cases will have invalid data in it. Will be removed on or after 2024-10-01.
     *
     * https://jira.corp.adobe.com/browse/SAM-3564
     */
    getCollaborator(assetID: string): Collaborator {
        oneTimeWarning('removeCurrentUserFromCollaborationList/getCollaborator',
            'This method does not work correctly and will be removed. Use'
            + ' ShareableItem.collaboratorsArray.find(c => c.isCurrentUser()) instead.');

        const userID = this._core._environment.getValue('USER_ID');
        const collaborator: Collaborator = this._getCollaboratorSources(assetID).collaboratorPool.getLocalItemById(userID) ?? new Collaborator(this._core, userID);
        return collaborator;
    }

    /**
     *
     * @package Used internally.
     *
     * @param assetID
     * @param collaborators List of collaborators to add
     * @param configuration Configuration for the invitation, for example useMounts and acceptanceRequired.
     * @param notification Notification for the invitation, @note undefined will not send any notifications.
     * @param captcha Captcha for the invitation.
     * @param inviterLabel Inviter label for the invitation.
     * @param collaborationModel Collaboration model: 'project' for MAC/FACS-based, undefined for ACL-based.
     */
    async _addCollaborators(
        assetID: string,
        collaborators: IInvitationRecipient[],
        configuration?: IInvitationConfiguration,
        /**
         * Leaving this undefined will not send any notifications.
         */
        notification?: IInvitationNotification,
        captcha?: IInvitationCaptcha,
        /**
         * Required for service principal token requests.
         */
        inviterLabel?: string,
        /**
         * Collaboration model for MAC-based projects.
         * When set to 'project', recipients should use rebacRole instead of role.
         */
        collaborationModel?: CollaborationModel
    ): Promise<IAddCollaboratorResult> {
        const request: IInvitationShareRequest = {
            recipients: collaborators,
            // Notification parameter requires a value.
            ...(
                !notification
                    ? {
                        notification: {
                            ans: {}
                        }
                    }
                    : { notification }
            ),
            ...(configuration ? { configuration } : {}),
            ...(captcha ? { captcha } : {}),
            ...(inviterLabel ? { inviterLabel } : {}),
            ...(collaborationModel ? { collaborationModel } : {})
        };
        return await this._invitationInterface.addCollaborators(assetID, request);
    }

    public async addCollaborators(
        assetID: string,
        collaborators: IInvitationRecipient[],
        configuration?: IInvitationConfiguration,
        notification?: IInvitationNotification,
        captcha?: IInvitationCaptcha,
        inviterLabel?: string,
        collaborationModel?: CollaborationModel
    ): Promise<IAddCollaboratorResult> {
        const result = await this._addCollaborators(assetID, collaborators, configuration, notification, captcha, inviterLabel, collaborationModel);

        // If any collaborators were successfully added, mark the sources as needing refresh
        // so the next access will fetch fresh data with the new collaborators/invitations
        if (result.addedCollaborators.length > 0) {
            const { collaboratorSource, invitedCollaboratorSource } = this._getCollaboratorSources(assetID);
            collaboratorSource.setNeedsRefresh();
            invitedCollaboratorSource.setNeedsRefresh();
        }

        return result;
    }

    /**
     * @package -- Used internally.
     *
     * @param assetID Resources URN or AssetID of the resource to modify collaborators for.
     * @param collaborators List of collaborators to modify/remove.
     * @param configuration Configuration for the invitation, for example useMounts and acceptanceRequired.
     * @param notification Notification for the invitation, @note undefined will not send any notifications.
     * @param collaborationModel Optional collaboration model for MAC-enabled projects.
     * @param invitedCollaborators List of invitations to modify/remove.
     */
    public async _modifyCollaborators(
        assetID: string,
        collaborators: IInvitationPatch[],
        configuration?: IInvitationConfiguration,
        notification?: IInvitationNotification,
        collaborationModel?: CollaborationModel,
        invitations?: IInvitationPatch[]
    ) {
        const request: IInvitationSharePatchRequest = {
            collaborators,
            ...(configuration ? { configuration } : {}),
            ...(notification ? { notification } : {}),
            ...(collaborationModel ? { collaborationModel } : {}),
            ...(invitations ? { invitations } : {})
        };
        return this._invitationInterface.modifyCollaborators(assetID, request);
    }

    /**
     * Maps a patch request to update data for optimistic UI updates.
     * Only extracts fields that are present in the patch request.
     *
     * Note: Different item types support different fields:
     * - Collaborators (active users): rebacRole, role, canDiscover (NO canComment - uses commentPermissions array)
     * - Invitations (pending users): rebacRole, role, canComment, canShare (NO canDiscover)
     *
     * The API accepts all fields in IInvitationPatch but applies only the relevant ones per type.
     * We extract all provided fields here and let ItemUpdater ignore unsupported properties.
     */
    private _mapPatchToUpdateData(patch: IInvitationPatch): Record<string, any> {
        const data: Record<string, any> = {};
        if (patch.rebacRole !== undefined) {
            data.rebacRole = patch.rebacRole;
        }
        if (patch.role !== undefined) {
            data.role = patch.role;
        }

        // TODO: Add canDiscover to IInvitationPatch in component-types
        if ('canDiscover' in patch && patch.canDiscover !== undefined) {
            data.canDiscover = patch.canDiscover;
        }
        if (patch.canComment !== undefined) {
            data.canComment = patch.canComment;
        }
        if (patch.canShare !== undefined) {
            data.canShare = patch.canShare;
        }
        return data;
    }

    /**
     * Generic helper to handle item modifications (remove or update) for both collaborators and invitations.
     * This centralizes the logic for processing PATCH responses and updating ItemPools optimistically.
     */
    private _handleItemModifications<TItem extends ItemBase, TUpdateData>(
        responseItems: IInvitationBulkPatchResponseItem[] | undefined,
        patches: IInvitationPatch[],
        pool: ItemPool<TItem>,
        updateSession: IUpdateSession<TItem>,
        updater: ItemUpdater<TItem, TUpdateData>,
        mapPatchToUpdateData: (patch: IInvitationPatch) => TUpdateData
    ): void {
        if (!responseItems) {
            return;
        }

        for (const responseItem of responseItems) {
            // Check for any successful status code (2xx range)
            if (responseItem.statusCode >= 200 && responseItem.statusCode < 300) {
                const patch = patches.find(p => p.id === responseItem.id);
                if (!patch) {
                    continue;
                }

                const existingItem = pool.getLocalItemById(responseItem.id);
                if (!existingItem) {
                    continue;
                }

                if (patch.action === 'remove') {
                    updateSession.queueDiscardedItem(existingItem);
                    // Remove the item from the pool
                    pool.removeLocalItems([ responseItem.id ]);
                } else if (patch.action === 'update') {
                    const updateData = mapPatchToUpdateData(patch);
                    updater.updateLocalItem(updateSession, existingItem, updateData);
                }
            }
        }
    }

    /**
     * Modify collaborators for a resource.
     *
     * @param assetID Resources URN or AssetID of the resource to modify collaborators for.
     * @param collaborators List of collaborators to modify/remove.
     * @param configuration Configuration for the invitation, for example useMounts and acceptanceRequired.
     * @param notification Notification for the invitation, @note undefined will not send any notifications.
     * @param collaborationModel Optional collaboration model for MAC-enabled projects.
     * @param invitedCollaborators List of invitations to modify/remove.
     */
    public async modifyCollaborators(
        assetID: string,
        collaborators: IInvitationPatch[],
        configuration?: IInvitationConfiguration,
        notification?: IInvitationNotification,
        collaborationModel?: CollaborationModel,
        invitations?: IInvitationPatch[],
    ): Promise<IInvitationBulkPatchResponse> {
        const response = await this._modifyCollaborators(assetID, collaborators, configuration, notification, collaborationModel, invitations);

        // Optimistic UI updates: immediately update ItemPools based on the patch actions
        const { collaboratorPool, invitedCollaboratorPool } = this._getCollaboratorSources(assetID);
        const collaboratorUpdateSession = collaboratorPool.createUpdateSession();
        const invitedCollaboratorUpdateSession = invitedCollaboratorPool.createUpdateSession();

        // If the current user was successfully removed, clean up accessConfirmedIDs
        // so they can properly confirm access if re-invited later.
        const currentUserRemovePatch = collaborators.find(p =>
            p.action === 'remove'
            && collaboratorPool.getLocalItemById(p.id)?.isCurrentUser
        );
        if (currentUserRemovePatch) {
            const responseItem = response.collaborators?.find(c => c.id === currentUserRemovePatch.id);
            if (responseItem && responseItem.statusCode >= 200 && responseItem.statusCode < 300) {
                this._accessConfirmedIDs.delete(assetID);
            }
        }

        // Handle collaborator modifications (active collaborators)
        this._handleItemModifications(
            response.collaborators,
            collaborators,
            collaboratorPool,
            collaboratorUpdateSession,
            CollaboratorUpdater,
            this._mapPatchToUpdateData.bind(this)
        );

        // Handle invitation modifications (pending invitations)
        if (invitations?.length) {
            this._handleItemModifications(
                response.invitations,
                invitations,
                invitedCollaboratorPool,
                invitedCollaboratorUpdateSession,
                InvitedCollaboratorUpdater,
                this._mapPatchToUpdateData.bind(this)
            );
        }

        collaboratorUpdateSession.commit();
        invitedCollaboratorUpdateSession.commit();

        return response;
    }

    /**
     * Get pending invitations for the current user.
     *
     * Returns pending invitations that have been sent with or without acceptance required.
     * By default, returns invitations where acceptance is required (invitation workflow) and
     * invitations where acceptance was not required but the target account could not be
     * disambiguated (e.g., multiple accounts associated with email or no valid account).
     *
     * @returns Promise that resolves with pending invitation data
     */
    public async getPendingInvitations(): Promise<IPendingInvitation> {
        return this._invitationInterface.getPendingInvitations();
    }

    /**
     * Accept an invitation by invitation ID.
     *
     * Accepts a pending invitation for the current user. The pending invitation will be converted
     * into appropriate sharing with corresponding ACL being set. This is useful when you need to:
     * - Accept a specific invitation by its ID
     * - Resolve email/account ambiguity when an email is associated with multiple Adobe accounts
     *
     * @param invitationId - The ID of the invitation to accept
     * @param request - Optional request body with mountParent and notification configuration
     * @returns Promise that resolves when the invitation is accepted
     *
     * @example
     * ```typescript
     * // Simple acceptance
     * await sam.collaborationContext.acceptInvitationById('invitation-id-123');
     *
     * // With mount parent
     * await sam.collaborationContext.acceptInvitationById('invitation-id-123', {
     *   mountParent: 'urn:aaid:sc:US:parent-folder-id'
     * });
     * ```
     *
     * @see https://git.corp.adobe.com/pages/acp-cs/CollabServices/invitations/#tag/Invitations/operation/AcceptInvitationsIDRouteV4
     */
    async acceptInvitationById(invitationId: string, request?: IAcceptInvitationByIdRequest): Promise<void> {
        return this._invitationInterface.acceptInvitationById(invitationId, request);
    }

    /**
     * Delete or decline an invitation by invitation ID.
     *
     * This method can be used by:
     * - The pending invitee to decline an invitation
     * - Collaborators with canShare permissions to revoke a pending invitation
     *
     * This is useful for:
     * - Declining specific invitations
     * - Cleaning up pending invitations
     * - Managing invitation lifecycle
     *
     * After successfully deleting the invitation via the API, this method will also
     * search through all loaded invitation pools and remove the invitation from the
     * local cache if found.
     *
     * @param invitationId - The ID of the invitation to delete/decline
     * @returns Promise that resolves when the invitation is deleted
     *
     * @example
     * ```typescript
     * await sam.collaborationContext.deleteInvitationById('invitation-id-123');
     * ```
     *
     * @see https://git.corp.adobe.com/pages/acp-cs/CollabServices/invitations/#tag/Invitations/operation/DeleteInvitationRouteV4
     */
    async deleteInvitationById(invitationId: string): Promise<void> {
        // First, delete the invitation via the API
        await this._invitationInterface.deleteInvitationById(invitationId);

        // After successful deletion, search through all invitation pools and remove the invitation
        // from the local cache if found. Since we don't know which asset this invitation belongs to,
        // we need to check all loaded pools.
        for (const sources of this._collaboratorSourceMap.values()) {
            const invitedCollaborator = sources.invitedCollaboratorPool.getLocalItemById(invitationId);
            if (invitedCollaborator) {
                const invitedCollaboratorPool = sources.invitedCollaboratorPool;
                // Found the invitation in this pool, remove it
                const updateSession = invitedCollaboratorPool.createUpdateSession();
                updateSession.queueDiscardedItem(invitedCollaborator);
                updateSession.commit();
                // Must call removeLocalItems to actually remove from the pool's _objectsById map
                invitedCollaboratorPool.removeLocalItems([ invitationId ]);
                break; // Invitation ID should be unique, so we can stop after finding it
            }
        }
    }

    /**
     * A method that confirms access for a resource or asset and keeps
     * track of that confirmation for this session to prevent
     * more than one call being made per session per asset.
     *
     * Confirming access is not about permissions per se, it's more
     * about accepting the invitation to a resource that requires acceptance.
     *
     * It also handles email/account ambiguity so let's say an email
     * has more than one adobe account associated with it, calling
     * confirm access will also resolve this issue at that time.
     *
     * @note This is really just a temporary measure until
     * the Invitations Service can provide a more efficient way
     * of checking multiple assets at a time to see if they
     * have already confirmed access for the current user token.
     *
     *
     * @param assetId Resource URN
     * @returns void
     */
    async confirmAccess(assetId: string) {
        // Skip confirm access call if we have already confirmed access, or if the user is using a guest access token.
        if (this._accessConfirmedIDs.has(assetId) || this._core._environment.getValue('SESSION_TYPE') === 'guest') {
            return;
        }

        await this._invitationInterface.confirmAccess(assetId);
        this._accessConfirmedIDs.add(assetId);
    }

    /**
     * Obtains authenticated access to a shared resource (e.g., a password-protected link).
     *
     * This method handles the authentication flow:
     * 1. Attempts to get access (credentials automatically sent based on SESSION_TYPE)
     * 2. If logged in and access denied, confirms access (accepts pending invite) and retries
     *
     * @param urn - The URN of the shared resource
     * @param authParams - Authentication parameters (password and optional recaptcha token).
     *                     Password can be omitted for public shares.
     * @param options - Optional configuration for retry behavior
     * @returns Access data including accessURL, accessToken, and metadata
     * @throws {SAMError} with code BAD_REQUEST (400) for malformed requests
     * @throws {SAMError} with code AUTHORIZATION_ERROR (401) for authentication failures
     * @throws {SAMError} with code ACCESS_DENIED (403) if resource access is forbidden
     * @throws {SAMError} with code NOT_FOUND (404) if resource not found or password is invalid
     *         - Use subCode SHARED_RESOURCE_PASSWORD_REQUIRED to check if password is needed
     *         - Use subCode SHARED_RESOURCE_NOT_FOUND for actual 404s
     * @throws {SAMError} for server errors (5xx) or other client errors (429, etc.)
     *
     * @example
     * // Public share (no password)
     * const access = await collaborationContext.getAuthenticatedAccessToSharedResource(urn, {});
     *
     * @example
     * // Password-protected share
     * const access = await collaborationContext.getAuthenticatedAccessToSharedResource(
     *   urn,
     *   { password: userPassword, recaptchaToken: token }
     * );
     *
     * @example
     * // Check if password is required
     * try {
     *   const access = await collaborationContext.getAuthenticatedAccessToSharedResource(urn, {});
     * } catch (error) {
     *   if (error.code === SAMErrorCode.NOT_FOUND && error.subCode === SAMErrorSubCode.SHARED_RESOURCE_PASSWORD_REQUIRED) {
     *     // Show password input UI
     *   }
     * }
     */
    async getAuthenticatedAccessToSharedResource(
        urn: string,
        authParams: SAM.ISharedResourceAuthParams = {},
        options: SAM.ISharedResourceAccessOptions = {}
    ): Promise<SAM.ISharedResourceAccessData> {
        const { maxRetries = 3, retryDelay = 500 } = options;
        const password = authParams.password || '';

        // Check if session has an access token to determine authentication state.
        // Use ACCESS_TOKEN presence rather than SESSION_TYPE because many hosts don't explicitly
        // configure SESSION_TYPE (it defaults to 'logged-in'). This approach works correctly:
        // - If ACCESS_TOKEN present → authenticated (SESSION_TYPE defaults to 'logged-in')
        // - If ACCESS_TOKEN absent → unauthenticated (explicitly exclude auth)
        // TODO: Rely on undefined getAccessToken/refreshAccessToken hook to determine authentication state. GLOW-2245
        const isAuthenticated = !!this._core._environment.getValue('ACCESS_TOKEN');

        // Try to get access - explicitly control auth behavior based on ACCESS_TOKEN presence:
        // - excludeAuth: true for unauthenticated (no ACCESS_TOKEN)
        // - excludeAuth: false for authenticated (has ACCESS_TOKEN, even if expired)
        // Note: When excludeAuth=false, Environment.fetch() falls back to SESSION_TYPE check,
        // but this works correctly because SESSION_TYPE defaults to 'logged-in'. By checking
        // ACCESS_TOKEN presence first, we avoid requiring hosts to explicitly configure SESSION_TYPE.
        let response = await this._invitationInterface.getAccessUrlAndToken(
            urn,
            password,
            authParams.recaptchaToken,
            !isAuthenticated // true when unauthenticated, false when authenticated
        );

        // If logged in and didn't get access, try accepting pending invite
        if (isAuthenticated && response.status !== 200) {
            try {
                await this._invitationInterface.confirmAccess(urn);

                // Poll a few times as it may take a moment for the server to process
                for (let i = 0; i < maxRetries; i++) {
                    response = await this._invitationInterface.getAccessUrlAndToken(
                        urn,
                        password,
                        authParams.recaptchaToken,
                        !isAuthenticated // Must pass same excludeAuth value as initial request
                    );
                    if (response.status === 200) {
                        break;
                    }
                    await sleep(retryDelay);
                }
            } catch (e) {
                // If confirmAccess fails, continue with current response
                this._core._environment.warn(`Unable to accept ambiguous invite: ${e}`);
            }
        }

        // Handle the response
        const passwordAccessHeader = response.headers.get('password-access');
        const requiresPassword = passwordAccessHeader === 'true';

        if (response.status === 200) {
            const result = await response.json();
            // Parse Link headers using http-link-header library (already used elsewhere in sam-js)
            const linkHeaderValue = response.headers.get('Link');
            const links: SAM.ILinkReference[] = [];
            if (linkHeaderValue) {
                const parsedLinks = LinkHeader.parse(linkHeaderValue);
                // refs is an array of link reference objects that match ILinkReference interface
                links.push(...parsedLinks.refs);
            }

            return {
                ...result,
                links,
                requiresPassword
            };
        }

        // Handle error responses
        if (response.status >= 500) {
            throw SAMError.createWithResponse(response);
        } else if (response.status === 400) {
            throw SAMError.create(
                SAMErrorCode.BAD_REQUEST,
                `Bad request for shared resource: ${urn}`,
                { response }
            );
        } else if (response.status === 401) {
            throw SAMError.create(
                SAMErrorCode.AUTHORIZATION_ERROR,
                `Authorization error for shared resource: ${urn}`,
                { response }
            );
        } else if (response.status === 403) {
            throw SAMError.create(
                SAMErrorCode.ACCESS_DENIED,
                `Access to shared resource denied: ${urn}`,
                { response }
            );
        } else if (response.status === 404) {
            // The service returns 404 for multiple scenarios:
            // - Invalid password or password required
            // - Unauthorized access
            // - Literal 404 (resource not found)
            // We use the 'password-access' header to disambiguate
            if (requiresPassword) {
                throw SAMError.create(
                    SAMErrorCode.NOT_FOUND,
                    `Password required or invalid for shared resource: ${urn}`,
                    { response },
                    SAMErrorSubCode.SHARED_RESOURCE_PASSWORD_REQUIRED
                );
            } else {
                throw SAMError.create(
                    SAMErrorCode.NOT_FOUND,
                    `Shared resource not found: ${urn}`,
                    { response },
                    SAMErrorSubCode.SHARED_RESOURCE_NOT_FOUND
                );
            }
        } else {
            // For any other 4xx errors (429, etc.), use createWithResponse
            // which will map known status codes or provide a generic error
            throw SAMError.createWithResponse(response);
        }
    }

    /**
     * Returns a list of AddressBooks for the current user.
     *
     * @experimental -- given the way this feature was rushed in, and some gaps in knowledge
     * about ABS and GenAI, this may not be the final API. Backward-compatibility will not
     * be guaranteed.
     *
     * @returns {AddressBookSource}
     */
    @memoize
    get addressBookSource(): AddressBookSource {
        const loader = new AddressBookLoader(this._addressBookPool, new AddressBookInterface(this._core), AddressBookUpdater);
        return new ItemSource(this._addressBookPool, [ loader ]);
    }

    /**
     * @experimental
     */
    getAddressBookOrder(direction: IOrderDirection = 'ascending', field: AddressBookOrderField = 'displayName'): AddressBookOrder {
        return new AddressBookOrder(direction, field);
    }

    /** @package -- for use in SAM.js only */
    _getAddressBookContactPool(addressBookIdent: string): ItemPool<AddressBookContact> {
        let pool = this._addressBookContactPoolMap.get(addressBookIdent);
        if (!pool) {
            pool = new ItemPool<AddressBookContact>(this._core, 'addressBookContact');
            this._addressBookContactPoolMap.set(addressBookIdent, pool);
        }
        return pool;
    }

    /**
     * For a specified AddressBook, look up the Contact for a specified userId
     *
     * @experimental -- given the way this feature was rushed in, and some gaps in knowledge
     * about ABS and GenAI, this may not be the final API. Backward-compatibility will not
     * be guaranteed.
     *
     * @param {string} addressBookIdent
     * @param {string} userId
     * @returns {Promise<AddressBookContact>}
     */
    @keepAlive
    async getContactInAddressBook(addressBookIdent: string, userId: string): Promise<AddressBookContact> {
        const pool = this._getAddressBookContactPool(addressBookIdent);
        let contact = pool.getLocalItemById(userId);
        if (contact) {
            return contact;
        }
        const abs = new AddressBookInterface(this._core);
        const result = await abs.getContactInAddressBook(addressBookIdent, userId);
        const session = pool.createMutationSession();
        contact = AddressBookContactUpdater.updateRemoteItem(session, result);
        session.commit();
        return contact;
    }

    /**
     * @experimental
     */
    getCollaboratorOrder(direction: IOrderDirection = 'ascending', field: CollaboratorOrderField = 'name'): CollaboratorOrder {
        return new CollaboratorOrder(direction, field);
    }

    /**
     * @experimental
     */
    getInvitedCollaboratorOrder(direction: IOrderDirection = 'ascending', field: InvitedCollaboratorOrderField = 'email'): InvitedCollaboratorOrder {
        return new InvitedCollaboratorOrder(direction, field);
    }

    /**
     * @package -- Currently only used by Project.requestAccessToLibraryReferences
     *
     * Request access to one or more assets.
     *
     * @param assetIds - Array of resource URNs or asset IDs to request access to
     * @param notification - Notification configuration for the access request
     * @param requestedPermissions - Optional requested permissions. By default, the user will be added as a viewer.
     * @returns Promise that resolves with results indicating success/failure for each asset
     *
     * @throws {SAMError} If the request itself fails (network issues, etc.), but not for individual asset failures
     */
    async _requestAccess(
        assetIds: string[],
        notification: IAccessRequestNotification,
        requestedPermissions?: IAccessRequestPermissions
    ): Promise<IAccessRequestResult> {

        return await this._invitationInterface.createAccessRequest(assetIds, notification, requestedPermissions);
    }

    /**
     * Fetch user suggestions for a given asset using People Graph
     *
     * @param assetId The asset ID to get suggestions for
     * @param value The search value/query string
     * @param config Configuration options for the suggestions
     * @returns Promise with array of user suggestions
     */
    async fetchSuggestions(assetId: string, value: string, config: SAM.SuggestionConfig): Promise<SAM.Suggestion[]> {
        return await this._peopleGraphInterface.fetchSuggestions(assetId, value, config);
    }

    /**
     * Accept previously returned suggestions
     *
     * @param tokens Array of suggestion tokens to accept
     * @returns Promise with acceptance results
     */
    async acceptSuggestions(tokens: string[]): Promise<SAM.AcceptResponse> {
        return await this._peopleGraphInterface.acceptSuggestions(tokens);
    }

    /**
     * Helper function to create a page result with recursive getNextPage
     * @package -- for use in SAM.js only
     */
    private _createAccessRequestPageResult(result: IGetAccessRequestResult): IAccessRequestPageResult {
        // Note: accessRequests can be null when there are no requests for the asset
        const accessRequestsArray = result._embedded.accessRequests || [];
        const pageResult: IAccessRequestPageResult = {
            page: accessRequestsArray,
            total: accessRequestsArray.length,
        };

        // Only add getNextPage if there's a next link
        if (result._links?.next?.href) {
            pageResult.getNextPage = async () => {
                const nextResult = await this._invitationInterface.getNextPageAccessRequests(result._links.next.href);
                return this._createAccessRequestPageResult(nextResult);
            };
        }

        return pageResult;
    }

    /**
     *
     * Get access requests for a given asset.
     *
     * @param assetId - The asset ID to get access requests for
     * @param orderBy - The order by which to sort the access requests
     * @param limit - The number of access requests to return
     * @param start - The start index of the access requests to return, first page requires start to be undefined
     * @param resourcesType - @NOTE Comma separated list of resource types
     * for Example: application/vnd.adobe.uxdesign.prototype+dcx,application/vnd.adobe.uxdesign.prototype+dcx
     * @returns Promise that resolves with an array of access requests
     */
    async getAccessRequests(assetId: string, orderBy: AccessRequestOrderBy, limit?: number, start?: number, resourcesType?: string): Promise<IAccessRequestPageResult> {
        const result = await this._invitationInterface.getAccessRequests(assetId, orderBy, limit, start, resourcesType);
        return this._createAccessRequestPageResult(result);
    }

    /**
     * Request access to one or more assets.
     *
     * @param assetIds - Array of resource URNs or asset IDs to request access to
     * @param notification - Notification configuration for the access request
     * @param requestedPermissions - Optional requested permissions. By default, the user will be added as a viewer.
     * @param collaborationModel - Optional collaboration model. By default, the collaboration model will be the default collaboration model.
     * @returns Promise that resolves with results indicating success/failure for each asset
     *
     * @throws {SAMError} If the request itself fails (network issues, etc.), but not for individual asset failures
     */
    async requestAccess(assetIds: string[], notification: IAccessRequestNotification, requestedPermissions: IAccessRequestPermissions,  collaborationModel?: CollaborationModel): Promise<IAccessRequestResult> {
        return await this._invitationInterface.createAccessRequest(assetIds, notification, requestedPermissions, collaborationModel);
    }

    /**
     * Grant or reject a pending access request. Only users with sharing permissions for a resource can grant or reject an access request.
     * When the access request is granted, then the role and permissions as determined
     * by the granter will be used to setup corresponding access permissions.
     *
     * @param config {IAccessGrantOrRejectAccessRequestConfig} - The configuration for the grant or reject access request.
     * @returns Promise that resolves when the access request is granted or rejected
     *
     * @throws {SAMErrorCode.UNAUTHORIZED} If the user is not authorized to grant or reject the access request.
     */
    async grantOrRejectAccessRequest(config: IAccessGrantOrRejectAccessRequestConfig): Promise<void> {
        return await this._invitationInterface.grantOrRejectAccessRequest(config);
    }

    /**
     * Get access request status for the user on a specific resource. Can be used to to check if an authenticated user has a pending or
     * rejected request for access or upgraded permissions (e.g. edit access). More detailed information can found on the wiki.
     * @param assetId - The asset ID or URN to get the access request status for
     */
    async getAccessRequestStatus(assetId: string): Promise<IAccessRequestResponse> {
        return await this._invitationInterface.getAccessRequestStatus(assetId);
    }

    /**
     * Get sharing capabilities and collaborator information for a user on the resource with the given URN.
     * The user can be an individual collaborator or members of one or more collaborator groups.
     *
     * The information returned includes:
     * - Access and permissions (role, canShare, canComment, commenting permissions) being mapped from the effective ACL of the user on the asset.
     * - Expected permission for the user to send (custom) email notifications when sharing this asset.
     * - Indicator if the user will be able to share this asset with public (based on sharing restrictions of the organization owning this asset).
     * - Information regarding the organization owning this asset.
     * - Permissions on the parent of this asset.
     * - Permissions of the special principals All and Authenticated on this asset.
     * - Timestamp when this asset was shared with the user.
     * - Custom message and custom parameters used in the notification sent when this asset was shared with this user
     *   (only when the extraFeatures query parameter contains the value include_custom_collaborator_data).
     *
     * The user is normally identified by the given user token and needs to be a collaborator. This API also accepts
     * guest user tokens. It is also possible to call this API without token, in which case capabilities will be
     * returned for the All principal, but only when the asset is shared publicly.
     *
     * @param urn - The URN of the asset to get the capabilities for
     * @param extraFeatures - Optional comma-separated list of extra features to include.
     *                       Use 'include_custom_collaborator_data' to include shareDate and notificationParameters.
     * @returns Promise that resolves with the capabilities for the asset
     */
    async getCapabilities(urn: string, extraFeatures?: string[]): Promise<IInvitationServiceCapabilities> {
        return await this._invitationInterface.getCapabilities(urn, extraFeatures ?? []);
    }

    /**
     * Get an ItemSource for access requests for a given asset.
     * This provides a paginated, observable list of access requests that can be
     * sorted, filtered, and automatically updated.
     *
     * @param assetId - The asset ID to get access requests for
     * @param resourcesType - Optional comma-separated list of resource types
     *                        for example: application/vnd.adobe.uxdesign.prototype+dcx
     * @returns AccessRequestSource - An ItemSource for the access requests
     *
     * @example
     * ```typescript
     * const source = sam.collaborationContext.getAccessRequestsItemSource('asset-id-123');
     * const order = sam.collaborationContext.getAccessRequestOrder('descending', 'createDate');
     * const list = source.getList(order);
     * await waitForListLoad(list);
     * const requests = list.items;
     * ```
     */
    public getAccessRequestsItemSource(assetId: string, resourcesType?: string): AccessRequestSource {
        // Get or create the pool for this asset
        let pool = this._accessRequestPoolMap.get(assetId);
        if (!pool) {
            pool = new ItemPool<AccessRequestItem>(this._core, 'accessRequest');
            this._accessRequestPoolMap.set(assetId, pool);
        }

        const loader = new AccessRequestLoader(pool, this._invitationInterface, assetId, resourcesType);
        return new ItemSource<AccessRequestConfig>(pool, [ loader ], new EverythingFilter());
    }

    /**
     * Create an order for AccessRequest lists
     *
     * @param direction - The sort direction ('ascending' or 'descending')
     * @param field - The field to sort by (currently only 'createDate' is supported)
     * @returns AccessRequestOrder instance
     */
    public getAccessRequestOrder(direction: IOrderDirection = 'descending', field: AccessRequestOrderField = 'createDate'): AccessRequestOrder {
        return new AccessRequestOrder(direction, field);
    }
}
