/**
 * reducer
 * @packageDocumentation
 * @module reducer
 * @internal
 */

import JSONPath from '../../utils/JSONPath';
import type {
    InsertAction,
    UpdateAction,
    RemoveAction,
    Action
} from '../Action';
import {
    isAggregateAction,
    isInsertAction,
    isUpdateAction,
    isRemoveAction
} from '../Action';

function insertObject<T>(state: T, action: InsertAction<any>): T {
    JSONPath.insert(state, action.path as string, action.data);
    return state;
}

function updateObject<T>(state: T, action: UpdateAction<any>): T {
    const itemData = JSONPath.get(state, action.path as string);
    // TODO: Deep
    Object.assign(itemData as string, action.data);

    return state;
}
function removeObject<T>(state: T, action: RemoveAction): T {
    JSONPath.remove(state, action.path as string);
    return state;
}

// Given a state and an Action, use the Action's path and data to update the state
export default function reducer<T>(state: T, action: Action): T {
    if (isAggregateAction(action)) {
        return action.actions.reduce((memo, subAction) => reducer(memo, subAction), state);
    }

    if (isInsertAction(action)) {
        return insertObject<T>(state, action);
    }

    if (isUpdateAction(action)) {
        return updateObject<T>(state, action);
    }

    if (isRemoveAction(action)) {
        return removeObject<T>(state, action);
    }

    return state;
}
