import type { IOrderDirection } from '../core/ItemOrder';
import InterfaceBase from './InterfaceBase';
import type { ISearchQuery, ISearchSortOrderDirection, USSResponse } from './USSModel';
import { SearchProps } from './USSModel';
import type { IUSSAdobeAssetOrderBy } from './AssetModel';
import { getUSSFetchFields } from './AssetModel';
import { updateAssetTypeForUSS } from './USSUtils';

 type IPageOptions = {
     limit: number;
     start?: number;
 }

interface IListingOptions<IOrderField> extends IPageOptions {
    orderDirection: IOrderDirection;
    orderBy: IOrderField;
}

export interface AssetsListingGlobalSearchOptions extends IListingOptions<IUSSAdobeAssetOrderBy> {
    mediaTypes?: string[];
    query?: string;
    excludeMediaTypes?: string[];
    embedPermissions?: boolean;
}

const DefaultAssetsListingGlobalSearchOptions: AssetsListingGlobalSearchOptions = {
    orderDirection: 'descending',
    orderBy: 'modify_date',
    start: 0,
    limit: 0
};

export function getDirectionValue(userOptions: Partial<AssetsListingGlobalSearchOptions>): ISearchSortOrderDirection {
    const directionFlag = userOptions.orderDirection === 'ascending' ? 'asc' : 'desc';
    return directionFlag;
}

export default class AdobeAssetGlobalSearchInterface extends InterfaceBase {
    /**
     * @TODO We should open this up to allow clients to configure the resctrictions
     * on this query through a filter.
     * https://jira.corp.adobe.com/browse/SAM-2542
     */
    async getFilteredAssets(options?: Partial<AssetsListingGlobalSearchOptions>): Promise<USSResponse> {
        options = { ...DefaultAssetsListingGlobalSearchOptions, ...options };
        updateAssetTypeForUSS(options.mediaTypes);
        updateAssetTypeForUSS(options.excludeMediaTypes);
        const filters: ISearchQuery = {
            hints: {
                acp_platform_v2: true,
            },
            fetch_fields: { includes: getUSSFetchFields() },
            [SearchProps.STORAGE_ASSIGNEE_TYPE]: [ 'user' ],
            op_none_of: [
                {
                    op_field_exists: [
                        // for excluding the older spaces and its children
                        // We would want to show project and its children in global search
                        'app_metadata$$cc:inheritable$$cc:space$$repo:assetId',
                        'app_metadata$$cc:inherited$$cc:space$$repo:assetId',
                    ],
                },
                {
                    [SearchProps.VISIBILITY]: [ 'hiddenSelf', 'hiddenRecursive' ],
                },
                {
                    [SearchProps.CREATIVE_CLOUD_TOPLEVEL_COLLECTION_NAME]: 'appdata',
                },
                {
                    [SearchProps.TYPE]: options.excludeMediaTypes || [],
                },

            ],
            op_or: [
                // TODO: Update _getItemData in AdobeAssetGlobalSearchLoader if we support Global
                // search loader to show other items as well. For e.g. projects
                {
                    [SearchProps.STORAGE_ASSIGNEE_ID]: this._core._environment.getValue('USER_ID')
                },
                {
                    [SearchProps.SHARED_VIA_INVITE]: true
                }
            ],
            [SearchProps.TYPE]: options.mediaTypes || [],
            sort_orderby: options.orderBy,
            sort_order: getDirectionValue(options),
            limit: options.limit,
            start_index: options.start,
            // Since this is a JSON payload in the request, the `query` param is safe from injection attacks
            ...(options.query ? { q: options.query } : {})
        };

        if (options.embedPermissions) {
            filters.fetch_fields!.includes.push('_embedded');
        }

        const response = await this._core.hostAssetContext._ussInterface.getQueryResponse(filters);
        return response;
    }
}
