import type ProjectInterface from '../interface/ProjectsInterface';
import type { ProjectUpdaterMetadata } from './Project';
import type Project from './Project';
import type { IItemLoader, IItemLoaderOptions, ILoadedPage, ILoadNextPage } from '../core/ItemLoader';
import type ItemPool from '../core/ItemPool';
import { OrderFieldToIProjectsOrderBy } from './ProjectOrder';
import type ProjectFilter from './ProjectFilter';
import type { ProjectConfig } from './ProjectSource';
import type { IServiceLink } from '../interface/LinkUtils';
import type {
    IProject,
    IProjectsResponse,
    IRecentProjectsResponse } from '../interface/ProjectsModel';
import {
    PROJECT_VIEW_TO_SERVICE_MAP,
    ProjectViews,
} from '../interface/ProjectsModel';
import type AdobeAsset from '../assets/AdobeAsset';
import type ItemUpdater from '../core/ItemUpdater';
import type { ISAMCorePrivate } from '../indexPrivate';
import { ORGANIZATIONS_CHANGED } from './OrganizationsChangedEvent';
import { LazyLoadManager } from '../core/decorators/LazyLoadManager';
import { getMostRecentValidMutation } from '../utils/loaderUtils';


export default class ProjectsListLoader implements IItemLoader<ProjectConfig> {

    constructor(
        private _projectPool: ItemPool<Project | AdobeAsset>,
        private _projectInterface: ProjectInterface,
        private _projectUpdater: ItemUpdater<Project, Partial<IProject | ProjectUpdaterMetadata>>,
        private _core: ISAMCorePrivate
    ) {
    }

    supportsFilter(filter?: ProjectFilter): boolean {
        return filter !== undefined;
    }

    async loadPage(options: IItemLoaderOptions<ProjectConfig>): Promise<ILoadedPage<ProjectConfig>> {
        return await this._loadPage(options);
    }

    private async _loadPage(options: IItemLoaderOptions<ProjectConfig>, pageLink?: IServiceLink): Promise<ILoadedPage<ProjectConfig>> {
        const { order, filter } = options;
        const { limit } = options.loadOptions ?? {};

        let result: IProjectsResponse | IRecentProjectsResponse;
        if (pageLink) {
            // We are loading the next page with the link provided.
            result = await this._projectInterface.getProjectsWithLink(pageLink);
        } else if (filter?.view === ProjectViews.Recent) {
            const recentOptions = limit ? { first: limit } : {};
            result = await this._projectInterface.getRecentProjects(recentOptions, options.resource);
        } else {
            // If ProjectFilter is not provided by the client, then it will be an EverythingFilter,
            // so each ProjectFilter property needs to be checked for existence.

            // Note: If `view` parameter is unspecified, the server uses All as the default
            const view = !filter.view ? {} : { view: PROJECT_VIEW_TO_SERVICE_MAP[filter.view] };
            const repositoryId = filter.repositoryID ? { repositoryId: filter.repositoryID } : {};
            const nameContains = filter.nameContains ? { nameContains: filter.nameContains } : {};
            const isDiscarded = filter.isDiscarded ? { isDiscarded: true } : {};
            const directorySubtypes = filter.directorySubtypes ? { directorySubtypes: filter.directorySubtypes } : {};
            const ownerIds: string[] = [];

            // Yours view needs the org list to determine what filter parameters to send. SWY needs
            // the org list to do client-side filtering.
            if (filter.view === ProjectViews.Yours || filter.view === ProjectViews.SWY) {
                await LazyLoadManager.fetchIfNeeded(this._core.hostAssetContext, ORGANIZATIONS_CHANGED);
            }

            if (filter.view === ProjectViews.Yours) {
                const homeOrgId = this._core.hostAssetContext.defaultOrganizationId || '';
                ownerIds.push(this._core._environment.getUserId());
                if (homeOrgId) {
                    ownerIds.push(homeOrgId);
                }
            } else if (filter.view === ProjectViews.Organization || filter.view === ProjectViews.Admin) {
                if (filter.organizationID) {
                    ownerIds.push(filter.organizationID);
                }
            }

            result = await this._projectInterface.getProjects({
                orderBy: OrderFieldToIProjectsOrderBy[order.field],
                orderDirection: order.direction,
                limit,
                ...view,
                ...repositoryId,
                ...nameContains,
                ...isDiscarded,
                ...(ownerIds.length ? { ownerId: ownerIds.join(',') } : {}),
                ...directorySubtypes
            }, options.resource);
        }

        // We will ignore the update if we had local changes sooner than this timestamp.
        // This default latency is set to 3 seconds right now. We should revisit this value.
        const latency = this._projectPool._core._environment.getValue('PROJECTS_LIST_UPDATE_LATENCY');
        const mostRecentValidMutation = getMostRecentValidMutation(options.resource, latency);

        const session = this._projectPool.createLoaderUpdateSession<Project>(mostRecentValidMutation);
        const projects: Partial<IProject | ProjectUpdaterMetadata>[] = result.children.map((project: IProject) =>
            filter.view === ProjectViews.Recent
                // [SAMJS-311] isRecent can only be set from Recent view; some Projects are only visible on Recent view
                ? { ...project, isRecent: true }
                : { ...project, allowInLists: true });
        const items = this._projectUpdater.updateRemoteItems(session, projects);
        session.commit();

        // Check if we have another page to load.
        let loadNextPage: ILoadNextPage<ProjectConfig> | undefined;
        const nextPageLink = result._links?.next;
        if (nextPageLink) {
            loadNextPage = (options: IItemLoaderOptions<ProjectConfig>) =>
                this._loadPage(options, nextPageLink);
        }

        return {
            items,
            total: result._page?.total,
            loadNextPage,
            mostRecentValidMutation
        };
    }
}
