import type { SAM } from '@ccx-public/component-types';
import type { IComparatorMap } from '../core/ItemOrder';
import { createItemOrderFactory } from '../core/ItemOrder';
import type Version from './AssetVersion';
import { compareValues } from '../core/ItemOrder';


export type AssetVersionField = 'created';

const OrderFieldToComparator: IComparatorMap<Version, AssetVersionField> = {
    created(a: Version, b: Version): number {
        return compareValues(a.created, b.created);
    }
};

export default class AssetVersionOrder extends createItemOrderFactory(OrderFieldToComparator) implements SAM.AssetVersionOrder {
    static default = new AssetVersionOrder('descending', 'created');
}
