import opentelemetry from '@opentelemetry/api';
import oneTimeWarning from '../../utils/oneTimeWarning';

/**
 * Decorator for capturing the class name that is included in the span name
 * We are unable to directly fetch the class name from the target due to minification of code
 * @param className - The name of the class.
 * @returns The decorated constructor.
 */
export function traceableAs(className: string) {
    return function (constructor: any) {
        constructor.traceableAs = () => { return className; };
    };
}

/**
 * Decorator for instrumenting a method for emitting tracing spans and events.
 * @param target - The class or prototype of the class.
 * @param propertyKey - The name of the method.
 * @param descriptor - The property descriptor for the method.
 * @returns The decorated method.
 * @remarks ensure that OTel SDK version is compatible with OTel API that SAM.js depends on.
 */
export function trace(target: any, propertyKey: string, descriptor: PropertyDescriptor) {
    let targetConstructor: any = undefined;
    if (typeof target === 'function' && target.prototype?.constructor) {
        // target is a class
        targetConstructor = target.prototype.constructor;

    } else if (typeof target === 'object' && target.constructor) {
        // target is a class instance
        targetConstructor = target.constructor;
    }

    const method = descriptor.value;
    descriptor.value = function (...args: any[]) {
        let spanName: string = propertyKey;
        if (targetConstructor) {
            let className: string;
            if (typeof targetConstructor.traceableAs === 'function') {
                // If the class has a static method traceableAs, use it
                className = targetConstructor.traceableAs();
            } else {
                // Otherwise, fall back to the class name, which might be mangled by minifiers
                oneTimeWarning(
                    'Class name not provided',
                    `Use the traceableAs decorator on the class of ${spanName} to ensure the class name does not get minified`
                );
                className = targetConstructor.name;
            }
            spanName = className + '.' + spanName;
        }

        const tracer = opentelemetry.trace.getTracer('sam-js');
        const span = tracer.startSpan(spanName);
        const ctx = opentelemetry.trace.setSpan(opentelemetry.context.active(), span);
        try {
            const result = opentelemetry.context.with(ctx, method, this, ...args);
            // Checking whether result is a JS Promise
            if (!!result && typeof result.then === 'function') {
                return result.catch((e: any) => {
                    if (e instanceof Error) {
                        span.recordException(e);
                    }
                    throw e;
                }).finally(() => {
                    span.end();
                });
            } else {
                span.end();
                return result;
            }
        } catch (e) {
            if (e instanceof Error) {
                span.recordException(e);
            }
            span.end();
            throw e;
        }
    };
    return descriptor;
}

/**
 * Sets an attribute on the active tracing span.
 * @param key - Tracing span attribute key.
 * @param value - Tracing span attribute value.
 */
export function setTracingSpanAttribute(key: string, value?: string) {
    opentelemetry.trace.getActiveSpan()?.setAttribute(key, value || '');
}
