import type ItemBase from './ItemBase';
import { ModernSet } from '../utils/ModernSet';

export type IItemFilterHash = string;

export type ItemFilterRelation =
    // There are no known shared elements between lists using the two filters.
    | 'disjoint'

    // Some items can be borrowed from a list filtered with the other filter,
    // however there might be other items that were not in the other list.
    | 'unknown'

    // The other filter has a sufficient list of items that the new filter
    // can create its entire list just by using the in-memory items from the previous
    // filter.
    | 'subset';

export interface IExplicitFilter<LocalType extends ItemBase> extends IItemFilter<LocalType>{
    /**
     * This mechanism allows to process items on the client side while the
     * server fetch executes in the background. We can create new lists based
     * on items that are already loaded in memory. For example, switching the
     * sorting order of a list that is fully loaded will do so entirely on
     * the client side. In that case the filter is a perfect match.
     *
     * Another example is when a filter narrows down the results. In that case,
     * if a list has the wider list of items, then we can create a new list
     * by applying the filter entirely on the client side.
     *
     * This should return `disjoint` in cases where the lists would be entirely disjoint.
     * For example, if the filter returns only Spaces inside a specific teamID, then there's
     * no reason to reuse the Spaces from a different teamID.
     * In that case, it would be a waste of time to grab items from the other list.
     *
     * In case `other` filter would be a good starting point to start populating a list,
     * the method returns 'unknown'. The new list would be incomplete and will require
     * a reload from the server in order to fully download all resources.
     *
     * In case `other` filter contains a sufficiently large list of items that the new
     * filter would generate a complete list, this method will return `subset`.
     * In theory, no server requests are necessary to create an entire list of items
     * using the `this` filter.
     *
     * @param other filter of the source list.
     */
    getRelationToFilter(other: IItemFilter<LocalType>): ItemFilterRelation;

    /**
     * Hash that can be used to uniqueuly identify the filter.
     * This hash is used for caching in the ItemSource implementation.
     */
    readonly hash: IItemFilterHash;
}

export interface IImplicitFilter<LocalType extends ItemBase> extends IItemFilter<LocalType>{}

export interface IItemFilter<LocalType extends ItemBase> {
    /**
     * Returns true if the provided item matches the filter.
     * @param item
     */
    matches(item: LocalType): boolean;
}

export function getFiltersRelation<LocalType extends ItemBase>(
    requestedFilter?: IExplicitFilter<LocalType>, other?: IExplicitFilter<LocalType>) {
    if (requestedFilter === other) {
        // If the exact same filter is given, then it must be a complete list.
        return 'subset';
    }

    if (requestedFilter && other) {
        // If the hash is the same, then we have the same filter.
        if (requestedFilter.hash === other.hash) {
            return 'subset';
        }

        // Since the hashes don't match, they aren't both EverythingFilter. So if `other`
        // is everything filter, then the requested filter is a subset.
        if (other.hash === 'everything') {
            return 'subset';
        }
        // If requested filter is the EverythingFilter, then it is a superset
        if (requestedFilter.hash === 'everything') {
            return 'unknown';
        }

        return requestedFilter.getRelationToFilter(other);
    }

    // If we have a filter, it means the other list had no filter, so this is a complete subset of an unfiltered list.
    if (requestedFilter) {
        return 'subset';
    }

    // If the other list had a filter and this new list doesn't have a filter, then this new list will be incomplete.
    return 'unknown';
}

/** Determine whether two date ranges overlap and return their filter relation
 * Default values chosen to functionally represent -Inf and Inf if any param is undefined
 * @param startThis
 * @param endThis
 * @param startOther
 * @param endOther
 */
export function getDateRangeRelation(
    startThis: Date = new Date(-9999, 0, 1),
    endThis: Date = new Date(9999, 0, 1),
    startOther: Date = new Date(-9999, 0, 1),
    endOther: Date = new Date(9999, 0, 1)
): ItemFilterRelation {

    //  startOther ---- startThis ---- endThis --- endOther
    //  A is completely within B
    if (startThis >= startOther && endThis <= endOther) { return 'subset'; }

    // startThis --- endThis --- startOther ---- endOther
    // or
    // startOther --- endOther --- startThis --- endThis
    // A and B have no overlap
    if (startThis > endOther || endThis < startOther) { return 'disjoint'; }

    // startThis --- startOther --- endThis --- startOther
    // or
    // startOther --- startThis --- endOther --- endThis
    // or
    // startThis --- startOther --- endOther --- endThis
    // A and B have some overlap, but A is not a subset
    return 'unknown';
}


type MultiVal<T> = T[] | Set<T> | undefined;

/**
 * Determines relationship between two filter properties that accept multiple values (Set or Array). By convention,
 * SAM.js treats undefined/empty properties as matching all values.
 *
 * Note that direction is important. If `thisVal` = [1] and `otherVal` = [1, 2], the relation from `thisVal` to
 * `otherVal` is 'subset', because `otherVal` completely overlaps `thisVal`. If `thisVal` = [1, 2] and `otherVal` = [1],
 * the relation is 'unknown', because `otherVal` only partially overlaps `thisVal`.
 *
 * @param {MultiVal<T>} thisVal The value from `this` filter in `ItemFilter.getRelationToFilter(other)`
 * @param {MultiVal<T>} otherVal The value from `other` filter parameter in `ItemFilter.getRelationToFilter(other)`
 * @returns {ItemFilterRelation}
 *    'disjoint' if `other` does not overlap `this`
 *    'unknown' if `other` partially overlaps `this`
 *    'subset' if `other` fully overlaps `this`
 */
export function getMultiValueFilterRelation<T>(
    thisVal: MultiVal<T>,
    otherVal: MultiVal<T>
): ItemFilterRelation {
    // These are equivalent: new Set(), new Set(undefined), new Set([])
    // As are these: new Set([1, 2]), new Set(new Set([1, 2]))
    const thisValM = new ModernSet<T>(thisVal);
    const otherValM = new ModernSet<T>(otherVal);

    // Empty set = match everything.
    // If `other` is empty, it overlaps `this` fully.
    if (!otherValM.size) { return 'subset'; }
    // `other` matches some items, `this` matches all items, so overlap is partial
    if (otherValM.size && !thisValM.size) { return 'unknown'; }

    // Both values are non-empty at this point.
    if (thisValM.isDisjointFrom(otherValM)) { return 'disjoint'; }
    if (thisValM.isSubsetOf(otherValM)) { return 'subset'; }
    return 'unknown';
}

export function getSingleValueFilterRelation<T extends string | number | boolean | undefined | null>(
    thisVal?: T,
    otherVal?: T): ItemFilterRelation {
    // if values are defined and different, no overlap
    if (thisVal && otherVal && thisVal !== otherVal) {
        return 'disjoint';
    }

    // if we filtered the old list and we're not filtering the new list, we need to fetch more items
    if (otherVal && !thisVal) {
        return 'unknown';
    }

    // either they're the same, the old one was unfiltered and either way we can generate the new list entirely from the old
    return 'subset';
}

