import type { SAM } from '@ccx-public/component-types';

import {
    getMultiValueFilterRelation,
    type IExplicitFilter,
    type ItemFilterRelation
} from '../core/ItemFilter';
import type { default as AdobeAsset } from './AdobeAsset';
import { ModernSet } from '../utils/ModernSet';

const AdobeAssetFilterName = 'AdobeAssetFilter';

export interface IAdobeAssetFilterOptions {
    readonly mediaTypes?: string[];
    readonly excludeMediaTypes?: string[];
    readonly assetTypes?: SAM.AssetType[];
    readonly excludeAssetTypes?: SAM.AssetType[];
    readonly assetSubTypes?: SAM.AssetSubType[];
    /** @package -- for internal use only */
    readonly _isDiscarded?: boolean;
}

/**
 * For ItemSources on AssetContext and AdobeAsset, the AdobeAssetFilter is the only one used by clients today.
 * Separately, we have the USSAdobeAssetFilter which is used by clients to filter USS assets,
 * and other external filters on other sources.
 * This filter can be used to filter AdobeAsset objects by mediaType and excludeMediaType.
 * If both mediaType and excludeMediaType are specified then only mediaType
 * will be considered for filtering. If neither mediaType nor excludeMediaType are specified then all mediaTypes
 * will be considered for filtering.
 */

export default class AdobeAssetFilter implements IExplicitFilter<AdobeAsset> {
    private readonly _mediaTypes?: ModernSet<string> = undefined;
    private readonly _excludeMediaTypes?: ModernSet<string> = undefined;
    private readonly _assetTypes?: ModernSet<SAM.AssetType> = undefined;
    private readonly _excludeAssetTypes?: ModernSet<SAM.AssetType> = undefined;
    private readonly _assetSubTypes?: ModernSet<SAM.AssetSubType> = undefined;
    private readonly _isDiscarded?: boolean = undefined;

    constructor(options?: Partial<IAdobeAssetFilterOptions>) {
        const makeSet = (a: string[] | undefined) => a?.length ? new ModernSet(a) : undefined;
        this._mediaTypes = makeSet(options?.mediaTypes);
        this._excludeMediaTypes = makeSet(options?.excludeMediaTypes);

        if (this._mediaTypes?.size && this._excludeMediaTypes?.size) {
            this._mediaTypes = new ModernSet([]);
            console.warn('AdobeAssetFilter - cannot have both mediaTypes and excludeMediaTypes. Omitting mediaTypes.');
        }

        this._assetTypes = makeSet(options?.assetTypes) as ModernSet<SAM.AssetType> | undefined;
        this._excludeAssetTypes = makeSet(options?.excludeAssetTypes) as ModernSet<SAM.AssetType> | undefined;
        if (this._assetTypes?.size && this._excludeAssetTypes?.size) {
            this._assetTypes = new ModernSet([]);
            console.warn('AdobeAssetFilter - cannot have both assetTypes and excludeAssetTypes. Omitting assetTypes.');
        }

        this._assetSubTypes = makeSet(options?.assetSubTypes) as ModernSet<SAM.AssetSubType> | undefined;

        this._isDiscarded = options?._isDiscarded;
    }

    get hash(): string {
        const stringify = (s?: Set<string>) => s?.size ? [ ...s ].sort().join(',') : '';
        let hash = 'mediatypes=' + stringify(this._mediaTypes);
        hash += ':excludemediatypes=' + stringify(this._excludeMediaTypes);
        hash += ':assetTypes=' + stringify(this._assetTypes);
        hash += ':excludeAssetTypes=' + stringify(this._excludeAssetTypes);
        hash += ':assetSubTypes=' + stringify(this._assetSubTypes);
        hash += (this._isDiscarded !== undefined) ? ':isDiscarded=' + this._isDiscarded : '';
        return hash;
    }

    get mediaTypes(): Set<string> | undefined {
        return this._mediaTypes;
    }

    get excludeMediaTypes(): Set<string> | undefined {
        return this._excludeMediaTypes;
    }

    get assetTypes(): Set<string> | undefined {
        return this._assetTypes;
    }

    get excludeAssetTypes(): Set<string> | undefined {
        return this._excludeAssetTypes;
    }

    get assetSubTypes(): Set<string> | undefined {
        return this._assetSubTypes;
    }

    get name(): string {
        return AdobeAssetFilterName;
    }

    matches(item: AdobeAsset): boolean {
        return Boolean((!this._excludeMediaTypes?.size || !this._excludeMediaTypes.has(item.mediaType))
            && (!this._mediaTypes?.size || this._mediaTypes.has(item.mediaType))
            && (!this._assetTypes?.size || item.assetType && this._assetTypes.has(item.assetType))
            // excludeAssetTypes should match assetType = undefined
            && (!this._excludeAssetTypes?.size || !this._excludeAssetTypes.has(item.assetType!))
            && (!this._assetSubTypes?.size || item.assetSubType && this._assetSubTypes.has(item.assetSubType))
            && (this._isDiscarded === undefined || this._isDiscarded === item.isDiscarded)
        );
    }

    getRelationToFilter(other: AdobeAssetFilter): ItemFilterRelation {
        const relations: ItemFilterRelation[] = [
            this.getMediaRelationToFilter(other),
            this._getAssetTypeRelationToFilter(other),
            getMultiValueFilterRelation(this._assetSubTypes, other.assetSubTypes),
            this._getDiscardedTypeRelationToFilter(other)
        ];

        if (relations.includes('disjoint')) { return 'disjoint'; }
        if (relations.includes('unknown')) { return 'unknown'; }

        // Since the filters can't be 'disjoint', there must be some overlap, leaving only 'unknown' and 'subset' as a
        // possibility. Then, since all 'unknown' cases have been eliminated, the only remaining possibility is
        // 'subset'.
        return 'subset';
    }

    // TODO: change to private _getMediaRelationToFilter after this method is removed from
    // public API.
    public getMediaRelationToFilter(other: AdobeAssetFilter): ItemFilterRelation {
        return this._getExcludeIncludeFilterRelation(this._mediaTypes, this._excludeMediaTypes, other._mediaTypes, other._excludeMediaTypes);
    }

    private _getAssetTypeRelationToFilter(other: AdobeAssetFilter): ItemFilterRelation {
        return this._getExcludeIncludeFilterRelation(this._assetTypes, this._excludeAssetTypes, other._assetTypes, other._excludeAssetTypes);
    }

    private _getExcludeIncludeFilterRelation<T>(
        thisInclude?: ModernSet<T>,
        thisExclude?: ModernSet<T>,
        otherInclude?: ModernSet<T>,
        otherExclude?: ModernSet<T>
    ): ItemFilterRelation {
        // Normalize undefined to empty ModernSet
        thisInclude = new ModernSet(thisInclude);
        thisExclude = new ModernSet(thisExclude);
        otherInclude = new ModernSet(otherInclude);
        otherExclude = new ModernSet(otherExclude);

        // If both includes are non-empty, and they do not overlap, they are disjoint. Assume excludes are undefined,
        // enforced in the constructor.
        if (getMultiValueFilterRelation(thisInclude, otherInclude) === 'disjoint') { return 'disjoint'; }

        // If `other` excludes all of `this`, there is no overlap. And vice versa.
        if (otherExclude.size && thisInclude.size && otherExclude.isSupersetOf(thisInclude)
            || thisExclude.size && otherInclude.size && thisExclude.isSupersetOf(otherInclude)
        ) {
            return 'disjoint';
        }
        // Note: it is impractical to compute the disjoint case between two "exclude" filters. To be disjoint,
        // the union of both exclude filters must be a superset of all possible values (APV). For some properties, the
        // APV may take gigabytes to represent.

        // If `otherIncludes` only partially overlaps `thisIncludes`, then the relation is 'unknown'
        if (!thisExclude.size && !otherExclude.size && getMultiValueFilterRelation(thisInclude, otherInclude) === 'unknown') {
            return 'unknown';
        }

        // If 'other' excludes only some of `this`, `other` only partially overlaps `this`
        if (!thisExclude.size && otherExclude.size && getMultiValueFilterRelation(thisInclude, otherExclude) === 'unknown') {
            return 'unknown';
        }
        // if `other` includes more items than `this` excludes, then `other` only partially overlaps `this`
        if (otherInclude.size && thisExclude.size && getMultiValueFilterRelation(thisExclude, otherInclude) === 'subset') {
            return 'unknown';
        }
        // if `this` excludes none of the items `other` includes, then `other` only partially overlaps `this`
        if (!otherExclude.size && thisExclude.size && getMultiValueFilterRelation(otherInclude, thisExclude) === 'disjoint') {
            return 'unknown';
        }
        // if `other` excludes some, but `this` includes all, `other` is missing some
        if (!thisExclude.size && !thisInclude.size && !otherInclude.size && otherExclude.size) { return 'unknown'; }

        if (thisExclude.size && otherExclude.size) {
            // If `other` is a proper subset of `this`, then `other` excludes fewer items than `this`, so it can provide
            // all. E.g. `this` = ~{A, B} and `other` = ~{A} means `this` = {C...Z} and `other` = {B...Z}. If `other`
            // excludes the same items as `this`, then they are identical. This condition is easier to eliminate than to
            // find all the 'unknown' cases.
            if (otherExclude.isSubsetOf(thisExclude)) { return 'subset'; }
            // If `this` is not a subset of `other`, then it is either disjoint or intersects. If the two are disjoint,
            // then each is missing something, but overlaps on everything else, so relation is 'unknown'. Otherwise, if
            // there is partial overlap, but `other` is not a subset of `this`, then each is missing something, but
            // overlaps on everything else, so relation is 'unknown'.
            return 'unknown';
        }

        return 'subset';
    }

    private _getDiscardedTypeRelationToFilter(other: AdobeAssetFilter): ItemFilterRelation {
        if (this._isDiscarded === other._isDiscarded || other._isDiscarded === undefined) {
            return 'subset';
        }

        if (this._isDiscarded === undefined) {
            return 'unknown';
        }

        // If one is discarded and the other is not, then they are disjoint.
        return 'disjoint';
    }
}
