// keeps `capacity` most recently added strings
export default class FIFOStringSet {
    private _cache: Map<string, number>;
    private _capacity: number;

    constructor(capacity: number = 10) {
        this._cache = new Map();
        this._capacity = capacity;
    }

    has(key: string): string | undefined {
        if (this._cache.get(key)) {
            return key;
        }
        return undefined;
    }

    add(key: string): void {
        if (this._cache.has(key)) {
            this._cache.delete(key); // update timestamp if key already exists
        } else if (this._cache.size >= this._capacity) {
            // remove least recently added item
            const oldestKey = Array.from(this._cache.entries()).reduce((oldest, entry) => {
                return oldest[1] < entry[1] ? oldest : entry;
            })[0];
            this._cache.delete(oldestKey);
        }
        this._cache.set(key, Date.now());
    }
}
