import { SAM } from '@ccx-public/component-types';
import ItemBase from '../core/ItemBase';
import PropertyUpdater from '../core/PropertyUpdater';
import ItemUpdater from '../core/ItemUpdater';
import type {
    CollaboratorType,
    ICollaboratorAdditionalData,
    IComputedInvitationCollaborator,
    InheritanceType,
    RebacRole,
    Role
} from '../interface/InvitationModel';
import {
    memoize,
    observable
} from '../core/decorators';
import { SharedCollaboratorChangedEvent } from '../indexPrivate';
import { AvatarSizes } from './AvatarSizes';
import oneTimeWarning from '../utils/oneTimeWarning';
import { AddressBookContactUpdater } from './AddressBookContact';
import type {
    GroupMemberConfig,
    GroupMemberSource
} from './GroupMemberSource';
import GroupMemberLoader from './GroupMemberLoader';
import AddressBookInterface from '../interface/AddressBookInterface';
import ItemSource from '../core/ItemSource';
import SAMError from '../core/SAMError';
import { extractAddressBookIdent } from '../interface/AddressBookModel';

export type CollaboratorRole = Role;
export const CollaboratorRoles: CollaboratorRole[]  = [ 'owner', 'viewer', 'editor', 'none' ];
export const RebacRoles: RebacRole[] = [ 'manager', 'editor', 'viewer', 'commenter' ];
const ContributorRoles: CollaboratorRole[] = [ 'editor', 'owner' ];
export type { CollaboratorType } from '../interface/InvitationModel';
const CollaboratorTypes: CollaboratorType[] = [
    'imsUser',
    'addressBookGroup',
    'addressBookContact',
    'predefinedPrincipal',
    'imsGroup',
];

// deep means that resource members have permission on the resource and all of its children.
// deep_override is for admins and owners in user storage, meaning the same as deep but it cannot be denied.
// If an admin is invited to collaborate, then they have both [deep_override, deep]
export type { InheritanceType } from '../interface/InvitationModel';
export const InheritanceTypes: InheritanceType[] = [ 'self', 'deep', 'deep_override' ];

/**
 * A Collaborator represents the relationship between the user and the
 * asset. Users have other Profile information that is unique to the user.
 *
 * Eventually we will offer a Profile class with a Profile context that
 * offers information unrelated to an asset.
 */
export default class Collaborator extends ItemBase implements SAM.Collaborator {
    private _role: CollaboratorRole = 'viewer';
    private _rebacRole?: RebacRole;
    private _type: CollaboratorType = 'imsUser';
    private _inheritances?: InheritanceType[];
    private _additionalData?: ICollaboratorAdditionalData;
    private _isDirect: boolean = false;
    private _assetID: string = '';
    private _canDiscover: boolean = false;
    private _canShare: boolean = false;
    private _commentPermissions: string[] = [];
    private _mutable: boolean = true;

    get assetId(): string {
        return this._assetID;
    }

    /**
     * Returns false if the Behance/PPS service
     * was unable to return a profile for this collaborator.
     * @deprecated -- clients should just check that profile info is not undefined (SAM-3420). Will be removed on or
     *                after 2024-10-01
     */
    get hasProfile(): boolean | undefined {
        oneTimeWarning('Collaborator.hasProfile', 'Collaborator.hasProfile is deprecated and will be'
            + ' removed on or after 2024-10-01');
        // This used to return the private property _hasProfile, but since _hasProfile was never
        // set correctly, we're just returning undefined here to avoid confusion.
        // This getter will eventually be removed by SAM-3420.
        return undefined;
    }

    // `imsUser id` if invited via user email directly
    // `addressBookContact id` (i.e urn.ab:contact:...) if members are invited via shareSheet's recommend dropdown
    // `addressBookGroup id` (i.e urn:ab:group:...) if groups are invited via shareSheet's recommend dropdown
    get collaboratorID(): string {
        return this.id;
    }

    // Track the imsUser id
    // - Same as 'id' for direct invited collaborators
    // - Represents the collaborator actual ims id for addressBookContact, which is useful to check (compare ims id)
    // for thing like if the logged in user is in the collaborator list ,...
    // - undefined for 'addressBookGroup'
    get imsUserId(): string | undefined {
        const type = this._type;
        if (type === 'imsUser') {
            return this.id;
        }

        return this._additionalData?.linkedIdentity;
    }

    @observable(SharedCollaboratorChangedEvent)
    // Collaborator email
    get email(): string | undefined {
        return this._additionalData?.email;
    }

    // Collaborator name for imsUser and addressBookContact
    // Group name for addressBookGroup
    @observable(SharedCollaboratorChangedEvent)
    get name(): string | undefined {
        const additionalData = this._additionalData;
        return (additionalData?.displayName
            ?? additionalData?.groupName
            ?? additionalData?.organizationName);
    }

    get role(): CollaboratorRole {
        return this._role;
    }

    get rebacRole(): RebacRole | undefined {
        return this._rebacRole;
    }

    get type(): CollaboratorType {
        return this._type;
    }

    get commentPermissions(): string[] {
        return this._commentPermissions;
    }

    get inheritances(): InheritanceType[] | undefined {
        return this._inheritances;
    }

    get isDirect() {
        return this._isDirect;
    }

    get hasContributorRole() {
        return ContributorRoles.includes(this._role);
    }

    get hasName() {
        return !!this.name;
    }

    get invited() {
        return this._inheritances?.includes('deep');
    }

    get isAdmin() {
        return this._inheritances?.includes('deep_override');
    }

    get canDiscover(): boolean {
        return this._canDiscover;
    }

    get canShare(): boolean {
        return this._canShare;
    }

    /**
     * Indicates whether this collaborator's permissions can be modified.
     * When false, the collaborator's role and permissions should be treated as read-only.
     * This is typically false for system-managed collaborators or special principals.
     */
    get mutable(): boolean {
        return this._mutable;
    }

    get additionalData(): ICollaboratorAdditionalData | undefined {
        return this._additionalData;
    }

    /**
     * Checks if this collaborator is the user that is currently logged in.
     *
     * **NOTE**: It is not safe to assume that Collaborator.id === currentUserId
     *           will work. Always use Collaborator.isCurrentUser instead.
     */
    get isCurrentUser() {
        return this._core._environment.getValue('USER_ID') === this.imsUserId;
    }

    /**
     * Returns a standard size of 138x138
     */
    @observable(SharedCollaboratorChangedEvent)
    get avatarURL(): string {
        return this.getAvatarURL(AvatarSizes.Size138);
    }

    @observable(SharedCollaboratorChangedEvent)
    getAvatarURL(size: AvatarSizes): string {
        return this._additionalData?.images?.[size] ?? '';
    }

    @observable(SharedCollaboratorChangedEvent)
    get addressBookGroupUrn(): string {
        return this._additionalData?.groupUrn || '';
    }

    /**
     * Lists AddressBookContacts for an AddressBook Group.
     *
     * @experimental -- given the way this feature was rushed in, and some gaps in knowledge
     * about ABS and GenAI, this may not be the final API. Backward-compatibility will not
     * be guaranteed.
     *
     * @returns {Promise<GroupMemberSource>}
     */
    @memoize
    async getGroupMemberSource(): Promise<GroupMemberSource> {
        if (this.type !== 'addressBookGroup') {
            throw SAMError.create(SAM.SAMErrorCode.BAD_REQUEST,
                'groupMemberSource only applies to addressBookGroup Collaborator');
        }
        if (!this.addressBookGroupUrn) {
            throw SAMError.create(SAM.SAMErrorCode.BAD_REQUEST, 'addressBookGroupUrn is required');
        }
        const abs = new AddressBookInterface(this._core);
        const url = await abs.getAddressBookURL(this.addressBookGroupUrn);
        const addressBookIdent = extractAddressBookIdent(url);
        const pool = this._core.collaborationContext._getAddressBookContactPool(addressBookIdent);

        const loader = new GroupMemberLoader(
            url,
            pool,
            abs,
            AddressBookContactUpdater
        );

        return new ItemSource<GroupMemberConfig>(pool, [ loader ]);
    }
}

export const CollaboratorUpdater = new ItemUpdater<Collaborator, Partial<IComputedInvitationCollaborator>>({
    localItemType: Collaborator,
    remoteIdProperty: 'id',
    changeEvent: SharedCollaboratorChangedEvent,
    propertyUpdater: new PropertyUpdater({
        '_type': { name: 'type', choices: CollaboratorTypes },
        '_role': { name: 'role', choices: CollaboratorRoles },
        '_rebacRole': { name: 'rebacRole', choices: RebacRoles },
        '_inheritances': { name: 'inheritances', isArray: true, choices: InheritanceTypes },
        '_additionalData': { name: 'additionalData', format: 'object' },
        '_isDirect': { name: 'isDirect', format: 'boolean' },
        '_avatarURLs': { name: 'avatarURLs', format: 'object' },
        '_assetID': { name: 'assetID', format: 'string' },
        '_canDiscover': { name: 'canDiscover', format: 'boolean' },
        '_canShare': { name: 'canShare', format: 'boolean' },
        '_commentPermissions': { name: 'commentPermissions', isArray: true },
        '_mutable': { name: 'mutable', format: 'boolean' },
    })
});
