import type { RepositoryMetadata } from '../interface/RepositoryModel';
import { RelType } from '../interface/LinkUtils';

export default function addProjectIdToMetadata(metadata: RepositoryMetadata, parentId: string) {
    metadata._embedded ||= {};
    metadata._embedded[RelType.APP_METADATA] ||= {};
    metadata._embedded[RelType.APP_METADATA]!['cc:inherited'] ||= {};
    metadata._embedded[RelType.APP_METADATA]!['cc:inherited']!['cc:team'] ||= {};
    metadata._embedded[RelType.APP_METADATA]!['cc:inherited']!['cc:team']!['repo:assetId'] = parentId;
}
