import type AdobeAsset from '../assets/AdobeAsset';
import { createItemOrderFactory } from '../core/ItemOrder';
import { compareValues } from '../core/ItemOrder';
import type { IComparatorMap } from '../core/ItemOrder';
import type StudentAssignmentFile from './StudentAssignmentFile';

export type StudentAssignmentFileOrderField = 'modified' | 'name' | 'created';

const OrderFieldToComparator: IComparatorMap<StudentAssignmentFile, StudentAssignmentFileOrderField> = {
    modified(a: AdobeAsset, b: AdobeAsset): number {
        return compareValues(a.modified, b.modified);
    },
    name(a: AdobeAsset, b: AdobeAsset): number {
        return compareValues(a.name, b.name);
    },
    created(a: AdobeAsset, b: AdobeAsset): number {
        return compareValues(a.created, b.created);
    },
};

export default class StudentAssignmentFileOrder extends createItemOrderFactory(OrderFieldToComparator) {
    static default = new StudentAssignmentFileOrder('descending', 'modified');
}
