import type { SAM } from '@ccx-public/component-types';
import type { IProjectsOrderBy } from '../interface/ProjectsModel';

import type { IComparatorMap } from '../core/ItemOrder';
import { compareStrings, compareValues, createItemOrderFactory } from '../core/ItemOrder';
import type Project from './Project';
import { LastAccessedOrderField } from '../interface/USSModel';

export type ProjectOrderField =
    | 'name'
    | 'created'
    | 'lastAccessed';

export const OrderFieldToIProjectsOrderBy: { [key in ProjectOrderField]: IProjectsOrderBy } = {
    'name': 'repo:name',
    'created': 'repo:createDate',
    'lastAccessed': LastAccessedOrderField
};

const OrderFieldToComparator: IComparatorMap<Project, ProjectOrderField> = {
    name(a: Project, b: Project): number {
        return compareStrings(a.name, b.name);
    },
    created(a: Project, b: Project): number {
        return compareValues(a.created, b.created);
    },
    lastAccessed(a: Project, b: Project): number {
        return compareValues(a.lastAccessed, b.lastAccessed);
    }
};

export default class ProjectOrder extends createItemOrderFactory(OrderFieldToComparator) implements SAM.ProjectOrder {
    static default = new ProjectOrder('ascending', 'name');
    static createdDesc = new ProjectOrder('descending', 'created');
    static lastAccessed = new ProjectOrder('descending', 'lastAccessed');
}
