import {
    getDateRangeRelation,
    getMultiValueFilterRelation,
    type IExplicitFilter,
    type ItemFilterRelation
} from '../core/ItemFilter';
import type AssetVersion from './AssetVersion';

export interface IAssetVersionFilterOptions {
    readonly isMilestone?: boolean;
    readonly createdAfter?: Date;
    readonly createdBefore?: Date;
    readonly createdBy?: string[];
    readonly version?: string;
}

export default class AssetVersionFilter implements IExplicitFilter<AssetVersion> {
    private _isMilestone: boolean | undefined;
    private _createdAfter: Date | undefined;
    private _createdBefore: Date | undefined;
    private _createdBy: string[] | undefined;
    private _version: string | undefined;

    constructor(options?: IAssetVersionFilterOptions) {
        this._isMilestone = options?.isMilestone;
        this._createdAfter = options?.createdAfter;
        this._createdBefore = options?.createdBefore;
        this._createdBy = options?.createdBy;
        this._version = options?.version;
    }

    static BookmarkedVersions = new AssetVersionFilter({
        isMilestone: true
    });

    static AssetVersionFilter(isMilestone?: boolean, createdAfter?: Date, createdBefore?: Date, createdBy?: string[], version?: string) {
        return new AssetVersionFilter({
            createdBy,
            createdAfter,
            createdBefore,
            isMilestone,
            version
        });
    }

    get isMilestone(): boolean | undefined {
        return this._isMilestone;
    }

    get createdBy(): string[] | undefined {
        return this._createdBy;
    }

    get createdAfter(): Date | undefined {
        return this._createdAfter;
    }

    get createdBefore(): Date | undefined {
        return this._createdBefore;
    }

    get version(): string | undefined {
        return this._version;
    }

    get hash(): string {
        const collaborator = this.createdBy?.join(',');
        const createdAfter =  this.createdAfter?.getTime() || 0;
        const createdBefore =  this.createdBefore?.getTime() || 0;
        const version = this.version || undefined;
        return String(this.isMilestone) + ':'
            + collaborator + ':'
            + createdAfter + ':' + createdBefore + ':' + version;
    }

    matches(item: AssetVersion): boolean {
        const matchesBookmark = this.isMilestone === undefined || this.isMilestone === Boolean(item.milestone);
        const matchesCollab = this.createdBy === undefined || this.createdBy.includes(item.createdBy);
        const matchesDateRange = (!this.createdAfter || item.created >= this.createdAfter) && (!this.createdBefore || item.created <= this.createdBefore);
        const matchesVersion = this.version === undefined || this.version === item.versionId;
        return matchesBookmark && matchesCollab && matchesDateRange && matchesVersion;
    }

    private _getRelationWrtMilestone(other: AssetVersionFilter): ItemFilterRelation {
        return this.isMilestone === other.isMilestone ? 'subset' : this.isMilestone === undefined || other.isMilestone === undefined ? 'unknown' : 'disjoint';
    }

    private _getRelationWrtCreatedBy(other: AssetVersionFilter): ItemFilterRelation {
        return getMultiValueFilterRelation(this._createdBy, other._createdBy);
    }

    private _getRelationWrtDateRange(other: AssetVersionFilter): ItemFilterRelation {
        return getDateRangeRelation(this._createdAfter, this._createdBefore, other._createdAfter, other._createdBefore);
    }

    private _getRelationWrtVersion(other: AssetVersionFilter): ItemFilterRelation {
        if (this.version === other.version) {
            return 'subset';
        }
        if (this.version === undefined || other.version === undefined) {
            return 'unknown';
        }
        return 'disjoint';
    }

    getRelationToFilter(other: AssetVersionFilter): ItemFilterRelation {
        const relations = [
            this._getRelationWrtMilestone(other),
            this._getRelationWrtCreatedBy(other),
            this._getRelationWrtDateRange(other),
            this._getRelationWrtVersion(other)
        ];
        if (relations.includes('disjoint')) {
            return 'disjoint';
        }
        if (relations.includes('unknown')) {
            return 'unknown';
        }
        // only remaining possibility is 'subset'
        return 'subset';
    }
}
