import type IEvent from '../IEvent';
import { SharedChangeEvent } from '../ChangeEvent';
import type {
    SAMObjectEventEmitter,
    SAMObjectUntypedEventEmitter
} from '../SAMObjectEventEmitter';


const $OBSERVABLE_MAP = Symbol('$OBSERVABLE_MAP');

type ObservableMap = Map<string, IEvent>;
type ITarget = SAMObjectUntypedEventEmitter | SAMObjectEventEmitter;

export function getEventForProp(obj: any, prop: string): IEvent | undefined {
    return (obj[$OBSERVABLE_MAP] as ObservableMap || undefined)?.get(prop);
}

export function getPropsForEvent(obj: any, event: IEvent): string[] {
    return [ ...(obj[$OBSERVABLE_MAP] as ObservableMap || new Map()).entries() ]
        .filter(([ , mappedEvent ]) => mappedEvent === event)
        .map(([ prop ]) => prop);
}

function setEventForProp(obj: any, prop: string, event: IEvent) {
    let map: ObservableMap;
    // Detect if a map exists and whether or not it is inherited
    if (Object.getOwnPropertyDescriptor(obj, $OBSERVABLE_MAP)) {
        // not inherited, and it already exists
        map = obj[$OBSERVABLE_MAP];
    } else if (obj[$OBSERVABLE_MAP]) {
        // Inherited, and it exists on the parent. The properties of the child class should not be mapped in the parent
        // class, but the child class should have all the mapped properties of the parent class. So create a new map
        // for the child that is a copy of the parent's map.
        map = new Map(obj[$OBSERVABLE_MAP]);
        obj[$OBSERVABLE_MAP] = map;
    } else {
        // Not inherited, and it does not exist
        map = new Map();
        obj[$OBSERVABLE_MAP] = map;
    }

    // TODO: warn if event is changed for a prop?
    map.set(prop, event);
}

export function observableImpl(event: IEvent, privatePropNames?: string[]) {
    return (target: ITarget, key: string, descriptor: PropertyDescriptor): void => {
        if (descriptor.get || descriptor.value) {
            privatePropNames?.forEach(prop => setEventForProp(target, prop, event));
        }
        if (descriptor.get) {
            const getter = descriptor.get;
            descriptor.get = function (this: ITarget) {
                this._core._environment.mobx.reportObserved(this, event.type);
                return getter.call(this);
            };
        } else if (descriptor.value) {
            const method = descriptor.value;
            const newMethod = function (this: ITarget, ...args: any[]): any {
                this._core._environment.mobx.reportObserved(this, event.type);
                return (method as any).apply(this, args);
            };
            descriptor.value = newMethod;
        } else {
            throw new Error('@observable decorator can only be used with `getters` or `methods`.');
        }
    };
}

// With `@observable` (no parens), observable is called with target, key, descriptor
function observable(target: ITarget, key: string, descriptor: PropertyDescriptor): void;
// @observable(SomeEvent)
// @observable(SomeEvent, '_prop1')
// @observable(SomeEvent, ['_prop1', '_prop2'])
function observable(event: IEvent, privatePropNames?: string | string[]): ReturnType<typeof observableImpl>;
function observable(arg1: IEvent | ITarget, arg2?: string | string[], arg3?: PropertyDescriptor): ReturnType<typeof observableImpl> | void {
    // @observable without parens
    if (arg1 && arg2 && arg3) {
        return observableImpl(SharedChangeEvent)(arg1 as ITarget, arg2 as string, arg3);
    }
    // @observable(SomeEvent)
    // @observable(SomeEvent, '_prop1')
    // @observable(SomeEvent, ['_prop1', '_prop2'])
    if (typeof (arg1 as IEvent).type === 'string' && (typeof arg2 === 'string' || typeof arg2 === 'undefined' || Array.isArray(arg2))) {
        arg2 = arg2 ? [].concat(arg2 as any) : undefined;
        return observableImpl(arg1 as IEvent, arg2);
    }
    throw new Error('Invalid arguments for @observable');
}

export default observable;
