import { gql } from '../generated/typed-gql';

// using typed-gql to generate the fragment allows this to be used in any query or mutation
export const typedRepoMetadataFragment = gql(/* GraphQL */ `
    fragment repoMetadata on Asset {
        repo_assetId
        repo_name
        repo_path
        repo_createDate
        repo_createdBy {
            id
        }
        repo_modifyDate
        repo_modifiedBy
        primary_etag
        repo_state
        repo_representations {
            composite
            directory
            file
        }
        dc_format
        storage_deviceCreateDate
        storage_deviceModifyDate
        storage_region
        storage_assignee {
            id
            type
        }
        repository {
            repo_repositoryId
            repo_repositoryType
            repo_owner {
                id
            }
        }
        repo_ancestors
        repo_ancestorInfo{
            assetId
            assetSubType
            assetType
        }
        repo_assetClass
        repo_assetType
        repo_assetSubType
        repo_pinnedVersion
        repo_pinnedVersionModifyDate
        repo_capabilities {
            file { name type state error }
            composite { name type state error }
            directory { name type state error }
        }
        primaryLink {
            href
            templated
        }
        blockUploadLink {
            href
            templated
        }
        ... on Composite {
            repo_version
            repo_size
            isComposite
            primaryLink {
                href
            }
            blockDownloadLink {
                href
            }
            renditionLink {
                href
            }
            componentLink {
                href
            }
        }
        ... on File {
            repo_version
            repo_size
            isFile
            primaryLink {
                href
            }
            blockDownloadLink {
                href
            }
            renditionLink {
                href
            }
            tiff_imageLength
            tiff_imageWidth
        }
    }
`);

