import { CustomModelOrderBy } from './LegacyCustomModelModel';
import type { IComparatorMap } from '../../core/ItemOrder';
import { compareStrings, compareValues, createItemOrderFactory } from '../../core/ItemOrder';

import type LegacyCustomModel from './LegacyCustomModel';

export type CustomModelOrderField =
    | 'name'
    | 'created'
    | 'modified';

export const LegacyOrderFieldToCustomModelOrderBy: { [key in CustomModelOrderField]: CustomModelOrderBy} = {
    'name': CustomModelOrderBy.NAME,
    'created': CustomModelOrderBy.CREATE_DATE,
    'modified': CustomModelOrderBy.MODIFY_DATE
};

const OrderFieldToComparator: IComparatorMap<LegacyCustomModel, CustomModelOrderField> = {
    name(a: LegacyCustomModel, b: LegacyCustomModel): number {
        return compareStrings(a.name, b.name);
    },

    created(a: LegacyCustomModel, b: LegacyCustomModel): number {
        return compareValues(a.created, b.created);
    },

    modified(a: LegacyCustomModel, b: LegacyCustomModel): number {
        return compareValues(a.modified, b.modified);
    }
};

export default class LegacyCustomModelOrder extends createItemOrderFactory(OrderFieldToComparator) {
    static default = new LegacyCustomModelOrder('descending', 'modified');
}
