//----------------------------------------------------------------

type FrameioCloudSourceDocument = {
    assetId: string;
    assetRegion?: string;
    repositoryId?: string;
    documentId?: never;
}

type FrameioLocalSourceDocument = {
    documentId: string;
    assetId?: never;
    assetRegion?: never;
    repositoryId?: never;
}

// When the source is a local-only document, you must provide only the documentId.
//
// When the source is a creative cloud document, you must provide an assetId,
// you cannot provide a documentId, and you can optionally provide the assetRegion
// and repositoryId for potential performance gains.
export type FrameioSourceDocument =  (FrameioCloudSourceDocument | FrameioLocalSourceDocument);

//----------------------------------------------------------------

type FrameioReviewLinkForDocumentError = {
    error: SAMError;
    reviewLink?: never;
}

type FrameioReviewLinkForDocumentReviewLink = {
    error?: never;
    reviewLink: FrameioReviewLink;
}

// getReviewLinksForDocument() returns a Promise<Array<FrameioReviewLinkForDocumentItem>>
export type FrameioReviewLinkForDocumentItem =  (FrameioReviewLinkForDocumentError | FrameioReviewLinkForDocumentReviewLink);

//----------------------------------------------------------------

export interface FrameioContextEvents extends IEventMap {
    frameioAuthorizationChange: FrameioAuthorizationChangeEvent;
    frameioReviewLinksChange: FrameioReviewLinksChangeEvent;
}

//----------------------------------------------------------------

export default class FrameioContext extends TypedEventEmitter<FrameioContextEvents> implements ISAMObject, SAM.FrameioContext {
    /**
     * @package - internal use only
     */
    _objectPool: ItemPool<FrameioBase> = new ItemPool(this._core, 'frameio');

    /**
     * @package - internal use only
     */
    _frameioInterface: FrameioInterface = new FrameioInterface(this);

    /**
     * @package - internal use only
     */
    _reviewServiceInterface: AssetReviewServiceInterface = new AssetReviewServiceInterface(this._core);

    private _currentUserId: string | undefined;
    private _currentUser: FrameioUser | undefined;
    private _accounts: Array<FrameioAccount> | undefined;
    private _reviewLinksForDocument: Map<string, WeakRef<Array<FrameioReviewLinkForDocumentItem>>> = new Map();

    constructor(readonly _core: ISAMCorePrivate) {
        super();
    }
    /**
     * @package
     *
     * We _updateUserId() whenever the native FrameioAssetContext::authInfo_
     * changes, to allow us to reset any user specific data when the user id
     * changes.
     */
    _updateCurrentUserId(id: string | undefined) {
        if (!id || (this._currentUserId !== id)) {
            this._currentUserId = id;
            this._currentUser = undefined;
            this._accounts = undefined;
            this._reviewLinksForDocument.clear();
        }
    }

    private _mapKeyForSourceDocument(source: FrameioSourceDocument): string {
        // We need a hash key for a Map<>,
        // so use the assetId of cloud documents,
        // and the documentId of local documents.
        if (source.documentId) {
            return source.documentId;
        }

        // ignore the optional assetRegion and repositoryId
        return source.assetId!;
    }

    private _retainUntilTimeout(weak: WeakRef<Array<FrameioReviewLinkForDocumentItem>>, milliseconds = 2 * 60 * 1000) {
        const obj = weak.deref();

        // obj will be retained until the timeout fires
        // because it's referenced in the handler.
        setTimeout(function (): any { return obj; }, milliseconds);
    }

    _handleReviewLinksChangeEvent(json: string): void {
        // after a successful FrameioReviewLink.updateReviewLink(),
        // we use SAM.cpp to dispatch an event to all DOM's,
        // so they can each update FrameioContext._reviewLinksForDocument
        //
        // For example, when ShareSheet creates a new review link,
        // ShareSheet and Commenting want to update their cache.
        //
        // See also FrameioReviewLink._dispatchReviewLinksChangeEvent()

        const param: FrameioReviewLinksChangeEventParam = JSON.parse(json);
        const response: Partial<IFrameioReviewLinkResponse> = param.reviewLink;
        const key: string = this._mapKeyForSourceDocument(param.source);

        const session = this._objectPool.createUpdateSession<FrameioReviewLink>();
        const reviewLink = FrameioReviewLinkUpdater.updateRemoteItem(session, response);
        session.commit();

        const weak = new WeakRef([ { reviewLink } ]);

        this._reviewLinksForDocument.set(key, weak);
        this._retainUntilTimeout(weak);

        // let client know the reviewLinksForDocument has changed.
        this.dispatch(SharedFrameioReviewLinksChangeEvent);
    }

    async isAuthenticated(): Promise<boolean> {
        return await this._frameioInterface.isAuthenticated();
    }

    async authenticationStatus(): Promise<IFrameioAuthenticationStatus> {
        return await this._frameioInterface.authenticationStatus();
    }

    // !!@ Consider making this package scoped
    async getToken(): Promise<string> {
        return this._frameioInterface.getToken();
    }

    async refreshToken(): Promise<string> {
        return this._frameioInterface.refreshToken();
    }

    /* Call with void parameters to rely on native authentication.
     * The return is a token.
     */
    async authenticate(info?: FrameioAuthenticationInfo): Promise<string> {
        return await this._frameioInterface.authenticate(info);
    }

    async deauthenticate(): Promise<void> {
        return await this._frameioInterface.deauthenticate();
    }

    async getCurrentUser(): Promise<FrameioUser> {
        let user = this._currentUser;
        if (!user) {
            const response = await this._frameioInterface.getCurrentUser();
            const session = this._objectPool.createUpdateSession<FrameioUser>();
            user = FrameioUserUpdater.updateRemoteItem(session, response);
            session.commit();

            this._currentUser = user;
        }
        return user;
    }


    async getAccounts(): Promise<Array<FrameioAccount>> {
        let accounts = this._accounts;
        if (!accounts) {
            const response = await this._frameioInterface.getAccounts();
            const session = this._objectPool.createUpdateSession<FrameioAccount>();
            accounts = FrameioAccountUpdater.updateRemoteItems(session, response);
            session.commit();
            this._accounts = accounts;
        }

        return accounts;
    }

    private _getLocalAncestors(id: string): Array<FrameioAsset> | undefined {
        // Based on prior usage of the package, it's possible
        // we can build ancestors from already local objects
        // in the _objectPool. If so, return the completed
        // array so getAncestors() can avoid the server call.
        //
        // However, if not all of the ancestors are locally available,
        // make the server call to get the entire array.
        const ancestors = new Array<FrameioAsset>();

        for (;;) {
            const asset = this._objectPool.getLocalItemById(id) as FrameioAsset;

            if (asset === undefined) {
                // At least one item isn't local,
                // so we'll need to GET the ancestors from the server.
                return undefined;
            }

            // add latest ancestor to front of array
            ancestors.unshift(asset);

            // walk up one link of the ancestor chain
            if (asset.parentId) {
                id = asset.parentId;
                continue;
            }

            // we've reached the root asset of the project
            break;
        }
        return ancestors;
    }

    async getAncestors(id: string): Promise<Array<FrameioAsset>> {
        // ideally, the whole ancestor chain is already local,
        // and we can fulfill this promise without a server call.
        let ancestors = this._getLocalAncestors(id);

        if (!ancestors) {
            const response = await this._frameioInterface.getAncestors(id);
            const session = this._objectPool.createUpdateSession<FrameioAsset>();

            // IFrameioAssetResponse is a special case, as it corresponds to multiple classes
            // inheriting from FrameioAsset ( FrameioFile, FrameioFolder, FrameioVersionStack ),
            // so use a utility function to select the correct updater for the type.
            //
            // See also FrameioFolder.getChildren()
            ancestors = response.map((asset: IFrameioAssetResponse) => frameioAssetUpdater(session, asset));

            session.commit();
        }

        return ancestors;
    }

    async getReviewLinksForDocument(source: FrameioSourceDocument, refresh: boolean = true): Promise<Array<FrameioReviewLinkForDocumentItem>> {
        const key: string = this._mapKeyForSourceDocument(source);
        const weak = this._reviewLinksForDocument.get(key);
        let result: Array<FrameioReviewLinkForDocumentItem> | undefined = weak ? weak.deref() : undefined;

        if (!refresh && result) {
            this._retainUntilTimeout(weak!); // non-null result means weak is also non-null
            return result; // return cached result
        }

        // compute result from scratch
        result = [];

        // The Review Service maintains a database of FrameioReview links we've
        // created maintained by our calls to ReviewServiceInterface.createReviewLinks()
        // and ReviewServiceInterface.updateReviewLinks().

        // Get the list of review links
        const reviews: Array<IReviewServiceFrameLinkResponse> = await this._reviewServiceInterface.getReviewLinks(source);

        // I'm uncertain of the list ordering, so sort it by date.
        reviews.sort((a, b) => (b['repo:createdDate'] - a['repo:createdDate']));

        // The id's associated with a review link may no longer be valid
        // ( i.e. the link has been deleted ) or not currently valid
        // ( i.e. we've logged into the wrong account ), so we need
        // to filter the list to only containing currently valid
        // review links.
        //
        // NOTE: As we cannot distinquish between no longer valid and
        // not currently valid, it's not safe to
        // ReviewServiceInterface.deleteReviewLinks() to clean up the
        // list.

        for (let i = 0; i < reviews.length; i++) {
            const review = reviews[i];
            const projectId = review['frameio:projectId'];
            const reviewLinkId = review['frameio:reviewLinkId'];
            const itemId = review['frameio:artifactId'];
            const etag = review['repo:etag'];

            // review is valid if we can obtain a reviewLink using reviewLinkId,
            // and we can obtain an item using itemId.
            //
            // ShareSheet potentially shows toast when the most recent reviewLinks
            // are invalid, so we push FrameioReviewLinkForDocumentError into
            // result when there's an error validating review.
            //
            // Because validation is expensive, and because reviews[] grows
            // unbounded, and because ShareSheet only cares whether there is
            // 0 or 1 valid reviews, we stop after adding a valid reviewLink
            // to result.

            let reviewLink: FrameioReviewLink | undefined = undefined;

            // obtain the reviewLink directly from Frame.io
            try {
                const response = await this._frameioInterface.getReviewLink(reviewLinkId);
                const session = this._objectPool.createUpdateSession<FrameioReviewLink>();
                reviewLink = FrameioReviewLinkUpdater.updateRemoteItem(session, response);
                session.commit();
            } catch (e) {
                // we expect it to throw when a review has been disabled.
            }

            try {
                if (!reviewLink) {
                    // disabled reviewLink's are known to throw 403 errors,
                    // so as a fallback, try to get the project, the project's
                    // list of reviewLinks, and find reviewLinkId in the list
                    // (disabled reviewLink's are known to be reachable this way)

                    // project is cached in the object pool,
                    // and project._reviewLinks is memoized,
                    // so although we are in a loop,
                    // each method should never hit the network more than once.
                    const project = await this.getProject(projectId);
                    const reviewLinks = await project.getReviewLinks();

                    reviewLink = reviewLinks.find(({ id }) => (id === reviewLinkId));
                }

                if (reviewLink) {
                    // Copy data that's on the Review Service and not Frame.io
                    // into the reviewLink.
                    reviewLink['_itemId'] = itemId;
                    reviewLink['_etag'] = etag;

                    // getItem() rejects when itemId isn't valid.
                    await reviewLink.getItem();

                    result.push({ reviewLink });
                    break;
                } else {
                    const error = SAMError.create(SAMErrorCode.NOT_FOUND, `frameio:reviewLinkId = ${reviewLinkId} not found in projectId = ${projectId}`);
                    result.push({  error });
                }
            } catch (e) {
                const error = e as SAMError;
                result.push({ error });
            }
        }

        const ref = new WeakRef(result);

        // cache the newly computed result
        this._reviewLinksForDocument.set(key, ref);
        this._retainUntilTimeout(ref);

        return result;
    }


    async getAccount(id: string): Promise<FrameioAccount> {
        const accounts = await this.getAccounts();
        let account = accounts.find(element => (element.id === id));

        if (!account) {
            const response = await this._frameioInterface.getAccount(id);
            const session = this._objectPool.createUpdateSession<FrameioAccount>();
            account = FrameioAccountUpdater.updateRemoteItem(session, response);
            session.commit();
        }

        return account;
    }

    @keepAlive
    async getAsset(id: string): Promise<FrameioAsset> {
        // avoid server call for local asset
        let asset = this._objectPool.getLocalItemById(id) as FrameioAsset;

        if (!asset) {
            // fetch remote asset with a server call
            const response = await this._frameioInterface.getAsset(id);
            const session = this._objectPool.createUpdateSession<FrameioAsset>();
            asset = frameioAssetUpdater(session, response);
            session.commit();
        }
        return asset;
    }

    async getTeam(id: string): Promise<FrameioTeam> {
        // avoid server call for local asset
        let team = this._objectPool.getLocalItemById(id) as FrameioTeam;

        if (!team) {
            // fetch remote asset with a server call
            const response = await this._frameioInterface.getTeam(id);
            const session = this._objectPool.createUpdateSession<FrameioTeam>();
            team = FrameioTeamUpdater.updateRemoteItem(session, response);
            session.commit();
        }
        return team;
    }

    async getProject(id: string): Promise<FrameioProject> {
        // avoid server call for local asset
        let project = this._objectPool.getLocalItemById(id) as FrameioProject;

        if (!project) {
            // fetch remote asset with a server call
            const response = await this._frameioInterface.getProject(id);
            const session = this._objectPool.createUpdateSession<FrameioProject>();
            project = FrameioProjectUpdater.updateRemoteItem(session, response);
            session.commit();
        }
        return project;
    }

    async getComment(id: string): Promise<FrameioComment> {
        // avoid server call for local asset
        let comment = this._objectPool.getLocalItemById(id) as FrameioComment;

        if (!comment) {
            // fetch remote asset with a server call
            const response = await this._frameioInterface.getComment(id);
            const session = this._objectPool.createUpdateSession<FrameioComment>();
            comment = FrameioCommentUpdater.updateRemoteItem(session, response);
            session.commit();
        }
        return comment;
    }

    async getAdobeSusiInfo(): Promise<FrameioAdobeSusiInfo> {
        return await this._frameioInterface.getAdobeSusiInfo();
    }
}

export function frameioAssetUpdater(session: IUpdateSession<FrameioBase>, asset: IFrameioAssetResponse): FrameioAsset {
    // frame.io multiplexes asset.type's 'file', 'folder', 'version_stack' and 'bundle' into IFrameioAssetResponse,
    // but we have separate FrameioFile, FrameioFolder, FrameioVersionStack classes that inherit from FrameioAsset.

    if (asset.type === 'file') {
        const fileSession = session as IUpdateSession<FrameioFile>;
        return FrameioFileUpdater.updateRemoteItem(fileSession, asset);
    } else if (asset.type === 'folder') {
        const folderSession = session as IUpdateSession<FrameioFolder>;
        return FrameioFolderUpdater.updateRemoteItem(folderSession, asset);
    } else if (asset.type === 'version_stack') {
        const versionStackSession = session as IUpdateSession<FrameioVersionStack>;
        return FrameioVersionStackUpdater.updateRemoteItem(versionStackSession, asset);
    }
    throw SAMError.create(SAMErrorCode.UNSUPPORTED, `Invalid Frameio asset type ${asset.type}`);
}
