// If multiple versions of SAM.js are loaded in the same app, they will have different
// contents in the closure of the module, so the Symbol used to store the global instances
// of SAMCore must be a global Symbol.
const $SAM_INSTANCE_MAP = Symbol.for('com.adobe.ccac-sam-js.instances');

// Matches ACPL log level enum
export enum LogLevel {
    Off,
    Err,
    Warn,
    Info,
    Debug
}

export type AssetPoolType = CustomModel | Assignment | StudentAssignment | StudentAssignmentFile | Project | Library | AdobeAsset | Board;

