    constructor(config: Configuration, hooks: Hooks = {}) {
        super();
        this._environment = new Environment(this, config, hooks);
        if (config.CACHE_KEEP_ALIVE_TTL) {
            KeepAliveManager.setTTL(config.CACHE_KEEP_ALIVE_TTL);
        }
    }

    /**
     * The primary ItemPool used by any context and item that extends AdobeAsset.
     *
     * @package - Used internally only.
     */
    _getAssetPool(): ItemPool<AssetPoolType> {
        return this._assetPool;
    }

    /**
     * @package -- Used for setting both the pure JS AssetContext,ts and the Native AssetContext
     * provided from the bindings.
     */
    async _setAssetContextFromBindings(nativeAssetContext: AssetContext): Promise<void> {
        if (this._AssetContext) {
            // If multiple SAM.js instances invoke this, only the first gets to set it. This
            // is likely a temporary condition while SAM.js clients converge on compatible versions.
            console.error('[SAMCore] AssetContext already initialized');
            return;
        }

        // Set the native context provided by the bindings.
        this._AssetContext = nativeAssetContext;

        // Set the pure JS Version of the context to be
        // accessed during patches to provide pure js functionality that
        // the native version doesn't provide.
        const AssetContext = (await import('../assets/AssetContext')).default;

        this._AssetContextJS = new AssetContext(this, this._assetPool);
    }

    /**
     * @package -- Used internally to synchronously get the loaded and cached instance
     * of AssetContext.
     */
    _getAssetContext(): AssetContext | undefined {
        return this._AssetContext;
    }

    /**
     * Returns an instance of AssetContext.
     * @note this method can only be used when integrating with SAM.js sources
     * and first calling initializeSharedAssetModel().
     *
     * @throws {SAMErrorCode.UNSUPPORTED} When initializeSharedAssetModel() has not been called first.
     * @deprecated -  use getAssetContext()
     */
    get hostAssetContext(): AssetContext {
        if (!this._AssetContext) {
            throw SAMError.create(
                SAMErrorCode.UNSUPPORTED,
                'samCore.hostAssetContext cannot be used without first calling initializeSharedAssetModel()'
            );
        }

        return this._AssetContext;
    }

    /** @package -- only for use in SAM.js */
    async _getGQLManager(): Promise<GQLManager> {
        if (!this._gqlManager) {
            const GQLManager = (await import('../graphql/GQLManager')).default;
            this._gqlManager = new GQLManager(this);
            await this._gqlManager.initialize();
        }
        return this._gqlManager;
    }

    /**
     * Returns an instance of the AssetContext class which can be used
     * to get the root folder and various sources for SWY or recent
     * documents.
     *
     * @returns {AssetContext}
     */
    @synchronized
    async getAssetContext(): Promise<AssetContext> {
        if (this._AssetContext) {
            return this._AssetContext;
        }

        const AssetContext = (await import('../assets/AssetContext')).default;
        this._AssetContext = new AssetContext(this, this._assetPool);
        await this._AssetContext._getONSContext();  // Ensure ONS Context is initialized.

        // @TODO https://jira.corp.adobe.com/browse/SAM-3580
        // Preload Collaboration Context since the ShareableItem.collaborators still requires some
        // work to fully separate the lazily loading of CollaborationContext only when  collaborators
        // and related features are required.
        await this.getCollaborationContext();
        return this._AssetContext;
    }

    /**
     * @deprecated use AssetContext.assetLinkManager going forward.
     *
     */
    @memoize
    get assetLinkManager(): AssetLinkManager {
        if (!this._AssetContext) {
            throw SAMError.create(
                SAMErrorCode.UNSUPPORTED,
                'samCore.assetLinkManager and samCore.assetContext cannot be used without first calling initializeSharedAssetModel()'
            );
        }

        if (!this._AssetContext._getAssetLinkManager()) {
            throw SAMError.create(
                SAMErrorCode.UNSUPPORTED,
                'samCore.assetLinkManager cannot be used without first calling initializeSharedAssetModel()'
            );
        }

        return this._AssetContext._getAssetLinkManager()!;
    }

