    /**
     * Provides Axon Client, representing an authenticated Axon Session over WebSocket protocol,
     * which facilitates creation of Virtual Channels to Adobe Sync Servies such as ONS.
     * This is a synchronous, promise-returning method, handling endpoint resolution,
     * authentication, configuration and singleton initialization of the AxonClient object.
     *
     * @package -- for use in SAM.js only
     */
    _getAxonClient(): Promise<AxonClient> {
        if (this._AxonClient) {  // Lazily initialized singleton instance.
            return this._AxonClient;
        }

        // Authenticated fetch function supporting abort signal and setting noApiKeyHeader.
        const authenticatedFetch: AxonClientAuthenticatedGet
            = async (url: string) => this._environment.fetch(url, { noApiKeyHeader: true });

        const axonConfig = new AxonClientConfig(
            this._environment.endpoints.AXON_HOST,  // Axon endpoint.
            authenticatedFetch,  // Must be of AxonClientAuthenticatedGet type.
            this._environment.logSink,  // Logging sink implementing LogSink interface.
        );

        if (this._environment.getValue('ENVIRONMENT') === Env.Stage) {
            // While on Stage, elevate the default log-level to DEBUG.
            axonConfig.logger.logLevel = AxonLogger.LogLevel.DEBUG;
        }
        const locale = this._environment.getValue('LOCALE');
        if (locale) { axonConfig.locale = locale; }
        this._AxonClient = Promise.resolve(new AxonClient(axonConfig));
        return this._AxonClient;
    }

