type SAMInstanceMap = { [s: string]: Promise<ISAMCore> };

declare global {
    interface Window {
        [$SAM_INSTANCE_MAP]: SAMInstanceMap;
    }
}

export async function initializeSharedAssetModel(config: Configuration, hooks: Hooks = {}): Promise<ISAMCore> {
    let samInstances: SAMInstanceMap = {};

    // SAM.js supports running in a node.js _environment, so we can't assume that window is defined.
    if (typeof window !== 'undefined') {
        if (!window[$SAM_INSTANCE_MAP]) {
            window[$SAM_INSTANCE_MAP] = samInstances;
        } else {
            samInstances = window[$SAM_INSTANCE_MAP];
        }
    }

    // Check to see if any versions of SAM.js have already been loaded that are compatible with us (using semantic versioning, the
    // major version must match, and the minor.patch version must be later than or equal to the one we need)
    const version = (config._VERSION_OVERRIDE_FOR_TEST !== undefined && config._VERSION_OVERRIDE_FOR_TEST !== '')
        ? config._VERSION_OVERRIDE_FOR_TEST
        : packageJSON.version;
    const [ major, minor, patch ] = version!.split('.').map(Number);
    const loadedVersions = Object.keys(samInstances);
    const compatibleLoadedVersion = loadedVersions.find(loadedVersion => {
        if (loadedVersion === version) {
            return true;
        }
        // If it's not an exact version match, we parse the versions and do a semantic version comparison - note that if
        // the major version is 0, it's assumed that all changes are breaking.
        const [ loadedMajor, loadedMinor, loadedPatch ] = loadedVersion.split('.').map(Number);
        return major !== 0 && loadedMajor === major && (loadedMinor > minor || (loadedMinor === minor && loadedPatch >= patch));
    });

    // If there's a compatible version, use it!
    if (compatibleLoadedVersion) {
        return samInstances[compatibleLoadedVersion];
    }

    // If not, create a new version (warn if this means there will be multiple SAM.js versions)
    if (loadedVersions.length > 0) {
        console.warn(`An instance of SAM.js already exists, but is not compatible with the requested version: ${version}. `
            + `Because of this, a new instance of SAM.js will be created. Loaded versions: ${loadedVersions.join(', ')}.`);
    }

    // Wait for host asset context, and patch SAM.cpp as needed
    // Presence of global acplModel tells us SAM.cpp JS bindings are present
    // @ts-expect-error
    const acplModel: any = (typeof window !== 'undefined') && window.acplModel;
    const enableACPLNextPolyfills = config.FEATURE_FLAGS?.['enable-acpl-next-polyfills'] ?? false;
    const disableSamCppModels = config.FEATURE_FLAGS?.['disable-sam-cpp-models'] ?? false;

    const isPatchableVersion = () => {
        // SAM.cpp 2.0.0-main.1301 is the earliest release that supports patching prototypes.
        const rootFolderProto = acplModel.applicationAssetContext?.rootFolder.constructor.prototype;
        return Boolean(rootFolderProto) && Object.getOwnPropertyDescriptor(rootFolderProto, 'name')?.configurable === true;
    };

    /**
     * Use before providing the core in order to
     * import and set contexts for use with clients who
     * are still integrating us by source.
     *
     * @param core {SAMCore}
     */
    const loadAndSetContexts = async (core: SAMCore) => {
        const useLazyContext = core._environment.getValue('LAZY_CONTEXT');

        if (enableACPLNextPolyfills) {
            await patchACPLNext(core);
        }

        if (!core._getAssetContext()) {
            await core.getAssetContext();
        }

        if (!useLazyContext) {
            const loadedAssetContext = core._getAssetContext()!;
            if (!loadedAssetContext._getAssetLinkManager()) {
                await loadedAssetContext.getAssetLinkManager();
            }

            if (!core._getProjectContext()) {
                await core.getProjectContext();
            }

            if (!core._getSpaceContext()) {
                await core.getSpaceContext();
            }

            if (!core._getClassroomContext()) {
                await core.getClassroomContext();
            }

            if (!core._getCollaborationContext()) {
                await core.getCollaborationContext();
            }

            if (!core._getLibraryContext()) {
                await core.getLibraryContext();
            }

            if (!core._getFrameioContext()) {
                await core.getFrameioContext();
            }

            if (!core._getCustomModelContext()) {
                await core.getCustomModelContext();
            }

            if (!core._getWorkfrontContext()) {
                await core.getWorkfrontContext();
            }
        }
    };

    samInstances[version] = new Promise<ISAMCore>((resolve, reject) => {
        if (acplModel && !config._DISABLE_SAM_CPP) {
            // Either immediately resolve with existing applicationAssetContext, or wait for it
            Promise.race([
                acplModel.applicationAssetContext ?? acplModel.waitForApplicationContextReady()
            ]).then(() => {
                try {
                    // If we can't (or shouldn't) patch this version of SAM.cpp, return a pure-JS implementation.
                    if (disableSamCppModels || !isPatchableVersion()) {
                        // This behavior is solidified by a test in SAMCore.spec.ts where "it should only patch SAM.ccp if it
                        // being patched".
                        const core = new SAMCore(config, hooks);
                        loadAndSetContexts(core)
                            .then(() => resolve(core));
                        return;
                    }
                    const core = new SAMCore(config, hooks);
                    // Patching should be done in this order, because the SAM.cpp prototypes aren't exposed in the global
                    // namespace, or on global `acplModel`, so the only way to get prototypes is to find an instance of
                    // the class and get a reference to `obj.constructor.prototype`. E.g., to patch AssetList, it needs
                    // to get it from `acplModel.applicationAssetContext.rootFolder.children.getList()`, so
                    // `AssetSource.getList()` cannot be patched yet.
                    patchAdobeAsset(core);
                    patchSpaceJS();
                    patchAssetList(core);
                    patchAssetSource(core);
                    patchAssetContext(core);

                    if (loadedVersions.length > 0) {
                        console.error('[initializeSharedAssetModel] SAM.cpp can only be observable by one'
                            + ' instance of SAMCore. Clients using SAM.js internal version ' + version + ' will not'
                            + ' see Mobx observables working. Clients on a host app should align on the same SAM.js'
                            + ' version before shipping to customers.');
                    }

                    // Provides the native context to SAM.js and creates a new
                    // instance of the pure JS AssetContext to also be used in the bindings.
                    core._setAssetContextFromBindings(acplModel.applicationAssetContext).then(() => {
                        resolve(core);
                    });
                } catch (e) {
                    console.error('[initializeSharedAssetModel] failed to patch SAM.cpp', e);
                    reject(e);
                }
            });
        } else {
            // No SAM.cpp present, use pure SAM.js implementation
            const samCore = new SAMCore(config, hooks);
            loadAndSetContexts(samCore)
                .then(() => resolve(samCore));
        }
    });

    // Do not cache failed initialization attempts
    try {
        await samInstances[version];
    } catch (e) {
        delete samInstances[version];
        throw e;
    }
    return samInstances[version];
}

/**
 * @deprecated Use {@link initializeSharedAssetModel} instead, will be removed on or after 2024-10-01.
 */
export function createSharedAssetModel(config: Configuration, hooks: Hooks = {}): ISAMCore {
    oneTimeWarning('createSharedAssetModel',
        'createSharedAssetModel is deprecated and will be removed on or after 2024-10-01. Use'
        + ' initializeSharedAssetModel instead.');
    return new SAMCore(config, hooks);
}
