import InterfaceBase from './InterfaceBase';
import type { SAM } from '@ccx-public/component-types';
import RepoMetadataResource from '../assets/RepoMetadataResource';

export default class PeopleGraphInterface extends InterfaceBase {

    private _getUrl(endpoint: string): string {
        return `https://${this._core._environment.endpoints.PGC_HOST}${endpoint}`;
    }

    /**
     * Fetch suggestions from People Graph
     *
     * @param assetId The asset ID to get suggestions for
     * @param value The search value/query string
     * @param config Configuration options for the suggestions
     * @returns Promise with array of suggestions
     */
    async fetchSuggestions(assetId: string, value: string, config: SAM.SuggestionConfig): Promise<SAM.Suggestion[]> {
        const url = this._getUrl('/api/suggestions');

        let mediaType: string;
        const assetPool = this._core._getAssetPool();
        const existingAsset = assetPool.getLocalItemById(assetId);

        if (existingAsset) {
            mediaType = existingAsset.mediaType;
        } else {
            const assetContext = await this._core.getAssetContext();
            const repositoryInterface = assetContext._rapi;
            const repoMetadataResource = new RepoMetadataResource(this._core);
            await repositoryInterface.getRepoMetadataById(assetId, repoMetadataResource);
            mediaType = repoMetadataResource.data['dc:format'];
        }

        // Construct the payload according to the PGC API specification
        const requestBody = {
            resourceType: mediaType,
            resourceUrn: assetId,
            relationship: config.relationship,
            query: {
                type: config.type || [ 'PERSON', 'GROUP' ],
                value,
                ...(config.tags && config.tags.length > 0 && { tags: config.tags })
            }
        };

        const response = await this._doPost(
            url,
            {
                'content-type': 'application/json',
            },
            JSON.stringify(requestBody),
            [ 200 ]
        );

        const responseData = await response.json();

        const suggestions = responseData._embedded?.suggestions || responseData;

        return suggestions.map((suggestion: any): SAM.Suggestion => ({
            ...suggestion,
            thumbnail: suggestion._links?.thumbnail?.href || ''
        }));
    }

    /**
     * Accept previously returned suggestions
     *
     * @param tokens Array of suggestion tokens to accept
     * @returns Promise with acceptance results
     */
    async acceptSuggestions(tokens: string[]): Promise<SAM.AcceptResponse> {
        const url = this._getUrl('/api/accept');

        const requestBody = {
            tokens
        };

        const response = await this._doPost(
            url,
            {
                'content-type': 'application/json',
            },
            JSON.stringify(requestBody),
            [ 200 ]
        );

        const data = await response.json();
        const embedded = data._embedded ?? {
            successes: data.successes ?? [],
            failures: data.failures ?? []
        };

        return {
            ...embedded,
            _embedded: embedded
        };
    }
}
