import type AdobeAsset from './AdobeAsset';
import type { IItemLoaderOptions, ILoadedPage } from '../core/ItemLoader';
import type ItemPool from '../core/ItemPool';
import type { AdobeAssetSearchConfig } from './AdobeAssetSource';
import type AdobeAssetSearchFilter from './AdobeAssetSearchFilter';
import type AdobeAssetSearchInterface from '../interface/AdobeAssetSearchInterface';
import USSv3LoaderHelper, {
    type IGetUSSResultsOpts,
    type IUSSLoader
} from './USSv3LoaderHelper';
import type { ISAMCorePrivate } from '../indexPrivate';
import { USSAssetFilterName } from './USSAssetFilterName';
import type USSAdobeAssetFilter from './USSAdobeAssetFilter';
import type { AssetsListingSearchOptions } from '../interface/AdobeAssetSearchInterface';
import {
    type USSResponse,
    USSv3OrderDirMap,
    USSv3OrderFieldMap
} from '../interface/USSv3Model';

export default class AdobeAssetDirectorySearchLoader implements IUSSLoader<AdobeAssetSearchConfig> {
    private _ussLoaderHelper: USSv3LoaderHelper<AdobeAssetSearchConfig>;

    constructor(
        assetPool: ItemPool<AdobeAsset>,
        core: ISAMCorePrivate,
        private _adobeAssetSearchInterface: AdobeAssetSearchInterface,
        private _asset: AdobeAsset,
        private _implicitFilter: AdobeAssetSearchFilter
    ) {
        this._ussLoaderHelper = new USSv3LoaderHelper(assetPool, core, this);
    }

    supportsFilter(filter?: any): boolean {
        // If we don't provide a filter at all, then we cannot use the loader
        return filter !== undefined;
    }

    async loadPage(options: IItemLoaderOptions<AdobeAssetSearchConfig>): Promise<ILoadedPage<AdobeAssetSearchConfig>> {
        return this._ussLoaderHelper.loadPage(options);
    }

    /**
     * @package -- only for use by USSLoaderHelper
     */
    async _getUSSResults({
        start,
        loadOptions,
        order,
        mediaTypes,
        excludeMediaTypes,
        filter
    }: IGetUSSResultsOpts<AdobeAssetSearchConfig>): Promise<USSResponse> {
        const query = this._implicitFilter?._query;
        const deepSearch = Boolean(this._implicitFilter.deepSearch);

        const options: Partial<AssetsListingSearchOptions> = {
            orderBy: USSv3OrderFieldMap[order.field],
            orderDirection: USSv3OrderDirMap[order.direction],
            start,
            limit: loadOptions?.limit,
            mediaTypes,
            excludeMediaTypes,
            query,
            deepSearch,
            assetId: this._asset.cloudID
        };

        if (filter.name === USSAssetFilterName) {
            const ussFilter = filter as USSAdobeAssetFilter;
            options.userId = ussFilter.userId;
            options.uploadedFrom = ussFilter.uploadedFrom;
        }

        return this._adobeAssetSearchInterface.getFilteredAssets(options);
    }
}
