import { memoize, observable } from '../core/decorators';
import ItemBase from '../core/ItemBase';
import type { CollaboratorSource } from './CollaboratorSource';
import type { InvitedCollaboratorSource } from './InvitedCollaboratorSource';
import type Collaborator from './Collaborator';
import type InvitedCollaborator from './InvitedCollaborator';
import type { ISAMCorePrivate } from '../indexPrivate';
import { SharedCollaboratorChangedEvent, COLLABORATOR_CHANGED } from '../indexPrivate';
import type { ICollaboratorSources } from './CollaborationContext';
import type { IItemPoolDelegate } from '../core/ItemPool';
import oneTimeWarning from '../utils/oneTimeWarning';
import { lazyLoaded, LazyLoadManager, LoadStatus } from '../core/decorators/LazyLoadManager';
import type { IInvitationRecipient, IInvitationServiceCapabilities, CollaborationModel } from '../interface/InvitationModel';
import { SAMError, SAMErrorCode } from '../core/SAMError';
import type { ShareType } from '../graphql/models/PLSModels';
import type { Principal, SharedWithYouLabel } from '../graphql/generated/types';
import type { PropertyFormatType } from '../core/PropertyUpdater';
import { isDeepEqual } from '../core/ObjectUtils';

// PLS SharedWithYouLabel as exposed in SharableItem
export interface ISharedWithYouLabel {
    shareDate: Date;
    shareTypes?: ShareType[];
    sharedBy?: Principal[];
}

export const SharedWithYouLabelFormat: PropertyFormatType = {
    parse: (value: SharedWithYouLabel): ISharedWithYouLabel | null  => {
        if (value === undefined) {
            // Since `undefined` means the property has not been loaded, ad hoc updating to undefined should not be
            // allowed. To "clear" the data, set to `null`. If the current value is known to be stale, fetch the new
            // value while leaving the old value in place.
            throw SAMError.create(SAMErrorCode.UNSUPPORTED, 'Cannot explicitly set sharedWithYouLabel to undefined');
        }
        if (!value) { return null; }

        return {
            shareDate: new Date(value.shareDate),
            shareTypes: (value.shareTypes as ShareType[]) || undefined,
            sharedBy: value.sharedBy || undefined
        };
    },
    isEqual: isDeepEqual
};

export default class ShareableItem extends ItemBase {
    private _collaboratorsArray: Collaborator[] = [];
    private _collaboratorSources?: ICollaboratorSources;
    /**
     * Used when this asset is created through USS and
     * the metadata collab_metadata#mine with a missing "type" property
     * indicates that this asset is shared with the current
     * user through a group and not individually.
     */
    protected _isSWYGroup: boolean | undefined;
    protected _isSharedWithYouAsset: boolean | undefined;
    protected _isShared: boolean | undefined;
    private _directCollaboratorCount: number | undefined;
    // from PLS
    private _sharedWithYouLabel: ISharedWithYouLabel | undefined | null;
    private _isPublicLink: boolean | undefined;
    protected _shareFlagsAreDirty: boolean = true;
    private _capabilities: IInvitationServiceCapabilities | undefined;
    private _collaborationModel?: CollaborationModel;

    constructor(core: ISAMCorePrivate, id: string) {
        super(core, id);
        LazyLoadManager.manageLazyLoading(this, [ {
            event: SharedCollaboratorChangedEvent,
            fetchData: this._queueCollaborators,
            prefetchTimeout: 0,
            cancelFetchData: this._dequeueCollaborators
        } ]);
    }

    @observable(SharedCollaboratorChangedEvent, '_isShared')
    get isShared(): boolean | undefined {
        this._fetchShareFlagsIfNeeded();
        return this._isShared;
    }

    @observable(SharedCollaboratorChangedEvent, '_isSharedWithYouAsset')
    get isSharedWithYouAsset(): boolean | undefined {
        this._fetchShareFlagsIfNeeded();
        return this._isSharedWithYouAsset;
    }

    @observable(SharedCollaboratorChangedEvent, '_directCollaboratorCount')
    get directCollaboratorCount(): number | undefined {
        this._fetchShareFlagsIfNeeded();
        return this._directCollaboratorCount;
    }

    @observable(SharedCollaboratorChangedEvent, '_isPublicLink')
    get isPublicLink(): boolean | undefined {
        this._fetchShareFlagsIfNeeded();
        return this._isPublicLink;
    }

    /**
     * Collaboration model indicating if this item is managed by Modern Access Control (MAC).
     * - 'project': MAC-enabled (FACS-based)
     * - undefined: Legacy ACL-based
     */
    get collaborationModel(): CollaborationModel | undefined {
        return this._collaborationModel;
    }

    /**
     * Returns data related to this Asset being shared with the current user.
     * @returns {ISharedWithYouLabel | undefined | null}
     * @note `undefined` means the data hasn't been loaded. Currently, this means that this item was
     *       not loaded from PLS SWY or Recents -- it is not lazy-loaded.
     *       `null` means the label has been queried, but it was not in the results. I.e., the item
     *       is not shared with the current user.
     */
    @observable(SharedCollaboratorChangedEvent, '_sharedWithYouLabel')
    get sharedWithYouLabel(): ISharedWithYouLabel | undefined | null {
        return this._sharedWithYouLabel;
    }

    /**
     * @package, used internally by filters, tests, etc.
     */
    get _isSWYAsset_NoLazyLoad(): boolean | undefined {
        return this._isSharedWithYouAsset;
    }

    /**
     * @package, used internally by filters, tests, etc.
     */
    get _isShared_NoLazyLoad(): boolean | undefined {
        return this._isShared;
    }

    /**
     * @package, used internally by filters, tests, etc.
     */
    get _directCollaboratorCount_NoLazyLoad(): number | undefined {
        return this._directCollaboratorCount;
    }

    /**
     * @package, used internally by filters, tests, etc.
     */
    get _isPublicLink_NoLazyLoad(): boolean | undefined {
        return this._isPublicLink;
    }

    /**
     * @deprecated Please use isSharedWithYouAsset -- will be removed on or after 2024-10-01
     */
    get isSharedWithMe(): boolean | undefined {
        oneTimeWarning('isSharedWithMe', 'isSharedWithMe is deprecated and will be removed on or after'
            + ' 2024-10-01. Please use isSharedWithYouAsset instead.');
        return this.isSharedWithYouAsset;
    }

    /**
     * @package -- used internally to check if collaborator data has been lazy-loaded without triggering lazy-loading.
     */
    get _isCollaboratorDataLoaded(): boolean {
        return LazyLoadManager.getLoadStatus(this, SharedCollaboratorChangedEvent.type) === LoadStatus.Loaded;
    }

    private _fetchShareFlagsIfNeeded() {
        if (this._shareFlagsAreDirty) {
            LazyLoadManager.fetchIfNeeded(this, SharedCollaboratorChangedEvent);
        }
    }

    /**
     * @package used internally.
     */
    _queueCollaborators(): Promise<void> {
        return this._core.collaborationContext._collaboratorRequestQueue.enqueue(this);
    }

    private _dequeueCollaborators(): boolean {
        return this._core.collaborationContext._collaboratorRequestQueue.dequeue(this);
    }

    @lazyLoaded(SharedCollaboratorChangedEvent, '_collaboratorsArray')
    get collaboratorArray(): Collaborator[] {
        return this._collaboratorsArray;
    }

    @memoize
    get collaborators(): CollaboratorSource {
        if (!this._collaboratorSources) {
            this._collaboratorSources = this._core.collaborationContext._getCollaboratorSources(this.id);
            this._collaboratorSources.collaboratorPool.addDelegate(this._itemPoolDelegate, 'context');
        }
        return this._collaboratorSources.collaboratorSource;
    }

    async removeCollaborator(collaborator: Collaborator): Promise<void> {
        await this._core.collaborationContext._removeCollaborator(this.id, collaborator);
    }

    async removeCurrentUserFromCollaborationList(): Promise<void> {
        return this._core.collaborationContext._removeCurrentUserFromCollaborationList(this);
    }

    async createPublicLink(canComment: boolean = true): Promise<void> {
        const publicLinkCollaborator: IInvitationRecipient = {
            recipient: 'all',
            role: 'viewer',
            canShare: false,
            canComment
        };

        this._core.collaborationContext._addCollaborators(this.id, [ publicLinkCollaborator ]);
    }

    /**
     * Get sharing capabilities and collaborator information for the current user on the asset.
     *
     *
     * See {@link CollaborationContext.getCapabilities} for more details.
     * @returns Promise that resolves with the capabilities for the asset
     */
    @observable(SharedCollaboratorChangedEvent, '_capabilities')
    async getCapabilities(): Promise<IInvitationServiceCapabilities> {
        const collaborationContext = await this._core.getCollaborationContext();

        if (this._capabilities) {
            return this._capabilities;
        }

        const capabilitiesData = await collaborationContext.getCapabilities(this.id);
        const updateSession = this._core._getAssetPool().createUpdateSession();
        const adobeAssetUpdater = this._core.hostAssetContext._adobeAssetUpdater;
        adobeAssetUpdater.updateRemoteItem(updateSession, {
            'repo:assetId': this.id,
            'invitationServiceCapabilities': capabilitiesData
        });
        updateSession.commit();
        return this._capabilities!;
    }

    async removePublicLink(): Promise<void> {
        if (!this._isCollaboratorDataLoaded) {
            // Queue up fetching collaborators
            await this._queueCollaborators();
            await new Promise<void>((resolve) => {
                this.on(COLLABORATOR_CHANGED, () => {
                    // check that the data has loaded again in case there is some other
                    // field loading that finished first and fired this event.
                    if (this._isCollaboratorDataLoaded) {
                        resolve();
                    }
                });
            });
        }

        const predefinedPrincipal = this.collaboratorArray.find(collaborator => collaborator.id === 'all');

        if (predefinedPrincipal) {
            this._core.collaborationContext._removeCollaborator(this.id, predefinedPrincipal);
        }
    }

    /**
     * Shares this item with the entire organization so that all members can access this item. This method adds
     * the predefined principal 'orgEverybody' as a viewer with commenting permissions but without sharing permissions.
     *
     * @throws {SAMError} if adding the organization collaborator fails (409 if already a collaborator, 403 if insufficient permissions, 500 if downstream errors occur)
     *
     * @returns {Promise<void>} Resolves when the organization has been successfully added as a collaborator
     */
    async shareWithOwnerOrganization(): Promise<void> {
        const orgEverybodyCollaborator: IInvitationRecipient = {
            recipient: 'orgEverybody',
            role: 'viewer',
            canComment: true,
            canShare: false,
        };

        const result = await this._core.collaborationContext._addCollaborators(this.id, [ orgEverybodyCollaborator ]);
        const orgEverybody = result.failedCollaborators.find(c => c.recipient === 'orgEverybody');
        if (orgEverybody) {
            throw SAMError.create(orgEverybody.error.code, orgEverybody.error.message);
        }
    }

    /**
     * @TODO_Deprecation -- will be marked deprecated on or after 2024-10-01, and removed on or after 2025-01-01.
     *   Only used in admin console for managing Teams, which is already deprecated.
     *
     * @returns {InvitedCollaboratorSource}
     */
    @memoize
    get invitedCollaborators(): InvitedCollaboratorSource {
        if (!this._collaboratorSources) {
            this._collaboratorSources = this._core.collaborationContext._getCollaboratorSources(this.id);
        }
        return this._collaboratorSources.invitedCollaboratorSource;
    }

    /**
     * @TODO_Deprecation -- will be marked deprecated on or after 2024-10-01, and removed on or after 2025-01-01.
     *   Only used in admin console for managing Teams, which is already deprecated.
     *
     * @param {InvitedCollaborator} invitedCollaborator
     * @returns {Promise<void>}
     */
    removeInvitedCollaborator(invitedCollaborator: InvitedCollaborator) {
        return this._core.collaborationContext.removeInvitedCollaborator(this.id, invitedCollaborator);
    }

    /**
     * @package Internal use only
     *
     * @param sources
     * @param collaborators
     */
    _setCollaboratorData(collaborators?: Collaborator[], collaborationModel?: CollaborationModel) {
        this._collaboratorSources = this._core.collaborationContext._getCollaboratorSources(this.id);
        const collaboratorItemPool = this._collaboratorSources.collaboratorPool;
        this._collaboratorsArray = collaborators ?? collaboratorItemPool.toArray();
        this._shareFlagsAreDirty = false;
        if (collaborationModel !== undefined) {
            this._collaborationModel = collaborationModel;
        }

        // set the isShared flag. The collaborators array contains the owner of the asset
        // as well the organization that owns the asset.
        // We use the isDirect flag to determine if the asset is explicitly shared or not.
        this._isShared = this._collaboratorsArray.some((collaborator) => {
            return collaborator.isDirect;
        });

        // set the isSharedWithYouAsset flag
        const isCurrentUserDirectCollaborator = this._collaboratorsArray.some((collaborator) => {
            return collaborator.isDirect && collaborator.isCurrentUser;
        });

        this._isSharedWithYouAsset = this._isSWYGroup || isCurrentUserDirectCollaborator;

        // set the isPublicLink flag
        this._isPublicLink = this._collaboratorsArray.some((collaborator) => {
            return collaborator.id === 'all';
        });

        // calculate the number of direct collaborators
        this._directCollaboratorCount = this._collaboratorsArray.filter(collaborator => collaborator.isDirect).length;
    }

    private _itemPoolDelegate: IItemPoolDelegate<Collaborator> = {
        onItemsUpdated: () => {
            this._setCollaboratorData();
            // This code path is not governed by LazyLoadManager, but LLM still needs to be informed of the update.
            LazyLoadManager.updatedExternally(this, SharedCollaboratorChangedEvent);
        }
    };
}
