import type ClassroomMember from '../classroom-member/ClassroomMember';
import type { IExplicitFilter, ItemFilterRelation } from '../core/ItemFilter';
import { ClassroomMemberRole } from '../interface/ClassroomMemberModel';

export interface IClassroomMemberFilterOptions {
    classroomId: string;
    role: ClassroomMemberRole;
}

/**
 * A filter for classroom members
 *
 * Example usage, to get just a list of students back:
 *
 * classroom.members.getList(ClassroomMemberOrder.default, new ClassroomMemberFilter({ classroomId: classroom.id, role: 'student' }), { refreshTimeout: -1 });
 */
export default class ClassroomMemberFilter implements IExplicitFilter<ClassroomMember> {
    public classroomId: string;
    public role: ClassroomMemberRole;

    constructor(options: Partial<IClassroomMemberFilterOptions>) {
        this.classroomId = options.classroomId || '';
        this.role = options.role || ClassroomMemberRole.NONE;
    }

    matches(item: ClassroomMember): boolean {
        // Can return immediately if the classroomId doesn't match
        if (this.classroomId !== item.classroomId) {
            return false;
        }

        // If we have a role, we're only loading students OR teachers
        if (this.role && this.role !== ClassroomMemberRole.NONE) {
            return item.role === this.role;
        }

        // If we don't have a role, we're loading all members, so check against either student or teacher
        return item.role === ClassroomMemberRole.STUDENT || item.role === ClassroomMemberRole.TEACHER;
    }

    /**
     * This method determines the commonality between the already present filter (other)
     * and the new filter to be applied (this). The point of this is to
     * see if the new filter (this) can build some, all, or none of it's items
     * from (other) filter.
     *
     * Subset: Means that ALL items for this filter can be built from other
     * Disjoint: No items for this filter can be built from other.
     * Unknown: Some items for this filter can be built from other.
     *
     * @note we should always determine disjoint cases first before other cases.
     * @note this = NEW FILTER, other = EXISTING FILTER
     *
     * @param other The existing filter that we are getting the relation to.
     * @returns { ItemFilterRelation }
     */
    getRelationToFilter(other: ClassroomMemberFilter): ItemFilterRelation {
        // Consider disjoint cases before all others
        // If classroomId is different, relation is disjoint
        if (other.classroomId !== this.classroomId) {
            return 'disjoint';
        }

        // If role is different, and neither is NONE, relation is disjoint
        if (this.role !== other.role && this.role !== ClassroomMemberRole.NONE && other.role !== ClassroomMemberRole.NONE) {
            return 'disjoint';
        }

        // If role and classroomId are the same, relation is subset
        if (this.role === other.role) {
            return 'subset';
        }

        // If other role is NONE, it means the filter we're checking against has loaded all members, so we can be sure that it's a subset as either teacher or student is contained in the other filter.
        if (other.role === ClassroomMemberRole.NONE) {
            return 'subset';
        }

        return 'unknown';
    }

    get hash(): string {
        return `id=${this.classroomId}-${this.role}`;
    }
}
