import SAMError, { SAMErrorCode } from '../SAMError';
import type { IHasKeyMap } from './key';
import { KeysProperty } from './key';

/**
 * The @consolidated decorator is for async methods where multiple calls in parallel can be combined into one
 * call. E.g., if caller1 is waiting for a response and caller2 makes a call, caller2 will receive the same
 * response as caller1.
 *
 * Often used in lazy-load cases where the data needs to be fetched only once initially, and only once when
 * it needs refreshing.
 **
 * A parameter can be marked as @key, allowing multiple concurrent calls so long as the keys are different.
 */
export default (target: any, propertyKey: string, descriptor: PropertyDescriptor) => {
    const promisesMapProperty = Symbol(`@consolidated ${propertyKey}`);
    const method = descriptor.value;
    if (!method) {
        throw SAMError.create(SAMErrorCode.BAD_REQUEST, '@consolidated decorator can only be applied to a method');
    }
    descriptor.value = async function (this: IHasKeyMap & { [promisesMapProperty]: Map<string, ReturnType<typeof method>> }, ...args: any[]) {
        const keyIndex = this[KeysProperty]?.get(propertyKey);
        const key: string = keyIndex === undefined ? 'default' : args[keyIndex];

        const map = this[promisesMapProperty] || (this[promisesMapProperty] = new Map);
        const promise = map.get(key);
        // Another call is pending, so piggy-back on it
        if (promise) {
            return promise;
        } else {
            // Track this call so other callers can piggy-back on it
            const promise = method.apply(this, args);
            map.set(key, promise);
            promise.finally(() => {
                map.delete(key);
            });
            return promise;
        }
    };
};
