import type { IEventMap } from './ITypedEventEmitter';
import type { IItemListBase } from './ItemList';
import type { LogLevel } from './SAMCore';

export const ITEM_LIST_STATE_CHANGED = 'itemListStateChanged';
export const MESSAGE_LOGGED = 'messageLogged';
export const CONFIG_CHANGE = 'configChanged';

export class ConfigChangeEvent extends Event {
    constructor() {
        super(CONFIG_CHANGE);
    }
}

export class ItemListStateChangedEvent extends Event {
    constructor(readonly list: IItemListBase) {
        super(ITEM_LIST_STATE_CHANGED);
    }
}

export class MessageLoggedEvent extends Event {
    constructor(readonly message: string, readonly logLevel: LogLevel) {
        super(MESSAGE_LOGGED);
    }
}

interface ISAMCoreEvents extends IEventMap {
    [ITEM_LIST_STATE_CHANGED]: ItemListStateChangedEvent;
    [MESSAGE_LOGGED]: MessageLoggedEvent;
    [CONFIG_CHANGE]: ConfigChangeEvent;
}

export default ISAMCoreEvents;
