import type { IEventMap } from './TypedEventEmitter';
import TypedEventEmitter from './TypedEventEmitter';
import type ChangeEvent from './ChangeEvent';
import { SharedChangeEvent } from './ChangeEvent';
import { observable } from './decorators';
import type  { ISAMObject, ISAMCorePrivate } from '../indexPrivate';

export type ItemId = string;

export interface ItemBaseEvents extends IEventMap {
    change: ChangeEvent;
}

export type TaskName =
    | 'archive'
    | 'bookmark'
    | 'copy'
    | 'delete'
    | 'move'
    | 'rename'
    | 'restore'
    | 'update'
    | 'package';

/**
 * Each ItemBase can be assigned a single task at a time.
 * Different objects have different instances of this object.
 */
export interface ExclusiveTask {
    readonly name: TaskName;
    readonly items: ItemBase<ItemBaseEvents>[];
}

export class ItemExclusiveTaskChain {
    next?: ItemExclusiveTaskChain;

    constructor(
        readonly task: ExclusiveTask,
        readonly onGotOwnership: () => void) {
    }

    // Add the task at the end of the linked list.
    registerNewTask(newTask: ItemExclusiveTaskChain) {
        let itemTask: ItemExclusiveTaskChain = this;
        while (itemTask) {
            const next: ItemExclusiveTaskChain | undefined = itemTask.next;
            if (!next) {
                // We've found the first empty slot.
                itemTask.next = newTask;
                return;
            }
            // Keep going till the end.
            itemTask = next;
        }
    }
}

/**
 * Base object used for all assets, teams, spaces etc.
 */
export default abstract class ItemBase<Events extends ItemBaseEvents = ItemBaseEvents> extends TypedEventEmitter<Events> implements ISAMObject {
    protected _exclusiveTaskChain?: ItemExclusiveTaskChain;

    // Timestamp of the last known mutation that this client executed.
    // The servers have to replicate this mutation between each other and sometimes the
    // fetches do not include changes for up to a specific amount of seconds.
    // The timestamp will be used to compare against the expected update
    // windows of each request.
    protected _lastKnownClientMutation?: number;

    constructor(
        readonly _core: ISAMCorePrivate,
        readonly id: ItemId) {
        super();
    }

    get lastKnownClientMutation(): number | undefined {
        return this._lastKnownClientMutation;
    }

    /**
     * Update the timestamp of the last known client mutation.
     * This is typically the time when an item was either locally modified,
     * or populated from an authoritative source. It may be older than Date.now()
     * if the data source is from cache.
     */
    updateLastKnownClientMutation(timestamp = Date.now()) {
        this._lastKnownClientMutation = timestamp;
    }

    /**
     * Waits for at least `delay` ms since the last known asset mutation.
     * @param delay
     */
    async waitForMutationPropagationIfNeeded(delay: number) {
        const mutation = this._lastKnownClientMutation;
        if (mutation) {
            const waitTime = mutation + delay - Date.now();
            if (waitTime > 0) {
                // We still have some time left before the asset change is propagated for sure.
                await new Promise((resolve) => setTimeout(resolve, waitTime));
            }
        }
    }

    @observable
    get exclusiveTask(): ExclusiveTask | undefined {
        return this._exclusiveTaskChain?.task;
    }

    private _setExclusiveTaskChain(itemTaskChain: ItemExclusiveTaskChain | undefined) {
        this._exclusiveTaskChain = itemTaskChain;
        this.dispatch(SharedChangeEvent);
    }

    /**
     * @package -- only for use by UpdateSession
     */
    _setId(newId: string) {
        // @ts-expect-error -- this is the only place where ID can be changed.
        this.id = newId;
    }

    /**
     * Locks exclusive ownership for a subset of items during execution of the `schedule`.
     * It is guaranteed that the `schedule` method will receive ownership of the items
     * before it starts execution and all the way up to the point when the returned promise
     * gets resolved.
     *
     * Multiple tasks can run at the same time as long as they do not share any of their items.
     * For example, task A working with assets (i1, i2) will be scheduled to run in parallel with
     * task B with assets (i3, i4).
     *
     * If multiple tasks are registered on same items, the tasks will be executed in their
     * order of scheduling. For example, task C working with assets (i1, i2) will not be allowed
     * to run at the same time with task D that needs assets (i2, i3). Task D will only schedule
     * once all the previously scheduled tasks have released ownership of i2 and i3.
     *
     * Recursivity is not supported, a task should not lock same items again while it holds ownership.
     *
     * A single item can only be part of a single exclusive task at any moment of time.
     *
     * @param name Name of the task to schedule. Useful for debugging.
     * @param items The items to lock during the execution of the task.
     * @param schedule The function to execute once the task has ownership of the items.
     * @returns A promise resolved once the task is complete. The value of the returned promise
     * is propagated from the promise returned by the `schedule` function.
     */
    static runExclusiveTask<T>(name: TaskName, items: ItemBase[], schedule: (task: ExclusiveTask) => Promise<T>): Promise<T> {
        return new Promise<T>((resolve) => {
            const task: ExclusiveTask = { name, items };

            const runTask = () => resolve(schedule(task).finally(() => {
                // Make sure all the items pick up their next task
                // before we give up ownership.
                for (const item of items) {
                    // We know the item must have a task. We just finished it.
                    const next = item._exclusiveTaskChain!.next;

                    // Assign ownership to the next waiting task.
                    // If tasks are still pending, then there should
                    // never be a gap of of ownership on the item,
                    // to avoid letting other tasks inject themselves
                    //in the middle. The tasks needs to execute in the order
                    // of scheduling to avoid interlacing issues.
                    item._setExclusiveTaskChain(next);

                    // Let the next task know it received the ownership now.
                    // Once the next task acquires all the locks, then it will
                    // continue with its own execution.
                    // Note that the callback uses use a timer once the execution
                    // actually starts to avoid crashing this promise chain.
                    next?.onGotOwnership();
                }
            }));

            // We don't want to schedule the task until all the items are ready to execute the task.
            let waitCount = 0;
            const onGotOwnership = () => {
                // Wait for all other task to finish first.
                if (--waitCount === 0) {
                    // Using a separate stack to avoid crashing the previous task
                    // that might have invoked the `onGotOwnership` method.
                    setTimeout(runTask, 0);
                }
            };

            for (const item of items) {
                // Each item gets its own task object. We cannot share the objects as
                // we require strict task ordering for each individual item.
                const newTask = new ItemExclusiveTaskChain(task, onGotOwnership);

                const itemTask = item._exclusiveTaskChain;
                if (!itemTask) {
                    // Assign the new task right away. The task will maintain
                    // owneship until it gets scheduled.
                    item._setExclusiveTaskChain(newTask);
                    continue;
                }

                // Increment the number of items that we are still waiting ownership for.
                ++waitCount;

                // Register the task to be executed immediately after the last task in this item's task chain.
                itemTask.registerNewTask(newTask);
            }

            if (waitCount === 0) {
                // We've got owernship of all the required assets already,
                // we can proceed with running the task.
                runTask();
            }
        });
    }

}
