import type { ICCLibraries } from '../../CCLibraries';
import LocalDriver from '../../drivers/LocalDriver';
import { hasLibrary } from '../utils/HasLibrary';
import LibraryError from '../../errors/LibraryError';
import type Element from '../../models/Element';
import type Representation from '../../models/Representation';
import type Group from '../../models/Group';
import { Permission } from '../../../index';

export function requiresWrite(target: unknown, propertyKey: string, propertyDescriptor: PropertyDescriptor) {
    const key = propertyDescriptor.set ? 'set' : propertyDescriptor.value ? 'value' : undefined;

    if (key) {
        const method = propertyDescriptor[key];

        propertyDescriptor[key] = function (this: Element | Group | Representation, ...args: any[]) {
            if (hasLibrary(this) && !this.library.hasPermission(Permission.Write)) {
                throw new LibraryError('NOT_ALLOWED', `${propertyKey} requires write access`, this.id);
            }

            return method.apply(this, args);
        };
    }
}

export function requiresCloudDriver(
    target: ICCLibraries,
    propertyKey: string,
    propertyDescriptor: PropertyDescriptor
) {
    const key = propertyDescriptor.set ? 'set' : propertyDescriptor.value ? 'value' : undefined;

    if (key) {
        const method = propertyDescriptor[key];

        propertyDescriptor[key] = function (this: ICCLibraries, ...args: any[]) {
            if (!this.apiRoot.cloudDriver) {
                throw new LibraryError('NOT_ALLOWED', `${propertyKey} requires a cloud driver`);
            }

            return method.apply(this, args);
        };
    }
}

export function requiresLocalDriver(
    target: ICCLibraries,
    propertyKey: string,
    propertyDescriptor: PropertyDescriptor
) {
    const key = propertyDescriptor.set ? 'set' : propertyDescriptor.value ? 'value' : undefined;

    if (key) {
        const method = propertyDescriptor[key];

        propertyDescriptor[key] = function (this: ICCLibraries, ...args: any[]) {
            if (!(this.apiRoot.driver instanceof LocalDriver)) {
                throw new LibraryError('NOT_ALLOWED', `${propertyKey} requires a local driver`);
            }

            return method.apply(this, args);
        };
    }
}
