import { compareStrings, compareValues, createItemOrderFactory } from '../core/ItemOrder';
import type Board from './Board';
import type { IComparatorMap } from '../core/ItemOrder';
import type { SAM } from '@ccx-public/component-types';

export type BoardOrderField = 'name' | 'created' | 'modified';

const compareBoardNames = (a: Board, b: Board) => compareStrings(a.displayName || '', b.displayName || '');

const compareBoardTimes = (a: Board, b: Board, field: 'created' | 'modified') => {
    let value: number;
    if (!a[field] && !b[field]) {
        value = 0;
    } else if (!a[field]) {
        value = 1;
    } else if (!b[field]) {
        value = -1;
    } else {
        value = compareValues(a[field].getTime(), b[field].getTime());
    }
    return value === 0 ? compareBoardNames(a, b) : value;
};

const OrderFieldToComparator: IComparatorMap<Board, BoardOrderField> = {
    name(a: Board, b: Board): number {
        return compareBoardNames(a, b);
    },
    created(a: Board, b: Board): number {
        return compareBoardTimes(a, b, 'created');
    },
    modified(a: Board, b: Board): number {
        return compareBoardTimes(a, b, 'modified');
    }
};

export default class BoardOrder extends createItemOrderFactory(OrderFieldToComparator) implements SAM.BoardOrder {
    static default = new BoardOrder('ascending', 'name');
}
