import { vulcanQueryRequestPayload } from '../config/constants';
import getVulcanInterface from '../utils/Vulcan';
import type { IVulcan, IVulcanMessage } from '../utils/Vulcan/IVulcan';
import type { VulcanCallback, VulcanMessageType, ConnectionInfo } from './Connector';
import Connector from './Connector';

// This NodeConnector is for the node-js vulcan implementation used by Stager
// To debug vulcan messages in Stager you can add the flag SG_DEBUG_VULCAN=1 when opening Stager

class NodeConnector extends Connector<any, IVulcanMessage> {
    protected messageTypes: VulcanMessageType = {
        REQUEST: 'cclibraries.api.QueryRequest',
        RESPONSE: 'cclibraries.api.QueryResponse',
        INITIALIZE: 'cclibraries.service.Initialized'
    };

    constructor(vulcanInterface: any, vulcanMessage: IVulcanMessage, timeout: number) {
        super(getVulcanInterface(vulcanInterface), vulcanMessage, timeout);
    }

    private _wrapHandler(callback: any) {
        return (message: any, _processName: any) => callback(message);
    }

    removeListener(callback: VulcanCallback, type?: string) {
        return this.vulcanInterface.removeMessageListener(type || this.messageTypes.RESPONSE, callback);
    }

    sendMessage(callback: VulcanCallback, type?: string) {
        // Add listener
        this.vulcanInterface.addMessageListener(type || this.messageTypes.RESPONSE, this._wrapHandler(callback));
        // Send the request
        if (type !== this.messageTypes.INITIALIZE) {
            const request = { message: vulcanQueryRequestPayload, type: type || this.messageTypes.REQUEST };
            this.vulcanInterface.dispatchMessage(request);
        }
    }

    async isAppRunning() {
        return this.vulcanInterface.isAppRunning();
    }

    launchApp(_callback: VulcanCallback) {
        this.vulcanInterface.launchApp();
    }

    getPayload(message: string) {
        return message;
    }
}

export default (
    VulcanInterface: IVulcan,
    VulcanMessage: IVulcanMessage,
    timeout = 8000
): ((abortSignal?: AbortSignal) => Promise<ConnectionInfo | void>) => {
    const connector = new NodeConnector(VulcanInterface, VulcanMessage, timeout);
    return (abortSignal?: AbortSignal) => connector.connect(abortSignal);
};
