import type { AssignmentLinks, AssignmentAdobeAssetMetadata, ClassroomAssetsContext } from './AssignmentModel';
import type { IServiceLink, LinkRequirements } from './LinkUtils';
import { RelType } from './LinkUtils';
import type { AssetLinks, IAppMetadata, RepositoryMetadata } from './RepositoryModel';
import type { IRemoteStudentAssignmentFile } from './StudentAssignmentFileModel';

export type Assignee = {
    displayName: string;
    email: string;
    id: string;
}

export type IRemoteAssignee = {
    displayName?: string;
    email?: string;
    id: string;
}

export interface IStudentAssignmentsIndexResponse {
    _links: IStudentAssignmentsIndexLinks
}

export interface IStudentAssignmentsIndexLinks {
    [RelType.STUDENT_ASSIGNMENTS_COLLECTION]: IServiceLink;
    [RelType.STUDENT_ASSIGNMENTS_PRIMARY]: IServiceLink;
    [RelType.ASSIGNMENTS_SUBMIT_FLOATING_FILE]: IServiceLink;
}

export const STUDENT_ASSIGNMENTS_INDEX_LINKS: LinkRequirements = {
    [RelType.STUDENT_ASSIGNMENTS_COLLECTION]: [ 'assignmentId', 'assignmentCode', 'includeStudentDocuments' ],
    [RelType.STUDENT_ASSIGNMENTS_PRIMARY]: [ 'studentAssignmentId', 'includeStudentDocuments' ],
    [RelType.ASSIGNMENTS_SUBMIT_FLOATING_FILE]: [ 'assignmentId', 'submissionId' ],
};

export interface IStudentAssignmentsActions {
    [RelType.ASSIGNMENTS_START]?: IServiceLink;
    [RelType.ASSIGNMENTS_RETURN]?: IServiceLink;
    [RelType.ASSIGNMENTS_SUBMIT]?: IServiceLink;
}

export type StudentAssignmentLinks = AssetLinks & IStudentAssignmentsActions

export enum StudentAssignmentStatus {
    NOT_STARTED = 'NOT_STARTED',
    IN_PROGRESS = 'IN_PROGRESS',
    RETURNED = 'RETURNED',
    SUBMITTED = 'SUBMITTED',
}

export const ALL_STATUSES = [ StudentAssignmentStatus.IN_PROGRESS, StudentAssignmentStatus.NOT_STARTED, StudentAssignmentStatus.RETURNED, StudentAssignmentStatus.SUBMITTED ];

export interface IRemoteStudentAssignmentAppMetadata extends Pick<IAppMetadata, 'cc:inherited'> {
    /** ID of the student assignment. Not started student assignment will not have 'repo:assetId' */
    'repo:assetId'?: string,
    /** Owner of this assignment */
    'assignment:assignee': Assignee;
    /** The submitted work for the assignment */
    'assignment:submission'?: AssignmentAdobeAssetMetadata;
    /** Status */
    'assignment:submissionStatus': StudentAssignmentStatus;
    /** Date the assignment was submitted */
    'assignment:submissionDate'?: string;
}

export interface IRemoteStudentAssignment extends IRemoteStudentAssignmentAppMetadata, Pick<RepositoryMetadata, '_embedded'> {
    /** Computed ID from id attribute of assignment:assignee */
    computedAssigneeId?: string;
    /** Student assignment links */
    _links: StudentAssignmentLinks;
    /** Student assignment files */
    children: IRemoteStudentAssignmentFile[]
    /** Classroom context data */
    'classroom:context': ClassroomAssetsContext;
}

export interface IStudentAssignmentReturnData {
    /** The current set of student assignment links. */
    links: StudentAssignmentLinks;
    /** The student assignment ID that is being returned. */
    studentAssignmentId: string;
    /** The submission ID that is being returned for this assignment. */
    submissionId: string;
}

export interface IStudentAssignmentStartData {
    /** The assignment ID that is being started. */
    assignmentId: string;
    /** The current set of student assignment links. */
    links: StudentAssignmentLinks;
}

export interface SubmitFloatingFileOptions {
    /** The assignment ID. This or studentAssignmentId is needed to submit an assignment. */
    assignmentId?: string;
    /**
     * The student assignment ID that is being submitted.
     * This or assignmentId is needed to submit an assignment.
     * */
    studentAssignmentId?: string;
    /** The asset ID of the file that is being submitted for this assignment. */
    submissionId: string;
    /**
     * The ID of the profile that owns the StudentAssignment being submitted to.
     * This should be set if this differs from the user who is currently logged in.
     * */
    targetProfileId?: string;
}

export interface ISubmitFloatingFileData {
    /** The assignment ID that the floating file is being submitted to. */
    assignmentId: string;
    /**
     * The student assignment ID that the floating file is being submitted to.
     * Providing this information helps Hume improve performance.
     * */
    studentAssignmentId?: string;
    /** The asset ID of the file that is being submitted for this assignment. */
    submissionId: string;
    /** The ID of the profile that owns the StudentAssignment being submitted to. */
    profileId?: string;
    /** The current set of student assignment links. */
    links?: AssignmentLinks;
}

export interface IStudentAssignmentSubmitClassroomContextData {
    /** The assignment ID. This or studentAssignmentId is needed to submit an assignment. */
    assignmentId?: string;
    /** The current set of student assignment links. */
    links: StudentAssignmentLinks;
    /** The current status of the student assignment, when not provided the status is assumed to not be NOT_STARTED. */
    status?: StudentAssignmentStatus;
    /** The student assignment ID that is being submitted. This or assignmentId is needed to submit an assignment. */
    studentAssignmentId?: string;
    /** The submission ID that is being submitted for this assignment. */
    submissionId: string;
}

export interface IStudentAssignmentSubmitData {
    /** The current set of student assignment links. */
    links: StudentAssignmentLinks;
    /** The student assignment ID that is being submitted. This or studentAssignmentId is needed to submit an assignment. */
    studentAssignmentId: string;
    /** The submission ID that is being submitted for this assignment. */
    submissionId: string;
}

export enum StudentAssignmentOwner {
    Any = 'ANY',
    Self = 'SELF'
}

export interface StudentAssignmentOptionalParams {
    /** Optional user ID for filtering student assignments to only those belonging to this user. When omitted, no user filtering is applied and all assignments matching other criteria are returned. */
    currentUserId?: string;
    /** Optional array of student assignment statuses to filter by (e.g., `[StudentAssignmentStatus.IN_PROGRESS, StudentAssignmentStatus.SUBMITTED]`). When omitted or empty, defaults to all statuses: `NOT_STARTED`, `IN_PROGRESS`, `RETURNED`, and `SUBMITTED`. */
    status?: StudentAssignmentStatus[];
    /** Whether to load student work files. When `true`, files are loaded immediately. When `false`, files are not loaded. Defaults to `true` when omitted. */
    loadDocuments?: boolean;
}

export interface StudentAssignmentCompleteParams extends StudentAssignmentOptionalParams {
    /** The assignment code */
    assignmentCode?: string;
    /** The assignment ID */
    assignmentId?: string;
}

export interface IStudentAssignmentsPageSpec {
    count: number;
}

export interface IStudentAssignmentsLinks {
    [RelType.STUDENT_ASSIGNMENTS_COLLECTION]: IServiceLink;
}

export interface IStudentAssignmentResponse {
    children: IRemoteStudentAssignment[];
    _page: IStudentAssignmentsPageSpec;
    _links: IStudentAssignmentsLinks;
}

export type RequiredStudentAssignmentFilterOptions = (
    {assignmentCode?: never; assignmentId: string;}
    | { assignmentCode: string; assignmentId?: never}
);

export interface GetStudentAssignmentOptions extends Pick<StudentAssignmentOptionalParams, 'loadDocuments'>{}

export interface IGetStudentAssignmentOptions {
    /** load student work files if true */
    loadDocuments?: boolean;
    /**
     * The profile ID to fetch the StudentAssignment for.
     * By default, only StudentAssignments for the current profile are fetched
     * */
    profileId?: string;
}

