import type { SAM } from '@ccx-public/component-types';
import type AdobeAsset from '../assets/AdobeAsset';
import { COLLABORATOR_CHANGED } from '@sam-js-src/collaboration/CollaboratorEvents';
import { LazyLoadManager } from '@sam-js-src/core/decorators/LazyLoadManager';
import type Collaborator from '@sam-js-src/collaboration/Collaborator';

const isPredefinedPrincipal = (collaborator: Collaborator): boolean => {
    return [ 'all', 'authenticated', 'allWithPassword', 'orgEverybody' ].includes(collaborator.id);
};


export const getPrincipalCollaborators = async (adobeAsset: AdobeAsset): Promise<SAM.Collaborator[]> => {
    // wait for collaborators to load if needed
    await LazyLoadManager.fetchIfNeeded(adobeAsset, COLLABORATOR_CHANGED);
    const collaborators = await adobeAsset.collaboratorArray;
    return collaborators.filter(isPredefinedPrincipal);
};
