import type { IComparatorMap } from '../core/ItemOrder';
import { createItemOrderFactory } from '../core/ItemOrder';
import type CollaboratorsByAssetID from './CollaboratorsByAssetID';

export type CollaboratorsByAssetIDOrderField = 'noop';

const OrderFieldToComparator: IComparatorMap<CollaboratorsByAssetID, CollaboratorsByAssetIDOrderField> = {
    // there is nothing in collaboratorListByUrn to order, this will keep order same
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    noop(a: CollaboratorsByAssetID, b: CollaboratorsByAssetID): number {
        return 0;
    }
};

export default class CollaboratorsByAssetIDOrder extends createItemOrderFactory(OrderFieldToComparator) {
    static default = new CollaboratorsByAssetIDOrder('ascending', 'noop');
}
