import ItemUpdater from '../core/ItemUpdater';
import PropertyUpdater from '../core/PropertyUpdater';

import type { IFrameioAssetResponse } from './FrameioInterface';
import FrameioAsset from './FrameioAsset';
import { frameioAssetUpdater } from './FrameioContext';
import type { ISAMObject } from '../core/ISAMObject';

// See https://developer.frame.io/api/reference/operation/getAsset/
//  for schema of IFrameioAssetResponse. FrameioVersionStack
//  encapsulates the data for assets of type="version_stack".
//
// See FrameioFile, FrameioFolder for other asset types.
export default class FrameioVersionStack extends FrameioAsset {
    private _children?: Array<FrameioAsset>;
    private _coverAsset?: FrameioAsset;
    private _coverAssetId: string = '';
    private _versions: number = 0;

    get coverAssetId(): string {
        return this._coverAssetId;
    }

    async getCoverAsset(): Promise<FrameioAsset> {
        if (!this._coverAsset) {
            this._coverAsset = await this.context.getAsset(this.coverAssetId);
        }

        return this._coverAsset!;
    }

    get versions(): number {
        return this._versions;
    }

    set coverAsset(asset: FrameioAsset) {
        this._coverAsset = asset;
    }

    async getChildren(): Promise<Array<FrameioAsset>> {
        if (!this._children) {
            const ctx = this.context;
            const response = await ctx._frameioInterface.getChildren(this.id);
            const session = ctx._objectPool.createUpdateSession<FrameioAsset>();

            // IFrameioAssetResponse is a special case, as it corresponds to multiple classes
            // inheriting from FrameioAsset ( FrameioFile, FrameioFolder, FrameioVersionStack ),
            // so use a utility function to select the correct updater for the type.
            //
            // See also FrameioContext.getAncestors()
            this._children = response.map((asset: IFrameioAssetResponse) => frameioAssetUpdater(session, asset));
            session.commit();
        }

        return this._children;
    }
}

export const FrameioVersionStackUpdater = new ItemUpdater<FrameioVersionStack, Partial<IFrameioAssetResponse>>({
    localItemType: FrameioVersionStack,
    remoteIdProperty: 'id',
    propertyUpdater: new PropertyUpdater({
        '_coverAsset': {
            // when the update reads response.root_asset
            // ( which matches name: 'root_asset' ),
            // it will invoke set: with the child object
            //
            name: 'cover_asset',
            format: 'object',
            set: (response: IFrameioAssetResponse, dest: ISAMObject): void => {
                const stack = dest as FrameioVersionStack;
                const pool = stack.context._objectPool;
                const session = pool.createUpdateSession<FrameioAsset>();
                const asset = frameioAssetUpdater(session, response);
                session.commit();

                stack.coverAsset = asset;
            },

        },
        '_coverAssetId': 'cover_asset_id',
        '_insertedAt': { name: 'inserted_at', format: 'date' },
        '_name': 'name',
        '_parentId': 'parent_id',
        '_projectId': 'project_id',
        '_teamId': 'team_id',
        '_updatedAt': { name: 'updated_at', format: 'date' },
        '_versions': { name: 'versions', format: 'number' }
    })
});

