import type { ISAMObject } from '../../indexPrivate';
import SAMError, { SAMErrorCode } from '../SAMError';
import type { IHasKeyMap } from './key';
import { KeysProperty } from './key';

type CacheableDescriptor<ValueType> = (target: ISAMObject, propertyKey: string, descriptor: TypedPropertyDescriptor<ValueType>) => void;

/**
 * Caches the result of the method, using the argument decorated with '@key' as the key (multiple arguments can also be
 * used, and they will be appended together). This ensures that the result is cached in memory and shared if multiple
 * people call the API at once. Once the value expires, it will be recomputed.
 *
 * Note:
 * 1) Keys are global, so different cached methods should use different key domains unless it's intended to be shared.
 *    We typically use URLs as keys to avoid such conflicts.
 * 2) Decorators are not passed the default value of parameters, so you can't write f(@key x = 'defaultValue') - you need
 *    to make sure the value is always passed in.
 */
function cacheImpl<ValueType extends ISAMObject>(validate?: (value: any) => boolean): CacheableDescriptor<ValueType> {
    return (target: ISAMObject, propertyKey: string, descriptor: TypedPropertyDescriptor<ValueType>) => {
        const method = descriptor.value;
        if (!method) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, '@cache decorator can only be applied to a method');
        }
        const newMethod = async function (this: IHasKeyMap & ISAMObject, ...args: any[]) {
            const keyIndex = this[KeysProperty]?.get(propertyKey);
            if (keyIndex === undefined) {
                throw SAMError.create(SAMErrorCode.BAD_REQUEST, '@cache decorator requires one of the parameters to be labelled with @key');
            }
            const key: string = args[keyIndex];
            return this._core._environment.cache.getItem(key, () => (method as any).apply(this, args), validate);
        };
        descriptor.value = (newMethod as unknown) as ValueType;
    };
}

// Allow both @cache with no parameters, or @cache(validate) with a validation function
export default function cache<T1 extends ISAMObject, ValueType>(target: T1, property: string, arg3: TypedPropertyDescriptor<ValueType>): TypedPropertyDescriptor<ValueType>;
export default function cache(validate?: (value: any) => boolean): CacheableDescriptor<any>;

export default function cache(arg1: any, arg2?: string, arg3?: any): any {
    if (!arg2) {
        return cacheImpl(arg1);
    }

    // No parameter - invoke without validation
    // (allows using @cache without any parameters)
    return cacheImpl()(arg1, arg2, arg3);
}
