import {
    type IOpFieldMatches,
    SearchProps,
    USS_ARTIFACT_MEDIATYPE
} from '../interface/USSModel';

export const EXPRESS_ARTIFACT_TYPE = 'application/vnd.adobe.hz.express+dcx';

export function excludeExpressArtifacts(): IOpFieldMatches[] {
    return [ {
        [SearchProps.FIELD_MATCHES]: { [USS_ARTIFACT_MEDIATYPE]: EXPRESS_ARTIFACT_TYPE }
    } ];
}
