import type jsonpatch from 'json-patch';

import type { IOrderDirection } from '../core/ItemOrder';
import InterfaceBase from './InterfaceBase';
import type {
    IProjectsTeamsResponse,
    IProjectsSpacesResponse,
    IProjectsSpaceOrderBy,
    IProjectsSpaceResponse,
    IProjectsSpaceLinks,
    IProjectsTeamCreateResponse,
    IWorkspacesIndexLinks,
    IProjectsTeamsOrderBy,
    IWorkspacesIndexResponse,
    IProjectsTeamProvisionResponse,
    IProjectsBookmarkOpsData,
    IProjectsSpaceContextRequest,
    IProjectsSpaceContextResponse,
    IProjectsBookmarkBatchResponse,
    IProjectsOrgRepositoriesResponse,
    IProjectSpaceSelector,
    IProjectsTeamLinks,
    IProjectsCreateQuery,
    IProjectsTeamCreateQuery,
    IProjectsTeamState,
    IProjectsTeamPropertiesResponse
} from './WorkspacesModel';
import {
    WORKSPACE_INDEX_LINKS
} from './WorkspacesModel';
import type {
    HeaderMap } from './LinkUtils';
import {
    getURLFromLinks,
    JSON_MIME_TYPE,
    JSON_PATCH_MIME_TYPE,
    RelType,
    validateLinks
} from './LinkUtils';
import { cache, key } from '../core/decorators';

// Team provisioning can return both 200 and 201 depending on if
// the user already had the team created or not. We check for this ahead of time,
// but there is a chance the user has a pending or simultaneous call to provision
// the team from a different tab or application. In SAM we don't actually
// care about 200 or 201, but we want to make sure they are both valid codes.
const TEAM_PROVISION_SUCCESS_CODES = [ 200, 201 ];

export const SPACE_FULL_SELECTOR: IProjectSpaceSelector[] = [ 'FULL' ];

type IPageOptions = {
    start: number;
    limit: number;
}

export interface TeamsListingOptions extends IListingOptions<IProjectsTeamsOrderBy> {
    state?: IProjectsTeamState;
    nameContains?: string;
}

interface IListingOptions<IOrderField> extends IPageOptions {
    orderDirection: IOrderDirection;
    orderBy: IOrderField;
}

export interface SpacesListingOptions extends IListingOptions<IProjectsSpaceOrderBy> {
    bookmarked: boolean;
    teamID?: string;
    teamAccess?: boolean;
}

const DefaultTeamListingOptions: TeamsListingOptions = {
    start: 0,
    limit: 0,
    orderDirection: 'ascending',
    orderBy: 'name'
};

const DefaultSpacesListingOptions: SpacesListingOptions = {
    orderDirection: 'ascending',
    orderBy: 'name',
    bookmarked: false,
    teamID: undefined,
    start: 0,
    limit: 0
};

function getDefaultOptions<OptionTypes>(Defaults: OptionTypes, options?: Partial<OptionTypes>): OptionTypes {
    return Object.assign({}, Defaults, options);
}

function getDirectionValue<IOrderField>(userOptions: IListingOptions<IOrderField>) {
    const directionFlag = userOptions.orderDirection === 'ascending' ? '+' : '-';
    return directionFlag + userOptions.orderBy;
}

function createPageTemplate(options: IPageOptions) {
    const templateValues: any = {};
    if (options.start) {
        templateValues.start = options.start;
    }
    if (options.limit) {
        templateValues.limit = options.limit;
    }
    return templateValues;
}

export function getTeamListingPath(links: IWorkspacesIndexLinks, options?: Partial<TeamsListingOptions>): string {
    const userOptions = getDefaultOptions(DefaultTeamListingOptions, options);
    const templateValues = createPageTemplate(userOptions);
    templateValues.orderBy = getDirectionValue(userOptions);
    templateValues.nameContains = userOptions.nameContains;
    templateValues.state = userOptions.state;
    return getURLFromLinks(links, RelType.TEAMS_PAGE, templateValues);
}

export function getSpacesListingPath(links: IWorkspacesIndexLinks, options?: Partial<SpacesListingOptions>): string {
    const userOptions = getDefaultOptions(DefaultSpacesListingOptions, options);
    const templateValues: any = createPageTemplate(userOptions);
    templateValues.orderBy = getDirectionValue(userOptions);
    // The service sets bookmarkFilter to "true" by default, so pass "false" if bookmarked is false or undefined.
    if (!userOptions.bookmarked) {
        templateValues.bookmarkFilter = false;
    }
    // The only value that is implemented by the server is teamAccess=undefined or teamAccess=false.
    // teamAccess=undefined -> all spaces are returned
    // teamAccess=false -> returns only the spaces that are from teams the user is not part of.
    if (userOptions.teamAccess === false) {
        templateValues.teamAccess = false;
    }
    const { teamID } = userOptions;
    if (teamID) {
        templateValues.teamId = teamID;
    }
    return getURLFromLinks(links, RelType.WORKSPACES_PAGE, templateValues);
}

function validateRequiredProjectLinks(links: any) {
    return validateLinks(links, WORKSPACE_INDEX_LINKS);
}

export default class WorkspacesInterface extends InterfaceBase {

    private _getHeaders(contentType?: string): HeaderMap {
        const headers: HeaderMap = {
            'x-service-features': 'CanvasMigration',
            // NOTE: [SAM-1222] disabling cache because /projects/{spaceId} sets an etag header that
            //      does not change when the user's bookmark preference changes, causing browsers to
            //      automatically add the etag header on requests and get the cached value of the
            //      bookmark field rather than the actual value.
            'Cache-Control': 'no-cache'
        };
        if (contentType) {
            headers['Content-Type'] = contentType;
        }
        return headers;
    }

    @cache(validateRequiredProjectLinks)
    private async _discoverLinks(@key rootHref: string): Promise<IWorkspacesIndexLinks> {
        const response: IWorkspacesIndexResponse = await this._getResponse(rootHref, this._getHeaders());
        return response._links;
    }

    private _getEndpointHref(endpoint: string): string {
        return `https://${this._core._environment.endpoints.PROJECTS_HOST}${endpoint}`;
    }

    async discoverLinks(): Promise<IWorkspacesIndexLinks> {
        return this._discoverLinks(this._getEndpointHref(`/api/v2/index`));
    }

    async getTeams(options?: Partial<TeamsListingOptions>): Promise<IProjectsTeamsResponse> {
        const links = await this.discoverLinks();
        const url = getTeamListingPath(links, options);
        return await this._getResponse(url, this._getHeaders());
    }

    /**
     * Get repositories where user can create CC Team
     */
    async getOrgRepositories(): Promise<IProjectsOrgRepositoriesResponse> {
        const links = await this.discoverLinks();
        const url = getURLFromLinks(links, RelType.REPOSITORIES_PAGE, {});
        return await this._getResponse(url, this._getHeaders());
    }

    /**
     * Create a team under /content/assets folder.
     */
    async createTeam(data: IProjectsTeamCreateQuery): Promise<IProjectsTeamCreateResponse> {
        const links = await this.discoverLinks();
        const url = getURLFromLinks(links, RelType.TEAMS_CREATE, {});
        const response = await this._doPost(
            url,
            this._getHeaders(JSON_MIME_TYPE),
            JSON.stringify(data));
        return response.json();
    }

    /**
     * Permanently Delete a Team
     */
    async permanentlyDeleteTeam(links: IProjectsTeamLinks): Promise<void> {
        const url = getURLFromLinks(links, RelType.TEAMS_PRIMARY);
        await this._doDelete(url, this._getHeaders(), [ 204 ]);
    }

    /**
     * Archive/Discard Team
     */
    async archiveTeam(links: IProjectsTeamLinks): Promise<void> {
        const url = getURLFromLinks(links, RelType.TEAMS_DISCARD);
        await this._doPost(url, this._getHeaders(), undefined, [ 204 ]);
    }

    /**
     * Restore Team.
     */
    async restoreTeam(teamLinks: IProjectsTeamLinks): Promise<void> {
        const url = getURLFromLinks(teamLinks, RelType.TEAMS_RESTORE);
        await this._doPost(url, this._getHeaders(), undefined, [ 204 ]);
    }

    /**
     * Rename Team.
     */
    async renameTeam(teamLinks: IProjectsTeamLinks, name: string): Promise<void> {
        const url = getURLFromLinks(teamLinks, RelType.TEAMS_RENAME);
        await this._doPost(url, this._getHeaders(JSON_MIME_TYPE), JSON.stringify({ name }), [ 204 ]);
    }

    /**
     * Patch a Team
     */
    async patchTeam(teamLinks: IProjectsTeamLinks, data: jsonpatch.OpPatch[]) {
        const url = getURLFromLinks(teamLinks, RelType.TEAMS_PROPERTIES);
        await this._doPatch(url, { ...this._getHeaders(JSON_PATCH_MIME_TYPE), 'If-Match': '*' }, JSON.stringify(data), [ 204 ]);
    }

    /**
     * Fetches Properties for a team.
     */
    async getTeamProperties(teamLinks: IProjectsTeamLinks): Promise<IProjectsTeamPropertiesResponse> {
        const url = getURLFromLinks(teamLinks, RelType.TEAMS_PROPERTIES);
        return await this._getResponse(url, this._getHeaders());
    }

    /**
     * Provisions a Team folder within User storage for a Type 1 user only. The provisioned team name is in format:
     * "Team {{USER_FIRST_NAME}}" depending on the localization of the requesting user.
     */
    async provisionTeam(): Promise<IProjectsTeamProvisionResponse> {
        const links = await this.discoverLinks();
        const url = getURLFromLinks(links, RelType.TEAM_PROVISION, {});
        const response = await this._doPost(url, this._getHeaders(), undefined, TEAM_PROVISION_SUCCESS_CODES);
        return response.json();
    }

    async getSpaces(options?: Partial<SpacesListingOptions>): Promise<IProjectsSpacesResponse> {
        const links = await this.discoverLinks();
        const url = getSpacesListingPath(links, options);
        return await this._getResponse(url, this._getHeaders());
    }

    async getSpace(id: string, selector: IProjectSpaceSelector[] = SPACE_FULL_SELECTOR): Promise<IProjectsSpaceResponse> {
        const links = await this.discoverLinks();
        const spaceLink = getURLFromLinks(links, RelType.WORKSPACES_PRIMARY, { id, selector });
        return await this._getResponse(spaceLink, this._getHeaders());
    }

    async reloadSpace(spaceLinks: IProjectsSpaceLinks, selector: IProjectSpaceSelector[] = SPACE_FULL_SELECTOR): Promise<IProjectsSpaceResponse> {
        const spaceLink = getURLFromLinks(spaceLinks, RelType.WORKSPACES_PRIMARY, { selector });
        return await this._getResponse(spaceLink, this._getHeaders());
    }

    async bookmarkOp(data: IProjectsBookmarkOpsData): Promise<IProjectsBookmarkBatchResponse> {
        const links = await this.discoverLinks();
        const url = getURLFromLinks(links, RelType.WORKSPACES_BOOKMARKS_BATCH);
        const response = await this._doPost(url, this._getHeaders(JSON_MIME_TYPE), JSON.stringify(data), [ 200 ]);
        return response.json();
    }

    async createSpace(teamLinks: IProjectsTeamLinks, data: IProjectsCreateQuery): Promise<IProjectsSpaceResponse> {
        const url = getURLFromLinks(teamLinks, RelType.WORKSPACES_CREATE);
        const response = await this._doPost(url, this._getHeaders(JSON_MIME_TYPE), JSON.stringify(data));
        return response.json();
    }

    async patchSpace(spaceLinks: IProjectsSpaceLinks, data: jsonpatch.OpPatch[]): Promise<void> {
        const url = getURLFromLinks(spaceLinks, RelType.WORKSPACES_PRIMARY);
        await this._doPatch(url, this._getHeaders(JSON_PATCH_MIME_TYPE), JSON.stringify(data), [ 200, 204 ]);
    }

    async getEnclosingSpaces(data: IProjectsSpaceContextRequest): Promise<IProjectsSpaceContextResponse> {
        const links = await this.discoverLinks();
        const url = getURLFromLinks(links, RelType.WORKSPACES_CONTEXT);
        const response = await this._doPost(url, this._getHeaders(JSON_MIME_TYPE), JSON.stringify(data), [ 200 ]);
        return response.json();
    }
}
