import type { SAM } from '@ccx-public/component-types';
import { observable } from '../core/decorators';
import ItemBase from '../core/ItemBase';
import PropertyUpdater from '../core/PropertyUpdater';
import ItemUpdater from '../core/ItemUpdater';
import type {
    CommentCore,
    CommentCreator,
    CommentMention,
    CommentTarget,
    MotivationType,
    GeneratorType,
    TypeAnnotation,
    StatusType,
    CommentData,
    CommentMetadata,
    ComputedCommentCore
} from '../interface/CommentModel';
import type CommentsResource from './CommentsResource';
import type CommentInterface from '../interface/CommentInterface';
import type ItemPool from '../core/ItemPool';

// RE: https://wiki.corp.adobe.com/display/ACPCSDK/Commenting+Service+Integration+Into+SAM

// TODO : Commenting can be used by Guest Users
// RE: https://git.corp.adobe.com/redhawk/native_client_sdk/blob/f0cd86aa3047c1392403b4444b5338189d7302e5/EurekaClientSDK/api/WebAnnotationsApi.cpp
//  I haven't researched how it's done, but the native code supports
//  AnonBearer tokens for guest users.


/**
 * Class representing the notion of a comment ( aka annotation ).
 * @extends ItemBase
 *
 * @example
 * // Instantiate list and load contents
 * const classroomsList = core.classroomContext.getClassrooms().getList(...options);
 * await waitForListLoad(classroomsList);
 *
 * // Get a specific classroom
 * const load = useMemo(() => core.classroomContext.getClassroomById(id), [classroomContext, id]);
 * const { value: classroom, error, loading } = useLoading<Classroom | undefined>(undefined, load);
 */

export default class Comment extends ItemBase implements SAM.Comment {
    private _commentsResource?: CommentsResource;

    // WARNING: the server response for a comment includes
    //  "id": "/assets/${assetUrn}/annots/${annotationId}",
    //  "creationId": "${annotationId}",
    //
    // so we map "creationId" to comment.id
    // because ItemBase.id is expected to be the object's cloud-id,
    // and "id" to comment.uri to avoid a naming conflict.

    private _creator?: CommentCreator = undefined;
    private _created: Date = new Date(0);
    private _bodyValue?: string = undefined;
    private _motivation?: MotivationType = undefined;
    private _generator: GeneratorType = 'https://comments.acrobat.com/Comment';
    private _type: TypeAnnotation = 'Annotation';
    private _target?: CommentTarget = undefined;
    private _mentions?: Array<CommentMention> = undefined;
    private _modified: Date = new Date(0);
    private _etag?: string = undefined;
    private _uri?: string = undefined;
    private _status?: StatusType = undefined;
    private _replies?: Array<CommentCore> = undefined;
    private _readStatus: boolean = false;

    //-----------------------------------------------------------------
    // Simple accessors

    @observable
    get creator(): any {
        return this._creator;
    }

    @observable
    get created(): Date {
        return this._created;
    }

    @observable
    get bodyValue(): string {
        return this._bodyValue || '';
    }

    @observable
    get motivation(): MotivationType {
        // Possible values are ('commenting' | 'replying')
        return this._motivation || 'commenting';
    }

    @observable
    get generator(): GeneratorType {
        // Possible value is 'https://comments.acrobat.com/Comment'
        return this._generator || 'https://comments.acrobat.com/Comment';
    }

    @observable
    get type(): TypeAnnotation {
        // Possible value is 'Annotation'
        return this._type || 'Annotation';
    }

    @observable
    get target(): CommentTarget | undefined {
        return this._target;
    }

    @observable
    get mentions(): Array<CommentMention> | undefined {
        return this._mentions;
    }

    @observable
    get modified(): Date {
        return this._modified;
    }

    @observable
    get etag(): string {
        return this._etag || '';
    }

    @observable
    get uri(): string {
        return this._uri || '';
    }

    @observable
    get status(): StatusType {
        // Possible values are defined in CommentModel.ts
        return this._status || 'open';
    }

    @observable
    get replies(): Array<CommentCore> | undefined {
        // Possible values are ('open' | 'resolved')
        return this._replies;
    }

    @observable
    get readStatus(): boolean {
        return this._readStatus;
    }

    toJSON() {

        // When an object implements toJSON()
        // JSON.stringify(object) serializes object.toJSON()
        // instead of object, allowing you to control
        // the keys and values written.
        //
        // This method is returning a Partial<CommentCore>
        // which can be used in a POST or PUT to the server.

        return {
            '@context': [
                'https://www.w3.org/ns/anno.jsonld',
                'https://comments.acrobat.com/ns/anno.jsonld'
            ],
            'creator': this._creator,
            'created': this.created.toISOString(),
            'bodyValue': this.bodyValue,
            'motivation': this.motivation,
            'generator': this.generator,
            'type': this.type,
            'target': this.target,

            /* TODO : 'mentions' : this.mentions */

            'modified': this.modified.toISOString(),
            'etag': this.etag,

            // Map ItemBase.id back to 'creationId',
            // and Comment.uri back to 'id'.

            'id': this.uri,
            'creationId': this.id,
            'status': this.status,

            /* TODO :  'replies': this.replies, */
        };

    }
    // Simple accessors
    //-----------------------------------------------------------------

    get assetUrn(): string {
        // Split "/assets/${assetUrn}/annots/${annotationId}"
        // into ['', 'assets', assetUrn, 'annots', annotationId]
        // so we can return assetUrn

        const uri = this.uri;
        const array = uri.split('/');

        return (array.length > 2) ? array[2] : '';
    }

    private get _pool(): ItemPool<Comment> {
        return this._commentsResource!._commentPool!;
    }

    private get _interface(): CommentInterface {
        return this._commentsResource!._commentInterface!;
    }

    //-----------------------------------------------------------------
    // Public methods

    async edit(changes: Partial<CommentCore>): Promise<Comment> {
        const commentInterface = this._interface;
        const commentPool = this._pool;

        // Get our current state as a CommentCore
        const current: Partial<CommentCore> = this.toJSON();

        // combine current with changes
        const body: Partial<CommentCore> = { ...current, ...changes };

        // update the server with the edited body
        const response = await commentInterface.editComment({
            annotationId: this.id,
            etag: this.etag,
            body
        });

        // update our local object with the server response, triggering notifications
        const session = commentPool.createUpdateSession<Comment>();
        CommentUpdater.updateLocalItem(session, this, response);
        session.commit();

        return this;
    }

    async updateResolvedStatus(isResolved: boolean): Promise<Comment> {
        const status = isResolved ? 'resolved' : 'open';

        return this.edit({ status });
    }

    async updateReadStatus(isRead: boolean): Promise<Comment> {
        const commentInterface = this._interface;
        const commentPool = this._pool;

        const response = await commentInterface.updateMetadata({
            annotId: this.id,
            read: isRead
        });

        const session = commentPool.createUpdateSession<Comment>();
        CommentUpdater.updateLocalItem(session, this, {
            creationId: this.id,
            readStatus: response.read

        });
        session.commit();

        return this;
    }

    async delete(): Promise<void> {
        const commentInterface = this._interface;
        const commentPool = this._pool;
        const id = this.id;

        await commentInterface.deleteComment({
            annotationId: id,
            etag: this.etag
        });

        // after the server deletes the remote object,
        // discard our local object which triggers notifications
        const session = commentPool.createUpdateSession<Comment>();
        session.queueDiscardedItem(this);
        session.commit();

        // the session doesn't actually remove the item from the pool
        commentPool.removeLocalItems([ id ]);
    }

    /**
     * @description Create a reply to this comment.
     * @param data The information necessary for calling the API.
     * @returns A promise that resolves to the newly created reply.
     */
    async reply(data: CommentData): Promise<Comment> {
        const required: Partial<CommentCore> = {
            motivation: 'replying',
            target: {
                source: this.uri
            }
        };

        // overwrite data with the reply required fields
        return this._commentsResource!.createComment({ ...data, ...required });
    }

    /**
     * @description Reclassify a comment through ACMP. This is used
     * to correct an error when a previous classification attempt failed.
     * @throws If the comment does not start in the 'error' status.
     * @returns A promise that resolves to the comment that is now waiting
     *   for reclassification.  The comment is expected to be in the 'pending' status.
     */
    async reclassify(): Promise<Comment> {
        if (this.status !== 'error') {
            throw new Error('Comment is not in the error status');
        }
        const commentInterface = this._interface;
        const commentPool = this._pool;

        const response = await commentInterface.reclassifyComment({
            annotationId: this.id,
            etag: this.etag
        });

        const session = commentPool.createUpdateSession<Comment>();
        CommentUpdater.updateLocalItem(session, this, response);
        session.commit();

        return this;
    }

    private async _updateModerationStatus(newStatus: StatusType): Promise<Comment> {
        if (this.status !== 'review') {
            throw new Error('Comment is not in the review status');
        }
        const commentInterface = this._interface;
        const commentPool = this._pool;

        const response = await commentInterface.editCommentStatus({
            annotationId: this.id,
            etag: this.etag,
            status: newStatus
        });

        const session = commentPool.createUpdateSession<Comment>();
        CommentUpdater.updateLocalItem(session, this, response);
        session.commit();

        return this;
    }

    /**
     * @description Approve a comment. This is used
     * to approve a comment that has been flagged for review.
     * @throws If the comment does not start in the 'review' status.
     * @returns A promise that resolves to the comment that is now in the 'open' status.
     */
    async approve(): Promise<Comment> {
        return this._updateModerationStatus('open');
    }

    /**
     * @description Reject a comment. This is used
     * to reject a comment that has been flagged for review.
     * @throws If the comment does not start in the 'review' status.
     * @returns A promise that resolves to the comment that is now in the 'blocked' status.
     */
    async reject(): Promise<Comment> {
        return this._updateModerationStatus('blocked');
    }
}

export const CommentUpdater = new ItemUpdater<Comment, Partial<ComputedCommentCore | CommentMetadata>>({
    localItemType: Comment,

    // NOTE: We are using property 'creationId' in the response as the ItemBase.id

    remoteIdProperty: 'creationId',
    propertyUpdater: new PropertyUpdater({
        // TODO : create nested updater for CommentCreator ?
        _creator: { name: 'creator', format: 'object' },

        // TODO : this is a Date.toISOString(); should this be Date ?
        _created: { name: 'created', format: 'date' },

        _bodyValue: { name: 'bodyValue', format: 'string' },

        // should be ( 'commenting' | 'replying' ), but allow any string (future proof)
        _motivation: { name: 'motivation', format: 'string' },

        // should be 'https://comments.acrobat.com/Comment', but allow any string (future proof)
        _generator: { name: 'generator', format: 'string' },

        // should be 'Annotation', but allow any string (future proof)
        _type: { name: 'type', format: 'string' },

        // TODO : create nested updater for CommentTarget ?
        _target: { name: 'target', format: 'object' },

        // TODO : create nested updater for CommentMention[] ?
        _mentions: { name: 'mentions', format: 'object' },

        // TODO : this is a Date.toISOString(); should this be Date ?
        _modified: { name: 'modified', format: 'date' },

        _etag: { name: 'etag', format: 'string' },

        // NOTE: 'creationId' is mapped to ItemBase.id,
        // and 'id' is mapped to comment.uri.
        _uri: { name: 'id', format: 'string' },

        // should be ( 'open' | 'resolved' ), but allow any string (future proof)
        _status: { name: 'status', format: 'string' },

        // TODO : create nested updater for Comment[] ?
        _replies: { name: 'replies', format: 'object' },

        _readStatus: { name: 'readStatus', format: 'boolean' }
    }),
});
