/**
 * Utils
 * @packageDocumentation
 * @module Utils
 * @internal
 */

import type { IMSProfileData } from '../../../models/data/IMSTokenData';
import type { UserData } from '../../../models/data/ConfigurationData';

const BYTE_SPLIT_REGEX = /[a-f0-9]{2}/gi;
const PLATFORM = 'platform-cs';
const PLATFORM_EDGE = `${PLATFORM}-edge`;
const PLATFORM_DISCOVERY_ENDPOINTS: Array<string> = [
    `https://${PLATFORM}.adobe.io/index`,
    `https://${PLATFORM}-stage.adobe.io/index`
];
const PRIORITY_HEADER = { Priority: 'u=1' };

function decodeToken(token: string): IMSProfileData | undefined {
    const parts = token.split('.');

    if (parts.length !== 3) {
        return undefined;
    }

    try {
        return JSON.parse(atob(parts[1]));
    } catch (e) {
        return undefined;
    }
}

export function extractUserDataFromToken(token: string): UserData | undefined {
    const decoded = decodeToken(token);

    if (decoded) {
        return {
            user: {
                id: decoded.user_id,
                clientId: decoded.client_id
            }
        };
    }
    return undefined;
}

export function extractExpiryFromToken(token: string): number | undefined {
    const decoded = decodeToken(token);

    if (decoded) {
        const elapsed = Date.now() - parseInt(decoded.created_at, 10);
        return Math.max(parseInt(decoded.expires_in, 10) - elapsed, 0);
    }

    return undefined;
}

export function hexToBase64(input: string): string {
    // Inspired by https://stackoverflow.com/questions/23190056/hex-to-base64-converter-for-javascript
    return btoa(String.fromCharCode(...(input.match(BYTE_SPLIT_REGEX) as string[]).map(byte => parseInt(byte, 16))));
}

/**
 * Utility function to inject use of ACP edge functionality with a
 * default priority of 3 set on optional request headers
 *
 * @export
 * @param {string} url URL client wants to promote to edge request
 * @returns modified edge url if provided url is a platform url and header object with set priority header
 */
export function useEdge(url: string): { url: string; headers: Record<string, any> } {
    // Potential relative paths / url with no domain injected yet...
    let parsedUri: URL;
    try {
        parsedUri = new URL(url);
    } catch (e) {
        return { url, headers: {} };
    }

    // Check if the url passed in is a platform endpoint
    if (!parsedUri.hostname.includes(PLATFORM)) {
        return { url, headers: {} };
    }

    // Check if the url is a discovery endpoint and replace hostname with edge endpoint if it is
    if (PLATFORM_DISCOVERY_ENDPOINTS.includes(url)) {
        parsedUri.hostname = parsedUri.hostname.replace(PLATFORM, PLATFORM_EDGE);
    }

    return { url: parsedUri.href, headers: { ...PRIORITY_HEADER } };
}
