import type { IServiceLink, RelType } from './LinkUtils';

export interface IGradientColorRGB {
    r: number;
    g: number;
    b: number;
}

export interface IGradientColorStopValue {
    mode: string;
    value: IGradientColorRGB;
}

/**
 * Color Stop
 * Each color stop has at minimum a color and offset.
 * Every color must include an sRGB representation.
 */
export interface IGradientColorStop {
    color: IGradientColorStopValue[];
    /**
     * Percentage offset for the color stop along the gradient path
     */
    offset: number;
}

export interface IGradientResponseLinks {
    [RelType.PROJECTS_GRADIENTS_COLLECTION]: IServiceLink
}

export interface IGradientItemResponse {
    'project:gradientId': string;
    /**
     * IComputedGradientData extends IGradientData and
     * adds a couple of properties for use within SAM.js.
     */
    'project:gradientData': IComputedGradientData;
    'project:gradientName': string;
    'project:gradientTextColor': IGradientTextColor;
}

export interface IGradientTextColor {
    alpha: number;
    mode: 'RGB' | string;
    value: IGradientColorRGB;
    type: 'process' | string;
}

// The computed item response interface allows us to create an unique
// id for the gradient based on language and it's actual id
// this way we can store the unique gradients.
export interface IGradientComputedItemResponse extends IGradientItemResponse {
    computedID: string;
}

export function computeGradientID(rawGradientId: string, languageCode: string): string {
    return `${rawGradientId}-${languageCode}`;
}

export interface IGradientOpacity {
    /**
     * Percentage offset for the opacity stop along the gradient path
     */
    offset: number;
    /**
     * Location of midpoint between the previous stop and this stop,
     * as a percentage of the distance between by the interpolation algorithm).
     * The midpoint is ignored for the first stop, since it has no previous stop.
     */
    opacity: number;
}

/**
 * Gradient Data Derived from
 * https://git.corp.adobe.com/caf/xcm/blob/1efcec108c1dcc7bfbfe7bc7eb313dcfdcc94138/schemas/cc/library/data/gradient/gradient.schema.json
 */

export interface IGradientData {
    /**
     * The type of gradient (linear or radial)
     */
    type: 'linear' | 'radial';
    /**
     * Rotation of the gradient (applies to both linear and radial gradients)
     * - this is measured anti clockwise from the positive x-axis
     */
    angle?: number;
    /**
     * Each color stop has at minimum a color and offset.
     * Every color must include an sRGB representation.
     */
    stops: IGradientColorStop[];
    /**
     * This is separate from the color stops, since some applications like
     * Photoshop support separate color and opacity stops
     */
    opacities?: IGradientOpacity[];
}

export interface IComputedGradientData extends IGradientData {
    isDefault?: boolean;
    languageCode?: string;
}

export interface IGradientsResponse {
    default: string;
    children: IGradientItemResponse[];
    _links: IGradientResponseLinks;
}

/**
 * Takes the response from the service and computes the result
 * to add additional properties.
 *
 * @param rawGradientData Data directly from the service.
 * @param defaultGradientId The default gradient from the service.
 * @param languageCode The language code.
 * @returns
 */
export function computeGradients(
    rawGradientData: IGradientItemResponse[],
    defaultGradientId: string,
    languageCode: string
): IGradientComputedItemResponse[] {
    return rawGradientData.map((gradient: IGradientItemResponse) => {
        return {
            ...gradient,
            computedID: computeGradientID(gradient['project:gradientId'], languageCode),
            'project:gradientData': {
                ...gradient['project:gradientData'],
                isDefault: defaultGradientId === gradient['project:gradientId'],
                languageCode
            }
        };
    });
}
