import { LibraryOrderBy } from '../interface/LibraryModel';
import type { IComparatorMap } from '../core/ItemOrder';
import { compareStrings, compareValues, createItemOrderFactory } from '../core/ItemOrder';

import type Library from './Library';

export type LibraryOrderField =
    | 'name'
    | 'created'
    | 'modified';

export const OrderFieldToLibraryOrderBy: { [key in LibraryOrderField]: LibraryOrderBy} = {
    'name': LibraryOrderBy.NAME,
    'created': LibraryOrderBy.CREATED_DATE,
    'modified': LibraryOrderBy.MODIFIED_DATE
};

// Appropriate comparator is used in order.sortItems when copying or updating ItemLists,
// which occurs when a page is loaded and the ItemLoaderState changes.
const OrderFieldToComparator: IComparatorMap<Library, LibraryOrderField> = {
    name(a: Library, b: Library): number {
        // LibraryOrder is only used on lists from LibrarySource, where LibraryData from melville should already be loaded.
        // (But just in case, this falls back to repoMetadata name, though this wouldn't work properly for libraries in sync groups.)
        return compareStrings(a.displayName || a.name, b.displayName || b.name);
    },

    created(a: Library, b: Library): number {
        return compareValues(a.created, b.created);
    },

    modified(a: Library, b: Library): number {
        return compareValues(a.modified, b.modified);
    }
};

export default class LibraryOrder extends createItemOrderFactory(OrderFieldToComparator) {
    static default = new LibraryOrder('descending', 'modified');
}
