import type AdobeAsset from './AdobeAsset';
import type { IItemLoaderOptions, ILoadedPage } from '../core/ItemLoader';
import type ItemPool from '../core/ItemPool';
import type { IGetUSSResults, IUSSLoader } from './USSLoaderHelper';
import USSLoaderHelper from './USSLoaderHelper';
import type { ISAMCorePrivate } from '../indexPrivate';
import type { USSResponse } from '../interface/USSModel';
import type { FFBoardsAdobeAssetConfig } from '../assets/FFBoardsSource';
import type FFBoardsInterface from '../interface/FFBoardsInterface';
import type { FFBoardsAssetsListingOptions } from '../interface/FFBoardsInterface';
import { DEFAULT_MAX_LIMIT } from '../interface/USSv3Interface';
import { getMediaTypesFromFilters, getVariableFromObj } from '@sam-js-src/utils/loaderUtils';

export default class FFBoardsLoader implements IUSSLoader<FFBoardsAdobeAssetConfig> {
    private _ussLoaderHelper: USSLoaderHelper<FFBoardsAdobeAssetConfig>;
    /**
     * @package -- only for use in SAM.js
     */
    constructor(
        assetPool: ItemPool<AdobeAsset>,
        _core: ISAMCorePrivate,
        private _ffBoardsInterface: FFBoardsInterface
    ) {
        this._ussLoaderHelper = new USSLoaderHelper<FFBoardsAdobeAssetConfig>(assetPool, _core, this);
    }

    async loadPage(options: IItemLoaderOptions<FFBoardsAdobeAssetConfig>): Promise<ILoadedPage<FFBoardsAdobeAssetConfig>> {
        return this._ussLoaderHelper.loadPage(options);
    }

    private _getListingOptionsFromFilters(implicitFilter: FFBoardsAdobeAssetConfig['implicitFilter'], filter: FFBoardsAdobeAssetConfig['filter']) {
        const opts = getVariableFromObj('options', filter);

        return {
            isSharedWithYou: getVariableFromObj('isSharedWithYou', opts),
            ownedBy: getVariableFromObj('ownedBy', opts),
            mediaTypes: getMediaTypesFromFilters(implicitFilter, filter)
        };
    }

    /**
     * @package -- only for use by USSLoaderHelper
     */
    async _getUSSResults({
        start,
        loadOptions,
        order,
        implicitFilter,
        filter
    }: IGetUSSResults<FFBoardsAdobeAssetConfig>): Promise<USSResponse> {
        const options: FFBoardsAssetsListingOptions = {
            start,
            limit: loadOptions?.limit || DEFAULT_MAX_LIMIT,
            orderDirection: order.direction,
            orderBy: order.field,
            ...this._getListingOptionsFromFilters(implicitFilter, filter)
        };
        return this._ffBoardsInterface.getAssets(options);
    }
}

