export const boardMediaTypeString = 'application/vnd.adobe.board+dcx';

export function repoMetadataIsBoard(repoMetadata: Partial<RepositoryMetadata>): boolean {
    return repoMetadata?.['dc:format'] === boardMediaTypeString;
}

export const libraryMediaTypeString = 'application/vnd.adobe.library+dcx';

export function repoMetadataIsLibrary(repoMetadata: Partial<RepositoryMetadata>): boolean {
    return repoMetadata?.['dc:format'] === libraryMediaTypeString;
}

export function repoMetadataIsGenerationHistoryAsset(repoMetadata: Partial<RepositoryMetadata>): boolean {
    return repoMetadata?.['dc:format'] ? GENERATION_HISTORY_MEDIA_TYPES.includes(repoMetadata?.['dc:format']) : false;
}

export function metadataIsAssignment({ repoMetadata, appMetadata }: {repoMetadata: RepositoryMetadata, appMetadata?: IAppMetadata}) {
    return appMetadataIsAssignment(appMetadata) || isAssignmentPath({ repoPath: repoMetadata['repo:path'] });
}

export function appMetadataIsAssignment(app_metadata?: IAppMetadata) {
    return !!app_metadata?.['cc:inheritable']?.['cc:assignment']?.['repo:assetId'];
}

export function appMetadataIsProject(app_metadata?: IAppMetadata) {
    return !!app_metadata?.['cc:inheritable']?.['cc:team']?.['repo:assetId'];
}

export function ussV3ItemMetadataIsProject(item: USSItemMetadata): boolean {
    return !!item.am?.['cc:inheritable']?.['cc:team']?.['repo:assetId'];
}

export function ussV3ItemMetadataIsBoard(item: USSItemMetadata): boolean {
    return item.rm?.['dc:format'] === boardMediaTypeString;
}

export function ussV3ItemMetadataIsLibrary(item: USSItemMetadata): boolean {
    return item.rm?.['dc:format'] === libraryMediaTypeString;
}

export function metadataIsStudentAssignment({ repoMetadata, appMetadata }: {repoMetadata: RepositoryMetadata, appMetadata?: IAppMetadata}) {
    return appMetadataIsStudentAssignment(appMetadata) || isStudentAssignmentPath({ repoPath: repoMetadata['repo:path'] });
}

export function appMetadataIsStudentAssignment(app_metadata?: IAppMetadata): boolean {
    return !!app_metadata?.['cc:inheritable']?.['cc:studentAssignment']?.['repo:assetId'];
}

export function ussMetadataIsLibrary(item: Partial<USSMetadata>): boolean {
    return item.type === libraryMediaTypeString;
}

export function ussMetadataIsCustomModel(item: Partial<USSMetadata>): item is CustomModelInfoUSS {
    return item.type === CUSTOM_MODEL_MEDIA_TYPE;
}

export function appMetadataIsStudentAssignmentFile(app_metadata?: IAppMetadata): boolean {
    return !!app_metadata?.['cc:inherited']?.['cc:studentAssignment']?.['repo:assetId'];
}

function metadataIsStudentAssignmentFile({ repoMetadata, appMetadata }: {repoMetadata: RepositoryMetadata, appMetadata: IAppMetadata}) {
    return appMetadataIsStudentAssignmentFile(appMetadata) || isStudentAssignmentFilePath({ repoPath: repoMetadata['repo:path'] });
}

function repoToStudentAssignmentFileData(item: Partial<RepositoryMetadata>, appMetadata: IAppMetadata): Partial<IRemoteStudentAssignmentFile> {
    return {
        ...item,
        ...appMetadata,
    };
}

function repoToProjectData(assetMetadata: Partial<AdobeAssetUpdaterMetadata>, projectMetadata?: IProject): IProject {
    return projectMetadata || {
        'repo:assetId': assetMetadata['repo:assetId'],
        'repo:repositoryId': assetMetadata['repo:repositoryId'],
    } as IProject;
}

function repoToStudentAssignmentData(item: Partial<RepositoryMetadata>, appMetadata: IAppMetadata): Partial<IRemoteStudentAssignment> {
    return {
        ...item,
        ...appMetadata,
        // Student Assignment specific links are not available from an AdobeAsset
        _links: undefined,
    };
}

/* Utils to translate incoming data to the type expected by the subclass's PropertyUpdater: */
// (This mapping is necessary at minimum to translate the id to the remoteIdProperty expected by the PropertyUpdater,
// because we use the updaters to indirectly create an instance of the subclass in the call to
// updater.updateRemoteItems({remoteIdProperty}), regardless of whether the updater supports the incoming data type.)

export function ussV3ToProjectMetadata(item: Partial<USSItemMetadata>): Partial<IProject> {
    // TODO: Add more Project attributes here as they become available in USS.
    // Minimal data needed for ProjectUpdater. When additional Project metadata
    // is available from the USSv3 query result, add them here.
    return { 'repo:assetId': item.id };
}
export function ussToProjectData(item: Partial<USSMetadata>): Partial<IProject> {
    return {
        'repo:assetId': item.asset_id,
        'repo:repositoryId': item['repo:repositoryId'],
        _embedded: {
            [RelType.AC_EFFECTIVE]: item._embedded?.[RelType.AC_EFFECTIVE] as IProjectsEffectivePermissions,
            [RelType.APP_METADATA]: item.app_metadata as IProjectsAppMetadata
        }
    };
}

export function ussToLibraryData(item: Partial<USSMetadata>): Partial<LibraryData> {
    return { 'library_urn': item.asset_id };
}

function ussToStudentAssignmentFileData(item: Partial<USSMetadata>): Partial<IRemoteStudentAssignmentFileMetadataWithComputedValues> {
    const ancestors = item.path || [];
    const studentAssignmentId = item.app_metadata?.['cc:inherited']?.['cc:studentAssignment']?.['repo:assetId'] || ancestors[ancestors.length - 1];
    return {
        ...item,
        'repo:assetId': item['asset_id'],
        'computedStudentAssignmentId': studentAssignmentId,
    };
}

function ussV3ToStudentAssignmentFileData(item: Partial<USSItemMetadata>): Partial<IRemoteStudentAssignmentFileMetadataWithComputedValues> {
    const ancestors = item.rm?.['repo:ancestors'] ?? [];
    const studentAssignmentId = item.am?.['cc:inherited']?.['cc:studentAssignment']?.['repo:assetId'] || ancestors[ancestors.length - 1];
    return {
        ...item.rm,
        ...item.am,
        'computedStudentAssignmentId': studentAssignmentId,
    };
}

function ussV3ToBoardData(item: Partial<USSItemMetadata>): Partial<RemoteBoard> {
    // Omit _links so BoardUpdater does not touch __links (repo metadata has no board-specific links).
    // eslint-disable-next-line @typescript-eslint/no-unused-vars -- destructuring to omit _links
    const { _links, ...restOfItemRepoMetadata } = item.rm || {};
    return {
        ...restOfItemRepoMetadata,
        ...item.am,
    };
}

export function ussToCustomModelData(item: Partial<CustomModelInfoUSS>): Partial<CustomModelInfoMelville> {
    return {
        ...item,
        'repo:assetId': item['asset_id'],
        'application_metadata': item['app_metadata'],
        'firefly#ffmodel': item['firefly#ffmodel'],
        'repo:path': item['original_path'],
        'repo:createDate': Math.floor((new Date(item['create_date']!)).getTime() / 1000),
        'repo:modifyDate': Math.floor((new Date(item['modify_date']!)).getTime() / 1000),
        'repo:version': item['asset_version_id'],
        'storage:region': item['region'],
        'repo:size': item['size']
    };
}

function ussV3ToLibraryData(item: Partial<USSItemMetadata>): Partial<LibraryData> {
    return { 'library_urn': item.id };
}

function repoToLibraryData(item: Partial<RepositoryMetadata>): Partial<LibraryData> {
    return { 'library_urn': item['repo:assetId'] };
}

function repoToAssignmentData(item: Partial<RepositoryMetadata>, appMetadata: IAppMetadata): Partial<IRemoteAssignment> {
    return {
        ...item,
        ...appMetadata,
        // Assignment specific links and correctly structured children assets are not available from an AdobeAsset
        _links: undefined,
        children: [],
    };
}

export type UpdaterMap =
    Map<'project', ItemUpdater<Project, IProject>> &
    Map<'library', ItemUpdater<Library, LibraryData>> &
    Map<'asset', ItemUpdater<AdobeAsset, AdobeAssetUpdaterMetadata>> &
    Map<'assignment', ItemUpdater<Assignment, IRemoteAssignment>> &
    Map<'board', ItemUpdater<Board, RemoteBoard>> &
    Map<'custom-model', ItemUpdater<CustomModel, CustomModelInfoMelville>> &
    Map<'student-assignment-file', ItemUpdater<StudentAssignmentFile, IRemoteStudentAssignmentFile>> &
    Map<'student-assignment', ItemUpdater<StudentAssignment, IRemoteStudentAssignment>> &
    Map<'generation-history', ItemUpdater<AdobeAsset, GenerationHistoryAssetData>>;

function repoToBoardData(item: Partial<RepositoryMetadata>): Partial<RemoteBoard> {
    // Omit _links so BoardUpdater does not touch __links (repo metadata has no board-specific links).
    // eslint-disable-next-line @typescript-eslint/no-unused-vars -- destructuring to omit _links
    const { _links, ...rest } = item;
    return { ...rest };
}

export default class AdobeAssetFactory implements ISAMObject {
    constructor(
        readonly _core: ISAMCorePrivate
    ) {}

    // Creates assets from a list of USSItemMetadata returned from USSv3
    // getItemData maps the repo metadata fields, as well as isShared, sharedViaInvite, and app metadata fields
    // from USSv3 format to RAPI format
    // NOTE: Caller is responsible for committing the session after this is called
    assetsFromUSSV3Response(
        session: IUpdateSession<AdobeAsset>,
        ussItemMetadata: USSItemMetadata[],
        getItemData: (arg: USSItemMetadata) => Partial<AdobeAssetUpdaterMetadata>,
        updaters: UpdaterMap
    ): AdobeAsset[] {
        // If there are no updaters we just return an
        // empty array since there likley isn't any items.
        if (updaters.size === 0 || ussItemMetadata.length === 0) {
            return [];
        }

        const libraryUpdater = updaters.get('library');
        if (libraryUpdater) {
            libraryUpdater.updateRemoteItems(
                session as IUpdateSession<Library>,
                ussItemMetadata.filter(ussV3ItemMetadataIsLibrary).map(ussV3ToLibraryData) as LibraryData[]
            );
        }

        const studentAssignmentFileUpdater = updaters.get('student-assignment-file');
        if (studentAssignmentFileUpdater) {
            studentAssignmentFileUpdater.updateRemoteItems(
                session as IUpdateSession<StudentAssignmentFile>,
                ussItemMetadata.filter((itemMetadata) => metadataIsStudentAssignmentFile({ repoMetadata: itemMetadata.rm, appMetadata: itemMetadata.am }))
                    .map(ussV3ToStudentAssignmentFileData) as IRemoteStudentAssignmentFile[]
            );
        }

        const projectUpdater = updaters.get('project');
        if (projectUpdater) {
            projectUpdater.updateRemoteItems(
                session as IUpdateSession<Project>,
                ussItemMetadata.filter(ussV3ItemMetadataIsProject).map(ussV3ToProjectMetadata) as IProject[]
            );
        }

        const boardUpdater = updaters.get('board');
        if (boardUpdater) {
            boardUpdater.updateRemoteItems(
                session as IUpdateSession<Board>,
                ussItemMetadata.filter(ussV3ItemMetadataIsBoard).map(ussV3ToBoardData) as RemoteBoard[]
            );
        }

        const assetUpdater = updaters.get('asset')!;
        return assetUpdater.updateRemoteItems(
            session,
            // allow Loader to provide additional item metadata (optional)
            ussItemMetadata.map((item: USSItemMetadata): Partial<AdobeAssetUpdaterMetadata> => {
                return getItemData(item);
            }));
    }

    async getUSSV3Updaters(resultsItems: USSItemMetadata[]): Promise<UpdaterMap> {
        const updaters: UpdaterMap = new Map();

        for (const item of resultsItems) {
            if (ussV3ItemMetadataIsBoard(item)) {
                const boardContext = await this._core.getBoardContext();
                updaters.set('board', boardContext._boardUpdater);
            }

            if (ussV3ItemMetadataIsProject(item)) {
                const projectContext = await this._core.getProjectContext();
                updaters.set('project', projectContext._projectUpdater);
            }

            if (ussV3ItemMetadataIsLibrary(item)) {
                const libraryContext = await this._core.getLibraryContext();
                updaters.set('library', libraryContext._libraryUpdater);
            }
        }

        const assetContext = await this._core.getAssetContext();
        updaters.set('asset', assetContext._adobeAssetUpdater);

        return updaters;
    }

    async getUSSUpdaters(resultsItems: USSMetadata[]): Promise<UpdaterMap> {
        const updaters: UpdaterMap = new Map();

        for (const item of resultsItems) {
            if (appMetadataIsProject(item.app_metadata)) {
                const projectContext = await this._core.getProjectContext();
                updaters.set('project', projectContext._projectUpdater);
            }

            if (ussMetadataIsLibrary(item)) {
                const libraryContext = await this._core.getLibraryContext();
                updaters.set('library', libraryContext._libraryUpdater);
            }

            if (ussMetadataIsCustomModel(item)) {
                const customModelContext = await this._core.getCustomModelContext();
                updaters.set('custom-model', customModelContext._customModelUpdaterMelville);
            }

            const assetContext = await this._core.getAssetContext();
            updaters.set('asset', assetContext._ussAdobeAssetUpdater);
        }

        return updaters;
    }

    async getRepoMetadataUpdaters(
        repoMetadatas: RepositoryMetadata[] | LocalAssetMetadata[]
    ): Promise<UpdaterMap>   {
        const updaters: UpdaterMap = new Map();
        for (const item of repoMetadatas) {
            const appMetadata = item._embedded?.[RelType.APP_METADATA]!;
            const assetContext = await this._core.getAssetContext();
            updaters.set('asset', assetContext._adobeAssetUpdater);
            if (appMetadataIsProject(appMetadata) || item['repo:assetType'] === 'project') {
                const projectContext = await this._core.getProjectContext();
                updaters.set('project', projectContext._projectUpdater);
            } else if (repoMetadataIsLibrary(item)) {
                const libraryContext = await this._core.getLibraryContext();
                updaters.set('library', libraryContext._libraryUpdater);
            } else if (repoMetadataIsBoard(item)) {
                const boardContext = await this._core.getBoardContext();
                updaters.set('board', boardContext._boardUpdater);
            } else if (appMetadata && metadataIsStudentAssignmentFile({ repoMetadata: item as RepositoryMetadata, appMetadata })) {
                const classroomContext = await this._core.getClassroomContext();
                updaters.set('student-assignment-file', classroomContext._studentAssignmentFileUpdater);
            } else if (metadataIsStudentAssignment({ repoMetadata: item as RepositoryMetadata, appMetadata })) {
                const classroomContext = await this._core.getClassroomContext();
                updaters.set('student-assignment', classroomContext._studentAssignmentUpdater);
            } else if (appMetadata && metadataIsAssignment({ repoMetadata: item as RepositoryMetadata, appMetadata })) {
                const classroomContext = await this._core.getClassroomContext();
                updaters.set('assignment', classroomContext._assignmentUpdater);
            } else if (repoMetadataIsGenerationHistoryAsset(item)) {
                const generationHistoryContext = await this._core.getGenerationHistoryContext();
                updaters.set('generation-history', generationHistoryContext._generationHistoryAssetUpdater);
            }
        }

        return updaters;
    }

    /**
     * Create assets from a list of items from USS.
     * getItemData allows the caller to add additional metadata
     * @note Caller is responsible for committing the session after this is called.
     *
     */
    assetsFromUSSMetadata(
        session: IUpdateSession<AdobeAsset>,
        items: USSMetadata[],
        getItemData: (arg: USSMetadata) => Partial<AdobeAssetUpdaterMetadata>,
        updaters: UpdaterMap
    ) {
        if (updaters.size === 0 || items.length === 0) {
            return [];
        }

        // Ensure that Projects are added to the discarded list as a "Project" instance.
        // ProjectUpdater creates a blank Project instance and relies on the USSAdobeAssetUpdater
        // to fill in the blanks.
        const projectUpdater = updaters.get('project');
        if (projectUpdater) {
            const projects = projectUpdater.updateRemoteItems(
                session as IUpdateSession<Project>,
                items.filter(item => appMetadataIsProject(item.app_metadata)).map(ussToProjectData) as IProject[]);

            // USS won't have all the permissions required for the deleted view
            // Loaders are responsible for populating the _canRestoreProject cache before it gets here.
            for (const project of projects) {
                project._applyRestorePermission(session as IUpdateSession<Project>);
            }
        }

        const studentAssignmentFileUpdater = updaters.get('student-assignment-file');
        if (studentAssignmentFileUpdater) {
            studentAssignmentFileUpdater.updateRemoteItems(
                session as IUpdateSession<StudentAssignmentFile>,
                items.filter((item) => appMetadataIsStudentAssignmentFile(item.app_metadata) || ussIsStudentAssignmentFilePath(item))
                    .map(ussToStudentAssignmentFileData) as IRemoteStudentAssignmentFile[]
            );
        }

        // Ensure that Libraries are added to the discarded list as a "Library" instance
        const libraryUpdater = updaters.get('library');
        if (libraryUpdater) {
            libraryUpdater.updateRemoteItems(
                session as IUpdateSession<Library>,
                items.filter(ussMetadataIsLibrary).map(ussToLibraryData) as LibraryData[]);
        }

        const customModelUpdater = updaters.get('custom-model');
        if (customModelUpdater) {
            customModelUpdater.updateRemoteItems(
                session as IUpdateSession<CustomModel>,
                items.filter(ussMetadataIsCustomModel).map(ussToCustomModelData) as CustomModelInfoMelville[]
            );
        }
        const ussAssetUpdater = updaters.get('asset')!;
        return ussAssetUpdater.updateRemoteItems(
            session,
            // allow Loader to provide additional item metadata (optional)
            items.map(item => getItemData?.(item) || item)
        );
    }

    // Create assets from a list of RepositoryMetadata returned from RAPI
    // NOTE: Caller is responsible for committing the session after this is called
    assetsFromRepoMetadata(
        session: IUpdateSession<AdobeAsset>,
        repoMetadatas: RepositoryMetadata[],
        updaters: UpdaterMap
    ): AdobeAsset[] {
        if (updaters.size === 0 || repoMetadatas.length === 0) {
            return [];
        }

        return repoMetadatas.map(repoMetadata => {
            let permissions: Permission = {} as Permission;
            if (repoMetadata._embedded?.[RelType.AC_EFFECTIVE]) {
                permissions = parseEffectivePermissions(repoMetadata._embedded?.[RelType.AC_EFFECTIVE] as IEffectivePermissions);
            }
            return this.assetFromRepoMetadata({
                session,
                repoMetadata,
                updaters,
                permissions,
                appMetadata: repoMetadata._embedded?.[RelType.APP_METADATA]!,
            });
        });
    }

    assetFromRepoMetadata({
        session,
        repoMetadata,
        updaters,
        permissions,
        appMetadata,
        projectMetadata,
        studentAssignmentMetadata,
        perUserMetadata,
        generationHistoryMetadata
    }: {
        session: IUpdateSession<AdobeAsset>,
        repoMetadata: RepositoryMetadata,
        updaters: UpdaterMap,
        permissions?: Permission,
        appMetadata?: IAppMetadata,
        projectMetadata?: IProject,
        studentAssignmentMetadata?: Partial<IRemoteStudentAssignment>,
        perUserMetadata?: IPerUserMetadata,
        generationHistoryMetadata?: Partial<GenerationHistoryAssetData>
    }): AdobeAsset {
        let asset: AdobeAsset | undefined;
        if (appMetadata && Object.keys(appMetadata).length > 0) {
            // We should have a better way to do this
            repoMetadata._embedded = { ...repoMetadata._embedded, [RelType.APP_METADATA]: appMetadata };
        }
        const assetMetadata: Partial<AdobeAssetUpdaterMetadata> =  repoMetadata || {};
        if (permissions && Object.keys(permissions).length > 0) {
            assetMetadata.effectivePermission = permissions;
        }
        if (perUserMetadata) {
            assetMetadata.perUserMetadata = perUserMetadata;
        }

        const assetUpdater = updaters.get('asset')!;
        if (appMetadataIsProject(appMetadata) || assetMetadata['repo:assetType'] === 'project') {
            const projectUpdater = updaters.get('project')!;
            const typedProjectMetadata = repoToProjectData(assetMetadata, projectMetadata);
            asset = projectUpdater.updateRemoteItem(session as IUpdateSession<Project>, typedProjectMetadata);
            // Since ProjectUpdater doesn't handle all repo metadata fields, use AdobeAssetUpdater
            // For example we need the links coming in from the repoMetadata to be used in AdobeAsset
            assetUpdater.updateLocalItem(session, asset, assetMetadata);
            // Apply Project-specific metadata and overrides
            // An example of this is the createdBy field which is different for Projects
            projectUpdater.updateLocalItem(session as IUpdateSession<Project>, asset as Project, typedProjectMetadata);
        } else if (repoMetadataIsLibrary(assetMetadata)) {
            const libraryUpdater = updaters.get('library')!;
            const libraryData = repoToLibraryData(assetMetadata) as LibraryData;
            asset = libraryUpdater.updateRemoteItem(session as IUpdateSession<Library>, libraryData);
            // Update repo metadata fields that are not handled by LibraryUpdater with the AdobeAssetUpdater
            assetUpdater.updateLocalItem(session, asset, assetMetadata);
            assetUpdater.updateRemoteItem(session, assetMetadata);
        } else if (repoMetadataIsBoard(assetMetadata)) {
            const boardUpdater = updaters.get('board')!;
            const boardData = repoToBoardData(assetMetadata);
            asset = boardUpdater.updateRemoteItem(session as IUpdateSession<Board>, boardData as RemoteBoard);
            // Update repo metadata fields that are not handled by BoardUpdater with the AdobeAssetUpdater
            assetUpdater.updateLocalItem(session, asset, assetMetadata);
        } else if (appMetadata && metadataIsStudentAssignmentFile({ repoMetadata, appMetadata })) {
            const studentAssignmentFileUpdater = updaters.get('student-assignment-file')!;
            const studentAssignmentFileData = repoToStudentAssignmentFileData(assetMetadata, appMetadata || {});
            const ancestors = repoMetadata['repo:ancestors'];
            // Last ancestor is the student assignment id. This is susceptible to breaking if the nesting of EDU assets change
            const studentAssignmentId = appMetadata['cc:inherited']?.['cc:studentAssignment']?.['repo:assetId'] || ancestors[ancestors.length - 1];
            (studentAssignmentFileData as IRemoteStudentAssignmentFileMetadataWithComputedValues).computedStudentAssignmentId = studentAssignmentId!;
            asset = studentAssignmentFileUpdater.updateRemoteItem(
                session as IUpdateSession<StudentAssignmentFile>,
                studentAssignmentFileData as IRemoteStudentAssignmentFile
            );
            assetUpdater.updateLocalItem(session, asset, assetMetadata);
        } else if (metadataIsStudentAssignment({ repoMetadata, appMetadata }) && studentAssignmentMetadata) {
            const studentAssignmentUpdater = updaters.get('student-assignment')!;
            const studentAssignmentData = repoToStudentAssignmentData(assetMetadata, { ...appMetadata || {}, ...studentAssignmentMetadata }) as IRemoteStudentAssignment;
            asset = studentAssignmentUpdater.updateRemoteItem(session as IUpdateSession<StudentAssignment>, studentAssignmentData);
            assetUpdater.updateLocalItem(session, asset, assetMetadata);
        } else if (metadataIsAssignment({ repoMetadata, appMetadata })) {
            const assignmentUpdater = updaters.get('assignment')!;
            const assignmentData = repoToAssignmentData(assetMetadata, appMetadata || {}) as IRemoteAssignment;
            asset = assignmentUpdater.updateRemoteItem(session as IUpdateSession<Assignment>, assignmentData);
            // Update repo metadata fields that are not handled by AssignmentUpdater with the AdobeAssetUpdater
            assetUpdater.updateLocalItem(session, asset, assetMetadata);
        } else if (repoMetadataIsGenerationHistoryAsset(assetMetadata) && generationHistoryMetadata) {
            const generationHistoryUpdater = updaters.get('generation-history')!;
            asset = assetUpdater.updateRemoteItem(session, assetMetadata);
            generationHistoryUpdater.updateLocalItem(session, asset, generationHistoryMetadata as GenerationHistoryAssetData);
        } else {
            // Otherwise, this is a normal AdobeAsset.
            const assetId = assetMetadata['repo:assetId'];
            const repoPath = assetMetadata['repo:path'];
            // Find the asset by ID, if possible, otherwise see if a local (ACPL) asset exists by repoPath,
            // since local assets may not yet have a cloudID when they're syncing for the first time.
            asset = (assetId ? session.getItemById(assetId) : undefined)
                || (repoPath ? this._findLocalAssetByRepoPath(session, assetId, repoPath) : undefined);
            if (asset) {
                assetUpdater.updateLocalItem(session, asset, assetMetadata);
            } else {
                asset = assetUpdater.updateRemoteItem(session, assetMetadata);
            }
            // If we have fetched the asset through non-local means (e.g. an ONS refresh or a directory load),
            // we'll already have the ancestor IDs, which indicates we've fleshed out repoMetadata from a real source.
            // Otherwise, we need to mark the asset as needing repoMetadata, since ACPL only provides a subset.
            if (!asset.ancestorIDs) {
                asset._setNeedsRepoMetadata(true);
            }
        }
        return asset;
    }

    /**
     * Find an ACPL-populated asset by repoPath, if it exists.
     */
    private _findLocalAssetByRepoPath(session: IUpdateSession<AdobeAsset>, assetId: string | undefined, repoPath: string): AdobeAsset | undefined {
        const asset = session.findItem(item => Boolean(item.localID) && item.repoPath === repoPath);
        if (assetId && asset && asset.id !== assetId) {
            // If we found an asset by repoPath and localID, but the cloudID doesn't match,
            // we now have enough information to reindex the item by the real ID.
            session.reindexItem(asset, asset.id, assetId);
        }
        return asset;
    }

    assetsFromLocalMetadata(session: IUpdateSession<AdobeAsset>, localMetadata: LocalAssetMetadata[], updaters: UpdaterMap): AdobeAsset[] {
        return this.assetsFromRepoMetadata(session, localMetadata as RepositoryMetadata[], updaters);
    }

    assetFromLocalMetadata(session:  IUpdateSession<AdobeAsset>, localMetadata: LocalAssetMetadata, updaters: UpdaterMap): AdobeAsset {
        return this.assetFromRepoMetadata({ session, repoMetadata: localMetadata as RepositoryMetadata, updaters });
    }
}
