import type { IComparatorMap } from '../core/ItemOrder';
import { compareValues, createItemOrderFactory } from '../core/ItemOrder';
import type Comment from './Comment';

export type CommentOrderField =
    | 'created';

const OrderFieldToComparator: IComparatorMap<Comment, CommentOrderField> = {
    created(a: Comment, b: Comment): number {
        return compareValues(a.created.getTime(), b.created.getTime());
    },
};

export default class CommentOrder extends createItemOrderFactory(OrderFieldToComparator) {
    static default = new CommentOrder('ascending', 'created');
}
