import type { IImplicitFilter } from '../core/ItemFilter';
import type { default as AdobeAsset } from './AdobeAsset';
import ImplicitAdobeAssetFilterBase from './ImplicitAdobeAssetFilterBase';

export default class MRUAdobeAssetFilter extends ImplicitAdobeAssetFilterBase implements IImplicitFilter<AdobeAsset> {
    constructor() {
        super({ _isSharedWithYou: true });
    }

    matches(item: AdobeAsset): boolean {
        // We don't want folders to match the Recents filter
        if (item.isFolder) {
            return false;
        }

        // do we need to allow certain items up to a threshold in the MRU list
        // as we do in the recents list by keeping record of lastModified
        if (item.lastAccessed === undefined) {
            return false;
        }

        return super.matches(item);
    }

}
