import type { ModelData } from './data/ModelData';
import type { HasModelBindings } from './utils/HasModelBindings';
import { isPlaceholder } from './utils';
import ItemBase from '../../core/ItemBase';
import type ISAMCorePrivate from '../../core/ISAMCorePrivate';
import type LibraryContext from '../../libraries/LibraryContext';
import type { ICCLibraries } from '../CCLibraries';
import type { RepresentationData } from './data/RepresentationData';
import type Representation from './Representation';

/**
 * Model
 * @packageDocumentation
 * @module Model
 * @internal
 *
 * Contains placeholder logic for Elements, Groups, and Representations, including when updating.
 * Model extends ItemBase, but given that there are some Model subclasses that don't use the ItemUpdater pattern,
 * because they exist in simple Arrays rather than the item pool, such as Representation,
 * the update logic has been moved down to the subclasses, other than the placeholder logic.
 */

/**
 * REFACTOR TODOs:
 * - When supporting CRUD Operations on Elements: replace commented out calls to this._modelCache with calls to this._itemPool<model>
 *
 * WHAT WORKS:
 * - getters
 *
 * WHAT DOES NOT YET WORK:
 * - updates/commits
 */

// TODO-R[SHARED-4609]: Handle this when refactoring change notifications. It propagates change events on children to the parent.
// We need to find out whether SAM has the same pattern.
// export function initializesCaches<D extends ModelData, B extends { new(...args: any[]): Model<D> }>(base: B): B {
//     return class extends base {
//         constructor(...args: any[]) {
//             super(...args);

//             for (const { cache } of Object.values(this._childModelCaches)) {
//                 cache.on('change', () => this.emit('change'));
//                 cache.on('modelChange', () => this.emit('change'));
//             }

