export default class Model<D extends ModelData> extends ItemBase implements HasModelBindings {

    private _commitFuture: Promise<void>;
    protected _commitResolver?: () => void;
    private _isCommitted = false;
    private _waitingForCommit = false;
    protected _libraryContext: LibraryContext;

    /**
     * @package -- for use in SAM.js only
     * Public because HasModelBindings has this as public
     */
    public _apiRoot: ICCLibraries;
    /**
     * @package -- for use in SAM.js only
     * Public because HasModelBindings has this as public
     */
    public _driver: ICCLibraries['driver'];

    /*
    * Subclasses must overwrite the below properties for _updateImplementation, _parent, and optionally _children, _ChildClass, and _childrenData
    * Note: There may be a better way to enforce this but this is more or less a pre-existing pattern.
    * TODO-R[SHARED-4623]: Make Model an Abstract class with composable mixin behaviors such as placeholderId management,
    * separate from ItemBase subclasses, but keep APIs consistent with HasModelBindings.
    */
    /**
     * @package -- only for use in SAM.js
     */
    protected _updateImplementation!: (data: Partial<D>) => void;
    /**
     * @package -- only for use in SAM.js
     */
    protected _parent!: HasModelBindings; // LibraryContents/Element/Representation/Group, etc.
    /**
     * @package -- only for use in SAM.js
     * This should always return the same Array instance and the same Representation instances,
     * to ensure MobX does not think there was a change when there wasn't.
     */
    protected _children: Representation[] = [];
    /**
     * @package -- only for use in SAM.js
     * It is OK for this to return a new Array instance as this is only used internally for data manipulation.
     */
    get _childrenData(): RepresentationData[] { return this._children.map(child => child._data); }
    /**
     * @package -- only for use in SAM.js
     */
    // Avoid circular dependency between Representation and Model by passing it in as the ChildClass
    protected _ChildClass!: new (
        core: ISAMCorePrivate,
        parent: HasModelBindings,
        data: RepresentationData
    ) => Representation;

    constructor(
        readonly core: ISAMCorePrivate,
        id: string, // same as _data.id
    ) {
        super(core, id);
        // Synchronously get the LibraryContext and ICCLibraries from the core,
        // as the async `core.getLibraryContext()` should already have been called.
        this._libraryContext = core._getLibraryContext() as LibraryContext;
        this._apiRoot = this._libraryContext._getLibrariesModule_NoLoad() as ICCLibraries;
        this._driver = this._apiRoot.driver;

        // If the model is a placeholder without a real ID, we need to wait for it to be committed.
        this._commitFuture = new Promise<void>((resolve, reject) => {
            this._commitResolver = () => {
                this._isCommitted = true;
                resolve();
            };
            if (!isPlaceholder(id as string)) {
                this._commitResolver();
            }
            // After 'remove' all event listeners are cleared, so we don't need to clean up here.
            this.on('remove', () => {
                if (this._waitingForCommit && !this._isCommitted) {
                    // If we're removing the model, make sure we reject any promises
                    // that are waiting for it to be committed, so that callers don't hang indefinitely.
                    reject();
                }
            });
        });
    }

    /**
     * Update the model with new data. (Models only have local data.)
     * @param data
     * @returns
     *
     * @package -- only for use in SAM.js
     */
    // TODO-R[SHARED-4149]: This no longer returns data since that property is gone. We need to check that this won't break anything during CRUD operations.
    _update(data: Partial<D>): void {
        const committed = isPlaceholder(this.id) && data.id && this.id !== data.id;
        this._updateImplementation(data); // Could use ItemUpdater pattern (e.g. element/group) or not (e.g. Representation)
        if (committed && this._commitResolver) { this._commitResolver(); }
    }

    /**
     * @package -- only for use in SAM.js
     */
    // Update children aka Representations, which do not use the ItemUpdater pattern as they exist as an array on the Element.
    _updateChildren(data: RepresentationData[]): void {
        if (!this._children) { return; } // Only Element and Representations have children defined.

        // Find representation that matches data.id/previousPlaceholderId and update *before* doing any removals
        const upsertItems = () => {
            data.forEach(childData => {
                let model = this._children.find(child => child.id === childData.id || child.id === childData.previousPlaceholderId);
                if (model) {
                    // TODO-R[SHARED-5159]: Diff old/new data with deep object equality to check if an update is needed.
                    // Old data can be accessed through model._data since children are always Representations
                    model._update(childData);
                    model.emit('change');
                } else {
                    model = new this._ChildClass(this._core, this, childData);
                    this._children.push(model);
                }
            });
        };
        const removeItems = () => {
            // 1. Get a set of IDs from new data
            const currentDataIds = new Set(data.map(data => data.id));
            // 2. Find the models that are not included in the updated set
            const oldData = this._childrenData;
            const removedItems = oldData.filter(data => !currentDataIds.has(data.id));
            // 3. Remove those models from the pool
            removedItems.forEach(data => {
                const model = this._children.find(child => child.id === data.id);
                if (model) {
                    // Emit a remove event so that the model can clean itself up.
                    model.emit('remove');
                    model.removeAllListeners();
                }
            });
        };
        upsertItems();
        removeItems();
    }

    // When resolved, we know this element is no longer a placeholder.
    // TODO-R: Might be clearer to name this waitForCommit().
    get committed() {
        this._waitingForCommit = true;
        return this._commitFuture;
    }

    // TODO-R: It might be clearer to switch this around and name it `isPlaceholder`, and the util can become isPlaceholderId
    get isCommitted() {
        return this._isCommitted;
    }

}
