import type { Action } from '../../models/Action';
import type { ElementData } from '../../models/data/ElementData';

import type { ExecuteResult } from '../Operation';
import Operation, { validatesOperation } from '../Operation';
import { extractElementId } from '../../utils/PathUtils';
import { mapElementDataToRequest, mapResponseToElementData } from './utils/restAPIModelMappers';
import type LocalDriver from '.';
import { removeRepresentationPlaceholderIds } from '../utils/operationUtils';
import { deepCopy } from '../../utils/StoreUtils';
import type { RepresentationData } from '../../models/data/RepresentationData';

/**
 * Element content is always replaced entirely, so if we're doing a bunch of representation changes, it makes
 * sense to batch them together.
 *
 * Also, since this operation isn't supported by the batch API, we want to cut down on requests.
 */
export default class ContentOperation extends Operation<LocalDriver> {
    supportsAction(action: Action) {
        return action.name === 'updateElementContent';
    }

    addAction(action: Action) {
        // Content operations must operate on the same element
        if (this._actions[0] && this._actions[0].path !== action.path) {
            return false;
        }

        return super.addAction(action);
    }

    @validatesOperation
    async execute(): Promise<ExecuteResult> {
        // The last content update action will always be the most up-to-date. We can omit all of the ones before it.
        const lastAction = this._actions[this._actions.length - 1];

        const response = await this._updateElementContent(
            extractElementId(lastAction.path as string) as string,
            lastAction.data
        );
        const json = await response.json();
        const data = mapResponseToElementData(json);

        const actions = this._actions.map((action, index): Action => {
            if (index !== this._actions.length - 1) {
                return { ...action, type: 'no-op', originalAction: action };
            } else {
                return { ...action, data, originalAction: action };
            }
        });

        return { actions, etag: response.headers.get('ETag') as string };
    }

    private _updateElementContent(elementId: string, data: Partial<ElementData>) {
        // The REST API requires that all new representations not have an ID. If the ID isn't found, then the API
        // returns an error.
        const cleanedData = {
            ...data,
            representations: removeRepresentationPlaceholderIds(deepCopy(data.representations as RepresentationData[]))
        };

        return this._driver.fetch(`/libraries/${this._library.id}/elements/${elementId}`, {
            method: 'PUT',
            headers: {
                'If-Match': this._library.etag
            },
            body: JSON.stringify(mapElementDataToRequest(cleanedData))
        });
    }
}
