import path from 'path-browserify';
import type AdobeAsset from '../assets/AdobeAsset';
import { type LocalAssetMetadata } from '../assets/AdobeAsset';
import { getACPLModel } from '../core/patches/SAMCpp';
import type { ISAMCorePrivate, ISAMObject } from '../indexPrivate';

interface ILocalAssetChangeEvent {
    type: 'add' | 'delete' | 'update';
    localAsset: LocalAssetMetadata;
}

/**
 * ACPLModelInterface interface wraps window.acplModel, which is available on some desktop surfaces:
 * - CCD, via SAM.cpp
 * - UXP, via SAM.cpp (or polyfilled in webviews)
 */
export default class ACPLModelInterface implements ISAMObject {
    constructor(readonly _core: ISAMCorePrivate) {}

    acplModel = getACPLModel();

    /**
     * Get an AdobeAsset from a localID or cloudID, if ACPL contains information about that asset.
     * On web, or if ACPL is not available, returns undefined.
     */
    async getLocalAsset(assetId: string): Promise<AdobeAsset | undefined> {
        if (!this.acplModel) {
            return undefined;
        }

        const localAssets = await this.getLocalAssets();
        const localAsset = localAssets.find(asset => asset['repo:assetId'] === assetId || asset.localID === assetId);
        if (localAsset) {
            const session = this._core._getAssetPool().createUpdateSession();
            const updaters = await this._core._adobeAssetFactory.getRepoMetadataUpdaters([ localAsset ]);
            const asset = this._core._adobeAssetFactory.assetFromLocalMetadata(session, localAsset, updaters);
            session.commit();
            return asset;
        }
    }

    /**
     * ACPL may return local assets with a repoID of '~' if the asset is in the user's root folder.
     * This method expands the repository path to include the home folder's repoPath and repositoryID.
     * This is necessary to ensure that the asset can be correctly identified and merged with SAM.js models.
     */
    private _expandRepositoryPath(homeFolder: AdobeAsset, localAsset: LocalAssetMetadata) {
        if (localAsset['repo:repositoryId'] === '~' && localAsset['repo:path']) {
            localAsset['repo:repositoryId'] = homeFolder.repositoryID;
            localAsset['repo:path'] = path.join(homeFolder.repoPath, localAsset['repo:path']);
        }
        return localAsset;
    }

    // When updating local assets, particularly newly-created assets, we may receive change notifications
    // before we have a cloudID available (during the sync process). To make sure we match the local asset
    // with the ONS-updated cloud asset without duplicates, we use repoPath. Here's a typical scenario:
    //
    // 1. A new file is created. ACPL emits uploadStatus changes, but we don't have a cloudID yet.
    //    - UpdateSession stores the item with the alternateID ("repo:path").
    // 2. ONS sends updates for a new cloud asset with cloudID and repoPath.
    //    - It doesn't find an existing cloudID, so it finds the right item with repoPath as the alternateID.
    //    - UpdateSession reindexes the item, whose ID is now its cloudID.
    // 3. More sync events from ACPL, where we still might not have a cloudID, so we still search for repoPath.
    //    - Eventually, everyone has a reference to the cloudID, and we no longer need the path.
    subscribeToLocalAssetChanges() {
        this.acplModel?.on('localAssetChange', async (eventData: string) => {
            const { type, localAsset } = JSON.parse(eventData) as ILocalAssetChangeEvent;
            if (!localAsset) {
                return;
            }
            const homeFolder = await this._core.getAssetContext().then(context => context.getHomeFolder());
            this._expandRepositoryPath(homeFolder, localAsset);

            const pool = this._core._getAssetPool();
            const assetId = localAsset['repo:assetId'];
            const session = pool.createUpdateSession();
            if (type === 'delete') {
                // Find an existing asset by assetId, if available. However, local assets may not have a cloudID yet,
                // so we must take care to find a matching service-populated asset if one exists (by repoPath).
                const asset = (assetId ? session.getItemById(assetId) : undefined)
                    || session.findItem(item => item.repoPath === localAsset['repo:path']);
                if (asset) {
                    session.queueDiscardedItem(asset);
                }
            } else if (type === 'add' || type === 'update') {
                const existingAsset = (assetId ? session.getItemById(assetId) : undefined);
                if (existingAsset?.repoPath && existingAsset.repoPath !== localAsset['repo:path']) {
                    // Do not populate the repoPath from ACPL if we already have a cloud asset with that ID.
                    // The cloud asset's repoPath is authoritative.
                    this._core._environment.debug(
                        `Ignoring local path for ACPL asset ${localAsset['repo:path']} `
                        + `because existing cloud asset has another path: ${existingAsset}`);
                    delete localAsset['repo:path'];
                }
                const updaters = await this._core._adobeAssetFactory.getRepoMetadataUpdaters([ localAsset ]);
                this._core._adobeAssetFactory.assetFromLocalMetadata(session, localAsset, updaters);
            }
            session.commit();
        });
    }

    get supportsDownloadComposite(): boolean {
        return this.acplModel?.downloadComposite !== undefined;
    }

    get supportsUnpin(): boolean {
        return this.acplModel?.unpin !== undefined;
    }

    get supportsLocalAssets(): boolean {
        return this.acplModel?.getLocalAssets !== undefined;
    }

    async downloadComposite(cloudID: string): Promise<void> {
        return this.acplModel?.downloadComposite?.(cloudID);
    }

    async unpin(cloudID: string): Promise<void> {
        return this.acplModel?.unpin?.(cloudID);
    }

    /**
     * Return a list of local assets populated from ACPL.
     * On web, or if ACPL is not available, returns an empty array.
     *
     * This method also ensures that assets have a
     * repositoryPath that can be merged with SAM.js models.
     */
    async getLocalAssets(): Promise<LocalAssetMetadata[]> {
        if (!this.acplModel) {
            return [];
        }
        const [ homeFolder, rawAssets = [] ] = await Promise.all([
            this._core.getAssetContext().then(context => context.getHomeFolder()),
            this.acplModel?.getLocalAssets?.()
        ]);
        return rawAssets.map(asset => this._expandRepositoryPath(homeFolder, asset));
    }
}
