import InterfaceBase from './InterfaceBase';
import type {
    ICommentDeleteCommentData,
    ICommentReclassifyCommentData,
    ICommentGetCommentData,
    ICommentEditCommentData,
    ICommentEditCommentStatusData,
    CommentCore,
    CommentData,
    ICommentMetadata
} from './CommentModel';
import type { HeaderMap } from './LinkUtils';
import type { ISAMCorePrivate } from '../indexPrivate';

export default class CommentInterface extends InterfaceBase {

    constructor(
        readonly _core: ISAMCorePrivate,
        readonly _assetId: string
    ) {
        super(_core);
    }

    private _getUrl(endpoint: string): string {
        // TODO: Should we be using a rel links ?
        //  const url = getURLFromLinks(links, RelType.ASSIGNMENTS_START, { assignmentId });

        return `https://${this._core._environment.endpoints.COMMENT_HOST}${endpoint}`;
    }
    private _getCommonHeaders(etag?: string): HeaderMap {
        const headers: HeaderMap = {
            'Content-Type': 'application/ld+json; profile="https://www.w3.org/ns/anno.jsonld"',
            'Accept': 'application/ld+json; profile="https://www.w3.org/ns/anno.jsonld"',
            'Prefer': 'return=representation;include="https://www.w3.org/ns/oa#PreferContainedDescriptions"',
            'x-ccx-workflow': 'true',
            'Directive': 'commenting-2024'
        };

        etag && (headers['If-Match'] = etag);

        return headers;
    }

    /**
     * @description Get a list of the comments associated with an asset
     * from the Red Hawk Commenting Service.
     * @param etag The etag from the previous request, if available
     * @returns The server Response object
     *
     * A typical interface method would return a strongly typed
     * response.json() ( in this case, an IAnnotationCollection ).
     *
     * But we expect the caller to poll this endpoint, so we also
     * want to return response.headers.get('etag'), so it can be
     * used as a parameter in the next use of this endpoint,
     * which allows the server to provide a 206 response ( nothing changed ).
     *
     * So this returns the Response object, which lets the caller
     * obtain both values.
     */
    async getCommentList(etag?: string): Promise<Response> {
        const url = this._getUrl(`/assets/${this._assetId}/annots/?status=open%2Cpending%2Cresolved%2Creview%2Cerror`);
        const headers = this._getCommonHeaders();

        etag && (headers['If-None-Match'] = etag);

        return this._doGet(url,
            {
                headers,
                successResponseCodes: [ 200, 208 ]
            }
        );
    }

    /**
     * @description Get a comment from the Red Hawk Commenting Service.
     * @param data The information necessary for calling the create API.
     * @returns A promise that resolves to the server's response,
     * a CommentCore corresponding to the comment requested for by id.
     */
    async getComment(data: ICommentGetCommentData): Promise<CommentCore> {
        const { annotationId, etag } = data;

        const url = this._getUrl(`/assets/${this._assetId}/annots/${annotationId}?recursive=true`);
        return this._getResponse(url,
            {
                headers: this._getCommonHeaders(etag)
            }
        );
    }

    /**
     * @description Creates a comment by POST-ing to the Red Hawk Commenting Service.
     * @param data The information necessary for calling the create API.
     * @returns A promise that resolves to the server's response.
     * a CommentCore corresponding to the comment created.
     */
    async createComment(data: CommentData): Promise<CommentCore> {
        // RE: https://git.corp.adobe.com/redhawk/native_client_sdk/blob/fddd524698ec5ad2cb4df23748c845a3c2129243/EurekaClientSDK/api/WebAnnotationsApi.cpp#L469
        // NOTE : CPP supports ANONBEARER, but for a first draft, we'll
        // only support BEARER, which we get for free from InterfaceBase
        // NOTE : We don't need to include User-Agent either
        // NOTE : Investigate whether we can get the URL from links

        // Get notification payload from AUP SDK if available
        let notificationPayload = {};
        const getAssetUtilitiesContext = this._core._environment._hooks.getAssetUtilitiesContext;

        if (getAssetUtilitiesContext) {
            try {
                const assetUtilitiesContext = await getAssetUtilitiesContext();

                notificationPayload = await assetUtilitiesContext.getCommentingNotificationPayload(
                    this._assetId
                );
            } catch (error) {
                this._core._environment.error(`Failed to get commenting notification payload: ${error}`);
            }
        }

        const url = this._getUrl(`/assets/${this._assetId}/annots`);

        // Combine the comment data with notification payload
        const requestBody = {
            ...data,
            ...notificationPayload
        };

        const response = await this._doPost(url,
            this._getCommonHeaders(),
            JSON.stringify(requestBody)
        );

        return response.json();
    }

    /**
     * @description Edit a comment from the Red Hawk Commenting Service.
     * @param data The information necessary for calling the API.
     * @returns A promise that resolves to the server's response,
     * a CommentCore corresponding to the updated comment.
     */
    async editComment(data: ICommentEditCommentData): Promise<CommentCore> {
        const { annotationId, etag, body } = data;

        // Get notification payload from AUP SDK if available
        let notificationPayload = {};
        const getAssetUtilitiesContext = this._core._environment._hooks.getAssetUtilitiesContext;

        if (getAssetUtilitiesContext) {
            try {
                const assetUtilitiesContext = await getAssetUtilitiesContext();

                notificationPayload = await assetUtilitiesContext.getCommentingNotificationPayload(
                    this._assetId,
                    { commentId: annotationId }
                );
            } catch (error) {
                this._core._environment.error(`Failed to get commenting notification payload: ${error}`);
            }
        }

        const url = this._getUrl(`/assets/${this._assetId}/annots/${annotationId}`);

        // Combine the body with notification payload
        const requestBody = {
            ...body,
            ...notificationPayload
        };

        const response = await this._doPut(url,
            this._getCommonHeaders(etag),
            JSON.stringify(requestBody),
            [ 200 ]
        );

        // response should be a new annotation.

        return response.json();
    }

    /**
     * @description Edit the status of a comment using PATCH to the Red Hawk Commenting Service.
     * @param data The information necessary for calling the API.
     * @returns A promise that resolves to the updated comment.
     */
    async editCommentStatus(data: ICommentEditCommentStatusData): Promise<CommentCore> {
        const { annotationId, etag, status } = data;

        const url = this._getUrl(`/assets/${this._assetId}/annots/${annotationId}`);

        // JSON Patch format (RFC 6902)
        const patchBody = [
            { 'op': 'replace', 'path': '/status', 'value': status }
        ];

        const headers = {
            ...this._getCommonHeaders(etag),
            'Content-Type': 'application/json-patch+json'
        };

        const response = await this._doPatch(url,
            headers,
            JSON.stringify(patchBody),
            [ 200 ]
        );

        // response should be the updated annotation.

        return response.json();
    }

    /**
     * @description Delete a comment from the Red Hawk Commenting Service.
     * @param data The information necessary for calling the delete API.
     * @returns A promise that resolves to void.
     */
    async deleteComment(data: ICommentDeleteCommentData): Promise<void> {
        const { annotationId, etag } = data;

        const url = this._getUrl(`/assets/${this._assetId}/annots/${annotationId}?recursive=true`);
        await this._doDelete(url,
            this._getCommonHeaders(etag),
            [ 204 ]
        );

        return;
    }

    /**
     * @description Reclassify a comment through ACMP. This is used
     * to correct an error when a previous classification attempt failed.
     * @param data The information necessary for calling the API.
     * @returns A promise that resolves to the server's response
     */
    async reclassifyComment(data: ICommentReclassifyCommentData): Promise<CommentCore> {
        const { annotationId, etag } = data;
        const url = this._getUrl(`/assets/${this._assetId}/annots/${annotationId}/reclassify`);
        const response = await this._doPost(url,
            this._getCommonHeaders(etag),
            JSON.stringify({}),
            [ 200 ]
        );

        return response.json();
    }

    /**
     * @description Get the collection of ICommentMetadata for an asset
     * with the Red Hawk Commenting Service.
     * @returns A promise that resolves to the server's response.
     */
    async getMetadata(): Promise<ICommentMetadata[]> {
        const url = this._getUrl(`/assets/${this._assetId}?operation=fetch_user_comment_metadata`);
        return this._getResponse(url,
            {
                headers: this._getCommonHeaders()
            }
        );
    }

    /**
     * @description Set the metadata for a comment with the Red Hawk Commenting Service.
     * @param data The information necessary for calling the API.
     * @returns A promise that resolves to the server's response.
     */
    async updateMetadata(data: Partial<ICommentMetadata>): Promise<ICommentMetadata> {
        const { annotId, read } = data;
        const annotationId = annotId || '';

        const url = this._getUrl(`/assets/${this._assetId}/annots/${annotationId}/metadata?recursive=false`);
        const response = await this._doPut(url,
            {
                'Content-Type': 'application/vnd.adobe.dc+json;profile="https://comments.adobe.io/schemas/annots_metadata.jsonld"',
                'Accept': 'application/vnd.adobe.dc+json;profile="https://comments.adobe.io/schemas/annots_metadata.jsonld"',
                'x-ccx-workflow': 'true'
            },
            JSON.stringify({
                annotId: `/assets/${this._assetId}/annots/${annotationId}`,
                read: read || false
            }),
            [ 200 ]
        );

        return response.json();
    }
}
