import type { Link, RapiLinkType } from './rapiModelMappers';

/**
 * Parses links returned from RAPI in response headers.
 *
 * @param linksList Comma-separated list of link relations.
 * @returns Record of links where the keys are the relation and the value is the link.
 *
 * @example
 * ```
 * const rapiResponse = await fetch('https://platform.adobe.io/some/path');
 * const links = parseLinks(rapiResponse.headers.get('link'));
 * const componentLink = links['http://ns.adobe.com/adobecloud/rel/component'];
 * ```
 */
export function parseLinks(linksList: string) {
    const links: Partial<Record<RapiLinkType, Link>> = {};

    do {
        const firstLinkIndex = linksList.indexOf('<');
        if (firstLinkIndex === -1) {
            break;
        }

        let secondLinkIndex = linksList.indexOf('<', firstLinkIndex + 1);
        if (secondLinkIndex === -1) {
            secondLinkIndex = linksList.length;
        }

        const linkString = linksList.substring(firstLinkIndex, secondLinkIndex);
        const link = parseLink(linkString);
        if (link) {
            links[link.rel as RapiLinkType] = link;
        }

        linksList = linksList.substring(secondLinkIndex);
    } while (linksList.length > 0);

    return links;
}

function parseLink(linkString: string): Link | undefined {
    // A link string will be in the format:
    // <https://subdomain.adobe.io/path>; rel="http://ns.adobe.com/adobecloud/rel/relation"; key="value"
    // Get the href from the link string (the part surrounded with angle brackets).
    const hrefMatch = linkString.match(/^<(.*)>;/);
    if (!hrefMatch) {
        return undefined;
    }
    const link: Record<string, any> = { href: hrefMatch[1] };

    // Get each key-value pair from the link string.
    const matches = linkString.matchAll(/\s([\w:]*)="([^"]*)"[;,]?/g);
    for (const match of matches) {
        const key = match[1];
        const value = match[2];
        link[key] = convertToPrimitiveType(value);
    }
    return link as Link;
}

function convertToPrimitiveType(str: string): string | number | boolean {
    if (str === 'true' || str === 'false') {
        return str === 'true';
    }

    const strAsNumber = +str;
    const isNumber = !isNaN(strAsNumber);
    if (isNumber) {
        return strAsNumber;
    }

    return str;
}
