import {
    getMultiValueFilterRelation,
    type IExplicitFilter,
    type ItemFilterRelation
} from '../core/ItemFilter';
import type StudentAssignment from './StudentAssignment';
import type { StudentAssignmentStatus, StudentAssignmentOptionalParams } from '../interface/StudentAssignmentModel';
import { ALL_STATUSES } from '../interface/StudentAssignmentModel';

export default class StudentAssignmentFilter implements IExplicitFilter<StudentAssignment> {
    public loadDocuments: boolean;
    public status: StudentAssignmentStatus[];
    private currentUserId?: string;

    constructor(options: StudentAssignmentOptionalParams = {}) {
        const { currentUserId, loadDocuments, status } = options;
        this.loadDocuments = loadDocuments === undefined ? true : loadDocuments;
        this.status = status && status.length > 0 ? status : ALL_STATUSES;
        this.currentUserId = currentUserId;
    }

    matches(item: StudentAssignment): boolean {
        // If we have items in the pool that extends beyond Self, then we filter to get only the assignments that currently logged in user submitted.
        // NOT_STARTED assignments would not attach a student so it would not be the users assignment.
        if (this.currentUserId && item.student.id !== this.currentUserId) {
            return false;
        }

        if (!this.status.includes(item.status)) {
            return false;
        }

        return true;
    }

    getRelationToFilter(other: StudentAssignmentFilter): ItemFilterRelation {
        const statusRelation = getMultiValueFilterRelation(this.status, other.status);
        // --- Handle all the 'disjoint' cases first ---

        if (statusRelation === 'disjoint') {
            return 'disjoint';
        }
        // NOTE: There are no disjoint cases for loadDocuments yet.

        // --- Handle all 'unknown' cases next ---
        // This has some statuses that are not included with other, but we've ruled out disjoint, so there
        // could be more matches on the server
        if (statusRelation === 'unknown') {
            return 'unknown';
        }
        // If this wants documents and other does not, then the other might have assignments, but it'll
        // still need to fetch documents.
        if (this.loadDocuments && !other.loadDocuments) {
            return 'unknown';
        }
        // This wants all owners, other only has current user
        if (!this.currentUserId && other.currentUserId) {
            return 'unknown';
        }

        // --- All 'disjoint' and 'unknown' cases are handled above, so it can only be 'subset'  ---
        return 'subset';
    }

    get hash(): string {
        return `status=${this.status.join()}&loadDocuments=${this.loadDocuments}${this.currentUserId ? `&currentUserId=${this.currentUserId}` : ''}`;
    }
}

