import type AppMetadataResource from '../assets/AppMetadataResource';
import type EffectivePermissionsResource from '../assets/EffectivePermissionsResource';
import type PerUserMetadataResource from '../assets/PerUserMetadataResource';
import type RepoMetadataResource from '../assets/RepoMetadataResource';
import { RelType } from '../interface/LinkUtils';
import type { RepositoryMetadata } from '../interface/RepositoryModel';
import Resource from '../assets/Resource';
import type { ISAMCorePrivate } from '../indexPrivate';
import type AdobeAsset from '../assets/AdobeAsset';
import type { Asset, Maybe } from './generated/types';
import { convertQueryBuilderAssetToAdobeAssetData } from './convertGQLDataToSAMModel';
import SAMError, { SAMErrorCode } from '../core/SAMError';
import type { QueryBuilderListAsset } from './models/AssetSubgraphModel';

export interface IAssetResources {
    repoMetadataResource?: RepoMetadataResource;
    appMetadataResource?: AppMetadataResource;
    effectivePermissionsResource?: EffectivePermissionsResource;
    perUserMetadataResource?: PerUserMetadataResource;
}

/**
 * A resource that can store and represent a single GraphQL result,
 * where the result may have Asset metadata within the query.
 * Methods on this Resource allow consumers to extract an AdobeAsset
 * from the result, with the appropriate data piped into the asset.
 */
export default class GraphQLAssetResource<TQuery> extends Resource {
    resultHandlers: Array<(result: TQuery) => void> = [];

    constructor(
        readonly _core: ISAMCorePrivate,
    ) {
        super(_core, {
            onChange: async (result) => {
                if (!result) {
                    return;
                }
                for (const onResult of this.resultHandlers) {
                    onResult(result);
                }
            },
        });
    }

    /**
     * Adds a result handler callback that will be invoked when query results are available.
     * If data is already present, the handler will be called immediately with the current data.
     *
     * @param onResult - Callback function that receives the query result data
     */
    addResultHandler(onResult: (result: TQuery) => void) {
        this.resultHandlers.push(onResult);
        if (this.data) {
            onResult(this.data);
        }
    }

    /**
     * Adds an asset from a GraphQL query result by applying a transformation function.
     *
     * @param assetFromResult - A function that extracts asset information from the GraphQL query result
     * @param asset - Optional existing AdobeAsset to update with the extracted data
     * @returns A Promise that resolves to an AdobeAsset with the applied data
     * @throws {SAMError} When the asset extraction fails or when applying data to the asset fails
     */
    addAssetFromResult(assetFromResult: (result: TQuery) => Maybe<Asset> | undefined, asset?: AdobeAsset): Promise<AdobeAsset> {
        return new Promise((resolve, reject) => {
            this.addResultHandler((result: TQuery) => {
                const maybeAssetInfo = assetFromResult(result);
                if (maybeAssetInfo) {
                    this._applyDataToAsset(maybeAssetInfo, asset)
                        .then(resolve)
                        .catch(error => {
                            reject(SAMError.create(SAMErrorCode.UNKNOWN, 'Error applying asset', error));
                        });
                } else {
                    reject(SAMError.create(SAMErrorCode.NOT_FOUND, 'Asset not found on GraphQL query'));
                }
            });
        });
    }

    /**
     * Adds asset resources from a GraphQL query result by applying a transformation function
     * and updating the provided subresources (such as repoMetadata, appMetadata, etc).
     *
     * @param assetFromResult - A function that extracts an Asset from the query result
     * @param subresources - The asset resources object to be updated with data from the extracted asset
     *
     * @throws {SAMError} With code UNKNOWN if there's an error applying asset resources or if no asset is found in the query result
     */
    addAssetResourcesFromResult(assetFromResult: (result: TQuery) => Maybe<Asset> | undefined, subresources: IAssetResources): Promise<void> {
        return new Promise((resolve, reject) => {
            this.addResultHandler(async (result: TQuery) => {
                const maybeAssetInfo = assetFromResult(result);
                if (maybeAssetInfo) {
                    try {
                        resolve(await this._applyDataToAssetResources(maybeAssetInfo, subresources));
                    } catch (error) {
                        reject(SAMError.create(SAMErrorCode.UNKNOWN, 'Error applying asset resources'));
                    }
                } else {
                    reject(SAMError.create(SAMErrorCode.NOT_FOUND, 'Asset not found on GraphQL query'));
                }
            });
        });
    }

    private async _applyDataToAssetResources(data: Asset, subresources: IAssetResources): Promise<void> {
        const {
            effectivePermission,
            perUserMetadata,
            _embedded,
            ...adobeAssetData
        } = convertQueryBuilderAssetToAdobeAssetData(data as QueryBuilderListAsset) ?? {};
        const appMetadata = _embedded?.[RelType.APP_METADATA] ?? {};
        const timestamp = this.timestamp;
        await Promise.all([
            subresources?.repoMetadataResource?._setData(adobeAssetData as RepositoryMetadata, { timestamp }),
            subresources?.effectivePermissionsResource?._setData(effectivePermission!, { timestamp }),
            subresources?.appMetadataResource?._setData(appMetadata, { timestamp }),
            subresources?.perUserMetadataResource?._setData(perUserMetadata!, { timestamp }),
        ]);
    }

    private async _applyDataToAsset(data: Asset, asset?: AdobeAsset): Promise<AdobeAsset> {
        const {
            effectivePermission,
            perUserMetadata,
            _embedded,
            ...adobeAssetData
        } = convertQueryBuilderAssetToAdobeAssetData(data as QueryBuilderListAsset) ?? {};
        const appMetadata = _embedded?.[RelType.APP_METADATA] ?? {};

        if (asset) {
            asset._handleResourceUpdates({
                timestamp: this.timestamp,
                effectivePermission,
                perUserMetadata,
                repoMetadata: adobeAssetData as RepositoryMetadata,
                appMetadata
            });
            return asset;
        } else {
            const pool = this._core._getAssetPool();
            const session = pool.createMutationSession(this.timestamp);
            const updaters = await this._core._adobeAssetFactory.getRepoMetadataUpdaters([ adobeAssetData ]);
            const asset = this._core._adobeAssetFactory.assetFromRepoMetadata({
                session,
                updaters,
                repoMetadata: adobeAssetData as RepositoryMetadata,
                permissions: effectivePermission,
                appMetadata,
                perUserMetadata,
            });
            session.commit();
            return asset;
        }
    }
}
