import { type TypePolicies } from '@apollo/client';

const typePolicies: TypePolicies = {
    Labels: {
        merge: true
    },
    Asset: {
        // This ensures that all subtypes of Asset (CompositeImpl, ProjectImpl, etc)
        // are stored in the Apollo Cache under a key that can be constructed without
        // knowing the concrete implementation type. This allows us to evict an Asset
        // by ID without knowing which kind of asset it actually is.
        keyFields: (obj) => `Asset:${obj.repo_assetId}`,
        fields: {
            // Because appMetadata is loaded with @defer, the default merge behavior for appMetadata
            // would consider it "missing" when the initial Asset query returns without it.
            // When Apollo thinks a field is missing, it tries to get it from the network again,
            // which can lead to unnecessary network requests and potential infinite loops.
            // This read function with (existing = null) ensures that if appMetadata is not present,
            // it will return null instead of undefined, preventing Apollo from thinking it's missing,
            // and allowing the deferred field to be merged in later without issues.
            appMetadata: {
                read(existing = null) {
                    return existing;
                }
            }
        }
    },
    ApplicationMetadata: {
        // ApplicationMetadata is fetched in two ways: either as a grab-bag
        // of properties on `valueOf({"key":""})` like "project:rendition",
        // or as actual GraphQL fields like "project_rendition".
        // By merging ApplicationMetadata here, we allow the cache to retain
        // data for both query types, ensuring we don't lose cache data depending
        // on the type of query being made.
        // For individual fields like "project_rendition", we merge them into the cache.
        // If a field is removed, the service will return the field as null.
        // For the grab-bag query, we do not merge, since the entire object is returned
        // each time, and we want to replace the previous data.
        merge: true,
        fields: {
            'valueOf({"key":""})': {
                merge: false
            }
        },
    },
    Repository: {
        keyFields: [ 'repo_repositoryId' ],
    },
    Link: {
        // Use keyFields=false to force Links to always be stored in their parent object.
        keyFields: false,
    },
    AssetList: {
        keyFields: [ 'assetListId' ]
    }
};
export default typePolicies;
