type AnyFunction = (this: any, ...args: any) => any;

/**
 * Creates a throttled version of the given function that only calls the original function
 * after the specified delay has passed, even if the throttled function is called multiple times.
 *
 * @example
 *   const throttled = throttle(() => console.log('Hello'), 1000);
 *   throttled();
 *   throttled(); // prints 'Hello' after 1 second, only once
 */
export default function throttle<T extends AnyFunction>(fn: T, delay: number): T {
    let timeout: ReturnType<typeof setTimeout> | null = null;
    return function (this: ThisParameterType<T>, ...args: Parameters<T>) {
        const self: ThisParameterType<T> = this;
        if (!timeout) {
            timeout = setTimeout(() => {
                fn.apply(self, args);
                timeout = null;
            }, delay);
        }
    } as T;
}
