const shownWarnings: Set<string> = new Set();

/**
 * A utility logging function that warns a client once per page load using
 * the params provided by the caller.
 * @param topic
 * @param message
 */
export default function oneTimeWarning(topic: string, message: string) {
    if (shownWarnings.has(topic)) { return; }
    console.warn('One time warning (%s): %s', topic, message);
    shownWarnings.add(topic);
}

export function missingImplementationWarning(topic: string) {
    oneTimeWarning(topic, 'Not implemented yet, but this method is safe to call.');
}
