import type { IImplicitFilter  } from '../core/ItemFilter';
import type { default as AdobeAsset } from './AdobeAsset';
import type { IImplicitAdobeAssetFilterBaseOptions } from './ImplicitAdobeAssetFilterBase';
import ImplicitAdobeAssetFilterBase from './ImplicitAdobeAssetFilterBase';

export interface IImplicitDirectoryListingFilterOptions extends IImplicitAdobeAssetFilterBaseOptions {
    readonly asset: AdobeAsset;
}

export default class ImplicitDirectoryListingFilter extends ImplicitAdobeAssetFilterBase implements IImplicitFilter<AdobeAsset> {
    private _asset: AdobeAsset;

    constructor(options: IImplicitDirectoryListingFilterOptions) {
        const { asset, ...superOptions } = options;
        super(superOptions);
        this._asset = asset;
    }

    get asset(): AdobeAsset {
        return this._asset;
    }

    matches(item: AdobeAsset): boolean {
        // Only check repositoryID if defined
        // TODO: this was to fix a USS bug that doesn't exist anymore, should it always verify repositoryID?
        if (this._asset.repositoryID && item.repositoryID
            && this._asset.repositoryID !== item.repositoryID) {
            return false;
        }

        // check item is a direct child of current asset
        const assetRepoPath = this._asset.repoPath;
        if (assetRepoPath && (assetRepoPath !== item.repoPath.substring(0, item.repoPath.lastIndexOf('/')))) {
            return false;
        }

        return super.matches(item);
    }
}
