const isNonEmptyString = (x: any) => (typeof x === 'string') && Boolean(x);
const isNumber = (x: any) => (typeof x === 'number');
type ConfigItemValidator = {
    key: keyof InternalConfiguration;
    validator: (x: any) => boolean;
}

const configItemValidators: Array<ConfigItemValidator> = [ {
    key: 'CLIENT_ID',
    validator: isNonEmptyString
}, {
    key: 'USER_ID',
    validator: isNonEmptyString
}, {
    key: 'ENVIRONMENT',
    validator: (x: any) => isNumber(x) && (x in Env)
}, {
    key: 'HOST_PRODUCT_DATA',
    validator(hostProductData?: HostProductData) {
        if (!hostProductData) {
            return false;
        }
        const { PRODUCT_ID } = hostProductData;
        // required for USS queries
        return isNonEmptyString(PRODUCT_ID);
    }
} ];

export type Hooks = {
    /**
     * Complete override of SAM's fetch implementation.
     * When provided, SAM will bypass all its authentication, retry logic, and other features.
     * Use this when you need completely different authentication schemes (e.g., Frame.io).
     * For most use cases, prefer baseFetch instead.
     */
    fetch?: typeof fetch,
    /**
     * The base fetch implementation that SAM builds upon.
     * SAM will add authentication headers, retry logic, and other features on top of this.
     * This is the recommended way to provide a custom fetch implementation.
     */
    baseFetch?: typeof fetch,
    refreshAccessToken?: (failedToken: string) => Promise<string>
    persistentCache?: IPersistentCache
    /**
     * Get the asset utilities context from the AUP SDK when available.
     * This provides access to asset utilities like commenting notification payloads.
     */
    getAssetUtilitiesContext?: () => Promise<any>
}

export type ConfigurationPayload = {
    configurationKeyName: keyof Configuration;
};

// Only allow one retry on a 401 response to avoid getting into an infinite loop if we keep being given an invalid access token
const MAX_401_RETRIES = 1;

export type IFetchOptions = Omit<RequestInit, 'headers'> & {
    headers?: HeaderMap;
    authHeader?: string;
    noOtherHeaders?: boolean;
    requestTimeoutMs?: number;
    noApiKeyHeader?: boolean;
    /**
     * Explicitly control whether to exclude Authorization header for this request.
     * - true: Omit auth header
     * - false/undefined: Use SESSION_TYPE to determine (default behavior)
     */
    excludeAuth?: boolean;
}

export default class Environment implements ISAMObject {
    private _config: InternalConfiguration;
    private _cache: Cache;
    /**
     * @package -- for use in SAM.js only
     */
    public _isTokenInvalid = true;
    readonly mobx = new MobX;

    /**
     * @package -- for use in SAM.js only
     */
    _responseCache: ResponseCache | undefined;


    constructor(
        readonly _core: ISAMCorePrivate,
        userConfig: Configuration,
        readonly _hooks: Hooks
    ) {
        const featureFlagsConfig = Object.assign({}, DEFAULT_CONFIG.FEATURE_FLAGS, userConfig.FEATURE_FLAGS);
        const config: InternalConfiguration = Object.assign({}, DEFAULT_CONFIG, userConfig);
        config.FEATURE_FLAGS = featureFlagsConfig;
        const invalidOptions = configItemValidators.filter(({ key, validator }) => !validator(config[key]));

        if (invalidOptions.length) {
            const invalidKeys = invalidOptions.map(({ key }) => key).join(', ');
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, `Invalid required options: ${invalidKeys}`);
        }

        if (config.ACCESS_TOKEN) {
            this._isTokenInvalid = false;
        } else if (!_hooks.refreshAccessToken) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, `refreshAccessToken hook must be provided if ACCESS_TOKEN is not set`);
        }

        this._config = config;
        this._cache = new Cache(config.USER_ID, _core, _hooks.persistentCache);

        if (this.getValue('FEATURE_FLAGS')['enable-response-cache']) {
            this._responseCache = new ResponseCache(this._core);
        }
    }

    get cache(): Cache {
        return this._cache;
    }

    getValue<K extends keyof InternalConfiguration>(key: K): InternalConfiguration[K] {
        return this._config[key];
    }

    /**
     * Set the _environment global configuration value.
     *
     * @param key Configuration KeyName
     * @param value The value of the Configuration.
     * @event IEvent Dispatches an event when a particular key has changed.
     */
    setValue<K extends keyof InternalConfiguration>(key: K, value: InternalConfiguration[K]) {
        this._config[key] = value;
        const event: IEvent = {
            type: CONFIG_CHANGE
        };
        const eventPayload: ConfigurationPayload = {
            configurationKeyName: key
        };
        this._core.dispatch(event, eventPayload);
    }

    get endpoints(): EnvironmentConfig {
        const env: Env = this._config.ENVIRONMENT;
        return ENVIRONMENTS[env];
    }

    // Returns a unique device id for the client - this can be provided as a config option, or a guid can
    // be generated (which will be cached across instances for the same user). Note that if a value is passed in,
    // this takes precedence even if there's a cached device id.
    @memoize
    async getDeviceId(): Promise<string> {
        return this._config['DEVICE_ID'] || await this.cache.getItem('DEVICE_ID', async () => uuid(), (value: any) => typeof value === 'string');
    }

    getUserId(): string {
        return this.getValue('USER_ID');
    }


    /**
     * Utility method to ease transition of duplicate feature flags due to deprecation of `enable-x-bucket-move` flag.
     * Will return whether cross-bucket move is enabled, preferring new `enable-ops-2021-move` flag value.
     * @package -- for use in SAM.js only
     */
    _getCrossBucketMoveEnabled(): boolean | undefined {
        // If present, prefer `enable-ops-2021-move` feature flag value.
        // As a fallback for older clients, support the deprecated `enable-x-bucket-move` feature flag
        // that was superseded by `enable-ops-2021-move`.
        const featureFlags = this.getValue('FEATURE_FLAGS');
        return featureFlags['enable-ops-2021-move'] ?? featureFlags['enable-x-bucket-move'];
    }

    /**
     * The maximum number of retries for any network operation.
     * @internal
     */
    get _maxNumberOfRetries(): number {
        return MAX_401_RETRIES;
    }

    /*
    * This is a convenience method returning a log sink for clients using the SAM.js logger.
    */
    @memoize
    get logSink(): Pick<Console, 'debug' | 'info' | 'warn' | 'error'> {
        return {
            error: this.error.bind(this),
            warn: this.warn.bind(this),
            info: this.log.bind(this),
            debug: this.debug.bind(this)
        };
    }

    private _loggerEvent(message: string, level: LogLevel) {
        if (this._core.listenerCount(MESSAGE_LOGGED) > 0) {
            this._core.emit(MESSAGE_LOGGED, new MessageLoggedEvent(message, level));
        }
    }

    // Reserve for informational messages that may be useful in debugging infrequent but major
    // SAM.js system events, such as initializing, or refreshing auth token.
    log(message: string) {
        this._loggerEvent(message, LogLevel.Info);
    }

    // Reserve for detailed messages about complex coordinated async processes, such as List loading, that
    // are difficult to trace without log messages, but are too noisy to include in regular production apps.
    debug(message: string) {
        this._loggerEvent(message, LogLevel.Debug);
    }

    // For error conditions that do not warrant throwing an exception that bubbles to the client, but could be
    // useful for debugging purposes. E.g., an ItemUpdater failing to parse a field from a service response --
    // devs should see and fix these errors immediately and have unit tests to validate it, but the same error
    // in a production system should not necessarily be raised to the user.
    error(message: string) {
        this._loggerEvent(message, LogLevel.Err);
    }

    // For deprecation notices and possibly (but not definitively) bad configuration options, etc. These sorts of
    // messages should include instructions on how to resolve the issue. E.g. how React treats warnings about missing
    // `key` on children -- this isn't necessarily a breaking condition but often can cause bugs; since they are
    // entirely avoidable, devs should work to eradicate the warnings so they do not become red herrings that must
    // be investigated when an unrelated bug emerges.
    warn(message: string) {
        this._loggerEvent(message, LogLevel.Warn);
    }

    /**
     * Checks if a URL should skip the telemetry wrapper (baseFetch).
     * Some hostnames don't support telemetry headers like x-request-id.
     * @internal
     */
    private _shouldSkipTelemetry(url: string): boolean {
        const hostnamesWithoutTelemetrySupport = [
            this.endpoints.PGC_HOST,
            this.endpoints.AXON_HOST
        ];
        const hostnamePatternsWithoutTelemetrySupport = [
            'acp-aep-cs-blobstore' // Blob store endpoints (varies by region/environment)
        ];
        return this._matchesSkipList(url, hostnamesWithoutTelemetrySupport, hostnamePatternsWithoutTelemetrySupport);
    }

    /**
     * Checks if a URL should skip the X-ACP-ADMIN-PRIVILEGES header.
     * Some hostnames don't support this header.
     * @internal
     */
    _shouldSkipAdminPrivileges(url: string): boolean {
        const hostnamesWithoutAdminPrivilegesSupport = [
            this.endpoints.PGC_HOST
        ];
        return this._matchesSkipList(url, hostnamesWithoutAdminPrivilegesSupport, []);
    }

    /**
     * Helper to check if a URL's hostname matches a skip list.
     * Used by _shouldSkipTelemetry and _shouldSkipAdminPrivileges to determine
     * whether certain headers should be omitted for a given request URL.
     *
     * @param url - The request URL to check
     * @param hostnames - Exact hostname matches (for known configured endpoints)
     * @param hostnamePatterns - Hostname patterns (for dynamic/regional endpoints) which are provided via links call
     * @returns True if the URL's hostname exactly matches a hostname or contains a pattern; false otherwise.
     * @internal
     */
    private _matchesSkipList(url: string, hostnames: string[], hostnamePatterns: string[]): boolean {
        try {
            const urlObj = new URL(url);
            return hostnames.some(host => urlObj.hostname === host)
                || hostnamePatterns.some(pattern => urlObj.hostname.includes(pattern));
        } catch {
            return false;
        }
    }

    /**
     * @internal
     */
    @synchronized
    async _refreshAccessToken() {
        if (this._config.SESSION_TYPE !== 'logged-out' && this._isTokenInvalid) {
            if (!this._hooks.refreshAccessToken) {
                // If a refresh hook wasn't provided, we just clear the token so we don't keep on
                // attempting requests with an invalid token
                return '';
            }
            this.log(`Refreshing old access token (... ${this._config.ACCESS_TOKEN?.slice(-10)}) from host.`);
            try {
                this._config.ACCESS_TOKEN = await this._hooks.refreshAccessToken(this._config.ACCESS_TOKEN);
            } catch (e) {
                // The error could already be a SAM error due to the recursive fetch calls above.
                throw SAMError.wrapErrorIfNeeded(SAMErrorCode.AUTHORIZATION_ERROR, 'Failed to refresh access token', e);
            }
            if (this._config.ACCESS_TOKEN) {
                this._isTokenInvalid = false;
            }
            this.log(`Refreshed to new access token (... ${this._config.ACCESS_TOKEN?.slice(-10)}) from host.`);
        }
        return this._config.ACCESS_TOKEN;
    }

    async fetch(url: string, options: IFetchOptions = {}, numRetries: number = 0): Promise<Response> {
        // If a custom fetch hook is provided, use it as a complete override (original behavior)
        if (this._hooks?.fetch) {
            return this._hooks.fetch(url, options as Parameters<typeof fetch>[1]);
        }

        const session = this._config.SESSION_TYPE;

        // If the access token is invalid, we wait for it to be refreshed:
        const token = this._isTokenInvalid ? await this._refreshAccessToken() : this._config.ACCESS_TOKEN;


        // Extract parameters that won't be passed to `fetch`, and clone the ones that will so that a) there are no
        // side-effects to the caller, and b) 401 retries can use the same `options` as the original request.
        const { headers = {}, authHeader, noOtherHeaders, requestTimeoutMs, noApiKeyHeader, excludeAuth, ...requestInit } = options;

        // Determine if we should include auth:
        // 1. If excludeAuth is true, don't include auth
        // 2. Otherwise, use SESSION_TYPE to determine (backward compatible)
        const shouldIncludeAuth = excludeAuth
            ? false
            : session !== 'logged-out';

        // Check if we're in a session that requires authentication
        // If so and we don't have a token after refresh, that's an error
        if (shouldIncludeAuth && !token) {
            throw SAMError.create(SAMErrorCode.AUTHORIZATION_ERROR, `Unable to obtain access token - did you provide a refreshAccessToken hook?`);
        }

        // ONS uses a different auth header from other services, so this needs to be configurable
        const authorizationHeader = 'Authorization';

        const auth = (shouldIncludeAuth && token)
            ? { [authHeader || authorizationHeader]: `${(session === 'guest') ? 'AnonBearer' : 'Bearer'} ${token}` }
            : { };

        // After this line, `requestHeaders` and `headers` should not be modified to avoid side-effects for the caller.
        // deepClone removes headers with undefined values -- this makes it easier to assemble Headers where some
        // headers could be optional.
        const requestHeaders = noOtherHeaders ? deepClone(headers) : {
            ...deepClone(headers),
            ...auth,
            ... (noApiKeyHeader) ? {} : { 'X-Api-Key': this._config.CLIENT_ID }
        };

        // Include a timeout on the request (fetch doesn't have a timeout, so it will never resolve if the socket hangs up)
        const abortController = new AbortController();
        let uncombineSignals = () => {};
        if (requestInit.signal) {
            uncombineSignals = combineSignals(requestInit, requestInit.signal, abortController.signal);
        } else {
            requestInit.signal = abortController.signal;
        }
        const timeoutLength = requestTimeoutMs || this.getValue('FETCH_REQUEST_TIMEOUT');
        const timeout = setTimeout(() => abortController.abort(), timeoutLength);

        const startTime = Date.now();

        try {
            // Use the custom baseFetch hook if provided, otherwise use the global fetch
            // Skip baseFetch (telemetry) if the URL is for a hostname that doesn't support it
            const skipTelemetry = this._shouldSkipTelemetry(url);
            const fetchFunction = (skipTelemetry || !this._hooks?.baseFetch) ? fetch : this._hooks.baseFetch;
            const response = await fetchFunction(url, { ...requestInit, headers: requestHeaders });
            const requestId = response.headers.get('X-Request-Id');
            const requestIdString = requestId || `no requestId`;
            this.debug(`[${requestIdString}] ${options.method || 'GET'} ${url} ${response.status} (${Date.now() - startTime}ms)`);

            clearTimeout(timeout);

            if (response.status === 401) {
                // If we get a 401 response it usually means that access token has expired.
                if (token !== this._config.ACCESS_TOKEN) {
                    // If the access token was already refreshed during the request, just retry and
                    // it will pick up the new token.
                    // NOTE: We are not using await here to avoid capturing the errors in the parent try block.
                    // NOTE: using `options` instead of `requestInit` so the retry will use the same settings as the original request.
                    return this.fetch(url, options, numRetries + 1);
                } else {
                    // Otherwise it means we discovered the current token is invalid. We need to invalidate the token and retry. The retry
                    // will detect that the token is invalid and refresh it (if the host has provided a hook).
                    this._isTokenInvalid = true;
                    if (numRetries < this._maxNumberOfRetries) {
                        // NOTE: We are not using await here to avoid capturing the errors in the parent try block.
                        // NOTE: using `options` instead of `requestInit` so the retry will use the same settings as the original request.
                        return this.fetch(url, options, numRetries + 1);
                    }
                }
            }

            return response;
        } catch (e) {
            this.debug(`Error - ${e} (${Date.now() - startTime}ms)`);

            // Check if the request was aborted due to timeout
            if (abortController.signal.aborted) {
                throw SAMError.wrapErrorIfNeeded(
                    SAMErrorCode.REQUEST_TIMED_OUT,
                    `Request timed out after ${timeoutLength}ms when fetching: ${url} method: ${options.method || 'GET'}`,
                    e
                );
            }

            throw SAMError.wrapErrorIfNeeded(SAMErrorCode.NETWORK_ERROR, `Failed network request when fetching: ${url}`, e);
        } finally {
            // If we combined signals, we need to uncombine after the request is done, otherwise we'll continue to add
            // event listeners to the original signal and hit the maximum limit. This would both be a memory leak and
            // result in some aborts not being handled.
            uncombineSignals();
        }
    }

    // Returns a retry time based on the retry attempt number.
    // For now, this uses the minimum retry interval a few times, before jumping to the maximum interval.
    // We may want to change this to an exponential or Fibonacci backoff in future.
    getRetryInterval(attempt: number): number {
        // We retry quickly a few times on failure, before backing off to a slower interval:
        return this.getValue(attempt < 3 ? 'MIN_RETRY_INTERVAL' : 'MAX_RETRY_INTERVAL');
    }
}
