import type { ISAMObject } from '../indexPrivate';
import ItemUpdater from '../core/ItemUpdater';
import PropertyUpdater from '../core/PropertyUpdater';

import type { IFrameioAccountResponse, IFrameioUserResponse } from './FrameioInterface';
import FrameioBase from './FrameioBase';
import type FrameioProject from './FrameioProject';
import { FrameioProjectUpdater } from './FrameioProject';
import type FrameioTeam from './FrameioTeam';
import { FrameioTeamUpdater } from './FrameioTeam';
import type FrameioUser from './FrameioUser';
import { FrameioUserUpdater } from './FrameioUser';

// See https://developer.frame.io/api/reference/operation/getAccount/
//  for schema of the data FrameioAccount encapsulates.
export default class FrameioAccount extends FrameioBase {
    private _teams: Array<FrameioTeam> | undefined;
    private _sharedProjects: Array<FrameioProject> | undefined;
    private _displayName: string = '';
    private _owner: FrameioUser | undefined;
    private _ownerId: string = '';
    private _version: number = 0;

    /**
     * @package - not yet decided if id's are internal use only.
     *  In the meantime, I'm decorating them to discourage their use.
     */
    get ownerId(): string {
        return this._ownerId;
    }

    get owner(): FrameioUser | undefined {
        return this._owner;
    }

    get displayName(): string {
        return this._displayName!;
    }

    get version(): number {
        return this._version;
    }

    // getTeams() should really be a getter for property teams,
    // but then we'd need an async getter, and I'm not sure
    // of the convention for that.
    // https://medium.com/trabe/async-getters-and-setters-is-it-possible-c18759b6f7e4

    // see getProjectTree() below
    async getTeams(): Promise<Array<FrameioTeam>> {
        let teams = this._teams;
        if (!teams) {
            const ctx = this.context;

            const teamsResponse = await ctx._frameioInterface.getTeams(this.id);
            const session = ctx._objectPool.createUpdateSession<FrameioTeam>();
            teams = FrameioTeamUpdater.updateRemoteItems(session, teamsResponse);
            session.commit();

            this._teams = teams;
        }

        return teams;
    }

    async getSharedProjects(): Promise<Array<FrameioProject>> {
        let shared = this._sharedProjects;
        if (!shared) {
            const ctx = this.context;

            const projectsResponse = await ctx._frameioInterface.getSharedProjects(this.id);
            const session = ctx._objectPool.createUpdateSession<FrameioProject>();
            shared = FrameioProjectUpdater.updateRemoteItems(session, projectsResponse);
            session.commit();

            this._sharedProjects = shared;
        }

        return shared;
    }

    async getSharedTeams(): Promise<Array<FrameioTeam>> {
        const projects = await this.getSharedProjects();
        const set = new Set<string>();
        const teams: Array<FrameioTeam> = [];

        // The array we return should not contain duplicates,
        // but a team could have more than one shared projects,
        // so use a set to unique the teams we add to the array.

        for (const project of projects) {
            const id = project.teamId;

            if (!set.has(id)) {
                const team = await project.getTeam();

                set.add(id);
                teams.push(team);
            }
        }

        return teams;
    }

    // same return as getTeams(), but we pre-load the projects of each team
    // before resolving the promise.
    async getProjectTree(): Promise<Array<FrameioTeam>> {
        const teams = await this.getTeams();
        const promises: Array<any> = [];

        teams.forEach((team: any) => {
            promises.push(team.getProjects());
        });

        await Promise.all(promises);
        return teams;
    }
}

export const FrameioAccountUpdater = new ItemUpdater<FrameioAccount, Partial<IFrameioAccountResponse>>({
    localItemType: FrameioAccount,
    remoteIdProperty: 'id',
    propertyUpdater: new PropertyUpdater({
        '_displayName': 'display_name',
        '_owner': {
            // The owner property of an IFrameioAccountResponse is a nested
            // object of type IFrameioUserResponse, so let's construct that
            // while we are here.
            set: (owner: IFrameioUserResponse, dest: ISAMObject) => {
                const account = dest as FrameioAccount;
                const context = account.context;
                const pool = context._objectPool;

                const session = pool.createUpdateSession<FrameioUser>();
                account['_owner'] = FrameioUserUpdater.updateRemoteItem(session, owner);
                session.commit();
            },
            name: 'owner',
            format: 'object'
        },
        '_ownerId': 'owner_id',
        '_version': { name: 'version', format: 'number' }
    })
});

