import type { IProjectsTeamsOrderBy } from '../interface/WorkspacesModel';

import type { IComparatorMap } from '../core/ItemOrder';
import { compareStrings, compareValues, createItemOrderFactory } from '../core/ItemOrder';
import type Team from './Team';

export type TeamOrderField =
    | 'name'
    | 'created';

export const OrderFieldToIProjectsTeamsOrderBy: { [key in TeamOrderField]: IProjectsTeamsOrderBy } = {
    'name': 'name',
    'created': 'createDate',
};

const OrderFieldToComparator: IComparatorMap<Team, TeamOrderField> = {
    name(a: Team, b: Team): number {
        return compareStrings(a.name, b.name);
    },
    created(a: Team, b: Team): number {
        return compareValues(a.created, b.created);
    }
};

export default class TeamOrder extends createItemOrderFactory(OrderFieldToComparator) {
    static default = new TeamOrder('ascending', 'name');
}
