type GQLRepoCapabilityInput = { state?: string; error?: string; name?: string; type?: string };

type GQLRepoCapabilities = {
    file?: GQLRepoCapabilityInput | null;
    composite?: GQLRepoCapabilityInput | null;
    directory?: GQLRepoCapabilityInput | null;
};

function mapOneCapability(gql?: GQLRepoCapabilityInput | null): RepoCapabilityEntry | undefined {
    if (gql === null || gql === undefined) {
        return undefined;
    }
    const state = isRepoCapabilityState(gql.state) ? gql.state : undefined;
    // Normalize GraphQL null/empty string to undefined so we don't emit spurious entries (e.g. { error: "" }).
    const error = gql.error !== null && gql.error !== undefined && gql.error !== '' ? gql.error : undefined;
    // Omit entry when there is no usable state or error (preserves prior behavior: invalid state + no error → omit)
    if (state === undefined && error === undefined) {
        return undefined;
    }
    const name = gql.name?.trim() || undefined;
    const type = gql.type?.trim() || undefined;
    return { name, type, state, error };
}

function mapAncestorInfoToRAPI(gql?: GQLAncestorInfo[] | null): AncestorInfo | undefined {
    if (!gql || gql.length === 0) {
        return undefined;
    }

    const result: AncestorInfo = {};

    for (const ancestor of gql) {
        if (ancestor.assetId) {
            result[ancestor.assetId] = {
                'repo:assetType': ancestor.assetType ?? undefined,
                'repo:assetSubType': ancestor.assetSubType ?? undefined
            };
        }
    }

    return Object.keys(result).length > 0 ? result : undefined;
}

function mapGQLRepoCapabilitiesToRAPI(gql?: GQLRepoCapabilities | null): RepoCapabilitiesMetadata | undefined {
    if (!gql) {
        return undefined;
    }
    const file = mapOneCapability(gql.file);
    const composite = mapOneCapability(gql.composite);
    const directory = mapOneCapability(gql.directory);
    const out: RepoCapabilitiesMetadata = {
        ...(file !== undefined && { file }),
        ...(composite !== undefined && { composite }),
        ...(directory !== undefined && { directory })
    };
    return Object.keys(out).length ? out : undefined;
}

export function parseGQLEffectivePermissions(permissions: EffectivePermission, projectPermissions?: AssetPermissions): Permission {
    const toLowerCase = (resource: Privilege[] | undefined) => resource?.map(p => p.toLowerCase() as PermissionType);

    const rapiPermissions: IEffectivePermissions = {};
    rapiPermissions['*'] = toLowerCase(permissions.default || undefined);
    rapiPermissions[RelType.PRIMARY] = toLowerCase(permissions.primary || undefined);
    rapiPermissions[RelType.AC_POLICY] = toLowerCase(permissions.aclPolicy || undefined);
    rapiPermissions[RelType.DIRECTORY] = toLowerCase(permissions.directory || undefined);
    rapiPermissions[RelType.APP_METADATA] = toLowerCase(permissions.applicationMetadata || undefined);
    rapiPermissions[RelType.ANNOTATIONS] = toLowerCase(permissions.annotations || undefined);
    // projectPermissions are only present in GraphQL responses for projects, not general assets.
    // When projectPermissions exist, we should use project-specific parsing instead of general asset parsing.
    if (projectPermissions) {
        return parseProjectEffectivePermissions(rapiPermissions, projectPermissions);
    }
    return parseEffectivePermissions(rapiPermissions);
}

/**
 * Removes undefined properties from an object recursively
 */
function filterUndefinedProperties<T extends Record<string, any>>(obj: T): Partial<T> {
    const result: Partial<T> = {};

    for (const [ key, value ] of Object.entries(obj)) {
        if (value !== undefined) {
            if (value && typeof value === 'object' && !Array.isArray(value)) {
                const filtered = filterUndefinedProperties(value);
                if (Object.keys(filtered).length > 0) {
                    result[key as keyof T] = filtered as T[keyof T];
                }
            } else {
                result[key as keyof T] = value;
            }
        }
    }

    return result;
}

export function convertQueryBuilderAssetToAdobeAssetData(data: QueryBuilderListAsset): AdobeAssetUpdaterMetadata {
    const listAsset: ListAsset = {
        // TODO: the response from graphQL does not match generated types. Switch resolve to use gql instead of
        // query builder so that Asset from resolve will look the same as Asset from PLS queries?
        ...(data as ListAsset),
        appMetadata: (data.appMetadata as any)?.am
    };
    return convertGQLAssetToAdobeAssetData(listAsset);
}

/**
 * Converts GraphQL query response  to Adobe asset data format.
 * In the future, we will add additional transformations to this data.
 * We might use codegen to generate types from the schema.
 */
export default function convertGQLAssetToAdobeAssetData(data: ListAsset): AdobeAssetUpdaterMetadata {
    if (!data) {
        throw SAMError.create(SAMErrorCode.UNKNOWN, 'Asset data missing from GraphQL response');
    }
    const repoRepresentations = Object.fromEntries(
        Object.entries(data.repo_representations ?? {}).filter(([ , value ]) => value === true)
    );
    const effectivePermissions = data.effectivePermissions ? parseGQLEffectivePermissions(data.effectivePermissions) : undefined;

    const assetData: AdobeAssetUpdaterMetadata = {
        'dc:format': data.dc_format,
        'repo:ancestors': data.repo_ancestors,
        'repo:ancestorInfo': mapAncestorInfoToRAPI(data.repo_ancestorInfo ?? undefined),
        'repo:assetClass': data.repo_assetClass.toLowerCase() as AssetClass,
        'repo:assetType': data.repo_assetType as AssetType,
        'repo:assetSubType': data.repo_assetSubType as AssetSubType,
        'repo:pinnedVersion': data.repo_pinnedVersion ?? undefined,
        'repo:pinnedVersionModifyDate': data.repo_pinnedVersionModifyDate ?? undefined,
        // repo:capabilities: Currently populated from GQL only; RAPI support not in scope for this change.
        'repo:capabilities': mapGQLRepoCapabilitiesToRAPI((data as { repo_capabilities?: GQLRepoCapabilities }).repo_capabilities),
        'repo:representations': repoRepresentations,
        'repo:assetId': data.repo_assetId,
        'repo:etag': data.primary_etag ?? undefined,
        'repo:createDate': data.repo_createDate,
        'repo:createdBy': data.repo_createdBy?.id,
        'repo:modifyDate': data.repo_modifyDate,
        'repo:name': data.repo_name,
        'repo:path': data.repo_path,
        'repo:modifiedBy': data.repo_modifiedBy,
        'repo:repositoryId': data.repository?.repo_repositoryId,
        'repo:state': data.repo_state,
        'repo:size': (data as Composite).repo_size,
        'repo:version': (data as Composite).repo_version ?? undefined,
        'storage:assignee': (data.storage_assignee as Assignee) || undefined,
        'storage:region': data.storage_region,
        'storage:deviceCreateDate': data.storage_deviceCreateDate,
        'storage:deviceModifyDate': data.storage_deviceModifyDate,
        'tiff:imageLength': (data as File).tiff_imageLength,
        'tiff:imageWidth': (data as File).tiff_imageWidth,
        generationModelDisplayName: getGenerationModelDisplayName(data.appMetadata?.firefly?.generationModel?.name || ''),
        effectivePermission: effectivePermissions,
        perUserMetadata: {
            'shell:lastAccessDate': data.labels?.['lastAccessDate'],
        },
        _embedded: {
            // TODO: cannot cast to IAppMetadata b/c GenerationHistoryAssetAppMetadata is
            // missing some `firefly` attributes that are in the generated types. Meanwhile,
            // SAM.js only uses IAppMetadata for validating internal uses of appMetadata,
            // so IAppMetadata is not intended to cover the entire schema for appMetadata.
            [RelType.APP_METADATA]: data.appMetadata || {} as any
        },
        _links: {
            [RelType.PRIMARY]: data.primaryLink as IServiceLink,
            [RelType.BLOCK_INITIALIZE]: data.blockUploadLink as IServiceLink,
            [RelType.DOWNLOAD]: (data as Composite).blockDownloadLink as IServiceLink,
            [RelType.RENDITION]: (data as Composite).renditionLink as IServiceLink,
            [RelType.COMPONENT]: (data as Composite).componentLink as IServiceLink,
            [RelType.PAGE]: (data as Directory).pageLink as IServiceLink,
        } as AssetLinks,
        isFavorite: data.labels?.favorite?.isFavorite,
        shareDate: data.sharingInfo?.sharedWithYou?.shareDate,
        sharedWithYouLabel: data.sharingInfo?.sharedWithYou,
        isSWYGroup: data.sharingInfo?.sharedWithYou?.shareTypes?.includes('GROUP')
    };

    return filterUndefinedProperties(assetData);
}

/**
 * Converts GraphQL Project query response to IProject data format.
 * Maps GraphQL Project fields to the expected IProject interface structure.
 */
export function convertGQLProjectToProjectData(data: Project): ProjectUpdaterMetadata {
    if (!data) {
        throw SAMError.create(SAMErrorCode.UNKNOWN, 'Project data missing from GraphQL response');
    }
    const projectPermissions = data.effectivePermissions ? parseGQLEffectivePermissions(data.effectivePermissions, data.permissions ?? undefined) : undefined;

    // Build project links from GraphQL data
    const projectLinks: IProjectLinks = {
        // PrimaryLink is used from the project index and individual project's
        // primary link is not used

        // ActionLinks - required by interface
        [RelType.CREATE]: data.createLink as IServiceLink,
        [RelType.RESTORE]: (data.restoreLink as IServiceLink) ?? undefined,
        [RelType.DISCARD]: (data.discardLink as IServiceLink) ?? undefined,

        // IProjectActions - required by interface
        [RelType.PROJECTS_RENAME]: data.renameLink as IServiceLink,

        // IProjectNavigationLinks
        [RelType.PAGE]: data.pageLink as IServiceLink,

        // Projects reference brands create and delete links are not present in the projects schema
        // SAM.js APIs have ensureLinks to make sure all the links are present
        // https://jira.corp.adobe.com/browse/SAMJS-1029
        // https://jira.corp.adobe.com/browse/SAMJS-1022

        // There is another link for move csc projects which is not present in the projects schema
        // At least we should have ensureLinks check in the moveCSCProject method
        // https://jira.corp.adobe.com/browse/SAMJS-1021
    } as IProjectLinks;

    const projectData: Partial<IProject> = {
        'repo:assetId': data.repo_assetId,
        'repo:repositoryId': data.repository?.repo_repositoryId || '',
        'repo:path': data.repo_path,
        'repo:createDate': data.repo_createDate,
        'repo:etag': data.primary_etag || '',
        'repo:name': data.repo_name,
        'repo:state': data.repo_state,
        // The below code provides type coercion to the expected format.
        // Also takes care of converting null to undefined which we probably is already taken care of.
        'storage:assignee': data.storage_assignee ? {
            id: data.storage_assignee.id,
            type: data.storage_assignee.type as 'user' | 'org'
        } : undefined,
        'project:directorySubtype': data.repo_assetSubType || undefined,
        _links: projectLinks,
        _embedded: {
            // Add embedded repository data if available
            ...(data.repository && data.repository.repo_owner && {
                [RelType.REPOSITORY]: {
                    'repo:repositoryId': data.repository.repo_repositoryId,
                    'repo:owner': {
                        id: data.repository.repo_owner.id || '',
                        type: (data.repository.repo_owner.type === 'org' ? 'org' : 'user') as 'user' | 'org',
                        displayName: data.repository.repo_owner.name?.displayName || ''
                    }
                }
            }),
            // Add creator data if available
            ...(data.repo_createdBy && {
                [RelType.PROJECTS_CREATOR]: {
                    id: data.repo_createdBy.id,
                    type: data.repo_createdBy.type as 'user' | 'org',
                    displayName: data.repo_createdBy.name?.displayName || '',
                    firstName: data.repo_createdBy.name?.firstName || undefined,
                    lastName: data.repo_createdBy.name?.lastName || undefined
                }
            }),
            // Add app metadata if available
            ...(data.appMetadata?.project_rendition?.gradientId && {
                [RelType.APP_METADATA]: {
                    'project:rendition': {
                        gradientId: data.appMetadata.project_rendition.gradientId
                    }
                }
            })
        }
    };

    // Add additional fields that are not part of IProject but used by ProjectUpdater
    const extendedData: ProjectUpdaterMetadata = {
        ...projectData,
        // Add modify date if available (used by ProjectUpdater)
        'repo:ancestors': data.repo_ancestors,
        'storage:region': data.storage_region,
        // Add labels data if available
        labels: data.labels ?? undefined,
        // Add sharing info if available
        sharedWithYouLabel: data.sharingInfo?.sharedWithYou,
        // Add parsed project permissions
        projectPermissions,
    };

    return filterUndefinedProperties(extendedData) as ProjectUpdaterMetadata;
}
