import type { IImplicitFilter } from '../core/ItemFilter';

import type { default as Library } from './Library';

import ImplicitAdobeAssetFilterBase from '../assets/ImplicitAdobeAssetFilterBase';
import { LibraryOwnerFilter, LibraryRolesFilter } from '../interface/LibraryModel';

import { itemMatchesOwnerFilter, itemMatchesRolesFilter } from './LibraryFilterUtils';
import type { LibraryFilterOptions } from './LibraryFilter';

type ImplicitLibraryFilterOptions = Pick<LibraryFilterOptions, 'owner' | 'roles'>;

/**
 * Internal filter that is for ensuring only libraries that are not hidden, discarded, etc. are shown in Library lists.
 * The Implicit Filter determines the nature of the LibrarySource.
 */
export default class ImplicitLibraryFilter extends ImplicitAdobeAssetFilterBase implements IImplicitFilter<Library> {
    static TrainingSets = new ImplicitLibraryFilter({
        owner: [ LibraryOwnerFilter.All ], roles: [ LibraryRolesFilter.TrainingSet ]
    });

    readonly _owner?: Set<LibraryOwnerFilter>;
    readonly _roles?: Set<LibraryRolesFilter>;

    constructor(readonly filterOptions?: ImplicitLibraryFilterOptions) {
        super({ _isSharedWithYou: true });

        if (filterOptions?.owner && filterOptions.owner.length > 0) {
            this._owner = new Set([ ...filterOptions.owner ]);
        }
        if (filterOptions?.roles && filterOptions.roles.length > 0) {
            this._roles = new Set([ ...filterOptions.roles ]);
        }
    }

    // used by ItemList and ItemLoaderState and is called when asset change notifications come in to check if the asset is still eligible to be on a particular list
    matches(item: Library): boolean {
        if (!item.isLibrary) {
            return false;
        }
        if (this._owner && !itemMatchesOwnerFilter(item, this._owner)) {
            return false;
        }
        if (this._roles && !itemMatchesRolesFilter(item, this._roles)) {
            return false;
        }
        return super.matches(item);
    }
}
