import type { SAM } from '@ccx-public/component-types';
import type { AssignmentAdobeAssetMetadata } from '../interface/AssignmentModel';
import type { Assignee, StudentAssignmentLinks, IRemoteAssignee, IRemoteStudentAssignment } from '../interface/StudentAssignmentModel';
import { StudentAssignmentStatus } from '../interface/StudentAssignmentModel';
import type { IRemoteStudentAssignmentFile, IStudentAssignmentFilesOptions } from '../interface/StudentAssignmentFileModel';
import type ISAMCorePrivate from '../core/ISAMCorePrivate';
import type { ISAMObject } from '../core/ISAMObject';
import type { AssetClass, AssetLinks, RepositoryMetadata } from '../interface/RepositoryModel';
import { observable } from '../core/decorators';
import AdobeAsset from '../assets/AdobeAsset';
import type StudentAssignmentFile from './StudentAssignmentFile';
import ItemUpdater from '../core/ItemUpdater';
import PropertyUpdater from '../core/PropertyUpdater';
import type { IPerUserMetadata } from '../interface/AssetModel';
import { Permission } from '../interface/AssetModel';
import type { StudentAssignmentFileSource } from './StudentAssignmentFileSource';
import StudentAssignmentAppMetadataResource from './StudentAssignmentAppMetadataResource';
import StudentAssignmentsInterface from '../interface/StudentAssignmentsInterface';
import ItemSource from '../core/ItemSource';
import type ItemPool from '../core/ItemPool';
import StudentAssignmentFilesListLoader from './StudentAssignmentFilesListLoader';
import StudentAssignmentFileFilter from './StudentAssignmentFileFilter';
import { RequestHeaders } from '../utils/classroomUtils';
import SAMError, { SAMErrorCode } from '../core/SAMError';

export type StudentAssignmentParams = {
    assignmentId: string;
    links: StudentAssignmentLinks;
    status: StudentAssignmentStatus;
    student: Assignee;
    studentDirectoryId?: string;
    submission?: AssignmentAdobeAssetMetadata;
    submissionDate?: Date;
}

export default class StudentAssignment extends AdobeAsset implements SAM.StudentAssignment {
    protected _assetClass: AssetClass = 'directory'; // this makes assignment a folder
    private _assignmentId: string = '';
    private _assignmentCode: string = '';
    private _parentClassroomId: string = '';
    private _inheritedClassroomId: string = '';
    // Have the associated SA Files been loaded into the pool?
    // Note: the odd "...Prop" naming is to avoid a conflict with the getter/setter
    private _hasLoadedChildrenProp: boolean = false;
    private _status: StudentAssignmentStatus = StudentAssignmentStatus.NOT_STARTED;
    private _student: Assignee = { id: '', displayName: '', email: '' };
    private _studentAssignmentsInterface = new StudentAssignmentsInterface(this._core);
    private _studentDirectoryId?: string;
    private _submission?: AssignmentAdobeAssetMetadata;
    private _submissionDate?: Date;
    private _studentAssignmentAppMetadata: StudentAssignmentAppMetadataResource;

    private _studentAssignmentFilesSource?: StudentAssignmentFileSource;
    // This field is intended to preserve child assets provided by the remote item that may not be available through the StudentAssignmentFileSource yet/that
    // a weak ref to the list does not exist yet until getList is called
    private _studentAssignmentFiles: StudentAssignmentFile[] = [];

    constructor(
        readonly _core: ISAMCorePrivate,
        id: string,
        metadata?: {
            links?: AssetLinks;
        }
    ) {
        super(_core, id, metadata);
        this._studentAssignmentAppMetadata = new StudentAssignmentAppMetadataResource(_core, this);

        // Overridden property.
        // True to start with. If we have the metadata, we will update this.
        // Keep in mind that the submission service does not include all Adobe
        // Asset metadata in its responses, hence why this is needed.
        this._needsRepoMetadata = true;
    }

    /**
     * A flag that indicates whether the StudentAssignment is virtual or not.
     * SAs are not actual assets until the status changes from NOT_STARTED,
     * at that time the SA folder asset is created.
     *
     * Overrides the AdobeAsset isVirtual.
     */
    @observable
    get isVirtual(): boolean {
        return this.status === StudentAssignmentStatus.NOT_STARTED;
    }

    @observable
    get appMetadata(): StudentAssignmentAppMetadataResource {
        return this._studentAssignmentAppMetadata;
    }

    /**
     * Were child assets fetched in parallel to this StudentAssignment.  This differentiates
     * when files were NOT fetched vs files were fetched but the files are not yet associated
     * with the StudentAssignment (i.e. the files are not present in this._studentAssignmentFiles)
     * @package Only for use in SAM.js.
     */
    get _hasLoadedChildren(): boolean {
        return this._hasLoadedChildrenProp;
    }

    /**
     * @package Only for use in SAM.js.
     */
    set _hasLoadedChildren(value: boolean) {
        this._hasLoadedChildrenProp = value;
    }

    /**
     * @package Only for use in SAM.js. Please use .files() instead.
     */
    get studentAssignmentFiles(): StudentAssignmentFile[] {
        return this._studentAssignmentFiles;
    }

    @observable
    get assignmentId(): string {
        return this._assignmentId;
    }

    @observable
    get assignmentCode(): string {
        return this._assignmentCode;
    }

    /**
     * Overrides the default implementation in AdobeAsset
     */
    @observable
    get parentClassroomId(): string {
        // We expect to always have classroom:context on hand
        // In the unexpected case that we don't, we can fall back to cc:inherited or the super call that will check appMetadata
        return this._parentClassroomId || this._inheritedClassroomId || super.parentClassroomId || '';
    }

    /**
     * Overrides the default implementation in AdobeAsset
     */
    @observable
    get parentAssignmentId(): string {
        return this.assignmentId;
    }

    @observable
    get status(): StudentAssignmentStatus {
        return this._status;
    }

    @observable
    get student(): Assignee {
        return this._student;
    }

    @observable
    get studentDirectoryId(): string | undefined {
        return this._studentDirectoryId;
    }

    @observable
    get submission(): AssignmentAdobeAssetMetadata | undefined {
        return this._submission;
    }

    @observable
    get submissionDate(): Date | undefined {
        return this._submissionDate;
    }

    get isStudentAssignment(): boolean | undefined {
        return true;
    }

    /**
     * Returns the files in the student's assignment directory. Optional parameter to specify the order of the files.
     * @throws {Error} if the student directory asset is not a folder
     * @deprecated Use `.files` instead. Will be removed in ACPCEDU-3305.
     */
    @observable
    async getFiles(options: IStudentAssignmentFilesOptions = {}): Promise<StudentAssignmentFile[]> {
        if (!this._studentDirectoryId) {
            return [];
        }

        return this._core.classroomContext.getStudentAssignmentFiles({
            studentDirectoryId: this.studentDirectoryId!, order: options.order
        });
    }

    /**
     * Returns undefined if the StudentAssignment is NOT_STARTED, otherwise
     * returns the StudentAssignmentsSource which contains a list of StudentAssignmentFile[].
     *
     * @example <caption>Get all StudentAssignmentFiles for this StudentAssignment</caption>
     * const safList = studentAssignment.files?.getList(StudentAssignmentFileOrder.default);
     * await waitForListLoad(safList);
     * const safs: StudentAssignmentFile[] = safList?.items || [];
     */
    get files(): StudentAssignmentFileSource | undefined {
        if (!this._studentDirectoryId) {
            // The StudentAssignment is NOT_STARTED so there are no files to fetch
            return undefined;
        }

        if (!this._studentAssignmentFilesSource) {
            this._studentAssignmentFilesSource = new ItemSource(
                this._core._getAssetPool() as ItemPool<StudentAssignmentFile>,
                [ new StudentAssignmentFilesListLoader({ core: this._core, studentAssignmentsInterface: this._studentAssignmentsInterface }) ],
                new StudentAssignmentFileFilter(this._studentDirectoryId)
            );
        }

        return this._studentAssignmentFilesSource;
    }

    /**
     * @deprecated This getter is deprecated and clients should use the links() function instead moving forward.
     * This method will be removed on or after 2025-7-1 in ACPCEDU-3393
     */
    @observable
    get studentAssignmentLinks(): StudentAssignmentLinks {
        return this.links;
    }

    @observable
    get links(): StudentAssignmentLinks {
        // Make a copy to avoid the client accidentally manipulating the links
        return Object.assign({}, this.__links as StudentAssignmentLinks);
    }

    /**
     * Other students will have read access to this directory if the class gallery is enabled.
     * To reduce visibility to in-progress work, we do not want to load new work files from ONS notifications.
     * @package -- internal use only
     */
    get _canLoadNewChildrenFromONSNotification(): boolean {
        return this.hasPermission(Permission.Write);
    }

    /**
     * Checks if this StudentAssignment is able to be started
     *
     * @example <caption>Check if the StudentAssignment can be started</caption>
     * if (studentAssignment.canStart()) {
     *  // Do something
     * }
     */
    canStart(): boolean {
        return this._status === StudentAssignmentStatus.NOT_STARTED;
    }

    /**
     * Checks if this StudentAssignment can be returned by the teachers
     *
     * @example <caption>Check if the StudentAssignment can be returned</caption>
     * if (studentAssignment.canReturn()) {
     *  // Do something
     * }
     */
    canReturn(): boolean {
        return this._status === StudentAssignmentStatus.SUBMITTED;
    }

    // this _load will be extended in https://jira.corp.adobe.com/browse/ACPCEDU-2125 to account for cases where we don't need to fetch Assignment just to get StudentAssignment
    // Until then, we can assume StudentAssignments are coming from GET assignments
    /**
   * @param repoMetadata {RepositoryMetadata} If passed in, it will be used instead of loading from the service
   * @param appMetadata {any} If passed in, it will be used instead of loading from the service
   *
   * @package -- only for use in SAM.js
   */
    async _load({
        repoMetadata,
        appMetadata,
        effectivePermission,
        perUserMetadata,
        doFetchStudentAssignmentMetadata = true,
    }: {
        repoMetadata?: RepositoryMetadata;
        appMetadata?: any;
        effectivePermission?: Permission;
        perUserMetadata?: IPerUserMetadata;
        doFetchStudentAssignmentMetadata?: boolean;
    } = {}): Promise<void> {
        // Similar to what Project already has, first load the AdobeAsset so that once we get the student assignment metadata we override any relevant
        // properties with the student assignment metadata
        await super._load({ repoMetadata, appMetadata, effectivePermission, perUserMetadata });

        if (doFetchStudentAssignmentMetadata) {
            const studentAssignmentMetadata = await this._studentAssignmentsInterface.getStudentAssignment(this.id, undefined, { [RequestHeaders.PREFER_RAPI]: 'true' });
            const session = this._core._getAssetPool().createMutationSession<StudentAssignment>();
            StudentAssignmentUpdater.updateRemoteItem(
                session,
                studentAssignmentMetadata
            );
            session.commit();
        }
    }

    /**
     * Marks this student assignment as returned.
     *
     * @example <caption>Return a StudentAssignment</caption>
     * await studentAssignment.return();
     */
    async return(): Promise<StudentAssignment> {
        return this._core.classroomContext._returnAssignment({
            links: this.links,
            studentAssignmentId: this.studentDirectoryId!,
            submissionId: this.submission?.['repo:assetId'] as string,
        });
    }

    /**
     * Marks this student assignment as started.
     *
     * @example <caption>Start a StudentAssignment</caption>
     * await studentAssignment.start();
     */
    async start(): Promise<StudentAssignment> {
        return this._core.classroomContext._startAssignment({
            assignmentId: this.assignmentId,
            links: this.links,
        });
    }

    /**
     * Marks this student assignment as submitted. Note that this should only be called by the student for
     * submitting their own assignment.
     * @param submissionId - The asset ID of the student's work to become the submission for this assignment.
     *
     * @example <caption>Submit a StudentAssignment</caption>
     * await studentAssignment.submit('submission-id');
     */
    async submit(submissionId: string): Promise<StudentAssignment> {
        await this._core.classroomContext.submitAssignment({
            assignmentId: this.assignmentId,
            links: this.links,
            status: this.status,
            studentAssignmentId: this.studentDirectoryId,
            submissionId,
        });
        return this;
    }

    /**
     * Returns true as the StudentAssignment is a child of Classroom
     * Overrides the default implementation in AdobeAsset
     */
    @observable
    get isChildOfClassroom(): boolean {
        return true;
    }

    /**
     * Returns true as the StudentAssignment is a child of Assignment
     * Overrides the default implementation in AdobeAsset
     */
    @observable
    get isChildOfAssignment(): boolean {
        return true;
    }

    /**
     * Returns false as the StudentAssignment is not a child of AssignmentMaterials
     * Overrides the default implementation in AdobeAsset
     */
    @observable
    get isChildOfAssignmentMaterials(): boolean {
        return false;
    }

    /**
     * Returns false as the StudentAssignment is not a child of StudentAssignment
     * Overrides the default implementation in AdobeAsset
     */
    @observable
    get isChildOfStudentAssignment(): boolean {
        return false;
    }
}

export function getAlternateStudentAssignmentId(remoteItem: Partial<IRemoteStudentAssignment>): string {
    // We expect to always have classroom:context on hand
    // In the unexpected case that we don't, we can fall back to cc:inherited or throw an error.
    let id;
    if (remoteItem['classroom:context'] !== undefined) {
        id = remoteItem['classroom:context']['classroom:assignmentContext']['classroom:assignmentAssetId'];
    } else if (remoteItem['cc:inherited'] !== undefined && remoteItem['cc:inherited']['cc:assignment'] !== undefined) {
        id = remoteItem['cc:inherited']['cc:assignment']['repo:assetId'];
    } else {
        throw SAMError.create(SAMErrorCode.INTERNAL_ERROR, `Remote item does not have classroom:context or cc:inherited defined`);
    }

    return `${remoteItem['assignment:assignee']?.id}-${id}`;
}

export const StudentAssignmentUpdater = new ItemUpdater<StudentAssignment, Partial<IRemoteStudentAssignment>>({
    remoteIdProperty: 'repo:assetId',
    getAlternateId: getAlternateStudentAssignmentId,
    localItemType: StudentAssignment,
    propertyUpdater: new PropertyUpdater({
        _assignmentId: { name: 'classroom:context[classroom:assignmentContext][classroom:assignmentAssetId]', format: 'string' },
        _assignmentCode: { name: 'computedAssignmentCode', format: 'string' },
        _parentClassroomId: { name: 'classroom:context[classroom:classroomContext][classroom:classroomAssetId]', format: 'string' },
        _inheritedClassroomId: { name: 'cc:inherited[cc:classroom][repo:assetId]', format: 'string' },
        _studentAssignmentFiles: {
            isArray: true,
            name: 'children',
            format: 'object',
            set: (remoteStudentAssignmentFiles: IRemoteStudentAssignmentFile[], dest: ISAMObject) => {
                const studentAssignment = dest as StudentAssignment;
                studentAssignment.studentAssignmentFiles.length = 0;
                const session = studentAssignment._core._getAssetPool().createMutationSession<StudentAssignmentFile>();
                const files = studentAssignment._core.classroomContext._updateStudentAssignmentFilesCache({ remoteStudentAssignmentFiles, session, assignmentId: studentAssignment.assignmentId, classroomId: studentAssignment.parentClassroomId, studentAssignmentId: studentAssignment.id });
                studentAssignment.studentAssignmentFiles.push(...files);
            }
        },
        __links: { name: '_links', format: 'object' },
        _status: { name: 'assignment:submissionStatus', format: 'string' },
        // if using 'object' in the format, the setter will be called  when the response omits displayName ( because undefined is different than the name it already has ).
        // This leads to the result of having the updater dispatches the change event whenever the setter is called.
        // Using 'object_subset' so the parse/isEqual's will only compare the members in the response with their corresponding values in the local object,
        // so it only calls the setter when something specified in the response differences from the existing value.
        _student: { name: 'assignment:assignee', format: 'object_subset', set: (remoteAssignee: IRemoteAssignee, dest: ISAMObject) => {
            const studentAssignment = dest as StudentAssignment;
            // Hume will not provide displayName or email in start/submit/return API responses.
            // If we only pass through the object from Hume, missing/undefined required fields of display name and email will override the existing non-empty ones.
            studentAssignment['_student'] = { ...studentAssignment['_student'], ...remoteAssignee };
        } },
        _studentDirectoryId: { name: 'repo:assetId', format: 'string' },
        _submission: { name: 'assignment:submission', format: 'object' },
        _submissionDate: { name: 'assignment:submissionDate', format: 'date' },
    }),
});
