import ItemUpdater from '../core/ItemUpdater';
import PropertyUpdater from '../core/PropertyUpdater';

import type { FrameioReviewLinksChangeEventParam, IFrameioReviewLinkResponse } from './FrameioInterface';
import type { FrameioSourceDocument } from './FrameioContext';
import type FrameioContext from './FrameioContext';
import FrameioBase from './FrameioBase';
import type FrameioAsset  from './FrameioAsset';
import type FrameioFile  from './FrameioFile';
import type FrameioFolder  from './FrameioFolder';
import FrameioVersionStack, { FrameioVersionStackUpdater } from './FrameioVersionStack';
import SAMError, { SAMErrorCode } from '../core/SAMError';

// See https://developer.frame.io/api/reference/operation/getTeamsByAccount/
//  for schema of the data FrameioTeam encapsulates.
export default class FrameioReviewLink extends FrameioBase {
    private _name: string = '';
    private _shortUrl: string = '';
    private _ownerId: string = '';
    private _projectId: string = '';
    private _active: boolean = false;
    private _inviteOnly: boolean = false;
    private _etag?: string;

    private _itemId?: string;
    private _item?: FrameioAsset;

    get name(): string {
        return this._name;
    }

    get shortUrl(): string {
        return this._shortUrl;
    }

    get ownerId(): string {
        return this._ownerId;
    }

    get projectId(): string {
        return this._projectId;
    }

    get active(): boolean {
        return this._active;
    }

    get inviteOnly(): boolean {
        return this._inviteOnly;
    }

    get itemId(): string | undefined {
        return this._itemId;
    }

    /*
     * Returns the number of artifacts currently in the review.
     */
    async getArtifactCount(): Promise<number> {
        const item = await this.getItem();

        if (item instanceof FrameioVersionStack) {
            return item.versions;
        }

        return 1;
    }

    /*
    * Recents the most recently published artifact,
    * a FrameioFile containing a PDF.
    */
    async getArtifact(): Promise<FrameioFile> {
        const item = await this.getItem();

        if (item instanceof FrameioVersionStack) {
            return (await item.getCoverAsset()) as FrameioFile;
        }

        return item as FrameioFile;
    }

    async getItem(): Promise<FrameioAsset> {
        if (!this._item) {
            if (!this._itemId) {
                return Promise.reject(SAMError.create(SAMErrorCode.BAD_REQUEST, `FrameioReviewLink.getItem() could not find item ${this._itemId}`));
            }

            this._item = await this.context.getAsset(this._itemId);
        }

        return this._item!;
    }

    private _dispatchReviewLinksChangeEvent(source: FrameioSourceDocument) {
        const ctx: FrameioContext = this.context;

        // After a successful updateReviewLink(),
        // we use SAM.cpp to dispatch an event to all DOM's,
        // so they can each update FrameioContext._reviewLinksForDocument
        //
        // For example, when ShareSheet creates a new review link,
        // ShareSheet and Commenting want to update their cache.
        //
        // See also FrameioContext._handleReviewLinksChangeEvent()

        const param: FrameioReviewLinksChangeEventParam = {
            source,
            reviewLink: {
                id: this.id,
                name: this._name,
                short_url: this._shortUrl,
                owner_id: this._ownerId,
                project_id: this._projectId,
                is_active: (this._active) ? true : false,
                access_control: {
                    invite_only: (this._inviteOnly) ? true : false
                },
                'frameio:artifactId': this._itemId,
                'repo:etag': this._etag
            }
        };

        ctx._frameioInterface.dispatchReviewLinksChangeEvent(JSON.stringify(param));
    }
    async updateReviewLink(source: FrameioSourceDocument, parent: FrameioFolder, artifactPath: string) {
        const file = await parent.createFile(this.name, artifactPath);

        if (!this._itemId) {
            // (_itemId === undefined) means this review has never been updated,
            // so the file asset should be added as an item to the review and remembered.
            const ctx: FrameioContext = this.context;

            const response = await ctx._frameioInterface.reviewLinkAddAsset(this.id, file.id);
            const session = ctx._objectPool.createUpdateSession<FrameioReviewLink>();
            FrameioReviewLinkUpdater.updateRemoteItem(session, response); // updates this
            session.commit();

            // Notify the Review Service of the newly created review.
            const result = await ctx._reviewServiceInterface.createReviewLink({
                ...source,
                projectId: this.projectId,
                reviewLinkId: this.id,
                artifactId: file.id
            });
            this._etag = result['repo:etag'];

            this._item = file;
            this._itemId = file.id;
        } else {
            // (_itemId !== undefined) means this isn't the first update.
            //
            // For the second update, we'll version the original file
            // (this._itemId) with the new file to create a stack.
            // We'll overwrite this._itemId with the stack's id and notify
            // the Review Service.
            //
            // For any remaining calls, this._itemId is already a stack,
            // and versioning a stack with a new file just adds the file
            // to the stack. As the stack doesn't change, there's no
            // further need to update the Review Service.

            const ctx: FrameioContext = this.context;
            const response = await ctx._frameioInterface.addVersionToAsset(this._itemId, file.id);
            const session = ctx._objectPool.createUpdateSession<FrameioVersionStack>();
            const item = FrameioVersionStackUpdater.updateRemoteItem(session, response);
            session.commit();

            if (this._itemId !== item.id) {
                // Notify the Review Service that the file
                // has been replaced with a version stack.
                const result = await ctx._reviewServiceInterface.updateReviewLink({
                    ...source,
                    projectId: this.projectId,
                    reviewLinkId: this.id,
                    artifactId: item.id,
                    etag: this._etag
                });
                this._etag = result['repo:etag'];

                this._item = item;
                this._itemId = item.id;
            }
        }
        this._dispatchReviewLinksChangeEvent(source);
    }
}

export const FrameioReviewLinkUpdater = new ItemUpdater<FrameioReviewLink, Partial<IFrameioReviewLinkResponse>>({
    localItemType: FrameioReviewLink,
    remoteIdProperty: 'id',
    propertyUpdater: new PropertyUpdater({
        '_name': 'name',
        '_shortUrl': 'short_url',
        '_ownerId': 'owner_id',
        '_projectId': 'project_id',
        '_active': { name: 'is_active', format: 'boolean' },
        '_inviteOnly': { name: 'access_control.invite_only', format: 'boolean' },
        '_itemId': 'frameio:artifactId',
        '_etag': 'repo:etag'
    })
});

