import { CombinedGraphQLErrors, ServerError, ServerParseError, type ErrorLike } from '@apollo/client';
import { SAM } from '@ccx-public/component-types';
import type { GraphQLFormattedError } from 'graphql';

import type { ISAMCorePrivate } from '../indexPrivate';

export const SAMErrorCode = SAM.SAMErrorCode;
// eslint-disable-next-line @typescript-eslint/no-redeclare
export type SAMErrorCode = SAM.SAMErrorCode;

export const SAMErrorSubCode = SAM.SAMErrorSubCode;
// eslint-disable-next-line @typescript-eslint/no-redeclare
export type SAMErrorSubCode = SAM.SAMErrorSubCode;

type ErrorCodeInfo = {
    code: SAMErrorCode;
    message: (href: string) => string;
    subCode?: SAMErrorSubCode;
}

const errorCodeInfos = new Map<number, ErrorCodeInfo>([
    [ 400, { code: SAMErrorCode.BAD_REQUEST, message: (href) => `400 error from ${href}` } ],
    [ 401, { code: SAMErrorCode.AUTHORIZATION_ERROR, message: (href) => `Authorization error: ${href}` } ],
    // Note: 403 maps to "ACCESS_DENIED" instead of something like "FORBIDDEN" because that's how SAM.cpp did it
    // and at one point, SAM.js errors were kept aligned with SAM.cpp errors.
    [ 403, { code: SAMErrorCode.ACCESS_DENIED, message: (href) => `Access to resource denied: ${href}` } ],
    [ 404, { code: SAMErrorCode.NOT_FOUND, message: (href) => `Resource not found: ${href}` } ],
    [ 409, { code: SAMErrorCode.CONFLICT, message: () => `Resource has a naming conflict.` } ],
    [ 412, { code: SAMErrorCode.CONFLICT, message: () => `Resource has a conflict. Etag mismatch.` } ],
]);

export function throwIfNoData(
    core: ISAMCorePrivate,
    data: any,
    error: ErrorLike | undefined
) {
    // If all the top-level keys on data have `null` or `undefined` values, then there is no data in the
    // response, so it should throw an exception
    const definedDataProperties = [ ...Object.entries(data || {}) ].filter(([ _, val ]) => val !== undefined && val !== null);
    if (!definedDataProperties.length) {
        if (error) {
            throw SAMError.createWithApolloError(error);
        }
        // TODO: is this reachable? If so, is there a way to get requestId?
        throw SAMError.create(SAMErrorCode.UNKNOWN, `throwIfNoData: no data ${data}`);
    }
    // There are defined data properties, log any errors but do not throw
    if (error) {
        if (CombinedGraphQLErrors.is(error)) {
            const requestId = CombinedGraphQLErrors.is(error) ? error.errors[0].extensions?.requestId : undefined;
            core._environment.error(`GraphQL response (reqId: ${requestId}) contained errors and data,`
            + ' ignoring errors: ' + JSON.stringify(error.errors));
        } else {
            core._environment.error(`GraphQL response contained non-GraphQLErrors and data: ` + error);
        }
    }
}

/**
 * Convert server error codes to regular HTTP number codes.
 * '4041' -> 404
 * '404.1' -> 404
 * 4041 -> 404
 * 404 -> 404
 *
 * @param code from server
 * @returns http error code
 */
function validateRepositoryCode(code: string | number): number {
    // Repo APIs return string codes instead of numbers. In that case
    if (typeof code === 'string') {
        code = parseInt(code);
    }

    // Remove any extra floating point.
    code = Math.floor(code);

    // HTTP error codes only use 3 digits, but repo APIs can have even 5 digits.
    // We only care about the most significant 3 digits though.
    // https://git.corp.adobe.com/DMA/dcx-lib/blob/729085f1ed77936a1718377ea6cd5e3b16f6aada/lib/dcxlib/src/main/java/com/adobe/dcx/storagesession/StorageErrorCode.java#L12
    while (code > 999) {
        code = Math.floor(code / 10);
    }

    return code;
}

export enum ProblemType {
    LIMIT_CHANGELOGRETENTION = 'http://ns.adobe.com/adobecloud/problem/limit/changelogretention',
    OPERATION_FAILED = 'adobecloud/problem/operation_failed',
    SUBSCRIPTION_COUNT = 'http://ns.adobe.com/adobecloud/problem/limit/subscriptioncount',
    QUOTA_EXCEEDED = 'http://ns.adobe.com/adobecloud/problem/quotaexceeded',
    CHILDREN_LIMIT_EXCEEDED = 'http://ns.adobe.com/adobecloud/problem/limit/childrencount',
    NO_HOME_REPOSITORY = 'http://ns.adobe.com/projects/problem/no-home-repository',
    INVALID_HOME_REPOSITORY = 'http://ns.adobe.com/projects/problem/invalid-repository',
    ADMIN_ONLY = 'http://ns.adobe.com/projects/problem/admin-only',
    ACCESS_DENIED = 'http://ns.adobe.com/adobecloud/problem/accessdenied',
    LAST_VERSION_LEFT = 'http://ns.adobe.com/adobecloud/problem/noversionleft',
    RESTRICTED_BY_POLICY = 'http://ns.adobe.com/adobecloud/problem/policyrestricted',
    ACCESS_DENIED_ORG_NON_MEMBER = 'http://ns.adobe.com/adobecloud/problem/accessdenied/externalentity',
    RESPONSE_TOO_LARGE = 'http://ns.adobe.com/adobecloud/problem/responsetoolarge',
}

function formatUnderlyingError(underlyingError: any): String {
    let errorStr: string = '';
    if (underlyingError !== null && underlyingError !== undefined) {
        try {
            errorStr = ` -> ${String(underlyingError)}`;
        } catch {
            // Avoid linter error on empty blocks.
            void (0);
        }
    }
    return errorStr;
}

/**
 * This additional info is to be only used for debugging purposes by clients
 * or internally by SAM.js
 */
export interface IAdditionalErrorInfo {
    /**
     * Response object mainly for HTTP errors created with the help of createWithResponse* API
     */
    response?: Response;
    /**
     * For services that return RFC 7807 `type` metadata in the body.
     */
    problemType?: string;
    /**
     * These could be errors thrown from a service or an error thrown while parsing JSON
     */
    underlyingError?: any;

    /**
     * X-Request-Id header extracted from response, if available
     */
    reqId?: string;

    /**
     * X-Breadcrumb-Trail header extracted from response, if available
     */
    breadcrumbTrail?: string;
}

export const SAMErrorName = 'SAMError';

/**
 * SAM.js would always throw back SAMError even when it is powered via SAM.cpp
 * The clients must rely only on `code` and `subCode` in order to write their business logic.
 * `description` can be used for logging purposes.
 * `_additionalInfo` should only be used for debugging purpose and there should not be any reference
 * to it in the code base.
 */
export class SAMError extends Error implements SAM.SAMError {
    readonly code: SAMErrorCode;
    readonly subCode?: SAMErrorSubCode;
    /**
     * The below fields are to be used by clients only for logging/debugging purposes only.
     * For fine-grain error-handling, clients should only inspect `code` and `subCode`.
     * They may be used internally by SAM.js
     */
    readonly description: string;
    readonly _additionalInfo: IAdditionalErrorInfo;

    protected constructor(
        code: SAMErrorCode,
        description: string,
        additionalInfo: IAdditionalErrorInfo = {},
        subCode?: SAMErrorSubCode
    ) {
        // NOTE: clients should not rely on SAMError.message for fine-grain error handling; instead, use `code` and `subcode`.
        const message = `[${SAMErrorCode[code]}${ subCode === undefined ? '' : '-' + SAMErrorSubCode[subCode]}] ${description}${formatUnderlyingError(additionalInfo.underlyingError)}`;

        if (additionalInfo.underlyingError !== undefined) {
            // When SAM rethrows errors, it wraps the caught error with
            // a SAMError, preserving the caught error as underlyingError.
            //
            // Unfortunately Sentry isn't aware of underlyingError,
            // so we loose valuable debugging information. Sentry
            // is aware of Error.cause ( ES2022 ), which is another
            // way to specify the caught error when rethrowing.
            //
            // So when there's an underlyingError, I'm setting both
            // to improve debugging in Sentry while preserving legacy
            // behaviour.
            super(message, { cause: additionalInfo.underlyingError });
        } else {
            super(message);
        }

        this.code = code;
        this.subCode = subCode;
        this.description = description;
        this._additionalInfo = additionalInfo;
    }

    get name() {
        return SAMErrorName;
    }

    static wrapErrorIfNeeded(code: SAMErrorCode, description: string, underlyingError: any, subCode?: SAMErrorSubCode): SAMError {
        if (underlyingError instanceof SAMError) {
            return underlyingError;
        }
        return new SAMError(code, description, { underlyingError }, subCode);
    }

    static create(code: SAMErrorCode, description: string, additionalInfo?: IAdditionalErrorInfo, subCode?: SAMErrorSubCode): SAMError {
        return new SAMError(code, description, additionalInfo, subCode);
    }

    static createWithResponse(response: Response, href?: string) {
        const { status } = response;
        const info = errorCodeInfos.get(validateRepositoryCode(status));
        const responseUrl = href ?? response.url;
        const reqId = response.headers.get('X-Request-Id') || '';
        const breadcrumbTrail = response.headers.get('X-Breadcrumb-Trail') || '';
        return new SAMError(
            info?.code ?? SAMErrorCode.UNKNOWN,
            (info?.message(href ?? responseUrl) ?? `Unexpected response status: ${status} for ${responseUrl}`)
                + ` reqId: ${reqId} breadcrumbTrail: ${breadcrumbTrail}`,
            { response, reqId, breadcrumbTrail },
            info?.subCode,
        );
    }

    static createWithResponseAndDescription(response: Response, description: string) {
        const info = errorCodeInfos.get(validateRepositoryCode(response.status));
        return new SAMError(
            info?.code ?? SAMErrorCode.UNKNOWN,
            description,
            { response },
            info?.subCode,
        );
    }

    static createWithRepositoryCode(
        code: number | string,
        problemType: string,
        description: string,
        reqId: string,
    ) {
        // Look out for Quota Exceeded errors.
        // RAPI returns 403 with problemType = http://ns.adobe.com/adobecloud/problem/quotaexceeded for such errors.
        // We want to return a more specific error code for this case.
        if (problemType === ProblemType.QUOTA_EXCEEDED) {
            return new SAMError(
                SAMErrorCode.FULL_CLOUD_STORAGE,
                description,
                { problemType, reqId },
            );
        }

        // When transfer of ownership is disabled by an administrator, RAPI will return with the 403 status
        // and problemType = http://ns.adobe.com/adobecloud/problem/restrictedbypolicy. As of this writing
        // this policy is controlled by the 3rd Party API.
        if (problemType === ProblemType.RESTRICTED_BY_POLICY) {
            return new SAMError(
                SAMErrorCode.TRANSFER_OF_OWNERSHIP_DISABLED,
                description,
                { problemType, reqId },
            );
        }

        if (problemType === ProblemType.ACCESS_DENIED_ORG_NON_MEMBER) {
            return new SAMError(
                SAMErrorCode.MOVES_FROM_ORG_DISALLOWED,
                description,
                { problemType, reqId },
            );
        }

        const validHTTPCode = validateRepositoryCode(code);
        const info = code ? errorCodeInfos.get(validHTTPCode) : undefined;
        return new SAMError(
            info?.code ?? SAMErrorCode.UNKNOWN,
            description,
            { problemType, reqId },
            info?.subCode,
        );
    }

    /**
     * In Apollo 4, all errors are ErrorLike; ApolloError is no longer available.
     * @see https://www.apollographql.com/docs/react/migrating/apollo-client-4-migration#errors-as-guaranteed-error-like-objects
     */
    static createWithApolloError(error: ErrorLike) {
        if (CombinedGraphQLErrors.is(error)) {
            return SAMError.createWithGraphQLError(error.errors[0]);
        } else if (ServerError.is(error) || ServerParseError.is(error)) {
            if (error.response) {
                return SAMError.createWithResponse(error.response);
            }
        }
        return SAMError.create(SAMErrorCode.UNKNOWN, `createWithApolloError ${error.name} ${error.message}`);
    }

    static createWithGraphQLError(error: GraphQLFormattedError) {
        // As per the discussion with asset subgraph team, the errors are RAPI compliant and
        // would be returned in the extensions field of the error. Apollo client returns an array of graphQLErrors but
        // it seems we typically will only have one error from the asset subgraph.
        const extensions = error.extensions;
        if (extensions) {
            return SAMError.createWithRepositoryCode(
                extensions.httpErrorCode as number,
                (extensions.problemType as any)?.type as string,
                `GQLError: ${error.message} - path: ${error.path?.join('/')}`,
                // requestId is added via an ErrorLink in GQLInterface
                extensions.requestId as string
            );
        }
        return SAMError.create(SAMErrorCode.UNKNOWN, `createWithGraphQLError ${error.message}`);
    }
}

/**
 * Throws SAMAssertionError when `assertedCondition` is false.
 * @param assertedCondition
 * @param message
 */
export function assert(assertedCondition: boolean, message: string) {
    if (!assertedCondition) {
        throw SAMError.create(SAMErrorCode.UNKNOWN, message);
    }
}

/**
 * Helper function used to accurately determine if an error
 * is a SAMError and not a plain Error.
 *
 * @param error An Error type object
 * @returns
 */
export function isSAMError(error: any): error is SAMError {
    return error && error.name === SAMErrorName;
}

// We've used this as a default in too many places now,
// this should avoid a huge change just to update the paths.
export default SAMError;
