/**
 * Converts a UTF-8 string to an ArrayBuffer.
 * This function uses TextEncoder if available, otherwise it falls back
 * to a custom implementation to support UXP environments.
 *
 * Request for UXP TextEncoder support: https://jira.corp.adobe.com/browse/UXP-23190
 */
export function utf8ToArrayBuffer(str: string): ArrayBuffer {
    if (typeof TextEncoder !== 'undefined') {
        return new TextEncoder().encode(str).buffer as ArrayBuffer;
    } else {
        return utf8ToArrayBufferWithoutTextEncoder(str);
    }
}

/**
 * Converts an ArrayBuffer to a UTF-8 string.
 * This function uses TextDecoder if available, otherwise it falls back
 * to a custom implementation to support UXP environments. For that reason, this version is async.
 */
export async function arrayBufferToUtf8(buffer: ArrayBuffer): Promise<string> {
    if (typeof TextDecoder !== 'undefined') {
        return new TextDecoder().decode(buffer);
    } else {
        return arrayBufferToStringWithoutTextDecoder(buffer);
    }
}

/**
 * Converts a UTF-8 string to an ArrayBuffer without using TextEncoder,
 * which UXP doesn't support.
 */
export function utf8ToArrayBufferWithoutTextEncoder(str: string) {
    // Implementation of UTF-8 encoding as described in this algorithm:
    // https://encoding.spec.whatwg.org/#utf-8-encoder
    // See public domain example: https://gist.github.com/Yaffle/5458286
    const octets = [];
    const length = str.length;
    let i = 0;
    while (i < length) {
        const codePoint = str.codePointAt(i)!;
        let c = 0;
        let bits = 0;
        if (codePoint <= 0x0000007f) {
            c = 0;
            bits = 0x00;
        } else if (codePoint <= 0x000007ff) {
            c = 6;
            bits = 0xc0;
        } else if (codePoint <= 0x0000ffff) {
            c = 12;
            bits = 0xe0;
        } else if (codePoint <= 0x001fffff) {
            c = 18;
            bits = 0xf0;
        }
        octets.push(bits | (codePoint >> c));
        c -= 6;
        while (c >= 0) {
            octets.push(0x80 | ((codePoint >> c) & 0x3f));
            c -= 6;
        }
        i += codePoint >= 0x10000 ? 2 : 1;
    }
    return new Uint8Array(octets).buffer;
}

/**
 * Converts an ArrayBuffer to a UTF-8 string without using TextDecoder,
 * which UXP doesn't support. See public domain example:
 * https://gist.github.com/Yaffle/5458286#file-textencodertextdecoder-js-L55-L90
 */
export function arrayBufferToStringWithoutTextDecoder(buffer: ArrayBuffer): string {
    const octets = new Uint8Array(buffer);
    let string = '';
    let i = 0;
    while (i < octets.length) {
        let octet = octets[i];
        let bytesNeeded = 0;
        let codePoint = 0;
        if (octet <= 0x7F) {
            bytesNeeded = 0;
            codePoint = octet & 0xFF;
        } else if (octet <= 0xDF) {
            bytesNeeded = 1;
            codePoint = octet & 0x1F;
        } else if (octet <= 0xEF) {
            bytesNeeded = 2;
            codePoint = octet & 0x0F;
        } else if (octet <= 0xF4) {
            bytesNeeded = 3;
            codePoint = octet & 0x07;
        }
        if (octets.length - i - bytesNeeded > 0) {
            let k = 0;
            while (k < bytesNeeded) {
                octet = octets[i + k + 1];
                codePoint = (codePoint << 6) | (octet & 0x3F);
                k += 1;
            }
        } else {
            codePoint = 0xFFFD;
            bytesNeeded = octets.length - i;
        }
        string += String.fromCodePoint(codePoint);
        i += bytesNeeded + 1;
    }
    return string;
}
