import type { SAM } from '@ccx-public/component-types';
import ItemUpdater from '../../core/ItemUpdater';
import AdobeAsset from '../../assets/AdobeAsset';
import type { CustomModelData } from './LegacyCustomModelModel';
import { CustomModelPublishedState } from './LegacyCustomModelModel';
import PropertyUpdater from '../../core/PropertyUpdater';
import { observable } from '../../core/decorators';

export default class LegacyCustomModel extends AdobeAsset implements SAM.LegacyCustomModel {
    public isCustomModel: boolean = true;

    private _inferenceReady: boolean = false;
    private _publishedState: CustomModelPublishedState = CustomModelPublishedState.UNPUBLISHED;
    private _samplePrompt: string = '';
    private _renditionUrl?: string;
    private _displayName: string = '';
    private _baseModelName: string = '';
    private _baseModelVersion: string = '';
    private _conceptId: string = '';
    private _trainingMode: string = '';

    @observable
    get inferenceReady() {
        return this._inferenceReady;
    }

    @observable
    get publishedState() {
        return this._publishedState;
    }

    @observable
    get samplePrompt() {
        return this._samplePrompt;
    }

    @observable
    get renditionUrl() {
        return this._renditionUrl;
    }

    @observable
    get displayName() {
        return this._displayName;
    }

    @observable
    get baseModelName() {
        return this._baseModelName;
    }
    @observable
    get baseModelVersion() {
        return this._baseModelVersion;
    }
    @observable
    get conceptId() {
        return this._conceptId;
    }
    @observable
    get trainingMode() {
        return this._trainingMode;
    }
}

export const LegacyCustomModelUpdater = new ItemUpdater<LegacyCustomModel, CustomModelData>(
    {
        localItemType: LegacyCustomModel,
        remoteIdProperty: 'assetId',
        propertyUpdater: new PropertyUpdater({
            '_inferenceReady': { name: 'inferenceReady', format: 'boolean' },
            // TODO: create a type with array of choices?
            '_publishedState': 'publishedState',
            '_samplePrompt': 'samplePrompt',
            '_renditionUrl': 'renditionUrl',
            '_displayName': 'displayName',
            '_baseModelName': 'baseModelName',
            '_baseModelVersion': 'baseModelVersion',
            '_conceptId': 'conceptId',
            '_trainingMode': 'trainingMode',
            // on AdobeAsset
            '_links': { name: '_links', format: 'object' },
            '_name': 'assetName',
            '_path': 'path',
            '_created': { name: 'createDate', format: 'date' },
            '_modified': { name: 'modifyDate', format: 'date'  },
            '_createdBy': 'createdBy',
            '_version': 'version',
            '_etag': 'etag',
            '_storageRegion': 'region',
            '_size': { name: 'size', format: 'number' },
        }),
    }
);
