import type AdobeAsset/*, { USSAdobeAssetUpdaterMetadata }*/  from './AdobeAsset';
import type { IItemLoaderOptions, ILoadedPage } from '../core/ItemLoader';
import type ItemPool from '../core/ItemPool';
import type { SWYAdobeAssetConfig } from './SWYAdobeAssetSource';
import type SWYAdobeAssetFilter from './SWYAdobeAssetFilter';
import { OrderFieldToISWYAdobeAssetOrderBy } from './SWYAdobeAssetOrder';
import type SWYInterface from '../interface/SWYInterface';
import type { USSResponse } from '../interface/USSModel';
import type { IGetUSSResults, IUSSLoader } from './USSLoaderHelper';
import USSLoaderHelper from './USSLoaderHelper';
import type { ISAMCorePrivate } from '../indexPrivate';
import type AdobeAssetFilter from '../assets/AdobeAssetFilter';
import type LibraryContext from '../libraries/LibraryContext';

export default class SWYAdobeAssetLoader implements IUSSLoader<SWYAdobeAssetConfig> {
    private _ussLoaderHelper: USSLoaderHelper<SWYAdobeAssetConfig>;
    /**
      * @package -- only for use in SAM.js
      */
    _libraryContext?: LibraryContext;

    constructor(
        assetPool: ItemPool<AdobeAsset>,
        private _core: ISAMCorePrivate,
        private _swyInterface: SWYInterface,
    ) {
        this._ussLoaderHelper = new USSLoaderHelper(assetPool, _core, this);
    }

    supportsFilter(filter?: SWYAdobeAssetFilter | AdobeAssetFilter): boolean {
        // If we don't provide a filter at all, then we cannot use the loader
        return filter !== undefined;
    }

    async loadPage(options: IItemLoaderOptions<SWYAdobeAssetConfig>): Promise<ILoadedPage<SWYAdobeAssetConfig>> {
        if (!this._libraryContext) {
            this._libraryContext = await this._core.getLibraryContext();
        }
        return this._ussLoaderHelper.loadPage(options);
    }

    /**
     * @package -- for use by USSLoaderHelper
     */
    async _getUSSResults({
        start,
        loadOptions,
        mediaTypes,
        excludeMediaTypes,
        order,
        resource
    }: IGetUSSResults<SWYAdobeAssetConfig>): Promise<USSResponse> {
        return this._swyInterface.getSWYAssets({
            orderBy: OrderFieldToISWYAdobeAssetOrderBy[order.field],
            orderDirection: order.direction,
            start,
            limit: loadOptions?.limit,
            mediaTypes,
            excludeMediaTypes,
            embedPermissions: true
        }, resource);
    }
}
