import type { IUpdateSession } from '../core/UpdateSession';
import type ItemPool from '../core/ItemPool';
import type AdobeAsset from './AdobeAsset';
import type Project from '../projects/Project';
import type { ISAMCorePrivate } from '../indexPrivate';
import type Space from '../workspaces/Space';
import type AssetContext from './AssetContext';
import { VersionPatchTypes } from '../interface/AssetInterface';
import { SAMError, SAMErrorCode } from '../core/SAMError';

const MAX_LENGTH = 255;
const RESERVED_NAME_REGEX = /^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])$/i;
const RESERVED_CHAR_REGEX = /[\\/:*?"|><]/;

export interface IFormatFileNameResult {
    newName: string;
    countUsed: number;
}

export type NameConflictMap = Map<string, IFormatFileNameResult>;

/** A map of asset IDs to their new names */
export type AssetRenameMap<T extends AdobeAsset | Space> = Map<T['id'], T['name']>;

interface CleanAssetNameOptions {
    /** The name of the asset */
    name: string;
    /** The maximum length of the name, defaults to {@link MAX_LENGTH} */
    maxLength?: number;
    /** Whether to validate the name after cleaning. Defaults to false. If true and the name is invalid then an error will be thrown. */
    shouldValidate?: boolean;
}

export function validatePlatformRepoName(name: string) {
    return (name.length > 0
        && name.length <= MAX_LENGTH
        && !RESERVED_NAME_REGEX.test(name)
        && !RESERVED_CHAR_REGEX.test(name));
}

export type ValidateAssetNameOptions = {
    /** The name to validate */
    name: string;
    /** The asset ID of the asset to validate */
    assetId?: string;
    /** The list of assets to validate against */
    assetList?: AdobeAsset[];
    /** The locale to use for validation */
    locale?: string;
    /** Function to get the name of other assets to validate against */
    getOtherAssetName?: (asset: AdobeAsset) => string;
};

const PATH_REGEX = /^(.*\/)?(.*?)(?:[\u00A0][^.]*)?(\.[^.]*)?$/;

/**
 * Called by SAM to get new name according to the specified format and counter
 * @param fullPath path of the asset, it can be full path/relative path/filename
 * @param format format should contain %@ and %d
 *      %@ to be replace with filename
 *      %d to be replace with supplied counter. counter value will change in following cases:
 *          - filename matches the format and counter supplied. counter will increment by 1
 *          - filename matches the formatWithoutCount and counter = 0. counter will be made 1
 *            e.g name = test copy, format = %@ copy %d, counter = 0 -> newName = test copy 1, countUsed = 1
 * @param counter count to be used in newName
 * @returns the IFormatFileNameResult object which contains new name and count used in new name
 */
export function formatFileName(fullPath: string, format: string, counter: number): IFormatFileNameResult {
    // create regex from client passed format
    function getRegexFormat(format: string, extPresent: boolean) {
        // replace '(', ')' with backspace '\(', '\)'
        let regexFormat = format.replace(/[()]/g, '\\$&');
        // insert match patern for %d and %@
        regexFormat = regexFormat.replace('%d', '([0-9]+)');
        regexFormat = regexFormat.replace('%@', '(.*)?');
        // if extPresent is true, we expect to find extension, otherwise it is optional
        regexFormat = regexFormat + (extPresent ? '(\\.[^.]*)$' : '(\\.[^.]*)?$');
        return regexFormat;
    }
    const extPresent = fullPath.lastIndexOf('.') > fullPath.lastIndexOf('/');
    const regexFormat = getRegexFormat(format, extPresent);

    // remove count from string
    const formatWithoutCount = format.replace(/ [^ ]*$/, '');
    const regexFormatWithoutCount = getRegexFormat(formatWithoutCount, extPresent);

    // get parsed result
    let result = fullPath.match(regexFormat);
    let resultMatchedRegexWithoutCount: boolean = false;
    if (result === null) {
        result = fullPath.match(regexFormatWithoutCount);
        resultMatchedRegexWithoutCount = result !== null;
    }
    let newPath: string = '';
    let fileExtension: string = '';
    if (result) {
        let path: string = '';
        let extension: string = '';
        let currentCount: string = '';
        if (resultMatchedRegexWithoutCount) {
            [ , path, extension ] = result;
        } else {
            [ , path, currentCount, extension ] = result;
        }
        newPath = path;
        fileExtension = extension;
        if (resultMatchedRegexWithoutCount && counter === 0) {
            // since the name does not contain the count
            // but matches the regex without count, so
            // if counter=0, next name in iteration is with counter=1
            counter = 1;
        } else if (!resultMatchedRegexWithoutCount && parseInt(currentCount) === counter) {
            // since the name matches the format with count
            // we should skip the counter that matches the current name
            counter += 1;
        }
    } else {
        const [ , directory, filename, extension ] = fullPath.match(PATH_REGEX)!; // All strings match the regexp above
        newPath = `${directory || ''}${filename || ''}`;
        fileExtension = extension;
    }
    let newName = '';
    if (counter !== 0) {
        newName = format.replace('%@', `${newPath || ''}`);
        newName = newName.replace('%d', counter.toString());
    } else {
        newName = formatWithoutCount.replace('%@', `${newPath || ''}`);
    }
    return {
        newName: `${newName || ''}${fileExtension || ''}`,
        countUsed: counter
    } as IFormatFileNameResult;
}

/**
 * Called to get newName as per format in case of batch ops. It considers name of other files as well in the operation for finding conflicts
 * @param core SAMCore
 * @param assetId Asset Id
 * @param newName FileName
 * @param sameFolder true if copying in same folder
 * @param assetConflictMap It saves the newName and count used for all files in batch
 */
export function batchFormatFileName(
    core: ISAMCorePrivate,
    assetId: string,
    newName: string,
    sameFolder: boolean,
    assetConflictMap: NameConflictMap
): string {
    let localCounter = assetConflictMap.get(assetId)?.countUsed || 0;
    let conflictWithOtherFilesInBatch: boolean = false;
    const conflictedAssetIds: string[] = [];
    // check if we are copying in the same folder
    // if yes, then it should follow ASSET_COPY_NAME_FORMAT i.e. %@ copy (%d)
    // if no and conflict, then it should follow ASSET_CONFLICT_NAME_FORMAT i.e. %@ (%d)
    do {
        const formatFileResult = sameFolder ? formatFileName(newName, core._environment.getValue('ASSET_COPY_NAME_FORMAT'), localCounter)
            : (localCounter > 0 ? formatFileName(newName, core._environment.getValue('ASSET_CONFLICT_NAME_FORMAT'), localCounter) : { newName, countUsed: localCounter });
        newName = formatFileResult.newName;
        localCounter = formatFileResult.countUsed;

        conflictWithOtherFilesInBatch = false;
        for (const [ key, value ] of assetConflictMap) {
            if (value.newName === newName) {
                conflictWithOtherFilesInBatch = true;
                conflictedAssetIds.push(key);
                break;
            }
        }

        if (conflictWithOtherFilesInBatch) {
            localCounter++;
        } else {
            assetConflictMap.set(assetId, formatFileResult);
        }
    } while (conflictWithOtherFilesInBatch);

    for (const id of conflictedAssetIds) {
        // we should update count of all files which this file conflicted with
        // so that they also start with the new count next time
        const currentValue = assetConflictMap.get(id);
        assetConflictMap.set(id, { newName: currentValue!.newName, countUsed: localCounter });
    }
    return newName;
}

const ARCHIVE_GUID_REGEX = /^(.*)\^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[12345][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$/;

// Archived assets get a guid suffix appended, so need to remove it when restoring
export function removeArchiveGuidFromName(name: string) {
    const match = name.match(ARCHIVE_GUID_REGEX);
    return match ? match[1] : name;
}

// Clients that haven't yet migrated to R-API still use the old archive locations when deleting assets (as a 2-step delete).
// These locations are treated as discarded by SAM.js, but to implement recover() we need to know where to move the assets back to.
// This is a mapping from the archive location to the restore location.
const ARCHIVE_TO_RESTORE_LOCATION: { [s: string]: string } = {
    'cloud-content-archive': 'cloud-content',
    'assets-archive': 'assets',
    'archive': 'files'
};

export function getRestorePath(path: string, newName?: string): string | undefined {
    const newPath = path.split('/');

    // Paths always start with "/" so newPath[0] is ''
    // ESM paths are of the form /users/<userid>/...
    const archiveIndex = newPath[1] === 'users' ? 3 : 1;
    const restoreFolder = ARCHIVE_TO_RESTORE_LOCATION[newPath[archiveIndex]];
    if (!restoreFolder) {
        // Not archived, so no restore location
        return undefined;
    }

    newPath[archiveIndex] = restoreFolder;
    newPath[newPath.length - 1] = newName || removeArchiveGuidFromName(newPath[newPath.length - 1]);
    return newPath.join('/');
}

/**
 * Replaces the ending filename in a path with the newName
 * and returns the result as a single string.
 *
 * @param newName
 * @param asset
 * @returns
 */
export function renameFileInPath(newName: string, asset: AdobeAsset | Project): string {
    const path = asset.repoPath.split('/').slice(0, -1);
    path.push(newName);
    return path.join('/');
}

/**
 * Updates the cached descendents of the provided asset.
 *
 * @param param.assetPool Asset pool where items are to be udpated
 * @param param.asset The target asset to check for descendants.
 * @param param.session The update session
 * @param param.basePath The new base path string.
 * @returns
 */
type UpdateCachedDescendentsOperation =
  | { type: 'discard' }
  | { type: 'restore'; newPath?: string }
  | { type: 'rename'; newPath: string }
  | { type: 'move'; newPath: string };

export function updateCachedDescendents(params: {
    operation: UpdateCachedDescendentsOperation,
    assetPool: ItemPool<AdobeAsset>,
    asset: AdobeAsset,
    session: IUpdateSession<AdobeAsset>,
    assetContext: AssetContext
}) {
    const { assetPool, asset, session, operation, assetContext } = params;
    if (!asset.isFolder || !asset.repoPath.trim()) {
        // The asset must be a folder with a non-empty path
        return;
    }

    // make sure we update the repo:path of all the descendants of this folder
    assetPool.forEach(item => {
        if (
            item.repoPath.startsWith(asset.repoPath + '/') // make sure the item is a descendant of the asset
        ) {
            switch (operation.type) {
            case 'move':
            case 'rename': {
                // Used by both rename and move operations.
                // Checking if the item's repoPath starts with the folder's repo:path with '/' appended
                // this also rules out the folder itself.
                if (!item.repoPath.startsWith(operation.newPath)) {
                    // We need to take care of recursive folders with the same name as well
                    const newChildPath = item.repoPath.replace(asset.repoPath, operation.newPath);
                    assetContext._adobeAssetUpdater.updateLocalItem(session, item, { 'repo:path': newChildPath });

                    // @note - RE Project Moves: It would be ideal to update the ancestor ids here but the Projects service does not
                    // return ancestor ids in any of it's results. So if we move a project into another project,
                    // we have no idea what the original ancestor ids were and what they are now so we can't update them.
                }
                break;
            }
            case 'discard': {
                // If item is a descendant of the asset and it is ACTIVE, set repo:state to DISCARDED_PARENT.
                // We do not want to modify the repo:state of assets that were directly discarded (DISCARDED),
                // and we don't need to update the repo:state of assets that are already discarded with parent (DISCARDED_PARENT).
                if (item.ancestorIDs?.includes(asset.id) && !item.isDiscarded) {
                    assetContext._adobeAssetUpdater.updateLocalItem(session, item, { 'repo:state': 'DISCARDED_PARENT' });
                }
                break;
            }
            case 'restore': {
                // Restore operations for assets may include a new path to restore to,
                // due to unarchiving the parent folder or a name conflict upon parent folder restore.
                if (operation.newPath) {
                    assetContext._adobeAssetUpdater.updateLocalItem(session, item, { 'repo:path': item.repoPath.replace(asset.repoPath, operation.newPath) });
                }
                // If any children were originally discarded along with the parent folder ('repo:state': 'DISCARDED_PARENT'),
                // update their repo:state to 'ACTIVE'. Children that were directly discarded should remain 'DISCARDED'.
                if (item._isDiscardedWithParent()) {
                    assetContext._adobeAssetUpdater.updateLocalItem(session, item, { 'repo:state': 'ACTIVE' });
                }
                break;
            }
            }
        }
    });
}

export const getBatchRenamedAssetName = <Item extends AdobeAsset | Space>(item: Item, map: AssetRenameMap<Item>): Item['name'] => {
    return map.has(item.id) ? map.get(item.id)! : item.name;
};

/**
     * Creates the jsonParams array for milestone operations
     * @param versionId The version ID to set the milestone on
     * @param hasExistingMilestone Whether the version already has a milestone
     * @param label The milestone label
     * @param description The milestone description
     * @returns The jsonParams array for the patch operation
     * @package -- only for use in SAM.js
     */
export function createMilestoneJsonParams(versionId: string, hasExistingMilestone: boolean, label: string, description: string, isPinned: boolean) {
    return [ {
        op: hasExistingMilestone ? VersionPatchTypes.replace : VersionPatchTypes.add,
        path: `/children/version=${versionId}/milestone`,
        value: { label, description, isPinned }
    } ];
}

/**
 * Determine if the given name is valid
 *  - Name cannot contain only whitespace
 *  - Name must adhere to asset naming rules
 *  - Name cannot end in a period
 *  - The name must be unique within the parent asset
 *  - If the name is a duplicate of an asset with the same given assetId, it is valid
 *  - If the name is a duplicate of an asset with a different given assetId, it is invalid
 *  - If assetList is not provided, it does not throw an error unless the name is malformed
 * @param param.name The name to validate. Name can include extensions.
 * @param param.assetId The ID of the asset to validate against
 * @param param.assetList The list of assets to validate against
 * @param param.locale The locale to use for validation
 * @param param.getOtherAssetName A function to get the name of the asset to validate against
 * @throws {SAMError} if the name is invalid or not unique
 * @package -- only for use in SAM.js
 */
export function validateAssetName({ name, assetId, assetList, locale, getOtherAssetName }: ValidateAssetNameOptions): void {
    // Name cannot have leading or trailing whitespace
    const trimmedName = name.trim();
    if (trimmedName.length === 0) {
        throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'The asset name cannot be blank.');
    }
    // Name must adhere to asset naming rules
    if (!validatePlatformRepoName(trimmedName)) {
        throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'The asset name is an invalid platform repo name.');
    }
    // Name cannot end in a period
    if (trimmedName.endsWith('.')) {
        throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'The asset name cannot end with a period.');
    }

    // if assetList is not provided, we can't validate uniqueness. So it does not throw an error
    const matchingAsset = assetList?.find((asset: AdobeAsset) => {
        const assetName = (getOtherAssetName?.(asset) || asset.name);
        return assetName.toLocaleLowerCase(locale) === trimmedName.toLocaleLowerCase(locale);
    });
    if (matchingAsset) {
        if (!assetId || matchingAsset.id !== assetId) {
            throw SAMError.create(SAMErrorCode.CONFLICT, 'The asset name must be unique within the parent asset.');
        }
    }
}

/**
 * Cleans an asset name by removing reserved characters and truncating the name to the specified length.
 * @throws {SAMError} When {@link shouldValidate} is true and if the name is invalid
 */
export const cleanAssetName = ({ name, maxLength = MAX_LENGTH, shouldValidate = false }: CleanAssetNameOptions) => {
    // RESERVED_NAME_REGEX is not used here since replacing it would result in an empty string
    const cleanedName = name.replaceAll(new RegExp(RESERVED_CHAR_REGEX, 'g'), '')
        .substring(0, maxLength)
        // eslint-disable-next-line no-control-regex
        .replace(/[\u{0000}-\u{001F}|\u{007F}]+/gu, '') // Replace invalid unicode characters
        .replace(/[\s|.]+$/g, ''); // Replace trailing periods and whitespace

    if (shouldValidate) {
        validateAssetName({ name: cleanedName });
    }

    return cleanedName;
};

/**
 * Checks if a path is a top-level folder
 * @param path The path to check
 * @returns true if the path matches /, /xyz, /users/xyz, or /users/xyz/xyz
 */
export function isTopLevelFolder(path: string): boolean {
    return /^(\/|\/users\/[^/]+|\/users\/[^/]+\/[^/]+|\/[^/]+)$/.test(path);
}

export function isUserHomeFolder(path: string): boolean {
    return /^(\/|\/users\/[^/]+\/?)$/.test(path);
}
