import type { IImplicitFilter } from '../core/ItemFilter';
import type { default as AdobeAsset } from './AdobeAsset';
import ImplicitAdobeAssetFilterBase from './ImplicitAdobeAssetFilterBase';

/**
 * @TODO We should open this up to allow clients to configure the restrictions
 * on this query through the filter options below.
 * https://jira.corp.adobe.com/browse/SAM-2542
 */
export interface IAdobeAssetGlobalSearchFilterOptions {
    /**
     * @package -- only for use by implicit filter
     */
    readonly _query: string;
    readonly _matchingIDsFromSearch: Set<string>;
    readonly _projectsOnly: boolean;
}

export default class AdobeAssetGlobalSearchFilter extends ImplicitAdobeAssetFilterBase implements IImplicitFilter<AdobeAsset> {
    _query: string = '';

    /**
     * @package -- only for use by AdobeAssetGlobalSearchFilter/Loader
     */
    _matchingIDsFromSearch: Set<string> | undefined;

    /**
     * @package only for use by AdobeAssetGlobalSearchFilter/Loader
     */
    _projectsOnly: boolean = false;

    constructor(options?: Partial<IAdobeAssetGlobalSearchFilterOptions>) {
        super({ _isSharedWithYou: true });
        this._query = options?._query || '';
        this._projectsOnly = options?._projectsOnly || false;
    }
    get query(): string {
        return this._query;
    }

    get projectsOnly(): boolean {
        return this._projectsOnly;
    }

    // The matching rules USS are deceptively complex, and could change over time. Attempting to
    // replicate here could result in items being incorrectly filtered out or incorrectly included.
    // Global search Lists should not try to share items from Lists with similar queries, other
    // than treating the queries as case-insensitive.
    matches(item: AdobeAsset): boolean {

        // Check if the item's id is in the current filter's id list
        if (this._matchingIDsFromSearch && !this._matchingIDsFromSearch.has(item.id)) {
            return false;
        }

        // If the query exists but there's no id list, we probably haven't finished loading yet
        if ((this._query) && !this._matchingIDsFromSearch) {
            return false;
        }
        return super.matches(item);
    }
}
