/**
 * Clamps a value to a minimum, maximum, or range
 *  @example <caption>Clamp to minimum of 4</caption>
 *  clamp(5, 4); // returns 4
 *  @example <caption>Clamp to a maximum of 3</caption>
 *  clamp(5, undefined, 3); // returns 3
 *  @example <caption>Clamp to a range 3 - 6</caption>
 *  clamp(5, 3, 6); // returns 5
 *
 * @param value {number} Value to be clamped
 * @param min {number|undefined} Minimum value
 * @param max {number|undefined} Maximum value
 * @return {number} Value that is clamped to be >= min (if provided) and <= max (if provided), or value if it is
 *          within range
 */

function clamp(value: number, min: undefined, max: number): number;
function clamp(value: number, min: number, max?: number): number;
function clamp(value: number, min?: number, max?: number): number {
    if (min !== undefined && value < min) { return min; }
    if (max !== undefined && value > max) { return max; }
    return value;
}

export default clamp;
