import AdobeAsset, { StorageAssigneeFormat } from '../assets/AdobeAsset';
import ItemUpdater from '../core/ItemUpdater';
import type { GenerationHistoryAssetData } from '../interface/GenerationHistoryAssetModel';
import { GENERATION_HISTORY_MEDIA_TYPES } from '../interface/GenerationHistoryAssetModel';
import PropertyUpdater from '../core/PropertyUpdater';

type GenerationModelDisplayName = 'Imagen' | 'Veo' | 'GPT' | 'Clio' | 'Firefly' | 'Flux' | 'Pika' | 'Ideogram' | 'Runway' | 'Luma' | 'Topaz' | 'ElevenLabs' | 'Moonvalley' | 'Gemini Flash' | 'Topaz' | 'Sora';

// maps internal generation model names to a display name to be used in 3rd party APIs
const GET_GENERATION_MODEL_DISPLAY_NAME: Record<string, GenerationModelDisplayName> = {
    'imagen': 'Imagen',
    'veo': 'Veo',
    'gpt-4o-image': 'GPT',
    'clio': 'Firefly',
    'clio_v4': 'Firefly',
    'clineto': 'Firefly',
    'image5_standard': 'Firefly',
    'flux': 'Flux',
    'fluxPro': 'Flux',
    'fluxUltra': 'Flux',
    'fluxBagel': 'Flux',
    'fluxKontextPro': 'Flux',
    'fluxKontextMax': 'Flux',
    'pika': 'Pika',
    'ideogram': 'Ideogram',
    'runway-gen4-image': 'Runway',
    'runway': 'Runway',
    'luma': 'Luma',
    'topaz': 'Topaz',
    'elevenlabs': 'ElevenLabs',
    'moonvalley': 'Moonvalley',
    'gemini-flash': 'Gemini Flash',
    'topaz_onprem': 'Topaz',
    'audio_gensoundfx': 'Firefly',
    'gen_music': 'Firefly',
    'sora': 'Sora',
    'lego_pipeline': 'Firefly'
} as const;

export const getGenerationModelDisplayName = (model: string): GenerationModelDisplayName | string => {
    return GET_GENERATION_MODEL_DISPLAY_NAME[model] ?? model;
};

export const GenerationHistoryAssetUpdater = new ItemUpdater<AdobeAsset, Partial<GenerationHistoryAssetData>>({
    localItemType: AdobeAsset,
    remoteIdProperty: 'asset_id',
    propertyUpdater: new PropertyUpdater({
        '_appMetadata._data': {
            name: 'applicationMetadata',
            format: 'object_subset',
            set: (parsedSource: any, dest: any) => {
                const asset = dest as AdobeAsset;
                asset.appMetadata._mergeData(parsedSource);
            }
        },
        _isFavorite: { name: 'isFavorite', format: 'boolean' },
        _assetClass: { get: () => 'composite' },
        _generationModelDisplayName: 'generationModelDisplayName',
        _name: 'repo:name',
        _size: { name: 'repo:size', format: 'number' },
        _type: { name: 'type', format: 'string', choices: GENERATION_HISTORY_MEDIA_TYPES },
        __links: { name: '_links', format: 'object' },
        _created: { name: 'createdDate', format: 'date' },
        _modified: { name: 'modifiedDate', format: 'date' },
        _etag: 'composite_manifest_etag',
        _path: { get: (parsedSource) => {
            const path = parsedSource.asset_name_path;

            // We need to normalize the path returned by Melville listings to match the repo:path, otherwise assets will get filtered out by the ImplicitGenerationHistoryAssetFilter.
            // Check to see if path ends with `/firefly-generations` and if so, we append a "/" and the asset name to match the repo:path.
            if (path.endsWith('/firefly-generations')) {
                return `${path}/${parsedSource['repo:name']}`;
            }

            return path;
        } },
        _repositoryID: 'repo:repositoryId',
        _createdBy: 'repo:createdBy',
        _modifiedBy: 'repo:modifiedBy',
        _storageAssignee: { name: 'storage:assignee', format: StorageAssigneeFormat },
    }),
});
