import Post, { getChildPostUpdater } from './Post';
import ItemUpdater from '../core/ItemUpdater';
import { PostModerationStatus, type RemoteTextPost } from '../interface/BoardModel';
import type { SAM } from '@ccx-public/component-types';
import { observable } from '@sam-js-src/core/decorators';

/** Represents a post for a Board which contains text and color */
class TextPost extends Post implements SAM.TextPost {
    private _text!: string;
    private _backgroundColor: string | undefined;
    private _textStatus: PostModerationStatus | undefined;

    /** The text content of the post */
    get text(): string {
        return this._text;
    }

    /** The background color of the text post. */
    @observable
    get backgroundColor(): string | undefined {
        return this._backgroundColor;
    }

    /** Returns the moderation status of the post text. Temporarily may return undefined based on Board migration status */
    @observable
    get textStatus(): PostModerationStatus | undefined {
        return this._textStatus;
    }

    /**
     * Triggers the reclassification of the Post text through ACMP
     * @experimental Text moderation work is in progress
     */
    async reclassifyText(): Promise<void> {
        return this._ensureBoardContext().reclassifyTextPost({ boardId: this.boardId, postId: this.id });
    }

    /**
     * Approves a TextPost that has been flagged for review.
     * @experimental Text moderation work is in progress
     */
    approveText(): Promise<void> {
        return this._ensureBoardContext().approveTextPost({ boardId: this.boardId, postId: this.id });
    }

    /**
     * Rejects a TextPost that has been flagged for review.
     * @experimental Text moderation work is in progress
     */
    rejectText(): Promise<void> {
        return this._ensureBoardContext().rejectTextPost({ boardId: this.boardId, postId: this.id });
    }
}

const TextPostUpdater = new ItemUpdater<TextPost, Partial<RemoteTextPost>>({
    localItemType: TextPost,
    remoteIdProperty: 'id',
    propertyUpdater: getChildPostUpdater({
        _text: { name: 'board#postText', format: 'string' },
        _backgroundColor: { name: 'board#postBackgroundColor', format: 'string' },
        _textStatus: { name: 'board#postTextStatus', format: 'string', choices: Object.values(PostModerationStatus) },
    })
});

export default TextPost;
export { TextPostUpdater };
