import { gql } from '@apollo/client';

export const recents = gql` query PLSRecents($first: Int!, $after: String, $filter: AssetListFilter) {
  recents {
    assetListId
    assetListConnection(first: $first, after: $after, filter: $filter) {
      pageInfo {
        endCursor
        hasNextPage
      }
      edges {
        cursor
        node {
          ... on Asset {
            dc_format
            repo_assetId
            repo_name
            repo_path
            primary_etag
            repo_representations {
              composite
              directory
              file
            }
            repo_state
            repo_ancestors
            repo_ancestorInfo{  
                assetId
                assetSubType
                assetType
            }
            repo_createDate
            repo_modifyDate
            repo_modifiedBy
            repo_createdBy {
              id
            }
            storage_region
            storage_deviceCreateDate
            storage_deviceModifyDate
            storage_assignee {
              id
              type
            }
            repo_assetClass
            repo_assetType
            repo_assetSubType
            repository {
              repo_repositoryId
            }
            sharingInfo {
              sharedWithYou {
                shareTypes
                shareDate
                sharedBy {
                  id
                }
              }
            }
            effectivePermissions {
              aclPolicy
              annotations
              applicationMetadata
              default
              directory
              primary
            }
            primaryLink {
              href
            }
            blockUploadLink {
              href
            }
            labels {
              lastAccessDate
            }
            ... @defer {
              appMetadata {
                am: valueOf(key: "")
              }
            }
            ... on Composite {
              repo_version
              repo_size
              isComposite
              blockDownloadLink {
                href
              }
              renditionLink {
                href
              }
              componentLink {
                href
              }
            }
            ... on File {
              repo_version
              repo_size
              isFile
              blockDownloadLink {
                href
              }
              renditionLink {
                href
              }
              tiff_imageLength
              tiff_imageWidth
            }
          }
        }
      }
    }
  }
}
`;
