import type IEvent from './IEvent';

/**
 * Base class for all events sent out from SAMJS.
 */
export default class SAMEvent implements IEvent {
    constructor(private _type: string) {
    }

    get type(): string {
        return this._type;
    }

    toString(): string {
        return `SAMEvent(${this._type})`;
    }
}
