export type RenditionSizeConfig = { [elementType: string]: Array<number> };
export type FullRenditionConfig = {
    [type: string]: [
        {
            id: string;
            condition: string;
            types: Array<string>;
        }
    ];
};

export function compareVersions(version1: string, version2: string) {
    //After effects does not use semver. They append a x before the build number.
    //We need to replace that with a .
    version1 = (version1 || '0')
        .toString()
        .replace(/(\.0)*$/, '')
        .replace(/[^.0-9]+/gim, '.');
    version2 = (version2 || '0')
        .toString()
        .replace(/(\.0)*$/, '')
        .replace(/[^.0-9]+/gim, '.');
    //Workaround for Illustrator CS6 & Illustrator CC returning version as CS6 and the build number instead of semver
    if (isNaN(parseInt(version1, 10)) || parseInt(version1, 10) > 250) {
        version1 = '0';
    }
    if (isNaN(parseInt(version2, 10)) || parseInt(version2, 10) > 250) {
        version2 = '0';
    }
    if (version1 === version2) {
        return 0;
    }
    const a1 = version1.split('.');
    const a2 = version2.split('.');
    let diff;
    for (let i = 0; i < a1.length && i < a2.length; i++) {
        diff = parseInt(a1[i], 10) - parseInt(a2[i], 10);
        if (isNaN(diff)) {
            if (isNaN(parseInt(a1[i], 10))) {
                return 1;
            }
            return -1;
        }
        if (diff > 0) {
            return -1;
        }
        if (diff < 0) {
            return +1;
        }
    }
    diff = a1.length - a2.length;
    return diff > 0 ? -1 : diff < 0 ? 1 : 0;
}
