import type { IImplicitFilter } from '../core/ItemFilter';
import type { default as AdobeAsset } from './AdobeAsset';
import ImplicitAdobeAssetFilterBase from './ImplicitAdobeAssetFilterBase';

export default class RecentAdobeAssetFilter extends ImplicitAdobeAssetFilterBase implements IImplicitFilter<AdobeAsset> {
    /**
     * @package -- only for use in SAM.js
     */
    _lastModificationDate: Date | undefined;
    constructor() {
        super({ _isSharedWithYou: true });
    }

    matches(item: AdobeAsset): boolean {
        // We don't want folders to match the Recents filter
        if (item.isFolder) {
            return false;
        }
        if (this._lastModificationDate && item.modified < this._lastModificationDate) {
            return false;
        }
        return super.matches(item);
    }
}

