import { RelType } from '../interface/LinkUtils';
import type AdobeAsset from './AdobeAsset';
import type { ISAMCorePrivate } from '../indexPrivate';
import type SAMError from '../core/SAMError';
import { SAMErrorCode } from '../core/SAMError';
import AdobeAssetResource from './AdobeAssetResource';

export default class EmbeddedMetadataResource extends AdobeAssetResource<any> {

    constructor(
        readonly _core: ISAMCorePrivate,
        readonly _parent: AdobeAsset,
    ) {
        super(_core, _parent, {
            onError: async (error) => {
                if ((error as SAMError).code === SAMErrorCode.NOT_FOUND) {
                    // If an asset doesn't have embedded metadata, just return empty metadata rather than
                    // treating it as a failure.
                    await this._setData({});
                }
            }
        });
    }

    protected async _loadData() {
        await this._parent._ensureLink(RelType.EMBEDDED_METADATA);
        const assetInterface = await this._parent._getAssetInterface();
        await assetInterface.getEmbeddedMetadata(this);
    }
}
