import ItemUpdater from '../core/ItemUpdater';
import PropertyUpdater from '../core/PropertyUpdater';
import FrameioBase from './FrameioBase';
import type { IFrameioCommentResponse, IFrameioLikeResponse } from './FrameioInterface';
import type { ISAMObject } from '../core/ISAMObject';
import type FrameioComment from './FrameioComment';
import { FrameioCommentUpdater } from './FrameioComment';

// See https://developer.frame.io/api/reference/operation/createCommentImpressionLike/
//  for schema of IFrameioLikeResponse, aka response.type="like".

export default class FrameioLike extends FrameioBase {
    // Frame.io uses { myString : null } for unspecified
    // values, which causes our updater to set the string
    // property to undefined, but our getters substitute
    // '' for undefined, so our clients aren't exposed to this.
    private _anonymousUserId?: string;
    private _comment?: FrameioComment;
    private _commentId?: string;
    private _deletedAt?: Date;
    private _insertedAt?: Date;
    private _updatedAt?: Date;
    private _userId?: string;

    get anonymousUserId(): string {
        return this._anonymousUserId || '';
    }

    get comment(): FrameioComment | undefined {
        return this._comment;
    }

    get commentId(): string {
        return this._commentId || '';
    }

    get deletedAt(): Date | undefined {
        return this._deletedAt;
    }

    get insertedAt(): Date | undefined {
        return this._insertedAt;
    }

    get updatedAt(): Date | undefined {
        return this._updatedAt;
    }

    get userId(): string {
        return this._userId || '';
    }
}

export const FrameioLikeUpdater = new ItemUpdater<FrameioLike, Partial<IFrameioLikeResponse>>({
    localItemType: FrameioLike,
    remoteIdProperty: 'id',
    propertyUpdater: new PropertyUpdater({
        '_anonymousUserId': 'anonymous_user_id',
        '_comment': {
            // The comment property of an IFrameioLikeResponse is a nested
            // object of type IFrameioCommentResponse, so let's update it!
            set: (comment: IFrameioCommentResponse, dest: ISAMObject) => {
                const like = dest as FrameioLike;
                const context = like.context;
                const pool = context._objectPool;

                const session = pool.createUpdateSession<FrameioComment>();
                like['_comment'] = FrameioCommentUpdater.updateRemoteItem(session, comment);
                session.commit();
            },
            name: 'comment',
            format: 'object'
        },
        '_commentId': 'comment_id',
        '_deletedAt': { name: 'deleted_at', format: 'date' },
        '_insertedAt': { name: 'inserted_at', format: 'date' },
        '_updatedAt': { name: 'updated_at', format: 'date' },
        '_userId': 'user_id'
    })
});
