import type { AssignmentSubmissionOwnershipEnums } from '../interface/AssignmentModel';
import type { IExplicitFilter, ItemFilterRelation } from '../core/ItemFilter';
import type Assignment from './Assignment';
import type AdobeAsset from '../assets/AdobeAsset';
import SAMError, { SAMErrorCode } from '../core/SAMError';

export interface IAssignmentFilterOptions {
    classroomId?: string;
    campaignId?: string;
    submissions?: AssignmentSubmissionOwnershipEnums;
    profiles?: string;
}

/**
 * Filter for assignments based on various criteria:
 * - To get assignments for the current profile (default): new AssignmentFilter({ classroomId: 'id' })
 * - To get assignments for a specific profile: new AssignmentFilter({ classroomId: 'id', profiles: 'profileId' })
 * Note: profiles='ALL' is not supported for assignments for now
 */
export default class AssignmentFilter implements IExplicitFilter<Assignment> {
    public classroomId?: string;
    public campaignId?: string;
    public submissions?: AssignmentSubmissionOwnershipEnums | undefined;
    public profiles?: string;

    /**
     * @package -- only for use in SAM.js
     */
    public _monitoredFolder?: AdobeAsset;

    /**
     * @throws {SAMError} if both classroomId and campaignId are provided or neither are provided
     * @package -- only for use in SAM.js
     */
    constructor(options: Partial<IAssignmentFilterOptions> = {}) {
        this.classroomId = options.classroomId || '';
        this.campaignId = options.campaignId || '';
        // We don't have any use cases where we would filter by both classroomId and campaignId or neither
        // so we throw an error if both are provided or neither are provided
        if (this.campaignId && this.classroomId) {
            throw SAMError.create(SAMErrorCode.UNSUPPORTED, 'Cannot filter by both campaignId and classroomId');
        } else if (!this.campaignId && !this.classroomId) {
            throw SAMError.create(SAMErrorCode.UNSUPPORTED, 'Must filter by either campaignId or classroomId');
        }
        this.submissions = options.submissions;
        this.profiles = options.profiles;
    }

    matches(item: Assignment): boolean {
        if (!item.isAssignment) {
            return false;
        }

        if (this.classroomId && item.classroomId !== this.classroomId) {
            return false;
        }
        if (this.campaignId && item.campaignId !== this.campaignId) {
            return false;
        }
        if (item.isDiscarded) {
            return false;
        }

        return true;
    }

    getRelationToFilter(other: AssignmentFilter): ItemFilterRelation {
        // Consider all subset cases first
        if (this.classroomId && this.classroomId === other.classroomId) {
            return 'subset';
        } else if (this.campaignId && this.campaignId === other.campaignId) {
            return 'subset';
        }

        return 'disjoint';
    }

    get hash(): string {
        return `classroomId=${this.classroomId}&campaignId=${this.campaignId}`;
    }
}
