import type {
    IAppMetadata,
    RepositoryMetadata
} from './RepositoryModel';
import type { UploadedFromType } from '../assets/USSAdobeAssetFilter';
import type { AdobeAssetOrderField } from '../assets/AdobeAssetOrder';
import type { IOrderDirection } from '../core/ItemOrder';
import type { USSAdobeAssetOrderField } from '../assets/USSAdobeAssetOrder';
import type { ValueOf } from '../core/ObjectUtils';
import { EXPRESS_ARTIFACT_TYPE } from '../utils/excludeExpressArtifacts';

export const USSv3OrderField = {
    Created: 'rm.storage:deviceCreateDate',
    Modified: 'rm.storage:deviceModifyDate',
    Name: 'rm.repo:name',
    Relevance: { 'function:relevance': {} }
} as const;


export const USSv3OrderFieldMap: Record<AdobeAssetOrderField | USSAdobeAssetOrderField, ValueOf<typeof USSv3OrderField>> = {
    'name': USSv3OrderField.Name,
    'created': USSv3OrderField.Created,
    'modified': USSv3OrderField.Modified,
    'relevance': USSv3OrderField.Relevance,
    // TODO: add USSv3 shareDate sorting
    'shared': USSv3OrderField.Modified,
    // TODO: add v3 lastAccessed sorting
    'lastAccessed': USSv3OrderField.Modified
} as const;

export enum USSv3OrderDir {
    Ascending = 'ASC',
    Descending = 'DESC'
}

export const USSv3OrderDirMap: Record<IOrderDirection, USSv3OrderDir> = {
    'ascending': USSv3OrderDir.Ascending,
    'descending': USSv3OrderDir.Descending
} as const;

export interface ISearchQueryEntrySort {
    sortOrderBy: ValueOf<typeof USSv3OrderField>;
    sortOrder: USSv3OrderDir;
}

export enum USSv3FilterField {
    MEDIA_TYPE = 'rm.dc:format',
    DIRECTORY_TYPE = 'am.project:directoryType',
    REVIEW_SOURCE_TYPE = 'am.review:sourceAsset.dc:format',
    STORAGE_ASSIGNEE_TYPE = 'rm.storage:assignee.type',
    PARENT_ID = 'rm.parentDirectoryId',
    REPO_ANCESTORS = 'rm.repo:ancestors',
    SHELL_VISIBILITY = 'am.shell:visibility',
    TOP_LEVEL_COLLECTION_NAME = 'rm.topLevelCollectionName',
    STORAGE_ASSIGNEE_ID = 'rm.storage:assignee.id',
    CREATED_FROM_UPLOAD = 'am.cc:createdFromUpload',
    CREATED_BY_CLIENT_ID = 'rm.repo:createdByClientId',
    ASSET_TYPE = 'rm.repo:assetType',
    ASSET_SUB_TYPE = 'rm.repo:assetSubType'
}

export enum USSv3Function {
    MISSING  = 'function:missing',
    NOT = 'function:not'
}

export enum USSv3DirectoryType {
    PROJECT = 'team'
}

export type USSv3InheritanceTypeField = 'am.cc:inherited.cc:studentAssignment.repo:assetId'
    | 'am.cc:inheritable.cc:studentAssignment.repo:assetId'
    | 'am.cc:inherited.cc:assignmentMaterials.repo:assetId'
    | 'am.cc:inheritable.cc:assignmentMaterials.repo:assetId'
    | 'am.cc:inherited.cc:assignment.repo:assetId'
    | 'am.cc:inheritable.cc:assignment.repo:assetId'
    /** old Projects v2 teams ? */
    | 'am.cc:inheritable.cc:team.repo:assetId'
    | 'am.cc:inherited.cc:team.repo:assetId'
;



export interface ISearchQueryEntryFilter {
    [USSv3FilterField.MEDIA_TYPE]?: string[];
    [USSv3FilterField.DIRECTORY_TYPE]?:  USSv3DirectoryType[];
    [USSv3FilterField.REVIEW_SOURCE_TYPE]?: string[];
    [USSv3FilterField.STORAGE_ASSIGNEE_TYPE]?: 'user';
    [USSv3FilterField.STORAGE_ASSIGNEE_ID]?: string;
    [USSv3FilterField.PARENT_ID]?: string;
    [USSv3FilterField.REPO_ANCESTORS]?: string;
    [USSv3FilterField.SHELL_VISIBILITY]?: ('hiddenSelf' | 'hiddenRecursive')[];
    [USSv3FilterField.TOP_LEVEL_COLLECTION_NAME]?: 'appdata';
    [USSv3FilterField.CREATED_FROM_UPLOAD]?: boolean;
    [USSv3FilterField.CREATED_BY_CLIENT_ID]?: UploadedFromType;
    [USSv3FilterField.ASSET_TYPE]?: string[];
    [USSv3FilterField.ASSET_SUB_TYPE]?: string[];

    [USSv3Function.NOT]?: {
        funcParams: ISearchQueryEntryFilter
    };

    /** To match a specific Asset, it must be missing the fields specified in `funcParams` */
    [USSv3Function.MISSING]?: {
        funcParams: {
            fields: USSv3InheritanceTypeField[]
        }
    }
}

export enum FetchFields {
    SharedBy = 'cm.sharedBy',
    LastAccessDate = 'am.shell:lastActivity.date',
    ShellVisibility = 'am.shell:visibility',
    Collaborator =  'cm.collaborator',
    PublicCollaborator = 'cm.publicCollaborator',
    ParentProjectId = 'am.cc:inherited.cc:team.repo:assetId',
    StudentAssignmentAssetId = 'am.cc:inherited.cc:studentAssignment.repo:assetId',
    StudentAssignmentDirectoryId = 'am.cc:inheritable.cc:studentAssignment.repo:assetId',
    AssignmentAssetId = 'am.cc:inherited.cc:assignment.repo:assetId',
    // We need both projects and its children to show up in global search
    CCInherited = 'am.cc:inherited',
    CCInheritable = 'am.cc:inheritable',
    // App metadata field required for Express
    HzDocumentMetadata = 'am.hz:documentMetadata',
    CreatedFromUpload = 'am.cc:createdFromUpload',
    CreatedByClientId = 'rm.createdByClientId',
    ReviewSourceAsset = 'am.review:sourceAsset',
    ReviewSourceAssetType = 'am.review:sourceAsset.dc:format',
    ConvertedTo = 'am.convertedTo',
    NonAutoMigratable = 'am.ccx:nonAutoMigratableCopiedFromId',
    CopiedLegacySparkId = 'am.ccx:copiedLegacySparkId'
}

export interface ISearchQueryEntry {
    start: number;
    limit: number;
    id?: string;
    textQuery?: string;
    sorts?: ISearchQueryEntrySort[];
    scope?: { entities: ('AcpAsset' | 'DMeEnterpriseAsset')[] };
    filters?: ISearchQueryEntryFilter[];
    fetchFields?: FetchFields[];
}

export interface ISearchQuery {
    experienceId: string;
    queries: ISearchQueryEntry[];
}

type USSQueryResults = {
    id: string;
    status: { httpCode: number; };
    metadata: {
        totalHits: number;
        start: number;
        limit: number;
    };
    items?: USSItemMetadata[];
}

export type USSResponse = {
    experienceId: string;
    status: { httpCode: number; };
    queryResults: USSQueryResults[];
}

export type USSItemMetadata = {
    id: string;
    cm: {
        sharedBy: string[]
    };
    rm: RepositoryMetadata;
    am: IAppMetadata;
};

export function excludeExpressArtifacts(): ISearchQueryEntryFilter {
    return {
        [USSv3Function.NOT]: { funcParams: { [USSv3FilterField.REVIEW_SOURCE_TYPE]: [ EXPRESS_ARTIFACT_TYPE ] } }
    };
}
