import type { SpaceSearchConfig } from './SpaceSearchSource';
import type ItemPool from '../core/ItemPool';
import type AdobeAsset from './AdobeAsset';
import type { USSMetadata, USSResponse } from '../interface/USSModel';
import { OrderByToUSSOrderBy } from '../interface/USSModel';
import SAMError, { SAMErrorCode } from '../core/SAMError';
import type { ISpaceSearchAssetFilterOptions } from './SpaceSearchAssetFilter';
import type SpaceSearchAssetFilter from './SpaceSearchAssetFilter';
import type USSInterface from '../interface/USSInterface';
import type { IGetUSSResults, IUSSLoader } from './USSLoaderHelper';
import USSLoaderHelper from './USSLoaderHelper';
import type { IItemLoaderOptions, ILoadedPage } from '../core/ItemLoader';
import type { ISAMCorePrivate } from '../indexPrivate';

export default class SpaceSearchAssetLoader implements IUSSLoader<SpaceSearchConfig> {
    private _ussLoaderHelper: USSLoaderHelper<SpaceSearchConfig>;

    constructor(
        assetPool: ItemPool<AdobeAsset>,
        core: ISAMCorePrivate,
        private _asset: AdobeAsset,
        private _ussInterface: USSInterface,
        private _artifactFilter: ISpaceSearchAssetFilterOptions['artifactFilter'],
        private _embedPermissions: boolean = false
    ) {
        this._ussLoaderHelper = new USSLoaderHelper(assetPool, core, this);
    }

    supportsFilter(filter: any): boolean {
        const supportedFilters: SpaceSearchAssetFilter[] = [];
        supportedFilters.push(filter);

        // Client can call getList with SpaceSearchAssetFilter.artifactFilter undefined, but can't pass
        // SSAF.artifactFilter that doesn't match this._artifactFilter
        if (!supportedFilters.every(f => (f.artifactFilter === this._artifactFilter || f.artifactFilter === undefined))) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST,
                'SpaceSearchAssetFilter.artifactFilter does not match SpaceSearchAssetLoader.artifactFilter');
        }
        return true;
    }

    loadPage(options: IItemLoaderOptions<SpaceSearchConfig>): Promise<ILoadedPage<SpaceSearchConfig>> {
        return this._ussLoaderHelper.loadPage(options);
    }

    /**
     * @package -- for use by USSLoaderHelper
     */
    async _getUSSResults({
        start,
        loadOptions,
        order,
        mediaTypes
    }: IGetUSSResults<SpaceSearchConfig>): Promise<USSResponse> {
        return this._ussInterface.searchSpace(
            this._asset.id,
            this._artifactFilter === 'onlyArtifacts',
            this._embedPermissions,
            {
                type: mediaTypes,
                sort_orderby: OrderByToUSSOrderBy[order.field],
                sort_order: order.direction === 'descending' ? 'desc' : 'asc',
                limit: loadOptions?.limit,
                start_index: start
            }
        );
    }

    /**
     * @package -- for use by USSLoaderHelper
     */
    _getItemData: (item: Partial<USSMetadata>) => Partial<USSMetadata> = this._getItemDataWithRepoId(this._asset.repositoryID);

    private _getItemDataWithRepoId(repoID: string) {
        // TODO: Patching should be removed once https://jira.corp.adobe.com/browse/SRCH-1989 is fixed
        //       and re-indexing is finished, which has ETA of Feb 28 2023
        return (item: Partial<USSMetadata>) => {
            return {
                ...item,
                'repo:repositoryId': repoID
            };
        };
    }
}
