import { isPlaceholder } from '../models/utils';

const stripWhitespace = (str: string) => str.replace(/ |\t|\n/g, '');

const elementRegex = /^(\$\.(?:elements|removedElements|documentationElements))\[\?\(@\.id=="([^"]+)"\)\]$/;
const groupRegex = /^\$\.groups\[\?\(@\.id=="([^"]+)"\)\]$/;

export function extractElementId(path: string): string | undefined {
    path = stripWhitespace(path);
    const [ , , elementId ] = elementRegex.exec(path) || [];
    return elementId;
}

export function extractElementCollection(path: string): string | undefined {
    path = stripWhitespace(path);
    const [ , elementCollection ] = elementRegex.exec(path) || [];
    return elementCollection;
}

export function extractGroupId(path: string): string | undefined {
    path = stripWhitespace(path);
    const [ , groupId ] = groupRegex.exec(path) || [];
    return groupId;
}

export function getPlaceholderId(path: string) {
    const id = extractElementId(path) || (extractGroupId(path) as string);
    return isPlaceholder(id) && id;
}

export function replaceId(path: string, oldId: string, newId: string) {
    return path.replace(oldId, newId);
}
