import type AdobeAsset from './AdobeAsset';
import type { AssetSubType, AssetType } from '../interface/AssetModel';
import { getRapiAppMetadataSelectors } from '../interface/AssetModel';
import type { IItemLoader, IItemLoaderOptions, ILoadedPage, ILoadNextPage } from '../core/ItemLoader';
import type ItemPool from '../core/ItemPool';
import type { AdobeAssetConfig } from './AdobeAssetSource';
import type AdobeAssetFilter from './AdobeAssetFilter';
import { OrderFieldToIAdobeAssetOrderBy } from './AdobeAssetOrder';
import { RelType } from '../interface/LinkUtils';
import type { EmbedSpecifier, RepositoryMetadata } from '../interface/RepositoryModel';
import type { ISAMCorePrivate } from '../indexPrivate';
import type Library from '../libraries/Library';
import type { LibraryData, LibrarySpecificData } from '../interface/LibraryModel';
import SAMError, { SAMErrorCode } from '../core/SAMError';
import { SharedStorageAssigneeChangedEvent } from './AssetEvents';
import { LazyLoadManager } from '../core/decorators/LazyLoadManager';
import type { AdobeAssetUpdaterMetadata } from './AdobeAsset';
import { getMediaTypesFromFilters, getMostRecentValidMutation } from '@sam-js-src/utils/loaderUtils';

export default class AdobeAssetDirectoryLoader implements IItemLoader<AdobeAssetConfig> {

    constructor(
        private _assetPool: ItemPool<AdobeAsset>,
        private _asset: AdobeAsset,
        private _core: ISAMCorePrivate,
        private _includePermissions?: boolean,
        private _loadLibraryData?: boolean
    ) {
    }

    supportsFilter(filter?: AdobeAssetFilter): boolean {
        // TODO: ?? can be undefined but can't be undefined ??
        return filter !== undefined;
    }

    async loadPage(options: IItemLoaderOptions<AdobeAssetConfig>): Promise<ILoadedPage<AdobeAssetConfig>> {
        return await this._loadPage(options);
    }

    private async _loadPage(options: IItemLoaderOptions<AdobeAssetConfig>, pageCursor?: string): Promise<ILoadedPage<AdobeAssetConfig>> {
        const { order, filter, implicitFilter, resource } = options;
        const { limit } = options.loadOptions ?? {};
        const mediaTypes = getMediaTypesFromFilters(implicitFilter, filter);

        /* Note: re-evaluate this after we have more data about the Project.libraries use case
         * We're currently calling for melville data for every page load.
         * We don't think it's a problem because it reduces code complexity and
         * we predict the standard use case to be just one page of libraries.
         * If that changes in future, we should re-evaluate this strategy.
         */
        let librariesDataPromise = undefined;

        /**
         * Project.librariesSource will set _loadLibraryData but mediaTypes filtering is done in the implicit filter,
         * so mediaTypes here could be empty.
         * Project.children will be up to the client to include/exclude Libraries based on explicit mediaTypes/excludeMediaTypes filter.
         */
        const loadLibraries = this._loadLibraryData && (
            !mediaTypes.length || mediaTypes.includes('application/vnd.adobe.library+dcx')
        ) && !filter.excludeMediaTypes?.has('application/vnd.adobe.library+dcx');
        if (loadLibraries) {
            if (!this._asset.isProject) {
                throw SAMError.create(SAMErrorCode.UNSUPPORTED, `Asking for child libraries from non-project asset with id: ${this._asset.id}`);
            } else {
                // TODO [SHARED-975]: This doesn't fetch subsequent pages (max list of 50). Needs to go through the LibraryListLoader.
                librariesDataPromise = this._core.hostAssetContext._libraryInterface.getLibrariesForProject(this._asset.id);
            }
        }

        let childrenData: AdobeAssetUpdaterMetadata[] | undefined;
        let nextPageCursor: string | undefined;
        let ancestors: string[] | undefined;

        const useGraphQL = this._core._environment.getValue('FEATURE_FLAGS')?.['use-graphql'];
        if (useGraphQL) {
            const gqlManager = await this._core._getGQLManager();
            const listData = await gqlManager.getChildren(this._asset.id, {
                filter,
                order,
                loadOptions: {
                    limit
                },
                after: pageCursor
            }, resource, this._asset.storageRegion);
            childrenData = listData.children;
            ancestors = listData.ancestors;
            nextPageCursor = listData.pageInfo.hasNextPage ? (listData.pageInfo.endCursor ?? undefined) : undefined;
        } else {
            const embed: EmbedSpecifier[] = [ {
                'resource': {
                    'reltype': RelType.APP_METADATA
                },
                'selectors': getRapiAppMetadataSelectors()
            } ];
            if (this._includePermissions) {
                embed.push(
                    {
                        'resource': {
                            'reltype': RelType.AC_EFFECTIVE
                        }
                    }
                );
            }

            // SAM-3087: USS doesn't include PAGE link
            await this._asset._ensureLink(RelType.PAGE);
            const assetInterface = await this._asset._getAssetInterface();
            const rapiPage = await assetInterface.getChildAssets({
                orderBy: OrderFieldToIAdobeAssetOrderBy[order.field],
                orderDirection: order.direction,
                start: pageCursor,
                limit,
                type: mediaTypes,
                filters: {
                    assetTypes: [ ...(filter.assetTypes || []) as AssetType[] ],
                    excludeAssetTypes: [ ...(filter.excludeAssetTypes || []) as AssetType[] ],
                    assetSubTypes: [ ...(filter.assetSubTypes || []) as AssetSubType[] ],
                },
                embed
            }, resource);

            ancestors = rapiPage['repo:ancestors'];
            childrenData = rapiPage.children;
            nextPageCursor = rapiPage._page.next;
        }

        if (this._asset.isProject && ancestors) {
            this._patchProjectAncestors(ancestors);
        }

        childrenData = childrenData.map((item) => {
            // Directory listings don't include repo:ancestors, but since we know the parent asset,
            // we can construct it based on the parent's repo:ancestors
            if (!item['repo:ancestors']) {
                item['repo:ancestors'] = [ ...(this._asset.ancestorIDs ?? []), this._asset.id ];
            }
            return item;
        });

        const updaters = await this._core._adobeAssetFactory.getRepoMetadataUpdaters(childrenData as RepositoryMetadata[]);

        // We will ignore the update if we had local changes sooner than this timestamp.
        const latency = this._assetPool._core._environment.getValue('ASSETS_LIST_UPDATE_LATENCY');
        const mostRecentValidMutation = getMostRecentValidMutation(resource, latency);
        const session = this._assetPool.createLoaderMutationSession(mostRecentValidMutation);

        const items = this._core._adobeAssetFactory.assetsFromRepoMetadata(
            session,
            (childrenData as RepositoryMetadata[])
                // RAPI does not support excludeMediaTypes, and only supports 1 value for excluding assetTypes.
                // [SAM-5188] Filter out items that should be excluded to avoid adding unreferenced items to the pool
                .filter((item) => {
                    return !filter.excludeMediaTypes?.has(item['dc:format']) && !filter.excludeAssetTypes?.has(item['repo:assetType'] as AssetType);
                }),
            updaters
        );

        let librariesInPage: Library[];
        if (loadLibraries) {
            librariesInPage = items.filter((item): item is Library => item.isLibrary);
            librariesInPage.forEach(library => library._setLibraryLoadState('LOADING'));
        }
        // Notify LLM that storageAssignee is loaded for entries that have it
        items.forEach(item => {
            if (item._storageAssignee_NoLazyLoad.id) {
                LazyLoadManager.updatedByItemUpdater(item, SharedStorageAssigneeChangedEvent);
            }
        });
        session.commit();

        librariesDataPromise?.then((librariesData) => this._updateLibrariesData(librariesInPage, librariesData));

        // Check if we have another page to load.
        let loadNextPage: ILoadNextPage<AdobeAssetConfig> | undefined;

        if (nextPageCursor) {
            loadNextPage = (options: IItemLoaderOptions<AdobeAssetConfig>) =>
                this._loadPage(options, nextPageCursor);
        }

        return {
            items,
            loadNextPage,
            mostRecentValidMutation
        };
    }

    private _patchProjectAncestors(ancestors: string[]) {
        // We use a separate updateSession here (rather than the MutationSession in loadPage) because
        // we need to apply the change based on when the Project was last mutated, rather than its children.
        const session = this._assetPool.createUpdateSession('patchProjectAncestors', this._asset.lastKnownClientMutation);
        // Update the project's children with the repo:ancestors from the parent project. This is to ensure that
        // the user's root and the project's root are included in the child's repo:ancestors. This is only an issue
        // for children of Project, so restricting this to only Projects.
        this._core.hostAssetContext._adobeAssetUpdater.updateLocalItem(session, this._asset, {
            'repo:ancestors': ancestors
        });
        session.commit();
    }

    // Libraries listing may have stale data due to USS indexing delays. Thus, this method
    // retrieves LibrarySpecificData from LibraryData, which is always safe to use as it will not overwrite RAPI data.
    // TODO [SHARED-902]: Move to LibraryUtils
    private _getSafeLibraryData(libraryData: LibraryData): Partial<LibraryData> {
        if (!libraryData) { return {}; }
        const { library_urn, id, bookmark, name, ownership, roles, rendition_grid, elements_count }: LibrarySpecificData = libraryData;
        return { library_urn, id, bookmark, name, ownership, roles, rendition_grid, elements_count };
    }

    /**
     * Given a set of libraries that have been loading, update their data and loading state with the data from Melville.
     */
    private async _updateLibrariesData(librariesToUpdate: Library[], librariesData: LibraryData[]): Promise<void> {
        const session = this._core.hostAssetContext._assetPool.createUpdateSession<Library>();
        const libraryContext = await this._core.getLibraryContext();

        librariesToUpdate.forEach(library => {
            const libraryData = librariesData.find(item => item.library_urn === library.id);
            if (libraryData) {
                const librarySpecificData = this._getSafeLibraryData(libraryData);
                libraryContext._libraryUpdater.updateLocalItem(session, library, librarySpecificData);
                library._setLibraryLoadState('LOADED');
            } else {
                // USS indexing delays may cause Melville non-public libraries listing data to be stale.
                // Thus it is possible that we have RAPI data for a new library but no matching melville data in the listing.
                // Setting the library to NOT_LOADED will trigger lazy loading if the library is being used,
                // which will cause Melville to pull the up-to-date data for this library from platform.
                library._setLibraryLoadState('NOT_LOADED');
            }
        });
        session.commit();
    }

}



