import RestrictedEventEmitter from './utils/RestrictedEventEmitter';
import type LocalDriver from '../drivers/LocalDriver';
import observable from '../utils/observable';
import type { FontData } from './data/FontData';
/**
 * Element
 * @packageDocumentation
 * @module FontManager
 */

export default class FontManager extends RestrictedEventEmitter {
    _fontsCache: { [s: string]: FontData };

    constructor(protected _driver: LocalDriver) {
        super();
        this._fontsCache = {};
    }

    /**
     * Returns the cached font data else goes ahead and fetches it
     */
    @observable
    async getFontData(fontId: string): Promise<FontData> {
        const fontData = this._fontsCache[fontId];
        if (fontData) {
            // Already exists in the cache
            return fontData;
        }
        const data: FontData = await this._driver.getFontData(fontId);
        this._updateFontData(fontId, data);
        return data;
    }

    private _updateFontData(fontId: string, fontData: FontData) {
        this._fontsCache[fontId] = fontData;
    }

    /**
     * Returns whether the given font is installed on the system (this queries the CC Library Process).
     */
    @observable
    async isSystemFontAvailable(fontName: string, matchFamily?: boolean): Promise<boolean> {
        return await this._driver.isSystemFontAvailable(fontName, matchFamily);
    }

    _clearCache() {
        this._fontsCache = {};
        this.emit('change');
    }
}
