import {
    compareValues,
    type IComparatorMap } from '../core/ItemOrder';
import {
    createItemOrderFactory
} from '../core/ItemOrder';
import type Post from './Post';
import type { SAM } from '@ccx-public/component-types';

/**
 * Extracts the milliseconds from an ISO timestamp
 * @example
 * extractMilliseconds('2024-10-01T22:01:01.772434721Z') // => 772434721
 */
const extractMilliseconds = (timestamp: string): number => {
    return parseInt(timestamp.split('.')[1], 10);
};

/**
 * Handles posts with microsecond precision timestamps to preserve ordering
 * when multiple posts have the same millisecond timestamp
 */
const comparePostTimes = (a: Post, b: Post) => {
    if (!a.created && !b.created) {
        return 0;
    } else if (!a.created) {
        return 1;
    } else if (!b.created) {
        return -1;
    }

    const aTime = a.created.getTime();
    const bTime = b.created.getTime();

    if (aTime === bTime) {
        // Times truncated to milliseconds are the same, so we need to compare the microseconds
        return compareValues(extractMilliseconds(a.createdTimestamp), extractMilliseconds(b.createdTimestamp));
    }

    return compareValues(aTime, bTime);
};

export type PostOrderField = 'created';

const OrderFieldToComparator: IComparatorMap<Post, PostOrderField> = {
    created(a: Post, b: Post): number {
        return comparePostTimes(a, b);
    },
};

export default class PostOrder extends createItemOrderFactory(OrderFieldToComparator) implements SAM.PostOrder {
    static default = new PostOrder('descending', 'created'); // Sort by newest first
}
