import type {
    AssetListFilter,
    SharedWithYouOrderByField,
    SharedWithYouQuery,
    SortOrder
} from '../graphql/generated/types';
import type { SWYAdobeAssetOrderField } from './SWYAdobeAssetOrder';
import type { SWYAdobeAssetConfig } from './SWYAdobeAssetSource';
import type { IOrderDirection } from '../core/ItemOrder';
import type { PLSListResponse } from '../graphql/models/PLSModels';
import PLSListLoader from '../graphql/PLSListLoader';
import type { AdobeAssetUpdaterMetadata } from './AdobeAsset';
import type Resource from './Resource';


export const OrderFieldToSharedWithYouOrderBy: { [key in SWYAdobeAssetOrderField]: SharedWithYouOrderByField } = {
    'name': 'NAME',
    'created': 'DEVICE_CREATE_DATE',
    'modified': 'DEVICE_MODIFY_DATE',
    'shared': 'SHARE_DATE',
};

export const OrderDirectionToSortOrder: { [key in IOrderDirection]: SortOrder } = {
    'ascending': 'ASCENDING',
    'descending': 'DESCENDING'
};

export default class PLSSWYAdobeAssetLoader extends PLSListLoader<SharedWithYouQuery, SWYAdobeAssetConfig> {
    async _getPLSData({
        first,
        after,
        filter,
        order,
        resource,
    }: {
        first: number;
        after?: string;
        filter: AssetListFilter;
        order: SWYAdobeAssetConfig['order'],
        resource?: Resource
    }, processIncrementalData: (incrementalData: SharedWithYouQuery) => void): Promise<PLSListResponse<AdobeAssetUpdaterMetadata>> {
        const gqlManager = await this._core._getGQLManager();
        return await gqlManager.getSharedWithYou({
            first,
            after,
            filter,
            orderBy: {
                field: OrderFieldToSharedWithYouOrderBy[order.field],
                direction: OrderDirectionToSortOrder[order.direction],
            },
        }, resource, processIncrementalData);
    }

    getAssetNodesFromData(incrementalData: SharedWithYouQuery) {
        return incrementalData.sharedWithYou.assetListConnection.edges.map(edge => {
            // The generated types for for the query are slightly overspecified by codegen, so a cast is needed here
            return edge.node as any;
        });
    }
}
