import RestrictedEventEmitter from '../models/utils/RestrictedEventEmitter';

export default abstract class AsyncOperation extends RestrictedEventEmitter {
    protected _abortController = new AbortController();
    protected _isComplete = false;
    protected _progress = 0;

    abort() {
        this.DANGEROUS.removeAllListeners();
        this._abortController.abort();
    }

    get isComplete() {
        return this.progress === 100;
    }

    get progress() {
        return this._progress;
    }

    set progress(progress) {
        this._progress = Math.min(progress, 100);
    }
}
