import type { GenerationHistoryAssetFilter, IItemSourceConfig } from 'src';
import type {
    IItemLoaderOptions,
    IItemLoader,
    ILoadedPage,
} from '../core/ItemLoader';
import type { ISAMCorePrivate } from '../indexPrivate';
import { getGenerationGroupId } from './utils';

/**
 * Loads siblings of the same generationGroupId that are already in the assetPool, so they appear in
 * the UI right away even if SAM has to go to the server to check if there are more.
 */
export default class GenerationSiblingLoader<Config extends IItemSourceConfig> implements IItemLoader<Config> {
    constructor(
        private _core: ISAMCorePrivate
    ) {}

    async loadPage(options: IItemLoaderOptions<Config>) {
        return await this._loadPage(options);
    }

    private async _loadPage(options: IItemLoaderOptions<Config>): Promise<ILoadedPage<Config>> {
        const { generationGroupId } = options.filter as GenerationHistoryAssetFilter ?? {};

        if (!generationGroupId) {
            return { items: [] };
        }

        return { items: this._core._getAssetPool().toArray().filter(item => getGenerationGroupId(item) === generationGroupId) };
    }

}
