import type { AdobeAssetOrderField } from '../../assets/AdobeAssetOrder';
import type {
    Asset,
    AssetChildConnection,
    AssetChildEdge,
    ListAsset,
    OrderByField,
    Query
} from '../generated/types';
import type { IAppMetadata } from '../../interface/RepositoryModel';

// TODO: get rid of query builder so all GQL types match generated types
export type QueryBuilderListAsset = Omit<ListAsset, 'appMetadata'> & {
    appMetadata: { am?: IAppMetadata };
}

export type QueryBuilderAssetChildEdge = Omit<AssetChildEdge, 'node'> & {
    node: QueryBuilderListAsset;
}
export type QueryBuilderAssetChildConnection = Omit<AssetChildConnection, 'edges'> & {
    edges: QueryBuilderAssetChildEdge[];
}
export type QueryBuilderAssetContainer = {
    childrenConnection?: QueryBuilderAssetChildConnection | null;
}

export type IdQuery = {
    resolveAssetById: Query['resolveAssetById'] & QueryBuilderAssetContainer
}

export type PathQuery = {
    resolveAssetByPath: Query['resolveAssetByPath']
}
export type RelativePathQuery = {
    resolveUserHome: Asset & {
        assetByRelativePath: Query['resolveAssetByRelativePath']
    }
};

export enum Privelege {
    READ = 'READ',
    WRITE = 'WRITE',
    ACK = 'ACK',
    DELETE = 'DELETE'
}

export type GQLEffectivePermissions = {
    // "Represents *"
    default: Privelege[];

    // Other rel types
    primary?: Privelege[];
    applicationMetadata?: Privelege[];
    aclPolicy?: Privelege[];
    directory?: Privelege[];
    annotations?: Privelege[];
}

export type PageInfo = { hasNextPage: boolean, endCursor?: string };

export const OrderFieldToGQLOrderBy: { [key in AdobeAssetOrderField]: OrderByField } = {
    'name': 'NAME',
    'created': 'CREATE_DATE',
    'modified': 'MODIFY_DATE',
    // GQL doesn't sort on share date
    'shared': 'MODIFY_DATE',
    // Note: currently, the only PLS view that sorts by lastAccessed is Recents, which doesn't
    // accept a sort parameter. Meanwhile, other PLS views do not sort by lastAccessed, so if
    // the client code requests sorting by lastAccessed for those views, it'll sort by `modified`
    // instead.
    'lastAccessed': 'MODIFY_DATE'
};
