import type AdobeAsset from '../assets/AdobeAsset';
import ImplicitAdobeAssetFilterBase from '../assets/ImplicitAdobeAssetFilterBase';
import type { IItemFilter } from '../core/ItemFilter';
import { isGenerationHistoryAsset } from './utils';

export default class ImplicitGenerationHistoryAssetFilter extends ImplicitAdobeAssetFilterBase implements IItemFilter<AdobeAsset> {
    matches(item: AdobeAsset) {
        return isGenerationHistoryAsset(item);
    }
}
