import type AdobeAsset from '../assets/AdobeAsset';
import AdobeAssetFilter from '../assets/AdobeAssetFilter';

/**
 * This file and filter may not be needed in the future.
 * @deprecated This can be removed with ClassroomContext.getStudentAssignmentFiles(). Will be removed in ACPCEDU-3305.
 */
// NOTE: This is used as an implicit filter in StudentAssignment.files, and internally as an explicit filter in
// ClassroomContext.getStudentAssignmentFiles(). In the latter case, it is used to filter AdobeAsset.children()
// so it must extend AdobeAssetFilter for type-checking purposes, even though none of the features of
// AdobeAssetFilter are used. This is preferable to allowing AdobeAsset.children take StudentAssignmentFilesListFilter
// as an explicit filter, as it shouldn't be part of the public interface.
export default class StudentAssignmentFilesListFilter extends AdobeAssetFilter {
    matches(item: AdobeAsset): boolean {
        // Note: not calling super here, because this is only needed for the internal case
        // of using StudentAssignmentFilesListFilter as the explicit filter in
        // ClassroomContext.getStudentAssignmentFiles()
        return item.isChildOfStudentAssignment;
    }
}
