import ItemUpdater from '../core/ItemUpdater';
import PropertyUpdater from '../core/PropertyUpdater';
import type { ISAMObject } from '../indexPrivate';

import type {
    IFrameioAssetResponse,
    IFrameioProjectResponse,
    IFrameioTeamResponse,
    IFrameioFolderTreeFolderResponse
} from './FrameioInterface';
import type FrameioContext from './FrameioContext';
import type FrameioFolder from './FrameioFolder';
import { FrameioFolderUpdater } from './FrameioFolder';
import type FrameioTeam from './FrameioTeam';
import { FrameioTeamUpdater } from './FrameioTeam';
import type FrameioReviewLink from './FrameioReviewLink';
import { FrameioReviewLinkUpdater } from './FrameioReviewLink';
import FrameioBase from './FrameioBase';

// See https://developer.frame.io/api/reference/operation/getProjectsByTeam/
//  for schema of the data FrameioProject encapsulates.
export default class FrameioProject extends FrameioBase {
    private _reviews: Array<FrameioReviewLink> | undefined;
    private _rootAssetId: string = '';
    private _rootFolder: FrameioFolder | undefined;
    private _name: string = '';
    private _ownerId: string = '';
    private _teamId: string = '';
    private _team: FrameioTeam | undefined;


    get name(): string {
        return this._name;
    }

    get ownerId(): string {
        return this._ownerId;
    }

    get rootAssetId(): string {
        return this._rootAssetId;
    }

    get teamId(): string {
        return this._teamId;
    }

    async getTeam(): Promise<FrameioTeam> {
        if (!this._team) {
            this._team = await this.context.getTeam(this.rootAssetId);
        }

        return this._team!;
    }

    async getRootFolder(): Promise<FrameioFolder> {
        if (!this._rootFolder) {
            this._rootFolder = await this.context.getAsset(this.rootAssetId) as FrameioFolder;
        }

        return this._rootFolder!;
    }

    async getReviewLinks(): Promise<FrameioReviewLink[]> {
        let reviews = this._reviews;
        if (!reviews) {
            const ctx = this.context;

            const response = await ctx._frameioInterface.getReviewLinks(this.id);
            const session = ctx._objectPool.createUpdateSession<FrameioReviewLink>();
            reviews = FrameioReviewLinkUpdater.updateRemoteItems(session, response);
            session.commit();

            this._reviews = reviews;
        }

        return reviews;
    }

    private createFolder(data: any, folder: IFrameioFolderTreeFolderResponse): FrameioFolder {
        const ctx = this.context;

        // IFrameioFolderTreeFolderResponse only contains
        //      { id, name, parent_id }
        //
        // but FrameioFolderUpdater expects to read
        //      { id, name, parent_id, project_id, team_id }
        //
        // from a IFrameioAssetResponse, so copy { project_id, team_id }
        // from this project into the response so we can use the
        // updater.

        const response = folder as IFrameioAssetResponse;
        response['project_id'] = this.id;
        response['team_id'] = this.teamId;

        const session = ctx._objectPool.createUpdateSession<FrameioFolder>();
        const that = FrameioFolderUpdater.updateRemoteItem(session, response);
        session.commit();

        that['_children'] = data[response.id].map((folder: IFrameioFolderTreeFolderResponse) => this.createFolder(data, folder));

        return that;
    }
    async getFolderTree(): Promise<FrameioFolder> {
        // returns the rootFolder, but only after constructing FrameioFolder's for all of the
        // folders in project using an undocumented API.

        const response =  await this._core.frameioContext._frameioInterface.getFolderTree(this.id);

        this._rootFolder = this.createFolder(response.data, response.data['root'][0]);

        return this._rootFolder;
    }

    async createReviewLink(display_name: string): Promise<FrameioReviewLink> {
        const ctx: FrameioContext = this.context;
        const response = await ctx._frameioInterface.createReviewLink(this.id, display_name);


        const session = ctx._objectPool.createUpdateSession<FrameioReviewLink>();
        const review = FrameioReviewLinkUpdater.updateRemoteItem(session, response);
        session.commit();

        if (this._reviews) {
            // update the cache of reviews owned by this project
            // by adding the newly created review.
            this._reviews.push(review);
        }

        return review;
    }
}

export const FrameioProjectUpdater = new ItemUpdater<FrameioProject, Partial<IFrameioProjectResponse>>({
    localItemType: FrameioProject,
    remoteIdProperty: 'id',
    propertyUpdater: new PropertyUpdater({
        '_name': 'name',
        '_ownerId': 'owner_id',
        '_rootAssetId': 'root_asset_id',
        '_rootFolder': {
            // when the update reads response.root_asset
            // ( which matches name: 'root_asset' ),
            // it will invoke set: with the child object
            //
            name: 'root_asset',
            format: 'object',
            set: (rootFolder: IFrameioAssetResponse, dest: ISAMObject): void => {
                const project = dest as FrameioProject;
                const pool = project.context._objectPool;
                const session = pool.createUpdateSession<FrameioFolder>();
                const folder = FrameioFolderUpdater.updateRemoteItem(session, rootFolder);
                session.commit();

                // @ts-expect-error
                project._rootFolder = folder;
            },

        },
        '_team': {
            // The owner property of an IFrameioAccountResponse is a nested
            // object of type IFrameioUserResponse, so let's construct that
            // while we are here.
            set: (team: IFrameioTeamResponse, dest: ISAMObject) => {
                const project = dest as FrameioProject;
                const context = project.context;
                const pool = context._objectPool;

                const session = pool.createUpdateSession<FrameioTeam>();
                project['_team'] = FrameioTeamUpdater.updateRemoteItem(session, team);
                session.commit();
            },
            name: 'team',
            format: 'object'
        },

        '_teamId': 'team_id'
    })
});
