import { KeysProperty } from './key';

const $WeakCacheProperty = Symbol('WeakCacheProperty');

function stringifyWithSortedKeys(input: string | number | Date | Record<string, any>): string {
    if (typeof input === 'string' || typeof input === 'number' || input instanceof Date || typeof input === 'boolean') {
        return JSON.stringify(input);
    } else if (typeof input === 'object' && input !== null) {
        const sortedObject = Object.keys(input).sort().reduce((newObj, key) => {
            newObj[key] = input[key];
            return newObj;
        }, {} as Record<string, any>);
        return JSON.stringify(sortedObject);
    }
    throw new Error(`Unsupported input type (${input})`);
}

function isPrimitive(value: any): boolean {
    return value === null || (typeof value !== 'object' && typeof value !== 'function');
}

/**
 * Cache the result of the method given a set of arguments. The cache is weak, meaning that the object will be garbage collected.
 * Therefore, it's recommended to use @keepAlive decorator to keep the object alive in memory.
 * This decorator will not work with method that returns primitive types (e.g. string, number, boolean, etc).
 * A parameter of the target function can be marked as @key to use as the key for the cache. If no parameter is marked as @key, the default key is 'default'.
 *
 * If the parameter, which is attached with @key, is explicitly set to null or undefined, the decorator will throw an error.
 * For example:
 *   @weakCache
 *   exampleFunction(@key value?: string) {}
 *   exampleFunction(null); // This would throw an error
 *
 */
export default (target: any, propertyKey: string, descriptor: PropertyDescriptor) => {
    const originalFn = descriptor.value;
    if (!originalFn) {
        throw new Error('@weakCache decorator can only be applied to a method');
    }
    // this is to avoid unexpected side-effects between unrelated target objects with the same property name (i.e. propertyKey)
    const cache = target[$WeakCacheProperty] ??= new Map<string, WeakRef<any>>();
    descriptor.value = function (this: any, ...args: any[]) {
        const keyIndex = this[KeysProperty]?.get(propertyKey);
        const keyArgs = keyIndex === undefined || args.length === 0 ? 'default' : args[keyIndex];
        // we need to sort the keys of keyArgs in case it is an object to ensure that the cache key is consistent
        // For example, do(@key {a: 1, b: 2}) and do(@key {b: 2, a: 1}) should have the same cache key
        const key = `${propertyKey} (${stringifyWithSortedKeys(keyArgs)})`;
        let result: any = cache.get(key)?.deref();
        if (result) {
            return result;
        }
        result = originalFn.call(this, ...args);
        if (isPrimitive(result)) {
            throw new Error('Cannot cache primitive types');
        }
        cache.set(key, new WeakRef(result));
        return result;
    };
};
