import type AdobeAsset from './AdobeAsset';
import type { IItemLoaderOptions, ILoadedPage } from '../core/ItemLoader';
import type ItemPool from '../core/ItemPool';
import type { RecentAdobeAssetConfig } from './RecentAdobeAssetSource';
import type RecentAdobeAssetFilter from './RecentAdobeAssetFilter';
import type RecentInterface from '../interface/RecentInterface';
import type { IGetUSSResults, IUSSLoader } from './USSLoaderHelper';
import USSLoaderHelper from './USSLoaderHelper';
import type { ISAMCorePrivate } from '../indexPrivate';
import type AdobeAssetFilter from '../assets/AdobeAssetFilter';
import type { USSResponse } from '../interface/USSModel';
import type LibraryContext from '../libraries/LibraryContext';
import { USSAssetFilterName } from './USSAssetFilterName';
import type USSAdobeAssetFilter from './USSAdobeAssetFilter';
import type { RecentAssetsListingOptions } from '../interface/RecentInterface';

export default class RecentAdobeAssetLoader implements IUSSLoader<RecentAdobeAssetConfig> {
    private _ussLoaderHelper: USSLoaderHelper<RecentAdobeAssetConfig>;
    /**
      * @package -- only for use in SAM.js
      */
    _libraryContext?: LibraryContext;
    constructor(
        assetPool: ItemPool<AdobeAsset>,
        private _core: ISAMCorePrivate,
        private _recentInterface: RecentInterface,
        private _implicitFilter: RecentAdobeAssetFilter
    ) {
        this._ussLoaderHelper = new USSLoaderHelper(assetPool, _core, this);
    }

    supportsFilter(filter?: RecentAdobeAssetFilter | AdobeAssetFilter): boolean {
        // If we don't provide a filter at all, then we cannot use the loader
        return filter !== undefined;
    }

    async loadPage(options: IItemLoaderOptions<RecentAdobeAssetConfig>): Promise<ILoadedPage<RecentAdobeAssetConfig>> {
        if (!this._libraryContext) {
            this._libraryContext = await this._core.getLibraryContext();
        }
        return this._ussLoaderHelper.loadPage(options);
    }

    /**
     * @package -- only for use by USSLoaderHelper
     */
    async _getUSSResults({
        start,
        loadOptions,
        mediaTypes,
        excludeMediaTypes,
        filter
    }: IGetUSSResults<RecentAdobeAssetConfig>): Promise<USSResponse> {
        const options: Partial<RecentAssetsListingOptions> = {
            start,
            limit: loadOptions?.limit,
            mediaTypes,
            excludeMediaTypes,
            embedPermissions: true
        };
        if (filter.name === USSAssetFilterName) {
            const ussFilter = filter as USSAdobeAssetFilter;
            options.userId = ussFilter.userId;
            options.uploadedFrom = ussFilter.uploadedFrom;
        }
        return this._recentInterface.getRecentAssets(options);
    }

    /**
     * @package -- only for use by USSLoaderHelper
     */
    _postProcessPage(
        loaderOptions: IItemLoaderOptions<RecentAdobeAssetConfig>,
        page: ILoadedPage<RecentAdobeAssetConfig>
    ): void {
        const { items } = page;

        // update modification time of last asset on implicit filter (assets are already sorted by modification time),
        // so that these items can be matched with this filter in ItemLoaderState before adding them in ItemLoaderState._pages
        if (items.length) {
            this._implicitFilter._lastModificationDate = items[items.length - 1].modified;
        }
    }
}

