import { vulcanLibrariesSAPCode, vulcanLibrariesTargetSpecifier } from '../../config/constants';
import type { IVulcan, IVulcan5, IVulcan7, IVulcanMessage, VulcanCallback } from './IVulcan';
import { VulcanInterface } from './IVulcan';

export default function getVulcanInterface(vulcanInterface: IVulcan): VulcanInterface {
    if (isVulcan7(vulcanInterface)) {
        return new Vulcan7(vulcanInterface);
    }

    return new Vulcan5(vulcanInterface);
}

function isVulcan7(vulcan: IVulcan): vulcan is IVulcan7 {
    return (vulcan as IVulcan7).launchAppEx !== undefined;
}

abstract class Vulcan extends VulcanInterface {
    protected _vulcanInterface: IVulcan;
    protected _specifer = vulcanLibrariesTargetSpecifier;

    constructor(vulcanInterface: IVulcan) {
        super();
        this._vulcanInterface = vulcanInterface;
    }

    addMessageListener(type: string, callback: VulcanCallback, obj?: string) {
        this.vulcanInterface.addMessageListener(type, callback, obj);
    }

    removeMessageListener(type: string, callback: VulcanCallback, obj?: {}) {
        this.vulcanInterface.removeMessageListener(type, callback, obj);
    }

    dispatchMessage(message: IVulcanMessage) {
        this.vulcanInterface.dispatchMessage(message);
    }

    getPayload(message: string): string | null {
        return this.vulcanInterface.getPayload(message);
    }
}

class Vulcan5 extends Vulcan {
    constructor(vulcanInterface: IVulcan) {
        super(vulcanInterface);
        this._vulcanInterface = vulcanInterface;
        this._specifer = vulcanLibrariesTargetSpecifier;
    }

    protected get vulcanInterface(): IVulcan5 {
        return this._vulcanInterface as IVulcan5;
    }

    getTargetSpecifiers(): string[] {
        return this.vulcanInterface.getTargetSpecifiers();
    }

    launchApp(focus: boolean, cmdLine: string): boolean {
        return this.vulcanInterface.launchApp(this._specifer, focus, cmdLine);
    }

    isAppRunning(): boolean {
        return this.vulcanInterface.isAppRunning(this._specifer);
    }

    isAppInstalled(): boolean {
        return this.vulcanInterface.isAppInstalled(this._specifer);
    }

    getAppPath(): string {
        return this.vulcanInterface.getAppPath(this._specifer);
    }
}

class Vulcan7 extends Vulcan {
    constructor(vulcanInterface: IVulcan) {
        super(vulcanInterface);
        this._specifer = vulcanLibrariesSAPCode;
    }

    protected get vulcanInterface(): IVulcan7 {
        return this._vulcanInterface as IVulcan7;
    }

    getTargetSpecifiers(): string[] {
        return this.vulcanInterface.getTargetSpecifiersEx();
    }

    launchApp(focus: boolean, cmdLine: string): boolean {
        return this.vulcanInterface.launchAppEx(this._specifer, focus, cmdLine);
    }

    isAppRunning(): boolean {
        return this.vulcanInterface.isAppRunningEx(this._specifer);
    }

    isAppInstalled(): boolean {
        return this.vulcanInterface.isAppInstalledEx(this._specifer);
    }

    getAppPath(): string {
        return this.vulcanInterface.getAppPathEx(this._specifer);
    }
}
