import type { IItemSourceConfig } from '../core/ItemList';
import type { IItemLoader, IItemLoaderOptions, ILoadedPage, ILoadNextPage } from '../core/ItemLoader';
import type { AdobeAssetUpdaterMetadata } from './AdobeAsset';
import type AdobeAsset from './AdobeAsset';
import type ItemPool from '../core/ItemPool';
import type { USSResponse, USSItemMetadata } from '../interface/USSv3Model';
import type { ISAMCorePrivate } from '../indexPrivate';
import type { IUpdateSession } from '../core/UpdateSession';
import { RelType } from '../interface/LinkUtils';
import type LibraryContext from '../libraries/LibraryContext';
import type USSAdobeAssetFilter from './USSAdobeAssetFilter';
import type { UpdaterMap } from './AdobeAssetFactory';
import { LazyLoadManager } from '../core/decorators/LazyLoadManager';
import { STORAGE_ASSIGNEE_CHANGED } from '../assets/AssetEvents';
import { getMostRecentValidMutation } from '../utils/loaderUtils';

export interface IGetUSSResultsOpts<T extends IItemSourceConfig<AdobeAsset>> extends IItemLoaderOptions<T> {
    start: number;
    // NOTE: the parameters below are common to *all* USS Loaders, so are included here to simplify the _getUSSResults()
    // implementation. Any additional parameters should come from the `filter` prop, which is inherited from
    // IItemLoaderOptions.
    mediaTypes: string[];
    excludeMediaTypes: string[];
}

export interface IUSSLoader<T extends IItemSourceConfig<AdobeAsset>> extends IItemLoader<T> {
    /**
     * Loaders must implement this method and call from Loader.loadPage(options)
     */
    _getUSSResults(opts: IGetUSSResultsOpts<T>): Promise<USSResponse>;
    /**
     * Loaders can optionally implement to provide additional metadata that is
     * implied by the Loader but not included in the USS response.
     */
    _getItemData?(item: USSItemMetadata): Partial<AdobeAssetUpdaterMetadata>;
    /**
     * Loaders can optionally implement to perform additional internal state management.
     */
    _postProcessPage?(loaderPageOpts: IItemLoaderOptions<T>, page: ILoadedPage<T>): void;
    /**
     * Loaders can optionally implement to perform additional processing of USS search results.
     */
    _extractItems?(session: IUpdateSession<AdobeAsset>, items: USSItemMetadata[], updaters: UpdaterMap): AdobeAsset[];
    /**
     * Loaders can optionally preload the library context.
     */
    _libraryContext?: LibraryContext;
}

const DEFAULT_LIMIT = 50;

export function getUSSV3ItemData(userId: string, item: USSItemMetadata)  {
    return {
        ...item.rm,
        // cm.sharedBy is an array of user IDs that have shared the asset
        // assuming that it is an ordered array, the first item is the first sharer
        // Even after this assumption we can't be sure that first sharer is the owner
        // We will need more info to figure out whether the asset is sharedViaInvite.
        // For example consider an asset inside a project that is not owned by the user
        // and that asset is 1-off shared with some user C by user B.
        // Now user A does not know whether this asset is shared via invite with him because
        // he is not the owner of the asset and cm.sharedBy will have user B's ID but it is not
        // shared via invite with user A.
        sharedViaInvite: item.cm?.sharedBy.length > 0 && item.cm!.sharedBy[0] !== userId,
        isShared: item.cm?.sharedBy.length > 0,
        // Get the app metadata from the item if it exists.
        ...(item.am && { _embedded: { [RelType.APP_METADATA]: item.am } }),
        // No need to refresh collaborators for share flags, directCollaboratorCount, since they are computed
        // above. Not clearing the collaboratorDataIsDirty flag, because we cannot populate collaboratorArray
        // from USS.
        shareFlagsAreDirty: false
    };
}


/**
 * AdobeAsset Loader classes should use this class to do the page loading. Using composition rather
 * than inheritance because a base USSLoader class was causing circular dependencies at runtime that
 * would cause the base USSLoader class to be undefined when the Loader class that was extending it
 * was declared.
 */
export default class USSv3LoaderHelper<T extends IItemSourceConfig<AdobeAsset>> {
    constructor(
        private _assetPool: ItemPool<AdobeAsset>,
        protected _core: ISAMCorePrivate,
        private _loader: IUSSLoader<T>
    ) {}

    async loadPage(options: IItemLoaderOptions<T>, start?: number): Promise<ILoadedPage<T>> {
        const { order, filter, implicitFilter, resource } = options;
        const { limit = DEFAULT_LIMIT } = options.loadOptions ?? {};
        start = start || 0;

        const { mediaTypes, excludeMediaTypes } = filter as USSAdobeAssetFilter;

        const result: USSResponse = await this._loader._getUSSResults({
            order,
            loadOptions: { limit, ...options.loadOptions,  },
            filter,
            implicitFilter,
            resource,
            start,
            // NOTE: the parameters below are common to *all* USS Loaders, so are normalized here to simplify the
            // _getUSSResults() implementation. The Loader._getUSSResults() implementation should get any additional
            // parameters it needs from `filter` or `implicitFilter`.
            mediaTypes: Array.from(mediaTypes ?? []),
            excludeMediaTypes: Array.from(excludeMediaTypes ?? []),
        });
        const latency = this._core._environment.getValue('USS_LIST_UPDATE_LATENCY');
        const mostRecentValidMutation = getMostRecentValidMutation(resource, latency);

        const queryResult = result.queryResults[0];
        // TODO: it'd be nice if USS returned empty array when there are no matches
        const resultItems = queryResult.items || [];
        const updaters = await this._core._adobeAssetFactory.getUSSV3Updaters(resultItems);
        const session = this._assetPool.createLoaderUpdateSession(mostRecentValidMutation);
        const items = this._loader._extractItems
            ? this._loader._extractItems(session, resultItems, updaters)
            : this._extractItems(session, resultItems, updaters);

        // All USS sources return storage:assignee, so there is no need to lazy-load it
        items.forEach(item => LazyLoadManager.updatedByItemUpdater(item, STORAGE_ASSIGNEE_CHANGED));

        let loadNextPage: ILoadNextPage<T> | undefined;
        const total = queryResult.metadata.totalHits || 0;
        const pageItemCount = resultItems.length;
        // [SEARCH-30755] -- May be caused by USS filtering out items due to permissions for the
        // current user, which aren't subtracted from the total. Try to ensure that the Loader paginates
        // as though the total_items is correct.
        const nextStartIndex = (pageItemCount === 0 ? start + limit : start + pageItemCount);
        if (nextStartIndex < total) {
            loadNextPage = (options: IItemLoaderOptions<T>) => this.loadPage(options, nextStartIndex);
        }

        const page: ILoadedPage<T> = {
            items,
            total,
            loadNextPage,
            mostRecentValidMutation
        };

        // allow Loader to do additional internal state management (optional)
        this._loader._postProcessPage?.(options, page);

        session.commit();

        return page;
    }

    private _getItemData = (item: USSItemMetadata) => {
        return getUSSV3ItemData(this._core._environment.getUserId(), item);
    };

    private _extractItems(
        session: IUpdateSession<AdobeAsset>,
        items: USSItemMetadata[],
        updaters: UpdaterMap
    ): AdobeAsset[] {
        return this._core._adobeAssetFactory.assetsFromUSSV3Response(
            session,
            items,
            this._loader._getItemData ?? this._getItemData,
            updaters
        );
    }
}
