import type { Action } from '../../models/Action';
import type LocalDriver from '.';

import ParallelOperation from '../ParallelOperation';
// @ts-expect-error R-TODO
import type Library from '../../models/Library';

export default class LocalParallelOperation extends ParallelOperation<LocalDriver> {
    protected _actionMappers = {
        uploadComponent: async (action: Action) => {
            const path = await this._driver.stageRepresentationForCommit(
                action.library as Library,
                action.data.file,
                action.data.type
            );
            return { ...action, data: { path }, originalAction: action };
        }
    };

    supportsAction(action: Action) {
        return action.name === 'uploadComponent';
    }
}
