import type LegacyCustomModelInterface from './LegacyCustomModelInterface';
import type ItemPool from '../../core/ItemPool';
import type { ISAMCorePrivate } from '../../indexPrivate';
import type { AdobeAsset } from 'src';
import type {
    LegacyCustomModelConfig,
} from './LegacyCustomModelSource';
import type {
    IItemLoader,
    IItemLoaderOptions,
    ILoadNextPage,
    ILoadedPage,
} from '../../core/ItemLoader';
import type LegacyCustomModel from './LegacyCustomModel';
import { LegacyCustomModelUpdater } from './LegacyCustomModel';
import { LegacyOrderFieldToCustomModelOrderBy } from './LegacyCustomModelOrder';
import type LegacyCustomModelFilter from './LegacyCustomModelFilter';

export default class CustomModelLoader
implements IItemLoader<LegacyCustomModelConfig> {
    constructor(
        private _assetPool: ItemPool<LegacyCustomModel | AdobeAsset>,
        private _core: ISAMCorePrivate,
        private _customModelInterface: LegacyCustomModelInterface
    ) {}

    async loadPage(options: IItemLoaderOptions<LegacyCustomModelConfig>) {
        return await this._loadPage(options);
    }

    private async _loadPage(
        options: IItemLoaderOptions<LegacyCustomModelConfig>,
        startIndex?: number
    ): Promise<ILoadedPage<LegacyCustomModelConfig>> {
        const { order, filter } = options;
        const { limit } = options.loadOptions ?? {};
        const customModelFilter = filter as LegacyCustomModelFilter;
        const listingOptions = customModelFilter.listingOptions;

        const listOptions = {
            orderBy: LegacyOrderFieldToCustomModelOrderBy[order.field],
            limit,
            ...listingOptions,
        };
        const result = await this._customModelInterface.getCustomModels(
            startIndex ? { ...listOptions, startIndex } : listOptions
        );
        const session = this._assetPool.createLoaderUpdateSession<LegacyCustomModel>(
            Date.now() - this._core._environment.getValue('USS_LIST_UPDATE_LATENCY')
        );
        const items = LegacyCustomModelUpdater.updateRemoteItems(session, result.items);
        session.commit();

        // Check if we have another page to load.
        let loadNextPage: ILoadNextPage<LegacyCustomModelConfig> | undefined;
        const nextPageLink = result.nextPage?.startIndex;
        if (nextPageLink) {
            loadNextPage = (options: IItemLoaderOptions<LegacyCustomModelConfig>) =>
                this._loadPage(options, nextPageLink);
        }

        return {
            items,
            loadNextPage,
            total: result.total
        };
    }
}
