    async getElementsPage(
        library: SAMLibrary,
        start: number = 0,
        limit: number = 100,
        sort: ElementSort = defaultElementSort,
        _etag?: string,
    ): Promise<ElementsResponse> {
        const orderBy = `${sort.direction === 'descending' ? '-' : ''}${sortFieldMap[sort.field]}`;

        const headers: Record<string, string> = {
            start: start.toString(),
            limit: limit.toString(),
            orderBy,
            selector: 'default,representations,details'
        };

        return await this.fetch(
            `/api/v1/libraries/${library.id}/elements`, { headers }).
            then(res => res.json());
    }

