    private _getLibrariesURL(filters?: LibraryListFilters): string {
        return `/api/v1/libraries?${new URLSearchParams(filters as Record<string, string>).toString()}`;
    }

    private _getLibrariesResponseMapper(filters?: LibraryListFilters): (response: LibrariesResponse) => LibraryData[] {
        return (response: LibrariesResponse) => {
            if (!isLibrariesResponse(response)) {
                return [];
            }
            return response.libraries.map(data =>
                mapResponseToLibraryData(
                    data,
                    this._options.readOnly,
                    filters?.selector?.includes('rendition_grid') ?? true
                )
            );
        };
    }

    /* Element operations */

    private _getElement(assetId: string, elementId: string): Promise<ElementData> {
        return this.fetch(
            `/api/v1/libraries/${assetId}/elements/${elementId}?selector=default,representations,details,tags`
        )
            .then(res => res.json())
            .then((res: ElementResponse) => mapResponseToElementData(res));
    }

    @trace
    private async *_getAllElements(assetId: string, options: GetElementsOptions): AsyncGenerator<Partial<LibraryData>> {
        const elementTypes = [
            [ 'elements', '_getElementsByAssetId' ],
            [ 'documentationElements', '_getDocumentationElementsByAssetId' ],
            [ 'removedElements', '_getRemovedElementsByAssetId' ]
        ] as const;

        // If the elements aren't loaded yet, update the library page by page
        // Otherwise, load them all at once.
        const updateData: Partial<LibraryData> = {};

        // TODO: We want to run all element type iterators at the same time. Right now it doesn't matter since we only deal with normal elements.
        for (const [ type, generator ] of elementTypes) {
            if (options.types.includes(type)) {
                for await (const page of this[generator](
                    assetId,
                    options.sort,
                    options.etag,
                    undefined,
                    options.abortController?.signal
                )) {
                    updateData[type] = updateData[type] || [];
                    updateData[type]?.push(...page);
                    if (options.loadProgressively) {
                        yield { [type]: updateData[type] };
                    }
                }
            }
        }

        yield { areElementsLoaded: true, ...(options.loadProgressively ? {} : updateData) };
    }

