    @trace
    private async *_getElementsOfTypeByAssetId(
        type: 'elements' | 'archive',
        assetId: string,
        sort: ElementSort = defaultElementSort,
        etag?: string,
        limit = 100,
        signal?: AbortSignal
    ): AsyncGenerator<PaginatedResponse<ElementData>> {
        const responseMapper = (res: ElementsResponse) =>
            res.elements.map(element => {
                // The no-etag-set-on-library-response-yet case
                if ((!element.manifest_etag && etag === melvilleFirstUseEtag) || element.manifest_etag === etag) {
                    return mapResponseToElementData(element);
                }

                throw new RequestError('PRECONDITION_FAILED', `An element did not match the provided etag: ${etag}`);
            });

        const orderBy = `${sort.direction === 'descending' ? '-' : ''}${sortFieldMap[sort.field]}`;
        const queryParams: { [s: string]: any } = {
            limit,
            orderBy,
            selector: [ 'default', 'representations', 'details' ]
        };

        yield* this.fetchAllPages(
            `/api/v1/libraries/${assetId}/${type}?${stringify(queryParams, { arrayFormat: 'comma' })}`,
            {},
            responseMapper,
            signal
        );

    }

    async *getSearchResults(
        searchQuery: string,
        filters: SearchFilters,
        elementSort: ElementSort,
        signal: AbortSignal
    ): AsyncGenerator<PaginatedResponse<ElementData>> {
        const { field, direction } = elementSort;
        let orderBy = field === 'modifiedDate' ? 'modified_date' : 'name';
        if (direction === 'descending') {orderBy = `-${orderBy}`;}
        yield* this.fetchAllPages(
            '/api/v1/search',
            {
                method: 'POST',
                signal,
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    query_string: searchQuery,
                    library_id: filters.library_id,
                    asset_type: [ 'element' ],
                    orderBy,
                    limit: 300
                })
            },
            (res: SearchElementsResponse) => {
                return res.elements.map(mapSearchResponseToElementData);
            }
        );
    }

