    async getRepresentationContent(representation: Representation): Promise<Response> {
        let representationUrl;

        // 10mb ACP API limit on download via `primary` link, otherwise use `download` to get presigned URL
        if (representation.contentLength < rapiMaxSingleTransferSize) {
            representationUrl = representation._data.url as string;
        } else {
            const blockDownloadData = await this.getPresignedDownloadUrl(
                representation._data.blockDownloadUrl as string
            );
            representationUrl = blockDownloadData && (blockDownloadData.url as string);

            if (!representationUrl) {
                representationUrl = representation._data.url as string;
            }
        }

        return this.fetch(representationUrl as string);
    }

