    /**
     * Moves query params to headers, for those that are in the MelvilleParamsAsHeaders list
     * @param melvillePath
     * @returns tuple of [path, headers], with the path truncated of the query params that were moved to headers
     */
    moveUrlQueryParamsToHeaders(
        melvillePath: string,
        headers: Record<string, string> = {}
    ): [string, Record<string, string>] {
        const [ path, query ] = melvillePath.split('?');
        const urlParams = new URLSearchParams(query);
        for (const headerParamKey of MelvilleParamsAsHeaders) {
            const headerParamValue = urlParams.get(headerParamKey);
            if (headerParamValue) {
                headers[headerParamKey] = headerParamValue;
                urlParams.delete(headerParamKey);
            }
        }

        return [ `${path}${[ ...urlParams ].length > 0 ? '?' : ''}${urlParams}`, headers ];
    }

