    @trace
    async fetch(path: string, init?: FetchRequestInit, options: { includeAuthHeader?: boolean } = {}) {
        setTracingSpanAttribute('path', path);
        init = init || {};
        init.headers = init.headers || {};
        init.headers['x-api-key'] = this._clientId as string;

        // Include the auth header, unless the options specifically say not to include it.
        if (options.includeAuthHeader !== false) {
            init.headers.Authorization = `Bearer ${this._token}`;
        }

        // Attempt to upgrade platform urls to use edge workflow
        // Turns on http/2 for ACP
        const { url, headers } = useEdge(path);
        path = url;
        init.headers = { ...headers, ...init.headers };

        init.signal = init.signal
            ? combineSignals(init.signal, this._abortController?.signal as AbortSignal)
            : this._abortController?.signal;

        if (path.startsWith('/')) {
            path = `https://${this.driverConfig.hostname}${path}`;
        }

        const startTime = Date.now();
        const response = await this._fetch(path, init).catch(e => {
            if (e.name === ABORT_ERROR) {
                return new Response('{}');
            }
            Logger.info(`Error - ${e} (${Date.now() - startTime}ms)`);
            throw e;
        });
        const requestId = response.headers.get('X-Request-Id') || 'no requestId';
        Logger.info(`[${requestId}] ${init.method || 'GET'} ${path} ${response.status} (${Date.now() - startTime}ms)`);

        if (response.status >= 300) {
            const requestError = getRequestError(response);
            // If the fetch fails because it is unauthorized, we want to refresh the access token to make sure we have a valid tokenZXGBVH
            if (requestError.requestErrorCode === 'UNAUTHORIZED') {
                this._refreshAccessToken?.();
            }

            throw await this._getFetchError(response);
        }

        return response;
    }

    private async _getFetchError(response: Response) {
        // Melville may include error details in the response body.
        if (response.status === 403) {
            try {
                const json = await response.json();
                if (typeof json.type === 'string' && (json.type as string).toLowerCase() === 'quota') {
                    return new LibraryError('EXCEEDS_QUOTA', json.problem_type_message || 'Storage quota exceeded');
                }
            } catch {
                // If the JSON is invalid, ignore it.
            }
        }

        return getRequestError(response);
    }

    async *fetchAllPages<T, U>(
        firstUrl: string,
        init: FetchRequestInit,
        responseMapper: (response: T) => PaginatedResponse<U>,
        signal?: AbortSignal,
        paramsAsHeaders: boolean = true
    ): AsyncGenerator<PaginatedResponse<U>> {
        let nextUrl = firstUrl;
        while (nextUrl) {
            const { headers = {}, ...rest } = init;
            if (paramsAsHeaders) {
                [ nextUrl ] = this.moveUrlQueryParamsToHeaders(nextUrl, headers);
            }

            const response = await this.fetch(nextUrl, { signal, ...rest, headers }).then(res => res.json());
            yield responseMapper(response);
            nextUrl = response._links?.next?.href;
        }
    }

    async *fetchOnePage<T, U>(
        firstUrl: string,
        responseMapper: (response: T) => PaginatedResponse<U>,
        signal?: AbortSignal,
        paramsAsHeaders: boolean = true
    ): AsyncGenerator<PaginatedResponse<U>> {
        let headers: { [s: string]: string } | undefined;
        if (paramsAsHeaders) {
            [ firstUrl, headers ] = this.moveUrlQueryParamsToHeaders(firstUrl);
        }

        const response = await this.fetch(firstUrl, { signal, headers }).then(res => res.json());
        yield responseMapper(response);
    }

