import { gql } from '@apollo/client';

const ProjectFragment = gql`
fragment projectData on Project {
    storage_region
    repo_assetId
    repo_name
    repo_path
    repo_createDate
    repo_createdBy {
        id
        type
        name {
           firstName
           lastName
           displayName
        } 
    }
    repo_state
    repo_assetSubType
    repo_ancestors
    primary_etag
    storage_assignee {
        id
        type
    }
    repository {
        repo_repositoryId
        repo_owner {
            id
            type
            name {
                displayName
            }
        }
    }

    primaryLink {
        href
        templated
    }
    blockUploadLink {
        href
        templated
    }
    discardLink {
        href
        templated
    }
    restoreLink {
        href
        templated
    }
    renameLink {
        href
        templated
    }
    pageLink {
        href
        templated
    }

    effectivePermissions {
        aclPolicy
        annotations
        applicationMetadata
        default
        directory
        primary
    }
    permissions {
        canWrite
        canRename
        canRestore
        canDiscard
        canDelete
    }

    appMetadata {
        project_rendition {
            gradientId
        }
    }
    
    labels {
        lastAccessDate
    }
    sharingInfo {
        sharedWithYou {
            shareDate
            shareTypes
            sharedBy {
                id
            }
        }
    }
}
`;

export const allProjects = gql`
    query AllProjects($first: Int!, $after: String, $filter: AssetListFilter!) {
        allAssets {
            assetListId
            assetListConnection(first: $first, after: $after, filter: $filter) {
                pageInfo {
                    endCursor
                    hasNextPage
                }
                edges {
                    node {
                        ...projectData
                    }
                }
            }
        }
    }
    ${ProjectFragment}
`;

