import type { SAM } from '@ccx-public/component-types';
import { observable } from '../core/decorators';
import ItemBase from '../core/ItemBase';
import SAMError, { SAMErrorCode } from '../core/SAMError';
import type { IRemoteClassroom, IClassroomUpdateData, IImportSource, IRemoteImportSource, ICoTeacherEligibilityEntry, ICheckCoTeacherEligibilityOptions, IUserProfile } from '../interface/ClassroomModel';
import { SubjectTypes, ClassroomStatus, ClassroomType } from '../interface/ClassroomModel';
import ClassroomsInterface from '../interface/ClassroomsInterface';
import PropertyUpdater from '../core/PropertyUpdater';
import ItemUpdater from '../core/ItemUpdater';
import type { ISAMCorePrivate, ISAMObject } from '../indexPrivate';
import type { ClassroomMemberSource } from '../classroom-member/ClassroomMemberSource';
import ItemSource from '../core/ItemSource';
import ClassroomMemberListLoader from '../classroom-member/ClassroomMemberListLoader';
import ClassroomMemberFilter from './ClassroomMemberFilter';
import { ClassroomMemberRole } from '../interface/ClassroomMemberModel';
import type ClassroomMember from '../classroom-member/ClassroomMember';

export const SubjectChoices: SubjectTypes[] = Object.values(SubjectTypes);

/**
 * Class representing the notion of a "classroom".  This is currently a read-only object
 * but this may be extended to support CRUD operations in the future.
 * @extends ItemBase
 *
 * @example
 * // Instatiate list and load contents
 * const classroomsList = core.classroomContext.getClassrooms().getList(...options);
 * await waitForListLoad(classroomsList);
 *
 * // Get a specific classroom
 * const load = useMemo(() => core.classroomContext.getClassroomById(id), [classroomContext, id]);
 * const { value: classroom, error, loading } = useLoading<Classroom | undefined>(undefined, load);
 */
export default class Classroom extends ItemBase implements SAM.Classroom {
    private _code: string = '';
    private _created?: string;
    private _createdBy: string = '';
    private _importSource: IImportSource = {};
    private _isDeleted: boolean = false;
    private _isVirtual: boolean = false;
    private _grades: string[] = [];
    private _members: ClassroomMemberSource;
    private _memberRole: ClassroomMemberRole = ClassroomMemberRole.NONE;
    private _name: string = '';
    private _period: string = '';
    private _status: ClassroomStatus = ClassroomStatus.ACTIVE;
    private _subject: SubjectTypes = SubjectTypes.noSubject;
    private _type?: ClassroomType;
    private _classroomsInterface = new ClassroomsInterface(this._core);
    private _userCount?: number; // User count is not captured for virtual classrooms
    private _assetId: string = '';
    // This field is intended to preserve members provided by the remote item
    // that may not be available through the ClassroomMemberListLoader yet
    private _cachedMembers: ClassroomMember[] = [];
    private _currentUser?: ClassroomMember;
    private _lastAccessDate?: string;

    constructor(readonly _core: ISAMCorePrivate, id: string) {
        super(_core, id);
        const loader = new ClassroomMemberListLoader({ core: this._core, classroomsInterface: this._classroomsInterface });
        this._members = new ItemSource(this._core.classroomContext._classroomMemberPool, [ loader ], new ClassroomMemberFilter({ classroomId: this.id }));
    }

    /**
     * For SAM.js internal use only
     * Due to the classroom ID changing when the classroom is migrated
     * from a virtual to a real class, clients will NOT have access to
     * the new instance of the classroom through their existing reference
     * to the original virtual instance of the class.
     *
     * To support classroom workflow reattempts directly following the migration
     * of the virtual class when the client is still referencing the class
     * ID when it was virtual, the virtual instance of the class ID will persist
     * on this session's migrated instance of the class.
     */
    _virtualId?: string;

    @observable
    get code(): string {
        return this._code;
    }

    @observable
    get created(): Date | undefined {
        if (!this._created) {
            return undefined;
        }

        return new Date(this._created);
    }

    @observable
    get createdBy(): string {
        return this._createdBy;
    }

    @observable
    get lastAccessed(): Date | undefined {
        if (!this._lastAccessDate) {
            return undefined;
        }

        const date = new Date(this._lastAccessDate);
        if (date.toString() === 'Invalid Date') {
            return undefined;
        }
        return date;
    }

    @observable
    get importSource(): IImportSource {
        return this._importSource;
    }

    @observable
    get isDeleted(): boolean {
        return this._isDeleted;
    }

    @observable
    get isVirtual(): boolean {
        return this._isVirtual;
    }

    @observable
    get grades(): string[] {
        return this._grades;
    }

    /**
     * When getting the resulting list from the ClassroomMemberSource, include a role on the filter to get only students or teachers back
     *
     * @example <caption>Get all students</caption>
     * const studentList = classroom.members.getList(ClassroomMemberOrder.default, new ClassroomMemberFilter({ classroomId: classroom.id, role: ClassroomMemberRole.STUDENT }));
     * waitForListLoad(studentList);
     * const students: ClassroomMember[] = studentList.items;
     *
     * @example <caption>Get all members</caption>
     * const allMembersList = classroom.members.getList(ClassroomMemberOrder.default, new ClassroomMemberFilter({ classroomId: classroom.id}));
     * waitForListLoad(allMembersList);
     * const allMembers: ClassroomMember[] = allMembersList.items;
     */
    @observable
    get members(): ClassroomMemberSource {
        return this._members;
    }

    @observable
    get membership(): ClassroomMember | undefined {
        return this._currentUser;
    }

    @observable
    get memberRole(): ClassroomMemberRole {
        return this._memberRole;
    }

    @observable
    get name(): string {
        return this._name;
    }

    @observable
    get period(): string {
        return this._period;
    }

    @observable
    get status(): ClassroomStatus {
        return this._status;
    }

    @observable
    get subject(): SubjectTypes {
        return this._subject;
    }

    @observable
    get type(): ClassroomType | undefined {
        return this._type;
    }

    @observable
    get userCount(): number | undefined {
        // For now, userCount is calculated as studentCount + 1.
        // In the future, this could give an inaccurate count if we allow multiple teachers to one classroom
        // Follow up on this field in [ACPCEDU-2333]
        return this._userCount;
    }

    /**
     * This is the asset ID of the classroom folder.
     * The classroom ID is the classroom org ID
     */
    @observable
    get assetId(): string {
        return this._assetId;
    }

    /**
     * @package Only for use in SAM.js.
     * Returns the cached members if they were provided in the API response.
     */
    @observable
    get _cachedMembersList(): ClassroomMember[] {
        return this._cachedMembers;
    }

    /**
     * Deletes this classroom, along with all assignments and other child object
     *
     * @example <caption>Delete a classroom</caption>
     * await classroom.delete();
     */
    async delete(): Promise<void> {
        await this._classroomsInterface.deleteClassroom(this.id);
    }

    /**
     * Refreshes the classroom code
     *
     * @example <caption>Refresh the classroom code</caption>
     * await classroom.refreshCode();
     */
    async refreshCode(): Promise<void> {
        this._classroomsInterface.refreshClassroomCode(this.id);
    }

    /**
     * Updates a classroom's data
     *
     * @example <caption>Update a Classrooms name</caption>
     * await classroom.update({ name: 'New Name' });
     */
    async update(data: IClassroomUpdateData): Promise<void> {
        return this._core.classroomContext.updateClassroom(this.id, data);
    }

    /**
     * Checks if the co-teacher is eligible to be added to the classroom
     *
     * @example <caption>Check if the co-teacher is eligible to be added to the classroom</caption>
     * await classroom.checkCoTeacherEligibility({ emails: ['test@test.com'] });
     */
    async checkCoTeacherEligibility(options: ICheckCoTeacherEligibilityOptions): Promise<Array<ICoTeacherEligibilityEntry>> {
        return this._classroomsInterface.checkCoTeacherEligibility({ ...options, classroomId: this.id });
    }

    /**
     * Update lastAccessed Per User Per Asset (PUPA) metadata
     * @returns {Promise<void>}
     * @throws {SAMError} If the classroom is virtual
     */
    async updateLastAccessed(): Promise<void> {
        if (this.isVirtual || !this.assetId) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Cannot update lastAccessed for virtual classrooms');
        }

        const accessDate = new Date();

        // Update last access date using the PLS API
        const gqlManager = await this._core._getGQLManager();
        await gqlManager.updateLastAccessed(this.assetId, accessDate.toISOString());

        // Update last access date on the classroom local item
        const session = this._core.classroomContext._classroomPool.createUpdateSession();
        ClassroomUpdater.updateLocalItem(session, this, {
            lastAccessDate: accessDate.toISOString(),
        });
        session.commit();
    }
}

function getAlternateClassroomId(remoteItem: Partial<IRemoteClassroom>): string | undefined {
    return remoteItem.virtualId;
}

export const ClassroomUpdater = new ItemUpdater<Classroom, Partial<IRemoteClassroom>>({
    localItemType: Classroom,
    remoteIdProperty: 'classId',
    getAlternateId: getAlternateClassroomId,
    propertyUpdater: new PropertyUpdater({
        _assetId: { name: 'assetId', format: 'string' },
        _code: { name: 'classCode', format: 'string' },
        _created: { name: 'createdOn', format: 'string' },
        _createdBy: { name: 'createdBy', format: 'string' },
        _importSource: {
            name: 'importedFrom',
            format: 'object',
            set: (remoteImportSource: IRemoteImportSource, dest: ISAMObject) => {
                const classroom = dest as Classroom;

                classroom['_importSource'] = {
                    id: remoteImportSource.sourceId,
                    type: remoteImportSource.source,
                    synced: remoteImportSource.lastUpdatedAt ? new Date(remoteImportSource.lastUpdatedAt) : undefined,
                };
            },
        },
        _isDeleted: { name: 'deleted', format: 'boolean' },
        _isVirtual: { name: 'isVirtualClassroom', format: 'boolean' },
        _grades: { isArray: true, name: 'grades' },
        _memberRole: { name: 'memberRole', format: 'string' },
        _name: { name: 'className', format: 'string' },
        _period: { name: 'period', format: 'string' },
        _status: { name: 'status', format: 'string', choices: Object.values(ClassroomStatus) },
        _subject: { name: 'subject', format: 'string', choices: SubjectChoices },
        _cachedMembers: {
            isArray: true,
            name: 'members',
            format: 'object',
            set: (remoteMembers: IUserProfile[], dest: ISAMObject) => {
                const classroom = dest as Classroom;
                classroom['_cachedMembers'].length = 0;

                if (remoteMembers && remoteMembers.length > 0) {
                    const members = classroom._core.classroomContext._updateMembersCache({
                        remoteMembers,
                        classroomId: classroom.id
                    });
                    classroom['_cachedMembers'].push(...members);
                }
            }
        },
        _type: { name: 'type', format: 'string', choices: Object.values(ClassroomType) },
        _userCount: { name: 'userCount', format: 'number' },
        _virtualId: { name: 'virtualId', format: 'string' },
        _lastAccessDate: { name: 'lastAccessDate', format: 'string' },
        _currentUser: {
            name: 'user',
            format: 'object',
            set: (remoteUser: IUserProfile | undefined, dest: ISAMObject) => {
                const classroom = dest as Classroom;

                classroom['_currentUser'] = classroom._core.classroomContext._updateCurrentMemberCache({
                    classroomId: classroom.id,
                    remoteUser,
                });
            }
        },
    }),
});
