import { observable } from '../core/decorators';
import ItemBase from '../core/ItemBase';
import PropertyUpdater from '../core/PropertyUpdater';
import ItemUpdater from '../core/ItemUpdater';
import type { IProjectsOrgRepository, IProjectsTeamCreateData } from '../interface/WorkspacesModel';
import type Team from './Team';

export default class OrgRepository extends ItemBase {

    private _repositoryID: string = '';

    @observable
    get repositoryID(): string {
        return this._repositoryID;
    }

    /**
     * Create a team under /content/assets folder.
     */
    async createTeam(data: IProjectsTeamCreateData): Promise<Team> {
        return await this._core.spaceContext.createTeam(this, data);
    }
}

export const OrgRepositoryUpdater = new ItemUpdater<OrgRepository, Partial<IProjectsOrgRepository>>({
    localItemType: OrgRepository,
    remoteIdProperty: 'repositoryId',
    propertyUpdater: new PropertyUpdater({
        '_repositoryID': 'repositoryId'
    })
});
