import { getUSSFetchFields } from './AssetModel';
import InterfaceBase from './InterfaceBase';
import type { ISearchQuery, USSResponse } from './USSModel';
import { OrderByToUSSOrderBy, SearchProps } from './USSModel';
import {
    updateAssetTypeForUSS
} from './USSUtils';
import type { IOrderDirection } from '../core/ItemOrder';
import type { USSAdobeAssetOrderField } from '../assets/USSAdobeAssetOrder';

interface IListingOptions {
    limit: number;
    start: number;
    orderDirection: IOrderDirection;
    orderBy: USSAdobeAssetOrderField;
}


export interface FFBoardsAssetsListingOptions extends IListingOptions {
    mediaTypes?: string[],
    isSharedWithYou?: boolean,
    ownedBy?: string
}

const DEFAULT_MAX_LIMIT = 50;

const DefaultListingOptions: IListingOptions = {
    start: 0,
    limit: DEFAULT_MAX_LIMIT,
    orderDirection: 'descending',
    orderBy: 'modified'
};

export default class FFBoardsInterface extends InterfaceBase {
    private _getCommonFilters(options?: Partial<IListingOptions>): ISearchQuery {
        const listingOptions: IListingOptions = { ...DefaultListingOptions, ...options };

        return {
            hints: {
                acp_platform_v2: true,
            },
            fetch_fields: { includes: [ ...getUSSFetchFields(), '_embedded' ] }, //include effective permissions
            limit: listingOptions.limit,
            start_index: listingOptions.start,
            op_none_of: [
                {
                    [SearchProps.VISIBILITY]: [ 'hiddenSelf', 'hiddenRecursive' ],
                }
            ],
            sort_orderby: OrderByToUSSOrderBy[listingOptions.orderBy],
            sort_order: listingOptions.orderDirection === 'ascending' ? 'asc' : 'desc'
        };
    }

    async getAssets(options: FFBoardsAssetsListingOptions): Promise<USSResponse> {
        const { ownedBy, isSharedWithYou, mediaTypes, ...listingOptions } = options;
        const filters = this._getCommonFilters(listingOptions);

        if (ownedBy) {
            filters[SearchProps.STORAGE_ASSIGNEE_ID] = ownedBy;
        }

        if (isSharedWithYou !== undefined) {
            filters[SearchProps.SHARED_VIA_INVITE] = isSharedWithYou;
        }

        if (mediaTypes && mediaTypes.length > 0) {
            updateAssetTypeForUSS(mediaTypes);
            filters[SearchProps.TYPE] = mediaTypes;
        }

        return this._core.hostAssetContext._ussInterface.getQueryResponse(filters);
    }
}
