import type { LibraryFilterOptions } from '../libraries/LibraryFilter';
import LibraryFilter from '../libraries/LibraryFilter';
import type { IExplicitFilter } from '../core/ItemFilter';
import type Library from '../libraries/Library';
import { LibraryOwnerFilter, LibraryRolesFilter } from '../interface/LibraryModel';

export default class TrainingSetFilter extends LibraryFilter implements IExplicitFilter<Library> {
    static DEFAULT = new TrainingSetFilter();

    constructor(options?: Pick<LibraryFilterOptions, 'project'>) {
        super({ ...options, owner: [ LibraryOwnerFilter.All ], roles: [ LibraryRolesFilter.TrainingSet ] });
    }
}
