import type { IItemLoader, ILoadedPage } from '../../core/ItemLoader';
import type ItemPool from '../../core/ItemPool';
import type { ISAMCorePrivate } from '../../indexPrivate';
import type { ElementSourceConfig } from '../../library-contents/models/ElementSource';
import type { ElementPoolId } from './Element';
import type Element from './Element';
import { ElementUpdater } from './Element';
import type Driver from '../../library-contents/drivers/Driver';
import type { ElementSort } from '../../library-contents/drivers/Driver';
import type Library from '../../libraries/Library';
import type { IItemLoaderOptions } from '../../core/ItemLoader';
import type ElementOrder from '../../library-contents/models/ElementOrder';
import type { ILoadNextPage } from '../../core/ItemLoader';
import type { ElementsResponse } from '@sam-js-src/library-contents/drivers/CloudDriver/utils/melvilleModelMappers';
import { mapResponseToElementData } from '../../library-contents/drivers/CloudDriver/utils/melvilleModelMappers';
import { getMostRecentValidMutation } from '../../utils/loaderUtils';


function ElementOrderToElementSort(order?: ElementOrder): ElementSort | undefined {
    if (!order) {
        return undefined;
    }

    const sortField = order.field === 'name' ? order.field : 'modifiedDate';
    return {
        field: sortField,
        direction: order.direction
    };
}

export default class ElementListLoader implements IItemLoader<ElementSourceConfig> {
    constructor(
        private _core: ISAMCorePrivate,
        private _elementPool: ItemPool<Element, ElementPoolId>,
        private _driver: Driver,
        private _library: Library
    ) {}


    public async loadPage(options?: IItemLoaderOptions<ElementSourceConfig>) {
        return this._loadPage(options);
    }

    private async _loadPage(options?: IItemLoaderOptions<ElementSourceConfig>, start: number = 0): Promise<ILoadedPage<ElementSourceConfig>> {
        const response = await this._driver.getElementsPage(this._library, start, options?.loadOptions?.limit, ElementOrderToElementSort(options?.order), this._library.etag);

        const latency = this._core._environment.getValue('USS_LIST_UPDATE_LATENCY');
        const mostRecentValidMutation = getMostRecentValidMutation(options?.resource, latency);

        const items = await this._updatePoolFromPage(response, mostRecentValidMutation);

        return {
            items,
            total: response.total_count,
            mostRecentValidMutation,
            loadNextPage: this._nextPageLinkFromResponse(response)
        };
    }

    private async _updatePoolFromPage(response: ElementsResponse, mostRecentValidMutation: number): Promise<Element[]> {
        const elements = response.elements.map(element => {
            const data = mapResponseToElementData(element);

            // Melville may not always include the library asset id, but we always know it. This data is required by the Element, so we add it in.
            data.libraryAssetId = this._library.id;
            return data;
        });

        const session = this._elementPool.createLoaderUpdateSession<Element>(mostRecentValidMutation);
        const items = ElementUpdater.updateRemoteItems(session, elements);
        session.commit();

        return items;
    }

    private _nextPageLinkFromResponse(response: ElementsResponse):  ILoadNextPage<ElementSourceConfig> | undefined {
        const nextStart = response._page?.next;
        if (!nextStart) {
            return undefined;
        }
        return (options) => this._loadPage(options, nextStart);
    }
}
