import { DocumentTransform } from '@apollo/client';
import { Kind, type OperationDefinitionNode, visit } from 'graphql';
import { ApolloLink } from '@apollo/client';
import { map } from 'rxjs';

export const TIMESTAMP_KEY = '_timestamp';

/**
 * Recursively adds timestamps to GraphQL responses (objects that contain __typename fields).
 * Mutates the original object.
 */
export function addTimestampsToGraphQLResponse(data: any): any {
    if (data && typeof data === 'object') {
        for (const key in data) {
            if (key === '__typename' && typeof data[key] === 'string') {
                data[TIMESTAMP_KEY] = Date.now();
            } else {
                addTimestampsToGraphQLResponse(data[key]);
            }
        }
    }
    return data;
}

/**
 * An ApolloLink that adds timestamps to GraphQL responses.
 */
export const addTimestampsApolloLink = new ApolloLink((operation, forward) => {
    // Strip the timestamps before we send it to the server, because it'd error if we request nonexistent properties.
    operation.query = stripTimestampDocumentTransform.transformDocument(operation.query);
    return forward(operation).pipe(map(result => {
        operation.query = timestampDocumentTransform.transformDocument(operation.query);
        return addTimestampsToGraphQLResponse(result);
    }));
});

/**
 * Recursively finds the minimum timestamp value within an object or array structure,
 * defaulting to the current timestamp if no timestamp fields are found.
 */
export function getOldestTimestamp(object: any, defaultTimestamp = Date.now()): number {
    if (Array.isArray(object)) {
        return Math.min(...object.map(item => getOldestTimestamp(item, defaultTimestamp)), defaultTimestamp);
    } else if (typeof object === 'object' && object !== null) {
        const objectTimestamp = (TIMESTAMP_KEY in object && typeof object[TIMESTAMP_KEY] === 'number')
            ? object[TIMESTAMP_KEY] : defaultTimestamp;
        return Math.min(objectTimestamp, ...Object.values(object).map(v => getOldestTimestamp(v, defaultTimestamp)));
    } else {
        return defaultTimestamp;
    }
}


/**
 * A DocumentTransform that removes the TIMESTAMP_KEY field from all GraphQL queries.
 */
export const stripTimestampDocumentTransform = new DocumentTransform((document) => {
    return visit(document, {
        SelectionSet(node) {
            const filteredSelections = node.selections.filter(selection =>
                !(selection.kind === 'Field' && selection.name.value === TIMESTAMP_KEY)
            );

            if (filteredSelections.length !== node.selections.length) {
                return {
                    ...node,
                    selections: filteredSelections,
                };
            }
        }
    });
});

/**
 * A DocumentTransform that adds the TIMESTAMP_KEY field to all GraphQL queries,
 * in the same way that Apollo adds __typename. The timestamp value is populated locally
 * with an ApolloLink when the response is processed.
 *
 * NOTE: We do NOT use the `@client` directive for the TIMESTAMP_KEY field, even though
 * that seems like a good fit. This is because Apollo doesn't allow queries to contain
 * both `@defer` and `@client` directives in the same query; we don't want to prevent
 * clients from using `@defer`, so we handle the timestamp field via middleware here.
 */
export const timestampDocumentTransform = new DocumentTransform((document) => {
    return visit(document, {
        SelectionSet(node, key, parent) {
            // Don't add a timestamp to OperationDefinitions, only to SelectionSets within them.
            // (This is the same behavior as Apollo's "__typename" modification).
            if ((parent as OperationDefinitionNode)?.kind === Kind.OPERATION_DEFINITION) {
                return;
            }

            // If node doesn't have the TIMESTAMP_KEY field add it.
            if (!node.selections.some(selection =>
                selection.kind === 'Field'
                && selection.name.value === TIMESTAMP_KEY
            )) {
                return {
                    ...node,
                    selections: [
                        ...node.selections,
                        {
                            kind: 'Field',
                            name: { kind: 'Name', value: TIMESTAMP_KEY },
                        },
                    ],
                };
            }
        }
    });
});
