export type PaginatedResponse<T> = T[];
export type Folder = number;
export type SearchRequest = number;
export type StockSearchRequest = number;
export type StockAsset = number;
export type SyncStatus = number;

export type DriverOptions = {
    enableBrandLifecycleManagement?: boolean;
    readOnly?: boolean;
    retryCount?: number;
    skipConnectingOnInit?: boolean;
    includeApprovedBrandsInLibraries?: boolean;
};

export type SearchFilters = {
    elements_only?: boolean;
    library_id?: string;
    element_types?: string[];
};

export type ElementSort = {
    sectionType?: 'group' | 'type';
    sections?: string[];
    field: 'name' | 'modifiedDate';
    direction: 'ascending' | 'descending';
};

export type GetElementsOptions = {
    types: ('elements' | 'removedElements' | 'documentationElements')[];
    sort?: ElementSort;
    abortController?: AbortController;
    etag?: string;
    loadProgressively?: boolean; // Should only load progressively if the elements have not already been loaded/restored and areElementsLoaded is false
};

export type OperationClass<T> = { supportsAction: (action: Action) => boolean } & (new (
    driver: T,
    library: Library
) => Operation<T>);

export type GetLibraryOptions = {
    etag?: string;
    firstElementsLoad?: boolean;
    elementParams?: GetElementsOptions;
    getRenditionGrid?: boolean;
    getAppMetadata?: boolean;
    optimisticFetch?: boolean;
    locallyManaged?: boolean;
};

export enum ConnectionState {
    CONNECTED = 'connected',
    CONNECTING = 'connecting',
    LOADING = 'loading',
    ERROR = 'error'
}

/**
 * The supported filter values to use when fetching libraries.
 * Matches Melville's API
 * @see https://git.corp.adobe.com/pages/Stormcloud/apidocs/?urls.primaryName=melville#/Libraries/getLibraries
 */
type LibrarySelectors = 'default' | 'details' | 'collaboration' | 'groups' | 'rendition_grid' | 'app_metadata';
type LibraryOwnership = 'all' | 'private' | 'incoming' | 'public' | 'other';
type TeamFilter = 'all' | 'none' | 'other' | TeamData['id'];
type LibraryCapabilities = 'write';
type RolesFilter = 'none' | Role['type'];
type ToolkitFilter = 'all' | 'none' | string;
type ItemFilter = 'allBrands' | 'allEditableBrands' | 'publishedBrands';
export type LibraryListFilters = {
    owner?: LibraryOwnership[];
    team?: TeamFilter[];
    roles?: RolesFilter[];
    toolkit?: ToolkitFilter[];
    selector?: LibrarySelectors[];
    capabilities?: LibraryCapabilities[];
    workspace?: string;
    start?: number;
    limit?: number;
    itemFilter?: ItemFilter[];
};

export type ConnectorParam<T> = (abortSignal?: AbortSignal) => Promise<void | T>;

export type FetchRequestInit = RequestInit & { headers?: { [s: string]: string } };

async function collectAll<T>(iterator: AsyncIterable<T[]>) {
    const all: T[] = [];

    for await (const page of iterator) {
        all.push(...page);
    }

    return all;
}

/**
 * Interface for an API driver for use in the CC Libraries orchestration API.
 */
export default abstract class Driver<T = {}, U extends DriverOptions = DriverOptions> extends RestrictedEventEmitter implements ISAMObject {
    private _connectionPromise?: Promise<void>;
    private _isConnected = false;
    _failedConnectionAttempt = false;
    protected _options: U = {} as U;
    protected _localStorage?: StorageInterface;
    protected _abortController?: AbortController;
    protected _operationTypes?: OperationClass<any>[];
    protected _config = new Configuration({ config: {}, environment: 'production' });
    protected _cachedFetch = promiseCache(fetch);
    protected _token?: string;

    /**
     * @package -- only for use in SAM.js
     */
    public _core: ISAMCorePrivate;

    _loadElementsAbortController = new AbortController();

    constructor(core: ISAMCorePrivate, protected _connector: ConnectorParam<T>) {
        super();
        this._core = core;
    }

    get config() {
        return this._config;
    }

    get environment() {
        return this._config.environment;
    }

    get token() {
        return this._token;
    }

    get isConnected() {
        return this._isConnected;
    }

    get connectionState() {
        if (this._failedConnectionAttempt) {return ConnectionState.ERROR;}
        if (this.isConnected) {return ConnectionState.CONNECTED;}
        if (this._connectionPromise) {return ConnectionState.CONNECTING;}
        return ConnectionState.LOADING;
    }

    resetAbortController() {
        this._abortController = new AbortController();
    }

    /**
     * @internal
     */
    get abortController() {
        return this._abortController;
    }

    init(
        options: U = {} as U,
        onConnect: (driver: this) => void = () => undefined,
        onDisconnect: () => void = () => undefined
    ) {
        this._options = { ...this._options, ...options };
        this.on('connect', onConnect);
        this.on('disconnect', onDisconnect);
        if (this._options.skipConnectingOnInit) {
            return Promise.resolve();
        }
        return this.connect();
    }

    private get _isConnectingOrConnected() {
        return Boolean(this._abortController && !this._abortController.signal.aborted);
    }

    connect() {
        if (this._isConnectingOrConnected) {
            return this._connectionPromise;
        }

        this.resetAbortController();
        this._connectionPromise = this._connect();
        this.emit('connecting');

        return this._connectionPromise;
    }

    //TODO: restructure this to use promises correctly after unit tests are in place
    //https://jira.corp.adobe.com/browse/SHARED-4386
    private async _attemptToConnect(abortSignal?: AbortSignal): Promise<boolean> {
        const fn = async (resolve: (value: (boolean | PromiseLike<boolean>)) => void) => {
            try {
                // forcibly reject a timeout. This way we ensure we always catch and resolve a negative value.
                const { future, cancel } = timoutFutureFactory(SignalType.REJECT, connectorTimeout);

                // race between the connector getting the information we require and the rejecting timeout above.
                const abortController = new AbortController();
                const connectionInfo = (await Promise.race([ this._connector(abortController.signal), future ]).finally(
                    () => {
                        abortController.abort();
                        cancel();
                    }
                )) as T;

                // have we aborted in the time we have asked for connection information?
                if (abortSignal?.aborted) {
                    return resolve(false);
                }

                // subclass connection handlers (can also throw)
                await this._handleConnected(connectionInfo);

                // if we got here we can claim to be connected and resolve truthy
                this._isConnected = true;
                return resolve(true);
            } catch (e) {
                return resolve(false);
            }
        };

        return new Promise<boolean>(resolve => fn(resolve)).then(state => {
            this._failedConnectionAttempt = !state;
            if (this._failedConnectionAttempt) {this.emit('failedConnection');}
            return state;
        });
    }

    private async _connect() {
        const currentAbortSignal = this._abortController?.signal;

        for (let i = 0; !(await this._attemptToConnect(currentAbortSignal)); i += 1) {
            if (this._options.retryCount !== undefined && this._options.retryCount <= i) {
                Logger.log(`[DRIVER] Failed to connect to server (Attempt: ${i}). Exceeded max retries.`);
                return;
            }

            const interval = backoffIntervals[Math.min(i, backoffIntervals.length - 1)] * 1000;
            Logger.log(`[DRIVER] Failed to connect to server (Attempt: ${i}). Will retry in ${interval}ms.`);

            try {
                await sleep(interval, currentAbortSignal);
            } catch (error) {
                if (error instanceof Error && error.name === 'AbortError') {
                    return;
                }

                throw error;
            }
        }
        this.emit('connect', this);
    }

    protected abstract _handleConnected(data: T): Promise<void>;
    protected abstract _handleDisconnected(): void;

    disconnect() {
        this._abortController?.abort();
        this._isConnected = false;
        this._failedConnectionAttempt = false;
        this._handleDisconnected?.();
        this.emit('disconnect', this);
    }

    async reconnect() {
        Logger.warn('Process restart. Attempting to reconnect');
        this.disconnect();
        await this.connect();
    }

    sleep(time: number, signal?: AbortSignal) {
        return sleep(
            time,
            signal && this._abortController?.signal
                ? combineSignals(signal, this._abortController.signal)
                : this._abortController?.signal
        );
    }

    abstract fetchAccessToken(userId: string, clientId: string, clientSecret: string, scopes: string): any;

    /**
     * Loads a page of libraries and optionally rendition grids
     */
    abstract getLibraries(
        signal?: AbortSignal,
        getRenditionGrids?: boolean
    ): AsyncGenerator<PaginatedResponse<LibraryData>>;

    abstract getLibrariesList(
        signal?: AbortSignal,
        filters?: LibraryListFilters
    ): AsyncGenerator<PaginatedResponse<LibraryData>>;

    abstract getLibrariesPage(
        signal?: AbortSignal,
        filters?: LibraryListFilters
    ): AsyncGenerator<PaginatedResponse<LibraryData>>;

    getAllLibraries(signal?: AbortSignal, getRenditionGrids?: boolean): Promise<LibraryData[]> {
        return collectAll(this.getLibraries(signal, getRenditionGrids));
    }

    /**
     * Loads a single library.
     * @param library     The existing library object
     */
    abstract getLibrary(library: Library, options?: GetLibraryOptions): AsyncGenerator<Partial<LibraryData>>;

    abstract getLibraryById(idOrAssetId: string, options?: GetLibraryOptions): Promise<LibraryData>;

    /**
     * Moves a library.
     * @param libraryId     The ID of the library to be moved
     * @param folderId      The ID of the folder to which the library will be moved
     */
    abstract moveLibrary(libraryId: string, folderId: string, organizationId?: string): Promise<LibraryData | void>;

    /**
     * Returns a generator that yields a page of Elements.
     * Note: On CloudDriver, it will fetch *all pages* up front and then yield each page.
     * Recommendation is to use getElementPage instead moving forward.
     * @params libraryId    The ID of the parent library
     */
    abstract getElements(
        library: Library,
        sort?: ElementSort,
        etag?: string,
        limit?: number,
        signal?: AbortSignal
    ): AsyncGenerator<PaginatedResponse<ElementData>>;

    /**
     * Fetches a single page of elements and returns a promise resolving to that page.
     * Note: Does not manipulate the response in any way. Receiver should map the data as needed.
     * @params library    The parent library
     */
    abstract getElementsPage(
        library: Library,
        start?: number,
        limit?: number,
        sort?: ElementSort,
        etag?: string
    ): Promise<ElementsResponse>;

    /**
     * Fetches all elements pages and returns a promise resolving to the full array of elements
     */
    getAllElements(library: Library, sort?: ElementSort, etag?: string): Promise<ElementData[]> {
        return collectAll(this.getElements(library, sort, etag));
    }

    abstract getRepresentationContent(representation: Representation): Promise<Response>;

    /**
     * Loads a page of elements.
     * @params libraryId    The ID of the parent library
     */
    abstract getSearchResults(
        searchQuery: string,
        filters: SearchFilters,
        elementSort: ElementSort,
        signal: AbortSignal
    ): AsyncGenerator<PaginatedResponse<ElementData>>;

    /**
     * Loads a page of documentation elements.
     * @params libraryId    The ID of the parent library
     */
    abstract getDocumentationElements(
        library: Library,
        sort?: ElementSort,
        etag?: string,
        limit?: number
    ): AsyncGenerator<PaginatedResponse<ElementData>>;

    getAllDocumentationElements(library: Library, sort?: ElementSort, etag?: string): Promise<ElementData[]> {
        return collectAll(this.getDocumentationElements(library, sort, etag));
    }

    /**
     * Loads a page of removed elements.
     * @params libraryId    The ID of the parent library
     */
    abstract getRemovedElements(
        library: Library,
        sort?: ElementSort,
        etag?: string,
        limit?: number
    ): AsyncGenerator<PaginatedResponse<ElementData>>;

    getAllRemovedElements(library: Library, sort?: ElementSort, etag?: string): Promise<ElementData[]> {
        return collectAll(this.getRemovedElements(library, sort, etag));
    }

    /**
     * Loads a single element.
     * @param libraryId     The ID of the parent library
     * @param elementId     The ID of the element to load
     */
    abstract getElement(library: Library, elementId: string): Promise<ElementData>;

    abstract getGroups(libraryId: string): AsyncGenerator<PaginatedResponse<GroupData>>;

    getAllGroups(libraryId: string): Promise<GroupData[]> {
        return collectAll(this.getGroups(libraryId));
    }

    abstract getTeams(): Promise<TeamData[]>;

    abstract getProjects(): Promise<TeamData[]>;

    abstract getProjectGradient(project: Team): Promise<GradientData | undefined>;

    abstract getRenditionUrl(element: Element, size: RenditionSize): string;

    abstract getAuthenticatedThumbnailURL(element: Element, size: RenditionSize): Promise<string>;

    /**
     * Get the path to a rendition on disk.
     * @param libraryId
     * @param elementId
     * @param size
     */
    abstract getRenditionPath(libraryId: string, elementId: string, size: RenditionSize): Promise<string>;

    abstract getRendition(element: Element, size: RenditionSize): Promise<Response>;

    abstract followLibrary(assetId: string, libraryId: string): Promise<void>;

    abstract importLibrary(
        file: string | File,
        callback: (error?: Error, libraryData?: LibraryData) => unknown
    ): AsyncResponse<any>;

    abstract exportLibrary(library: Library, path?: string, callback?: (error?: Error) => unknown): AsyncResponse<any>;

    publishBrand(_brand: Library): Promise<Response> {
        throw new LibraryError('NOT_IMPLEMENTED', 'Driver.publishBrand is not implemented.');
    }

    unpublishBrand(_brand: Library): Promise<Response> {
        throw new LibraryError('NOT_IMPLEMENTED', 'Driver.unpublishBrand is not implemented.');
    }

    // Start watching the given `libraries` for changes, calling `callback` with the ids of any changed libraries.
    // By default it's assumed that the driver implementation calls the callback with library ids, but if passing in
    // asset ids (e.g. as we get from the cloud driver via ONS) it can be called with index = 'assetId'.
    abstract setLibraryChangeListener(
        libraries: LibraryData[],
        callback: (ids: string[], index?: any) => any
    ): void;

    setRenditionCacheChangeListener(_cb: (element: ElementData) => void) {
        return;
    }

    // Add a library to the list of assets being watched for changes.
    addWatchedLibrary(_library: LibraryData): void {
        return;
    }

    // Remove a library from the list of assets being watched for changes.
    removeWatchedLibrary(_library: LibraryData): void {
        return;
    }

    addLibrariesSyncGroupListener(_cb: () => void): void {
        return;
    }
    removeLibrariesSyncGroupListener(): void {
        return;
    }

    // In LocalDriver mode there are two levels of sync state:
    // 1. In Browser
    // 2. In Process
    //
    // This API is used to detect the process sync state.
    abstract setSyncStateListener(callback: (state: SyncStateNotification) => void): void;
    // This API is used to detect any process system font data changes
    abstract setFontDataChangeListener(callback: () => void): void;

    abstract removeLibraryChangeListener(): void;
    abstract removeSyncStateListener(): void;
    abstract removeFontDataChangeListeners(): void;

    operationFactory(Op: OperationClass<Driver>, driver: Driver, library: Library): Operation<Driver> {
        return new Op(driver, library);
    }

    getOperationTypes(_library: Library) {
        return this._operationTypes;
    }

    /**
     * From an array of actions, form an atomic operation
     * @param actions
     */
    constructOperation(library: Library): Operation<Driver> | undefined {
        if (library.actions.length === 0) {
            return undefined;
        }

        // If the driver is set as readOnly, don't allow any operations to be registered
        if (this._options.readOnly) {
            throw new LibraryError('NOT_ALLOWED', 'Cannot perform write action -- in read-only mode.');
        }

        const Op = this.getOperationTypes(library)?.find(klass => klass.supportsAction(library.actions[0]));

        if (!Op) {
            // If the action cannot be mapped to an operation, we have a problem.
            // TODO: Error
            throw new Error();
        }

        const operation = this.operationFactory(Op, this as Driver, library);

        for (const action of library.actions) {
            if (!operation.addAction(action)) {
                break;
            }
        }

        return operation;
    }

    abstract fetch(path: string, init?: RequestInit): Promise<Response>;

    abstract getConfiguration(): Promise<Configuration>;

    abstract sendAction(applicationAction: ApplicationAction): Promise<Response>;

    abstract openInCCD(path: string): Promise<Response>;

    protected getLocalSettings(): ConfigData {
        const settings = this._localStorage ?? new Map();
        return { config: Object.fromEntries(settings.entries()) };
    }

    abstract setLocalSetting(key: string, value: any): Promise<void>;

    abstract getLocalSetting(key: string): any;

    abstract getInstalledVersion(appCode: string): any;

    abstract copyFile(source: string, destination: string, allowOverride?: boolean): Promise<string>;

    abstract getFileSize(path: string): Promise<string>;

    abstract getRenditionGrid(library: Library): Object | undefined;

    abstract stageRepresentationForCommit(library: Library, file: File, type?: string): Promise<string>;

    abstract getTempDir(library: Library): Promise<string>;

    abstract abortOperation(operationId: string): Promise<Response>;

    /**
     * Loads a page of collaborators.
     * @param assetId The library's asset ID.
     */
    abstract getCollaborators(assetId: string): Promise<CollaboratorData[]>;

    /**
     * should return whether driver should ignore local syncChanges for sync Status Calculation
     */
    abstract ignoreLocalSyncEvents(): boolean;
}
