/**
 * The Operation Document describes requests that manipulate Assets within a Repository.
 */
export type IOperationQuery = IOperation | IOperation[];

export type IOperation =
    | ICopyOperation
    | IPublishOperation
    | IRemixOperation
    | ICopyResourcesOperation
    | IMoveOperation
    | IDeleteOperation
    | IDiscardOperation
    | IRestoreOperation
    | IPackageOperation;

export type AssetRef =
    | IAssetRefRepoPath
    | IAssetRefRepoAssetId
    | IAssetRefPath
    | IAssetRefRepoId
    | IAssetRefHref;

export type AssetRefWithoutVersion =
    | Omit<IAssetRefRepoPath, 'repo:version'>
    | Omit<IAssetRefRepoAssetId, 'repo:version'>
    | Omit<IAssetRefPath, 'repo:version'>
    | Omit<IAssetRefRepoId, 'repo:version'>
    | Omit<IAssetRefHref, 'repo:version'>;

interface IAssetRefBase {
    'if-match'?: string;
    'if-none-match'?: string;
    'repo:version'?: string;
}

export interface IAssetRefRepoPath extends IAssetRefBase {
    'repo:path': string;
    'repo:baseAssetId'?: string;
    'repo:repositoryId': string;
}

export interface IAssetRefRepoAssetId extends IAssetRefBase {
    'repo:assetId': string;
    'repo:repositoryId'?: string;
}

export interface IAssetRefPath extends IAssetRefBase {
    path: string;
}

export interface IAssetRefRepoId extends IAssetRefBase {
    'repo:id': string;
}

export interface IAssetRefHref extends IAssetRefBase {
    href: string;
}

/**
 * If the resource is a component in a composite, component_id identifies the exact component referenced
 */
export type ComponentId = string;

/**
 * If the resource is a component in a composite, the revision provides identifies the exact revision of the component
 */
export type Revision = string;

/**
 * If an individual resource is being identified, this property represents that resource's entity tag
 */
export type EntityTag = string;


export interface IResourceDesignator {
    reltype: RelType;
    component_id?: ComponentId;
    revision?: Revision;
    etag?: EntityTag;
    selectionType?: 'include' | 'exclude';
    selectors?: string[];
}

export type ResourceSourceTarget = {
    source: IResourceDesignator;
    target: IResourceDesignator;
};

export type ResourceCopy = IResourceDesignator | ResourceSourceTarget;

export type OneOrMoreAssetRef = AssetRef | AssetRef[];

/**
 * The physical or digital manifestation of the resource. Typically, Format should include the media-type of the resource.
 * Format may be used to determine the software, hardware or other equipment needed to display or operate the resource.
 * Recommended best practice is to select a value from a controlled vocabulary (for example, the list of
 * [Internet Media Types](http://www.iana.org/assignments/media-types/) defining computer media formats).
 */
export type Format = string;

export type Assignee = {
    // ID of the owner e.g. IMS user-id or IMS org-id
    id: string,

    // the name to show in the UI
    displayName?: string,

    // The type of owner e.g. org or user
    type: 'user' | 'org'
}

export type Representations = {
    // file representation availability
    file?: boolean,
    // composite representation availability
    composite?: boolean,
    // directory representation availability
    directory?: boolean
}

// NOTE: R-API uses 'file', 'composite', 'directory'
//       USS uses 'element' to identify Library Elements
//       'entity' is not implemented yet
export type AssetClass = 'file' | 'composite' | 'directory' | 'entity' | 'element';
export type AssetState = 'ACTIVE' | 'DISCARDED' | 'DISCARDED_PARENT';
export type DirectoryType = 'system' | 'assigned' | 'content' | 'syncgroup';
export type ShellVisibility = 'hiddenSelf' | 'hiddenRecursive' | '';

// We get discard, restore, and rename privileges from the projects service
export type PermissionType = 'ack' | 'read' | 'write' | 'delete' | 'discard' | 'restore' | 'rename';

export const AssetClassChoices: AssetClass[] = [ 'file', 'composite', 'directory', 'entity', 'element' ];
export const AssetStateChoices: AssetState[] = [ 'ACTIVE', 'DISCARDED', 'DISCARDED_PARENT' ];
export const DirectoryTypeChoices: DirectoryType[] = [ 'system', 'assigned', 'content', 'syncgroup' ];
export const ShellVisibilityChoices: ShellVisibility[] = [ 'hiddenSelf', 'hiddenRecursive', '' ];

