export type ActionLinks = {
    [RelType.CREATE]: IServiceLink,
    [RelType.RESTORE]: IServiceLink,
    [RelType.DISCARD]: IServiceLink,
    [RelType.DOWNLOAD]: IServiceLink,
    // Move is only supported for CSC Projects as of this writing.
    [RelType.PROJECTS_MOVE]?: IServiceLink,
}

interface IRootChildLinks {
    [RelType.PRIMARY]: IServiceLink,
    [RelType.PAGE]?: IServiceLink,
}

export type AssetLinks = AclLinks & NavigationLinks & AssociatedLinks & ActionLinks;

// Used for client-provided set of links, where all but REPO_METADATA are optional.
export type MinimalAssetLinks =  RequiredProps<Partial<AssetLinks>, RelType.REPO_METADATA>;

export interface IEffectivePermissions {
    '*'?: PermissionType[];
    [RelType.PRIMARY]?: PermissionType[];
    [RelType.AC_POLICY]?: PermissionType[];
    [RelType.DIRECTORY]?: PermissionType[];
    [RelType.APP_METADATA]?: PermissionType[];
    [RelType.ANNOTATIONS]?: PermissionType[];
}

