/**
 * Metadata of an ancestor, containing its type and subtype.
 */
export type AncestorInfoEntry = {
    'repo:assetType'?: string;
    'repo:assetSubType'?: string;
}

/**
 * A map of ancestor asset IDs to their type metadata.
 *
 * The key is the parent/ancestor asset ID (URN).
 * The value contains the assetType and assetSubType of that ancestor.
 *
 * Example:
 * {
 *   "urn:aaid:sc:US:parent-id-123": {
 *     "repo:assetType": "project",
 *     "repo:assetSubType": "ccProject"
 *   }
 * }
 */
type AncestorID = string;
export type AncestorInfo = Record<AncestorID, AncestorInfoEntry>;

/** Known capability states for a representation. Currently populated from GQL only; RAPI support not in scope for this change. Single source of truth for the set. */
const REPO_CAPABILITY_STATES = [ 'empty', 'available', 'failed', 'processing' ] as const;

export type RepoCapabilityState = (typeof REPO_CAPABILITY_STATES)[number];

export function isRepoCapabilityState(value: string | null | undefined): value is RepoCapabilityState {
    return value !== null && value !== undefined && (REPO_CAPABILITY_STATES as readonly string[]).includes(value);
}

/** Per-representation capability. Currently populated from GQL only; RAPI support not in scope for this change. state is one of the known values; error when failed. */
export type RepoCapabilityEntry = { name?: string; type?: string; state?: RepoCapabilityState; error?: string };

/** Capabilities for the asset. Currently populated from GQL only; RAPI support not in scope for this change. */
export type RepoCapabilitiesMetadata = {
    file?: RepoCapabilityEntry;
    composite?: RepoCapabilityEntry;
    directory?: RepoCapabilityEntry;
};

export type RepositoryMetadata = {
    'dc:format': Format,
    'repo:name': string,
    'repo:path': string,

    // The server date and time the asset was created. This time may precede the date
    // of the first version if it was created without a Primary Resource.
    // The Date Time property conforms to the RFC 3339 standard.
    'repo:createDate': string,

    // The server date and time the Primary Resource of this Asset was last modified.
    // The behavior may differ by Asset Class, as described in the specification.
    // The Date Time property conforms to the RFC 3339 standard.
    'repo:modifyDate': string,

    // The Repository ID of the Repository storing this Asset.
    'repo:repositoryId': string,

    // A globally unique identifier for this Asset.
    'repo:assetId': string,

    // The class of this Asset (folder, composite, etc).
    'repo:assetClass': AssetClass,

    'repo:assetType': AssetType | undefined;
    'repo:assetSubType': AssetSubType | undefined;

    // @deprecated -- use repo:assetId
    // 'repo:id': string,

    // Size of the Primary Resource in bytes. Not applicable for directories
    'repo:size': number,

    // The HTTP entity tag of the Asset's Primary Resource.
    'repo:etag': EntityTag,

    // Identifier of the head version of the Asset. Applicable only to assets that support versioning and have a primary resource.
    'repo:version': string,

    // IMS User Id of the user who created this Asset.
    'repo:createdBy': string,

    // 'IMS User Id of the user who caused the last Asset modification, as defined in repo:modifyDate'
    'repo:modifiedBy': string,

    // 'Indicates whether an Asset is active, or if it has been directly or indirectly discarded.'
    'repo:state': AssetState,

    // The time the Asset was discarded, either directly or by inheritance. The Date Time property conforms to the RFC 3339 standard.
    'repo:discardDate': string,

    // IMS User Id of the user who discarded the Asset directly or by inheritance.
    'repo:discardedBy': string,

    // The date and time an Asset is scheduled for deletion, either directly or by inheritance.
    'repo:scheduledDeletionDate': string,

    // A policy set on Directories, to decide after how many hours the direct children shall be scheduled for deletion.
    'repo:defaultScheduledDeletionDuration': string,

    // IMS Client ID of the client that created this Asset.
    'repo:createdByClientId': string,

    // IMS Client ID of the client that last modified the Primary Resource of this Asset.
    'repo:modifiedByClientId': string,

    // IP address(es) received in x-forwarded-for header with request that created this Asset.
    'repo:createdByIpAddress': string[],

    // IP address(es) received in x-forwarded-for header with request that last modified the Asset.
    'repo:modifiedByIpAddress': string[],

    // assetId of asset's ancestors, root starts from index 0
    'repo:ancestors': string[],

    // Type metadata for select ancestors (e.g., project type and subtype).
    // Partial and unordered -- use repo:ancestors for the canonical chain.
    'repo:ancestorInfo'?: AncestorInfo,

    // Available asset class representations
    'repo:representations': Representations,

    // An opaque, unique identifier of the device associated with the most recent update to this Asset,
    // if any. This property is removed when a request creates a new version of the Asset and does not
    // specify a new value for this property.
    'storage:deviceId': string,

    // A timestamp capturing the time at which this Asset was created on the client, and which may
    // therefore precede the time at which it was created in the Repository. (It can also be later,
    // due to clock skew.).
    // Can be set only at the time of Asset creation and, if not set, defaults to repo:createDate.
    'storage:deviceCreateDate': string,

    // A timestamp capturing the time at which this Asset was last modified on the client,
    // and which may therefore precede the time at which the corresponding modification was
    // uploaded to the Repository. (It can also be later, due to clock skew.).
    // If not specified with any request that creates a new version of the Asset, it will
    // be updated to repo:modifyDate.
    'storage:deviceModifyDate': string,

    'storage:assignee': Assignee,

    'storage:directoryType': DirectoryType,

    'storage:region': string,

    // For image and video Assets, width in pixels. Otherwise, not present.
    'tiff:imageWidth': number,

    // For image and video Assets, height in pixels, Otherwise, not present.
    'tiff:imageLength': number,

    // For document Assets, number of pages or artboards. Otherwise, not present.
    'xmpTPg:NPages': number,

    // The pinned version of the asset, if any.
    'repo:pinnedVersion'?: string,

    // The date and time the pinned version was created, and is converted to a date object for AdobeAsset._pinnedVersionModifyDate.
    'repo:pinnedVersionModifyDate'?: string,

    _links: AssetLinks,

    // If requested, listings can contain application metadata
    _embedded?: RepoResponseEmbeddedData
};

