export type IOperationError = {
    status: number | string;
    title: string;
    type: string;
}

export type IOperationResultProps = {
    error?: IOperationError;
    asset?: RepositoryMetadata;
}
export type IOperationResult = IOperation & IOperationResultProps;

// In some cases the operation API returns a single error entry.
export type IOperationSingleError = {
    code: string;
    message: string;
}

export type IOperationResults =  IOperationSingleError | IOperationResult | IOperationResult[];

// The repository interface updates the return values to use SAM errors instead.
export type ISAMOperationResultProps = {
    error?: SAMError;
    asset?: RepositoryMetadata;
}

export type ISAMOperationResult = IOperation & ISAMOperationResultProps;
export type ISAMOperationResults = ISAMOperationResult[];

// The return obj interface when one operation fails for any context
export interface IFailedOperation<LocalType> {
    model: LocalType;
    error: SAMError;
}

// result for batch operations
// failedResults contains failed list of items
// newModels contains list of new assets which are added,
// newModels will be populated with items for ops like copy/duplicate and will be empty in case of ops like move
export interface IBatchOperationResult<LocalType> {
    failedResults: IFailedOperation<LocalType>[];
    newModels: LocalType[];
}

