// Currently, the Owner and Assignee have the same shape, but that could change.
// Also, they're logically distinct entities.
export type Owner = Assignee;

export enum MoveWarning {
    None,
    CollaboratorMaybeEditing,
    OwnerChange,                // Owner of source and target are different
    CCItoCCI,                   // Owners of source and target are both CCI users (CCI-to-CCI move)
    TransferOfOwnership         // At least one of the owners of source or target is an Org (Org-to-Org, CCI-to-Org, or Org-to-CCI move)
}

export enum CannotMoveReason {
    DifferentOwner = 1,
    PermissionDeniedDestination = 2,
    PermissionDeniedSource = 3,
    NotAFolder = 4,
    CrossBucketMoveDisabled = 5,
    UserNotInSourceOrg = 6,
    TransferOfOwnershipDisabled = 7,
}

export enum NameConflictPolicy {
    RENAME = 'rename',
    CANCEL = 'cancel'
}

export type MoveCapability =
    {
        canMove: true;
        /** @deprecated use {@link warnings} instead */
        warning: MoveWarning;
        warnings: MoveWarning[];
    } |
    { canMove: false; reason: CannotMoveReason; };

// Note: this just describes the schema we've encountered in SAM.js,
// and does not include all possible options.
// https://git.corp.adobe.com/pages/caf/api-spec/schemas/accesscontrol/accesscontrolpolicy.html
export interface IACPolicyResponse {
    'repo:acl': {
        'repo:discoverable'?: boolean;
        'repo:principal': 'all' | 'authenticated' | 'unauthenticated' |
            // XDM principals, such as IMS users
            {
                'xdm:provider': { '@id': string };
                '@id': string;
                '@type': string;
            };
        'repo:modifier': 'grant' | 'deny';
        'repo:privileges': ('read' | 'write' | 'delete')[];
        'repo:relations': (
            RelType.AC_POLICY |
            RelType.ANNOTATIONS |
            RelType.APP_METADATA |
            RelType.EMBEDDED_METADATA |
            RelType.REPO_METADATA |
            RelType.PRIMARY |
            RelType.RENDITION
        )[];
        'repo:inheritance': 'self' | 'deep' | 'deep_override';
    }[];
}
