    constructor(
        readonly _core: ISAMCorePrivate,
        /**
         * @package -- only for use in SAM.js
         */
        readonly _assetPool: ItemPool<AdobeAsset>
    ) {
        super(_core);

        // We want to know all the asset ids that we care about, so we can register for change
        // notifications with ONS. This consists of all loaded assets in the asset pool.
        this._assetPool.on(ITEMS_CHANGED, this._onAssetsChanged);

        // When a new list is added to the pool, update ONS subscriptions.
        this._assetPool.on(LIST_ADDED, this._onListAdded);

        LazyLoadManager.manageLazyLoading(this, [ {
            event: OrganizationsChangedEventInstance,
            fetchData: this._fetchOrganizations,
            // [SHARED-3811] there's no reason to allow cancelling lazy-loading of orgs
            prefetchTimeout: 0
        } ]);

        // Handle dynamic configuration change.
        this._core.on(CONFIG_CHANGE, (event: ConfigChangeEvent, sender: ISAMCorePrivate, payload: ConfigurationPayload) => {
            switch (payload.configurationKeyName) {
            case 'DISABLE_ONS':
                this.onsContext?.reinitialize();
                break;
            case 'ONS_OVER_AXON':
                if (this._core._environment.getValue('ENVIRONMENT') === Env.Stage) {
                    if (this.onsContext) { this.onsContext.useAxon = this._core._environment.getValue('ONS_OVER_AXON'); }
                } else {
                    console.warn('Runtime config update for ONS_OVER_AXON is only supported in the Stage environment.');
                }
                break;
            default:
                break;
            }
        });
    }

    /**
     * @package -- only for use in SAM.js
     * Updaters shouldn't be accessed directly.
     */
    readonly _adobeAssetUpdater = AdobeAssetUpdater;

    /** @package -- for use in SAM.js only */
    @synchronized
    async _getONSContext(): Promise<ONSContext> {
        if (this._OnsContext) { return this._OnsContext; }
        this._OnsContext = new ONSContext(this._core);

        // Dispatch the initial ONS monitoring status.
        this.dispatch(new ONSMonitoringStatusChangedEvent(this._OnsContext.onsMonitoringStatus));

        // Attach the ONS asset change event listener.
        this._OnsContext.on(CHANGE, this._onOnsAssetChangeEvent);

        // Long Poll related events.
        this._OnsContext.on(ONS_FIRST_LONG_POLL_STARTED, event => {
            this.dispatch(new ONSFirstLongPollStartedEvent(event.cachedSubscriptionsUsed));
        });
        this._OnsContext.on(ONS_FIRST_LONG_POLL_COMPLETED, event => {
            this.dispatch(new ONSFirstLongPollCompletedEvent(event.expired));
        });

        // ONS monitoring status changed event.
        this._OnsContext.on(ONS_MONITORING_STATUS_CHANGED, event => {
            this.dispatch(new ONSMonitoringStatusChangedEvent(event.status));
        });

        return this._OnsContext;
    }

