    // Once the performance is better when compared to the USS,
    // we will default to PLSSWYAdobeAssetLoader
    @memoize
    get sharedSource(): SWYAdobeAssetSource {
        const implicitFilter = new SWYAdobeAssetFilter();
        const localAssetsLoader = new LocalAssetLoader<SWYAdobeAssetConfig>(this._assetPool, this._core);
        const featureFlags = this._core._environment.getValue('FEATURE_FLAGS');
        const usePLSSharedWithYou = featureFlags?.['use-pls-swy'] ?? false;
        const swyloader = usePLSSharedWithYou
            ? new PLSSWYAdobeAssetLoader(this._core)
            : new SWYAdobeAssetLoader(this._assetPool, this._core, this._swyInterface);
        return new ItemSource<SWYAdobeAssetConfig>(this._assetPool, [ swyloader, localAssetsLoader ], implicitFilter);
    }

