    /**
     * Resolves the Asset at the given assetPath. If repositoryId is not passed, it will look up the repositoryId
     * for the current user, and assume that the path is relative to the user's home directory (`/` for USM users,
     * `/users/<userId>` for ESM users). If the repositoryId is passed, then the path is assumed to be absolute.
     *
     * @example <caption>Assuming 'xyz' is the current userId and 'abc' is the repositoryId</caption>
     *    getAssetWithRepoPath('/cloud-content');                  // returns /users/xyz/cloud-content
     *    getAssetWithRepoPath('/users/xyz/cloud-content', 'abc'); // "
     *    getAssetWithRepoPath('/users/xyz/cloud-content');        // NOT_FOUND error
     *
     * @param assetPath {string}
     * @param repositoryId {string} (optional)
     * @return AdobeAsset
     */
    @keepAlive
    @synchronized
    async getAssetWithRepoPath(assetPath: string, repositoryId?: string): Promise<AdobeAsset> {
        // cache and use the cloud-content folder
        if (assetPath === CLOUD_CONTENT_ROOT_FOLDER) {
            return this.getRootFolder();
        }
        return this._getAssetWithRepoPathImpl(assetPath, repositoryId);
    }

    /**
     * A small abstraction to get the repository metadata and resources for a given asset path and repository ID.
     * @package -- only for use in SAM.js
     *
     * @param assetPath The path to get the repository metadata for.
     * @param repositoryId The repository ID to get the repository metadata for.
     * @returns The repository metadata for the given asset path and repository ID.
     */
    public async _getRepoDataByPath(assetPath: string, repositoryId: string): Promise<RepoMetadataResource> {
        const repoMetadataResource = new RepoMetadataResource(this._core);
        const data = await this._rapi.getRepoMetadataByPath(
            repositoryId!,
            assetPath,
            repoMetadataResource
        );
        repoMetadataResource._setData(data);
        return repoMetadataResource;
    }

    /**
     * Gets a top-level folder asset by its path and repository ID.
     * This is a lightweight method optimized for top-level folders that avoids the overhead
     * of _getAssetById by directly creating the asset from repository metadata.
     *
     * @private
     * @param assetPath - The path of the top-level folder
     * @param repositoryId - The repository ID containing the folder
     * @returns Promise resolving to the AdobeAsset for the top-level folder
     * @throws {SAMError} If the asset ID is missing from metadata
     */
    private async _getTopLevelFolder(assetPath: string, repositoryId: string): Promise<AdobeAsset> {
        const repoMetadataResource = await this._getRepoDataByPath(assetPath, repositoryId);
        const assetId = repoMetadataResource.data['repo:assetId'];

        if (!assetId) {
            throw SAMError.create(SAMErrorCode.NOT_FOUND, `Top-level folder not found at path: ${assetPath}`);
        }

        const updaters = await this._core._adobeAssetFactory.getRepoMetadataUpdaters([ repoMetadataResource.data ]);

        return this._assetPool.getLocalItemById(assetId) ?? (() => {
            const session = this._assetPool.createMutationSession(repoMetadataResource.timestamp);
            const newAsset = this._core._adobeAssetFactory.assetFromRepoMetadata({ session, repoMetadata: repoMetadataResource.data, updaters });
            session.commit();
            return newAsset;
        })();
    }

    /**
     * @package -- only for use in SAM.js
     */
    @synchronized
    private async _getAssetWithRepoPathImpl(assetPath: string, repositoryId?: string): Promise<AdobeAsset> {
        if (!repositoryId) {
            // Since clients typically start by resolving a folder by path, also get the `/` folder so that it is
            // monitored for ONS changes.
            const homeFolder = await this.getHomeFolder();
            repositoryId = homeFolder.repositoryID;
            const userContentRootFolder = homeFolder.repoPath;
            assetPath = path.join(userContentRootFolder, assetPath);
        }
        try {
            let asset: AdobeAsset | undefined = undefined;

            // If the asset is a top-level folder call _getTopLevelFolder which just creates it with repository metadata
            if (isTopLevelFolder(assetPath)) {
                asset = await this._getTopLevelFolder(assetPath, repositoryId);
                return asset;
            }
            const repoMetadataResource = await this._getRepoDataByPath(assetPath, repositoryId);
            const data = repoMetadataResource.data;
            asset = await this._getAssetById(data['repo:assetId'], repoMetadataResource);
            asset._setResources({ repoMetadataResource });
            return asset;
        } catch (e) {
            const topLevelFolders = [ 'cloud-content', 'temp' ];
            for (const topLevelFolder of topLevelFolders) {
                const topLevelPath = `/${topLevelFolder}`;
                const appearsOnlyOnce = assetPath.indexOf(topLevelPath) === assetPath.lastIndexOf(topLevelPath);
                if ((e as SAMError).code === SAMErrorCode.NOT_FOUND && appearsOnlyOnce && assetPath.endsWith(topLevelPath)) {
                    const homeFolder = await this.getHomeFolder();
                    // return the promise to create the folder
                    return homeFolder.createFolder(topLevelFolder);
                }
            }
            throw e;
        }
    }

    // including confirmAccess to match Seal bindings.
    @keepAlive
    async getAssetWithAssetRefString(assetRefStr: string, confirmAccess = false): Promise<AdobeAsset> {
        type AssetRefKeys = 'cloud_id' | 'local_id' | 'path' | 'repository_id';
        let parsedAssetRef: Partial<{ [key in AssetRefKeys]: string }>;

        try {
            parsedAssetRef = JSON.parse(assetRefStr);
        } catch (error: any) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Incorrectly formatted AssetRefString', { underlyingError: error });
        }

        if (parsedAssetRef.cloud_id) {
            return this.getAssetWithCloudID(parsedAssetRef.cloud_id, confirmAccess);
        } else if (parsedAssetRef.path) {
            return this.getAssetWithRepoPath(parsedAssetRef.path, parsedAssetRef.repository_id);
        } else {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Invalid AssetRefString');
        }
    }

