    async permanentlyDeleteAssets(assets: AdobeAsset[]): Promise<IBatchOperationAssetResult> {
        let assetResults: IBatchOperationAssetResult;

        // If client will try to resolve permanently deleted assets, SAM should not return the cached assets
        // from asset pool. Hence removing permanently deleted assets from asset pool.
        const onItemsChanged = async (event: ItemsChangedEvent<AdobeAsset>) => {
            // Remove only successfully permanently deleted items from asset pool.
            if (event.discardedItems) {
                const permanentDeletedAssetsIds: ItemId[] = event.discardedItems.filter(value => assets.includes(value)).map(item => item.id);
                if (permanentDeletedAssetsIds.length) {
                    this.removeAssetsFromAssetsPool(permanentDeletedAssetsIds);
                    await this.notifyGraphQLCacheAboutDeletedAssets(permanentDeletedAssetsIds);
                }
            }
        };

        // ITEMS_CHANGED event is triggered from item pool for all update/mutate sessions.
        // This event will be triggered by other sessions (sessions other than the session
        // created by this permanent delete operation) also. But in onItemsChanged we will
        // remove assets which were added in this session.
        this._assetPool.on(ITEMS_CHANGED, onItemsChanged);

        try {
            await ItemBase.runExclusiveTask('delete', assets, async () => {
                const assetsById = new Map<string, AdobeAsset>();

                const ops = assets.map((asset) => {
                    assetsById.set(asset.id, asset);

                    const deleteOp: IDeleteOperation = {
                        op: 'delete',
                        id: asset.id,
                        target: {
                            'repo:assetId': asset.id,
                        }
                    };

                    // repository id is optional field in target here
                    // because target is specified by assetId
                    if (asset.repositoryID) {
                        const target = deleteOp.target as IAssetRefRepoAssetId;
                        target['repo:repositoryId'] = asset.repositoryID;
                    }

                    deleteOp.recursive = asset.isFolder;
                    return deleteOp;
                });

                assetResults = await this._runOperations(ops,
                    assetsById,
                    (session: IUpdateSession<AdobeAsset>, asset: AdobeAsset) => {
                        // Since we know the asset has been permanently deleted
                        // we should clear any renditions on it to prevent memory leaks.
                        asset._releaseRenditions();

                        // If the Asset was removed from the pool while the operation was underway (such as by ONS-
                        // triggered refresh), do not try to update it again, as it will get re-added to the pool.
                        if (!this._assetPool.getLocalItemById(asset.id)) {
                            return undefined;
                        }

                        // We update the effectivePermission here first to notify on "change" subscribers
                        // of AdobeAsset (such as AssetLink) that may need to know this assets permission is set to None before
                        // it gets discarded.
                        this._adobeAssetUpdater.updateLocalItem(session, asset, { effectivePermission: Permission.None });
                        session.queueDiscardedItem(asset);
                        return undefined;
                    });

            });
        } finally {
            this._assetPool.off(ITEMS_CHANGED, onItemsChanged);
        }

        return assetResults!;
    }

