import type { Action } from '../models/Action';
// @ts-expect-error R-TODO
import type { default as Library } from '../models/Library';
import type { ElementData } from '../models/data/ElementData';
import type Driver from './Driver';
import { extractElementId } from '../utils/PathUtils';
import type { ExecuteResult } from './Operation';
import Operation, { validatesOperation } from './Operation';

/**
 * A transfer operation is an operation to move or copy elements or groups.
 * Due to the cross-library nature of these operations, these operations may
 * need to act on two different libraries multiple times.
 */
export default abstract class MoveCopyElementOperation<T extends Driver> extends Operation<T> {
    supportsAction(action: Action) {
        return [ 'moveElement', 'copyElement', 'dependent' ].includes(action.name as string);
    }

    addAction(action: Action) {
        // move/copy are batchable if:
        //  - the action is a supported action
        //  - the source and destination libraries are the same
        //  - the action is the same (move or copy)
        //  - the linked action is in the same queue position as the action
        //  - if the source and target libraries are the same:
        //    * the linked action is in the n+1 position

        if (!this.supportsAction(action)) {
            return false;
        }

        const lastAction = this._actions[this._actions.length - 1];

        if (!lastAction && action.name !== 'dependent') {
            return super.addAction(action);
        }

        if (action.library === action.link?.library) {
            if (action.name === 'dependent') {
                if (lastAction.link === action) {
                    this._actions.push(action);
                    return true;
                }
                return false;
            }
            // @ts-expect-error R-TODO
            const actionIndex = action.library?.actions.indexOf(action) as number;
            // @ts-expect-error R-TODO
            const linkedActionIndex = action.link?.library?.actions.indexOf(action.link as Action);

            if (actionIndex + 1 !== linkedActionIndex) {
                return false;
            }

            return super.addAction(action);
        }

        if (lastAction.link?.library !== action.link?.library || lastAction.type !== action.type) {
            return false;
        }

        return super.addAction(action);
    }

    @validatesOperation
    async execute(): Promise<ExecuteResult> {
        const isMove = this._actions[0].name === 'moveElement';

        const targetLibrary = this._actions[0].link?.library as Library;
        const actualActions = this._actions.filter(action => action.name !== 'dependent');
        const elementIds = actualActions.map(action => extractElementId(action.path as string) as string);

        const { elements, etag, sourceEtag } = await this._doMoveCopyRequest(
            isMove,
            this._library,
            targetLibrary,
            elementIds
        );

        // The elements in the response should be 1:1 with the elements in the actions. If not, something has gone wrong.
        if (elements.length !== actualActions.length) {
            // TODO: Better error
            throw new Error();
        }

        let linkedActions: Action[];
        let actions: Action[];

        if (targetLibrary === this._library) {
            linkedActions = [];
            actions = this._actions.map(action => {
                if (action.name !== 'dependent') {
                    return action;
                }

                const index = actualActions.findIndex(
                    a => a === (action.link as Action) || a.originalAction === (action.link as Action)
                );

                return {
                    ...action,
                    data: elements[index],
                    originalAction: action
                };
            });
        } else {
            actions = this._actions;
            linkedActions = this._actions.map(
                (action, index) =>
                    ({
                        ...action.link,
                        data: elements[index],
                        originalAction: action.link
                    } as Action)
            );
        }

        return {
            actions,
            etag: sourceEtag as string,
            linkedActions,
            linkedEtag: etag as string
        };
    }

    protected abstract _doMoveCopyRequest(
        isMove: boolean,
        sourceLibrary: Library,
        targetLibrary: Library,
        elementIds: string[]
    ): Promise<{ elements: ElementData[]; etag: string | null; sourceEtag: string | null }>;
}
