if (typeof queueMicrotask === 'undefined') {
    window.queueMicrotask = cb => {
        Promise.resolve()
            .then(cb)
            .catch(err =>
                setTimeout(() => {
                    throw err;
                }, 0)
            );
    };
}

export {};
