import type { ISAMCorePrivate } from '../indexPrivate';
import type { ISAMObject } from '../core/ISAMObject';
import { key, synchronized } from '../core/decorators';
import { keepAlive } from '../core/decorators/KeepAliveManager';
import type { MinimalAssetLinks } from '../interface/RepositoryModel';
import type AdobeAsset from '../assets/AdobeAsset';
import RepoMetadataResource from '../assets/RepoMetadataResource';
import { LazyLoadManager } from '../core/decorators/LazyLoadManager';
import { STORAGE_ASSIGNEE_CHANGED } from '../assets/AssetEvents';

export type MinimalAssetLoadOptions = {
    isCuratedCollectionAsset?: boolean
}

export const DefaultMinimalAssetLoadOptions = {
    isCuratedCollectionAsset: false
};

type MinimalAssetProperties = {
    isCuratedCollectionAsset: boolean
}

export default class KnowledgeWorkspaceContext implements ISAMObject {
    constructor(
        readonly _core: ISAMCorePrivate
    ) {}

    // Tracks assets that have been requested via the KnowledgeWorkspaceContext. This may
    // affect how SAM.js internally handles these assets re: ONS monitoring or other optimizations.
    private _minimalAssets: WeakMap<AdobeAsset, MinimalAssetProperties> = new WeakMap<AdobeAsset, MinimalAssetProperties>;

    /**
     * @package -- only for use in SAM.js
     */
    _isCuratedCollectionAsset(asset: AdobeAsset): boolean {
        const assetProps = this._minimalAssets.get(asset);
        return assetProps ? assetProps.isCuratedCollectionAsset : false;
    }

    /**
     * @package -- only for use in SAM.js
     */
    _isMinimalAsset(asset: AdobeAsset): boolean {
        return this._minimalAssets.has(asset);
    }

    /**
     * Gets the Asset with the given assetId, loading the minimal amount of data needed to create an AdobeAsset instance.
     *
     * @remarks
     *
     * A minimal `AdobeAsset` instance is only populated with the repo:metadata of the asset.
     * No application metadata, effective permissions, or other properties are requested.
     *
     * If asset exists in the local cache, that existing instance will be returned.
     *
     * If asset does not exist in the local cache, a new minimal `AdobeAsset` instance will be created using the
     * `RelType.REPO_METADATA` link to fetch the repo:metadata for the asset.
     *
     * The provided `assetLinks` are only used for the initial fetching of the repo:metadata. The links in the
     * repo:metadata response will be used for future requests.
     *
     * Some AdobeAsset subtypes, such as Projects, Classrooms, etc., currently require application metadata to
     * determine the correct subtype instance to create. Only use this method if you know that the requested
     * asset is not one of these types. In the future, repo:metadata will contain the asset subtype, and
     * we can remove this restriction.
     *
     * @param assetId {string} assetId of the desired asset.
     * @param assetLinks {AssetLinks} set of asset links. `RelType.REPO_METADATA` link must be present to retrieve a minimal asset.
     * @param loadOptions {MinimalAssetLoadOptions} options for loading the asset. These will not apply if asset is already present in ItemPool.
     * @return AdobeAsset
     */
    @keepAlive
    @synchronized
    async getMinimalAssetWithAssetId(@key assetId: string, assetLinks: MinimalAssetLinks, loadOptions?: Partial<MinimalAssetLoadOptions>): Promise<AdobeAsset> {
        return this._getMinimalAssetById(assetId, assetLinks, loadOptions);
    }

    @synchronized
    private async _getMinimalAssetById(@key assetId: string, assetLinks: MinimalAssetLinks, loadOptions?: Partial<MinimalAssetLoadOptions>, repoMetadataResource?: RepoMetadataResource,): Promise<AdobeAsset> {
        const assetContext = await this._core.getAssetContext();
        const repositoryInterface = assetContext._rapi;
        const asset = assetContext._assetPool.getLocalItemById(assetId);
        if (asset) {
            // If no repo:metadata resource provided and ONS is disabled, force refresh repo:metadata, because the data may be stale
            const forceRefresh = this._core._environment.getValue('DISABLE_ONS');
            if (!repoMetadataResource && forceRefresh) {
                repoMetadataResource = new RepoMetadataResource(this._core);
                await repositoryInterface.getRepoMetadataById(assetId, repoMetadataResource, assetLinks);
            }

            if (repoMetadataResource) {
                const session = assetContext._assetPool.createMutationSession(repoMetadataResource.timestamp);
                assetContext._adobeAssetUpdater.updateRemoteItem(session, repoMetadataResource.data);
                session.commit();
            }

            return asset;
        }

        if (!repoMetadataResource) {
            repoMetadataResource = new RepoMetadataResource(this._core);
            await repositoryInterface.getRepoMetadataById(assetId, repoMetadataResource, assetLinks);
        }

        // Preserve any asset links provided by client when constructing the asset's repo:metadata.
        const repoMetadata = repoMetadataResource.data;
        repoMetadata._links = { ...repoMetadata._links, ...assetLinks };

        const session = assetContext._assetPool.createMutationSession(repoMetadataResource.timestamp);
        const updaters = await this._core._adobeAssetFactory.getRepoMetadataUpdaters([ repoMetadata ]);
        const newAsset = this._core._adobeAssetFactory.assetFromRepoMetadata({
            session,
            repoMetadata,
            updaters
        });

        const loadConfig = { ...DefaultMinimalAssetLoadOptions, ...loadOptions };
        this._minimalAssets.set(newAsset, { isCuratedCollectionAsset: loadConfig.isCuratedCollectionAsset });

        // Mark storage:assignee as loaded, if it is set from repo:metadata
        if (repoMetadata && repoMetadata['storage:assignee'] && newAsset._storageAssignee_NoLazyLoad.id === repoMetadata['storage:assignee'].id) {
            LazyLoadManager.updatedByItemUpdater(newAsset, STORAGE_ASSIGNEE_CHANGED);
        }

        session.commit();

        newAsset._setResources({
            repoMetadataResource,
            effectivePermissionsResource: undefined,
            appMetadataResource: undefined,
            perUserMetadataResource: undefined
        });

        return newAsset;
    }

    /**
     * Gets an Asset with the given assetPath and repositoryId, loading the minimal amount of data needed to create an AdobeAsset instance.
     *
     * @remarks
     *
     * A minimal `AdobeAsset` instance is only populated with the repo:metadata of the asset.
     * No application metadata, effective permissions, or other properties are requested.
     *
     * The provided path should be the full path to the asset. It cannot be a relative path, such as
     * a path relative to the user's /cloud-content folder.
     *
     * If the asset exists in the local cache, that existing instance will be returned. If the asset does not exist
     * in the local cache, a new minimal `AdobeAsset` instance will be created using the `RelType.REPO_METADATA`
     * link to fetch the repo:metadata for the asset.
     *
     * For performance reasons, if you have the assetId of the asset, you should use `getMinimalAssetWithAssetId()` instead. Because
     * our item pool maps assets by assetId, if you request an asset by path, we will need to fetch the repo:metadata to get
     * the assetId of the asset to see if it is in the local cache.
     *
     * The provided `assetLinks` are only used for the initial fetching of the repo:metadata. The links in the
     * repo:metadata response will be used for future requests.
     *
     * Some AdobeAsset subtypes, such as Projects, Classrooms, etc., currently require application metadata to
     * determine the correct subtype instance to create. Only use this method if you know that the requested
     * asset is not one of these types. In the future, repo:metadata will contain the asset subtype, and
     * we can remove this restriction.
     *
     * @param assetPath {string} full path for the asset
     * @param repositoryId {string} repositoryID of the asset
     * @param assetLinks {AssetLinks} set of asset links. `RelType.REPO_METADATA` link must be present to retrieve a minimal asset.
     * @param loadOptions {MinimalAssetLoadOptions} options for loading the asset. These will not apply if asset is already present in ItemPool.
     * @return AdobeAsset
     */
    @keepAlive
    @synchronized
    async getMinimalAssetWithRepoPath(assetPath: string, repositoryId: string, assetLinks: MinimalAssetLinks, loadOptions?: Partial<MinimalAssetLoadOptions>): Promise<AdobeAsset> {
        return this._getMinimalAssetWithRepoPathImpl(assetPath, repositoryId, assetLinks, loadOptions);
    }

    /**
     * @package -- only for use in SAM.js
     */
    @synchronized
    private async _getMinimalAssetWithRepoPathImpl(assetPath: string, repositoryId: string, assetLinks: MinimalAssetLinks, loadOptions?: Partial<MinimalAssetLoadOptions>): Promise<AdobeAsset> {
        const assetContext = await this._core.getAssetContext();
        const repositoryInterface = assetContext._rapi;
        let asset: AdobeAsset | undefined = undefined;
        const repoMetadataResource = new RepoMetadataResource(this._core);
        const repositoryMetadata = await repositoryInterface.getRepoMetadataByPath(
            repositoryId!,
            assetPath,
            repoMetadataResource,
            assetLinks
        );
        asset = await this._getMinimalAssetById(repositoryMetadata['repo:assetId'], assetLinks, loadOptions, repoMetadataResource);
        return asset;
    }
}
