import SAMError, { SAMErrorCode } from '../core/SAMError';
import CacheableResponse from './CacheableResponse';


// https://www.w3.org/Protocols/rfc2616/rfc2616-sec2.html#sec2.1

// OCTET          = <any 8-bit sequence of data>
// CHAR           = <any US-ASCII character (octets 0 - 127)>
// CTL            = <any US-ASCII control character
//                  (octets 0 - 31) and DEL (127)>
// SP             = <US-ASCII SP, space (32)>
// HT             = <US-ASCII HT, horizontal-tab (9)>
// separators     = "(" | ")" | "<" | ">" | "@"
//                | "," | ";" | ":" | "\" | <">
//                | "/" | "[" | "]" | "?" | "="
//                | "{" | "}" | SP | HT
// token          = 1*<any CHAR except CTLs or separators>

// A header is just a <token>, the char ':' and the value.
function createHeaderRegexp() {
    const separators = '()<@,;:"/[]={}';

    // Start from the first character that is accepted by the <token>.
    let start = 33;
    const regexp = [ '^([' ];

    for (let i = 34; i <= 127; ++i) {
        // We know 127 is not accepted, so we use it as a terminator for our regexp segments.
        // None of the separators are allowed.
        if (i === 127 || separators.indexOf(String.fromCharCode(i)) !== -1) {
            regexp.push('\\' + start.toString(8));
            if (start < i - 1) {
                regexp.push('-\\' + (i - 1).toString(8));
            }
            start = i + 1;
        }
    }
    regexp.push(']+):(.*)$');
    return new RegExp(regexp.join(''));
}

const END_OF_LINE = '\n';
const CR = '\r';
const headerRegexp = createHeaderRegexp();
const statusRegexp = /^[^\s]+\s+(\d+)\s*(.*)$/;

class HttpResponseParser {

    private _index: number = 0;

    constructor(private _text: string) {
    }

    readLine(): string | undefined {
        const { _index, _text } = this;

        // The standard expects lines to end with CRLF by default.
        // However, it recommends to accept a single LF as well,
        // just in case some implementations do not implement the
        // standard correctly.
        // Async responses only use LF.
        const endOfLine = _text.indexOf(END_OF_LINE, _index);
        if (endOfLine === -1) {
            // We're done.
            return;
        }
        this._index = endOfLine + END_OF_LINE.length;

        let line = _text.slice(_index, endOfLine);
        if (line.endsWith(CR)) {
            // If we have the CR just before the LF, then we want to skip it too.
            line = line.slice(0, -1);
        }
        return line;
    }

    get remainderText(): string {
        return this._text.slice(this._index);
    }

}

/**
 * Implements parsing of the async response body.
 * https://git.corp.adobe.com/pages/caf/api-spec/chapters/advanced/asynchronous_invocation.html
 *
 * The caller should check for status code 202 then call this method to extract the contents
 * of final async result. The actual result is very similar to a nested HTTP reply inside the body
 * of the initial request.
 *
 */
export function parseAsyncResponse(originalUrl: string, body: string): Response {
    if (!body) {
        throw SAMError.create(SAMErrorCode.INTERNAL_ERROR, 'Invalid async response body.');
    }

    const parser = new HttpResponseParser(body);

    let status: number;
    let statusText: string;

    const statusLine = parser.readLine();
    if (!statusLine) {
        // throw SAMError.create(SAMErrorCode.INTERNAL_ERROR, 'Could not find async response status line.');
        // TODO: R-API does not return the status line for operations api. Any errors are reported in data section.
        // When this is fixed, then missing status line should be an error.
        // https://developers.corp.adobe.com/supplemental-resources/docs/async-invocation.md/#operations-api-exception
        status = 200;
        statusText = '';
    } else {
        // The status line has 3 parts separated by spaces.
        // Example status line: HTTP/1.1 200 Status text
        const statusMatch = statusLine.match(statusRegexp);
        if (!statusMatch) {
            throw SAMError.create(SAMErrorCode.INTERNAL_ERROR, 'Invalid status line for async response.');
        }

        // The status code is the second element
        status = parseInt(statusMatch[1], 10);
        if (!status) {
            throw SAMError.create(SAMErrorCode.INTERNAL_ERROR, 'Could not find status code for async response.');
        }

        statusText = statusMatch[2];
    }

    // Now we extract the headers line by line.
    const headers: HeadersInit = [];
    let headerName: string | undefined;

    for (;;) {
        const headerLine = parser.readLine();
        if (!headerLine) {
            break;
        }

        const match = headerLine.match(headerRegexp);
        if (!match) {
            if (headerName) {
                // If this is not a token, then we just continue with the value.
                headers.push([ headerName, headerLine ]);
            }
            continue;
        }

        headerName = match[1];
        headers.push([ headerName, match[2] ]);
    }

    // 1. The last `readLine()` call above will actually jump over the empty
    // line that separates the headers from the data section.
    // 2. The Headers constructor below takes care of multiple headers with the
    // same name and concatenates them as necessary.
    return new CacheableResponse(originalUrl, new Headers(headers), status, statusText, Date.now(), parser.remainderText);
}
