import { gql } from '@apollo/client';

export const UPDATE_LAST_ACCESSED = gql`
    mutation updateLastAccessed($assetId: ID!, $input: UpdateLabelInput!) {
        updateLabel(assetId: $assetId, input: $input) {
            lastAccessDate
        }
    }
`;
