export default class Project extends AdobeAsset implements SAM.Project {
    public isProject: boolean = true;

    private _description: string = '';
    private _projectLinks?: IProjectLinks;

    // We have separate permissions for a Project and AdobeAsset.
    // AdobeAsset permissions for a project are the permissions on the folder (i.e. representing the project)
    // ESM users might not have permission on the parent folder for Projects, so the permissions cannot be derived
    // from the parent folder like normal folders.
    private _projectPermissions: Permission = PERMISSION_ALL;

    /**
     * This is the raw id that exists on the project app metadata
     * but we internally compute this value and join the language
     * code so we can store them in the ItemPool uniquely
     * so if you need the computed gradientID, use the public
     * Project.gradientID() and not the private _gradientID;
     */
    private _gradientID?: string;
    private _creator?: IProjectsCreatorData;
    private _gradient: Gradient | undefined;
    private _projectInterface = new ProjectsInterface(this._core);
    private _repositoryOwner: Owner = { id: '', type: 'user' };
    private _directorySubtype: ProjectDirectorySubtype = ProjectDirectorySubtype.CC_PROJECTS;
    protected _assetClass: AssetClass = 'directory';

    /**
     * [SHARED-3832] Some Projects are available to the whole org but should not show up in the current user's listings
     * unless it is a recent Project. However, detecting this case is tricky in getProjectbyID, so it should assume the
     * Project is not allowed on lists until it is proven that it should be allowed.
     *
     * @package -- for use in SAM.js only
     */
    public _allowInLists = false;
    /**
     * @package -- only for use in SAM.js
     * TODO: once we have support for lastAccessDate from projects service, we can set remove this.
     */
    public _isRecent = false;

    /**
     * List of inaccessible library references for this project.
     * These are library references that the user does not have access to.
     */
    private _inaccessibleLibraryReferences: string[] | undefined;

    constructor(
        readonly _core: ISAMCorePrivate,
        id: string,
        metadata?: {
            projectLinks?: IProjectLinks,
            links?: AssetLinks,
            etag?: string
        }
    ) {
        super(_core, id, metadata);
        this._projectLinks = metadata?.projectLinks;

        // Overridden property.
        // True to start with. If we have the metadata, we will update this.
        this._needsRepoMetadata = true;

        LazyLoadManager.manageLazyLoading(this, [ {
            event: SharedChangeEvent,
            fetchData: this._getGradient
        } ]);
    }


    @observable
    get gradientID(): string {
        return this._gradientID ?? '';
    }

    /**
     * Lazy loads and returns the Gradient belonging to this
     * Project.
     */
    @lazyLoaded(SharedChangeEvent, '_gradient')
    get gradient(): Gradient | undefined {
        return this._gradient;
    }

    private async _getGradient() {
        this._gradient = await this._core.projectContext.getGradient(this.gradientID);
    }

    /**
     * @TODO@PROJECT
     * @experimental API may change.
     */
    @observable
    get description(): string {
        oneTimeWarning('Description Not yet Supported', 'Currently the description field is not supported by the service.');
        return this._description;
    }

    /**
     * This property represents the "sub-type" of the project directory. There have been several
     * new types introduced to support CSC Projects.
     *
     * ACPC Project is the general term used to describe the "project" construct
     * in AUP, the CSC Project (Content Supply Chain) Project
     *
     * WFProject: Work Front Project
     * CCProject: Creative Cloud Project
     *
     */
    get directorySubtype(): ProjectDirectorySubtype {
        return this._directorySubtype;
    }

    /**
     * @experimental API May change.
     * Returns the number of library references in this project that the current user does not have access to.
     *
     * @warning This property is not guaranteed to be loaded. It is only populated when this project's library references are loaded via a LibrarySource.
     *
     * @returns {number|undefined} Count of inaccessible library reference IDs or undefined if not loaded
     */
    @observable
    get inaccessibleLibraryReferencesCount(): number | undefined {
        return this._inaccessibleLibraryReferences ? this._inaccessibleLibraryReferences.length : undefined;
    }

    /**
     * @param repoMetadata {RepositoryMetadata} If passed in, it will be used instead of loading from the service
     * @param appMetadata {any} If passed in, it will be used instead of loading from the service
     *
     * @package -- only for use in SAM.js
     */
    async _load({
        repoMetadata,
        appMetadata,
        effectivePermission,
        projectMetadata,
        perUserMetadata
    }: {
        repoMetadata?: RepositoryMetadata;
        appMetadata?: any;
        effectivePermission?: Permission;
        projectMetadata?: IProject;
        perUserMetadata?: IPerUserMetadata;
    } = {}): Promise<void> {
        // First load the AdobeAsset so that once we get the project metadata we override any relevant
        // properties with the project metadata. One example of such field is createdBy. Etag is another one.
        // We need to take care of permissions. We will get the permissions from the project service
        // and we should handle them here as they are extended from RAPI effective permissions.
        // https://jira.corp.adobe.com/browse/SAM-3086
        // Also we need update the load method so that it does not load the permissions for a project
        // We can probably govern that with the help of an argument to the load method.
        await super._load({ repoMetadata, appMetadata, effectivePermission, perUserMetadata });

        // If we have the project metadata, then we will use that to update the project
        if (!projectMetadata) {
            // load the project metadata using the project service
            projectMetadata = await this._projectInterface.getProject(this.id);
        }
        const session = this._core.projectContext._assetPool.createMutationSession<Project>();
        this._core.projectContext._projectUpdater.updateRemoteItem(session, projectMetadata!);
        session.commit();
    }

    // @TODO@PROJECT We should implement something similar to _ensureLink here.
    get projectLinks(): IProjectLinks | undefined {
        return this._projectLinks;
    }

    get creator(): IProjectsCreatorData | undefined {
        return this._creator;
    }

    /**
     * The view that this project belongs to.
     */
    @observable
    get view(): ProjectItemView {
        // repositoryOwner is not loaded yet
        if (!this._repositoryOwner.id) {
            return undefined;
        }
        const currentUserId = this._core._environment.getUserId();
        const { organizations } = this._core.hostAssetContext;
        const allOwners: string[] = [
            currentUserId,
            ...(organizations?.map(org => org.id) || [])
        ];
        if (allOwners.includes(this._repositoryOwner.id)) {
            return ProjectViews.Yours;
        }
        return ProjectViews.SWY;
    }

    /**
     * @package -- for use in SAM.js only
     */
    get _views(): SAM.ProjectViews[] {
        // repositoryOwner is not loaded yet
        if (!this._repositoryOwner.id) {
            return [];
        }
        const views: SAM.ProjectViews[] = [];
        const currentUserId = this._core._environment.getUserId();
        const { organizations } = this._core.hostAssetContext;
        const orgIds = organizations?.map(org => org.id) || [];
        // Check if project belongs to current user or any of the user's organizations
        if (this._repositoryOwner.id === currentUserId || orgIds.includes(this._repositoryOwner.id)) {
            views.push(ProjectViews.Yours);
        }
        if (this.sharedWithYouLabel) {
            views.push(ProjectViews.SWY);
        }
        return views;
    }

    async move(destFolder: AdobeAsset): Promise<void> {
        oneTimeWarning('[MOVE_UNSUPPORTED]', `Move on a project is not supported ${destFolder}`);
        return;
    }

    /**
     * A move method designed only for CSC Projects to encapsulate some of the buisiness logic
     * required to move a CSC Project to a new location.
     *
     * @service -- This method requires an allow listed Service Principal
     * @param targetProjectId - The ID of the target CSC Project where the source project will be moved to.
     * @param options - Optional parameters for the move operation.
     * @param options.renameOnConflict - If true, the project will be renamed by ACP if a conflict occurs.
     *
     */
    async moveCSCProject(targetProjectId: string, options?: MoveCSCProjectOptions): Promise<void> {
        const projectContext = await this._core.getProjectContext();
        await projectContext.moveCSCProject(this.id, targetProjectId, options);
    }

    /**
     * Renames the project with the new name
     * @param newName new name for the project.
     * @param renameOnConflict If true, the project will be renamed by ACP if a conflict occurs.
     * If false, the request will be cancelled if a conflict occurs (false by default).
     */

    async rename(newName: string, renameOnConflict: boolean = false): Promise<void> {
        if (!this._projectLinks?.[RelType.PROJECTS_RENAME]) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Rename link is missing for this project.');
        }
        if (!validatePlatformRepoName(newName)) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Invalid name provided for asset rename operation.');
        }
        const renamedProject = await this._projectInterface.renameProject(newName, this._projectLinks, renameOnConflict);
        const projectPool = this._core.projectContext._assetPool;
        const assetContext = await this._core.getAssetContext();
        // Update the repo:name and repo:path after a rename
        const session = projectPool.createUpdateSession<Project>();

        // Use server response only when renameOnConflict is true, otherwise use proposed name
        // This ensures consistency between parent and child assets
        const actualName = renameOnConflict ? renamedProject['repo:name'] : newName;
        const newPath = renameFileInPath(actualName, this);
        updateCachedDescendents({
            assetPool: this._core._getAssetPool(),
            asset: this,
            session,
            operation: { type: 'rename', newPath },
            assetContext
        });
        this._core.projectContext._projectUpdater.updateLocalItem(session, this, {
            'repo:name': actualName,
            'repo:path': newPath,
        });
        session.commit();
    }

    /**
     * Discards a project through the Projects service instead of RAPI.
     *
     */
    async discard(): Promise<void> {
        if (this.isDiscarded) {
            throw SAMError.create(SAMErrorCode.INVALID_OPERATION, 'Asset is already discarded');
        }

        await this._ensureLink(RelType.DISCARD);

        await this._projectInterface.discardProject(this.id, this._projectLinks as IProjectLinks);
        const projectPool = this._core._getAssetPool();
        const assetContext = await this._core.getAssetContext();
        const session = projectPool.createUpdateSession<Project>();

        updateCachedDescendents({
            assetPool: projectPool,
            asset: this,
            session,
            operation: { type: 'discard' },
            assetContext
        });
        this._core.projectContext._projectUpdater.updateLocalItem(session, this, { 'repo:state': 'DISCARDED' });
        session.commit();
    }

    /**
     * Restores a project through the Projects service instead of RAPI.
     *
     */
    async restore(): Promise<void> {
        if (!this.isDiscarded) {
            throw SAMError.create(SAMErrorCode.INVALID_OPERATION, 'Cannot restore an asset that is not discarded');
        }

        await this._ensureLink(RelType.RESTORE);
        const restoredProject = await this._projectInterface.restoreProject(this.id, this._projectLinks as IProjectLinks);
        const projectPool = this._core._getAssetPool();
        const assetContext = await this._core.getAssetContext();
        const session = projectPool.createUpdateSession<Project>();
        updateCachedDescendents({
            assetPool: projectPool,
            asset: this,
            session,
            operation: { type: 'restore' },
            assetContext
        });
        this._core.projectContext._projectUpdater.updateLocalItem(session, this, {
            'repo:name': restoredProject['repo:name'],
            'repo:path': restoredProject['repo:path'],
            'repo:state': 'ACTIVE'
        });
        session.commit();
    }

    /**
     * @package
     **/
    async _updateProjectLinksFromService() {
        // load the project links using the project service
        const returnProject = await this._projectInterface.getProject(this.id);
        const { _links } = returnProject;

        const projectPool = this._core.projectContext._assetPool;
        const session = projectPool.createUpdateSession<Project>();
        this._core.projectContext._projectUpdater.updateLocalItem(session, this, { _links });
        session.commit();
    }

    /**
     * @package
     **/
    _isProjectLinkType(relType: RelType): relType is keyof IProjectLinks {
        return _projectLinkKeys().includes(relType);
    }

    async _ensureLink(relType: keyof (AssetLinks & IProjectLinks)): Promise<void> {
        // if the link is in _projectLinks, copy the _projectLink into _links
        // relType is an AssetsLink index, it might be a link that isn't in IProjectLinks
        if (this._isProjectLinkType(relType)) {
            if (!this._projectLinks?.[relType as keyof IProjectLinks]) {
                await this._updateProjectLinksFromService();
            }
            const links: AssetLinks = { ...this.__links, [relType]: this._projectLinks![relType] } as AssetLinks;

            //using the AssetUpdater instead of ProjectUpdater because ProjectUpdater has no way to update _links
            const session = this._core.hostAssetContext._assetPool.createUpdateSession();
            this._core.hostAssetContext._adobeAssetUpdater.updateLocalItem(
                session,
                this,
                { '_links': links }
            );
            session.commit();
            return;
        }

        //call out to fetch the missing link
        this._core._environment.debug(`ProjectLinkMissing ${relType} Link ${relType} missing on project, called out fetch it`);
        await super._ensureLink(relType);
    }

    /**
     * Validates whether this project can be renamed to the provided name
     * SAM will take in the name from the client and substitute this in the repo:path
     * of the project to get an absolute path. Project service would need the absolute
     * path to disambiguate between projects for accounts that contain projects in both
     * shared storage (/content/assets) and user storage (/projects). Right now both these
     * belong to the same repository and once we have the unified storage model they will
     * have separate repository ids and we will be able to identify them using repository id.
     * @param name name of the project to be validated for rename.
     */
    async validateProjectNameForRename(name: string): Promise<boolean> {
        if (name.toLowerCase() === this.name.toLowerCase()) {
            return true;
        }

        return await this._core.projectContext.validateProjectNameForCreate(name, this);
    }

    /**
     * @experimental API May change.
     * @deprecated - to be removed in a future major version on or after 2024-10-01. SAM-3333
     */
    async updateProperties(/* properties: IProjectProperties */) {}

    /**
     * Returns an enumeration with a more precise reason for why the user
     * can or cannot leave the Project. It may also return PENDING if we are still
     * loading collaborator information.
     *
     * @returns {ProjectLeaveReason} An enumeration of reasons why the user can or cannot leave.
     */
    @lazyLoaded(SharedCollaboratorChangedEvent, '_collaboratorsArray')
    leaveStatus(): ProjectLeaveReason {
        // Note: queues collaborators if not fetched already
        const collaborators = this.collaboratorArray;

        if (!this._isCollaboratorDataLoaded) {
            return ProjectLeaveReason.PENDING;
        }

        // If there are no collaborators returned, they can't leave anyway
        if (collaborators.length === 0) {
            return ProjectLeaveReason.CANNOT_LEAVE_NO_COLLABORATORS;
        }

        const currentUserCollaborator = collaborators.find((c) => c.isCurrentUser);

        // If the user doesn't exist in the collaborators list
        // this user has inherited access to this project and thus they can't
        // leave and we should return the address book group member error response.
        if (!currentUserCollaborator) {
            return ProjectLeaveReason.CANNOT_LEAVE_ADDRESS_BOOK_GROUP_MEMBER;
        }

        if (currentUserCollaborator.role === 'owner') {
            return ProjectLeaveReason.CANNOT_LEAVE_IS_OWNER;
        }

        // Admins of the org have access to all Projects. But sometimes, they can be directly invited by other members
        // to the Project, which in this case, they are allowed to leave the Project as direct collaborator.
        // This only removes their entry in the `directCollaborators` list, but won't change the permission as admin
        // still have access to all content. Without direct invite permission, on leave, we show toast message such
        // that admin can't leave Project.
        if (!currentUserCollaborator.isDirect && currentUserCollaborator.isAdmin) {
            return ProjectLeaveReason.CANNOT_LEAVE_IS_ADMIN_OF_PROJECT;
        }

        // MAC (Modern Access Control) projects: Check if user is the last direct manager
        if (this.collaborationModel === 'project') {
            if (currentUserCollaborator.isDirect && currentUserCollaborator.rebacRole === 'manager') {
                const anotherDirectManager = collaborators.find((c) =>
                    c.rebacRole === 'manager'
                    && c.isDirect
                    && c !== currentUserCollaborator
                );

                if (!anotherDirectManager) {
                    return ProjectLeaveReason.CANNOT_LEAVE_LAST_MAC_MANAGER;
                }
            }
        }

        // At this point if they are the only collaborator then
        // they can't leave, this case happens when a CCI user creates
        // a Project and they are the only collaborator direct or not.
        if (collaborators.length === 1) {
            return ProjectLeaveReason.CANNOT_LEAVE_LAST_COLLABORATOR;
        }

        // User cannot leave if they are no more collaborators who can share.
        const anotherDirectCollabWithSharePermissions = collaborators.find((c) => c.canShare && c.isDirect && c !== currentUserCollaborator);
        // We also need to distinguish between whether it is a USM project or shared-storage project.
        // In shared-storage projects, the user can't leave if they are the last direct collaborator with share permissions.
        // In user storage projects, the user can leave as long as she is not the owner of the project.
        if (!anotherDirectCollabWithSharePermissions && this.storageAssignee.type !== 'user') {
            return ProjectLeaveReason.CANNOT_LEAVE_LAST_DIRECT_COLLAB_WITH_SHARE_PERMISSION;
        }

        // If the user is not a direct collaborator and is also
        // not and admin, they can't leave due to inheriting
        // access to this project and not getting directly invited.
        if (!currentUserCollaborator.isDirect) {
            return ProjectLeaveReason.CANNOT_LEAVE_ADDRESS_BOOK_GROUP_MEMBER;
        }

        return ProjectLeaveReason.CAN_LEAVE;
    }

    /**
     * Returns a boolean based on the userCanLeaveReason() response above.
     *
     * @deprecated -- Use {@link Project.leaveStatus instead} -- will be removed on or after 2024-10-01
     *
     * @returns Undefined while fetching collaborator data.
     */
    userCanLeaveProject(): boolean | undefined {
        oneTimeWarning('userCanLeaveProject Deprecated', 'Use Project.leaveStatus instead.'
            + ' This will be removed on or after 2024-10-01.');
        const reason: ProjectLeaveReason = this.leaveStatus();
        switch (reason) {
        case ProjectLeaveReason.PENDING:
            return;
        case ProjectLeaveReason.CAN_LEAVE:
            return true;
        case ProjectLeaveReason.CANNOT_LEAVE_NO_COLLABORATORS:
        case ProjectLeaveReason.CANNOT_LEAVE_ADDRESS_BOOK_GROUP_MEMBER:
        case ProjectLeaveReason.CANNOT_LEAVE_LAST_COLLABORATOR:
        case ProjectLeaveReason.CANNOT_LEAVE_LAST_DIRECT_COLLAB_WITH_SHARE_PERMISSION:
        case ProjectLeaveReason.CANNOT_LEAVE_IS_ADMIN_OF_PROJECT:
        case ProjectLeaveReason.CANNOT_LEAVE_IS_OWNER:
        case ProjectLeaveReason.CANNOT_LEAVE_LAST_MAC_MANAGER:
            return false;
        }
    }

    @observable
    hasPermission(...permissions: Permission[]): boolean {
        return permissions.every((permission) =>
            (this._projectPermissions & permission) === permission);
    }

    /**
     * Updates project data like gradientID
     *
     * @param data Data to be updated on a project.
     */
    async updateProject(data: IProjectPatchData) {
        await this._core.projectContext.updateProject(this.id, data);
    }

    /**
     * @package For SAM.js internal use only
     * checks and sets the permission to restore the project
     */
    _applyRestorePermission(updateSession: IUpdateSession<Project>): void {
        // We don't get the project permissions from USS right now so we try to infer the restore permissions
        // A user has restore permissions if she can create a project in the repository.
        const canRestore = this._core.projectContext._getCachedRestoreCapability(this.repositoryID);

        const restorePermissionChanged = canRestore !== this.hasPermission(Permission.Restore);
        this._projectPermissions = canRestore
            ? (this._projectPermissions | Permission.Restore)
            : (this._projectPermissions & ~Permission.Restore);

        if (restorePermissionChanged) {
            // Manually queue a changed item event since using the updater will not allow
            // the change to be detected since we are modifying the bits and then asking
            // the updater to compare the new value with the original value which is the same.
            updateSession.queueChangedItem(this, [ SharedChangeEvent ]);
        }
    }

    /**
    * @package -- only for use in SAM.js
    */
    // TODO: SAM-3499 will allow us to make this more efficient.
    async _reloadPermissions(): Promise<void> {
        await this._load();
        super._reloadPermissions();
    }

    @memoize
    get librariesSource(): AdobeAssetSource {
        const directoryLoader = new AdobeAssetDirectoryLoader(this._core.hostAssetContext._assetPool, this, this._core, true, true);
        const implicitFilter = new ImplicitDirectoryListingAssetFilter({
            asset: this,
            mediaTypes: [ libraryMediaTypeString ],
            // Any Asset in a Project can also be SWY
            _isSharedWithYou: true
        });
        return new ItemSource(this._core.hostAssetContext._assetPool, [ directoryLoader ], implicitFilter);
    }

    @memoize
    get children(): AdobeAssetSource {
        const loader = new AdobeAssetDirectoryLoader(this._core._getAssetPool(), this, this._core, true, true);
        // Children of Project folders can be SWY items
        const implicitFilter = new ImplicitDirectoryListingFilter({ asset: this, _isSharedWithYou: true  });
        const assetPool = this._core._getAssetPool();
        // There could be local assets in the project.
        const localAssetLoader = new LocalAssetLoader<AdobeAssetConfig>(assetPool, this._core);
        return new ItemSource(assetPool, [ loader, localAssetLoader ], implicitFilter);
    }

    @observable
    get repositoryOwner(): Owner {
        return this._repositoryOwner;
    }

    /**
     * Creates a Library in this Project.
     *
     * @example
     * const roles: LibraryRole[] = [{
     *      type: 'brand',
     *      usage: 'usage_brand',
     *      priority: 'priority_brand'
     * }];
     * const library = project.createLibrary({ name: 'test', restrictEdit: true, roles });
     *
     */
    async createLibrary(data: CreateProjectLibraryData): Promise<Library> {
        const libraryContext = await this._core.getLibraryContext();
        const options: CreateLibraryOptions = {
            name: data.name,
            parent_assetId: this.id,
            roles: data.roles
        };

        options.access = data.restrictEdit ? 'team_view' : 'team_edit';

        return libraryContext._createLibrary(options);
    }

    async updateLastAccessed(clear?: boolean): Promise<void> {
        await super.updateLastAccessed(clear);
        const session = this._core.projectContext._assetPool.createUpdateSession<Project>();
        // [SHARED-3832] all Recent projects show in Recent list, but might not show in any other list, so only
        // set isRecent here.
        this._core.projectContext._projectUpdater.updateLocalItem(session, this, { isRecent: Boolean(this.lastAccessed) });
        session.commit();
    }

    /**
     * @experimental API May change.
     *
     * Creates a reference to a library for this project
     * Only libraries can be referenced. Reference creation is restricted to
     * assets with mime type 'application/vnd.adobe.library+dcx'.
     *
     * Users must have write permission to the project to create a reference.
     * Users must have at least read permission on the library to be referenced.
     *
     * @param {string} assetId - the id of the library to reference
     *
     * @example <caption>Create a library reference</caption>
     * const library: Library;
     * await project.createLibraryReference(library.id);
     *
     */
    async createLibraryReference(assetId: string): Promise<void> {
        // call the service
        await this._ensureLink(RelType.PROJECTS_REFERENCE_CREATE);
        const { 'project:referenceId': libraryId } = await this._projectInterface.createLibraryReference(assetId, this._projectLinks as IProjectLinks);

        // update the local library item with the referenced by project
        const libraryContext = await this._core.getLibraryContext();
        const library = await libraryContext.getLibraryByAssetId(libraryId);
        const session = libraryContext._assetPool.createUpdateSession<Library>('create reference library');
        libraryContext._libraryUpdater.updateLocalItem(session, library,
            {
                referenced_by_project: { projectId: this.id, reference: true }
            });
        session.commit();
    }

    /**
     * @experimental API May change.
     *
     * Deletes a reference to a library for this project
     *
     * Users must have write permission to the project to delete a reference.
     * Users must have at least read permission on the library to delete the reference.
     *
     * @param {string} assetId - the id of the library to delete the reference for
     *
     * @example <caption>Delete a library reference</caption>
     * const library: Library;
     * await project.deleteLibraryReference(library.id);
     *
     */
    async deleteLibraryReference(assetId: string): Promise<void> {
        // call the service
        await this._ensureLink(RelType.PROJECTS_REFERENCE_PRIMARY);
        await this._projectInterface.deleteLibraryReference(assetId, this._projectLinks as IProjectLinks);

        // update the local library item to remove the referenced by project
        // since this is a removal of the reference, we only need to update the library if its already in the asset pool
        const assetPool = this._core.hostAssetContext._assetPool;
        const localLibrary = assetPool.getLocalItemById<Library>(assetId);
        if (localLibrary) {
            const libraryContext = await this._core.getLibraryContext();
            const session = libraryContext._assetPool.createUpdateSession<Library>('delete reference library');
            libraryContext._libraryUpdater.updateLocalItem(session, localLibrary,
                {
                    referenced_by_project: { projectId: this.id, reference: false }
                });
            session.commit();
        }
    }

    /**
     * @experimental API May change.
     * Requests access to inaccessible library references for this project.
     * @param notification - The configuration that will be used to notify owners of the library references.
     * @returns The result of the access request.
     */
    async requestAccessToLibraryReferences(notification: IAccessRequestNotification): Promise<IAccessRequestResult> {
        if (this._inaccessibleLibraryReferences === undefined) {
            oneTimeWarning('[INACCESSIBLE_REFERENCES_NOT_LOADED]', 'Inaccessible library references not loaded. No access requests will be made.');
            return {
                successfulRequests: [],
                failedRequests: []
            };
        }

        if (this._inaccessibleLibraryReferences.length === 0) {
            // No inaccessible references - return successful empty result
            return {
                successfulRequests: [],
                failedRequests: []
            };
        }

        // By default request access to library references is a viewer
        const permission: IAccessRequestPermissions = {
            canComment: true,
            canShare: true,
            role: 'viewer'
        };

        const collaborationContext = await this._core.getCollaborationContext();
        return await collaborationContext._requestAccess(
            this._inaccessibleLibraryReferences,
            notification,
            permission
        );
    }
}

function getPermission(source: ProjectUpdaterMetadata): Permission | typeof NotFound {
    // From GraphQL PLS projects (parsed permissions)
    if (source.projectPermissions !== undefined) {
        return source.projectPermissions;
    }
    // From Project listing non-GraphQL
    if (source._embedded?.[RelType.AC_EFFECTIVE]) {
        return parseProjectEffectivePermissions(source._embedded[RelType.AC_EFFECTIVE]!);
    }
    // If the permissions are not present in the metadata then maintain the current value
    return NotFound;
}

export type ProjectUpdaterMetadata = Partial<IProject> & {
    projectPermissions?: Permission;
    isRecent?: boolean;
    allowInLists?: boolean;
    inaccessibleReferences?: string[];
    // Extended fields from GraphQL that aren't part of core IProject
    'repo:ancestors'?: string[];
    'storage:region'?: string;
    // Labels and sharing info
    labels?: Labels;
    // From PLS generated types
    sharedWithYouLabel?: SharedWithYouLabel | null;
}

export const ProjectUpdater = new ItemUpdater<Project, ProjectUpdaterMetadata>({
    localItemType: Project,
    remoteIdProperty: 'repo:assetId',
    propertyUpdater: new PropertyUpdater({
        '_repositoryID': 'repo:repositoryId',
        '_path': 'repo:path',
        '_etag': 'repo:etag',
        '_created': { name: 'repo:createDate', format: 'date' },
        '_description': 'description',
        '_name': 'repo:name',
        '_assetState': { name: 'repo:state', choices: AssetStateChoices },
        '_storageAssignee': { name: 'storage:assignee', format: StorageAssigneeFormat },
        '_projectLinks': { name: '_links', format: 'object' },
        '_creator': { name: `_embedded[${RelType.PROJECTS_CREATOR}]`, format: 'object' },
        '_createdBy': `_embedded[${RelType.PROJECTS_CREATOR}].id`,
        /**
         * @note Adding single quotes to ['project:rendition'] causes the property
         * name to be computed as ''project:rendition'' with two single quotes.
         * This obviously will cause the property updater to not find the requested property and
         * not update it so the property naming convention is [project:rendition]
         * without single quotes around the name.
         */
        '_gradientID': {
            name: `_embedded[${RelType.APP_METADATA}][project:rendition].gradientId`,
            set: (gradientID: string, dest: ISAMObject) => {
                const project = dest as Project;

                if (!gradientID) {
                    project['_gradientID'] = '';
                    return;
                }
                const computedGradientID = computeGradientID(gradientID, project._core._environment.getValue('LOCALE')!);
                if (project['_gradientID'] !== computedGradientID) {
                    project['_gradientID'] = computedGradientID;
                    LazyLoadManager.setLoadStatus(project, CHANGE, LoadStatus.NotLoaded);
                }
            }
        },
        '_projectPermissions': { get: getPermission, format: 'number' },
        '_repositoryOwner': { name: `_embedded[${RelType.REPOSITORY}][repo:owner]`, format: StorageAssigneeFormat },
        '_isRecent': { name: 'isRecent', format: 'boolean' },
        '_allowInLists': { name: 'allowInLists', format: 'boolean' },
        '_directorySubtype': { name: 'project:directorySubtype', choices: projectDirectorySubTypes },
        '_inaccessibleLibraryReferences': { name: 'inaccessibleReferences', isArray: true, format: 'string' },
        '_lastAccessed': { get: (source: ProjectUpdaterMetadata) => source.labels?.lastAccessDate ?? NotFound, format: 'date' },
        '_ancestorIDs': { name: 'repo:ancestors', isArray: true, format: 'string' },
        '_shared': { get: (source: ProjectUpdaterMetadata) => source.sharedWithYouLabel?.shareDate ?? NotFound, format: 'date' },
        '_sharedWithYouLabel': { name: 'sharedWithYouLabel', format: SharedWithYouLabelFormat },
        '_storageRegion': 'storage:region'
    })
});
