import ItemUpdater from '../core/ItemUpdater';
import Post, { getChildPostUpdater } from './Post';
import type { AssetLinkPostDetails, RemoteAssetLinkPost, ResourceReference } from '../interface/BoardModel';
import { observable } from '../core/decorators';
import type { SAM } from '@ccx-public/component-types';

/** Represents a post for a Board which links to an Asset */
class AssetLinkPost extends Post implements SAM.AssetLinkPost {
    private _remoteLink!: ResourceReference;

    @observable
    get link(): AssetLinkPostDetails {
        return {
            mediaType: this._remoteLink['dc:format'],
            assetId: this._remoteLink['repo:assetId'],
            publicUrl: this._remoteLink['board#postPublicUrl']
        };
    }
}

const AssetLinkPostUpdater = new ItemUpdater<AssetLinkPost, Partial<RemoteAssetLinkPost>>({
    localItemType: AssetLinkPost,
    remoteIdProperty: 'id',
    propertyUpdater: getChildPostUpdater({
        _remoteLink: { name: 'link', format: 'object' },
    }),
});

export default AssetLinkPost;
export { AssetLinkPostUpdater };
