import type InvitationInterface from '../interface/InvitationInterface';
import type { IComputedInvitationCollaborator } from '../interface/InvitationModel';
import type Collaborator from './Collaborator';
import { CollaboratorUpdater } from './Collaborator';
import type { IItemLoader, ILoadedPage } from '../core/ItemLoader';
import type ItemPool from '../core/ItemPool';
import type { CollaboratorConfig } from './CollaboratorSource';

export default class CollaboratorLoader implements IItemLoader<CollaboratorConfig> {

    constructor(
        private _collaboratorPool: ItemPool<Collaborator>,
        private _invitationInterface: InvitationInterface,
        private _urn: string) {
    }

    async loadPage(): Promise<ILoadedPage<CollaboratorConfig>> {
        // FIXME: Implement latency tracker once we move more collaborator operations into SAM.JS.

        // Note, this request is piggy-backed, so if we load both the collaborators and invited collaborators at the same
        // time, it only results in one network call
        const result = await this._invitationInterface.getCollaborators(this._urn);

        // Update the collaborators
        const collaboratorUpdateSession = this._collaboratorPool.createLoaderUpdateSession(Date.now());
        const directCollaboratorsData = result.directCollaborators ?? [];
        const directSet = new Set(directCollaboratorsData.map(({ id }) => id));
        const collaboratorsWithComputedProps: IComputedInvitationCollaborator[] = result.collaborators.map(collaborator => {
            const isDirect = directSet.has(collaborator.id);
            const canDiscover = isDirect
                ? directCollaboratorsData.find(dc => dc.id === collaborator.id)?.canDiscover ?? false
                : false;
            return { ...collaborator, isDirect, canDiscover };
        });
        const collaborators = CollaboratorUpdater.updateRemoteItems(collaboratorUpdateSession, collaboratorsWithComputedProps);
        collaboratorUpdateSession.commit();

        return { items: collaborators };
    }
}
