import FrameioBase from './FrameioBase';

// See https://developer.frame.io/api/reference/operation/getAsset/
//  for schema of IFrameioAssetResponse. FrameioFolder
//  encapsulates the data for assets of type="folder".
//
// See FrameioFile, FrameioVersionStack for other asset types.
export default class FrameioAsset extends FrameioBase {
    // ItemBase implements this.id for us
    private _insertedAt?: Date;
    private _name: string = '';
    private _parentId: string | undefined;
    private _projectId: string = '';
    private _teamId: string = '';
    private _updatedAt?: Date;

    /* All of a FrameioAsset's id's should be valid id's.
     *
     * But Frame.io indicates a root_asset folder with
     * (parent_id == null), as a root doesn't have a parent.
     *
     * SAM.js isn't a fan of the null's, so it's using
     * undefined for the same thing.
     */
    get insertedAt(): Date | undefined {
        return this._insertedAt;
    }

    get name(): string {
        return this._name;
    }

    get parentId(): string | undefined {
        return this._parentId;
    }

    async getParent(): Promise<FrameioAsset | undefined> {
        const ctx = this.context;
        const parentId = this.parentId;

        if (parentId) {
            return ctx.getAsset(parentId);
        }
        return undefined;
    }

    get projectId(): string {
        return this._projectId;
    }

    get teamId(): string {
        return this._teamId;
    }

    get updatedAt(): Date | undefined {
        return this._updatedAt;
    }

    /*
     * If the path to an asset relative to it's project is
     *      ./folder/subfolder/asset
     *
     * Then
     *      ancestors[0] = folder : FrameioFolder
     *      ancestors[1] = subfolder : FrameioFolder
     *      ancestors[2] = asset : FrameioAsset
     */
    async getAncestors(): Promise<Array<FrameioAsset>> {
        return this.context.getAncestors(this.id);
    }
}
