import SAMError from '../core/SAMError';
import type { IAdobeAssetFilterOptions } from './AdobeAssetFilter';
import AdobeAssetFilter from './AdobeAssetFilter';
import { SAMErrorCode } from '../core/SAMError';
import type AdobeAsset from './AdobeAsset';
import {
    getMultiValueFilterRelation,
    type ItemFilterRelation
} from '../core/ItemFilter';
import oneTimeWarning from '../utils/oneTimeWarning';
import { USSAssetFilterName } from './USSAssetFilterName';
import { FetchFields } from '../interface/USSv3Model';
/**
 * undefined = include files not uploaded by the user
 * string[] = include files uploaded by the user using these client ids
 * 'ALL' = include all files uploaded by the user under any client id
 */
export type UploadedFromType = 'ALL' | string[] | undefined;

export interface IUSSAdobeAssetFilter extends IAdobeAssetFilterOptions {
    readonly uploadedFrom?: UploadedFromType;

    /**
     * Includes the provided value in the USS query
     * to search for assets that match the storage:assignee.id value.
     *
     */
    readonly userId?: string;
    readonly excludeInheritanceTypes?: string[];
}

/**
 * A Filter that extends AdobeAssetFilter and provides some USS Specific
 * filter options that don't apply to RAPI directory listings.
 */
export default class USSAdobeAssetFilter extends AdobeAssetFilter {
    private _uploadedFrom?: UploadedFromType;
    private _userId: string | undefined;
    private _excludeInheritanceTypes?: Set<string> = undefined;

    constructor(options?: Partial<IUSSAdobeAssetFilter>) {
        super(options);
        const { uploadedFrom, userId, excludeInheritanceTypes } = options ?? {};

        if (uploadedFrom !== undefined) {
            if (!uploadedFrom.length) {
                throw SAMError.create(SAMErrorCode.UNSUPPORTED, 'Empty uploadedFrom array is not currently supported.');
            }
            this._uploadedFrom = uploadedFrom;
        }

        if (userId) {
            this._userId = userId;
        }

        if (excludeInheritanceTypes) {
            this._excludeInheritanceTypes = new Set(excludeInheritanceTypes);
        }
    }

    get name(): string {
        return USSAssetFilterName;
    }

    get hash(): string {
        let hash = `${super.hash}:${this._uploadedFrom}:${this._userId}`;
        hash += ':excludeinheritancetypes=' + (this._excludeInheritanceTypes?.size ? `${[ ...this._excludeInheritanceTypes ].sort().join(',')}` : 'none');
        return hash;
    }

    get uploadedFrom(): UploadedFromType {
        return this._uploadedFrom;
    }

    /**
     * Matches the provided userId to the value of storage:assignee.id in the service.
     *
     * @TODO_Deprecation [SAM-3813] will be removed in future releases in favor of using AdobeAsset.searchChildren searching
     * for items in users /cloud-content.
     *
     * {@link AdobeAsset.searchChildren()}
     */
    get userId(): string | undefined {
        return this._userId;
    }

    /**
     * Excludes assets that are inherited or are inheritable of the types included. For example including
     * "am.cc:inherited.cc:studentAssignment.repo:assetId" would exclude all assets that are within student
     * assignment directories. Including "am.cc:inheritable.cc:studentAssignment.repo:assetId" would exclude
     * all assets that ARE student assignment directories.
     */
    get excludeInheritanceTypes(): Set<string> | undefined {
        return this._excludeInheritanceTypes;
    }

    matches(item: AdobeAsset): boolean {
        // NOTE: storageAssignee is lazy-loaded from R-API data, but not USS. All USS loaders must use
        //       LazyLoadManager to clear the dirty flag for storageAssignee.
        if (this._userId && this._userId !== item.storageAssignee.id) {
            return false;
        }

        /** Filter       Item         createdFromUpload    Return value
         * -----------------------------------------------------------
         * undefined    *            *                    super.matches()
         * 'ALL'        'xyz'        true                 super.matches()
         * ['xyz']      'xyz'        true                 super.matches()
         * 'ALL'        *            false                false
         * ['xyz']      undefined    *                    false
         * ['xyz']      'pdq'        *                    false
         * ['xyz']      *            false                false
         *
         * */

        if (
            Array.isArray(this._uploadedFrom)
            && item.createdFromUpload
            && !this._uploadedFrom.includes(item.createdByClientId ?? '')
        ) {
            return false;
        }

        if (
            (this._uploadedFrom === 'ALL'
            || Array.isArray(this._uploadedFrom))
            && !item.createdFromUpload
        ) {
            return false;
        }

        if (this._excludeInheritanceTypes?.has(FetchFields.StudentAssignmentAssetId) && item.isChildOfStudentAssignment) {
            return false;
        }

        if (this._excludeInheritanceTypes?.has(FetchFields.AssignmentAssetId) && item.isChildOfAssignment) {
            return false;
        }

        return super.matches(item);
    }

    getRelationToFilter(existingFilter: USSAdobeAssetFilter): ItemFilterRelation {
        if (existingFilter.name !== USSAssetFilterName) {
            // Currently we don't support switching between the AdobeAssetFilter and the
            // USSAssetFilter.
            // TODO [SAMJS-821]: cast AAF as USSAAF. If existingFilter is AAF, it works the same as USSAAF where
            //    USSAAF-specific fields are undefined.
            oneTimeWarning('USSAdobeAssetFilter', 'Cannot switch between an AdobeAssetFilter and a USSAdobeAssetFilter');
            return 'disjoint';
        }

        // If they both have ID's and they both are not equal we can assume
        // they are disjointed.
        if (this._userId && existingFilter.userId && this._userId !== existingFilter.userId) {
            return 'disjoint';
        }

        if (this._excludeInheritanceTypes && existingFilter._excludeInheritanceTypes) {
            // Convert to a format that can be easily compared
            const thisFilterExcludeInheritanceTypes = [ ...this._excludeInheritanceTypes ].sort();
            const existingFilterExcludeInheritanceTypes = [ ...existingFilter._excludeInheritanceTypes ].sort();
            // TODO [SAMJS-821]: this is comparing if the two arrays are the same *instance*, not the same *values*,
            //      so will always be disjoint. Also, "exclude" relations are tricky. "Exclude {A}" entirely overlaps
            //      "exclude {A, B}" but "exclude {A, B}" only partially overlaps "exclude {A}". See
            //      AdobeAssetFilter.excludeMediaTypes for example on how to compare "exclude" filters.
            if (thisFilterExcludeInheritanceTypes !== existingFilterExcludeInheritanceTypes) {
                return 'disjoint';
            }
        }

        // TODO [SAMJS-821] since there are additional 'disjoint' cases detected below, this can return 'unknown'
        //    when the filters are actually 'disjoint'
        if ((this.excludeInheritanceTypes && !existingFilter.excludeInheritanceTypes) || (!this.excludeInheritanceTypes && existingFilter.excludeInheritanceTypes)) {
            return 'unknown';
        }

        // If both the new filter and the existing filter are arrays
        // meaning they are requesting a specific applications client id
        // and they are both different, this means the list is disjoint because
        // if let's say the existing filter is app 'xyz' and the new one is 'zzz'
        // they cannot share any items.
        if (Array.isArray(this.uploadedFrom)
            && Array.isArray(existingFilter.uploadedFrom)
        ) {
            const arrayRelationship = getMultiValueFilterRelation(this.uploadedFrom, existingFilter.uploadedFrom);
            if (arrayRelationship === 'disjoint') {
                return 'disjoint';
            }
            if (arrayRelationship === 'unknown') {
                return 'unknown';
            }
        }

        /**
         * If the new filter has uploadedFrom undefined and the existing filter
         * is defined that means we could possibly borrow some items from the new list.
         */
        if (!this.uploadedFrom && existingFilter.uploadedFrom) {
            return 'unknown';
        }

        if (this.uploadedFrom === 'ALL' && Array.isArray(existingFilter.uploadedFrom)) {
            return 'unknown';
        }

        if (!this.userId && existingFilter.userId) {
            return 'unknown';
        }

        // Call into super to handle all AdobeAsset filter cases.
        // TODO [SAMJS-821]: since the above will return 'unknown' before calling super, it will miss cases that are
        //      disjoint in the super.
        return super.getRelationToFilter(existingFilter);
    }
}
