import type { USSAdobeAssetUpdaterMetadata } from './AdobeAsset';
import type AdobeAsset from './AdobeAsset';
import type { IItemSourceConfig } from '../core/ItemList';
import type { IItemLoader, IItemLoaderOptions, ILoadedPage, ILoadNextPage } from '../core/ItemLoader';
import type ItemPool from '../core/ItemPool';
import type { USSMetadata, USSResponse } from '../interface/USSModel';
import type { ISAMCorePrivate } from '../indexPrivate';
import type { IUpdateSession } from '../core/UpdateSession';
import type LibraryContext from '../libraries/LibraryContext';
import { USSAssetFilterName } from './USSAssetFilterName';
import type USSAdobeAssetFilter from './USSAdobeAssetFilter';
import { LazyLoadManager } from '../core/decorators/LazyLoadManager';
import { STORAGE_ASSIGNEE_CHANGED } from './AssetEvents';
import type { UpdaterMap } from './AdobeAssetFactory';
import type CustomModelContext from '../custom-models/CustomModelContext';
import { getExcludeMediaTypesFromFilters, getMediaTypesFromFilters, getMostRecentValidMutation } from '../utils/loaderUtils';

interface IMediaTypes {
    mediaTypes: string[];
    excludeMediaTypes: string[];
}

export interface IGetUSSResults<T extends IItemSourceConfig<AdobeAsset>> extends IItemLoaderOptions<T>, IMediaTypes {
    start: number;
}

export function getUSSV2ItemData(item: Partial<USSMetadata>): USSAdobeAssetUpdaterMetadata {
    let publicLink: boolean | undefined = false;
    let directCount: number | undefined = 0;
    const collaboration_metadata = item['collaboration_metadata'];
    if (collaboration_metadata !== undefined) {
        publicLink = collaboration_metadata.some((collaborator) => {
            return collaborator.collaborator_id === 'all';
        });
        directCount = collaboration_metadata.length;
    }
    const collabMetadataMine = item['collab_metadata#mine'];
    return {
        ...item,
        // Presence of collab_metadata#mine indicates that the item is shared with the user via an invite
        sharedViaInvite: collabMetadataMine !== undefined,
        // absence of coallb_metadata#mine.type means the user belongs to a group on this Asset
        // Invitation service cannot detect this case, so lazy-loading collaborator data should
        // never override isSWYAsset when isSWYGroup is true.
        isSWYGroup: collabMetadataMine !== undefined && !collabMetadataMine.type,
        isShared: directCount > 0,
        isPublicLink: publicLink,
        directCollaboratorCount: directCount,
        // No need to refresh collaborators for share flags, directCollaboratorCount, since they are computed
        // above. Not clearing the collaboratorDataIsDirty flag, because we cannot populate collaboratorArray
        // from USS.
        shareFlagsAreDirty: false
    };
}

export interface IUSSLoader<T extends IItemSourceConfig<AdobeAsset>> extends IItemLoader<T> {
    /**
     * Loaders must implement this method and call from Loader.loadPage(options)
     */
    _getUSSResults(opts: IGetUSSResults<T>): Promise<USSResponse>;
    /**
     * Loaders can optionally implement to provide additional metadata that is
     * implied by the Loader but not included in the USS response.
     */
    _getItemData?(item: Partial<USSMetadata>): USSAdobeAssetUpdaterMetadata;
    /**
     * Loaders can optionally implement to perform additional internal state management.
     */
    _postProcessPage?(loaderPageOpts: IItemLoaderOptions<T>, page: ILoadedPage<T>): void;
    /**
     * Loaders can optionally implement to perform additional processing of USS search results.
     */
    _extractItems?(session: IUpdateSession<AdobeAsset>, items: USSMetadata[]): AdobeAsset[];
    /**
     * Loaders can optionally preload the library context.
     */
    _libraryContext?: LibraryContext;
    /**
     * Loaders can optionally pass reference to the CustomModelContext.
     */
    _customModelContext?: CustomModelContext;
}

const DEFAULT_LIMIT = 50;

/**
 * AdobeAsset Loader classes should use this class to do the page loading. Using composition rather
 * than inheritance because a base USSLoader class was causing circular dependencies at runtime that
 * would cause the base USSLoader class to be undefined when the Loader class that was extending it
 * was declared.
 */
export default class USSLoaderHelper<T extends IItemSourceConfig<AdobeAsset>> {
    constructor(
        private _assetPool: ItemPool<AdobeAsset>,
        protected _core: ISAMCorePrivate,
        private _loader: IUSSLoader<T>
    ) {}

    async loadPage(options: IItemLoaderOptions<T>, start?: number): Promise<ILoadedPage<T>> {
        const {  order, filter, implicitFilter, resource } = options;
        const { limit = DEFAULT_LIMIT } = options.loadOptions ?? {};
        const latency = this._core._environment.getValue('USS_LIST_UPDATE_LATENCY');
        start = start || 0;

        const mediaTypes = getMediaTypesFromFilters(implicitFilter, filter);
        const excludeMediaTypes = getExcludeMediaTypesFromFilters(implicitFilter, filter);

        let uploadedFrom;
        let userId;
        if ('name' in filter && filter.name === USSAssetFilterName) {
            const ussAssetFilter = filter as USSAdobeAssetFilter;
            uploadedFrom = ussAssetFilter.uploadedFrom;
            userId = ussAssetFilter.userId;
        }

        const result: USSResponse = await this._loader._getUSSResults({
            order,
            loadOptions: { limit, ...options.loadOptions,  },
            filter,
            implicitFilter,
            resource,
            start,
            mediaTypes: Array.from(mediaTypes ?? []),
            excludeMediaTypes: Array.from(excludeMediaTypes ?? []),
            ...(uploadedFrom ? { uploadedFrom } : {}),
            ...(userId ? { userId } : {})
        });

        const resultSet = result.result_sets[0];

        const mostRecentValidMutation = getMostRecentValidMutation(resource, latency);

        const updaters = await this._core._adobeAssetFactory.getUSSUpdaters(resultSet.items as USSMetadata[]);
        const session = this._assetPool.createLoaderUpdateSession(mostRecentValidMutation);
        const items = this._extractItems(session, resultSet.items as USSMetadata[], updaters);

        let loadNextPage: ILoadNextPage<T> | undefined;
        const total = resultSet.total_items || 0;
        const pageItemCount = resultSet.items.length;
        // [SEARCH-30755] -- May be caused by USS filtering out items due to permissions for the
        // current user, which aren't subtracted from the total. Try to ensure that the Loader paginates
        // as though the total_items is correct.
        const nextStartIndex = (pageItemCount === 0 ? start + limit : start + pageItemCount);
        if (nextStartIndex < total) {
            loadNextPage = (options: IItemLoaderOptions<T>) => this.loadPage(options, nextStartIndex);
        }

        const page: ILoadedPage<T> = {
            items,
            total,
            loadNextPage,
            mostRecentValidMutation
        };

        // allow Loader to do additional internal state management (optional)
        this._loader._postProcessPage?.(options, page);

        // Mark storage assignee as loaded to prevent lazy loading
        for (const item of items) {
            LazyLoadManager.updatedByItemUpdater(item, STORAGE_ASSIGNEE_CHANGED);
        }

        session.commit();

        return page;
    }

    private _getItemData(item: Partial<USSMetadata>): USSAdobeAssetUpdaterMetadata {
        return getUSSV2ItemData(item);
    }

    /**
     * @package -- for use by USSLoaderHelper
     */
    _extractItems(session: IUpdateSession<AdobeAsset>, items: USSMetadata[], updaters: UpdaterMap): AdobeAsset[] {
        return this._core._adobeAssetFactory.assetsFromUSSMetadata(session, items, this._loader._getItemData || this._getItemData, updaters);
    }
}
