import type { IItemLoader, IItemLoaderOptions, ILoadedPage, ILoadNextPage } from '../core/ItemLoader';
import type ISAMCorePrivate from '../core/ISAMCorePrivate';
import type { ApplicationMetadata, AssetListFilter } from './generated/types';
import type AdobeAssetFilter from '../assets/AdobeAssetFilter';
import type { AdobeAssetUpdaterMetadata } from '../assets/AdobeAsset';
import type AdobeAsset from '../assets/AdobeAsset';
import { DEFAULT_PLS_PAGE_SIZE, type PLSListResponse } from './models/PLSModels';
import { RelType } from '../interface/LinkUtils';
import type { IAppMetadata, RepositoryMetadata } from '../interface/RepositoryModel';
import { AssetType } from '../interface/AssetModel';
import { FOLDER_TYPE } from '../interface/AssetInterface';
import type { IItemSourceConfig } from '../core/ItemList';
import type Resource from '../assets/Resource';
import { ManagedPromise } from '../utils/ManagedPromise';
import { getMostRecentValidMutation } from '../utils/loaderUtils';

export default abstract class PLSListLoader<TData, T extends IItemSourceConfig> implements IItemLoader<T> {
    _assetListId?: string;
    constructor(protected _core: ISAMCorePrivate) { }

    async loadPage(options: IItemLoaderOptions<T>): Promise<ILoadedPage<T>> {
        return await this._loadPage(options);
    }

    supportsFilter(): boolean {
        return true;
    }
    /**
    * Gets the assetListId associated with this loader, if available.
    */
    get assetListId(): string | undefined {
        return this._assetListId;
    }


    private async _loadPage(
        options: IItemLoaderOptions<T>,
        after?: string
    ): Promise<ILoadedPage<T>> {
        const filter = this._getAssetListFilter(options);

        // We must wait until we've added the list items to the ItemPool
        // before we can update those items with _processIncrementalData,
        // which assumes the items are in the pool.
        const readyToProcessIncrementalData = new ManagedPromise<void>();

        const { items: plsRemoteItems, pageInfo, assetListId } = await this._getPLSData({
            first: options.loadOptions?.limit ?? DEFAULT_PLS_PAGE_SIZE,
            after,
            filter,
            order: options.order,
            resource: options.resource
        }, async (incrementalData) => {
            await readyToProcessIncrementalData.promise;
            this._processIncrementalData(incrementalData);
        });

        if (assetListId) {
            this._assetListId = assetListId;
        }

        const latency = this._core._environment.getValue('GQL_LIST_UPDATE_LATENCY');
        const mostRecentValidMutation = getMostRecentValidMutation(options.resource, latency);

        const session = this._core
            ._getAssetPool()
            .createLoaderUpdateSession<AdobeAsset>(mostRecentValidMutation);
        const updaters = await this._core._adobeAssetFactory.getRepoMetadataUpdaters(plsRemoteItems as RepositoryMetadata[]);
        const items = this._core._adobeAssetFactory.assetsFromRepoMetadata(session, plsRemoteItems as RepositoryMetadata[], updaters);
        let loadNextPage: ILoadNextPage<T> | undefined;
        if (pageInfo.hasNextPage) {
            loadNextPage = (options: IItemLoaderOptions<T>) => this._loadPage(options, pageInfo.endCursor!);
        }

        session.commit();
        readyToProcessIncrementalData.resolve();

        return {
            items,
            loadNextPage,
            mostRecentValidMutation,
            assetListId: this._assetListId
        };
    }

    private _getAssetListFilter(options: IItemLoaderOptions<T>): AssetListFilter {
        const { mediaTypes, assetTypes, excludeAssetTypes, assetSubTypes } = options.filter as AdobeAssetFilter;

        // Folders and projects should never be included in PLS listings
        const filter: AssetListFilter = {
            dcFormat: {
                nin: [ FOLDER_TYPE ],
                // Include specific media types if specified, while still excluding directories
                ...(mediaTypes?.size ? { in: [ ...mediaTypes ] } : {})
            }
        };

        if (excludeAssetTypes?.size) {
            filter.assetType = { nin: [ ...new Set([ AssetType.Project, ...excludeAssetTypes ]) ] };
        } else if (assetTypes?.size) {
            filter.assetType = { in: [ ...new Set(assetTypes) ], nin: [ AssetType.Project ] };
        } else {
            // By default, exclude the projects
            filter.assetType = { nin: [ AssetType.Project ] };
        }
        if (assetSubTypes?.size) {
            filter.assetSubType = { in: [ ...assetSubTypes ] };
        }

        return filter;
    }

    abstract _getPLSData(
        options: {
            first: number;
            after?: string;
            filter: AssetListFilter;
            order: T['order'],
            resource?: Resource
        },
        processIncrementalData: (incrementalData: TData) => void
    ): Promise<PLSListResponse<AdobeAssetUpdaterMetadata>>;


    abstract getAssetNodesFromData(incrementalData: TData): { repo_assetId: string; appMetadata: { am: ApplicationMetadata } }[];

    private _processIncrementalData(incrementalData: TData): void {
        const pool = this._core._getAssetPool();
        const session = pool.createUpdateSession();
        const updater = this._core._getAssetContext()!._adobeAssetUpdater;

        const remoteItems: AdobeAssetUpdaterMetadata[] = this.getAssetNodesFromData(incrementalData)
            .filter(item => {
                return item.appMetadata?.am && pool.getLocalItemById(item.repo_assetId) !== undefined;
            })
            .map(item => {
                return {
                    'repo:assetId': item.repo_assetId,
                    _embedded: {
                        [RelType.APP_METADATA]: item.appMetadata?.am as IAppMetadata,
                    }
                };
            });

        updater.updateRemoteItems(
            session,
            remoteItems
        );
        session.commit();
    }
}
