import type { IGetUSSResultsOpts, IUSSLoader } from './USSv3LoaderHelper';
import USSv3LoaderHelper from './USSv3LoaderHelper';
import type { AdobeAssetGlobalSearchConfig } from './AdobeAssetSource';
import type ItemPool from '../core/ItemPool';
import type AdobeAsset from './AdobeAsset';
import { DEFAULT_MAX_LIMIT } from '../interface/USSv3Interface';
import type { IItemLoaderOptions, ILoadedPage } from '../core/ItemLoader';
import type {
    USSResponse,
    USSv3InheritanceTypeField
} from '../interface/USSv3Model';
import type AdobeAssetGlobalSearchFilter from './AdobeAssetGlobalSearchFilter';
import type GlobalSearchInterface from '../interface/GlobalSearchInterface';
import type { ISAMCorePrivate } from '../indexPrivate';
import type LibraryContext from '../libraries/LibraryContext';
import type USSAdobeAssetFilter from './USSAdobeAssetFilter';

export default class GlobalSearchLoader implements IUSSLoader<AdobeAssetGlobalSearchConfig> {
    private _ussLoaderHelper: USSv3LoaderHelper<AdobeAssetGlobalSearchConfig>;
    /**
      * @package -- only for use in SAM.js
      */
    _libraryContext?: LibraryContext;
    constructor(
        assetPool: ItemPool<AdobeAsset>,
        private _core: ISAMCorePrivate,
        private _globalSearchInterface: GlobalSearchInterface,
        private _implicitFilter: AdobeAssetGlobalSearchFilter
    ) {
        this._ussLoaderHelper = new USSv3LoaderHelper<AdobeAssetGlobalSearchConfig>(assetPool, this._core, this);
    }

    supportsFilter(filter?: AdobeAssetGlobalSearchConfig['filter']): boolean {
        return filter !== undefined;
    }

    async loadPage(options: IItemLoaderOptions<AdobeAssetGlobalSearchConfig>): Promise<ILoadedPage<AdobeAssetGlobalSearchConfig>> {
        if (!this._libraryContext) {
            this._libraryContext = await this._core.getLibraryContext();
        }
        return this._ussLoaderHelper.loadPage(options);
    }

    _getUSSResults({
        start,
        loadOptions,
        order,
        mediaTypes,
        excludeMediaTypes,
        filter
    }: IGetUSSResultsOpts<AdobeAssetGlobalSearchConfig>): Promise<USSResponse> {
        const { _query: query, projectsOnly } = this._implicitFilter;
        const {
            excludeInheritanceTypes,
            assetTypes,
            excludeAssetTypes,
            assetSubTypes
        } = filter as USSAdobeAssetFilter;

        return this._globalSearchInterface.globalSearch({
            start,
            limit: loadOptions?.limit ?? DEFAULT_MAX_LIMIT,
            query,
            order,
            mediaTypes,
            excludeMediaTypes,
            // Public interface doesn't enforce valid values for excludeInheritanceTypes. Using cast here
            // to avoid breaking the public interface.
            excludeInheritanceTypes: [ ...(excludeInheritanceTypes || []) ] as USSv3InheritanceTypeField[],
            projectsOnly,
            assetTypes: [ ...(assetTypes || []) ],
            excludeAssetTypes: [ ...(excludeAssetTypes || []) ],
            assetSubTypes: [ ...(assetSubTypes || []) ]
        });
    }

    _postProcessPage(
        // eslint-disable-next-line @typescript-eslint/no-unused-vars
        { filter }: IItemLoaderOptions<AdobeAssetGlobalSearchConfig>,
        { items }: ILoadedPage<AdobeAssetGlobalSearchConfig>
    ): void {
        this._implicitFilter._matchingIDsFromSearch = new Set([
            // copy existing
            ...(this._implicitFilter._matchingIDsFromSearch || []),
            ...(items.map(item => item.id))
        ]);
    }
}
