import type AdobeAsset from '../assets/AdobeAsset';
import type { IComparatorMap } from '../core/ItemOrder';
import { compareValues, createItemOrderFactory } from '../core/ItemOrder';
import { getSeedInfo } from './utils';

export type GenerationHistoryAssetOrderField = 'created' | 'seed';

const OrderFieldToComparator: IComparatorMap<AdobeAsset, GenerationHistoryAssetOrderField> = {
    created(a: AdobeAsset, b: AdobeAsset): number {
        return compareValues(a.created, b.created);
    },
    seed(a: AdobeAsset, b: AdobeAsset): number {
        let aSeed: string | undefined;
        let bSeed: string | undefined;

        try {
            aSeed = getSeedInfo(a);
        } catch (e) {
            // Seed not available for asset a
        }

        try {
            bSeed = getSeedInfo(b);
        } catch (e) {
            // Seed not available for asset b
        }

        // Handle undefined seeds
        if (aSeed === undefined && bSeed === undefined) {
            return 0; // Both undefined, consider equal
        } else if (aSeed === undefined) {
            return 1; // Undefined seeds sort to the end (ascending)
        } else if (bSeed === undefined) {
            return -1; // Undefined seeds sort to the end (ascending)
        } else {
            return compareValues(parseInt(aSeed, 10), parseInt(bSeed, 10));
        }
    },
};

export default class GenerationHistoryAssetOrder extends createItemOrderFactory(OrderFieldToComparator) {
    static default = new GenerationHistoryAssetOrder('descending', 'created');
}
