import type { IOrderDirection } from '../core/ItemOrder';
import InterfaceBase from './InterfaceBase';
import type { ISearchQuery, ISearchSortOrderDirection, USSResponse } from './USSModel';
import { SearchProps } from './USSModel';
import type { IUSSAdobeAssetOrderBy } from './AssetModel';
import {
    updateAssetTypeForUSS
} from './USSUtils';
import { excludeExpressArtifacts } from '../utils/excludeExpressArtifacts';

type IPageOptions = {
    limit: number;
    start?: number;
}

interface IListingOptions<IOrderField> extends IPageOptions {
    orderDirection: IOrderDirection;
    orderBy: IOrderField;
}

export interface PublishedAssetsListingOptions extends IListingOptions<IUSSAdobeAssetOrderBy> {
    mediaTypes?: string[],
    excludeMediaTypes?: string[],
}

const DefaultPublishedAssetsListingOptions: PublishedAssetsListingOptions = {
    orderDirection: 'descending',
    orderBy: 'modify_date',
    start: 0,
    limit: 0,
    mediaTypes: [],
    excludeMediaTypes: [],
};

export function getDirectionValue(userOptions: Partial<PublishedAssetsListingOptions>): ISearchSortOrderDirection {
    return userOptions.orderDirection === 'ascending' ? 'asc' : 'desc';
}

export default class PublishedInterface extends InterfaceBase {

    async getPublishedAssets(options?: Partial<PublishedAssetsListingOptions>): Promise<USSResponse> {
        options = { ...DefaultPublishedAssetsListingOptions, ...options };
        updateAssetTypeForUSS(options.mediaTypes);
        updateAssetTypeForUSS(options.excludeMediaTypes);

        const filters: ISearchQuery = {
            sort_orderby: options.orderBy,
            hints: {
                acp_platform_v2: true,
            },
            fetch_fields: { includes: [ 'app_metadata' ] },
            op_or: [
                {
                    [SearchProps.CREATIVE_CLOUD_TOPLEVEL_COLLECTION_NAME]: 'pubs'
                },
                {
                    [SearchProps.OP_AND]: [
                        {
                            [SearchProps.CREATIVE_CLOUD_TOPLEVEL_COLLECTION_NAME]: 'cloud-content'
                        },
                        {
                            [SearchProps.FIELD_EXISTS]: [ 'app_metadata$$review:sourceAsset$$dc:format' ]
                        }
                    ],
                }
            ],
            op_none_of: [
                {
                    [SearchProps.TYPE]: options.excludeMediaTypes || [],
                },
                // SAMJS-773
                ...excludeExpressArtifacts()
            ],
            [SearchProps.STORAGE_ASSIGNEE_ID]: this._core._environment.getValue('USER_ID'),
            asset_id_opacity: true,
            [SearchProps.TYPE]: options.mediaTypes || [],
            sort_order: getDirectionValue(options),
            limit: options.limit,
            start_index: options.start,
        };

        return await this._core.hostAssetContext._ussInterface.getQueryResponse(filters);
    }
}
