import type {
    IItemLoader,
    IItemLoaderOptions,
    ILoadedPage
} from '../core/ItemLoader';
import type { GroupMemberConfig } from './GroupMemberSource';
import type AddressBookContact from './AddressBookContact';
import type ItemPool from '../core/ItemPool';
import type AddressBookInterface from '../interface/AddressBookInterface';
import type ItemUpdater from '../core/ItemUpdater';
import type {
    IAddressBookGroupMembersFlat,
    IAddressBookContact
} from '../interface/AddressBookModel';

export default class GroupMemberLoader implements IItemLoader<GroupMemberConfig> {

    constructor(
        private _addressBookUrl: string,
        private _groupMemberPool: ItemPool<AddressBookContact>,
        private _addressBookInterface: AddressBookInterface,
        private _groupMemberUpdater: ItemUpdater<AddressBookContact, IAddressBookContact>,
    ) {}

    async loadPage(opts?: IItemLoaderOptions<GroupMemberConfig>, nextPageLink?: string): Promise<ILoadedPage<GroupMemberConfig>> {
        const { limit = 100 } = opts?.loadOptions || { limit: 100 };
        let result: IAddressBookGroupMembersFlat;

        if (!nextPageLink) {
            result = await this._addressBookInterface.getMembersFirstPage(this._addressBookUrl, limit);
        } else {
            result = await this._addressBookInterface.getMembersNextPage(nextPageLink);
        }

        const session = this._groupMemberPool.createLoaderMutationSession();
        const items = this._groupMemberUpdater.updateRemoteItems(session, result._embedded.contacts);
        session.commit();

        const loadNextPage = result._links.next
            ? () => this.loadPage(undefined, result._links.next.href)
            : undefined;

        return {
            items,
            loadNextPage,
            total: result.total
        };
    }

}
