import type ISAMCorePrivate from '../core/ISAMCorePrivate';
import type { ISAMObject } from '../core/ISAMObject';
import type AdobeACE from './AdobeACE';
import type { AdobeACEMetadata } from './AccessControlModel';
import SAMError, { isSAMError, SAMErrorCode } from '../core/SAMError';
import type AssetInterface from '../interface/AssetInterface';

export default class AdobeACL implements ISAMObject {
    constructor(
        public _core: ISAMCorePrivate,
        private _assetId: string,
        private _etag: string,
        private _aces: AdobeACE[] = [],
        private _assetInterface: AssetInterface
    ) {}

    /**
     * Returns a copy of the ACEs as an array
     */
    public get aces(): AdobeACE[] {
        // Copy the ACEs to avoid mutating the original array
        return [ ...this._aces ];
    }

    public set aces(value: AdobeACE[]) {
        // Copy the ACEs from the original data to ensure it doesn't get mutated
        this._aces = [ ...value ];
    }

    public get assetId(): string {
        return this._assetId;
    }

    public get etag(): string {
        return this._etag;
    }

    public set etag(value: string) {
        this._etag = value;
    }

    public get isEmpty(): boolean {
        return this._aces.length === 0;
    }

    private async _forceRefreshACL(): Promise<void> {
        const accessControlContext = await this._core.getAccessControlContext();
        await accessControlContext.getACL(this.assetId, true /* forceRefresh */);
    }

    private async _handleConflict(e: any) {
        if (isSAMError(e)) {
            if (e.code === SAMErrorCode.CONFLICT) {
                // If the ETag does not match the server's ETag, it will throw
                // a CONFLICT error. In this case, we should optimistically refresh
                // the ACL from the server and try again.
                await this._forceRefreshACL();
            }
        }
        throw e;
    }

    /**
     * Determines if there are any ACES with changes locally that have not been
     * pushed to the server.
     *
     * @returns - an array of ACEs that have been modified locally
     */
    public hasDirtyACES(): boolean {
        return this._aces.some(ace => ace._isDirty);
    }

    /**
     * Removes the provided ACEs from the ACL.
     *
     * @param aces - The ACEs to remove from the ACL.
     * @returns - The updated ACL.
     */
    public async removeACES(aces: AdobeACE[]): Promise<AdobeACE[]> {
        // if there are any dirty ACEs, throw an error since
        // this will clear the local changes and get new ACEs from the server
        // so we want to give the client a chance to update the local ACEs.
        if (this.hasDirtyACES()) {
            throw SAMError.create(
                SAMErrorCode.BAD_REQUEST,
                'Cant delete ACEs with pending changes, these will be overwritten'
            );
        }

        // Copy the ACEs to avoid mutating the original array
        const copiedAces = [ ...aces ];
        copiedAces.sort((ace1, ace2) => ace1.id < ace2.id ? 0 : -1);

        try {
            await this._assetInterface.deleteAccessControlEntries(aces, this._etag);
        } catch (e) {
            await this._handleConflict(e);
        }

        // If we made it this far, the ACEs were deleted successfully so let's
        // fetch the new ACEs from the server and update the local ACEs.
        await this._forceRefreshACL();
        return this._aces;
    }

    /**
     * Adds the provided ACEs to the ACL.
     *
     * @param aces - The ACEs to add to the ACL.
     * @returns - The updated ACL.
     */
    public async addACES(aces: AdobeACEMetadata[]): Promise<AdobeACE[]> {
        // if there are any dirty ACEs, throw an error since
        // this will clear the local changes and get new ACEs from the server
        // so we want to give the client a chance to update the local ACEs.
        if (this.hasDirtyACES()) {
            throw SAMError.create(
                SAMErrorCode.BAD_REQUEST,
                'Cant add ACES with pending changes, these will be overwritten'
            );
        }

        await this._assetInterface.addAccessControlEntries(aces, this._etag);

        // If we made it this far, the ACEs were added successfully so let's
        // fetch the new ACEs from the server and update the local ACEs.
        await this._forceRefreshACL();
        return this._aces;
    }

    /**
     * Commits and updates the local ACEs in this ACL with the servers ACL
     *
     * @throws {SAMErrorCode.CONFLICT} if the ETag does not match the server's ETag
     *
     */
    public async updateACES() {
        if (!this.hasDirtyACES()) {
            throw SAMError.create(
                SAMErrorCode.BAD_REQUEST,
                'No changes to commit'
            );
        }

        const dirtyACES = this._aces.filter(ace => ace._isDirty);
        try {
            await this._assetInterface.updateAccessControlList(dirtyACES, this._etag);
        } catch (e) {
            await this._handleConflict(e);
        }

        // If we made it this far, the ACEs were updated successfully so let's
        // fetch the new ACEs from the server and update the local ACEs.
        await this._forceRefreshACL();
    }
}
