import type { IProjectsSpaceOrderBy } from '../interface/WorkspacesModel';

import type { IComparatorMap } from '../core/ItemOrder';
import { compareStrings, compareValues, createItemOrderFactory } from '../core/ItemOrder';
import type Space from './Space';

export type SpaceOrderField =
    | 'name'
    | 'created';

export const OrderFieldToIProjectsSpaceOrderBy: { [key in SpaceOrderField]: IProjectsSpaceOrderBy } = {
    'name': 'name',
    'created': 'createdDate',
};

const OrderFieldToComparator: IComparatorMap<Space, SpaceOrderField> = {
    name(a: Space, b: Space): number {
        return compareStrings(a.name, b.name);
    },
    created(a: Space, b: Space): number {
        return compareValues(a.created, b.created);
    }
};

export default class SpaceOrder extends createItemOrderFactory(OrderFieldToComparator) {
    static default = new SpaceOrder('ascending', 'name');
}
