import type { SAM } from '@ccx-public/component-types';
import type AdobeAsset from '../assets/AdobeAsset';
import type ItemPool from '../core/ItemPool';
import ItemSource from '../core/ItemSource';
import { type ISAMCorePrivate, type ISAMObject } from '../indexPrivate';
import SAMError, { SAMErrorCode } from '../core/SAMError';
import { memoize } from '../core/decorators';
import { keepAlive } from '../core/decorators/KeepAliveManager';
import GenerationHistoryInterface from '../interface/GenerationHistoryInterface';
import { GenerationHistoryAssetUpdater } from './GenerationHistoryAsset';
import { isGenerationHistoryAsset, getGenerationGroupId } from './utils';
import ImplicitGenerationHistoryAssetFilter from './ImplicitGenerationHistoryAssetFilter';
import GenerationHistoryAssetLoader from './GenerationHistoryAssetLoader';
import type { GenerationHistoryAssetConfig } from './GenerationHistoryAssetSource';
import GenerationHistorySiblingLoader from './GenerationHistorySiblingLoader';
import type {
    IGenerationHistoryFilterParams
} from './GenerationHistoryAssetFilter';
import {
    default as GenerationHistoryAssetFilter,
} from './GenerationHistoryAssetFilter';
import type { IOrderDirection } from '../core/ItemOrder';
import { default as GenerationHistoryAssetOrder, type GenerationHistoryAssetOrderField } from './GenerationHistoryAssetOrder';
import * as generationHistoryUtils from './utils';
import type { UpdateAccessRequest } from '@sam-js-src/sharing/SharingContext';
import { MEDIA_TO_HISTORY_ASSET_TYPE, HISTORY_ASSET_TYPE_TO_MEDIA_TYPE, GENERATION_HISTORY_MEDIA_TYPES } from '../interface/GenerationHistoryAssetModel';
import { getPrincipalCollaborators } from '@sam-js-src/utils/sharingUtils';
import { waitForSisterList } from './utils';

const ERROR_MESSAGE_SHARING_RESTRICTION = 'security/sharingRestriction';
type PublicLinkResponse = {
    link: string; // TODO: [GLOW-1696] Remove this after we remove the link from the PublicLinkResponse
    permission: 'all' | 'orgEverybody';
};

const _throwIfFailedCollaborators = (updateAccessResult: SAM.UpdateAccessResult) => {
    const failedCollaborators = updateAccessResult.filter(
        r => r.action === 'add' && r.error
    );
    if (failedCollaborators.length > 0) {
        throw failedCollaborators[0].error;
    }
};

/**
 * Provides Generation History functionality such as listing.
 *
 * @experimental This API is in an experimental phase so expect that
 * API's will not be final and there will be breaking changes
 * without bumping the major version until this comment is removed.
 */
export default class GenerationHistoryContext implements ISAMObject, SAM.GenerationHistoryContext {
    readonly _generationHistoryInterface = new GenerationHistoryInterface(this._core);
    readonly _generationHistoryAssetUpdater = GenerationHistoryAssetUpdater;
    /** @package -- for use in SAM.js only */
    _fireflyGenerationsDirectoryID?: string;

    constructor(
        /** @package -- for use in SAM.js only
         */
        readonly _core: ISAMCorePrivate,
        /** @package -- for use in SAM.js only
         */
        readonly _assetPool: ItemPool<AdobeAsset>
    ) {}


    @memoize
    get generationHistorySource() {
        return new ItemSource<GenerationHistoryAssetConfig>(
            this._assetPool as ItemPool<AdobeAsset>,
            [
                new GenerationHistoryAssetLoader(this._core, this._generationHistoryInterface),
                new GenerationHistorySiblingLoader(this._core)
            ],
            new ImplicitGenerationHistoryAssetFilter());
    }

    @keepAlive
    async getGenerationHistoryAssetById(assetId: string, updateLastAccessed?: boolean): Promise<AdobeAsset> {
        const localAsset = this._assetPool.getLocalItemById<AdobeAsset>(assetId);
        if (localAsset) {
            if (!isGenerationHistoryAsset(localAsset)) {
                throw SAMError.create(SAMErrorCode.INVALID_OPERATION, 'Attempting to fetch asset type that is not a generation history asset');
            }
            if (updateLastAccessed) {
                localAsset.updateLastAccessed().catch(error => {
                    // Log the error but do not fail the entire operation if updating last accessed fails
                    this._core._environment.error(`Failed to update last accessed for asset ${assetId}: ${error}`);
                });
            }
            return localAsset;
        }

        // Use only GraphQL getAssetById to fully resolve the generation history asset.
        // GraphQL returns all needed data including isFavorite and generationModelDisplayName.
        const historyAsset = await (await this._core._getGQLManager()).getAssetById(assetId);

        if (!isGenerationHistoryAsset(historyAsset)) {
            throw SAMError.create(SAMErrorCode.INVALID_OPERATION, 'Attempting to fetch asset type that is not a generation history asset');
        }

        if (updateLastAccessed) {
            historyAsset.updateLastAccessed().catch(error => {
                // Log the error but do not fail the entire operation if updating last accessed fails
                this._core._environment.error(`Failed to update last accessed for asset ${assetId}: ${error}`);
            });
        }
        return historyAsset;
    }

    /**
     * Fetches the sister assets for a given Generation History Asset
     * @param asset A Generation History Asset
     * @returns A promise that resolves to an object containing an array of Generation History Assets, sorted by seed in ascending order
     */
    async getGenerationHistorySisterAssets(asset: AdobeAsset): Promise<AdobeAsset[]> {
        if (!isGenerationHistoryAsset(asset)) {
            throw SAMError.create(SAMErrorCode.INVALID_OPERATION, 'Attempting to fetch sister assets for an asset that is not a generation history asset');
        }

        const generationGroupId = getGenerationGroupId(asset);
        // We only want to load the sister list if the asset:
        // - has a generation group ID (i.e. was generated along side other assets)
        // - is owned by the current user (based on storageAssignee, not createdBy)
        // If storageAssignee is unpopulated (empty id), we load siblings (err on side of showing)
        const assigneeId = asset._storageAssignee_NoLazyLoad.id;
        const isNotOwnedByOthers = !assigneeId || assigneeId === this._core._environment.getUserId();
        const shouldLoadSisterList = Boolean(generationGroupId) && isNotOwnedByOthers;

        let sisterAssets: AdobeAsset[];
        const order = this.getGenerationHistoryAssetOrder('ascending', 'seed');

        if (shouldLoadSisterList) {
            const filter = this.getGenerationHistoryAssetFilter({ generationGroupId });
            const sisterList = this.generationHistorySource.getList(order, filter);
            await waitForSisterList(sisterList);
            sisterAssets = sisterList.items;
        } else {
            sisterAssets = [ asset ];
        }

        return sisterAssets;
    }

    get generationHistoryUtils() {
        return { ...generationHistoryUtils, MEDIA_TO_HISTORY_ASSET_TYPE, HISTORY_ASSET_TYPE_TO_MEDIA_TYPE, GENERATION_HISTORY_MEDIA_TYPES };
    }

    /**
     * @experimental
     */
    getGenerationHistoryAssetFilter(options: Partial<SAM.IGenerationHistoryAssetListingOptions>) {
        const params: Partial<IGenerationHistoryFilterParams> = options;
        params.featureFlags = {
            generationHistoryVectors: this._core._environment.getValue('FEATURE_FLAGS')?.['generation-history-vectors'] ?? false,
        };
        params.userId = this._core._environment.getUserId();
        return new GenerationHistoryAssetFilter(params);
    }

    /**
     * @experimental
     */
    getGenerationHistoryAssetOrder(direction: IOrderDirection = 'descending', field: GenerationHistoryAssetOrderField = 'created') {
        return new GenerationHistoryAssetOrder(direction, field);
    }


    /**
     * @param assetId The asset ID of the asset to get the public link for.
     * @returns A promise that resolves to an object containing the public link for the asset and the permission the asset was set to.
     * @experimental This API is still in development.
     */
    async getPublicLink(assetId: string): Promise<PublicLinkResponse> {
        // TODO: [GLOW-1696] Remove this after we remove the link from the PublicLinkResponse
        const link = `https://firefly-stage.corp.adobe.com/open/${assetId}`;
        const ghaAsset = await this.getGenerationHistoryAssetById(assetId);
        const principalCollaborators = await getPrincipalCollaborators(ghaAsset);

        // [GLOW-1512] Early return if the asset previously shared to orgEverybody.
        // This is to prevent the usecase where an org has Sharing restriction limited to the org:
        // When user calls this method again, the code would quickly try to share the link to public (which unshares with `orgEverybody`),
        // fail due to sharing restrictions, and then reshare with `orgEverybody` again. Client code is fine with this, however, there is
        // Invitation Service limitation on this.
        if (principalCollaborators.filter(c => c.id === 'orgEverybody').length > 0) {
            // previously shared to orgEverybody, so return the link right away
            return {
                link,
                permission: 'orgEverybody'
            };
        }

        const updateRequest: UpdateAccessRequest = {
            mode: 'all',
            role: 'viewer',
            canShare: false,
            canComment: true
        };
        let targetPermission: PublicLinkResponse['permission'] = 'all';
        const sharingContext = await this._core.getSharingContext();
        await sharingContext.updateAccess(assetId, updateRequest).then(_throwIfFailedCollaborators).catch(e => {
            // If asset sharing failed due to sharing restrictions by the org (403.1), swallow the error and attempt to share to orgEverybody
            if (e.code === SAMErrorCode.ACCESS_DENIED && e.description === ERROR_MESSAGE_SHARING_RESTRICTION) {
                targetPermission = 'orgEverybody';
                return sharingContext.updateAccess(assetId, { ...updateRequest, mode: 'orgEverybody' }).then(_throwIfFailedCollaborators);
            } else {
                throw e;
            }
        });

        return {
            link, // TODO: [GLOW-1696] Remove this after we remove the link from the PublicLinkResponse
            permission: targetPermission
        };
    }

}

