import type LibraryInterface from '../interface/LibraryInterface';
import type Library from './Library';
import type { IItemLoader, IItemLoaderOptions, ILoadedPage, ILoadNextPage } from '../core/ItemLoader';
import type ItemPool from '../core/ItemPool';
import type ImplicitLibrarySearchFilter from './ImplicitLibrarySearchFilter';
import type { LibraryData, LibrariesResponse, MelvilleLink } from '../interface/LibraryModel';
import type { LibrarySearchConfig } from './LibrarySearchSource';
import type AdobeAsset from '../assets/AdobeAsset';
import type ItemUpdater from '../core/ItemUpdater';
import { LazyLoadManager } from '../core/decorators/LazyLoadManager';
import { STORAGE_ASSIGNEE_CHANGED } from '../assets/AssetEvents';
import type { IExplicitFilter } from '../core/ItemFilter';
import { getMostRecentValidMutation } from '../utils/loaderUtils';

export default class LibrarySearchLoader implements IItemLoader<LibrarySearchConfig> {

    constructor(
        private _libraryPool: ItemPool<Library | AdobeAsset>,
        private _libraryInterface: LibraryInterface,
        private _libraryUpdater: ItemUpdater<Library, Partial<LibraryData>>
    ) {
    }

    supportsFilter(filter?: IExplicitFilter<Library>): boolean {
        return filter !== undefined;
    }

    async loadPage(options: IItemLoaderOptions<LibrarySearchConfig>): Promise<ILoadedPage<LibrarySearchConfig>> {
        return await this._loadPage(options);
    }

    private async _loadPage(options: IItemLoaderOptions<LibrarySearchConfig>, pageLink?: MelvilleLink): Promise<ILoadedPage<LibrarySearchConfig>> {
        const { implicitFilter } = options;
        const { _query } = implicitFilter as ImplicitLibrarySearchFilter;

        // We will ignore the update if we had local changes sooner than this timestamp.
        // This default latency is set to 3 seconds right now. We should revisit this value.
        const latency = this._libraryPool._core._environment.getValue('PROJECTS_LIST_UPDATE_LATENCY');
        const mostRecentValidMutation = getMostRecentValidMutation(options.resource, latency);

        let result: LibrariesResponse;
        if (pageLink) {
            if (options.loadOptions?.limit) {
                // replace the limit value in the URL with the provided limit value from the options.
                pageLink.href = pageLink.href.replace(/limit=[0-9]*/, `limit=${options.loadOptions.limit}`);
            }
            result = await this._libraryInterface.searchLibrariesWithLink(_query, pageLink);
        } else {
            result = await this._libraryInterface.searchLibraries(_query);
        }

        const session = this._libraryPool.createLoaderUpdateSession<Library>(mostRecentValidMutation);
        const items = this._libraryUpdater.updateRemoteItems(session, result.libraries ?? []);
        for (const item of items) {
            LazyLoadManager.updatedByItemUpdater(item, STORAGE_ASSIGNEE_CHANGED);
        }
        session.commit();

        // Check if we have another page to load.
        let loadNextPage: ILoadNextPage<LibrarySearchConfig> | undefined;
        const nextPageLink = result._links?.next;
        if (nextPageLink) {
            loadNextPage = (options: IItemLoaderOptions<LibrarySearchConfig>) =>
                this._loadPage(options, nextPageLink);
        }
        implicitFilter!._matchingIDsFromSearch = new Set([
            // copy existing, if needed
            ...(implicitFilter!._matchingIDsFromSearch || []),
            ...(items.map(item => item.id)) ]);

        return {
            items,
            total: result.total_count,
            loadNextPage,
            mostRecentValidMutation
        };
    }
}
