import InterfaceBase from './InterfaceBase';
import {
    updateAssetTypeForUSS
} from './USSUtils';
import type { UploadedFromType } from '../assets/USSAdobeAssetFilter';
import {
    excludeExpressArtifacts,
    type ISearchQueryEntryFilter,
    type USSResponse,
    USSv3FilterField,
    USSv3Function,
    USSv3OrderDir,
    USSv3OrderField
} from './USSv3Model';
import type { ValueOf } from '../core/ObjectUtils';

export interface AssetsListingSearchOptions {
    limit: number;
    start?: number;
    mediaTypes?: string[];
    excludeMediaTypes?: string[];
    query?: string;
    deepSearch?: boolean;
    assetId?: string;
    embedPermissions?: boolean;
    userId?: string;
    uploadedFrom?: UploadedFromType;
    orderBy: ValueOf<typeof USSv3OrderField>;
    orderDirection: USSv3OrderDir;
}

const DefaultAssetsListingSearchOptions: AssetsListingSearchOptions = {
    orderDirection: USSv3OrderDir.Descending,
    orderBy: USSv3OrderField.Modified,
    start: 0,
    limit: 0
};

export default class AdobeAssetSearchInterface extends InterfaceBase {

    async getFilteredAssets(options?: Partial<AssetsListingSearchOptions>): Promise<USSResponse> {
        options = { ...DefaultAssetsListingSearchOptions, ...options };
        updateAssetTypeForUSS(options.mediaTypes);
        updateAssetTypeForUSS(options.excludeMediaTypes);
        const filters: ISearchQueryEntryFilter[] = [
            { [USSv3Function.NOT]: {
                funcParams: {
                    [USSv3FilterField.SHELL_VISIBILITY]: [ 'hiddenSelf', 'hiddenRecursive' ],
                    // USS v3 new endpoint does not match on empty array
                    ...(options.excludeMediaTypes?.length ? { [USSv3FilterField.MEDIA_TYPE]: options.excludeMediaTypes } : {}),
                }
            } }
        ];

        if (options.mediaTypes?.length) {
            // USS v3 new endpoint does not match on empty array
            filters.push({ [USSv3FilterField.MEDIA_TYPE]: options.mediaTypes });
        }

        if (options.deepSearch) {
            filters.push({ [USSv3FilterField.REPO_ANCESTORS]: options.assetId });
        } else {
            filters.push({ [USSv3FilterField.PARENT_ID]: options.assetId });
        }

        const userId = options.userId;
        const uploadedFrom = options.uploadedFrom;

        if (userId) {
            filters.push({ [USSv3FilterField.STORAGE_ASSIGNEE_ID]: userId });
        }
        if (uploadedFrom) {
            filters.push({ [USSv3FilterField.CREATED_FROM_UPLOAD]: true });
            if (uploadedFrom !== 'ALL') {
                filters.push({ [USSv3FilterField.CREATED_BY_CLIENT_ID]: uploadedFrom });
            }
        }

        // SAMJS-773
        filters.push(excludeExpressArtifacts());

        return await this._core.hostAssetContext.__ussInterfaceV3.getQueryResponse({
            start: options.start!,
            sorts: [ { sortOrderBy: options.orderBy!, sortOrder: options.orderDirection! } ],
            limit: options.limit!,
            ...(options.query ? { textQuery: options.query } : {}),
            filters
        });
    }
}
