import type { SAM } from '@ccx-public/component-types';
import { observable } from '../core/decorators';
import type { AdobeAssetUpdaterMetadata } from '../assets/AdobeAsset';
import AdobeAsset from '../assets/AdobeAsset';
import PropertyUpdater from '../core/PropertyUpdater';
import ItemUpdater from '../core/ItemUpdater';
import type { IPatchStudentAssignmentFileData, IRemoteStudentAssignmentFileMetadataWithComputedValues } from '../interface/StudentAssignmentFileModel';
import type { Tutorial } from '../interface/TutorialModel';
import type { IItemSourceConfig } from '../core/ItemList';
import StudentAssignmentFileAppMetadataResource from './StudentAssignmentFileAppMetadataResource';
import type ISAMCorePrivate from '../core/ISAMCorePrivate';
import type { AssetLinks } from '../interface/RepositoryModel';
import { AssetClassChoices } from '../interface/RepositoryModel';
import type { LinkReference } from '../links/AssetLink';

export type StudentAssignmentFileConfig = IItemSourceConfig<StudentAssignmentFile>;

/**
 * Represents a file that is part of a student assignment.
 */
export default class StudentAssignmentFile extends AdobeAsset implements SAM.StudentAssignmentFile {
    private _studentAssignmentId: string = '';
    private _parentAssignmentId: string = '';
    private _parentClassroomId: string = '';
    /**
     * @TODO_Deprecation will be marked as deprecated once all SAM clients
     * have migrated over to linking using sourceAsset.
     */
    private _sourceAssets: string[] = [];
    private _sourceAsset?: LinkReference;
    private _sourceTasks: string[] = [];
    private _sourceTutorials: Partial<Tutorial>[] = [];
    private _studentAssignmentFileAppMetadata: StudentAssignmentFileAppMetadataResource;

    constructor(
        readonly _core: ISAMCorePrivate,
        id: string,
        metadata?: {
            links?: AssetLinks;
        }
    ) {
        super(_core, id, metadata);
        this._studentAssignmentFileAppMetadata = new StudentAssignmentFileAppMetadataResource(_core, this);
        this._needsRepoMetadata = true;
    }

    @observable
    get isChildOfStudentAssignment(): boolean {
        return true;
    }

    @observable
    get studentAssignmentId(): string {
        return this._studentAssignmentId;
    }

    /**
     * Overrides AdobeAsset instance of parentStudentAssignmentId.
     * Equivalent to studentAssignmentId.
     * */
    @observable
    get parentStudentAssignmentId(): string {
        return this._studentAssignmentId || super.parentStudentAssignmentId || '';
    }

    /**
     * Overrides AdobeAsset instance of parentAssignmentID.
     * */
    @observable
    get parentAssignmentID(): string {
        return this._parentAssignmentId || super.parentAssignmentID || '';
    }

    /**
     * Overrides AdobeAsset instance of isChildOfAssignment.
     * */
    @observable
    get isChildOfAssignment(): boolean {
        return true;
    }

    /**
     * Overrides AdobeAsset instance of isChildOfClassroom.
     * */
    @observable
    get isChildOfClassroom(): boolean {
        return true;
    }

    /**
     * Overrides AdobeAsset instance of parentClassroomId.
     * */
    @observable
    get parentClassroomId(): string | undefined {
        return this._parentClassroomId  || super.parentClassroomId;
    }

    /**
     * Overrides AdobeAsset instance of isChildOfAssignmentMaterials.
     * */
    @observable
    get isChildOfAssignmentMaterials(): boolean {
        return false;
    }

    /**
     * A link to the asset that this file was copied from.
     * Undefined if sourceAssets is set instead OR if this file
     * was NOT copied from an asset
     */
    @observable
    get sourceAsset(): LinkReference | undefined {
        return this._sourceAsset;
    }

    /**
     * Use sourceAsset over sourceAssets if sourceAsset is defined
     * to access the link to the file's source asset.
     *
     * @TODO_Deprecation will be marked as deprecated once all SAM clients
     * have migrated over to linking using sourceAsset.
     */
    @observable
    get sourceAssets(): string[] | undefined {
        return this._sourceAssets;
    }

    @observable
    get sourceTasks(): string[] | undefined {
        return this._sourceTasks;
    }

    @observable
    get sourceTutorials(): Partial<Tutorial>[] | undefined {
        return this._sourceTutorials;
    }

    @observable
    get appMetadata(): StudentAssignmentFileAppMetadataResource {
        return this._studentAssignmentFileAppMetadata;
    }

    /**
     * Updates a StudentAssignmentFile with new metadata.
     *
     * @throws {Error} Incorrect parameters: sourceAsset, sourceTasks, or sourceTutorials parameter required
     *
     * @example <caption>Update a StudentAssignmentFile's sourceAsset</caption>
     * await studentAssignmentFile.update({ sourceAsset: {'repo:assetId': 'urn:mock-id'} });
     */
    async update({ sourceAsset, sourceAssets, sourceTasks, sourceTutorials }: IPatchStudentAssignmentFileData): Promise<StudentAssignmentFile> {
        if (!sourceAsset && !sourceAssets && !sourceTasks && !sourceTutorials) {
            throw Error('Incorrect parameters: sourceAsset, sourceTasks, or sourceTutorials parameter required');
        }

        await this._core.classroomContext.updateStudentAssignmentFile(
            this,
            {
                sourceAsset,
                sourceAssets,
                sourceTasks,
                sourceTutorials
            },
        );

        return this;
    }
}

export const StudentAssignmentFileUpdater = new ItemUpdater<StudentAssignmentFile, Partial<IRemoteStudentAssignmentFileMetadataWithComputedValues | AdobeAssetUpdaterMetadata>>({
    localItemType: StudentAssignmentFile,
    remoteIdProperty: 'repo:assetId',
    propertyUpdater: new PropertyUpdater({
        _repositoryID: 'repo:repositoryId',
        _name: 'repo:name',
        _path: 'repo:path',
        _type: 'dc:format',
        _assetClass: { name: 'repo:assetClass', choices: AssetClassChoices },
        _created: { name: 'repo:createDate', format: 'date' },
        _modified: { name: 'repo:modifyDate', format: 'date' },
        _createdBy: 'repo:createdBy',
        _modifiedBy: 'repo:modifiedBy',
        __links: { name: '_links', format: 'object' },
        _parentAssignmentId: { name: 'computedAssignmentId', format: 'string' },
        _parentClassroomId: { name: 'computedClassroomAssetId', format: 'string' },
        _studentAssignmentId: { name: 'computedStudentAssignmentId', format: 'string' },
        _sourceAsset: { name: 'assignment:sourceAsset', format: 'object' },
        /**
         * @TODO_Deprecation will be marked as deprecated once all SAM clients
         * have migrated over to linking using sourceAsset.
         */
        _sourceAssets: { isArray: true, name: 'assignment:sourceAssets', format: 'string' },
        _sourceTasks: { isArray: true, name: 'assignment:sourceTasks', format: 'string' },
        _sourceTutorials: { isArray: true, name: 'assignment:sourceTutorials', format: 'object' },
    })
});
