import type Classroom from './Classroom';
import type { IExplicitFilter, ItemFilterRelation } from '../core/ItemFilter';
import { ClassroomProfiles, type IClassroomFilterOptions } from '../interface/ClassroomModel';

/**
 * A filter for classrooms
 *
 * Example usage:
 * - To get classrooms for the current profile (default): new ClassroomFilter()
 * - To get classrooms across all profiles: new ClassroomFilter({ profiles: 'ALL' })
 * - To get classrooms for a specific profile: new ClassroomFilter({ profiles: 'profileId' })
 * - To get classrooms with lastAccessed: new ClassroomFilter({ hasLastAccessed: true })
 */
export default class ClassroomFilter implements IExplicitFilter<Classroom> {
    public profiles?: string | ClassroomProfiles;
    public hasLastAccessed?: boolean;
    public hasTeachers: boolean = false;
    private currentUserId?: string;

    constructor(options: Partial<IClassroomFilterOptions> = {}) {
        this.profiles = options.profiles;
        this.currentUserId = options.currentUserId;
        this.hasLastAccessed = options.hasLastAccessed;
        this.hasTeachers = options.hasTeachers ?? false;
    }

    // Need to check for 3 profiles cases (ALL, specific profile, and undefined)
    // And if lastAccessDate is true, we match if the classroom has a lastAccessDate
    matches(item: Classroom): boolean {
        if (this.hasLastAccessed && !item.lastAccessed) {
            return false;
        }


        const classroomUserId = item.membership?.userId;
        if (this.profiles && this.profiles !== ClassroomProfiles.ALL && this.profiles !== classroomUserId) {
            return false;
        }

        if (!this.profiles && classroomUserId && classroomUserId !== this.currentUserId) {
            return false;
        }

        // If this.hasTeachers and item does not have cached teachers, teachers can still be lazy
        // loaded therefore can be part of the list that surfaces teacher info
        return true;
    }

    /**
     * This method determines the commonality between the already present filter (other)
     * and the new filter to be applied (this). The point of this is to
     * see if the new filter (this) can build some, all, or none of it's items
     * from (other) filter.
     *
     * Subset: Means that ALL items for this filter can be built from other
     * Disjoint: No items for this filter can be built from other.
     * Unknown: Some items for this filter can be built from other.
     *
     * @note we should always determine disjoint cases first before other cases.
     * @note this = NEW FILTER, other = EXISTING FILTER
     *
     * @param other The existing filter that we are getting the relation to.
     * @returns { ItemFilterRelation }
     */
    getRelationToFilter(other: ClassroomFilter): ItemFilterRelation {
        // If this filter is showing all classrooms and other is showing only recents, this is disjoint
        if (this.hasLastAccessed !== other.hasLastAccessed) {
            return 'disjoint';
        }

        // If this filter is "ALL" and other is not, we cannot build from other
        if (this.profiles === ClassroomProfiles.ALL && other.profiles !== ClassroomProfiles.ALL) {
            return 'disjoint';
        }

        // If both filters don't match, and other is not "ALL", relation is disjoint (two disparate filters)
        if (this.profiles !== other.profiles && other.profiles !== ClassroomProfiles.ALL) {
            return 'disjoint';
        }

        // To encourage fetching teachers for the whole list once, instead of individual
        // API calls to get teachers for each class
        if (this.hasTeachers && !other.hasTeachers) {
            return 'disjoint';
        }

        return 'subset';
    }

    get hash(): string {
        return `profiles=${this.profiles ?? this.currentUserId}?hasLastAccessed=${this.hasLastAccessed ? 'true' : 'false'}&hasTeachers=${this.hasTeachers ? 'true' : 'false'}`;
    }
}
