import type StudentAssignmentsInterface from '../interface/StudentAssignmentsInterface';
import type { IItemLoader, IItemLoaderOptions, ILoadedPage } from '../core/ItemLoader';
import type StudentAssignment from './StudentAssignment';
import { StudentAssignmentUpdater } from './StudentAssignment';
import type { StudentAssignmentConfig } from './StudentAssignmentSource';
import type { IRemoteStudentAssignment, IStudentAssignmentResponse } from '../interface/StudentAssignmentModel';
import type AdobeAsset from '../assets/AdobeAsset';
import type { ISAMCorePrivate } from '../indexPrivate';

export default class StudentAssignmentListLoader implements IItemLoader<StudentAssignmentConfig> {
    constructor(private _StudentAssignmentsInterface: StudentAssignmentsInterface, private _core: ISAMCorePrivate) {}

    async loadPage(options: IItemLoaderOptions<StudentAssignmentConfig>): Promise<ILoadedPage<StudentAssignmentConfig>> {
        return await this._loadPage(options);
    }

    /**
     * Fetch and observe the students folder to track when its children NOT_STARTED Student assignments are changed to IN_PROGRESS ones.
     * @param studentsMetadata - metadata of the students folder
     * @returns promise that resolves to students adobe asset instance
     */
    private async observeStudentsFolder({ remoteStudentAssignments }: { remoteStudentAssignments: IRemoteStudentAssignment[] }): Promise<AdobeAsset> {
        // Every remote student assignment has the same students asset id
        const firstRemoteStudentAssignment = remoteStudentAssignments[0];
        const studentsAssetId = firstRemoteStudentAssignment['classroom:context']['assignment:studentsContext']['assignment:studentsAssetId'];
        // Maintain a full-weight adobe asset representation of the students folder as of now since other client can request one of its attributes.
        // This ticket [ACPCEDU-2563] will try to optimize this.
        return this._core.hostAssetContext.getAssetWithCloudID(studentsAssetId);
    }

    /** @note api does not support pagination */
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    private async _loadPage(options: IItemLoaderOptions<StudentAssignmentConfig>, start?: number): Promise<ILoadedPage<StudentAssignmentConfig>> {
        const { filter: explicitFilter, implicitFilter } = options;
        /**
         * Filter scenarios:
         *
         * From Assignment.getStudentAssignments() or ClassroomContext.getStudentAssignments():
         * implicitFilter = ImplicitStudentAssignmentFilter({assignmentId OR assignmentCode})
         * explicitFilter = StudentAssignmentFilter | EverythingFilter
         */

        const { loadDocuments } = explicitFilter;
        const { assignmentId, assignmentCode } = implicitFilter;

        let studentAssignments: StudentAssignment[] = [];

        const result: IStudentAssignmentResponse = await this._StudentAssignmentsInterface.getStudentAssignments({
            assignmentCode, assignmentId, loadDocuments });
        const remoteStudentAssignments: IRemoteStudentAssignment[] = result.children;

        const session = this._core._getAssetPool().createUpdateSession<StudentAssignment>();

        // Add computedAssignmentCode to each remote student assignment if present
        const studentAssignmentsWithCode = assignmentCode ? remoteStudentAssignments.map(sa => (
            {
                ...sa,
                'computedAssignmentCode': assignmentCode,
            }
        )) : remoteStudentAssignments;

        studentAssignments = StudentAssignmentUpdater.updateRemoteItems(session, studentAssignmentsWithCode);
        session.commit();

        if (loadDocuments) {
            for (const studentAssignment of studentAssignments) {
                // Since we are preloading the files before there is a StudentAssignment object to associate them with,
                // the SA and it's files may need to be linked up later by the file loader.
                studentAssignment._hasLoadedChildren = true;
            }
        }

        // No need to await, let this happen in parallel because we don't really care if it ends up failing
        // this is a nice-to-have for an ideal real-time experience for user, but is not needed by
        // the user at this moment so do not impact the performance of the current workflow
        // If there's no student assignments, which means we don't have students assigned to this assignment, we don't need to observe the students folder
        if (remoteStudentAssignments.length > 0) {
            this.observeStudentsFolder({ remoteStudentAssignments }).then((folder) => {
                // pin this to memory so Garbage Collector does not remove it as long as the list is still kept in memory
                implicitFilter._monitoredFolder = folder;
            });
        }

        return {
            items: studentAssignments,
            total: studentAssignments.length,
            loadNextPage: undefined,
        };
    }
}
