export type IsEqualFn = (a: any, b: any) => boolean;
export type ValueOf<T> = T[keyof T];

export function isStrictEqual(a: any, b: any) {
    return a === b;
}

export function deepClone(value: any) {
    return JSON.parse(JSON.stringify(value));
}

/**
 * Compares two items, including all their iterable properties, and all their nested properties.
 *
 * @note isDeepEqual(a, b) is O(n)
 * @note isDeepEqual(a, b, true) is O(n log n)
 * @note isDeepEqual(a, b, false, true) is O(n^2) -- use sparingly!
 * @note isDeepEqual(a, b, true, true) is O(n^3) -- use sparingly!
 *
 * @param {any} a is compared to b
 * @param {any} b is compared to a
 * @param {boolean} ignoreArrayOrder (optional) when true, order of arrays does not matter.
 * @param {boolean} partialMatch (optional) when true, all properties of `a` must match `b`, but `b`
 *      can contain additional properties not in `a`.
 * @return {boolean} true if they match
 */
export function isDeepEqual(a: any, b: any, ignoreArrayOrder: boolean = false, partialMatch: boolean = false): boolean {
    if (a === b) {
        return true;
    }

    // typeof null is 'object' but null.constructor is undefined
    if (a === null || b === null) {
        return false;
    }

    if (typeof a !== typeof b || a.constructor !== b.constructor) {
        return false;
    }

    if (a instanceof Date) {
        return a.toISOString() === b.toISOString();
    }

    if (Array.isArray(a)) {
        if (!partialMatch && a.length !== b.length) {
            return false;
        }
        if (partialMatch && a.length > b.length) {
            return false;
        }

        let arry1: any[] = a;
        let arry2: any[] = b;
        if (ignoreArrayOrder) {
            // copy array to avoid mutating the original arrays
            // .slice(0) is fastest, even faster than .slice()
            // Note: this only works on sortable values (not Maps, Sets, Objects, or Arrays)
            arry1 = a.slice(0).sort();
            arry2 = b.slice(0).sort();
        }

        let i: number = 0;
        let j: number = 0;
        for (;;) {
            // we've matched everything in a
            if (i === arry1.length) { return true; }

            // we've run out of b before matching everything in a
            if (j === arry2.length) {
                return false;
            }

            if (isDeepEqual(arry1[i], arry2[j], ignoreArrayOrder, partialMatch)) {
                // advance our index in a and b after a match
                i = i + 1;
                j = j + 1;

                continue;
            }

            if (partialMatch) {
                // advance our index in b, and try again
                j = j + 1;

                continue;
            }

            // when not partialMatch, the first mismatch is a failure to match.
            return false;
        }
    }

    if (a instanceof Set) {
        if (!partialMatch && a.size !== b.size) {
            return false;
        }
        if (partialMatch && a.size > b.size) {
            return false;
        }
        // Note: only works for strings/numbers/booleans, not objects
        for (const key of a.keys()) {
            if (!b.has(key)) {
                return false;
            }
        }
        return true;
    }

    if (a instanceof Map) {
        if (!partialMatch && a.size !== b.size) {
            return false;
        }
        if (partialMatch && a.size > b.size) {
            return false;
        }
        for (const key of a.keys()) {
            if (!b.has(key)) {
                return false;
            }
            if (!isDeepEqual(a.get(key), b.get(key), ignoreArrayOrder, partialMatch)) {
                return false;
            }
        }
        return true;
    }

    if (typeof a === 'object') {
        const keysA = new Set(Object.keys(a));
        const keysB = new Set(Object.keys(b));
        if (!partialMatch && keysA.size !== keysB.size) {
            return false;
        }
        if (partialMatch && keysA.size > keysB.size) {
            return false;
        }
        for (const key of keysA) {
            if (!keysB.has(key)) {
                return false;
            }
            if (!isDeepEqual(a[key], b[key], ignoreArrayOrder, partialMatch)) {
                return false;
            }
        }
        return true;
    }

    // We don't support other types.
    return false;
}

export const secondsPerHour = 60 * 60;

export const millisecondsPerHour = secondsPerHour * 1000;

export function firstInSet<T>(s?: Set<T>): T | undefined {
    if (s?.size) {
        return s.entries().next().value![0];
    }
}
