import { observable } from '../core/decorators';
import ShareableItem from '../collaboration/ShareableItem';
import type { IProjectsCreateData, IProjectsTeam, IProjectsTeamLinks, IProjectsTeamState } from '../interface/WorkspacesModel';
import PropertyUpdater from '../core/PropertyUpdater';
import ItemUpdater from '../core/ItemUpdater';
import type { CollaboratorRole } from '../collaboration/Collaborator';
import { CollaboratorRoles } from '../collaboration/Collaborator';
import type Space from './Space';
import type { ITeamUpdate } from './SpaceContext';
import oneTimeWarning from '../utils/oneTimeWarning';

export type RepositoryOwnerType =
    | 'org'
    | 'user';

const RepositoryOwnerTypes: RepositoryOwnerType[]  = [ 'org', 'user' ];

export type TeamState = IProjectsTeamState;
const TeamStates: TeamState[] = [ 'active', 'discarded' ];

/**
 * Represents the notion of a "team" of Adobe account
 * holders that collaborate on projects.
 *
 * @example
 * // Instatiate list and load contents
 * const teamsList = core.spaceContext.getTeams().getList(...options);
 * await waitForListLoad(teamsList);
 *
 * // Get the first team in the list as an example.
 * const team = teamsList.items[0];
 *
 * // Perform some actions on a team.
 * await team.rename('newName');
 * await team.archive();
 * await team.restore();
 *
 * // log the teamID
 * console.log(team.teamID)
 *
 */
export default class Team extends ShareableItem {

    private _created: Date = new Date();
    private _createdBy: string = '';
    private _description?: string;
    private _name: string = '';
    private _repositoryID: string = '';
    private _repositoryName: string = '';
    private _repositoryOwnerID: string | undefined;
    private _repositoryOwnerEmail: string | undefined;
    private _repositoryOwnerType: RepositoryOwnerType | undefined;
    private _state: TeamState = 'active';
    private _role: CollaboratorRole = 'none';
    private __links: IProjectsTeamLinks | undefined;

    /**
     * The unique id that represents the team.
     */
    get teamID(): string {
        return this.id;
    }

    @observable
    get created(): Date {
        return this._created;
    }

    @observable
    get createdBy(): string {
        return this._createdBy;
    }

    /**
     * The user-visible name assigned to the team
     */
    @observable
    get name(): string {
        return this._name;
    }

    /**
     * The description property of this team.
     *
     * @note Only available after a call to ensureDescription()
     */
    @observable
    get description(): string | undefined {
        return this._description;
    }

    /**
     * The unique id of the repository that owns this team
     */
    @observable
    get repositoryID(): string {
        return this._repositoryID;
    }

    /**
     * The user-visible name of the repository (i.e. the organization name)
     * that owns this team
     */
    @observable
    get repositoryName(): string {
        return this._repositoryName;
    }

    @observable
    get repositoryOwnerID(): string | undefined {
        return this._repositoryOwnerID;
    }

    @observable
    get repositoryOwnerEmail(): string | undefined {
        return this._repositoryOwnerEmail;
    }

    @observable
    get repositoryOwnerType(): RepositoryOwnerType | undefined {
        return this._repositoryOwnerType;
    }

    /**
     * The role or permissions of the user for this team.
     * 'editor' and 'owner' are combined for backward
     * compatibility.
     * @deprecated Use 'role' instead.
     */
    @observable
    get collaboratorRole(): CollaboratorRole {
        oneTimeWarning(
            'collaboratorRoleDeprecated',
            'The property collaboratorRole has been depecrated in favor of role.'
        );
        return this._role === 'owner'
            ? 'editor' : this._role;
    }

    /**
     * The role or permissions of the user for this team.
     * can be any of the following values: 'editor', 'viewer'
     * 'owner'.
     *
     * @note The 'viewer' role is not set in any workflow currently.
     */
    @observable
    get role(): CollaboratorRole {
        return this._role;
    }

    @observable
    get state(): TeamState {
        return this._state;
    }

    /**
     * The links provided by the service for this team.
     *
     * @private
     */
    @observable
    get _links(): IProjectsTeamLinks | undefined {
        return this.__links;
    }

    /**
     * Archive/Discard team
     *
     * @NOTE Currently there are some inconsistencies in how the API's are
     * named within Projects
     * Team API uses “discarded”, Project API uses “archived”
     */
    async archive(): Promise<void> {
        await this._core.spaceContext.archiveTeam(this);
    }

    /**
     * Create a space for this team.
     *
     * @param data {IProjectsCreateData}
     */
    async createSpace(data: IProjectsCreateData): Promise<Space> {
        return await this._core.spaceContext.createSpace(this, data);
    }

    /**
     * Permanently Delete a Team that has already been discarded.
     *
     */
    async permanentlyDelete(): Promise<void> {
        await this._core.spaceContext.permanentlyDeleteTeam(this);
    }

    /**
     * Rename this Team.
     *
     * @param newName
     */
    async rename(newName: string): Promise<void> {
        await this._core.spaceContext.renameTeam(this, newName);
    }

    /**
     * Restore this Team
     */
    async restore(): Promise<void> {
        await this._core.spaceContext.restoreTeam(this);
    }

    /**
     * Update properties on this team
     */
    async update(data: ITeamUpdate): Promise<void> {
        await this._core.spaceContext.updateTeam(this, data);
    }

    /**
     * Ensures the description is loaded and available
     * on a team.
     */
    async ensureDescription(): Promise<void> {
        await this._core.spaceContext.loadTeamProperties(this);
    }
}

export const TeamUpdater = new ItemUpdater<Team, Partial<IProjectsTeam>>({
    localItemType: Team,
    remoteIdProperty: 'id',
    propertyUpdater: new PropertyUpdater({
        '_created': { name: 'createDate', format: 'date' },
        '_createdBy': 'createdBy',
        '_description': 'description',
        '_name': 'name',
        '_repositoryID': 'repositoryId',
        '_repositoryName': 'repositoryName',
        '_repositoryOwnerID': 'repositoryOwner.id',
        '_repositoryOwnerEmail': 'repositoryOwner.email',
        '_repositoryOwnerType': { name: 'repositoryOwner.type', choices: RepositoryOwnerTypes },
        '_role': { name: 'role', choices: CollaboratorRoles },
        '_state': { name: 'state', choices: TeamStates },
        '__links': { name: '_links', format: 'object' }
    })
});
