import { SAM } from '@ccx-public/component-types';
import type { ClassroomMemberRole, IClassroomMember } from './ClassroomMemberModel';
import type { RequiredStudentAssignmentFilterOptions } from './StudentAssignmentModel';
import type { CreateBoardOptions } from './BoardModel';

export interface IEntityRef {
    authSrc: string;
    ident: string;
}
export type IUserProfile =
    Pick<IClassroomMember, 'userId' | 'firstName' | 'lastName' | 'email'>
    & Partial<Pick<IClassroomMember, 'displayName' | 'role' | 'membershipStatus' | 'inviteSource'>>;

export enum LearningManagementSystems {
    GC = 'GC', // GC is Google Classroom
}

export enum LearningManagementSystemRoles {
    STUDENT = 'STUDENT',
    TEACHER = 'TEACHER',
}

export enum RosterImportState {
    BLOCKED = 'BLOCKED',
    INVITED = 'INVITED',
    JOINED = 'JOINED',
    NOT_ENROLLED = 'NOT_ENROLLED',
    REMOVED = 'REMOVED',
}

export enum ImportSourceType {
    CLEVER = 'clever',
    CLASS_LINK = 'classlink',
}

export enum ClassroomStatus {
    ACTIVE = 'ACTIVE',
    ARCHIVED = 'ARCHIVED',
}

export type ClassroomType = SAM.ClassroomType;
// eslint-disable-next-line @typescript-eslint/no-redeclare
export const ClassroomType = SAM.ClassroomType;

export interface IRemoteImportSource {
    /** The ImportSource's ID of the classroom */
    source?: ImportSourceType;
    /** The type of import source, e.g., 'clever', 'classlink' */
    sourceId?: string;
    /** The date when the classroom was last synced with the import source */
    lastUpdatedAt?: string;
}

export interface IImportSource {
    /**
     * The ImportSource's ID of the classroom
     * Maps to the remote importedFrom.sourceId
     * */
    id?: string;
    /**
     * The type of import source, e.g., 'clever', 'classlink'
     * Maps to the remote importedFrom.source
     * */
    type?: ImportSourceType;
    /**
     * The date when the classroom was last synced with the import source
     * Maps to the remote importedFrom.lastUpdatedAt
     * */
    synced?: Date;
}

export interface IRosterEntry {
    adobeId: string;
    courseId: string;
    emailID: string;
    firstName: string;
    lastName: string;
    lmsRole: LearningManagementSystemRoles;
    rosterImportState: RosterImportState[];
    sourceLms: LearningManagementSystems;
    userId: string;
}

export enum SubjectTypes {
    noSubject = '',
    allsubjects = 'allsubjects',
    careersTechnicalEducation = 'careersTechnicalEducation',
    computerScience = 'computerScience',
    english = 'english',
    math = 'math',
    otherLanguages = 'otherLanguages',
    others = 'others',
    science = 'science',
    socialStudies = 'socialStudies',
    visualPerformingArts = 'visualPerformingArts',
}

export interface IClassroomCreateData {
    // Can be undefined if the classroom is being created from a virtual class
    name?: string;
    // Defined if the classroom is being created from a virtual class
    id?: string;
    subject?: SubjectTypes;
    grades?: string[];
    period?: string;
    // Defined if the classroom is created or updated with co-teachers
    teachers?: string[];
}

export interface IClassroomUpdateData extends Partial<IClassroomCreateData> {}

export enum ClassroomRole {
    STUDENT = 'STUDENT',
    TEACHER = 'TEACHER',
}

export interface IRemoteClassroom {
    /**
     * The asset ID of the classroom.
     */
    assetId: string;
    /**
     * The class code for the classroom.  Used for generating invite links and LMS integration.
     * @example '3R9RPQ'
     */
    classCode: string;
    /**
     * The unique id that represents the classroom.
     * @example 'EFBF1A3F6567A3180A494138@AdobeOrg'
     */
    classId: string;
    /**
     * The name of the classroom.
     */
    className: string;
    /**
     * Username for the account that created this classroom.
     */
    createdBy: string;
    /**
     * The unix time the classroom was created. Note that it is in seconds and not milliseconds.
     */
    createdOn: number;
    entityRef: IEntityRef;
    /**
     * Indicates if the classroom has been deleted.
     */
    deleted: boolean;
    /**
     * The list of grades associated with the classroom.
     * @example [ 'K', '1' ]
     */
    grades: string[];
    importedFrom?: IRemoteImportSource;
    /**
     * Contains the role of the member fetching the classroom.
     */
    memberRole: ClassroomMemberRole;
    /**
     * The period of the classroom.
     * @example '1'
     */
    period: string;
    /** True if the classroom is a virtual classroom */
    isVirtual?: boolean;
    /**
     * The class status
     * @example 'ACTIVE'
     */
    status: ClassroomStatus;
    /**
     * The class subject.
     * @example 'math'
     */
    subject: SubjectTypes;
    /**
     * The list of members for the classroom.
     */
    members?: IUserProfile[];
    /**
     * The class type
     * @example 'UNRESTRICTED'
     */
    type: ClassroomType;
    /**
     * The current user in this classroom.
     */
    user?: IUserProfile;
    /**
     * For SAM.js internal use only
     * Due to the classroom ID changing when the classroom is migrated
     * from a virtual to a real class, clients will NOT have access to
     * the new instance of the classroom through their existing reference
     * to the original virtual instance of the class.
     *
     * To support classroom workflow reattempts directly following the migration
     * of the virtual class when the client is still referencing the class
     * ID when it was virtual, the virtual instance of the class ID will persist
     * on this session's migrated instance of the class.
     */
    virtualId?: string;
    /**
     * The last time this classroom was accessed by the current user (ISO string)
     * Example: 2023-03-10T19:27:23.094Z
     */
    lastAccessDate?: string;
}

export interface IRemoteBlockOrRemoveResponse {
    apiSuccessResponse: BlockApiSuccessResponses;
    httpStatus: string;
}

export interface IRemoteMembership {
    role: ClassroomMemberRole;
    status: MembershipStatus;
}

export enum BlockApiSuccessResponses {
    REMOVE_STUDENT_SUCCESS = 'REMOVE_STUDENT_SUCCESS',
    BLOCK_STUDENT_SUCCESS = 'BLOCK_STUDENT_SUCCESS',
    UNBLOCK_STUDENT_SUCCESS = 'UNBLOCK_STUDENT_SUCCESS',
    DELETE_DOMAIN_MAPPING_ACCEPTED = 'DELETE_DOMAIN_MAPPING_ACCEPTED',
}

export enum MembershipStatus {
    OWNER = 'OWNER',
    ACTIVE = 'ACTIVE',
    INACTIVE = 'INACTIVE',
    INVITED = 'INVITED',
    IN_REVIEW = 'IN_REVIEW',
    DECLINED = 'DECLINED',
    NOT_A_MEMBER = 'NOT_A_MEMBER',
}

export enum CoTeacherEligibilityStatus {
    ALLOWED = 'ALLOWED',
    NOT_ALLOWED = 'NOT_ALLOWED'
}

export enum CoTeacherIneligibilityReason {
    ACCOUNT_NOT_FOUND = 'ACCOUNT_NOT_FOUND',
    STUDENT_IN_CLASSROOM = 'STUDENT_IN_CLASSROOM',
    TEACHER_IN_CLASSROOM = 'TEACHER_IN_CLASSROOM'
}

export interface ICoTeacherEligibilityEntry {
    email?: string;
    userId?: string;
    status: CoTeacherEligibilityStatus;
    reason?: CoTeacherIneligibilityReason;
}

export interface ICheckCoTeacherEligibilityOptions {
    emails: string[];
    classroomId?: string;
}

export type GetClassroomBoardsOptions = (
    {classroomCode?: never; classroomId: string;}
    | { classroomCode: string; classroomId?: never}
);

export type ValidateClassroomBoardNameForCreateOptions = Partial<GetClassroomBoardsOptions> & {
    /** The name of the classroom board to validate */
    name: string;
}

export type ValidateClassroomBoardNameForUpdateOptions = GetClassroomBoardsOptions & {
    /** The ID of the classroom board */
    boardId: string;
    /** The name of the classroom board to validate */
    name: string;
}

export type GetAssignmentBoardsOptions = RequiredStudentAssignmentFilterOptions;

export type CreateClassroomBoardOptions = Pick<CreateBoardOptions, 'name' | 'description' | 'posts' | 'theme' | 'areNewCommentsAllowed'> & GetClassroomBoardsOptions;

export type CopyBoardToClassroomOptions = GetClassroomBoardsOptions & {
    /** The ID of the board to copy */
    boardId: string;
    /**
     * New name for the copied board. If not provided, the original board's name is used.
     * @experimental Updated payload to support renamed boards is in progress
     * (available 2/12/2026, see https://jira.corp.adobe.com/browse/ACPCEDU-6480).
     */
    name?: string;
}

export interface GetClassroomsOptions {
    /**
     * Optional profiles parameter.
     * - If "ALL", fetches classrooms across all profiles
     * - If undefined, fetches classrooms for the current profile (default behavior)
     * - If a specific profile ID, returns classrooms for that profile
     */
    profiles?: string | ClassroomProfiles;
    /**
     * Optional hasLastAccessed will filter to only classrooms with a lastAccessDate if true.
     */
    hasLastAccessed?: boolean;
    /**
     * Optional hasTeachers will filter to only classrooms with teachers if true.
     */
    hasTeachers?: boolean;
}

export interface IClassroomFilterOptions extends GetClassroomsOptions {
    /**
     * Optional current user id
     */
    currentUserId?: string;
}

export enum ClassroomProfiles {
    ALL = 'ALL',
}
