type IPageOptions = {
    start: number;
    limit: number;
};

interface IListingOptions<IOrderField> extends IPageOptions {
    orderDirection: IOrderDirection;
    orderBy: IOrderField;
}

const headers = getSAMVersionRequestHeader();

export interface AssignmentsListingOptions // will be used in getAssignments
    extends IListingOptions<IAssignmentsOrderBy> {
    classroomId?: string;
    campaignId?: string;
    submissions?: string;
    profiles?: string;
}

const DefaultAssignmentsListingOptions: AssignmentsListingOptions = {
    orderDirection: 'ascending',
    orderBy: 'repo:name',
    start: 0,
    limit: 0
};

function createPageTemplate(options: IPageOptions) {
    const templateValues: Parameters<typeof getURLFromLinks>[2] = {};
    if (options.start) {
        templateValues.start = options.start.toString();
    }
    if (options.limit) {
        templateValues.limit = options.limit.toString();
    }
    return templateValues;
}

function getDirectionValue<IOrderField>(userOptions: IListingOptions<IOrderField>) {
    const directionFlag = userOptions.orderDirection === 'ascending' ? '+' : '-';
    return directionFlag + userOptions.orderBy;
}

/**
 * @description Gets the path for the assignments listing
 * @param links The links object containing valid actions this user has on the assignment
 * @param options The options for the assignments listing
 * @throws {SAMError} if both classroomId and campaignId are provided or neither are provided
 * @returns The path for the assignments listing
 */
export function getAssignmentsListingPath(links: IAssignmentsLinks, options?: Partial<AssignmentsListingOptions>): string {
    const userOptions = Object.assign({}, DefaultAssignmentsListingOptions, options);
    const templateValues = createPageTemplate(userOptions);
    templateValues.orderBy = getDirectionValue(userOptions);
    const { classroomId, campaignId, submissions, profiles } = userOptions;

    if (classroomId) {
        templateValues.classroomId = classroomId;
    } else if (campaignId) {
        templateValues.campaignId = campaignId;
    }
    if (submissions) {
        templateValues.submissions = submissions;
    }
    if (profiles) {
        templateValues.profileId = profiles;
    }

    // Generate the base URL using the URI template
    return getURLFromLinks(links, RelType.ASSIGNMENTS_COLLECTION, templateValues);
}

function validateRequiredAssignmentLinks(links: any) {
    return validateLinks(links, ASSIGNMENTS_INDEX_LINKS);
}

/**
 * Validates that a Tutorial object has all of the required properties and they are the correct types
 * @returns An array of error messages if there are any validation errors
 */
function validateTutorialData(data: Tutorial): string[] {
    return validateTypes([
        { key: 'surfaces', type: 'object', isRequired: true },
        { key: 'aem_id', type: 'string', isRequired: true },
        { key: 'metadata', type: 'object', isRequired: false },
    ], data);
}

/**
 * Validates that the object which will create an Assignment has all of the required properties and they are the correct types
 * @returns An array of error messages if there are any validation errors
 */
export function validateAssignmentData(data: IAssignmentCreateData): string[] {
    const errors: string[] = [];

    // Handle basic type validation
    const assignmentDataToValidate: ValidationMap<IAssignmentCreateData>[] = [
        { key: 'classroomId', type: 'string', isRequired: true },
        { key: 'createdBy', type: 'string', isRequired: false },
        { key: 'dueDate', type: 'date', isRequired: false },
        { key: 'externalTemplateIds', type: 'string[]', isRequired: false },
        { key: 'instructions', type: 'string', isRequired: false },
        { key: 'name', type: 'string', isRequired: true },
        { key: 'status', type: 'enum', isRequired: false, ref: AssignmentStatus },
        { key: 'tasks', type: 'string[]', isRequired: false },
        { key: 'templateIds', type: 'string[]', isRequired: false },
    ];

    errors.push(...validateTypes(assignmentDataToValidate, data));

    // Handle references since it can be multiple types
    data.references?.forEach((reference, idx) => {
        if (typeof reference === 'object') {
            if (!validateType(reference.content, 'string', true) && !validateType(reference.content, 'blob', true)) {
                errors.push(`references[${idx}].content is not a string, Blob, or is missing`);
            }

            if (!validateType(reference.name, 'string', true)) {
                errors.push(`references[${idx}].name is not a string or is missing`);
            }
        } else if (typeof reference !== 'string') {
            errors.push(`references[${idx}] is not an string or ExternalAsset`);
        }
    });

    // Handle tutorials
    if (data.externalTutorials) {
        if (!Array.isArray(data.externalTutorials)) {
            errors.push('externalTutorials is not an array');
        } else {
            data.externalTutorials.forEach((tutorial, idx) => {
                validateTutorialData(tutorial).forEach((error) => {
                    errors.push(`externalTutorials[${idx}]: ${error}`);
                });
            });
        }
    }

    // Handle assignment material validation
    const hasTasks = (data.tasks?.length ?? 0) > 0;
    const hasTemplates = (data.templateIds?.length ?? 0) > 0;
    const hasTutorials = (data.externalTutorials?.length ?? 0) > 0;
    const hasExternalTemplates = (data.externalTemplateIds?.length ?? 0) > 0;
    const isDraft = data.status === AssignmentStatus.DRAFT;
    const hasStartingPoint = hasTasks || hasTemplates || hasTutorials || hasExternalTemplates;

    if (!isDraft && !hasStartingPoint) {
        errors.push('Assigned Assignment must have tasks, templates, externalTemplateIds, or tutorials');
    }

    return errors;
}

export default class AssignmentsInterface extends InterfaceBase {
    @cache(validateRequiredAssignmentLinks)
    private async _discoverLinks(@key rootHref: string): Promise<IAssignmentsIndexLinks> {
        const response: IAssignmentsIndexResponse = await this._getResponse(rootHref, { headers });
        return response._links;
    }

    private _getEndpointHref(endpoint: string): string {
        return `https://${this._core._environment.endpoints.ASSIGNMENTS_HOST}${endpoint}`;
    }

    async discoverLinks(): Promise<IAssignmentsIndexLinks> {
        return this._discoverLinks(this._getEndpointHref(`/api/v1/index`));
    }

    /**
     * @description Fetches the list of Assignments based on the options provided
     * @param options : options to sort and filter the Assignments listing
     * @throws {SAMError} if both classroomId and campaignId are provided or neither are provided
     * @throws {SAMError} if profiles is set to ALL
     * @returns resolves to list of Assignments along with the page information and links to the next page
    */
    async getAssignments(options: Partial<AssignmentsListingOptions>): Promise<IAssignmentsResponse> {
        // options.classroomId is optional as the type is reused elsewhere, but really it's needed here to get assignments
        if (!options.classroomId && !options.campaignId) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'classroomId or campaignId is required to fetch assignments');
        }
        if (options.classroomId && options.campaignId) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Cannot fetch assignments by both classroomId and campaignId');
        }

        // ALL is not supported for assignments
        if (options.profiles === 'ALL') {
            throw SAMError.create(SAMErrorCode.UNSUPPORTED, 'profiles=ALL is not supported for assignments. Use a specific profile ID with classroomId instead.');
        }
        const links = await this.discoverLinks();
        const url = getAssignmentsListingPath(links, options);
        return this._getResponse(url, { headers });
    }

    /**
     * Get an Assignment by id or code
     * @param identifierType What type of identifier we will fetch by
     * @param identifier The assignment ID or code depending on value of identifierType
     * @param submissions Use this if you want to include or exclude submissions from the assignment
     * @param additionalHeaders Additional headers to include in the request
     * @returns The fetched assignment
     */
    private async getAssignmentBy(identifierType: 'id' | 'code', identifier: string, submissions?: AssignmentSubmissionOwnershipEnums, additionalHeaders?: HeaderMap): Promise<IRemoteAssignment> {
        const links = await this.discoverLinks();
        const params: Parameters<typeof getURLFromLinks>[2] = identifierType === 'id'
            ? { assignmentId: identifier }
            : { assignmentCode: identifier };
        const relType = identifierType === 'id' ? RelType.ASSIGNMENTS_PRIMARY : RelType.ASSIGNMENTS_CODE;

        if (submissions) {
            params.submissions = submissions;
        }
        const url = getURLFromLinks(links, relType, params);
        return this._getResponse(url, { headers: { ...headers, ...additionalHeaders } });
    }

    /**
     * @description Gets the metadata for a single assignment
     * @param id asset id that uniquely identifies the assignment
     * @param submissions Use this if you want to include or exclude submissions from the assignment
     * @param additionalHeaders Additional headers to include in the request
     * @returns resolves to assignment metadata for the given id
    */
    async getAssignment(id: string, submissions?: AssignmentSubmissionOwnershipEnums, additionalHeaders?: HeaderMap): Promise<IRemoteAssignment> {
        return this.getAssignmentBy('id', id, submissions, additionalHeaders);
    }

    /**
     * @description Gets the metadata for a single assignment by code
     * @param code code that identifies assignment
     * @param submissions Use this if you want to include or exclude submissions from the assignment
     * @param additionalHeaders Additional headers to include in the request
     * @returns resolves to assignment metadata for the given code
    */
    async getAssignmentByCode(code: string, submissions?: AssignmentSubmissionOwnershipEnums, additionalHeaders?: HeaderMap): Promise<IRemoteAssignment> {
        return this.getAssignmentBy('code', code, submissions, additionalHeaders);
    }

    private getPrerequisitesForCreateAssignment(data: IAssignmentCreateData): any {
        // [ACPCEDU-444]: When specified, status always takes precedence; if tasks present then assignment is ASSIGNED, otherwise it is DRAFT.
        const hasTasks = (data.tasks?.length ?? 0) > 0;
        const status = data.status || (hasTasks ? AssignmentStatus.ASSIGNED : AssignmentStatus.DRAFT);
        const extTemplateIds = data.externalTemplateIds || [];
        const extTutorials = data.externalTutorials?.map(t => JSON.stringify(t)) || [];

        return {
            'assignment:canClassroomReadSubmissions': data.canClassroomReadSubmissions,
            'assignment:dueDate': data.dueDate?.toISOString(),
            'assignment:instructions': data.instructions,
            'repo:name': data.name,
            'assignment:status': status,
            'assignment:tasks': data.tasks || [],
            'assignment:createdBy': data.createdBy,
            'assignment:externalTemplateIds': [ ...extTemplateIds, ...extTutorials ],
            'assignment:campaignId': data.campaignId
        };
    }

    /**
     * Creates a new Assignment
     * @param data needed to create a Assignment like name and instructions
     * @returns the newly created Assignment
    */
    async createAssignment(data: IAssignmentCreateData): Promise<IRemoteAssignment> {
        const links = await this.discoverLinks();
        const url = new URL(getURLFromLinks(links, RelType.ASSIGNMENTS_CREATE));
        const hasTasks = (data.tasks?.length ?? 0) > 0;
        const status = data.status || (hasTasks ? AssignmentStatus.ASSIGNED : AssignmentStatus.DRAFT);
        setURLSearchParams(url, {
            classroomId: data.classroomId,
            assign: (status === AssignmentStatus.ASSIGNED).toString(),
        });

        const options = this.getPrerequisitesForCreateAssignment(data);

        const response = await this._doPost(url.toString(), { ...headers, 'Content-Type': JSON_MIME_TYPE }, JSON.stringify(options), [ 201 ]);
        // TODO: https://jira.corp.adobe.com/browse/ACPCEDU-403 Add error handling
        const jsonResponse = await response.json();

        return jsonResponse;
    }

    /**
     * Creates a new Assignment using the v2 API
     * @param data creation data (e.g. title, instructions, etc)
     * @returns the newly created Assignment
     */
    async createAssignmentV2(data: IAssignmentCreateDataV2): Promise<IRemoteAssignment> {
        const options = this.getPrerequisitesForCreateAssignment(data);

        if (data.templates) {
            options['assignment:templates'] = data.templates.map((template) => ({
                'repo:assetId': template.assetId,
                'repo:repositoryId': template.repositoryId,
                'repo:name': template.name,
            }));
        }

        const links = await this.discoverLinks();
        const createUrl = new URL(getURLFromLinks(links, RelType.ASSIGNMENTS_CREATE_V2, { classroomId: data.classroomId, assign: (data.status === AssignmentStatus.ASSIGNED).toString() }));
        const response = await this._doPost(createUrl.toString(), { ...headers, 'Content-Type': JSON_MIME_TYPE }, JSON.stringify(options), [ 201 ]);
        return response.json();
    }

    /**
     * Updates an assignment's data
     * @param id The id of the Assignment to update
     * @param data The data to update the Assignment with. Currently only the instructions, dueDate, tasks, and templateIds can be modified.
     */
    async patchAssignment(id: string, ops: {
        op: string;
        path: string;
        value: unknown;
    }[]): Promise<IRemoteAssignment> {
        const links = await this.discoverLinks();
        const url = getURLFromLinks(links, RelType.ASSIGNMENTS_PRIMARY, { assignmentId: id });
        const response = await this._doPatch(url, { ...headers, 'Content-Type': JSON_MIME_TYPE }, JSON.stringify(ops), [ 200, 204 ]);
        const jsonResponse = await response.json();
        return jsonResponse;
    }

    /**
     * Discards an assignment -- from the DISCARDED state, an assignment can be permanently deleted or restored
     * @param id The id of the Assignment to discard
     * @param links The links object containing valid actions this user has on the assignment
     */
    async discardAssignment(id: string, links: AssignmentLinks): Promise<void> {
        if (!links?.[RelType.DISCARD]) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, `Discard link is missing for this assignment ${id}`);
        }
        const url = getURLFromLinks(links, RelType.DISCARD, { assignmentId: id });

        await this._doPost(url, headers, undefined, [ 204 ]);
    }

    /**
     * Restores a discarded assignment
     * @param id The id of the Assignment to restore
     * @param links The links object containing valid actions this user has on the assignment
     */
    async restoreAssignment(id: string, links: AssignmentLinks): Promise<void> {
        if (!links?.[RelType.RESTORE]) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, `Restore link is missing for this assignment ${id}`);
        }
        const url = getURLFromLinks(links, RelType.RESTORE, { assignmentId: id });

        await this._doPost(url, headers, undefined, [ 204 ]);
    }
}
