import SAMError, { SAMErrorCode } from '../core/SAMError';
import { arrayBufferToUtf8, utf8ToArrayBuffer } from '../utils/encoding';


export interface CachedResponseData {
    url: string;
    status: number;
    statusText: string;
    headers: Record<string, string>;
    body: string;
    timestamp: number;
}

/**
 * A CacheableResponse is a Response that can be serialized and deserialized.
 * It is useful for caching responses in a persistent cache, and for passing
 * responses around, where we may want to read the response body more than once.
 */
export default class CacheableResponse implements Response {

    private _body: ArrayBuffer;

    constructor(
        readonly url: string,
        readonly headers: Headers,
        readonly status: number,
        readonly statusText: string,
        readonly timestamp: number,
        body: ArrayBuffer | string
    ) {
        this._body = typeof body === 'string' ? utf8ToArrayBuffer(body) : body;
    }

    static async fromResponse(response: Response): Promise<CacheableResponse> {
        if (response instanceof CacheableResponse) {
            return response;
        }
        let body: ArrayBuffer;
        // We must take care to not read `arrayBuffer()` if body is null, because UXP throws an error in that case.
        if (response.body) {
            body = await response.arrayBuffer();
        } else {
            body = new ArrayBuffer(0);
        }
        return new CacheableResponse(response.url, response.headers, response.status, response.statusText, Date.now(), body);
    }

    static async deserialize(json: CachedResponseData): Promise<CacheableResponse> {
        return new CacheableResponse(json.url, new Headers(json.headers), json.status, json.statusText, json.timestamp ?? Date.now(), base64ToBytes(json.body).buffer);
    }

    /**
     * Serialize the CachedResponse to a JSON object that can be stored in a PersistentCache.
     * The body is currently stored as a base64-encoded string, which is not the most efficient,
     * but it allows us to use the Cache API as-is. A future enhancement could store these bodies
     * in a separate binary IndexedDB store, for instance.
     */
    serialize(): CachedResponseData {
        return {
            url: this.url,
            status: this.status,
            statusText: this.statusText,
            headers: headersToObject(this.headers),
            body: bytesToBase64(new Uint8Array(this._body)),
            timestamp: this.timestamp
        };
    }

    async matches(other: Response | undefined): Promise<boolean> {
        if (!other) {
            return false;
        } else if (this.headers.has('etag') && other.headers.has('etag')) {
            return this.headers.get('etag') === other.headers.get('etag');
        } else {
            const [ buffer1, buffer2 ] = await Promise.all([ this.arrayBuffer(), other.arrayBuffer() ]);
            const array1 = new Uint8Array(buffer1);
            const array2 = new Uint8Array(buffer2);
            return array1.byteLength === array2.byteLength && array1.every((value, index) => value === array2[index]);
        }
    }

    get ok(): boolean {
        const { status } = this;
        return status >= 200 && status <= 299;
    }

    get redirected(): boolean {
        return false;
    }

    get type(): ResponseType {
        return 'basic';
    }

    async json(): Promise<any> {
        try {
            return JSON.parse(await this.text());
        } catch (err: any) {
            throw SAMError.create(SAMErrorCode.INTERNAL_ERROR,
                `Failed to parse JSON response from '${this.url}' async request.`,
                { underlyingError: err }
            );
        }
    }

    async bytes(): Promise<Uint8Array<ArrayBuffer>> {
        return new Uint8Array(this._body);
    }

    async text(): Promise<string> {
        return arrayBufferToUtf8(this._body);
    }

    clone(): CacheableResponse {
        const clonedHeaders = new Headers();
        this.headers.forEach((value, key) => clonedHeaders.set(key, value));
        return new CacheableResponse(this.url,
            clonedHeaders,
            this.status,
            this.statusText,
            this.timestamp,
            this._body);
    }

    get bodyUsed(): boolean {
        return false; // The body can always be read from a CacheableResponse.
    }

    get body(): ReadableStream<Uint8Array<ArrayBuffer>> | null {
        throw SAMError.create(SAMErrorCode.UNSUPPORTED, 'AsyncResponse.body not implemented.');
    }

    async arrayBuffer(): Promise<ArrayBuffer> {
        return this._body;
    }

    async blob(): Promise<Blob> {
        return new Blob([ this._body ], { type: this.headers.get('content-type') ?? undefined });
    }

    async formData(): Promise<FormData> {
        throw SAMError.create(SAMErrorCode.UNSUPPORTED, 'AsyncResponse.formData not implemented.');
    }

}

// TS is configured with ES2015, which doesn't define Header's iterators,
// so this function does the job:
function headersToObject(headers: Headers): Record<string, string> {
    const responseHeaders: Record<string, string> = {};
    headers.forEach((value, key) => {
        responseHeaders[key] = value;
    });
    return responseHeaders;
}

// Sample implementation from https://developer.mozilla.org/en-US/docs/Glossary/Base64
function base64ToBytes(base64: string) {
    const binString = atob(base64);
    return Uint8Array.from(binString, (m) => m.codePointAt(0) ?? 0);
}

function bytesToBase64(bytes: Uint8Array) {
    const binString = Array.from(bytes, (byte) =>
        String.fromCodePoint(byte),
    ).join('');
    return btoa(binString);
}
