import InterfaceBase from './InterfaceBase';
import type { IServiceLink } from './LinkUtils';
import { getURLFromLinks, RelType } from './LinkUtils';
import SAMError from '../core/SAMError';

interface IAssetTransferServiceLinks {
    [RelType.ATS_MOVE]: IServiceLink
}

interface IAssetTransferServiceIndexResponse {
    _links: IAssetTransferServiceLinks
}

interface IAssetTransferQuery {
    source: { assetId: string, repositoryId: string},
    target: { assetId: string, repositoryId: string}
}

export default class AssetTransferInterface extends InterfaceBase {
    async transfer(data: IAssetTransferQuery): Promise<string> {
        const links = await this.discoverLinks();
        const response = await this._doPost(
            getURLFromLinks(links, RelType.ATS_MOVE),
            { 'Content-Type': 'application/json' },
            JSON.stringify(data), [ 200 ]);

        // Asset Transfer Service will return a 200 response when a dependent service fails.
        const json = await response.json();
        if (json.status && json.status !== 200) {
            throw SAMError.createWithResponse(response);
        }

        // Returns the transferred asset's Cloud ID.
        return json.assetId;
    }

    async discoverLinks(): Promise<IAssetTransferServiceLinks> {
        const response = await this._getResponse<IAssetTransferServiceIndexResponse>(this.getUrl('/'));
        return response._links;
    }

    private getUrl(endpoint: string): string {
        return `https://${this._core._environment.endpoints.TRANSFER_SERVICE_HOST}${endpoint}`;
    }
}
