import { canComputeRenditionFromMimeType, getMimeTypes } from '../utils/MimeTypeUtils';
import { asimovMaxChunkSize, maxSockets } from '../config/constants';

type Filelike = Pick<File, 'size'>;

export function getFileExtension(fileNameOrPath: string) {
    const fileName = fileNameOrPath && fileNameOrPath.replace(/^.*[\\/]/, '');
    const dotIndex = fileName ? fileName.lastIndexOf('.') : -1;
    if (dotIndex !== -1) {
        return fileName.substr(dotIndex + 1).toLowerCase();
    }
}

export function getPrimaryMimetypeForFile(filename: string) {
    const extension = getFileExtension(filename);
    const [ mimetype ] = getMimeTypes(extension) || [];
    return mimetype || 'application/octet-stream';
}

/**
 * Split a given filelike list into 2 based on filesize being over the threshhold for Asimov api
 *
 * @param {Filelike[]} files list of files to separate
 * @returns {{standard: Filelike[], asimov: Filelike[]}} list split into standard upload api and asimov upload
 */
function _splitFileUploadsByApi(files: Filelike[]): { standard: Filelike[]; asimov: Filelike[] } {
    return files.reduce<{ standard: Filelike[]; asimov: Filelike[] }>(
        (acc, val) => {
            val.size > asimovMaxChunkSize ? acc.asimov.push(val) : acc.standard.push(val);
            return acc;
        },
        { standard: [], asimov: [] }
    );
}

/**
 * Break files given into sizable chunks mimicing asimov uploads
 *
 * @param {Filelike[]} files list of files to upload via asimov (all files in this list should be greater than 5242880 bytes in size)
 * @returns {Filelike[]} list of chunks that would be used to upload to asimov
 */
function _chunkAsimovUploads(files: Filelike[]): Filelike[] {
    return files
        .map(file => {
            const { size } = file;
            const fullChunks = Math.floor(size / asimovMaxChunkSize);
            const remainingChunk = size % asimovMaxChunkSize;
            const newChunks = fullChunks + (remainingChunk ? 1 : 0);

            return Array.from({ length: newChunks }, (_, idx) => ({
                size: idx === newChunks - 1 ? remainingChunk : asimovMaxChunkSize
            }));
        })
        .flat();
}

/**
 * Utility function to estimate how long it will take to upload a set of files
 *
 * @param {Filelike[]} files files to upload
 * @returns {number} estimated time to upload list of files given
 */
function _estimateTimeToUploadSortedArray(files: Filelike[]) {
    // Sort in decending order by size
    files.sort((a: Filelike, b: Filelike) => b.size - a.size);

    // Number of batches we require to upload all files in the given array
    const numBatches = Math.ceil(files.length / maxSockets);

    // Assume worst case scenario that the largest files are shared equally across batches
    const largestFilesPerBatch = files.splice(0, numBatches);

    // According to automation data collection it currently takes approximately
    // 1 sec per 1Mb to upload. Use this as a marker
    return largestFilesPerBatch.reduce((acc, file) => (acc += Math.round((file.size / 1024) * 2.5)), 0);
}

/**
 * Some environments require showing a warning to the user if an upload
 * is estimated to take longer than a certain amount of time. Utility
 * estimates the time to upload assets so the UI can make a rough estimate
 * whether to display a message.
 *
 * Utility generates an estimated upload time for standard and asimov api uploaded
 * files and returns the highest estimate of the 2.
 *
 * @example
 * ```ts
 * import { utils } from '@cclibraries/cc-libraries-js';
 *
 * const estimate = utils.estimateUploadTime([{size: 1234567678}]);
 * ```
 * @param {Filelike[]} fileList list of files you want an estimated upload time for
 * @returns {number} estimated time to upload in milliseconds
 */
export function estimateUploadTime(fileList: Filelike[]) {
    // Split the list into 2 arrays. 1 for standard upload, the other for asimov uploads
    const { standard, asimov } = _splitFileUploadsByApi(fileList);

    // Calculate time to upload files and return the largest of the 2 results
    return Math.max(
        _estimateTimeToUploadSortedArray(standard),
        _estimateTimeToUploadSortedArray(_chunkAsimovUploads(asimov))
    );
}

function getImageDimensionsWeb(file: File): Promise<undefined | { width: number; height: number }> {
    return new Promise(resolve => {
        const reader = new FileReader();
        reader.onload = event => {
            const img = new Image();
            img.onload = () => {
                resolve({ width: img.width, height: img.height });
            };
            img.onerror = () => {
                resolve(undefined);
            };
            img.src = event.target?.result as any;
        };
        reader.readAsDataURL(file);
    });
}

/**
 * Asynchronously get the dimensions of an image file
 * @param {File} file
 * @param {string} type
 * @returns {Promise<undefined | Object>} the dimensions object, if it's possible to compute.
 */
export async function getImageDimensions(
    file: File,
    type: string
): Promise<undefined | { width?: number; height?: number }> {
    if (!canComputeRenditionFromMimeType(type)) {
        // If the file type cannot be interpreted as an image,
        // we can't compute its "width" and "height".
        return;
    }
    try {
        if (typeof window !== 'undefined' && window.FileReader && window.Image) {
            // For Web browser environment
            return getImageDimensionsWeb(file);
        } else {
            // TODO: This should also work in a Node.js environment.
            // See: https://git.corp.adobe.com/ProjectCentral/cc-libs-firefly-script#areas-to-fix
            return;
        }
    } catch (e) {
        return;
    }
}
