export interface IGetAccessRequestResult {
    _embedded: {
        accessRequests: IAccessRequestData[] | null;
    };
    _links: {
        next: {
            href: string;
        },
        self: {
            href: string;
        }
    }
}

/**
 * The locally computed result of a page of access requests.
 * to be returned to the UI layer.
 */
export interface IAccessRequestPageResult {
    /**
     * The current page of access requests.
     */
    page: IAccessRequestData[];
    /**
     * The total number of access requests.
     */
    total: number;
    /**
     * A function to get the next page of access requests.
     */
    getNextPage?: () => Promise<IAccessRequestPageResult>;
}

export enum AccessRequestStatus {
    PENDING = 'pending',
    GRANTED = 'granted',
    REJECTED = 'rejected'
}

export interface IAccessRequestResponse {
    additionalData: any;
    canRequestAccess: boolean;
    collaborationModel: string;
    createDate: number;
    requestedPermissions: {
        canComment: boolean;
        canShare: boolean;
        rebacRole: string;
        role: string;
    };
    requesterEmail: string;
    requesterId: string;
    requesterName: string;
    resourceName: string;
    resourceType: string;
    resourceUrn: string;
    status: AccessRequestStatus;
}

/**
 *
 * Example: orderBy=+requesttime
 * Sort order. Supported values:
 * +requesttime: ascending by request create date
 * -requesttime: descending by request create date
 */
export type AccessRequestOrderBy = '+requesttime' | '-requesttime';

export interface IAccessRequestData {
    resourceUrn: string;
    canRequestAccess: boolean;
    collaborationModel: string;
    createDate: number;
    requesterEmail: string;
    requesterId: string;
    requesterName: string;
    resourceName: string;
    resourceType: string;
    status: AccessRequestStatus;
    requestedPermissions?: IRequestedPermissions;
    additionalData?: IAdditionalData;
}

export interface IRequestedPermissions {
    role: string;
    rebacRole: string;
    canShare: boolean;
    canComment: boolean;
}

export interface IAdditionalData {
    email?: string;
    userId?: string;
    displayName?: string;
    images?: Record<string, string>;
}
