/**
 * Representation
 * @packageDocumentation
 * @module Representation
 */

import type { RepresentationData } from './data/RepresentationData';
// @ts-expect-error R-TODO
import type Library from './Library';
import type Element from './Element';
import Model from './Model';
import type LibraryContents from './LibraryContents';
import { getFileExtension } from '../utils/FileUtils';
import { getExtensions } from '../utils/MimeTypeUtils';
import { requiresWrite } from './utils/AccessUtils';
import { replaceRepresentationsOnTarget } from './utils/representationUtils';
import { isRepresentationPreflightResponse } from '../drivers/CloudDriver/utils/melvilleModelMappers';
import type { UnderlyingError } from '../errors/LibraryError';
import LibraryError from '../errors/LibraryError';
import { createPlaceholderId, isPlaceholder } from './utils';
import { mapAttributesToArray } from './utils/AttributeUtils';
import type ISAMCorePrivate from '../../core/ISAMCorePrivate';
import type { HasModelBindings } from './utils/HasModelBindings';

export default class Representation extends Model<RepresentationData> {
    /**
     * @package -- only for use in SAM.js
     */
    _ChildClass = Representation;

    // Because Representation is not updated through the ItemUpdater, we can define more parameters,
    // including passing data in directly.
    constructor(
        readonly core: ISAMCorePrivate,
        parent: HasModelBindings,
        /**
         * @package -  -- for use in SAM.js only
         * Preserving the data object makes it easy to do updates and also to serialize data back.
         */
        public _data: RepresentationData
    ) {
        super(core, _data.id); // TODO-R[SHARED-4623]: Later, refactor to use abstract/composable classes so that Representation does not need to inherit from Item to get the Model's placeholder logic. It has no other need for core.
        this._parent = parent;
    }

    // We have 3 representation types: json, file, multi-state components.
    // Multi-state components utilize child representations.
    // e.g. PS and Fresco have brushes with a file/component for the tip of the brush,
    // and another for the pattern.
    // Reference: https://wiki.corp.adobe.com/display/ccexperience/Multi-state+Components
    get children() {
        return this._children;
    }

    get parent(): Representation | Element {
        return this._parent as Representation | Element;
    }

    get element(): Element {
        let element = this._parent;

        while (element instanceof Representation) {
            element = element._parent;
        }

        return element as Element;
    }

    get library(): Library {
        return this.element.library;
    }

    get isWritable(): boolean {
        return this.element.isWritable;
    }

    get type(): string {
        const type = this._data.type;
        if (type === 'application/vnd.adobe.library.link+dcx') {
            return this._data.linktype as string;
        }
        return type;
    }

    get relationship() {
        return this._data.relationship;
    }

    @requiresWrite
    set relationship(relationship: any) {
        // TODO-R [SHARED-4563] When setters are enabled, remove error thrown and re-enable the linter below.
        throw new LibraryError('NOT_IMPLEMENTED', 'Only Read Only functionality supported currently.');
        // eslint-disable-next-line
        this._updateActionDispatch({ relationship });
    }

    get width(): number {
        return this._data.width as number;
    }

    @requiresWrite
    set width(width: number) {
        // TODO-R [SHARED-4563] When setters are enabled, remove error thrown and re-enable the linter below.
        throw new LibraryError('NOT_IMPLEMENTED', 'Only Read Only functionality supported currently.');
        // eslint-disable-next-line
        this._updateActionDispatch({ width });
    }

    get height(): number {
        return this._data.height as number;
    }

    @requiresWrite
    set height(height: number) {
        // TODO-R [SHARED-4563] When setters are enabled, remove error thrown and re-enable the linter below.
        throw new LibraryError('NOT_IMPLEMENTED', 'Only Read Only functionality supported currently.');
        // eslint-disable-next-line
        this._updateActionDispatch({ height });
    }

    get isFullSize(): boolean {
        return this._data.isFullSize;
    }

    @requiresWrite
    set isFullSize(isFullSize: boolean) {
        // TODO-R [SHARED-4563] When setters are enabled, remove error thrown and re-enable the linter below.
        throw new LibraryError('NOT_IMPLEMENTED', 'Only Read Only functionality supported currently.');
        // eslint-disable-next-line
        this._updateActionDispatch({ isFullSize });
    }

    get isPreferredThumbnail(): boolean {
        return this._data.isPreferredThumbnail as boolean;
    }

    @requiresWrite
    set isPreferredThumbnail(isPreferredThumbnail: boolean) {
        // TODO-R [SHARED-4563] When setters are enabled, remove error thrown and re-enable the linter below.
        throw new LibraryError('NOT_IMPLEMENTED', 'Only Read Only functionality supported currently.');
        // eslint-disable-next-line
        this._updateActionDispatch({ isPreferredThumbnail });
    }

    get contentLength(): number {
        return this._data.contentLength as number;
    }

    @requiresWrite
    set contentLength(contentLength: number) {
        // TODO-R [SHARED-4563] When setters are enabled, remove error thrown and re-enable the linter below.
        throw new LibraryError('NOT_IMPLEMENTED', 'Only Read Only functionality supported currently.');
        // eslint-disable-next-line
        this._updateActionDispatch({ contentLength });
    }

    get libraryContents(): LibraryContents {
        return this.element.libraryContents;
    }

    /**
     * @deprecated
     */
    get isDeletedLocally(): boolean {
        return false;
    }

    get isExternalLink(): boolean {
        return this._data.isExternalLink;
    }

    isCompatibleType(type: string): boolean {
        const path = this.getContentPath();
        // Check that the representation's component matches the requested type.
        // Elements sourced from external links don't reference components so we can't enforce this check.
        if (path && !this.isExternalLink) {
            const extension = getFileExtension(path);
            const extensions = getExtensions(type);
            if (extensions.indexOf(extension as string) === -1) {
                return false; // Extension and content-type doesn't match therefore not compatible.
            }
        }
        // Fall back to ensuring the requested type matches the actual representation type.
        return type === this.type;
    }

    getValue(namespace: string, key: string): any {
        return this._data.customData?.[`${namespace}#${key}`];
    }

    getValues(): { namespace: string; key: string; value: any }[] {
        return mapAttributesToArray(this._data.customData as { [s: string]: any });
    }

    @requiresWrite
    setValue(namespace: string, key: string, value: any, _isMetadata?: boolean): void {
        // TODO-R [SHARED-4563] When setters are enabled, remove error thrown and re-enable the linter below.
        throw new LibraryError('NOT_IMPLEMENTED', 'Only Read Only functionality supported currently.');
        // eslint-disable-next-line
        this._updateActionDispatch({
            customData: {
                ...this._data.customData,
                [`${namespace}#${key}`]: value
            }
        });
    }

    @requiresWrite
    removeValue(namespace: string, key: string, isMetadata?: boolean): void {
        // TODO-R [SHARED-4563] When setters are enabled, remove error thrown and re-enable the linter below.
        throw new LibraryError('NOT_IMPLEMENTED', 'Only Read Only functionality supported currently.');
        // eslint-disable-next-line
        this.setValue(namespace, key, null, isMetadata);
    }

    @requiresWrite
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    setContent(content: ArrayBuffer | string | Blob, encoding: string, filename: string): Promise<void> {
        // TODO-R [SHARED-4563] When setters are enabled, remove error thrown and uncomment the code below.
        throw new LibraryError('NOT_IMPLEMENTED', 'Only Read Only functionality supported currently.');

        // TODO-R [SHARED-4563] All the code below should be uncommented when the setters are enabled

        // if (content instanceof Blob) {
        //     return this._driver
        //         .stageRepresentationForCommit(
        //             this.library,
        //             new File([ content ], filename, {
        //                 type: content instanceof File ? content.type : getPrimaryMimetypeForFile(filename)
        //             })
        //         )
        //         .then(payload => {
        //             return this.setStagedContent(payload);
        //         });
        // }

        // let data: string;
        // if (typeof content === 'string' && [ 'base64', 'utf8' ].includes(encoding)) {
        //     data = content;
        // } else {
        //     throw new Error('Not implemented');
        // }

        // return this._updateActionDispatch({ source: { filename, data } });
    }

    @requiresWrite
    setContentFromPath(path: string, _moveFile?: boolean): Promise<void> {
        // TODO-R [SHARED-4563] When setters are enabled, remove error thrown and re-enable the linter below.
        throw new LibraryError('NOT_IMPLEMENTED', 'Only Read Only functionality supported currently.');
        // eslint-disable-next-line
        if (!this.library.locallyManaged) {
            // Not supported in this mode
            throw new Error();
        }

        return this._updateActionDispatch({ source: { path, moveFile: false } });
    }

    @requiresWrite
    setStagedContent(payload: string): Promise<void> {
        // TODO-R [SHARED-4563] When setters are enabled, remove error thrown and re-enable the linter below.
        throw new LibraryError('NOT_IMPLEMENTED', 'Only Read Only functionality supported currently.');
        // eslint-disable-next-line
        try {
            const source = JSON.parse(payload);

            if (!isRepresentationPreflightResponse(source)) {
                // Should accept placeholder representations staged to commit.
                if (!source || !isPlaceholder(source.id)) {
                    // Caught immediately below
                    throw new Error();
                }
            }

            return this._updateActionDispatch({ source });
        } catch (e) {
            throw new LibraryError(
                'INVALID_PARAMETER',
                'Payload is not consumable by remote target',
                this.library.id,
                e as UnderlyingError
            );
        }
    }

    @requiresWrite
    setContentFromURL(createLink: boolean, url: string, headers: HeadersInit): Promise<void> {
        // TODO-R [SHARED-4563] When setters are enabled, remove error thrown and re-enable the linter below.
        throw new LibraryError('NOT_IMPLEMENTED', 'Only Read Only functionality supported currently.');
        // eslint-disable-next-line
        return this._updateActionDispatch({ source: { url, createLink, headers } });
    }

    getContentPath(): string {
        return this._data.path as string;
    }

    /**
     * Get the data stored in the content of the representation, by reading the file from disk (in a filesystem environment), or by
     * downloading it (in a browser environment). This is the content set by calling
     * Representation.setContent, Representation.setContentFromPath, or Representation.setContentFromURL.
     */
    getContent(): Promise<Blob> {
        return this._driver.getRepresentationContent(this).then(res => res.blob());
    }

    getContentURL(): string {
        return this._data.url as string;
    }

    getAuthenticatedContentURL(): Promise<string> {
        return Promise.resolve('');
    }

    /**
     * @package -- only for use in SAM.js
     */
    _createChild(type: string): Representation {
        const id = createPlaceholderId();
        const children = this._data.children ? [ ...this._data.children ] : [];
        children.push({
            id,
            type,
            isFullSize: false,
            isExternalLink: false
        });

        this.element._actionDispatch({
            name: 'updateElementContent',
            type: 'update',
            data: {
                representations: replaceRepresentationsOnTarget(this, children)
            }
        });

        return this._children.find(child => child.id === id) as Representation;
    }

    /**
     * @package -- only for use in SAM.js
     */
    _removeChild(representation: Representation) {
        const children = this._data.children ? [ ...this._data.children ] : [];
        const index = children.findIndex(rep => rep.id === representation.id);

        if (index === -1) {
            return;
        }

        children.splice(index, 1);

        this.element._actionDispatch({
            name: 'updateElementContent',
            type: 'update',
            data: {
                representations: replaceRepresentationsOnTarget(this, children)
            }
        });
    }

    testExternalLink(): Promise<boolean> {
        return Promise.resolve(false);
    }

    clearCachedExternalLink(): void {
        // TODO
    }

    getCachedExternalLinkError(): any {
        return undefined;
    }

    /**
     * Get the download progress for a representation that is an external link
     * keyed in sync state via `libraryId.elementId.representationId`
     * returns -1 when an error occurs
     * returns undefined if no progress
     * returns 0 - 100 specifying percentage of download complete otherwise
     */
    getExternalLinkDownloadProgress() {
        if (this.isExternalLink) {
            const key = `${this.library.id}.${this.element.elementId}.${this.id}`;
            return this.library.apiRoot.syncState.getExternalLinkDownloadProgressByKey(key);
        }
    }

    get _childrenData() {
        return this._data.children || [];
    }

    private _updateActionDispatch(updatedData: Partial<RepresentationData>) {
        const representations = this.parent._childrenData;
        const filteredRepresentations = representations.filter((rep: RepresentationData) => rep.id !== this.id);
        this.element._actionDispatch({
            name: 'updateElementContent',
            type: 'update',
            data: {
                representations: replaceRepresentationsOnTarget(this.parent, [
                    ...filteredRepresentations,
                    {
                        ...this._data,
                        ...updatedData
                    }
                ])
            }
        });
        return Promise.resolve();
    }

    // TODO-R: Not ideal to use arrow function property instead of a method. Takes more memory than methods on the prototype.
    // Solution is to refactor to use Abstract/composable classes.
    protected _updateImplementation = (data: Partial<RepresentationData>) => {
        this._data = Object.assign(this._data, data);
        this._updateChildren(this._data.children || []); // child array is expected to be full list
        // TODO-R: Need to ensure this gets squelched during Store.begin/endOperation
        this.emit('change');
    };
}
