import type { IImplicitFilter } from '../core/ItemFilter';
import type { default as AdobeAsset } from './AdobeAsset';
import ImplicitAdobeAssetFilterBase from './ImplicitAdobeAssetFilterBase';

export default class SWYAdobeAssetFilter extends ImplicitAdobeAssetFilterBase implements IImplicitFilter<AdobeAsset> {

    constructor() {
        super({
            _isSharedWithYou: true
        });
    }
    matches(item: AdobeAsset): boolean {
        // GQL returns sharedWithYouLabel for SWY items, while _isSWYAsset_NoLazyLoad is populated by lazy-loading
        // Collaborators; or when PLS feature flags are disabled, is populated from USS. The likely roadmap is to have
        // clients switch to using `sharedWithYouLabel` for all SWY detection and deprecate `isSharedWithYouAsset`.
        if (!item._isSWYAsset_NoLazyLoad && !item.sharedWithYouLabel) {
            return false;
        }
        if (item.isProject) {
            return false;
        }
        return super.matches(item);
    }
}
