import type AdobeAsset from './AdobeAsset';
import type { IItemLoaderOptions, ILoadedPage } from '../core/ItemLoader';
import type ItemPool from '../core/ItemPool';
import type { AdobeAssetGlobalSearchConfig } from './AdobeAssetSource';
import type AdobeAssetGlobalSearchFilter from './AdobeAssetGlobalSearchFilter';
import { OrderFieldToIUSSAdobeAssetOrderBy } from './USSAdobeAssetOrder';
import type AdobeAssetGlobalSearchInterface from '../interface/AdobeAssetGlobalSearchInterface';
import type { USSResponse } from '../interface/USSModel';
import type { IGetUSSResults, IUSSLoader } from './USSLoaderHelper';
import USSLoaderHelper from './USSLoaderHelper';
import type { ISAMCorePrivate } from '../indexPrivate';
import type AdobeAssetFilter from './AdobeAssetFilter';
import type LibraryContext from '../libraries/LibraryContext';

export default class AdobeAssetGlobalSearchLoader implements IUSSLoader<AdobeAssetGlobalSearchConfig> {
    private _ussLoaderHelper: USSLoaderHelper<AdobeAssetGlobalSearchConfig>;
    _libraryContext?: LibraryContext;
    constructor(
        assetPool: ItemPool<AdobeAsset>,
        private _implicitFilter: AdobeAssetGlobalSearchFilter,
        private _core: ISAMCorePrivate,
        private _adobeAssetGlobalSearchInterface: AdobeAssetGlobalSearchInterface
    ) {
        this._ussLoaderHelper = new USSLoaderHelper(assetPool, _core, this);
    }

    supportsFilter(filter?: AdobeAssetGlobalSearchFilter | AdobeAssetFilter): boolean {
        // If we don't provide a filter at all, then we cannot use the loader
        return filter !== undefined;
    }

    async loadPage(options: IItemLoaderOptions<AdobeAssetGlobalSearchConfig>): Promise<ILoadedPage<AdobeAssetGlobalSearchConfig>> {
        if (!this._libraryContext) {
            this._libraryContext = await this._core.getLibraryContext();
        }
        return this._ussLoaderHelper.loadPage(options);
    }

    /**
     * @package -- only for use by USSLoaderHelper
     */
    _getUSSResults({
        start,
        loadOptions,
        order,
        mediaTypes,
        excludeMediaTypes
    }: IGetUSSResults<AdobeAssetGlobalSearchConfig>): Promise<USSResponse> {
        const query = this._implicitFilter?._query;

        return this._adobeAssetGlobalSearchInterface.getFilteredAssets({
            orderBy: OrderFieldToIUSSAdobeAssetOrderBy[order.field],
            orderDirection: order.direction,
            start,
            limit: loadOptions?.limit,
            mediaTypes,
            excludeMediaTypes,
            query,
            embedPermissions: true,
        });
    }

    /**
     * @package -- only for use by USSLoaderHelper
     */
    _postProcessPage(
        loaderOptions: IItemLoaderOptions<AdobeAssetGlobalSearchConfig>,
        page: ILoadedPage<AdobeAssetGlobalSearchConfig>
    ): void {
        const { items } = page;

        this._implicitFilter!._matchingIDsFromSearch = new Set([
            // copy existing, if needed
            ...(this._implicitFilter!._matchingIDsFromSearch || []),
            ...(items.map(item => item.id)) ]);
    }
}
