import AppMetadataResource from '../assets/AppMetadataResource';
import type { ISAMCorePrivate } from '../indexPrivate';
import type Assignment from './Assignment';
import { AssignmentUpdater } from './Assignment';

export default class AssignmentAppMetadataResource extends AppMetadataResource {

    constructor(
        readonly _core: ISAMCorePrivate,
        readonly _parent: Assignment,
    ) {
        super(_core, _parent);
    }

    protected async _loadData() {
        // Directly fetches app metadata from R-API since there is a chance app metadata
        // has been fetched external to Hume, such as the case the Assignment was fetched
        // with AssetContext.getAssetWithCloudID.
        await super._loadData();
        // Updates the Assignment to include the latest app metadata
        const session = this._core._getAssetPool().createMutationSession<Assignment>(this.timestamp);
        AssignmentUpdater.updateLocalItem(session, this._parent, this.data);
        session.commit();
    }
}
