// Converts all the non library related DCXData values to any Array of Objects.
export function mapAttributesToArray(customData: { [s: string]: any }) {
    customData = customData ?? {};
    const ret = [];
    for (const [ customKey, value ] of Object.entries(customData)) {
        const [ namespace, key ] = customKey.split('#', 2);
        ret.push({ namespace, key, value });
    }
    return ret;
}
