import type { RepresentationData } from '../../../models/data/RepresentationData';
import type { ElementData } from '../../../models/data/ElementData';
import type { LibraryData } from '../../../models/data/LibraryData';
import type { GroupData } from '../../../models/data/GroupData';
import type { VersionData } from '../../../models/data/VersionData';
import type { CollaboratorData } from '../../../models/data/CollaboratorData';
import uriTemplates from 'uri-templates';
