export type DCXNode = {
    id: string;
    children?: DCXNode[];
    components?: DCXNode[];
    [s: string]: any;
};

type DCXGroupMembershipData = {
    order: string;
};

export type Link = {
    href: string;
    rel: string;
    type: string;
    templated?: boolean;
    'repo:maxSingleTransferSize'?: number;
    'repo:minBlockTransferSize'?: number;
};

export enum RapiLinkType {
    DOWNLOAD = 'http://ns.adobe.com/adobecloud/rel/download',
    MANIFEST = 'http://ns.adobe.com/adobecloud/rel/manifest',
    APPLICATION = 'http://ns.adobe.com/adobecloud/rel/metadata/application',
    EMBEDDED = 'http://ns.adobe.com/adobecloud/rel/metadata/embedded',
    REPOSITORY = 'http://ns.adobe.com/adobecloud/rel/metadata/repository',
    PRIMARY = 'http://ns.adobe.com/adobecloud/rel/primary',
    RENDITION = 'http://ns.adobe.com/adobecloud/rel/rendition',
    COMPONENT = 'http://ns.adobe.com/adobecloud/rel/component',
    RESOLVE = 'http://ns.adobe.com/adobecloud/rel/resolve/id',
    BLOCK_INIT = 'http://ns.adobe.com/adobecloud/rel/block/init',
    BLOCK_TRANSFER = 'http://ns.adobe.com/adobecloud/rel/block/transfer',
    BLOCK_FINALIZE = 'http://ns.adobe.com/adobecloud/rel/block/finalize'
}

export type BlockDownloadResponse = {
    href: string;
    size: number;
    type: string;
};

export type VersionResponse = {
    created: string;
    created_by: string;
    version: string;
    _links: {
        [s in RapiLinkType]: Link;
    };
};

export function mapManifestToLibraryData(
    asset: AdobeAsset,
    manifest: DCXNode = asset.manifest.data
): Partial<LibraryData> {
    const etag = asset.manifest?.etag;

    const elements = getElementsFromDCXNode(
        asset,
        manifest.children?.find(node => node.name === 'elements') as DCXNode
    );
    const removedElements = getElementsFromDCXNode(
        asset,
        manifest.children?.find(node => node.name === 'removed_elements') as DCXNode
    );
    const documentationElements = getElementsFromDCXNode(
        asset,
        manifest.children?.find(node => node.name === 'documentation_elements') as DCXNode
    );

    const groupsNode = manifest.children?.find(node => node.name === 'groups');
    const groups: GroupData[] =
        groupsNode?.children?.map(node => ({
            id: node.id,
            name: node.name,
            classifier: node['library#classifier'],
            order: node['library#order'],
            parentId: node['library#parentId'],
            sourceRef: node['library#sourceRef'],
            customData: getCustomDCXData(node)
        })) || [];

    const libraryData: Partial<LibraryData> = {
        id: manifest.id,
        name: manifest.name,
        etag,
        localizedNames: manifest['library#localizedName'],
        toolkitId: manifest['toolkit#id'],
        documentId: manifest['library#documentId'],
        documentType: manifest['library#documentType'],
        createdBy: asset.createdBy,
        modifiedBy: asset.modifiedBy,
        createdDate: asset.created.valueOf(),
        modifiedDate: asset.modified.valueOf(),
        version: manifest.components && manifest.components[0].version,
        roles: manifest['library#roles'],
        description: manifest['library#description'],
        details: {
            elementCount: elements.length,
            documentationElementCount: documentationElements.length,
            removedElementCount: removedElements.length
        },
        groups,
        elements,
        documentationElements,
        removedElements,
        customData: getCustomDCXData(manifest),
        isLibraryLoaded: true,
        areElementsLoaded: true,
        appMetadata: asset.appMetadata?.data
        // default: can't get from manifest,
        // ownership: can't get from manifest,
        // collaboration: can't get from manifest,
        // assetId: can't get from manifest,
        // isWritable: can't get from manifest,
        // isParentWritable: can't get from manifest,
        // team: can't get from manifest,
        // owner: can't get from manifest,
        // ownerType: can't get from manifest
    }; // TODO

    if (manifest.components && manifest.components[0].version) {
        libraryData.version = manifest.components[0].version;
    }

    return libraryData;
}

function getElementsFromDCXNode(asset: AdobeAsset, node: DCXNode): ElementData[] {
    if (!node) {
        return [];
    }

    return (
        node.children?.map(element => {
            const elementData: ElementData = {
                id: element.id,
                name: element.name,
                isAutoNamed: element['library#autoName'],
                type: element.type,
                tags: element.tags || [],
                dependencyIds: element['library#dependencies'] || [],
                localizedNames: element['library#localizedName'],
                createdDate: element['library#created'],
                createdLocally: false,
                createdContext: element['library#createdData'] || {},
                modifiedDate: element['library#modified'],
                modifiedLocally: false,
                description: element['library#description'],
                descriptionModifiedLocally: false,
                removedLocally: false,
                representations: getRepresentationsFromDCXNode(asset, element),
                groups: element['library#groups']
                    ? Object.entries<DCXGroupMembershipData>(element['library#groups']).map(
                        ([ key, { order } ]: [string, DCXGroupMembershipData]) => {
                            // example key: $default#3c9fea12-e456-4d3f-b209-d76e52b2e89c
                            const [ classifier, id ] = key.split('#');
                            return { id, classifier, order };
                        }
                    )
                    : [],
                sourceRef: element['library#sourceRef'],
                roles: element['library#roles'],
                customData: getCustomDCXData(element)
            };

            // Attempt to set renditionUrl on elementData if a usable representation exists
            setRenditionUrl(asset, elementData);

            return elementData;
        }) || []
    );
}

function getComponentUrl(asset: AdobeAsset, representation: DCXNode): string {
    const links = asset.links[RelType.COMPONENT];
    if (!links || (Array.isArray(links) && links.length === 0)) {
        return '';
    }

    // getURLFromLinks handles both array and object formats via getTemplateFromLinks
    return getURLFromLinks(asset.links, RelType.COMPONENT, {
        revision: representation.version,
        component_id: representation.id
    });
}

function setRenditionUrl(asset: AdobeAsset, element: ElementData) {
    const links = asset.links[RelType.RENDITION];
    if (!links || (Array.isArray(links) && links.length === 0)) {
        return;
    }

    const candidate = getRenditionCandidate(element.representations);
    if (candidate) {
        const templateString = getTemplateFromLinks(asset.links, RelType.RENDITION);
        element.renditionUrl = {
            template: templateString,
            substitutions: {
                fragment: `id=${candidate.id}`,
                size: 200
            }
        };
    }
}

function getRepresentationsFromDCXNode(asset: AdobeAsset, node: DCXNode): RepresentationData[] {
    const components: RepresentationData[] =
        node.components?.map(component => ({
            id: component.id,
            type: component.type,
            relationship: component.rel,
            url: getComponentUrl(asset, component),
            isFullSize: component['library#isFullSize'] || component['library#isfullSize'],
            isExternalLink: false,
            width: component.width,
            height: component.height,
            contentLength: component.length,
            isPreferredThumbnail: component['library#isPreferredThumbnail'],
            customData: getCustomDCXData(component)
        })) || [];

    const children: RepresentationData[] =
        node.children?.map(child => ({
            id: child.id,
            type: child.type,
            linktype: child['library#linktype'],
            relationship: child['library#rel'],
            isFullSize: false,
            isExternalLink: false,
            customData: getCustomDCXData(child)
        })) || [];

    return [ ...components, ...children ];
}

export function getCustomDCXData(node: DCXNode) {
    const customData: { [s: string]: any } = {};

    for (const [ key, value ] of Object.entries(node)) {
        const [ namespace, entry ] = key.split('#');
        if (namespace !== 'library' && entry) {
            customData[key] = value;
        }
    }

    return customData;
}

export function mapResponseToBlockDownloadData(blockDownloadResponse: BlockDownloadResponse): BlockDownloadData {
    return {
        size: blockDownloadResponse.size,
        type: blockDownloadResponse.type,
        url: blockDownloadResponse.href
    };
}

export function mapResponseToVersionData(assetId: string, response: AssetVersion): VersionData {
    const templateString = response.links?.[RapiLinkType.MANIFEST].href;
    const manifestTemplate = templateString ? uriTemplates(templateString) : undefined;

    return {
        id: response.versionId,
        assetId,
        createdDate: response.created.getTime(),
        createdBy: response.createdBy,
        manifestUrl: manifestTemplate?.fill({}) as string
    };
}

export function mapResponseToCollaboratorData(assetId: string, collaborator: Collaborator): CollaboratorData {
    return {
        id: collaborator.collaboratorID,
        assetId,
        imsUserId: collaborator.imsUserId,
        email: collaborator.email,
        name: collaborator.name,
        role: collaborator.role,
        type: collaborator.type,
        inheritances: collaborator.inheritances,
        isDirect: collaborator.isDirect,
        hasContributorRole: collaborator.hasContributorRole,
        hasName: collaborator.hasName,
        invited: collaborator.invited,
        isAdmin: collaborator.isAdmin
    };
}
