import type Element from '../Element';

const DEFAULT_SRGB_PROFILE = 'sRGB IEC61966-2.1';
const isRGB = (data: any) => data.mode === 'RGB';
const isSRGB = (data: any) => isRGB(data) && (!data.profileName || data.profileName === DEFAULT_SRGB_PROFILE);

// Convert RGB values to a hex string (e.g. rgbToHex(50, 50, 50) = '#323232')
const rgbToHex = (r: number, g: number, b: number) => {
    let str = ((Math.round(r) << 16) | (Math.round(g) << 8) | Math.round(b)).toString(16);
    while (str.length < 6) {
        str = '0' + str;
    }
    return `#${str}`.toUpperCase();
};

// Convert color data to a hex string. (With a few other color utils encapsulated inside.)
const colorDataToHexString = (color: Object) => {
    // If data is a swatch array of colorData, get the sRGB data
    const data = Array.isArray(color) ? color.find(isSRGB) || color.find(isRGB) : color;
    return data && data.value ? rgbToHex(data.value.r, data.value.g, data.value.b) : '';
};

const getData = (element: Element, namespace: string, filter?: Function) => {
    const type = `application/vnd.adobe.${namespace}+json`;
    for (let i = 0; i < element.representations.length; i++) {
        const representation = element.representations[i];
        if (representation.type === type) {
            const data = representation.getValue(namespace, 'data');
            if (data && (!filter || filter(data))) {
                return data;
            }
        }
    }
};

const getColorName = (element: Element) => {
    // Note: Some colors have an RGB representation that's not sRGB. That's technically not allowed,
    // but we fall back to picking the first RGB representation (regardless of mode) if there's no sRGB
    // representation
    const color = getData(element, 'color', isSRGB) || getData(element, 'color', isRGB);
    return colorDataToHexString(color);
};

const getFontName = (element: Element) => {
    const font = getData(element, 'font');
    return font?.name || '';
};

const getStyleName = (namespace: string) => (element: Element) => {
    const style = getData(element, namespace);
    if (style) {
        const fontStyle = style.adbeFont && style.adbeFont.style.toLowerCase();
        if (fontStyle && !fontStyle.includes('normal') && !fontStyle.includes('regular')) {
            return `${style.fontFamily} ${style.adbeFont.style}`;
        }
        return style.fontFamily;
    }
};

const generateNameMap: any = {
    'application/vnd.adobe.element.color+dcx': getColorName,
    // Note: character and paragraph styles now require names, but some older elements are nameless:
    'application/vnd.adobe.element.characterstyle+dcx': getStyleName('characterstyle'),
    'application/vnd.adobe.element.paragraphstyle+dcx': getStyleName('paragraphstyle'),
    'application/vnd.adobe.element.font+dcx': getFontName
};

export const getGeneratedName = (element: Element) => {
    const getName = generateNameMap[element.type];
    return getName ? getName(element) : '';
};
