import type ItemBase from '../core/ItemBase';
import type SAMError from '../core/SAMError';
import { SAMErrorCode } from '../core/SAMError';
import type { IBatchOperationResult, IFailedOperation } from '../interface/RepositoryModel';
import type { AssetRenameMap, NameConflictMap } from './AssetUtils';

interface IConflictRetryOp<Source extends ItemBase, Destination extends ItemBase> {
    (
        assets: Source[],
        destination: Destination,
        assetRenameMap: AssetRenameMap<any>,
        retryOnConflict: boolean,
        conflictMap: NameConflictMap
    ): Promise<IBatchOperationResult<Source>>
}

/**
 * Used by batch operations to retry failed ops and rename the conflicted assets
 *
 * * **Note:** For most use cases, developers should rely on SAM's `renameOnConflict` API arguments
 * to leverage ACP's built-in name conflict resolution. This helper is only needed for the legacy
 * SpaceContext class, which will be removed in a future release.
 *
 * @param resultOps result for batch operation. Contains failed results and new models.
 * @param destination target asset location where the source assets are moved/copied
 * @param assetRenameMap allows renaming of assets in the batch operation
 * @param conflictMap saves the newName and count used for all files in batch
 * @param conflictRetryOp the original batch op method that is called after renaming conflicted assets
 * @returns the result for batch operation after retrying for failed assets.
 */
export async function retryFailedOpsDueToConflict<Source extends ItemBase, Destination extends ItemBase>(
    resultOps: IBatchOperationResult<Source>,
    destination: Destination,
    assetRenameMap: AssetRenameMap<any>,
    conflictMap: NameConflictMap,
    conflictRetryOp: IConflictRetryOp<Source, Destination>
): Promise<IBatchOperationResult<Source>> {
    const failedAssetsDueToConflict: Source[] = [];
    const otherFailedOps: IFailedOperation<Source>[] = [];

    resultOps.failedResults.forEach((failedOp) => {
        if ((failedOp.error as SAMError).code === SAMErrorCode.CONFLICT) {
            failedAssetsDueToConflict.push(failedOp.model);
        } else {
            otherFailedOps.push(failedOp);
        }
    });

    if (failedAssetsDueToConflict.length) {
        for (const [ key, value ] of conflictMap) {
            conflictMap.set(key, { newName: value.newName, countUsed: value.countUsed + 1 });
        }
        const newResultOps = await conflictRetryOp(failedAssetsDueToConflict, destination, assetRenameMap, true, conflictMap);
        newResultOps.failedResults = [ ...newResultOps.failedResults, ...otherFailedOps ];
        newResultOps.newModels = [ ...newResultOps.newModels, ...resultOps.newModels ];
        return newResultOps;
    }

    return resultOps;
}
