import InterfaceBase from './InterfaceBase';
import type {
    IRemoteStudentAssignment,
    IStudentAssignmentReturnData,
    IStudentAssignmentStartData,
    IStudentAssignmentSubmitData,
    IStudentAssignmentResponse,
    StudentAssignmentCompleteParams,
    IGetStudentAssignmentOptions,
    IStudentAssignmentsIndexLinks,
    IStudentAssignmentsIndexResponse,
    IStudentAssignmentsLinks,
    ISubmitFloatingFileData
} from './StudentAssignmentModel';
import { STUDENT_ASSIGNMENTS_INDEX_LINKS } from './StudentAssignmentModel';
import type { HeaderMap } from './LinkUtils';
import { RelType, getURLFromLinks, validateLinks } from './LinkUtils';
import SAMError, { SAMErrorCode } from '../core/SAMError';
import { cache, key } from '../core/decorators';
import { getSAMVersionRequestHeader } from '../utils/classroomUtils';
import type { AssignmentLinks } from './AssignmentModel';

interface StudentAssignmentsListingBaseOptions {
    includeStudentDocuments: boolean;
}

interface StudentAssignmentListingIdentifier {
    [identifier: string]: string;
}

type StudentAssignmentsListingOptions = StudentAssignmentsListingBaseOptions | StudentAssignmentListingIdentifier;

const DefaultStudentAssignmentsListingOptions: StudentAssignmentsListingBaseOptions = {
    includeStudentDocuments: false,
};

function validateRequiredStudentAssignmentLinks(links: any) {
    return validateLinks(links, STUDENT_ASSIGNMENTS_INDEX_LINKS);
}

function getStudentAssignmentsListingPath(links: IStudentAssignmentsLinks, options: StudentAssignmentsListingOptions): string {
    // Use defaults first and then overwrite any provided options.
    const userOptions = { ...DefaultStudentAssignmentsListingOptions, ...options };

    // Get appropriate link from collection and populate any templated options.
    const url = new URL(getURLFromLinks(links, RelType.STUDENT_ASSIGNMENTS_COLLECTION, userOptions));

    return url.toString();
}

const headers = getSAMVersionRequestHeader();

export default class StudentAssignmentsInterface extends InterfaceBase {
    @cache(validateRequiredStudentAssignmentLinks)
    private async _discoverLinks(@key rootHref: string): Promise<IStudentAssignmentsIndexLinks> {
        const response: IStudentAssignmentsIndexResponse = await this._getResponse(rootHref, { headers });
        return response._links;
    }

    private _getEndpointHref(endpoint: string): string {
        return `https://${this._core._environment.endpoints.ASSIGNMENTS_HOST}${endpoint}`;
    }

    async discoverStudentAssignmentLinks(): Promise<IStudentAssignmentsIndexLinks> {
        return this._discoverLinks(this._getEndpointHref('/api/v1/index'));
    }

    async getStudentAssignments(data: StudentAssignmentCompleteParams): Promise<IStudentAssignmentResponse> {
        let identifier: StudentAssignmentListingIdentifier = {};
        if (data.assignmentId) {
            identifier = { assignmentId: data.assignmentId };
        } else if (data.assignmentCode) {
            identifier = { assignmentCode: data.assignmentCode };
        } else {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Either assignmentCode or assignmentId must be provided');
        }

        const { loadDocuments = false, ...otherData } = data;
        const dataForQuery = {  ...otherData };

        // remove `undefined` and empty values from the data object
        Object.keys(dataForQuery).forEach((key) => {
            const value = dataForQuery[key as keyof Omit<StudentAssignmentCompleteParams, 'loadDocuments'>];
            if (value === '' || value === undefined || Array.isArray(value) && value.length === 0) {
                delete dataForQuery[key as keyof Omit<StudentAssignmentCompleteParams, 'loadDocuments'>];
            }
        });

        // loadDocuments is deprecated on the Hume call; switch to includeStudentDocuments here.
        const options = { ...identifier, ...dataForQuery, includeStudentDocuments: loadDocuments };

        const links = await this.discoverStudentAssignmentLinks();
        const url = getStudentAssignmentsListingPath(links, options);

        const response: IStudentAssignmentResponse = await this._getResponse(url, { headers });

        return response;
    }

    async getStudentAssignment(studentAssignmentId: string, options?: IGetStudentAssignmentOptions, additionalHeaders?: HeaderMap): Promise<IRemoteStudentAssignment> {
        const loadDocuments: boolean = options?.loadDocuments ?? false;

        const preparedOptions: any = { studentAssignmentId, includeStudentDocuments: loadDocuments, ...options };

        const links = await this.discoverStudentAssignmentLinks();
        let url = getURLFromLinks(links, RelType.STUDENT_ASSIGNMENTS_PRIMARY, preparedOptions);

        // TODO [ACPCEDU-5964]: Remove once Hume Index supports profileId in links
        if (preparedOptions.profileId) {
            const separator = url.includes('?') ? '&' : '?';
            const value = encodeURIComponent(preparedOptions.profileId);
            url += `${separator}profileId=${value}`;
        }

        return this._getResponse(url, { headers: { ...headers, ...additionalHeaders } });
    }

    /**
     * @description Calls the return API for a student assignment.
     * @param data The information necessary for calling the return API.
     * @returns A promise that the assignment has been returned.
     */
    async return(data: IStudentAssignmentReturnData): Promise<IRemoteStudentAssignment> {
        const { links, studentAssignmentId, submissionId } = data;

        const url = getURLFromLinks(links, RelType.ASSIGNMENTS_RETURN, { studentAssignmentId, submissionId });
        const response = await this._doPost(url, headers, undefined, [ 200 ]);
        return response.json();
    }

    /**
     * @description Calls the start API for a student assignment.
     * @param data The information necessary for calling the start API.
     * @returns A promise that resolves to the interface for the remote student assignment.
     */
    async start(data: IStudentAssignmentStartData): Promise<IRemoteStudentAssignment> {
        const { assignmentId, links } = data;

        const url = getURLFromLinks(links, RelType.ASSIGNMENTS_START, { assignmentId });
        const response = await this._doPost(url, headers, undefined, [ 200 ]);
        return response.json();
    }

    /**
     * @description Calls the submit API for a student assignment.
     * @param data The information necessary for calling the submit API.
     * @returns A promise that the assignment has been submitted.
     */
    async submit(data: IStudentAssignmentSubmitData): Promise<IRemoteStudentAssignment> {
        const { links, studentAssignmentId, submissionId } = data;

        const url = getURLFromLinks(links, RelType.ASSIGNMENTS_SUBMIT, { studentAssignmentId, submissionId });
        const response = await this._doPost(url, headers, undefined, [ 200 ]);
        return response.json();
    }

    /**
     * @description Calls the submit-floating-file API for a student's assignment.
     * @param assignmentId The assignment ID to submit the floating file to.
     * @param submissionId The asset ID of the file being submitted.
     * @returns A promise that resolves to the interface for the remote student assignment when the floating file has been submitted.
     */
    async submitFloatingFile(data: ISubmitFloatingFileData): Promise<IRemoteStudentAssignment> {
        const { assignmentId, submissionId, profileId, studentAssignmentId, links } = data;

        // Use regional link if available, otherwise use Index link.
        const currentLinks: AssignmentLinks | IStudentAssignmentsIndexLinks = links?.[RelType.ASSIGNMENTS_SUBMIT_FLOATING_FILE] ? links : await this.discoverStudentAssignmentLinks();

        const preparedOptions: any = { assignmentId, submissionId };
        if (profileId) {
            preparedOptions.profileId = profileId;
        }
        if (studentAssignmentId) {
            preparedOptions.studentAssignmentId = studentAssignmentId;
        }
        const url = getURLFromLinks(currentLinks, RelType.ASSIGNMENTS_SUBMIT_FLOATING_FILE, preparedOptions);
        const response = await this._doPost(url, headers, undefined, [ 200 ]);
        return response.json();
    }
}
