import type InvitationInterface from '../interface/InvitationInterface';
import type CollaboratorsByAssetID from './CollaboratorsByAssetID';
import { CollaboratorsByAssetIDUpdater } from './CollaboratorsByAssetID';
import type { IItemLoader, IItemLoaderOptions, ILoadedPage, ILoadNextPage } from '../core/ItemLoader';
import type ItemPool from '../core/ItemPool';
import type { CollaboratorsByAssetIDConfig } from './CollaboratorsByAssetIDSource';

export default class CollaboratorsByAssetIDLoader implements IItemLoader<CollaboratorsByAssetIDConfig> {

    constructor(
        private _collaboratorsByAssetIDPool: ItemPool<CollaboratorsByAssetID>,
        private _invitationInterface: InvitationInterface,
        private _assetIDs: string[]) {
    }

    async loadPage(options: IItemLoaderOptions<CollaboratorsByAssetIDConfig>): Promise<ILoadedPage<CollaboratorsByAssetIDConfig>> {
        return await this._loadPage(options);
    }

    private async _loadPage(options: IItemLoaderOptions<CollaboratorsByAssetIDConfig>, start: number = 0): Promise<ILoadedPage<CollaboratorsByAssetIDConfig>> {
        // max limit supported by invitation service batch api is 50, capping limit
        const limit = Math.min(options.loadOptions?.limit ?? Infinity, this._invitationInterface.batchRequestLimit);

        const slicedAssetIDs = this._assetIDs.slice(start, start + limit);

        const batchInvitationResponse = await this._invitationInterface.getCollaboratorListForUrns(slicedAssetIDs);
        const session = this._collaboratorsByAssetIDPool.createLoaderUpdateSession(Date.now());
        const collaboratorByAssetIDs = CollaboratorsByAssetIDUpdater.updateRemoteItems(session, batchInvitationResponse.result);
        session.commit();

        // Check if we have another page to load.
        let loadNextPage: ILoadNextPage<CollaboratorsByAssetIDConfig> | undefined;
        if (start + collaboratorByAssetIDs.length < this._assetIDs.length) {
            loadNextPage = (options: IItemLoaderOptions<CollaboratorsByAssetIDConfig>) =>
                this._loadPage(options, start + collaboratorByAssetIDs.length);
        }

        return { items: collaboratorByAssetIDs, loadNextPage };
    }
}
