import type { IExplicitFilter, ItemFilterRelation } from '../core/ItemFilter';
import type { default as Library } from './Library';
import type { LibraryProjectFilter, LibraryReferenceFilter } from '../interface/LibraryModel';
import { LibraryOwnerFilter, LibraryRolesFilter, BrandPublishMetadataFilter } from '../interface/LibraryModel';
import SAMError, { SAMErrorCode } from '../core/SAMError';
import { checkOwnerRelation, checkProjectRelation, checkRolesRelation, checkPublishMetadataRelation, itemMatchesOwnerFilter, itemMatchesProjectFilter, itemMatchesRolesFilter, itemMatchesPublishMetadataFilter, checkReferenceRelation } from './LibraryFilterUtils';

/**
 * Filter options for libraries.
 */
export interface LibraryFilterOptions {
    owner?: LibraryOwnerFilter[];
    roles?: LibraryRolesFilter[];
    project?: LibraryProjectFilter;
    /**
     * NOTE: This maps to Melville's "itemFilter" parameter, but that name is very confusing to use when there's an existing "ItemFilter" class and type.
     * Therefore, we're naming this "publishMetadata" to be more clear.
     */
    publishMetadata?: BrandPublishMetadataFilter;
    reference?: LibraryReferenceFilter;
}
/**
 * Internal filter that is for defining the ItemSource(s).
 * It contains both the parameters sent in the server request, and the filters used on the returned item data.
 * e.g. The LibrarySource should return libraries that are private, incoming, etc.
 */
export default class LibraryFilter implements IExplicitFilter<Library> {
    _hash: string | undefined;
    _owner: Set<LibraryOwnerFilter> | undefined;
    _roles: Set<LibraryRolesFilter> | undefined;
    _project: LibraryProjectFilter | undefined;
    _publishMetadata: BrandPublishMetadataFilter | undefined;
    _reference: LibraryReferenceFilter | undefined;
    /* Static filters that represent typical filters used in the UI. */

    // Contains all of the user's libraries, including private, followed project libraries, and libraries the user has accepted an invite to.
    // In the future, this will also include followed public libraries. (USS does not currently support adding public to the query.)
    static AllLibraries = new LibraryFilter({
        // we don't use LibraryOwnerFilter.All query param because it includes unfollowed business storage libraries
        owner: [ LibraryOwnerFilter.Incoming, LibraryOwnerFilter.Personal ]
    });

    /**
     * This filter is used to fetch the brands of a brands consumer, who can only see published brands (but not edit them).
     */
    static CollaboratorBrands = new LibraryFilter({
        owner: [ LibraryOwnerFilter.All ],
        roles: [ LibraryRolesFilter.Brand ],
        publishMetadata: BrandPublishMetadataFilter.PublishedBrands
    });

    /**
     * This filter is used to fetch the brands of a brands editor, who can edit all brands in the given brands project.
     * This filter should return all published brands in the project, along with any draft brands that are not published.
     *
     * _NOTE: This does NOT include the draft brands that have a published counterpart, since those should not be listed in their main view._
     * @param brandsProjectId The project ID for the brands project.
     */
    static EditorBrands(brandsProjectId: string): LibraryFilter {
        return new LibraryFilter({
            owner: [ LibraryOwnerFilter.All ],
            roles: [ LibraryRolesFilter.Brand ],
            publishMetadata: BrandPublishMetadataFilter.AllBrands,
            project: brandsProjectId
        });
    }

    static DEFAULT = LibraryFilter.AllLibraries;

    constructor(readonly filterOptions: LibraryFilterOptions = {}) {
        this._project = filterOptions.project;
        if (filterOptions.roles && filterOptions.roles.length > 0) {
            this._roles = new Set([ ...(filterOptions.roles) ]);
        }
        if (filterOptions.reference) {
            this._reference = filterOptions.reference;
            if (filterOptions.owner) {
                throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'The reference filter cannot be used with the owner filter.');
            }
            if (!this._project) {
                throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'The reference filter must be used with the project filter.');
            }
        } else {
            this._owner = filterOptions.owner ? new Set([ ...filterOptions.owner ]) : LibraryFilter.DEFAULT._owner;
            if (this._owner && this._owner.size > 1) {
                if (this._owner.has(LibraryOwnerFilter.Public)) {
                    // This is the case temporarily until melville supports public libraries in the same query.
                    throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Public libraries cannot be combined with other ownership types.');
                }
                if (this._owner.has(LibraryOwnerFilter.Discovery) && this._owner.has(LibraryOwnerFilter.Incoming)) {
                    throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Discovery and Incoming are redundant, as Incoming is a subset of Discovery.');
                }
            }
        }
        if (filterOptions.publishMetadata) {
            if (!this._roles || !this._roles.has(LibraryRolesFilter.Brand)) {
                throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'The publish metadata filter can only be used with the brands role.');
            }
            this._publishMetadata = filterOptions.publishMetadata;
        }
    }

    // Used in ItemSource._getListHash to identify the list.
    get hash(): string {
        if (!this._hash) {
            this._hash = [
                this._owner ? `owner=${[ ...this._owner ].sort().join(',')}` : undefined,
                this._roles ? `roles=${[ ...this._roles ].sort().join(',')}` : undefined,
                this._project ? `project=${this._project}` : undefined,
                this._publishMetadata ? `publishMetadata=${this._publishMetadata}` : undefined,
                this._reference ? `reference=${this._reference}` : undefined
            ].filter(x => x).join(':');
        }
        return this._hash;
    }

    /**
     * Checks if an item matches the filter. (May be used by ItemList and ItemLoaderState, and is called when asset change notifications
     * come in to check if the asset is still eligible to be on a particular list.)
     */
    matches(item: Library): boolean {
        // If a library has not loaded melville data, it is not considered a match.
        // We also make sure not to trigger lazy loading on an unloaded library, as that should only be triggered by the client.
        // If the data has been loaded once, we want the library to pass here (unless we get data that says it no longer passes) because
        //   we don't want it to disappear from listings after it's already been shown to the user
        if (!item.isLibrary) {
            return false;
        }
        if (this._owner && !itemMatchesOwnerFilter(item, this._owner)) {
            return false;
        }
        if (this._project && !itemMatchesProjectFilter(item, this._project, this._reference)) {
            return false;
        }
        if (this._roles && !itemMatchesRolesFilter(item, this._roles)) {
            return false;
        }
        if (this._publishMetadata && !itemMatchesPublishMetadataFilter(item, this._publishMetadata)) {
            return false;
        }
        return true;
    }

    /**
     * This method determines the commonality between the already present filter (existing)
     * and the new filter to be applied (this). The point of this is to
     * see if the new filter (this) can build some, all, or none of it's items
     * from (existing) filter.
     *
     * Subset: Means that ALL items for this filter can be built from existing
     * Disjoint: No items for this filter can be built from existing.
     * Unknown: Some items for this filter can be built from existing.
     *
     * @note we should always determine disjoint cases first before other cases.
     * @note this = NEW FILTER, existing = EXISTING FILTER
     *
     * @param existing The existing filter that we are getting the relation to.
     * @returns { ItemFilterRelation }
     */
    getRelationToFilter(existing: LibraryFilter): ItemFilterRelation {
        const relations = [
            // owner filter always exists
            checkOwnerRelation(this._owner, existing._owner),
            checkRolesRelation(this._roles, existing._roles),
            checkProjectRelation(this._project, existing._project),
            checkPublishMetadataRelation(this._publishMetadata, existing._publishMetadata),
            checkReferenceRelation(this._reference, existing._reference)
        ];

        if (relations.includes('disjoint')) {
            return 'disjoint';
        }
        if (relations.includes('unknown')) {
            return 'unknown';
        }

        // only remaining possibility is 'subset'
        return 'subset';
    }
}
