import type { LocalAssetMetadata } from '../../assets/AdobeAsset';
import type AdobeAsset from '../../assets/AdobeAsset';
import type ISAMCorePrivate from '../ISAMCorePrivate';
import { OrderDirection, OrderField } from '../ItemSource';
import { getACPLModel, LIST_CHANGE_DELAY_MS } from './SAMCpp';
import type { RecentAdobeAssetConfig } from '../../assets/RecentAdobeAssetSource';
import type { IItemList } from '../ItemList';
import throttle from '../../utils/throttle';
import ACPLModelInterface from '../../interface/ACPLModelInterface';

interface ChangedAssetsEvent {
    previews: AdobeAsset[];
    properties: AdobeAsset[];
    status: AdobeAsset[];
}

export function acplAssetToLocalAsset(adobeAsset: AdobeAsset): LocalAssetMetadata {
    return {
        localID: adobeAsset.localID,
        syncStatus: adobeAsset.syncStatus,
        syncSuspensionReason: adobeAsset.syncSuspensionReason,
        downloadStatus: adobeAsset.downloadStatus,
        uploadStatus: adobeAsset.uploadStatus,
        // In ACPL, the `repo:repositoryId` may be `~`, which represent the user's home repository;
        // in this case, `repo:path` only contains a path relative to the home repository.
        // SAM.js will internally convert that to a full repository path (see ACPLModelInterface).
        'repo:repositoryId': adobeAsset.repositoryID,
        'repo:path': adobeAsset.repoPath,
        'repo:assetId': adobeAsset.cloudID,
        'repo:size': adobeAsset.sizeInBytes,
        'repo:name': adobeAsset.name,
        'dc:format': adobeAsset.mediaType,
        // Even though created and modified are not optional, they are not always present on ACPL assets.
        'storage:deviceCreateDate': adobeAsset.created?.toISOString(),
        'storage:deviceModifyDate': adobeAsset.modified?.toISOString(),
        // TODO: In ACPL, etag and version are not yet exposed
        // 'repo:etag': adobeAsset.etag,
        // 'repo:version': adobeAsset.version,
        'repo:createdBy': adobeAsset.createdBy,
        'repo:modifiedBy': adobeAsset.modifiedBy,
        // We no longer propagate `repo:state`. SAM.js will treat service responses as authoritative.
    };
}

/**
 * A class that tracks the list of local assets, emitting "localAssetChange" events when that list changes.
 */
class LocalAssetUpdateTracker {
    // This is a SAM-C++ item list, not a SAM.js one. Assuming that cachedSource has the same
    // sort options as recentsSource.
    cachedItemsList: IItemList<RecentAdobeAssetConfig>;

    constructor(public applicationContext: any) {
        // SAMJS-1143 -- use cachedSource when available. When all clients are on SAM.cpp with
        // cachedSource, remove references to recentsSource (probably just this line).
        const source = applicationContext.cachedSource || applicationContext.recentsSource;
        this.cachedItemsList = source.getList(OrderDirection.Descending, OrderField.Modified);

        this.cachedItemsList.on('refreshed', this.onListUpdated);
        this.cachedItemsList.on('movedAsset', this.onListUpdated);
        this.cachedItemsList.on('addedAsset', event => this.addedToCachedList(event as unknown as AdobeAsset));
        this.cachedItemsList.on('removedAsset', event => this.onRemovedFromCachedList(event as unknown as AdobeAsset));

        applicationContext.on('changedAssets', this.onChangedAssets);
        // Populate the initial list. (Usually this is empty; we monitor for subsequent changes.)
        this.onListUpdated();
    }

    getLocalAssets() {
        return this.cachedItemsList.items.filter(item => item.localID).map(item => acplAssetToLocalAsset(item));
    }

    private isAssetInCachedList(asset: AdobeAsset) {
        return this.cachedItemsList.items.some(item => asset.localID === item.localID || asset.cloudID === item.cloudID);
    }

    private emitLocalAssetChange(type: 'add' | 'delete' | 'update', localAsset: LocalAssetMetadata) {
        getACPLModel()?.trigger('localAssetChange', JSON.stringify({
            type,
            localAsset
        }));
    }

    onChangedAssets = ({ previews, properties, status }: ChangedAssetsEvent) => {
        const changes = [ ...previews, ...properties, ...status ];
        for (const asset of changes) {
            if (this.isAssetInCachedList(asset)) {
                this.emitLocalAssetChange('update', acplAssetToLocalAsset(asset));
            }
        }
        // Occasionally, ACPL emits changedAssets events with empty arrays, even when updates have occurred.
        // To ensure these updates are still handled, invoke `onListChanged` when no changes are detected.
        if (!changes.length) {
            this.onListUpdated();
        }
    };

    /** When an item is added to the cached list, notify clients immediately. */
    addedToCachedList = (asset: AdobeAsset) => {
        this.emitLocalAssetChange(asset.cloudID ? 'update' : 'add', acplAssetToLocalAsset(asset));
    };

    /**
     * When an asset is removed from the cached list, it is no longer considered part of the local list.
     * This typically occurs when ACPL processes an ONS notification indicating the asset has been moved.
     * To ensure the client stops treating it as local, we emit a final update clearing the localID,
     * after which the asset will no longer be tracked unless it is re-added to the cached list.
     */
    onRemovedFromCachedList = (asset: AdobeAsset) => {
        this.emitLocalAssetChange('update', {
            localID: '',
            'repo:assetId': asset.cloudID,
        });
    };

    onListUpdated = throttle(() => {
        for (const item of this.cachedItemsList.items) {
            this.emitLocalAssetChange('update', acplAssetToLocalAsset(item));
        }
    }, LIST_CHANGE_DELAY_MS);
}

export default async function patchACPLNext(_core: ISAMCorePrivate) {
    const acplModel = getACPLModel();
    if (!acplModel) {
        return;
    }

    if (!acplModel.getLocalAssets) {
        const initialLoadPromise = Promise.resolve().then(async () => {
            const applicationContext = await acplModel.waitForApplicationContextReady();
            return new LocalAssetUpdateTracker(applicationContext);
        });

        acplModel.getLocalAssets = async () => {
            const tracker = await initialLoadPromise;
            return tracker.getLocalAssets();
        };
    }

    const acplModelInterface = new ACPLModelInterface(_core);
    // We should always subscribe to localAssetChange: whether we polyfilled getLocalAssets ourselves
    // or we're on a compatible host implementation, we need to keep the local asset list in sync.
    acplModelInterface.subscribeToLocalAssetChanges();

    if (!acplModel.downloadComposite) {
        acplModel.downloadComposite = async (id: string) => {
            const asset: AdobeAsset = await acplModel.applicationAssetContext.getAssetWithCloudID(id);
            await asset.downloadComposite?.();
        };
    }

    if (!acplModel.unpin) {
        acplModel.unpin = async (id: string) => {
            const asset: AdobeAsset = await acplModel.applicationAssetContext.getAssetWithCloudID(id);
            await asset.unpin?.();
        };
    }

    return acplModelInterface;
}
