import EventEmitter from 'events';
import type { ISAMCorePrivate } from '../indexPrivate';

type Extension = {[key: string]: PropertyDescriptor | Function}

// NOTE: since previous versions of SAM.js used override_map, this cannot be changed to override_set,
//       or it would defeat the purpose of tracking overrides applied by different versions of SAM.js.
const $OVERRIDE_SET = Symbol.for('com.adobe.ccac.samjs.extendclass.override_map');
const $EXTENSION_SET = Symbol.for('com.adobe.ccac.samjs.extendclass.extension_set');
const $OBSERVABLE_SET = Symbol.for('com.adobe.ccac.samjs.extendclass.observable_set');
const $EMITTER = Symbol.for('com.adobe.ccac.samjs.extendclass.emitter');
export const $OVERRIDDEN_GETTERS = Symbol.for('com.adobe.ccac.samjs.extendclass.overridden_getters');

interface IExtendClassOptions<T> {
    /**
     * The target class to be extended
     */
    klass: T;
    /**
     * The instance of SAMCore
     */
    core: ISAMCorePrivate;
    /**
     * Properties that will extend the target class if they are not defined
     */
    extensions?: Extension;
    /**
     * Properties that will override the target class, whether or not they are defined.
     */
    overrides?: Extension;
    /**
     * Some SAM.js classes emit a single event for a topic while SAM.cpp emits multiple. Sometimes only the event names
     * differ. This map will allow the client code to subscribe to the SAM.js event (key) and the extended class will
     * subscribe to all of the SAM.cpp events (values). It will add EventEmitter APIs to classes that do not have them.
     */
    eventMap?: { [key: string]: string[] };
    /**
     * If provided, it will make all of the getter properties of the target class observable, bound to this event.
     * It will not make observable any property defined in `extensions` nor `overrides` nor `observableMap`.
     */
    defaultObservableEvent?: string;
    /**
     * If provided, it will make just the getter properties specified in the values observable. It will not add
     * observability to properties defined in `extensions` nor `overrides`. The keys represent the event that
     * the observable properties will be bound to.
     */
    observableMap?: { [event: string]: string[]; };
}


/**
 * Extends the provided `klass` with the properties with new behaviors, and ensures it supports the
 * EventEmitter interface. Optionally, it will make all getter properties observable.
 *
 * @param options: IExtendClassOptions
 * @example
 *     class MyClass {
 *         private _foo = 32;
 *         private _bar = 99;
 *         private _baz = {};
 *         refreshBaz(x) { some impl }
 *         get foo() { return this._foo; }
 *         get bar() { return this._bar; }
 *         get baz() { return this.baz; }
 *     }
 *     ExtendClass({
 *         klass: MyClass,
 *         extensions: {
 *             refreshBaz(x) { return x * 2; },       // ignored because it exists on MyClass
 *             newFn() { return this._foo; }          // Added
 *             // Getters/setters must use PropertyDescriptor syntax
 *             // NOTE: won't be automatically made observable
 *             aliasForFoo: {
 *                 get() {
 *                     // make this getter alias observable
 *                     this._core._environment.mobx.reportObserved('change');
 *                     return this._foo;
 *                 }
 *             }
 *         },
 *         overrides: {
 *             // replaces original refreshBaz
 *             refreshBaz(x) {
 *                 // Use the added TypedEventEmitter.dispatch()
 *                 this.dispatch({ type: 'bazRefresh' });
 *                 // invoke original oldFn
 *                 return this.oldFn.original(x);
 *             }
 *         },
 *         // When client subscribes to 'change' event, the extended class will proxy that event handler to the
 *         // 'incrementFoo' and 'incrementBar' events that the native implementation emits.
 *         eventMap: { change: [ 'incrementFoo', 'incrementBar' ] },
 *         observableMap: {
 *             // the `baz` getter will be made observable, bound to the 'bazRefresh' event
 *             'bazRefresh': [ 'baz' ]
 *         }
 *         // `foo` and `bar` getter will be made observable, bound to the 'change' event;
 *         defaultObservableEvent: 'change',
 *     });
 */
export default function ExtendClass<T extends { prototype: { [key: string]: any } }>(
    {
        klass,
        core,
        extensions = {},
        overrides = {},
        eventMap = {},
        defaultObservableEvent,
        observableMap = {}
    }: IExtendClassOptions<T>
) {
    const originalProps = Object.getOwnPropertyDescriptors(klass.prototype);
    // SAM.cpp EventEmitter-ish interface is on the prototype's prototype
    let emitterProps = originalProps;
    if (typeof emitterProps.on === 'undefined') {
        emitterProps = Object.getOwnPropertyDescriptors(Object.getPrototypeOf(klass.prototype));
    }

    // Add reference to shared core if not already defined
    if (!originalProps._core) {
        Object.defineProperty(klass.prototype, '_core', { value: core });
    }

    // When overriding a getter, patch code may need access to the original using
    //    this[$OVERRIDDEN_GETTERS]['someProp'].call(this)
    if (!Object.getOwnPropertyDescriptor(klass.prototype, $OVERRIDDEN_GETTERS)) {
        Object.defineProperty(klass.prototype, $OVERRIDDEN_GETTERS, { value: {} });
    }


    // Some SAM.cpp classes (AssetList) have an event handling API similar to EventEmitter, and some don't
    // (Asset). Meanwhile, most SAM.js classes implement TypedEventEmitter. This section patches the
    // prototype to match the TypedEventEmitter API. If the SAM.cpp class doesn't have an event-handling
    // API, an actual instance of EventEmitter is used instead.
    if (!Object.getOwnPropertyDescriptor(klass.prototype, $EMITTER)) {
        Object.defineProperties(klass.prototype, {
            [$EMITTER]: {
                get() {
                    // Redefine the $EMITTER getter property for `this` instance to an actual EventEmitter, or an
                    // adapter to the SAM.cpp equivalent. The $EMITTER getter on the prototype remains unchanged
                    // so the next instance will get its own properly bound $EMITTER.
                    let emitter: EventEmitter;
                    if (typeof emitterProps.on?.value === 'function') {
                        // SAM.cpp class has an event handling API already, so create an adapter bound
                        // to the SAM.cpp implementation
                        emitter = {
                            on: emitterProps.on.value.bind(this),
                            off: emitterProps.off.value.bind(this),
                            emit: emitterProps.trigger.value.bind(this),
                            addListener: emitterProps.on.value.bind(this),
                            removeListener: emitterProps.off.value.bind(this)
                        } as EventEmitter;
                    } else {
                        // SAM.cpp class has no event handling API, so use an actual EventEmitter
                        emitter = new EventEmitter();
                    }
                    Object.defineProperty(this, $EMITTER, { value: emitter });
                    return this[$EMITTER];
                }
            },
            on: {
                value(eventName: string, ...rest: any[]) {
                    // Some SAM.cpp events map to multiple SAM.js events. If there's no mapping, then subscribe
                    // to `eventName` only.
                    const mappedEvents = eventMap[eventName] ?? [ eventName ];
                    mappedEvents.forEach(mappedEventName => this[$EMITTER].on(mappedEventName, ...rest));
                    return this;
                }
            },
            addListener: {
                value(...args: any[]) { return this.on(...args); }
            },
            off: {
                value(eventName: string, ...rest: any[]) {
                    // Some SAM.cpp events map to multiple SAM.js events. If there's no mapping, then unsubscribe
                    // from `eventName` only.
                    const mappedEvents = eventMap[eventName] ?? [ eventName ];
                    mappedEvents.forEach(mappedEventName => this[$EMITTER].off(mappedEventName, ...rest));
                    return this;
                }
            },
            removeListener: {
                value(...args: any[]) { return this.off(...args); }
            },
            emit: {
                value(...args: any[]) {
                    return this[$EMITTER].emit(...args);
                }
            },
            // SAM.js TypedEventEmitter behavior
            dispatch: {
                value(event: Event) { return this.emit(event.type, event, this); }
            }
        });

    }

    // Allow shortcut of { someMethod(): {} } instead of { someMethod: { value: function() {} } }
    function makePropertyDesc(
        map: { [key: string]: Function | PropertyDescriptor },
        key: string
    ): PropertyDescriptor {
        const propertyDesc = map[key];
        if (typeof map[key] === 'function') {
            return { value: propertyDesc };
        } else if ([ 'string', 'boolean', 'number' ].includes(typeof map[key])) {
            // TypeScript doesn't block clients from passing a primitive, and
            // Object.defineProperty(obj, key, primitive) is a no-op.
            throw new Error('Cannot use primitives for PropertyDescriptor');
        } else {
            // An object. TypeScript will verify that it is a valid PropertyDescriptor.
            return propertyDesc as PropertyDescriptor;
        }
    }

    // Track which properties have been handled in this call to ExtendClass
    const handledProps: Set<string> = new Set();

    // Extensions should handle their own observability, thus should not be made observable automatically,
    // so extensions must be tracked across calls to ExtendClass.
    const extendedProps: Set<string> = klass.prototype[$EXTENSION_SET as any] || new Set();

    Object.keys(extensions).forEach(propertyName => {
        // cannot override existing properties with extensions
        if (originalProps[propertyName]) { return; }

        const propertyDesc = makePropertyDesc(extensions, propertyName);
        Object.defineProperty(klass.prototype, propertyName, propertyDesc);
        handledProps.add(propertyName);
        extendedProps.add(propertyName);
    });
    klass.prototype[$EXTENSION_SET as any] = extendedProps;

    const overriddenProps = klass.prototype[$OVERRIDE_SET as any] || new Set();
    Object.keys(overrides).forEach(propertyName => {
        if (overriddenProps.has(propertyName)) {
            // Overrides from a previous call to ExtendClass should not be overridden again, but this
            // is not an error.
            return;
        }
        if (handledProps.has(propertyName) || extendedProps.has(propertyName)) {
            throw new Error(`[ExtendClass] cannot override property '${propertyName}' because it is an extension.`);
        }
        // Since overridden functions might expect to use `this.originalFn.original()`, it's not safe to treat the
        // override as an extension. Different hosts could have different versions of SAM.cpp, so patching code should
        // be aware of what is needed.
        if (!originalProps[propertyName]) {
            throw new Error(`[ExtendClass] target class does not have property '${propertyName}' so it cannot `
                + 'be overridden.');
        }
        const propertyDesc = makePropertyDesc(overrides, propertyName);
        const original = originalProps[propertyName].value;
        if (typeof original === 'function') {
            // Replace the the original method with the override, then attach the original
            // to the override so you can call it with `this.override.original()`
            Object.defineProperty(klass.prototype, propertyName, {
                get() {
                    // Ensure `original` is bound to correct `this`
                    propertyDesc.value.original = original.bind(this);
                    return propertyDesc.value;
                }
            });
        } else {
            if (originalProps[propertyName].get) {
                klass.prototype[$OVERRIDDEN_GETTERS as any][propertyName] = originalProps[propertyName].get;
            }
            Object.defineProperty(klass.prototype, propertyName, propertyDesc);
        }
        overriddenProps.add(propertyName);
        handledProps.add(propertyName);
    });
    klass.prototype[$OVERRIDE_SET as any] = overriddenProps;

    // Validate the passed-in observableMap config does not contain coding errors. If a config defines
    // two events for the same property, or defines an event for an extension/override, that is likely
    // a bug.
    const propToEventMap: { [key: string]: string } = {};
    Object.keys(observableMap).reduce((seenPropNames, eventName) => {
        observableMap[eventName].forEach(propName => {
            // If a property is mapped multiple times, or was extended/overwritten, treat as a coding error,
            // otherwise the result would be difficult to debug
            if (seenPropNames.has(propName)) {
                throw new Error(`[ExtendClass] cannot have the same property (${propName}) appear multiple times in observableMap`);
            }
            if (handledProps.has(propName)) {
                throw new Error(`[ExtendClass] cannot make property (${propName}) observable as it was defined in extensions/overrides`);
            }
            seenPropNames.add(propName);
            propToEventMap[propName] = eventName;
        });
        return seenPropNames;
    }, new Set());

    // Add properties to be observed using the defaultObservableEvent to propToEventMap
    if (defaultObservableEvent) {
        Object.keys(originalProps)
            // only collect getter properties
            .filter(propName => !!originalProps[propName].get)
            .forEach(propName => propToEventMap[propName] = defaultObservableEvent);
    }

    // Get already-wrapped properties that were made observable by previous calls to ExtendClass, if any,
    // so that they won't be wrapped again.
    const observedProps: Set<string> = klass.prototype[$OBSERVABLE_SET as any] || new Set<string>();

    // merge all extended/overridden/observed props (including from previous calls to ExtendClass) into handledProps
    [ ...extendedProps, ...overriddenProps, ...observedProps ].forEach(propName => handledProps.add(propName));

    Object.entries(propToEventMap).forEach(([ propName, eventName ]) => {
        // Only wrap getters, and properties that have not already been patched, either from this
        // call to ExtendClass, or a previous call. If it is from a previous call, then this is not
        // error.
        if (!originalProps[propName]?.get || handledProps.has(propName)) {
            return;
        }

        Object.defineProperty(klass.prototype, propName, {
            get() {
                this._core._environment.mobx.reportObserved(this, eventName);
                return originalProps[propName].get!.call(this);
            }
        });
        observedProps.add(propName);
    });
    klass.prototype[$OBSERVABLE_SET as any] = observedProps;
}
