import InterfaceBase from './InterfaceBase';
import type {
    ISearchQuery,
    USSResponse
} from './USSModel';
import {
    USS_ARTIFACT_MEDIATYPE,
    SearchProps
} from './USSModel';
import packageJSON from '../../package.json';
import type Resource from '../assets/Resource';

const DefaultSearchQuery: ISearchQuery = {
    scope: [ 'creative_cloud' ],
    // Ensures assetIds in results are returned with the correct casing. E.g. ":US:" instead of ":us:"
    asset_id_opacity: true
};

export default class USSInterface extends InterfaceBase {

    private _getEndpointHref(endpoint: string): string {
        return `https://${this._core._environment.endpoints.USS_HOST}${endpoint}`;
    }

    async getQueryResponse(searchQuery: ISearchQuery, resource?: Resource): Promise<USSResponse> {
        searchQuery = { ...DefaultSearchQuery, ...searchQuery };
        const endpointHref = this._getEndpointHref('/universal-search/v2/search');
        const { PRODUCT_ID } = this._core._environment.getValue('HOST_PRODUCT_DATA');

        const response = await this._doPost(
            endpointHref,
            {
                'Content-Type': 'application/vnd.adobe.search-request+json',
                'X-Product': PRODUCT_ID,
                'X-Product-Location': `SAM.js/${packageJSON.version}`
            },
            JSON.stringify(searchQuery), [ 200 ], false, resource);

        return response.json();
    }

    async searchSpace(
        parentFolderId: string,
        searchArtifacts: boolean,
        embedPermissions: boolean,
        options?: Partial<ISearchQuery>
    ): Promise<USSResponse> {
        const query: ISearchQuery = {
            hints: [ { acp_platform_v2: true, creative_cloud_rendition_v2: true } ],
            fetch_fields: { includes: [ 'app_metadata', 'collaboration_metadata' ] },
            sort_orderby: options?.sort_orderby ?? 'modify_date',
            sort_order: options?.sort_order ?? 'desc',
            limit: options?.limit ?? 50,
            start_index: options?.start_index ?? 0,
            [SearchProps.TYPE]: options?.type || [],
            container: { asset_id: [ parentFolderId ] },
        };

        if (!searchArtifacts) {
            query.op_none_of = [
                // exclude Artifacts
                { op_field_exists: [ USS_ARTIFACT_MEDIATYPE ] },
                // exclude hidden
                { [SearchProps.VISIBILITY]: [ 'hiddenSelf', 'hiddenRecursive' ] }
            ];
        } else {
            // Only include artifacts
            query.op_field_exists = [ USS_ARTIFACT_MEDIATYPE ];
        }
        if (embedPermissions) {
            query.fetch_fields!.includes.push('_embedded');
        }

        return this.getQueryResponse(query);
    }
}
