import ItemUpdater from '../core/ItemUpdater';
import PropertyUpdater from '../core/PropertyUpdater';

import type { IFrameioAssetResponse, IFrameioFileHandle } from './FrameioInterface';
import FrameioAsset from './FrameioAsset';
import type FrameioFile from './FrameioFile';
import { FrameioFileUpdater } from './FrameioFile';
import type FrameioContext from './FrameioContext';
import { frameioAssetUpdater } from './FrameioContext';

// See https://developer.frame.io/api/reference/operation/getAsset/
//  for schema of IFrameioAssetResponse. FrameioFolder
//  encapsulates the data for assets of type="folder".
//
// See FrameioFile, FrameioVersionStack for other asset types.
export default class FrameioFolder extends FrameioAsset {
    private _children: Array<FrameioAsset> | undefined;

    // clients shouldn't need to deal with id's

    async getChildren(): Promise<Array<FrameioAsset>> {
        if (!this._children) {
            const ctx = this.context;
            const response = await ctx._frameioInterface.getChildren(this.id);
            const session = ctx._objectPool.createUpdateSession<FrameioAsset>();

            // IFrameioAssetResponse is a special case, as it corresponds to multiple classes
            // inheriting from FrameioAsset ( FrameioFile, FrameioFolder, FrameioVersionStack ),
            // so use a utility function to select the correct updater for the type.
            //
            // See also FrameioContext.getAncestors()
            this._children = response.map((asset: IFrameioAssetResponse) => frameioAssetUpdater(session, asset));
            session.commit();
        }

        return this._children;
    }

    private async _uploadFile(urls: Array<string>, fp: IFrameioFileHandle): Promise<void> {
        // Frame.io splits uploads into ~20MB chunks, whereas our expected
        // artifact size is ~5MB, so the most common case will be (numChunks == 1).

        const ctx: FrameioContext = this.context;

        // limit the number of concurrent streams
        const maxStreams = 8;

        const fileSize = fp.size();
        const numChunks = urls.length;
        const chunkSize = Math.ceil(fileSize / numChunks); // round-down might lead to omitted bytes.

        let iChunk = 0;

        const nextChunk = async (bytes: ArrayBuffer): Promise<void> => {
            const i = iChunk++;
            bytes = await fp.read((i) * chunkSize, bytes);

            return ctx._frameioInterface.uploadFile(urls[i], bytes).then(() => {
                return  (iChunk < numChunks) ? nextChunk(bytes) : Promise.resolve();
            });
        };

        const limit = Math.min(numChunks, maxStreams);
        const promises = [];

        for (let i = 0; i < limit; i++) {
            promises.push(nextChunk(new ArrayBuffer(chunkSize)));
        }

        await Promise.all(promises);
    }

    async createFile(display_name: string, path: string): Promise<FrameioFile> {
        const ctx: FrameioContext = this.context;

        const fp = await ctx._frameioInterface.openFile(path);
        const fileSize = fp.size();

        // create the empty asset
        const response = await ctx._frameioInterface.createFile(this.id, display_name, fileSize);
        const session = ctx._objectPool.createUpdateSession<FrameioFile>();
        const file = FrameioFileUpdater.updateRemoteItem(session, response);
        session.commit();

        await this._uploadFile(response['upload_urls'], fp);
        fp.close();

        return file;
    }

    async createFolder(display_name: string): Promise<FrameioFolder> {
        const ctx: FrameioContext = this.context;

        const response = await ctx._frameioInterface.createFolder(this.id, display_name);
        const session = ctx._objectPool.createUpdateSession<FrameioFolder>();
        const folder = FrameioFolderUpdater.updateRemoteItem(session, response);
        session.commit();

        return folder;
    }

}

export const FrameioFolderUpdater = new ItemUpdater<FrameioFolder, Partial<IFrameioAssetResponse>>({
    localItemType: FrameioFolder,
    remoteIdProperty: 'id',
    propertyUpdater: new PropertyUpdater({
        '_insertedAt': { name: 'inserted_at', format: 'date' },
        '_name': 'name',
        '_parentId': 'parent_id',
        '_projectId': 'project_id',
        '_teamId': 'team_id',
        '_updatedAt': { name: 'updated_at', format: 'date' }
    })
});

