import type { Action } from '../../models/Action';

import SingleOperation from '../SingleOperation';
import { mapResponseToLibraryData } from './utils/restAPIModelMappers';
import LibraryAbortController from '../LibraryAbortController';
import AsyncResponse from '../AsyncResponse';
import type LocalDriver from '.';

export default class LocalSingleOperation extends SingleOperation<LocalDriver> {
    protected _actionMappers = {
        createLibrary: (action: Action) => this._createLibraryActionMap(action),
        copyLibrary: (action: Action) => this._createLibraryActionMap(action),
        permanentlyDeleteLibrary: (action: Action) => this._permanentlyDeleteLibrary(action),
        removeLibrary: async (action: Action) => {
            await this._removeLibrary();
            return action;
        },
        unfollowLibrary: async (action: Action) => {
            await this._removeLibrary('unfollow');
            return action;
        },
        leaveLibrary: async (action: Action) => {
            await this._removeLibrary('leave');
            return action;
        },
        moveLibrary: async (action: Action): Promise<Action> => {
            const data = await this._moveLibrary();
            return { ...action, data, originalAction: action };
        }
    };

    supportsAction(action: Action) {
        return [
            'createLibrary',
            'removeLibrary', // private library
            'permanentlyDeleteLibrary', // not actually supported, but let it through so we can throw a descriptive error
            'unfollowLibrary', // leave a team or public or even incoming library
            'leaveLibrary', // leave an incoming library
            'copyLibrary',
            'moveLibrary'
        ].includes(action.name as string);
    }

    private async _createLibraryActionMap(action: Action): Promise<Action> {
        const data = await this._createLibrary(action);
        return { ...action, type: 'update', data, originalAction: action };
    }

    private _createLibrary(action: Action) {
        const { data = {}, flags = {} } = action;
        return new Promise((resolve, reject) => {
            const request = this._driver.fetch('/libraries', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    name: data.name,
                    team_id: data.team?.id,
                    roles: data.roles,
                    team_permission_inheritance: flags.permissionInheritance,
                    source: flags.source?.id
                })
            });
            const asyncResponse = new AsyncResponse(this._driver, request);

            asyncResponse.on('change', (isDone, libraryResponse) => {
                if (isDone) {
                    if (asyncResponse.error) {
                        reject(asyncResponse.error);
                    }
                    const libraryData = libraryResponse ? mapResponseToLibraryData(libraryResponse) : undefined;
                    resolve(libraryData);
                }
            });
        });
    }

    private _permanentlyDeleteLibrary(_: Action): Promise<Action> {
        throw new Error('permanentlyDeleteLibrary not supported by LocalDriver, use removeLibrary instead');
    }

    private _removeLibrary(action: 'unfollow' | 'leave' | 'remove' = 'remove') {
        // Prevent unnecessary refetching of deleted libraries
        if (action === 'remove') {
            LibraryAbortController.getInstance(this._library.id).abort();
        }
        const actionPromise = this._driver.fetch(`/libraries/${this._library.id}?action=${action}`, { method: 'DELETE' }).then(() => {
            // SHARED-2544: Remove instace of library from abort controller's cache after library removal
            // as this will interfere with fetching restored libraries
            if (action === 'remove') {
                LibraryAbortController.removeInstance(this._library.id);
            }
        });
        return actionPromise;
    }

    private _moveLibrary() {
        return this._driver.moveLibrary(this._library.id, this.action.data.team.id);
    }
}
