export type LibraryDataLoadState = 'NOT_LOADED' | 'LOADING' | 'LOADED';

interface ILibraryDataLoadInfo {
    state: LibraryDataLoadState;
    promise?: Promise<void>; // A promise that completes when resolve is called, meant for waiting for libraries to load
    resolve?: () => void; // Call to resolve promise
}

