    _getLibraryInterface(): LibraryInterface {
        return this._libraryInterface;
    }

    /**
     * Returns the LibraryContents API for the library.
     * LibraryContents controls and exposes the state of the library's contents, including elements and groups.
     * The LibraryContents instance is stored using WeakRef to avoid leaking.
     * Please note that the client is responsible for holding onto this reference if they do not want the contents to be garbage collected,
     * and make sure to remove the reference when it is no longer needed, as we only keep the reference alive for the 10 minute default.
     * @returns LibraryContents
     */
    @keepAlive
    async getContents(): Promise<LibraryContents> {
        if (!this._contents || !this._contents.deref()) { // deref() may return undefined if the object has been garbage collected
            // Load and initialize CC Libraries API, if it isn't already
            const libraryContext = await this._core.getLibraryContext();
            const CCLibraries = await libraryContext._getLibrariesModule();
            // Create a LibraryContents instance from the Library asset (this is
            // a subset of the existing Library interface in the CC Libraries API)
            this._contents = new WeakRef(CCLibraries.getLibraryContents(this));
        }

        return this._contents.deref() as LibraryContents; // typescript doesn't recognize we already did an undefined check, so we have to typecast
    }

    /**
     * @package -- for use in SAM.js only
     * Use from inside library-contents code, where we know libraryContext and CCLibraries are already defined.
     * Note: This returns a hard reference, not a weak reference.
     */
    @keepAlive
    // TODO Later: Have a no-load version of this for use once load/change notifications set up.
    _getContentsSync(): LibraryContents {
        // Contents should already be defined if calling this from the CCLibraries Module, but just in case, we can get it synchronously here.
        if (!this._contents || !this._contents.deref()) {
            const libraryContext = this._core._getLibraryContext();
            // Will throw error if CCLibraries is not defined, which is why this should only be accessed from inside /library-contents
            const CCLibraries = libraryContext!._getLibrariesModule_NoLoad();
            this._contents = new WeakRef(CCLibraries!.getLibraryContents(this));
        }
        return this._contents.deref() as LibraryContents;
    }

    /**
     * @package -- for use in SAM.js only
     */
    // Check if melville data is currently fully loaded
    get _libraryLoaded(): boolean {
        return this._libraryDataLoadInfo.state === 'LOADED';
    }

    /**
     * @package -- for use in SAM.js only
     * Set a promise to resolve when libraries are loaded.  Returns a resolve function that needs to be called after
     * the library is loaded, or undefined if something else is already calling for melville data.
     */
    _setLibraryLoadState(state: LibraryDataLoadState): void  {
        const { state: priorState } = this._libraryDataLoadInfo;
        if (state === priorState) { return; }

        this._libraryDataLoadInfo.state = state;

        if (state === 'LOADED') {
            if (this._libraryDataLoadInfo.resolve) {
                this._libraryDataLoadInfo.resolve();
            }
        } else if (state === 'LOADING') {
            let resolve;
            this._libraryDataLoadInfo.promise = new Promise(r => { resolve = r; });
            this._libraryDataLoadInfo.resolve = resolve;
        } else if (state === 'NOT_LOADED') {
            // Transitioning to NOT_LOADED means the data still needs to be loaded. Notify listeners
            // in order to trigger lazy-loading. Unblock anything waiting on the Promise.
            // Use this also for when the data is stale and needs reloading.
            if (this._libraryDataLoadInfo.resolve) {
                this._libraryDataLoadInfo.resolve();
            }
            this.emit(LIBRARY_DATA_CHANGED);
        }
    }

    /**
     * Starts loading Melville data for a single Library, if it hasn't already been loaded, or waits
     * for in-flight load to complete.
     *
     * @parameter canRetry {boolean} (optional) For cases in Library that need to ensure Library
     *         data loads, but it may have failed from a listing, it can try one extra time.
     *
     * @package -- for use in SAM.js only
     */
    async _waitForLibraryLoad(canRetry: boolean = false): Promise<void> {
        this._populateLibraryDataIfNotLoading();
        await this._libraryDataLoadInfo.promise;
        if (canRetry && !this._libraryLoaded) {
            await this._waitForLibraryLoad(false);
        }
        return this._libraryDataLoadInfo.promise;
    }

    async _load({
        repoMetadata,
        appMetadata,
        effectivePermission,
        perUserMetadata,
        requireLibraryDataFetch // e.g. newly created libraries need to load melville data to be filtered properly
    }: {
        repoMetadata?: RepositoryMetadata;
        appMetadata?: any;
        effectivePermission?: Permission;
        perUserMetadata?: IPerUserMetadata;
        requireLibraryDataFetch?: boolean;
    } = {}): Promise<void> {
        // When an ONS notification comes in, load the repoMetadata
        await super._load({ repoMetadata, appMetadata, effectivePermission, perUserMetadata });

        /* We need the melville reload to happen in all cases because the LibraryFilter won't match libraries without the melville data
        * There's a pathological case where:
        * - UI is currently showing libraries with a filter
        * - A library is created externally
        * - We receive a notification here to add the library
        * - We add the library, but it has no melville data
        * - The library doesn't pass the LibraryFilter without melville data
        * - We don't show the library to the UI
        * - The UI never requests any data that would trigger the lazy load, because it doesn't see the library
        * - The library is never populated with melville data and therefore is never shown
        */

        this._setLibraryLoadState('NOT_LOADED');
        if (requireLibraryDataFetch) {
            this._populateLibraryDataIfNotLoading();
            await this._waitForLibraryLoad();
        }
    }

