import type CustomModel from './CustomModel';
import { isCustomModel } from './CustomModel';
import type {
    IImplicitAdobeAssetFilterBaseOptions
} from '../assets/ImplicitAdobeAssetFilterBase';
import ImplicitAdobeAssetFilterBase from '../assets/ImplicitAdobeAssetFilterBase';
import type { IImplicitFilter } from '../core/ItemFilter';
import type AdobeAsset from '../assets/AdobeAsset';

export interface IImplicitCustomModelFilterOptions extends IImplicitAdobeAssetFilterBaseOptions {
    trainingSetId?: string,
    generatorOnly?: boolean
}

export default class ImplicitCustomModelFilter extends ImplicitAdobeAssetFilterBase implements IImplicitFilter<CustomModel> {
    private readonly _trainingSetId?: string;
    private readonly _generatorOnly?: boolean;

    constructor(options: Partial<IImplicitCustomModelFilterOptions> = {}) {
        const { trainingSetId, generatorOnly, ...superOptions } = options;
        super(superOptions);
        this._trainingSetId = trainingSetId;
        this._generatorOnly = generatorOnly;
    }

    matches(item: AdobeAsset) {
        if (!isCustomModel(item)) {
            return false;
        }

        if (this._trainingSetId && this._trainingSetId !== item.trainingSetInfo.id) {
            return false;
        }

        if (this._generatorOnly && !item.hasDefaultGeneratorPermissions) {
            return false;
        }

        return super.matches(item);
    }
}
