// Link for the projects service v3 API spec: https://developers.corp.adobe.com/ccteams/src/main/resources/static/openapi/v3/index.yaml

type IPageOptions = {
    start: number;
    limit: number;
}

interface IListingOptions<IOrderField> extends IPageOptions {
    orderDirection: IOrderDirection;
    orderBy: IOrderField;
}

export interface ProjectsListingOptions extends IListingOptions<IProjectsOrderBy> {
    // Projects service allows certain properties to be embedded in the response as '_embedded' property in each child
    embed?: IProjectsEmbeddableResource;

    // filters out the projects based on the view. Gives all the results if not specified
    view?: IProjectView;

    // We need to provide support for repository ID based filtering
    // This will be required by Admin console to narrow results to a specific organization
    repositoryId?: string;

    // String search term mostly used by AdminConsole.
    nameContains?: string;

    // Filters Projects by a comma-delimited list of repo:ownerIDs, which can be userIds or orgIds
    ownerId?: string;

    // Will fetch projects are discarded or not
    isDiscarded?: boolean;

    // Filters the listed values based on the sub type. Accepts multiple comma-separated values.
    // For the first iteration, the two supported options are wfProject and ccProject, the others
    // will be supported in the near future.
    directorySubtypes?: ProjectDirectorySubtype[];
}

export type RecentProjectsListingOptions = {
    // we won't be using after as we always get the next page link from the response
    after?: string;
    first?: number;
    embed?: IProjectsEmbeddableResource;
}
export interface IContextAPIResponse {
    'repo:assetId': string;
}

export const DefaultEmbeddedResources: IProjectsEmbeddableResource = [
    RelType.AC_EFFECTIVE,
    RelType.APP_METADATA,
    RelType.PROJECTS_CREATOR,
    RelType.REPOSITORY
];

const DefaultProjectsListingOptions: ProjectsListingOptions = {
    orderDirection: 'ascending',
    orderBy: 'repo:name',
    start: 0,
    limit: 0,
    // we want to embed all the resources by default
    embed: DefaultEmbeddedResources,

    // The default use case is to show all active project projects.
    isDiscarded: false
};

const DefaultRecentProjectsListingOptions: RecentProjectsListingOptions = {
    first: 10,
    // we want to embed all the resources by default
    embed: DefaultEmbeddedResources
};

function getDirectionValue<IOrderField>(userOptions: IListingOptions<IOrderField>) {
    const directionFlag = userOptions.orderDirection === 'ascending' ? '+' : '-';
    return directionFlag + userOptions.orderBy;
}

function createPageTemplate(options: IPageOptions) {
    const templateValues: any = {};
    if (options.start) {
        templateValues.start = options.start;
    }
    if (options.limit) {
        templateValues.limit = options.limit;
    }
    return templateValues;
}

export function getProjectsListingPath(links: IProjectsIndexLinks, options?: Partial<ProjectsListingOptions>): string {
    const userOptions: ProjectsListingOptions =  { ...DefaultProjectsListingOptions, ...options };
    const templateValues: any = createPageTemplate(userOptions);
    templateValues.orderBy = getDirectionValue(userOptions);
    const { embed, view, repositoryId, ownerId, nameContains, isDiscarded, directorySubtypes } = userOptions;
    if (embed?.length) {
        templateValues.embed = embed.join(',');
    }
    if (view) {
        templateValues.view = view;
    }
    if (repositoryId) {
        templateValues.repositoryId = repositoryId;
    }

    // No default value for namContains so
    // just pull the value from the filter.
    if (nameContains) {
        templateValues.nameContains = nameContains;
    }

    if (ownerId) {
        templateValues.ownerId = ownerId;
    }

    if (isDiscarded) {
        templateValues.state = 'discarded';
    }

    if (directorySubtypes) {
        templateValues.directorySubtype = directorySubtypes.join(',');
    }

    return getURLFromLinks(links, RelType.PROJECTS_COLLECTION, templateValues);
}

function validateRequiredProjectLinks(links: any) {
    return validateLinks(links, PROJECTS_INDEX_LINKS);
}

/**
 * Small utility function that returns an OpPatch operation
 * for gradients. Seperated to make it easier to share here and
 * in tests.
 *
 * @param path
 * @param gradientID
 * @returns
 */
export function getProjectGradientPatchOP(path: string, gradientID: string): jsonpatch.OpPatch {
    return {
        'op': 'replace',
        path,
        'value': gradientID
    };
}

export function getRecentProjectsListingURL(links: IProjectsIndexLinks, options?: Partial<RecentProjectsListingOptions>): string {
    const userOptions =  { ...DefaultRecentProjectsListingOptions, ...options };
    const templateValues: any = {};
    if (userOptions.after) {
        templateValues.after = userOptions.after;
    }
    if (userOptions.first) {
        templateValues.first = userOptions.first;
    }
    if (userOptions.embed?.length) {
        templateValues.embed = userOptions.embed.join(',');
    }
    return getURLFromLinks(links, RelType.PROJECTS_RECENT, templateValues);
}

// Exporting the path to make it easier to use in tests as well.
export const CSC_PROJECT_CREATE_ENDPOINT_PATH = '/api/v3/internal/csc-projects/:create';

export interface ICSCProjectCreateMetadata {
    [RelType.APP_METADATA]?: Record<string, any>;
    'repo:name': string;
    'project:directorySubtype': string;
    'repo:path'?: string;
    'repo:assetId'?: string;
}

export interface ICSCProjectBase {
    projectDirectorySubType: ProjectDirectorySubtype;
    name: string;
    /**
     * An object value with open-ended schema to support including additional properties to the application metadata of
     * the Project. The purpose of this property is for Workfront to set some of their metadata on the
     *  Project. Any property names that will conflict with Project app metadata will be overwritten.
     */
    appMetadata?:  Record<string, any>;
}

interface ICSCProjectWithPath extends ICSCProjectBase {
    /**
     * The path of directories leading to the Project. This does not represent the entire path, but only the directories
     * that should be created. This should include the Project name as the final segment of the path.
     * If both this parameter and the repo:assetId are provided or the provided repo:path
     * contains an existing Project, then an error will be returned.
     */
    path: string;
    parentAssetId?: never;
}

interface ICSCProjectWithParent extends ICSCProjectBase {
    /**
     * The asset ID of the Project that the new Project should be created within.
     * The Project will be validated to ensure that it is of subType "wfPortolio" or "wfProgram".
     * If this parameter is not provided, then the Project will be created starting from the top-level.
     * If both this parameter and the "repo:path" are provided, then an error will be returned (see Response).
     */
    parentAssetId: string;
    path?: never;
}

type ICSCProjectCreate = ICSCProjectWithPath | ICSCProjectWithParent;

export default class ProjectsInterface extends InterfaceBase {

    @cache(validateRequiredProjectLinks)
    private async _discoverLinks(@key rootHref: string): Promise<IProjectsIndexLinks> {
        const response: IProjectsIndexResponse = await this._getResponse(rootHref);
        return response._links;
    }

    private _getEndpointHref(endpoint: string): string {
        return `https://${this._core._environment.endpoints.PROJECTS_HOST}${endpoint}`;
    }

    private _getCreateEndpointHref() {
        // At the moment we don't need to worry about the region since
        // the services will likely not be located in various regions at the moment
        // so that optimizations is not necessary, it may change in the future if
        // those reqs arise.

        // This is also a well known URL
        return this._getEndpointHref(CSC_PROJECT_CREATE_ENDPOINT_PATH);
    }

    /**
     *
     * @package Internal use only
     */
    async _discoverProjectLinks(): Promise<IProjectsIndexLinks> {
        return this._discoverLinks(this._getEndpointHref(`/api/v3/index`));
    }

    /**
     * Fetches the list of projects based on the options provided
     * @param options : options to sort and filter the projects listing
     * @returns the list of projects along with the page information and links to the next page
     */
    async getProjects(options: Partial<ProjectsListingOptions>, resource?: Resource<Response>): Promise<IProjectsResponse> {
        const links = await this._discoverProjectLinks();
        const url = getProjectsListingPath(links, options);
        return await this._getResponse(url, { resource });
    }

    /**
     * Fetches the list of recent projects based on the options provided
     * @param options : options limit and pagination
     * @returns the list of recent projects along with the page information
     */
    async getRecentProjects(options: Partial<RecentProjectsListingOptions>, resource?: Resource<Response>): Promise<IRecentProjectsResponse> {
        const links = await this._discoverProjectLinks();
        const url = getRecentProjectsListingURL(links, options);
        return await this._getResponse(url, { resource });
    }

    private async _getProjectLink(
        id: string,
        embed: IProjectsEmbeddableResource = DefaultEmbeddedResources
    ) {
        const links = await this._discoverProjectLinks();
        const url = getURLFromLinks(links, RelType.PROJECTS_PRIMARY, {
            assetId: id,
            ...(embed.length ? { embed: embed.join(',') } : undefined)
        });
        return url;
    }
    /**
     *
     * @param id Gets the project metadata for the given project id from the projects service
     * @param embed the resources that are to be embedded in the response. By default all the resources are embedded
     * @returns the project metadata for the given project id
     */
    async getProject(
        id: string,
        embed: IProjectsEmbeddableResource = DefaultEmbeddedResources
    ): Promise<IProject> {
        const url = await this._getProjectLink(id, embed);
        return await this._getResponse(url);
    }

    async getProjectsWithLink(pageLink: IServiceLink): Promise<IProjectsResponse> {
        return await this._getResponse(pageLink.href);
    }

    private async _getCreateLink(embed: IProjectsEmbeddableResource) {
        const links = await this._discoverProjectLinks();
        return getURLFromLinks(links, RelType.PROJECTS_CREATE, embed.length ? { embed: embed.join(',') } : undefined);
    }

    /**
     * Creates a new project
     * @param data needed to create a project like name and color
     * @param embed the resources to be returned in the response of the newly created project. By default all the
     *     resources are embedded
     * @returns the newly created project
     */
    async createProject(data: IProjectsCreateData, embed: IProjectsEmbeddableResource = DefaultEmbeddedResources): Promise<IProject> {
        const url = await this._getCreateLink(embed);

        // 403 is included as a success code below so we can special case it after _doPost returns.
        const response = await this._doPost(url, { 'Content-Type': JSON_MIME_TYPE }, JSON.stringify(data), [ 201, 403 ]);
        let jsonResponse = {} as any;

        // Use try/catch in case body is empty or not JSON. It's expected that success cases will always return
        // JSON, but not sure about all error cases. Otherwise, it could throw an exception here and hide the
        // service call that caused the problem.
        try {
            jsonResponse = await response.json();
        } catch {
            // Ignore the error here.
        }

        if (jsonResponse.status === 403) {
            if (jsonResponse.type === ProblemType.CHILDREN_LIMIT_EXCEEDED) {
                throw SAMError.create(
                    SAMErrorCode.PROJECT_LIMIT_EXCEEDED,
                    'Maximum number of Projects exceeded',
                    { response, reqId: response.headers.get('x-request-id') || '' }
                );
            } else {
                const error = SAMError.createWithResponse(response, response.url);
                this._core._environment.error(`ProjectsInterface error ${error}`);
                throw error;
            }
        }

        return jsonResponse;
    }

    /**
     * Creates a new CSC Project with the Projects Service
     *
     * The data interface is setup to only allow either a path or assetId
     * supplying both may work but fail in the services since only one of
     * these values are allowed.
     *
     */
    async createCSCProject(data: ICSCProjectCreate, orgId: string, userId?: string, renameOnConflict?: boolean): Promise<Partial<IProject>> {
        const { path, parentAssetId, projectDirectorySubType, name, appMetadata } = data;
        let projectCreateRepoData: ICSCProjectCreateMetadata = {
            'project:directorySubtype': projectDirectorySubType.toString(),
            'repo:name': name,
            ...(appMetadata ? {
                [RelType.APP_METADATA]: { ...appMetadata }
            } : {})
        };

        let createLink = this._getCreateEndpointHref();
        const url = new URL(createLink);
        const nameConflictPolicyValue = renameOnConflict ? NameConflictPolicy.RENAME : NameConflictPolicy.CANCEL;
        setURLSearchParams(url, { 'nameConflictPolicy': nameConflictPolicyValue });

        createLink = url.toString();

        if (path) {
            projectCreateRepoData = {
                ...projectCreateRepoData,
                'repo:path': path
            };
        } else {
            projectCreateRepoData = {
                ...projectCreateRepoData,
                'repo:assetId': parentAssetId
            };
        }

        // Currently there isn't a response from this API
        // in the future there may be.
        const response = await this._doPost(
            createLink,
            {
                'Content-Type': JSON_MIME_TYPE,
                'Org-Id': orgId,
                ...(userId ? { 'User-Id': userId } : {})
            },
            JSON.stringify(projectCreateRepoData),
            [ 201 ]
        );

        const responseJson = await response.json();

        // Since there isn't a response from service, we need to return
        // a partial metadata structure using the properties returned
        // from the project service.
        return responseJson;
    }

    /**
     * Find the project that matches the given name, if available
     * @param path relative path of the project, which is the project name
     * @returns data associated with the project
     */
    async resolveProjectByName(path: string): Promise<IProject> {
        const url = await this._getResolveByPathLink(path);
        return this._getResponse(url);
    }

    /**
     * Renames a project.
     * @param newName The new name for the project.
     * @param links The project links.
     * @param renameOnConflict If true, the request will be renamed if a conflict occurs.
     * If false, the request will be cancelled if a conflict occurs.
     * @returns The updated project as a promise.
     */
    async renameProject(newName: string, links: IProjectLinks, renameOnConflict: boolean): Promise<IProject> {
        const href = getURLFromLinks(links, RelType.PROJECTS_RENAME, {
            nameConflictPolicy: renameOnConflict ? NameConflictPolicy.RENAME : NameConflictPolicy.CANCEL,
            respondWith: RelType.PROJECTS_PRIMARY
        });

        const response = await this._doPost(
            href,
            { 'Content-Type': JSON_MIME_TYPE },
            JSON.stringify({ 'repo:name': newName }),
            [ 200 ]);

        let jsonResponse = {} as any;

        // Use try/catch in case body is empty or not JSON. It's expected that success cases will always return
        // JSON, but not sure about all error cases. Otherwise, it could throw an exception here and hide the
        // service call that caused the problem.
        try {
            jsonResponse = await response.json();
        } catch {
            // Ignore the error here.
        }

        return jsonResponse;
    }

    private async _getResolveByPathLink(path: string, repositoryID?: string, workspaceID?: string): Promise<string> {
        const links = await this._discoverProjectLinks();
        const url = getURLFromLinks(links, RelType.RESOLVE_PATH, {
            path,
            ...(repositoryID ? { repositoryId: repositoryID } : {}),
            ...(workspaceID ? { organizationId: workspaceID } : {})
        });
        return url;
    }

    /**
     * Validate the project name either for creation or renaming a project.
     * If the head call responds with 404, it means the project name is valid
     * and no other project exists with the same name/path.
     * 200 and 403 responses are considered name conflicts.
     * Please refer https://wiki.corp.adobe.com/display/assetscollab/Proposal%3A+Project+API+V3+-+Resolve
     * for more details.
     * @param path The relative path or absolute path of a project. If the path is relative,
     * project service prepends a prefix to form an absolute path.
     * @param options Optional validation scope. Pass `{ repositoryID }` for rename validation
     * or `{ workspaceID }` for Connected Enterprise validation. Cannot be used together.
     */
    async validateProjectName(path: string, options?: { repositoryID: string } | { workspaceID: string }): Promise<void> {
        const repositoryID = options && 'repositoryID' in options ? options.repositoryID : undefined;
        const workspaceID = options && 'workspaceID' in options ? options.workspaceID : undefined;
        const url = await this._getResolveByPathLink(path, repositoryID, workspaceID);
        await this._doHead(url);
    }

    /**
     * Discards a project.
     */
    async discardProject(id: string, links: IProjectLinks) {
        if (!links?.[RelType.DISCARD]) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, `Discard link is missing for this project${id}`);
        }

        const href = getURLFromLinks(links, RelType.DISCARD);
        await this._doPost(
            href,
            undefined,
            undefined,
            [ 204 ]
        );
    }

    /**
     * Restores a project.
     * @param id The ID of the project to restore.
     * @param links The links associated with the project, we use the restore link to restore the project.
     * @return The restored project.
     */
    async restoreProject(id: string, links: IProjectLinks): Promise<IProject> {
        if (!links?.[RelType.RESTORE]) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, `Restore link is missing for this project${id}`);
        }
        const href = getURLFromLinks(links, RelType.RESTORE, {
            respondWith: RelType.PROJECTS_PRIMARY
        });

        const response = await this._doPost(
            href,
            undefined,
            undefined,
            [ 200 ]
        );

        let jsonResponse = {} as any;

        // Use try/catch in case body is empty or not JSON. It's expected that success cases will always return
        // JSON, but not sure about all error cases. Otherwise, it could throw an exception here and hide the
        // service call that caused the problem.
        try {
            jsonResponse = await response.json();
        } catch {
            // Ignore the error here.
        }

        return jsonResponse;
    }

    _gradientResourcesByLanguage = new Map<string, Resource<IGradientsResponse>>();

    /**
     * Get a Resource representing the gradients available for a given language.
     * By using separate resources for each language, we can more easily cache them,
     * rather than one Resource that can vary by language.
     */
    getGradientsResource(language: string) {
        let resource = this._gradientResourcesByLanguage.get(language);
        if (!resource) {
            let loadedOnceThisSession = false;
            resource = new Resource<IGradientsResponse>(this._core, {
                // Since gradients vary by language using the same URL,
                // we need to include the language in the cache key.
                getCacheKey: (method, href) => `${method}-${href}-${language}`,
                skipRevalidation: () => loadedOnceThisSession,
                onChange: async (_response, flags) => {
                    if (!flags?.loading) {
                        loadedOnceThisSession = true;
                    }
                },
                loadData: async () => {
                    const url = await this._getGradientsLink();
                    await this._doGet(url, {
                        headers: {
                            'Content-Type': JSON_MIME_TYPE,
                            'Accept-Language': language
                        },
                        resource
                    });
                },
            });
            this._gradientResourcesByLanguage.set(language, resource);
        }
        return resource;
    }

    private async _getGradientsLink() {
        const links = await this._discoverProjectLinks();
        const url = getURLFromLinks(
            links,
            RelType.PROJECTS_GRADIENTS_COLLECTION,
        );
        return url;
    }

    @synchronized
    async getGradients(
        languageCode: string
    ): Promise<IGradientsResponse> {
        const resource = this.getGradientsResource(languageCode);
        return await resource.get({ });
    }

    async patchProject(links: IProjectLinks, data: IProjectPatchData) {
        const jsonData: jsonpatch.OpPatch[] = [];

        if (data.gradientID) {
            jsonData.push(getProjectGradientPatchOP(IProjectPatchKeys.GRADIENT_ID, data.gradientID));
        }

        const url = getURLFromLinks(links, RelType.APP_METADATA);
        await this._doPatch(url, { 'Content-Type': JSON_PATCH_MIME_TYPE, 'If-Match': '*' }, JSON.stringify(jsonData), [ 204 ]);
    }

    private async _getCapabilityLink(capability: ProjectCapabilities, repositoryID?: string) {
        const links = await this._discoverProjectLinks();
        return getURLFromLinks(links, RelType.PROJECTS_CAPABILITY, {
            privilege: capability,
            // @TODO We need change all instances of repositoryID to repositoryId
            // in order to prevent some bugs in the future and keep the naming consistent.
            ...(repositoryID ? { repositoryId: repositoryID } : {})
        });
    }

    async getCapability(capability: ProjectCapabilities, repositoryID?: string) {
        const url = await this._getCapabilityLink(capability, repositoryID);

        try {
            await this._doGet(url);
        } catch (e) {
            // If the error is not a SAMError then we can
            // just throw it normally. We don't want to obfuscate a regular error
            // that could occur just because it's not a SAMError.
            if (!isSAMError(e)) {
                throw e;
            }

            const samError = e as SAMError;
            const errorResponse = samError._additionalInfo.response;

            // If the response is not defined then let's just
            // throw the error as well since it's not an error created by
            // a response from a request in SAM.
            if (!errorResponse) {
                throw e;
            }

            const failedResponseCode = [ 404, 403 ];
            if (!failedResponseCode.includes(errorResponse.status)) {
                throw e;
            }

            const responseJson: IProjectsServiceErrorResponse = await errorResponse.json();
            switch (responseJson.type) {
            case ProblemType.ADMIN_ONLY:
                throw SAMError.create(
                    SAMErrorCode.ACCESS_DENIED,
                    'Admin disabled creation of projects for user',
                    undefined,
                    SAMErrorSubCode.PROJECTS_ADMIN_ONLY
                );
            case ProblemType.NO_HOME_REPOSITORY:
                throw SAMError.create(
                    SAMErrorCode.NOT_FOUND,
                    'No home repository for the user',
                    undefined,
                    SAMErrorSubCode.PROJECTS_NO_HOME_REPOSITORY
                );
            case ProblemType.INVALID_HOME_REPOSITORY:
                throw SAMError.create(
                    SAMErrorCode.NOT_FOUND,
                    'Invalid home Repository for the user',
                    undefined,
                    SAMErrorSubCode.PROJECTS_INVALID_REPOSITORY
                );
            default:
                throw e;
            }
        }
    }

    /**
     * Creates a new library reference
     * See https://git.corp.adobe.com/pages/stormcloud/ccteams/docs/reference/api/v3/#tag/relreferences for more details
     * @param assetId the id of the asset to create a reference for
     * @param links the links associated with the project, we use the create reference link
     * @returns IProjectCreateReferenceResponse representing the newly created reference
     */
    async createLibraryReference(assetId: string, links: IProjectLinks): Promise<IProjectCreateReferenceResponse> {
        const href = getURLFromLinks(links, RelType.PROJECTS_REFERENCE_CREATE);
        const response = await this._doPost(href, { 'Content-Type': JSON_MIME_TYPE }, JSON.stringify({ 'project:referenceId': assetId }), [ 201 ]);
        return response.json();
    }

    /**
     *
     * @package Internal use only
     *
     */
    async _issueContextAPIRequest(assetId: string, repoId: string, href: string) {
        const body = JSON.stringify({
            'repo:assetId': assetId,
            'repo:repositoryId': repoId
        });
        const response = await this._doPost(href, {
            'Content-Type': 'application/json'
        }, body, [ 200 ]);
        return response.json();
    }

    private async _getOrganizationsCollectionLink() {
        const links = await this._discoverProjectLinks();
        return getURLFromLinks(links, RelType.ORGANIZATIONS_COLLECTION);
    }

    @synchronized
    async getOrganizations(resource: Resource<IOrganizationsResponse>): Promise<void> {
        const url = await this._getOrganizationsCollectionLink();
        await this._doGet(url, { resource });
    }

    /**
     * Move a CSC Project to a new location
     *
     * @note - The projects service currently doesn't return Project Metadata in the response
     * but that should be fixed in the future.
     *
     * @param targetProjectId The ID of the project to move to
     * @param links The links associated with the project, we use the move link to move the project
     * @param renameOnConflict If true, the project will be renamed by ACP if a conflict occurs.
     */
    async moveCSCProject(targetProjectId: string, links: IProjectLinks, renameOnConflict?: boolean): Promise<void> {
        const url = getURLFromLinks(links, RelType.PROJECTS_MOVE, {
            nameConflictPolicy: renameOnConflict ? NameConflictPolicy.RENAME : NameConflictPolicy.CANCEL
        });
        await this._doPost(url, {
            'Content-Type': JSON_MIME_TYPE,
        },
        JSON.stringify({
            target: {
                'repo:assetId': targetProjectId
            }
        }), [ 200, 204 ]
        );
    }

    async deleteLibraryReference(assetId: string, links: IProjectLinks): Promise<void> {
        const href = getURLFromLinks(links, RelType.PROJECTS_REFERENCE_PRIMARY, { referenceId: assetId });
        await this._doDelete(href, { 'Content-Type': JSON_MIME_TYPE }, [ 204 ]);
    }
}
