import type { IGetUSSResults, IUSSLoader } from './USSLoaderHelper';
import USSLoaderHelper from './USSLoaderHelper';
import type { DiscardedAdobeAssetConfig } from './DiscardedAdobeAssetSource';
import type { USSAdobeAssetUpdaterMetadata } from './AdobeAsset';
import type AdobeAsset from './AdobeAsset';
import type ItemPool from '../core/ItemPool';
import type { USSMetadata, USSResponse } from '../interface/USSModel';
import type { IItemLoaderOptions } from '../core/ItemLoader';
import type { ILoadedPage } from '../core/ItemLoader';
import type DiscardedInterface from '../interface/DiscardedInterface';
import { RelType } from '../interface/LinkUtils';
import type { AssetLinks } from '../interface/RepositoryModel';
import type { ISAMCorePrivate } from '../indexPrivate';
import type LibraryContext from '../libraries/LibraryContext';
import type Project from '../projects/Project';
import type { IUpdateSession } from '../core/UpdateSession';
export default class DiscardedAdobeAssetLoader implements IUSSLoader<DiscardedAdobeAssetConfig> {
    private _ussLoaderHelper: USSLoaderHelper<DiscardedAdobeAssetConfig>;
    /**
      * @package -- only for use in SAM.js
      */
    _libraryContext?: LibraryContext;
    constructor(
        assetPool: ItemPool<AdobeAsset>,
        private _core: ISAMCorePrivate,
        private _discardedInterface: DiscardedInterface
    ) {
        this._ussLoaderHelper = new USSLoaderHelper<DiscardedAdobeAssetConfig>(assetPool, _core, this);
    }

    supportsFilter(filter?: DiscardedAdobeAssetConfig['filter']): boolean {
        return filter !== undefined;
    }

    async loadPage(options: IItemLoaderOptions<DiscardedAdobeAssetConfig>): Promise<ILoadedPage<DiscardedAdobeAssetConfig>> {
        // Start prefetching data for the discarded source but don't block on it
        // since this will be needed shortly for the discarded source and even if this finishes before
        // the call to loadPage, the data will be available in the cache so the AdobeAssetFactory will get it from cache
        // and set the restore permissions on the project. If this finishes after loadPage, this method will also look
        // at the item pool for projects and set the restore permissions on each one found.
        this._discardedSourcePrefetch();

        if (!this._libraryContext) {
            this._libraryContext = await this._core.getLibraryContext();
        }

        return await this._ussLoaderHelper.loadPage(options);
    }

    /**
     * @package -- for internal SAM.js use only
     */
    private async _discardedSourcePrefetch() {
        const projectContext = await this._core.getProjectContext();

        const assetContext = await this._core.getAssetContext();
        const projectIndexPromise = projectContext._prefetchIndex();
        const repositoriesPromise = assetContext._getListOfRepositoryIDs();

        const results = await Promise.all([ projectIndexPromise, repositoriesPromise ]);

        const canRestorePromises: Promise<boolean>[] = [];
        const repositories = results[1];

        repositories?.forEach(repository => canRestorePromises.push(projectContext._canRestoreProject(repository)));
        await Promise.all(canRestorePromises);
        const session = projectContext._assetPool.createUpdateSession();
        projectContext._assetPool.forEach(item => {
            if (item.isProject) {
                const project = item as Project;
                project._applyRestorePermission(session as IUpdateSession<Project>);
            }
        });
        session.commit();
    }

    _getUSSResults({
        start,
        loadOptions,
        mediaTypes,
        excludeMediaTypes,
        order,
        resource
    }: IGetUSSResults<DiscardedAdobeAssetConfig>): Promise<USSResponse> {
        return this._discardedInterface.getDiscardedAssets({
            start,
            limit: loadOptions?.limit,
            orderBy: order.field,
            orderDirection: order.direction,
            mediaTypes,
            excludeMediaTypes
        }, resource);
    }

    _getItemData(item: Partial<USSMetadata>): USSAdobeAssetUpdaterMetadata {
        // TODO: come up with proposal for Melville to provide rendering service for non-image LEs
        // Colors/gradients have RENDITION links that cause 404 error. Clear them out so that
        // AdobeAsset does not try to fetch their renditions.

        const LERenditionURL = item.creative_cloud_colortheme || item.creative_cloud_gradient
            ? undefined
            : item._links?.[RelType.RENDITION];

        const isArchivedLibraryElement = item.asset_sub_type === 'element';
        if (isArchivedLibraryElement) {
            item._links = {
                ...(item._links || {}),
                [RelType.RENDITION]: LERenditionURL
            } as AssetLinks;
        }
        return {
            ...item,
            isArchivedLibraryElement
        };
    }
}
