import mobXRegistry from './mobXRegistry';

/**
 * Our @observable decorator is not actually making the property observable via MobX's @observable decorator. Instead,
 * it manually hooks into MobX through mobXRegistry.reportObserved, allowing custom event-based tracking.
 * It works more like @computed in terms of where you'd apply it (getters), but only triggers reactions
 * when the listed events are fired on the this context. So if you return a new array every time in the getter,
 * it will not trigger updates unless one of the listed events ("change" by default) is reported
 * via mobXRegistry.reportObserved(this, event) and mobXRegistry.reportChanged(this, event) is called elsewhere.
 */


type DecoratorArgs = [target: any, key: string, descriptor: PropertyDescriptor];
type BindingArgs = [...events: string[]];
type Decorator = (target: any, key: string, descriptor: PropertyDescriptor) => void;

const isDecoratorArgs = (args: DecoratorArgs | BindingArgs): args is DecoratorArgs => typeof args[0] !== 'string';

function getObservableDecorator(...events: string[]) {
    return function (target: any, key: string, descriptor: PropertyDescriptor) {
        const bindingKey = descriptor.get ? 'get' : descriptor.value ? 'value' : undefined;

        if (bindingKey) {
            const method = descriptor[bindingKey];

            descriptor[bindingKey] = function (this: any, ...args: any[]) {
                for (const event of events) {
                    // The mobX target observed will be the 'this' context (i.e. the class containing the method being decorated)
                    mobXRegistry.reportObserved(this, event);
                }
                return method.apply(this, args);
            };
        }
    };
}

// Overload 1: can call with events. e.g. const myDecorator: Decorator = observable('event1', 'event2');
export default function observable(...events: string[]): Decorator;
// Overload 2: can call as a decorator above a method:  @observable.
export default function observable(target: any, key: string, descriptor: PropertyDescriptor): void;
// Implementation overload: observable([target, key, descriptor]) or observable(['event1', 'event2']);
export default function observable(...args: DecoratorArgs | BindingArgs) {
    if (isDecoratorArgs(args)) {
        // Default to listening to change events on the target
        return getObservableDecorator('change')(...args);
    }

    return getObservableDecorator(...args);
}

export function transaction(fn: () => unknown) {
    return mobXRegistry.transaction(fn);
}
