import { ONS_MONITORING_STATUS_CHANGED, OnsMonitoringStatus, ONSMonitoringStatusChangedEvent } from './ONSEvent';
import type { ONSFirstLongPollCompletedEvent, ONSFirstLongPollStartedEvent } from './ONSEvent';
import { ONS_FIRST_LONG_POLL_COMPLETED, ONS_FIRST_LONG_POLL_STARTED } from './ONSEvent';
import type { default as ISAMCorePrivate } from '../core/ISAMCorePrivate';
import { ONSLongPollWorker } from './ONSLongPollWorker';
import { CHANGE } from '../core/ChangeEvent';
import { getURLFromLinks, RelType } from '../interface/LinkUtils';
import { synchronized, cache, key } from '../core/decorators';
import type { ONSWorkerEventMap, ONSWorkerInterface } from './ONSWorker.interface';
import { ONS_AUTH_HEADER } from './ONSWorker.interface';
import { ONSAxonWorker } from './ONSAxonWorker';
import { SAMObjectEventEmitter } from '../core/SAMObjectEventEmitter';
import { Logger } from '@ccx-public/axon-client';
import type { Loggable } from '@ccx-public/axon-client';
import type { ONSObjectMap, SubscriptionConfig } from './ONSSubscription';
import { Env } from '../core/Environment';
import { SAMError, SAMErrorCode } from '../core/SAMError';

// This is the data used by SAM.js that's expected from ONS service, there are considerably more properties in the
// actual response.
export interface ONSDiscoveryDocument {
    config: {
        subscriptions: {
            maxAssetsPerRequest: number;
            maxSubscriptionPerLongPoll: number;
            onsAxonServiceName: string;
        }
    };
    _links: {
        'notifications/longpoll': {
            href: string;
            templated: true;
        }
    }
}

const REQUIRED_LINKS: RelType[] = [ RelType.SUBSCRIPTION_CREATE, RelType.ONS_CHANGELOG ];
const validateRootDocument = (json: any) => json._links && REQUIRED_LINKS.every(key => json._links[key]);

interface OnsContextEventMap extends ONSWorkerEventMap {
    [ONS_FIRST_LONG_POLL_STARTED]: ONSFirstLongPollStartedEvent;
    [ONS_FIRST_LONG_POLL_COMPLETED]: ONSFirstLongPollCompletedEvent;
    [ONS_MONITORING_STATUS_CHANGED]: ONSMonitoringStatusChangedEvent;
}

/**
 * Provides SAM context for Object Notification System (ONS).
 */
export class ONSContext extends SAMObjectEventEmitter<OnsContextEventMap> implements Loggable {
    private readonly _logger: Logger;
    private _useAxon: boolean;
    private _onsLongPollWorker: ONSWorkerInterface | undefined;
    private _onsAxonWorker: ONSWorkerInterface | undefined;
    private _isStarted = false;
    private _stopTimeout?: ReturnType<typeof setTimeout>;
    private _subscribedObjects: ONSObjectMap = new Map();
    private _onsMonitoringStatus: OnsMonitoringStatus = OnsMonitoringStatus.Unknown;

    constructor(core: ISAMCorePrivate,
        // @TODO SAM-2845 This may be enabled the same in the future but working
        // with the SharedWorker. For now we want to return undefined.
        private readonly _cacheEnabled: boolean = core._environment.getValue('ENABLE_ONS_CACHE')) {
        super(core);
        this._useAxon = core._environment.getValue('ONS_OVER_AXON');
        this._logger = new Logger('ONS', core._environment.logSink);
        if (this._core._environment.getValue('ENVIRONMENT') === Env.Stage) {
            // While on Stage, elevate the default log-level to DEBUG.
            this._logger.logLevel = Logger.LogLevel.DEBUG;
        }
        this.onsMonitoringStatus = OnsMonitoringStatus.Inactive;
    }

    // Sync ONS Monitoring Status with the ONS Worker.
    private _onONSMonitoringStatusChanged = (event: ONSMonitoringStatusChangedEvent) => {
        this.logDebug(`ONS Monitoring Status changed to '${OnsMonitoringStatus[event.status]}'.`);
        this.onsMonitoringStatus = event.status;
    };

    /**
     * Gets the current status of the ONS monitoring.
     */
    get onsMonitoringStatus(): OnsMonitoringStatus {
        return this._onsMonitoringStatus;
    }

    /**
     * Sets the current status of the ONS monitoring.
     */
    set onsMonitoringStatus(status: OnsMonitoringStatus) {
        if (this.onsMonitoringStatus === status) {
            return; // Ignore duplicate events.
        }
        this._onsMonitoringStatus = status;
        this.emit(ONS_MONITORING_STATUS_CHANGED, new ONSMonitoringStatusChangedEvent(status));
    }

    /**
     * Whether to use Axon as the transport mode for ONS.
     */
    get useAxon(): boolean {
        return this._useAxon;
    }

    /**
     * Enables or disables the use of Axon as the transport mode for ONS.
     * @param newValue A boolean indicating whether to use Axon Virtual Connection. If false, Long Poll is used.
     */
    set useAxon(newValue: boolean) {
        this.logInfo(`Setting ONS Context transport mode to ${newValue ? 'Axon' : 'Long Poll'}.`);
        if (this._useAxon === newValue) { return; }
        this.reinitialize(newValue);
    }

    /**
     * Gets the logger.
     */
    get logger(): Logger {
        return this._logger;
    }

    /**
     * Whhether the cache is enabled.
     */
    get cacheEnabled(): boolean {
        return this._cacheEnabled;
    }

    /**
     * Whether the ONS Worker is active.
     */
    get isActive(): boolean {
        if (this._useAxon && this._onsAxonWorker || !this._useAxon && this._onsLongPollWorker) {
            return this.worker.isActive;
        }
        return false;
    }

    /**
     * Whether the ONS Context is started.
     */
    get isStarted(): boolean {
        return this._isStarted;
    }

    // TODO: [SHARED-4061] Improve readability of the following code. Note that worker should not be initialize
    // only to check if it's active. This is a temporary solution until we have a better way to check if the worker is active.
    get worker(): ONSWorkerInterface {
        return this._useAxon ? this._getAxonWorker() : this._getLongPollWorker();
    }

    private get _document(): Document | undefined {
        if (typeof window === 'object' && window !== null && window.document instanceof Document) {
            return window.document;
        }
        return undefined;
    }

    private get _documentSupportsVisibility(): boolean {
        const document = this._document;
        if (!document) { return false; }
        if (typeof document.addEventListener !== 'function' ||
            typeof document.removeEventListener !== 'function') {
            return false;
        }
        if (typeof document.visibilityState !== 'string') {
            return false;
        }
        if (typeof document.onvisibilitychange !== 'object') {
            return false;
        }
        return true;
    }

    private _getAxonWorker(): ONSWorkerInterface {
        if (this._onsAxonWorker) {  // Ensure to maintain a singleton instance.
            return this._onsAxonWorker;
        }
        this._onsAxonWorker = new ONSAxonWorker(this);
        this.onsMonitoringStatus = OnsMonitoringStatus.Inactive;
        this._onsAxonWorker.on(ONS_MONITORING_STATUS_CHANGED, this._onONSMonitoringStatusChanged);

        return this._onsAxonWorker;
    }

    private _getLongPollWorker(): ONSWorkerInterface {
        if (this._onsLongPollWorker) {  // Ensure to maintain a singleton instance.
            return this._onsLongPollWorker;
        }
        this._onsLongPollWorker = new ONSLongPollWorker(this);
        this.onsMonitoringStatus = OnsMonitoringStatus.Inactive;
        this._onsLongPollWorker.on(ONS_MONITORING_STATUS_CHANGED, this._onONSMonitoringStatusChanged);
        this._onsLongPollWorker.on(CHANGE, (event) => {
            this.emit(CHANGE, event);
        });
        this._onsLongPollWorker.on(ONS_FIRST_LONG_POLL_STARTED, (event) => {
            this.emit(ONS_FIRST_LONG_POLL_STARTED, event);
        });
        this._onsLongPollWorker.on(ONS_FIRST_LONG_POLL_COMPLETED, (event) => {
            this.emit(ONS_FIRST_LONG_POLL_COMPLETED, event);
        });
        this._onsLongPollWorker.on('aborted', () => {
            this.emit('aborted');
        });
        this._onsLongPollWorker.on('notified', () => {
            this.emit('notified');
        });
        return this._onsLongPollWorker;
    }

    /**
     * Cleanly (re)initializes the ONS Context for the selected transport mode (Axon vs Long Poll).
     * @param useAxon A boolean indicating whether to use Axon Virtual Connection. If false, Long Poll is used.
     */
    @synchronized
    async reinitialize(useAxon: boolean = this._useAxon) {
        const newModeName = useAxon ? 'Axon' : 'Long Poll';
        this.logInfo(`Reinitializing ONS Context Process for transport mode: ${newModeName}...`);
        const errorHandler = (error: unknown) => {
            const errorMessage = `Error initializing ONS Context for transport mode: ${newModeName}`;
            this.logError(errorMessage, error);
        };
        const wasStarted = this.isStarted;
        await this._deinitialize()
            .then((result) => {
                if (!result) {
                    throw new Error('Failed to deinitialize ONS Context');
                } else {
                    this.logInfo('ONS Context deinitialized.');
                }
            })
            .catch(errorHandler);
        this._useAxon = useAxon;
        if (this._core._environment.getValue('DISABLE_ONS')) {
            return; // If ONS is disabled, don't start the ONS Context.
        }
        await this.watch(this._subscribedObjects)
            .then(() => {
                this.logInfo('ONS Context reinitialized.');
            }).catch(errorHandler);
        if (wasStarted) { await this.start(); }
    }

    /**
     * Ensures that the ONS Context is initialized and the underlying connection to ONS is active.
     * @returns A promise that resolves to true if the ONS Context is initialized, false otherwise.
     */
    @synchronized
    async ensureInitialized(): Promise<boolean> {
        try {
            return this.worker.ensureReady();
        } catch (error) {
            this.logError('Failed to initialize ONS Axon Worker', error);
            return false;
        }
    }

    /**
     * Deinitializes the ONS Context and closes the underlying connection to ONS.
     * @returns A promise that resolves to true if the ONS Context is deinitialized, false otherwise.
     * @package -- only for use in SAM.js
     */
    @synchronized
    async _deinitialize(): Promise<boolean> {
        this.logInfo('Deinitializing ONS Context...');
        if (this.isStarted) { this.stop(); }
        const result = this.worker.deinitialize();
        this.worker.off(ONS_MONITORING_STATUS_CHANGED, this._onONSMonitoringStatusChanged);
        if (this._useAxon) {
            this._onsAxonWorker = undefined;
        } else {
            this._onsLongPollWorker = undefined;
        }
        this.onsMonitoringStatus = OnsMonitoringStatus.Unknown;
        return result;
    }

    private _onVisibilityChange = () => {
        if (this._stopTimeout) {
            clearTimeout(this._stopTimeout);
            this._stopTimeout = undefined;
        }
        if (this._document?.visibilityState === 'visible') {
            this.worker.start(); // Won't do anything if we didn't stop yet, since still active.
        } else {
            // we're de-bouncing to avoid repeatedly stopping/restarting if the user switches between Web browser tabs frequently.
            this._stopTimeout = setTimeout(() => this.worker.stop(), this._core._environment.getValue('ONS_DOCUMENT_VISIBILITY_TIMEOUT')); // 10s
        }
    };

    /**
     * Activate ONS Context.
     */
    async start(): Promise<void> {
        if (this._isStarted) {
            this.logDebug('ONS Context is already active! Skipping activation call...');
            return;
        }
        this.logInfo('Activating ONS Context...');
        this._isStarted = true;
        if (this._documentSupportsVisibility) {
            this._document?.addEventListener('visibilitychange', this._onVisibilityChange);
        }
        if (!this._documentSupportsVisibility || this._document?.visibilityState === 'visible') {
            return this.worker.start();
        }
    }

    /**
     * Deactivate ONS Context.
     */
    stop() {
        if (!this._isStarted) {
            this.logDebug('ONS Context is inactive! Skipping deactivation call...');
            return;
        }
        this.logInfo('Deactivating ONS Context...');
        this._isStarted = false;
        if (this._documentSupportsVisibility) {
            this._document?.removeEventListener('visibilitychange', this._onVisibilityChange);
        }
        if (this._stopTimeout) {
            clearTimeout(this._stopTimeout);
            this._stopTimeout = undefined;
        }
        this.worker.stop();
    }

    /**
     * Gets the object ids currently being watched by the ONS Context.
     * @returns A set of object ids currently being watched by the ONS Context.
     */
    get watchedObjectIds(): Set<string> {
        return new Set(Array.from(this._subscribedObjects.keys()));
    }

    /**
     * Watches an array of assetIds and PLSAssetListIds.
     *
     * @param {ONSObjectMap} objects - Asset ids & PLS List ids to monitor, along with what resources to monitor
     */
    @synchronized
    async watch(objects: ONSObjectMap) {
        this._subscribedObjects = objects;
        this.logDebug(`Watching ${this._subscribedObjects.size} object(s):`, Array.from(this._subscribedObjects.keys()));
        if (await this.ensureInitialized()) {
            await this.worker.watch(this._subscribedObjects);
        } else {
            this.logError('Failed to watch assets due to ONS Context initialization error.');
        }
    }

    @cache(validateRootDocument)
    private async _getAndCacheDocument<T>(@key href: string): Promise<T> {
        const response = await this._core._environment.fetch(href, {
            headers: {
                Accept: 'application/vnd.syncservice.v2.hal+json'
            },
            authHeader: ONS_AUTH_HEADER
        });

        return response.json() as T;
    }

    private async _getSyncServiceDiscovery(): Promise<ONSDiscoveryDocument> {
        const discovery = await this._getAndCacheDocument<ONSDiscoveryDocument>(`https://${this._core._environment.endpoints.SYNC_SERVICE_HOST}/api/v1`);
        if (!this.useAxon) {
            // Ensure that the discovery comes with necessary Long Poll link.
            if (!discovery?._links?.[RelType.NOTIFICATIONS_LONGPOLL]) {
                throw SAMError.create(SAMErrorCode.UNKNOWN, 'Invalid Sync Service Discovery (Missing the required link for Long Poll).');
            }
        }
        return discovery;
    }

    async getSubscriptionConfig(): Promise<SubscriptionConfig> {
        try {
            const rootDocument = await this._getSyncServiceDiscovery();
            return rootDocument?.config?.subscriptions ?? {};
        } catch (e) {
            this.logInfo(`Error fetching ONS subscription config from the Sync Service Discovery: ${e}`);
            return {};
        }
    }

    async getLink(key: RelType, options: {[s: string]: string | string[]}  = {}) {
        const rootDocument = await this._getSyncServiceDiscovery();
        return getURLFromLinks(rootDocument._links, key, options);
    }

    /**
     * Logs a debug message.
     * @param message - Message to log.
     * @param optionalParams - Optional objects to stringify and log after the message.
     */
    logDebug(message: string, ...optionalParams: any[]) {
        this._logger.logDebug(message, 'Context', ...optionalParams);
    }

    /**
     * Logs an info message.
     * @param message - Message to log.
     * @param optionalParams - Optional objects to stringify and log after the message.
     */
    logInfo(message: string, ...optionalParams: any[]) {
        this._logger.logInfo(message, 'Context', ...optionalParams);
    }

    /**
     * Logs a warning message.
     * @param message - Message to log.
     * @param optionalParams - Optional objects to stringify and log after the message.
     */
    logWarn(message: string, ...optionalParams: any[]) {
        this._logger.logWarn(message, 'Context', ...optionalParams);
    }

    /**
     * Logs an error message.
     * @param message - Message to log.
     * @param optionalParams - Optional objects to stringify and log after the message.
     * @remarks If the first optional parameter is an Error object, the message will be appended with the error message.
     */
    logError(message: string, ...optionalParams: any[]) {
        this._logger.logError(message, 'Context', ...optionalParams);
    }

}
