import type { ConnectorParam, ElementSort, GetLibraryOptions, OperationClass } from '../Driver';
import type Driver from '../Driver';
import type { Params as CloudDriverParams } from '../CloudDriver';
import CloudDriver from '../CloudDriver';
import type { LocalDriverOptions, Params as LocalDriverParams } from '../LocalDriver';
import LocalDriver from '../LocalDriver';
// @ts-expect-error R-TODO
import type Library from '../../models/Library';
import type { LibraryData } from '../../models/data/LibraryData';
import type { KeyOfType, RenditionSize } from '../../types';
import type Element from '../../models/Element';
import type Representation from '../../models/Representation';
import type Operation from '../Operation';
import type ISAMCorePrivate from '../../../core/ISAMCorePrivate';

export default class HybridDriver extends CloudDriver {
    private _localDriver: LocalDriver;

    constructor(
        core: ISAMCorePrivate,
        protected _localConnector: ConnectorParam<LocalDriverParams>,
        protected _cloudConnector: ConnectorParam<CloudDriverParams>,
        options: LocalDriverOptions = {}
    ) {
        super(core, () => _cloudConnector().then(p => ({ samDisableOns: true, ...p } as CloudDriverParams)));
        this._localDriver = new LocalDriver(core, _localConnector, {
            ...options,
            optimistic: true
        });
    }

    connect() {
        return Promise.all([ this.localDriver.connect(), super.connect() ]).then(() => {
            /** empty **/
        });
    }

    private get localDriver() {
        return this._localDriver;
    }

    private call(library: Library, fn: KeyOfType<Driver, Function>, ...args: any[]) {
        return library.locallyManaged ? (this._localDriver[fn] as Function)(...args) : (super[fn] as Function)(...args);
    }

    protected _handleDisconnected(): void {
        super._handleDisconnected();
        if (this.localDriver.isConnected) {this.localDriver.disconnect();}
    }

    setLibraryChangeListener(libraries: LibraryData[], callback: (libraryIds: string[]) => any): void {
        this.localDriver.setLibraryChangeListener(libraries, callback);
    }

    setFontDataChangeListener(callback: () => void) {
        this.localDriver.setFontDataChangeListener(callback);
    }

    removeFontDataChangeListeners(): void {
        this.localDriver.removeFontDataChangeListeners();
    }

    getLibraries() {
        return this.localDriver.getLibraries();
    }

    getLibrary(library: Library, options?: GetLibraryOptions): AsyncGenerator<Partial<LibraryData>> {
        // If the library is locally managed, or we want to download the library locally
        // utilize the local driver to return library data from disk
        if (library.locallyManaged || options?.optimisticFetch) {
            return this.localDriver.getLibrary(library, options);
        }
        // otherwise return the cloud drivers library response
        return super.getLibrary(library, options);
    }

    getElements(library: Library, sort?: ElementSort, etag?: string, limit?: number, signal?: AbortSignal) {
        return this.call(library, 'getElements', sort, etag, limit, signal);
    }

    getElement(library: Library, elementId: string) {
        return this.call(library, 'getElement', library, elementId);
    }

    async getLibraryById(id: string, options?: GetLibraryOptions) {
        // Introducing the idea of passing locallManaged to options here
        // to allow for utilizing the local driver if we know the library is local.
        // Current use cases for this utility are situations where we do not know
        // the library yet so we fall back to cloud driver in these cases.
        if (options?.optimisticFetch || options?.locallyManaged) {
            return this._localDriver._getLibraryById(id, options).next();
        }
        return super.getLibraryById(id);
    }

    getRenditionUrl(element: Element, size: RenditionSize) {
        return this.call(element.library, 'getRenditionUrl', element, size);
    }

    getRendition(element: Element, size: RenditionSize) {
        return this.call(element.library, 'getRendition', element, size);
    }

    getRepresentationContent(representation: Representation) {
        return this.call(representation.library, 'getRepresentationContent', representation);
    }

    getOperationTypes(library: Library) {
        return library.locallyManaged ? this._localDriver.getOperationTypes(library) : super.getOperationTypes(library);
    }

    operationFactory(Op: OperationClass<Driver>, driver: Driver, library: Library): Operation<Driver> {
        return new Op((library.locallyManaged ? this._localDriver : this) as Driver, library);
    }

    ignoreLocalSyncEvents(): boolean {
        return this.localDriver.isConnected ? this.localDriver.ignoreLocalSyncEvents() : super.ignoreLocalSyncEvents();
    }
}
