/**
 * IntlInterface
 * @packageDocumentation
 * @module IntlInterface
 */

import type { IntlShape } from '@formatjs/intl';
import { createIntl, createIntlCache } from '@formatjs/intl';
import Logger from './utils/Logger';

const DEFAULT_LOCALE = 'en-US';

/**
 * Set of supported locales that the jsapi has predefinds translations for.
 * Falls back on English if the locale requested does not exist in the list below.
 *
 * This may seem a little disgusting but with the typescript update (v4.9.5)
 * The ES5 target throws a wedge in dynamic imports. E.g.
 *
 * This:
 * ```
 * const locale = 'en-US';
 * async import(`./locale/${en-US}.json`)
 * ```
 *
 * Gets converted into this:
 * ```
 * var locale = 'en-US';
 * var path = './locale/'.concat(locale, '.json');
 * return Promise.resolve().then(() => require(path))
 * ```
 *
 * This breaks Webpack's dynamic import flow. It is raised as a warning but webpack attempts to
 * load the locale data from the wrong location. We then end up in a perpetual loop.
 * This needs to stay as is so the dynamic import knows exactly where to pull the files from.
 * At least till the underlying transformation is fixed.
 */
const SUPPORTED_LOCALES: Record<string, () => Promise<Record<string, any>>> = {
    'cs-CZ': () => import('./locale/cs-CZ.json'),
    'da-DK': () => import('./locale/da-DK.json'),
    'de-DE': () => import('./locale/de-DE.json'),
    'en-US': () => import('./locale/en-US.json'),
    'es-ES': () => import('./locale/es-ES.json'),
    'fi-FI': () => import('./locale/fi-FI.json'),
    'fr-CA': () => import('./locale/fr-CA.json'),
    'fr-FR': () => import('./locale/fr-FR.json'),
    'fr-MA': () => import('./locale/fr-MA.json'),
    'hu-HU': () => import('./locale/hu-HU.json'),
    'it-IT': () => import('./locale/it-IT.json'),
    'ja-JP': () => import('./locale/ja-JP.json'),
    'ko-KR': () => import('./locale/ko-KR.json'),
    'nb-NO': () => import('./locale/nb-NO.json'),
    'nl-NL': () => import('./locale/nl-NL.json'),
    'pl-PL': () => import('./locale/pl-PL.json'),
    'pt-BR': () => import('./locale/pt-BR.json'),
    'ru-RU': () => import('./locale/ru-RU.json'),
    'sv-SE': () => import('./locale/sv-SE.json'),
    'tr-TR': () => import('./locale/tr-TR.json'),
    'uk-UA': () => import('./locale/uk-UA.json'),
    'zh-CN': () => import('./locale/zh-CN.json'),
    'zh-TW': () => import('./locale/zh-TW.json'),
    'zu-ZU': () => import('./locale/zu-ZU.json'),
    'zz-ZZ': () => import('./locale/zz-ZZ.json')
} as const;

// Export supported locales as type.
export type SupportedLocale = keyof typeof SUPPORTED_LOCALES;

export default class IntlInterface {
    private _intl?: IntlShape;
    private _locale?: SupportedLocale;

    constructor(locale: SupportedLocale = DEFAULT_LOCALE) {
        this.setLocale(locale);
    }

    get locale() {
        return this._locale;
    }

    async setLocale(locale: SupportedLocale) {
        if (!SUPPORTED_LOCALES[locale]) {
            Logger.log(`[INTL] ${locale} is not a supported language. Falling back to en-US`);
            locale = DEFAULT_LOCALE;
        }
        const { messages, locale: _locale } = await this._loadLocaleData(locale);
        // We load the localized strings manually, but we still need to specify `locale`
        // for localization of non-string values like numbers, dates, etc.
        // We give a fallback `defaultLocale` to use if the given `locale` doesn't have a
        // defined localization configuration for those non-string values.
        this._intl = createIntl({ locale, messages, defaultLocale: DEFAULT_LOCALE }, createIntlCache());
        this._locale = _locale;
        return locale;
    }

    _loadLocaleData(locale: SupportedLocale): Promise<{
        messages: Record<string, string>;
        locale: SupportedLocale;
    }> {
        return SUPPORTED_LOCALES[locale]()
            .then(messages => ({ messages, locale }))
            .catch(_e => this._loadLocaleData(DEFAULT_LOCALE));
    }

    formatMessage(id: string, values?: Record<string, any>) {
        if (!this._intl) {
            Logger.log(`[INTL] no localization data loaded`);
            return;
        }
        return this._intl.formatMessage({ id }, values);
    }
}
