import type {
    CustomModelPublishedState,
    LegacyCreateTrainingSetOptions,
    LegacyCustomModelCreateOptions,
    CustomModelOrderBy,
    CustomModelsMelvilleResponse,
    CustomModelsResponse
} from './LegacyCustomModelModel';
import InterfaceBase from '../../interface/InterfaceBase';
import { fillURLTemplate } from '../../interface/LinkUtils';
import packageJSON from '../../../package.json';
import type { CreateLibraryOptions } from '../../interface/LibraryModel';
import SAMError, { SAMErrorCode } from '../../core/SAMError';
import type Library from '../../libraries/Library';
import type { IFetchOptions } from '../../core/Environment';

export const REGION_MAP: Record<string, string> = {
    VA6C2: 'va6',
    VA6: 'va6',
    VA7: 'va6',
    JPN3: 'jpn3',
    IRL1: 'irl1',
};

// define type based off of keys of REGION_MAP
type RegionKey = keyof typeof REGION_MAP;

/**
 * Returns the storage region for a given region key. The storage region is stored in the home folder and is stored as
 * an uppercase string. The mapping takes this uppercase string and returns the corresponding storage region that is used
 * to build the url to the endpoint.
 * @param region    The region key as stored in the home folder
 */
export function storageRegionForUrl(region: RegionKey): string {
    return REGION_MAP[region];
}

interface IListingOptions<IOrderField> {
    orderBy: IOrderField;
    limit: number;
}

export interface CustomModelListingOptions
    extends IListingOptions<CustomModelOrderBy> {
    startIndex?: number;
    createdBy?: string;
    name?: string;
    publishedState?: CustomModelPublishedState;
    createDateMin?: Date;
    createDateMax?: Date;
    modifyDateMin?: Date;
    modifyDateMax?: Date;
}

export default class CustomModelInterface extends InterfaceBase {
    private _getMelvilleUrl(endpoint: string): string {
        return `https://${this._core._environment.endpoints.MELVILLE_HOST}${endpoint}`;
    }

    //
    protected async _getFetchOptionOverrides(originalHref: string, originalOptions: IFetchOptions): Promise<{
        href: string;
        options: IFetchOptions
    }> {
        const { href, options } = await super._getFetchOptionOverrides(originalHref, originalOptions);
        return {
            href,
            options: {
                ...options,
                headers: {
                    ...options.headers,
                    'X-Product-Location': `SAM.js/${packageJSON.version}`
                }
            }
        };
    }

    private async _getUrl(endpoint: string): Promise<string> {
        const homeFolder = await this._core.hostAssetContext.getHomeFolder();
        const region = REGION_MAP[homeFolder.storageRegion];
        const acpHost = this._core._environment.endpoints.ACP_CS_HOST;
        const subdomain = acpHost.split('.')[0];
        const regionalizedSubdomain = `${subdomain}-${region}`;

        // Replaces non-regionalized subdomain with its' regionalized version, using the region of the homeFolder eg.
        //
        //   when storage region = 'JPN3':
        //     platform-cs-stage.adobe.io =>
        //     platform-cs-stage-${REGION_MAP[JPN3]}.adobe.com =>
        //     platform-cs-stage-jpn3.adobe.com
        //
        //   when storage region = 'IRL1':
        //     platform-cs-stage.adobe.io =>
        //     platform-cs-stage-${REGION_MAP[IRL1]}.adobe.com =>
        //     platform-cs-stage-irl1.adobe.com
        return `https://${acpHost.replace(
            subdomain,
            regionalizedSubdomain
        )}/fps/${endpoint}`;
    }

    /**
   * Fetches the list of custom models based on the options provided
   * @param options : options to sort and filter the projects listing
   * @returns the list of custom models along with the page information and links to the next page
   */
    async getCustomModels(
        options?: Partial<CustomModelListingOptions>
    ): Promise<CustomModelsResponse> {
        const queryParams = options
            ? JSON.parse(
                JSON.stringify(options)
            )
            : {};

        const url = fillURLTemplate(
            await this._getUrl('customModels'),
            queryParams
        );

        return this._getResponse(url);
    }

    /**
     * Create a training set to be used with a custom model. The training set is considered a child of the parent asset
     * specified by the parentAssetId.
     */
    async createTrainingSet(options: LegacyCreateTrainingSetOptions): Promise<Library> {
        if (!options.name) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Invalid argument: missing required name');
        }

        if (!options.projectId) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Invalid argument: missing required projectId. The parent must be a project');
        }

        if (!options['firefly#ffmodel'].schemaVersion) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Invalid argument: missing required schemaVersion.');
        }

        const creationOptions: CreateLibraryOptions = {
            name: options.name,
            parent_assetId: options.projectId,
            roles: [ {
                type: 'cm_training_set'
            } ],

            // this key is not currently used by melville but will soon be enabled
            // sending it does not affect the request
            'firefly#ffmodel': options['firefly#ffmodel'],

            // TODO: remove this when melville switches to 'firefly#ffmodel'
            'firefly#cme': {
                ...options['firefly#ffmodel'],
                version: options['firefly#ffmodel'].schemaVersion
            }
        };

        const libraryContext = await this._core.getLibraryContext();
        return libraryContext._createLibrary(creationOptions);
    }

    async getTrainingSetById(assetId: string): Promise<Library | undefined> {
        const libraryContext = await this._core.getLibraryContext();
        return libraryContext._getLibraryRemotely(assetId);
    }

    async createCustomModel(options: LegacyCustomModelCreateOptions): Promise<CustomModelsMelvilleResponse> {
        const endpoint: string = `/api/v1/custom-models`;

        const response = await this._doPost(
            this._getMelvilleUrl(endpoint),
            { 'Content-Type': 'application/json' },
            JSON.stringify(options),
            [ 201, 200 ]);

        const idString = response.headers.get('asset-id');
        if (!idString) {
            throw SAMError.create(SAMErrorCode.NOT_FOUND, 'Asset id for newly created custom model not returned by melville');
        }

        return { id: idString };
    }
}
