import LibraryError from '../errors/LibraryError';
import Logger from '../utils/Logger';

//TODO: fix this linter error when unit tests are in place
//https://jira.corp.adobe.com/browse/SHARED-4388

// eslint-disable-next-line no-useless-escape
const PATH_REGEX = /(\.[a-zA-Z0-9]+)|(\[\?\(([^\[\]]+)\)\])/g;
// eslint-disable-next-line no-useless-escape
const VALID_PATH_REGEX = /^\$(?:(\.[a-zA-Z0-9]+)|(\[\?\(([^\[\]]+)\)\]))*$/;
const EXPRESSION_REGEX = /^([^ ]+) *== *"(.+)"$/;

function validatesPath() {
    return function (target: JSONPath, propertyKey: string, descriptor: PropertyDescriptor) {
        const original = descriptor.value;

        descriptor.value = function (object: any, path: string, ...otherArgs: any[]) {
            if (!VALID_PATH_REGEX.test(path)) {
                throw new LibraryError('INVALID_PARAMETER', 'JSON Path is not valid');
            }

            return original.apply(this, [ object, path, ...otherArgs ]);
        };

        return descriptor;
    };
}

/**
 * Super-simplistic subset of JSONPath (https://goessner.net/articles/JsonPath/)
 *
 * ONLY supports:
 * dot syntax ($.fieldName)
 * simple filtering (only field to string comparison) ($[@.fieldName == '2'])
 * composition of the above ($.field[@.innerField1 == 'abc'].innerField2[@.innerInnerField1 == 'xyz'].innerInnerField2)
 *
 * The above would access:
 *
 * {
 *     field: [
 *         {
 *             innerField1: 'abc'
 *             innerField2: [
 *                 {
 *                     innerInnerField1: 'xyz',
 *                     innerInnerField2: 'foo' // <-- THIS
 *                 }
 *             ]
 *         }
 *     ]
 * }
 */
interface ParentObject<T> {
    [key: string]: T;
}

export default class JSONPath {
    @validatesPath()
    static get<T>(object: any, path: string): T | null {
        if (path === '$') {
            return object as T | null;
        }

        return path
            .match(PATH_REGEX)
            ?.reduce((memo, part) => memo && this._handlePathPart(memo, part), object) as T | null;
    }

    @validatesPath()
    static set<T>(object: any, path: string, value: T): T | undefined {
        if (path === '$') {
            throw new LibraryError('INVALID_PARAMETER', 'Cannot set in root of object');
        }

        const parts = path.match(PATH_REGEX);
        if (parts) {
            const lastPart = parts.pop();
            const parentPath = parts.join('');

            if (!lastPart) {
                throw new LibraryError('INVALID_PARAMETER', 'JSON path must end in a field');
            }

            let parent = object;

            if (parentPath) {
                parent = this.get(object, `$${parentPath}`);

                if (!parent) {
                    throw new LibraryError('INVALID_PARAMETER', 'JSON path parent does not exist');
                }
            }

            (parent as ParentObject<T>)[lastPart.substring(1)] = value;

            return value;
        }
    }

    @validatesPath()
    static insert<T>(object: any, path: string, value: T) {
        const array = this.get(object, path) ?? this.set(object, path, []);

        if (!Array.isArray(array)) {
            Logger.warn('JSONPath.insert failed to insert into non-array');
            return;
        }

        array.push(value);
    }

    @validatesPath()
    static remove(object: any, path: string): void {
        const parts = path?.match(PATH_REGEX);
        const lastPart = parts?.pop();

        const parentArray = parts?.reduce((memo, part) => memo && this._handlePathPart(memo, part), object) || [];

        if (!lastPart?.startsWith('[?(')) {
            throw new LibraryError('INVALID_PARAMETER', 'JSON Path must end in a filter');
        }

        if (!Array.isArray(parentArray)) {
            return;
        }

        const value = this._handleFilterExpression(parentArray, lastPart.substring(3, lastPart.length - 2));
        const index = parentArray.indexOf(value);

        if (index !== -1) {
            parentArray.splice(index, 1);
        }
    }

    private static _handlePathPart(object: any, part: string): any {
        if (part.startsWith('[?(')) {
            return this._handleFilterExpression(object, part.substring(3, part.length - 2));
        }

        return object[part.substring(1)];
    }

    private static _handleFilterExpression(object: any, expression: string): any {
        const [ , a, b ] = EXPRESSION_REGEX.exec(expression) || [];
        const path = a.replace(/^@/, '$');

        if (!Array.isArray(object)) {
            return undefined;
        }

        return object.find((item: any) => this.get(item, path) === b);
    }
}
