import type { IClassroomMember } from '../interface/ClassroomMemberModel';
import { ClassroomMemberRole } from '../interface/ClassroomMemberModel';
import { observable } from '../core/decorators';
import ItemBase from '../core/ItemBase';
import { ClassroomMemberStatus } from '../interface/ClassroomMemberModel';
import { ClassroomMemberInviteSource } from '../interface/ClassroomMemberModel';
import ItemUpdater from '../core/ItemUpdater';
import PropertyUpdater from '../core/PropertyUpdater';

export default class ClassroomMember extends ItemBase {
    private _classroomId: string = '';
    private _displayName: string = '';
    private _email: string = '';
    private _firstName: string = '';
    private _inviteSource: ClassroomMemberInviteSource = ClassroomMemberInviteSource.NONE;
    private _lastName: string = '';
    private _membershipStatus: ClassroomMemberStatus = ClassroomMemberStatus.NOT_A_MEMBER;
    private _role: ClassroomMemberRole = ClassroomMemberRole.NONE;
    private _userId: string = '';

    @observable
    get classroomId(): string {
        return this._classroomId;
    }

    @observable
    get displayName(): string {
        return this._displayName;
    }

    @observable
    get email(): string {
        return this._email;
    }

    @observable
    get firstName(): string {
        return this._firstName;
    }

    @observable
    get inviteSource(): ClassroomMemberInviteSource {
        return this._inviteSource;
    }

    @observable
    get lastName(): string {
        return this._lastName;
    }

    @observable
    get membershipStatus(): ClassroomMemberStatus {
        return this._membershipStatus;
    }

    @observable
    get role(): ClassroomMemberRole {
        return this._role;
    }

    @observable
    get userId(): string {
        return this._userId;
    }
}

export const ClassroomMemberUpdater = new ItemUpdater<ClassroomMember, Partial<IClassroomMember>>({
    localItemType: ClassroomMember,
    // Note that ID of classroomMember is computed, and in the format of `{classroomId}-{role}`
    remoteIdProperty: 'computedKey',
    propertyUpdater: new PropertyUpdater({
        _classroomId: { name: 'classroomId', format: 'string' },
        _displayName: { name: 'displayName', format: 'string' },
        _email: { name: 'email', format: 'string' },
        _firstName: { name: 'firstName', format: 'string' },
        _inviteSource: { name: 'inviteSource', format: 'string', choices: Object.values(ClassroomMemberInviteSource) },
        _lastName: { name: 'lastName', format: 'string' },
        _membershipStatus: { name: 'membershipStatus', format: 'string', choices: Object.values(ClassroomMemberStatus) },
        _role: { name: 'role', format: 'string', choices: Object.values(ClassroomMemberRole) },
        _userId: { name: 'userId', format: 'string' },
    }),
});
