import type Element from './Element';
import type { IImplicitFilter } from '../../core/ItemFilter';

export interface IImplicitCustomModelFilterOptions {
    libraryId?: string,
}

export default class ImplicitElementFilter implements IImplicitFilter<Element> {
    private readonly _libraryId?: string;

    constructor(options: Partial<IImplicitCustomModelFilterOptions> = {}) {
        this._libraryId = options.libraryId;
    }

    matches(item: Element) {
        return !this._libraryId || this._libraryId === item.library.id;
    }
}
