import SAMError, { SAMErrorCode } from '../SAMError';

const DEFAULT_CACHE_KEEP_ALIVE_TTL = 10 * 60 * 1000; // 10 minutes
export { DEFAULT_CACHE_KEEP_ALIVE_TTL };

/**
 * @description KeepAliveManager -- a singleton class that will keep a hard reference to objects passed to it.
 * This decorator should be used on all public context methods that return an AdobAsset.
 */
export default class KeepAliveManager {
    private static _instance: KeepAliveManager;
    private _keepAliveMap: Map<any, ReturnType<typeof setTimeout>> = new Map();
    private constructor(private _ttl: number = DEFAULT_CACHE_KEEP_ALIVE_TTL) {}

    /**
     * @description Get the singleton instance of the KeepAliveManager.
     */
    static getInstance(): KeepAliveManager {
        if (!KeepAliveManager._instance) {
            KeepAliveManager._instance = new KeepAliveManager(DEFAULT_CACHE_KEEP_ALIVE_TTL);
        }
        return KeepAliveManager._instance;
    }

    /**
     * @description Set the time to live for objects in the KeepAliveManager.
     * @param ttl The time to live in milliseconds as a non-zero integer.
     * @throws Error if ttl is less than 0.
     */
    static setTTL(ttl: number): void {
        if (ttl < 0) {
            throw SAMError.create(SAMErrorCode.UNKNOWN, 'TTL must be greater than or equal to 0');
        }
        KeepAliveManager.getInstance()._ttl = ttl;
    }

    /**
     * @description Add an object to the KeepAliveManager.
     * @param obj The object to keep alive.
     */
    add(obj: any): void {
        if (this._ttl === 0) {
            return;  // Not enabled by config
        }
        const existingTimer = this._keepAliveMap.get(obj);
        if (existingTimer) {
            clearTimeout(existingTimer);
        }
        this._keepAliveMap.set(obj, setTimeout(() => {
            this._keepAliveMap.delete(obj);
        }, this._ttl));
    }
}

/**
 * @description decorator to prevent garbage collection of a returned object for a certain amount of time.
 */
export function keepAlive(target: any, propertyKey: string, descriptor: PropertyDescriptor): void {
    const originalMethod = descriptor.value;
    descriptor.value = function (this: any, ...args: any[]) {
        const value = originalMethod.apply(this, args);
        if (value instanceof Promise) {
            value.then(
                (v) => KeepAliveManager.getInstance().add(v)
            ).catch(() => {
                // Do not re-throw.  The error will still bubble up through the decorated function
            });
        } else if ((value ?? null) !== null) {
            KeepAliveManager.getInstance().add(value);
        }
        return value;
    };
}
