export const VALID_HTTP_RESPONSE_CODES = [ 200 ];

export type ValidHttpResponseCodes = number[] | 'any';

// See https://git.corp.adobe.com/pages/caf/api-spec/chapters/responses/service_responses.html
export const RETRY_HTTP_RESPONSE_CODES = [
    429, // Too many requests -- request is valid but should be retried later
    500, // Internal service error -- may be transient, client can retry
    // 501 -- Not implemented -- client must not retry
    502, 503, 504 // Upstream service (gateways/proxies) errors -- may be transient, client can retry
    // >=505 -- other non-retryable errors
];
