import type { IItemLoader, ILoadedPage } from '../core/ItemLoader';
import type ItemPool from '../core/ItemPool';
import type ProjectInterface from '../interface/WorkspacesInterface';
import type OrgRepository from './OrgRepository';
import { OrgRepositoryUpdater } from './OrgRepository';
import type { OrgRepositoryConfig } from './OrgRepositorySource';

export default class OrgRepositoryLoader implements IItemLoader<OrgRepositoryConfig> {

    constructor(
        private _orgRepositoryPool: ItemPool<OrgRepository>,
        private _projectInterface: ProjectInterface) {
    }

    async loadPage(): Promise<ILoadedPage<OrgRepositoryConfig>> {
        const result = await this._projectInterface.getOrgRepositories();
        const session = this._orgRepositoryPool.createLoaderUpdateSession(Date.now());

        const items = OrgRepositoryUpdater.updateRemoteItems(session, result.repositories);
        session.commit();

        return { items };
    }
}
