import type PublishedInterface from '../interface/PublishedInterface';
import type { IItemLoaderOptions, ILoadedPage } from '../core/ItemLoader';
import type ItemPool from '../core/ItemPool';
import type { USSMetadata, USSResponse } from '../interface/USSModel';
import type { USSAdobeAssetUpdaterMetadata } from './AdobeAsset';
import type AdobeAsset from './AdobeAsset';
import type PublishedAdobeAssetFilter from './PublishedAdobeAssetFilter';
import type { PublishedAdobeAssetConfig } from './PublishedAdobeAssetSource';
import type { IUSSLoader, IGetUSSResults } from './USSLoaderHelper';
import USSLoaderHelper from './USSLoaderHelper';
import { OrderFieldToIUSSAdobeAssetOrderBy } from './USSAdobeAssetOrder';
import type { ISAMCorePrivate } from '../indexPrivate';
import type AdobeAssetFilter from '../assets/AdobeAssetFilter';

export default class PublishedAdobeAssetLoader implements IUSSLoader<PublishedAdobeAssetConfig> {
    private _ussLoaderHelper: USSLoaderHelper<PublishedAdobeAssetConfig>;

    constructor(
        assetPool: ItemPool<AdobeAsset>,
        core: ISAMCorePrivate,
        private _publishedInterface: PublishedInterface
    ) {
        this._ussLoaderHelper = new USSLoaderHelper(assetPool, core, this);
    }

    supportsFilter(filter?: PublishedAdobeAssetFilter | AdobeAssetFilter): boolean {
        // If we don't provide a filter at all, then we cannot use the loader
        return filter !== undefined;
    }

    async loadPage(options: IItemLoaderOptions<PublishedAdobeAssetConfig>): Promise<ILoadedPage<PublishedAdobeAssetConfig>> {
        return this._ussLoaderHelper.loadPage(options);
    }

    /**
     * @package -- only for use inside USSLoaderHelper
     */
    async _getUSSResults({
        start,
        loadOptions,
        mediaTypes,
        excludeMediaTypes,
        order
    }: IGetUSSResults<PublishedAdobeAssetConfig>): Promise<USSResponse> {
        return this._publishedInterface.getPublishedAssets({
            orderBy: OrderFieldToIUSSAdobeAssetOrderBy[order.field],
            orderDirection: order.direction,
            start,
            limit: loadOptions?.limit,
            mediaTypes,
            excludeMediaTypes
        });
    }

    /**
     * @package -- only for use inside USSLoaderHelper
     */
    _getItemData(item: Partial<USSMetadata>): USSAdobeAssetUpdaterMetadata {
        return {
            ...item,
            published: true
        };
    }
}
