import { gql } from '../generated/typed-gql';

export const setAsFavorite = gql(
    /* GraphQL */
    `
    mutation setAsFavorite($assetId: ID!, $input: UpdateLabelInput!) {
      updateLabel(assetId: $assetId, input: $input) {
        favorite {
          isFavorite
        }
      }
    }
  `
);
