import type { SAM } from '@ccx-public/component-types';
import type { AssetLinks, ISAMOperationResultProps } from '../interface/RepositoryModel';
import ItemBase from '../core/ItemBase';
import type { ISAMObject } from '../indexPrivate';
import { observable } from '../core/decorators';
import PropertyUpdater from '../core/PropertyUpdater';
import ItemUpdater from '../core/ItemUpdater';
import { getURLFromLinks, RelType } from '../interface/LinkUtils';
import AssetInterface, { VersionPatchTypes } from '../interface/AssetInterface';
import SAMError, { isSAMError, SAMErrorCode } from '../core/SAMError';
import type { RenditionStatus } from '../utils/RenditionFetcher';
import { RenditionFetcher, RenditionType, SUPPORTED_SIZES } from '../utils/RenditionFetcher';
import ManifestResource from './ManifestResource';
import { createMilestoneJsonParams } from '../assets/AssetUtils';
import { isConvertibleCloudAsset } from '../utils/compositeConversion';

export interface IAssetVersion {
    // These fields come from the version history listing
    version: string;
    created: string;
    created_by: string;
    milestone: IVersionMilestoneMetadata | undefined;
    _links: AssetLinks;  // links for this version
    // These fields are provided from AssetVersionLoader using data from the parent AdobeAsset's AssetInterface
    assetId: string;
    assetEtag: string;
    assetLinks: AssetLinks;
    'device_asset_name': string;
    /** Live Editing Service collaborators: user identifiers (e.g. Adobe IDs). From API as "contributors". */
    contributors?: string[];
}

/**
 * Represents the milestone data directly from the services
 */
export interface IVersionMilestoneMetadata {
    label: string;
    description: string;
    isPinned: boolean;
    created: string;
}

/**
 * Represents the milestone data that we have exposed to clients.
 */
export interface IVersionMilestone {
    label?: string;
    description?: string;
    versionId?: string;
    isPinned?: boolean;
    created?: Date;
}

/**
 * Options for getting a presigned URL for an asset version.
 */
export interface GetPresignedURLOptions {
    /**
     * Time-to-live for the presigned URL in seconds.
     * If not provided, the service's default expiration time will be used (4 hours as of this writing).
     */
    presignedUrlExpirationSeconds?: number;
}

export default class AssetVersion extends ItemBase implements ISAMObject, SAM.AssetVersion {
    // These fields come from the parent Asset
    private _assetId: string = '';
    private _assetEtag: string = '';
    private _assetLinks?: AssetLinks;

    // These fields come from the AssetVersionLoader
    private _createdAt: Date = new Date();
    private _createdBy: string = '';
    private __links?: AssetLinks;
    private _renditionFetcher: RenditionFetcher | undefined;

    private _manifest: ManifestResource = new ManifestResource(this._core, this);
    private _name: string = '';
    private _milestoneMetadata?: IVersionMilestoneMetadata;
    private _collaborators: string[] = [];

    private async _getHeadAssetInterface() {
        const assetContext = await this._core.getAssetContext();
        // NOTE: this AssetInterface is tied to the parent AdobeAsset for all AssetVersion instances. Where API
        // calls are version-specific, the links need to come from this.__links; if the API call is not specific to
        // a particular version, then the links need to come from `this._assetLinks`.
        return new AssetInterface(
            assetContext._rapi,
            this._assetId,
            this._assetLinks!,
            // etag only applies to the head version, and isn't needed
            // by version history R-API calls, but is required for AssetInterface.
            this._assetEtag
        );
    }

    async _getAssetInterface() {
        return new AssetInterface(
            this._core.hostAssetContext._rapi,
            this._assetId,
            this.__links!,
            // etag doesn't apply to VersionHistory, but AssetInterface requires it
            // as constructor parameter
            'static-etag'
        );
    }

    @observable
    get assetId(): string {
        return this._assetId;
    }

    @observable
    get created(): Date {
        return this._createdAt;
    }

    @observable
    get createdBy(): string {
        return this._createdBy;
    }

    @observable
    get isPinned(): boolean {
        return this.milestoneMetadata?.isPinned || false;
    }

    @observable
    get lesCollaborators(): string[] {
        return this._collaborators || [];
    }

    @observable
    get links(): AssetLinks {
        // Make a copy to avoid the client accidentally manipulating the links
        return Object.assign({}, this.__links);
    }

    get manifest(): ManifestResource {
        return this._manifest;
    }

    @observable
    get milestoneCreated(): Date | undefined {
        return this.milestoneMetadata?.created ? new Date(this.milestoneMetadata.created) : undefined;
    }

    /**
     * The client side mapping of the milestone data we provide to clients. Going forward,
     * we have deprecated this property and replaced it with {@link AssetVersion#milestoneMetadata}.
     * and so any new properties should be added to {@link AssetVersion#milestoneMetadata} instead.
     *
     * @deprecated Use {@link AssetVersion#milestoneMetadata} instead.
     * @see {@link AssetVersion#milestoneMetadata}
     */
    @observable
    get milestone(): IVersionMilestone | undefined {
        return this._milestoneMetadata ? {
            label: this._milestoneMetadata.label,
            description: this._milestoneMetadata.description,
            isPinned: this._milestoneMetadata.isPinned,
            created: new Date(this._milestoneMetadata.created)
        } : undefined;
    }

    /**
     * The raw data provided by the services for the milestone with
     * no additional mapping of properties.
     */
    @observable
    get milestoneMetadata(): IVersionMilestoneMetadata | undefined {
        return this._milestoneMetadata;
    }

    @observable
    get name(): string {
        return this._name;
    }

    @observable
    get versionId(): string {
        return this.id;
    }

    private _getRenditionFetcher(): RenditionFetcher {
        if (!this._renditionFetcher) {
            this._renditionFetcher = new RenditionFetcher(
                this._core,
                SUPPORTED_SIZES,
                async (size: number, type: string) => {
                    const ai = await this._getAssetInterface();
                    return ai.getRendition(size, type, this.versionId);
                }
            );

            // Forward change events from the rendition fetcher
            // to this class.
            this._renditionFetcher.on('change', () => {
                this.dispatch({ type: 'change' });
            });
        }
        return this._renditionFetcher;
    }

    @observable
    getRenditionURL(size: number, type: string = RenditionType.PNG): string {
        const renditionFetcher = this._getRenditionFetcher();
        return renditionFetcher.getURL(size, type, this.versionId);
    }

    @observable
    public renditionURLStatus(size: number, type: string): RenditionStatus {
        const renditionFetcher = this._getRenditionFetcher();
        return renditionFetcher.renditionURLStatus(size, type, this.versionId);
    }

    /**
     * See {@link AdobeAsset#getCustomRendition} for full documentation.
     */
    async getCustomRendition({
        size,
        type,
        urlTemplateOptions,
        additionalHeaders
    }: Parameters<AssetInterface['getCustomRendition']>[0] = {}): Promise<Response> {
        const assetInterface = await this._getAssetInterface();
        // Note: no need to pass versionId here b/c the link has a static version
        // parameter, so it cannot be modified by urlTemplateOptions.
        return assetInterface.getCustomRendition({ size, type, urlTemplateOptions, additionalHeaders });
    }

    /**
     * See {@link AdobeAsset#getAllCustomRenditions} for full documentation.
     */
    async getAllCustomRenditions({
        type,
        urlTemplateOptions,
        additionalHeaders
    }: Parameters<AssetInterface['getAllCustomRenditions']>[0] = {}): Promise<Response> {
        const assetInterface = await this._getAssetInterface();
        // Note: no need to pass versionId here b/c the link has a static version
        // parameter, so it cannot be modified by urlTemplateOptions.
        return assetInterface.getAllCustomRenditions({ type, urlTemplateOptions, additionalHeaders });
    }

    /**
     * Returns a pre-signed rendition url for the given size and type.
     * @param size The size of the asset version rendition    (e.g. 128, 256, 512, 1024)
     * @param type The type of the asset version rendition    (e.g. 'image/png', 'image/jpg', etc.)
     * see {@link https://git.corp.adobe.com/pages/caf/api-spec/chapters/common_resources/renditions_resources.html#media-types} for available types
     * @returns A pre-signed URL for the asset version rendition
     */
    async getPresignedRenditionURL({
        size,
        type
    }: {
        size: number;
        type: string;
    }): Promise<string> {

        const response = await this.getCustomRendition({
            size,
            type,
            additionalHeaders: {
                'Accept': 'application/vnd.adobecloud.download+json'
            }
        });

        const res = await response.json();
        return res.href;
    }

    /**
     * Gets a presigned URL for downloading this version of the asset.
     * The URL will be valid for the specified duration or the service's default expiration time if not specified.
     *
     * @param options - Options for getting the presigned URL
     * @returns A promise that resolves to the presigned download URL.
     */
    async getPresignedURL(options: GetPresignedURLOptions = {}): Promise<string> {
        const blockDownloadServiceURL = getURLFromLinks(this.__links, RelType.DOWNLOAD);
        const assetInterface = await this._getAssetInterface();
        const assetContext = await this._core.getAssetContext();
        const asset = await assetContext.getAssetWithCloudID(this._assetId);
        const convertToDesktop = isConvertibleCloudAsset(asset.mediaType);
        return await assetInterface.getBlockDownloadURL(blockDownloadServiceURL, options.presignedUrlExpirationSeconds, convertToDesktop);
    }

    async restore() {
        const assetContext = await this._core.getAssetContext();
        const asset = await assetContext.getAssetWithCloudID(this._assetId);
        const isComposite = asset.isComposite;
        if (isComposite) {
            const href = getURLFromLinks(this.__links, RelType.MANIFEST);
            const headInterface = await this._getHeadAssetInterface();
            await headInterface.restoreVersionManifest(href);
            await asset._load();
        } else {
            const target = getURLFromLinks(asset.links, RelType.PRIMARY);
            await this.copy(target);
        }
    }

    /**
     * Copy the asset version to the target asset using the target's asset
     * RelType.PRIMARY link.
     *
     * @deprecated Use {@link AssetVersion#copyPrimaryToAsset} instead.
     * @see {@link AssetVersion#copyPrimaryToAsset}
     *
     * @warning - Not currently functioning.
     *
     * @param target - The target HREF of the asset to copy the asset version to.
     * @returns A promise that resolves to the result of the copy operation.
     */
    async copy(target: string) {
        const assetContext = await this._core.getAssetContext();
        const asset = await assetContext.getAssetWithCloudID(this._assetId);
        const isComposite = asset.isComposite;
        const source = getURLFromLinks(this.__links, RelType.PRIMARY);
        if (isComposite) {
            // Copy for composite assets not yet implemented, JIRA: https://jira.corp.adobe.com/browse/ACPCSS-1875
            throw SAMError.create(SAMErrorCode.UNSUPPORTED, 'AssetVersion.copy not implemented for composite assets');
        } else {
            const headInterface = await this._getHeadAssetInterface();
            const result = await headInterface.runOperation({
                op: 'copy',
                id: this._assetId,
                source: { 'href': source, 'if-match': '*' },
                target: { 'href': target, 'if-match': '*' }
            });
            return result;
        }
    }

    /**
     * Move this version of an asset to an existing asset identified by the targetAssetID.
     * Currently this is implemented by copying the asset version to the target asset and then
     * permanently deleting the version from the source asset. In the future we should ask
     * the platform to support this operation directly.
     *
     * @param targetAssetID - The target asset ID of the asset to move the asset version to.
     * @param deleteHeadAssetIfLastVersion - If true, delete the head asset when this version is the last. RAPI
     * won't allow the last version to be deleted, so if needed, this will delete the head asset which will
     * also delete the last version.
     */
    async moveToAsset(targetAssetID: string, deleteHeadAssetIfLastVersion: boolean = false): Promise<void> {
        await this.copyPrimaryToAsset(targetAssetID);
        await this.permanentlyDelete(deleteHeadAssetIfLastVersion);
    }

    /**
     * Permanently delete this version of an asset and it's representation
     * in the local asset pool (in memory cache).
     *
     * @param deleteHeadAssetIfLastVersion - If true, delete the head asset when this version is the last. RAPI
     * won't allow the last version to be deleted, so if needed, this will delete the head asset which will
     * also delete the last version.
     */
    async permanentlyDelete(deleteHeadAssetIfLastVersion: boolean = false): Promise<void> {
        const headInterface = await this._getHeadAssetInterface();
        const assetContext = await this._core.getAssetContext();
        const headAsset = assetContext._assetPool.getLocalItemById(this._assetId);

        try {
            await headInterface.patchVersion([ {
                op: VersionPatchTypes.remove,
                path: `/children/version=${this.versionId}`
            } ]);
        } catch (e) {
            if (!isSAMError(e)) {
                throw e;
            }

            const samError = e as SAMError;
            /**
             * @TODO SAMJS-604: Once the actual response body is confirmed from RAPI
             * we can use that to check for the problem type instead of a blanket
             * check for ACCESS_DENIED.
             *
             * @note Seems odd that we would say it's ACCESS_DENIED when it's really
             * when it's really FORBIDDEN_OPERATION.
             */
            if (samError.code !== SAMErrorCode.ACCESS_DENIED
                || !deleteHeadAssetIfLastVersion
            ) {
                throw e;
            }

            if (headAsset) {
                await headAsset.permanentlyDelete();
            }
        }

        // If the asset is not found, that means there isn't a version to delete.
        // since the head asset doesn't exist locally.
        if (!headAsset) {
            return;
        }

        const session = headAsset._versionPool.createUpdateSession();
        session.queueDiscardedItem(this);
        session.commit();
    }

    /**
     * Copy this version of an asset to an existing asset identified by the targetAssetID.
    * @deprecated Use {@link AssetVersion#copyPrimaryToAsset} instead.
     * @see {@link AssetVersion#copyPrimaryToAsset}
     *
     * @note this method does not fetch the repository metadata and other data
     * from the services for the targetAssetID. If the targetAssetID does not
     * exist the services will throw an error, which will bubble up to the caller.
     *
     * @param targetAssetID - The target asset ID of the asset to copy the asset version to.
     * @returns A promise that resolves to the result of the copy operation.
     */
    async copyToAsset(targetAssetID: string): Promise<void> {
        const headInterface = await this._getHeadAssetInterface();
        await headInterface.runOperationWithEmptyResponse({
            op: 'copy_resources',
            source: {
                'repo:assetId': this._assetId,
                'repo:version': this.versionId
            },
            target: {
                'repo:assetId': targetAssetID
            },
            resources: [
                {
                    reltype: RelType.PRIMARY
                },
            ]
        });
    }

    /**
     * Copy this version of an asset to an existing asset identified by the targetAssetID.
     *
     * @note this method does not fetch the repository metadata and other data
     * from the services for the targetAssetID. If the targetAssetID does not
     * exist the services will throw an error, which will bubble up to the caller.
     *
     * @param targetAssetID - The target asset ID of the asset to copy the asset version to.
     * @returns A promise that resolves to the result of the copy operation.
     */
    async copyPrimaryToAsset(targetAssetID: string): Promise<void> {
        await this.copyToAsset(targetAssetID);
    }

    /**
     * Copy this version of an asset to a new asset.
     *
     * @param newAssetPath - The path of the new asset.
     * @param newAssetName - The name of the new asset.
     * @param repositoryId - The repository ID of the new asset.
     * @returns A promise that resolves to the new asset as an AdobeAsset instance.
     */
    async copyToNewAsset(newAssetPath: string, newAssetName: string, repositoryId: string): Promise<SAM.AdobeAsset> {
        const headInterface = await this._getHeadAssetInterface();
        const result = await headInterface.runOperation({
            op: 'copy',
            source: {
                'repo:assetId': this._assetId,
                'repo:version': this.versionId
            },
            target: {
                'repo:path': newAssetPath + '/' + newAssetName,
                'repo:repositoryId': repositoryId
            }
        }) as ISAMOperationResultProps;

        if (!result.asset) {
            throw SAMError.create(SAMErrorCode.UNKNOWN, 'Failed to copy asset version');
        }

        const assetContext = await this._core.getAssetContext();
        const session = assetContext._assetPool.createUpdateSession();
        const asset = assetContext._adobeAssetUpdater.updateRemoteItem(session, result.asset);
        session.commit();
        return asset;
    }

    async setMilestone({
        label = this.milestoneMetadata?.label || '',
        description = this.milestoneMetadata?.description || '',
        isPinned = this.milestoneMetadata?.isPinned || false
    }: Partial<IVersionMilestone>) {
        const jsonParams = createMilestoneJsonParams(
            this.versionId,
            !!this.milestoneMetadata,
            label,
            description,
            isPinned
        );
        const headInterface = await this._getHeadAssetInterface();
        await headInterface.patchVersion(jsonParams);
        const createdDate = new Date(Date.now()).toISOString();
        const assetContext = await this._core.getAssetContext();
        const asset = await assetContext.getAssetWithCloudID(this._assetId);
        const session = asset._versionPool.createUpdateSession();

        VersionUpdater.updateLocalItem(session, this, {
            milestone: {
                label,
                description,
                isPinned,
                // Since the patch call doesn't return the created date, we set it to the current date for now
                // after refresh the data will be the one from the service.
                created: createdDate
            }
        });
        session.commit();
    }

    async removeMilestone() {
        if (!this.milestoneMetadata) {
            return;
        }
        const jsonParams = [ {
            op: VersionPatchTypes.remove,
            path: `/children/version=${this.versionId}/milestone`,
        } ];

        const headInterface = await this._getHeadAssetInterface();
        await headInterface.patchVersion(jsonParams);
        const assetContext = await this._core.getAssetContext();
        const asset = await assetContext.getAssetWithCloudID(this._assetId);
        const session = asset._versionPool.createUpdateSession();
        VersionUpdater.updateLocalItem(session, this, {
            // Set milestone as undefined since that's what the service
            // returns when the milestone is not set.
            milestone: undefined
        });
        session.commit();
    }
}

export const VersionUpdater = new ItemUpdater<AssetVersion, Partial<IAssetVersion>>({
    localItemType: AssetVersion,
    remoteIdProperty: 'version',
    propertyUpdater: new PropertyUpdater({
        '_createdAt': { name: 'created', format: 'date' },
        '_createdBy': 'created_by',
        '_assetId': 'assetId',
        '_assetEtag': 'assetEtag',
        '_assetLinks': { name: 'assetLinks', format: 'object' },
        '__links': { name: '_links', format: 'object' },
        '_name': 'device_asset_name',
        '_milestoneMetadata': { name: 'milestone', format: 'object' },
        '_collaborators': {
            name: 'contributors',
            isArray: true,
            format: 'string'
        }
    })
});
