import type AdobeAsset from './AdobeAsset';
import type { IItemLoader, IItemLoaderOptions, ILoadedPage } from '../core/ItemLoader';
import type ItemPool from '../core/ItemPool';
import type AdobeAssetFilter from './AdobeAssetFilter';
import type { ISAMCorePrivate } from '../indexPrivate';
import type { IItemSourceConfig } from '../core/ItemList';
import ACPLModelInterface from '../interface/ACPLModelInterface';
import KeepAliveManager from '../core/decorators/KeepAliveManager';
import { getMostRecentValidMutation } from '../utils/loaderUtils';

export default class LocalAssetLoader<ItemConfig extends IItemSourceConfig> implements IItemLoader<ItemConfig> {

    constructor(
        private _assetPool: ItemPool<AdobeAsset>,
        private _core: ISAMCorePrivate,
        private acplModelInterface = new ACPLModelInterface(_core)
    ) {
    }

    supportsFilter(filter?: AdobeAssetFilter): boolean {
        return filter !== undefined;
    }

    async loadPage(options: IItemLoaderOptions<ItemConfig>): Promise<ILoadedPage<ItemConfig>> {
        const cachedAssets = await this.acplModelInterface.getLocalAssets();

        const mostRecentValidMutation = getMostRecentValidMutation(options.resource);
        const session = this._assetPool.createLoaderUpdateSession(mostRecentValidMutation);
        const updaters = await this._core._adobeAssetFactory.getRepoMetadataUpdaters(cachedAssets);
        const items = this._core._adobeAssetFactory.assetsFromLocalMetadata(session, cachedAssets, updaters);
        session.commit();

        // Assets with only local data may be filtered out of active lists (e.g. a lack of repoPath in directory filters).
        // This puts them at risk of being garbage-collected before sibling loaders have a chance to fill out those models
        // with remote data. To prevent this, we keep a reference to them in memory, which persists until we reload the list.
        items.map(item => KeepAliveManager.getInstance().add(item));

        return {
            items,
            mostRecentValidMutation
        };
    }
}



