import { default as uuid } from './uuid';

export type CreateAtomFn = (name: string, onBecomeObservedHandler: () => void, onBecomeUnobservedHandler: () => void) => any;

type MobXInstanceInfo = {
    id: string,
    references: Set<string>
}

/**
 * Manager for observability via MobX - classes should call reportObserved
 * for any getters or methods that should be observable if used in the context
 * of MobX. Since SAM.js does not include MobX, clients need to makeObservable()
 * with their MobX instance
 */
export default class MobX {

    private _contexts: Map<CreateAtomFn, MobXInstanceInfo> = new Map();

    /**
     * Register a MobX instance to make SAM.js observable.
     * Returns a function that can be called to unregister.
     */
    register(createAtom: CreateAtomFn): () => void {
        // It can be the case the register is called multiple times with the same createAtom function,
        // which can happen if multiple components are using SAM.js but sharing the same MobX instance.
        // In this case, we don't want to create more atoms than necessary since that would cause performance
        // problems - instead, we detect if the createAtom was already registered, and just keep a reference
        // count instead of registering it multiple times.
        let instanceInfo = this._contexts.get(createAtom);
        if (!instanceInfo) {
            instanceInfo = { id: uuid(), references: new Set() };
            this._contexts.set(createAtom, instanceInfo);
        }
        const refId = uuid();
        instanceInfo.references.add(refId);

        return () => {
            const instanceInfo = this._contexts.get(createAtom);
            if (instanceInfo) {
                instanceInfo.references.delete(refId);
                if (instanceInfo.references.size === 0) {
                    this._contexts.delete(createAtom);
                }
            }
        };
    }

    /**
     * Called to report an observation on an object. Any reaction that observes this
     * will be triggered whenever the given change event on the object triggers.
     * In the simple case where we only have one change event for an object ('change'),
     * getters and methods can be instrumented with just _environment.mobx.reportObserved(this).
     */
    reportObserved(object: any, event: string = 'change') {
        for (const [ createAtom, { id } ] of this._contexts) {
            const key = `_atom_${id}_${event}`;
            let atom = object[key];
            if (!atom) {
                const onChange = () => atom.reportChanged();
                atom = createAtom(`${object.constructor.name}_${event}`,
                    () => {
                        object.on(event, onChange);
                    },
                    () => {
                        object.off(event, onChange);
                    }
                );
                object[key] = atom;
            }
            atom.reportObserved();
        }
    }
}
