type CloudParams = {
    clientId: string;
    clientSecret: string;
    scopes: string;
    core: ISAMCorePrivate;
};

export type Params = ConnectionInfo & {
    cloudParams?: CloudParams;
};

type ElementClass = 'elements' | 'documentationElements' | 'removedElements';
type ElementGenerator =
    | '_getElementsByLibraryId'
    | '_getDocumentationElementsByLibraryId'
    | '_getRemovedElementsByLibraryId';

const defaultElementSort: ElementSort = {
    field: 'modifiedDate',
    direction: 'descending'
};

type FetchOptions = {
    reconnectOnErrors?: number[];
    reconnectOnNoResponse?: boolean;
    optimisticFetch?: boolean;
};

const DEFAULT_FETCH_OPTIONS: FetchOptions = {
    reconnectOnErrors: [ 401, 403 ],
    reconnectOnNoResponse: true
};

export type LocalDriverOptions = DriverOptions & {
    optimistic?: boolean;
    ignoreRenditionGrids?: boolean;
};

export default class LocalDriver extends Driver<Params, LocalDriverOptions> {
    private _hostname?: string;
    private _cloudParams?: CloudParams;

    private _notificationEventSource?: INotificationEventSource;

    private _libraryChangeListener: (libraryIds: string[]) => any = () => {
        return;
    };
    private _renditionCacheChangeListener: (element: ElementData) => any = () => {
        /**/
    };
    private _lastNotificationPayload: any = {};

    protected _operationTypes = [
        BatchOperation,
        ContentOperation,
        SingleOperation,
        MoveCopyElementOperation,
        MoveCopyGroupOperation,
        ParallelOperation
    ];

    constructor(core: ISAMCorePrivate, connector: ConnectorParam<Params>, options: LocalDriverOptions = {}) {
        super(core, connector);
        this._options = options;
    }

    getLibrary(library: Library, options?: GetLibraryOptions) {
        return this._getLibraryById(library.id, options);
    }

    getElements(library: Library, ...args: any[]) {
        return this._getElementsByLibraryId(library.id, ...args);
    }

    getRemovedElements(library: Library, ...args: any[]) {
        return this._getRemovedElementsByLibraryId(library.id, ...args);
    }

    getDocumentationElements(library: Library, ...args: any[]) {
        return this._getDocumentationElementsByLibraryId(library.id, ...args);
    }

    getElement(library: Library, elementId: string) {
        return this._getElement(library.id, elementId);
    }

    reconnect() {
        this._notificationEventSource?.close();
        if (this.isConnected) {return super.reconnect();}
        return Promise.resolve();
    }

    protected async _handleConnected(data: Params) {
        if (isUpdateRequiredInfo(data)) {
            this._handleConfigurationMutation({
                config: {},
                environment: this._config.environment,
                processInfo: {
                    updateRequired: data.updateRequired,
                    apiVersion: data.apiVersion
                }
            });
            throw new LibraryError(
                'CONNECTION_FAILED',
                `LocalDriver failed to connect - ${data.updateRequired} update required`
            );
        }

        this._hostname = data.hostname;
        this._token = data.token;
        this._cloudParams = data.cloudParams;
        this._notificationEventSource = new NotificationEventSource(
            `${this._hostname}/notifications?token=${this._token}`
        );

        this._notificationEventSource.on('error', (error: Error | LibraryError) => {
            if (error instanceof LibraryError && error.libraryErrorCode === 'INVALID_JSON') {
                Logger.log('[NOTIFICATIONS] Received invalid JSON object.');
                return;
            }

            this.reconnect();
        });

        await this.getConfiguration();
        this._notificationEventSource.on('configurationMutation', this._handleConfigurationMutation.bind(this));
        this._notificationEventSource.on('libraryMutation', this._handleLibraryMutation.bind(this));
        this._notificationEventSource.on('renditionCacheMutation', this._handleRenditionCacheMutation.bind(this));
    }

    protected _handleDisconnected() {
        this._notificationEventSource?.close();
    }

    get cloudParams() {
        if (!this._cloudParams || !this.config.user?.id) {
            return undefined;
        }

        return {
            ...this._cloudParams,
            userId: this.config.user?.id
        };
    }

    getCloudDriver(): CloudDriver {
        if (!this.cloudParams) {
            return undefined as unknown as CloudDriver;
        }

        const connector = async () => {
            const { userId, clientId, clientSecret, scopes, core } = this.cloudParams as Exclude<
            LocalDriver['cloudParams'],
            undefined
            >;

            const { access_token } = await this.fetchAccessToken(userId, clientId, clientSecret, scopes);

            return {
                env: this.config.environment,
                core,
                token: access_token
            };
        };

        return new CloudDriver(this._core, connector);
    }

    fetchAccessToken(userId: string, clientId: string, clientSecret: string, scopes: string) {
        return this.fetch('/configuration/access_token', {
            method: 'POST',
            body: JSON.stringify({ userId: this._config.user?.id, clientId, clientSecret, scopes })
        }).then(res => res.json());
    }

    private _getElement(libraryId: string, elementId: string): Promise<ElementData> {
        return this.fetch(`/libraries/${libraryId}/elements/${elementId}`)
            .then(res => res.json())
            .then(mapResponseToElementData);
    }

    private async *_getElementsOfType(
        type: 'elements' | 'removed_elements' | 'documentation_elements',
        libraryId: string,
        _sort: ElementSort = defaultElementSort,
        etag?: string,
        signal?: AbortSignal
    ): AsyncGenerator<PaginatedResponse<ElementData>> {
        // TODO: Sort

        const headers: any = {};

        if (etag) {
            headers['if-none-match'] = etag;
        }

        const res = await this.fetch(`/libraries/${libraryId}/${type}`, { headers, signal });
        const json: ElementsResponse = await res.json();
        yield json.elements.map(mapResponseToElementData);
    }

    private async *_getElementsByLibraryId(
        libraryId: string,
        sort: ElementSort = defaultElementSort,
        etag?: string,
        limit?: number,
        signal?: AbortSignal
    ): AsyncGenerator<PaginatedResponse<ElementData>> {
        yield* this._getElementsOfType('elements', libraryId, sort, etag, signal);
    }

    async getElementsPage(
        _library: Library,
        _start?: number,
        _limit?: number,
        _sort?: ElementSort,
        _etag?: string,
    ): Promise<MelvilleElementsResponse> {
        throw new LibraryError('NOT_IMPLEMENTED', 'LocalDriver.getElementsPage not implemented.');
    }

    async *getSearchResults(
        searchQuery: string,
        filters: SearchFilters,
        elementSort: ElementSort,
        signal: AbortSignal
    ): AsyncGenerator<PaginatedResponse<ElementData>> {
        filters.elements_only = true;
        let orderBy = elementSort.field === 'name' ? 'name' : 'modified_date';
        if (elementSort.direction === 'descending') {
            orderBy = `-${orderBy}`;
        }

        const responseMapper = (response: SearchElementsResponse) =>
            response.results?.map(mapResponseToElementData) ?? [];

        const headers: any = {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            signal
        };

        const limit = 300;

        // We only group search results by type so if the section type is anything
        // other than "type" we just do a normal search of all types
        if (elementSort.sectionType !== 'type') {
            headers.body = JSON.stringify({
                q: searchQuery,
                order_by: orderBy,
                filters,
                limit
            });
            yield* this.fetchAllPages('/search', headers, responseMapper);
        } else {
            // If there is a list of type sections we want to fetch search results for each type separately
            // so that we get our results as a list of ordered elements grouped by element type.
            for (const section of elementSort.sections as string[]) {
                filters.element_types = filters.element_types = [ section ];
                headers.body = JSON.stringify({
                    q: searchQuery,
                    order_by: orderBy,
                    filters,
                    limit
                });
                yield* this.fetchAllPages('/search', headers, responseMapper);
            }
        }
    }

    async *fetchAllPages<T, U>(
        firstUrl: string,
        headers: any,
        responseMapper: (response: T) => PaginatedResponse<U>
    ): AsyncGenerator<PaginatedResponse<U>> {
        let nextUrl = firstUrl;
        while (nextUrl) {
            const response = await this.fetch(nextUrl, headers).then(res => res.json());
            yield responseMapper(response);
            nextUrl = response._links?.next?.uri;
            const newBody = response._links?.next?.body;
            if (newBody) {
                headers.body = JSON.stringify(newBody);
            }
        }
    }

    private async *_getDocumentationElementsByLibraryId(
        libraryId: string,
        sort: ElementSort = defaultElementSort,
        etag?: string
    ): AsyncGenerator<PaginatedResponse<ElementData>> {
        yield* this._getElementsOfType('documentation_elements', libraryId, sort, etag);
    }

    private async *_getRemovedElementsByLibraryId(
        libraryId: string,
        sort: ElementSort = defaultElementSort,
        etag?: string
    ): AsyncGenerator<PaginatedResponse<ElementData>> {
        yield* this._getElementsOfType('removed_elements', libraryId, sort, etag);
    }

    async getTeams(): Promise<TeamData[]> {
        const response = await this.fetch('/teams');
        const data: TeamsResponse = await response.json();
        return isTeamsResponse(data) ? data.teams.map(mapResponseToTeamData) : [];
    }

    async getProjects(): Promise<TeamData[]> {
        const response = await this.fetch('/projects');
        const data: ProjectsResponse = await response.json();
        return data?.projects?.map(mapProjectsResponseToTeamData) ?? [];
    }

    async getProjectGradient(project: Team): Promise<GradientData | undefined> {
        const response = await this.fetch(`/projects/${project.id}/gradient`);
        const data: ProjectGradientResponse = await response.json();
        return data.gradient ? mapResponseToGradientData(data.gradient) : undefined;
    }

    async *getGroups(_libraryId: string): AsyncGenerator<PaginatedResponse<GroupData>> {
        yield Promise.resolve(undefined as unknown as PaginatedResponse<GroupData>);
    }

    async *getLibraries(): AsyncGenerator<PaginatedResponse<LibraryData>> {
        // The includeRenditionGrid flag on this endpoint will include only elements in the rendition grid, but setting it to false will not cause all elements to be returned.
        // The paths of renditions for image elements in the rendition grid will only be returned when cached.
        // This flag will not cause the imaging service to generate renditions like getRenditionPath would.
        let endpoint = '/libraries';
        if (!this._options.ignoreRenditionGrids) {
            endpoint += '?includeRenditionGrid=true';
        }
        yield this.fetch(endpoint)
            .then(res => res.json())
            .then((res: LibrariesResponse) =>
                isLibrariesResponse(res)
                    ? res.libraries.map(data => mapResponseToLibraryData(data, this._options.readOnly))
                    : []
            );
    }

    async *getLibrariesList(): AsyncGenerator<PaginatedResponse<LibraryData>> {
        yield Promise.resolve(undefined as unknown as PaginatedResponse<LibraryData>);
    }

    async *getLibrariesPage(): AsyncGenerator<PaginatedResponse<LibraryData>> {
        yield Promise.resolve(undefined as unknown as PaginatedResponse<LibraryData>);
    }

    protected async *_getAllElements(
        libraryId: string,
        options: GetElementsOptions
    ): AsyncGenerator<Partial<LibraryData>> {
        const elementTypes: [ElementClass, ElementGenerator][] = [
            [ 'elements', '_getElementsByLibraryId' ],
            [ 'documentationElements', '_getDocumentationElementsByLibraryId' ],
            [ 'removedElements', '_getRemovedElementsByLibraryId' ]
        ];

        // If the elements aren't loaded yet, update the library page by page
        // Otherwise, load them all at once.
        const updateData: Partial<LibraryData> = {};

        // TODO: We want to run all element type iterators at the same time. Right now it doesn't matter since we only deal with normal elements.
        for (const [ type, generator ] of elementTypes) {
            if (options.types.includes(type)) {
                for await (const page of this[generator](
                    libraryId,
                    options.sort,
                    options.etag,
                    undefined,
                    options.abortController?.signal
                )) {
                    updateData[type] = updateData[type] || [];
                    updateData[type]?.push(...page);
                    if (options.loadProgressively) {
                        yield { [type]: updateData[type] };
                    }
                }
            }
        }

        yield { areElementsLoaded: true, ...(options.loadProgressively ? {} : updateData) };
    }

    async getLibraryById(libraryId: string, options?: GetLibraryOptions) {
        const { value } = await this._getLibraryById(libraryId, options).next();
        return value;
    }

    async *_getLibraryById(libraryId: string, options: GetLibraryOptions = {}): AsyncGenerator<Partial<LibraryData>> {
        const etag = options.etag;
        try {
            const headers: HeadersInit = {};

            if (etag) {
                headers['if-none-match'] = etag;
            }

            let fetchOptions: FetchOptions | undefined;
            if (options.optimisticFetch !== undefined) {
                fetchOptions = { optimisticFetch: options.optimisticFetch };
            }

            // The includeRenditionGrid flag on this endpoint is equivalent to saying do not include elements except those in the rendition grid
            let endpoint = `/libraries/${libraryId}`;
            if (!this._options.ignoreRenditionGrids) {
                endpoint += '?includeRenditionGrid=true';
            }
            const res = await this.fetch(endpoint, { headers }, fetchOptions);

            // If we receive a 202 here, the process is optimistically loading the library to disk...
            // we can return early
            if (res.status === 202) {
                return;
            }

            const json = await res.json();
            json.etag = res.headers.get('ETag');

            // We do not care about the updated elements from this call unless they are rendition grid elements.
            // If all elements need to be updated, that will be done by this._getAllElements.
            if (options.elementParams) {
                delete json.elements;
            } else {
                // Elements path should exist on library data to append new elements, in case of empty library
                json.elements ??= [];
            }

            const libraryResponse = mapResponseToLibraryData(json, this._options.readOnly);
            yield libraryResponse;
        } catch (error) {
            if (!(error instanceof RequestError && error.requestErrorCode === 'NOT_MODIFIED' && options.elementParams)) {
                throw error;
            }
        }

        if (options.elementParams) {
            yield* this._getAllElements(libraryId, {
                ...options.elementParams,
                etag: options.firstElementsLoad ? undefined : etag
            });
        }
    }

    followLibrary(assetId: string, libraryId: string): Promise<void> {
        return this.fetch('/libraries', {
            method: 'POST',
            body: JSON.stringify({
                follow: true,
                type: 'collab',
                id: libraryId,
                assetId
            })
        }).then((/** bookmark */) => {
            // The bookmark data is basically a copy of the request body.
            // It doesn't have anything useful to the caller, so we won't send it back.
            return;
        });
    }

    moveLibrary(libraryId: string, folderId: string): Promise<LibraryData | void> {
        return new Promise((resolve, reject) => {
            const request = this.fetch('/libraries', {
                method: 'POST',
                body: JSON.stringify({
                    self: libraryId,
                    team_id: folderId
                })
            });
            const asyncResponse = new AsyncResponse(this, request);

            asyncResponse.on('change', (isDone, libraryResponse) => {
                if (isDone) {
                    if (asyncResponse.error) {
                        reject(asyncResponse.error);
                    } else if (libraryResponse) {
                        resolve(mapResponseToLibraryData(libraryResponse));
                    } else {
                        resolve();
                    }
                }
            });
        });
    }

    importLibrary(
        file: string | File,
        callback: (error?: Error, libraryData?: LibraryData) => unknown = () => undefined
    ): AsyncResponse<LocalDriver> {
        if (typeof file !== 'string') {
            throw new Error('Input must be a local path in local mode.');
        }

        const request = this.fetch('/libraries', {
            method: 'POST',
            body: JSON.stringify({
                source: {
                    path: file
                }
            })
        });

        const asyncResponse = new AsyncResponse(this, request);

        asyncResponse.on('change', (isDone: boolean, libraryResponse: LibraryResponse) => {
            if (isDone) {
                const libraryData = libraryResponse ? mapResponseToLibraryData(libraryResponse) : undefined;
                callback(asyncResponse.error, libraryData);
            }
        });

        return asyncResponse;
    }

    exportLibrary(
        library: Library,
        path?: string,
        callback: (error?: Error) => unknown = () => undefined
    ): AsyncResponse<LocalDriver> {
        if (!path) {
            // TODO
            throw new Error('Destination path is required in local mode.');
        }

        const request = this.fetch(`/libraries/${library.id}/export`, {
            method: 'POST',
            body: JSON.stringify({ path })
        });

        const asyncResponse = new AsyncResponse(this, request);

        asyncResponse.on('change', (isDone: boolean) => {
            if (isDone) {
                callback(asyncResponse.error);
            }
        });

        return asyncResponse;
    }

    async abortOperation(operationId: string): Promise<Response> {
        return this.fetch(operationId, {
            method: 'DELETE'
        });
    }

    getRenditionUrl(element: Element, size: RenditionSize): string {
        return `${this._hostname}/libraries/${element.library.id}/elements/${element.elementId}/renditions/${size}?token=${this._token}`;
    }

    getAuthenticatedThumbnailURL(element: Element, size: RenditionSize): Promise<string> {
        return this.fetch(`/libraries/${element.library.id}/elements/${element.elementId}/renditions/${size}/url`, {
            headers: {
                'cache-control': 'none'
            }
        })
            .then(res => res.json())
            .then(res => res.url);
    }

    getRenditionPath(libraryId: string, elementId: string, size: RenditionSize): Promise<string> {
        const controllerInstance: AbortController = LibraryAbortController.getInstance(libraryId);
        return this.fetch(`/libraries/${libraryId}/elements/${elementId}/renditions/${size}/path`, {
            headers: {
                'cache-control': 'none' // if the rendition does not exist, it will be generated and added to the cache
            },
            signal: controllerInstance.signal
        })
            .then(res => res.json())
            .then(res => res.path);
    }

    getRendition(element: Element, size: RenditionSize): Promise<Response> {
        return this.fetch(`/libraries/${element.library.id}/elements/${element.elementId}/renditions/${size}`);
    }

    getRepresentationContent(representation: Representation): Promise<Response> {
        return this.fetch(
            `/libraries/${representation.library.id}/elements/${representation.element.elementId}/representations/${representation.id}`
        );
    }

    setLibraryChangeListener(libraries: LibraryData[], callback: (libraryIds: string[]) => any): void {
        this._libraryChangeListener = callback;
    }

    setRenditionCacheChangeListener(callback: (elementData: ElementData) => any): void {
        this._renditionCacheChangeListener = callback;
    }

    setFontDataChangeListener(callback: () => void): void {
        this.removeFontDataChangeListeners();
        this._notificationEventSource?.on('fontDataMutation', callback);
    }

    setSyncStateListener(callback: (state: SyncStateNotification) => void) {
        this._notificationEventSource?.removeAllListeners('syncMutation');
        this._notificationEventSource?.on('syncMutation', callback);
    }

    removeLibraryChangeListener() {
        this._notificationEventSource?.removeAllListeners('libraryMutation');
    }

    removeFontDataChangeListeners() {
        this._notificationEventSource?.removeAllListeners('fontDataMutation');
    }

    removeSyncStateListener() {
        this._notificationEventSource?.removeAllListeners('syncMutation');
    }

    removeRenditionCacheChangeListener() {
        this._notificationEventSource?.removeAllListeners('renditionCacheMutation');
    }

    private _handleConfigurationMutation = (data: ConfigurationData): Configuration => {
        const configurationUpdate = new Configuration(data);

        if (this._needToReconnect(configurationUpdate)) {
            this.reconnect();
        }
        this._config = configurationUpdate;
        this.emit('configChange');
        return this.config;
    };

    private _handleRenditionCacheMutation = (data: ElementResponse): void => {
        this._renditionCacheChangeListener(mapResponseToElementData(data));
    };

    private _handleLibraryMutation = (payload: LibraryChangeResponse): void => {
        if (!payload) {
            return;
        }

        // See what changed / was removed
        const responseKeys = new Set(Object.keys(payload));
        const libraryIds: string[] = Object.keys(this._lastNotificationPayload).filter(libraryId => {
            const libraryResponseEntry = payload[libraryId];
            responseKeys.delete(libraryId);
            return (
                !libraryResponseEntry
                || (typeof libraryResponseEntry !== 'number' && typeof libraryResponseEntry !== 'string')
            );
        });

        // Add in any new libraries
        libraryIds.push(...responseKeys);

        this._lastNotificationPayload = Object.keys(payload).reduce(
            (memo: LibraryChangeBody, key: string): LibraryChangeBody => {
                const value: string | number | LibraryResponse = payload[key];
                if (typeof value === 'number' || typeof value === 'string') {
                    if (value) {
                        // deleted libraries have empty string values
                        memo[key] = value;
                    }
                } else {
                    memo[key] = value.modified_date;
                }

                return memo;
            },
            {}
        );

        this._libraryChangeListener(libraryIds);
    };

    private _needToReconnect(configUpdate: Configuration): boolean {
        return (
            // We were previously authenticated with 1 user and that information has changed in the process....
            // Reconnect
            (this.config?.user?.id && this.config.user.id !== configUpdate.user?.id) || false
        );
    }

    async getConfiguration(): Promise<Configuration> {
        const response = await this.fetch('/configuration');
        const json = await response.json();
        this._handleConfigurationMutation(json);
        return this.config;
    }

    async updateRenditionCacheConfiguration(
        renditionSizes?: RenditionSizeConfig,
        fullRenditionConfig?: FullRenditionConfig
    ): Promise<Configuration> {
        if (!renditionSizes && !fullRenditionConfig) {return this.config;}
        await this.updateConfiguration({
            RENDITION_SIZES: renditionSizes,
            FULL_RENDITION_CONFIG: fullRenditionConfig
        }).catch(err => {
            Logger.error(`Unable to update process configuration. ${err}`);
        });
        return this.config;
    }

    async updateConfiguration(update: object): Promise<Configuration> {
        if (Object.keys(update).length) {
            const response = await this.fetch('/configuration', {
                method: 'PATCH',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify(update)
            });
            const json = await response.json();
            this._handleConfigurationMutation(json);
        }
        return this.config;
    }

    async setLocalSetting(key: string, value: any) {
        if (value === undefined) {
            value = null;
        }
        await this.updateConfiguration(Object.fromEntries([ [ key, value ] ]));
        this._config.config[key] = value;
    }

    getLocalSetting(key: string) {
        return this._config.config?.[key];
    }

    getInstalledVersion(appCode: string): string {
        return this._config.installedApps
            .filter(app => app.code.toLowerCase() === appCode.toLowerCase())
            .map(version => version.version)
            .sort(compareVersions)[0];
    }

    async sendAction(applicationAction: ApplicationAction) {
        return this.fetch('/action', { method: 'POST', body: applicationAction.toJSON() });
    }

    async openInCCD(path: string) {
        return this.fetch('/action/open_ccd', { method: 'POST', body: JSON.stringify({ path }) });
    }

    async fetch(path: string, init?: FetchRequestInit, options: FetchOptions = {}) {
        init = init || {};
        init.headers = init.headers || {};
        init.headers.token = this._token as string;
        init.headers['Content-Type'] = init.headers['Content-Type'] || 'application/json';
        // TODO: Get actual client version
        init.headers['x-client-version'] = '15';

        options = { ...DEFAULT_FETCH_OPTIONS, ...options };

        if (this._options.optimistic && (options.optimisticFetch === undefined || options.optimisticFetch === true)) {
            init.headers['x-optimism'] = 'true';
        }

        init.signal = init.signal
            ? combineSignals(init.signal, this._abortController?.signal as AbortSignal)
            : this._abortController?.signal;

        try {
            const response = await fetch(`${/^https?:\/\//.test(path) ? '' : this._hostname}${path}`, init);

            if (response.status >= 300) {
                const responseBody = await response.text();
                const errorCode = responseBody.replace(/["]+/g, '');
                throw getRequestError(response, errorCode);
            }

            return response;
        } catch (e) {
            if (RequestError.isRequestError(e as Error)) {
                // By default, reconnect on 401 and 403.
                // Process REST API can throw 401 (invalid process token) or 403 (If no library collections are loaded).
                // At this point we assume that the process has restarted or the authenticated user state has changed.
                const shouldReconnect
                    = options?.reconnectOnErrors?.includes((e as RequestError).response?.status as number)
                    && this.isConnected;

                if (shouldReconnect) {
                    this.reconnect();
                } else if (!shouldReconnect && (e as RequestError).name === ABORT_ERROR) {
                    return new Response('{}');
                }
            } else if ((e as RequestError).message === 'Failed to fetch' && options?.reconnectOnNoResponse) {
                // More than likely, libraries process shut down.
                Logger.warn(`Fetch request failed to respond: ${e}`);
                this.reconnect();
            } else if ((e as RequestError).message === 'Network request failed') {
                // Throws when Process REST API is disconnected in UXP
                Logger.warn(`Network request failed to respond: ${e}`);
                this.reconnect();
            }
            throw e;
        }
    }

    async copyFile(source: string, destination: string, allowOverride = false) {
        const result = await this.fetch(
            '/util/file/copy',
            {
                method: 'POST',
                body: JSON.stringify({ source, destination, allowOverride: Boolean(allowOverride) })
            },
            { reconnectOnNoResponse: true, reconnectOnErrors: [ 401 ] }
        );

        const json = await result.json();

        return json.path;
    }

    async getFileSize(path: string) {
        const result = await this.fetch('/util/file/size', {
            method: 'POST',
            body: JSON.stringify({ path })
        });
        const json = await result.json();
        return json.size;
    }

    getRenditionGrid(library: Library) {
        return library.renditionGrid;
    }

    async stageRepresentationForCommit(
        library: Library,
        file: File | { path: string } | any,
        _type?: string
    ): Promise<string> {
        try {
            if (file instanceof File) {
                const result = await this.fetch('/util/file', {
                    method: 'POST',
                    headers: {
                        'Content-Type': getMimeTypes(file.name?.split('.')[1])?.[0]
                    },
                    body: file
                });
                const json = await result.json();
                return json.path;
            }
        } catch (error: any) {
            // if the fetch request explicitly failed we want to reject the promise
            if (error?.response?.status === HttpStatus.INTERNAL_SERVER_ERROR) {
                return Promise.reject(error);
            }
            // otherwise, it might be a general uncaught exception from accessing File in UXP (undefined), so do nothing
        }

        return file.path;
    }

    async isSystemFontAvailable(fontName: string, matchFamily?: Boolean): Promise<boolean> {
        const result = await this.fetch(`/util/font/available`, {
            method: 'POST',
            body: JSON.stringify({ font_name: fontName, match_family: matchFamily })
        });
        const json = await result.json();
        return json.is_font_available;
    }

    async getFontData(fontId: string): Promise<FontData> {
        const result = await this.fetch(`/util/font/data`, {
            method: 'POST',
            body: JSON.stringify({ font_id: fontId })
        });
        const json = await result.json();
        return json.font_data;
    }

    async getTempDir(library: Library): Promise<string> {
        if (!library || !library.id) {
            throw new LibraryError('INVALID_PARAMETER', 'Need to pass a library with an ID');
        }
        const result = await this.fetch(`/libraries/${library.id}/temp_dir`);
        const json = await result.json();
        return json.path;
    }

    getCollaborators(_assetId: string): Promise<CollaboratorData[]> {
        throw new LibraryError('NOT_IMPLEMENTED', 'LocalDriver.getCollaborators not implemented.');
    }

    ignoreLocalSyncEvents(): boolean {
        // For Local driver the sync status should only be driven by what process is doing.
        return true;
    }
}
