import SAMError, { SAMErrorCode } from '../SAMError';

export const KeysProperty = Symbol('@key parameterMap');
export interface IHasKeyMap {
    [KeysProperty]: Map<string, number>
}

// @key decorator is used to indicate the argument to the @cache and @synchronized decorators
export default (target: unknown, propertyKey: string, parameterIndex: number) => {
    const map = (target as IHasKeyMap)[KeysProperty] = (target as IHasKeyMap)[KeysProperty] || new Map;
    if (map.has(propertyKey)) {
        throw SAMError.create(SAMErrorCode.BAD_REQUEST, '@key cannot be applied to more than one parameter');
    }
    map.set(propertyKey, parameterIndex);
};
