function _fetchNext(generator: AsyncGenerator, index: number) {
    return generator.next().then(result => ({ result, index }));
}

/**
 * Utility to allow combining async generators in a way that runs their tasks in parallel
 *
 * @export
 * @template T
 * @param {...Array<AsyncGenerator<T>>} generators generators to combine
 * @returns {AsyncGenerator<T>} A combined generator that runs individual generators in parallel
 */
export async function *combineGenerators<T>(...generators: Array<AsyncGenerator<T>>): AsyncGenerator<T> {
    const results = generators.map(_fetchNext);
    let finalized = results.length;
    while (finalized) {
        const yielded = await Promise.race(results);
        if (!yielded.result.done) {
            yield yielded.result.value as Awaited<T>;
            results[yielded.index] = _fetchNext(generators[yielded.index], yielded.index);
        } else {
            results[yielded.index] = new Promise(() => {
                /* NOOP */
            });
            finalized--;
        }
    }
}
