import RestrictedEventEmitter from '../../models/utils/RestrictedEventEmitter';
import type CloudDriver from '.';
import type { LibraryData } from '../../models/data/LibraryData';
import type { AssetLinkList, AdobeAsset, SAMError } from '../../../index';
import { syncGroupPath } from '../../config/constants';
import type IEvent from '../../../core/IEvent';

export default class AssetNotificationManager extends RestrictedEventEmitter {
    // The callback to invoke when libraries are updated.
    private _changeCallback?: (assetIds: string[]) => any;

    // List of library asset ids to monitor - this comes from SAM, and any ids we add to this list will be auto-monitored by ONS.
    private _librariesToMonitor?: AssetLinkList;

    private _syncGroupListener?: {
        notify: () => void;
        asset?: AdobeAsset;
    };

    constructor(private _driver: CloudDriver) {
        super();
    }

    connect() {
        this._librariesToMonitor = this._driver._core?.assetLinkManager.createList();
        this._librariesToMonitor?.on('notified', this._onChangeCallback);
    }

    disconnect() {
        this._changeCallback = undefined;
        this._librariesToMonitor?.clear();
        this._librariesToMonitor?.off('notified', this._onChangeCallback);
        this._librariesToMonitor = undefined;
    }

    get isConnected() {
        return !!this._librariesToMonitor;
    }

    async setWatchedLibraries(libraries: LibraryData[], callback: (assetIds: string[]) => any) {
        // No-op if we haven't been initialized.
        if (!this._librariesToMonitor) {
            return;
        }

        const librariesToMonitor = this._librariesToMonitor;
        const assetIds = new Set(libraries.map(library => library.assetId));

        // Remove any links no longer being watched
        librariesToMonitor.monitoredAssetIDs.forEach(id => !assetIds.has(id) && librariesToMonitor.removeAssetID(id));

        // Make sure we're watching all the assets we need to watch (this is a no-op if already being monitored)
        assetIds.forEach(id => id && librariesToMonitor.addAssetID(id));
        this._changeCallback = callback;
    }

    private _onChangeCallback = (event: IEvent, sender: AssetLinkList, payload?: any) => {
        const assetIds = payload as string[];
        this._changeCallback?.(assetIds);
    };

    async addWatchedLibrary(library: LibraryData) {
        library.assetId && this._librariesToMonitor?.addAssetID(library.assetId);
    }

    removeWatchedLibrary(library: LibraryData) {
        library.assetId && this._librariesToMonitor?.removeAssetID(library.assetId);
    }

    // Shallow watch of libraries sync group so we can tell when libraries are added/deleted/renamed/moved
    // Note: Shallow watch is not working, it's actually a deep watch until eTag propogation is turned off.
    async addLibrariesSyncGroupListener(cb: () => void) {
        // ensure listener is only added once
        if (this._syncGroupListener || !cb) {
            return;
        }
        this._syncGroupListener = { notify: cb };
        // SAM keeps weak references to AdobeAssets/Lists, so clients must keep a strong reference to stop SAM from garbage collecting them.
        // Otherwise SAM would hear the ONS event but the AdobeAsset notification would not occur. (See SAM-2711)
        let syncGroupDirectory = undefined;
        try {
            syncGroupDirectory = await this._driver._core?.hostAssetContext.getAssetWithRepoPath(syncGroupPath);
        } catch (error) {
            if ((error as SAMError).code === 21) {
                // If the sync group directory (assets/adobe-libraries) does not exist, we can't listen for changes.
                // This is expected if the user has not yet created a library.
                return;
            }
            throw error;
        }
        if (!syncGroupDirectory) {
            delete this._syncGroupListener;
            return;
        }
        this._syncGroupListener.asset = syncGroupDirectory;
        syncGroupDirectory.on('change', cb);
    }

    removeLibrariesSyncGroupListener() {
        if (this._syncGroupListener) {
            const { asset, notify } = this._syncGroupListener;
            asset?.off('change', notify);
            delete this._syncGroupListener;
        }
    }
}
