import type { IAdobeAssetOrderBy } from '../interface/AssetModel';

import type { IComparatorMap } from '../core/ItemOrder';
import { compareStrings, compareValues, createItemOrderFactory } from '../core/ItemOrder';
import type AdobeAsset from './AdobeAsset';

export type AdobeAssetOrderField =
    | 'name'
    | 'created'
    | 'modified'
    | 'shared'
    | 'lastAccessed';

export const OrderFieldToIAdobeAssetOrderBy: { [key in AdobeAssetOrderField]: IAdobeAssetOrderBy } = {
    'name': 'repo:name',
    'created': 'storage:deviceCreateDate',
    'modified': 'storage:deviceModifyDate',
    // R-API doesn't sort on share date
    'shared': 'storage:deviceModifyDate',
    // R-API: doesn't sort on lastAccessed
    'lastAccessed': 'storage:deviceModifyDate'
};

const OrderFieldToComparator: IComparatorMap<AdobeAsset, AdobeAssetOrderField> = {
    name(a: AdobeAsset, b: AdobeAsset): number {
        return compareStrings(a.name, b.name);
    },
    created(a: AdobeAsset, b: AdobeAsset): number {
        return compareValues(a.created, b.created);
    },
    modified(a: AdobeAsset, b: AdobeAsset): number {
        return compareValues(a.modified, b.modified);
    },
    shared(a: AdobeAsset, b: AdobeAsset): number {
        return compareValues(a.shared, b.shared);
    },
    lastAccessed(a: AdobeAsset, b: AdobeAsset): number {
        return compareValues(a.lastAccessed, b.lastAccessed);
    }
};

export default class AdobeAssetOrder extends createItemOrderFactory(OrderFieldToComparator) {
    static default = new AdobeAssetOrder('descending', 'modified');
}
