/**
 * Utility that short term caches promises based on the provided arguments to produce
 * the promise from a factory function.
 *
 * @export
 * @param {(...args: Array<any>) => Promise<any>} _asyncFn Promise delivering function that we wish to cache using parameters as key
 * @returns {Promise<any>} Cached or fresh promise based on provided arguments
 */
export default function promiseCache(_asyncFn: (...args: Array<any>) => Promise<any>) {
    const _cache = new Map<string, Promise<any>>();
    return (...args: Array<any>) => {
        const serializedArgs = JSON.stringify(args);
        const cachedPromise = _cache.get(serializedArgs);
        if (cachedPromise) {return cachedPromise;}

        const newPromise = _asyncFn.apply(undefined, args);
        _cache.set(serializedArgs, newPromise);
        setTimeout(() => newPromise.finally(() => _cache.delete(serializedArgs)));
        return newPromise;
    };
}
