import type AssetVersion from './AssetVersion';
import AdobeAsset from './AdobeAsset';
import type { ISAMCorePrivate } from '../indexPrivate';
import Resource from './Resource';
import { RelType } from '../interface/LinkUtils';

// ManifestResource is a Resource that represents the manifest of an AdobeAsset or AssetVersion.
export default class ManifestResource extends Resource<any> {

    constructor(
        readonly _core: ISAMCorePrivate,
        readonly _parent: AdobeAsset | AssetVersion,
    ) {
        super(_core);
    }

    protected async _loadData() {
        // TODO: check for graphQL
        if (this._parent instanceof AdobeAsset) {
            await (this._parent as AdobeAsset)._ensureLink(RelType.MANIFEST);
        }
        const assetInterface = await this._parent._getAssetInterface();
        await assetInterface.getManifest(this);
    }
}
