import { gql } from '@apollo/client';
import { repoMetadataFragment, appMetadataFragment } from './fragments';

const assetFragments = repoMetadataFragment + appMetadataFragment;

const query = assetFragments + `
query generationHistoryListing($relativePath: String!, $first: Int!, $after: String, $orderBy: [OrderByInput], $filter: AssetFilter) {
  homeFolder: resolveUserHome {
    id: repo_assetId

    ... on Directory {
      fireflyGenerationsDirectory: assetByRelativePath(
        relativePath: $relativePath
      ) {
        id: repo_assetId
        name: repo_name
        ... on Directory {
          generationAssetsConnection: childrenConnection(first: $first, after: $after, orderBy: $orderBy, filter: $filter) {
            pageInfo {
              hasNextPage
              endCursor
            }
            assets: edges {
              cursor
              node {
                ...repoMetadata
                ...applicationMetadata
                ... on Composite @defer {
                  manifest
                }
              }
            }
          }
        }
      }
    }
  }
}
`;

export const generationHistoryAssets = gql`${query}`;
