import InterfaceBase from './InterfaceBase';
import type ISAMCorePrivate from '../core/ISAMCorePrivate';
import type {
    IAddressBookGroupMembersFlat,
    IAddressBookList,
    IAddressBookContact,
    IResolveAddressBookGroupResponse
} from './AddressBookModel';

class AddressBookInterface extends InterfaceBase {
    constructor(
        _core: ISAMCorePrivate
    ) { super(_core); }

    get endpoint() {
        return `https://${this._core._environment.endpoints.ABS_HOST}`;
    }

    async getAddressBookURL(addressBookUrn: string): Promise<string> {
        const result = await this._getResponse<IResolveAddressBookGroupResponse>(`${this.endpoint}/api/urns/resolve/${addressBookUrn}`);
        return result.url;
    }

    async getMembersFirstPage(addressBookUrl: string, limit: number = 100): Promise<IAddressBookGroupMembersFlat> {
        return this._getResponse(`${addressBookUrl}/members/flat?limit=${limit}`);
    }

    async getMembersNextPage(nextPageLink: string): Promise<IAddressBookGroupMembersFlat> {
        return this._getResponse(nextPageLink);
    }

    async getAddressBooks(limit: number = 100): Promise<IAddressBookList> {
        return this._getResponse<IAddressBookList>(`${this.endpoint}/api/address-books?limit=${limit}`);
    }

    async getContactInAddressBook(addressBookIdent: string, userId: string): Promise<IAddressBookContact> {
        return this._getResponse<IAddressBookContact>(`${this.endpoint}/api/address-books/${addressBookIdent}/contacts?linkedIdentity=${userId}`);
    }
}

export default AddressBookInterface;
