import type { UnderlyingError } from '../errors/LibraryError';
import LibraryError from '../errors/LibraryError';

type APIVersionInfo = {
    apiVersion: number;
    apiMinVersion: number;
    apiMaxVersion: number;
};

type SuccessfulConnectionInfo = Partial<APIVersionInfo> & {
    token: string;
    hostname: string;
};

type UpdateRequiredConnectionInfo = Partial<APIVersionInfo> & {
    updateRequired: 'client' | 'server';
};

export type ConnectionInfo = SuccessfulConnectionInfo | UpdateRequiredConnectionInfo;

export function isUpdateRequiredInfo(info: ConnectionInfo): info is UpdateRequiredConnectionInfo {
    return 'updateRequired' in info;
}

export type VulcanCallback = (message: string) => void;

export type VulcanMessageType = {
    REQUEST: string;
    RESPONSE: string;
    INITIALIZE: string | null;
};

export default abstract class Connector<VulcanInterface, VulcanMessage> {
    protected vulcanInterface: VulcanInterface;
    protected VulcanMessage: VulcanMessage;
    private _timeout: number;
    private _launchTimeout: number;
    private _timeoutId?: number;

    constructor(vulcanInterface: VulcanInterface, vulcanMessage?: VulcanMessage, timeout = 2000, launchTimeout = 8000) {
        this.vulcanInterface = vulcanInterface;
        this.VulcanMessage = vulcanMessage as VulcanMessage;
        this._timeout = timeout;
        this._launchTimeout = launchTimeout;
    }

    private _generateListener(callback: Function, type?: string): VulcanCallback {
        const listener: VulcanCallback = (message?: string) => {
            clearTimeout(this._timeoutId);
            this.removeListener(listener, type);
            callback(message);
        };
        return listener;
    }

    private async _connectionInfoHandler(message?: string, abortSignal?: AbortSignal): Promise<ConnectionInfo | void> {
        if (abortSignal?.aborted) {
            // At this point the overarching connect workflow has timed out.
            // So we do not want to throw here
            return;
        }

        if (!message) {
            throw new LibraryError('REQUEST_FAILED', 'No Vulcan response received');
        }

        try {
            const payload = JSON.parse(this.getPayload(message));
            const apiVersionInfo: APIVersionInfo = {
                apiVersion: payload.apiVersion,
                apiMinVersion: payload.apiMinVersion,
                apiMaxVersion: payload.apiMaxVersion
            };
            if (payload.updateRequired) {
                return {
                    ...apiVersionInfo,
                    updateRequired: payload.updateRequired
                };
            }
            if (payload.serviceToken && payload.serviceHostname) {
                return {
                    ...apiVersionInfo,
                    token: payload.serviceToken,
                    hostname: payload.serviceHostname
                };
            }
            throw new LibraryError('INVALID_RESPONSE', 'Incorrect data was returned via Vulcan');
        } catch (error) {
            throw new LibraryError(
                'INVALID_RESPONSE',
                'Incorrect data was returned via Vulcan',
                undefined,
                error as UnderlyingError
            );
        }
    }

    private async _launchProcessHandler(message?: string, abortSignal?: AbortSignal) {
        if (abortSignal?.aborted) {
            // At this point the overarching connect workflow has timed out.
            // So we do not want to throw here
            return;
        }

        if (!message) {
            throw new LibraryError('REQUEST_FAILED', 'No Vulcan response received');
        }
        return this._requestConnectionInfo(abortSignal);
    }

    private _launchProcess(abortSignal?: AbortSignal) {
        return new Promise<ConnectionInfo | void>(resolve => {
            const launchProcessCallback = this._generateListener(
                (message: string) => resolve(this._launchProcessHandler(message, abortSignal)),
                this.getMessageType('INITIALIZE') as string
            );
            this._timeoutId = setTimeout(launchProcessCallback, this._launchTimeout);
            this.sendMessage(launchProcessCallback, this.getMessageType('INITIALIZE') as string);
            this.launchApp(launchProcessCallback);
        });
    }

    private _requestConnectionInfo(abortSignal?: AbortSignal): Promise<ConnectionInfo | void> {
        return new Promise(resolve => {
            const connectionInfoCallback = this._generateListener((message?: string) => {
                resolve(this._connectionInfoHandler(message, abortSignal));
            });
            this._timeoutId = setTimeout(connectionInfoCallback, this._timeout);
            this.sendMessage(connectionInfoCallback);
        });
    }

    public async connect(abortSignal?: AbortSignal) {
        // Always try connecting first. (local process running bug where connection info is not broadcasted)
        return this._requestConnectionInfo(abortSignal).catch(async err => {
            if (!(await this.isAppRunning().catch(() => false))) {
                return this._launchProcess(abortSignal);
            }
            throw err;
        });
    }

    protected getMessageType(key: keyof VulcanMessageType) {
        return this.messageTypes[key];
    }

    protected abstract messageTypes: VulcanMessageType;
    abstract removeListener(callback: VulcanCallback, type?: string): void;
    abstract sendMessage(callback: VulcanCallback, type?: string): void;
    abstract isAppRunning(): Promise<boolean>;
    abstract launchApp(callback: VulcanCallback): void;
    abstract getPayload(message: string | VulcanMessage): string;
}
