import { SAM } from '@ccx-public/component-types';
import {
    type IExplicitFilter,
    type ItemFilterRelation
} from '../core/ItemFilter';
import type { default as Project } from './Project';
import { ProjectDirectorySubtype } from '../interface/ProjectsModel';

/**
 * Account type values from IMS.
 * - 'type1' (CCI) - Individual Creative Cloud users
 * - 'type2' (CCT) - Teams users
 * - 'type2e' - CCE variant
 * - 'type3' (CCE) - Enterprise users
 */
export type AccountType = 'type1' | 'type2' | 'type2e' | 'type3';

type PrivateProjectFilterOptions = {
    /**
     * Use isDiscarded going forward.
     * @deprecated;
     */
    _isDiscarded?: boolean;
    view?: SAM.ProjectViews;
    repositoryID?: string;
    organizationID?: string;
    nameContains?: string;
    /**
     * Public facing filter for fetching and filtering
     * discarded projects from the projects service.
     */
    isDiscarded?: boolean;
    directorySubtypes?: ProjectDirectorySubtype[];
    /**
     * The account type of the logged-in user. Required for Yours view to determine
     * which PLS query to use (businessStorage for CCE/CCT, yours for CCI).
     * Clients should obtain this value from IMS.
     */
    accountType?: AccountType;
}

const DIRECT_COMPARE_VIEWS = [ SAM.ProjectViews.Yours, SAM.ProjectViews.SWY ];

export default class ProjectFilter implements IExplicitFilter<Project> {
    private _isDiscarded: boolean;
    private _view: SAM.ProjectViews = SAM.ProjectViews.All;
    private _repositoryID?: string;
    private _nameContains?: string;
    private _organizationID?: string;
    private _directorySubtypes?: ProjectDirectorySubtype[] = [
        // Default to CC_PROJECTS because the service just defaults to
        // returning CC_PROJECTS if no directorySubtypes are provided.
        ProjectDirectorySubtype.CC_PROJECTS
    ];
    private _accountType?: AccountType;

    /**
     * @deprecated — A breaking API change has been introduced
     *    to ProjectFilter that makes this static filter not work correctly for USM accounts.
     *    must pass `accountType` (type1, type2, type2e, type3) along with view=Yours to get the correct
     *    listing for both USM and ESM accounts.
     */
    static YourProjects = new ProjectFilter({
        view: SAM.ProjectViews.Yours
    });

    static AllProjects = new ProjectFilter({
        view: SAM.ProjectViews.All
    });

    static SWYProjects = new ProjectFilter({
        view: SAM.ProjectViews.SWY
    });

    static AdminProjects = new ProjectFilter({
        view: SAM.ProjectViews.Admin
    });

    constructor(
        options: PrivateProjectFilterOptions = {
            view: SAM.ProjectViews.All
        }
    ) {
        const { _isDiscarded, view, repositoryID, organizationID, nameContains, isDiscarded, directorySubtypes, accountType } = options;
        this._isDiscarded = !!(_isDiscarded || isDiscarded);
        if (view !== undefined) {
            this._view = view;
        }
        this._repositoryID = repositoryID;
        this._organizationID = organizationID;
        // @TODO Eventually just store the sorted name with no whitespace in the array
        // so we don't have to do it in multiple places.
        this._nameContains = nameContains;
        this._directorySubtypes = directorySubtypes ?? this._directorySubtypes;
        this._accountType = accountType;
    }

    get hash(): string {
        return `discarded=${this._isDiscarded}view=${this._view}repositoryId=${this._repositoryID}`
       + `orgID=${this._organizationID || ''}nameContains=${this._nameContains}directorySubtype=${this._directorySubtypes?.sort().join('')}`
       + `accountType=${this._accountType || ''}`;
    }

    get view(): SAM.ProjectViews {
        return this._view;
    }

    /**
     * @TODO_Deprecation will be marked as deprecated on or after 2025-01-01 and removed on or after 2025-03-01
     *    Use ownerIDs instead.
     */
    get repositoryID(): string | undefined {
        return this._repositoryID;
    }

    get nameContains(): string | undefined {
        return this._nameContains;
    }

    get isDiscarded(): boolean {
        return this._isDiscarded;
    }

    /**
     *
     * @TODO https://jira.corp.adobe.com/browse/SHARED-3489
     */
    private _searchTarget(searchString: string, targetString: string): boolean {
        const searchTerms = searchString.toLowerCase().split(/\s+/);
        const targetTerms = targetString.toLowerCase().split(/\s+/);

        // Empty word or search term
        if (searchTerms.length === 0 || targetTerms.length === 0) {
            return false;
        }

        return searchTerms.every((searchTerm) => {
            return targetTerms.find((targetTerm) => {
                return targetTerm.startsWith(searchTerm);
            });
        });
    }

    get organizationID(): string | undefined {
        return this._organizationID;
    }

    get directorySubtypes(): ProjectDirectorySubtype[] | undefined {
        return this._directorySubtypes;
    }

    get accountType(): AccountType | undefined {
        return this._accountType;
    }

    matches(item: Project): boolean {
        // Note: ImplicitProjectFilter requires Project to be either _isRecent or _allowInLists

        // We don't want to allow any matching for the Recent project listing
        // TODO: once we have support for lastAccessDate from projects service, we should use that instead.
        if (this._view === SAM.ProjectViews.Recent && !item._isRecent) {
            return false;
        }

        // For views other than Recent, only allow _isRecent Project if it was also seen in some other listing from the
        // service (All, Yours, etc)
        if (this.view !== SAM.ProjectViews.Recent && item._isRecent && !item._allowInLists) {
            return false;
        }

        if (!item.isProject) {
            return false;
        }

        if (item.isDiscarded !== this._isDiscarded) {
            return false;
        }

        // For Admin view: If specified, match on repositoryID
        if (this._repositoryID && this._repositoryID !== item.repositoryID) {
            return false;
        }

        // For view = Organization or Admin, filter by organizationID
        if (this._organizationID && this._organizationID !== item.repositoryOwner.id) {
            return false;
        }

        if (this._directorySubtypes?.length && !this._directorySubtypes.includes(item.directorySubtype)) {
            return false;
        }


        const nameContains = this._nameContains;
        if (nameContains
            && !this._searchTarget(nameContains, item.name)
        ) {
            return false;
        }

        // Project.view computes Yours and SWY
        if (DIRECT_COMPARE_VIEWS.includes(this._view) && !item._views.includes(this._view)) {
            return false;
        }

        // this.view is undefined, All, or Admin
        return true;
    }

    // Project views have a lot of overlap such that none are fully disjoint or subset and should always go to the
    // service for the correct list. Note: "unknown" lists that are fully loaded can be used to populate other lists,
    // which can cause unexpected results. E.g., if one list has 10 items loaded and limit = 5, then switching to a
    // different list with relation "unknown" would load 5 items from the service but show 10 items in the list.
    getRelationToFilter(_other: ProjectFilter): ItemFilterRelation {
        return 'disjoint';
    }
}
