import { gql } from '../generated/typed-gql';

export const getAssetById = gql(
    /* GraphQL */
    `
    query getAssetById($assetId: ID!) {
        resolveAssetById(assetId: $assetId) {
            labels {
                lastAccessDate
                favorite {
                    isFavorite
                }
            }
            ...repoMetadata
            ...applicationMetadata
            ...effectivePermissions
            # Directory specific fields
            ... on Directory {
                pageLink {
                    href
                    linkType
                    templated
                }
                blockUploadLink {
                    href
                    linkType
                    templated
                }
            }
        }
    }
`);
