import AsyncOperation from './AsyncOperation';

export default class ProgressiveLoader<T> extends AsyncOperation {
    private _results: T[] = [];

    constructor(private _generator: (signal: AbortSignal) => AsyncIterableIterator<T[]>) {
        super();
        this._getPages();
    }

    private async _getPages() {
        for await (const page of this._generator(this._abortController.signal)) {
            this._results.push(...page);
            this.emit('change', false);
        }

        this.progress = 100;
        this.emit('change', true);
    }

    get results() {
        return this._results;
    }
}
