import { synchronized, key } from './decorators';
import SAMError, { SAMErrorCode } from './SAMError';
import type { ISAMCorePrivate, ISAMObject } from '../indexPrivate';

type TransactionType = 'readonly' | 'readwrite';
type RequestsFn = (objectStore: IDBObjectStore) => Promise<any> | any;

export type CachedValue = {
    value?: any,
    expiry?: Date
};

export const NotFound = Symbol('NotFound');

export interface IPersistentCache {
    getItem(itemKey: string): Promise<CachedValue | undefined>;
    setItem(itemKey: string, value: any, expiry?: Date): Promise<void>;
    deleteItem(itemKey: string): Promise<void>;
}

// Persistent cache based on indexedDB
class IndexedDBCache implements IPersistentCache {

    constructor(protected _name: string, protected _core: ISAMCorePrivate) {}

    private _database?: IDBDatabase;

    static isSupported(): boolean {
        if (typeof window === 'undefined' || !window.indexedDB) {
            return false;
        }

        try {
            const request = window.indexedDB.open('sam_indexeddb_test', 1);
            request.onsuccess = () => request.result.close();
            return true;
        } catch (error) {
            return false;
        }
    }

    private async _transaction(transactionType: TransactionType, requestsFn: RequestsFn): Promise<any> {
        const database = await this._connect();
        if (!database) {
            return;
        }

        return new Promise((resolve) => {
            try {
                const transaction = database.transaction(this._name, transactionType);
                const objectStore = transaction.objectStore(this._name);
                const promResult = requestsFn(objectStore);
                transaction.onerror = (err) => {
                    this._core._environment.error(`transaction error: ${err}`);
                    resolve(undefined);
                };
                transaction.oncomplete = () => {
                    resolve(promResult);
                };
            } catch (ex) {
                // this can happens due to version upgrade when we close db.
                this._core._environment.error(`transaction exception: ${ex}`);
                resolve(undefined);
            }
        });
    }

    async getItem(itemKey: string): Promise<CachedValue | undefined> {
        return this._transaction('readonly', async (objectStore: IDBObjectStore) => {
            return new Promise((resolve) => {
                const request = objectStore.get(itemKey);
                request.onsuccess = () => {
                    resolve(request.result ? {
                        value: request.result.value,
                        expiry: request.result.expiry as Date
                    } : undefined);
                };
            });
        });
    }

    async setItem(itemKey: string, value: any, expiry?: Date): Promise<void> {
        return this._transaction('readwrite', (objectStore: IDBObjectStore) => {
            objectStore.put({ id: itemKey, expiry, value });
            return;
        });
    }

    async deleteItem(itemKey: string): Promise<void> {
        return this._transaction('readwrite', (objectStore: IDBObjectStore) => {
            objectStore.delete(itemKey);
            return;
        });
    }

    private async _connect(): Promise<IDBDatabase | undefined> {
        if (this._database) {
            return this._database;
        }
        const version = this._core._environment.getValue('INDEXED_DB_VERSION');
        const request = window.indexedDB.open(this._name, version);

        return new Promise((resolve) => {
            request.onerror = (err) => {
                this._core._environment.error(`CONNECTION_FAILED Unable to connect to IndexedDB: ${this._name}, error: ${err}`);
                resolve(undefined);
            };

            request.onupgradeneeded = () => {
                const database = request.result;
                if (database.objectStoreNames.contains(this._name)) {
                    database.deleteObjectStore(this._name);
                }
                database.createObjectStore(this._name, { keyPath: 'id' });
            };

            request.onsuccess = () => {
                const database = this._database = request.result;
                database.onversionchange = (evt) => {
                    this._core._environment.error(`IndexedDb version changed detected ${this._name}.${version}, ${evt}`);
                    // close current db connection allowing the other client to upgrade a version
                    database.close();
                    database.onversionchange = null;
                    this._database = undefined;
                };
                resolve(database);
            };
        });
    }

    // @ts-expect-error -- for use in console debugging
    private async _clear(): Promise<void> {
        return this._transaction('readwrite', async (objectStore: IDBObjectStore) => {
            return new Promise((resolve) => {
                const request = objectStore.clear();
                request.onsuccess = () => {
                    // eslint-disable-next-line no-console
                    console.log('localDB cleared for', objectStore.name);
                    resolve(undefined);
                };
            });
        });
    }
}

// Persistent cache based on localStorage
class LocalStorageCache implements IPersistentCache {

    constructor(protected _name: string, protected _core: ISAMCorePrivate) {}

    static isSupported(): boolean {
        try {
            return typeof window !== 'undefined' && !!window.localStorage;
        } catch (e) {
            // Firefox throws an exception when accessing localStorage in private mode
            return false;
        }
    }

    private _getKey(itemKey: string): string {
        return `${this._name}#${itemKey}`;
    }

    async getItem(itemKey: string): Promise<CachedValue | undefined> {
        const storedValue = window.localStorage.getItem(this._getKey(itemKey));
        if (storedValue) {
            try {
                const { value, expiry } = JSON.parse(storedValue);
                return {
                    value,
                    expiry: expiry ? new Date(expiry as string) : undefined
                };
            } catch (e) {
                // ignore
            }
        }
        return undefined;
    }

    async setItem(itemKey: string, value: any, expiry?: Date): Promise<void> {
        const storedValue = JSON.stringify({ expiry, value });
        window.localStorage.setItem(this._getKey(itemKey), storedValue);
    }

    async deleteItem(itemKey: string): Promise<void> {
        window.localStorage.removeItem(this._getKey(itemKey));
    }
}

interface InMemoryCachedValue extends CachedValue {
    cleanupTimeout: ReturnType<typeof setTimeout>;
}

/**
 * An in-memory cache that automatically expires items after a certain time,
 * so as to avoid memory growing unbounded. Items will be evicted after
 * MAX_TIME_IN_MEMORY_MS or the expiry time, whichever is sooner.
 * In the implementation in SAM, this is mostly just a performance optimization,
 * because entries will still be included in the persistent cache.
 */
export class InMemoryCache {
    static MAX_TIME_IN_MEMORY_MS = 60 * 1000; // 1 minute
    items: Map<string, InMemoryCachedValue> = new Map<string, InMemoryCachedValue>();

    getItem(itemKey: string) {
        return this.items.get(itemKey);
    }

    setItem(itemKey: string, value: any, expiry?: Date) {
        const existingItem = this.items.get(itemKey);
        if (existingItem) {
            clearTimeout(existingItem.cleanupTimeout);
        }

        const requestedExpiry = expiry?.getTime() ?? Date.now() + InMemoryCache.MAX_TIME_IN_MEMORY_MS;
        const cleanupTime = Math.min(InMemoryCache.MAX_TIME_IN_MEMORY_MS, requestedExpiry - Date.now());
        const cleanupTimeout = setTimeout(() => {
            this.deleteItem(itemKey);
        }, cleanupTime);
        this.items.set(itemKey, { value, expiry, cleanupTimeout });
    }

    deleteItem(itemKey: string) {
        const item = this.items.get(itemKey);
        if (item) {
            clearTimeout(item.cleanupTimeout);
        }
        this.items.delete(itemKey);
    }
}

/**
 * Persistent cache of values using indexedDB - if the browser doesn't support indexedDB it falls back to localStorage,
 * and if neither is supported it'll just use a local in-memory cache that doesn't persist between sessions.
 */
export default class Cache implements ISAMObject {

    private _name: string;

    // Persistent cache layer - either indexedDB, localStorage, or neither if none are supported (e.g. in private browsing)
    private _persistentCache?: IPersistentCache;

    // Local cache layer - this is an optimization if there's no persistent cache layer
    private _localCache = new InMemoryCache();

    constructor(private _userId: string, readonly _core: ISAMCorePrivate, _persistentCache?: IPersistentCache) {
        this._name = 'SAM.js-' + this._userId;

        if (_persistentCache) {
            // Clients can override SAM.js to use their own caching layer if required
            this._persistentCache = _persistentCache;
        } else if (IndexedDBCache.isSupported()) {
            this._persistentCache = new IndexedDBCache(this._name, _core);
        } else if (LocalStorageCache.isSupported()) {
            this._persistentCache = new LocalStorageCache(this._name, _core);
        }
    }

    get name(): string {
        return this._name;
    }

    @synchronized
    async getItem(@key itemKey: string, computeValue?: () => Promise<any>, validateValue?: (value: any) => boolean, expiryMs?: number): Promise<any> {
        let cachedItem: CachedValue | undefined = this._localCache.getItem(itemKey);

        if (!cachedItem && this._persistentCache) {
            cachedItem = await this._persistentCache.getItem(itemKey);
        }

        // Check if the cached item expired or invalid - if so, ignore it
        const isInvalid = validateValue && cachedItem && !validateValue(cachedItem.value);
        const isExpired = cachedItem?.expiry && cachedItem.expiry <= new Date(Date.now());
        if (isInvalid || isExpired) {
            await this.deleteItem(itemKey);
            cachedItem = undefined;
        }

        // If we're passed in a computeValue function, use it to update the cache if there's no
        // cached value (or it expired)
        if (!cachedItem && computeValue) {
            const value = await computeValue();
            if (validateValue && !validateValue(value)) {
                throw SAMError.create(SAMErrorCode.UNKNOWN, `Value for cache key ${itemKey} is invalid: ${JSON.stringify(value)}`);
            }
            await this.setItem(itemKey, value, expiryMs);
            return value;
        }

        return cachedItem ? cachedItem.value : NotFound;
    }

    async setItem(itemKey: string, value: any, expirationDurMsec: number = this._core._environment.getValue('CACHE_DEFAULT_TTL')): Promise<void> {
        const expiry = expirationDurMsec ? new Date(Date.now() + expirationDurMsec) : undefined;
        // NOTE: _localCache has its own eviction policy that takes priority if it is < expiry. This
        // keeps _localCache from growing unbounded during a session, while still optimizing reads
        // from persistent cache.
        this._localCache.setItem(itemKey, value, expiry);

        if (this._persistentCache) {
            await this._persistentCache.setItem(itemKey, value, expiry);
        }
    }

    async deleteItem(itemKey: string): Promise<void> {
        this._localCache.deleteItem(itemKey);
        if (this._persistentCache) {
            await this._persistentCache.deleteItem(itemKey);
        }
    }
}
