/**
 * ParallelOperation
 * @packageDocumentation
 * @module ParallelOperation
 * @internal
 */

import type { Action } from '../models/Action';

import type { ExecuteResult } from './Operation';
import Operation, { validatesOperation } from './Operation';
import type Driver from './Driver';

/**
 * ParallelOperation
 *
 * An operation that can execute several actions at the same time.
 *
 * Actions in a ParallelOperation should be able to run without affecting or
 * being affected by other actions that may run concurrently.
 */
export default abstract class ParallelOperation<T extends Driver = Driver> extends Operation<T> {
    protected _actionMappers: { [s: string]: (action: Action) => Promise<Action> } = {};

    @validatesOperation
    async execute(): Promise<ExecuteResult> {
        const promises = this.actions.map(action => this._actionMappers[action.name as string](action));
        // TODO: What about allSettled?
        return { actions: await Promise.all(promises) };
    }
}
