export type GroupRequest = {
    group: {
        /** Group name */
        name: string;
        /**
         * Group namespace. Currently defaults to $default. The default should be used unless there's
         * a specific case to provide a custom classifiers. Non-default classifiers are presently not
         * supported in any applications.
         */
        classifier?: string;
        /**
         * Lexicographical string for setting the group's place in the group list, or for an element's
         * place within a group. The client is responsible for providing and sorting using these strings.
         */
        order: string;
        /**
         * Defines a relationship between nested groups. If provided, and the specified parent group
         * exists, this group will be the "child" of the parent group. If there is no group in the
         * library that matches the supplied parentId the group will still be created or updated with
         * an empty parentId.
         */
        parent_id?: string;
    };
    client?: ClientInfo;
    /** Id of group to copy. If present, self cannot be present and target must be present */
    source?: string;
    /** Id of group to move. If present, source cannot be present and target must be present */
    self?: string;
    /**
     * Library id to copy or move group into. Can only equal source as a group cannot be moved into
     * the same library.
     */
    target?: string;
    /** Id of group to set as copied/moved groups parent. */
    parentId?: string;
};

