const allowedRepresentationCustomData = [
    'color#data',
    'colortheme#data',
    'channel#data',
    'imageguideline#data',
    'gradient#data',
    'audio#data',
    'font#data',
    'characterstyle#data',
    'paragraphstyle#data',
    'text#data',
    '3d#data',
    'video#data',
    'pattern#data',
    'candy#data',
    'graphic#data',
    // TODO: For Firefly POC purposes.
    'clio#data',
    'firefly#cme'
] as const;

type AllowedRepresentationCustomData = (typeof allowedRepresentationCustomData)[number];

export function isRepresentationPreflightResponse(
    data: any | RepresentationPreflightResponse
): data is RepresentationPreflightResponse {
    return (
        data?.id
        && data?.storage_href
        && data?.asset_id
        && data?.type
        && data?.content_length
        && data?.etag
        && data?.version
    );
}

export type RepresentationRequestCustomData = Partial<{ [key in AllowedRepresentationCustomData]: any }>;

