export function mapResponseToRepresentationData(representationResponse: RepresentationResponse): RepresentationData {
    return {
        id: representationResponse.id,
        type: representationResponse.type,
        linktype: representationResponse.linktype,
        relationship: representationResponse.relationship,
        isFullSize: representationResponse.is_full_size as boolean,
        isExternalLink: representationResponse.is_external_link as boolean,
        height: representationResponse.height,
        width: representationResponse.width,
        contentLength: representationResponse.content_length,
        url: representationResponse._links?.['http://ns.adobe.com/melville/rel/primary']?.href,
        blockDownloadUrl: representationResponse._links?.['http://ns.adobe.com/melville/rel/download']?.href,
        customData: {
            'channel#data': representationResponse['channel#data'],
            'imageguideline#data': representationResponse['imageguideline#data'],
            'color#data': representationResponse['color#data'],
            'characterstyle#data': representationResponse['characterstyle#data'],
            'paragraphstyle#data': representationResponse['paragraphstyle#data'],
            'gradient#data': representationResponse['gradient#data'],
            'colortheme#data': representationResponse['colortheme#data'],
            'font#data': representationResponse['font#data'],
            'adobestock#trackingdata': representationResponse['adobestock#trackingdata'],
            'firefly#cme': representationResponse['firefly#cme']
        }
    };
}

export function mapResponseToTeamData(teamResponse: TeamResponse): TeamData {
    return {
        name: teamResponse.name,
        id: teamResponse.id,
        isWritable: teamResponse.collaboratorRole === 'editor',
        owner: teamResponse.repositoryOwner,
        ownerName: teamResponse.repositoryName
    };
}

export function mapLibraryDataToRequest(libraryData: Partial<LibraryData>): Partial<LibraryRequest> {
    return {
        name: libraryData.name,
        document_id: libraryData.documentId,
        roles: libraryData.roles,
        description: libraryData.description,
        ...extractCustomData(libraryData.customData)
    };
}

export function mapElementDataToElementMetadata(elementData: Partial<ElementData>): Partial<ElementMetadata> {
    return {
        id: elementData.id,
        name: elementData.name,
        roles: elementData.roles,
        description: elementData.description,
        tags: elementData.tags,
        sourceRef: elementData.sourceRef,
        group: elementData.groups?.[0],
        ...extractCustomData(elementData.customData)
    };
}

export function mapSearchResponseToElementData(searchResponse: SearchElementResponse): ElementData {
    return {
        id: searchResponse.id,
        libraryAssetId: searchResponse.parent_id,
        name: searchResponse.name,
        type: searchResponse.type,
        createdDate: searchResponse.created_date,
        modifiedDate: searchResponse.modified_date,
        renditionUrl: searchResponse.thumbnail.rendition,
        tags: searchResponse.tags,
        roles: searchResponse.roles,
        representations: searchResponse.representations.map(mapResponseToRepresentationData),
        groups: (searchResponse.groups || []).map(mapResponseToGroupMembershipData)
    };
}

export function mapRepresentationDataToRequest(
    representationData: RepresentationData
): RepresentationRequest & Partial<RepresentationPreflightResponse> {
    const source = isRepresentationPreflightResponse(representationData.source) ? representationData.source : undefined;

    return {
        id: source?.id ?? representationData.id,
        type: source?.type ?? representationData.type,
        relationship: representationData.relationship as 'primary' | 'rendition',
        path: representationData.path as string,
        is_full_size: representationData.isFullSize,
        is_external_link: representationData.isExternalLink,
        width: source?.width ?? (representationData.width as number),
        height: source?.height ?? (representationData.height as number),
        content_length: source?.content_length ?? (representationData.contentLength as number),
        is_preferred_thumbnail: representationData.isPreferredThumbnail as boolean,
        name: source?.name,
        storage_href: source?.storage_href,
        asset_id: source?.asset_id,
        etag: source?.etag,
        md5: source?.md5,
        version: source?.version,
        ...extractCustomData(representationData.customData, allowedRepresentationCustomData as any)
    };
}

function extractCustomData(
    customData: { [s: string]: any } = {},
    allowedKeys?: string[]
): RepresentationRequestCustomData {
    const result: RepresentationRequestCustomData = {};
    for (const [ key, value ] of Object.entries(customData)) {
        // Typescript is just not that smart
        const typedKey = key as AllowedRepresentationCustomData;

        // Allow keys by default if allowedKeys is undefined.
        // Melville will reject any keys it doesn't recognize.
        if (allowedKeys?.includes(typedKey) || !allowedKeys) {
            result[typedKey] = value;
        }
    }
    return result;
}

export function mapElementDataToRequest(elementData: Partial<ElementData>, clientInfo: ClientInfo) {
    return {
        ...mapElementDataToElementMetadata(elementData),
        client: clientInfo,
        type: elementData.type,
        representations: elementData.representations?.map(mapRepresentationDataToRequest)
    };
}

export function mapGroupDataToRequest(groupData: GroupData, clientInfo: ClientInfo): GroupRequest {
    return {
        group: {
            name: groupData.name,
            classifier: groupData.classifier,
            order: groupData.order,
            parent_id: groupData.parentId
        },
        client: clientInfo
    };
}
