import EventEmitter from 'events';
import type IEvent from './IEvent';
import type { IEventMap, GetEventNames } from './ITypedEventEmitter';

export * from './ITypedEventEmitter';

export const BECOME_OBSERVED = 'observed';
export const BECOME_UNOBSERVED = 'unobserved';

/**
 * Base class that can be used to create Typed SAMEvent Emitters.
 * @example:
 * class ClickEvent extends SAMEvent {
 *     myClickProp: string;
 *     constructor() {
 *         super('click');
 *     }
 * }
 *
 * class MyClass extends TypedEventEmitter<{ click: ClickEvent }>() {
 *     baseProp : string;
 * }
 *
 * const obj = new MyClass();
 * obj.on('click', (ev, sender, payload) => {
 *     // The ev object is typed based on the 'click' event.
 *     ev.myClickProp;
 * });
 *
 * subClass.dispatch(new ClickEvent());
 */
export default class TypedEventEmitter<EventMap extends IEventMap> extends EventEmitter {
    dispatch(ev: IEvent, payload?: any): boolean {
        return super.emit(ev.type, ev, this, payload);
    }
    once<AnEventType extends GetEventNames<EventMap>>(
        type: AnEventType,
        callback: (event: EventMap[AnEventType], sender: this, payload?: any) => void
    ): this {
        const result = super.once(type, callback);
        this._onEventListenerAdded();
        return result;
    }
    on<AnEventType extends GetEventNames<EventMap>>(
        type: AnEventType,
        callback: (event: EventMap[AnEventType], sender: this, payload?: any) => void
    ): this {
        // Prevent adding duplicate listeners
        if (this.listeners(type).includes(callback)) {
            return this;
        }
        const result = super.on(type, callback);
        if (type !== BECOME_OBSERVED && type !== BECOME_UNOBSERVED) {
            this._onEventListenerAdded();
            if (this.listenerCount(type) === 1) {
                this.emit(BECOME_OBSERVED, type);
            }
        }
        return result;
    }
    off<AnEventType extends GetEventNames<EventMap>>(
        type: AnEventType,
        callback: (event: EventMap[AnEventType], sender: this, payload?: any) => void
    ): this {
        const result = super.off(type, callback);
        if (type !== BECOME_OBSERVED && type !== BECOME_UNOBSERVED) {
            this._onEventListenerRemoved();
            if (this.listenerCount(type) === 0) {
                this.emit(BECOME_UNOBSERVED, type);
            }
        }
        return result;
    }
    // Called when a new event listener is added on the object.
    protected _onEventListenerAdded() {
    }

    protected _onEventListenerRemoved() {
    }
}
