import { vulcanQueryRequestPayload } from '../config/constants';
import getVulcanInterface from '../utils/Vulcan';
import type { IVulcan, IVulcanMessage, VulcanInterface } from '../utils/Vulcan/IVulcan';
import type { ConnectionInfo, VulcanCallback, VulcanMessageType } from './Connector';
import Connector from './Connector';

class CEPConnector extends Connector<VulcanInterface, IVulcanMessage> {
    protected messageTypes: VulcanMessageType = {
        REQUEST: 'vulcan.SuiteMessage.cclibraries.api.QueryRequest',
        RESPONSE: 'vulcan.SuiteMessage.cclibraries.api.QueryResponse',
        INITIALIZE: 'vulcan.SuiteMessage.cclibraries.service.Initialized'
    };

    constructor(vulcanInterface: IVulcan, vulcanMessage: IVulcanMessage, timeout: number) {
        super(getVulcanInterface(vulcanInterface), vulcanMessage, timeout);
    }

    removeListener(callback: VulcanCallback, type?: string) {
        return this.vulcanInterface.removeMessageListener(type || this.messageTypes.RESPONSE, callback);
    }

    sendMessage(callback: VulcanCallback, type?: string) {
        // Add listener
        this.vulcanInterface.addMessageListener(type || this.messageTypes.RESPONSE, callback);
        // Send the request
        if (type !== this.messageTypes.INITIALIZE) {
            const request = new this.VulcanMessage(this.messageTypes.REQUEST);
            request.setPayload(vulcanQueryRequestPayload);
            this.vulcanInterface.dispatchMessage(request);
        }
    }

    async isAppRunning() {
        return this.vulcanInterface.isAppRunning();
    }

    launchApp(_callback: VulcanCallback) {
        this.vulcanInterface.launchApp();
    }

    getPayload(message: string) {
        return this.vulcanInterface.getPayload(message) as string;
    }
}

export default (
    VulcanInterface: IVulcan,
    VulcanMessage: IVulcanMessage,
    timeout = 8000
): ((abortSignal?: AbortSignal) => Promise<ConnectionInfo | void>) => {
    const connector = new CEPConnector(VulcanInterface, VulcanMessage, timeout);
    return (abortSignal?: AbortSignal) => connector.connect(abortSignal);
};
