import type { IEventMap } from './TypedEventEmitter';
import TypedEventEmitter from './TypedEventEmitter';
import SAMEvent from './SAMEvent';
import type { ItemId } from './ItemBase';
import type ItemBase from './ItemBase';
import WeakRef from './WeakRef';
import type { IUpdateSession, IUpdateSessionDelegate } from './UpdateSession';
import UpdateSession from './UpdateSession';
import type { ISAMCorePrivate, ISAMObject } from '../indexPrivate';
import type ItemList from './ItemList';
import { LOADER_UPDATE_CONTEXT } from './ItemList';

export const ITEMS_CHANGED = 'itemsChanged';
export const LIST_ADDED = 'listAdded';

export class ItemsChangedEvent<LocalType extends ItemBase> extends SAMEvent {
    constructor(
        readonly addedItems?: LocalType[],
        readonly changedItems?: LocalType[],
        readonly discardedItems?: LocalType[],
        readonly updateContext?: string,
    ) {
        super(ITEMS_CHANGED);
    }
}

export class ListAddedEvent extends SAMEvent {
    constructor() {
        super(LIST_ADDED);
    }
}

interface ItemPoolEventMap<LocalType extends ItemBase> extends IEventMap {
    [ITEMS_CHANGED]: ItemsChangedEvent<LocalType>;
    [LIST_ADDED]: ListAddedEvent;
}

export interface IItemPoolDelegate<LocalType extends ItemBase> {
    onItemsUpdated(event: ItemsChangedEvent<LocalType>, sender: ItemPool<LocalType>): void;
}

// We want to make sure that contexts delegates are added after all the lists,
// so that they can expect the contents of the lists to be updated already.
type PoolDelegatePriority = 'list' | 'context';

// Delegates are like events, but they keep weak references to the callbacks to
// prevent memory leaks caused by the subscriber forgetting to unsubscribe.
type IPoolDelegateRef<LocalType extends ItemBase> = {
    priority: PoolDelegatePriority;
    delegate: WeakRef<IItemPoolDelegate<LocalType>>;
};

function compareDelegatesByPriority<LocalType extends ItemBase>(
    a: IPoolDelegateRef<LocalType>, b: IPoolDelegateRef<LocalType>) {
    if (a.priority === b.priority) {
        return 0;
    }
    return a.priority === 'list' ? -1 : 1;
}

export type ItemType =
    | 'orgRepository'
    | 'team'
    | 'space'
    | 'asset'
    | 'collaborator'
    | 'collaboratorsByAssetID'
    | 'invitedCollaborator'
    | 'version'
    | 'project or adobeasset'
    | 'customModel'
    | 'assignment'
    | 'gradient'
    | 'frameio'
    | 'classroom'
    | 'comment'
    | 'studentAssignmentFile'
    | 'classroomMember'
    | 'studentAssignment'
    | 'addressBookContact'
    | 'addressBook'
    | 'element'
    | 'post'
    | 'board'
    | 'accessRequest';

/**
 * The ItemPool class is used to keep unique references in memory for objects that
 * represent cloud items like assets, teams or spaces.
 * The ItemPool helps with mapping between a remote id and a local reference in memory.
 *
 * On supported browsers the pool uses the WeakRef object to keep the objects alive.
 * only as long as they are used by the application.
 */
export default class ItemPool<LocalType extends ItemBase, IdType extends ItemId = ItemId>
    extends TypedEventEmitter<ItemPoolEventMap<LocalType>> implements ISAMObject {

    private _objectsById = new Map<ItemId, WeakRef<LocalType>>();
    private _discardedObjects = new WeakSet<LocalType>();
    private _delegates: IPoolDelegateRef<LocalType>[] = [];
    private _hasUnsortedDelegates: boolean = false;
    private _lists: WeakRef<ItemList<any, IdType>>[] = [];

    constructor(readonly _core: ISAMCorePrivate, readonly type: ItemType) {
        super();
    }

    private _getObjectsById<TypeExtendsLocal extends LocalType>() {
        return this._objectsById as Map<ItemId, WeakRef<TypeExtendsLocal>>;
    }

    /**
     * Looks up the item in the local in-memory storage.
     * The items are stored used WeakRef to avoid leaking. The client of this
     * method is responsible with keeping these objects alive for as long as
     * they are needed.
     * @param id
     * @returns
     */
    getLocalItemById = <TypeExtendsLocal extends LocalType>(id: IdType): TypeExtendsLocal | undefined => {
        const ref = this._getObjectsById<TypeExtendsLocal>().get(id);
        return ref?.deref();
    };

    /**
     * Fully removes items from the pool when `queueDiscardedItem()` alone is not sufficient.
     *
     * Normally, `queueDiscardedItem()` will remove an Item from the ItemPool, but it does not when it has been
     * modified in the same UpdateSession (using `updateLocalItem()` or `updateRemoteItem()`). When this occurs, you will need to call
     * `removeLocalItems()` afterwards to ensure the Item is fully removed from the pool.
     * This scenario typically occurs when an Item is permanently deleted or unshared
     * because we first need to update the permissions to None before removing in the same session.
     * Calling `removeLocalItems()` will prevent stale items from remaining in the pool after this update,
     * and ensure `getAssetWithCloudID()` returns `NOT_FOUND` instead of returning an item that has broken APIs.
     *
     * To ensure full removal, use:
     *     ```
     *     updateLocalItem(session, item, { effectivePermission: Permission.None });
     *     queueDiscardedItem(item);
     *     removeLocalItems([item.id]);  // Ensures full removal from the pool
     *     ```
     * If you are NOT updating the item in the same session, you only need to call `queueDiscardedItem()`.
     * 🚨 ** Calling `removeLocalItems()` without calling `queueDiscardedItem()` will NOT remove the Item from ItemLists. **
     */
    removeLocalItems = (ids: ItemId | ItemId[]): void => {
        if (Array.isArray(ids)) {
            ids.forEach((id: ItemId) => {
                this._objectsById.delete(id);
            });
            return;
        }
        this._objectsById.delete(ids);
    };

    isItemDiscarded = (item: LocalType): boolean => {
        return this._discardedObjects.has(item);
    };

    reindexItem = (item: LocalType, oldId: IdType, newId: IdType): void => {
        if (oldId !== newId) {
            this._objectsById.set(newId, new WeakRef(item));
            this._objectsById.delete(oldId);
        }
    };

    /**
     * Creates an UpdateSession instance for add/update/delete of models in the SAM system, outside of ItemLoaders.
     * UpdateSessions let you delay firing events until you're ready to notify clients via the commit--typically
     * right after updating the model with remote data via one or more ItemUpdaters.
     *
     * @param updateContext {string} (optional) Useful to identify what is causing a particular change, especially
     *        in ItemPool delegates.
     * @param mostRecentValidMutation {number} (optional) Determines if UpdateSession will allow the update (see
     *        {@link createLoaderUpdateSession})
     */
    createUpdateSession<TypeExtendsLocal extends LocalType>(updateContext?: string, mostRecentValidMutation?: number): IUpdateSession<TypeExtendsLocal> {
        return new UpdateSession(this._core, this._updateSessionDelegate<TypeExtendsLocal>(), updateContext, mostRecentValidMutation);
    }

    /**
     * For use in USS-based ItemLoaders.
     *
     * @param mostRecentValidMutation {number} UpdateSession only allows changes to items that that have a
     *        `lastKnownClientMutation` before this timestamp. Since USS index lag can cause data to be 2-3 seconds
     *        stale, all USS-based ItemLoaders *must* pass `mostRecentValidMutation` of
     *        `Date.now() - core._environment.getValue('USS_LIST_UPDATE_LATENCY')`
     */
    createLoaderUpdateSession<TypeExtendsLocal extends LocalType>(mostRecentValidMutation: number): IUpdateSession<TypeExtendsLocal> {
        return new UpdateSession(this._core, this._updateSessionDelegate<TypeExtendsLocal>(), LOADER_UPDATE_CONTEXT, mostRecentValidMutation);
    }

    /**
     * Creates an UpdateSession for add/update/delete of models in the SAM system that get tracked as
     * `item.lastKnownClientMutation`. Used when the data source is the "source of truth" for this model, in order to
     * prevent stale data from overwriting it. E.g., for AdobeAsset, it should be used when loading a single Asset
     * from R-API.
     *
     * The mostRecentValidMutation timestamp should represent the time for which we know the data was accurate;
     * cached data should use the timestamp when the data was originally fetched.
     */
    createMutationSession<TypeExtendsLocal extends LocalType>(mostRecentValidMutation?: number): IUpdateSession<TypeExtendsLocal> {
        return new UpdateSession(this._core, this._updateSessionDelegate<TypeExtendsLocal>(), undefined, mostRecentValidMutation, 'mutation');
    }

    /**
     * Creates an UpdateSession for ItemLoader implementations, as well as updates `item.lastKnownClientMutation`
     * when models are added/updated/deleted. Used when the data source is the "source of truth" for this model,
     * in order to prevent stale data from overwriting it via `create*UpdateSession()`.
     *
     * The mostRecentValidMutation timestamp should represent the time for which we know the data was accurate;
     * cached data should use the timestamp when the data was originally fetched.
     */
    createLoaderMutationSession<TypeExtendsLocal extends LocalType>(mostRecentValidMutation?: number): IUpdateSession<TypeExtendsLocal> {
        return new UpdateSession(this._core, this._updateSessionDelegate<TypeExtendsLocal>(), LOADER_UPDATE_CONTEXT, mostRecentValidMutation, 'mutation');
    }

    private _updateSessionDelegate = <TypeExtendsLocal extends LocalType>(): IUpdateSessionDelegate<TypeExtendsLocal> => {
        return {
            getLocalItemById: this.getLocalItemById,
            isItemDiscarded: this.isItemDiscarded,
            reindexItem: this.reindexItem,
            findItem: this.findItem<TypeExtendsLocal>,
            commitUpdateSession: (session: IUpdateSession<TypeExtendsLocal>): void => {
                if (!session.hasChanges) {
                    return;
                }

                const objectsById = this._objectsById;
                const discardedObjects = this._discardedObjects;

                // Make a note about discarded objects.
                const { discardedItems } = session;
                if (discardedItems) {
                    for (const item of discardedItems) {
                        discardedObjects.add(item);
                    }
                }

                // Inject the new items in the local map.
                const { addedItems } = session;
                if (addedItems) {
                    for (const item of addedItems) {
                        objectsById.set(item.id, new WeakRef(item));
                        discardedObjects.delete(item);
                    }
                }

                const event = new ItemsChangedEvent<LocalType>(
                    session.addedItems,
                    session.changedItems,
                    session.discardedItems,
                    session.updateContext,
                );

                const delegates = this._delegates;
                if (this._hasUnsortedDelegates) {
                    delegates.sort(compareDelegatesByPriority);
                    this._hasUnsortedDelegates = false;
                }

                let hasEmptyWeakRefs = false;

                for (const delegateRef of delegates) {
                    const delegate = delegateRef.delegate.deref();
                    if (!delegate) {
                        // Remember to filter out the expired weak refs.
                        hasEmptyWeakRefs = true;
                        continue;
                    }

                    //We wanted to add a custom IdType for type safety for combined id's, which is why there's an IdType on the ItemPool
                    //  However, to avoid piping the IdType through the entire ItemPool and UpdateSession, we're cutting off the
                    //  fanout from that change here.  It should be fine because IdType extends string.
                    //@ts-expect-error
                    delegate.onItemsUpdated(event, this);
                }

                if (hasEmptyWeakRefs) {
                    // Make another pass and keep only the delegates that are still alive.
                    this._delegates = delegates.filter((ref) => ref.delegate.deref());
                }

                this.dispatch(event);
            }
        };
    };

    /**
     * Adds a delegate to receive notifications when items change.
     * The delegates cannot be removed, so the connection is alive
     * as long as both the pool and the delegate are still referenced.
     * The client must ensure the delegate is kept alive until the events
     * are not necessary anymore.
     *
     * Performance: Adding too many delegates can obviously hurt performance.
     * Make sure that the callbacks on the delegate are as fast as possible.
     * If the user is not interested in any updates, it is best to make a note
     * that the list is dirty and return as quick as possible. Make sure to delay
     * any of the actual work until the data is requested by the client.
     *
     * Note that we are not adding this on top of the event dispatcher to avoid
     * making the weak ref model a wide spread solution across the repo.
     *
     * @param delegate
     */
    addDelegate(delegate: IItemPoolDelegate<LocalType>, priority: PoolDelegatePriority): void {
        this._delegates.push({ priority, delegate: new WeakRef(delegate) });
        this._hasUnsortedDelegates = true;
    }

    *[Symbol.iterator](): IterableIterator<LocalType> {
        const objectsById = this._objectsById;
        for (const [ key, itemRef ] of objectsById) {
            const item = itemRef.deref();
            if (!item) {
                // Clean up stale references while iterating.
                objectsById.delete(key);
                continue;
            }
            yield item;
        }
    }

    forEach(fn: (item: LocalType) => void): void {
        for (const item of this) {
            fn(item);
        }
    }

    map<T>(fn: (item: LocalType) => T): Array<T> {
        const results: Array<T> = [];
        for (const item of this) {
            results.push(fn(item));
        }
        return results;
    }

    /**
     * Finds the first item in the ItemPool that matches the given predicate.
     */
    findItem = <TypeExtendsLocal extends LocalType>(fn: (item: TypeExtendsLocal) => boolean): TypeExtendsLocal | undefined => {
        for (const item of this) {
            if (fn(item as TypeExtendsLocal)) {
                return item as TypeExtendsLocal;
            }
        }
        return undefined;
    };

    /**
     * Returns all items currently in the ItemPool as an Array
     */
    toArray<TypeExtendsLocal extends LocalType>(): TypeExtendsLocal[] {
        return this.map<TypeExtendsLocal>(item => item as TypeExtendsLocal);
    }

    /**
     * Adds a list to this ItemPool's list tracking, ensuring it's only added once.
     * Fires LIST_ADDED event when a new list is added.
     *
     * @package -- for use in SAM.js only
     */
    addList(list: ItemList<any, IdType>): void {
        // Check if this list is already tracked.
        if (this._lists.some(listRef => listRef.deref() === list)) {
            return;
        }

        this._lists.push(new WeakRef(list));
        this.dispatch(new ListAddedEvent());
    }

    /**
     * Returns all lists currently tracked by this ItemPool.
     * @returns Array of ItemList instances
     *
     * @package -- for use in SAM.js only
     */
    get lists() {

        const lists: ItemList<any, IdType>[] = [];

        // Cleanup dead refs and collect live lists.
        this._lists = this._lists.filter(listRef => {
            const list = listRef.deref();
            if (list) {
                lists.push(list);
                return true;
            }
            return false;
        });

        return lists;
    }

}
