/**
 * Phases of a file upload operation.
 * Note that INITIALIZING and FINALIZING are specific to block uploads.
 */
export enum UploadPhase {
    /**
     * Upload is being initialized (block upload only)
     */
    INITIALIZING = 'initializing',
    /**
     * File blocks are being uploaded
     */
    UPLOADING = 'uploading',
    /**
     * Upload is being finalized (block upload only, cannot be cancelled)
     */
    FINALIZING = 'finalizing',
    /**
     * Upload is complete
     */
    COMPLETE = 'complete'
}

/**
 * Information about the current upload phase
 */
export interface UploadPhaseInfo {
    /**
     * Current phase of the upload
     */
    phase: UploadPhase;
    /**
     * Whether the upload can be cancelled in this phase
     */
    canCancel: boolean;
}

/**
 * Options for uploading an asset
 */
export interface ImportFileOptions {
    /**
     * The file blob to import
     */
    file: Blob | string;
    /**
     * The name of the file to be uploaded
     */
    name: string;
    /**
     * The media type of the file to be uploaded
     */
    mediaType?: string;
    /**
     * @deprecated Use renameOnConflict instead.
     */
    retryOnConflict?: boolean;
    /**
     * If true, a new name will be generated for the file (by ACP) if the name already exists, otherwise it will throw an error.
     */
    renameOnConflict?: boolean;
    /**
     * If true, sets the createdFromUpload property to true
     */
    setCreatedFrom?: boolean;
    /**
     * @deprecated This property is ignored and will be removed in a future version.
     */
    counter?: number;
    /**
     * Specifies the preferred block transfer threshold
     */
    preferredBlockTransferThreshold?: number;
    /**
     * If true, specifies that the file should be uploaded using the "block store" variant of block uploads (more efficient for large files)
     */
    useBlockStore?: boolean;

    /**
     * If this option is provided, the asset will be created and immediatley set as a milestone.
     */
    milestoneProperties?: MilestoneProperties;
    /**
     * Optional AbortSignal to cancel the upload.
     */
    signal?: AbortSignal;
    /**
     * Optional callback to track upload phase changes. Called when the upload enters a new phase.
     * Use this to update UI elements like the cancel button (which should be disabled during finalization).
     */
    onPhaseChange?: (phaseInfo: UploadPhaseInfo) => void;
}

/**
 * Options for getting a download URL for an asset
 */
export interface GetDownloadURLOptions {
    /**
     * If true, forces block download even for small files
     */
    forceBlockDownload?: boolean;
    /**
     * Size threshold for block transfer. Defaults to DEFAULT_MAX_SINGLE_TRANSFER_SIZE.
     */
    preferredBlockTransferThreshold?: number;
    /**
     * Time-to-live for the presigned URL in seconds. If not provided, uses service default (4 hours as of this writing).
     */
    presignedUrlExpirationSeconds?: number;
    /**
     * If specified, indicates that when the RelType.DOWNLOAD link is not present, the file should be downloaded
     * using the direct download method, as long as it is under the specified threshold.
     *
     * The client is responsible for ensuring that the specified threshold is reasonable for direct downloads
     * from both a platform perspective and a browser in-memory storage limit. Note, that this option is currently incompatible
     * with cloud to desktop conversion because download conversion is only supported by block downloads.
     */
    fallbackToDirectDownloadThreshold?: number;
}

