    /**
     * Update lastAccessed Per User Per Asset (PUPA) metadata
     * @param {boolean} clear (optional) Pass `true` to clear the lastAccessedDate on folders
     * @returns {Promise<void>}
     */
    async updateLastAccessed(clear?: boolean): Promise<void> {
        if (clear && !this.isFolder) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Can only clear lastAccessed for folders');
        }

        const accessDate = new Date();
        // we use the link to clear the last access date
        // and the PLS API to update the last access date as PLS does not support clearing the last access date
        // https://jira.corp.adobe.com/browse/SYSE-19734
        if (clear) {
            await this._ensureLink(RelType.PERUSER_METADATA);
            const assetInterface = await this._getAssetInterface();
            await assetInterface.removeLastAccessed();
        } else {
            // Update last access date using the PLS API
            const gqlManager = await this._core._getGQLManager();
            await gqlManager.updateLastAccessed(this.id, accessDate.toISOString());
        }

        const assetContext = this._getAssetContext();
        const assetPool = this._core._getAssetPool();
        const session = assetPool.createUpdateSession();
        assetContext._adobeAssetUpdater.updateLocalItem(
            session,
            this,
            {
                perUserMetadata: {
                    'shell:lastAccessDate': clear ? null : accessDate.toISOString(),
                }
            }
        );
        session.commit();
    }

