    @memoize
    get children(): AdobeAssetSource | undefined {
        if (!this.isFolder) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Children list can be fetched only for folder');
        }
        // https://jira.corp.adobe.com/browse/SAM-3206
        // We will embed permissions for projects and children of projects
        const loader = new AdobeAssetDirectoryLoader(this._core._getAssetPool(), this, this._core, this.isChildOfProject);
        // Children of Project folders can be SWY items
        const implicitFilter = new ImplicitDirectoryListingFilter({ asset: this, _isSharedWithYou: this.isChildOfProject });
        const assetPool = this._core._getAssetPool();
        const localAssetLoader = new LocalAssetLoader<AdobeAssetConfig>(assetPool, this._core);
        return new ItemSource(assetPool, [ loader, localAssetLoader ], implicitFilter);
    }

    searchChildren(opts: { deepSearch?: boolean, query?: string}): AdobeAssetSearchSource {
        if (!this.isFolder) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Children can be searched only in the folder');
        }

        const { deepSearch, query } = opts;
        const implicitFilter = new AdobeAssetSearchFilter({ asset: this, deepSearch, query });
        const assetContext = this._getAssetContext();
        const loader = new AdobeAssetDirectorySearchLoader(
            this._core._getAssetPool(),
            this._core,
            assetContext._adobeAssetSearchInterface,
            this,
            implicitFilter
        );
        return new ItemSource(this._core._getAssetPool(), [ loader ], implicitFilter);
    }

    handleONSChangedResources(changedResources: ONSChangedAssetInfo['changedResources']) {
        // NOTE: if overriding this method in subclasses, please make a utility for parsing the
        // ONSChangedResources to encapsulate in case it changes/reduce errors in implementation.
        if (changedResources?.includes('api:metadata/repository')) {
            this._repoMetadataResource.isDirty = true;
            // TODO: bypass loading app metadata if changedResources includes api:metadata/application
            // TODO: bypass permission refresh if changedResources includes api:ac/policy
            // https://jira.corp.adobe.com/browse/SAM-3499
            this._loadWithRetry();
        }

        if (changedResources?.includes('api:metadata/application')) {
            this._appMetadata.isDirty = true;
            this.appMetadata.load();
        }

        if (changedResources?.includes('api:ac/policy')) {
            // Load the permissions and set collaborator data dirty flags.
            this._effectivePermissionsResource.isDirty = true;
            this._reloadPermissions();

            // Queue collaborators to be refreshed on the asset since policy changes
            // may affect the collaborators as well.
            this._queueCollaborators();
        }
    }

    // Handle changes in the PLS data of the asset
    async handleONSChangesForPLS(): Promise<void> {
        const gqlManager = await this._core._getGQLManager();
        const updateData: {
            perUserMetadata?: Partial<IPerUserMetadata>;
            sharedWithYouLabel?: SharedWithYouLabel;
            isFavorite?: boolean;
        } = {};

        try {
            const result = await gqlManager.getPLSData(this.id);
            if (result.lastAccessDate !== undefined) {
                updateData.perUserMetadata = {
                    ...updateData.perUserMetadata,
                    'shell:lastAccessDate': result.lastAccessDate
                };
            }
            if (result.isFavorite !== undefined) {
                updateData.isFavorite = result.isFavorite;
            }
            if (result.sharedWithYouLabel !== undefined) {
                updateData.sharedWithYouLabel = result.sharedWithYouLabel;
            }
        } catch (error) {
            this._core._environment.error(`Failed to fetch PLS data: ${error}`);
        }

        if (Object.keys(updateData).length > 0) {
            const session = this._core._getAssetPool().createUpdateSession();
            this._getAssetContext()._adobeAssetUpdater.updateLocalItem(session, this, updateData);
            session.commit();
        }
    }

    /**
     * Discard the asset - this changes its repo:state to DISCARDED, but it's still present as an
     * asset, and can later be restored, or permanently deleted.
     */
    async discard(): Promise<void> {
        if (this.isDiscarded) {
            throw SAMError.create(SAMErrorCode.INVALID_OPERATION, 'Asset is already discarded');
        }
        const assetInterface = await this._getAssetInterface();
        const repoMetadata = await assetInterface.discard();
        const assetContext = this._getAssetContext();

        // Artifacts are from Share For Review, for assets where you can create a Review artifact via the Share For Review workflow
        if (this._hasArtifacts) {
            // NOTE: this is done in the background and if it fails will not count as a failure
            // for discard. This also means when `discard()` resolves, the output folder may not
            // be deleted yet.
            assetContext._deleteAssetOutputsFolder(this);
        }

        if (repoMetadata) {
            const assetPool = this._core._getAssetPool();
            // Use response metadata to reflect the new state of the Asset
            const session = assetPool.createUpdateSession();
            assetContext._adobeAssetUpdater.updateLocalItem(session, this, repoMetadata);

            if (this.isFolder) {
                // If it's a directory, we also need to update the repo:state of all its children.
                updateCachedDescendents({
                    assetPool,
                    asset: this,
                    session,
                    operation: { type: 'discard' },
                    assetContext
                });
            }

            session.commit();
        }
    }

