    _clearRepositoryName() {
        this._repositoryName = undefined;
    }

    private async _populateRepositoryName(): Promise<void> {
        if (this._repositoryName) {
            return;
        }
        const assetContext = this._getAssetContext();
        const assetPool = this._core._getAssetPool();
        const repositoryName = await assetContext._repositoryNameFromID(this._repositoryID);
        if (repositoryName) {
            const session = assetPool.createUpdateSession();
            assetContext._adobeAssetUpdater.updateLocalItem(session, this, { repositoryName });
            session.commit();
        }
    }

