    @observable
    /**
     * Detect if the user has a specific permission or permissions
     * @param permissions
     * @usage
     *    // single permission check
     *    asset.hasPermission(Permission.Delete);
     *    // multiple
     *    asset.hasPermission(Permission.Write, Permission.Read);
     *    // multiple via bitwise OR
     *    asset.hasPermission(Permission.Write | Permission.Read);
     *    // multiple via spread operator
     *    asset.hasPermission(...permsToCheck);
     */
    hasPermission(...permissions: Permission[]): boolean {
        return permissions.every((permission) =>
            (this._permissions & permission) === permission);
    }

    /**
     * Returns an object of permissions and role for the current user in a similar format to
     * the Invitation Service GET /capabilities API.
     *
     * **Note**: This is a simplified version derived from the effective ACL of the user, returning only
     * the core fields (canComment, canShare, role). For the complete capabilities information including
     * organization details, parent permissions, special principals, and more, use the {@link ShareableItem#getCapabilities} method.
     *
     * @returns {InvitationServiceCapabilities} A subset of capabilities with canComment, canShare, and role
     * @see {@link ShareableItem#getCapabilities} for the full type definition from the Swagger spec
     */
    @observable
    get invitationServiceCapabilities(): InvitationServiceCapabilities {
        let role: Role = 'none';

        if (this.hasPermission(Permission.Read)) {
            if (this.hasPermission(Permission.Write)) {
                role = this.hasPermission(Permission.Ack) ? 'owner' : 'editor';
            } else {
                role = 'viewer';
            }
        }

        return {
            canComment: this.hasPermission(Permission.WriteComment),
            canShare: this.hasPermission(Permission.Share),
            role
        };
    }

    isReadOnly(): boolean {
        return this.hasPermission(Permission.Read) && !this.hasPermission(Permission.Write);
    }

