    @observable
    public renditionURLStatus(size: number, type: string): RenditionStatus {
        // Do not try to fetch rendition for folders, or LEs that have no rendition link
        if (this.isFolder || (this.isLibraryElement && !this.links[RelType.RENDITION])) {
            return RenditionStatus.Done;
        }
        return this._renditionFetcher.renditionURLStatus(size, type, this.preferredVersion);
    }

