function getUSSAssetType(source: Partial<USSMetadata>) {
    // uss type is 'application/x-sharedcloud-collection+json' for directory
    // changing it to standard mime directory type to abstract it for SAM clients
    if (source.type === FOLDER_ALTERNATE_TYPE) {
        return FOLDER_TYPE;
    }
    return source.type;
}

function getUSSAssetClass(source: Partial<USSMetadata>) {
    // for directories, asset_sub_type is not present in USS response
    if (source.type === FOLDER_ALTERNATE_TYPE || source.type === FOLDER_TYPE) {
        return 'directory';
    }
    // for files, asset_sub_type is not present in USS response
    // so we assign anything else that is not dcx or directory as file
    if (source.creative_cloud_asset_type !== 'dcx') {
        return 'file';
    }
    return source.asset_sub_type;
}

function getUSSLastAccessed(source: Partial<USSMetadata>) {
    const lastAccessedISOString = source['api:metadata/peruser']?.[0]?.['shell:lastAccessDate'];
    // If the property is not present, the current value should be left alone
    if (lastAccessedISOString === undefined) {return NotFound;}
    // If the property is present, but empty, clear the current value
    if (lastAccessedISOString === '') {return undefined;}
    return lastAccessedISOString;
}

function getUSSStorageRegion(source: Partial<USSMetadata>): string {
    // USS stores 'region' as 'US', 'AP', 'EU' for some Assets, and 'va6c2', 'va7' for other Assets. According to USS
    // team, the US/AP/EU strings can be mapped to VA6/JPN3/IRL1, and the others match the R-API storage:region.
    switch (source.region?.toLowerCase()) {
    case 'us':
        return 'VA6';
    case 'ap':
        return 'JPN3';
    case 'eu':
        return 'IRL1';
    default:
        return source.region?.toUpperCase() || '';
    }
}

// USS result item does not contain asset name in path, to keep it sync with repo path
// received from RAPI, we will add asset name in asset path while creating/updating asset
// from USS result
function getAssetPath(source: Partial<USSMetadata>): string {
    if (source.asset_name_path && source.asset_name) {
        return path.join(source.asset_name_path, source.asset_name);
    }
    return source.asset_name_path || source.asset_name || '';
}

function getEtag(source: Partial<USSMetadata>): string {
    return source.composite_manifest_etag || source.etag?.primary || '';
}

