import type Board from './Board';
import type { IExplicitFilter, ItemFilterRelation } from '../core/ItemFilter';
import type AdobeAsset from '../assets/AdobeAsset';
import type { SAM } from '@ccx-public/component-types';

export interface BoardFilterOptions {
    baseAssetId: string;
    shouldGetDirectlyInBaseAsset?: boolean;
}

export default class BoardFilter implements IExplicitFilter<Board>, SAM.BoardFilter {
    public baseAssetId: string;
    public shouldGetDirectlyInBaseAsset?: boolean;
    /**
     * @package only for use in SAM.js
     */
    public _monitoredFolder?: AdobeAsset;

    constructor(options: Partial<BoardFilterOptions> = {}) {
        this.baseAssetId = options.baseAssetId || '';
        this.shouldGetDirectlyInBaseAsset = options.shouldGetDirectlyInBaseAsset || false;
    }

    matches(item: Board): boolean {
        if (!item.isBoard) {
            return false;
        }
        // Filter by baseAssetId and discard discarded boards
        if (item.baseAssetId !== this.baseAssetId) {
            return false;
        }
        if (item.isDiscarded) {
            return false;
        }
        return true;
    }

    getRelationToFilter(other: BoardFilter): ItemFilterRelation {
        if (this.baseAssetId !== other.baseAssetId) {
            return 'disjoint';
        } else {
            return 'subset';
        }
    }

    get hash(): string {
        return `baseAssetId=${this.baseAssetId}&shouldGetDirectlyInBaseAsset=${this.shouldGetDirectlyInBaseAsset}`;
    }
}
