import type { Action } from '../models/Action';
import { isPlaceholder } from '../models/utils';
import { getPlaceholderId, replaceId } from './PathUtils';

export function deepCopy<T>(object: T): T {
    // eslint-disable-next-line no-undef
    if (typeof structuredClone !== 'undefined') { return structuredClone(object); }
    return JSON.parse(JSON.stringify(object));
}

function replaceActionPlaceHolders(
    targetAction: Action,
    idCache: { [s: string]: Action['data'] },
    placeholderReplacers: Array<(action: Action, idCache: { [s: string]: Action['data'] }) => Action>
) {
    const newAction = placeholderReplacers.reduce((action, replacer) => replacer(action, idCache), targetAction);
    if (newAction !== targetAction) {
        newAction.originalAction = targetAction;
    }

    if (newAction.type === 'aggregate') {
        newAction.actions = newAction.actions?.map(action =>
            replaceActionPlaceHolders(action, idCache, placeholderReplacers)
        );
    }

    return newAction;
}

export function replacePlaceholders(sourceActions: Action[], targetActions?: Action[]): Action[] {
    if (!targetActions) {
        targetActions = sourceActions;
    }

    // If an ID has changed between the original action and the response (placeholder substitution),
    // we need to replace that id in all pending actions. Otherwise the actions will be pointing at
    // an element that doesn't exist.
    const idCache: { [s: string]: Action['data'] } = {};
    for (const sourceAction of sourceActions) {
        if (isPlaceholder(sourceAction.originalAction?.data?.id)) {
            idCache[sourceAction.originalAction?.data.id] = sourceAction.data;
        }
    }

    // Replace placeholder ids on queued actions
    const placeholderReplacers: Array<(action: Action, idCache: { [s: string]: Action['data'] }) => Action> = [
        pathPlaceholderReplacer,
        groupDataPlaceholderReplacer,
        representationDataPlaceholderReplacer
    ];
    return targetActions.map(action => replaceActionPlaceHolders(action, idCache, placeholderReplacers));
}

function pathPlaceholderReplacer(action: Action, idCache: { [s: string]: Action['data'] }) {
    const placeholderId = action.path && getPlaceholderId(action.path);

    if (placeholderId) {
        const actualId = idCache[placeholderId]?.id;

        if (actualId) {
            return {
                ...action,
                path: replaceId(action.path as string, placeholderId, actualId)
            };
        }
    }

    return action;
}

function groupDataPlaceholderReplacer(action: Action, idCache: { [s: string]: Action['data'] }) {
    let hasReplacedGroups = false;
    const newGroups: { id: string }[] = [];
    action.data?.groups?.forEach((group: { id: string }) => {
        if (group.id && isPlaceholder(group.id)) {
            const actualId = idCache[group.id]?.id;
            if (actualId) {
                hasReplacedGroups = true;
                newGroups.push({ ...group, id: actualId });
                return;
            }
        }
        newGroups.push(group);
    });

    if (hasReplacedGroups) {
        return {
            ...action,
            data: {
                ...action.data,
                groups: newGroups
            }
        };
    }

    // Replacing potential placeholder Ids with actual Ids.
    if (action.data?.id && isPlaceholder(action.data?.id)) {
        const actualId = idCache[action.data?.id]?.id;
        if (actualId) {
            action.data.id = actualId;
        }
    }

    if (action.data?.parentId && isPlaceholder(action.data?.parentId)) {
        const actualId = idCache[action.data?.parentId]?.id;
        if (actualId) {
            action.data.parentId = actualId;
        }
    }
    return action;
}

function representationDataPlaceholderReplacer(action: Action, idCache: { [s: string]: Action['data'] }) {
    const newRepresentations: { id: string; source?: { id: string } }[] = [];
    let replacedRepresentations = false;

    const replaceRepresentation = (representation: { id: string }) => {
        let newRepresentation = { ...representation };
        if (representation.id && isPlaceholder(representation.id)) {
            const actualData = idCache[representation.id];
            // We need to inject the entire representation data, the id alone is not sufficient.
            if (actualData) {
                newRepresentation = actualData;
                replacedRepresentations = true;
            }
        }
        return newRepresentation;
    };

    action.data?.representations?.forEach((representation: { id: string; source?: { id: string } }) => {
        if (representation.source) {
            representation.source = replaceRepresentation(representation.source);
        }
        newRepresentations.push(replaceRepresentation(representation));
    });

    if (replacedRepresentations) {
        // Don't inject new fields into the action payload that weren't there before.
        return {
            ...action,
            data: {
                ...action.data,
                representations: newRepresentations
            }
        };
    }
    return action;
}

export function markSubstitutedPlaceholders(actions: Action[]) {
    for (const action of actions) {
        if (action.data && isPlaceholder(action.originalAction?.data?.id)) {
            action.data.previousPlaceholderId = action.originalAction?.data.id;
        }
    }
}
