import path from 'path-browserify';
import type AssetLinkList from './AssetLinkList';
import type AdobeAsset from '../assets/AdobeAsset';
import SAMError, { SAMErrorCode } from '../core/SAMError';
import { observable, retry, synchronized } from '../core/decorators';
import { Permission } from '../interface/AssetModel';
import { SAMObjectEventEmitter } from '../core/SAMObjectEventEmitter';

export type LinkReference = {
    ['repo:assetId']: string,
    ['repo:repositoryId']?: string,
    ['repo:name']?: string,
    ['repo:etag']?: string,
    ['repo:version']?: string,
    ['dc:format']?: string,
    ['stRef:relativePath']?: string,
    ['stRef:fromPart']?: string,
    ['stRef:documentID']?: string,
    ['stRef:instanceID']?: string,
    ['stRef:fromPartInstanceID']?: string,
    ['stRef:fromPartName']?: string,
    ['stRef:fromPartDerivedFrom']?: LinkReference,
    ['stRef:manager']?: 'Adobe Cloud'
};

// Properties of a link reference that correspond to mutable asset metadata properties (e.g. name, path etc).
// These are properties that can change on the asset, but don't correspond to a content change
// (i.e. the link state would be MetadataOutOfDate rather than OutOfDate)
const assetMetadataProperties: (keyof LinkReference)[] = [
    'repo:repositoryId',
    'repo:name',
    'repo:etag',
    'stRef:relativePath',
    'stRef:documentID'
];

export type LinkStatus =
    | 'UpToDate'
    | 'MetadataOutOfDate'
    | 'OutOfDate'
    | 'Restricted'
    | 'Discarded'
    | 'Broken';

function isBrokenAsset(asset: AdobeAsset) {
    // Need to know if permission exactly matches Ack or None, rather than contains, so can't use
    // hasPermission() here.
    const permission = asset['_permissions'];
    return permission === Permission.Ack
        || permission === Permission.None;
}

// Illustrator (prior to MAX 2021) does not update the instance ID on save, so we need to fall back to the etag in this case
// See https://jira.corp.adobe.com/browse/AI-4251857
const typesWithUnreliableInstanceID = [
    'application/illustrator'
];

export default class AssetLink extends SAMObjectEventEmitter {

    private _resolvedAssets?: AdobeAsset[];
    private _resolutionErrors: SAMError[] = [];

    constructor(
        private _assetLinkList: AssetLinkList,
        private _data: LinkReference
    ) {
        super(_assetLinkList._core);
    }

    _onChange = () => {
        // Check if any of the resolved assets broke, and transfer their errors to the link
        // so we get the right link state (broken or restricted)
        const brokenAssets = this._resolvedAssets?.filter(isBrokenAsset);
        if (brokenAssets?.length) {
            this._resolutionErrors = brokenAssets.map(asset =>
                SAMError.create(
                    asset['_permissions'] === Permission.Ack ? SAMErrorCode.ACCESS_DENIED : SAMErrorCode.NOT_FOUND,
                    'lost access'
                ));
            this._resolvedAssets = this._resolvedAssets?.filter(asset => !brokenAssets.includes(asset));
        }
        this.emit('change');
        this._assetLinkList._onChange();
    };

    @synchronized
    async _setLinkData(linkData: LinkReference, asset?: AdobeAsset) {
        this._data = linkData;
        if (asset) {
            this._resolvedAssets = [ asset ];
        }
        this._onChange();
        if (!this.adobeAsset || this.assetID !== this.adobeAsset.cloudID) {
            await this._resolveWithRetry();
        }
        // TODO: Check if relative path changed
        return this;
    }

    async _setLinkedAsset(asset: AdobeAsset) {
        const data = this._getLinkDataForAsset(asset);
        return this._setLinkData(data, asset);
    }

    _getLinkDataForAsset(asset: AdobeAsset): LinkReference {
        const linkData: LinkReference = {
            'repo:assetId': asset.cloudID,
            'repo:repositoryId': asset.repositoryID,
            'repo:etag': asset.etag,
            'dc:format': asset.mediaType,
            'repo:name': asset.name,
            'stRef:documentID': asset.embeddedMetadata.data?.['xmpMM:DocumentID'],
            'stRef:instanceID': asset.embeddedMetadata.data?.['xmpMM:InstanceID'],
            'stRef:manager': 'Adobe Cloud'
        };

        // Add relative path if it exists
        const parent = this._assetLinkList.containerAsset;
        if (parent && parent.repositoryID === asset.repositoryID) {
            linkData['stRef:relativePath'] = path.relative(path.dirname(parent.repoPath), asset.repoPath);
        }

        return linkData;
    }

    // Ensures that link reference strings are always serialized with the keys in the same order
    _serializeLinkData(linkData: LinkReference): string {
        return JSON.stringify(linkData, Object.keys(linkData).sort());
    }

    @retry
    _resolveWithRetry(): Promise<void> {
        return this._resolve();
    }

    async _resolve(): Promise<void> {
        const resolvedAssets: AdobeAsset[] = [];
        const resolutionErrors: SAMError[] = [];

        const handleError = (e: SAMError) => {
            if ([ SAMErrorCode.NOT_FOUND, SAMErrorCode.ACCESS_DENIED ].includes(e.code)) {
                resolutionErrors.push(e);
            } else {
                throw e;
            }
        };

        try {
            const asset = await this._context.getAssetWithCloudID(this.assetID);
            if (!asset.embeddedMetadata.isLoaded) {
                // First time, we need to load - after that, it'll get updated whenever the asset is refreshed
                await asset.embeddedMetadata.load();
            }
            resolvedAssets.push(asset);
        } catch (e) {
            this._core._environment.error(`Failed to resolve link by id (${this.assetID}): ${e}`);
            handleError(e as SAMError);
        }

        const parent = this._assetLinkList.containerAsset;
        if (this.relativePath && parent && parent.repositoryID === this.repositoryID) {
            // Resolve by relative path, but this only makes sense if the container asset and linked
            // asset are in the same repository.
            const repoPath = path.join(path.dirname(parent.repoPath), this.relativePath);
            try {
                const asset = await this._context.getAssetWithRepoPath(repoPath, this.repositoryID);
                if (!asset.embeddedMetadata.isLoaded) {
                    // First time, we need to load - after that, it'll get updated whenever the asset is refreshed
                    await asset.embeddedMetadata.load();
                }
                // Most of the time, resolution by path will match resolution by asset id - only add an alternate
                // if they're different.
                if (!resolvedAssets[0] || resolvedAssets[0].cloudID !== asset.cloudID) {
                    if (resolvedAssets[0]?.isDiscarded) {
                        // Special case if the resolution by id is discarded - we want the path-based resolution
                        // to become the primary adobeAsset
                        resolvedAssets.unshift(asset);
                    } else {
                        resolvedAssets.push(asset);
                    }
                }
            } catch (e) {
                this._core._environment.error(`Failed to resolve link by path: ${this.repositoryID}, ${repoPath}`);
                handleError(e as SAMError);
            }
        }

        // Attach event listeners so we can notify the link when the asset changes
        this._resolvedAssets && this._resolvedAssets.forEach(asset => asset.off('change', this._onChange));
        resolvedAssets.forEach(asset => asset.on('change', this._onChange));

        this._resolvedAssets = resolvedAssets;
        this._resolutionErrors = resolutionErrors;
        this._onChange();
    }

    get _context() {
        return this._assetLinkList._manager._context;
    }

    /**
     * The asset that the link resolves to - this will not be defined if the linkStatus
     * is Restricted or Broken.
     */
    @observable
    get adobeAsset(): AdobeAsset | undefined {
        return this._resolvedAssets?.[0];
    }

    /**
     * An alternative asset which can be used as link, in case there is ambiguity resolving the link.
     * This will usually be undefined.
     */
    @observable
    get alternativeAdobeAsset(): AdobeAsset | undefined {
        return this._resolvedAssets?.[1];
    }

    /**
     * The current state of the link (OutOfDate, UpToDate, Restricted or Broken).
     */
    @observable
    get linkStatus(): LinkStatus {
        if (!this._resolvedAssets) {
            return 'UpToDate';
        }
        if (!this.adobeAsset) {
            // If we get a 403 resolving an asset, we know it exists but the user doesn't have access
            // This corresponds to the Restricted state - we can direct the user to request access via assets web.
            return this._resolutionErrors.some(error => error.code === SAMErrorCode.ACCESS_DENIED) ? 'Restricted' : 'Broken';
        }
        if (this.adobeAsset.isDiscarded) {
            // If the primary asset resolved is discarded, it means that we don't have an undiscarded alternative
            // (otherwise it would be the primary asset). We therefore treat the link state as Discarded.
            // This means that the user can be presented the option to restore the asset to fix the link.
            return 'Discarded';
        }

        // Check to see if the asset has changed - we check the xmpMM:InstanceID, which should be modified on every save.
        // There are two exceptions:
        // 1) If the asset doesn't have any XMP metadata (and neither does the link), we fall back to compare the repo:etag
        // 2) Illustrator has a bug that it doesn't update the XMP metadata on save - so we also fall back to the repo:etag
        //    for Illustrator types, in case they were edited in an older version of Illustrator.
        const instanceID = this.adobeAsset.embeddedMetadata.data['xmpMM:InstanceID'] || '';
        const shouldCheckEtag = (!instanceID && !this.instanceID) || typesWithUnreliableInstanceID.includes(this.type);
        const assetHasChanged = instanceID !== this.instanceID || (shouldCheckEtag && this.etag !== this.adobeAsset.etag);
        if (this.alternativeAdobeAsset || assetHasChanged) {
            return 'OutOfDate';
        }

        // Check whether any metadata is out of date
        const assetLinkData = this._getLinkDataForAsset(this.adobeAsset);
        const hasMetadataChanges = assetMetadataProperties.some(key => assetLinkData[key] !== this._data[key]);
        return hasMetadataChanges ? 'MetadataOutOfDate' : 'UpToDate';
    }

    /**
     * The fragment specifier which can be used by the client to link to a fragment within the asset.
     */
    @observable
    get fragmentIdentifier(): string {
        return this._data['stRef:fromPart'] || '';
    }

    /**
     * The version of the asset to which the link is referring to. This is only used if linking to a specific
     * version, and the version must be specified at the time of link creation.
     */
    @observable
    get version(): string {
        return this._data['repo:version'] || '';
    }

    /**
     * The asset ID of the asset which the link refers to.
     */
    @observable
    get assetID(): string {
        return this._data['repo:assetId'];
    }

    /**
     * The repository ID of the asset which the link refers to.
     */
    @observable
    get repositoryID(): string {
        return this._data['repo:repositoryId'] || '';
    }

    /**
     * The owner ID of the asset which the link refers to.
     */
    // get ownerID(): string {
    //     return this._data['stRef:fromPart'] || '';
    // }

    /**
     * The name of the asset when the link was created or last updated.
     */
    @observable
    get name(): string {
        return this._data['repo:name'] || '';
    }

    /**
     * The type of the asset when the link was created.
     */
    @observable
    get type(): string {
        return this._data['dc:format'] || '';
    }

    /**
     * The etag of the asset when the link was created or last updated.
     */
    @observable
    get etag(): string {
        return this._data['repo:etag'] || '';
    }

    /**
     * The relative path of the asset when the link was created or last updated.
     */
    @observable
    get relativePath(): string {
        return this._data['stRef:relativePath'] || '';
    }

    /**
     * The document id as per the XMP metadata when the link was created or last updated.
     */
    @observable
    get documentID(): string {
        return this._data['stRef:documentID'] || '';
    }

    /**
     * The instance id as per the XMP metadata when the link was created or last updated.
     */
    @observable
    get instanceID(): string {
        return this._data['stRef:instanceID'] || '';
    }

    /**
     * Obtain the asset link reference to be stored in the container document for the link.
     * Note: Clients can choose to store this as a string by calling getAssetLinkRefString() instead.
     */
    @observable
    getAssetLinkRef(): LinkReference {
        return Object.assign({}, this._data);
    }

    /**
     * Obtain the asset link reference string to be stored in the container document for the link.
     * Note: Clients can choose to store this as an object by calling getAssetLinkRef() instead.
     */
    @observable
    getAssetLinkRefString(): string {
        return this._serializeLinkData(this._data);
    }

    /**
     * Obtain the asset link reference corresponding to the given asset. This is useful for knowing
     * the new link reference that would be obtained by updating to the given asset
     */
    @observable
    getNewAssetLinkRef(asset: AdobeAsset): LinkReference {
        return this._getLinkDataForAsset(asset);
    }

    /**
     * Obtain the asset link reference string corresponding to the given asset. This is useful for knowing
     * the new linkReference string that would be obtained by updating to the given asset
     */
    @observable
    getNewAssetLinkRefString(asset: AdobeAsset): string {
        return this._serializeLinkData(this.getNewAssetLinkRef(asset));
    }

    /**
     * Called by the clients to accept the latest changes and get the new asset link reference
     * @param asset The new asset to update to (or the current asset to accept an update)
     * @returns The new linkReference string.
     */
    async updateWithAsset(asset: AdobeAsset): Promise<string> {
        await this._setLinkedAsset(asset);
        return this.getAssetLinkRefString();
    }

    /**
     * Called by the clients to accept the latest changes and get the new asset link reference
     * @param linkRef A new link reference to update to
     * @returns The new link reference.
     */
    async updateWithLinkRef(linkRef: LinkReference): Promise<LinkReference> {
        await this._setLinkData(linkRef);
        return linkRef;
    }

    /**
     * Called by the clients to accept the latest changes and get the new asset link reference
     * @param linkRef A new link reference string to update to
     * @returns The new link reference string.
     */
    async updateWithLinkRefString(linkRefString: string): Promise<string> {
        await this._setLinkData(JSON.parse(linkRefString));
        return linkRefString;
    }

    /**
     * Called by the clients to accept metadata updates when the link is in the OutOfDate state.
     * If called when the link is in a different state, this does nothing.
     * @returns The new linkReference string.
     */
    acceptMetadataChanges(): string {
        if (this.adobeAsset && this.linkStatus === 'MetadataOutOfDate') {
            const assetLinkData = this._getLinkDataForAsset(this.adobeAsset);
            // Note that we substitute fields rather than replacing the whole link reference, because the link reference
            // may include fragment data that we don't want to delete
            this._data = { ...this._data, ...assetLinkData };
            this._onChange();
        }
        return this.getAssetLinkRefString();
    }
}
