import { v4 as uuid } from 'uuid';

type Atom = {
    reportChanged: () => void;
    reportObserved: () => void;
};

export type CreateAtom = (name: string, onBecomeObserved: () => void, onBecomeUnobserved: () => void) => Atom;
export type Transaction = (fn: () => unknown) => void;

class MobXRegistry {
    _contexts = new Map<string, { createAtom: CreateAtom; transaction: Transaction }>();

    register(createAtom: CreateAtom, transaction: Transaction) {
        const id = uuid();
        this._contexts.set(id, { createAtom, transaction });
        return () => this._contexts.delete(id);
    }

    transaction(fn: () => unknown) {
        const nestedTransaction = Array.from(this._contexts.values()).reduce((memo, { transaction }) => {
            return () => transaction(() => memo());
        }, fn);

        return nestedTransaction();
    }

    reportObserved(target: any, event: string) {
        for (const [ id, { createAtom } ] of this._contexts) {
            const key = `_atom_${id}_${event}`;
            let atom = target[key];
            if (!atom) {
                const onChange = () => atom.reportChanged();
                atom = createAtom(
                    `${target.constructor.name}${key}`,
                    () => target.on(event, onChange),
                    () => target.off(event, onChange)
                );
                target[key] = atom;
            }
            atom.reportObserved();
        }
    }
}

export default new MobXRegistry();
