import UriTemplate from 'uri-templates';
import LinkHeader from 'http-link-header';
import SAMError, { SAMErrorCode } from '../core/SAMError';
import type { ISAMCorePrivate, ISAMObject } from '../indexPrivate';
import type { HeaderMap } from './LinkUtils';
import { RelType, getRetryAfterHeader } from './LinkUtils';
import { parseAsyncResponse } from './AsyncResponse';
import type { IFetchOptions } from '../core/Environment';
import clamp from '../utils/clamp';
import type Resource from '../assets/Resource';
import { PassthroughResource } from '../assets/Resource';
import type { ValidHttpResponseCodes } from './ResponseCodes';
import { RETRY_HTTP_RESPONSE_CODES, VALID_HTTP_RESPONSE_CODES } from './ResponseCodes';
import CacheableResponse from './CacheableResponse';
import samJsUuid from '../core/uuid';

// Make 1 request, then MAX_ERROR_RETRIES retries
const MAX_ERROR_RETRIES = 5;

type PaginatedResponse = { result: any, next?: () => Promise<PaginatedResponse> };

export type InterfaceBaseFetchOptions<ParsedResponse> = IFetchOptions & {
    additionalRetryErrorCodes?: number[];
    successResponseCodes?: ValidHttpResponseCodes;
    headers?: HeaderMap;
    resource?: Resource<ParsedResponse>;
    handleError?: (response: Response) => Promise<void>;
    signal?: AbortSignal;
};

/**
 * InterfaceBase and its subclasses are abstractions around calling into a service (not to be confused with typescript
 * interfaces). It extends fetch to provide retry and error handling logic.
 */
export default class InterfaceBase implements ISAMObject {
    protected _useHighPriorityRequestsIfEnabled: boolean = false;

    constructor(
        readonly _core: ISAMCorePrivate
    ) {}

    protected async _fetch<ParsedResponse>(
        href: string,
        options: InterfaceBaseFetchOptions<ParsedResponse> = {
            successResponseCodes: VALID_HTTP_RESPONSE_CODES
        }
    ): Promise<Response> {
        // Ensure we remove any non-fetch-related options before passing to fetch,
        // as the nock library will hold references to these (and cause GC tests to fail).
        const {
            resource = new PassthroughResource(this._core) as unknown as Resource<ParsedResponse>,
            ...fetchOptions
        } = options;

        const performFetch = () => this._fetchImpl(href, fetchOptions, 0).then(CacheableResponse.fromResponse);
        return await resource._interceptFetch(options.method ?? 'GET', href, options.body, performFetch);
    }

    private async _fetchImpl(
        href: string,
        options: InterfaceBaseFetchOptions<unknown>,
        retryCount: number
    ): Promise<Response> {
        const {
            additionalRetryErrorCodes,
            successResponseCodes = VALID_HTTP_RESPONSE_CODES,
            // fetchOptions should only contain IFetchOptions
            ...fetchOptions
        } = options;
        const retryErrorCodes = [ ...RETRY_HTTP_RESPONSE_CODES, ...(additionalRetryErrorCodes || []) ];
        const overrides = await this._getFetchOptionOverrides(href, fetchOptions);
        let response = await this._core._environment.fetch(overrides.href, overrides.options);
        const { status } = response;
        if (status === 202) {
            response = await this._monitorResponse(response);
        }

        // Handle any custom error cases
        if (options.handleError && status >= 400) {
            await options.handleError(response.clone());
        }

        // Retry if any of these conditions are met:
        // 1. Response has a Retry-After header
        // 2. Status code is in retryErrorCodes
        if (status >= 400 && (
            getRetryAfterHeader(response.headers)
            || retryErrorCodes.includes(status)
        )) {
            if (retryCount < MAX_ERROR_RETRIES) {
                const delay = this._getRetryErrorDelay(response, retryCount);
                this._core._environment.log(
                    `Retryable error ${status} retrying in ${delay}ms, ${retryCount} retries so far`);
                await new Promise(resolve => setTimeout(resolve, delay));
                return await this._fetchImpl(href, options, retryCount + 1);
            } else {
                this._core._environment.log(
                    `Retryable error ${status} attempt ${retryCount} exceeded ${MAX_ERROR_RETRIES} retries`);
            }
        }
        if (successResponseCodes !== 'any') {
            this._checkResponseStatus(response, href, successResponseCodes);
        }
        return response;
    }

    protected _checkResponseStatus(response: Response, href: string, successResponseCodes: number[]) {
        if (!successResponseCodes.includes(response.status)) {
            const error = SAMError.createWithResponse(response, href);
            this._core._environment.error(`InterfaceBase error ${error}`);
            throw error;
        }
    }

    protected async _monitorResponse(response: Response): Promise<Response> {
        let href: string | null = response.headers.get('location');

        if (!href) {
            const json = await response.json();
            if (!json) {
                throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Failed to parse content for 202 monitor response.');
            }
            href = json.href;
            if (!href) {
                throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Missing href property for 202 monitor response.');
            }
        }

        const delay = this._getMonitorRetryAfter(response.headers);
        return this._fetchMonitorResponse(response.url, href, delay);
    }

    private async _fetchMonitorResponse(originalUrl: string, asyncUrl: string, delay: number): Promise<Response> {
        if (delay) {
            // Wait before trying again.
            await new Promise((resolve) => setTimeout(resolve, delay));
        }
        const asyncResponse = await this._core._environment.fetch(asyncUrl);
        const body = await asyncResponse.text();

        const shouldRetry = this._shouldRetryMonitorResponse(asyncResponse, body);
        if (shouldRetry) {
            // Try again later.
            const newDelay = this._getMonitorRetryAfter(asyncResponse.headers);
            return this._fetchMonitorResponse(originalUrl, asyncUrl, newDelay);
        }

        // If the response was recently returned and it's now a JSON response
        // let's just parse it and return the result, otherwise it's not going to
        // have a standard response body that parseAsyncResponse can handle.
        if (asyncResponse.headers.get('content-type')?.includes('application/json')) {
            return new CacheableResponse(
                originalUrl,
                new Headers(asyncResponse.headers),
                asyncResponse.status,
                asyncResponse.statusText,
                Date.now(),
                body
            );
        }

        // Parse the response from the async call.
        return parseAsyncResponse(originalUrl, body);
    }

    /**
     * Determines whether or not the response indicates the server-side async process is still underway.
     */
    // Overrides can use `body`
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    protected _shouldRetryMonitorResponse(asyncResponse: Response, body: string): boolean {
        return asyncResponse.status === 202;
    }

    /**
     * Calculate how long of a delay before re-requesting the status of a server-side async process.
     */
    private _getMonitorRetryAfter(headers: Headers): number {
        return getRetryAfterHeader(headers) * 1000 || this._core._environment.getValue('ASYNC_DEFAULT_DELAY');
    }

    /**
     * Calculate how long of a delay before retrying a request that failed
     */
    protected _getRetryErrorDelay(response: Response | undefined, retryCount: number): number {
        const min = this._core._environment.getValue('MIN_RETRY_INTERVAL');
        const max = this._core._environment.getValue('MAX_RETRY_INTERVAL');
        const delay = (response && getRetryAfterHeader(response.headers) || Math.pow(2, retryCount)) * 1000;
        return clamp(delay, min, max);
    }

    /**
     * Make a GET request to the Platform API.
     * @param href for request
     * @param additionalFetchOptions {InterfaceBaseFetchOptions} (optional)
     */
    protected async _doGet<ParsedResponse>(href: string, additionalFetchOptions?: InterfaceBaseFetchOptions<ParsedResponse>) {
        return this._fetch(
            href,
            {
                method: 'GET',
                successResponseCodes: VALID_HTTP_RESPONSE_CODES,
                ...additionalFetchOptions
            });
    }

    /**
     * Make a HEAD request to the Platform API.
     * @param href for request
     * @param headers for request
     */
    protected async _doHead(href: string, headers: HeaderMap = {}) {
        return this._fetch(href, { method: 'HEAD', headers });
    }

    /**
     * Make a POST request to the Platform API.
     * @param href for request
     * @param headers for request
     * @param body for request
     * @param successResponseCodes for request. Most POST requests that create something will return a 201 success
     *     code, but sometimes a different success code is used (e.g. 204 for discard/restore).
     * @param noOtherHeaders whether to skip adding other headers
     * @param resource Resource for caching
     * @param signal Optional AbortSignal to cancel the request
     */
    protected async _doPost(href: string, headers: HeaderMap = {}, body?: string | Blob, successResponseCodes: ValidHttpResponseCodes = [ 201 ], noOtherHeaders: boolean = false, resource?: Resource, signal?: AbortSignal) {
        return this._fetch(href, { method: 'POST', headers, noOtherHeaders, body, successResponseCodes, resource, signal });
    }

    /**
     * Make a PATCH request to the Platform API.
     * @param href for request
     * @param headers for request
     * @param body for request
     * @param successResponseCodes for request.
     */
    protected async _doPatch(href: string, headers: HeaderMap = {}, body?: string, successResponseCodes: ValidHttpResponseCodes = [ 200 ]) {
        return this._fetch(href, { method: 'PATCH', headers, body, successResponseCodes });
    }

    /**
     * Make a PUT request to the Platform API.
     * @param href for request
     * @param headers for request
     * @param body for request
     * @param successResponseCodes for request
     * @param noOtherHeaders whether to skip adding other headers
     * @param options Additional options for the request, including handleError callback and signal for cancellation
     */
    protected async _doPut(href: string, headers: HeaderMap = {}, body?: string | Blob, successResponseCodes: ValidHttpResponseCodes = [ 201 ], noOtherHeaders: boolean = false, options?: InterfaceBaseFetchOptions<Response>) {
        return this._fetch(href, { method: 'PUT', headers, body, noOtherHeaders, successResponseCodes, ...options });
    }

    /**
     * Make a DELETE request to the Platform API.
     * @param href for request
     * @param headers for request
     * @param successResponseCodes for request.
     */
    protected async _doDelete(href: string, headers: HeaderMap = {}, successResponseCodes: ValidHttpResponseCodes = [ 200 ], noOtherHeaders: boolean = false) {
        return this._fetch(href, { method: 'DELETE', headers, noOtherHeaders, successResponseCodes });
    }

    /**
     * Get a JSON resource from the platform API - handles parsing the response as JSON
     * @param href for request
     * @param additionalFetchOptions {InterfaceBaseFetchOptions} (optional)
     */
    protected async _getResponse<ParsedResponse extends object>(href: string, additionalFetchOptions?: InterfaceBaseFetchOptions<Response>): Promise<ParsedResponse> {
        const response = await this._doGet(
            href,
            additionalFetchOptions
        );
        return response.json() as ParsedResponse;
    }

    private _sharedResponses: Map<string, Promise<any>> = new Map;

    /**
     * The same as _getResponse, except that it allows piggybacking on a request if it's
     * already in-flight. This is useful when we have multiple places in the code that
     * depend on data from the same request (e.g. getting both collaborators and invitations
     * from the same API), and we want to avoid making repeated requests.
     *
     * @param href for request
     * @param headers for request
     */
    protected async _getSharedResponse(href: string, headers: HeaderMap = {}) {
        let response = this._sharedResponses.get(href);
        if (!response) {
            response = this._getResponse(href, { headers });
            this._sharedResponses.set(href, response);
            response.finally(() => this._sharedResponses.delete(href));
        }
        return response;
    }

    /**
     * Make a request to the Platform API. If it is paged, provide a next callback
     * @param href for page
     * @param headers to send with request
     */
    protected async _getPagedResponse(href: string, headers: HeaderMap = {}): Promise<PaginatedResponse> {
        const result = await this._getResponse<any>(href, headers);
        if (result?._page?.next && result?._links?.[RelType.PAGE]) {
            const template = UriTemplate(result._links[RelType.PAGE].href);
            const nextHref = template.fill({
                ...result._page,
                start: result._page.next,
                resource: RelType.PRIMARY
            });
            const next = () => this._getPagedResponse(nextHref, headers);
            return { result, next };
        }

        return { result };
    }

    /**
     * Get all of the pages of a page (or not) Platform API request
     * @param href starting href
     * @param headers to send along with the requests
     */
    protected _getAllPages(href: string, headers: HeaderMap = {}): Promise<any> {
        let fullResult: any;

        const readPages: (requestFn: () => Promise<PaginatedResponse>) => Promise<any> = async requestFn => {
            const result = await requestFn();
            const children = result && result.result && result.result.children;
            if (!children) {
                return fullResult;
            }

            if (!fullResult) {
                fullResult = result.result;
            } else {
                fullResult.children = fullResult.children.concat(children);
            }

            return result.next ? readPages(result.next) : fullResult;
        };

        return readPages(() => this._getPagedResponse(href, headers));
    }

    /**
     * Get and parse the links header for an object in the Platform API
     * @param href of the object
     */
    protected _getLinksFromHeaders(headers: Headers) {
        const linkHeader = headers && headers.get('Link');
        if (!linkHeader) {
            throw SAMError.create(SAMErrorCode.UNKNOWN, 'HEAD request did not return link header');
        }

        const link = LinkHeader.parse(linkHeader);

        return (
            link
            && link.refs.reduce(
                (memo: any, { rel, uri, ...otherData }) => {
                    if (rel) {
                        memo[rel] = memo[rel] || [];
                        memo[rel].push({ href: uri, ...otherData });
                    }

                    return memo;
                },
                {}
            )
        );
    }

    // Sub-classes can refine requests if needed
    protected async _getFetchOptionOverrides(
        href: string,
        options: IFetchOptions
    ): Promise<{
            href: string;
            options: IFetchOptions
        }> {
        if (this._useHighPriorityRequestsIfEnabled && this._core._environment.getValue('HIGH_PRIORITY_RAPI_REQUESTS')) {
            // See https://wiki.corp.adobe.com/pages/viewpage.action?spaceKey=CA&title=Proposal%3A+Priority+Header#Proposal:PriorityHeader-UrgencySummary
            //
            // If enabled, R-API requests will be made using with Priority u=1 header to enable HTTP/2 and HTTP/3, and
            // to direct R-API to optimize calls for response time. HTTP/2+ reduces delays caused by too many
            // connections open on the same domain. Currently, this can only be done on the edge network (CDN), which
            // incurs some cost, but will likely be brought in-house.
            //
            // User-facing web clients SHOULD typically enable this to optimize user experience, but is off by default
            // so that clients take responsibility for determining what priority to use.
            href = !href.includes('platform-cs-edge')
                ? href.replace('platform-cs', 'platform-cs-edge')
                : href;
            options.headers = {
                ...(options.headers || {}),
                'Priority': 'u=1'
            };
        }

        // See https://wiki.corp.adobe.com/display/CA/Proposal%3A+Storage+Model+Unification+Detailed+Design#Proposal:StorageModelUnificationDetailedDesign-AdministratorACEs
        // If ADMIN_MODE_ORG_ID is set, we need to add a header value to all service requests
        // that contains the orgID provided by the Admin Console.
        const adminModeOrgID = this._core._environment.getValue('ADMIN_MODE_ORG_ID');
        if (adminModeOrgID && !this._core._environment._shouldSkipAdminPrivileges(href)) {
            options.headers = {
                ...(options.headers || {}),
                'X-ACP-ADMIN-PRIVILEGES': adminModeOrgID
            };
        }

        // See https://wiki.corp.adobe.com/display/CA/Support+scalability+in+serving+public+content+in+alignment+with+Community+Platform+Advancement#SupportscalabilityinservingpubliccontentinalignmentwithCommunityPlatformAdvancement-DetailedDesign
        // If REQUEST_EDGE_BASED_PUBLISHED_LINKS is true and we're making a R-API request, we need to
        // add a header value to all service requests so that RAPI returns edge-accelerated links for
        // public assets,even when the originating service endpoint is not edge-accelerated.
        if (this._core._environment.getValue('REQUEST_EDGE_BASED_PUBLISHED_LINKS') && href.startsWith('https://platform-cs')) {
            options.headers = {
                ...(options.headers || {}),
                'acpc-published-links': 'true'
            };
        }

        // When set, all requests will include a User-Id header with the value of REQUEST_AS_USER_ID.
        // This is primarily used for services who are acting on behalf of a user, such as
        // Workfront.
        const requestAsUserID = this._core._environment.getValue('REQUEST_AS_USER_ID');
        if (requestAsUserID) {
            options.headers = {
                ...(options.headers || {}),
                'User-Id': requestAsUserID
            };
        }

        const requestID = this._core._environment.getValue('REQUEST_ID');
        const breadcrumbTrail = this._core._environment.getValue('BREADCRUMB_TRAIL');
        const uuid = samJsUuid();
        if (requestID) {
            options.headers = {
                ...(options.headers || {}),
                'x-request-id': `${requestID}:${uuid}`,
            };
        }

        if (breadcrumbTrail) {
            options.headers = {
                ...(options.headers || {}),
                'x-breadcrumb-trail': `${breadcrumbTrail}-SAMJS_${uuid}`
            };
        }

        const { PRODUCT_ID } = this._core._environment.getValue('HOST_PRODUCT_DATA');
        const appVersion = PRODUCT_ID || 'na';

        const clientAgentData = {
            v: '2',
            app: appVersion || 'na',
            os: 'na',
            device: 'na',
            surface: 'na'
        };

        const analyticsInfo = this._core._environment.getValue('ANALYTICS');

        if (analyticsInfo) {
            let surface: 'web' | 'desktop' | 'mobile' | 'na' = 'na';
            if (analyticsInfo.device) {
                if (analyticsInfo.device === 'phone' || analyticsInfo.device === 'tablet') {
                    surface = 'mobile';
                } else if (analyticsInfo.device === 'desktop') {
                    surface = 'desktop';
                } else {
                    surface = 'web';
                }
            }

            let deviceString = 'na';
            if (analyticsInfo.osArchitecture && analyticsInfo.osVersion) {
                deviceString = analyticsInfo.osArchitecture + ' ' + analyticsInfo.osVersion;
            } else if (analyticsInfo.osVersion) {
                deviceString = analyticsInfo.osVersion;
            }

            clientAgentData.os = analyticsInfo.os || '';
            clientAgentData.device = deviceString;
            clientAgentData.surface = surface;
        }

        const supportedServices = this._core._environment.getValue('EXECUTION_CONTEXT_SUPPORTED_SERVICES') || [];
        const isSupportedService = supportedServices.some(service => href.startsWith(service));

        if (isSupportedService) {
            options.headers = {
                ...(options.headers || {}),
                'Client-Agent': Object.entries(clientAgentData).map(([ key, value ]) => `${key}=${value ? value : 'na'}`).join('; ')
            };
        }

        return { href, options };
    }
}
