import ItemUpdater from '../core/ItemUpdater';
import PropertyUpdater from '../core/PropertyUpdater';

import type { IFrameioTeamResponse } from './FrameioInterface';
import FrameioBase from './FrameioBase';
import type FrameioProject from './FrameioProject';
import { FrameioProjectUpdater } from './FrameioProject';

// See https://developer.frame.io/api/reference/operation/getTeamsByAccount/
//  for schema of the data FrameioTeam encapsulates.
export default class FrameioTeam extends FrameioBase {
    private _projects: Array<FrameioProject> | undefined;
    private _email: string = '';
    private _name: string = '';

    get email(): string {
        return this._email;
    }

    get name(): string {
        return this._name;
    }

    async getProjects(): Promise<Array<FrameioProject>> {
        let projects = this._projects;
        if (!projects) {
            const ctx = this.context;

            const projectsResponse = await this._core.frameioContext._frameioInterface.getProjects(this.id);
            const session = ctx._objectPool.createUpdateSession<FrameioProject>();
            projects = FrameioProjectUpdater.updateRemoteItems(session, projectsResponse);
            session.commit();

            this._projects = projects;
        }

        return projects;
    }
}

export const FrameioTeamUpdater = new ItemUpdater<FrameioTeam, Partial<IFrameioTeamResponse>>({
    localItemType: FrameioTeam,
    remoteIdProperty: 'id',
    propertyUpdater: new PropertyUpdater({
        '_email': 'owner.email',
        '_name': 'name'
    })
});

