import { SAM } from '@ccx-public/component-types';
import type AdobeAsset from '../../src/assets/AdobeAsset';
import {
    MEDIA_TO_HISTORY_ASSET_TYPE
} from '../../src/interface/GenerationHistoryAssetModel';
import { ModernSet } from '../../src/utils/ModernSet';
import type {
    IItemFilter,
    ItemFilterRelation
} from '../../src/core/ItemFilter';
import {
    getMultiValueFilterRelation,
    getSingleValueFilterRelation
} from '../../src/core/ItemFilter';
import { SAMError, SAMErrorCode } from '../../src/core/SAMError';
import { isCopied } from './utils';
export interface GenerationHistoryFeatureFlags {
    featureFlags?: {
        generationHistoryVectors?: boolean;
    }
}

export type IGenerationHistoryFilterParams = SAM.IGenerationHistoryAssetListingOptions & GenerationHistoryFeatureFlags & {
    userId: string;
};

export default class GenerationHistoryAssetFilter implements IItemFilter<AdobeAsset> {
    private _generationGroupId?: string;
    private _historyAssetTypes: SAM.GenerationHistoryAssetType[];
    private _module?: SAM.GenerationHistoryModule;
    private _ignoreCopiedAssets?: boolean;
    private _ignoreOthersCreations?: boolean;
    private _userId?: string;

    constructor(listingOptions?: Partial<IGenerationHistoryFilterParams>) {
        this._generationGroupId = listingOptions?.generationGroupId;
        this._module = listingOptions?.module;
        this._ignoreCopiedAssets = listingOptions?.ignoreCopiedAssets;
        this._ignoreOthersCreations = listingOptions?.ignoreOthersCreations;
        this._userId = listingOptions?.userId;

        let allowedMediaTypes = new ModernSet([
            SAM.GenerationHistoryAssetType.IMAGE,
            SAM.GenerationHistoryAssetType.VIDEO,
            SAM.GenerationHistoryAssetType.AUDIO,
            ...(listingOptions?.featureFlags?.generationHistoryVectors ? [ SAM.GenerationHistoryAssetType.VECTOR ] : []),
        ]);

        if (listingOptions?.historyAssetTypes) {
            allowedMediaTypes = allowedMediaTypes.intersection(new ModernSet(listingOptions.historyAssetTypes));
        }

        if (listingOptions?.historyAssetType) {
            allowedMediaTypes = allowedMediaTypes.intersection(new ModernSet([ listingOptions.historyAssetType ]));
        }

        this._historyAssetTypes = Array.from(allowedMediaTypes);

        if (this._historyAssetTypes.length === 0) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'GenerationHistoryAssetFilter: No valid history asset types provided.');
        }
    }

    get generationGroupId() {
        return this._generationGroupId;
    }

    get historyAssetTypes() {
        return this._historyAssetTypes;
    }

    get module() {
        return this._module;
    }

    get hash(): string {
        return [
            this._module ? `module:${this._module}` : undefined,
            this._generationGroupId ? `generationGroupId:${this._generationGroupId}` : undefined,
            this._historyAssetTypes ? `historyAssetType:${this._historyAssetTypes}` : undefined,
            this._ignoreCopiedAssets ? `ignoreCopiedAssets:${this._ignoreCopiedAssets}` : undefined,
            this._ignoreOthersCreations ? `ignoreOthersCreations:${this._ignoreOthersCreations}` : undefined,
            this._ignoreOthersCreations && this._userId ? `userId:${this._userId}` : undefined,
        ].filter(x => x).join(':');
    }

    matches(item: AdobeAsset) {
        if (this._ignoreCopiedAssets && isCopied(item)) {
            return false;
        }

        // Filter out items if storageAssignee doesn't match the current user
        // If storageAssignee.id is empty/unpopulated, we err on the side of hiding it
        // Use _NoLazyLoad to avoid triggering lazy-load machinery during filtering
        if (this._ignoreOthersCreations && item._storageAssignee_NoLazyLoad.id !== this._userId) {
            return false;
        }

        // If there's a generationGroupId, use this for the item match
        if (this._generationGroupId) {
            return item.appMetadata.data?.firefly?.generationGroupId === this._generationGroupId;
        }

        // If there's a module on the filter, use this for the item match
        if (this._module && item.appMetadata.data?.firefly?.module !== this._module) {
            return false;
        }

        // Default to using the historyAssetTypes for the item match
        return !!this._historyAssetTypes.find(requestedFilterType => {
            return requestedFilterType === MEDIA_TO_HISTORY_ASSET_TYPE[item.mediaType];
        });
    }

    _getGenerationGroupIdRelation(previousGenerationGroupId?: string, newGenerationGroupId?: string): ItemFilterRelation {
        if (previousGenerationGroupId && newGenerationGroupId && previousGenerationGroupId !== newGenerationGroupId) {
            return 'disjoint';
        }

        if (!newGenerationGroupId && previousGenerationGroupId) {
            return 'unknown';
        }

        return 'subset';
    }

    /**
     * This method determines the commonality between the already present filter (previous)
     * and the new filter to be applied (this). The point of this is to
     * see if the new filter (this) can build some, all, or none of it's items
     * from (previous) filter.
     *
     * Subset: Means that ALL items for this filter can be built from previous
     * Disjoint: No items for this filter can be built from previous.
     * Unknown: Some items for this filter can be built from previous.
     *
     * @note we should always determine disjoint cases first before other cases.
     * @note this = NEW FILTER, previous = EXISTING FILTER
     *
     * @param previousFilter The existing filter that we are getting the relation to.
     * @returns { ItemFilterRelation }
     */
    getRelationToFilter(previousFilter: GenerationHistoryAssetFilter): ItemFilterRelation {
        // We don't need to test for the feature flags here because the behavior is incorporated into the historyAssetTypes
        const { _generationGroupId: previousGenerationGroupId,
            _historyAssetTypes: previousHistoryAssetTypes,
            _module: previousModule,
            _ignoreCopiedAssets: previousIgnoreCopiedAssets,
            _ignoreOthersCreations: previousIgnoreOthersCreations,
            _userId: previousUserId } = previousFilter;
        const { _generationGroupId: newGenerationGroupId,
            _historyAssetTypes: newHistoryAssetTypes,
            _module: newModule,
            _ignoreCopiedAssets: newIgnoreCopiedAssets,
            _ignoreOthersCreations: newIgnoreOthersCreations,
            _userId: newUserId } = this;

        const relations: ItemFilterRelation[] = [
            getSingleValueFilterRelation(newModule, previousModule),
            getSingleValueFilterRelation(newGenerationGroupId, previousGenerationGroupId),
            getMultiValueFilterRelation(newHistoryAssetTypes, previousHistoryAssetTypes),
            getSingleValueFilterRelation(newIgnoreCopiedAssets, previousIgnoreCopiedAssets),
            getSingleValueFilterRelation(newIgnoreOthersCreations, previousIgnoreOthersCreations),
            // Only compare userId if ignoreOthersCreations is enabled on BOTH filters
            // If either filter has ignoreOthersCreations disabled, userId has no effect on that filter
            (newIgnoreOthersCreations && previousIgnoreOthersCreations)
                ? getSingleValueFilterRelation(newUserId, previousUserId)
                : 'subset',
        ];

        if (relations.includes('disjoint')) { return 'disjoint'; }
        if (relations.includes('unknown')) { return 'unknown'; }

        return 'subset';
    }
}
