import ItemBase from '../core/ItemBase';
import type { PropertyFormatType } from '../core/PropertyUpdater';
import PropertyUpdater from '../core/PropertyUpdater';
import ItemUpdater from '../core/ItemUpdater';
import type { ISAMObject } from '../indexPrivate';
import ItemPool from '../core/ItemPool';
import { isDeepEqual } from '../core/ObjectUtils';
import SAMError from '../core/SAMError';
import type { IInvitationCollaborator, IInvitationShareBatchResponseItem, IInvitationShareResponse } from '../interface/InvitationModel';
import type Collaborator from './Collaborator';
import { CollaboratorUpdater } from './Collaborator';

export default class CollaboratorsByAssetID extends ItemBase {
    private _collaborators: Collaborator[] = [];
    private _error: SAMError | undefined = undefined;

    /**
     * Since collaborators are a model around the relationship of a
     * particular user and an asset, it should always have an AssetID.
     */
    get getAssetID(): string {
        return this.id;
    }

    get collaborators(): Collaborator[] {
        return this._collaborators;
    }

    get error(): SAMError | undefined {
        return this._error;
    }
}

const CollaboratorFormat: PropertyFormatType = {
    parse: (value: Collaborator[]): Collaborator[] => {
        return value;
    },
    isEqual: (a: Collaborator[], b: Collaborator[]): boolean => {
        return isDeepEqual(a, b);
    }
};

function getCollaborators(source: Partial<IInvitationShareBatchResponseItem>, dest: ISAMObject): Collaborator[] {
    const collaboratorPool = new ItemPool<Collaborator>(dest._core, 'collaborator');
    const session = collaboratorPool.createUpdateSession();
    // failed to fetch collaborators for this asset
    if (source.statusCode! !== 200) {
        return [];
    }
    const response: IInvitationShareResponse = JSON.parse(source.response!);

    // Add the assetID to the response from the URN provided by
    // the service so Collaborators are tied to an asset.
    const collaboratorsWithID = response.collaborators.map((collab: IInvitationCollaborator) => {
        return { ...collab, assetID: source.urn };
    });
    const collaborators = CollaboratorUpdater.updateRemoteItems(session, collaboratorsWithID);
    session.commit();
    return collaborators;
}

const ErrorFormat: PropertyFormatType = {
    parse: (value: SAMError): SAMError => {
        return value;
    },
    isEqual: (a: SAMError, b: SAMError): boolean => {
        return isDeepEqual(a, b);
    }
};

function getError(source: Partial<IInvitationShareBatchResponseItem>): SAMError | undefined {
    if (source.statusCode! === 200) {
        return undefined;
    }
    // this is how a sample response looks like (got it from the sam.js demo)
    // response: '{"statusCode":404,"error":"Not Found"}'
    const response = JSON.parse(source.response!);
    // Note: Since CollaboratorsByAssetID is deprecated, this doesn't attempt to extract the requestId
    return SAMError.createWithRepositoryCode(response.statusCode, '', response.error, '-collaborators-by-asset-id-');
}

export const CollaboratorsByAssetIDUpdater = new ItemUpdater<CollaboratorsByAssetID, Partial<IInvitationShareBatchResponseItem>>({
    localItemType: CollaboratorsByAssetID,
    remoteIdProperty: 'urn',
    propertyUpdater: new PropertyUpdater({
        '_collaborators': { get: getCollaborators, format: CollaboratorFormat },
        '_error': { get: getError, format: ErrorFormat }
    })
});
