export interface IServiceLink {
    href: string;
    templated?: boolean;
    mode?: string;
    type?: string;
}

export type LinkRequirements = Partial<{ [key in RelType]: string[] }>;

export function validateLinkParameters(links: any, key: RelType, params: string[]): boolean {
    try {
        const templateString = getTemplateFromLinks(links, key);
        const template = UriTemplate(templateString);

        // Check that required arguments are available.
        return params.every((param) => template.varNames.indexOf(param) !== -1);
    } catch {
        // We only care if the link is valid. If it is not valid, then we will return false,
        // so that our caches could be invalidated correctly.
        return false;
    }
}

export function validateLinks(links: any, requirements?: LinkRequirements): boolean {
    if (links === undefined) {
        return true;
    }

    if (Object(links) !== links) {
        return false;
    }

    // All links should have an href
    const hasMissingHrefs = Object.keys(links).some(key => {
        const link = links[key];

        if (!Array.isArray(link)) {
            return typeof link.href !== 'string';
        }

        return link.some(({ href }) => typeof href !== 'string');
    });
    if (hasMissingHrefs) {
        return false;
    }

    if (requirements) {
        const keys = Object.keys(requirements) as RelType[];
        const hasAllParameters = keys.every((key) => validateLinkParameters(links, key, requirements[key]!));
        if (!hasAllParameters) {
            return false;
        }
    }

    return true;
}

export function getLink(links: any, key: RelType): IServiceLink {

    let link = links && links[key];

    if (!link || (Array.isArray(link) && link.length === 0)) {
        // The callers of these methods would fail without an actual URL.
        // It is better to fail early by throwing a proper exception.
        throw SAMError.create(SAMErrorCode.BAD_REQUEST, `Missing link for relationship type: ${key}.`);
    }

    if (Array.isArray(link)) {
        link = link[0];
    }

    return link;
}

export function getTemplateFromLinks(links: any, key: RelType): string {
    return getLink(links, key).href;
}
type PrimitiveValue = string | boolean | number;
export function getURLFromLinks(links: any, key: RelType, params: {[s: string]: string | string[] | boolean | Record<string, PrimitiveValue>} = {}): string {
    const templateString = getTemplateFromLinks(links, key);

    const template = UriTemplate(templateString);

    const preparedParams: { [s: string]: string | string[] } = JSON.parse(
        JSON.stringify(params, (key, val) => (typeof val === 'boolean') ? val.toString() : val)
    );

    return template && template.fill(preparedParams);
}

const RETRY_RANDOM_SECONDS = 30; // Choose random seconds between [0,x] for retry-after as a date

export function getRetryAfterHeader(headers?: Headers): number {
    const retryAfterHeader = headers && headers.get('Retry-After');
    if (retryAfterHeader) {
        try {
            // First, try to parse it as a number (retry time in seconds)
            const retryTime = parseInt(retryAfterHeader, 10);
            if (retryTime) {
                return Math.max(0, retryTime);
            }

            // If that fails, try to parse it as a date
            const retryDate = Date.parse(retryAfterHeader);
            if (retryDate) {
                // Need to add a randomised element to ensure requests don't all come back at the same time
                const now = Date.now();
                const retrySeconds = Math.max(0, retryDate - now) / 1000;
                const retryRandom = Math.floor(Math.random() * RETRY_RANDOM_SECONDS);
                return retrySeconds + retryRandom;
            }
        } catch (e) {
            // ignore
        }
    }

    return 0;
}

/**
 * Add query parameters to a url from an object.
 * @param url
 * @param queryParams
 * @returns encoded url with query params
 */
export function fillURLTemplate(url: string, queryParams: Record<string, any>): string {
    const template = UriTemplate(`${url}{?queryParams*}`);
    return template.fillFromObject({ queryParams });
}
