import type { IComparatorMap } from '../core/ItemOrder';
import { compareStrings, createItemOrderFactory } from '../core/ItemOrder';
import type InvitedCollaborator from './InvitedCollaborator';

export type InvitedCollaboratorOrderField = 'email';

const OrderFieldToComparator: IComparatorMap<InvitedCollaborator, InvitedCollaboratorOrderField> = {
    email(a: InvitedCollaborator, b: InvitedCollaborator): number {
        return compareStrings(a.email ?? a.id, b.email ?? a.id);
    }
};

export default class InvitedCollaboratorOrder extends createItemOrderFactory(OrderFieldToComparator) {
    static default = new InvitedCollaboratorOrder('ascending', 'email');
}
