import type {
    IImplicitFilter
} from '../core/ItemFilter';
import type Project from './Project';
import { SAM } from '@ccx-public/component-types';

export default class ImplicitProjectFilter implements IImplicitFilter<Project> {
    view: SAM.ProjectViews = SAM.ProjectViews.All;

    matches(item: Project): boolean {
        // [SHARED-3832] Projects should not show in lists until they're proven to be part of a list
        // [SAMJS-311] All Projects flagged as _isRecent should show up in _isRecent view
        return item.isProject && (item._allowInLists || item._isRecent);
    }
}
