import type { IGetUSSResults } from '../assets/USSLoaderHelper';
import USSLoaderHelper from '../assets/USSLoaderHelper';
import type {
    IItemLoader,
    IItemLoaderOptions,
    ILoadedPage,
} from '../core/ItemLoader';
import type { ISAMCorePrivate } from '../indexPrivate';
import type CustomModelFilter from './CustomModelFilter';
import type { CustomModelSearchConfig } from './CustomModelSource';
import type { USSResponse } from '../interface/USSModel';
import { SearchProps } from '../interface/USSModel';
import type USSInterface from '../interface/USSInterface';
import type { ISearchQueryCustomModel } from '../interface/CustomModelModel';
import { CUSTOM_MODEL_MEDIA_TYPE } from '../interface/CustomModelModel';
import { customModelOrderToUSSOrder } from './CustomModelOrder';
import type CustomModelContext from './CustomModelContext';
import { makeDateRange } from '../utils/dateUtils';

export default class CustomModelSearchLoader implements IItemLoader<CustomModelSearchConfig> {
    private _ussLoaderHelper: USSLoaderHelper<CustomModelSearchConfig>;
    private _ussInterface: USSInterface;

    constructor(
        private _core: ISAMCorePrivate,
        public _customModelContext: CustomModelContext
    ) {
        this._ussInterface = this._core.hostAssetContext._ussInterface;
        this._ussLoaderHelper = new USSLoaderHelper(this._core.hostAssetContext._assetPool, _core, this);
    }

    supportsFilter(filter?: CustomModelFilter): boolean {
        // If we don't provide a filter at all, then we cannot use the loader
        return filter !== undefined;
    }

    loadPage(options: IItemLoaderOptions<CustomModelSearchConfig>): Promise<ILoadedPage<CustomModelSearchConfig>> {
        return this._ussLoaderHelper.loadPage(options);
    }

    /**
     * @package -- for use by USSLoaderHelper
     */
    async _getUSSResults(options: IGetUSSResults<CustomModelSearchConfig>
    ): Promise<USSResponse> {
        const {
            implicitFilter: { query },
            filter: { listingOptions },
            order: customModelOrder
        } = options;

        const createDateRange = makeDateRange(listingOptions?.createDateMax, listingOptions?.createDateMin);
        const modifyDateRange = makeDateRange(listingOptions?.modifyDateMax, listingOptions?.modifyDateMin);

        const ussQuery: ISearchQueryCustomModel = {
            hints: [ { acp_platform_v2: true, creative_cloud_rendition_v2: true } ],
            asset_name: query,
            limit: options.loadOptions?.limit ?? 100,
            start_index: options?.start ?? 0,
            [SearchProps.TYPE]: [ CUSTOM_MODEL_MEDIA_TYPE ],
            creative_cloud_asset_type: 'dcx',
            ...customModelOrderToUSSOrder(customModelOrder),
            fetch_fields: {
                includes: [
                    '_embedded',
                    'stock_content',
                    'link_additional_metadata',
                    'app_metadata',
                    'firefly#cme$$baseModelName',
                    'firefly#cme$$baseModelVersion',
                    'firefly#cme$$conceptId',
                    'firefly#cme$$trainingMode',
                    'firefly#cme$$superclass',
                    'firefly#cme$$version',
                    'firefly#ffmodel'
                ]
            },
            'app_metadata$$cme:publishedState': listingOptions?.publishedState,
            sync_created_date: createDateRange ? { range: createDateRange } : undefined,
            sync_updated_date: modifyDateRange ? { range: modifyDateRange } : undefined
        };

        return this._ussInterface.getQueryResponse(ussQuery);
    }

    /**
     * @package -- only for use by USSLoaderHelper
     */
    _postProcessPage(
        { implicitFilter }: IItemLoaderOptions<CustomModelSearchConfig>,
        page: ILoadedPage<CustomModelSearchConfig>
    ): void {
        const { items } = page;

        implicitFilter._matchingIDsFromSearch = new Set([
            // copy existing, if needed
            ...(implicitFilter._matchingIDsFromSearch || []),
            ...(items.map(item => item.id)) ]);
    }
}
