import type { Action } from '../../models/Action';
import type CloudDriver from './';

import SingleOperation from '../SingleOperation';
import { mapResponseToLibraryData } from './utils/melvilleModelMappers';
import { getRequestError } from '../../errors/RequestError';
import AsyncResponse from '../AsyncResponse';
import type { ResourceRef } from '../../CCLibraries';
import type { LinkReference } from '../../../index';
import { trace, traceableAs } from '../../../core/decorators/trace';

type Access = 'team_view' | 'invite_only' | 'team_edit';

type ResourceDesignator = {
    relType: 'http://ns.adobe.com/adobecloud/rel/metadata/application' | 'http://ns.adobe.com/adobecloud/rel/primary';
};

type CreateLibraryPayload = {
    name?: string;
    roles?: Array<{
        type: 'brand' | string;
        usage?: string;
        priority?: string;
    }>;
    source?: string;
    parent_assetId?: string;
    access?: Access;
    includeResources?: Array<ResourceDesignator>;
    documentExtractionData?: ResourceRefPayload[];
};

type ResourceRefPayload = {
    ['repo:assetId']: string;
    ['repo:version']: string;
} & LinkReference;

// Modify attribute names to their full names when interfacing with the API
const resourceRefToPayload = (resourceRef: ResourceRef[]): ResourceRefPayload[] => {
    return resourceRef.map(r => {
        const { id, version, ...rest } = r;
        return { ...rest, ['repo:assetId']: id, 'repo:version': version };
    });
};

const PERMISSION_INHERITANCE_MAP: { [s: string]: Access } = {
    read: 'team_view',
    all: 'team_edit'
};

const supportedActionNames = [
    'createLibrary',
    'removeLibrary', // private library
    'unfollowLibrary', // leave a team or public or even incoming library
    'leaveLibrary', // leave an incoming library
    'permanentlyDeleteLibrary',
    'copyLibrary',
    'moveLibrary'
];

@traceableAs('CloudSingleOperation')
export default class CloudSingleOperation extends SingleOperation<CloudDriver> {
    protected _actionMappers = {
        createLibrary: (action: Action) => this._createLibraryActionMap(action),
        copyLibrary: (action: Action) => this._createLibraryActionMap(action),
        removeLibrary: async (action: Action) => {
            await this._removeLibrary();
            return action;
        },
        permanentlyDeleteLibrary: async (action: Action) => {
            await this._permanentlyDeleteLibrary();
            return action;
        },
        unfollowLibrary: async (action: Action) => {
            await this._unfollowLibrary();
            return action;
        },
        leaveLibrary: async (action: Action) => {
            await this._leaveLibrary();
            return action;
        },
        moveLibrary: async (action: Action) => {
            const data = await this._moveLibrary();
            return { ...action, data, originalAction: action };
        }
    };

    supportsAction(action: Action) {
        return supportedActionNames.includes(action.name as string);
    }

    private _createLibraryActionMap = async (action: Action): Promise<Action> => {
        const data = await this._createLibrary(action);
        return { ...action, type: 'update', data, originalAction: action };
    };

    @trace
    private _createLibrary(action: Action) {
        return new Promise((resolve, reject) => {
            const { name, team, roles, documentExtractionData } = action.data ?? {};
            const {
                permissionInheritance,
                source,
                includeAppMetadata: includeApplicationMetadata
            } = action.flags ?? {};
            const payload: CreateLibraryPayload = {
                name,
                roles,
                documentExtractionData:
                    documentExtractionData?.length > 0 ? resourceRefToPayload(documentExtractionData) : undefined,
                // @ts-expect-error R-TODO
                source: source?.assetId,
                parent_assetId: team?.id,
                access: PERMISSION_INHERITANCE_MAP[permissionInheritance as string] || undefined,
                includeResources: includeApplicationMetadata
                    ? [
                        { relType: 'http://ns.adobe.com/adobecloud/rel/metadata/application' },
                        { relType: 'http://ns.adobe.com/adobecloud/rel/primary' }
                    ]
                    : undefined
            };
            const request = this._driver.fetch('/api/v1/libraries?invocation_mode=async', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify(payload)
            });
            const asyncResponse = new AsyncResponse(this._driver, request);
            asyncResponse.on('change', (done, response) => {
                if (done) {
                    if (asyncResponse.error) {
                        reject(asyncResponse.error);
                    } else if (response) {
                        const libraryData = mapResponseToLibraryData(response);

                        // TEMPORARY WORKAROUND TO MANUALLY UPDATE APPMETADATA
                        // CCXB-21559 WILL DO THIS AUTOMATICALLY IN THE BACKEND SOON
                        if (documentExtractionData?.length > 0 && libraryData.assetId) {
                            this._patchBrandAppMetadata(
                                libraryData.assetId,
                                '/brand:extractedFrom',
                                resourceRefToPayload(documentExtractionData)
                            );
                        }

                        // Implicitly, if we've created a library, we know it and its parent are writable.
                        // Melville does not return ACLs on create response.
                        libraryData.isWritable = true;
                        libraryData.isParentWritable = true;
                        resolve(libraryData);
                    } else {
                        resolve(undefined);
                    }
                }
            });
        });
    }

    private _removeLibrary() {
        return this._driver.fetch(`/api/v1/libraries/${this._library.assetId}`, { method: 'DELETE' });
    }

    private _permanentlyDeleteLibrary() {
        return this._driver.fetch(`/api/v1/libraries/${this._library.assetId}?permanent=true`, { method: 'DELETE' });
    }

    private _unfollowLibrary() {
        return this._driver.fetch(`/api/v1/libraries/bookmarks/${this._library.bookmark?.id}`, { method: 'DELETE' });
    }

    private async _leaveLibrary() {
        const userId = this._driver.config.user?.id;
        const response = await this._driver.fetch(
            `https://${this._driver.driverConfig.invitation_hostname}/api/v4/share/${this._library.assetId}`,
            {
                method: 'PATCH',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    collaborators: [
                        {
                            action: 'remove',
                            id: userId
                        }
                    ]
                })
            }
        );

        const json = await response.json();

        const error = json.collaborators?.find((collab: any) => collab.statusCode > 300);
        if (!error) {
            return this._unfollowLibrary();
        } else {
            throw getRequestError(response);
        }
    }

    private _moveLibrary() {
        return this._driver.moveLibrary(
            this._library.assetId as string,
            this.action.data.team.id,
            this.action.data.owner
        );
    }

    private async _patchBrandAppMetadata(assetId: string, path: string, newAppMetadata: Object) {
        const asset = await this._driver._core?.hostAssetContext.getAssetWithCloudID(assetId);
        asset?.patchAppMetadata([ { op: 'add', path, value: newAppMetadata } ]);
    }
}
