import type { ObservableQuery, WatchQueryFetchPolicy } from '@apollo/client';
import SAMError, { throwIfNoData } from '../core/SAMError';
import { isDeepEqual } from '../core/ObjectUtils';
import type Resource from '../assets/Resource';
import { synchronized } from '../core/decorators';
import { ManagedPromise } from '../utils/ManagedPromise';
import type { ISAMCorePrivate } from '../indexPrivate';
import { getOldestTimestamp } from './timestamps';
import type { Observer } from 'rxjs';

/**
 * Watches an Apollo watchQuery and manages its lifecycle, including subscription,
 * error handling, and callbacks for deferred data. Provides a promise for the first result,
 * and a callback when subsequent results are returned (to handle deferred data).
 *
 * @template T The type of the resource data.
 * @implements Observer<ApolloClient.QueryResult<T>>
 */
export class ResourceQueryWatcher<T> implements Partial<Observer<ObservableQuery.Result<T>>> {

    static nextDebugId = 0;

    subscription: ReturnType<ObservableQuery<any>['subscribe']> | undefined;
    previousResult: ObservableQuery.Result<T> | undefined;
    firstResultPromise = new ManagedPromise<T>();
    debugId = ++ResourceQueryWatcher.nextDebugId;

    // Due to ambiguities in Apollo's loading flag when using the cache,
    // we track the time we fetched this query. Any results older than
    // this are definitely from the cache.
    readonly startTime = Date.now();

    constructor(
        private readonly _core: ISAMCorePrivate,
        private readonly resource: Resource<T>,
        private readonly fetchPolicy: WatchQueryFetchPolicy,
        private readonly processIncrementalData?: (result: any) => void
    ) {
    }

    start(subscription: ReturnType<ObservableQuery<any>['subscribe']>) {
        this.subscription = subscription;
    }

    unsubscribe() {
        // Unsubscribing directly from a `next()` callback causes errors in
        // Apollo's baseHttpLink, because the unsubscribe triggers a
        // signal.abort() that aborts the underlying fetch request while reading
        // the body. To avoid this, we schedule the subscription to unsubscribe
        // in the next microtask.
        Promise.resolve().then(() => {
            if (!this.subscription?.closed) {
                this.subscription?.unsubscribe();
            }
        });
    }

    @synchronized
    async next(result: ObservableQuery.Result<T>) {
        // SAM requests weren't designed to observe a GQL query indefinitely,
        // so we unsubscribe when the query is complete.
        if (!result.loading) {
            this._core._environment.log(`[ResourceQueryWatcher ${this.debugId}] Query complete for ${this.resource?.constructor.name}`);
            this.unsubscribe();
        }

        let parsedResult;
        let oldestTimestamp = Date.now();
        try {
            const nonNullDataProperties = [ ...Object.entries(result.data || {}) ]
                .filter(([ _, val ]) => val !== undefined && val !== null);
            if (result.loading && !nonNullDataProperties.length) {
                // All properties on response.data are null/undefined, so there is no data from cache to
                // be returned yet. Since it's loading, that means it is refreshing in the background.
                return;
            }
            throwIfNoData(this._core, result.data, result.error);
            parsedResult = await this.resource?._parse(result) as T;
            oldestTimestamp = getOldestTimestamp(parsedResult);
        } catch (error) {
            this.resource?._setError(error);
            if (!this.previousResult) {
                this.firstResultPromise.reject(error);
            }
            this.unsubscribe();
            return;
        }

        // Sometimes, the Apollo cache will fire an update in response to a _separate_ query.
        // For example, if we query for folder metadata _and_ getChildren at the same time,
        // whenever those updates change the Apollo cache, observables will trigger.
        // However, Apollo's "loading" flag can be `false` in this case[1], even though the data is
        // from the cache and may still be stale.
        //
        // To ensure that we don't prematurely mark the resource as loaded, we check the timestamps
        // of the result against the start time of the query. If any of the data is older than when we started
        // the query, we know it's from the cache and may be stale, so we keep `loading` as `true`.
        // This ensures that lists don't get marked as ReadyFullyLoaded until we have data directly from the service.
        // However, if we're doing a "cache-first" request (during revalidation) where we _don't_ expect a network response,
        // we don't expect results to be newer than startTime, so we'll just trust the loading flag in that case.
        //
        // [1]: https://github.com/apollographql/apollo-client/issues/11318
        const expectsNetworkResponse = this.fetchPolicy !== 'cache-first';
        const isStillFromCache = oldestTimestamp < this.startTime;
        const loading = result.loading || (expectsNetworkResponse && isStillFromCache);

        if (this.previousResult && isStillFromCache) {
            this._core._environment.debug(
                `[ResourceQueryWatcher ${this.debugId}] Ignoring additional cached result `
                + `for ${this.resource?.constructor.name} (oldest timestamp ${oldestTimestamp})`);
        }

        // If we're skipping revalidation, never mark the result as changed.
        const changed = !this.resource?.skipRevalidation && !isDeepEqual(this.previousResult?.data, result.data, true);

        await this.resource?._setData(parsedResult, {
            // We only want to set `loading` if we know we're definitely going to get more data.
            // This is used to prevent lists from being ReadyFullyLoaded until all data is received.
            loading,
            // If the result has changed from the previous result, we mark it as changed.
            // ItemLoaderState will recompute its lists if it gets notified that a non-loading
            // result has arrived that didn't match the previous result.
            changed,
            // We use the oldest timestamp found in the result to mark when the data was fetched.
            // If the data is directly from the service, this will be (very close to) Date.now().
            // If the data is from the cache, it may be older. When merging data into the models,
            // assets that have been mutated newer than this timestamp will not be overwritten.
            timestamp: oldestTimestamp
        });

        // If there was a mix of data and errors, capture the error but still resolve. Downstream code
        // can decide if the missing data is an error, and throw or inspect Resource.error as needed.
        // It should come after _setData, which clears _error. Probably should come before resolving
        // so that Resource.error is set when the firstResultPromise resolves.
        if (result.error) {
            await this.resource?._setError(SAMError.createWithApolloError(result.error));
        }

        if (!this.previousResult) {
            this.firstResultPromise.resolve(parsedResult);
        } else {
            this.processIncrementalData?.(parsedResult);
        }
        this.previousResult = result;
    }

    // Note: ObservableQuery never fires `error` in Apollo 4, so no `.error()` callback is needed.
    // https://www.apollographql.com/docs/react/migrating/apollo-client-4-migration#network-errors-never-terminate-observablequery
}
