import type { Gradient } from '../../index';
import Model from './Model';
import observable from '../utils/observable';

export type GradientData = {
    type: Gradient['type'];
    angle: Gradient['angle'];
    stops: Gradient['stops'];
};

export type TeamData = {
    name: string;
    id: string;
    owner: {
        type: 'org' | 'user';
        id: string;
    };
    ownerName: string;
    isReadOnly?: boolean;
    isWritable?: boolean;
    gradient?: GradientData;
};

export default class Team extends Model<TeamData> {

    // TODO-R: Temporarily avoids breaking code. When updating this file to use ItemUpdater Pattern, remove this.
    private _data: TeamData = {} as TeamData;
    get data(): TeamData {
        return this._data;
    }

    get name() {
        return this._data.name;
    }

    get owner() {
        return this._data.owner;
    }

    get ownerName() {
        return this._data.ownerName;
    }

    get isReadOnly() {
        return this._data.isReadOnly;
    }

    get isWritable() {
        return this._data.isWritable;
    }

    private async _refreshGradient() {
        // Don't refetch the gradient.
        if (this._data.gradient) {
            return this._data.gradient;
        }
        const gradient = await this._apiRoot.driver.getProjectGradient(this);
        this._update({ gradient });
    }

    @observable
    get gradientData() {
        this._refreshGradient();
        return this._data.gradient;
    }
}
