import type { IItemLoader, IItemLoaderOptions, ILoadedPage } from '../core/ItemLoader';
import type Comment from './Comment';
import { CommentUpdater } from './Comment';
import type { CommentConfig } from './CommentSource';
import type CommentsResource from './CommentsResource';
import type ItemPool from '../core/ItemPool';
import type CommentInterface from '../interface/CommentInterface';
import type { CommentCore, ComputedCommentCore, IAnnotationCollection } from '../interface/CommentModel';
import type { ILoadOptions } from '../core/ItemList';

export default class CommentLoader implements IItemLoader<CommentConfig> {
    private _etag?: string;
    private _retryAfter?: string;

    constructor(private _commentsResource: CommentsResource) {}

    async loadPage(options: IItemLoaderOptions<CommentConfig>): Promise<ILoadedPage<CommentConfig>> {
        return await this._loadPage(options);
    }

    get retryAfter(): number {
        // convert seconds:string into milliseconds:Number
        return +(this._retryAfter || '12') * 1000;
    }

    private get _pool(): ItemPool<Comment> {
        return this._commentsResource!._commentPool!;
    }

    private get _interface(): CommentInterface {
        return this._commentsResource!._commentInterface!;
    }

    private async _loadPage(options: IItemLoaderOptions<CommentConfig> & { clearEtag?: boolean }, start?: number): Promise<ILoadedPage<CommentConfig>> {
        // Red Hawk doesn't paginate or sort, so parameters are ignored.
        start;

        // The etag doesn't update when the PUPA Data for comments has been updated (read/unread status)
        // so we need to clear the etag when a force refresh is requested.
        const loadOptions = options.loadOptions as ILoadOptions & { clearEtag?: boolean };
        const forceRefresh = loadOptions.clearEtag ?? false;
        if (forceRefresh) {
            this._etag = undefined;
        }

        // For the initial load(), this._etag is undefined.
        // When polling(), it's the etag from the last call.

        // NOTE: This makes the assumption the loader is only used for one list,
        // which is true in the CommentsResource case.
        const response = await this._interface.getCommentList(this._etag);

        // use (get() || undefined) to convert null into undefined
        this._retryAfter = response.headers.get('retry-after') || undefined;
        this._etag = response.headers.get('etag') || undefined;
        const status = response.status;

        // For (status === 200), the body is a list of comments.
        if (status === 200) {
            const result = await response.json() as IAnnotationCollection;
            const items: ComputedCommentCore[] = result.first.items.map((item: CommentCore) => {
                return {
                    ...item,
                    readStatus: item.perUserPerAnnotation?.read || false
                };
            });

            const session = this._pool.createLoaderUpdateSession(Date.now());
            const comments = CommentUpdater.updateRemoteItems(session, items);
            session.commit();

            comments.forEach((comment) => {
                comment['_commentsResource'] = this._commentsResource;
            });

            return {
                items: comments,
                total: comments.length,
                loadNextPage: undefined
            };
        }

        // For (status === 208), the body is omitted because our local etag
        // matches the remote etag ( aka nothing has changed ).
        //
        // We are required to return a list of comments, and we've already
        // assumed CommentsResource has one list for one loader, so we'll
        // return the existing list of comments.
        const comments = this._commentsResource.getCommentList()?.items || [];

        return {
            items: comments,
            total: comments.length,
            loadNextPage: undefined
        };
    }
}
