import type { RelType } from './LinkUtils';

/**
 * Known organization capabilities returned by the Projects service organizations API.
 */
export enum OrgCapability {
    /**
     * The organization can create projects.
     */
    CREATE = 'create',
}

export interface IOrganization {
    'organization:id': string;
    'organization:name': string;
    'organization:capability'?: OrgCapability[];
}

export interface Organization {
    id: string;
    name: string;
    capability?: OrgCapability[];
}

export interface IOrganizationsResponse {
    children: IOrganization[];
    _links: [RelType.ORGANIZATIONS_COLLECTION];
    default: string;
}
