import type { SAM } from '@ccx-public/component-types';
import type {
    CustomModelConfig,
    CustomModelDashboardConfig,
    CustomModelDashboardSource,
    CustomModelSearchConfig,
    CustomModelSearchSource,
    CustomModelSource,
} from './CustomModelSource';
import { memoize } from '../core/decorators';
import { keepAlive } from '../core/decorators/KeepAliveManager';
import type AdobeAsset from '../assets/AdobeAsset';
import type ItemPool from '../core/ItemPool';
import type { ISAMCorePrivate, ISAMObject } from '../indexPrivate';
import ItemSource from '../core/ItemSource';
import CustomModelLoader from '../custom-models/CustomModelLoader';
import type CustomModel from './CustomModel';
import { CustomModelUpdaterMelville } from './CustomModel';
import CustomModelSearchLoader from './CustomModelSearchLoader';
import CustomModelInterface from '../interface/CustomModelInterface';
import CustomModelSearchFilter from './CustomModelSearchFilter';
import ImplicitCustomModelFilter from './ImplicitCustomModelFilter';
import type Library from '../libraries/Library';
import { LibraryUpdater } from '../libraries/Library';
import type { LibraryConfig, LibrarySource } from '../libraries/LibrarySource';
import LibraryInterface from '../interface/LibraryInterface';
import LibraryListLoader from '../libraries/LibraryListLoader';
import ImplicitLibraryFilter from '../libraries/ImplicitLibraryFilter';
import type {
    CreateTrainingSetOptions,
    CustomModelCreateOptions,
    CustomModelTrainingConfiguration,
    CustomModelUpdateInfoMelville,
} from '../interface/CustomModelModel';
import SAMError, { SAMErrorCode } from '../core/SAMError';
import LegacyCustomModelContext from './legacy-cme/LegacyCustomModelContext';
import type { IOrderDirection } from '../core/ItemOrder';
import type { ICustomModelListingOptions } from './CustomModelFilter';
import CustomModelFilter from './CustomModelFilter';
import { default as CustomModelOrder, type CustomModelOrderField } from './CustomModelOrder';
import ImplicitCustomModelDashboardFilter from './ImplicitCustomModelDashboardFilter';
import { type  LibraryFilterOptions } from '../libraries/LibraryFilter';
import { default as TrainingSetFilter } from './TrainingSetFilter';
import { default as LibraryOrder, type  LibraryOrderField } from '../libraries/LibraryOrder';

/**
 * Provides Custom Model functionality such as listing.
 *
 * @experimental This API is in an experimental phase so expect that
 * API's will not be final and there will be breaking changes
 * without bumping the major version until this comment is removed.
 */
export default class CustomModelContext implements ISAMObject, SAM.CustomModelContext  {
    readonly _customModelInterface = new CustomModelInterface(this._core);

    constructor(
        /** @package -- for use in SAM.js only
         */
        readonly _core: ISAMCorePrivate,
        /** @package -- for use in SAM.js only
         */
        readonly _assetPool: ItemPool<CustomModel | AdobeAsset>) {
    }

    /** @package -- only for use in SAM.js Updaters shouldn't be accessed directly.
     */
    readonly _customModelUpdaterMelville =  CustomModelUpdaterMelville;

    /** @package -- only for use in SAM.js
     */
    private _LegacyCustomModelContext: LegacyCustomModelContext | undefined;

    /** @deprecated -- prefer use of CustomModelContext
     */
    get legacyCustomModelContext() {
        if (!this._LegacyCustomModelContext) {
            this._LegacyCustomModelContext = new LegacyCustomModelContext(this._core, this._assetPool);
        }

        return this._LegacyCustomModelContext;
    }

    /**
     * @package -- only for use in SAM.js
     */
    private readonly _libraryInterface: LibraryInterface = new LibraryInterface(this._core);

    /**
   * The accuracy of a search source is ephemeral in that after the search is executed, the collection of returned assets
   * returned can no longer be assumed to be the complete set of assets that meet the search criteria. ie as new assets
   * are added/removed which should alter assets in the source, the source will not be live updated and will need to be
   * recreated (refetched) from USS to get the latest set of qualifying assets.
   */
    customModelSearchSource(query: string): CustomModelSearchSource {
        const implicitFilter = new CustomModelSearchFilter({ query });

        return new ItemSource<CustomModelSearchConfig>(
            this._assetPool as ItemPool<CustomModel>,
            [ new CustomModelSearchLoader(this._core, this) ],
            implicitFilter
        );
    }


    /*This source contains:
     *  - All training sets a user has access to
     *  - All custom models for which the user is a generator
     * The only way to detect if the user is a generator is to filter out the custom models where the user DOES have access to the training set.
     * However, since that takes a very long time in cases where there are many training sets, we're going to instead use the heuristic
     * that a generator typically has read, but not write or comment permissions.
     * This is subject to change in the future, and hopefully we come up with a better solution for determining which custom models to include in this view.
     */
    customModelDashboardSource(): CustomModelDashboardSource {
        //don't use the same source as the full training set list, to leave open the possibility of a filter on the training sets
        const implicitFilter = new ImplicitCustomModelDashboardFilter({
            //filter out custom models where we have access to the training set id
            customModelFilter: new ImplicitCustomModelFilter({ generatorOnly: true }),
            trainingSetFilter: ImplicitLibraryFilter.TrainingSets }
        );
        return new ItemSource<CustomModelDashboardConfig>(
            this._assetPool as ItemPool<CustomModel | Library>,
            [
                new CustomModelLoader<CustomModelDashboardConfig>(
                    this._assetPool,
                    this._core,
                    this._customModelInterface
                ),
                new LibraryListLoader<CustomModelDashboardConfig>(
                    this._assetPool as ItemPool<AdobeAsset | Library>,
                    this._libraryInterface,
                    LibraryUpdater,
                    this._core
                )
            ],
            implicitFilter
        );
    }

    /**
   * @example
   * const customModelContext = samCore.customModelContext;
   * const customModelSource = customModelContext.customModelSource;
   *
   * Gets all custom models a user has access to
   */
    @memoize
    get customModelSource(): CustomModelSource {
        return new ItemSource<CustomModelConfig>(
            this._assetPool as ItemPool<CustomModel>,
            [
                new CustomModelLoader<CustomModelConfig>(
                    this._assetPool,
                    this._core,
                    this._customModelInterface
                ),
            ],
            new ImplicitCustomModelFilter()
        );
    }



    @keepAlive
    async createTrainingSet(options: CreateTrainingSetOptions): Promise<Library> {
        return this._customModelInterface.createTrainingSet(options);
    }

    /**
     * Returns the `TrainingSetSource` which will return a list of training set libraries the user has access to.
     * @example
     * const context = await core.getCustomModelContext();
     * const order = new LibraryOrder('ascending', 'modified');
     * const filter = TrainingSetFilter.DEFAULT;
     * const list = await context.trainingSetsSource().getList(order, filter, loadOptions);
     * list.on(STATE_CHANGED, () => {
     *     if (list.status !== AssetListStatus.Loading) { const trainingSets = list.items; }
     * });
     */
    @memoize
    async trainingSetsSource(): Promise<LibrarySource> {
        const libraryContext = await this._core.getLibraryContext();
        const loader = new LibraryListLoader<LibraryConfig>(
            libraryContext._assetPool,
            this._libraryInterface,
            LibraryUpdater,
            this._core
        );
        return new ItemSource<LibraryConfig>(libraryContext._assetPool as ItemPool<Library>, [ loader ], ImplicitLibraryFilter.TrainingSets);
    }

    /* We need to always fetch remotely because local training sets might have been populated by a melville listing,
     * and those training sets don't have custom model data.
     */
    @keepAlive
    async getTrainingSetById(assetId: string): Promise<Library | undefined> {
        return this._customModelInterface.getTrainingSetById(assetId);
    }

    /**
     * Update a training set's metadata
     * @param assetId Training set asset ID
     * @param metadata metadata object to update the training set with
     * @param overwrite boolean indicating whether to overwrite existing metadata or merge it with the new metadata.
     * To delete a metadata field, set overwrite to true and exclude the field from the metadata object.
     */
    async updateTrainingSet(assetId: string, metadata: Partial<CustomModelTrainingConfiguration>, overwrite: boolean = false): Promise<void> {
        // If overwrite is true and the metadata payload doesn't have all required fields, throw an error
        if (overwrite && (!metadata.schemaVersion || !metadata.trainingMode)) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Schema version and training mode are required fields on the training set metadata. To overwrite all metadata, these must be included in the payload.');
        }

        const trainingSet = await this.getTrainingSetById(assetId);

        if (!trainingSet) {
            throw SAMError.create(SAMErrorCode.NOT_FOUND, 'Training set not found');
        }

        let payload;
        // If overwrite is false, merge existing metadata with passed in metadata to make sure we don't overwrite old metadata fields
        if (!overwrite) {
            payload = {
                ['firefly#cme']: {
                    ...trainingSet.customModelInfo,
                    ...metadata
                }
            };
        } else {
            payload = {
                ['firefly#cme']: {
                    ...metadata
                }
            };
        }

        await this._libraryInterface.updateMetadata(trainingSet.id, payload);
        // TODO: If Melville changes the PUT libraries metadata endpoint to return the updated item, we need to remove refetching the item
        // JIRA: https://jira.corp.adobe.com/browse/GLOW-467
        // `getTrainingSetById` will fetch from remote and update the local item
        await this.getTrainingSetById(trainingSet.id);
    }

    @keepAlive
    async createCustomModel(options: CustomModelCreateOptions): Promise<CustomModel> {
        const customModelData = await this._customModelInterface.createCustomModel(options);

        const session = this._assetPool.createMutationSession<CustomModel>();
        const customModel = this._customModelUpdaterMelville.updateRemoteItem(session, customModelData);
        session.commit();

        return customModel;
    }

    /**
     * Fetch the custom model from the server, update the remote/local cache, and return it.
     * @param customModelId The ID of the custom model to fetch
     * @returns The updated custom model
     */
    private async _fetchAndUpdateCustomModelById(customModelId: string): Promise<CustomModel> {
        const customModelData = await this._customModelInterface.getCustomModelById(customModelId);
        const session = this._assetPool.createMutationSession<CustomModel>();
        const customModel = this._customModelUpdaterMelville.updateRemoteItem(session, customModelData);
        session.commit();

        return customModel;
    }

    /**
     * Fetches one custom model by its ID.
     * Will first check the local asset pool for the custom model and return it if found.
     * If not found, will fetch the custom model from the server and return it.
     * @param customModelId
     * @returns
     */
    @keepAlive
    async getCustomModelById(customModelId: string): Promise<CustomModel> {
        // Check if we have the custom model in the local item pool
        const customModel = this._assetPool.getLocalItemById<CustomModel>(customModelId);
        if (customModel) {
            if (!customModel.isCustomModel) {
                throw SAMError.create(SAMErrorCode.INVALID_OPERATION, 'Attempting to fetch asset type that is not a custom model');
            }
            return customModel;
        }

        // If not, fetch it from the server
        return this._fetchAndUpdateCustomModelById(customModelId);
    }

    /**
     * Given an id and CustomModelUpdateInfoMelville, update the custom model with the new data.
     * @param customModelId string
     * @param options CustomModelUpdateInfoMelville
     */
    async updateCustomModel(customModelId: string, options: CustomModelUpdateInfoMelville): Promise<void> {
        // Update the custom model in Melville
        await this._customModelInterface.updateCustomModel(customModelId, options);
        // Update the local custom model with the new data
        await this._fetchAndUpdateCustomModelById(customModelId);
    }

    /**
     * @experimental
     */
    getCustomModelOrder(direction: IOrderDirection = 'descending', field: CustomModelOrderField = 'modified'): CustomModelOrder {
        return new CustomModelOrder(direction, field);
    }

    /**
     * @experimental
     */
    getCustomModelFilter(options?: Partial<ICustomModelListingOptions | undefined>): CustomModelFilter {
        return new CustomModelFilter(options);
    }

    /**
     * @experimental
     */
    getTrainingSetOrder(direction: IOrderDirection = 'descending', field: LibraryOrderField = 'modified'): LibraryOrder {
        return new LibraryOrder(direction, field);
    }

    /**
     * @experimental
     */
    getTrainingSetFilter(options?: Pick<LibraryFilterOptions, 'project'>): TrainingSetFilter {
        return new TrainingSetFilter(options);
    }
}
