import {
    FOLDER_ALTERNATE_TYPE,
    FOLDER_TYPE
} from './AssetInterface';

export function updateAssetTypeForUSS(type?: string[]) {
    // directories in uss contain mime type 'application/x-sharedcloud-collection+json'
    // adding it to the list if clients wants to search for directories
    if (type?.find((item) => {return item === FOLDER_TYPE;})) {
        type.push(FOLDER_ALTERNATE_TYPE);
    }
}
