import { v4 } from 'uuid';

declare global {
    interface Crypto {
        randomUUID(): `${string}-${string}-${string}-${string}-${string}`
    }
}

// NOTE: since UXP doesn't provide `window.crypto` (https://jira.corp.adobe.com/browse/UXP-12909), SAM.js must include
// an old version of uuid (3.3.2) that does not require `window.crypto` at all. Otherwise, each host app has to
// inject the crypto API, which is not ideal, as it then becomes a hidden dependency for SAM.js. Host apps may still
// choose to provide the crypto API for more cryptographically secure uuid, but there does not appear to be any
// security holes in SAM.js using the older algorithm.
export default function samJsUuid(): string {
    if (typeof crypto !== 'undefined' && crypto.randomUUID) {
        return crypto.randomUUID();
    }
    return v4();
}
