import type LegacyCustomModel from './LegacyCustomModel';
import type {
    IImplicitAdobeAssetFilterBaseOptions
} from '../../assets/ImplicitAdobeAssetFilterBase';
import ImplicitAdobeAssetFilterBase from '../../assets/ImplicitAdobeAssetFilterBase';
import type { IImplicitFilter } from '../../core/ItemFilter';

export default class ImplicitCustomModelFilter extends ImplicitAdobeAssetFilterBase implements IImplicitFilter<LegacyCustomModel> {
    constructor(options?: Partial<IImplicitAdobeAssetFilterBaseOptions>) {
        super(options);
    }

    matches(item: LegacyCustomModel) {
        if (!item.isCustomModel) {
            return false;
        }

        return super.matches(item);
    }
}
