import TypedEventEmitter from '../core/TypedEventEmitter';
import type { ItemBaseEvents } from '../core/ItemBase';
import { isDeepEqual } from '../core/ObjectUtils';
import type { ISAMCorePrivate } from '../indexPrivate';

// @TODO Verify this solution and address the following task.
// We should also write unit tests precisely verifying this behavior.
// https://jira.corp.adobe.com/browse/SAM-2677
const finalizationRegistry = new FinalizationRegistry(objUrl => {
    URL.revokeObjectURL(objUrl as string);
});

export enum RenditionStatus {
    /**
     * Initial status
     */
    NotStarted = 0,
    Fetching = 1,
    Done = 2,
    /**
     * Occurs when there are any errors around fetching the
     * rendition from the service, AdobeAsset.clearRenditionError can
     * be used to clear the error and fetch again.
     */
    Error = 3
}

export enum RenditionSize {
    Size64 = 64,
    Size128 = 128,
    Size256 = 256,
    Size512 = 512,
    Size1024 = 1024,
}

export enum RenditionType {
    PNG = 'image/png',
    JPEG = 'image/jpeg'
}

export const THUMBNAIL_SIZE: number = RenditionSize.Size512; // matches ACPL/SAM.cpp thumbnail size

export const SUPPORTED_SIZES = [
    RenditionSize.Size64,
    RenditionSize.Size128,
    RenditionSize.Size256,
    RenditionSize.Size512,
    RenditionSize.Size1024
];

type RenditionSizeEntry = {
    type: string;
    url: string;
    size: number;
    status: RenditionStatus;
    versionToken: string; //Either an etag or a rendition url (in the case of Library element renditions)
}

export class RenditionFetcher extends TypedEventEmitter<ItemBaseEvents>  {
    private _entries: RenditionSizeEntry[] = [];
    private _versionToken: string = '';

    constructor(
        readonly _core: ISAMCorePrivate,
        private _availableSizes: number[],
        private _fetchRenditionBlob: (size: number, mediaType: string) => Promise<Blob>
    ) {
        super();
    }

    /**
     * Given any number, this method will return a predefined
     * size that is greater than or equal to the target size.
     * You may also specify an existing sizes array.
     *
     * @param targetSize The preferred or target size.
     * @param sizes An array of sizes to sort and find.
     * @returns
     */
    private _getStandardSize(targetSize: number, sizes: number[] = this._availableSizes) {
        // Clone the provided array so we don't alter it.
        const sortedArray = [ ...sizes ].sort((a, b) => a - b);
        const index = sortedArray.findIndex((s) => s >= targetSize);

        // If no sizes are large enough, return the largest
        if (index === -1) {
            return sortedArray[sortedArray.length - 1];
        }

        return sortedArray[index];
    }

    private _findURLEntry(size: number, type: string): RenditionSizeEntry | undefined {
        const clampedSize = this._getStandardSize(size);
        if (this._entries.length > 0) {
            return this._entries.find((u) => u.size === clampedSize && u.type === type && u.status !== RenditionStatus.Error);
        }
        return undefined;
    }

    /**
     * Removes all entries matching the provided outdated
     * versionToken.
     *
     * @param outdatedVersionToken
     */
    private _clearStaleEntries(outdatedVersionToken: string) {
        const filteredEntries = this._entries.filter((entry) => {
            if (entry.versionToken === outdatedVersionToken) {
                URL.revokeObjectURL(entry.url);
                return false;
            }
            return true;
        });
        this._entries = filteredEntries;
    }

    /**
     * Finds an entry based on the provided size/type and returns
     * a fallback size that is greater than the target, if available.
     *
     * @param size
     * @param type
     * @returns {IURLEntry}
     */
    private _getEntryWithFallback(size: number, type: string): RenditionSizeEntry | undefined {
        const foundEntry = this._findURLEntry(size, type);
        if (foundEntry) {
            return foundEntry;
        }

        // If the exact size is not available and there
        // are other sizes and types, return the size
        // that is at-least greater than or equal to the current size.
        const sizesArray =  this._entries.map((entry) => entry.size);
        if (this._entries.length > 0) {
            // Since we are passing in our own sizes array
            // this should return the closest size already
            // available.
            const foundSize = this._getStandardSize(size, sizesArray);
            return this._entries.find(s => s.size === foundSize);
        }
        return undefined;
    }

    /**
     * Returns the download status of the requested rendition.
     *
     * @param size
     * @param type
     * @param versionToken // Either an etag or a rendition url (in the case of Library element renditions)
     * @returns
     */
    public renditionURLStatus(size: number, type: string, versionToken: string): RenditionStatus {
        const clampedSize = this._getStandardSize(size);
        const urlStatus = this._entries.find(
            e => e.versionToken === versionToken
            && e.size >= clampedSize
            && e.type === type
        );
        return (urlStatus && urlStatus.status) ?? RenditionStatus.NotStarted;
    }

    public get versionToken(): string {
        return this._versionToken;
    }

    /**
     *
     * @param size Target size for the rendition
     * @param type String type for example image/png.
     * @param versionToken Either an etag or a rendition url (in the case of Library element renditions)
     * @returns {string} The URL for the rendition.
     */
    public getURL(
        size: number,
        type: string,
        versionToken: string
    ): string {
        const versionTokenChanged = versionToken !== this.versionToken;
        const renditionEntry = this._getEntryWithFallback(size, type);
        const clampedSize = this._getStandardSize(size);

        // If we do have a rendition wether it be exact or a fallback
        // we could return it but if the requested size is larger
        // than the one we have in the cache we will need to add a new entry
        // and start fetching.
        if (renditionEntry && renditionEntry.size >= clampedSize && !versionTokenChanged) {
            return renditionEntry.url;
        }

        const newEntry = {
            size: clampedSize,
            status: RenditionStatus.Fetching,
            url: '',
            type,
            versionToken
        };

        // If we find an existing entry that exactly matches our new
        // entry then we wont need to fetch again.
        const recentlyAddedEntry = this._entries.find(e =>
            isDeepEqual(e, newEntry)
            // We also want to check if there is an identical entry
            // but with an error so that we don't keep fetching over and
            // over again in case of a thumbnail fetching error.
            || isDeepEqual(e, { ...newEntry, status: RenditionStatus.Error })
        );

        // If we know we have an existing entry and we have
        // a new entry that was recently added but it's state
        // is loading then we need to just return the existing url
        // until this is no longer true.
        // @note Without this logic, the ui will go into an infinite
        // loop causing the browser to crash because we are fetching
        // and pushing change notifications over and over again.
        if (renditionEntry && recentlyAddedEntry) {
            return renditionEntry.url;
        }

        this._entries.push(newEntry);

        this._fetch(
            newEntry
        );

        // If we have a rendition entry after starting to fetch
        // it means that we have a new size requested with a fallback.
        // Return the fallback while the new size is fetching.
        if (renditionEntry) {
            return renditionEntry.url;
        }

        // If the versionToken hasn't changed and we have an entry we should
        // return the existing entry while waiting for the new one.
        return newEntry.url;
    }

    // First we find if there is an existing entry
    // then if there isn't, we create one
    // if there is, we update the existing entry
    private async _fetch(
        entry: RenditionSizeEntry
    ): Promise<void> {
        const { size, type, versionToken } = entry;

        this.dispatch({ type: 'change' });

        // We want to fetch the URL contents and create an objectURL and return the path
        // to clients instead of the raw URL because services in future will not
        // allow the authorization token to be passed directly in the rendition URL
        try {
            const renditionBlob = await this._fetchRenditionBlob(size, type);

            // If there is a new versionToken all the old URLS that are now
            // out of date so let's remove the existing ones.
            if (versionToken && versionToken !== this._versionToken) {
                this._clearStaleEntries(this._versionToken);
                this._versionToken = versionToken;
            }

            entry.size = size;
            entry.type = type;
            entry.url = URL.createObjectURL(renditionBlob);
            finalizationRegistry.register(this, entry.url, entry);
            entry.status = RenditionStatus.Done;
            entry.versionToken = versionToken;

            this.dispatch({ type: 'change' });
        } catch (e) {
            // IF there was an error fetching the thumbnail, we don't
            // want clients stuck in a bad state so we set the rendition
            // to an error dispatch a change event.
            entry.status = RenditionStatus.Error;
            this.dispatch({ type: 'change' });
        }

    }

    /**
     * Resets the rendition status on the requested rendition to RenditionStatus.NotStarted
     */
    public clearRenditionError(size: number, type: string, versionToken: string): void {
        const clampedSize = this._getStandardSize(size);
        // Find an entry that has all the properties
        // of the request one including the error status.
        // Leaving out the URL case if for some reason it has a value
        // but we still want to reset the error.
        const foundErrorEntryIndex = this._entries.findIndex(e =>
            e.size >= clampedSize
            && e.type === type
            && e.versionToken === versionToken
            && e.status === RenditionStatus.Error
        );

        if (foundErrorEntryIndex === -1) {
            return;
        }

        // Remove the entry so that when getURL is called again
        // it will add a new entry and begin the fetch process
        // again.
        this._entries.splice(foundErrorEntryIndex, 1);
        this.dispatch({ type: 'change' });
    }

    public release(): void {
        if (this._entries.length === 0) {
            return;
        }

        this._entries.forEach((value) => {
            URL.revokeObjectURL(value.url);
            finalizationRegistry.unregister(this);
        });
        this._entries = [];
    }
}
