import type { UploadedFromType } from '../assets/USSAdobeAssetFilter';
import { getUSSFetchFields } from './AssetModel';
import InterfaceBase from './InterfaceBase';
import type { ISearchQuery, USSResponse, IOpOr } from './USSModel';
import { SearchProps, LastAccessedOrderField } from './USSModel';
import {
    updateAssetTypeForUSS
} from './USSUtils';
import { excludeExpressArtifacts } from '../utils/excludeExpressArtifacts';

type IPageOptions = {
    limit: number;
    start?: number;
}

interface IListingOptions extends IPageOptions {}

export interface RecentAssetsListingOptions extends IListingOptions {
    mediaTypes?: string[],
    excludeMediaTypes?: string[],
    embedPermissions?: boolean,
    uploadedFrom?: UploadedFromType;
    userId?: string;
}

const DefaultRecentAssetsListingOptions: RecentAssetsListingOptions = {
    start: 0,
    limit: 0,
    mediaTypes: [],
    excludeMediaTypes: [],
};

export default class RecentInterface extends InterfaceBase {

    private _getCommonFilters(options?: Partial<RecentAssetsListingOptions>): ISearchQuery {
        options = { ...DefaultRecentAssetsListingOptions, ...options };
        const { uploadedFrom } = options ?? {};
        updateAssetTypeForUSS(options.mediaTypes);
        updateAssetTypeForUSS(options.excludeMediaTypes);
        // Folders should never be included in Recents listing
        options.excludeMediaTypes = Array.from(
            new Set([ 'application/x-sharedcloud-collection+json', ...(options.excludeMediaTypes || []) ])
        );
        const filters: ISearchQuery = {
            hints: {
                acp_platform_v2: true,
            },
            fetch_fields: { includes: getUSSFetchFields() },
            sort_order: 'desc',
            limit: options.limit,
            start_index: options.start,
            [SearchProps.TYPE]: options.mediaTypes || [],
            op_none_of: [
                {
                    [SearchProps.FIELD_EXISTS]: [
                        // for excluding the older spaces and its children
                        'app_metadata$$cc:inheritable$$cc:space$$repo:assetId',
                        'app_metadata$$cc:inherited$$cc:space$$repo:assetId',
                        // for excluding only the projects
                        'app_metadata$$cc:inheritable$$cc:team$$repo:assetId',
                    ],
                },
                {
                    [SearchProps.VISIBILITY]: [ 'hiddenSelf', 'hiddenRecursive' ],
                },
                {
                    [SearchProps.CREATIVE_CLOUD_TOPLEVEL_COLLECTION_NAME]: [ 'appdata' ],
                },
                {
                    [SearchProps.TYPE]: options.excludeMediaTypes || [],
                },
                {
                    // For excluding legacy artifacts.
                    [SearchProps.CREATIVE_CLOUD_TOPLEVEL_COLLECTION_NAME]: 'pubs'
                },
                {
                    // For excluding more modern artifacts.
                    [SearchProps.OP_AND]: [
                        {
                            [SearchProps.CREATIVE_CLOUD_TOPLEVEL_COLLECTION_NAME]: 'cloud-content'
                        },
                        {
                            [SearchProps.FIELD_EXISTS]: [ 'app_metadata$$review:sourceAsset$$dc:format' ]
                        }
                    ],
                },
                // SAMJS-773
                ...excludeExpressArtifacts()
            ],
        };

        if (options.embedPermissions) {
            filters.fetch_fields!.includes.push('_embedded');
        }

        if (uploadedFrom) {
            filters.op_and = [];
            filters.op_and.push({
                [SearchProps.CREATED_FROM_UPLOAD]: true
            });
        }

        if (uploadedFrom && Array.isArray(uploadedFrom)) {
            const length = filters.op_and!.push({
                [SearchProps.OP_OR]: []
            });
            uploadedFrom.forEach((value: string) => {
                const filter = filters.op_and![length - 1] as IOpOr;
                filter[SearchProps.OP_OR].push(
                    {
                        [SearchProps.CREATED_BY_CLIENT_ID]: value
                    }
                );
            });
        }

        if (uploadedFrom && !Array.isArray(uploadedFrom) && uploadedFrom !== 'ALL') {
            filters.op_and!.push({
                [SearchProps.CREATED_BY_CLIENT_ID]: uploadedFrom
            });
        }

        return filters;
    }

    async getRecentAssets(options?: Partial<RecentAssetsListingOptions>): Promise<USSResponse> {
        const filters = this._getCommonFilters(options);
        const { userId } = options ?? {};
        // should not give order given by client in this request
        // because Recent assets mean descending direction of modified date
        filters.sort_orderby = 'modify_date';
        const storageAssigneeQuery = {
            [SearchProps.STORAGE_ASSIGNEE_ID]: userId ?? this._core._environment.getValue('USER_ID')
        };

        // If the userId is present we want to add this to the and
        // operation of the query.
        if (userId) {
            if (!filters.op_and) {
                filters.op_and = [];
            }
            filters.op_and.push(storageAssigneeQuery);
        } else {
            // If the userId is present then we don't want to include the
            // SHARED_VIA_INVITED as well since that will include results that are not
            // equal to the userId provided.

            if (!filters.op_or) {
                filters.op_or = [];
            }

            filters.op_or.push(storageAssigneeQuery);
            filters.op_or.push({
                [SearchProps.SHARED_VIA_INVITE]: true
            });
        }

        const response = await this._core.hostAssetContext._ussInterface.getQueryResponse(filters);
        return response;
    }

    async getMRUAssets(options?: Partial<RecentAssetsListingOptions>): Promise<USSResponse> {
        const filters = this._getCommonFilters(options);
        filters.fetch_fields!.includes.push(LastAccessedOrderField);
        const { userId } = options ?? {};

        if (userId) {
            if (!filters.op_and) {
                filters.op_and = [];
            }

            filters.op_and.push({
                [SearchProps.STORAGE_ASSIGNEE_ID]: userId
            });
        }

        // should not give order given by client in this request
        // because Recent assets mean descending direction of last accessed date
        filters.sort_orderby = LastAccessedOrderField;
        filters.op_field_exists = [ LastAccessedOrderField ];
        const response = await this._core.hostAssetContext._ussInterface.getQueryResponse(filters);
        return response;
    }
}
