import { RelType } from '../interface/LinkUtils';
import type AdobeAsset from './AdobeAsset';
import type { ISAMCorePrivate } from '../indexPrivate';
import type { RepositoryMetadata } from '../interface/RepositoryModel';
import AdobeAssetResource from './AdobeAssetResource';

export default class RepoMetadataResource extends AdobeAssetResource<RepositoryMetadata> {

    constructor(
        readonly _core: ISAMCorePrivate,
        _parent?: AdobeAsset,
    ) {
        super(_core, _parent, {
            onChange: async (repoMetadata, { timestamp } = {}) => {
                if (repoMetadata) {
                    try {
                        const assetId = repoMetadata['repo:assetId'];
                        const links = repoMetadata._links;
                        const etag = repoMetadata['repo:etag'];
                        // Update the persistent cache with the updated links (by ID, because paths change)
                        const resolveHref = this._core.hostAssetContext._rapi.getAssetResolveByIdHref(assetId);
                        await this._core._environment.cache.setItem(resolveHref, { links, etag });
                    } catch (e) {
                        // it is not a failure if we're unable to update the persistent cache
                    }
                }
                await this._parent?._handleResourceUpdates({ timestamp, repoMetadata });
            },
            onError: async (error) => {
                await this._parent?._handleResourceUpdates({ error });
            }
        });
    }

    protected async _loadData() {
        await this._parent?._ensureLink(RelType.REPO_METADATA);
        const assetInterface = await this._parent?._getAssetInterface();
        await assetInterface?.getRepoMetadata(this);
    }
}
