import type CustomModelInterface from '../interface/CustomModelInterface';
import type ItemPool from '../core/ItemPool';
import type { ISAMCorePrivate } from '../indexPrivate';
import type { AdobeAsset, IItemSourceConfig } from 'src';
import type {
    IItemLoader,
    IItemLoaderOptions,
    ILoadNextPage,
    ILoadedPage,
} from '../core/ItemLoader';
import type CustomModel from '../custom-models/CustomModel';
import { CustomModelUpdaterMelville } from '../custom-models/CustomModel';
import CustomModelOrder from './CustomModelOrder';
import { OrderFieldToCustomModelOrderBy } from './CustomModelOrder';
import type { MelvilleLink } from '../interface/LibraryModel';
import type {
    CustomModelsResponseMelville,
    MelvilleCustomModelListParameters,
} from '../interface/CustomModelModel';
import type CustomModelFilter from '@sam-js-src/custom-models/CustomModelFilter';
import { getMostRecentValidMutation } from '../utils/loaderUtils';

export default class CustomModelLoader<Config extends IItemSourceConfig>
implements IItemLoader<Config> {
    constructor(
        private _assetPool: ItemPool<CustomModel | AdobeAsset>,
        private _core: ISAMCorePrivate,
        private _customModelInterface: CustomModelInterface
    ) {}

    async loadPage(options: IItemLoaderOptions<Config>) {
        return await this._loadPage(options);
    }

    private async _loadPage(
        options: IItemLoaderOptions<Config>,
        pageLink?: MelvilleLink
    ): Promise<ILoadedPage<Config>> {
        let result: CustomModelsResponseMelville;

        const { order, limit, filter } = options;
        const queryParams: MelvilleCustomModelListParameters = {};
        const effectiveOrder = order || CustomModelOrder.default;
        const field = (effectiveOrder as CustomModelOrder).field;
        queryParams.orderBy = effectiveOrder.direction === 'ascending'
            ? OrderFieldToCustomModelOrderBy[field]
            : `-${OrderFieldToCustomModelOrderBy[field]}`;

        if (limit) {
            queryParams.limit = limit;
            if (!queryParams.start) {
                queryParams.start = 0;
            }
        }

        const listingOptions = (filter as CustomModelFilter)?.listingOptions;

        const body: Record<string, any> = listingOptions ? { ...listingOptions } : {};
        // Map external field names to internal API names
        if (body.createDateMin) {
            body.createdDateMin = body.createDateMin.getTime();
            delete body.createDateMin;
        }
        if (body.createDateMax) {
            body.createdDateMax = body.createDateMax.getTime();
            delete body.createDateMax;
        }
        if (body.modifyDateMin) {
            body.modifiedDateMin = body.modifyDateMin.getTime();
            delete body.modifyDateMin;
        }
        if (body.modifyDateMax) {
            body.modifiedDateMax = body.modifyDateMax.getTime();
            delete body.modifyDateMax;
        }

        if (pageLink) {
            result = await this._customModelInterface.searchCustomModelsUsingPageLink(body, pageLink);
        } else {
            result = await this._customModelInterface.searchCustomModels(queryParams, body);
        }

        const latency = this._core._environment.getValue('USS_LIST_UPDATE_LATENCY');
        const mostRecentValidMutation = getMostRecentValidMutation(options.resource, latency);
        const session = this._assetPool.createLoaderUpdateSession<CustomModel>(mostRecentValidMutation);
        const items = CustomModelUpdaterMelville.updateRemoteItems(session, result.custom_models);
        session.commit();

        let loadNextPage: ILoadNextPage<Config> | undefined;
        const nextPageLink = result._links?.next;
        if (nextPageLink) {
            loadNextPage = (nextOptions: IItemLoaderOptions<Config>) =>
                this._loadPage(nextOptions, nextPageLink);
        }

        return {
            items,
            total: result.total_count,
            loadNextPage,
            mostRecentValidMutation
        };
    }
}
