import type { SAM } from '@ccx-public/component-types';
import type {
    LegacyCustomModelConfig, LegacyCustomModelSearchConfig, LegacyCustomModelSearchSource,
    LegacyCustomModelSource,
} from './LegacyCustomModelSource';
import { memoize } from '../../core/decorators';
import type AdobeAsset from '../../assets/AdobeAsset';
import type ItemPool from '../../core/ItemPool';
import type { ISAMCorePrivate, ISAMObject } from '../../indexPrivate';
import ItemSource from '../../core/ItemSource';
import LegacyCustomModelLoader from './LegacyCustomModelLoader';
import LegacyCustomModelInterface from './LegacyCustomModelInterface';
import type LegacyCustomModel from './LegacyCustomModel';
import { LegacyCustomModelUpdater } from './LegacyCustomModel';
import LegacyCustomModelSearchLoader from './LegacyCustomModelSearchLoader';
import LegacyCustomModelSearchFilter from './LegacyCustomModelSearchFilter';
import LegacyImplicitCustomModelFilter from './LegacyImplicitCustomModelFilter';
import type Library from '../../libraries/Library';
import { LibraryUpdater } from '../../libraries/Library';
import type { LibraryConfig, LibrarySource } from '../../libraries/LibrarySource';
import LibraryInterface from '../../interface/LibraryInterface';
import LibraryListLoader from '../../libraries/LibraryListLoader';
import ImplicitLibraryFilter from '../../libraries/ImplicitLibraryFilter';
import type { LegacyCustomModelCreateOptions, CustomModelsMelvilleResponse, LegacyCreateTrainingSetOptions } from './LegacyCustomModelModel';
import type { IOrderDirection } from '../../core/ItemOrder';
import { default as LegacyCustomModelOrder,  type CustomModelOrderField } from './LegacyCustomModelOrder';
import { default as LegacyCustomModelFilter, type ICustomModelListingOptions } from './LegacyCustomModelFilter';


/**
 * Provides Custom Model functionality such as listing.
 *
 * @experimental This API is in an experimental phase so expect that
 * API's will not be final and there will be breaking changes
 * without bumping the major version until this comment is removed.
 */
export default class LegacyCustomModelContext implements ISAMObject, SAM.LegacyCustomModelContext {
    readonly _customModelInterface = new LegacyCustomModelInterface(this._core);

    constructor(
        /**
         * @package -- for use in SAM.js only
         */
        readonly _core: ISAMCorePrivate,
        /**
         * @package -- for use in SAM.js only
         */
        readonly _assetPool: ItemPool<LegacyCustomModel | AdobeAsset>
    ) {}

    /**
     * @experimental
     */
    getCustomModelOrder(direction: IOrderDirection = 'descending', field: CustomModelOrderField = 'modified'): LegacyCustomModelOrder {
        return new LegacyCustomModelOrder(direction, field);
    }

    /**
     * @experimental
     */
    getCustomModelFilter(options?: Partial<ICustomModelListingOptions | undefined>): LegacyCustomModelFilter {
        return new LegacyCustomModelFilter(options);
    }

    /**
     * @package -- only for use in SAM.js
     * Updaters shouldn't be accessed directly.
     */
    readonly _customModelUpdater =  LegacyCustomModelUpdater;

    /**
     * @package -- only for use in SAM.js
     */
    private readonly _libraryInterface: LibraryInterface = new LibraryInterface(this._core);

    /**
   * @example
   * const customModelContext = samCore.customModelContext;
   * const customModelSource = customModelContext.customModelSearchSource;
   *
   * Search custom models a user has access to by name. The set of assets returned in a list is static once the
   * search is executed - ie newly created items which fit a list will not be added, edits to items which qualify
   * them to be part of a list will not have any effect. However, discard/delete/permission loss will still be
   * reflected.
   */
    customModelSearchSource(query: string): LegacyCustomModelSearchSource {
        // declare an implicitFilter
        const implicitFilter = new LegacyCustomModelSearchFilter({ query });

        // declare a CustomModelSearchLoader
        return new ItemSource<LegacyCustomModelSearchConfig>(
            this._assetPool as ItemPool<LegacyCustomModel>,
            [
                new LegacyCustomModelSearchLoader(
                    this._assetPool,
                    this._core,
                    this._customModelInterface
                ),
            ],
            implicitFilter
        );
    }

    /**
   * @example
   * const customModelContext = samCore.customModelContext;
   * const customModelSource = customModelContext.customModelSource;
   *
   * Gets all custom models a user has access to
   */
    @memoize
    get customModelSource(): LegacyCustomModelSource {
        return new ItemSource<LegacyCustomModelConfig>(
            this._assetPool as ItemPool<LegacyCustomModel>,
            [
                new LegacyCustomModelLoader(
                    this._assetPool,
                    this._core,
                    this._customModelInterface
                ),
            ],
            new LegacyImplicitCustomModelFilter()
        );
    }

    async createTrainingSet(options: LegacyCreateTrainingSetOptions): Promise<Library> {
        return this._customModelInterface.createTrainingSet(options);
    }

    /**
     * Returns the `TrainingSetSource` which will return a list of training set libraries the user has access to.
     * @example
     * const context = await core.getCustomModelContext();
     * const order = new LibraryOrder('ascending', 'modified');
     * const filter = TrainingSetFilter.DEFAULT;
     * const list = await context.trainingSetsSource().getList(order, filter, loadOptions);
     * list.on(STATE_CHANGED, () => {
     *     if (list.status !== AssetListStatus.Loading) { const trainingSets = list.items; }
     * });
     */
    @memoize
    async trainingSetsSource(): Promise<LibrarySource> {
        const libraryContext = await this._core.getLibraryContext();
        const loader = new LibraryListLoader<LibraryConfig>(
            libraryContext._assetPool,
            this._libraryInterface,
            LibraryUpdater,
            this._core
        );
        return new ItemSource<LibraryConfig>(libraryContext._assetPool as ItemPool<Library>, [ loader ], ImplicitLibraryFilter.TrainingSets);
    }

    /* We need to always fetch remotely because local training sets might have been populated by a melville listing,
     * and those training sets don't have custom model data.
     */
    async getTrainingSetById(assetId: string): Promise<Library | undefined> {
        return this._customModelInterface.getTrainingSetById(assetId);
    }

    async createCustomModel(options: LegacyCustomModelCreateOptions): Promise<CustomModelsMelvilleResponse> {
        return this._customModelInterface.createCustomModel(options);
    }
}
