import type { MelvilleLinks } from './LibraryModel';
import type { RelType } from './LinkUtils';
import { SAM } from '@ccx-public/component-types';

export const FIREFLY_GENERATIONS_DIRECTORY = 'appassets/firefly-generations';

export const GENERATION_HISTORY_IMAGE_MEDIA_TYPE = 'application/vnd.adobe.firefly-generation-image+dcx';
export const GENERATION_HISTORY_VIDEO_MEDIA_TYPE = 'application/vnd.adobe.firefly-generation-video+dcx';
export const GENERATION_HISTORY_AUDIO_MEDIA_TYPE = 'application/vnd.adobe.firefly-generation-audio+dcx';
export const GENERATION_HISTORY_VECTOR_MEDIA_TYPE = 'application/vnd.adobe.firefly-generation-vector+dcx';
export const GENERATION_HISTORY_MEDIA_TYPES = [ GENERATION_HISTORY_IMAGE_MEDIA_TYPE, GENERATION_HISTORY_VIDEO_MEDIA_TYPE, GENERATION_HISTORY_AUDIO_MEDIA_TYPE, GENERATION_HISTORY_VECTOR_MEDIA_TYPE ];

export const MEDIA_TO_HISTORY_ASSET_TYPE: Record<string, SAM.GenerationHistoryAssetType> = {
    'application/vnd.adobe.firefly-generation-image+dcx': SAM.GenerationHistoryAssetType.IMAGE,
    'application/vnd.adobe.firefly-generation-video+dcx': SAM.GenerationHistoryAssetType.VIDEO,
    'application/vnd.adobe.firefly-generation-audio+dcx': SAM.GenerationHistoryAssetType.AUDIO,
    'application/vnd.adobe.firefly-generation-vector+dcx': SAM.GenerationHistoryAssetType.VECTOR
} as const;

export const HISTORY_ASSET_TYPE_TO_MEDIA_TYPE: Record<SAM.GenerationHistoryAssetType, string> = {
    [SAM.GenerationHistoryAssetType.IMAGE]: GENERATION_HISTORY_IMAGE_MEDIA_TYPE,
    [SAM.GenerationHistoryAssetType.VIDEO]: GENERATION_HISTORY_VIDEO_MEDIA_TYPE,
    [SAM.GenerationHistoryAssetType.AUDIO]: GENERATION_HISTORY_AUDIO_MEDIA_TYPE,
    [SAM.GenerationHistoryAssetType.VECTOR]: GENERATION_HISTORY_VECTOR_MEDIA_TYPE
} as const;

export type GenerationHistoryAssetStatusLinks = {
    [RelType.MELVILLE_FIREFLY_GENERATION_CANCEL]: string;
    [RelType.MELVILLE_FIREFLY_GENERATION_RESULT]?: string;
}

type MelvilleOrderBy = 'created_date' | '-created_date';

export type MelvilleGenerationHistoryAssetsParams = {
    generationGroupId?: string;
    generationType?: string;
    module?: SAM.GenerationHistoryModule;
    start?: number;
    limit?: number;
    orderBy?: MelvilleOrderBy;
}

// TODO: PR in progress to introspect types from graphql server, when that is merged we won't need the below typedef
type AssetLabel = {
    isFavorite: boolean;
}

export type MelvilleGenerationHistoryAssetInfo = {
    type: (typeof GENERATION_HISTORY_MEDIA_TYPES)[number];
    'repo:createdBy': string;
    'repo:modifiedBy': string;
    'repo:name': string;
    'repo:size': number;
    'repo:repositoryId': string;
    asset_id: string;
    createdDate: string;
    modifiedDate: string;
    composite_manifest_etag: string;
    asset_name_path: string;
    generationModelDisplayName: string;
    _links: MelvilleLinks;
    applicationMetadata: {
        firefly: {
            module: string;
            prompt?: string;
            generationGroupId?: string;
            generationModel?: {
                name: string;
                customModelId?: string;
                version: string;
                detailLevel?: 'preview' | 'full';
                apiPath?: string;
            }
            outputComponents: Array<{
                type: string;
                componentId: string;
                revision: string;
                length: number;
                seed: number;
                rel: string;
            }>
            status: {
                errorCode?: string;
                errorMessage?: string;
                jobId?: string;
                progress?: number;
                state: SAM.GenerationHistoryAssetState;
                links?: GenerationHistoryAssetStatusLinks;
            }
        }
    }
}

export type GenerationHistoryAssetData = AssetLabel & MelvilleGenerationHistoryAssetInfo;

export type GenerationHistoryAssetAppMetadata = GenerationHistoryAssetData['applicationMetadata'] | undefined;

export type MelvilleGenerationHistoryAssetsResponse = {
    total_count: number;
    listings: GenerationHistoryAssetData[];
    _links: any
}
