import { default as uuid } from './uuid';
import SAMEvent from './SAMEvent';

import type ItemBase from './ItemBase';
import type { ItemId } from './ItemBase';
import type { IItemLoader } from './ItemLoader';
import type { IExplicitFilter, IImplicitFilter } from './ItemFilter';
import { getFiltersRelation } from './ItemFilter';
import type { IItemPoolDelegate, ItemsChangedEvent, ItemType } from './ItemPool';
import type ItemPool from './ItemPool';
import type { ItemLoaderRefreshNeededEvent, ItemLoaderStateChangeEvent } from './ItemLoaderState';
import ItemLoaderState, { AssetListStatus, LOADER_REFRESH_NEEDED, LOADER_STATE_CHANGED } from './ItemLoaderState';
import { observable } from './decorators';
import type { IEventMap } from './ITypedEventEmitter';
import type ITypedEventEmitter from './ITypedEventEmitter';
import TypedEventEmitter from './TypedEventEmitter';
import type { IItemOrder } from './ItemOrder';
import type { ISAMCorePrivate } from '../indexPrivate';
import { ItemListStateChangedEvent } from '../indexPrivate';
import oneTimeWarning from '../utils/oneTimeWarning';
import EverythingFilter from './EverythingFilter';
import SAMError, { SAMErrorCode } from './SAMError';

// STATE_CHANGED must be a different than the SAM.cpp equivalent so that patchAssetList can throttle
// the SAM.cpp notifications, and map the SAM.js event listeners to the throttled pseudo-events.
export const STATE_CHANGED = 'status_changed';
export const LIST_CHANGED = 'listChanged';
// NOTE: listFullyLoaded should only be fired when its loaders completed a page and no more pages are available.
//       It should *not* be fired for any other reason that list status changes to ReadyFullyLoaded.
export const LIST_FULLY_LOADED = 'listFullyLoaded';

// For identifying updates of ItemList that originate from ItemLoaders. ONLY ItemLoaders should
// use this updateContext.
export const LOADER_UPDATE_CONTEXT = 'LoaderUpdateContext';

export class StateChangedEvent extends SAMEvent {
    constructor() {
        super(STATE_CHANGED);
    }
}

export class ListChangedEvent extends SAMEvent {
    constructor() {
        super(LIST_CHANGED);
    }
}

export const SharedListChangedEvent = new ListChangedEvent();
export const SharedStateChangedEvent = new StateChangedEvent();

interface IItemListEventMap extends IEventMap {
    [STATE_CHANGED]: StateChangedEvent,
    [LIST_CHANGED]: ListChangedEvent
}

export interface IItemSourceConfig<
    LocalType extends ItemBase = ItemBase,
    ItemOrder extends IItemOrder<LocalType> = IItemOrder<LocalType>,
    ImplicitItemFilter extends IImplicitFilter<LocalType> = IImplicitFilter<LocalType>,
    ExplicitItemFilter extends IExplicitFilter<LocalType> = IExplicitFilter<LocalType>> {
    type: LocalType;
    order: ItemOrder;
    implicitFilter: ImplicitItemFilter;
    filter: ExplicitItemFilter;
}

export interface ILoadOptions {
    loadAllPages?: boolean;
    /**
     * Number of milliseconds past the last fetch where a refresh will be required.
     * Note: Zero/undefined will force immediate refresh.
     * Note: -1 will never force a refresh
     */
    refreshTimeout?: number;
    limit?: number;
}

export interface IItemListBase extends ITypedEventEmitter<IItemListEventMap> {
    readonly type: ItemType;
    readonly status: AssetListStatus;
    readonly total: number | undefined;
    readonly errors?: any[];
    readonly generation: number;
    readonly completedGeneration: number;
    readonly hasLoaders: boolean;
    readonly lastFetchTime: number;

    /**
     * Triggers the refresh of the items in the list.
     *
     * If the list already contains items from a previous load, the refresh
     * doesn't throw away all the items immediately. It will refresh
     * all preloaded pages one by one. The pages that were already loaded
     * will be preserved until they had a chance to refresh.
     */
    refresh(): void;

    /**
     * If the initial `load` was started without using the `loadAllPages = true` option,
     * this method allows the client to grab more items from the loaders as soon as more
     * items are necessary.
     *
     * Note that calling this method again while the current page is still loading will
     * not queue more pages.
     */
    loadNextPage(loadOptions?: ILoadOptions): void;

    /**
     * Make the list automatically update itself.
     */
    setNeedsRefresh(): void;
}

export interface IItemList<ItemConfig extends IItemSourceConfig> extends IItemListBase {
    readonly order: ItemConfig['order'];
    readonly filter: ItemConfig['filter'];
    readonly implicitFilter: ItemConfig['implicitFilter'];
    readonly items: ItemConfig['type'][];
}

interface IPendingNotification<LocalType extends ItemBase> {
    generation: number;
    event: ItemsChangedEvent<LocalType>;
}

type ItemGeneration<LocalType extends ItemBase> = Map<LocalType, boolean>;

let GlobalGeneration = 0;

/**
 * Make sure we can sort lists based on how recent they've
 * started their server load. The more recent loads will have higher
 * priority over lists that have not been updated in a while.
 */
function allocGenerationIndex(): number {
    return ++GlobalGeneration;
}

interface IPendingLoad {
    loadOptions?: ILoadOptions;
    promise: Promise<void>;
    revalidateAtPage: number;
    invalidateCache?: boolean;
}

export default class ItemList<ItemConfig extends IItemSourceConfig, IdType extends ItemId = ItemId> extends TypedEventEmitter<IItemListEventMap> implements IItemList<ItemConfig> {

    private _status: AssetListStatus = AssetListStatus.NotStarted;
    private _errors: any;
    private _items: ItemConfig['type'][] = [];
    private _total: number | undefined;

    // Every time we refresh the list we increment the generation. This is used
    // to make sure that older lists are updated once the new pages are loaded.
    private _generation: number = 0;
    private _completedGeneration: number = 0;

    private _loaderStates: ItemLoaderState<ItemConfig>[] = [];

    private _lastFetchTime: number = 0;
    private _previousLoadPromise: Promise<any> | undefined;
    private _needsRefresh: boolean = false;
    private _invalidateCacheForNextLoad: boolean = false;
    private _pendingLoad: IPendingLoad | undefined;

    // We will have to keep the client side items around until we fully fetch again the entire list.
    // Example: We fetched the latest favorite spaces for the sidebar. Then we add a new space and make it favorite.
    // The new space will be added to the list automatically without doing another fetch from the server.
    // This list will refresh in the background eventually. Once the fetch is complete (ie. all pages are loaded),
    // we can get rid of the assets added in the previous generation. At that point we can know for sure,
    // that the items added in the previous generation have already been captured in the new generation of loaded pages.
    // If an item is created after the load started, we have to keep it around until the next generation ends.
    // That's because the initial pages might have contained the item, but we've started the load too early and the
    // item might not be captured in the result yet.
    // NOTE: only external changes, such as ONS refreshes, should cause entries to be made in _itemUpdatesByGeneration.
    //       Changes from an ItemLoader loading a page should NOT be reflected here. To avoid that, ItemLoader should
    //       always use `createUpdateSession()` or `createMutationSession()` with an `updateContext`.
    private _itemUpdatesByGeneration = new Map<number, ItemGeneration<ItemConfig['type']>>();
    private _pendingNotifications?: IPendingNotification<ItemConfig['type']>[];
    private _listId: string = uuid();
    private _assetListId: string | undefined;

    constructor(
        private _itemPool: ItemPool<ItemConfig['type'], IdType>,
        loaders: IItemLoader<ItemConfig>[],
        readonly order: ItemConfig['order'],
        readonly implicitFilter: ItemConfig['implicitFilter'],
        readonly filter: ItemConfig['filter'] = new EverythingFilter(),
        similarItemList?: IItemList<ItemConfig>,
        private _loadOptions?: ILoadOptions
    ) {
        super();
        for (const loader of loaders) {
            if (loader.supportsFilter && !loader.supportsFilter(filter)) {
                // We don't want to use loaders that do not support the filters.
                // Otherwise, we are better off running this list entirely on the client side.
                // For example, the discarded items are better handled on the client for now.
                continue;
            }
            const state = new ItemLoaderState(this._core, loader, order, implicitFilter, filter);
            state.on(LOADER_STATE_CHANGED, this._onItemLoaderStateChanged);
            state.on(LOADER_REFRESH_NEEDED, this._onItemLoaderRefreshNeeded);
            this._loaderStates.push(state);
        }

        if (similarItemList) {
            this._copyInitialItemsFrom(similarItemList);
        }

        _itemPool.addDelegate(this._itemPoolDelegate, 'list');
    }

    private _debug(msg: string) {
        this._core._environment.debug(`[ItemList ${this._itemPool.type} ${this._listId.slice(-4)}] ${msg}`);
    }

    /**
     * When client calls `Source.getList()` and an existing List is returned, the existing List's
     * loadOptions might be different than the loadOptions that were requested. ItemSource calls
     * this method to allow some adjustments.
     *
     * @package -- only to be used internally by SAM.js
     */
    _updateLoadOptions(loadOptions: ILoadOptions = {}): void {
        if (!this._loadOptions) {
            this._loadOptions = {};
        }

        // Can only increase the limit if there is a limit set, otherwise keep the default limit
        // because it's not possible to tell if it is being increased or decreased since it could
        // be defined on the service and not anywhere in SAM.js.
        if (this._loadOptions.limit && loadOptions.limit && this._loadOptions.limit < loadOptions.limit) {
            this._loadOptions.limit = loadOptions.limit;
        }

        // Can turn on loadAllPages, but cannot turn it off
        if (!this._loadOptions.loadAllPages && loadOptions.loadAllPages) {
            this._loadOptions.loadAllPages = loadOptions.loadAllPages;
        }

        // It can only lower the refreshTimeout duration. Annoyingly, -1 means "infinite future", while 0 means "now".
        if (loadOptions.refreshTimeout !== -1
            && (this._loadOptions.refreshTimeout === -1
                || (this._loadOptions.refreshTimeout ?? 0) >= (loadOptions.refreshTimeout ?? 0))
        ) {
            this._loadOptions.refreshTimeout = loadOptions.refreshTimeout;
        }

        this._loadAsync({
            ...this._loadOptions,
            // if new refreshTimeout is -1, then it shouldn't refresh, but it can still turn on
            // loadAllPages, which might require loading more pages.
            refreshTimeout: loadOptions.refreshTimeout === -1 ? -1 : this._loadOptions.refreshTimeout
        }).catch(this._onUnhandledPromiseError);
    }

    get type(): ItemType {
        return this._itemPool.type;
    }

    get generation(): number {
        return this._generation;
    }

    get completedGeneration(): number {
        return this._completedGeneration;
    }

    get hasLoaders(): boolean {
        return this._loaderStates.length > 0;
    }

    get lastFetchTime(): number {
        return this._lastFetchTime;
    }

    get _core(): ISAMCorePrivate {
        return this._itemPool._core;
    }

    get assetListId(): string | undefined {
        return this._assetListId;
    }

    /**
     * In many cases the items already exist in a different list,
     * we just need to reorder the items or just apply a different filter.
     * In that case, we can bootstrap the list with items borrowed from a different
     * list until the items are refreshed in the background if necessary.
     * @package -- only for use in SAM.js
     * @param other
     */
    _copyInitialItemsFrom(other: IItemList<ItemConfig>): void {
        const itemGeneration: ItemGeneration<ItemConfig['type']> = new Map<ItemConfig['type'], boolean>();

        const filter = this.filter;

        for (const item of other.items) {
            if (this.implicitFilter.matches(item) && filter.matches(item)) {
                itemGeneration.set(item, true);
            }
        }

        // Inject the items as if they were just new items.
        // These items will be invalidated once the next generation loads,
        // which happened when `load()` finishes to load all pages.

        // This list starts with the items from a previously downloaded list,
        // so it inherits the generation from the other list too.
        this._generation = other.generation;
        this._completedGeneration = other.completedGeneration;

        this._itemUpdatesByGeneration.set(this._generation, itemGeneration);

        // Set the status to ready if other list is also set to ready and the other
        // list matches the filtering of this list.
        if (other.status === AssetListStatus.ReadyFullyLoaded && getFiltersRelation(filter, other.filter) === 'subset') {
            this._status = AssetListStatus.ReadyFullyLoaded;
            // SAM should copy the lastFetchTime from the other list as it is Fully loaded.
            // Essentially, the same items sorted in a different direction should be just as stale as the source list.
            this._lastFetchTime = other.lastFetchTime;
        }

        // Make sure we recompute the items once the user calls the `items` getter.
        this._updateListItemsFromItemLoaderStates();
    }

    /**
     * When a list completely loads, its items can be copied to other compatible lists. E.g., ListA and ListB have the
     * same filter and both are partially loaded. When ListA finishes loading, all of its items can be copied to
     * ListB, and ListB can be considered fully loaded.
     *
     * @package -- only for use in SAM.js
     */
    _applyListItemsFrom(other: IItemList<ItemConfig>): void {
        if (other.status !== AssetListStatus.ReadyFullyLoaded) {
            throw SAMError.create(SAMErrorCode.INTERNAL_ERROR, '_applyListItems other list must be fully loaded');
        }
        if (getFiltersRelation(this.filter, other.filter) !== 'subset') {
            throw SAMError.create(SAMErrorCode.INTERNAL_ERROR, '_applyListItems other list must be subset');
        }

        this._items = other.items.filter(item => this.implicitFilter.matches(item) && this.filter.matches(item));
        this.order.sortItems(this._items);
        this._dispatchItemsChangedEvent();
        if (this._status !== AssetListStatus.ReadyFullyLoaded) {
            this._status = AssetListStatus.ReadyFullyLoaded;
            this._dispatchStateChangedEvents();
        }
    }

    @observable(SharedStateChangedEvent)
    get status(): AssetListStatus {
        if (!this._loaderStates.length) {
            // If we don't have any loaders, we always use the in-memory data for this list.
            return AssetListStatus.ReadyFullyLoaded;
        }
        return this._status;
    }

    @observable(SharedStateChangedEvent)
    get errors(): any[] {
        return this._errors;
    }

    @observable(SharedListChangedEvent)
    get items(): ItemConfig['type'][] {
        return this._items;
    }

    @observable(SharedListChangedEvent)
    get total(): number | undefined {
        return this._total;
    }

    private _cleanPreviousGenerationItemsIfNeeded() {
        // Check if all loaders are fully loaded and trim our previous generations.
        let globalMostRecentValidMutation: number | undefined;

        for (const loader of this._loaderStates) {
            const { status, mostRecentValidMutation } = loader;
            if (status === AssetListStatus.NotStarted || loader.status === AssetListStatus.HadLoaderErrors) {
                // Ignore loaders that are not available.
                continue;
            }
            if (status === AssetListStatus.Loading || status === AssetListStatus.ReadyHasMorePages) {
                // We cannot trim any of the local items just yet. There are still more pages to load.
                return;
            }

            // This loader is ready to trim some pages.

            if (mostRecentValidMutation) {
                // We have to take the minimum timestamps of all the loaders.
                // If we have two loaders that have different latencies, then we have to keep items
                // in the list until the most latent on has a chance to validate our local changes.
                // The most recent mutations that we can eliminate from the local
                // list are the ones outside of any latency window. The minimum is the most recent
                // timestamp that is known to be valid across all loaders. Anything more recent than that
                // would remove changes that were not yet replicated on at least one of the loaders.
                globalMostRecentValidMutation = globalMostRecentValidMutation
                    ? Math.min(globalMostRecentValidMutation, mostRecentValidMutation)
                    : mostRecentValidMutation;
            }
        }

        // We've loaded the entire set of pages, we are now ready to
        // throw away the items that were added on the client side in
        // the previous generations. These items should have been
        // captured already by the new fetches from the server.
        this._cleanPreviousGenerationItems(globalMostRecentValidMutation);
    }


    /**
     * Removes items from the previous generations.
     */
    private _cleanPreviousGenerationItems(mostRecentValidMutation?: number): void {
        // Convert any pending events into actual maps to make the changes available below.
        this._applyItemsChangedEvents();

        const currentGeneration = this._generation;
        this._completedGeneration = currentGeneration;

        // Pick all items added in the previous generations. If these items were indeed added, the updated
        // lists should already contain the new items and we can go ahead and remove them from our in-memory store.
        // Note that we cannot remove items added in the current generation as those were added
        // after we've fetched the requests from the server and might not be up-to-date yet.
        const newState: ItemGeneration<ItemConfig['type']> = new Map<ItemConfig['type'], boolean>();

        let hadChanges = false;
        let mostRecentDeletedGeneration = 0;

        for (const [ key, generation ] of this._itemUpdatesByGeneration) {
            if (key >= currentGeneration) {
                continue;
            }
            // Deletes in JS Maps do not break the iterators, so it should be safe to delete generations while reading the map.
            hadChanges = true;
            this._itemUpdatesByGeneration.delete(key);
            mostRecentDeletedGeneration = Math.max(mostRecentDeletedGeneration, key);

            // If we have a most recent valid mutation timeframe, then we need to look for items that
            // might still be inside that update time window.
            if (mostRecentValidMutation) {
                // Consolidate all the pending changes into a single generation.
                for (const [ item, state ] of generation) {
                    const { lastKnownClientMutation } = item;
                    // If the item was already added to the list, then we have to keep updating its final state.
                    if (newState.has(item) || lastKnownClientMutation && lastKnownClientMutation > mostRecentValidMutation) {
                        // This item had a mutation too close to the last reload, so we cannot trust
                        // that the listing returns the most up-to-date values. We have to preserve the item state (added / deleted)
                        // until a future refresh.
                        newState.set(item, state);
                    }
                }
            }
        }

        if (newState.size) {
            // Inject the new state in place of the most recent deleted generation.
            this._itemUpdatesByGeneration.set(mostRecentDeletedGeneration, newState);
        }

        if (hadChanges) {
            // Let the clients know the list must be recomputed.
            this._dispatchItemsChangedEvent();
        }
    }

    refresh(): void {
        this._loadAsync(this._loadOptions).catch(this._onUnhandledPromiseError);
    }

    /**
     * @deprecated -- Use {@link ItemList.refresh} instead. Will be removed on or after 2024-10-01.
     */
    load(options?: ILoadOptions): void {
        oneTimeWarning('ItemList.load', 'ItemList.load() is deprecated and will be removed on or after'
            + ' 2024-10-01. Use ItemList.refresh() instead. List load parameters are passed as the 3rd parameter to'
            + ' ItemSource.getList(), which now automatically starts loading.');

        // Previously, `ItemList.load()` with no parameters would always refresh the list because it implied a default
        // value for `options.refreshTimeout` of `0` ("refresh now"). However, `_updateLoadOptions` assumes a
        // default value for `options.refreshTimeout` of `-1` ("never refresh"). For better backward-compatibility,
        // force a default for refreshTimeout of `0`. A defined value for refreshTimeout will override.
        options = { refreshTimeout: 0, ...options };
        this._updateLoadOptions(options);
    }

    // In case there is an error in load/loadNextPage that does not come from the Loader,
    // append the error to the errors list.
    private _onUnhandledPromiseError = (err: any): void => {
        this._updateListStatusFromItemLoaderStates();
        if (!this._errors?.length) {
            this._errors = [];
        }
        this._errors.push(err);
        this._status = AssetListStatus.HadLoaderErrors;
        this.emit(STATE_CHANGED);
    };

    /**
     * Other internal SAM.js code relies on getting a Promise.
     * This should only be used inside SAM.js, not by clients.
     * @package
     */
    async _loadAsync(options?: ILoadOptions, revalidateAtPage?: number): Promise<void> {
        if (!this._loaderStates.length) {
            // We don't have any loaders.
            return;
        }

        const refreshTimeout = options?.refreshTimeout ?? 0;

        // Check if the list needs to be refreshed:
        // 1. The user didn't provide a refresh timeout, meaning we always load the contents.
        // 2. There is a need to refresh the contents because the list has changed outside of SAMJS.
        // 3. There's a refresh timeout and the timeout expired. We can use this mechanism to prevent using
        //    data that is considered to be too old without forcing a refresh all the times.
        // 4. refreshTimeout === -1 means the client does NOT want to refresh, only wait for existing
        //    load requests to finish, possibly for the purpose of modifying other loadOptions like limit
        //    or loadAllPages.
        const lastFetchTime = this._lastFetchTime;
        if (this._needsRefresh || !lastFetchTime || !refreshTimeout || (refreshTimeout !== -1 && lastFetchTime + refreshTimeout < Date.now())) {
            this._debug(`_loadAsync() calling _load(): _needsRefresh: ${this._needsRefresh}, lastFetchTime: ${lastFetchTime}`
                + ` refreshTimeout: ${refreshTimeout}`);
            await this._load(options, revalidateAtPage);
            return;
        } else {
            this._debug(`_loadAsync() not time to refresh: _needsRefresh: ${this._needsRefresh}, lastFetchTime: ${lastFetchTime}`
                + ` refreshTimeout: ${refreshTimeout}`);
        }

        // If there's a pending load, wait until it's finished.
        const previousLoadPromise = this._previousLoadPromise;
        if (previousLoadPromise) {
            // Wait until the previous load is complete.
            this._debug('_loadAsync() awaiting previousLoadPromise');
            await previousLoadPromise;
        }

        if (options?.loadAllPages) {
            // Make sure the previous load didn't load just the first page.
            await this._ensureAllPagesAreLoaded(options);
        }
    }

    private async _load(loadOptions?: ILoadOptions, revalidateAtPage: number = 0): Promise<void> {
        // Make sure we don't keep refreshing this list.
        this._needsRefresh = false;
        const invalidateCache = this._invalidateCacheForNextLoad;
        // Reset the invalidate cache flag after using it for this load
        this._invalidateCacheForNextLoad = false;

        // Coalesce multiple load requests into one.
        let pendingLoad = this._pendingLoad;
        if (!pendingLoad) {
            // Since _handlePendingLoad execution is deferred, control is returned to the caller where it
            // should expect the List to already be loading, even though the Loader hasn't actually
            // started.
            this._status = AssetListStatus.Loading;
            // _lastFetchTime must be defined now, because the _handlePendingLoad execution is deferred, which
            // causes control to be passed back to the client. If the client then calls getList(), the refreshTimeout
            // option would not be evaluated properly since _lastFetchTime would be stale.
            this._lastFetchTime = Date.now();

            // We use the generation to ignore results that are still in-flight.
            // When a new load is issued, we will slowly cleanup the
            // results as soon as the prior loading actions finish.
            this._generation = allocGenerationIndex();

            this._debug('_load() creating _pendingLoad');
            this._pendingLoad = pendingLoad = {
                loadOptions,
                revalidateAtPage,
                invalidateCache,
                // Make sure the load executes after the stack unrolls.
                promise: Promise.resolve().then(this._handlePendingLoad)
            };

            // Alert clients of state change
            this._dispatchStateChangedEvents();
        } else if (loadOptions?.loadAllPages) {
            // Make sure that the pending load fetches all the pages.
            if (!pendingLoad.loadOptions) {
                pendingLoad.loadOptions = {};
            }
            pendingLoad.loadOptions.loadAllPages = true;
        }
        this._debug('_load() awaiting _pendingLoad');
        await pendingLoad.promise;
    }

    private _handlePendingLoad = async () => {
        const pendingLoad = this._pendingLoad;
        if (pendingLoad) {
            const { loadOptions, revalidateAtPage, invalidateCache } = pendingLoad;
            this._pendingLoad = undefined;
            this._debug('_handlePendingLoad() awaiting _runLoaders for loaderState.load');
            await this._runLoaders((loaderState) => loaderState.load(this._generation, loadOptions, revalidateAtPage, invalidateCache));
        }
    };

    loadNextPage(loadOptions?: ILoadOptions): void {
        this._loadNextPageAsync(loadOptions || this._loadOptions).catch(this._onUnhandledPromiseError);
    }

    /**
     * Other internal SAM.js code relies on getting a Promise.
     * This should only be used inside SAM.js, not by clients.
     * @package
     */
    async _loadNextPageAsync(options?: ILoadOptions): Promise<void> {
        if (!this._loaderStates.length) {
            // We don't have any loaders.
            return;
        }
        if (this._pendingLoad) {
            this._debug('_loadNextPageAsync() awaiting _pendingLoad');
            await this._pendingLoad.promise;
        } else {
            // Since _loadAsync doesn't immediately start loading, but it does update its status and broadcast the
            // status change event, _loadNextPageAsync must do the same. It can't be handled in _runLoaders only,
            // because without the status event fired in _loadAsync, it'd be fired too late; with the status event
            // fired in _loadAsync, it'd be fired redundantly.
            this._status = AssetListStatus.Loading;
            this._dispatchStateChangedEvents();
            this._debug('_loadNextPageAsync() awaiting _runLoaders for loaderState.loadNextPage');
            await this._runLoaders((loaderState) => loaderState.loadNextPage(options));
        }
    }

    private async _runLoaders(fn: (loaderState: ItemLoaderState<ItemConfig>) => Promise<void>) {
        // We need to update this first to avoid multiple calls to load
        // from trying to load too often.
        this._lastFetchTime = Date.now();

        // Save the promise that triggered the last load.
        const promise = Promise.all(this._loaderStates.map(fn));
        this._previousLoadPromise = promise;

        try {
            this._debug('_runLoaders() awaiting loaders');
            await promise;
        } finally {
            this._debug('_runLoaders() loaders complete');

            // Remove the load promise.
            this._previousLoadPromise = undefined;

            // Notify listeners that the List.status has changed (computed from ItemLoaders). This must be the
            // last line processed that alters any state in List, so that event listeners can immediately utilize
            // the List in a completely settled state.
            this._updateListStatusFromItemLoaderStates();
            this._dispatchStateChangedEvents();

            // Notify ItemSource that it can copy this list to other compatible lists.
            // NOTE: this event not intended for clients.
            if (this._status === AssetListStatus.ReadyFullyLoaded) {
                this.emit(LIST_FULLY_LOADED);
            }

            // Ensure this list is added to the ItemPool.
            this._itemPool.addList(this);
        }
    }

    setNeedsRefresh(): void {
        if (this.status === AssetListStatus.NotStarted || !this._loaderStates.length) {
            // List has never been loaded, so doesn't need refresh
            return;
        }

        if (this.listenerCount(LIST_CHANGED)) {
            // We have listeners waiting for changes, so go ahead and reload this list now.
            this._needsRefresh = true;
            this._invalidateCacheForNextLoad = true;
            this.refresh();
            return;
        }

        // There are no listeners, we will keep a note to refresh this list
        // once the list becomes active again.
        this._needsRefresh = true;
        this._invalidateCacheForNextLoad = true;
    }

    _onEventListenerAdded() {
        if (this._needsRefresh && this.listenerCount(LIST_CHANGED)) {
            // Make sure the list is updated once the client
            // needs to use the items of this list again.
            this.refresh();
        }
    }

    private async _ensureAllPagesAreLoaded(loadOptions?: ILoadOptions): Promise<void> {
        if (this.status !== AssetListStatus.ReadyHasMorePages) {
            // No more pages to load. Bail out.
            return;
        }
        // Looks like the previous load didn't finish all the pages.
        // Note that if another prefetch is issued, we will just wait on the promise
        // created by the _runLoaders below via `this._previousLoadPromise`.
        await this._runLoaders((loaderState) => loaderState.loadAllPages(loadOptions));
    }

    private _onItemLoaderStateChanged = (ev: ItemLoaderStateChangeEvent) => {
        const { hasUpdatedItems } = ev;

        this._cleanPreviousGenerationItemsIfNeeded();

        // Only dispatch ItemsChanged events in response to ItemLoaderState events. ItemList will broadcast the
        // StatusChanged event when exiting the load/loadNextPage methods so that all ItemList state is settled
        // when the StatusChanged event fires.
        if (hasUpdatedItems) {
            this._updateListItemsFromItemLoaderStates();
        }
    };

    private _onItemLoaderRefreshNeeded = (ev: ItemLoaderRefreshNeededEvent) => {
        const { revalidateAtPage } = ev;

        this._updateListItemsFromItemLoaderStates();

        this._needsRefresh = true;
        this._loadAsync(this._loadOptions, revalidateAtPage).catch(this._onUnhandledPromiseError);
    };

    // Reusable event that we use to avoid creating a new event object all the times.
    private _globalStateChangedEvent = new ItemListStateChangedEvent(this);

    /**
     * @package -- only for use in SAM.js
     */
    _dispatchStateChangedEvents() {
        this._debug(`_dispatchStateChangedEvents status: ${AssetListStatus[this.status]}`);
        this.dispatch(SharedStateChangedEvent);

        // Dispatch a global event that can be used to handle global
        // state updates without adding individual events on all the item lists.
        this._core.dispatch(this._globalStateChangedEvent);
    }

    private _updateListStatusFromItemLoaderStates() {
        let newStatus: AssetListStatus = this._pendingLoad ? AssetListStatus.Loading : AssetListStatus.NotStarted;

        // Remove any previous error.
        this._errors = undefined;

        for (const loaderState of this._loaderStates) {
            // Update status and error from the loader state.
            switch (loaderState.status) {
            case AssetListStatus.HadLoaderErrors:
                // We only surface the error in cases when there's no loader pending to start.
                if (this._pendingLoad) {
                    break;
                }

                // We surface errors immediately.
                this._status = AssetListStatus.HadLoaderErrors;
                this._errors = [ loaderState.error ];

                // Return early to avoid cleaning previous generation items.
                return;

            case AssetListStatus.ReadyHasMorePages:
                if (newStatus !== AssetListStatus.Loading && !this._loadOptions?.loadAllPages) {
                    // If we don't have a loader that is still loading, and we're not loading all pages, then
                    // change status to ReadyHasMorePages
                    newStatus = AssetListStatus.ReadyHasMorePages;
                }
                break;

            case AssetListStatus.Loading:
                // We always want to know when a page is still loading.
                newStatus = AssetListStatus.Loading;
                break;

            case AssetListStatus.ReadyFullyLoaded:
                if (newStatus !== AssetListStatus.ReadyHasMorePages && newStatus !== AssetListStatus.Loading) {
                    // If we don't have a loader that still has pages to load and if we don't actually load something.
                    newStatus = AssetListStatus.ReadyFullyLoaded;
                }
                break;
            }

            // Update this list Id, if the loader provides it.
            if (loaderState.assetListId) {
                this._assetListId = loaderState.assetListId;
            }
        }
        this._status = newStatus;
    }

    private _dispatchItemsChangedEvent() {
        // Let the client know they have to read the item list again.
        this.dispatch(SharedListChangedEvent);
    }

    private _updateListItemsFromItemLoaderStates() {
        this._applyItemsChangedEvents();

        const itemSet = new Set<ItemConfig['type']>();

        let total: number | undefined;

        // Collect the items from all the loaders.
        for (const loaderState of this._loaderStates) {
            loaderState.collectAllItems(itemSet);

            if (loaderState.total !== undefined) {
                total = Math.max(total || 0, loaderState.total);
            }
        }

        // Collect any items that were changed on the client
        // side and might not be captured in the requests from
        // the server side yet.
        for (const itemGeneration of this._itemUpdatesByGeneration.values()) {
            for (const [ item, state ] of itemGeneration.entries()) {
                if (state) {
                    itemSet.add(item);
                } else {
                    itemSet.delete(item);
                }
            }
        }

        const items = Array.from(itemSet);

        // Sort the items based on the current ordering.
        this.order.sortItems(items);

        this._items = items;
        this._total = total;

        this._dispatchItemsChangedEvent();
    }

    /**
     * Handles the change notifications from the pool.
     * This method executes until the GC collects the List reference.
     * This handler must be as quick as possible and postpone any list
     * updates until the items are actually needed by the client.
     * @param ev
     */
    private _itemPoolDelegate: IItemPoolDelegate<ItemConfig['type']> = {
        onItemsUpdated: (event: ItemsChangedEvent<ItemConfig['type']>) => {
            if (event.updateContext === LOADER_UPDATE_CONTEXT) {
                // Ignore changes from ItemLoaders, which are handled in _updateListItemsFromItemLoaderStates
                // but not _applyItemsChangedEvents. This is so partially loaded lists can maintain independence
                // from other partially loaded lists whose filters intersect. E.g., if listA has items sorted ascending,
                // and listB has the same filter but sorted descending, loading a page from listA won't add items to
                // listB, and vice versa. Updates still go through ItemPool, so if both lists have loaded the same item,
                // there will only be one instance of the item.
                return;
            }

            let pendingNotifications = this._pendingNotifications;
            if (!pendingNotifications) {
                pendingNotifications = [];
                this._pendingNotifications = pendingNotifications;
            }

            pendingNotifications.push({
                generation: this._generation,
                event
            });

            this._updateListItemsFromItemLoaderStates();
        }
    };

    /**
     * Handles changes injected through the item pool. These can be either local changes
     * made by the user, or changes detected while fetching other lists.
     *
     * We use this mechanism to propagate the changes immediately across the entire app.
     * For example, if a different call detects a Space has been updated, all the active
     * lists will get the notification and automatically apply the change to their own listing.
     *
     * We are only interested about additions and deletions. Note that items
     * can be added (or removed) to the list if the mutations of the item properties make the
     * updated item pass (or fail) the filter of the current list.
     */
    private _applyItemsChangedEvents(): void {
        const pendingNotifications = this._pendingNotifications;
        if (!pendingNotifications) {
            return;
        }
        this._pendingNotifications = undefined;

        // Break down changes into their own generations of added/removed items.

        for (const notification of pendingNotifications) {
            const { event, generation } = notification;
            if (generation < this._completedGeneration) {
                // Ignore changes from completed generations. We already have all
                // the correct items received from the server.
                continue;
            }

            let itemGeneration = this._itemUpdatesByGeneration.get(generation);
            if (!itemGeneration) {
                itemGeneration = new Map();
                this._itemUpdatesByGeneration.set(generation, itemGeneration);
            }

            if (event.addedItems) {
                for (const item of event.addedItems) {
                    if (this.implicitFilter.matches(item) && this.filter.matches(item)) {
                        itemGeneration.set(item, true);
                    }
                }
            }

            if (event.changedItems) {
                for (const item of event.changedItems) {
                    // Check if we have any items that pass the filter test or not.
                    // We need to store both matching and non-matching, just in case
                    // an non-matching item was matching before the update and
                    // we now have to manually remove it from the list fetched from
                    // the server.
                    const included = this.implicitFilter.matches(item) && this.filter.matches(item);
                    if (included) {
                        itemGeneration.set(item, true);
                    } else {
                        // Only exclude items from the list when they're already on the list. Optimistic updates
                        // of local items shouldn't preclude an item from appearing on the list in the future.
                        // Note: this means that code that updates the local item before mutating in the
                        // cloud can cause items in lists to flicker in/out of the list -- it is strongly recommended
                        // that local updates only happen after the remote update completes successfully.
                        if (this._items.includes(item)) {
                            itemGeneration.set(item, false);
                        }
                    }
                }
            }

            if (event.discardedItems) {
                for (const item of event.discardedItems) {
                    // Any discarded items must be removed entirely.
                    itemGeneration.set(item, false);
                }
            }
        }
    }
}
