import { EventEmitter } from 'events';

/**
 * Restrict the ability for clients of JSAPI to remove all listeners on an Event Emitter.
 * Adding the getter for DANGEROUS set of methods ensures the developer understands that
 * their actions could have unforeseen consequences.
 *
 * @export
 * @class RestrictedEventEmitter
 */
export default class RestrictedEventEmitter {
    private _emitter: EventEmitter = new EventEmitter();

    get DANGEROUS(): { removeAllListeners: (event?: string | symbol) => RestrictedEventEmitter } {
        return {
            removeAllListeners: (event?: string | symbol) => {
                // This one is weird. Native EventEmitter has a conditional in the implementation
                // that checks for the length of arguments... an undefined value still counts as a
                // argument so it bypasses removal of all event listeners...
                event ? this._emitter.removeAllListeners(event) : this._emitter.removeAllListeners();
                return this;
            }
        };
    }

    /**
     * add a listener for a specified event
     *
     * @param {(string | symbol)} eventName name of the event to listen to
     * @param {(...args: any[]) => void} listener callback that is triggered when an event is emitted
     * @returns {this}
     * @memberof RestrictedEventEmitter
     */
    addListener(eventName: string | symbol, listener: (...args: any[]) => void): this {
        this._emitter.addListener(eventName, listener);
        return this;
    }

    /**
     * alias for addListener
     *
     * @param {(string | symbol)} eventName name of the event to listen to
     * @param {(...args: any[]) => void} listener callback that is triggered when an event is emitted
     * @returns {this}
     * @memberof RestrictedEventEmitter
     */
    on(eventName: string | symbol, listener: (...args: any[]) => void): this {
        return this.addListener(eventName, listener);
    }

    /**
     * add an event listener for a specified event. When that event fires and the given callback
     * is triggered, the listener will be removed.
     *
     * @param {(string | symbol)} eventName name of the event to listen to
     * @param {(...args: any[]) => void} listener callback that is triggered when an event is emitted
     * @returns {this}
     * @memberof RestrictedEventEmitter
     */
    once(eventName: string | symbol, listener: (...args: any[]) => void): this {
        this._emitter.once(eventName, listener);
        return this;
    }

    /**
     * Remove the listener for the given event name
     *
     * @param {(string | symbol)} eventName name of the event to listen to
     * @param {(...args: any[]) => void} listener callback that is to be removed
     * @returns {this}
     * @memberof RestrictedEventEmitter
     */
    removeListener(eventName: string | symbol, listener: (...args: any[]) => void): this {
        this._emitter.removeListener(eventName, listener);
        return this;
    }

    /**
     * Alias for removeListener
     *
     * @param {(string | symbol)} eventName name of the event to listen to
     * @param {(...args: any[]) => void} listener callback that is to be removed
     * @returns {this}
     * @memberof RestrictedEventEmitter
     */
    off(eventName: string | symbol, listener: (...args: any[]) => void): this {
        return this.removeListener(eventName, listener);
    }

    /**
     * By default EventEmitters will print a warning if more than 10 listeners are added for a particular event.
     * This is a useful default that helps finding memory leaks. The emitter.setMaxListeners() method allows the
     * limit to be modified for this specific EventEmitter instance. The value can be set toInfinity (or 0) to
     * indicate an unlimited number of listeners.
     *
     * Returns a reference to the EventEmitter, so that calls can be chained.
     *
     * @param {number} n Set the maximum amount of listeners that can be added to this instance of EventEmitter
     * @returns {this}
     * @memberof RestrictedEventEmitter
     */
    setMaxListeners(n: number): this {
        this._emitter.setMaxListeners(n);
        return this;
    }

    /**
     * Returns the maximum number of listeners allowed
     *
     * @returns {number} The number of listeners allowed on on this instance of EventEmitter
     * @memberof RestrictedEventEmitter
     */
    getMaxListeners(): number {
        return this._emitter.getMaxListeners();
    }

    /**
     * Return an array of function references for a given event name
     *
     * @param {(string | symbol)} eventName name of the event we want to match when returning function array.
     * @returns {Function[]} array of function references that are triggered when an event is emitted
     * @memberof RestrictedEventEmitter
     */
    listeners(eventName: string | symbol): Function[] {
        return this._emitter.listeners(eventName);
    }

    /**
     * Returns a copy of the array of listeners for the event named eventName, including any wrappers (such as those created by .once()).
     *
     * @example
     * ```ts
     * const emitter = new EventEmitter();
     * emitter.once('log', () => console.log('log once'));
     *
     * // Returns a new Array with a function `onceWrapper` which has a property
     * // `listener` which contains the original listener bound above
     * const listeners = emitter.rawListeners('log');
     * const logFnWrapper = listeners[0];
     *
     * // Logs "log once" to the console and does not unbind the `once` event
     * logFnWrapper.listener();
     *
     * // Logs "log once" to the console and removes the listener
     * logFnWrapper();
     *
     * emitter.on('log', () => console.log('log persistently'));
     * // Will return a new Array with a single function bound by `.on()` above
     * const newListeners = emitter.rawListeners('log');
     *
     * // Logs "log persistently" twice
     * newListeners[0]();
     * emitter.emit('log');
     * ```
     *
     * @param {(string | symbol)} eventName
     * @returns {Function[]}
     * @memberof RestrictedEventEmitter
     */
    rawListeners(eventName: string | symbol): Function[] {
        return this._emitter.rawListeners(eventName);
    }

    /**
     * Synchronously calls each of the listeners registered for the event namedeventName, in the order they were registered, passing the supplied arguments to each.
     * Returns true if the event had listeners, false otherwise.
     *
     * @example
     * ```ts
     * const EventEmitter = require('events');
     * const myEmitter = new EventEmitter();
     *
     *
     * // First listener
     * myEmitter.on('event', function firstListener() {
     *   console.log('Helloooo! first listener');
     * });
     * // Second listener
     * myEmitter.on('event', function secondListener(arg1, arg2) {
     *   console.log(`event with parameters ${arg1}, ${arg2} in second listener`);
     * });
     * // Third listener
     * myEmitter.on('event', function thirdListener(...args) {
     *   const parameters = args.join(', ');
     *   console.log(`event with parameters ${parameters} in third listener`);
     * });
     *
     * console.log(myEmitter.listeners('event'));
     *
     * myEmitter.emit('event', 1, 2, 3, 4, 5);
     *
     * // Prints:
     * // [
     * //   [Function: firstListener],
     * //   [Function: secondListener],
     * //   [Function: thirdListener]
     * // ]
     * // Helloooo! first listener
     * // event with parameters 1, 2 in second listener
     * // event with parameters 1, 2, 3, 4, 5 in third listener
     * ```
     *
     * @param {(string | symbol)} eventName name of the event to trigger
     * @param {...any[]} args arguments to pass to the listener
     * @returns {boolean} Returns true if the event had listeners. False otherwise
     * @memberof RestrictedEventEmitter
     */
    emit(eventName: string | symbol, ...args: any[]): boolean {
        return this._emitter.emit(eventName, ...args);
    }

    /**
     * Number of listeners for a given event name
     *
     * @param {(string | symbol)} eventName
     * @returns {number}
     * @memberof RestrictedEventEmitter
     */
    listenerCount(eventName: string | symbol): number {
        return this._emitter.listenerCount(eventName);
    }

    /**
     * Adds the listener function to the beginning of the listeners array for the event named eventName. No checks are made to see if the listener has already been added. Multiple calls passing the same combination of eventNameand listener will result in the listener being added, and called, multiple times.
     *
     * @example
     * ```ts
     * server.prependListener('connection', (stream) => {
     *   console.log('someone connected!');
     * });
     * ```
     *
     * Returns a reference to the EventEmitter, so that calls can be chained.
     *
     * @param {(string | symbol)} eventName Name of the event to create a listener for
     * @param {(...args: any[]) => void} listener Function to call when given event name is triggered
     * @returns {this}
     * @memberof RestrictedEventEmitter
     */
    prependListener(eventName: string | symbol, listener: (...args: any[]) => void): this {
        this._emitter.prependListener(eventName, listener);
        return this;
    }

    /**
     * Adds a one-timelistener function for the event named eventName to the_beginning_ of the listeners array. The next time eventName is triggered, this listener is removed, and then invoked.
     *
     * @example
     * ```ts
     * server.prependOnceListener('connection', (stream) => {
     *   console.log('Ah, we have our first user!');
     * });
     * ```
     *
     * Returns a reference to the EventEmitter, so that calls can be chained.
     *
     * @param {(string | symbol)} eventName Name of the event to listen for
     * @param {(...args: any[]) => void} listener callback to fire when named event is triggered
     * @returns {this}
     * @memberof RestrictedEventEmitter
     */
    prependOnceListener(eventName: string | symbol, listener: (...args: any[]) => void): this {
        this._emitter.prependOnceListener(eventName, listener);
        return this;
    }

    /**
     * Returns an array listing the events for which the emitter has registered listeners. The values in the array are strings or Symbols.
     *
     * @example
     * ```ts
     * const EventEmitter = require('events');
     * const myEE = new EventEmitter();
     * myEE.on('foo', () => {});
     * myEE.on('bar', () => {});
     *
     * const sym = Symbol('symbol');
     * myEE.on(sym, () => {});
     *
     * console.log(myEE.eventNames());
     * // Prints: [ 'foo', 'bar', Symbol(symbol) ]
     * ```
     *
     * @returns {((string | symbol)[])} Array of event names that are being listened for
     * @memberof RestrictedEventEmitter
     */
    eventNames(): (string | symbol)[] {
        return this._emitter.eventNames();
    }
}
