import SAMError, { SAMErrorCode } from '@sam-js-src/core/SAMError';

/**
 * LibraryError class encompasses all Error types that can be generated internally by the JSAPI
 *
 * @packageDocumentation
 * @module LibraryError
 */

export const CodePriority = [
    'NETWORK_ERROR',
    'EXCEEDS_QUOTA',
    'LOGGED_OUT',
    'INVALID_DATA',
    'NOT_ALLOWED',
    'NOT_SUPPORTED',
    'NOT_IMPLEMENTED',
    'INVALID_PARAMETER',
    'CONNECTION_FAILED',
    'REQUEST_FAILED',
    'INVALID_RESPONSE',
    'INVALID_JSON'
] as const;

export type Code = typeof CodePriority[number];

type ErrorLike = {
    code: Code;
    message: string;
    libraryId?: string;
    _additionalInfo?: {
        underlyingError?: UnderlyingError
    };
};

export type UnderlyingError = Omit<ErrorLike, '_additionalInfo'>;

function isErrorLike(errorLikeObj: {}): errorLikeObj is ErrorLike {
    const errLikeCast = errorLikeObj as ErrorLike;
    return !!errLikeCast.code && !!errLikeCast.message;
}

function ConvertErrorCode(libraryErrorCode: Code): SAMErrorCode {
    switch (libraryErrorCode) {
    case 'EXCEEDS_QUOTA':
        return SAMErrorCode.FULL_CLOUD_STORAGE;
    case 'LOGGED_OUT':
    case 'NOT_ALLOWED':
        return SAMErrorCode.AUTHORIZATION_ERROR;
    case 'NETWORK_ERROR':
        return SAMErrorCode.NETWORK_ERROR;
    case 'NOT_SUPPORTED':
    case 'NOT_IMPLEMENTED':
        return SAMErrorCode.UNSUPPORTED;
    case 'INVALID_DATA':
    case 'INVALID_PARAMETER':
    case 'CONNECTION_FAILED':
    case 'REQUEST_FAILED':
    case 'INVALID_RESPONSE':
    case 'INVALID_JSON' :
    default:
        return SAMErrorCode.UNKNOWN;
    }
}

export default class LibraryError extends SAMError {
    public libraryErrorCode: Code;
    public libraryId?: string;

    constructor(code: Code, message: string, libraryId?: string, underlyingError?: UnderlyingError);
    constructor(errorObject: ErrorLike);
    constructor(
        codeOrErrorLikeObject: Code | ErrorLike,
        message?: string,
        libraryId?: string,
        underlyingError?: UnderlyingError
    ) {
        if (isErrorLike(codeOrErrorLikeObject)) {
            message = codeOrErrorLikeObject.message;
            libraryId = codeOrErrorLikeObject.libraryId;
            underlyingError = codeOrErrorLikeObject._additionalInfo?.underlyingError;
            codeOrErrorLikeObject = codeOrErrorLikeObject.code;
        }

        super(ConvertErrorCode(codeOrErrorLikeObject), message || '', { underlyingError });
        this.libraryErrorCode = codeOrErrorLikeObject;
        this.libraryId = libraryId;
    }

    get underlyingError(): UnderlyingError | undefined {
        return this._additionalInfo?.underlyingError;
    }
}
