import type LibraryInterface from '../interface/LibraryInterface';
import type { LibraryListParameters, LibraryData, LibrariesResponse, MelvilleLink, OwnerParameters, RolesParameters } from '../interface/LibraryModel';
import { LibraryProjectFilterEnum } from '../interface/LibraryModel';
import type Library from './Library';
import type { IItemLoader, IItemLoaderOptions, ILoadedPage, ILoadNextPage } from '../core/ItemLoader';
import type ItemPool from '../core/ItemPool';
import type LibraryOrder from './LibraryOrder';
import { OrderFieldToLibraryOrderBy } from './LibraryOrder';
import LibraryFilter from './LibraryFilter';

import type AdobeAsset from '../assets/AdobeAsset';
import type ItemUpdater from '../core/ItemUpdater';
import type ImplicitLibraryFilter from './ImplicitLibraryFilter';
import type { IItemSourceConfig } from '../core/ItemList';
import { LazyLoadManager } from '../core/decorators/LazyLoadManager';
import { STORAGE_ASSIGNEE_CHANGED } from '../assets/AssetEvents';
import type Project from '../projects/Project';
import type { ISAMCorePrivate } from '../indexPrivate';
import { getMostRecentValidMutation } from '../utils/loaderUtils';

// Load Libraries from Melville
export default class LibraryListLoader<Config extends IItemSourceConfig> implements IItemLoader<Config> {

    constructor(
        private _libraryPool: ItemPool<Library | AdobeAsset>,
        private _libraryInterface: LibraryInterface,
        private _libraryUpdater: ItemUpdater<Library, Partial<LibraryData>>,
        private _core: ISAMCorePrivate
    ) {}

    // only supports LibraryFilter
    supportsFilter(filter: LibraryFilter): boolean {
        // If we don't provide a filter at all, then we cannot use the loader
        return filter !== undefined;
    }

    async loadPage(options: IItemLoaderOptions<Config>): Promise<ILoadedPage<Config>> {
        return await this._loadPage(options);
    }

    private async _loadPage(options: IItemLoaderOptions<Config>, pageLink?: MelvilleLink): Promise<ILoadedPage<Config>> {
        let result: LibrariesResponse;
        const filter = options.filter as LibraryFilter;

        if (pageLink) {
            if (options.loadOptions?.limit) {
                pageLink.href = pageLink.href.replace(/limit=[0-9]*/, `limit=${options.loadOptions.limit}`);
            }
            result = await this._libraryInterface.getLibrariesWithLink(pageLink);
        } else {
            const {  limit } = options.loadOptions ?? {};
            const implicitFilter = options.implicitFilter as ImplicitLibraryFilter;
            const order = options.order as LibraryOrder;

            // Give preference to the implicit filter. Use default if filter is EverythingFilter.
            const ownerFilter = implicitFilter._owner || filter._owner || LibraryFilter.DEFAULT._owner;
            const rolesFilter = implicitFilter._roles || filter._roles;

            // Move filters into query parameters, making sure to sort the arrays so that the eventual query string is deterministic.
            const queryParams: LibraryListParameters = {};
            if (ownerFilter && !filter._reference) {
                // Only set owner parameter if filter._reference doesn't exist
                queryParams.owner = [ ...ownerFilter ].sort().join(',') as OwnerParameters;
            }
            if (filter._reference) {
                queryParams.references = filter._reference;
            }
            if (rolesFilter) {
                queryParams.roles = [ ...rolesFilter ].sort().join(',') as RolesParameters;
            }
            if (filter._project) {
                queryParams.team = filter._project;
            }
            if (filter._publishMetadata) {
                queryParams.itemFilter = filter._publishMetadata;
            }
            queryParams.orderBy = order.direction === 'ascending' ? OrderFieldToLibraryOrderBy[order.field] : `-${OrderFieldToLibraryOrderBy[order.field]}`;
            if (limit) {
                queryParams.limit = limit;
                if (!queryParams.start) {
                    queryParams.start = 0;
                }
            }
            // The selector specifies what data will be returned on each library.
            // Details includes extra information about each library, including the library's custom thumbnail.
            queryParams.selector = 'rendition_grid,collaboration,details';

            result = await this._libraryInterface.getLibraries(queryParams);
        }

        // update the libraries data with referenced by project data
        if (filter._project) {
            this._decorateLibraryDataWithReferencedByProject(result.libraries, filter._project);
        }


        // Libraries listings from Melville are considered "USS" sources (with the current exception of a public libraries-only listing), and may have stale data.
        // To prevent it from potentially overwriting fresh RAPI data within the USS latency window, we will use
        // 'createLoaderUpdateSession' instead of 'createLoaderMutationSession' and this update will be ignored if there were local changes later than this timestamp.
        const latency = this._libraryPool._core._environment.getValue('USS_LIST_UPDATE_LATENCY');
        const mostRecentValidMutation = getMostRecentValidMutation(options.resource, latency);
        const session = this._libraryPool.createLoaderUpdateSession<Library>(mostRecentValidMutation);
        const items = this._libraryUpdater.updateRemoteItems(session, result.libraries); // get or create Library instances
        items.forEach(library => library._setLibraryLoadState('LOADED'));
        // Mark storage_assignee as loaded, so that we do not trigger a lazy load of the value.
        items.forEach(library => LazyLoadManager.updatedByItemUpdater(library, STORAGE_ASSIGNEE_CHANGED));
        session.commit(); // put items in the pool

        // Update project with inaccessible references if available
        if (filter._project) {
            this._updateProjectInaccessibleReferences(filter._project, result.inaccessibleReferences);
        }

        // Check if we have another page to load.
        let loadNextPage: ILoadNextPage<Config> | undefined;
        const nextPageLink = result._links?.next;
        if (nextPageLink) {
            loadNextPage = (options: IItemLoaderOptions<Config>) =>
                this._loadPage(options, nextPageLink);
        }

        return {
            items,
            total: result.total_count, // total number of libraries in the account (not the page)
            loadNextPage,
            mostRecentValidMutation
        };
    }

    /**
     * When requesting libraries with the references filter for a specific project,
     * Melville returns a list of libraries and includes a 'reference' boolean field to indicate
     * if the library is referenced by the project vs. when the library is in the project itself.
     *
     * request: team=project-123&references=only
     * response: from Melville:
     *
     * {
     *  "libraries": [
     *      {
     *          "library_urn": "library-in-project-123", // library is in the project
     *      },
     *      {
     *          "library_urn": "library-referenced-by-project-123", // library is referenced by the project
     *          "reference": true
     *      }
     *  ]
     * }
     *
     * This method supplements the Melville data by adding a 'referenced_by_project' field to the library data that includes the projectId
     * used to request the data. This allows us to use the item updater to update the libraries and track which libraries are referenced by a project.
     *
     * @param libraries - The Melville libraries data.
     * @param projectId - The project ID that was used to request the referenced libraries.
     */
    private _decorateLibraryDataWithReferencedByProject(libraries: LibraryData[], projectId: string) {
        if (projectId === LibraryProjectFilterEnum.All || projectId === LibraryProjectFilterEnum.None) {
            return;
        }
        libraries.forEach(library => {
            const { reference } = library;
            if (reference && projectId) {
                library.referenced_by_project = { projectId, reference };
            }
        });
    }

    /**
     * Updates the project with inaccessible references from the Melville response.
     * inaccessibleReferences are only returned by Melville when requesting libraries
     * with a reference filter for a specific project.
     *
     * @param inaccessibleReferences - Any inaccessible references from Melville
     * @param projectId - The project ID that was used to request the referenced libraries
     */
    private _updateProjectInaccessibleReferences(projectId: string, inaccessibleReferences?: string[]) {
        if (!inaccessibleReferences) {
            return;
        }

        const projectContext = this._core._getProjectContext();
        // Only update Projects if ProjectContext is already loaded
        if (!projectContext) { return; }
        const project = projectContext._assetPool.getLocalItemById<Project>(projectId);

        // if project is not already found in the pool, skip updating inaccessible references
        if (!project) {
            return;
        }

        // Update the project with inaccessible references
        const session = projectContext._assetPool.createUpdateSession<Project>('update project inaccessible references');
        projectContext._projectUpdater.updateLocalItem(session, project, { inaccessibleReferences });
        session.commit();
    }

}
