import type { ItemFilterRelation } from '../core/ItemFilter';
import type {
    LibraryProjectFilter } from '../interface/LibraryModel';
import {
    LibraryOwnerFilter,
    LibraryProjectFilterEnum,
    LibraryRolesFilter,
    BrandPublishMetadataFilter,
    LibraryReferenceFilter
} from '../interface/LibraryModel';
import type Library from './Library';
import { ModernSet } from '../utils/ModernSet';

// Helper methods for IItemFilter.matches() when the filter uses LibraryFilterOptions.

export function itemMatchesOwnerFilter(item: Library, owner: Set<LibraryOwnerFilter>) {
    if (item._ownership_NoLazyLoad === undefined) {
        return false;
    }

    return owner.has(item._ownership_NoLazyLoad as LibraryOwnerFilter)
        // Public libraries are not returned by the 'all' owner filter
        || (owner.has(LibraryOwnerFilter.All) && !item._isPublicLink_NoLazyLoad)
        // 'ownership' field can be 'incoming' or 'team' for followed project libraries. We are trying to move away from relying on this field,
        // so this just checks for a collab bookmark.
        || (owner.has(LibraryOwnerFilter.Incoming) && !item._isPublicLink_NoLazyLoad && item._isBookmarked_NoLazyLoad)
        // Discovery includes everything the user has access to that is NOT in User Storage except public libraries.
        // * Includes: Incoming libraries, Project libraries (except CCI Project Libraries since they are in User Storage)
        // * Excludes: Public libraries, CCI Project Libraries, Private Libraries
        || (owner.has(LibraryOwnerFilter.Discovery) && (item._ownership_NoLazyLoad !== 'private') && !item._isPublicLink_NoLazyLoad && !item._isCCIProjectLibrary);
}

export function itemMatchesRolesFilter(item: Library, roles: Set<LibraryRolesFilter>) {
    if (item._roles_NoLazyLoad === undefined) {
        return false;
    }

    return roles.has(LibraryRolesFilter.None) && (!item._roles_NoLazyLoad || item._roles_NoLazyLoad.length === 0)
        // one of the roles filters matches one of the roles on the library
        || item._roles_NoLazyLoad?.some(role => roles.has(role.type as LibraryRolesFilter));
}

export function itemMatchesProjectFilter(item: Library, project: LibraryProjectFilter, reference?: LibraryReferenceFilter) {
    return (project === LibraryProjectFilterEnum.All && item.isChildOfProject)
        || (project === 'none' && !item.isChildOfProject)
        || (project === 'other' && item.isChildOfProject && !item._isBookmarked_NoLazyLoad)
        || (reference === LibraryReferenceFilter.Only && item.isReferencedByProject(project))
        || (reference === LibraryReferenceFilter.All && item.isReferencedByProject(project))
        || (project === item.parentProjectID && reference !== LibraryReferenceFilter.Only);
}

export function itemMatchesPublishMetadataFilter(item: Library, publishMetadata: BrandPublishMetadataFilter) {
    return (publishMetadata === BrandPublishMetadataFilter.AllBrands && !item.publishedTo)
        || (publishMetadata === BrandPublishMetadataFilter.PublishedBrands && item.publishedFrom)
        || (publishMetadata === BrandPublishMetadataFilter.AllEditableBrands && !item.publishedFrom);
}

// Helper methods for IItemFilter.getRelationToFilter() when the filter uses LibraryFilterOptions.

export function checkOwnerRelation(newOwnerSet: Set<LibraryOwnerFilter> = new Set([ LibraryOwnerFilter.All ]), existingOwnerSet: Set<LibraryOwnerFilter> = new Set([ LibraryOwnerFilter.All ])): ItemFilterRelation {
    const intersection = ModernSet.prototype.intersection.call(newOwnerSet, existingOwnerSet);
    const subset = intersection.size === newOwnerSet.size;
    if (subset) { return 'subset';} // all new values are in existing values

    const difference = ModernSet.prototype.symmetricDifference.call(newOwnerSet, existingOwnerSet);

    //Public libraries don't overlap with anything, including 'all'
    if (difference.has(LibraryOwnerFilter.Public)) {
        return 'disjoint';
    }

    // all other combinations are subsets of 'all'
    if (existingOwnerSet.has(LibraryOwnerFilter.All)) {
        return 'subset';
    }

    // newOwnerSet is a superset of existing owner set, because all includes all libraries
    if (newOwnerSet.has(LibraryOwnerFilter.All)) {
        return 'unknown';
    }

    if (difference.has(LibraryOwnerFilter.Discovery) && difference.has(LibraryOwnerFilter.Incoming)) {
        // If one filter is 'incoming', it may partially overlap with a 'discovery' filter,
        // regardless of what other filters are present, or which is pre-existing.
        if (newOwnerSet.has(LibraryOwnerFilter.Discovery) && existingOwnerSet.has(LibraryOwnerFilter.Incoming)
                || existingOwnerSet.has(LibraryOwnerFilter.Discovery) && newOwnerSet.has(LibraryOwnerFilter.Incoming)) {
            return 'unknown';
        }
    }

    if (intersection.size > 0) { return 'unknown'; } // some overlap
    return 'disjoint'; // no overlap since intersection.size === 0
}

export function checkRolesRelation(newRolesSet?: Set<LibraryRolesFilter>, existingRolesSet?: Set<LibraryRolesFilter>): ItemFilterRelation {
    if (newRolesSet && existingRolesSet) {
        return checkSetOverlap(newRolesSet, existingRolesSet);
    }
    if (newRolesSet || existingRolesSet) {
        return 'unknown';
    }
    // if both are undefined, we don't need to check roles. 'undefined' is equivalent to 'all roles'
    return 'subset';
}

export function checkProjectRelation(newProjectFilter?: LibraryProjectFilter, existingProjectFilter?: LibraryProjectFilter): ItemFilterRelation {
    if (newProjectFilter) {
        const checkIfIsProjId = (projectFilter: string): boolean => {
            // Assume that any projectFilter that is not one of the enum values is a project id
            return !Object.values(LibraryProjectFilterEnum).includes(projectFilter as LibraryProjectFilterEnum);
        };
        const subset = !existingProjectFilter // if existing project filter is undefined, that means it includes libraries that may or may not be in a project
            || newProjectFilter === existingProjectFilter
            || (checkIfIsProjId(newProjectFilter) && existingProjectFilter === LibraryProjectFilterEnum.All); // if project filter is 'all', that means the library must be in a project
        return subset ? 'subset' : 'disjoint';
    }
    if (!newProjectFilter && existingProjectFilter) {
        return 'unknown';
    }
    return 'subset';
}

export function checkPublishMetadataRelation(newPublishMetadataFilter?: BrandPublishMetadataFilter, existingPublishMetadataFilter?: BrandPublishMetadataFilter): ItemFilterRelation {
    // If there was no filter before or the filter has not changed, we can assume that the new filter is a subset of the existing filter
    if (!existingPublishMetadataFilter || newPublishMetadataFilter === existingPublishMetadataFilter) {
        return 'subset';
    }

    // If the new filter is for published brands and the existing filter is for all editable brands, they are inverse of each other and there is no overlap
    if (newPublishMetadataFilter === BrandPublishMetadataFilter.PublishedBrands && existingPublishMetadataFilter === BrandPublishMetadataFilter.AllEditableBrands) {
        return 'disjoint';
    }

    // The inverse is also true -- if the new filter is for all editable brands and the existing filter is for published brands, they are inverse of each other and there is no overlap
    if (newPublishMetadataFilter === BrandPublishMetadataFilter.AllEditableBrands && existingPublishMetadataFilter === BrandPublishMetadataFilter.PublishedBrands) {
        return 'disjoint';
    }

    // The "All brands" publish metadata filter will always include all published brands as well
    if (existingPublishMetadataFilter === BrandPublishMetadataFilter.AllBrands && newPublishMetadataFilter === BrandPublishMetadataFilter.PublishedBrands) {
        return 'subset';
    }

    return 'unknown';
}

/**
  * Checks the relation between the new reference filter and the existing reference filter.
  * @param newReference - The new reference filter
  * @param existingReference - The existing reference filter
  * @returns The relation between the new reference filter and the existing reference filter
  */
export function checkReferenceRelation(newReference?: LibraryReferenceFilter, existingReference?: LibraryReferenceFilter): ItemFilterRelation {

    // If the reference filter is the same, it's a subset
    if (newReference === existingReference) {
        return 'subset';
    }

    // All covers both Only and undefined
    if (existingReference === LibraryReferenceFilter.All) {
        return 'subset';
    }

    // If the new reference is All then the existing reference must not be All (because we made it here after the prior equality check)
    // the list can be partially built with the existing reference, so it's unknown
    if (newReference === LibraryReferenceFilter.All) {
        return 'unknown';
    }

    // new reference is undefined and existing reference is Only
    // new reference is Only and existing reference is undefined
    return 'disjoint';
}

function checkSetOverlap(newValuesSet: Set<string>, existingValuesSet: Set<string>): ItemFilterRelation {
    const intersection = ModernSet.prototype.intersection.call(newValuesSet, existingValuesSet);
    const subset = intersection.size === newValuesSet.size;

    if (subset) { return 'subset';} // all new values are in existing values
    if (intersection.size > 0) { return 'unknown'; } // some overlap
    return 'disjoint'; // no overlap since intersection.size === 0
}
