import { ManagedPromise } from '../utils/ManagedPromise';

class BatchOperationQueue<T extends { id: string }> {
    // Sets are guaranteed to be iterated in FIFO order
    private _itemQueue: Set<T> = new Set();
    private _itemPromises: Map<T, ManagedPromise<void>> = new Map();
    private _inFlightBatches: Set<{ batch: Set<T>, promise: Promise<void> }> = new Set();
    private _timer: any;

    constructor(
        private _batchProcessor: (items: Set<T>) => Promise<void>,
        private _maxItemsPerBatch: number = 50,
        private _delay: number = 50,
        private _maxInFlightBatches: number = 3
    ) {}

    enqueue(item: T): Promise<void> {
        // Already in progress
        if (this.isInQueue(item) || this.isInFlight(item)) {
            return this._itemPromises.get(item)!.promise;
        }
        this._itemQueue.add(item);
        const managedPromise = new ManagedPromise<void>();
        this._itemPromises.set(item, managedPromise);
        if (!this._timer) {
            this._timer = setTimeout(this._processQueue, this._delay);
        }
        // Don't wait to process the batch if a max-size batch request can be made
        if (this._itemQueue.size >= this._maxItemsPerBatch) {
            this._processQueue();
        }
        return managedPromise.promise;
    }

    dequeue(item: T): boolean {
        const hasItem = this._itemQueue.has(item);
        this._itemQueue.delete(item);
        // Only resolve if still pending, otherwise it is too late to dequeue and must wait for the batch result
        if (hasItem) {
            this._itemPromises.get(item)!.resolve();
            this._itemPromises.delete(item);
        }
        return hasItem;
    }

    /**
     * Called by batchProcessor implementation if it needs to mark some items in the batch as successes, and some
     * as failures. If it does neither, it will assume that resolving the batchProcessor means all succeeded, and
     * rejecting the batchProcessor will mean all failed.
     *
     * @param item {T}
     */
    resolveItemPromise(item: T): void {
        this._itemPromises.get(item)?.resolve();
        this._itemPromises.delete(item);
    }

    rejectItemPromise(item: T): void {
        this._itemPromises.get(item)?.reject();
        this._itemPromises.delete(item);
    }

    get size(): number {
        return this._itemQueue.size;
    }

    get inFlightCount(): number {
        return this._inFlightBatches.size;
    }

    isInQueue(item: T): boolean {
        return this._itemQueue.has(item);
    }

    isInFlight(item: T): boolean {
        return !![ ... this._inFlightBatches ].find(inFlightBatch => inFlightBatch.batch.has(item));
    }

    /**
     * Forces the queue to run all batches as fast as possible.
     *
     * @package -- for internal SAM.js use only
     */
    async _processNow(): Promise<void> {
        if (!this._itemQueue.size && !this._inFlightBatches.size) {
            // No work to do
            return;
        }
        do {
            this._processQueue();
            try {
                await Promise.race([ ...this._inFlightBatches ].map(batch => batch.promise));
            } catch (e) {
                // do nothing
            }
        } while (this._itemQueue.size);
    }

    private _processQueue = async () => {
        clearTimeout(this._timer);
        this._timer = undefined;

        try {
            if (this.inFlightCount >= this._maxInFlightBatches) {
                await Promise.race([ ...this._inFlightBatches ].map(inFlightBatch => inFlightBatch.promise));
            }
        } catch (e) {
            // Do nothing
        }

        while (this.inFlightCount <= this._maxInFlightBatches && this._itemQueue.size > 0) {
            const batch: Set<T> = new Set();
            while (this._itemQueue.size > 0 && batch.size < this._maxItemsPerBatch) {
                const item = this._itemQueue.values().next().value!;
                this._itemQueue.delete(item);
                batch.add(item);
            }

            // self-deleting batch Promise
            const inFlightBatch = {
                batch,
                promise: this._batchProcessor(batch)
                    .catch(() => { [ ...batch.values() ].forEach((item) => this.rejectItemPromise(item)); })
                    .finally(() => {
                        this._inFlightBatches.delete(inFlightBatch);
                        [ ...batch.values() ].forEach(item => this.resolveItemPromise(item));
                    })
            };
            this._inFlightBatches.add(inFlightBatch);
        }

        if (this._itemQueue.size > 0 && !this._timer) {
            this._timer = setTimeout(this._processQueue, this._delay);
        }
    };
}

export default BatchOperationQueue;
