import type { RenditionStatus } from '../utils/RenditionFetcher';
import { RenditionFetcher, RenditionType } from '../utils/RenditionFetcher';
import type { LibraryRenditionData, DataRenditionMimeTypes, LibraryObjectRenditions } from '../interface/LibraryModel';
import SAMError, { SAMErrorCode } from '../core/SAMError';
import { observable } from '../core/decorators';
import TypedEventEmitter from '../core/TypedEventEmitter';
import type { ItemBaseEvents } from '../core/ItemBase';
import type { ISAMCorePrivate, ISAMObject } from '../indexPrivate';
import type LibraryInterface from './LibraryInterface';

export const IMG_TILE_SIZE = 200;

export class RenditionTile extends TypedEventEmitter<ItemBaseEvents> implements ISAMObject {
    // 'href' rendition will be a BlobUrl for an image, a rendition of type
    // DataRenditionMimeTypes is an  object (e.g. with color or gradient data).
    type: 'href' | DataRenditionMimeTypes;
    elementId: string;
    elementType: string;
    mimetype?: DataRenditionMimeTypes; // This data is only received for non-image renditions.
    private readonly _renditionFetcher?: RenditionFetcher;
    /** @package -- for use in SAM.js only */
    public _renditionData?: LibraryObjectRenditions;
    /** @package -- for use in SAM.js only */
    public _renditionUrl?: string;

    constructor(
        data: LibraryRenditionData,
        /** @package -- only for use in SAM.js */
        public _index: number,
        /** @package -- only for use in SAM.js */
        readonly _core: ISAMCorePrivate,
        private _libraryInterface: LibraryInterface
    ) {
        super();
        this.type = data.type as 'href' | DataRenditionMimeTypes;
        if (this.type === 'href') {
            // Only image renditions have _renditionUrl.
            this._renditionUrl = data.rendition as string;
            // Only image renditions need a _renditionFetcher.
            this._renditionFetcher = new RenditionFetcher(
                this._core,
                [ IMG_TILE_SIZE ],
                async () => {
                    return this._libraryInterface.getRenditionTileImage(this._renditionUrl!);
                }
            );

            // Forward change events from the rendition fetcher
            // to this class (to catch the event from the fetcher).
            this._renditionFetcher.on('change', () => {
                this.dispatch({ type: 'change' });
            });
        } else {
            // Only non-image renditions have _renditionData and a mimetype.
            this._renditionData = data.rendition as LibraryObjectRenditions;
            this.mimetype = (data as { rendition_mimetype: DataRenditionMimeTypes }).rendition_mimetype;
        }
        this.elementId = data.elementId;
        this.elementType = data.elementType;
    }

    /**
     * Returns a blob url of an image based rendition. Returns an empty string while loading, and will
     * notify observers when the image is done loading and the blobURL is ready.
     * @example
     * imageUrl only applies to image renditions.
     * if (tile.type === 'href') return <img src={tile.imageUrl} />;
     */
    @observable
    get imageUrl(): string {
        if (this.type !== 'href') {
            throw SAMError.create(SAMErrorCode.UNKNOWN, 'Cannot fetch rendition for non-image renditions');
        }
        return this._renditionFetcher!.getURL(IMG_TILE_SIZE, RenditionType.PNG, this._renditionUrl!);
    }

    /**
     * Returns the rendition object for non-image based renditions (only applies to non-image renditions).
     * @example
     * if (tile.type !== 'href') return <div>{tile.data} </div>;
     */
    get data(): object {
        if (this.type !== 'href') {
            if (typeof this._renditionData === 'object') {
                return this._renditionData;
            }
            console.warn('Rendition data is not an object, returning default value.');
            return {};
        } else {
            throw SAMError.create(SAMErrorCode.UNKNOWN, 'Cannot get data for image renditions');
        }
    }

    /**
     * Returns one of the enumeration values of RenditionStatus.
     *
     * @returns {RenditionStatus}
     */
    @observable
    get imageStatus(): RenditionStatus {
        return this._renditionFetcher!.renditionURLStatus(IMG_TILE_SIZE, RenditionType.PNG, this._renditionUrl!);
    }

    /**
     * For use internally to release renditions after
     * the asset has been deleted permanently.
     * @package
     */
    _releaseRenditions() {
        if (this._renditionFetcher) {
            this._renditionFetcher.release();
        }
    }
}

