import ItemBase from '../core/ItemBase';
import type ISAMCorePrivate from '../core/ISAMCorePrivate';
import type { IAddressBookContact } from '../interface/AddressBookModel';
import { observable } from '../core/decorators';
import ItemUpdater from '../core/ItemUpdater';
import PropertyUpdater from '../core/PropertyUpdater';

class AddressBookContact extends ItemBase {
    private _countryCode: string = '';
    private _displayName: string = '';
    private _email: string = '';
    private _firstName: string = '';
    private _lastName: string = '';
    private _addressBookIdent: string = '';
    private _images: Record<string, string> = {};
    private _linkPolicy?: IAddressBookContact['linkPolicy'];
    private _linkedIdentity: string = '';
    private _urn: string = '';
    constructor(core: ISAMCorePrivate, id: string) {
        super(core, id);
    }

    get ident(): string {
        return this.id;
    }

    @observable
    get countryCode(): string {
        return this._countryCode;
    }

    @observable
    get displayName(): string  {
        return this._displayName;
    }

    @observable
    get email(): string {
        return this._email;
    }

    @observable
    get firstName(): string {
        return this._firstName;
    }

    @observable
    get lastName(): string {
        return this._lastName;
    }

    @observable
    get addressBookIdent(): string {
        return this._addressBookIdent;
    }

    @observable
    get images(): Record<string, string> {
        return this._images;
    }

    @observable
    get linkPolicy(): IAddressBookContact['linkPolicy'] | undefined {
        return this._linkPolicy;
    }

    @observable
    get linkedIdentity(): string {
        return this._linkedIdentity;
    }

    @observable
    get urn(): string {
        return this._urn;
    }
}

export const AddressBookContactUpdater = new ItemUpdater<AddressBookContact, IAddressBookContact>({
    localItemType: AddressBookContact,
    remoteIdProperty: 'ident',
    propertyUpdater: new PropertyUpdater({
        _countryCode: 'countryCode',
        _displayName: 'displayName',
        _email: 'email',
        _firstName: 'firstName',
        _addressBookIdent: 'addressBookIdent',
        _images: { format: 'object', name: 'images' },
        _lastName: 'lastName',
        _linkPolicy: 'linkPolicy',
        _linkedIdentity: 'linkedIdentity',
        _urn: 'urn'
    })
});

export default AddressBookContact;

