import type AdobeAsset from '../assets/AdobeAsset';
import type { IComparatorMap } from '../core/ItemOrder';
import { compareValues, createItemOrderFactory } from '../core/ItemOrder';

export type FavoriteAdobeAssetOrderField = 'created' | 'name';

const OrderFieldToComparator: IComparatorMap<AdobeAsset, FavoriteAdobeAssetOrderField> = {
    created(a: AdobeAsset, b: AdobeAsset): number {
        return compareValues(a.created, b.created);
    },
    name(a: AdobeAsset, b: AdobeAsset): number {
        return compareValues(a.name, b.name);
    }
};

// This sort order will eventually be moved to a generic sort order for all GraphQL sort options.
/**
 * @experimental
 */
export default class FavoriteAdobeAssetOrder extends createItemOrderFactory(OrderFieldToComparator) {
    static default = new FavoriteAdobeAssetOrder('descending', 'created');
}
