// @TODO
// This needs a little more thought. The test cases and real world cases are not clear
// replacing words in the string with a dot(.) does not make a lot of sense to me
// and the removal of the last .0 is also a little strange.
// This can be cleaned up and should be but this is pulled directly from cc-libraries-api-js and its well tested
// https://git.corp.adobe.com/ProjectCentral/cc-libraries-api-js/blob/80ebed61ec41b980495c485fe17a6f1bbd5d1b5c/src/utils/AdobeLibraryGeneralUtils.js#L74
function sanitizeVersionInput(version: string) {
    // After effects does not use semver. They append a x before the build number.
    // We need to replace that with a .
    version = version
        .toString()
        .replace(/(\.0)*$/, '')
        .replace(/[^.0-9]+/gim, '.');
    // Workaround for Illustrator CS6 & Illustrator CC returning version as CS6 and the build number instead of semver
    if (isNaN(parseInt(version, 10)) || parseInt(version, 10) > 250) {
        version = '0';
    }
    return version;
}

export function compareVersions(version1 = '0', version2 = '0') {
    if (version1 === version2) {
        return 0;
    }

    const a1 = sanitizeVersionInput(version1).split('.');
    const a2 = sanitizeVersionInput(version2).split('.');

    let diff;
    for (let i = 0; i < a1.length && i < a2.length; i++) {
        const a1Part = parseInt(a1[i], 10);
        diff = a1Part - parseInt(a2[i], 10);
        if (isNaN(diff)) {
            if (isNaN(a1Part)) {
                return 1;
            }
            return -1;
        }
        if (diff > 0) {
            return -1;
        }
        if (diff < 0) {
            return 1;
        }
    }
    diff = a1.length - a2.length;
    return diff > 0 ? -1 : diff < 0 ? 1 : 0;
}
