import type { SAM } from '@ccx-public/component-types';

import type AdobeAsset from '../assets/AdobeAsset';
import type AssetLinkManager from './AssetLinkManager';
import type { LinkReference } from './AssetLink';
import AssetLink from './AssetLink';
import { observable } from '../core/decorators';
import oneTimeWarning from '../utils/oneTimeWarning';
import { SAMObjectUntypedEventEmitter } from '../core/SAMObjectEventEmitter';

export default class AssetLinkList extends SAMObjectUntypedEventEmitter implements SAM.AssetLinkList {
    private _links: Set<AssetLink> = new Set();

    // We store directly monitored asset ids as a map, where the key is the lower case
    // asset id, and the value is the asset id passed in. This allows us to easily look
    // up the original case of the asset id passed in, so we can send notifications in
    // the correct case, in case a client passed it in with the wrong case
    private _directlyMonitoredAssetIDs: Map<string, string> = new Map();

    constructor(
        public _manager: AssetLinkManager,
        private _containerAsset?: AdobeAsset
    ) {
        super(_manager._core);
    }

    _onChange = () => {
        this.emit('change');
    };

    private _refreshLinks = (changedIDs: Set<string> = new Set(this.monitoredAssetIDs)) => {
        this.forEach(link => {
            if (!link.adobeAsset && changedIDs.has(link.assetID)) {
                // Link is broken, but asset id changed - try re-resolving
                link._resolveWithRetry();
            }
            // Note - we do not need to refresh any assets; this will be handled by AssetContext
            // since it's updating all the assets in the asset pool.
        });
    };

    _refreshLinksForChangedAssets = (changedIDs: Set<string>) => {
        this._refreshLinks(changedIDs);

        // As well as refreshing changed links, we emit a notified event, so clients can know that
        // we were notified of a change to these assets - this is useful if clients are only monitoring
        // asset ids directly, not via links.
        // Compute the intersection of changedIDs and the ones we're monitoring:
        const monitoredAssetIDs = this._monitoredAssetIDs;
        const monitoredChangedIDs = new Set();
        changedIDs.forEach(id => {
            if (monitoredAssetIDs.has(id)) {
                monitoredChangedIDs.add(id);
            }
            // The client might have passed in an asset id in a different case to the normalized
            // platform case (e.g. clients like CC Libraries might have some older cached client
            // ids). We therefore need to map the asset id we get from the notification to the
            // one passed in.
            const normalizedId = this._directlyMonitoredAssetIDs.get(id.toLowerCase());
            if (normalizedId) {
                monitoredChangedIDs.add(normalizedId);
            }
        });
        this.emit('notified', [ ...monitoredChangedIDs ]);
    };

    /**
     * Monitor an asset id directly, rather than going through an AssetLink. This allows you to monitor
     * a specific asset for changes without maintaining any state (i.e. it will not resolve the assetID
     * to an AdobeAsset).
     *
     * This is a lower-level API and should only be used if you're explicitly not wanting to load the
     * asset with SAM (for example, the CC Libraries API uses this since it fetches the asset data
     * from Melville, rather than R-API via SAM, so it just needs the raw notification).
     */
    addAssetID(assetID: string) {
        this._directlyMonitoredAssetIDs.set(assetID.toLowerCase(), assetID);
        this._onChange();
    }

    /**
     * Stop monitoring an asset id that was added via `addAssetId()`. Note that if any links in the list
     * also reference this asset id, this will not stop monitoring them.
     */
    removeAssetID(assetID: string) {
        this._directlyMonitoredAssetIDs.delete(assetID.toLowerCase());
        this._onChange();
    }

    /**
     * Add one or more existing links (from link reference or link reference strings) to the list.
     */
    add(linkReferences: (string | LinkReference)[]): Promise<AssetLink[]> {
        return Promise.all(linkReferences.map(async linkRef => {
            // TODO: Should check if already have duplicate link
            const linkReference = typeof linkRef === 'string' ? JSON.parse(linkRef) : linkRef;
            const link = new AssetLink(this, linkReference);
            this._links.add(link);
            this._onChange();
            // When adding an existing link we can always return an AssetLink even if it fails
            // We'll retry the resolution after which the link state will update.
            await link._resolveWithRetry();
            return link;
        }));
    }

    /**
     * Create a new link from an asset, and add it to the list.
     * @param asset
     * @param [fragmentSpecifier] An optional string containing the fragmentSpecifier within the asset.
     * @param [version] An optional string containing the version identifier of the Adobe asset.
     */
    async create(asset: AdobeAsset | string, fragmentSpecifier?: string, version?: string): Promise<AssetLink> {
        const assetID = typeof asset === 'string' ? asset : asset.cloudID;
        const link = new AssetLink(this, {
            'repo:assetId': assetID,
            'stRef:fromPart': fragmentSpecifier,
            'repo:version': version,
            'stRef:manager': 'Adobe Cloud'
        });
        this._links.add(link);
        this._onChange();
        // When creating a new link, we do _not_ retry on failure - this is because the link reference needs to be updated.
        // Errors are propagated to the client.
        await link._resolve();
        if (link.adobeAsset) {
            link._setLinkedAsset(link.adobeAsset);
        }
        return link;
    }

    /**
     * Remove an asset link from the list. This will cause it to stop being actively monitored for changes.
     */
    remove(link: AssetLink) {
        this._links.delete(link);
        this._onChange();
    }

    /**
     * Clear the whole list.
     */
    clear() {
        this._links.clear();
        this._onChange();
    }

    /**
     * Number of asset links in the list.
     */
    @observable
    get count() {
        return this._links.size;
    }

    /**
     * Get an array of all the asset links in the list.
     */
    @observable
    get links(): AssetLink[] {
        return [ ...this._links ];
    }

    /**
     * Get a set of all the asset ids being monitored by the link list. This includes
     * asset ids in any links, as well as asset ids being directly monitored.
     */
    private get _monitoredAssetIDs(): Set<string> {
        const assetIDs: Set<string> = new Set(this._directlyMonitoredAssetIDs.values());
        this.forEach(link => {
            assetIDs.add(link.assetID);
            // We also monitor the path-based resolution if it differs from asset-based:
            if (link.alternativeAdobeAsset) {
                assetIDs.add(link.alternativeAdobeAsset.cloudID);
            }
        });
        return assetIDs;
    }

    /**
     * Get an array of all the asset ids being monitored by the link list. This includes
     * asset ids in any links, as well as asset ids being directly monitored.
     */
    @observable
    get monitoredAssetIDs(): string[] {
        return [ ...this._monitoredAssetIDs ];
    }

    /**
     * Iterate through all the asset links in the list.
     */
    @observable
    forEach(callback: (link: AssetLink) => void) {
        this._links.forEach(callback);
    }

    /**
     * Get the container asset for the link list (the document that contains the links)
     */
    @observable
    get containerAsset(): AdobeAsset | undefined {
        return this._containerAsset;
    }

    /**
     * Marks a list as active so that the asset link manager can actively start monitoring all the asset links in it.
     * @param [duration] If a duration is specified (in ms), the list will automatically deactivate after this time. Otherwise it will remain active.
     * @deprecated This method is deprecated - lists are always monitored for notifications unless you pass in DISABLE_ONS when initializing SAM.
     *    Will be removed on or after 2024-10-01.
     */
    activate(duration: number = 0) {
        oneTimeWarning('AssetLinkList.activate', `AssetLinkList.activate(${duration}) is deprecated - lists are always monitored for notifications.`
         + `This method will be removed on or after 2024-10-01.`);
    }

    /**
     * Deactivate a list so that the asset link manager can stop monitoring all the asset links in it.
     * @deprecated This method is deprecated - lists are always monitored for notifications unless you pass in DISABLE_ONS when initializing SAM.
     *    Will be removed on or after 2024-10-01.
     */
    deactivate() {
        oneTimeWarning('AssetLinkList.deactivate', 'AssetLinkList.deactivate() is deprecated - lists are'
            + ' always monitored for notifications. This method will be removed on or after 2024-10-01.');
    }

    /**
     * Whether the list is active (asset links in it are actively monitored for changes or not).
     * @deprecated This method is deprecated - lists are always monitored for notifications unless you pass in DISABLE_ONS when initializing SAM.
     *    Will be removed on or after 2024-10-01.
     */
    @observable
    get isActive(): boolean {
        oneTimeWarning('AssetLinkList.isActive', 'AssetLinkList.isActive is deprecated - lists are always'
            + ' monitored for notifications. This method will be removed on or after 2024-10-01.');
        return true;
    }

    /**
     * Change the container asset associated with this list (the document that contains the links in the list)
     * This will change relative path based resolution of the links
     */
    async updateContainerAsset(containerAsset: AdobeAsset) {
        this._containerAsset = containerAsset;
        this._onChange();
        // Need to resolve all the links again, because the relative path could have changed
        await Promise.all(Array.from(this._links).map(link => link._resolveWithRetry()));
    }

    /**
     * Clone the asset list for a another container asset (adding it to this list)
     */
    clone(assetLinkList: AssetLinkList) {
        // TODO: Need to trigger all links to re-resolve, since relative path resolution may have changed
        assetLinkList.links.forEach(link => this._links.add(link));
    }
}
