import type { IComparatorMap } from '../core/ItemOrder';
import { compareStrings, createItemOrderFactory } from '../core/ItemOrder';
import type ClassroomMember from './ClassroomMember';

export type ClassroomMemberOrderField =
    | 'name';

const OrderFieldToComparator: IComparatorMap<ClassroomMember, ClassroomMemberOrderField> = {
    name(a: ClassroomMember, b: ClassroomMember): number {
        return compareStrings(a.displayName, b.displayName);
    },
};

export default class ClassroomMemberOrder extends createItemOrderFactory(OrderFieldToComparator) {
    static default = new ClassroomMemberOrder('ascending', 'name');
}
