import { SAM } from '@ccx-public/component-types';
import Logger from '../utils/Logger';
import { SAMError } from '@sam-js-src/core/SAMError';

type Code =
    | 'UNAUTHORIZED'
    | 'INVALID_CREDENTIALS'
    | 'REQUEST_TIMEOUT'
    | 'PRECONDITION_FAILED'
    | 'GENERIC_ERROR'
    | 'UNEXPECTED_RESPONSE'
    | 'MALFORMED_RESPONSE'
    | 'NOT_MODIFIED'
    | 'OUT_OF_SPACE'
    | 'NOT_FOUND'
    | 'FS_ERROR'
    | 'ENOENT'
    | 'INVALID_DATA';

function ConvertErrorCode(requestErrorCode: Code): SAM.SAMErrorCode {
    switch (requestErrorCode) {
    case 'UNAUTHORIZED':
    case 'INVALID_CREDENTIALS':
        return SAM.SAMErrorCode.AUTHORIZATION_ERROR;
    case 'REQUEST_TIMEOUT':
        return SAM.SAMErrorCode.REQUEST_TIMED_OUT;
    case 'OUT_OF_SPACE':
        return SAM.SAMErrorCode.FULL_LOCAL_DISK_SPACE;
    case 'NOT_FOUND':
    case 'ENOENT':
        return SAM.SAMErrorCode.NOT_FOUND;
    case 'PRECONDITION_FAILED':
    case 'GENERIC_ERROR':
    case 'UNEXPECTED_RESPONSE':
    case 'MALFORMED_RESPONSE':
    case 'NOT_MODIFIED':
    case 'FS_ERROR':
    case 'INVALID_DATA':
    default:
        return SAM.SAMErrorCode.UNKNOWN;
    }
}

export default class RequestError extends SAMError {
    private _requestErrorCode: Code;
    private _response?: Response;

    static isRequestError(error: Error): error is RequestError {
        return !!(error as RequestError).code;
    }

    constructor(code: Code, message: string, response?: Response, underlyingError?: Error) {
        super(ConvertErrorCode(code), message, { underlyingError });
        this._requestErrorCode = code;
        this._response = response;
    }

    get requestErrorCode() {
        return this._requestErrorCode;
    }

    get response() {
        return this._response;
    }

    get underlyingError() {
        return this._additionalInfo.underlyingError as Error;
    }

    set underlyingError(error: Error) {
        this._additionalInfo.underlyingError = error;
    }

    setResponse(response: Response) {
        if (!this.response) {
            this._response = response;
        } else {
            Logger.warn('Request Error response reference is already set.');
        }

        return this;
    }
}

export function getRequestError(response: Response, errorCode?: String) {
    return getRequestErrorFromStatus(response?.status, errorCode as Code).setResponse(response);
}

export function getRequestErrorFromStatus(statusCode: number, errorCode?: Code) {
    switch (statusCode) {
    case 304:
        return new RequestError('NOT_MODIFIED', 'Response has not changed.');
    case 401:
        return new RequestError('UNAUTHORIZED', 'Token expired or invalid');
    case 403:
        return new RequestError('INVALID_CREDENTIALS', 'You do not have access to this resource.');
    case 404:
        return new RequestError(errorCode === 'ENOENT' ? errorCode : 'NOT_FOUND', 'Resource not found');
    case 408:
        return new RequestError('REQUEST_TIMEOUT', 'Server could not respond in a timely manner');
    case 412:
        return new RequestError('PRECONDITION_FAILED', 'This resource does not match the requisite conditions.');
    case 422:
        return new RequestError('INVALID_DATA', 'Library is corrupt, unzipping failed.');
    case 507:
        return new RequestError('OUT_OF_SPACE', 'Hard disk ran out of space.');
    default:
        return new RequestError('GENERIC_ERROR', `Something went wrong: ${statusCode}`);
    }
}

export function getSAMRequestError(error: SAMError) {
    const err = getRequestError(error._additionalInfo.response as Response);
    err.underlyingError = error;
    return err;
}
