export type CombinedId = ItemId & `${ItemId}#${ItemId}`;
export type ElementPoolId = CombinedId | PlaceholderIdType;
export const extractElementId = (path: CombinedId): ItemId => {
    return path.split('#')[1];
};

export function getCombinedId(data: Partial<ElementData>): CombinedId {
    return `${data.libraryAssetId}#${data.id}`;
}

export function getCombinedIdOrPlaceholder(data: Partial<ElementData>): ElementPoolId {
    if (!data.id) {
        throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Element data requires an id');
    }
    return isPlaceholder(data.id) ? data.id : getCombinedId(data);
}

// @initializesCaches
export default class Element extends PublishedModel<ElementData> {
    /* New private APIs to replace _data APIs [incomplete] */
    // Note: Since the Store has a special _data property, wherein element data must be defined, we might as
    // well keep that as the source of truth and reference it here. If it weren't for that, we could have deprecated ElementData
    // and moved all its types here.
    private _roles?: ElementData['roles'];
    private _description?: ElementData['description'];
    private _descriptionModifiedDate?: ElementData['descriptionModifiedDate'];
    private _descriptionModifiedBy?: ElementData['descriptionModifiedBy'];
    private _descriptionModifiedContext?: ElementData['descriptionModifiedContext'];
    private _descriptionModifiedLocally?: ElementData['descriptionModifiedLocally'];
    private _modifiedDate?: ElementData['modifiedDate'];
    private _modifiedBy?: ElementData['modifiedBy'];
    private _modifiedContext?: ElementData['modifiedContext'];
    private _modifiedLocally?: ElementData['modifiedLocally'];
    private _createdDate?: ElementData['createdDate'];
    private _createdBy?: ElementData['createdBy'];
    private _createdContext?: ElementData['createdContext'];
    private _createdLocally?: ElementData['createdLocally'];
    private _tags?: ElementData['tags'];
    private _customData?: ElementData['customData'];
    private _dependencyIds?: ElementData['dependencyIds'];
    private _elementRef?: ElementData['elementRef'];
    private _autoName?: ElementData['autoName'];
    private _libraryAssetId?: ElementData['libraryAssetId']; // TODO-R: Verify melville response format. Their MIA documentation just says "libraryIdentifier" but i don't think that's accurate, sigh.
    // The following properties are not optional in ElementData, so we added
    // default values to avoid undefined checks, with the assumption being that these values
    // should be defined through _update() before calling dependent code.
    // If you run into these default unexpectedly, then you are failing to update the element properly.
    // (Previously defaults were not required because ElementData was required by the constructor.)
    private _groups: ElementData['groups'] = [] as ElementData['groups'];
    /**
     * @package -- for use in SAM.js only
     */
    private _name: ElementData['name'] = '';
    private _type: ElementData['type'] = '' as ElementMimeType;

    isElement = true;
    protected _updateAction: ActionName = 'updateElement';

    protected _lastLocalUpdateDate = 0;
    /**
     * @package -- only for use in SAM.js
     */
    protected _updater!: typeof ElementUpdater;
    /**
     * @package -- only for use in SAM.js
     */
    protected _itemPool!: ItemPool<Element, ElementPoolId>;
    /**
     * @package -- only for use in SAM.js
     */
    _ChildClass = Representation;

    private _elementId!: ItemId;

    // TODO-R: Because element may be created by UpdateSession, we cannot expect parent to be passed in.
    // However, we should probably refactor the remoteUpdate to handle passing in the parent to avoid the issues noted below in libraryContents
    constructor(core: ISAMCorePrivate, id: ElementPoolId) {
        super(core, id);
        this._updater = this._apiRoot.elementUpdater;
        this._itemPool = this._apiRoot.elementPool;
        this._elementId = isPlaceholder(id) ? id : extractElementId(id);
    }

    // Note: Previously, we could pass the parent directly into the Element constructor.
    // With the ItemUpdater pattern, only the id is passed in upon instantiation, and the data, including the parent id, is updated later.
    // In order to avoid breaking APIs depending on the library (or libraryContents) APIs being defined,
    // we need to throw an error here if the libraryAssetId is undefined. We can revisit this strategy if it becomes a problem.
    // In other words, we assume that in production the libraryAssetId will always be defined in an Element Response.
    // TODO-R: Need to verify Melville response format to ensure this assumption is correct.
    get libraryContents(): LibraryContents {
        if (!this._parent) {
            if (!this._libraryAssetId) { throw Error('Element._libraryAssetId is not defined, so we cannot find the Library or LibraryContents.'); }
            const library = this._core._getAssetPool().getLocalItemById(this._libraryAssetId!) as SAMLibrary;
            this._parent = library._getContentsSync(); // We assume LibraryContents is already loaded given this Element wouldn't exist otherwise.
        }
        return this._parent as LibraryContents;
    }

    get library(): SAMLibrary {
        // Rather than holding a reference to the library directly, the element holds a reference to its parent LibraryContents,
        // which in turn points to its parent library.
        return this.libraryContents.library;
    }

    get elementId(): ItemId {
        return this._elementId;
    }

    /**
     * The mimetype of the library element
     */
    get type(): string {
        return this._type;
    }

    /**
     * The date the library element was modified
     */
    @observable
    get modified(): Date {
        return new Date(Math.max(this._modifiedDate as number, this._lastLocalUpdateDate));
    }

    /**
     * The date the library element was created
     */
    @observable
    get created(): Date {
        return new Date(this._createdDate as number);
    }

    /**
     * The instanceID (in the case of a library) or fromPartInstanceID (in the case of a fragment),
     * is used to tell if the content of a link is out of date in the new link reference schema.
     * For elements, we use the primary representation id, which changes every time a change is made to the element.
     * Since there is no content that can change when there's no representation, this will be undefined in that case.
     *
     * Note that the InstanceID has to be a guid as per XMP semantics -- modified dates are not unique enough.
     * This is important primarily for references to library elements,
     * since they will be exposed in XMP as well, as part of the content graph.
     *
     */
    get instanceId(): string | undefined {
        const primaryRepresentation = this.getPrimaryRepresentation();
        return primaryRepresentation?.id;
    }

    /**
     * Get a unique link reference for the element, which is a JSON object using the [link schema](https://git.corp.adobe.com/caf/xcm/blob/master/schemas/cc/link/link.schema.json).
     * This reference can be used anytime to retrieve this element.
     * For more information on linking architecture, see [here](https://wiki.corp.adobe.com/pages/viewpage.action?spaceKey=ccexperience&title=Linking+Architecture).
     */
    // TODO-R[SHARED-3693]: We may need to make this async given that the library may not have melville data loaded yet.
    getReference(): LinkReference {
        const linkData: LinkReference = {
            'dc:format': this.library.mediaType,
            'repo:assetId': this._libraryAssetId as string,
            'repo:name': this.library.displayName, // important to include the library name to use in broken link messaging
            'stRef:manager': 'Adobe Cloud',
            'stRef:documentID': this.library.libraryManifestId,
            'stRef:fromPart': `id=${this.id}`, // fragment id
            'stRef:fromPartName': this.name
        };

        if (this.instanceId) {
            linkData['stRef:fromPartInstanceID'] = this.instanceId;
        }

        if (this.sourceRef) {
            // If this element is derived from a different cloud asset, include the reference to it as well.
            // But if the element is derived from the Firefly mimetype, then avoid sending this field
            // because the Firefly mimetype is still being developed and so the sourceRef is still incomplete
            if (this.sourceRef['dc:format'] !== 'application/vnd.adobe.firefly-recipe+dcx') {
                linkData['stRef:fromPartDerivedFrom'] = this.sourceRef;
            }
        }

        return linkData;
    }

    /**
     * Get the serialized version of the unique link reference for the element, returned from getReference()
     * Getting the object through getReference() is typically more useful and skips serialization steps,
     * but the serialized string is useful to compare reference equality, since we take care of sorting the object.
     */
    getReferenceString(): Stringified<LinkReference> | string {
        const reference = this.getReference();
        return serializeLinkReference(reference);
    }

    // Legacy references are still used by clients that have not migrated to the new link format yet.
    getLegacyReference(): string {
        return this._elementRef ?? `cloud-asset://${this.library.id};node=${this.id}`;
    }

    /**
     * The display name of the element
     */
    @observable
    @requiresWrite
    get name(): string {
        if (this.isAutoNamed) {
            return getGeneratedName(this);
        }

        return this._name;
    }

    set name(name: string) {
        this._actionDispatch({
            name: 'updateElement',
            type: 'update',
            data: {
                name: name?.normalize()
            }
        });
    }

    /**
     * Was this element named automatically?
     */
    // TODO-R[SHARED-5404]: This seems buggy. Melville only returns isAutoNamed, not autoName. rapi data from the LocalDriver returns both.
    // May need to add optional autoName = name to Melville mapping for Elements.
    @observable
    get isAutoNamed(): boolean {
        const name = this._name;
        const autoName = this._autoName;
        // An element is auto-named if it doesn't have a name, or its auto-name equals its name.
        // This lets us detect if older clients renamed an element without updating its name,
        // since they wouldn't update the autoName field.
        return !name || name === autoName;
    }

    /**
     * Is the element editable?
     */
    @observable
    get isWritable(): boolean {
        return this.library.hasPermission(Permission.Write);
    }

    /**
     * The tags (strings) associated with the element
     */
    @observable
    @requiresWrite
    get tags(): string[] {
        return this._tags || [];
    }

    set tags(tags: string[]) {
        this._actionDispatch({
            name: 'updateElement',
            type: 'update',
            data: { tags }
        });
    }

    /**
     * The dependencies for the element (other elements)
     */
    @observable
    async getDependencies(): Promise<Element[]> {
        const elements: Element[] = [];

        // TODO-R[SHARED-5423] Optimize Element.getDependencies fetches
        if (this._dependencyIds) {
            for (const dependencyID of this._dependencyIds) {
                const element = await this.libraryContents.getElementById(dependencyID);
                if (element !== this) {
                    elements.push(element);
                }
            }
        }

        return elements;
    }

    @requiresWrite
    setDependencies(elements: Element[]) {
        const dependencyIds = elements.map(element => element.id);
        this._actionDispatch({
            name: 'updateElement',
            type: 'update',
            data: { dependencyIds }
        });
    }

    /**
     * Why does this exist?
     * @deprecated
     */
    @requiresWrite
    createGroup() {
        // TODO
    }

    @observable
    getGroups(_classifier: string = '$default'): Group[] {
        // TODO: Implement this once new groups API decided
        // return this.library.getGroups(classifier).filter(group => {
        //     return this._groups.find(membership => membership.id === group.id);
        // });
        return [] as Group[];
    }

    @observable
    getOrderInGroup(group: Group): string | undefined {
        if (group.library !== this.library) {
            return;
        }

        const groupMembership = this._groups.find(
            membership => membership.classifier === group.classifierName && membership.id === group.id
        );
        return groupMembership && groupMembership.order;
    }

    @requiresWrite
    setOrderInGroup(group: Group, order: string, removeExistingGroups: boolean = true): void {
        const groups = removeExistingGroups
            ? this._groups.filter(gr => gr.classifier !== group.classifierName)
            : [ ...this._groups ];
        const index = this._groups.findIndex(({ id }) => id === group.id);
        const groupMembership = {
            id: group.id,
            classifier: group.classifierName,
            order
        };

        if (!order && index !== -1) {
            groups.splice(index, 1);
        } else if (order && index !== -1) {
            groups.splice(index, 1, groupMembership);
        } else if (index === -1) {
            groups.push(groupMembership);
        }

        this._actionDispatch({
            name: 'updateElement',
            type: 'update',
            data: { groups }
        });
    }

    @observable
    @requiresWrite
    get description(): string {
        return this._description as string;
    }

    set description(description: string) {
        this._actionDispatch({
            name: 'updateElement',
            type: 'update',
            data: { description }
        });
    }

    @observable
    get descriptionModified(): Date {
        return new Date(this._descriptionModifiedDate as number);
    }

    @observable
    get descriptionModifiedBy(): string {
        return this._descriptionModifiedBy as string;
    }

    @observable
    get descriptionModifiedContext(): UpdateContext {
        return this._descriptionModifiedContext as UpdateContext;
    }

    @observable
    get wasDescriptionModifiedLocally(): boolean {
        return this._descriptionModifiedLocally as boolean;
    }

    @observable
    get modifiedBy(): string {
        return this._modifiedBy as string;
    }

    @observable
    get modifiedContext(): UpdateContext {
        return this._modifiedContext as UpdateContext;
    }

    @observable
    get wasModifiedLocally(): boolean {
        return this._modifiedLocally as boolean;
    }

    @observable
    get createdBy(): string {
        return this._createdBy as string;
    }

    @observable
    get createdContext(): UpdateContext {
        return this._createdContext as UpdateContext;
    }

    @observable
    get wasCreatedLocally(): boolean {
        return this._createdLocally as boolean;
    }

    @observable
    get isDeletedLocally(): boolean {
        return false;
    }

    beginOperation() {
        return this.libraryContents.beginOperation();
    }
    endOperation(callback?: () => void): Promise<void> {
        return this.libraryContents.endOperation(callback);
    }

    @observable
    get representations(): Representation[] {
        return this._children;
    }

    @observable
    getPrimaryRepresentation(): Representation | undefined {
        return this.representations.find(representation => representation.relationship === 'primary');
    }

    @observable
    getRepresentationById(id: string): Representation | undefined {
        return this.representations.find(representation => representation.id === id);
    }

    @requiresWrite
    createRepresentation(
        type: string,
        relationship: 'primary' | 'rendition',
        _index?: number,
        _preserveThumbnail?: boolean
    ): Representation {
        const id = createPlaceholderId();
        const representations = [ ...this._childrenData ];
        representations.splice(1, 0, {
            id,
            type,
            relationship,
            isFullSize: false,
            isExternalLink: false
        });

        this._actionDispatch({
            name: 'updateElementContent',
            type: 'update',
            data: {
                representations
            }
        });

        return this.getRepresentationById(id) as Representation;
    }

    @requiresWrite
    removeRepresentation(representation: Representation): void {
        const representations = [ ...this._childrenData ];
        const index = representations.findIndex(rep => rep.id === representation.id);

        if (index === -1) {
            return;
        }

        representations.splice(index, 1);

        this._actionDispatch({
            name: 'updateElementContent',
            type: 'update',
            data: {
                representations
            }
        });
    }

    @requiresWrite
    removeAllRepresentations(): void {
        this._actionDispatch({
            name: 'updateElementContent',
            type: 'update',
            data: {
                renditionUrl: {},
                representations: []
            }
        });
    }

    @observable
    getValue(namespace: string, key: string): any {
        return this._customData?.[`${namespace}#${key}`];
    }

    @observable
    getValues(): { namespace: string; key: string; value: any }[] {
        return mapAttributesToArray(this._customData as { [s: string]: any });
    }

    @requiresWrite
    setValue(namespace: string, key: string, value: any): void {
        this._actionDispatch({
            name: 'updateElement',
            type: 'update',
            data: {
                customData: {
                    [`${namespace}#${key}`]: value
                }
            }
        });
    }

    @requiresWrite
    removeValue(namespace: string, key: string): void {
        this.setValue(namespace, key, null);
    }

    getThumbnailURL(size: RenditionSize): string {
        return this._driver.getRenditionUrl(this, size);
    }

    async getThumbnailPath(size: RenditionSize = 'full'): Promise<string> {
        await this.committed;
        return this._driver.getRenditionPath(this.library.id, this.id, size);
    }

    getThumbnailContent(size: RenditionSize): Promise<Blob> {
        return this._driver.getRendition(this, size).then(res => res.blob());
    }

    @observable
    supportsVectorThumbnail(): boolean {
        const primary = this.getPrimaryRepresentation();
        if (primary) {
            return LibraryConstants.VECTOR_RENDITION_ELEMENT_TYPES.includes(primary.type);
        }
        return false;
    }

    @observable
    getActions(actionId: ActionType): ApplicationAction[] {
        const representation = this.getPrimaryRepresentation();

        if (!representation) {
            return [];
        }

        if (this.library.documentType) {
            const docProductMap = this._apiRoot.getOption('DOCUMENT_LIBRARY_ACTION_PRODUCT_MAP');
            const docCodes = (docProductMap.types as any)[this.library.documentType] || [];
            return constructActions(this.library, actionId, docCodes, docProductMap.products) as ApplicationAction[];
        }

        const productMap = this._apiRoot.getOption('ELEMENT_ACTION_PRODUCT_MAP');
        const representationTypeMap = (productMap.types as any)[this.type] || {};
        const codes = representationTypeMap[representation.type] || [];
        return constructActions(this, actionId, codes, productMap.products) as ApplicationAction[];
    }

    @observable
    @requiresWrite
    get roles(): Role[] {
        return this._roles || [];
    }

    set roles(roles: Role[]) {
        this._actionDispatch({
            name: 'updateElement',
            type: 'update',
            data: { roles }
        });
    }

    get isStockAsset(): boolean {
        const isSupportedElementType = Object.values(ElementMimeTypeMap).includes(this.type as ElementMimeType);
        const hasStockData = this.getStockDataForElement() !== undefined;
        return isSupportedElementType && hasStockData;
    }

    get isLicensed() {
        return this.getStockDataForElement()?.state === 'purchased';
    }

    private getStockDataForElement(index?: number) {
        // First try the primary representation
        const representation = index === undefined ? this.getPrimaryRepresentation() : this.representations[index];
        let stockData = representation?.getValue('adobestock', 'trackingdata');

        // If the contentURL is blank, then do not consider it as a download failure
        if (
            stockData
            && representation?.isExternalLink
            && representation?.getCachedExternalLinkError()
            && representation?.getContentURL() !== ''
        ) {
            // It's an external link, but the external link isn't valid: See if there's a comp representation to try:
            const compStockData = this.getStockDataForElement(index === undefined ? 0 : index + 1);
            if (compStockData) {
                // Use the comp representation's comp data, because the primary isn't licensed
                stockData = compStockData;
            } else {
                // The primary isn't licensed, and we don't have a comp - oh no!
                // Let's be tricksy and reconstruct the unlicensed stock data
                stockData = { ...stockData, state: 'not_purchased' };
            }
        }

        return stockData;
    }

    /**
     * @package -- only for use in SAM.js
     */
    _actionDispatch(action: Optional<Action, 'path'>) {
        if (!action.path) {
            action.path = `$.elements[?(@.id == "${this.id}")]`;
        }

        this._lastLocalUpdateDate = Date.now();
        this.libraryContents._actionDispatch(action);
    }

    // TODO-R[SHARED-4623]: Not ideal to use arrow function property instead of a method. Takes more memory than methods on the prototype.
    // Solution is to refactor to use Abstract/composable classes.
    protected _updateImplementation = (data: Partial<ElementData>) => {
        const session = this._itemPool.createUpdateSession();
        this._updater.updateLocalItem(session, this, data); // will also call this._updateChildren, which emits change events
        session.commit(); // emits a change event
    };
}

const propertyUpdaterTypes: IPropertyTypeMap = {
    '_roles': { name: 'roles', format: 'object', isArray: true },
    '_name': 'name',
    '_libraryAssetId': 'libraryAssetId',
    '_children': {
        name: 'representations',
        format: 'object',
        set: (representationsData: RepresentationData[], dest: any) => {
            const element = dest as Element;
            element._updateChildren(representationsData); // updates this._children with the full list of representations
        }
    },
    '_elementId': 'id',
    '_type': 'type',
    '_modifiedDate': { name: 'modifiedDate', format: 'number' },
    '_createdDate': { name: 'createdDate', format: 'number' },
    '_tags': { name: 'tags', format: 'object', isArray: true },
    // '_groups': 'groups',
    '_dependencyIds': { name: 'dependencyIds', format: 'object', isArray: true },
    '_description': 'description',
    '_descriptionModifiedDate': { name: 'descriptionModifiedDate', format: 'number' },
    '_descriptionModifiedBy': 'descriptionModifiedBy',
    '_descriptionModifiedContext': { name: 'descriptionModifiedContext', format: 'object' },
    '_descriptionModifiedLocally': { name: 'descriptionModifiedLocally', format: 'boolean' },
    '_modifiedBy': 'modifiedBy',
    '_modifiedContext': { name: 'modifiedContext', format: 'object' },
    '_modifiedLocally': { name: 'modifiedLocally', format: 'boolean' },
    '_createdBy': 'createdBy',
    '_createdContext': { name: 'createdContext', format: 'object' },
    '_createdLocally': { name: 'createdLocally', format: 'boolean' },
    '_customData': { name: 'customData', format: 'object' },
    // '_autoName': 'autoName',
    // '_elementRef': 'elementRef',
    // '_sourceRef': 'sourceRef',
    // '_sourceModifiedDate': 'sourceModifiedDate',
};

export function getPreviousPlaceholderId(remoteItem: Partial<ElementData>): PlaceholderIdType | undefined {
    return remoteItem.previousPlaceholderId;
}

const elementItemUpdaterOptions: IItemUpdaterBaseOptions<Element, Partial<ElementData>> = {
    //@ts-expect-error -- Element constructor has a more strict string type parameter than ItemBase requires
    localItemType: Element,
    getRemoteId: (data: Partial<ElementData>) => getCombinedIdOrPlaceholder(data),
    getAlternateId: getPreviousPlaceholderId,
    // TODO: implement ELEMENT_DATA_CHANGED if necessary
    // Any changes to these properties from the update will trigger watchers of ELEMENT_DATA_CHANGED.
    // Other properties updated will trigger the  default 'change' event
    changeEventMap: new Map([
    ]),
    // Mapping ElementData to Element
    propertyUpdater: new PropertyUpdater(propertyUpdaterTypes)
};

export const ElementUpdater = new ItemUpdaterBase<Element, Partial<ElementData>>(elementItemUpdaterOptions);
