import type { ConfigurationData } from './data/ConfigurationData';

export default class Configuration {
    constructor(private data: ConfigurationData) {}
    get config() {
        return this.data.config;
    }
    get user() {
        return this.data.user;
    }
    get ignoreRenditionGrids() {
        return this.data.ignoreRenditionGrids;
    }
    get installedApps() {
        return this.data.installedApps || [];
    }
    get processInfo() {
        return this.data.processInfo;
    }
    get environment() {
        return this.data.environment;
    }
    get renditionSize() {
        return this.data.config.RENDITION_SIZES;
    }
    get fullRenditionConfig() {
        return this.data.config.FULL_RENDITION_CONFIG;
    }
}
