// Maximum number of operations per batch request to avoid "Invalid batch size" errors
// See: https://developers.corp.adobe.com/storage-api/docs/reference/operations-delete.md/
const MAX_BATCH_OPERATION_SIZE = 50;
const MAX_INDEX_RETRIES = 5;

// SAMJS-757 These endpoints will not support the link-2023 directive fully, so should not be used
const LINK_2023_EXCEPTIONS: string[] = [
    '/index',
    '/repositories',
    '/repositories/:page',
    '/index-workfront'
];

export interface IQuotaServiceData {
    'storage:bytesLimit': number;
    'storage:bytesUsed': number;
    'storage:limitType': 'soft' | 'hard';
}

export default class RepositoryInterface extends InterfaceBase {
    // Index document is a well-known endpoint, so does not need to come from discovery.
    // https://developers.corp.adobe.com/index-repository-api/docs/index-document.md
    public repositoryIndex = `https://${this._core._environment.endpoints.ACP_CS_HOST}/index`;
    public repositoryNameIndex = `https://${this._core._environment.endpoints.ACP_CS_HOST}/repositories/:page`;
    public workfrontRepositoryIndex = `https://${this._core._environment.endpoints.ACP_CS_HOST}/index-workfront`;

    protected _useHighPriorityRequestsIfEnabled = true;
    private _cache: Cache = this._core._environment.cache;

    private get _fetchIndexState() { return this._core._fetchIndexState; }
    private set _fetchIndexState(state) { this._core._fetchIndexState = state; }

    protected async _getFetchOptionOverrides(href: string, options: IFetchOptions): Promise<{
        href: string;
        options: IFetchOptions
    }> {
        const overrides = await super._getFetchOptionOverrides(href, options);

        // SAMJS-1134: link-2023 temporarily behind a feature flag until service bugs are fixed
        if (!this._core._environment.getValue('FEATURE_FLAGS')?.['enable-rapi-link-2023']) {
            return overrides;
        }

        // By design, some endpoints won't fully support link-2023 directive.
        // https://wiki.corp.adobe.com/display/CA/Proposal%3A+Optimised+resource+links#Proposal:Optimisedresourcelinks-Amendment-DefineAPIswhichwon'tsupportoptimisedlinks
        const url = new URL(href);
        if (LINK_2023_EXCEPTIONS.some(endpoint => url.pathname.endsWith(endpoint))) {
            return overrides;
        }

        overrides.options.headers ??= {};
        const directive = overrides.options.headers.directive || '';
        // `link-2023` directive adds `version` parameter to link templates
        overrides.options.headers.directive = [ 'link-2023', ...directive.split(',') ]
            .filter(s => s).join(',');
        /**
         *  `link-options` ensures unwanted behavior of `link-2023` is omitted
         *    `absolute-base` returns the full protocol + domain of the link instead of `{+base}`
         *    `long-form-rel` uses the original RelType keys for links, rather than the new short form
         *
         * This avoids added complexity for parsing links that would be throw-away work after SAM transitions
         * to GraphQL, and avoids potential breaking changes (or complex backward-compatibility fixes) caused
         * by changing the link keys.
         *
         * See https://wiki.corp.adobe.com/display/CA/Support+fully+formed+links+with+Optimised+Links
         */
        const linkOptions = overrides.options.headers['link-options'] || '';
        overrides.options.headers['link-options'] = [ 'absolute-base', 'long-form-rel', ...linkOptions.split(',') ]
            .filter(s => s).join(',');

        return overrides;
    }

    @cache
    _getAndCacheDocument(@key href: string) {
        return this._getAllPages(href);
    }

    private _getIndexHeaders() {
        return {
            // R-API returns an E-Tag which doesn't change when the content changes, causing the browser to
            // use stale cached data. Using Cache-Control header to disable browser cache so this doesn't happen.
            // [SAM-2952]
            'Cache-Control': 'no-cache, no-store, max-age=0',
            // SAMJS-467: calculating which regions the user has discoverable assets in is slow, but
            // no clients require this behavior, so disable calculation for better performance.
            'directive': 'index-skip-repo-regions'
        };
    }

    public _getRepositoryHref(repositoryID: string): string {
        return `https://${this._core._environment.endpoints.ACP_CS_HOST}/content/repo/${repositoryID}/repositoryResource`;
    }

    async getRootLink(relType: RelType, params: {[s: string]: string} = {}): Promise<string> {
        // The only thing uses in SAM.js from the `/` resource is the `_links` metadata, which is identical to the
        // `_links` in the `/index` resource, so use the `/index` resource for the root links
        const rootDocument = await this.getIndex();
        return getURLFromLinks(rootDocument._links, relType, params);
    }

    async getIndex(): Promise<IRepositoryIndex> {
        const fetchIndexState = this._fetchIndexState;

        // If something triggered clearing the cache, wait for it to finish
        if (fetchIndexState.pendingCacheClear) {
            await fetchIndexState.pendingCacheClear;
        }
        if (fetchIndexState.response && fetchIndexState.hasChildren) {
            // Data is complete, so return it now
            return fetchIndexState.response;
        }

        const existing = await this._cache.getItem(this.repositoryIndex);
        if (existing !== NotFound) {
            fetchIndexState.response = existing;
            fetchIndexState.hasChildren = Boolean(fetchIndexState.response?.children?.length);
        }

        // Refresh index in background if it hasn't been refreshed successfully this session. This allows typical
        // calls to return quickly from cache while still updating the cache regularly [SAM-3165].
        if (!fetchIndexState.promise) {
            fetchIndexState.promise = new Promise((resolve, reject) => {
                this._getResponse<IRepositoryIndex>(
                    this.repositoryIndex,
                    {
                        headers: this._getIndexHeaders(),
                        // R-API might be temporarily returning 404 on the /index document for some users
                        additionalRetryErrorCodes: [ 404 ],
                    }
                ).then(async indexJson => {
                    // Only cache /index if it has children [SAM-2952]
                    if (indexJson.children?.length) {
                        await this._cache.setItem(this.repositoryIndex, indexJson);
                        fetchIndexState.hasChildren = true;
                    } else {
                        // Allow getHomeDirectoryMetadata() to retry fetching /index if there were no children
                        fetchIndexState.hasChildren = false;
                        fetchIndexState.promise = undefined;
                    }
                    // Response can be used for _links even if there are no children
                    fetchIndexState.response = indexJson;
                    resolve(indexJson);
                })
                    .catch(reject);
            });
        }

        // If the /index is not in cache, or missing data, wait for fetch, otherwise use the
        // cache value while the index is refreshed in the background.
        if (fetchIndexState.promise && (!fetchIndexState.response || !fetchIndexState.hasChildren)) {
            try {
                await fetchIndexState.promise;
            } catch (e) {
                // Do not cache bad response, but let the original error bubble up
                fetchIndexState.promise = undefined;
                throw e;
            }
        }

        // The _links property of the response will still be usable even if children are not present.
        return fetchIndexState.response!;
    }

    async getWorkfrontIndex(orgId: string): Promise<IWorkfrontRepositoryIndexResponse> {
        const response = await this._getResponse<IWorkfrontRepositoryIndexResponse>(
            this.workfrontRepositoryIndex,
            {
                headers: {
                    ...this._getIndexHeaders(),
                    'Org-Id': orgId
                },
                // R-API might be temporarily returning 404 on the /index document for some users
                additionalRetryErrorCodes: [ 404 ]
            }
        );
        return response;
    }

    /**
     * @package -- for use in SAM.js only
     */
    _clearIndexCache(): void {
        this._fetchIndexState.pendingCacheClear = new Promise(resolve => {
            // Allow pending request to complete before clearing the cache so the final state is
            // a clear cache.
            Promise.resolve(this._fetchIndexState.promise)
                .finally(() => {
                    return this._cache.deleteItem(this.repositoryIndex);
                })
                .finally(() => {
                    this._fetchIndexState = {};
                    resolve();
                });
        });
    }

    @cache
    private async _getAndCacheLinksFromHref(@key href: string): Promise<{ links: AssetLinks }> {
        const response = await this._doGet(href);
        // The etag header from Links API no longer represents the Asset or its repo metadata, so it
        // isn't being stored in the SAM.js persistent cache.
        const { _links } = await response.json();
        return { links: _links };
    }

    getAssetResolveByIdHref(assetId: string): string {
        // Links API is a "well-known endpoint" and so does not need to use discovery
        // https://developers.corp.adobe.com/storage-api/docs/reference/links.md
        const url = new URL(`https://${this._core._environment.endpoints.ACP_CS_HOST}/links`);
        setURLSearchParams(url, { assetId });
        return url.toString();
    }

    async getCloudQuotaUsedAndMax(): Promise<IQuotaInfo> {
        const metadata = await this.getHomeDirectoryMetadata();
        const url = getURLFromLinks(metadata._links, RelType.QUOTA);

        const responseJson: IQuotaServiceData = await this._getResponse(url);
        return { used: responseJson['storage:bytesUsed'], total: responseJson['storage:bytesLimit'] };
    }

    /**
     * Takes an asset id and returns the links for the resource.
     *
     * @param id {string} assetId of the object
     * @TODO_Deprecation to be removed after it is no longer used in SAMCpp.ts patchAdobeAsset
     */
    async resolveById(assetId: string): Promise<AssetInterface> {
        const resolveHref = this.getAssetResolveByIdHref(assetId);
        const { links } = await this._getAndCacheLinksFromHref(resolveHref);
        return new AssetInterface(this, assetId, links, '');
    }

    async getRepoMetadataById(assetId: string, resource: Resource<RepositoryMetadata>, assetLinks?: MinimalAssetLinks): Promise<RepositoryMetadata> {
        const resolveHref = assetLinks && assetLinks[RelType.REPO_METADATA]
            // we have a client-provided link for repo:metadata, use that instead of a resolve call.
            ? getURLFromLinks(assetLinks, RelType.REPO_METADATA)
            // GET on the resolve link will return the repo metadata
            : await this.getRootLink(RelType.RESOLVE_ID, { id: assetId });
        await this._doGet(resolveHref, { resource });
        return resource.data;
    }

    async getRepoMetadataByPath(repositoryId: string, path: string, resource: Resource<RepositoryMetadata>, assetLinks?: MinimalAssetLinks): Promise<RepositoryMetadata> {
        const resolveHref = assetLinks && assetLinks[RelType.REPO_METADATA]
            // we have a client-provided link for repo:metadata, use that instead of a resolve call.
            ? getURLFromLinks(assetLinks, RelType.REPO_METADATA)
            // GET on the resolve link will return the repo metadata
            : await this.getRootLink(RelType.RESOLVE_PATH, { repositoryId, path, mode: 'id' });
        await this._doGet(resolveHref, { resource });
        return resource.data;
    }

    async getHomeDirectoryMetadata(): Promise<RepositoryMetadata> {
        return await this._getHomeDirectoryMetadata(0);
    }

    private async _getHomeDirectoryMetadata(retryCount: number): Promise<RepositoryMetadata> {
        // Fire off background refresh of index data
        let index = await this.getIndex();

        const featureFlags = this._core._environment.getValue('FEATURE_FLAGS');
        if (featureFlags?.['enable-response-cache'] && retryCount === 0) {
            // TODO: The behavior here is already the same effect (using a cached value first).
            // We don't want to wait for the fetchIndexState.promise to resolve (for quick load),
            // but we do want to properly handle all scenarios where that initial value might change.
        } else {
            // Wait for background refresh, which may or may not be the same as the cached value
            index = await (this._fetchIndexState.promise ?? index);
        }


        // Likely cause: Enterprise user has not been granted quota by their administrator, but this error
        // could change. Host apps should verify that the user has quota before trying to get their home
        // directory info, and if they have none, show a message suggesting they contact their administrator.
        if (!index.children.length) {
            if (retryCount >= MAX_INDEX_RETRIES) {
                throw SAMError.create(SAMErrorCode.INVALID_OPERATION, `Home repository not found after ${MAX_INDEX_RETRIES} retries`);
            } else {
                // NOTE: assumes that getIndex() does not cache if there are no children, so no need to clear cache here
                this._core._environment.log(`/index has no children, ${MAX_INDEX_RETRIES - retryCount} retries left`);
                await new Promise(resolve => setTimeout(resolve, this._getRetryErrorDelay(undefined, retryCount)));
                return await this._getHomeDirectoryMetadata(retryCount + 1);
            }
        }
        return index.children[0]._embedded[RelType.REPO_METADATA];
    }

    /**
     * Run a cloud operation.
     * https://git.corp.adobe.com/pages/caf/api-spec/schemas/repository/operation.html
     *
     * @param ops {IOperationQuery}
     * @template T The expected return type. Defaults to ISAMOperationResults for standard operations.
     */
    async runOperation<T = ISAMOperationResults>(ops: IOperationQuery): Promise<T> {
        const opHref = await this.getRootLink(RelType.OPS);

        const headers: HeaderMap = {
            'Content-type': 'application/vnd.adobe.asset-operation+json',
            'Prefer': 'respond-async, wait=5',
        };
        const firstOp = Array.isArray(ops) ? ops[0] : ops;
        // If the operation is copy and SAM is configured to copy all resources
        // by default then we add the directive header in RAPI call as RAPI needs
        // this header to copy secondary resources by default.
        const copyResources = (firstOp as ICopyOperation)?.op === 'copy';
        copyResources && (headers['directive'] = 'ops-2021');

        // If the operation is move and the client has set the 'enable-x-bucket-move' (deprecated) or
        // 'enable-ops-2021' feature flags to 'true', add the ops-2021 directive to the request
        // to ensure that cross bucket moves are enabled for the operation (SHARED-844). Cross-bucket
        // moves will occur when the storage-assignee of the source and destination are different.
        const moveResources = (firstOp as IMoveOperation)?.op === 'move';
        if (moveResources && this._core._environment._getCrossBucketMoveEnabled()) {
            headers['directive'] = 'ops-2021';
        }

        // If the operation is package, we need to send the `rapi-response` directive to indicate
        // that we want the response to include the repo metadata for the packaged assets, skipped
        // assets, etc. If this is excluded, the package operation result will only indicate success/failure.
        const packageResources = (firstOp as IPackageOperation)?.op === 'package';
        if (packageResources) {
            headers['directive'] = 'rapi-response';
        }

        // If we send a single operation, then errors will fail the entire request.
        // If we send multiple operations, we always get a 200 and then separate error
        // codes inside the response. We want to normalize this behavior here, in order
        // to make it easier to handle the response.
        // Note that some errors are still going to return a proper array even
        // for single items, so we need to be prepared for both types of replies.

        // We are using 'any' below to disable the status code validation and allow
        // this method to handle the error codes.
        const response = await this._doPost(opHref, headers, JSON.stringify(ops), 'any');
        const reqId = response.headers.get('x-request-id')!;

        let result: IOperationResults | IOperationError | undefined;
        try {
            result = await response.json();
        } catch {
            // Ignore the error here.
        }

        if (result && !Array.isArray(result) && response.status !== 200) {
            // If this was a single operation request, then sometimes the service will fail the entire request
            // instead of returning the array for the item. Try to normalize the reply to avoid bugs in the callers.
            // https://jira.corp.adobe.com/browse/ACPCSS-3613
            return [
                {
                    ...firstOp,
                    error: SAMError.createWithRepositoryCode(
                        // We cannot use the result.code as that uses non-standard HTTP error codes like 4041 instead of 404.
                        response.status,
                        (result as IOperationError).type ?? ProblemType.OPERATION_FAILED,
                        (result as IOperationError).title ?? (result as IOperationSingleError).message ?? 'Operation failed',
                        reqId
                    )
                }
            ] as T;
        }

        // If we don't actually get a response or if we get an array,
        // then we should expect to get a 200 response code.
        this._checkResponseStatus(response, opHref, [ 200 ]);

        if (!result) {
            // We've got a 200 status, but there's no actual result or the JSON parsing failed.
            throw SAMError.create(SAMErrorCode.UNKNOWN, 'Failed to parse response for repo bulk API.');
        }

        // Convert the result to ensure it is always an array.
        // If we have a single item, we know it cannot be an error as that was handled above already.
        const list = Array.isArray(result) ? result : [ result as IOperationResult ];

        // Map errors to SAMErrors before returning.
        return list.map((item): ISAMOperationResult => {
            const { error } = item;
            return {
                ...item,
                error: error ? SAMError.createWithRepositoryCode(error.status, error.type, error.title, reqId) : undefined
            };
        }) as T;
    }

    /**
     * Utility function to chunk an array into smaller batches
     * @param array The array to chunk
     * @param chunkSize Maximum size of each chunk
     * @returns Array of chunks
     */
    private _chunkArray<T>(array: T[], chunkSize: number): T[][] {
        const chunks: T[][] = [];
        for (let i = 0; i < array.length; i += chunkSize) {
            chunks.push(array.slice(i, i + chunkSize));
        }
        return chunks;
    }

    /**
     * Combine results from multiple batch operation results
     * @param results Array of batch operation results to combine
     * @returns Combined batch operation result
     */
    private _combineOperationResults<LocalType extends ItemBase>(results: IBatchOperationResult<LocalType>[]): IBatchOperationResult<LocalType> {
        const combinedResult: IBatchOperationResult<LocalType> = {
            failedResults: [],
            newModels: []
        };

        for (const result of results) {
            combinedResult.failedResults.push(...result.failedResults);
            combinedResult.newModels.push(...result.newModels);
        }

        return combinedResult;
    }

    /**
     * Runs the runOperation API for any specific context
     * Initiate session of that context
     * Check every model operation's result and update model meta data
     * commit session
     * returns ILocalOperationResult array collected over all results collectively
     *
     * @param ops Opeartions to run
     * @param modelsById A map of model to it's id
     * @param itemPool ItemPool of the specific context used to create session
     * @param updateLocalModel for updating Model metaData
     * @param errorHandlers If needed to validate or check any specific error code, and respond differently
     */
    async runOperationsForContext<LocalType extends ItemBase>(
        ops: IOperationQuery,
        modelsById: Map<string, LocalType>,
        itemPool: ItemPool<LocalType>,
        updateLocalModel: (session: IUpdateSession<LocalType>, model: LocalType, remoteItem?: RepositoryMetadata) => LocalType | undefined,
        errorHandlers?: { match: (error: SAMError) => boolean, action: (model: LocalType, error: SAMError) => Promise<void | IFailedOperation<LocalType>> }[]
    ): Promise<IBatchOperationResult<LocalType>> {
        // Convert single operation to array for uniform processing
        const operations = Array.isArray(ops) ? ops : [ ops ];

        // Chunk operations and process in parallel (handles both small and large batches)
        const chunks = this._chunkArray(operations, MAX_BATCH_OPERATION_SIZE);
        const chunkPromises = chunks.map(chunk =>
            this._runOperationsForContextBatch(chunk, modelsById, itemPool, updateLocalModel, errorHandlers)
        );

        // Wait for all chunks to complete
        const chunkResults = await Promise.all(chunkPromises);

        // Combine results from all chunks
        return this._combineOperationResults(chunkResults);
    }

    /**
     * Internal method to run operations for a single batch (within size limits)
     * @param ops Operations to run (should be <= MAX_BATCH_OPERATION_SIZE)
     * @param modelsById A map of model to it's id
     * @param itemPool ItemPool of the specific context used to create session
     * @param updateLocalModel for updating Model metaData
     * @param errorHandlers If needed to validate or check any specific error code, and respond differently
     * @returns Batch operation result
     */
    private async _runOperationsForContextBatch<LocalType extends ItemBase>(
        ops: IOperationQuery,
        modelsById: Map<string, LocalType>,
        itemPool: ItemPool<LocalType>,
        updateLocalModel: (session: IUpdateSession<LocalType>, model: LocalType, remoteItem?: RepositoryMetadata) => LocalType | undefined,
        errorHandlers?: { match: (error: SAMError) => boolean, action: (model: LocalType, error: SAMError) => Promise<void | IFailedOperation<LocalType>> }[]
    ): Promise<IBatchOperationResult<LocalType>> {
        const result = await this.runOperation(ops);

        const resultOps: IBatchOperationResult<LocalType> = { failedResults: [], newModels: [] };

        const session = itemPool.createMutationSession();
        const promises: Promise<void>[] = [];

        for (const op of result) {
            const currentModel = op.id && modelsById.get(op.id);
            if (!currentModel) {
                continue;
            }

            const { asset: updatedModelMetaData, error } = op;

            if (error) {
                if (errorHandlers) {
                    const onError = (errorHandlers.find(errorHandler => errorHandler.match(error)))?.action;
                    if (onError) {
                        promises.push(onError(currentModel, error).then(failedOp => {
                            if (failedOp) {
                                resultOps.failedResults.push(failedOp);
                            }
                        }));
                        continue;
                    }
                }

                resultOps.failedResults.push({ model: currentModel, error });
                continue;
            }

            try {
                const newModel = updateLocalModel(session, currentModel, updatedModelMetaData);
                if (newModel) {
                    resultOps.newModels.push(newModel);
                }
            } catch (error: any) {
                const samError = error as SAMError;
                if (samError && samError.code === SAMErrorCode.UNKNOWN) {
                    resultOps.failedResults.push({ model: currentModel, error: samError });
                } else {
                    throw error;
                }
            }
        }

        session.commit();

        // Wait for any Promises from errorHandlers callback
        await Promise.all(promises);

        return resultOps;
    }

    /**
     * Fetches all repositories from the paginated repositories endpoint.
     * @returns IRepositoriesDataResponse
     */
    async _fetchRepositoriesData(): Promise<IRepositoriesDataResponse> {
        let pageLink = this.repositoryNameIndex;
        let repositories: IRepositoryData[] = [];
        while (pageLink) {
            const response: IRepositoriesDataResponsePage = await this._getResponse(pageLink);
            if (!response) {
                throw SAMError.create(SAMErrorCode.INTERNAL_ERROR, 'Failed to fetch discoverable repositories data for page ' + pageLink);
            }
            // using concat instead of ... spread operator for better memory handling and performance
            repositories = repositories.concat(response.children);
            pageLink = response._links?.next?.href;
        }
        return { children: repositories };
    }

    /* Fetches data from the repositories endpoint.
     * These are all the repositories that contain at least one discoverable asset for this user.
     */
    @synchronized
    async getRepositoriesData(): Promise<IRepositoriesDataResponse> {
        const ttlInMs = 60 * 60 * 1000; // 1 hr cache expiration (see SAMJS-985)
        return await this._cache.getItem(this.repositoryNameIndex, this._fetchRepositoriesData.bind(this), undefined, ttlInMs);
    }

    async getRepositoryName(id: string): Promise<string | undefined> {
        const response =  await this.getRepositoriesData();
        if (!response) {
            return undefined;
        }

        const children = response.children;
        const data =  children.find(data => data._embedded[RelType.PRIMARY]['repo:repositoryId'] === id);
        return data?._embedded[RelType.PRIMARY]['dc:title']?.['rdf:_1']?.['@value'];
    }

    async getStorageAssignee(id: string): Promise<Assignee | undefined> {
        const response =  await this.getRepositoriesData();

        const children = response.children;
        const data =  children.find(data => data._embedded[RelType.PRIMARY]['repo:repositoryId'] === id);
        if (data?._embedded[RelType.PRIMARY]['storage:assignee']) {
            return data?._embedded[RelType.PRIMARY]['storage:assignee'];
        } else {
            return undefined;
        }
    }

    /**
     * Fetches and returns the owner details for a given list of repositoryIDs.
     * @param targetRepoId Optional repository ID to ensure is included in the result. Will delete cache and retry fetching if not found in the initial response.
     * @returns A map where each key is a repositoryID and the value is an Owner object.
     */
    async getRepoOwnerMap(targetRepoId?: string): Promise<Map<string, Owner>> {
        let response = await this.getRepositoriesData();
        let ownerMap = new Map(response.children.map(repoData => {
            const primary = repoData._embedded[RelType.PRIMARY] || {};
            return [ primary['repo:repositoryId'], primary['repo:owner'] ];
        }));

        // If a specific repository is missing, clear cache and try once more
        if (targetRepoId && !ownerMap.has(targetRepoId)) {
            await this._cache.deleteItem(this.repositoryNameIndex);
            response = await this.getRepositoriesData();
            ownerMap = new Map(response.children.map(repoData => {
                const primary = repoData._embedded[RelType.PRIMARY] || {};
                return [ primary['repo:repositoryId'], primary['repo:owner'] ];
            }));
        }

        return ownerMap;
    }

    /* Call the Links API to get the asset links resulting in a service call instead of using local cache.
     * This is intended as an eventual replacement for resolveById which uses the local cache.
     * Fixes [SAM-3444]. NOTE: the /links API does not include the restore and discard links, but since
     * SAM.js uses the /ops API for these operations, it shouldn't be needed. Meanwhile, SAM.js
     * needs the download and block transfer links, which do not appear in the /:repometadata
     * body (they're only in the header), but do appear in the /links body.
     */
    async getAssetLinks(assetId: string): Promise<AssetLinks> {
        const resolveHref = this.getAssetResolveByIdHref(assetId);
        const { _links } = await this._getResponse(resolveHref) as { _links: AssetLinks };
        return _links;
    }

    @cache
    async getRepositoryLinks(@key repositoryID: string): Promise<AssetLinks> {
        const href = this._getRepositoryHref(repositoryID);
        const { _links } = await this._getResponse(href) as { _links: AssetLinks };
        return _links;
    }

    /**
     * Creates a folder at the given path in the repository
     *
     * @param path The path to create the folder at.
     * @param repositoryID The repository id to create the folder in.
     * @param createIntermediates Whether to create intermediate folders if they don't exist.
     * @param links The repository links to use for the request. Workfront repositories can only be fetched through /index-workfront and not
     * from the /content/repo/:repositoryID endpoint.
     * @returns The created folder's repository metadata.
     */
    async createFolderByPath(path: string, repositoryID: string, createIntermediates: boolean = true, links?: AssetLinks): Promise<RepositoryMetadata> {
        const repositoryLinks = links ?? await this.getRepositoryLinks(repositoryID);
        const createHref = getURLFromLinks(
            repositoryLinks,
            RelType.CREATE,
            {
                path,
                intermediates: createIntermediates,
                respondWith: RelType.REPO_METADATA
            }
        );

        const response = await this._doPost(createHref, {
            'Content-Type': FOLDER_TYPE
        }, undefined, [ 200, 201 ]);
        return response.json();
    }
}
