import type { IUpdateSession } from './UpdateSession';
import { SharedChangeEvent } from './ChangeEvent';
import type SAMEvent from './SAMEvent';
import type { ItemId } from './ItemBase';
import type ItemBase from './ItemBase';
import type PropertyUpdater from './PropertyUpdater';
import SAMError, { SAMErrorCode } from './SAMError';
import type { ISAMCorePrivate } from '../indexPrivate';
import { getEventForProp } from './decorators/observable';

type ItemConstructor<LocalType extends ItemBase> = { new (core: ISAMCorePrivate, id: ItemId, ...args: any[]): LocalType };

export interface ILocalItemUpdaterOptions {
    /**
     * The property updater used to apply the changes.
     */
    propertyUpdater: PropertyUpdater;

    /**
     * The default event scheduled when a change is detected.
     * @default value is the 'change' event.
     */
    changeEvent?: SAMEvent;

    /**
     * A mapping of properties to events to allow
     * events to be sent for specific properties that
     * have changed and override the default event.
     */
    changeEventMap?: Map<string, SAMEvent>
}

export class LocalItemUpdater<LocalType extends ItemBase, RemoteType> {

    protected _propertyUpdater: PropertyUpdater;
    protected _changeEvent: SAMEvent;
    protected _changeEventsMap?:  Map<string, SAMEvent>;

    constructor(options: ILocalItemUpdaterOptions) {
        this._propertyUpdater = options.propertyUpdater;
        this._changeEvent = options.changeEvent || SharedChangeEvent;
        this._changeEventsMap = options.changeEventMap;
    }

    /**
     * Update the local item with values from the remote item.
     * @param localItem
     * @param remoteItem
     */
    updateLocalItem(updateSession: IUpdateSession<LocalType>, localItem: LocalType, remoteItem: RemoteType): void {
        if (!updateSession.checkIfItemAllowsMutations(localItem)) {
            // The item had local changes that we don't want to overwrite because
            // the data in this session may be older than the item's local changes.
            const localTime = (localItem.lastKnownClientMutation ?? Date.now());
            const validTime = (updateSession.mostRecentValidMutation ?? Date.now());
            const cacheAge = localTime - validTime;
            updateSession._core._environment.debug(
                `[ItemUpdater] Ignoring update to ${localItem.id}; mostRecentValidMutation for this session is `
                + `${(cacheAge / 1000).toFixed(2)} seconds before item’s lastKnownClientMutation (${localTime})`
            );
            return;
        }

        // If the item is not already added, add it to the list.
        updateSession.ensureItemIsAdded(localItem);
        const changedFields = this._propertyUpdater.update(localItem, remoteItem);
        const changeEvents = new Set(changedFields
            .map(
                changedProperty =>
                    this._changeEventsMap?.get(changedProperty)
                        ?? getEventForProp(localItem, changedProperty)
                        ?? this._changeEvent
            )
        );
        if (changedFields.length) {
            updateSession.queueChangedItem(localItem, [ ...changeEvents ]);
        }
    }
}

export interface IItemUpdaterBaseOptions<LocalType extends ItemBase, RemoteType> extends ILocalItemUpdaterOptions {
    /**
     * The constructor of the local object.
     */
    localItemType: ItemConstructor<LocalType>;

    /**
     * Returns the alternate ID, if any, for the value received from the local cache or server side.
     * This is a placeholder until the primary ID is received.
     * @param remoteItem
     */
    getAlternateId?: (remoteItem: RemoteType) => string | undefined;

    /**
     * Returns the ID for the value received from the server side.
     * @param remoteItem
     */
    getRemoteId(remoteItem: RemoteType): string | undefined;
}

// Adds on remote id and placeholder ("alternate") id handling to the LocalItemUpdater
export class ItemUpdaterBase<LocalType extends ItemBase, RemoteType> extends LocalItemUpdater<LocalType, RemoteType> {

    /**
     * The constructor of the local object.
     */
    protected _localItemType: ItemConstructor<LocalType>;

    protected _getRemoteId: (remoteItem: RemoteType) => string | undefined;
    protected _getAlternateId: (remoteItem: RemoteType) => string | undefined;

    constructor(options: IItemUpdaterBaseOptions<LocalType, RemoteType>) {
        super(options);
        this._localItemType = options.localItemType;
        this._getRemoteId = options.getRemoteId;
        this._getAlternateId = options.getAlternateId || (() => undefined);
    }

    /**
     * If you have an instance of the item already (such `this` in the item class), use updateLocalItem directly.
     * If you don't, use this method to create a new instance of the item from the remote data and update it locally.
     */
    updateRemoteItem(
        updateSession: IUpdateSession<LocalType>,
        remoteItem: RemoteType // server response data
    ): LocalType {
        const id = this._getRemoteId(remoteItem);
        const altId = this._getAlternateId(remoteItem);
        if (!id && !altId) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'An ID or alternate ID must exist on the remote item structure.');
        }
        let localItem = id ? updateSession.getItemById(id) : undefined;
        // Item is not cached by primary ID so check if it has been cached by an alt ID
        if (!localItem && altId) {
            localItem = updateSession.getItemById(altId);
            if (localItem) {
                if (id) {
                    // Re-index cached item with its new preferred ID (altId was a placeholder)
                    updateSession.reindexItem(localItem, altId, id);
                }

            }

        }

        // Item is not cached at all so create a new instance
        if (!localItem) {
            const LocalItemType = this._localItemType;
            // The primary altId is the first ID in the array
            localItem = new LocalItemType(updateSession._core, id || altId!);
        }

        // Inject remote data.
        this.updateLocalItem(updateSession, localItem, remoteItem);

        return localItem;
    }

    updateRemoteItems(
        updateSession: IUpdateSession<LocalType>,
        remoteItems: RemoteType[]
    ): LocalType[] {
        if (!Array.isArray(remoteItems)) {
            // Invalid remote data provided.
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Invalid data received, expected list of items.');
        }
        return remoteItems.map((remoteItem) => this.updateRemoteItem(updateSession, remoteItem));
    }
}

export interface IItemUpdaterOptions<LocalType extends ItemBase, RemoteType>
    // Removing the `getRemoteId` requirement as we are going to implement it in the `ItemUpdater` constructor
    // based on the remoteIdProperty passed via this interface.
    extends Omit<IItemUpdaterBaseOptions<LocalType, RemoteType>, 'getRemoteId'>
{
    /**
     * Can be used to customize the property of the remote id that is used for the hash lookup.
     *
     * @see If the `id` is more complicated to reach and is not an immediate property of the RemoteType,
     * then you can use the `ItemUpdaterBase` instead and override the `getRemoteId` method instead
     * of using the `remotePropertyId` name in this class.
     */
    remoteIdProperty: string;
}

// Adds the ability to customize the remote id property that is used to get the remote id to ItemUpdaterBase
export default class ItemUpdater<LocalType extends ItemBase, RemoteType> extends ItemUpdaterBase<LocalType, RemoteType> {
    public changeEventMap?: Map<string, SAMEvent>;
    constructor(options: IItemUpdaterOptions<LocalType, RemoteType>) {
        super(Object.assign({
            getRemoteId(remoteItem: RemoteType): string | undefined {
                // The generic types in TS are not lazy evaluated, so TS will try to resolve this based entirely
                // on the constraints added to the generic type. Maybe one day TS will be able to evaluate
                // based on the actual interface that is passed as the `RemoteType` and we could fix this model.
                // As a result, we have use `any` because TS doesn't know the type of the generic RemoteType.
                return (remoteItem as any)[options.remoteIdProperty];
            },
        }, options));
    }

}
