import type { IComparatorMap } from '../core/ItemOrder';
import { compareStrings, createItemOrderFactory } from '../core/ItemOrder';
import type OrgRepository from './OrgRepository';

export type OrgRepositoryOrderField = 'id';

const OrderFieldToComparator: IComparatorMap<OrgRepository, OrgRepositoryOrderField> = {
    id(a: OrgRepository, b: OrgRepository): number {
        return compareStrings(a.id, b.id);
    }
};

export default class OrgRepositoryOrder extends createItemOrderFactory(OrderFieldToComparator) {
    static default = new OrgRepositoryOrder('ascending', 'id');
}
