import type AssetInterface from '../interface/AssetInterface';
import type { IItemLoader, IItemLoaderOptions, ILoadedPage, ILoadNextPage } from '../core/ItemLoader';
import type ItemPool from '../core/ItemPool';
import type { AssetVersionConfig } from './AdobeAssetSource';
import type { IAssetVersion } from './AssetVersion';
import type AssetVersion from './AssetVersion';
import { VersionUpdater } from './AssetVersion';
import type AssetVersionFilter from './AssetVersionFilter';
import { getMostRecentValidMutation } from '../utils/loaderUtils';


export interface IAssetVersionResponse {
    children: IAssetVersion[];
    total_children: number;
}

export default class AssetVersionLoader implements IItemLoader<AssetVersionConfig> {

    constructor(
        private _versionPool: ItemPool<AssetVersion>,
        private _assetInterfacePromise: Promise<AssetInterface>
    ) {}

    async loadPage(options: IItemLoaderOptions<AssetVersionConfig>, start?: string): Promise<ILoadedPage<AssetVersionConfig>> {
        return await this._loadPage(options, start);
    }

    private async _loadPage(options: IItemLoaderOptions<AssetVersionConfig>, start?: string): Promise<ILoadedPage<AssetVersionConfig>> {
        const { limit } = options.loadOptions ?? {};
        // We will ignore the update if we had local changes sooner than this timestamp.
        const latency = this._versionPool._core._environment.getValue('VERSIONS_LIST_UPDATE_LATENCY');
        const mostRecentValidMutation = getMostRecentValidMutation(options.resource, latency);

        const assetInterface = await this._assetInterfacePromise;
        const filter = options.filter as AssetVersionFilter;
        const version = filter?.version || undefined;
        const result: IAssetVersionResponse = await assetInterface.getVersions({ start, limit, version });
        const session = this._versionPool.createLoaderUpdateSession(mostRecentValidMutation);
        const versions: IAssetVersion[] =  result.children.map((version: IAssetVersion) => ({
            ...version,
            // assetId, assetEtag, assetLinks are needed to construct the AssetInterface for the AssetVersion
            assetId: assetInterface.assetID,
            assetEtag: assetInterface.etag,
            assetLinks: assetInterface.links
        }));
        const items = VersionUpdater.updateRemoteItems(session, versions);
        session.commit();
        // Check if we have another page to load.
        let loadNextPage: ILoadNextPage<AssetVersionConfig> | undefined;
        const currentCount = result.children.length;
        // TODO: unit test to ensure this doesn't throw an exception if there are 0 pages
        const nextStart = result.children[currentCount - 1]?.created;

        if (nextStart && limit && currentCount === limit) {
            loadNextPage = (options: IItemLoaderOptions<AssetVersionConfig>) =>
                this._loadPage(options, nextStart);
        }

        return {
            items,
            total: result.total_children,
            loadNextPage,
            mostRecentValidMutation
        };
    }
}
