import AsyncOperation from '../utils/AsyncOperation';
import RequestError from '../errors/RequestError';
import { parseAsyncResponse } from './AsyncResponseParser';
import Logger from '../utils/Logger';
import { HttpStatus } from '../config/constants';
import type Driver from './Driver';

/**
 * AsyncResponse roughly mirrors AdobeLibraryOperation for interop reasons.
 * TODO: Clean this up
 */
export default class AsyncResponse<T extends Driver> extends AsyncOperation {
    _error?: Error;
    _location?: string;

    constructor(private _driver: T, request: Promise<Response>) {
        super();
        this._handleResponse(request);
    }

    cancel() {
        this.abort();
        if (this._location) {
            this._driver.abortOperation(this._location);
            this._location = undefined;
        }
    }

    get error() {
        return this._error;
    }

    private async _handleResponse(request: Promise<Response>): Promise<unknown> {
        try {
            const response = await request;
            if ([ HttpStatus.NO_CONTENT, HttpStatus.OK ].includes(response.status)) {
                this.progress = 100;
                let rawBody: string, jsonData, headers: Headers | undefined;

                if (response.status === HttpStatus.OK) {
                    // Async response completion from melville is raw http. We need to parse it out
                    // first and we use utility from SAMjs to do this. If there is an error parsing json data
                    // then we can assume this was a json response from local driver request to process
                    jsonData = await response
                        .text()
                        .then(body => {
                            rawBody = body;
                            return parseAsyncResponse('', body);
                        })
                        .then(res => {
                            headers = res.headers;
                            // Body is either JSON or empty, so if we fail to parse just return undefined
                            return res.json().catch(() => undefined);
                        })
                        .catch(() => JSON.parse(rawBody))
                        .catch(() => {
                            Logger.error(`Error parsing async response: ${response}`);
                        });
                }

                if (jsonData?.exception_code) {
                    // Example async error response:
                    // {
                    //     exception_code: "4000",
                    //     log_id: "5390a825-144a-429b-bf7d-9f1ae5b52728",
                    //     message: "unexpected error while copying asset - HttpProblemDetail{type='http://ns.adobe.com/adobecloud/problem/operation_failed', title='Unexpected response code when creating collection: 409 != 201', status=409, detail='null', instance='null', properties='{}'}",
                    //     status: 409,
                    //     type: "InputValidation"
                    // }
                    throw new RequestError(jsonData.status, jsonData.message, response, jsonData);
                } else {
                    this.emit('change', true, jsonData, headers);
                    this.DANGEROUS.removeAllListeners();
                    return;
                }
            }

            if (response.status === HttpStatus.ACCEPTED) {
                let json: Record<string, any> = {};
                try {
                    json = await response.json();
                } catch {
                    // R-API async responses don't have a body.
                }

                if (json.progress) {
                    this.progress = json.progress;
                    this.emit('change');
                }

                // R-API does not return a location from a monitor request.
                // Reuse the current location if there is not a location in the response.
                const newLocation = response.headers.get('location') ?? json.href;
                if (newLocation) {
                    this._location = newLocation;
                }

                const retryAfter = response.headers.get('retry-after')
                    ? parseInt(response.headers.get('retry-after') as string, 10)
                    : 1;

                if (!this._location) {
                    throw new RequestError(
                        'MALFORMED_RESPONSE',
                        'Location header is missing from ops monitor response'
                    );
                }

                await this._driver.sleep(retryAfter * 1000, this._abortController.signal);

                return this._handleResponse(
                    this._driver.fetch(this._location, {
                        signal: this._abortController.signal
                    })
                );
            }

            throw new RequestError('UNEXPECTED_RESPONSE', `Unexpected response from ops monitor: ${response.status}`);
        } catch (error) {
            this._error = error as Error;
            this.progress = 100;
            this.emit('change', true);
            this.DANGEROUS.removeAllListeners();
        }
    }
}
