import { isInsertAction, isUpdateAction } from './Action';
import Logger from '../utils/Logger';
import reducer from './utils/reducer';
import { deepCopy, replacePlaceholders, markSubstitutedPlaceholders } from '../utils/StoreUtils';
import type Operation from '../drivers/Operation';
import { isAnyRemoveLibraryAction } from './Action';
import FIFOStringSet from '../utils/FIFOStringSet';
import { rebaseAction } from '../utils/LibraryUtils';
import type { ElementData } from './data/ElementData';
import { extractElementId } from '../utils/PathUtils';
import type { LibraryContentsData } from './data/LibraryData';
import JSONPath from '../utils/JSONPath';
import type { HasModelBindings } from './utils/HasModelBindings';
import type ItemPool from '../../core/ItemPool';
import type SAMLibrary from '../../libraries/Library';
import type AdobeAsset from '../../assets/AdobeAsset';
