import type Element from './Element';
import type { ElementPoolId, ElementUpdater } from './Element';
import { getCombinedId } from './Element';

/**
 * Store
 * @packageDocumentation
 * @module Store
 * @internal
 *
 * The `Store` follows a Redux-like pattern, where the Store holds the app state,
 * and a reducer function processes actions to update the state:
 * `const newState = reducer(state, action);`.
 *
 * ## State Structure
 * The Store maintains two branches of state:
 * - **`currentData` (exposed as `data`)**: Represents the "current local" state with changes made by the user.
 *   - All actions are immediately applied.
 * - **`baseData`**: Represents the "base" or "last known remote" state.
 *   - "Remote" may refer to Melville or Process.
 *   - Actions are only applied upon a successful REST API call.
 *
 * ## Store Responsibilities
 * 1. Dispatching actions for processing.
 * 2. Committing actions once a remote response is received.
 * 3. Batching actions using `beginOperation` and `endOperation`.
 *
 * ## Reducer Responsibilities
 * Unlike a typical React/Redux reducer, the Store's reducer handles additional logic beyond just updating state:
 * 1. **Basing the operation** – Capturing the original `currentData` before the operation.
 * 2. **Rebasing the operation** – Reconciling changes if the `baseData` has been updated and no longer matches the original state.
 *
 * ## Rebasing Rules
 * 1. If a field modified by the operation remains unchanged in the base, apply the change.
 * 2. If a field modified by the operation has changed, but the change timestamp is **before** the operation timestamp, apply the change.
 * 3. If a field modified by the operation has changed **after** the operation timestamp, discard the change.
 * 4. If all changes are invalidated by (3), remove the operation entirely.
 *
 * ## ItemUpdater vs. Reducer Pattern
 * SAM does not follow a pure reducer pattern but instead uses an **ItemUpdater** pattern.
 * - All subclasses of `ItemBase` (`Element`, `Group`, `Library`) use the **ItemUpdater** pattern.
 * - `LibraryContents`, however, uses the **reducer** pattern for state updates.
 */

/**
 * REFACTOR TODOs:
 * - When supporting CRUD Operations/commits: replace commented out calls to this._modelCache as no actions are supported on libraries here
 * - Specify which methods are internal/package and which are public
 *
 * WHAT WORKS:
 * - getters
 *
 * WHAT DOES NOT YET WORK:
 * - updates/commits/actions
 *
 * NOTES:
 * Store no longer inherits from Model because it does not need to be a subclass of Item,
 * and no longer supports `committed` as there are currently no placeholder libraries in SAM.
 * (Placeholder logic required the id always be defined but for libraryContents the assetId is always defined and id maybe lazy loaded.)
 * Panel needs to be updated to remove `library.committed` check.
 */

export type ActionNotification = {
    // 'type' is really more of a 'state' of the action lifecycle
    // 1. Dispatch: Both Store._actionDispatch() and Store.endOperation() may call this.emit('action', { type: 'dispatch', action }), which leads to Orchestrator._doOperations()
    // 2. Processing: Orchestrator calls this.emit('report', { type: 'processing', action}[]) when it is  about to make a server request (execute an Operation) and commit
    // 3. Commit: Store._commit() updates the base state of the library with one or more actions, removes the action from the library, and calls this.emit('action', { type: 'commit', action })
    // You can listen to either library/group/element.on('action') or orchestrator/CCLibraries.on('report') to receive ActionNotifications.
    type: 'dispatch' | 'processing' | 'commit';
    action: Action;
};

export const operationPending: unique symbol = Symbol('operationPending');

export default class Store extends TypedEventEmitter<any> implements HasModelBindings {
    protected _baseData: LibraryContentsData;
    protected _currentData: LibraryContentsData;
    protected _oldCurrentData_temp: LibraryContentsData | undefined;
    protected _actions: Action[] = [];
    protected _reducer = reducer;
    private _operation: Operation<unknown> | undefined | typeof operationPending = undefined;
    private _isSquelched = false;
    private _receivedEventDuringSquelchPeriod = false;
    private _pendingActionSemaphore = 0; // Track calls to beginOperation()
    private _pendingOperationResolvers: (() => void)[] = [];
    protected _lastLocalUpdateDate = 0;
    protected _previouslySeenEtags = new FIFOStringSet();
    protected _assetPool: ItemPool<SAMLibrary | AdobeAsset>;
    /**
     * @package -- for use in SAM.js only
    */
    // TODO-R[SHARED-3520]: Temporarily public for tests, until we implement getElementById API
    public _elementPool: ItemPool<Element, ElementPoolId>;
    protected _elementUpdater: typeof ElementUpdater;

    /**
     * Pending actions are applied to the current state, but aren't yet ready to be committed.
     * Actions are added to this queue when an operation is in progress.
     */
    protected _pendingActions: Action[] = [];

    constructor(
        readonly _core: ISAMCorePrivate,
        /**
         * @internal
         * @package -- for use in SAM.js only
         */
        // TODO: Later, move internal API to using underscores.
        readonly _apiRoot: ICCLibraries,
        readonly library: SAMLibrary // holds a hard reference to the parent library
    ) {
        super();

        // TODO-R: Consider paring down LibraryContentsData to only these. Might need time stamps though.
        const startingState: LibraryContentsData = {
            // Elements/groups need to be initialized even when the data is not yet available,
            // so that they can be referred to by JSONPath (e.g. '$.elements').
            groups: [],
            elements: [],
            // Not sure if I need these
            assetId: library.id,
            id: library._legacyLibraryId_NoLazyLoad,
        };

        this._baseData = startingState;
        this._currentData = deepCopy(startingState);
        this._assetPool = _apiRoot.assetPool;
        // shared pools across all libraries:
        this._elementPool = _apiRoot.elementPool;
        this._elementUpdater = _apiRoot.elementUpdater;
    }

    // local data (current state in UI)
    get data(): LibraryContentsData {
        return this._currentData;
    }

    // last known remote or process state (regardless of whether the process has pushed the change to the server)
    get baseData(): LibraryContentsData {
        return this._baseData;
    }

    get actions() {
        return this._actions;
    }

    /**
     * @internal
     * @package -- for use in SAM.js only
     */
    _revert() {
        // Clear any remaining actions
        this._actions = [];
        this._pendingActions = [];
        this._pendingActionSemaphore = 0;

        // Revert data back to last committed stable state
        const oldData = this._currentData;
        this._currentData = deepCopy(this._baseData);
        this._updateChildren(oldData, this._currentData);
        this.emit('change');
    }

    /**
     * Enqueue the user-initiated action to make the request to the remote server/process.
     * Also update the local state (currentData) optimistically, so the user sees the change immediately.
     *
     * Specifically this will:
     * 1. Put the action in the pendingActions queue
     * 2. LibraryContents - update currentData using reducer pattern.
     * 3. Children - update (local) data using the ItemUpdater pattern
     * 4. Emit a change event
     *
     * @param action
     * @package -- only for use in SAM.js
     */
    // uses a reducer to update currentData on libraryContents and propagate to the children using the ItemUpdater pattern.
    // However, since the Library class does not support optimistic updates, the Library should NOT be updated here.
    // It will continue to reflect the equivalent of baseData (last known server/process state).
    _actionDispatch(action: Action) {
        // TODO: Optimistic updates are not currently supported on the Library itself in SAM.
        // But SAM does support viewing discarded assets. Therefore, we need to consider preventing actions except for restore on a discarded library.
        // if (this.isDeletedLocally) {
        //     Logger.log(`[LIBRARY] Cannot actionDispatch action on deleted library unless it is for a restore: ${this.id}`);
        //     return;
        // }

        if (!action.path) {
            action.path = '$';
        }

        // TODO: Where should we inject this data? Probably not here.
        if (action.type === 'aggregate') {
            action.actions?.map(subAction => {
                if (subAction.type === 'remove') {
                    const item = JSONPath.get(this._currentData, action.path as string) as any;
                    subAction.baseData = {
                        modifiedDate: item.modifiedDate
                    };
                }
                return subAction;
            });
        }

        if (action.type === 'remove') {
            const item = JSONPath.get(this._currentData, action.path) as any;
            action.baseData = {
                modifiedDate: item.modifiedDate
            };
        }

        if (action.type === 'update') {
            action.baseData = deepCopy(JSONPath.get(this._currentData, action.path));
        }

        // Deep copy the data here so it doesn't get updated via reference.
        if (isInsertAction(action) || isUpdateAction(action)) {
            action.data = deepCopy(action.data);
        }

        const currentData = this._reducer(this._currentData, action);

        if (this.isOperationInProgress) {
            this._pendingActions.push(action);
        } else {
            this._actions.push(action);
        }

        this._currentData = currentData;

        this._lastLocalUpdateDate = Date.now();

        // If the action is a no-op, then the state hasn't changed. No need to update caches
        // or emit a change event since the data didn't actually change.
        if (action.type !== 'no-op') {
            // TODO-R[SHARED-5159]: A 'no-op' action.type from _actionDispatch will not define old/baseData. We need to account for this when implementing CRUD updates, and diffing, in _updateChildren.
            this._updateChildren(action.baseData, currentData);

            // Need to call change listener after caches have been updated. Otherwise we may end up in an inconsistent state.
            this.emit('change');
        }
    }

    /**
     * Post remote modification (on server or process), merge the new data into the store.
     *
     * Specifically this will update:
     * 1. LibraryContents - use reducer pattern to update baseData, then rebase currentData and actions (and placeholderIDs) on top.
     * 2. Children - update using ItemUpdater pattern (Reflects currentData rebased on top of baseData)
     * @param actions   The actions that were committed.
     * @param [etag]    The new etag for the library.
     */
    public _commit(actions: Action[], etag?: string) {
        if (!this._confirmActionsAtHead(actions)) {
            // TODO: Our action may have changed due to feedback from the server. How do we link these together?
            // Something catastrophic has happened and our state is corrupt!
            // throw new Error();
        }

        markSubstitutedPlaceholders(actions);

        // The same actions that have been replayed on the baseData to get the currentData
        // are now replayed on baseData to get the new baseData,
        // effectively bringing baseData up to date with the currentData at commit().
        let newBaseData = { ...this._baseData };
        for (const action of actions) {
            // The actions contain the returned json from each operation in the data property,
            // so we can use that to update the baseData
            newBaseData = this._reducer(newBaseData, action);
            this._actions.shift();
        }

        this._actions = replacePlaceholders(actions, this._actions);

        // All commits should have an etag from the server. We want to update it now for this batch of committed actions.
        if (etag) {
            this._previouslySeenEtags.add(this.etag);
            newBaseData.etag = etag;
        }

        this._lastLocalUpdateDate = Date.now();
        this._update(newBaseData, false);

        actions.forEach(action => {
            // If locally removed/unfollowed library, remove from cache
            // Remotely removed libs are handled in the top level listener (e.g. sync group listener)
            if (isAnyRemoveLibraryAction(action)) {
                // this._modelCache?.remove(this, false);
            }
        });

        this.emit(
            'action',
            ...actions.map<ActionNotification>(action => ({ type: 'commit', action }))
        );

        this.emit('commit');
    }

    private _confirmActionsAtHead(actions: Action[]) {
        if (this._actions.length < actions.length) {
            return false;
        }

        for (const i in actions) {
            if (actions[i] !== this._actions[i]) {
                return false;
            }
        }

        return true;
    }

    // Delay dispatching actions until the outermost endOperation() call, which should result in one atomic batch request, for less server traffic.
    // Note: A more appropriate name at this point would be something like 'startBatchingActions'/'endBatchingActions'
    // since we now have a separate 'Operation' concept, which is a portion of the Driver that represents an atomic API request
    // containing batchable actions, and technically the Operation is not constructed until a _actionDispatch occurs.
    // Meaning the driver Operation doesn't actually exist until the outermost endOperation() is called.
    /**
     * @package -- only for use in SAM.js
     */
    beginOperation() {
        this._squelchChangeEvents();
        this._pendingActionSemaphore += 1;
        Logger.log(`[STORE] Starting operation (Depth: ${this._pendingActionSemaphore})`);
    }

    // On the outermost endOperation call, dispatch all pending actions
    // After the orchestrator has made the server request(s) and called library._commit,
    // resolve all endOperation promises.
    endOperation(_callback?: () => void): Promise<void> {
        this._pendingActionSemaphore = Math.max(0, this._pendingActionSemaphore - 1);
        Logger.log(`[STORE] Ending operation (Depth: ${this._pendingActionSemaphore})`);

        if (this._pendingActionSemaphore === 0) {
            Logger.log(`[STORE] Reached end of operation stack. Adding actions to queue...`);
            const collapsedActions = this._collapseActions(this._pendingActions);
            this._actions = this.actions.concat(collapsedActions);
            this._pendingActions = [];

            this.emit(
                'action',
                ...collapsedActions.map<ActionNotification>(action => ({ type: 'dispatch', action }))
            );

            this._unsquelchChangeEvents();

            return new Promise(resolve => {
                const onCommit = () => {
                    if (this._actions.length) {
                        return; // we still need to listen for 'commit' events
                    }
                    // We only want to resolve all operations' promises after all actions have been committed
                    this._pendingOperationResolvers.forEach(resolve => resolve());
                    this._pendingOperationResolvers = [];
                    resolve();
                    // all side effects following 'commit' events have been handled
                    this.off('commit', onCommit);
                };
                this.on('commit', onCommit);
            });
        }

        return new Promise(resolve => {
            this._pendingOperationResolvers.push(resolve);
        });
    }

    /**
     * @package -- only for use in SAM.js
     */
    // TODO-R: Need to make sure that the refactored change events can be squelched.
    // That means session.commit() for itemUpdater pattern models such as element
    // and emit('change') for Representation and Store
    _squelchChangeEvents() {
        this._isSquelched = true;
    }

    /**
     * @package -- only for use in SAM.js
     */
    _unsquelchChangeEvents() {
        this._isSquelched = false;

        if (this._receivedEventDuringSquelchPeriod) {
            this._receivedEventDuringSquelchPeriod = false;
            this.emit('change');
        }
    }

    emit(eventName: string | symbol, ...args: any[]): boolean {
        if (this._isSquelched && eventName === 'change') {
            this._receivedEventDuringSquelchPeriod = true;
            return this.listenerCount(eventName) > 0;
        }
        return super.emit(eventName, ...args);
    }

    get etag(): string {
        return this._baseData.etag as string;
    }

    set etag(value: string) {
        this._baseData.etag = value;
    }

    /*
        Note: This is a Library operation. (i.e. wait to dispatch until the operation closes)
     */
    get isOperationInProgress() {
        return this._pendingActionSemaphore !== 0;
    }

    /*
        Note: This is an Orchestrator operation. (i.e. batch these compatible dispatched actions)
     */
    set operation(operation: Operation<unknown> | undefined | typeof operationPending) {
        this._operation = operation;
    }

    get operation() {
        return this._operation;
    }

    // TODO: I believe we can deprecate this, as I don't see it being used anywhere.
    // Also, should probably consolidate with library.locallyManaged which comes from data.locallyManaged
    // get isLocallyManaged(): boolean {
    //     return this._apiRoot.isLocallyManaged;
    // }

    /**
     * Iterates through all of the passed-in actions, combines actions that contain changes upon the same element into one action
     * This helps reduce the number of requests we send out
     *
     * @param {DisaptchAction[]} actions An array of actions to execute within the current operation.
     * @returns {Action[]} newActions
     */
    private _collapseActions(actions: Action[]) {
        // For now, all we really need to collapse are create element actions and their subsequent updates

        const newActions: Action[] = [];
        const newElementActions: { [s: string]: InsertAction<ElementData> } = {};
        const updateElementContentActions: { [s: string]: UpdateAction<ElementData> } = {};

        for (const action of actions) {
            if ([ 'updateElement', 'updateElementContent' ].includes(action.name as string) && isUpdateAction(action)) {
                const elementId = extractElementId(action.path as string);
                const newElementAction = newElementActions[elementId as string];

                if (newElementAction) {
                    Logger.log(
                        '[LIBRARY] Identified collapsible action (updateElement). Combining with (createElement)'
                    );

                    newElementAction.data = { ...newElementAction.data, ...action.data };
                    continue;
                }

                const updateElementContentAction = updateElementContentActions[elementId as string];

                if (updateElementContentAction) {
                    updateElementContentAction.data = { ...updateElementContentAction.data, ...action.data };
                    continue;
                }
            }

            if (action.name === 'createElement' && isInsertAction(action)) {
                newElementActions[action.data.id] = action;
            }

            if (action.name === 'updateElementContent' && isUpdateAction(action)) {
                updateElementContentActions[extractElementId(action.path as string) as string] = action;
            }

            newActions.push(action);
        }

        return newActions;
    }

    /**
     * Model APIs
     */

    /**
     * @internal
     * @package -- for use in SAM.js only
     */
    /**
     * When new remote data from the server/process arrives, update the base state, and rebase the current state and action queue on top of it.
     *
     * Specifically this will update the state of:
     * LibraryContents - overwrite the baseData, then rebase the currentData and actions using the reducer pattern
     * Children - update (local) data using the ItemUpdater pattern
     *
     * It will NOT update:
     * Library - When the server update came in, lazy loading library data would already be handled by the Library._load.
     * (Also fyi, since the Library class does not yet support optimistic updates, there is no currentData to rebase in Library.)
     * @param newBase - the newest data from the server
     * @param progressiveLoad
     *  - should be true if the newBase contains an incomplete elements array (e.g. when loading elements page by page in the ElementLoader).
     *    Only handles adding/updating elements. Will not result in deleting any elements (from either base or current data).
     *  - should be false if the newBase contains a full elements array (e.g. when fetching the manifest after a change notification).
     *    Will delete elements that are not in the newBase, in addition to adding/updating elements.
     * @returns the updated base data
    */
    // TODO-R[SHARED-4629]: Also look into why this returns the baseData, unlike on Model. Ideally we can remove this if not needed to keep the API the same.
    _update(newBase: Partial<LibraryContentsData>, progressiveLoad: boolean) {
        // Shallow copy newBase data into existing baseData
        this._mergeBaseData(newBase, progressiveLoad);
        // Rebase action queue (e.g. if an element has been removed, remove the removeElement action) and currentData on top of updated baseData
        this._rebaseCurrentDataAndActions();

        // Unlike the children which use the UpdateSession to emit notifications on the Items upon commit,
        // the Store should just emit a change.
        this.emit('change');
    }

    private _mergeBaseData = (newBase: Partial<LibraryContentsData>, progressiveLoad: Boolean) => {
        // In the case of progressive loading, we should only add/update elements,
        // and not remove any elements in baseData that are missing from the newBase
        if (progressiveLoad === true) {
            const mergeElements = (newElements: ElementData[], baseElements: ElementData[]): ElementData[] => {
                const newElementIds = new Set(newElements.map(el => el.id));
                const unchangedElements = baseElements.filter(el => !newElementIds.has(el.id));
                return unchangedElements.concat(newElements);
            };

            const newElements = newBase.elements || [];
            const baseElements = this._baseData.elements || [];
            newBase.elements = mergeElements(newElements, baseElements);
        }

        this._baseData = { ...this._baseData, ...newBase };  // in case the newBase is a partial object, rather than replace baseData, we merge it in.
    };

    // Rebase currentData and actions on top of the new baseData
    // See the Library conflicts tests and LibraryUtils.rebaseAction tests for more information
    private _rebaseCurrentDataAndActions() {
        let newCurrentData = deepCopy(this._baseData);

        this._actions = this._actions
            .map(action => {
                const rebasedActions = rebaseAction(newCurrentData, action);
                newCurrentData = rebasedActions.reduce(
                    (memo, rebasedAction) => this._reducer(newCurrentData, rebasedAction),
                    newCurrentData
                );
                return rebasedActions;
            })
            .flat();

        this._pendingActions = this._pendingActions
            .map(action => {
                const rebasedActions = rebaseAction(newCurrentData, action);
                newCurrentData = rebasedActions.reduce(
                    (memo, rebasedAction) => this._reducer(newCurrentData, rebasedAction),
                    newCurrentData
                );
                return rebasedActions;
            })
            .flat();

        // This is the local state of models in the pool prior to being updated, which is kept temporarily to diff the latest current data and make appropriate changes to the children.
        // TODO-R[SHARED-4711]: Later on, when we remove this._currentData after updating the children (since it duplicates the same data now saved in the item),
        // we won't have this old data available for this short cut. Getting existing currentData would require finding the
        // elements in the pool for this library, then serializing them into current Data.
        const oldCurrentData = this._currentData;

        // Update local state on the Store.
        // TODO-R[SHARED-4711]: This actually duplicates the data that will be saved in the child Items next.
        // To de-dupe memory usage, we can get rid of this. BUT, currentData will need to be recreated above and in actionDispatch().
        // For more info: https://wiki.corp.adobe.com/display/ACPCSDK/Additional+Changes+to+State+Management
        this._currentData = newCurrentData;

        // Update local state of children using diff of current and previous local data from the Store
        this._updateChildren(oldCurrentData, newCurrentData);
    }

    /**
     * Diff previous and new currentData to determine what has changed.
     * Then update, add, or remove elements accordingly. (Groups to be supported in the future.)
     * Note: oldData and newData are both expected to have a *full* list of elements, (as far as we have fetched so far in the baseData,
     * with any local changes (which may include deletes) rebased on top).
     */
    _updateChildren(oldData: LibraryContentsData, newData: LibraryContentsData) {
        // TODO-R[SHARED-5159]: A 'no-op' action.type from _actionDispatch will not define old/baseData. We need to account for this when implementing CRUD updates, and diffing.
        const elementPool = this._elementPool;
        const session = elementPool.createUpdateSession();
        const newElementsData = newData.elements;
        const oldElementsData = oldData.elements;
        // Find model that matches data.id/previousPlaceholderId and update *before* doing any removals
        const upsertItems = () => {
            /* Note: It would be nice if we could just call `updater.updateRemoteItems(session, newElementsData);`
                to handle both creating and updating items, but it doesn't handle everything that Model._update does,
                such as custom placeholder logic and updating children. In theory, it *could* though.
                We could optimize to combine the compoundId and placeholder logic, and when data comes through the model/elementUpdater,
                it can call a function to do special handling for the id and for child properties like 'representations'. */

            newElementsData.forEach(data => {
                // TODO-R[SHARED-4488]: Use compound id once supported.
                // TODO-R[SHARED-4970]: Make sure placeholderId updates working as expected.
                // TODO-R[SHARED-4971]: When we support CRUD updates, make sure this item has not been deleted locally before updating it.
                const item = data.previousPlaceholderId ? elementPool.getLocalItemById(data.previousPlaceholderId) : elementPool.getLocalItemById(getCombinedId(data));
                if (item) {
                    // Update existing items in the pool
                    // TODO-R[SHARED-5159]: Diff old/new data with deep object equality to check if an update is needed
                    item._update(data); // TODO-R[SHARED-4970]: Ensure this updates the placeholderId to the real id in the Updater
                } else {
                    // Create new items in the pool
                    // TODO-R[SHARED-4970]: Consider whether placeholder IDs will ever need to be considered here.
                    // I believe that if the change is always coming from the server, there won't be any placeholder IDs.
                    // But we need to analyze each use case of updateChildren() to be sure.
                    this._elementUpdater.updateRemoteItem(session, data);
                }
            });
        };
        const removeItems = () => {
            // 1. Get a set of IDs from new data
            const currentDataIds = new Set(newElementsData.map(data => data.id));
            // 2. Find the models that are not included in the updated set
            const removedItems = oldElementsData.filter(data => !currentDataIds.has(data.id)); // May include some that had placeholder IDs
            // 3. Remove those models from the pool
            removedItems.forEach(data => {
                const item = elementPool.getLocalItemById(getCombinedId(data)); // Should not return an item if using its old placeholder id
                if (item) {
                    session.queueDiscardedItem(item);
                }
                // Note: It is sufficient to call queueDiscardedItem and not elementPool.removeLocalItem(item) because
                // the item should not be updated in upsertItems() as there should be no overlap between the removedItems and newElementsData.
            });
        };

        upsertItems();
        removeItems();
        session.commit();
    }

    /**
     * @internal
     * @package -- for use in SAM.js only
     */
    get _driver() {
        return this._apiRoot.driver;
    }
}
