import { keepAlive } from './decorators/KeepAliveManager';
import type {
    IItemSourceConfig,
    IItemList,
    ILoadOptions } from './ItemList';
import ItemList, {
    LIST_FULLY_LOADED,
} from './ItemList';
import { AssetListStatus } from './ItemLoaderState';
import type { IItemLoader } from './ItemLoader';
import type { ItemFilterRelation } from './ItemFilter';
import { getFiltersRelation } from './ItemFilter';
import type ItemPool from './ItemPool';
import WeakRef from './WeakRef';
import SAMError, { SAMErrorCode } from './SAMError';
import EverythingFilter from './EverythingFilter';
import { waitForListLoad } from '../utils/waitForListLoad';
import type { ItemId } from './ItemBase';

type IListHash = string;
type ListByHash<ItemListType extends object> = Map<IListHash, WeakRef<ItemListType>>;

type IListCandidate<ItemListType> = {
    list: ItemListType;
    filterRelation: ItemFilterRelation | undefined;
    generation: number;
    length: number;
}

// TODO: change OrderDirection/Field to use SAM.cpp enums
// https://jira.corp.adobe.com/browse/SAM-1644
export enum OrderDirection {
    Ascending,
    Descending
}
export enum OrderField {
    Name,
    Modified,
    Created,
    Shared
}

function candidateSort<ItemListType>(a: IListCandidate<ItemListType>, b: IListCandidate<ItemListType>): number {
    if (a.filterRelation !== b.filterRelation) {
        // We prefer to start from a list that contains as many items as possible,
        // so a list that can generate a complete `subset` must be moved to the left.
        return a.filterRelation === 'subset' ? -1 : 1;
    }

    if (a.generation !== b.generation) {
        // Newer generations must be moved to the left.
        // Return a negative number if a.generation is larger.
        return b.generation - a.generation;
    }

    // Lists with more items move left.
    // Return a negative number if a.length is larger.
    return b.length - a.length;
}

/**
 * ItemSource is the primary class and interface for interacting with lists of items
 * throughout SAM.js. It holds the only reference to the cache of lists which allows
 * SAM.js to be much more efficient when applying new filters and fetching new lists.
 *
 * @usage Instances of to this class must be cached so clients can
 * take advantage of shared cached lists.
 */

export default class ItemSource<ItemConfig extends IItemSourceConfig, IdType extends ItemId = ItemId> {

    private _lists: ListByHash<ItemList<ItemConfig, IdType>> = new Map();

    // To ensure that we always have an implicit filter, we will use the EverythingFilter as a default

    /**
     * @package -- for use in SAM.js only
     */
    _loaders: IItemLoader<ItemConfig>[];

    constructor(
        private _itemPool: ItemPool<ItemConfig['type'], IdType>,
        loaders: IItemLoader<ItemConfig>[],
        protected _implicitFilter: ItemConfig['implicitFilter'] = new EverythingFilter()
    ) {
        this._loaders = loaders;
    }

    // [SAM-2302] SAMCpp.ts patches SAM.cpp to support two different call signatures. Once CDO has moved to using
    // SAM.js-style getList and SAM.cpp supports the SAM.js call signature, this can be removed.
    getList(orderDir: OrderDirection, orderField: OrderField): IItemList<ItemConfig>;
    // eslint-disable-next-line no-dupe-class-members
    getList(order: ItemConfig['order'], filter?: ItemConfig['filter'], loadOptions?: ILoadOptions): IItemList<ItemConfig>;
    // To ensure that we always have an explicit filter, we will use the EverythingFilter as a default
    // eslint-disable-next-line no-dupe-class-members
    @keepAlive
    getList(
        order: (ItemConfig['order'] | OrderDirection),
        filter: (ItemConfig['filter'] | OrderField) = new EverythingFilter(),
        loadOptions?: ILoadOptions
    ): IItemList<ItemConfig> {
        if (typeof order === 'number' || typeof filter === 'number') {
            throw SAMError.create(
                SAMErrorCode.UNSUPPORTED,
                'Using OrderDirection and OrderField is not implemented in SAM.js, and will be deprecated in SAM.cpp'
            );
        }

        let list: ItemList<ItemConfig, IdType> | undefined = this._getExistingList(order, filter);

        // If the list has been deactivated, then we cannot use the list anymore
        // and we have to create a new one.

        if (!list) {
            // If this is an internal list, then we can bootstrap the
            // contents of the list based on a similar list in the cache.
            // This way we don't have to reload the contents when changing
            // sort order.
            const mostCompleteList = this._getMostCompleteCompatibleList(filter);
            list = new ItemList<ItemConfig, IdType>(
                this._itemPool,
                this._loaders,
                order,
                this._implicitFilter,
                filter,
                mostCompleteList,
                loadOptions
            );
            // When a list fully loads, copy its items to other compatible lists
            list.on(LIST_FULLY_LOADED, () => this._onListFullyLoaded(list!));
            this._lists.set(this._getListHash(order, filter), new WeakRef(list));
        } else {
            // The client may be passing in different loadOptions than what was specified for the
            // existing List. Try to accommodate these new options without negatively impacting
            // other clients of the same List. If the client did not explicitly specify refreshTimeout, assume
            // that the existing list should not be refreshed. This is for better backward-compatibility for
            // cases where clients expected that `getList()` would not automatically load data in order to make use
            // of a cached List.
            list._updateLoadOptions({ refreshTimeout: -1, ...loadOptions });
        }

        if (list.status === AssetListStatus.NotStarted) {
            // Start loading.
            list.refresh();
        }

        return list;
    }

    /**
     * @TODO_Deprecation will be marked as deprecated on or after 2024-10-01 and removed on or after 2025-01-01
     */
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    getListWithTypes(orderDir: OrderDirection, orderField: OrderField, types: string[]) {
        throw SAMError.create(SAMErrorCode.UNSUPPORTED, 'getListWithTypes is not implemented in SAM.js and will be deprecated in SAM.cpp');
    }

    private _getListHash(order: ItemConfig['order'], filter: ItemConfig['filter']): string {
        return `${filter.hash}:${order.hash}`;
    }

    /**
     * @package -- for use in SAM.js only
     */
    _getExistingList(order: ItemConfig['order'], filter: ItemConfig['filter']): ItemList<ItemConfig, IdType> | undefined {
        const existingHash = this._getListHash(order, filter);
        const listWeakRef = this._lists.get(existingHash);
        if (listWeakRef) {
            return listWeakRef.deref();
        }
    }

    public setNeedsRefresh() {
        for (const list of this._getLists()) {
            list.setNeedsRefresh();
        }
    }

    /**
     * Find an already loaded list that is a good candidate to borrow items for when creating a new list.
     *
     * For example, switching the sorting order of a list would have the same filter,
     * so it should be ok to just run that entirely on the client side.
     *
     * Another example is filtering down some items. If we already loaded a list that contained these items,
     * then we can build the filtered down list by just executing the same filter on the client side.
     *
     * @param requestedFilter Filter of the new list.
     * @returns The best candidate list that could be used as a starting point.
     */
    private _getMostCompleteCompatibleList(requestedFilter?: ItemConfig['filter']): IItemList<ItemConfig> | undefined {
        const candidates: IListCandidate<IItemList<ItemConfig>>[] = [];

        for (const list of this._getLists()) {
            if (list.status === AssetListStatus.ReadyFullyLoaded) {
                const filterRelation = getFiltersRelation(requestedFilter, list.filter);
                if (filterRelation !== 'disjoint') {
                    candidates.push({ list, filterRelation, generation: list.generation, length: list.items.length });
                }
            }
        }

        // We want to pick the item with the newest items, or the list that has the largest subset of items.
        candidates.sort(candidateSort);

        // The first item in the list is the best candidate.
        return candidates[0]?.list;
    }

    /**
     * @package -- for use in SAM.js only
     */
    *_getLists() {
        const lists = this._lists;
        for (const [ hash, listRef ] of lists.entries()) {
            const list = listRef.deref();
            if (!list) {
                // The weak ref has expired, remove it from the map.
                // Note that JS Maps are ok with deletions during iteration.
                lists.delete(hash);
                continue;
            }
            yield list;
        }
    }

    /**
     * Copies fully loaded lists to compatible lists when load completes.
     */
    private _onListFullyLoaded(loadedList: ItemList<ItemConfig, IdType>) {
        if (loadedList.status !== AssetListStatus.ReadyFullyLoaded) {
            return;
        }

        for (const list of this._getLists()) {
            // Other lists that are subsets of the loaded list can be inferred to be fully loaded, too.
            if (list !== loadedList
                && getFiltersRelation(list.filter, loadedList.filter) === 'subset'
            ) {
                // Don't update lists that are loading, as it could interfere with its generation tracking
                waitForListLoad(list).then(() => {
                    // Skip lists that are fresher than the loaded list
                    if (list.completedGeneration >= loadedList.completedGeneration) {
                        return;
                    }
                    list._applyListItemsFrom(loadedList);
                });
            }
        }
    }
}

