interface IACPLAssetContext {
    getAssetWithCloudID(assetID: string): AdobeAsset;
    recentsSource: RecentAdobeAssetSource;
    rootFolder: AdobeAsset;
    on(event: string, listener: (data: any) => void): void;
    off(event: string, listener: (data: any) => void): void;

    /** @package Only used here for the SAM-C++ patches. */
    _isForwardingAssetChangeEvents?: boolean;
    /** @deprecated -- will be removed on or after 2024-10-01 */
    spaceContext: any;
}

export const SAM_CPP_ITEM_EVENTS = [ 'refreshed', 'movedAsset', 'addedAsset', 'removedAsset' ];
export const LIST_CHANGE_DELAY_MS = 120;

export interface IACPLModel {
    waitForApplicationContextReady(): Promise<IACPLAssetContext>;
    getHostAssetContext(): Promise<IACPLAssetContext>;
    trigger(event: string, data: any): void;
    on(event: string, listener: (data: any) => void): void;
    off(event: string, listener: (data: any) => void): void;

    getLocalAssets?(): Promise<LocalAssetMetadata[]>;
    /** ACPL.next polyfill */
    downloadComposite?(assetID: string): Promise<void>;
    /** ACPL.next polyfill ("unpin" is just to remove the composite from cache) */
    unpin?(assetID: string): Promise<void>;

    applicationAssetContext: IACPLAssetContext;
    version: string;
}

/*
NOTE when testing in UXP SAM Demo app:

When using Chrome debugger to refresh the JS source code, it does not destroy and recreate the SAM.cpp
JS prototypes, so any changes made to this file will not be applied despite appearing in the source
inspector. You have to quit the SAM.cpp demo app and restart.
*/

// Use a getter so that unit tests can inject a mock acplModel
export function getACPLModel(): IACPLModel | undefined {
    // NOTE: must use this syntax for accessing properties of `window`, or else it will break NodeJS clients
    // like Libraries.
    // @ts-expect-error
    return typeof window !== 'undefined' ? window?.acplModel : undefined;
}

// Convert semver into a padded string that can be compared lexically
function parseVersion(version: string = ''): string {
    // Old SAM.cpp versions looked like 2.0.0-main.1234, where the final number was the
    // patch version. Current SAM.cpp uses standard semver major.minor.patch.
    const parts: string[] = version.split('.');

    // Coerce old SAM.cpp version into a standard semver, like 2.0.1234, by
    // deleting the '0-main' element
    if (parts[2] === '0-main') {
        parts.splice(2, 1);
    }
    // Ensure each part has some value
    const [ major = '0', minor = '0', patch = '0' ] = parts;
    // '2.0.1234' becomes '000200001234'
    return [ major, minor, patch ].map(part => part.padStart(4, '0')).join('');
}

function isSAMCppVer(comparison: 'lt' | 'gte', version: string) {
    const aVer = parseVersion(getACPLModel()?.version);
    const bVer = parseVersion(version);
    switch (comparison) {
    case 'lt': return aVer < bVer;
    case 'gte':return aVer >= bVer;
    default: return false;
    }
}

