// See note above about testing in UXP SAM demo app
export function patchAssetContext(core: ISAMCorePrivate) {
    const acplModel = getACPLModel()!;
    // TODO: expose SAM.cpp AssetContext as acplModel.AssetContext
    // https://jira.corp.adobe.com/browse/SAM-1365
    const AssetContextJS = acplModel.applicationAssetContext.constructor;

    // TODO: update actual version when the issues below are fixed
    if (isSAMCppVer('lt', '9999.9999.9999')) {
        ExtendClass({
            klass: AssetContextJS,
            core,
            overrides: {
                // SAM.cpp does not support optional param
                getAssetWithCloudID(this: any, id: string, confirmAccess: boolean = false) {
                    return this.getAssetWithCloudID.original(id, confirmAccess);
                },
                // SAM.cpp does not support optional param
                getAssetWithAssetRefString(this: any, assetRefString: string, confirmAccess: boolean = false) {
                    return this.getAssetWithAssetRefString.original(assetRefString, confirmAccess);
                }
            },
            extensions: {
                // SAM.cpp hasn't implemented AssetContext#getUserRepoId(). This method was added to
                // address *SAM-1888*. This patch can be removed when SamCpp supports AssetContext#getUserRepoId()
                getUserRepoID(this: any) {
                    // Can't use hostAssetContext.getUserRepoID() because it needs hostAssetContext.itemPool,
                    // which doesn't exist on SAM.cpp hostAssetContext.
                    if (!this._userRepoID) {
                        return this._core._AssetContextJS._rapi.getHomeDirectoryMetadata()
                            .then((homeDirectoryMetadata: RepositoryMetadata) => {
                                this._userRepoID = homeDirectoryMetadata['repo:repositoryId'];
                                return this._userRepoID;
                            });
                    }
                    return Promise.resolve(this._userRepoID);
                },

                transfer(this: any, source: AdobeAsset, target: AdobeAsset | Space): Promise<string> {
                    return (async () => {
                        let targetId: string;
                        if (target instanceof Space) {
                            const workingFiles = await target.getChild('working_files');
                            if (!workingFiles) {
                                throw SAMError.create(SAMErrorCode.NOT_FOUND, 'unable to find working_files for provided space');
                            }
                            targetId = workingFiles.id;
                        } else {
                            targetId = target.cloudID;
                        }

                        // ACPL substitutes ~ for user's repoID
                        let sourceRepoID = source.repositoryID;
                        let targetRepoID = target.repositoryID;
                        if (sourceRepoID === '~') {
                            sourceRepoID = await this.getUserRepoID();
                        }
                        if (targetRepoID === '~') {
                            targetRepoID = await this.getUserRepoID();
                        }

                        const payload = {
                            source: { assetId: source.cloudID, repositoryId: sourceRepoID },
                            target: { assetId: targetId, repositoryId: targetRepoID }
                        };

                        return this._core._AssetContextJS._assetTransferService.transfer(payload);
                    })();
                },

                // For code in SAM.js that needs to use the ItemPool from SAM.js, like SpaceContext.moveSpace()
                /**
                 * @deprecated To be removed on or after 2024-10-01.
                 */
                assetPool: {
                    get(this: any) {
                        oneTimeWarning('SAMCpp.ts _assetPool', 'AssetContext._assetPool is deprecated and will be'
                            + ' removed on or after 2024-10-01. ItemPools are not for use by clients.');
                        return this._core._AssetContextJS._assetPool;
                    }
                },

                /**
                 * @package -- for use in SAM.js only
                 */
                _assetPool: {
                    get(this: any) {
                        return this._core._AssetContextJS._assetPool;
                    }
                },

                isOnline: {
                    get(this: any) {
                        return this.networkStatus !== undefined ? this.networkStatus !== NetworkStatus.Offline : undefined;
                    }
                },

                // Most JS clients never used recentsSource, so use the SAM.js name
                recentAssetsSource: {
                    get(this: any) {
                        return this.recentsSource;
                    }
                },

                getRootFolder(this: any): Promise<AdobeAsset> {
                    return Promise.resolve(this.rootFolder);
                },

                assetsHaveArtifacts(assets: AdobeAsset[]) {
                    return (async () => {
                        // @ts-expect-error
                        if (assets.some((a: AdobeAsset) => !a.routesToAcplV2)) {
                            return false;
                        }

                        const assetReviewServiceInterface = new AssetReviewServiceInterface(core);
                        const assetIndentifiers: IReviewServiceAssetIdentifer[] = mapAssetsToAssetIndentifier(assets);
                        const results = await assetReviewServiceInterface.hasOutputs(assetIndentifiers);
                        if (results.length === 0) {
                            return false;
                        }

                        results.forEach((asset) => {
                            const foundAsset = assets.find((a) => a.id === asset['repo:assetId']);
                            if (!foundAsset) {
                                return;
                            }

                            foundAsset['_hasArtifacts'] = true;
                            foundAsset.dispatch({ type: 'change' });
                        });

                        return true;
                    })();
                }
            },
            observableMap: {
                'networkChanged': [ 'networkStatus' ],
                'stateChanged': [ 'cloudSyncStatus' ]
            }
        });
        const onAssetsChanged = ({ properties, status, previews }: IAssetsChangedEvent) => {
            for (const asset of [ ...properties, ...status ]) {
                asset._onAssetChanged?.();
            }

            for (const asset of previews) {
                asset?._onRenditionChanged?.();
            }
        };
        // only subscribe once
        if (!acplModel.applicationAssetContext._isForwardingAssetChangeEvents) {
            acplModel.applicationAssetContext.on('changedAssets', onAssetsChanged);
            acplModel.applicationAssetContext._isForwardingAssetChangeEvents = true;
        }
    }
}

// See note above about testing in UXP SAM demo app
export function patchAssetSource(core: ISAMCorePrivate) {
    const acplModel = getACPLModel()!;

    const dirMap: { [key in IOrderDirection]: OrderDirection } = {
        ascending: OrderDirection.Ascending,
        descending: OrderDirection.Descending
    };

    const fieldMap: { [key in AdobeAssetOrderField]: OrderField} = {
        name: OrderField.Name,
        modified: OrderField.Modified,
        created: OrderField.Created,
        shared: OrderField.Shared,
        lastAccessed: OrderField.Modified
    };

    const AssetSource = acplModel.applicationAssetContext.rootFolder.children!.constructor;

    // TODO: update actual version when the issues below are fixed
    if (isSAMCppVer('lt', '9999.9999.9999')) {
        ExtendClass({
            klass: AssetSource,
            core,
            overrides: {
                // SAM.cpp doesn't support Order/Filter objects that SAM.js clients are using. Meanwhile,
                // clients like CDO are expecting the SAM.cpp call signature, so both APIs are supported here.
                getList(this: any, maybeOrder: (AdobeAssetOrder | OrderDirection), maybeFilter?: (AdobeAssetFilter | OrderField)) {
                    let field: OrderField;
                    let dir: OrderDirection;

                    // if both `direction` and `field` are defined, then it is an AdobeAssetOrder instance
                    const order = maybeOrder as AdobeAssetOrder;
                    if (order.direction ?? order.field ?? true) {
                        dir = dirMap[order.direction];
                        field = fieldMap[order.field];
                    } else {
                        dir = maybeOrder as OrderDirection;
                        field = maybeFilter as OrderField;
                        maybeFilter = undefined;
                    }

                    // Fallback to safe defaults
                    dir = (dir in OrderDirection) ? dir : OrderDirection.Descending;
                    field = (field in OrderField) ? field : OrderField.Modified;

                    const filter = maybeFilter as AdobeAssetFilter;
                    let list: any;
                    // Note: if mediaTypes is undefined, it should use the default filter (SAM.cpp only)
                    // If mediaTypes is an empty array, that means "show everything".
                    if (filter?.mediaTypes) {
                        list = this.getListWithTypes(dir, field, [ ...filter.mediaTypes ]);
                    } else {
                        list = this.getList.original(dir, field);
                    }
                    // Note: must patch AssetList before patching AssetSource or else next line will throw an exception
                    list._addEventInterceptors();
                    return list;
                }
            }
        });
    }
}

// See note above about testing in UXP SAM demo app
export function patchAssetList(core: ISAMCorePrivate) {
    const acplModel = getACPLModel()!;

    const SAM_CPP_ITEM_EVENTS = [ 'refreshed', 'movedAsset', 'addedAsset', 'removedAsset' ];
    const SAM_CPP_STATUS_EVENT = 'statusChanged';

    // TODO: expose AssetSource, AssetList as acplModel.AssetSource, acplModel.AssetList
    // https://jira.corp.adobe.com/browse/SAM-1365
    const assetSource = acplModel.applicationAssetContext.rootFolder.children!;
    const AssetList = assetSource.getList(OrderDirection.Descending, OrderField.Modified).constructor;

    // TODO: update actual version when the issues below are fixed
    if (isSAMCppVer('lt', '9999.9999.9999')) {
        ExtendClass({
            klass: AssetList,
            core,
            extensions: {
                // SAM.cpp doesn't have loadNextPage, so map to loadMoreItems
                loadNextPage(this: any) {
                    return this.loadMoreItems();
                },
                // TODO: deprecate SAM.cpp load() and add refresh()
                //       https://jira.corp.adobe.com/browse/SAM-2099
                refresh(this: any) {
                    return this.load();
                },
                // patchAssetSource calls this
                _addEventInterceptors(this: any) {
                    // only subscribe once
                    if (!this._onError) {
                        this._onError = (error: string) => {
                            this._errors = this._errors || [];
                            this._errors.push(error);
                            this.dispatch(SharedStateChangedEvent);
                        };
                        this.on('error', this._onError);
                    }

                    if (!this._onListNotification) {
                        this._onListNotification = throttle(() => {
                            // Invoke the SAM.cpp items getter
                            this._items = this[$OVERRIDDEN_GETTERS]['items'].call(this);
                            this.dispatch(SharedListChangedEvent);
                            // Also fire status change so that items list is at the expected contents
                            // when the status changes. Clients may post-process and cache list items
                            // from SharedListChangedEvent, so SharedStateChangeEvent must be fired
                            // afterward to ensure their cache has all expected items when the status changes.
                            this.dispatch(SharedStateChangedEvent);
                        }, LIST_CHANGE_DELAY_MS);

                        // SAM.cpp fires 4 different events for list change, but SAM.js clients only expect 1.
                        SAM_CPP_ITEM_EVENTS.forEach(eventName => this.on(eventName, this._onListNotification));
                    }

                    if (!this._onStatusChange) {
                        this._onStatusChange = () => {
                            // After calling getList, clients should immediately receive the Loading
                            // status change event
                            if (this.status === AssetListStatus.Loading) {
                                this.dispatch(SharedStateChangedEvent);
                            } else {
                                this._onListNotification();
                            }
                        };
                        this.on(SAM_CPP_STATUS_EVENT, this._onStatusChange);
                    }
                },
                errors: {
                    get(this: any) {
                        // Mobx observes under the SAM.js status event, rather than the CPP events
                        this._core._environment.mobx.reportObserved(this, SharedStateChangedEvent.type);
                        return this._errors;
                    }
                }
            },
            overrides: {
                load(this: any) {
                    this._errors = undefined;
                    this.load.original();
                    this.dispatch(SharedStateChangedEvent);
                },
                loadMoreItems(this: any) {
                    this.loadMoreItems.original();
                    this.dispatch(SharedStateChangedEvent);
                },
                // SAM.cpp creates a new Array instance and populates it every time clients call `list.items`, which
                // adds a small (but non-zero) performance hit, and has unexpected behavior like
                // `list.items !== list.items`. This patch caches the SAM.cpp items Array.
                items: {
                    get(this: any) {
                        this._core._environment.mobx.reportObserved(this, SharedListChangedEvent.type);
                        if (!this._items) {
                            // Invoke the SAM.cpp getter
                            this._items = this[$OVERRIDDEN_GETTERS]['items'].call(this);
                        }
                        return this._items;
                    }
                }
            },
            observableMap: {
                // This makes 'status' property observable under the SAM.js SharedStateChangedEvent
                [SharedStateChangedEvent.type]: [ 'status' ]
                // The 'items' property is made observable in the getter override under the SharedListChangeEvent
            }
        });
    }
}

// @TODO Will be used once https://jira.corp.adobe.com/browse/SAM-2145 is resolved.
export function patchTeamList(core: ISAMCorePrivate): void {
    const acplModel = getACPLModel()!;
    if (isSAMCppVer('gte', '9999.9999.9999')) {
        return;
    }

    const spacesContext = acplModel.applicationAssetContext.spaceContext;
    const teamsList = spacesContext.getTeams()
        .getList(OrderDirection.Descending, OrderField.Name).constructor;
    ExtendClass({
        klass: teamsList,
        core,
        extensions: {
            // TODO: deprecate SAM.cpp load() and add refresh()
            //       https://jira.corp.adobe.com/browse/SAM-2099
            refresh(this: any) {
                return this.load();
            }
        }
    });
}

// See note above about testing in UXP SAM demo app
export function patchAdobeAsset(core: ISAMCorePrivate) {
    const acplModel = getACPLModel()!;
    const ACPLAsset = acplModel.applicationAssetContext.rootFolder.constructor;
    // TODO: update actual version when the issues below are fixed
    if (isSAMCppVer('lt', '9999.9999.9999')) {
        ExtendClass({
            klass: ACPLAsset,
            core,
            overrides: {
                restore(this: any, name?: string) {
                    if (this.isLibraryElement) {
                        // SAM.cpp doesn't support restoring CCLibrary Elements
                        return this._core._AssetContextJS.restoreLibraryElement(this.cloudID);
                    } else {
                        return this.restore.original(name);
                    }
                },
                permanentlyDelete(this: any) {
                    if (this.isLibraryElement) {
                        // SAM.cpp doesn't support permanently deleting CCLibrary Elements
                        return this._core._AssetContextJS.permanentlyDeleteLibraryElement(this.cloudID);
                    } else {
                        return this.permanentlyDelete.original();
                    }
                },
                duplicate(this: any) {
                    return this.duplicate.original(false /*overWriteExisting*/);
                }
            },
            extensions: {
                // SAM.cpp doesn't have a `_setCollaboratorData`, which is called when the bulk fetch response is received in _handleBatchRequest.
                _setCollaboratorData(this: any, updatedCollaborators: Collaborator[]) {
                    AdobeAsset.prototype._setCollaboratorData.apply(this, [ updatedCollaborators ]);
                    this._isCollaboratorDataLoaded = true;
                    this.dispatch(SharedCollaboratorChangedEvent);
                },
                _queueCollaborators() {
                    if (!this._isCollaboratorDataLoaded) {
                        AdobeAsset.prototype._queueCollaborators.apply(this);
                    }
                },
                // SAM.cpp doesn't have a `isShared` property
                isShared: {
                    get(this: any) {
                        this._core._environment.mobx.reportObserved(this, COLLABORATOR_CHANGED);
                        // SWY Assets are shared, so no need to load collaborator data
                        // if isSharedWithYouAsset is false, it might not be known if it is a SWY item
                        if (this.isSharedWithYouAsset) { return true; }
                        this._queueCollaborators();
                        return this._isShared;
                    }
                },
                // SAM.cpp doesn't have a `directCollaboratorCount` property
                directCollaboratorCount: {
                    get(this: any) {
                        this._core._environment.mobx.reportObserved(this, COLLABORATOR_CHANGED);
                        this._queueCollaborators();
                        return this._directCollaboratorCount;
                    }
                },
                // SAM.cpp doesn't have a `collaboratorArray` property
                collaboratorArray: {
                    get(this: any) {
                        this._core._environment.mobx.reportObserved(this, COLLABORATOR_CHANGED);
                        this._queueCollaborators();
                        return this._collaboratorsArray;
                    }
                },
                // SAM.cpp doesn't have an `isPublicLink` property
                isPublicLink: {
                    get(this: any) {
                        this._core._environment.mobx.reportObserved(this, COLLABORATOR_CHANGED);
                        this._queueCollaborators();
                        return this._isPublicLink;
                    }
                },
                // SAM.cpp doesn't have an `id` property
                id: {
                    get(this: any) {
                        // `id` is observable because cloudID and localID are observable
                        // due to defaultObservableEvent
                        return this.cloudID || this.localID;
                    }
                },
                // SAM.cpp doesn't expose leave
                removeCurrentUserFromCollaborationList(this: any): Promise<void> {
                    return this._core.collaborationContext._removeCurrentUserFromCollaborationList(this);
                },
                // SAM.cpp doesn't expose discard
                discard(this: any) {
                    // For Projects items, archive() will do a discard
                    return this.archive().then(() => {
                        if (!this.routesToAcplV2) {
                            oneTimeWarning('discardAsArchive',
                                `Asset.discard(): '${this.repoPath}' will be archived rather than discarded`
                                + ' because it routes to ACPL v1 rather than V2.');
                        }

                        // Archive might not be complete in the cloud yet, so monitor via event listener
                        const discardOutputs = () => {
                            // If the asset is not discarded or does not have artifacts
                            // or does not route to ACPLv2 we don't want to attempt to discard
                            // the outputs folder.
                            if (!this.isDiscarded || !this._hasArtifacts || !this.routesToAcplV2) { return; }

                            const assetReviewServiceInterface = new AssetReviewServiceInterface(this._core);
                            assetReviewServiceInterface.discardOutputsForAsset(this.id).then(() => {
                                this._hasArtifacts = false;
                                this.off(SharedChangeEvent.type, discardOutputs);
                            });
                        };

                        this.on(SharedChangeEvent.type, discardOutputs);

                        // in case it did complete in the cloud
                        if (this.isDiscarded && this._hasArtifacts) { discardOutputs(); }
                    });
                },
                // SAM.cpp doesn't have `links`
                links: {
                    get(this: any) {
                        // Can't infer the real links because there's no way to know the real region the Asset is
                        // hosted. Can't use the generalized endpoints, because when the service redirects to the
                        // regionalized endpoint, it can drop the auth headers, causing the redirect to fail. For
                        // now, return empty object to prevent `undefined` errors.
                        return {};
                    }
                },
                hasPermission(this: any, ...permissions: Permission[]): boolean {
                    this._core._environment.mobx.reportObserved(this, SharedPermissionsChangeEvent.type);
                    const hasPermissions = !!this._permissions && AdobeAsset.prototype.hasPermission.apply(this, permissions);
                    if (!this._hasLoadedPermissions) {
                        // prevent loading when already loading
                        this._hasLoadedPermissions = true;
                        this._core._AssetContextJS._rapi.resolveById(this.cloudID)
                            .then(async (assetInterface: AssetInterface) => {
                                const resource = new EffectivePermissionsResource(this._core);
                                await assetInterface.getEffectivePermissions(resource);
                                return resource.data;
                            })
                            .then((permissions: Permission) => {
                                this._permissions = permissions;
                                this.dispatch(SharedPermissionsChangeEvent);
                            });
                    }
                    return hasPermissions;
                },
                // SAM.cpp doesn't have thumbnailURL
                thumbnailURL: {
                    get(this: any) {
                        this._core._environment.mobx.reportObserved(this, SharedThumbnailChangeEvent.type);
                        // Library Elements do not work on SAM.cpp at all
                        if (this.isFolder || this.isLibraryElement) {
                            return '';
                        }
                        if (this._refreshThumbnail || !this._thumbnailInfo) {
                            // Prevent multiple calls to getThumbnailRendition. ACPLAsset.ts didn't retry
                            // on reject, so this code shouldn't need to.
                            this._refreshThumbnail = false;
                            this._thumbnailStatus = RenditionStatus.Fetching;
                            this.getThumbnailRendition()
                                .then(({ file, hash }: { file: string, hash: string }) => {
                                    this._thumbnailStatus = RenditionStatus.Done;
                                    if (this._thumbnailInfo?.file === file && this._thumbnailInfo?.hash === hash) {
                                        return; // no change
                                    }
                                    // `#` and `^` must be encoded separately to work in UXP
                                    file = file.replace('#', '%23').replace('^', '%5E');

                                    const url = new URL(`file://${file}`);
                                    setURLSearchParams(url, {
                                        force: hash
                                    });
                                    this._thumbnailInfo = {
                                        file,
                                        hash,
                                        url: url.href
                                    };
                                    this.dispatch(SharedThumbnailChangeEvent);
                                })
                                .catch(() => {
                                    this._thumbnailStatus = RenditionStatus.Error;
                                    // Use empty thumbnailInfo so that re-render due to the status change doesn't try to
                                    // fetch, which will probably still fail, getting stuck in a loop.
                                    this._thumbnailInfo = {};

                                    this.dispatch(SharedThumbnailChangeEvent);
                                });
                        }
                        // While waiting for thumbnail, return existing thumbnail (if it exists) so the
                        // UI doesn't go blank while waiting.
                        return this._thumbnailInfo?.url || '';
                    }
                },

                thumbnailStatus: {
                    get(this: any) { return this._thumbnailStatus ?? RenditionStatus.NotStarted; }
                },

                getRenditionURL() {
                    oneTimeWarning(
                        'getRenditionURL',
                        'SAM.cpp does not support all options of getRenditionURL. Clients that run on web'
                        + ' and desktop should use AdobeAsset.thumbnailURL instead.');
                    return this.thumbnailURL;
                },

                renditionURLStatus(this: any) { return this.thumbnailStatus; },

                clearRenditionError(this: any) {
                    if (this._thumbnailStatus === RenditionStatus.Error) {
                        this._thumbnailStatus = RenditionStatus.NotStarted;
                        this._thumbnailInfo = undefined;
                        this._refreshThumbnail = true;
                        this.dispatch(SharedThumbnailChangeEvent);
                    }
                },

                // SAM.cpp fires Asset events via AssetContext, but SAM.js emits them from AdobeAsset
                _onAssetChanged(this: any) {
                    this.dispatch(SharedChangeEvent);
                },
                _onRenditionChanged(this: any) {
                    this._refreshThumbnail = true;
                    // Raise event so only clients that are observing will refresh the thumbnail
                    this.dispatch(SharedThumbnailChangeEvent);
                },
                transferToSpace(this: AdobeAsset, target: Space | AdobeAsset) {
                    return this._core.hostAssetContext.transfer(this, target);
                },
                // SAM.cpp doesn't have versions
                versions: {
                    get(this: any) {
                        if (this._assetVersionSource) { return this._assetVersionSource; } // memoize
                        const versionPool = new ItemPool<AssetVersion>(this._core, 'version');
                        const getAssetInterface = this._core._AssetContextJS._rapi.resolveById(this.id);
                        const loader = new AssetVersionLoader(versionPool, getAssetInterface);
                        this._assetVersionSource = new ItemSource(versionPool, [ loader ], new EverythingFilter());
                        return this._assetVersionSource;
                    }
                },
                // SAM.cpp doesn't have getCommentsResource
                getCommentsResource(this: any): Promise<CommentsResource> {
                    if (!this._commentsResource) {
                        // TODO: lazy-load CommentsResource module
                        this._commentsResource = new CommentsResource(this._core, this.id);
                    }
                    return this._commentsResource;
                },
                hasArtifacts: {
                    get(this: any) {
                        this._core._environment.mobx.reportObserved(this, 'change');
                        return this._hasArtifacts;
                    }
                }
            },
            // make all getter properties observable under the standard 'change' event
            defaultObservableEvent: SharedChangeEvent.type
        });
    }
}


interface IPatchedSpace extends Space {
    _searchWorkingFilesSource: Promise<SpaceSearchSource>;
    _searchArtifactsSource: Promise<SpaceSearchSource>;
}

export function patchSpaceJS() {
    const acplModel = getACPLModel()!;
    const assetContext = acplModel.applicationAssetContext;

    // Prior to version 1524, SAM.cpp space search APIs were not working correctly
    // https://jira.corp.adobe.com/browse/SAM-1886
    // https://jira.corp.adobe.com/browse/SAM-2189
    if (isSAMCppVer('gte', '2.0.0-main.1524') && isSAMCppVer('lt', '9999.9999.9999')) {
        // Until SAM.cpp can supply everything needed from SpaceContext and Spaces UI is not
        // dependant on SAM.js internals, patching the Sources for Space contents to use SAM.cpp
        // Sources so Spaces UI can have caching/badging.
        Object.defineProperties(Space.prototype, {
            searchWorkingFiles: {
                value(this: IPatchedSpace): Promise<SpaceSearchSource> {
                    if (this._searchWorkingFilesSource) {
                        return Promise.resolve(this._searchWorkingFilesSource);
                    }
                    this._searchWorkingFilesSource = new Promise((resolve, reject) => {
                        assetContext.spaceContext.lookupSpaceById(this.id)
                            .then((space: Space) => {
                                // `space` is the SAM.cpp Space object
                                if (!space) {
                                    reject(SAMError.create(SAMErrorCode.NOT_FOUND, `searchWorkingFiles could not find Space ${this.id}`));
                                }
                                resolve(space.searchWorkingFiles());
                            });
                    });
                    return this._searchWorkingFilesSource;
                }
            },

            searchArtifacts: {
                value(this: IPatchedSpace, embedPermissions = false): Promise<SpaceSearchSource> {
                    if (this._searchArtifactsSource) {
                        return Promise.resolve(this._searchArtifactsSource);
                    }
                    this._searchArtifactsSource = new Promise((resolve, reject) => {
                        assetContext.spaceContext.lookupSpaceById(this.id)
                            .then((space: Space) => {
                                // `space` is the SAM.cpp Space object
                                if (!space) {
                                    reject(SAMError.create(SAMErrorCode.NOT_FOUND, `searchArtifacts could not find Space ${this.id}`));
                                }
                                resolve(space.searchArtifacts(embedPermissions));
                            });
                    });
                    return this._searchArtifactsSource;
                }
            }
        });
    } else if (isSAMCppVer('lt', '2.0.0-main.1524')) {
        // For the prior versions of SAM where we don't have space search
        // support in SAM.cpp we are using the temp code
        // to use _AssetContextJS for _assetPool, USSInterface;
        // use hostAssetContext for workingFilesFolder or spaceAdobeAsset
        Object.defineProperties(Space.prototype, {
            searchWorkingFiles: {
                async value(this: Space): Promise<SpaceSearchSource> {
                    const assetContext: AssetContext = this._core._AssetContextJS!;
                    const { _assetPool, _ussInterface } = assetContext;

                    // We need to use the hostAssetContext as we need to get updates from SAM.cpp AdobeAsset so that the search
                    // filter works fine in case of updates to the space.
                    const workingFilesFolder = await this._core.hostAssetContext
                        .getAssetWithRepoPath(`${this.pathName}/working_files`, this.repositoryID);

                    const spaceSearchAssetLoader = new SpaceSearchAssetLoader(
                        _assetPool,
                        this._core,
                        workingFilesFolder,
                        _ussInterface,
                        'excludeArtifacts',
                        true // always include permissions for 1-off invitees
                    );

                    const implicitFilter = new SpaceSearchAssetFilter({
                        asset: workingFilesFolder,
                        artifactFilter: 'excludeArtifacts'
                    });
                    return new ItemSource(_assetPool, [ spaceSearchAssetLoader ], implicitFilter);
                }
            },

            searchArtifacts: {
                async value(this: Space, embedPermissions = false): Promise<SpaceSearchSource> {
                    // SAM.cpp AssetContext doesn't expose _assetPool/_ussInterface, so need
                    // to fall back to the JS impl of AssetContext when present. This is
                    // required as SAM.cpp space search APIs are not patched for
                    // SAM versions prior to 1524
                    const assetContext: AssetContext = this._core._AssetContextJS!;
                    const { _assetPool, _ussInterface } = assetContext;

                    // We need to use the hostAssetContext as we need to get updates from SAM.cpp AdobeAsset so that the search
                    // filter works fine in case of updates to the space.
                    const spaceAdobeAsset = await this._core.hostAssetContext.getAssetWithCloudID(this.id);

                    const spaceSearchAssetLoader = new SpaceSearchAssetLoader(
                        _assetPool,
                        this._core,
                        spaceAdobeAsset,
                        _ussInterface,
                        'onlyArtifacts',
                        embedPermissions
                    );

                    const implicitFilter = new SpaceSearchAssetFilter({
                        asset: spaceAdobeAsset,
                        artifactFilter: 'onlyArtifacts',
                        // Some artifacts may be in hidden folders
                        _includeHiddenRecursive: true
                    });
                    return new ItemSource(_assetPool, [ spaceSearchAssetLoader ], implicitFilter);
                }
            }
        });
    }
}
