import type { ISAMObject } from '../../indexPrivate';
import { getRetryAfterHeader } from '../../interface/LinkUtils';
import { RETRY_HTTP_RESPONSE_CODES } from '../../interface/ResponseCodes';

// Support retrying an asynchronous method on failure, with a backoff
export default (target: ISAMObject, propertyKey: string, descriptor: PropertyDescriptor) => {
    const timeout = Symbol(`@retry ${propertyKey}`);
    const method = descriptor.value;
    descriptor.value = async function (this: ISAMObject & { [timeout]?: ReturnType<typeof setTimeout> }, attempt: number = 0) {
        const timeoutId = this[timeout];
        if (timeoutId) {
            clearTimeout(timeoutId);
            this[timeout] = undefined;
        }

        try {
            await method.call(this);
        } catch (e) {
            let interval: number = 0;
            const response = (e as any)._additionalInfo?.response;
            if (RETRY_HTTP_RESPONSE_CODES.includes(response?.status)) {
                // InterfaceBase already auto-retried, so back off using the maximum retry interval.
                interval = this._core._environment.getValue('MAX_RETRY_INTERVAL') || 20000;
            } else {
                // Retry all other errors, but at a different interval
                const retryAfter = (e as any)._additionalInfo?.response ? getRetryAfterHeader((e as any)._additionalInfo.response.headers) * 1000 : 0;
                // If we're unable to resolve (unable to connect to services or unexpected response), we schedule a retry
                interval = Math.max(this._core._environment.getRetryInterval(attempt), retryAfter);
            }

            this._core._environment.log(`Retrying ${propertyKey} in ${interval}ms`);
            this[timeout] = setTimeout(() => descriptor.value.call(this, attempt + 1), interval);
        }
    };
};
