// CCLibs imports using relative paths:
import Store from './Store';

// SAM imports using aliases (since this module is symlinked):
import type { ISAMObject } from '../../core/ISAMObject';
import type { Action } from './Action';
import LibraryError from '../errors/LibraryError';
import type Element from './Element';
import type { ElementPoolId } from './Element';
import ItemSource from '../../core/ItemSource';

import type { ElementSource, ElementSourceConfig } from '../../library-contents/models/ElementSource';
import ElementListLoader from '../../library-contents/models/ElementListLoader';
import ImplicitElementFilter from '../../library-contents/models/ImplicitElementFilter';
import type { CombinedId } from './Element';
import type { ItemId } from '../../core/ItemBase';
import { SAMError, SAMErrorCode } from '../../core/SAMError';
import memoize from '../../core/decorators/memoize';

/**
 * Manager for LibraryContents (Elements, Groups, etc.) which exposes public APIs for fetching elements and groups.
 * This class can be thought of like an ElementContext, except that it has the additional responsibility of managing state.
 * Inherits from Store, which holds the data and updates the state for the library's contents.
 */
export default class LibraryContents extends Store implements ISAMObject {

    // async _load() - When there's a change notification, reloads all elements, groups, and applies update

    /**
     * Returns the ElementSource which will return a list of the user's elements.
     * @example
     * const libraryContents = await library.getLibraryContents();
     * const order = new ElementOrder('ascending', 'modified');
     * const elementList = libraryContents.elementsSource.getList(order, undefined, loadOptions);
     * await waitForListLoad(elementList);
     * Note: loadOptions.limit will be ignored on public libraries, which are not currently paginated.
     * Other Note: public libraries aren't yet supported
     * https://jira.corp.adobe.com/browse/SHARED-5316
     */
    @memoize
    get elementsSource(): ElementSource {
        if (this.library._isPublicLink_NoLazyLoad) {
            throw SAMError.create(SAMErrorCode.UNSUPPORTED, 'elements source is not currently supported for public libraries');
        }

        return new ItemSource<ElementSourceConfig, ElementPoolId>(
            this._elementPool,
            [
                new ElementListLoader(
                    this._core,
                    this._elementPool,
                    this._driver,
                    this.library
                ),
            ],
            new ImplicitElementFilter({ libraryId: this.library.id })
        );
    }

    // groupsSource	 - Returns GroupSource for fetching group lists

    // getElementById(id) - Loads a single element. (Note: For the time being, elements will only be kept up to date by ONS notifications when all the elements are loaded in a library.)

    public async getElementById(elementId: ItemId): Promise<Element> {
        const combinedId: CombinedId = `${this.library.id}#${elementId}`;
        let element = this._elementPool.getLocalItemById(combinedId);

        if (!element) {
            const elementData = await this._driver.getElement(this.library, elementId);
            elementData.libraryAssetId = elementData.libraryAssetId || this.library.id; // Our models require this data, though Melville may not always supply it.
            this._update({ elements: [ elementData ] }, true);
            element = this._elementPool.getLocalItemById(combinedId);
        }

        if (!element) {
            throw new LibraryError('INVALID_PARAMETER', 'Need to pass a valid element ID');
        }

        return Promise.resolve(element);
    }

    /* Store API Overrides */

    /**
     * @internal
     * @package -- for use in SAM.js only
     */
    // TODO: Move this into Store._actionDispatch
    _actionDispatch(action: Action) {
        if (!action.library) {
            action.library = this.library;
        }
        if (!action.libraryContents) {
            action.libraryContents = this;
        }

        super._actionDispatch(action);
    }
}
