import type {
    IComparatorMap
} from '../core/ItemOrder';
import {
    compareStrings,
    createItemOrderFactory
} from '../core/ItemOrder';
import type AddressBookContact from './AddressBookContact';

const OrderFieldToComparator: IComparatorMap<AddressBookContact, 'displayName'> = {
    displayName(a: AddressBookContact, b: AddressBookContact): number {
        // List is sorted in order returned by service
        // if no display name, sort to end of list using the π character
        return compareStrings(a.displayName || 'π', b.displayName || 'π');
    }
};

export default class AddressBookContactOrder extends createItemOrderFactory(OrderFieldToComparator) {
    static default = new AddressBookContactOrder('ascending', 'displayName');
}
