import type { IItemList, IItemSourceConfig } from '../core/ItemList';
import { LIST_CHANGED, STATE_CHANGED } from '../core/ItemList';
import type EventEmitter from 'events';
import { AssetListStatus } from '../core/ItemLoaderState';

/**
 * Returns a Promise that resolves when a List is loaded.
 * @param list to monitor for loading
 */
export function waitForListLoad(list: IItemList<IItemSourceConfig>): Promise<void> {
    const listEventSource = list as unknown as EventEmitter;

    return new Promise(resolve => {
        function onStatusChange(): void {
            if (list.status !== AssetListStatus.Loading) {
                listEventSource.off(STATE_CHANGED, onStatusChange);
                resolve();
            }
        }

        listEventSource.on(STATE_CHANGED, onStatusChange);
        // if List is already loaded, resolve now
        onStatusChange();
    });
}

export function waitForListChange(list: IItemList<any>): Promise<void> {
    const listEventSource = list as unknown as EventEmitter;

    return new Promise(resolve => {
        function onStatusChange(): void {
            listEventSource.off(LIST_CHANGED, onStatusChange);
            resolve();
        }

        listEventSource.on(LIST_CHANGED, onStatusChange);
    });
}
