import { RelType } from '../interface/LinkUtils';
import type AdobeAsset from './AdobeAsset';
import type { ISAMCorePrivate } from '../indexPrivate';
import AdobeAssetResource from './AdobeAssetResource';
import type { IPerUserMetadata } from '../interface/AssetModel';

export default class PerUserMetadataResource extends AdobeAssetResource<IPerUserMetadata> {

    constructor(
        readonly _core: ISAMCorePrivate,
        _parent?: AdobeAsset,
    ) {
        super(_core, _parent, {
            onChange: async (perUserMetadata, { timestamp } = {}) => {
                await this._parent?._handleResourceUpdates({ timestamp, perUserMetadata });
            },
            onError: async (error) => {
                await this._parent?._handleResourceUpdates({ error });
            }
        });
    }

    protected async _loadData() {
        await this._parent?._ensureLink(RelType.PERUSER_METADATA);
        const assetInterface = await this._parent?._getAssetInterface();
        await assetInterface?.getPerUserMetadata(this);
    }
}
