import type { AssetLoadHints } from '../../interface/AssetModel';
import { OrderFieldToGQLOrderBy } from '../models/AssetSubgraphModel';
import { appMetadataFragment, effectivePermissionsFragment, repoMetadataFragment } from './fragments';

function getListingQuery(loadHints?: AssetLoadHints) {
    if (!loadHints?.listingHints) {
        return '';
    }
    let listingFragment = '... on Directory {';
    listingFragment += `
        repo_assetId
    `;
    for (let i = 0; i < loadHints.listingHints.length; i++) {
        const order = loadHints.listingHints[i].order;
        listingFragment += `
        list${i + 1}: childrenConnection(
            first: ${loadHints.listingHints[i].loadOptions?.limit ?? 10},
            orderBy: [
                {
                    field: ${OrderFieldToGQLOrderBy[order.field]},
                    direction: ${order.direction.toUpperCase()}
                }
            ],
            filter: {
                dc_format: ${loadHints.listingHints[i].filter?.mediaTypes ?? null}
            }
        ) {
            edges {
                node {
                    ...repoMetadata
                    ...applicationMetadata
                    # TODO: undefined effectivePermissions is equivalent to false for now.
                    # We will change it to deferred in the future.
                    ${loadHints.listingHints[i].effectivePermissions ? '...effectivePermissions' : ''}
                }
            }
            pageInfo {
                endCursor
                hasNextPage
            }
        }
        `;
    }
    listingFragment += '}';
    return listingFragment;
}

function assetByPathDataQuery(loadHints?: AssetLoadHints) {
    let query = '';
    // undefined and false are different for appMetadata.
    // undefined means load all the appMetadata fields that SAM.js requires eagerly for now (i.e. shell:visibility).
    // false means load no appMetadata fields in the query
    if (loadHints?.appMetadata) {
        query += `
            ...applicationMetadata
        `;
    }
    if (loadHints?.effectivePermissions) {
        query += `
            ...effectivePermissions
        `;
    }
    return query;
}

function needEffectivePermissionsFragment(loadHints?: AssetLoadHints) {
    return loadHints?.effectivePermissions || loadHints?.listingHints?.some((hint) => hint.effectivePermissions);
}

function needAppMetadataFragment(loadHints?: AssetLoadHints) {
    return loadHints?.appMetadata || loadHints?.listingHints?.length;
}

export function resolveAssetByPathQuery(loadHints?: AssetLoadHints) {
    const query = repoMetadataFragment
                    + (needAppMetadataFragment(loadHints) ? appMetadataFragment : '')
                    + (needEffectivePermissionsFragment(loadHints) ? effectivePermissionsFragment : '');
    return query + `
        query getAssetByPath($assetPath: String!, $repositoryId: ID!) {
            resolveAssetByPath(assetPath: $assetPath, repositoryId: $repositoryId) {
                ...repoMetadata
                ${assetByPathDataQuery(loadHints)}
                ${getListingQuery(loadHints)}
            }
        }
    `;
}

export function assetByRelativePathQuery(loadHints?: AssetLoadHints) {
    const query = repoMetadataFragment
                    + (needAppMetadataFragment(loadHints) ? appMetadataFragment : '')
                    + (needEffectivePermissionsFragment(loadHints) ? effectivePermissionsFragment : '');
    return query + `
        query getAssetByPath($assetPath: String!) {
            resolveUserHome {
                ...repoMetadata
                ... on Directory {
                    assetByRelativePath(relativePath: $assetPath) {
                        ...repoMetadata
                        ${assetByPathDataQuery(loadHints)}
                        ${getListingQuery(loadHints)}
                    }
                }
            }
        }
    `;
}

export function getChildrenQuery() {
    const query = repoMetadataFragment + appMetadataFragment + effectivePermissionsFragment;
    return query + `
        query getChildren($assetId: ID!, $storageRegion: String, $first: Int!, $after: String, $orderBy: [OrderByInput!], $filter: AssetFilter) {
            resolveAssetById(assetId: $assetId, storageRegion: $storageRegion) {
                ... on Directory {
                    repo_assetId
                    repo_ancestors
                    childrenConnection(first: $first, after: $after, orderBy: $orderBy, filter: $filter) {
                        edges {
                            node {
                                ...repoMetadata
                                ...applicationMetadata
                                ...effectivePermissions
                            }
                        }
                        pageInfo {
                            endCursor
                            hasNextPage
                        }
                    }
                }
            }
        }
    `;
}
