/**
 * Model representing a DCXComponent.
 * See https://devhome.corp.adobe.com/docs/default/component/dcx-documentation/docs/dcx-basics/manifest-syntax/#components
 * This is used by boards to represent the board background image.
 * @package -- for SAM.js internal use only
 */
export interface DCXComponent {
    /** The component ID */
    id: string;
    /** The etag of the component */
    etag?: string;
    /** The version of the component. Used to determine if the component has changed since the last fetch. */
    version?: string;
    /** The MD5 hash of the component. */
    md5?: string;
    /** The media type of the component, e.g. image/png, etc... */
    type: string;
    /** The length of the component in bytes */
    length?: number;
    /** The state of the component. */
    state: string;
    /** The name of the component. Descriptive name of the component. Not required to be unique.*/
    name?: string;
    /** The relationship of the component to the composite structure. */
    rel?: string;
    /** The relative path of the component from the root of the composite structure. */
    path: string;
}

export interface RemoteBoard extends Pick<RepositoryMetadata,
    'repo:assetId' | 'repo:createDate' | 'repo:state' | 'repo:name' | 'repo:createdBy' | 'repo:modifiedBy' | 'repo:modifyDate' | 'dc:format' | 'repo:etag'
> {
    /** The role of the member with regards to the board */
    'memberRole': BoardMemberRole;
    /** The type of the board */
    'boardType'?: BoardType;
    /** Board context */
    'board:context': BoardContext;
    /** The visibility level of the board */
    'board:visibilityLevel'?: BoardVisibilityLevel;
    /** The target visibility level of the board */
    'board:targetVisibilityLevel'?: BoardVisibilityLevel;
    /** Whether the current user can elevate the permission of the board */
    'canUserElevatePermission'?: boolean;
    /** Board description */
    'dc:description': string;
    /** Remote post data in the board */
    posts?: (RemoteTextPost | RemoteAssetLinkPost)[];
    /** DCX components array. Where the board background image data is stored. */
    components?: DCXComponent[];
    /** Board links */
    _links?: BoardLinks;
    /** The schema version of the board */
    'board#version': string;
    /** The source board */
    'board:sourceBoard'?: RemoteSourceBoardInfo;
    /** The published board */
    'board:publishedBoard'?: RemotePublishedBoardInfo;
    /** The theme of the board */
    'board:theme'?: BoardTheme;
    /** Whether new comments are allowed on the posts of the board*/
    'board:newCommentsAllowed'?: boolean;
}

