/**
 * Custom patch operation for granting board access
 * This is not a standard JSON Patch operation - it's specific to the Boole service
 */
export interface BoardUserPatchOperation {
    /**
     * The operation type. Must be 'grantAccessToPosts' to grant access to posts on a board.
     * This is a custom operation used by the Boole service for board access management.
     */
    op: 'grantAccessToPosts';

    /**
     * The path indicating the type of principal being granted access.
     * Valid values:
     * - '/user' - Grant access to a specific user (requires userId or email in value)
     * - '/group' - Grant access to a group (requires groupId in value)
     * - '/orgEverybody' - Grant access to all users in the organization
     * - '/all' - Grant access to all users (public access)
     */
    path: string;

    /**
     * The principal information for the entity being granted access.
     * The structure varies based on the path:
     * - For '/user': { id?: string, email?: string } - User ID and/or email
     * - For '/group': { id: string } - Group ID
     * - For '/orgEverybody': { id: PredefinedPrincipalId.ORG_EVERYBODY }
     * - For '/all': { id: PredefinedPrincipalId.ALL }
     */
    value: Record<string, any>;
}

