/** The supported theme tokens for a board */
export const BOARD_THEME_TOKENS = {
    BLACK: 'black',
    CHARTREUSE: 'chartreuse',
    CYAN: 'cyan',
    FUSCHIA: 'fuschia',
    GRAY: 'gray',
    INDIGO: 'indigo',
    LIGHT_CHARTREUSE: 'light-chartreuse',
    LIGHT_CYAN_GRADIENT: 'light-cyan-gradient',
    LIGHT_FUSCHIA_GRADIENT: 'light-fuschia-gradient',
    LIGHT_INDIGO_GRADIENT: 'light-indigo-gradient',
    LIGHT_ORANGE_GRADIENT: 'light-orange-gradient',
    LIGHT_RED_GRADIENT: 'light-red-gradient',
    LIGHT_SEAFOAM_GRADIENT: 'light-seafoam-gradient',
    ORANGE: 'orange',
    RED: 'red',
    SEAFOAM: 'seafoam',
    WHITE: 'white',
} as const;

/** Union of valid board theme tokens */
export type BoardThemeToken = typeof BOARD_THEME_TOKENS[ keyof typeof BOARD_THEME_TOKENS ];

/** The supported theme modes for a board */
export const BOARD_THEME_MODES = {
    COLOR: 'color',
    IMAGE: 'image',
} as const;

export type BoardThemeMode = typeof BOARD_THEME_MODES[ keyof typeof BOARD_THEME_MODES ];

/** Component paths for board components
 *
 * @package -- for SAM.js internal use only.
*/
export const BOARD_COMPONENT_PATHS = {
    FULL_SIZE_BACKGROUND_IMAGE: 'background/fullsize',
} as const;

/** Board theme with a color */
type ColorTheme = {
    /** The theme token to use. Not present if the theme is a custom color. */
    token?: BoardThemeToken;
    /** The primary color as hex. */
    primaryColor: string;
    /** The secondary color as hex. Only present if the theme is a gradient. */
    secondaryColor?: string;
    /** Color mode where the user can set custom hex colors or a predefined theme token */
    mode: typeof BOARD_THEME_MODES.COLOR;
};

/**
 * Board theme with a background image.
 *
 * The background image is stored as a component within the board's composite structure
 * and must be fetched separately using Board.getBackgroundImage().
 * backgroundImageReference is used to determine when the background image has changed.
 * @see Board.getBackgroundImage() for fetching the actual image blob
 */
export type ImageTheme =
    | {
        backgroundImageReference: BackgroundImageReference;
        /** Image mode where the user can set a background image */
        mode: typeof BOARD_THEME_MODES.IMAGE;
    }
    | {
        /** Image mode where the user can set a background image */
        mode: typeof BOARD_THEME_MODES.IMAGE;
        /** @deprecated Use backgroundImageReference to determine when the background image has changed. */
        backgroundImageReference?: never;
    };

/** The background image data to facilitate fetching the image.
 * This data is used to determine when the background image has changed.
 * Background images are stored as components and fetched via Board.getBackgroundImage().
*/
export type BackgroundImageReference = {
    /** The component ID of the background image */
    componentId: string;
    /** The revision ID of the background image */
    revisionId: string;
};

/** Options for setting the background image */
type SetImageThemeOptions = {
    /** The background image to use (uploaded from device).
     * TODO: ACPCEDU-5531 - Update to only accept Blob once all occurrences are updated.
     * @deprecated Use only Blob, not string.
    */
    backgroundImage: Blob | string;
    /** Image mode where the user can set a background image */
    mode: typeof BOARD_THEME_MODES.IMAGE;
} |
{
    /** The background image to use (uploaded from device). */
    backgroundImage: Blob;
    /** Image mode where the user can set a background image */
    mode: typeof BOARD_THEME_MODES.IMAGE;
};

/** The theme of the board */
export type BoardTheme = ColorTheme | ImageTheme;

/** Options for setting the board theme */
export type SetBoardThemeOptions = ColorTheme | SetImageThemeOptions;
