import type { ISAMCorePrivate } from '../indexPrivate';
import type { ISAMObject } from '../core/ISAMObject';
import type { IRepository } from '../interface/RepositoryModel';
import { RelType } from '../interface/LinkUtils';
import type AdobeAsset from '../assets/AdobeAsset';
import WorkfrontInterface from '../interface/WorkfrontInterface';
import ProjectsInterface from '../interface/ProjectsInterface';
import type { IOrganizationsResponse } from '../interface/OrganizationsModel';
import Resource from '../assets/Resource';
import { AccessControlModifier, AccessControlPrivileges, type AccessControlInheritance, type Principal } from '../access-control/AccessControlModel';
import { isDeepEqual } from '../core/ObjectUtils';
import SAMError, { SAMErrorCode } from '@sam-js-src/core/SAMError';
import type { AssetRGNRelType } from '../interface/AssetInterface';

export default class WorkfrontContext implements ISAMObject {
    private _workfrontInterface: WorkfrontInterface;
    constructor(
        readonly _core: ISAMCorePrivate
    ) {
        this._workfrontInterface = new WorkfrontInterface(this._core);
    }

    /**
     * Get an AdobeAsset from a given asset path and repository ID. This method is optimized
     * to use to only get and build an asset based on repo-metadata without having to call
     * all the other services to get additional data up-front (PUPA). To get the full asset you can
     * still call either AssetContext.getAssetWithRepoPath or AssetContext.getAssetWithCloudID().
     *
     * @param assetPath The path to get the asset for.
     * @param repositoryId The repository ID to get the asset for.
     * @returns The AdobeAsset for the given asset path and repository ID.
     */
    public async getAssetWithRepoPath(assetPath: string, repositoryId: string): Promise<AdobeAsset> {
        const assetContext = await this._core.getAssetContext();
        const repoMetadataResource = await assetContext._getRepoDataByPath(assetPath, repositoryId);
        const session = assetContext._assetPool.createMutationSession(repoMetadataResource.timestamp);
        const updaters = await this._core._adobeAssetFactory.getRepoMetadataUpdaters([ repoMetadataResource.data ]);
        const newAsset = this._core._adobeAssetFactory.assetFromRepoMetadata({
            session,
            repoMetadata: repoMetadataResource.data,
            updaters
        });
        session.commit();
        return newAsset;
    }

    /**
     * Get the repository information from the RAPI index-workfront endpoint.
     * This is required to decouple workfront from SMU migration scenarios.
     *
     * @service Requires service principal token for authentication.
     * @param orgId The organization ID to get the repository for.
     * @returns The repository for the Workfront context.
     */
    async getRepository(orgId: string): Promise<IRepository> {
        const assetContext = await this._core.getAssetContext();
        const repositoryInterface = assetContext._rapi;
        const workfrontRepositoryIndex = await repositoryInterface.getWorkfrontIndex(orgId);
        const repositoryData = workfrontRepositoryIndex.newWorkfrontParentDir._embedded[RelType.REPO_METADATA];
        return {
            id: repositoryData['repo:repositoryId'],
            path: repositoryData['repo:path'],
            name: repositoryData['repo:name'],
            links: repositoryData._links
        };
    }

    /**
     * Creates an AdobeAsset instance from a cloud ID. Note that this method always returns an AdobeAsset,
     * even for specialized asset types like Projects or Libraries. Do not use this method if you need
     * specialized asset behavior - for example, if you need Project-specific functionality, use the
     * ProjectContext instead. This is intended to be a lightweight way to get an asset when only minimal
     * metadata is needed.
     *
     * @param assetId The cloud ID of the asset
     * @returns An AdobeAsset instance
     */
    async getAssetWithCloudID(assetId: string): Promise<AdobeAsset> {
        const assetContext = await this._core.getAssetContext();
        const repoMetadataResource = await assetContext._getAssetRepoDataWithCloudID(assetId);
        const repoMetadata = repoMetadataResource.data;

        const session = this._core._getAssetPool().createUpdateSession('getAssetWithCloudID');
        const updaters = await this._core._adobeAssetFactory.getRepoMetadataUpdaters([ repoMetadata ]);
        const asset = this._core._adobeAssetFactory.assetFromRepoMetadata({ session, repoMetadata, updaters });
        session.commit();
        return asset;
    }

    /**
     * Get the Workfront link for a given asset ID and organization ID.
     *
     * @param assetId The cloud ID of the asset
     * @param orgId Optional. The organization ID to get the Workfront link.
     * @returns The Workfront link for the given asset ID and organization ID
     */
    async getWorkfrontLink(assetId: string, orgId?: string): Promise<string> {
        let org;
        if (orgId) {
            org = orgId;
        } else {
            const organizationsResource = new Resource<IOrganizationsResponse>(this._core);
            const projectInterface = new ProjectsInterface(this._core);
            await projectInterface.getOrganizations(organizationsResource);
            org = organizationsResource.data?.default;
        }

        const workfrontLink = await this._workfrontInterface.getWorkfrontLink(assetId, org);
        return workfrontLink.workfrontURL;
    }

    /**
     * @deprecated This method is no longer supported.
     * Use {@link WorkfrontContext.setDeny} instead.
     */
    async setDenyWithDeepOverride(assetId: string): Promise<void> {
        return Promise.reject(`Method is unimplemented, assetId: ${assetId}`);
    }

    private _getPrivileges(): AccessControlPrivileges[] {
        return [
            AccessControlPrivileges.ACK,
            AccessControlPrivileges.READ,
            AccessControlPrivileges.WRITE,
            AccessControlPrivileges.DELETE
        ];
    }

    /**
     * Add the ACE using the requested inheritance and principal provided
     * and the pre-configured deny rules.
     *
     * @param assetId The cloud ID of the asset
     * @return void Promise
     */
    async setDeny(assetId: string, inheritance: AccessControlInheritance, principal: Principal): Promise<void> {
        const accessControlContext = await this._core.getAccessControlContext();
        const acl = await accessControlContext.getACL(assetId);
        await acl.addACES([
            {
                inheritance,
                principal,
                privileges: this._getPrivileges(),
                modifier: AccessControlModifier.DENY,
                relations: []
            }
        ]);
    }

    /**
     * Remove the ACE matching the requested inheritance and principal provided
     * and the pre-configured deny rules.
     *
     * @param assetId The cloud ID of the asset
     * @param inheritance The inheritance value used to set the ACE originally.
     * @param principal The principal used to set the ACE originally.
     * @return void Promise
     */
    async removeDeny(assetId: string, inheritance: AccessControlInheritance, principal: Principal): Promise<void> {
        const accessControlContext = await this._core.getAccessControlContext();
        const acl = await accessControlContext.getACL(assetId);
        const findAce = acl.aces.find(
            (ace) => {
                const matchesAce =  ace.inheritance === inheritance
                    && isDeepEqual(ace.principal, principal)
                    && ace.isDeny
                    && ace.privileges.every((privilege) => this._getPrivileges().includes(privilege))
                    && ace.relations.length === 0;
                return matchesAce;
            }
        );

        if (findAce) {
            await acl.removeACES([ findAce ]);
            return;
        }

        // The requested inhertiance and princpal did not match any known ACEs.
        throw SAMError.create(SAMErrorCode.NOT_FOUND, 'ACE matching the requested inheritance and principal was not found');
    }

    /**
     * @deprecated use {@link WorkfrontContext.removeDeny} instead.
     *
     */
    async removeDenyWithDeepOverride(assetId: string): Promise<void> {
        return Promise.reject(`Method is unimplemented, assetId: ${assetId}`);
    }

    private async _getResourceGenerationNumber(assetId: string, relType: AssetRGNRelType): Promise<number> {
        const assetContext = await this._core.getAssetContext();
        const assetPool = assetContext._assetPool;
        let asset = assetPool.getLocalItemById(assetId);
        if (!asset) {
            asset = await assetContext.getAssetWithCloudID(assetId, false);
        }
        await asset._ensureLink(relType);
        const assetInterface = await asset._getAssetInterface();

        const rgn = await assetInterface.getResourceGenerationNumber(relType);
        if (!rgn) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Resource Generation Number not found, only available in Node environments');
        }

        const convertedRGN = Number(rgn);
        if (isNaN(convertedRGN)) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Resource Generation Number is not a number');
        }

        return convertedRGN;
    }

    /**
     * Resource Generation Numbers
     *
     *
     * Each Associated Resource has a Resource Generation Number,
     * which is incremented whenever the Resource itself changes. While strictly increasing,
     * it is not guaranteed to be gapless. Clients can use the Resource Generation Number to
     * determine if the Resource, retrieved either through the API or an Asset Event, is more
     * recent than a local copy of that resource. If retrieved through the API,
     * the Resource-Generation header is used. If retrieved through an Asset Event,
     * the event:resourceGeneration property is used.
     */

    /**
     * Get the Resource Generation Number for the primary resource.
     * The Resources-Generation header is not set in the CORS access-control-expose-header provided
     * by the services behind RAPI. This means Browser based clients will not be able to get the
     * Resource Generation Number for the primary resource.
     *
     * We also don't want to cache the Resource Generation Number for the primary resource
     * as it may change rapidly over time.
     */
    async getPrimaryRGN(assetId: string): Promise<number> {
        return this._getResourceGenerationNumber(assetId, RelType.PRIMARY);
    }

    /**
     * Get the Resource Generation Number for the repository metadata.
     * The Resources-Generation header is not set in the CORS access-control-expose-header provided
     * by the services behind RAPI. This means Browser based clients will not be able to get the
     * Resource Generation Number for the repository metadata.
     *
     * We also don't want to cache the Resource Generation Number for the repository metadata
     * as it may change rapidly over time.
     *
     */
    async getRepoMetadataRGN(assetId: string): Promise<number> {
        return this._getResourceGenerationNumber(assetId, RelType.REPO_METADATA);
    }

    /**
     * Get the Resource Generation Number for the application metadata.
     * The Resources-Generation header is not set in the CORS access-control-expose-header provided
     * by the services behind RAPI. This means Browser based clients will not be able to get the
     * Resource Generation Number for the application metadata.
     *
     * We also don't want to cache the Resource Generation Number for the repository metadata
     * as it may change rapidly over time.
     *
     */
    async getAppMetadataRGN(assetId: string): Promise<number> {
        return this._getResourceGenerationNumber(assetId, RelType.APP_METADATA);
    }
}
