/**
 * Implements newer methods added to Set in 2024. Temporary until browser usage % that supports
 * these methods is high enough to remove. Currently at 87.6%.
 * https://caniuse.com/?search=isDisjointFrom
 */
export class ModernSet<T> extends Set<T> {
    isDisjointFrom(other: ReadonlySetLike<unknown>): boolean {
        return ![ ...this ].some(value => other.has(value));
    }
    isSubsetOf(other: ReadonlySetLike<unknown>): boolean {
        return [ ...this ].every(value => other.has(value));
    }
    isSupersetOf(other: ReadonlySetLike<unknown>): boolean {
        return ModernSet.prototype.isSubsetOf.call(other, this);
    }
    intersection<U>(other: ReadonlySetLike<U>): ModernSet<T & U> {
        return new ModernSet<T & U>([ ...this ].filter(value => other.has(value as unknown as U)) as (T & U)[]);
    }
    union<U>(other: ReadonlySetLike<U>): Set<T | U> {
        return new ModernSet<T | U>([ ...this, ...Array.from(other.keys() as any) ] as (T | U)[]);
    }
    difference<U>(other: ReadonlySetLike<U>): Set<T> {
        return new ModernSet<T>([ ...this ].filter(value => !other.has(value as unknown as U)));
    }
    symmetricDifference<U>(other: ReadonlySetLike<U>): Set<T | U> {
        return new ModernSet<T | U>([ ...this, ...Array.from(other.keys() as any) ].filter(
            value => this.has(value as unknown as T) !== other.has(value as unknown as U)) as (T | U)[]);
    }
}
