import type { OpPatch } from 'json-patch';
import { SAM } from '@ccx-public/component-types';
import type { USSMetadata, ISearchQuery } from './USSModel';
import type { IEffectivePermissions } from './RepositoryModel';

export const CUSTOM_MODEL_MEDIA_TYPE = 'application/vnd.adobe.ffmodel+dcx';

export const CUSTOM_MODEL_RESTRICTED_METADATA_KEYS = [ 'cme:training' ] as const;
export type CustomModelRestrictedMetadataKey = typeof CUSTOM_MODEL_RESTRICTED_METADATA_KEYS[number];
type CustomModelAppMetadataPatchPath = `/${CustomModelRestrictedMetadataKey}`;

export type CustomModelPublishedState = SAM.CustomModelPublishedState;

// Due to CustomModelPublishedState type alias, we need to maintain TS behavior of exporting enum as a runtime value
// eslint-disable-next-line @typescript-eslint/no-redeclare
export const CustomModelPublishedState = SAM.CustomModelPublishedState;

export type CreateTrainingSetOptions = {
    name: string;
    projectId: string;
    description?: string;
    // @deprecated - use the `firefly#cme` key
    'firefly#ffmodel'?: {
        schemaVersion: string;
        [key: string]: any;
    },
    'firefly#cme': CustomModelTrainingConfiguration
};

export type CustomModelTrainingConfiguration = {
    contentType?: string;
    samplePrompt?: string;
    trainingMode: CustomModelTrainingMode;
    // @deprecated - use schemaVersion
    version?: string;
    schemaVersion: string;
    baseModelSuperclass?: string;
    conceptId?: string;
    classDescriptors?: string[];
    previousClassDescriptors?: string[];
    invalidClassDescriptors?: Record<string, string>;
}

export type CustomModelTrainingMode = 'style' | 'subject' | 'product';

export type CustomModelTrainingState = 'inProgress' | 'success' | 'failed' | 'cancelled';

export type CustomModelMetadata = Partial<USSMetadata['app_metadata']> & {
    'cme:inferenceReady'?: boolean;
    'cme:signature'?: string;
    'cme:category'?: string;
    'cme:publishedState'?: CustomModelPublishedState;
    'cme:samplePrompt': string;
    'cme:baseModel'?: {
        name: string;
        version: string;
    }
    'cme:trainingSet': {
        'repo:assetId': string;
        'repo:version': string;
    }
    'cme:training': {
        state: CustomModelTrainingState;
        progress?: number;
        jobId: string;
        errorMessage?: string;
        errorCode?: string;
        links?: Record<string, any>,
    }
}

export interface ISearchQueryCustomModel extends ISearchQuery {
    'app_metadata$$cme:publishedState'?: CustomModelPublishedState
}

type CustomModelManifestData = {
    classDescriptors?: string[];
    // String representing the assessment of the training images for different archetypes (photo, vector, etc)
    contentType: string;
    // Specifies how the model is trained - style | subject | product
    trainingMode: CustomModelTrainingMode;
    // Schema version used by Firefly team to manage new fields with backward compatibility
    schemaVersion: string;
    // A word that describes what are the images about. e.g. dog, cat, etc. This is deduced from all the images during the training and added to the prompt during inference
    baseModelSuperclass: string;
    // Identifies the new concept this training will add
    conceptId?: string;
    // Firefly ID for the weights
    deltaWeightsID?: string;
    // Compression mechanism
    compression?: string;
};


export type CustomModelInfoUSS = USSMetadata & {
    type: typeof CUSTOM_MODEL_MEDIA_TYPE;
    original_path: string;
    'storage:assignee': string;
    app_metadata: CustomModelMetadata;
    'firefly#ffmodel': CustomModelManifestData;
}

// describes the shape of CustomModelInfo as returned from Melville
// https://git.corp.adobe.com/pages/Stormcloud/apidocs/?urls.primaryName=melville#/Custom%20Models/getCustomModel
export type CustomModelInfoMelville = {
    type: typeof CUSTOM_MODEL_MEDIA_TYPE;
    // boolean indicating if the custom model data was served from Melville's cache
    _fc: boolean;
    _links: any;
    asset_acl: IEffectivePermissions;
    'repo:assetId': string;
    'repo:createDate': number;
    'repo:modifyDate': number;
    'repo:name': string;
    'repo:createdBy': string;
    'repo:version': string;
    'repo:size': number;
    'repo:path': string;
    'repo:etag': string;
    'storage:region': string;
    'storage:assignee': string;
    application_metadata: CustomModelMetadata;
    'firefly#ffmodel': CustomModelManifestData
}

type CustomModelUpdateInfoApplicationMetadata = Pick<
CustomModelInfoMelville['application_metadata'],
'cme:baseModel' | 'cme:signature' | 'cme:samplePrompt' | 'cme:category'
>;
type CustomModelUpdateInfoComponent = {
    id: string;
    name?: string;
    path: string;
    type: string;
    rel?: string;
    etag: string;
    version: string;
    md5: string;
    length: 0;
    width?: 0;
    height?: 0;
}

/**
 * describes the shape of request body for updating a custom model in Melville
 * https://git.corp.adobe.com/pages/Stormcloud/apidocs/?urls.primaryName=melville#/Custom%20Models/updateCustomModel
 */
export type CustomModelUpdateInfoMelville = Partial<
CustomModelUpdateInfoApplicationMetadata &
Pick<CustomModelInfoMelville, 'firefly#ffmodel'> & {
    components: CustomModelUpdateInfoComponent[];
}>;

/**
 * For most cases, Custom Models should be updated with the CustomModel.update method.
 * There are exceptions where the application metadata can be updated directly, though.
 */
export type CustomModelAppMetadataPatch = OpPatch & {
    path: CustomModelAppMetadataPatchPath;
}

export type CustomModelsResponseMelville = {
    total_count: number;
    custom_models: CustomModelInfoMelville[];
    _links: any
}

export type CustomModelCreateOptions = {
    'firefly#ffmodel': {
        trainingMode: string,
        baseModelSuperclass?: string,
        deltaWeightsID?: string,
        classDescriptors?: string[],
        conceptId?: string,
        contentType: string,
        schemaVersion: string
    },
    'cme:trainingSet': {
        'repo:assetId': string,
        'repo:version': string
    },
    'cme:baseModel'?: {
        name: string,
        version: string
    },
    'cme:signature'?: string,
    'cme:samplePrompt': string,
    'cme:category'?: string
}

export enum CustomModelOrderBy {
    MODIFY_DATE = 'modified_date',
    CREATE_DATE = 'created_date',
    NAME = 'name'
}

type MelvilleOrderBy = CustomModelOrderBy.NAME | CustomModelOrderBy.MODIFY_DATE | CustomModelOrderBy.CREATE_DATE | '-name' | '-created_date' | '-modified_date' | string;

// When adding values here which take an array of strings, write tests against LibraryInterface.sortParameters to ensure
// we are are getting the same order of strings each time. This prevents unnecessary cache misses Melville side
export type MelvilleCustomModelListParameters = {
    start?: number;
    limit?: number;
    orderBy?: MelvilleOrderBy;
}
