import type { AdobeAssetUpdaterMetadata } from '../assets/AdobeAsset';
import type { AssetLinks, RepositoryMetadata } from '../interface/RepositoryModel';
import type ISAMCorePrivate from '../core/ISAMCorePrivate';
import type BoardContext from './BoardContext';
import type { PostSource } from './PostSource';
import type {
    AddBoardPostOptions,
    AddPostsResult,
    BoardTheme,
    BoardLinks,
    BoardUpdateOptions,
    PublishedBoardInfo,
    PublishOptions,
    RemoteAssetLinkPost,
    RemoteBoard,
    RemotePublishedBoardInfo,
    RemoteSourceBoardInfo,
    RemoteTextPost,
    SourceBoardInfo,
    UpdatePostOptions,
    ValidateBoardNameForUpdateOptions,
    DCXComponent,
    ImageTheme,
    BoardGrantAccessToAmbiguousUserOptions,
    BoardGrantAccessToUnambiguousUserOptions,
    BoardGrantAccessToGroupOptions,
    BoardGrantAccessToUsersOptions,
    BoardGrantAccessToGroupsOptions,
} from '../interface/BoardModel';
import type { ISAMObject } from '../core/ISAMObject';
import type Post from './Post';
import type AssetLinkPost from './AssetLinkPost';
import type TextPost from './TextPost';
import type { IUpdateSession } from '../core/UpdateSession';
import type { ONSChangedAssetInfo } from '../sync-services/ONSEvent';

import AdobeAsset from '../assets/AdobeAsset';
import { AssetClassChoices, AssetStateChoices } from '../interface/RepositoryModel';
import ItemUpdater from '../core/ItemUpdater';
import { BoardMemberRole, BoardTypeChoices, PostRemoteType, BoardVisibilityLevelChoices, BoardVisibilityLevel, BoardVisibilityLevelOrder, BOARD_COMPONENT_PATHS, BOARD_THEME_MODES } from '../interface/BoardModel';
import PropertyUpdater from '../core/PropertyUpdater';
import ItemSource from '../core/ItemSource';
import { memoize, observable, retry } from '../core/decorators';
import PostListLoader from './PostListLoader';
import type { Permission } from '../interface/AssetModel';
import type { SAM } from '@ccx-public/component-types';
import { AssetLinkPostUpdater } from './AssetLinkPost';
import { TextPostUpdater } from './TextPost';
import ItemPool from '../core/ItemPool';
import SAMError, { SAMErrorCode } from '../core/SAMError';
import type { BoardType } from '../../src/interface/BoardModel';

export default class Board extends AdobeAsset implements SAM.Board {
    private _description: string | undefined;
    private _baseAssetId: string | undefined;
    private _boardContext!: BoardContext;
    private _boardType: BoardType | undefined;
    private _memberRole: BoardMemberRole = BoardMemberRole.UNKNOWN;
    private _publishedBoardInfo: PublishedBoardInfo | undefined;
    private _sourceBoardInfo: SourceBoardInfo | undefined;
    // This helps indicate whether the board has complete board metadata fetched from the board service
    // Note: the odd "...Prop" naming is to avoid a conflict with the getter/setter
    private _hasCompleteBoardMetadataProp: boolean = false;
    private _theme: BoardTheme | undefined;
    // Note: the odd "...Prop" naming is to avoid a conflict with the getter/setter
    private _componentsProp: DCXComponent[] = [];
    private _areNewCommentsAllowed: boolean | undefined;
    private _visibilityLevel: BoardVisibilityLevel = BoardVisibilityLevel.NONE;
    private _targetVisibilityLevel: BoardVisibilityLevel = BoardVisibilityLevel.NONE;
    private _canUserElevatePermission: boolean = false;

    /** @package -- for SAM.js internal use only */
    public _postPool = new ItemPool<Post>(this._core, 'post');

    /**
     * This field is intended to preserve the references to posts provided by the remote item so that
     * they do not get garbage collected before {@link posts}.getList is called.
     * @package -- for SAM.js internal use only
     */
    public _posts: Post[] = [];

    constructor(
        readonly _core: ISAMCorePrivate,
        id: string,
        metadata?: {
            links?: AssetLinks;
        }
    ) {
        super(_core, id, metadata);

        this._core.getBoardContext().then((boardContext) => {
            this._boardContext = boardContext;
        });

        // Overridden property.
        // True to start with. If we have the metadata, we will update this.
        // Keep in mind that the board service does not include all Adobe
        // Asset metadata in its responses, hence why this is needed.
        this._needsRepoMetadata = true;
    }

    /**
     * Ensures that the board context has been fetched before using it
     * @throws {SAMError} if the board context is not initialized
     * @package -- for SAM.js internal use only
     */
    private _ensureBoardContext(): BoardContext {
        if (!this._boardContext) {
            throw SAMError.create(SAMErrorCode.INTERNAL_ERROR, 'Board context not initialized');
        }
        return this._boardContext;
    }

    /**
     * The type of the board
     *
     * @example <caption>Get the type of the board</caption>
     * const boardType = board.boardType;
     */
    @observable
    get boardType(): BoardType | undefined {
        return this._boardType;
    }

    /**
     * Whether the current user can see the full content of the board. If this is false, then the user may only see partial content of the board or no content at all.
     *
     * @example <caption>Check if the current user can see the full content of the board</caption>
     * const canSeeFullBoardContent = board.canSeeFullBoardContent;
     */
    @observable
    get canSeeFullBoardContent(): boolean {
        // if the canUserElevatePermission is true, then the user can see the full content of the board
        // otherwise, this returns true if the visibility level is greater than or equal to the target visibility level
        // the idea is that the user can see the full content of the board if they can elevate the permission of the board aka board owner
        return this._canUserElevatePermission || (BoardVisibilityLevelOrder[this._visibilityLevel] >= BoardVisibilityLevelOrder[this._targetVisibilityLevel]);
    }

    /**
     * Whether the current user can elevate the permission of the board.
     *
     * @example <caption>Check if the current user can elevate the permission of the board</caption>
     * const canElevatePermission = board.canElevatePermission;
     */
    @observable
    get canElevatePermission(): boolean {
        // Only the owner or editor can elevate the permission of the board
        if (this._canUserElevatePermission) {
            // The user with canUserElevatePermission=true can elevate the permission of the board if the visibility level is lower than the target visibility level
            return BoardVisibilityLevelOrder[this._visibilityLevel] < BoardVisibilityLevelOrder[this._targetVisibilityLevel];
        }

        // The user with canUserElevatePermission=false cannot elevate the permission of the board
        return false;
    }

    /**
     * The visibility level of the board.
     *
     * @example <caption>Get the visibility level of the board</caption>
     * const visibilityLevel = board.visibilityLevel;
     */
    @observable
    get visibilityLevel(): BoardVisibilityLevel {
        return this._visibilityLevel;
    }

    /**
     * The target visibility level of the board.
     *
     * @example <caption>Get the target visibility level of the board</caption>
     * const targetVisibilityLevel = board.targetVisibilityLevel;
     */
    @observable
    get targetVisibilityLevel(): BoardVisibilityLevel {
        return this._targetVisibilityLevel;
    }

    /**
     * Whether the board has complete board metadata, fetched from the board service, including posts
     * @package Only for use in SAM.js.
     */
    get _hasCompleteBoardMetadata(): boolean {
        return this._hasCompleteBoardMetadataProp;
    }

    /**
     * @package Only for use in SAM.js.
     */
    set _hasCompleteBoardMetadata(value: boolean) {
        this._hasCompleteBoardMetadataProp = value;
    }

    /**
     * The components of the board.
     * @package Only for use in SAM.js.
     */
    get _components(): DCXComponent[] {
        return this._componentsProp;
    }

    /**
     * @package Only for use in SAM.js.
     */
    set _components(value: DCXComponent[]) {
        this._componentsProp = value;
    }

    /**
     * Fetches the list of Posts for this Board
     *
     * @example <caption>Get all posts for this board</caption>
     * const posts = board.posts.getList(PostOrder.default);
     */
    @memoize
    get posts(): PostSource {
        // board.id is not passed into the filter because the PostListLoader already has a reference to the board from the constructor
        // The PostListLoader will access the board's _postPool which only contains posts for this board
        const loader = new PostListLoader(this._core, this);
        return new ItemSource(this._postPool, [ loader ]);
    }

    /**
     * The description of the board.
     *
     * @example <caption>Get the description of the board</caption>
     * const description = board.description;
     */
    @observable
    get description(): string | undefined {
        return this._description;
    }

    static boardNameSuffix = '.ccboard';

    /** The board name contains '.ccboard' suffix, so we need to remove it for display */
    @observable
    get displayName(): string {
        return this._name.replace(Board.boardNameSuffix, '');
    }

    /**
     * The ID of the asset containing the 'boards' directory that contains the board.
     * In other words, the ID of the asset that is 2 levels up from the board.
     */
    @observable
    get baseAssetId(): string | undefined {
        return this._baseAssetId;
    }

    /**
     * The role of the current user in the board.
     *
     * @example <caption>Get the role of the current user in the board</caption>
     * const role = board.role;
     */
    @observable
    get role(): BoardMemberRole {
        return this._memberRole;
    }

    /**
     * The information about the published board. Only available if the board is a source board.
     *
     * @example <caption>Get the published board info</caption>
     * const publishedBoardInfo = board.publishedBoardInfo;
     */
    @observable
    get publishedBoardInfo(): PublishedBoardInfo | undefined {
        return this._publishedBoardInfo;
    }

    /**
     * Whether the board is published to another board.
     *
     * @example <caption>Check if the board has been published</caption>
     * const isPublishedToAnotherBoard = board.isPublishedToAnotherBoard;
     */
    @observable
    get isPublishedToAnotherBoard(): boolean {
        return !!this._publishedBoardInfo;
    }

    /**
     * The information about the source board. Only available if the board is a published board.
     *
     * @example <caption>Get the source board info</caption>
     * const sourceBoardInfo = board.sourceBoardInfo;
     */
    @observable
    get sourceBoardInfo(): SourceBoardInfo | undefined {
        return this._sourceBoardInfo;
    }

    /**
     * Whether the board is published from another board.
     *
     * @example <caption>Check if the board is a published board</caption>
     * const isPublishedFromAnotherBoard = board.isPublishedFromAnotherBoard;
     */
    @observable
    get isPublishedFromAnotherBoard(): boolean {
        return !!this._sourceBoardInfo;
    }

    /**
     * The theme of the board.
     *
     * @example <caption>Get the theme of the board</caption>
     * const theme = board.theme;
     */
    @observable
    get theme(): BoardTheme | undefined {
        return this._theme;
    }

    /**
     * Gets the background image for the board if the theme mode is set to 'image'.
     *
     * This method fetches the full-size background image from the composite component API.
     * Will use the browser cache if the component id and version are the same as the cached version.
     *
     * @returns A promise that resolves to the background image as a Blob
     * @throws {SAMError} with code BAD_REQUEST if the theme mode is not 'image'
     * @throws {SAMError} for HTTP errors (404, 500, etc.) with appropriate error codes
     *
     * @example <caption>Get the background image of the board</caption>
     *   const backgroundBlob = await board.getBackgroundImage();
     */
    async getBackgroundImage(): Promise<Blob> {
        return this._ensureBoardContext().getBoardBackgroundImage({ boardId: this.id });
    }

    /**
     * Adds a new post to a board.
     * - If the type is AssetLink:
     *   - If assetId is provided then the board will create a reference to that asset. The blob is ignored in this case
     *   - If a blob is provided then the file will be uploaded and a new asset will be created from it which the board will reference
     * - If the type is Text then the board will create a new text post with the provided text
     * @throws {SAMError} for AssetLink posts:
     *   - If the blob is provided without fileName
     *   - If the blob's filename is invalid
     *   - If the blob is provided and the parent folder cannot be found or created
     *   - If neither an assetId nor a blob is provided
     * @throws {SAMError} for Text posts:
     *   - If the text is not provided
     * @example <caption>Add a post to the board</caption>
     * await board.addPost({ type: PostType.Text, text: 'Hello, world!' });
     * await board.addPost({ type: PostType.AssetLink, assetId: 'asset-id' });
     * await board.addPost({ type: PostType.AssetLink, blob: new Blob([ 'Hello, world!' ]), fileName: 'hello.txt' });
     */
    async addPost(options: AddBoardPostOptions): Promise<void> {
        return this._ensureBoardContext().addPost({ boardId: this.id, ...options });
    }

    /**
     * Adds multiple new posts to a board. Each post is processed individually so that a subset of posts can be added even
     * if some posts fail to be added. Returns an object with the status of the operation.
     *
     * @throws {SAMError} If no posts are provided
     *
     * @example <caption>Add multiple posts to the board</caption>
     * await board.addPosts([
     *   { type: PostType.Text, text: 'Hello, world!' },
     *   { type: PostType.AssetLink, assetId: 'asset-id' },
     *   { type: PostType.AssetLink, blob: new Blob([ 'Hello, world!' ]), fileName: 'hello.txt' }
     * ]);
     */
    async addPosts(posts: AddBoardPostOptions[]): Promise<AddPostsResult> {
        return this._ensureBoardContext().addPosts({ boardId: this.id, posts });
    }

    /**
     * Updates the visibility level of the board to a higher level.
     *
     * @example <caption>Elevate the permission of the board</caption>
     * await board.elevatePermission();
     */
    async elevatePermission(): Promise<void> {
        return this._ensureBoardContext().elevatePermission({ boardId: this.id });
    }

    /**
     * Removes a post from a board
     * @example <caption>Remove a post from the board</caption>
     * await board.removePost('post-id');
     */
    async removePost(postId: string): Promise<void> {
        await this._ensureBoardContext().removePost({ boardId: this.id, postId });
    }

    /**
     * Updates a post on the given board
     * @example <caption>Update a post on the board</caption>
     * await board.updatePost({ postId: 'post-id', text: 'Hello, world!' });
     */
    async updatePost(options: UpdatePostOptions): Promise<void> {
        await this._ensureBoardContext().updatePost({ boardId: this.id, ...options });
    }

    /**
     * Update the board. Use {@link addPost}, {@link updatePost}, and {@link removePost} to manage posts.
     *
     * @example <caption>Update the board </caption>
     * await board.update({ displayName: 'Updated name', description: 'Updated description' });
     */
    async update(options: BoardUpdateOptions): Promise<void> {
        return this._ensureBoardContext().updateBoard({ boardId: this.id, ...options });
    }

    /**
     * Classifies text against ACMP classifier to determine whether or not is will be flagged for moderation.
     * @example <caption>Classify text</caption>
     * await board.classifyText({ bodyText: 'This is text to classify' });
     */
    async classifyText(options: Omit<SAM.ClassifyBoardTextOptions, 'boardId'>): Promise<SAM.ClassifyTextResponse> {
        return this._ensureBoardContext().classifyText({ boardId: this.id, ...options });
    }

    @observable
    get links(): BoardLinks {
        // Make a copy to avoid the client accidentally manipulating the links
        return Object.assign({}, this.__links as BoardLinks);
    }

    /**
     * Publishes the current board. This returns a new board object that is public.
     * @returns the public/published board
     * @experimental Boards functionality is still in progress, this method is subject to change ACPCEDU-3888
     * @example <caption>Publish the board with a custom title and subtitle</caption>
     * const publishedBoard = await board.publish({ boardTitle: 'Published Biology Board', boardSubTitle: 'By Biology - Period 2', showPosterName: true });
     */
    async publish(options: PublishOptions = {}): Promise<Board> {
        return this._ensureBoardContext().publishBoard({ boardId: this.id, ...options });
    }

    /**
     * Unpublishes the current board. This removes the published board from the board service.
     * @experimental Boards functionality is still in progress, this method is subject to change ACPCEDU-3888
     * @example <caption>Unpublish the board</caption>
     * await board.unpublish();
     */
    async unpublish(): Promise<void> {
        return this._ensureBoardContext().unpublishBoard(this.id);
    }

    /**
     * Grants board access to the entire organization (orgEverybody)
     * @example <caption>Grant access to organization</caption>
     * await board.grantAccessToOrgEverybody();
     */
    async grantAccessToOrgEverybody(): Promise<void> {
        await this._ensureBoardContext().grantBoardAccessToOrgEverybody(this.id);
    }

    /**
     * Grants public access to the board (all users)
     * @example <caption>Grant public access</caption>
     * await board.grantAccessToAll();
     */
    async grantAccessToAll(): Promise<void> {
        await this._ensureBoardContext().grantBoardAccessToAll(this.id);
    }

    /**
     * Grants board access to a user identified by email only
     * @param options - Options for granting access
     * @param options.email - User email address
     * @example <caption>Grant access by email</caption>
     * await board.grantAccessToAmbiguousUser({ email: 'user@example.com' });
     */
    async grantAccessToAmbiguousUser({ email }: BoardGrantAccessToAmbiguousUserOptions): Promise<void> {
        await this._ensureBoardContext().grantBoardAccessToAmbiguousUser({ boardId: this.id, email });
    }

    /**
     * Grants board access to a specific user with both email and user ID
     * @param options - Options for granting access
     * @param options.userId - User ID
     * @param options.email - User email address
     * @example <caption>Grant access to specific user</caption>
     * await board.grantAccessToUnambiguousUser({
     *   userId: 'user-id-123@AdobeID',
     *   email: 'user@example.com'
     * });
     */
    async grantAccessToUnambiguousUser({ userId, email }: BoardGrantAccessToUnambiguousUserOptions): Promise<void> {
        await this._ensureBoardContext().grantBoardAccessToUnambiguousUser({ boardId: this.id, userId, email });
    }

    /**
     * Grants board access to a group
     * @param options - Options for granting access
     * @param options.groupId - Group ID
     * @example <caption>Grant access to a group</caption>
     * await board.grantAccessToGroup({ groupId: 'group-id@AdobeOrg:123' });
     */
    async grantAccessToGroup({ groupId }: BoardGrantAccessToGroupOptions): Promise<void> {
        await this._ensureBoardContext().grantBoardAccessToGroup({ boardId: this.id, groupId });
    }

    /**
     * Grants board access to multiple users at once
     * @param options - Options for granting access
     * @param options.users - Array of users with email and optional userId
     * @example <caption>Grant access to multiple users</caption>
     * await board.grantAccessToUsers({
     *   users: [
     *     { email: 'user1@example.com' },
     *     { email: 'user2@example.com', userId: 'user-id-123@AdobeID' }
     *   ]
     * });
     */
    async grantAccessToUsers({ users }: BoardGrantAccessToUsersOptions): Promise<void> {
        await this._ensureBoardContext().grantBoardAccessToUsers({ boardId: this.id, users });
    }

    /**
     * Grants board access to multiple groups at once
     * @param options - Options for granting access
     * @param options.groupIds - Array of group IDs
     * @example <caption>Grant access to multiple groups</caption>
     * await board.grantAccessToGroups({
     *   groupIds: ['group1@AdobeOrg:1', 'group2@AdobeOrg:2']
     * });
     */
    async grantAccessToGroups({ groupIds }: BoardGrantAccessToGroupsOptions): Promise<void> {
        await this._ensureBoardContext().grantBoardAccessToGroups({ boardId: this.id, groupIds });
    }

    /**
     * Whether the board is read only. This means the board name and description cannot be edited.
     * This is overriding AdobeAsset.isReadOnly function.
     *
     * Note: this function may not be accurate if the board metadata is not loaded from the board service.
     * @example <caption>Check if the board is read only</caption>
     * const isReadOnly = board.isReadOnly;
     */
    @observable
    isReadOnly(): boolean {
        // the board is read only if the board is published from another board or the user is not the owner of the board
        return this.isPublishedFromAnotherBoard || this._memberRole !== BoardMemberRole.OWNER;
    }

    /**
     * Whether the current user can add a post to the board.
     *
     * @example <caption>Check if the current user can add a post to the board</caption>
     * const canAddPost = board.canAddPost;
     */
    @observable
    get canAddPost(): boolean {
        // user (regardless of role) cannot add post to a board that is published from another board
        if (this.isPublishedFromAnotherBoard) {
            return false;
        }

        return this._memberRole === BoardMemberRole.OWNER || this._memberRole === BoardMemberRole.POSTER;
    }

    /**
     * Whether the current user can unpublish the board.
     *
     * @example <caption>Check if the current user can unpublish the board</caption>
     * const canUnpublish = board.canUnpublish;
     */
    @observable
    get canUnpublish(): boolean {
        return this._memberRole === BoardMemberRole.OWNER && this.isPublishedToAnotherBoard;
    }

    /**
     * Whether the current user can publish the board.
     *
     * @example <caption>Check if the current user can publish the board</caption>
     * const canPublish = board.canPublish;
     */
    @observable
    get canPublish(): boolean {
        // if the board is read only / published from another board, then the user cannot publish it
        if (this.isPublishedFromAnotherBoard) {
            return false;
        }

        return this._memberRole === BoardMemberRole.OWNER;
    }

    /**
     * Get a post by its ID in this board
     * @throws {SAMError} if the post is not found in this board
     * @example <caption>Get a post by its ID</caption>
     * const post = await board.getPostById('post-id');
     */
    async getPostById(id: string): Promise<Post> {
        return this._ensureBoardContext().getPostByBoardAndPostId({ boardId: this.id, postId: id });
    }

    /** Whether new comments are allowed on the posts of the board */
    @observable
    get areNewCommentsAllowed(): boolean | undefined {
        return this._areNewCommentsAllowed;
    }

    /**
     * Overwrites AdobeAsset instance of handleONSChangedResources.
     *
     * The board service is the source of truth for Board-specific
     * repo metadata, app metadata, and permissions/links. Meaning
     * metadata that is not required for board actions is fetched
     * with R-API. There is a chance the cached board contains a
     * combination of board metadata and core asset metadata
     * therefore metadata is fetched from both the board service and R-API
     *
     * @package -- for SAM.js internal use only
     */
    handleONSChangedResources(changedResources: ONSChangedAssetInfo['changedResources']) {
        // Refetch any potential non-board metadata using the AdobeAsset's handleONSChangedResources
        super.handleONSChangedResources(changedResources);
        // If changedResources includes repoMetadata changes then Board._load will be
        // called by the line above which calls the same line as below. This check
        // minimizes unnecessary calls to the board service
        if (!changedResources?.includes('api:metadata/repository')) {
            // Then fetch board-specific metadata from the board service
            this._boardContext._fetchBoardById(this.id);
        }
    }

    /**
     * @package -- for use in SAM.js only
     * Will override any cached board with the latest data from the board service and R-API
     */
    @retry
    _loadWithRetry(): Promise<void> {
        return this._load();
    }

    /**
     * @param repoMetadata {RepositoryMetadata} If passed in, it will be used instead of loading from the service
     * @param appMetadata {any} If passed in, it will be used instead of loading from the service
     * @param effectivePermission {Permission} If passed in, it will be used instead of loading from the service
     *
     * @package -- only for use in SAM.js
     */
    async _load({
        repoMetadata,
        appMetadata,
        effectivePermission,
    }: {
        repoMetadata?: RepositoryMetadata;
        appMetadata?: any;
        effectivePermission?: Permission;
    } = {}): Promise<void> {
        // Ensure board context is initialized
        if (!this._boardContext) {
            this._boardContext = await this._core.getBoardContext();
        }

        const promise = super._load({ repoMetadata, appMetadata, effectivePermission });
        // Run both loading operations in parallel
        await Promise.allSettled([
            promise,
            // since we don't want the RAPI call to override the result from this._boardContext._fetchBoardById, we pass in the promise from super._load
            // This way, this._boardContext._fetchBoardById will wait for the super._load to complete before making changes to the internal state of the board
            this._boardContext._fetchBoardById(this.id, promise)
        ]);
    }

    /**
     * Determine if the given name is valid when updating a board. This will validate using the baseAssetId of the current board.
     * @throws {SAMError} if the name is invalid or if the base asset ID is not set in the board
     *
     * @example <caption>Validate a board name before updating a board</caption>
     * try {
     *  await board.validateNameForUpdate({ name: 'My Board' });
     * } catch (error) {}
     */
    async validateNameForUpdate(options: Omit<ValidateBoardNameForUpdateOptions, 'boardId' | 'baseAssetId'>): Promise<void> {
        if (!this.baseAssetId) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Base asset ID of the current board is required for name validation');
        }

        return this._ensureBoardContext().validateBoardNameForUpdate({
            ...options,
            boardId: this.id,
            baseAssetId: this.baseAssetId
        });
    }

    protected _getCacheBuster(): string | undefined {
        return this.etag;
    }
}

/**
 * Updates the backgroundImageReference on the board's theme when components or theme changes.
 * Only applies when theme mode is 'image'.
 */
function updateBackgroundImageReference(board: Board): void {
    const theme = board['_theme'];
    if (!theme || theme.mode !== BOARD_THEME_MODES.IMAGE) {
        return;
    }

    const backgroundComponent = board['_components']?.find(
        (component: DCXComponent) => component.path === BOARD_COMPONENT_PATHS.FULL_SIZE_BACKGROUND_IMAGE
    );

    if (backgroundComponent?.id && backgroundComponent?.version) {
        (board['_theme'] as ImageTheme).backgroundImageReference = {
            componentId: backgroundComponent.id,
            revisionId: backgroundComponent.version,
        };
    }
    // If the background component is not found but theme mode is IMAGE,
    // do not clear previous background image reference to avoid breaking downstream logic
}

export const BoardUpdater = new ItemUpdater<Board, Partial<RemoteBoard | AdobeAssetUpdaterMetadata>>({
    localItemType: Board,
    remoteIdProperty: 'repo:assetId',
    propertyUpdater: new PropertyUpdater({
        _id: { name: 'repo:assetId', format: 'string' },
        _assetClass: { name: 'repo:assetClass', choices: AssetClassChoices },
        _boardType: { name: 'boardType', choices: BoardTypeChoices },
        _canUserElevatePermission: { name: 'canUserElevatePermission', format: 'boolean' },
        _description: { name: 'dc:description', format: 'string' },
        _name: { name: 'repo:name', format: 'string' },
        _created: { name: 'repo:createDate', format: 'date' },
        _repositoryID: { name: 'repo:repositoryId', format: 'string' },
        __links: { name: '_links', format: 'object' },
        _createdBy: { name: 'repo:createdBy', format: 'string' },
        _modifiedBy: { name: 'repo:modifiedBy', format: 'string' },
        _modified: { name: 'repo:modifyDate', format: 'date' },
        _assetState: { name: 'repo:state', choices: AssetStateChoices },
        _type: { name: 'dc:format', format: 'string' },
        _path: { name: 'repo:path', format: 'string' },
        _etag: { name: 'repo:etag', format: 'string' },
        _remotePosts: {
            isArray: true,
            name: 'posts',
            format: 'object',
            set: async (remotePosts: (RemoteTextPost | RemoteAssetLinkPost)[], dest: ISAMObject) => {
                const board = dest as Board;
                board._posts.length = 0;
                const session = board._postPool.createMutationSession<Post>();

                // When a post is deleted it will not be in the remotePosts array, but it will still exist in the pool
                // Here we will remove the posts from the pool that are not in the new remotePosts array
                const itemsToRemoveFromPool = board._postPool.toArray().filter((post) => !remotePosts.some((remotePost) => remotePost.id === post.id));
                itemsToRemoveFromPool.forEach((post) => session.queueDiscardedItem(post));
                board._postPool.removeLocalItems(itemsToRemoveFromPool.map((post) => post.id));

                // Add new posts to the pool, or update remaining posts
                const posts: Post[] = [];
                remotePosts.forEach((remotePost) => {
                    const remotePostWithComputedValues = { ...remotePost, computedBoardId: board.id };
                    if (remotePost.type === PostRemoteType.TEXT) {
                        posts.push(TextPostUpdater.updateRemoteItem(session as IUpdateSession<TextPost>, remotePostWithComputedValues));
                    } else if (remotePost.type === PostRemoteType.ASSET_LINK) {
                        posts.push(AssetLinkPostUpdater.updateRemoteItem(session as IUpdateSession<AssetLinkPost>, remotePostWithComputedValues));
                    }
                });
                session.commit();
                board._posts.push(...posts);
            }
        },
        _baseAssetId: { name: 'board:context[baseAssetId]', format: 'string' },
        _memberRole: { name: 'memberRole', choices: Object.values(BoardMemberRole) },
        _publishedBoardInfo: {
            name: 'board:publishedBoard',
            format: 'object',
            set: (publishedBoardInfo: RemotePublishedBoardInfo | undefined, dest: ISAMObject) => {
                const board = dest as Board;
                if (!publishedBoardInfo) {
                    board['_publishedBoardInfo'] = undefined;
                    return;
                }
                board['_publishedBoardInfo'] = {
                    boardId: publishedBoardInfo['repo:assetId'],
                    showPosterName: publishedBoardInfo['board:showPosterName'] || false,
                };
            }
        },
        _sourceBoardInfo: {
            name: 'board:sourceBoard',
            format: 'object',
            set: (sourceBoardInfo: RemoteSourceBoardInfo, dest: ISAMObject) => {
                const board = dest as Board;
                board['_sourceBoardInfo'] = {
                    boardId: sourceBoardInfo['repo:assetId'],
                    publishedVersion: sourceBoardInfo['repo:version'],
                };
            }
        },
        _theme: { name: 'board:theme',
            format: 'object',
            set: (theme: BoardTheme, dest: ISAMObject) => {
                const board = dest as Board;
                board['_theme'] = theme;
                updateBackgroundImageReference(board);
            }
        },
        _components: {
            name: 'components',
            isArray: true,
            format: 'object',
            set: (components: DCXComponent[], dest: ISAMObject) => {
                const board = dest as Board;
                board['_components'] = components;
                updateBackgroundImageReference(board);
            }
        },
        _areNewCommentsAllowed: { name: 'board:newCommentsAllowed', format: 'boolean' },
        _visibilityLevel: { name: 'board:visibilityLevel', choices: BoardVisibilityLevelChoices },
        _targetVisibilityLevel: { name: 'board:targetVisibilityLevel', choices: BoardVisibilityLevelChoices },
    }),
});
