import type ISAMCorePrivate from '../core/ISAMCorePrivate';
import type { IItemLoader, IItemLoaderOptions, ILoadedPage, ILoadNextPage } from '../core/ItemLoader';
import type ProjectFilter from './ProjectFilter';
import type { ProjectConfig } from './ProjectSource';
import type { IProject } from '../interface/ProjectsModel';
import { ProjectViews } from '../interface/ProjectsModel';
import { SAMError, SAMErrorCode } from '../core/SAMError';
import type { AssetListFilter } from '../graphql/generated/types';
import type { PLSListResponse } from '../graphql/models/PLSModels';
import { DEFAULT_PLS_PAGE_SIZE } from '../graphql/models/PLSModels';
import type { ProjectUpdaterMetadata } from './Project';
import type Project from './Project';
import { AssetType } from '../interface/AssetModel';
import { getMostRecentValidMutation } from '../utils/loaderUtils';
import ProjectsListLoader from './ProjectsListLoader';
import { LazyLoadManager } from '../core/decorators/LazyLoadManager';
import { ORGANIZATIONS_CHANGED } from './OrganizationsChangedEvent';

export default class PLSProjectsLoader implements IItemLoader<ProjectConfig> {
    constructor(private _core: ISAMCorePrivate) { }

    supportsFilter(): boolean {
        return true;
    }

    async loadPage(options: IItemLoaderOptions<ProjectConfig>): Promise<ILoadedPage<ProjectConfig>> {
        return await this._loadPage(options);
    }

    private async _loadPage(options: IItemLoaderOptions<ProjectConfig>, after?: string): Promise<ILoadedPage<ProjectConfig>> {
        // We just need to take care of view and directorySubtypes for now as PLS doesn't support other filters
        const { view, directorySubtypes } = options.filter as ProjectFilter;
        const filter: AssetListFilter = {
            assetType: {
                in: [ AssetType.Project ]
            },
            assetSubType: {
                // directorySubtypes should match to assetSubType
                in: directorySubtypes
            }
        };
        const latency = this._core._environment.getValue('GQL_LIST_UPDATE_LATENCY');
        const mostRecentValidMutation = getMostRecentValidMutation(options.resource, latency);

        // Yours and SWY views depend on the organizations list being loaded so that
        // Project._views can correctly compute orgIds for CCE/CCT org-owned projects.
        if (view === ProjectViews.Yours || view === ProjectViews.SWY) {
            await LazyLoadManager.fetchIfNeeded(this._core.hostAssetContext, ORGANIZATIONS_CHANGED);
        }

        let result: PLSListResponse<Partial<IProject>>;
        const gqlManager = await this._core._getGQLManager();
        const projectContext = await this._core.getProjectContext();
        switch (view) {
        case ProjectViews.All:
        case undefined: // Default to All view when view is not specified (e.g., EverythingFilter)
            result = await gqlManager.allProjects({
                first: options.loadOptions?.limit ?? DEFAULT_PLS_PAGE_SIZE,
                after,
                filter,
            }, options.resource);
            break;
        case ProjectViews.Yours: {
            const projectFilter = options.filter as ProjectFilter;
            const accountType = projectFilter.accountType;
            // CCE/CCT users (type2/type3) use the PLS businessStorage query
            if (accountType !== 'type1') {
                result = await gqlManager.businessStorageProjects({
                    first: options.loadOptions?.limit ?? DEFAULT_PLS_PAGE_SIZE,
                    after,
                    filter,
                }, options.resource);
            } else {
                // CCI users (type1) use the PLS yours query
                result = await gqlManager.yoursProjects({
                    first: options.loadOptions?.limit ?? DEFAULT_PLS_PAGE_SIZE,
                    after,
                    filter,
                }, options.resource);
            }
            break;
        }
        case ProjectViews.SWY:
            result = await gqlManager.sharedWithYouProjects({
                first: options.loadOptions?.limit ?? DEFAULT_PLS_PAGE_SIZE,
                after,
                filter,
            }, options.resource);
            break;
        case ProjectViews.Recent:
            result = await gqlManager.recentProjects({
                first: options.loadOptions?.limit ?? DEFAULT_PLS_PAGE_SIZE,
                after,
                filter,
            }, options.resource);
            break;
        case ProjectViews.Admin:
        case ProjectViews.Organization: {
            // Admin and Organization views use Projects Service (not PLS) because PLS doesn't support nameContains
            const projectsServiceLoader = new ProjectsListLoader(
                this._core._getAssetPool(),
                projectContext['_projectInterface'],
                projectContext._projectUpdater,
                this._core
            );
            return await projectsServiceLoader.loadPage(options);
        }
        default:
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, `Unsupported view: ${view}`);
        }

        const session = this._core
            ._getAssetPool()
            .createLoaderUpdateSession<Project>(mostRecentValidMutation);
        const updater = projectContext._projectUpdater;
        const projects: Partial<IProject | ProjectUpdaterMetadata>[] = result.items.map((project: Partial<IProject>) =>
            view === ProjectViews.Recent
                // isRecent would go away in favor of lastAccessed
                ? { ...project, isRecent: true }
                : { ...project, allowInLists: true });
        const items = updater.updateRemoteItems(session, projects);

        let loadNextPage: ILoadNextPage<ProjectConfig> | undefined;
        if (result.pageInfo.hasNextPage) {
            loadNextPage = (options: IItemLoaderOptions<ProjectConfig>) => this._loadPage(options, result.pageInfo.endCursor!);
        }

        session.commit();

        return {
            items,
            loadNextPage,
            mostRecentValidMutation,
        };
    }
}
