import type { SAM } from '@ccx-public/component-types';
import SAMError, { SAMErrorCode } from '../core/SAMError';
import type { GenerationHistoryAssetData, MelvilleGenerationHistoryAssetsParams, MelvilleGenerationHistoryAssetsResponse } from './GenerationHistoryAssetModel';
import InterfaceBase from './InterfaceBase';
import { moveUrlQueryParamsToHeaders } from './LibraryInterface';
import type { MelvilleLink } from './LibraryModel';
import type { HeaderMap } from './LinkUtils';
import { fillURLTemplate } from './LinkUtils';
import type Resource from '../assets/Resource';

export default class GenerationHistoryInterface extends InterfaceBase {
    private _getUrl(endpoint: string): string {
        return `https://${this._core._environment.endpoints.MELVILLE_HOST}${endpoint}`;
    }

    async getGenerationHistoryAssets(queryParams: MelvilleGenerationHistoryAssetsParams, resource?: Resource): Promise<MelvilleGenerationHistoryAssetsResponse> {
        if (queryParams?.limit && queryParams?.start === undefined) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, '[Melville] If limit is provided, start must also be provided.');
        }
        queryParams = sortParameters(queryParams);
        const urlWithQueryParams = fillURLTemplate(
            this._getUrl('/api/v1/firefly-generations'),
            queryParams
        );
        // Pass as many parameters as headers as we can, to avoid extra CORS preflight OPTIONS requests per url.
        const [ url, headers ] = moveUrlQueryParamsToHeaders(urlWithQueryParams);
        // Ensure browser doesn't automatically add If-None-Match, otherwise
        // service may respond with cached data for a library
        const defaultHeaders: HeaderMap = { ['Cache-Control']: 'no-cache, no-store, max-age=0' };
        const finalHeaders = { ...defaultHeaders, ...headers };

        return await this._getResponse(url, { headers: finalHeaders, resource });
    }

    /**
   * @package -- only for use in SAM.js
   * Fetches the next page of history assets from Melville
   * @returns a list of history assets along with page information and links to the next page
   */
    async getGenerationHistoryAssetsUsingPageLink(pageLink: MelvilleLink, resource?: Resource): Promise<MelvilleGenerationHistoryAssetsResponse> {
        const [ url, headers ] = moveUrlQueryParamsToHeaders(this._getUrl(pageLink.href));
        return this._getResponse(url, { headers, resource });
    }

    /**
     * Fetches a history asset by ID
     *
     * @param assetId ID of custom model to be fetched
     * @returns the custom model
     */
    async getGenerationHistoryAssetById(assetId: string): Promise<GenerationHistoryAssetData> {
        return await this._getResponse<GenerationHistoryAssetData>(
            this._getUrl(`/api/v1/firefly-generations/${assetId}`),
            { headers: { 'Content-Type': 'application/json' } }
        );
    }

    async getOutputComponentDownloadURLs(componentURLs: Record<string, SAM.ComponentURL>): Promise<string[]> {
        const downloadURLPromises = Object.values(componentURLs).map(componentURL => this.getOutputComponentDownloadURL(componentURL));

        return Promise.all(downloadURLPromises);
    }

    async getOutputComponentDownloadURL(componentURL: SAM.ComponentURL): Promise<string> {
        const { isBlockDownload, url } = componentURL;

        if (isBlockDownload) {
            return url;
        }

        const componentLinkResponse = await this._doGet(url);

        const blobUrl = URL.createObjectURL(await componentLinkResponse.blob());

        if (!blobUrl?.length) {
            throw SAMError.create(SAMErrorCode.INTERNAL_ERROR, 'Cannot convert blob to URL');
        }

        return blobUrl;
    }
}

// Sort parameters so that the query string is stable, preventing unnecessary cache misses.
export const sortParameters = (parameters: MelvilleGenerationHistoryAssetsParams): MelvilleGenerationHistoryAssetsParams => {
    return Object.fromEntries(
        Object.entries(parameters)
            .map(([ key, value ]) => {
                if (Array.isArray(value)) {
                    return [ key, value.sort() ];
                }
                return [ key, value ];
            })
            .sort()
    );
};
