import type { SAM } from '@ccx-public/component-types';

import type AssetContext from '../assets/AssetContext';
import type AdobeAsset from '../assets/AdobeAsset';
import AssetLinkList from './AssetLinkList';
import { observable } from '../core/decorators';
import { SAMObjectEventEmitter } from '../core/SAMObjectEventEmitter';

export default class AssetLinkManager extends SAMObjectEventEmitter implements SAM.AssetLinkManager {

    private _lists: Set<AssetLinkList> = new Set();

    constructor(
        public _context: AssetContext
    ) {
        super(_context._core);
    }

    private _onListChange = () => {
        // We need to notify the AssetContext whenever a list changes, so it can
        // update the asset ids it's subscribing to in ONS (if a link is broken,
        // we still want to get updates even if the asset isn't in the asset pool)
        this._context._updateONSSubscriptions();
    };

    createList(containerAsset?: AdobeAsset): AssetLinkList {
        const list = new AssetLinkList(this, containerAsset);
        list.on('change', this._onListChange);
        this._lists.add(list);
        this.emit('change');
        return list;
    }

    removeList(list: AssetLinkList) {
        this._lists.delete(list);
        list.off('change', this._onListChange);
        this.emit('change');
    }

    /**
     * Get an array of all the asset link lists.
     */
    @observable
    get lists(): AssetLinkList[] {
        return [ ...this._lists ];
    }
}
