/**
 * MIME types for cloud-native file formats that can be converted back to their
 * desktop counterparts during download.
 */
export const DOWNLOAD_CONVERSION_REGISTRY = [
    'document/vnd.adobe.cpsd+dcx',           // .psdc (from .psd/.psb)
    'document/vnd.adobe.illustrator+dcx',    // .aic (from .ai)
    'document/vnd.adobe.indesign+dcx',       // .inddc (from .indd)
    'document/vnd.adobe.cpsd.live+dcx',      // .psdl (from .psd)
    'document/vnd.adobe.indesign.live+dcx'   // .inddl (from .indd)
] as const;

/**
 * Returns true if the given media type is a cloud format that can be converted
 * to a desktop format during download. Shared by AdobeAsset and AssetVersion.
 */
export function isConvertibleCloudAsset(mediaType: string | undefined): boolean {
    return !!(mediaType && DOWNLOAD_CONVERSION_REGISTRY.some(mt => mt === mediaType));
}

/**
 * Registry of supported file types for upload conversion with their desktop media types
 *
 * Each property represents a desktop file extension (e.g., '.psd', '.ai', '.indd')
 * Each property value is an object containing:
 * - cloudExtension: An array of corresponding cloud file extensions. This is provided as a courtesy to clients to use when specifying the targetfile name, but is not used by SAM.js.
 * - desktopMediaType: The MIME type for the desktop file format. This is required for the conversion to cloud process. Clients can also use this to specify
 *   the desktop media type for the file when uploading to cloud, or if they don't specify a media type, SAM.js will use this value when needed.
 */
export const UPLOAD_CONVERSION_REGISTRY = {
    '.psd': {
        cloudExtension: [ '.psdc', '.psdl' ],
        desktopMediaType: 'image/vnd.adobe.photoshop'
    },
    '.ai': {
        cloudExtension: [ '.aic' ],
        desktopMediaType: 'application/vnd.adobe.illustrator'
    },
    '.indd': {
        cloudExtension: [ '.inddc', '.inddl' ],
        desktopMediaType: 'application/x-indesign'
    },
    '.psb': {
        cloudExtension: [ '.psdc' ],
        desktopMediaType: 'image/photoshop-large'
    }
} as const;
