import type { ISAMObject } from '../indexPrivate';
import type { IsEqualFn } from './ObjectUtils';
import { deepClone, isDeepEqual, isStrictEqual } from './ObjectUtils';
import SAMError, { SAMErrorCode } from './SAMError';

export const NotFound = Symbol('NotFound');

type ParseFn = (a: any) => any;

export type PropertyFormatType = {
    parse: ParseFn,
    isEqual: IsEqualFn
}

type GetFn = (source: any, dest: ISAMObject) => any;
type SetFn = (parsedSource: any, dest: ISAMObject) => any;

type BuiltinPropertyFormats = 'string' | 'boolean' | 'number' | 'date' | 'date_as_number' | 'object' | 'object_subset';
type PropertyFormat = BuiltinPropertyFormats | PropertyFormatType;

type IPropertyType = {
    name: string,
    format: PropertyFormatType,
    choices?: any[],
    isArray: boolean,
    mapByKey?: string,
    // "get" from the source data
    get: GetFn,
    // "set" on the dest object
    set: SetFn
}

type IUserPropertyType = string | {
    name?: string,
    format?: PropertyFormat,
    choices?: any[],
    isArray?: boolean,
    mapByKey?: string,
    get?: GetFn,
    set?: SetFn
};

export type IPropertyTypeMap = {
    [key: string]: IUserPropertyType
}

type IPropertyUpdater = (dest: ISAMObject, source: any) => boolean;

const formats: { [ key in BuiltinPropertyFormats ]: PropertyFormatType } = {
    string: {
        // In general, parse strings as strings, but special case null's as undefined, and undefined's as undefined since String() will convert them to "undefined".
        parse: (value: any) => (value === null) || (value === undefined) ? undefined : String(value),
        isEqual: isStrictEqual
    },
    number: {
        parse: Number,
        isEqual: isStrictEqual
    },
    date: {
        parse: (value: any) => {
            if (value === null) {return undefined;}
            if (value === undefined || value instanceof Date) { return value; }
            return new Date(String(value));
        },
        isEqual: (a?: Date, b?: Date) => a?.toISOString() === b?.toISOString()
    },
    // Some APIs like the invitation service return dates as a number (Unix epoch time) rather than a string
    // These still map onto the JS Date object, but need to be parsed differently.
    date_as_number: {
        parse: (value: any) => value === undefined ? undefined : new Date(Number(value)),
        isEqual: (a?: Date, b?: Date) => a?.toISOString() === b?.toISOString()
    },

    // Support actual booleans, the string 'true', or non-zero numbers.
    boolean: {
        parse: (value: any) => value === true
            || (typeof value === 'string' && value.toLowerCase() === 'true')
            || (typeof value === 'number' && Boolean(value)),
        isEqual: isStrictEqual
    },
    object: {
        // Make a deep copy of the object if it is defined.
        parse: (value: any) => value !== undefined ? deepClone(value) : undefined,
        isEqual: isDeepEqual
    },
    // Sometimes the source data is only going to be merged into the destination property, so
    // comparison only needs to happen among the top-level keys that are present in the source.
    object_subset: {
        parse: deepClone,
        isEqual(destObj: any, sourceObj: any): boolean {
            // if both are undefined, then they are equal
            if (destObj === sourceObj) { return true; }
            // if destObj is undefined, then it can be overwritten with sourceObj
            // NOTE: sourceObj is expected to not be undefined because JSON doesn't support undefined properties,
            // and so will get skipped since the sourceObj will be NotFound.
            if (destObj === undefined) {
                return false;
            }

            // Fix for https://jira.corp.adobe.com/browse/SHARED-2096
            //
            // Although we don't expect our servers to return null's,
            // we are receiving repometadata with :
            //   "_embedded": {
            //      "http://ns.adobe.com/adobecloud/rel/metadata/application": null
            //   }
            //
            // which reaches this code as (sourceObj === null),
            // which causes Object.keys(null) to throw
            //   TypeError: Cannot convert undefined or null to object
            //
            // The code below would return true for sourceObj = {},
            // so it makes sense to have an early return of true for sourceObj = null.
            //
            // NOTE: At the moment, the only client of 'object_subset' is '_appMetadata._data',
            // which would work with returning true ( the setter isn't invoked because sourceObj
            // isEqual() to the existing data ) or false ( the setter is invoked, but _mergeData(null)
            // is the same as _mergeData( {} ), which doesn't add anything to data ). The difference
            // is the setter would also emit('change') despite nothing changing.
            //
            // ALSO NOTE: Some servers might meaningfully provide (sourceObj === null) to have us
            // delete local data, but our server's don't, and if they did, our use of 'object_subset'
            // would have to be re-written to handle this as _mergeData(null) doesn't. But if they
            // did, we'd need to return false for this case. Until then, we're returning true
            // to avoid the unnecessary change event.

            if (!sourceObj) {
                return true;
            }

            const sourceKeys =  Object.keys(sourceObj);
            const destObjSubset = sourceKeys.reduce((result: any, key: string) => {
                result[key] = destObj[key];
                return result;
            }, {});
            return isDeepEqual(destObjSubset, sourceObj);
        }
    }
};

const KEY_REGEXP = /([^.[]+)|(\[[^\]]+\])/g;
function getKeys(name: string): string[] {
    const keys = name.match(KEY_REGEXP) || [];
    if (!keys.length) {
        throw SAMError.create(SAMErrorCode.BAD_REQUEST, `Un-parseable key ${name}`);
    }
    const newKeys = keys.map(key => {
        // Remove brackets
        if (key[0] === '[' && key.slice(-1) === ']') {
            return key.slice(1, -1);
        }
        return key;
    });
    return newKeys;
}

function makeGetFn(name: string) {
    const keys = getKeys(name);
    return (source: any) => {
        let value = source;
        for (const key of keys) {
            if (!Object.prototype.hasOwnProperty.call(value, key)) {
                return NotFound;
            }
            value = value[key];
        }
        return value;
    };
}

function makeSetFn(name: string) {
    if (name.includes('.')) {
        // For complex properties of the Item being updated, assumptions can't be made about how to set them,
        // because some might be a class instance.
        throw SAMError.create(SAMErrorCode.BAD_REQUEST, `Cannot use dot delimiter (${name}) without a custom setter`);
    }
    return (parsedSource: any, dest: any): void => {
        dest[name] = parsedSource;
    };
}

function makeMergeSetFn(name: string) {
    if (name.includes('.')) {
        // For complex properties of the Item being updated, assumptions can't be made about how to set them,
        // because some might be a class instance.
        throw SAMError.create(SAMErrorCode.BAD_REQUEST, `Cannot use dot delimiter (${name}) without a custom setter`);
    }
    return (parsedSource: any, dest: any): void => {
        dest[name] = {
            ...(dest[name] ?? {}),
            ...(parsedSource ?? {})
        };
    };
}

function normalizeFormat(name: string, format?: PropertyFormat, mapByKey?: string): PropertyFormatType {
    if (!format) {
        // When we use mapByKey, the format is always an object as needs to have the actual mapByKey property.
        return mapByKey ? formats.object : formats.string;
    }
    if (typeof format === 'string') {
        if (!Object.prototype.hasOwnProperty.call(formats, format)) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, `Unexpected type format ${format} for ${name} property updater.`);
        }
        return formats[format];
    }
    return format as PropertyFormatType;
}

function normalizeType(key: string, type: IUserPropertyType): IPropertyType {
    // When the property type is a simple string, then the source property is a simple
    // string parameter
    if (typeof type === 'string') {
        return {
            name: key,
            format: formats.string,
            get: makeGetFn(type),
            set: makeSetFn(key),
            isArray: false
        };
    }

    const { name, format, choices, get, set, isArray, mapByKey } = type;
    const sourceName = name ?? key;
    return {
        name: sourceName,
        format: normalizeFormat(sourceName, format, mapByKey),
        choices,
        mapByKey,
        isArray: isArray ?? false,
        get: get ?? makeGetFn(name ?? key),
        set: set ?? (format === 'object_subset' ? makeMergeSetFn(key) : makeSetFn(key))
    };
}

function validateValue(dest: ISAMObject, name: string, choices: any[] | undefined, value: any): boolean {
    if (choices && !choices.includes(value)) {
        dest._core._environment.error(`Invalid value ${value} passed for the ${name} property. Expected one of ${ choices.join(', ') }.`);
        return false;
    }
    return true;
}

function createPropertyUpdater(key: string, userType: IUserPropertyType): IPropertyUpdater {
    const type = normalizeType(key, userType);
    const { name, format, choices, get, set, isArray, mapByKey } = type;

    return (dest: ISAMObject, source: any): boolean => {
        const anyDest: any = dest;
        const destValGetter = makeGetFn(key);
        // If the dest property does not exist, treat it as undefined so it can be updated
        // This prevents the `a.toISOString is not a function` error for date fields
        const destVal = (destValGetter(anyDest) === NotFound ? undefined : destValGetter(anyDest));

        let value = get(source, dest);
        if (value === NotFound) {
            return false;
        }

        if (mapByKey) {
            /**
             * The input value is just an array like the following example:
             *
             * [
             *     {
             *         name: 'working_files',
             *         id: 'urn:1'
             *     },
             *     {
             *         name: 'canvases',
             *         id: 'urn:2'
             *     }
             * ]
             *
             * The result will be a Map object like the following:
             *
             *  'working_files' => {
             *      name: 'working_files',
             *      id: 'urn:1'
             *  },
             *  'canvases' => {
             *      name: 'canvases',
             *      id: 'urn:1'
             *  },
             *
             * - In this case the 'name' property becomes the key of the map. The caller can change the key using the
             * `mapByKey` variable.
             * - The actual value of the map entries is just the object itself.
             * - This value can be customized using the `format.parse` function provided by the caller.
             * - The parsed value can be validated against a predefined list of `choices` provided by the caller.
             */
            if (!Array.isArray(value)) {
                dest._core._environment.error(`Invalid value ${value} passed for the ${name} property. Expected an array.`);
                return false;
            }

            const map = new Map();
            for (const item of value) {
                if (!Object.prototype.hasOwnProperty.call(item, mapByKey)) {
                    dest._core._environment.error(`Invalid item passed for the ${name} array property. Missing ${mapByKey} property on the item of the array.`);
                    continue;
                }
                const key = item[mapByKey];
                const parsedItem = format.parse(item);
                if (!validateValue(dest, name, choices, parsedItem)) {
                    continue;
                }
                map.set(key, parsedItem);
            }

            if (isDeepEqual(destVal, map)) {
                return false;
            }

            value = map;

        } else if (isArray) {
            if (!Array.isArray(value)) {
                dest._core._environment.error(`Invalid value ${value} passed for the ${name} property. Expected an array.`);
                return false;
            }
            // Arrays must make a copy of their initial content to avoid mutations
            // of the original array after the value is stored inside the object.
            const array = [];
            for (const item of value) {
                const parsedItem = format.parse(item);
                if (validateValue(dest, name, choices, parsedItem)) {
                    array.push(parsedItem);
                }
            }
            if (isDeepEqual(destVal, array)) {
                return false;
            }

            value = array;

        } else {
            value = format.parse(value);
            if (!validateValue(dest, name, choices, value)) {
                return false;
            }
            if (format.isEqual(destVal, value)) {
                return false;
            }
        }

        set(value, anyDest);
        return true;
    };
}

export default class PropertyUpdater {

    private _updaters: { updater: IPropertyUpdater; key: string}[];

    constructor(map: IPropertyTypeMap) {
        this._updaters = Object.keys(map).map(
            (key) => {
                return {
                    updater: createPropertyUpdater(key, map[key]),
                    key
                };
            }
        );
    }

    update(dest: ISAMObject, source: any): string[] {
        const propertyChanges = [];
        for (const updateObj of this._updaters) {
            const { updater, key } = updateObj;
            if (updater(dest, source)) {
                propertyChanges.push(key);
            }
        }
        return propertyChanges;
    }
}
