import setURLSearchParams from '@sam-js-src/utils/searchParams';
import InterfaceBase from './InterfaceBase';

interface IWorkfrontLinkResponse {
    UID: string;
    workfrontObjectGuid: string;
    workfrontType: string;
    workfrontURL: string;
}

export default class WorkfrontInterface extends InterfaceBase {
    /**
     * @TODO [SAMJS-729] replace with prod/stage urls once available.
     */
    public _getWorkfrontLinkURL() {
        return `https://${this._core._environment.endpoints.WORKFRONT_HOST}/esm-connector/api/v1/search`;
    }

    async getWorkfrontLink(assetId: string, ordId: string): Promise<IWorkfrontLinkResponse> {
        const url = new URL(`${this._getWorkfrontLinkURL()}?`);
        setURLSearchParams(url, { 'UID': assetId });
        const response = await this._doGet(url.toString(),  {
            headers: {
                'x-gw-ims-org-id': ordId
            }
        });
        return response.json();
    }
}
