import type { SAM } from '@ccx-public/component-types';
import type {
    IComparatorMap } from '../core/ItemOrder';
import {
    compareValues,
    createItemOrderFactory
} from '../core/ItemOrder';
import { StudentAssignmentStatus } from '../interface/StudentAssignmentModel';
import type StudentAssignment from './StudentAssignment';

export type StudentAssignmentOrderField = 'studentDisplayName' | 'submissionDate' | 'status';

// Prioritize assignments that require teacher attention: SUBMITTED, IN_PROGRESS, RETURNED, NOT_STARTED
const StatusOrderValues = {
    [StudentAssignmentStatus.SUBMITTED]: 0,
    [StudentAssignmentStatus.IN_PROGRESS]: 1,
    [StudentAssignmentStatus.RETURNED]: 2,
    [StudentAssignmentStatus.NOT_STARTED]: 3,
};

const compareStudentDisplayName =  (a: StudentAssignment, b: StudentAssignment) => {
    return compareValues(a.student.displayName || '', b.student.displayName || '');
};

const OrderFieldToComparator: IComparatorMap<StudentAssignment, StudentAssignmentOrderField>
  = {
      studentDisplayName(a: StudentAssignment, b: StudentAssignment): number {
          return compareStudentDisplayName(a, b);
      },
      submissionDate(a: StudentAssignment, b: StudentAssignment): number {
          let value;
          if (!a.submissionDate && !b.submissionDate) {
              value  = 0;
          } else if (!a.submissionDate) {
              value = 1; // Undefined date should be sorted last in ascending order
          } else if (!b.submissionDate) {
              value = -1;
          } else {
              value = compareValues(a.submissionDate.getTime(), b.submissionDate.getTime());
          }
          if (value === 0) {
              // If equal submission date (probably both are undefined), sort by student display name
              return compareStudentDisplayName(a, b);
          }
          return value;
      },
      status(a: StudentAssignment, b: StudentAssignment): number {
          const value = compareValues(StatusOrderValues[a.status], StatusOrderValues[b.status]);
          if (value === 0) {
              // Within the same status, sort by student display name
              return compareStudentDisplayName(a, b);
          }
          return value;
      }
  };

export default class StudentAssignmentOrder extends createItemOrderFactory(
    OrderFieldToComparator
) implements SAM.StudentAssignmentOrder {
    static default = new StudentAssignmentOrder('ascending', 'studentDisplayName');
}
