import type { AssetLinks, RepositoryMetadata } from './RepositoryModel';
import type { IServiceLink, LinkRequirements } from './LinkUtils';
import { RelType } from './LinkUtils';
import type { IRemoteStudentAssignment } from './StudentAssignmentModel';
import type { Tutorial } from './TutorialModel';

export interface IAssignmentsIndexResponse {
    _links: IAssignmentsIndexLinks
}

export interface IAssignmentsIndexLinks {
    [RelType.ASSIGNMENTS_COLLECTION]: IServiceLink,
    [RelType.ASSIGNMENTS_CREATE]: IServiceLink,
    [RelType.ASSIGNMENTS_PRIMARY]: IServiceLink,
}

export const ASSIGNMENTS_INDEX_LINKS: LinkRequirements = {
    [RelType.ASSIGNMENTS_COLLECTION]: [ 'classroomId' ],
    [RelType.ASSIGNMENTS_CREATE]: [ 'classroomId' ],
    [RelType.ASSIGNMENTS_CREATE_V2]: [ 'classroomId', 'assign' ],
    [RelType.ASSIGNMENTS_PRIMARY]: [ 'assignmentId' ]
};

export interface IAssignmentActions {
    [RelType.ASSIGNMENTS_PRIMARY]: IServiceLink;
    [RelType.ASSIGNMENTS_CODE]: IServiceLink,
    [RelType.ASSIGNMENTS_ASSIGN]: IServiceLink;
    [RelType.DISCARD]: IServiceLink;
    [RelType.RESTORE]: IServiceLink;
    [RelType.ASSIGNMENTS_SUBMIT_FLOATING_FILE]?: IServiceLink;
}

export type AssignmentLinks = AssetLinks & IAssignmentActions;

export enum AssignmentStatus {
    DRAFT = 'DRAFT',
    ASSIGNED = 'ASSIGNED',
}

export interface AssignmentAdobeAssetMetadata {
    'repo:assetId': string;
}

/** Model representing an assignment from the service */
export interface IRemoteAssignment extends IRemoteAssignmentAppMetadata, Pick<RepositoryMetadata,
    'repo:assetId' | 'repo:createDate' | 'repo:state' | 'repo:name' | 'repo:path' | 'repo:createdBy' | 'repo:modifiedBy' | 'repo:repositoryId'
> {
    /** User information */
    user?: AssignmentMember;
    /** Student assignments */
    'children': IRemoteStudentAssignment[];
    /** Assignment links */
    _links?: AssignmentLinks;
    /** Classroom context */
    'classroom:context': AssignmentAssetsContext;
}

/** Model representing an assignment info stored as appMetadata */
export interface IRemoteAssignmentAppMetadata {
    /** Whether student can read each other's submission */
    'assignment:canClassroomReadSubmissions': boolean;
    /** Associated campaign ID */
    'assignment:campaignId'?: string;
    /** Associated classroom ID */
    'assignment:classroomId': string;
    /** Assignment creator */
    'assignment:createdBy': string;
    /** Instructions */
    'assignment:instructions': string;
    /** Due date */
    'assignment:dueDate'?: string;
    /** Status */
    'assignment:status': string;
    /** acceptable types of assignment task document: https://git.corp.adobe.com/Horizon/hz/blob/main/features/tasks/src/typings/TaskIDEnums.ts#L26 */
    'assignment:tasks'?: string[];
    /** Asset IDs of template files that students can use to start their assignment */
    'assignment:templateIds'?: string[];
    /** Asset ID of a guided activity as a starting point for the student's assignment */
    'assignment:externalTemplateIds'?: string[];
    /** A stringified list of @see {Tutorial} objects */
    'assignment:externalTutorials'?: string;
    /** Assignment code used for URLs/share with students */
    'assignment:code': string;
    /** Additional reference assets used to create the assignment */
    'assignment:referenceIds'?: string[];
}

export interface ExternalAsset {
    content: Blob | string;
    name: string;
    mediaType?: string;
}

export interface IAssignmentCreateData {
    canClassroomReadSubmissions?: boolean;
    campaignId?: string;
    classroomId: string;
    createdBy?: string;
    dueDate?: Date;
    externalTemplateIds?: string[],
    instructions?: string;
    name: string;
    status?: AssignmentStatus;
    tasks?: string[];
    templateIds?: string[];
    references?: (string | ExternalAsset)[];
    externalTutorials?: Tutorial[];
}

export interface IAssignmentCreateDataV2 extends Omit<IAssignmentCreateData, 'templateIds'> {
    templates?: {
        assetId: string,
        repositoryId: string,
        name: string,
    }[];
}

export interface IAssignmentUpdateData extends IAssignmentCreateData {}

export interface IAssignmentPatchData extends Partial<Pick<IAssignmentUpdateData,
    | 'canClassroomReadSubmissions'
    | 'instructions'
    | 'dueDate'
    | 'externalTemplateIds'
    | 'externalTutorials'
    | 'name'
    | 'tasks'
    | 'templateIds'
    | 'status'>> {
    referenceIds?: string[]
}

export interface IAssignmentRemotePatchData extends Partial<Pick<IRemoteAssignment,
    | 'assignment:canClassroomReadSubmissions'
    | 'assignment:instructions'
    | 'assignment:dueDate'
    | 'assignment:externalTemplateIds'
    | 'assignment:externalTutorials'
    | 'assignment:templateIds'
    | 'repo:name'
    | 'assignment:tasks'
    | 'assignment:status'
    | 'assignment:referenceIds'>> {}

/**
 * A mapping of fields from the local assignment model to the remote assignment model
 * This is the inverse of AssignmentUpdater.
 */
export const assignmentRemoteFieldMapping: Record<keyof IAssignmentPatchData, keyof IAssignmentRemotePatchData> = {
    canClassroomReadSubmissions: 'assignment:canClassroomReadSubmissions',
    instructions: 'assignment:instructions',
    dueDate: 'assignment:dueDate',
    externalTemplateIds: 'assignment:externalTemplateIds',
    templateIds: 'assignment:templateIds',
    name: 'repo:name',
    tasks: 'assignment:tasks',
    status: 'assignment:status',
    referenceIds: 'assignment:referenceIds',
    externalTutorials: 'assignment:externalTemplateIds'
};

export interface IAssignmentsAppMetadata {
    // not sure what would be the required/optional app metadata here, will update this later when we learn more
    'assignment:rendition': Partial<IRemoteAssignment>;
}

export type IAssignmentsOrderBy =
  | 'repo:name'
  | 'assignment:status'
  | 'assignment:dueDate';

export interface IAssignmentsPageSpec {
    start: number;
    limit: number;
    orderBy: string;
    count: number;
    total: number;
}

export interface IAssignmentsLinks {
    [RelType.ASSIGNMENTS_CREATE]: IServiceLink;
    [RelType.ASSIGNMENTS_COLLECTION]: IServiceLink;
}

export interface IAssignmentsResponse {
    children: IRemoteAssignment[];
    _page: IAssignmentsPageSpec;
    _links: IAssignmentsLinks;
}

export enum AssignmentSubmissionOwnershipEnums {
    ANY = 'ANY',
    NONE = 'NONE',
    SELF = 'SELF'
}

export type ClassroomAssetsContext = {
    'classroom:classroomContext': {
        'classroom:classroomAssetId': string;
    },
    // AssetId of a specific assignment folder (ie /content/assets/classrooms/{classOrgId}/assignments/{assignmentName})
    'classroom:assignmentContext': {
        'classroom:assignmentAssetId': string;
    },
    // AssetId of the top level assignments folder (ie /content/assets/classrooms/{classOrgId}/assignments)
    // There is one situation where we don't have this field -- when we're getting a student assignment that has status NOT_STARTED. Can rely on it in all other cases.
    'classroom:assignmentsContext'?: {
        'classroom:assignmentsAssetId'?: string;
    },
    'assignment:materialsContext': {
        'assignment:materialsAssetId': string;
    },
    'assignment:studentsContext': {
        'assignment:studentsAssetId': string;
    }
}

export type AssignmentAssetsContext = Required<ClassroomAssetsContext>

export interface AssignmentMember {
    userId: string;
}
