/**
 * Simplfies cases where a Promise needs to be resolved or rejected externally from the Promise itself.
 */
export class ManagedPromise<T> {
    promise: Promise<T>;
    resolve!: (result: T) => void;
    reject!: (error?: any) => void;

    constructor() {
        this.promise = new Promise((resolve, reject) => {
            this.resolve = resolve;
            this.reject = reject;
        });
    }
}
