import { vulcanLibrariesSAPCode, vulcanLibrariesTargetSpecifier, vulcanQueryRequestPayload } from '../config/constants';
import type { IUXPVulcan, IUXPVulcanMessage, UXPInstalledApps } from '../utils/Vulcan/IVulcan';
import type { VulcanCallback, VulcanMessageType, ConnectionInfo } from './Connector';
import Connector from './Connector';

const LAUNCH_APP_RESPONSE = 'launched';

class UXPConnector extends Connector<IUXPVulcan, IUXPVulcanMessage> {
    protected messageTypes: VulcanMessageType = {
        REQUEST: 'vulcan.SuiteMessage.cclibraries.api.QueryRequest',
        RESPONSE: 'vulcan.SuiteMessage.cclibraries.api.QueryResponse',
        INITIALIZE: null
    };

    private get _installedAppsFn(): () => Promise<UXPInstalledApps> {
        const { getInstalledApps, getInstalledAppsEx } = this.vulcanInterface.control;
        if (getInstalledAppsEx) {
            return getInstalledAppsEx.bind(this.vulcanInterface.control);
        }
        return getInstalledApps.bind(this.vulcanInterface.control);
    }

    private async _getCCLibrariesInstall() {
        return (await this._installedAppsFn()).find(
            app => app.name === vulcanLibrariesTargetSpecifier || app.sapCode === vulcanLibrariesSAPCode
        );
    }

    removeListener(callback: VulcanCallback, type?: string) {
        if (type === null) {
            return;
        }
        this.vulcanInterface.dispatcher.removeEventListener(this.messageTypes.RESPONSE, callback);
    }

    sendMessage(callback: VulcanCallback, type?: string) {
        if (type === null) {
            return;
        }
        this.vulcanInterface.dispatcher.addEventListener(this.messageTypes.RESPONSE, callback);
        this.vulcanInterface.dispatcher.broadcastMessage(
            // eslint-disable-next-line new-cap
            new this.vulcanInterface.message(this.messageTypes.REQUEST, vulcanQueryRequestPayload)
        );
    }

    async isAppRunning(): Promise<boolean> {
        return (await this._getCCLibrariesInstall())?.isRunning() as Promise<boolean>;
    }

    async launchApp(callback: VulcanCallback) {
        const ccLibrariesInstall = await this._getCCLibrariesInstall();
        if (ccLibrariesInstall) {
            await ccLibrariesInstall.launch();
            callback(LAUNCH_APP_RESPONSE);
        }
    }

    getPayload(message: IUXPVulcanMessage) {
        return message.payload;
    }
}

export default (
    vulcanInterface: IUXPVulcan,
    timeout = 8000
): ((abortSignal?: AbortSignal) => Promise<ConnectionInfo | void>) => {
    const connector = new UXPConnector(vulcanInterface, undefined, timeout);
    return (abortSignal?: AbortSignal) => connector.connect(abortSignal);
};
