/**
 * Operation
 * @packageDocumentation
 * @module Operation
 * @internal
 */

import type { Action } from '../models/Action';
// @ts-expect-error R-TODO
import type Library from '../models/Library';
import LibraryError from '../errors/LibraryError';
import Logger from '../utils/Logger';

export type ExecuteResult = { actions: Action[]; etag?: string; linkedActions?: Action[]; linkedEtag?: string };

export function validatesOperation<T>(
    target: Operation<T>,
    propertyKey: string,
    propertyDescriptor: PropertyDescriptor
) {
    const method = propertyDescriptor.value;

    propertyDescriptor.value = async function (this: Operation<T>, ...args: any[]) {
        if (this._actions.length === 0) {
            throw new LibraryError(
                'NOT_SUPPORTED',
                'Operation must have at least one action to be executed.',
                this._library.id
            );
        }

        Logger.log(`[OPERATION] Performing ${this._actions.length} actions.`);

        return method.apply(this, args);
    };
}

/**
 * An operation is an atomic API request. It contains some number of batchable actions.
 */
export default abstract class Operation<T> {
    /**
     * Is the action supported by this type of operation?
     * @param action
     */
    static supportsAction(action: Action) {
        return this.prototype.supportsAction(action);
    }

    protected _actions: Action[] = [];
    protected _library: Library;
    protected _driver: T;

    constructor(driver: T, library: Library) {
        this._driver = driver;
        this._library = library;
    }

    /**
     * Add an action to the operation, but only if it fits in the operation type.
     * @param action
     * @returns Did the operation accept the action?
     */
    addAction(action: Action): boolean {
        if (!this.supportsAction(action)) {
            return false;
        }

        this._actions.push(action);
        return true;
    }

    /**
     * Executes the operation. Should make a single request to an API.
     *
     * This method is also responsible for converting the action into its final form.
     * For example, when a library is created, we get the ID. We need to add the ID to
     * the action before applying it to the base state.
     */
    abstract execute(): Promise<ExecuteResult>;

    /**
     * Is the action supported by this type of operation?
     * @param action
     */
    abstract supportsAction(action: Action): boolean;

    get actions() {
        return this._actions;
    }
}
