export function mapResponseToLibraryData(libraryResponse: LibraryResponse, forceReadOnly = false): LibraryData {
    const isWritable = forceReadOnly ? false : libraryResponse.is_writable;

    const data: LibraryData = {
        id: libraryResponse.id,
        etag: libraryResponse.etag,
        name: libraryResponse.name,
        ownership: libraryResponse.ownership,
        default: libraryResponse.default,
        localizedNames: libraryResponse.localized_names,
        toolkitId: libraryResponse.toolkit_id,
        documentId: libraryResponse.document_id,
        documentType: libraryResponse.document_type,
        createdDate: libraryResponse.created_date,
        modifiedDate: libraryResponse.modified_date,
        groups: (libraryResponse.groups || []).map(mapResponseToGroupData),
        details: {
            elementCount: libraryResponse.details.num_elements,
            documentationElementCount: libraryResponse.details.num_documentation_elements,
            removedElementCount: libraryResponse.details.num_archived_elements
        },
        renditionGrid: libraryResponse.rendition_grid,
        collaboration: libraryResponse.collaboration,
        assetId: libraryResponse.asset_id,
        isWritable,
        isParentWritable: forceReadOnly ? false : libraryResponse.is_parent_writable,
        team: libraryResponse.team_id
            ? {
                id: libraryResponse.team_id
            }
            : undefined,
        roles: libraryResponse.roles,
        owner: libraryResponse.owner,
        ownerType: libraryResponse.owner_type,
        customData: libraryResponse.custom_data,
        isLibraryLoaded: true, // If the library data is coming from an API we know it is truly loaded
        storageUsed: libraryResponse.storage_used,
        publicLinkId: getPublicLinkId(libraryResponse.public_link),
        locallyManaged: libraryResponse.locally_managed,
        bookmark: libraryResponse.bookmark,
        // If `remove_type` is not in the response, then we are connected to an older version
        // of the process that did not support discard. We can assume the remove type is delete.
        removeType: libraryResponse.remove_type ?? (isWritable ? 'delete' : 'none'),
        deletable: isWritable
    };

    if (libraryResponse.elements) {
        data.elements = libraryResponse.elements.map(mapResponseToElementData);
    }

    return data;
}

export function mapLibraryDataToRequest(libraryData: Partial<LibraryData>): Partial<LibraryResponse> & { id: string } {
    return {
        id: libraryData.id as string,
        name: libraryData.name,
        ownership: libraryData.ownership,
        default: libraryData.default,
        localized_names: libraryData.localizedNames,
        toolkit_id: libraryData.toolkitId,
        document_id: libraryData.documentId,
        document_type: libraryData.documentType,
        groups: libraryData.groups?.map(mapGroupDataToRequest),
        collaboration: libraryData.collaboration,
        details: {
            num_elements: 0, // TODO
            num_documentation_elements: 0, // TODO
            num_archived_elements: 0 // TODO
        },
        // asset_id: '',
        // isWritable: true,
        // isParentWritable: true,
        team_id: libraryData.team?.id,
        roles: libraryData.roles,
        custom_data: libraryData.customData
    };
}

