export interface IClassroomMember {
    classroomId: string;
    computedKey: string;
    userId: string;
    firstName: string;
    lastName: string;
    email: string;
    displayName: string;
    role: ClassroomMemberRole;
    membershipStatus: ClassroomMemberStatus;
    inviteSource: ClassroomMemberInviteSource;
}

export interface IRemoteClassroomMembers {
    members: IClassroomMember[];
    classroomId: string;
}

export enum ClassroomMemberRole {
    STUDENT = 'student',
    TEACHER = 'teacher',
    NONE = 'none',
}

export enum ClassroomMemberStatus {
    ACTIVE = 'ACTIVE',
    DECLINED = 'DECLINED',
    INACTIVE = 'INACTIVE',
    INVITED = 'INVITED',
    IN_REVIEW = 'IN_REVIEW',
    NOT_A_MEMBER = 'NOT_A_MEMBER',
    OWNER = 'OWNER',
}

export enum ClassroomMemberInviteSource {
    CLASSLINK = 'CLASSLINK',
    CLEVER = 'CLEVER',
    EMAIL = 'EMAIL',
    GOOGLE_CLASSROOM = 'GOOGLE_CLASSROOM',
    NONE = 'NONE',
}
