import type { AdobeAsset, GenerationHistoryAssetFilter } from 'src';
import type { SAM } from '@ccx-public/component-types';
import type { IItemLoader, IItemLoaderOptions, ILoadedPage, ILoadNextPage } from '../core/ItemLoader';
import SAMError, { SAMErrorCode } from '../core/SAMError';
import type { ISAMCorePrivate } from '../indexPrivate';
import type GenerationHistoryInterface from '../interface/GenerationHistoryInterface';
import type { MelvilleLink } from '../interface/LibraryModel';

import type {
    MelvilleGenerationHistoryAssetsParams,
    MelvilleGenerationHistoryAssetsResponse
} from '../interface/GenerationHistoryAssetModel';
import {
    FIREFLY_GENERATIONS_DIRECTORY,
    HISTORY_ASSET_TYPE_TO_MEDIA_TYPE
} from '../interface/GenerationHistoryAssetModel';

import { GenerationHistoryAssetUpdater } from './GenerationHistoryAsset';
import FavoriteAdobeAssetOrder from '../assets/FavoriteAdobeAssetOrder';
import AdobeAssetFilter from '../assets/AdobeAssetFilter';
import { AdobeAssetUpdater } from '../assets/AdobeAsset';
import type { GenerationHistoryAssetConfig } from '../generation-history/GenerationHistoryAssetSource';
import { getMostRecentValidMutation } from '../utils/loaderUtils';

const $GH_DIR_REF = Symbol('GenerationHistoryDirectoryRef');
const $GH_FAVORITES_LIST_REF = Symbol('GenerationHistoryFavoritesListRef');

export { $GH_DIR_REF };

export default class GenerationHistoryAssetLoader implements IItemLoader<GenerationHistoryAssetConfig> {
    constructor(
        private _core: ISAMCorePrivate,
        private _generationHistoryInterface: GenerationHistoryInterface
    ) {}

    async loadPage(options: IItemLoaderOptions<GenerationHistoryAssetConfig>) {
        return await this._loadPage(options);
    }

    /**
   * Loads assets from the supergraph. This is used to load assets from the supergraph which utilizes a directory listing and is more performant than Melville which relies on USS.
   * However we will still need to go Melville to get a listing of assets by generationGroupId.
   * @param options - The options for the loader.
   * @param pageLink - The page link to load.
   * @returns The assets.
   */
    private async _loadAssetsFromSupergraph(
        options: IItemLoaderOptions<GenerationHistoryAssetConfig>,
        after?: string
    ): Promise<ILoadedPage<GenerationHistoryAssetConfig>> {
        const gqlManager = await this._core._getGQLManager();

        const { loadOptions: { limit: first = 50 } = {}, order, filter } = options;

        let historyAssetTypes: SAM.GenerationHistoryAssetType[] = [];
        if (filter && filter.historyAssetTypes) {
            historyAssetTypes = filter.historyAssetTypes;
        }
        //@ts-expect-error
        options.filter[$GH_FAVORITES_LIST_REF] = this._core.hostAssetContext.favoriteAssetsSource.getList(FavoriteAdobeAssetOrder.default, new AdobeAssetFilter({ mediaTypes: historyAssetTypes.map(type => HISTORY_ASSET_TYPE_TO_MEDIA_TYPE[type]) }), { loadAllPages: true });

        // @ts-expect-error
        await this.getDefaultGHAFolder().then(folder => folder && (options.filter[$GH_DIR_REF] = folder));

        const result = await gqlManager.getGenerationHistoryAssets({
            first,
            after,
            orderBy: [
                {
                    direction: order.direction === 'ascending' ? 'ASCENDING' : 'DESCENDING',
                    field: 'CREATE_DATE'
                }
            ],
            filter: {
                dc_format: historyAssetTypes.map(type => HISTORY_ASSET_TYPE_TO_MEDIA_TYPE[type]),
            }
        }, options.resource, (incrementalData) => {
            this._processIncrementalData(incrementalData);
        });

        const latency = this._core._environment.getValue('GQL_LIST_UPDATE_LATENCY');
        const mostRecentValidMutation = getMostRecentValidMutation(options.resource, latency);

        const session = this._core
            ._getAssetPool()
            .createLoaderUpdateSession<AdobeAsset>(mostRecentValidMutation);

        const items = AdobeAssetUpdater.updateRemoteItems(
            session,
            result.items
        );

        session.commit();

        let loadNextPage: ILoadNextPage<GenerationHistoryAssetConfig> | undefined;

        if (result.pageInfo.hasNextPage) {
            loadNextPage = (options: IItemLoaderOptions<GenerationHistoryAssetConfig>) =>
                this._loadAssetsFromSupergraph(options, result.pageInfo.endCursor ?? undefined);
        }

        return {
            items,
            loadNextPage
        };
    }

    private async _loadPage(
        options: IItemLoaderOptions<GenerationHistoryAssetConfig>,
        pageLink?: MelvilleLink
    ): Promise<ILoadedPage<GenerationHistoryAssetConfig>> {
        let result: MelvilleGenerationHistoryAssetsResponse;

        if (!(options.filter as GenerationHistoryAssetFilter).generationGroupId && !(options.filter as GenerationHistoryAssetFilter).module) {
            return await this._loadAssetsFromSupergraph(options);
        }

        if (pageLink) {
            // We are loading the next page with the link provided.
            result = await this._generationHistoryInterface.getGenerationHistoryAssetsUsingPageLink(pageLink, options.resource);
        } else {
            const { order } = options;
            const { limit } = options.loadOptions ?? {};

            const { generationGroupId, historyAssetTypes, module } = options.filter as GenerationHistoryAssetFilter ?? {};
            const queryParams: MelvilleGenerationHistoryAssetsParams = {};
            queryParams.orderBy = order.direction === 'ascending' ? 'created_date' : '-created_date';
            generationGroupId && (queryParams.generationGroupId = generationGroupId);
            module && (queryParams.module = module);
            historyAssetTypes?.length && (queryParams.generationType = historyAssetTypes.join(','));

            if (limit) {
                queryParams.limit = limit;
                if (!queryParams.start) {
                    queryParams.start = 0;
                }
            }

            const assetsPromise = this._generationHistoryInterface.getGenerationHistoryAssets(queryParams, options.resource);

            // Keep reference to a fully loaded favorites list (filtered on the GHA mimetype)
            // Attaching the list to an instance of the filter allows those assets to be GC'd when GHAs from this loader
            // are no longer being referenced.
            // Fetching favorites allows us to instantiate assets in the item pool which include whether or not that
            // asset is a favorite (we need this as favorites data is not returned from Melville)
            // TODO: Once we can get the data from Melville, remove this list. Fetching two lists here
            // could cause bad performance. See https://jira.corp.adobe.com/browse/GLOW-890
            //@ts-expect-error
            options.filter[$GH_FAVORITES_LIST_REF] = this._core.hostAssetContext.favoriteAssetsSource.getList(FavoriteAdobeAssetOrder.default, new AdobeAssetFilter({ mediaTypes: historyAssetTypes.map(type => HISTORY_ASSET_TYPE_TO_MEDIA_TYPE[type]) }), { loadAllPages: true });

            // wait for the favorite assset query to resolve as well as generation history assets before returning
            // results in GHA list
            const [ assetsResponse ] = await Promise.all([
                assetsPromise,

                // Note: most GHAs will likely exist in the ghaFolder. Keeping a ref to it let SAMs optimize ONS monitoring to
                // just the folder for most GHAs, and enables ONS notifications for new GHAs generated. Attaching to the
                // explicit filter ensures the ghaFolder gets GC'd with the list, then SAM can stop monitoring it via ONS.
                // @ts-expect-error
                this.getDefaultGHAFolder().then(folder => options.filter[$GH_DIR_REF] = folder)
            ]);

            result = assetsResponse;
        }

        const latency = this._core._environment.getValue('USS_LIST_UPDATE_LATENCY');
        const mostRecentValidMutation = getMostRecentValidMutation(options.resource, latency);
        const session = this._core._getAssetPool().createLoaderUpdateSession<AdobeAsset>(mostRecentValidMutation);
        const items = GenerationHistoryAssetUpdater.updateRemoteItems(session, result.listings);
        session.commit();

        let loadNextPage: ILoadNextPage<GenerationHistoryAssetConfig> | undefined;
        const nextPageLink = result._links?.next;

        if (nextPageLink) {
            loadNextPage = (options: IItemLoaderOptions<GenerationHistoryAssetConfig>) =>
                this._loadPage(options, nextPageLink);
        }

        return {
            items,
            total: result.total_count,
            loadNextPage,
            mostRecentValidMutation
        };
    }

    async getDefaultGHAFolder() {
        const generationHistoryContext = await this._core.getGenerationHistoryContext();
        const { _fireflyGenerationsDirectoryID } = generationHistoryContext;

        // attempt to resolve FIREFLY_GENERATIONS_DIRECTORY, create if needed
        const generationsDirectory = _fireflyGenerationsDirectoryID
            ? await this._core.hostAssetContext.getAssetWithCloudID(_fireflyGenerationsDirectoryID)
            : await this._core.hostAssetContext.getAssetWithRepoPath(`/${FIREFLY_GENERATIONS_DIRECTORY}`)
                .then(directory => directory)
                .catch(async (err: any) => {
                    if (err.code === SAMErrorCode.NOT_FOUND) {
                        // If the firefly-generations directory is not found, return an empty listing
                        return;
                    }

                    throw SAMError.create(
                        SAMErrorCode.UNKNOWN,
                        'SAM was unable to resolve or create the firefly-generations directory'
                    );
                });

        generationHistoryContext._fireflyGenerationsDirectoryID = generationsDirectory?.cloudID;

        return generationsDirectory;
    }

    /**
     * Processes incremental data from GraphQL deferred fields, specifically manifest data.
     * This method is called when deferred manifest data arrives after the initial response.
     * @param incrementalData - The incremental data containing manifest information
     */
    private _processIncrementalData(incrementalData: any): void {
        const pool = this._core._getAssetPool();

        // Extract assets that have manifest data from the incremental response
        const assetsWithManifest = incrementalData.homeFolder.fireflyGenerationsDirectory?.generationAssetsConnection?.assets?.filter((asset: any) =>
            asset.node?.manifest && pool.getLocalItemById(asset.node.repo_assetId)
        ) || [];

        if (assetsWithManifest.length === 0) {
            return;
        }

        // Update each asset's manifest resource with the new data
        assetsWithManifest.forEach((asset: any) => {
            const localAsset = pool.getLocalItemById(asset.node.repo_assetId);
            if (localAsset && asset.node.manifest) {
                // Set the manifest data on the asset's manifest resource
                // This will mark the manifest as loaded with isLoaded: true
                localAsset.manifest._setData(asset.node.manifest);
            }
        });
    }
}
