/**
 * Dummy implementation of the WeakRef interface to be used
 * in browsers that do not support WeakRefs natively.
 * Note that the associated objects will not be reclaimed by the
 * garbage collector. We don't expect this to be an actual issue
 * in practice for SAM though.
 */
export default class WeakRefPolyfill<T extends object> implements WeakRef<T> {
    constructor(private _ref: T) {
    }

    /**
     * Needed in order to fully implement the WeakRef interface.
     * The `Symbol.toStringTag` symbol is a property that
     * is used by the default implementation of the toString method.
     */
    get [Symbol.toStringTag](): 'WeakRef' {
        return 'WeakRef';
    }

    /**
     * Returns the WeakRef target object.
     * Note that this implementation emulates the API, but cannot
     * actually keep a weak reference.
     *
     * Based on MDN data, most modern browsers support WeakRef.
     */
    deref(): T | undefined {
        return this._ref;
    }
}
