import type { ValidationMap } from '../utils/classroomUtils';
import { getMemberComputedKey, validateTypes } from '../utils/classroomUtils';
import type { IClassroomMember, IRemoteClassroomMembers } from './ClassroomMemberModel';
import { ClassroomMemberRole } from './ClassroomMemberModel';
import type { IClassroomCreateData, IClassroomUpdateData, IRemoteBlockOrRemoveResponse, IRemoteClassroom, IRemoteMembership, ICoTeacherEligibilityEntry, ICheckCoTeacherEligibilityOptions, GetClassroomsOptions } from './ClassroomModel';
import { ClassroomProfiles, SubjectTypes } from './ClassroomModel';
import InterfaceBase from './InterfaceBase';
import type { HeaderMap } from './LinkUtils';
import { JSON_MIME_TYPE } from './LinkUtils';

const API_ROOT = '/api/v1';
const headers: HeaderMap = { 'Content-Type': JSON_MIME_TYPE };

interface IRefreshCodeResponse {
    classroomId: string;
    classcode: string;
}

export function validateClassroomData(data: IClassroomCreateData): string[] {
    const errors: string[] = [];

    // Handle basic validation
    const classroomDataToValidate: ValidationMap<IClassroomCreateData>[] = [
        { key: 'subject', type: 'enum', isRequired: false, ref: SubjectTypes },
        { key: 'grades', type: 'string[]', isRequired: false },
        { key: 'period', type: 'string', isRequired: false },
        { key: 'teachers', type: 'string[]', isRequired: false },
    ];

    errors.push(...validateTypes(classroomDataToValidate, data));

    // Handle validation of virtual and non-virtual classrooms
    const hasName = typeof data.name === 'string' && data.name !== null;
    const hasId = typeof data.id === 'string' && data.id !== null;

    // One of these must be defined
    // Both _can_ be defined, but id will take precedence and name will be ignored
    if (!hasName && !hasId) {
        errors.push('name or id is missing');
    }

    return errors;
}

export default class ClassroomsInterface extends InterfaceBase {
    /** Overrides the default behavior for a 202 response */
    protected async _monitorResponse(response: Response): Promise<Response> {
        return response;
    }

    private _getUrl(endpoint: string): string {
        return `https://${this._core._environment.endpoints.CLASSROOMS_HOST}${endpoint}`;
    }

    /**
     * @description Creates a new Classroom
     *
     * @param data needed to create a Classroom like name and subject
     * @returns promise resolving to the newly created Classroom
    */
    async createClassroom(data: IClassroomCreateData): Promise<IRemoteClassroom> {
        const response = await this._doPost(this._getUrl(`${API_ROOT}/classrooms`), headers, JSON.stringify({
            className: data.name,
            subject: data.subject,
            grades: data.grades,
            period: data.period,
            teachers: data.teachers?.map(email => encodeURIComponent(email)) || []
        }), [ 201 ]);
        const jsonResponse = await response.json();

        return jsonResponse;
    }

    /**
     * Creates a new Classroom from a virtual class
     * @param id that maps to the virtual classroom being migrated to a real class
     * @returns promise resolving to the newly created Classroom
    */
    async createClassroomFromVirtual(virtualClassroomId: string): Promise<IRemoteClassroom> {
        const response = await this._doPost(this._getUrl(`${API_ROOT}/classrooms/virtual/${virtualClassroomId}/create`), { 'Content-Type': JSON_MIME_TYPE }, undefined, [ 201 ]);
        const jsonResponse = await response.json();

        return jsonResponse;
    }

    /**
     * Creates a new Classroom with updated metadata from a virtual class
     * @param id that maps to the virtual classroom being migrated to a real class
     * @param data that the real classroom will be created with
     * @returns promise resolving to the newly created Classroom
    */
    async updateClassroomFromVirtual(virtualClassroomId: string, data: IClassroomCreateData): Promise<IRemoteClassroom> {
        const response = await this._doPost(this._getUrl(`${API_ROOT}/classrooms/virtual/${virtualClassroomId}/update`), { 'Content-Type': JSON_MIME_TYPE }, JSON.stringify({
            className: data.name,
            subject: data.subject,
            grades: data.grades,
            period: data.period,
            teachers: data.teachers?.map(email => encodeURIComponent(email)) || []
        }), [ 201 ]);
        const jsonResponse = await response.json();

        return jsonResponse;
    }

    /**
     * @description Deletes a single classroom
     *
     * @param id Either the classId or the classCode.  The endpoint queries both.
    */
    async deleteClassroom(id: string): Promise<void> {
        await this._doDelete(this._getUrl(`${API_ROOT}/classrooms/${id}`), headers, [ 202 ]);
    }

    /**
     * @description Deletes a single virtual classroom
     *
     * @param id the classId
    */
    async deleteVirtualClassroom(id: string): Promise<void> {
        await this._doPost(this._getUrl(`${API_ROOT}/classrooms/virtual/${id}/delete`), headers, undefined, [ 202 ]);
    }

    /**
     * @description Gets a single classroom by class ID
     *
     * @param id Either the classId or the classCode.  The endpoint queries both.
     * @returns A promise that resolves to a classroom
     */
    async getClassroom(id: string): Promise<IRemoteClassroom> {
        const response = this._getResponse(this._getUrl(`${API_ROOT}/classrooms/${id}`));
        return response.then((classroom: any) => {
            // Handle the null value of importedFrom in ACPCEDU-1892
            classroom.importedFrom ??= {};
            return classroom;
        });
    }

    /**
     * @description Gets a list of all available classrooms
     *
     * @param options.profiles Optional parameter to get classrooms by profile
     * @param options.lastAccessed Optional parameter to include lastAccessed field on classrooms
     * @param options.hasTeachers Optional parameter to include teachers in the classrooms
     * @returns A promise that resolves to a list of classrooms
     */
    async getClassrooms(options: GetClassroomsOptions = {}): Promise<IRemoteClassroom[]> {
        const { hasTeachers, hasLastAccessed, profiles } = options;
        let url = this._getUrl(`${API_ROOT}/classrooms`);

        const fetchFields = [];
        if (hasTeachers) {
            fetchFields.push('teachers');
        }
        if (hasLastAccessed) {
            fetchFields.push('lastAccessDate');
        }
        if (fetchFields.length > 0) {
            url += `?fetchFields=${fetchFields.join(',')}`;
        }

        if (profiles) {
            const value = profiles === ClassroomProfiles.ALL ? ClassroomProfiles.ALL : encodeURIComponent(profiles);
            if (fetchFields.length === 0) {
                url += `?profiles=${value}`;
            } else {
                url += `&profiles=${value}`;
            }
        }

        const response = this._getResponse(url);
        // Handle the null value of importedFrom in ACPCEDU-1892
        return response.then((classrooms) => {
            return (classrooms as any[]).map((classroom) => {
                classroom.importedFrom ??= {};
                return classroom;
            });
        });
    }

    /**
     * @description Refreshes the classroom code for a given classroom
     *
     * @param id The classroom ID associated with a single classroom
     * @returns A promise that resolves to a classroom
     */
    async refreshClassroomCode(id: string): Promise<IRefreshCodeResponse> {
        return this._doPut(this._getUrl(`${API_ROOT}/classrooms/${id}/code/refresh`), undefined, undefined, [ 200 ]).then((response) => response.json());
    }

    /**
     * Updates a classroom with new data
     * @param id The classroom ID
     * @param data The new data that the classroom will be updated with
     * @returns A promise that resolves to the classroom with updated fields
     */
    async updateClassroom(id: string, data: IClassroomUpdateData): Promise<Partial<IRemoteClassroom>> {
        const response = await this._doPatch(this._getUrl(`${API_ROOT}/classrooms/${id}`), { 'Content-Type': JSON_MIME_TYPE }, JSON.stringify({
            className: data.name,
            subject: data.subject,
            grades: data.grades,
            period: data.period,
            teachers: data.teachers?.map(email => encodeURIComponent(email)) || [],
        }));
        return response.json();
    }

    /**
     * Gets the teachers of a classroom
     * @param id The classroom ID
     * @returns Teachers of a given classroom
     */
    async getClassroomTeachers(id: string): Promise<IClassroomMember[]> {
        return this.getClassroomMembers(id, ClassroomMemberRole.TEACHER);
    }

    /**
     * Gets the students of a classroom
     * @param id The classroom ID
     * @returns Students of a given classroom, wrapped in a classroom object for the list loader
     */
    async getClassroomStudents(id: string): Promise<IClassroomMember[]> {
        return await this.getClassroomMembers(id, ClassroomMemberRole.STUDENT);
    }

    /**
     * Gets the members of a classroom
     * @param id The classroom ID
     * @param filter The filter to apply to the members, either 'students' or 'teachers'. If not provided, all members are returned.
     * @returns Members of a given classroom
     */
    async getClassroomMembers(id: string, filter: ClassroomMemberRole): Promise<IClassroomMember[]> {
        const urlFilter = filter === ClassroomMemberRole.NONE ?  '' : `/${filter}s`;
        const url = `${API_ROOT}/classrooms/${id}/members${urlFilter}`;
        const classroomResponse: IRemoteClassroomMembers = await this._getResponse(this._getUrl(url));

        // Response doesn't include classroomId on each member, so need to add it here
        classroomResponse.members.forEach((member) => {
            member.classroomId = id;
            member.computedKey = getMemberComputedKey(id, member.userId);
        });

        return classroomResponse.members;
    }

    /**
     * Gets the membership status of a user in a classroom
     * @param id The classroom ID
     *
     * @returns Membership status of the user in the classroom
     */
    async getMembership(id: string): Promise<IRemoteMembership> {
        return this._getResponse(this._getUrl(`${API_ROOT}/classrooms/${id}/members/status`));
    }

    /**
     * Blocks a student from a classroom
     *
     * @param classroomId Class ID of the classroom to block the student from
     * @param studentId Student ID to block
     *
     * @returns A promise that resolves to the response from the server
     */
    async blockStudent(classroomId: string, studentId: string): Promise<IRemoteBlockOrRemoveResponse> {
        const response = await this._doPost(this._getUrl(`${API_ROOT}/classrooms/${classroomId}/members/students/block`), headers, JSON.stringify({
            studentId
        }), [ 200 ]);
        return await response.json();
    }

    /**
     * Unblocks a student from a classroom
     *
     * @param classroomId Class ID of the classroom to unblock the student from
     * @param studentId Student ID to unblock
     *
     * @returns A promise that resolves to the response from the server
     */
    async unblockStudent(classroomId: string, studentId: string): Promise<IRemoteBlockOrRemoveResponse> {
        const response = await this._doPost(this._getUrl(`${API_ROOT}/classrooms/${classroomId}/members/students/unblock`), headers, JSON.stringify({
            studentId
        }), [ 200 ]);
        return await response.json();
    }

    /**
     * Removes a student from a classroom
     *
     * @param classroomId Class ID of the classroom to remove the student from
     * @param studentId Student ID to remove
     *
     * @returns A promise that resolves to the response from the server
     */
    async removeStudent(classroomId: string, studentId: string): Promise<IRemoteBlockOrRemoveResponse> {
        const response = await this._doDelete(this._getUrl(`${API_ROOT}/classrooms/${classroomId}/members/students?studentId=${studentId}`), headers, [ 202 ]);
        return await response.json();
    }

    /**
     * Removes a teacher from a classroom
     *
     * @param classroomId Class ID of the classroom to remove the teacher from
     * @param userId Teacher's user ID to remove
     *
     * @returns A promise that resolves to the response from the server
     */
    async removeTeacher(classroomId: string, userId: string): Promise<IRemoteBlockOrRemoveResponse> {
        const response = await this._doDelete(this._getUrl(`${API_ROOT}/classrooms/${classroomId}/members/teachers?userId=${userId}`), headers, [ 202 ]);
        return await response.json();
    }

    /**
     * Checks eligibility of users to be added as co-teachers to a classroom
     *
     * @param options The options for checking co-teacher eligibility
     * @returns A promise that resolves to the eligibility response from the server
     */
    async checkCoTeacherEligibility(options: ICheckCoTeacherEligibilityOptions): Promise<Array<ICoTeacherEligibilityEntry>> {
        const response = await this._doPost(
            this._getUrl(`${API_ROOT}/classrooms/users/eligibility`),
            headers,
            JSON.stringify({
                classroomId: options.classroomId,
                role: 'teacher',
                emails: options.emails,
            }),
            [ 200 ]
        );
        return await response.json();
    }
}
