import RestrictedEventEmitter from '../models/utils/RestrictedEventEmitter';
import observable from './observable';

/**
 * Utility for creating limited map objects with observable getters
 * and that emit change events when they're modified.
 */
export default class ObservableMap extends RestrictedEventEmitter {
    private _map = new Map();

    set(key: any, value: any) {
        this._map.set(key, value);
        this.emit('change');
    }

    delete(key: any) {
        this._map.delete(key);
        this.emit('change');
    }

    clear() {
        this._map.clear();
        this.emit('change');
    }

    @observable('change')
    entries() {
        return this._map.entries();
    }

    @observable('change')
    get(key: any) {
        return this._map.get(key);
    }
}
