import type { ISAMCorePrivate, ISAMObject } from '../indexPrivate';
import ItemPool from '../core/ItemPool';
import CommentInterface from '../interface/CommentInterface';
import type { IEventMap } from '../core/TypedEventEmitter';
import TypedEventEmitter from '../core/TypedEventEmitter';
import type Comment from '../comments/Comment';
import { CommentUpdater } from '../comments/Comment';
import type {
    CommentData,
    ICommentGetCommentData,
} from '../interface/CommentModel';
import type { CommentConfig, CommentSource } from '../comments/CommentSource';
import CommentLoader from '../comments/CommentLoader';
import ItemSource from '../core/ItemSource';
import type { IItemList } from '../core/ItemList';
import CommentOrder from './CommentOrder';
import { waitForListLoad } from '../utils/waitForListLoad';
import CommentsResourceChangeEvent, { COMMENTS_CHANGED, CommentsChangedEventInstance } from './CommentsResourceChangeEvent';
import type { ONSChangedAssetInfo } from '../sync-services/ONSEvent';
import { observable, synchronized } from '@sam-js-src/core/decorators';
import { LIST_CHANGED } from '../core/ItemList';

export interface CommentsResourceEvents extends IEventMap {
    [COMMENTS_CHANGED]: CommentsResourceChangeEvent;
}

export default class CommentsResource extends TypedEventEmitter<CommentsResourceEvents> implements ISAMObject {

    /**
     * @package -- for SAM.js internal use only
     */
    readonly _commentInterface = new CommentInterface(this._core, this._assetId);

    /**
     * @package -- for SAM.js internal use only
     */
    readonly _commentPool: ItemPool<Comment> = new ItemPool<Comment>(this._core, 'comment');

    private _loader =  new CommentLoader(this);

    private _source: CommentSource =  new ItemSource(this._commentPool, [ this._loader ]);

    private _list?: IItemList<CommentConfig>;

    private _stopTimeout?: ReturnType<typeof setTimeout>;

    private _unreadCount: number | undefined;

    constructor(readonly _core: ISAMCorePrivate, readonly _assetId: string) {
        super();
    }

    /**
     * @description Get a list of the comments associated with an asset
     * from the Red Hawk Commenting Service.
     * @param data The information necessary for calling the API.
     * @returns A promise that resolves to the server's response,
     * an Array of CommentCore's listing the asset's comments.
     */
    async createComment(data: CommentData): Promise<Comment> {

        // Update the remote object with our proposed edit
        const response = await this._commentInterface.createComment(data);

        // The server has successfully updated the remote object,
        // so update our local object to match the final state.
        const session = this._commentPool.createUpdateSession<Comment>();
        const comment = CommentUpdater.updateRemoteItem(session, response);
        session.commit();

        comment['_commentsResource'] = this;

        return comment;
    }

    /**
     * @experimental API is not ready and mock data is being used
     *
     * @param data creation data (e.g. title, instructions, etc)
     *
     * @returns a promise that resolves to the assignment recently and successfully created
     */
    async getComment(data: ICommentGetCommentData): Promise<Comment> {
        let comment = this._commentPool.getLocalItemById(data.annotationId);

        if (!comment) {
            // fetch remote asset with a server call
            const response = await this._commentInterface.getComment(data);
            const session = this._commentPool.createUpdateSession<Comment>();
            comment = CommentUpdater.updateRemoteItem(session, response);
            session.commit();

            // @ts-expect-error : bit of a hack
            comment._commentsResource = this;
        }

        return comment;
    }

    getCommentList(): IItemList<CommentConfig> {
        if (!this._list) {
            this._list = this._source.getList(CommentOrder.default, undefined, { refreshTimeout: -1 });
            this._list.on(LIST_CHANGED, () => {
                this._updateUnreadCount();
            });
        }

        return this._list;
    }

    @synchronized
    private _updateUnreadCount() {
        const count = this._list!.items.filter((item) => !item.readStatus).length;
        let needsEvent;
        if (count !== this._unreadCount) {
            needsEvent = true;
        }
        this._unreadCount = count;
        if (needsEvent) {
            this.emit(COMMENTS_CHANGED);
        }
    }

    /**
    *
    * @note The list of all comments must be loaded completely before calling this method.
    *
    * @observable
    * @description Get the number of unread comments.
    * @returns The number of unread comments.
    */
    @observable(CommentsChangedEventInstance)
    get unreadCount(): number {
        // If the list is not loaded, or the unread count is not set, load it lazily
        // in the background. Eventually the call to UpdateMetadata will dispatch
        // an event that will notify clients subscribed to this method.
        if (!this._list || this._unreadCount === undefined) {
            this.getCommentList();
        }

        return this._unreadCount || 0;
    }

    /**
     * @description Get the number of unread comments asynchronously without
     * using observable.
     *
     * @param forceLoad If true, the list will be loaded completely before returning the number of unread comments.
     * @returns The number of unread comments.
     */
    async getUnreadCount(forceRefresh: boolean = false): Promise<number> {
        if (this._list && this._unreadCount !== undefined && !forceRefresh) {
            return this._unreadCount;
        }

        if (!this._list || this._unreadCount === undefined) {
            const list = this.getCommentList();
            await waitForListLoad(list);
            return this._unreadCount!;
        }

        if (forceRefresh) {
            // We may want to expose this method in the public interfaces in the future.
            // or an easy way internally to access the loaders/loader
            // @ts-expect-error : _loadAsync is not part of the public interfaces
            await this._list._loadAsync({
                clearEtag: true
            });
        }

        return this._unreadCount || 0;
    }

    private async _poll() {
        const list = this.getCommentList();

        // let the loader re-load the list of comments
        list.setNeedsRefresh();
        list.refresh();

        this._stopTimeout = setTimeout(() => this._poll(), this._loader.retryAfter);
    }

    startShortPoll() {
        if (!this._stopTimeout) {
            this._poll();
        }
    }

    stopShortPoll(): void {
        if (this._stopTimeout) {
            clearTimeout(this._stopTimeout);
            this._stopTimeout = undefined;
        }
    }

    get isShortPollActive(): boolean {
        return (this._stopTimeout !== undefined);
    }

    /**
     * @package -- for SAM.js internal use only
     */
    public _onONSNotification(assetInfo: ONSChangedAssetInfo) {
        this.emit(COMMENTS_CHANGED, new CommentsResourceChangeEvent(assetInfo.annotationIds || []));
        this._list?.setNeedsRefresh();
        this._list?.refresh();
    }
}
