import type { RepresentationData } from '../../models/data/RepresentationData';
import { isPlaceholder, extractPlaceholder } from '../../models/utils';

type Method = 'PUT' | 'POST' | 'DELETE';

// valid Process sub-routes of `.../libraries/{libraryId}`
export type ProcessLibrariesRoute = `${
    | 'elements'
    | 'removed_elements'
    | 'groups'
    | 'documentation_elements'
    | 'temp_dir'
    | 'export'
    | ''}${string}`;

export type ProcessRESTOperation<T = any> = {
    body?: T;
    method: Method;
    path: ProcessLibrariesRoute;
    query_params?: Record<string, string>;
};

// valid Melville sub-routes of `api/v1/libraries/{libraryId}`
export type MelvilleV1LibrariesRoute = `${'elements' | 'bookmarks' | 'archive' | 'metadata' | 'groups'}${string}`;

export type MelvilleRESTOperation<T = any> = {
    body?: T;
    method: Method;
    path: MelvilleV1LibrariesRoute;
    query_params?: Record<string, string>;
};

type RESTOperation = MelvilleRESTOperation | ProcessRESTOperation;

export function tokenizePlaceholders(requests: RESTOperation[]): RESTOperation[] {
    const tokenMap: { [s: string]: string } = {};

    for (let i = 0; i < requests.length; i += 1) {
        const request = requests[i];
        const id = request.body?.id;

        if (request.method === 'POST' && isPlaceholder(id)) {
            tokenMap[id] = `$${i}.id`;
            delete request.body.id;
        }

        // For PUT and DELETE check the path
        if ([ 'PUT', 'DELETE' ].includes(request.method)) {
            const placeholder = extractPlaceholder(request.path);

            if (placeholder) {
                if (!tokenMap[placeholder]) {
                    throw new Error(`Unmapped placeholder ID: ${placeholder}`);
                }

                request.path = request.path.replace(placeholder, tokenMap[placeholder]);
            }
        }

        // For PUT AND POST check the content
        if ([ 'PUT', 'POST' ].includes(request.method)) {
            if (request.path.startsWith('elements') && request.body.representations) {
                // Make sure representations in the outgoing requests have no placeholder ID values
                // Note: this only handles top-level representations. Child representations will be dealt with in this ticket: https://jira.corp.adobe.com/browse/CCXC-18482
                removeRepresentationPlaceholderIds(request.body.representations);
            }

            if (request.path.startsWith('elements') && request.body.groups) {
                for (const group of request.body.groups) {
                    if (!isPlaceholder(group.id)) {
                        continue;
                    }

                    if (!tokenMap[group.id]) {
                        throw new Error(`Unmapped placeholder ID: ${group.id}`);
                    }

                    group.id = tokenMap[group.id];
                }
            }

            if (request.path.startsWith('groups') && request.body.parent_id && isPlaceholder(request.body.parent_id)) {
                if (!tokenMap[request.body.parent_id]) {
                    throw new Error(`Unmapped placeholder ID: ${request.body.parent_id}`);
                }

                request.body.parent_id = tokenMap[request.body.parent_id];
            }
        }
    }

    return requests;
}

/**
 * Return an object equivalent to the given one but with any undefined values removed.
 * Exceptions can be made for certain keys, passed as second argument
 */
export function omitUndefined<T extends { [key: string]: any }>(object: T, keys?: string[]) {
    const result = {} as T;
    for (const [ key, val ] of Object.entries(object)) {
        if (val !== undefined || keys?.includes(key)) {
            result[key as T['key']] = val;
        }
    }
    return result;
}

/**
 * Removes any placeholder IDs from top-level representations
 * This utility method is used to make sure that all outgoing requests have no placeholder IDs in them
 * Note: This needs to be modified to account for nested child representations (see https://jira.corp.adobe.com/browse/CCXC-18482)
 *
 * @param {RepresentationData[]} representations An array of representations associated with an outgoing element request
 * @returns {RepresentationData[]}
 */
export function removeRepresentationPlaceholderIds(representations: RepresentationData[]) {
    for (const representation of representations) {
        if (isPlaceholder(representation.id)) {
            // eslint-disable-next-line @typescript-eslint/ban-ts-comment
            // @ts-expect-error
            representation.id = undefined;
        }
    }

    return representations;
}
