// https://identity.corp.adobe.com/abs/docs/#_resolveurn
export interface IResolveAddressBookGroupResponse {
    url: string;
}

export interface IABSPageLinks {
    next: { href: string };
}

// https://identity.corp.adobe.com/abs/docs/#_contactcoreresource
export interface IAddressBookContact {
    /** unique identifier for this contact */
    ident: string;
    /** the unique identifier for the AddressBook this contact is a member of */
    addressBookIdent: string;
    countryCode?: string;
    displayName?: string;
    email?: string;
    firstName?: string;
    images?: Record<string, string>;
    lastName?: string;
    linkPolicy?: 'HARD_LINK' | 'NO_LINK' | 'SOFT_LINK';
    linkedIdentity?: string;
    urn?: string;
}

// https://identity.corp.adobe.com/abs/docs/#_listflatmembers
export interface IAddressBookGroupMembersFlat {
    _embedded: {
        contacts: IAddressBookContact[];
    };
    _links: IABSPageLinks;
    total: number;
}

export interface IAddressBook {
    ident: string;
    displayName: string;
    ownerId: string;
    _links: {
        self: { href: string; }
    };
}

// https://identity.corp.adobe.com/abs/docs/#_listaddressbooks
export interface IAddressBookList {
    _embedded: {
        addressBooks: IAddressBook[];
    };
    _links: IABSPageLinks;
    total: number;
}

export function extractAddressBookIdent(url: string): string {
    return (new URL(url)).pathname.match(/^\/api\/address-books\/[^/]+/)![1];
}
