import type { IExplicitFilter, ItemFilterRelation } from '../core/ItemFilter';
import type { default as Team, TeamState } from './Team';
import whitespaceFilter from '../utils/whitespaceFilter';

export interface ITeamFilterOptions {
    readonly nameContains?: string;
    readonly state?: TeamState;
}

enum StringRelationResult {
    DISJOINTED,
    SUPERSET,
    SUBSET,
    UNKNOWN,
    IDENTICAL
}

/**
 * Available when M2 is released, M1 currently
 * does not support this filter.
 * @experimental
 */
export default class TeamFilter implements IExplicitFilter<Team> {
    private _nameContains?: string;
    private _state?: TeamState;

    constructor(options?: Partial<ITeamFilterOptions>) {
        this._nameContains = options?.nameContains;
        this._state = options?.state;
    }

    static TeamsContainingName(name: string) {
        return new TeamFilter({
            nameContains: name
        });
    }

    static ActiveTeams = new TeamFilter({
        state: 'active'
    });

    static DiscardedTeams = new TeamFilter({
        state: 'discarded'
    });

    get nameContains(): string | undefined {
        return this._nameContains;
    }

    get state(): TeamState | undefined {
        return this._state;
    }

    get hash(): string {
        return (this._nameContains ?? 'any-name') + ':'
            + (this._state ?? 'any-state');
    }

    private _getRelationToNameContains(name: string, otherName: string): StringRelationResult {
        if (name === otherName) {
            return StringRelationResult.IDENTICAL;
        }
        const nameTerms = name.toLowerCase()
            .split(' ').filter(whitespaceFilter).sort();
        const otherNameTerms = otherName.toLowerCase()
            .split(' ').filter(whitespaceFilter).sort();

        if (nameTerms.length === 0 && otherNameTerms.length === 0) {
            return StringRelationResult.IDENTICAL;
        }

        if (nameTerms.length === 0 || otherNameTerms.length === 0) {
            return StringRelationResult.DISJOINTED;
        }

        if (nameTerms.length === otherNameTerms.length
            && nameTerms.every(
                (n, i) => n === otherNameTerms[i]
            )) {
            return StringRelationResult.IDENTICAL;
        }

        let subsetMatches = 0;
        let supersetMatches = 0;

        nameTerms.forEach((nameTerm) => {
            const findMatch = otherNameTerms.find((otherTerm) => {
                const superSet = otherTerm.startsWith(nameTerm);
                const subSet = nameTerm.startsWith(otherTerm);
                return superSet || subSet;
            });

            if (findMatch) {
                if (nameTerm.length <= findMatch.length) {
                    supersetMatches++;
                }

                if (nameTerm.length > findMatch.length) {
                    subsetMatches++;
                }
            }
        });

        if (nameTerms.length === subsetMatches) {
            return StringRelationResult.SUBSET;
        }

        if (nameTerms.length === supersetMatches) {
            return StringRelationResult.SUPERSET;
        }

        if (subsetMatches === 0 && supersetMatches === 0) {
            return StringRelationResult.DISJOINTED;
        }

        return StringRelationResult.UNKNOWN;
    }

    private _searchTarget(searchString: string, targetString: string): boolean {
        const searchTerms = searchString.toLowerCase()
            .split(' ').filter(whitespaceFilter);
        const targetTerms = targetString.toLowerCase()
            .split(' ').filter(whitespaceFilter);

        // Empty word or search term
        if (searchTerms.length === 0 || targetTerms.length === 0) {
            return false;
        }

        return searchTerms.every((searchTerm) => {
            return targetTerms.find((targetTerm) => {
                return targetTerm.startsWith(searchTerm);
            });
        });
    }

    matches(item: Team): boolean {
        const state = this._state;
        if (state && state !== item.state) {
            return false;
        }

        const nameContains = this._nameContains;
        if (nameContains
            && !this._searchTarget(nameContains, item.name)
        ) {
            return false;
        }

        return true;
    }

    getRelationToFilter(other: TeamFilter): ItemFilterRelation {
        let searchMatch;
        if (this.nameContains && other.nameContains) {
            searchMatch = this._getRelationToNameContains(this.nameContains, other.nameContains);
            if (searchMatch === StringRelationResult.DISJOINTED) {
                return 'disjoint';
            }
        }

        if (this.state && other.state && this.state !== other.state) {
            return 'disjoint';
        }

        if (!this.state && other.state) {
            return 'unknown';
        }

        if (!this.nameContains && other.nameContains) {
            return 'unknown';
        }

        if (searchMatch && searchMatch === StringRelationResult.SUPERSET
            || searchMatch === StringRelationResult.UNKNOWN
        ) {
            return 'unknown';
        }

        //------ All 'unknown' cases must be handled above this line
        return 'subset';
    }
}
