import type jsonpatch from 'json-patch';

import { RelType } from '../interface/LinkUtils';
import type AdobeAsset from './AdobeAsset';
import type { ISAMCorePrivate } from '../indexPrivate';
import type SAMError from '../core/SAMError';
import { SAMErrorCode } from '../core/SAMError';
import AdobeAssetResource from './AdobeAssetResource';

export default class AppMetadataResource extends AdobeAssetResource<any> {

    constructor(
        readonly _core: ISAMCorePrivate,
        _parent?: AdobeAsset,
    ) {
        super(_core, _parent, {
            onError: async (error) => {
                if ((error as SAMError).code === SAMErrorCode.NOT_FOUND) {
                    // If an asset doesn't have app metadata, just return empty metadata rather than
                    // treating it as a failure. (Setting the data here clears the error.)
                    await this._setData({});
                }
            }
        });
    }

    /*
        A note regarding the following commented code:

        While the code below is what we want, the issue is that, at the time load() is being called,
        the parent's permissions have not been set yet.

        In AdobeAsset _load(), the permissions are updated by AdobeAssetUpdater.updateLocalItem at the end,
        but AppMetadataResource/load() is being called by await Promise.all(resourcesToReload.map(resource => resource.load()));
        that happens before.

        As long as we do not have a better mechanism to handle the permissions, we have to unsatisfy this request from
        https://jira.corp.adobe.com/browse/SAM-3326:

        6. Update `AppMetadataResource._loadData()` to check the permission on the parent, and if it does not have Permission.ReadAppMetadata, throw ACCESS_DENIED error instead of making the call.
    */

    // async load() {
    //     if (this._parent.hasPermission(Permission.ReadAppMetadata)) {
    //         await super.load();
    //     } else {
    //         throw SAMErrorCode.ACCESS_DENIED;
    //     }
    // }

    protected async _loadData() {
        await this._parent?._ensureLink(RelType.APP_METADATA);
        const assetInterface = await this._parent?._getAssetInterface();
        await assetInterface?.getAppMetadata(this);
    }

    /**
     * @package to be used internally by SAM.js
     */
    async _patch(patches: jsonpatch.OpPatch[]): Promise<void> {
        // TODO: check for graphQL
        await this._parent?._ensureLink(RelType.APP_METADATA);
        const assetInterface = await this._parent?._getAssetInterface();
        await assetInterface?.patchAppMetadata(patches);
    }
}
