import type { LinkReference } from '../../index';
import type { PublishedData } from './data/PublishedData';
import type { Action } from './Action';

import observable from '../utils/observable';
import { requiresWrite } from './utils/AccessUtils';
import { parseNewLinkSchema } from '../utils/LinkUtils';
import type { ModelData } from './data/ModelData';
import Model from './Model';
import type { ActionName } from './Action';
import LibraryError from '../errors/LibraryError';
import type { Optional } from '../types';
import type LibraryContents from './LibraryContents';

/**
 * Defines library items that may have been created by publishing a document's assets.
 * At the time of this writing, that includes only Elements and Groups.
 * @packageDocumentation
 * @module Published
 */

export default abstract class Published<T extends ModelData & PublishedData> extends Model<T> {
    private _sourceRef?: PublishedData['sourceRef'];
    private _sourceModifiedDate?: PublishedData['sourceModifiedDate'];

    protected abstract _updateAction: ActionName;
    /**
     * @package -- only for use in SAM.js
     */
    abstract _actionDispatch(action: Optional<Action, 'path'>): void;

    /**
     * A string reference to where the element or group came from.
     *
     * This should be in the new migrated link format, of a serialized JSON string storing link data:
     * https://git.corp.adobe.com/caf/xcm/blob/master/schemas/cc/link/link.schema.json
     * However, the getter will return whatever any legacy string stored as well, without modification.
     *
     * @type {Stringified<LinkReference> | undefined}
     */
    @observable
    get sourceRefString() {
        return this._sourceRef;
    }

    /**
     * An object reference to where the element or group came from.
     *
     * This should be in the new migrated link format, of an expanded JSON object storing link data:
     * https://git.corp.adobe.com/caf/xcm/blob/master/schemas/cc/link/link.schema.json
     * The getter will convert a legacy reference format into an object.
     * The sourceRef should be read and written as an object but stored in the manifest as a serialized string.
     * The stringified JSON will also be available to read through sourceRefString.
     *
     * It's highly encouraged to set the sourceRef when creating an element, so that we can trace it back later.
     *
     * @type {LinkReference|undefined}
     */
    @observable
    @requiresWrite
    get sourceRef() {
        if (!this.sourceRefString) {
            return undefined;
        }

        let newLinkSchema = parseNewLinkSchema(this.sourceRefString);
        if (!newLinkSchema) {
            // Return legacy sourceRef in the new link schema.
            // The actual migration of the sourceRef should be handled by the client.
            const [ urn, fragment ] = this.sourceRefString.split('#');
            newLinkSchema = {
                'repo:assetId': urn,
                'stRef:fromPart': fragment
            };
            const legacySourceModified = this._sourceModifiedDate;
            if (legacySourceModified) {
                // fromPartInstanceID should be a uuid string, sourceModified is a number.
                newLinkSchema['stRef:fromPartInstanceID'] = `${legacySourceModified}`;
            }
        }

        return newLinkSchema;
    }

    set sourceRef(sourceRef: LinkReference | undefined) {
        if (typeof sourceRef !== 'object' || !parseNewLinkSchema(sourceRef)) {
            const parent = this._parent as LibraryContents;
            throw new LibraryError('INVALID_PARAMETER', 'sourceRef must be a valid JSON object', parent.library.id);
        }
        this._actionDispatch({
            name: this._updateAction,
            type: 'update',
            data: {
                // The sourceRef should be read and written as an object but stored in the manifest as a serialized string.
                sourceRef: JSON.stringify(sourceRef, Object.keys(sourceRef).sort())
            }
        });
    }
}
