import type { LibraryData, LibraryContentsData } from '../models/data/LibraryData';
import type { GroupData } from '../models/data/GroupData';
import type { ElementData } from '../models/data/ElementData';
import type SAMLibrary from '../../libraries/Library';
import microdiff from 'microdiff';

/**
 * REFACTOR NOTES:
 * Anything with LibraryData should move to LibraryContentsData.
 * To avoid too many breaking changes as once, for now I have just added LibraryContentsData to the accepted types on methods that will be used by LibraryContents.
 */

import type {
    Action,
    AggregateAction,
    UpdateAction,
    RemoveAction } from '../models/Action';
import {
    isRemoveAction,
    isUpdateAction,
    isAggregateAction
} from '../models/Action';
import { deepCopy } from '../utils/StoreUtils';
import JSONPath from './JSONPath';
import { extractElementCollection, extractGroupId } from './PathUtils';
import { createPlaceholderId } from '../models/utils';

const ACTION_TYPE_HANDLERS = [
    {
        test: (action: Action) =>
            isAggregateAction(action) && [ 'moveGroup', 'copyGroup' ].includes(action.name as string),
        handler: rebaseGroupActionWithContents
    },
    {
        test: (action: Action) => isUpdateAction(action) && action.name === 'updateElementContent',
        handler: rebaseContentAction
    },
    {
        test: (action: Action) => isUpdateAction(action) && action.name === 'updateGroup',
        handler: rebaseUpdateGroupAction
    },
    {
        test: (action: Action) => isUpdateAction(action) && action.name === 'updateElement',
        handler: rebaseUpdateElementMetadataAction
    },
    {
        test: (action: Action) => isAggregateAction(action) && action.name === 'removeElement',
        handler: rebaseRemoveElementAction
    },
    {
        test: (action: Action) => isRemoveAction(action),
        handler: rebaseRemoveAction
    }
] as const;

function rebaseContentAction(data: LibraryData | LibraryContentsData, action: Action): Action[] {
    const newBaseData = JSONPath.get(data, action.path as string) as any;

    // 1. If a change to this element has been applied since this action was created
    if (newBaseData && newBaseData.modifiedDate !== action.baseData.modifiedDate) {
        if (
            !microdiff(newBaseData.representations, action.baseData.representations, {
                cyclesFix: false
            }).find(
                d =>
                    // Disregard changes in id
                    d.path[1] !== 'id' &&
                    // Check if changes to representations are only additive
                    d.type !== 'CREATE' &&
                    // Disregard removals of undefined values
                    !(d.oldValue === undefined && d.type === 'REMOVE')
            )
        ) {
            // If this diff is only additive or a no-op, we will do nothing.
            return [ action ];
        }
    }

    // 2. If newBaseData does not exist recreate the element
    // OR if base modified dates have changed and the changes were more than additive, fork element
    if (!newBaseData || newBaseData.modifiedDate !== action.baseData.modifiedDate) {
        return [
            {
                name: 'createElement',
                type: 'insert',
                path: extractElementCollection(action.path as string),
                data: deepCopy({
                    ...action.baseData,
                    ...action.data,
                    id: createPlaceholderId()
                })
            }
        ];
    }

    // 3. Otherwise, nothing to do
    return [ action ];
}

function rebaseGroupActionWithContents(data: LibraryData | LibraryContentsData, action: AggregateAction) {
    const actions: Action[] = [];

    const groupId = extractGroupId(action.path as string);
    const oldElements = action.actions.map(subAction => subAction.name === 'removeElement' && subAction.baseData);
    const newElements = data.elements?.filter(el => el.groups.find(group => group.id === groupId)) || [];

    // 1. If a group member has been added, remove the element from the group before moving.
    // - Preprend action removing the element from the group
    const addedElements = newElements.filter(element => !oldElements.find(oldElement => oldElement.id === element.id));
    for (const element of addedElements) {
        actions.push({
            name: 'updateElement',
            type: 'update',
            path: `$.elements[?(@.id == "${element.id}")]`,
            data: {
                groups: element.groups.filter(group => group.id !== groupId)
            }
        });
    }

    // 2. If a group member has been removed, leave the element removed from the group.
    // - Remove element from aggregate's local actions
    const removedElements = oldElements.filter(
        element => !newElements.find(newElement => newElement.id === element.id)
    );
    for (let i = action.actions.length - 1; i >= 0; i -= 1) {
        const subAction = action.actions[i];
        if (removedElements.find(element => element.id === subAction.baseData.id)) {
            action.actions.splice(i, 1);
        }
    }

    // 3. If a group member has been changed, remove the changed element from group, create a new element based on the original in group, move group
    // - Prepend createElement
    // - Prepend updateElement
    // - Replace old element with new element in aggregate's local actions

    actions.push(action);

    return actions;
}

function rebaseRemoveElementAction(data: LibraryData | LibraryContentsData, action: AggregateAction) {
    const newBaseData = JSONPath.get(data, action.path as string) as any;
    const removeAction = action.actions.find(subAction => subAction.name === 'removeElement');

    // if element is changed, dont want to delete or create in removedElements
    if (!newBaseData || newBaseData.modifiedDate !== removeAction?.baseData.modifiedDate) {
        return [];
    }

    return [ action ];
}

function rebaseUpdateGroupAction(data: LibraryData | LibraryContentsData, action: UpdateAction<GroupData>): Action[] {
    const newBaseData = JSONPath.get(data, action.path as string) as GroupData;

    // If the target no longer exists, restore the target (group)
    // TODO: How do we restore the group members?
    if (!newBaseData) {
        return [
            {
                name: 'createGroup',
                type: 'insert',
                path: '$.groups',
                data: deepCopy({
                    ...action.baseData,
                    ...action.data,
                    id: createPlaceholderId()
                })
            }
        ];
    }

    // Otherwise rebase the action. This doesn't really matter for a metadata update, but we might as well.
    return [
        {
            ...action,
            baseData: deepCopy(newBaseData)
        }
    ];
}

function rebaseUpdateElementMetadataAction(data: LibraryData | LibraryContentsData, action: UpdateAction<ElementData>) {
    const newBaseData = JSONPath.get(data, action.path as string) as ElementData;

    // If the target no longer exists, delete the action (element metadata)
    if (!newBaseData) {
        return [];
    }

    // Otherwise rebase the action. This doesn't really matter for a metadata update, but we might as well.
    return [
        {
            ...action,
            baseData: deepCopy(newBaseData)
        }
    ];
}

function rebaseRemoveAction(data: LibraryData | LibraryContentsData, action: RemoveAction) {
    const newBaseData = JSONPath.get(data, action.path as string) as any;

    // If the target no longer exists, delete the action (nothing to delete)
    // If the element has been changed, delete the action (keep the changed element/group)
    if (!newBaseData || newBaseData.modifiedDate !== action.baseData.modifiedDate) {
        return [];
    }

    // Otherwise, keep the action (remove element/group)
    return [ action ];
}

export function rebaseAction(data: LibraryData | LibraryContentsData, action: Action): Action[] {
    for (const { test, handler } of ACTION_TYPE_HANDLERS) {
        if (test(action)) {
            return handler(data, action as never);
        }
    }

    return [ action ];
}

// R-TODO: ownership may not be loaded yet on SAMLibrary. Temporarily disabling this until we can move over to a SAM Library util.
