// }

export function isTeamLibrary(library: SAMLibrary): boolean {
    return library.isChildOfProject;
}

export function isBrandLibrary(library: SAMLibrary): boolean {
    return !!library.roles?.find(role => role.type === 'brand');
}

export function isTrainingSetLibrary(library: SAMLibrary | LibraryData): boolean {
    return !!library.roles?.some(role => role.type === 'cm_training_set');
}

export function isLibraryLoadedByDefault(library: LibraryData, enableBrandLifecycleManagement?: boolean): boolean {
    if (!library || isTrainingSetLibrary(library)) {
        return false;
    }

    const isTeam = library.ownership === 'incoming';
    const isPersonal = library.ownership === 'private' || library.ownership === 'outgoing';
    const ownershipFilter = enableBrandLifecycleManagement ? isTeam : isPersonal;
    const isBookmarked = !!library.bookmark?.id;
    const isApprovedBrand = !!library.roles?.find(role => role.type === 'approvedbrand');
    // A library is a loaded by default group if it is personal or bookmarked.
    // Training Set Libraries are currently excluded from the default listing.
    return ownershipFilter || isBookmarked || isApprovedBrand;
}
