import type { SAM } from '@ccx-public/component-types';
import { AssignmentStatus } from '../interface/AssignmentModel';
import type {
    IComparatorMap } from '../core/ItemOrder';
import {
    compareStrings,
    compareValues,
    createItemOrderFactory
} from '../core/ItemOrder';
import type Assignment from './Assignment';

export type AssignmentOrderField = 'name' | 'dueDate' | 'status';

const StatusOrderValues = {
    [AssignmentStatus.DRAFT]: 0,
    [AssignmentStatus.ASSIGNED]: 1,
};

const compareAssignmentNames =  (a: Assignment, b: Assignment) => {
    return compareStrings(a.name || '', b.name || '');
};

const OrderFieldToComparator: IComparatorMap<Assignment, AssignmentOrderField>
  = {
      name(a: Assignment, b: Assignment): number {
          return compareAssignmentNames(a, b);
      },
      dueDate(a: Assignment, b: Assignment): number {
          let value;
          if (!a.dueDate && !b.dueDate) {
              value  = 0;
          } else if (!a.dueDate) {
              value = 1; // Undefined date should be sorted last in ascending order
          } else if (!b.dueDate) {
              value = -1;
          } else {
              value = compareValues(a.dueDate.getTime(), b.dueDate.getTime());
          }
          if (value === 0) {
              // Within the same dueDate, sort by name
              return compareAssignmentNames(a, b);
          }
          return value;
      },
      status(a: Assignment, b: Assignment): number {
          const value = compareValues(StatusOrderValues[a.status as AssignmentStatus], StatusOrderValues[b.status as AssignmentStatus]);
          if (value === 0) {
              // Within the same status, sort by name
              return compareAssignmentNames(a, b);
          }
          return value;
      }
  };

export default class AssignmentOrder extends createItemOrderFactory(OrderFieldToComparator) implements SAM.AssignmentOrder {
    static default = new AssignmentOrder('ascending', 'name');
}
