import type { SAM } from '@ccx-public/component-types';
import type { IComparatorMap } from '../core/ItemOrder';
import { compareStrings, createItemOrderFactory } from '../core/ItemOrder';
import type Collaborator from './Collaborator';

export type CollaboratorOrderField = 'name';

const OrderFieldToComparator: IComparatorMap<Collaborator, CollaboratorOrderField> = {
    name(a: Collaborator, b: Collaborator): number {
        return compareStrings(a.name ?? a.id, b.name ?? a.id);
    }
};

export default class CollaboratorOrder extends createItemOrderFactory(OrderFieldToComparator) implements SAM.CollaboratorOrder {
    static default = new CollaboratorOrder('ascending', 'name');
}
