import type { IExplicitFilter, ItemFilterRelation } from '../core/ItemFilter';
import type { default as Space, SpaceState, TeamRole } from './Space';

export interface ISpaceFilterOptions {
    readonly bookmarked?: boolean;
    readonly teamID?: string;
    readonly state?: SpaceState;

    /**
     * Undefined -> returns all spaces, regardless of the role on the parent team.
     * 'NONE' -> Returns only the spaces from teams the user IS NOT part of
     * (ie. the role of the user on those team is none).
     *
     * In the future we may add a value of 'MEMBER' to return only the spaces from teams the
     * user IS part of. However, that feature is not supported by the server at the moment,
     * so we are not exposing that value yet.
     */
    readonly teamRole?: TeamRole;
}

export default class SpaceFilter implements IExplicitFilter<Space> {

    private _bookmarked: boolean = false;
    private _teamID?: string;
    private _state?: SpaceState;
    private _teamRole?: TeamRole;

    constructor(options?: Partial<ISpaceFilterOptions>) {
        this._bookmarked = Boolean(options?.bookmarked);
        this._teamID = options?.teamID;
        this._teamRole = options?.teamRole;
        this._state = options?.state;
        this._teamRole = options?.teamRole;
    }

    static ActiveSpaces = new SpaceFilter({
        state: 'active'
    });

    static ArchivedSpaces = new SpaceFilter({
        state: 'archived'
    });

    static ActiveBookmarkedSpaces = new SpaceFilter({
        state: 'active',
        bookmarked: true
    });

    static ActiveSpacesFromOtherTeams = new SpaceFilter({
        state: 'active',
        teamRole: 'NONE'
    });

    static ActiveSpacesFromTeam(teamID: string) {
        return new SpaceFilter({
            state: 'active',
            teamID
        });
    }

    get bookmarked(): boolean {
        return this._bookmarked;
    }

    get teamID(): string | undefined {
        return this._teamID;
    }

    get teamRole(): TeamRole | undefined {
        return this._teamRole;
    }

    get state(): SpaceState | undefined {
        return this._state;
    }

    get hash(): string {
        return String(this.bookmarked) + ':'
            + (this.teamID || 'all-teams') + ':'
            + (this._teamRole ?? 'all-roles') + ':'
            + (this._state ?? 'any-state');
    }

    matches(item: Space): boolean {
        if (this._bookmarked && !item.isBookmarked) {
            return false;
        }
        const teamID = this._teamID;
        if (teamID && item.teamID !== teamID) {
            return false;
        }

        const teamRole = this._teamRole;
        if (teamRole && item.teamRole !== teamRole) {
            return false;
        }

        const state = this._state;
        if (state && state !== item.state) {
            return false;
        }

        return true;
    }

    getRelationToFilter(other: SpaceFilter): ItemFilterRelation {
        const otherSpaceFilter = other as SpaceFilter;

        if (this._teamRole !== otherSpaceFilter._teamRole) {
            if (this._teamRole && otherSpaceFilter._teamRole) {
                // If both filters specify a completely different teamRole then the
                // lists are entirely disjoint.
                return 'disjoint';
            }
            // If only one filter specifically looks for the team role, then the other might be
            // able to borrow some items from it.
            return 'unknown';
        }

        if (this.teamID && otherSpaceFilter.teamID && this.teamID !== otherSpaceFilter.teamID) {
            // Teams are entirely different, no shared elements are expected.
            return 'disjoint';
        }

        if (!this.teamID && otherSpaceFilter.teamID) {
            // If the other list has a teamID and this filter doesn't then
            // this is list is going to have an unknown final state.
            return 'unknown';
        }

        // If the other list filtered for only bookmarked items and this doesn't,
        // then this is list is going to have an unknown final state.
        if (!this.bookmarked && other.bookmarked) {
            return 'unknown';
        }

        if (this._state !== other._state) {
            // If both filters expect a state and the states do not match, then
            // the lists are not going to have any items in common.
            if (this._state && other._state) {
                return 'disjoint';
            }
            // If only one list expects a specific state and the other can take any state,
            // then we could possible share some items.
            return 'unknown';
        }

        return 'subset';
    }

}
