import { CustomModelPublishedState } from './LegacyCustomModelModel';
import type { IExplicitFilter, ItemFilterRelation } from '../../core/ItemFilter';
import { getDateRangeRelation } from '../../core/ItemFilter';
import type LegacyCustomModel from './LegacyCustomModel';

export interface ICustomModelListingOptions {
    publishedState?: CustomModelPublishedState;
    createDateMin?: Date;
    createDateMax?: Date;
    modifyDateMin?: Date;
    modifyDateMax?: Date;
    createdBy?: string;
}

export default class CustomModelFilter implements IExplicitFilter<LegacyCustomModel> {
    private _listingOptions: Partial<ICustomModelListingOptions> = {};

    constructor(listingOptions?: Partial<ICustomModelListingOptions>) {
        if (listingOptions) {
            this._listingOptions = listingOptions;
        }
    }

    get listingOptions() {
        return this._listingOptions;
    }

    get hash(): string {
        return [
            this._listingOptions.publishedState ? `publishedState:${this._listingOptions.publishedState}` : undefined,
            this._listingOptions.createDateMin ? `createDateMin:${this._listingOptions.createDateMin.getTime()}` : undefined,
            this._listingOptions.createDateMax ? `createDateMax:${this._listingOptions.createDateMax.getTime()}` : undefined,
            this._listingOptions.modifyDateMin ? `modifyDateMin:${this._listingOptions.modifyDateMin.getTime()}` : undefined,
            this._listingOptions.modifyDateMax ? `modifyDateMax:${this._listingOptions.modifyDateMax.getTime()}` : undefined,
            this._listingOptions.createdBy ? `createdBy:${this._listingOptions.createdBy}` : undefined,
        ].filter(x => x).join(':');
    }

    matches(item: LegacyCustomModel) {
        if (this._listingOptions.publishedState
            && (item.publishedState !== this._listingOptions.publishedState)
            && this._listingOptions.publishedState !== CustomModelPublishedState.ALL) {
            return false;
        }

        if (this._listingOptions.createdBy && (item.createdBy !== this._listingOptions.createdBy)) {
            return false;
        }

        if (this._listingOptions.createDateMin && (item.created < this._listingOptions.createDateMin)) {
            return false;
        }

        if (this._listingOptions.createDateMax && (item.created > this._listingOptions.createDateMax)) {
            return false;
        }

        if (this._listingOptions.modifyDateMin && (item.modified < this._listingOptions.modifyDateMin)) {
            return false;
        }

        if (this._listingOptions.modifyDateMax && (item.modified > this._listingOptions.modifyDateMax)) {
            return false;
        }

        return true;
    }

    /**
     * This method determines the commonality between the already present filter (other)
     * and the new filter to be applied (this). The point of this is to
     * see if the new filter (this) can build some, all, or none of it's items
     * from (other) filter.
     *
     * Subset: Means that ALL items for this filter can be built from other
     * Disjoint: No items for this filter can be built from other.
     * Unknown: Some items for this filter can be built from other.
     *
     * @note we should always determine disjoint cases first before other cases.
     * @note this = NEW FILTER, other = EXISTING FILTER
     *
     * @param other The existing filter that we are getting the relation to.
     * @returns { ItemFilterRelation }
     */
    getRelationToFilter(other: CustomModelFilter): ItemFilterRelation {
        const relationWrtPublishedState: ItemFilterRelation = this.getRelationPublishedState(other);
        const relationWrtCreatedBy: ItemFilterRelation = this.getRelationCreatedBy(other);

        const relationWrtCreatedAt: ItemFilterRelation = getDateRangeRelation(
            this._listingOptions.createDateMin,
            this._listingOptions.createDateMax,
            other._listingOptions.createDateMin,
            other._listingOptions.createDateMax);

        const relationWrtModifiedAt: ItemFilterRelation = getDateRangeRelation(
            this._listingOptions.modifyDateMin,
            this._listingOptions.modifyDateMax,
            other._listingOptions.modifyDateMin,
            other._listingOptions.modifyDateMax);

        //Check for any disjoint cases first
        if ([ relationWrtPublishedState, relationWrtCreatedBy, relationWrtCreatedAt, relationWrtModifiedAt ].some(x => x === 'disjoint')) {
            return 'disjoint';
        }

        //Then check for any unknown cases
        if ([ relationWrtPublishedState, relationWrtCreatedBy, relationWrtCreatedAt, relationWrtModifiedAt ].some(x => x === 'unknown')) {
            return 'unknown';
        }

        //All cases are subset
        return 'subset';
    }

    getRelationPublishedState(other: CustomModelFilter): ItemFilterRelation {
        if (this._listingOptions.publishedState === other._listingOptions.publishedState) {
            return 'subset';
        }

        if (other._listingOptions.publishedState === CustomModelPublishedState.ALL || other._listingOptions.publishedState === undefined) {
            return 'subset';
        }

        if (this._listingOptions.publishedState === CustomModelPublishedState.ALL || this._listingOptions.publishedState === undefined) {
            return 'unknown';
        }

        return 'disjoint';
    }

    getRelationCreatedBy(other: CustomModelFilter): ItemFilterRelation {
        if (this._listingOptions.createdBy === other._listingOptions.createdBy) {
            return 'subset';
        }

        if (!other._listingOptions.createdBy) {
            return 'subset';
        }

        if (!this._listingOptions.createdBy) {
            return 'unknown';
        }

        return 'disjoint';
    }
}
