import { SharedChangeEvent } from './ChangeEvent';
import SAMError, { SAMErrorCode } from '../core/SAMError';
import type IEvent from './IEvent';
import type { ItemId } from './ItemBase';
import type ItemBase from './ItemBase';
import type { ISAMCorePrivate, ISAMObject } from '../indexPrivate';

export type IUpdateSessionType = 'fetch' | 'mutation';

export interface IUpdateSession<LocalType extends ItemBase> extends ISAMObject {
    readonly hasChanges: boolean;
    readonly updateContext?: string;
    readonly mostRecentValidMutation?: number;
    readonly type: IUpdateSessionType;

    ensureItemIsAdded(item: LocalType): void;
    reindexItem(item: LocalType, oldId: ItemId, newId: ItemId): void;

    queueAddedItem(item: LocalType): void;
    queueChangedItem(item: LocalType, event?: IEvent[]): void;
    queueDiscardedItem(item: LocalType): void;

    readonly addedItems?: LocalType[];
    readonly changedItems?: LocalType[];
    readonly discardedItems?: LocalType[];
    readonly changedItemsWithEvents?: [LocalType, Set<IEvent>][];

    getItemById(id: ItemId): LocalType | undefined;
    findItem(callback: (item: LocalType) => boolean): LocalType | undefined;

    checkIfItemAllowsMutations(item: LocalType): boolean;

    commit(): void;
}

export type IUpdateSessionDelegate<LocalType extends ItemBase> = {
    getLocalItemById(id: ItemId): LocalType | undefined;
    isItemDiscarded(item: LocalType): boolean;
    reindexItem(item: LocalType, oldId: ItemId, newId: ItemId): void;
    commitUpdateSession(session: UpdateSession<LocalType>): void;
    findItem(callback: (item: LocalType) => boolean): LocalType | undefined;
}

export default class UpdateSession<LocalType extends ItemBase> implements IUpdateSession<LocalType> {

    private _addedItems?: Map<ItemId, LocalType>;
    private _changedItems?: Map<LocalType, Set<IEvent>>;
    private _discardedItems?: Set<LocalType>;

    constructor(
        readonly _core: ISAMCorePrivate,
        private _delegate: IUpdateSessionDelegate<LocalType>,
        readonly updateContext?: string,
        readonly mostRecentValidMutation?: number,
        readonly type: IUpdateSessionType = 'fetch'
    ) {
    }

    get hasChanges(): boolean {
        return Boolean(this._addedItems || this._changedItems || this._discardedItems);
    }

    get addedItems(): LocalType[] | undefined {
        return this._addedItems && Array.from(this._addedItems.values());
    }

    get changedItems(): LocalType[] | undefined {
        return this._changedItems && Array.from(this._changedItems.keys());
    }

    get discardedItems(): LocalType[] | undefined {
        return this._discardedItems && Array.from(this._discardedItems);
    }

    get changedItemsWithEvents(): [LocalType, Set<IEvent>][] | undefined {
        return this._changedItems && Array.from(this._changedItems);
    }

    checkIfItemAllowsMutations(item: LocalType): boolean {
        const { lastKnownClientMutation } = item;
        const { mostRecentValidMutation } = this;
        // Return false only when the item has a mutation time that is more recent than the
        // window of latency that the server APIs can guarantee.
        // Note that if lastKnownClientMutation === mostRecentValidMutation, we still allow the mutation,
        // because if a client mutates an item (such as from a listing) and then immediately updates it,
        // we want to allow that second update to go through.
        return !lastKnownClientMutation || !mostRecentValidMutation || lastKnownClientMutation <= mostRecentValidMutation;
    }

    ensureItemIsAdded(item: LocalType): void {
        const { id } = item;
        if (this._addedItems?.get(id) === item) {
            // It was already part of this session.
            return;
        }

        // Check if we already had it in the pool. If it was discarded before,
        // then we want to recover it by adding it again.
        const delegate = this._delegate;
        const existingItem = delegate.getLocalItemById(id);
        if (existingItem && existingItem !== item) {
            // Note: This is typically caused by using updateLocalItem in an async function after some `await`
            //            statement. While waiting, some other process causes the item to be added to the ItemPool
            //            under the same ID. Using updateRemoteItem ensures that only the current item in the pool
            //            is updated; however, changing `updateLocalItem(session, this, ...)` to updateRemoteItem could cause
            //            an instance other than `this` to be updated.
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, `Item with id ${id} does not match the item with this id in the item pool`);
        }

        if (existingItem && !delegate.isItemDiscarded(item)) {
            return;
        }

        // Finally, let's just add this item again.
        this.queueAddedItem(item);
    }

    reindexItem(item: LocalType, oldId: ItemId, newId: ItemId): void {
        item._setId(newId);
        this.queueChangedItem(item, [ SharedChangeEvent ]);
        // Updates the key in the key-item cache
        this._delegate.reindexItem(item, oldId, newId);
    }

    queueAddedItem(item: LocalType): void {
        let addedItems = this._addedItems;
        if (!addedItems) {
            addedItems = new Map<ItemId, LocalType>();
            this._addedItems = addedItems;
        }
        addedItems.set(item.id, item);

        // Make sure we don't send any changed events on new items.
        this._changedItems?.delete(item);
    }

    queueChangedItem(item: LocalType, events: IEvent[] = [ SharedChangeEvent ]): void {
        if (this._addedItems?.has(item.id)) {
            // We don't send any events on new items.
            return;
        }

        let changedItems = this._changedItems;
        if (!changedItems) {
            changedItems = new Map<LocalType, Set<IEvent>>();
            this._changedItems = changedItems;
        }

        let itemEvents = changedItems.get(item);
        if (!itemEvents) {
            itemEvents = new Set<IEvent>();
            changedItems.set(item, itemEvents);
        }

        events.forEach((event) => itemEvents?.add(event));
    }

    /**
     * Marks an item for discard by adding it to a WeakSet holding pen.
     * - On `commit()`, the item is removed from lists and itemPool.
     * - The item is garbage collected once no direct references remain.
     * - Prevents undefined errors while async processes settle.
     *
     * **Scenario 1: When Clients Do NOT Need Notification (Standard Removal)**
     * - Use this when removing an item from a list, **but no explicit client notification is needed**.
     * - Example: Item no longer belongs in the list.
     * - The item is removed from lists but stays in the holden pen and pool temporarily for safety.
     *
     * **Scenario 2: When Clients DO Need Notification (Permanent Delete or Unshare)**
     * - If `updateLocal/RemoteItem()` is called first (e.g., setting `Permission.None` to revoke access),
     *   the item is **not** added to the holding pen and remains in the pool.
     * - This ensures clients (in 1Up or Editor views) get an event to handle permission loss.
     * - 🚨 In this case, **manually call `removeLocalItems([item.id])`** after to remove it from the pool.
     *
     * Note: If there is a new use case for removing an Item and notifying clients other than AdobeAsset access loss,
     * we should add a more generalized "access lost" status and event in ItemBase. Reach out to SAM.js core team if you run into this need.
     */
    queueDiscardedItem(item: LocalType): void {
        let discardedItems = this._discardedItems;
        if (!discardedItems) {
            discardedItems = new Set<LocalType>();
            this._discardedItems = discardedItems;
        }
        discardedItems.add(item);
    }

    getItemById(id: ItemId): LocalType | undefined {
        return this._addedItems?.get(id) || this._delegate.getLocalItemById(id);
    }

    findItem(callback: (item: LocalType) => boolean): LocalType | undefined {
        return this._delegate.findItem(callback);
    }

    commit() {
        // Committing the update session first to make sure the pool is up-to-date
        // with the latest changes before we move control back to the client code.
        this._delegate.commitUpdateSession(this);

        // Dispatch all events on the changed items.
        const changedItems = this._changedItems;
        if (changedItems) {
            for (const [ item, events ] of changedItems.entries()) {
                for (const event of events) {
                    item.dispatch(event);
                }
            }
        }

        if (this.type === 'mutation') {
            // If this was the result of a mutation change, update the timestamps
            // of all the items that were used. We use this.mostRecentValidMutation
            // rather than Date.now(), because the data this mutation was based on
            // is only valid as of this.mostRecentValidMutation.
            const allModifications =  [
                ...this._addedItems?.values() ?? [],
                ...this._discardedItems?.values() ?? [],
                ...changedItems?.keys() ?? []
            ];
            for (const item of allModifications) {
                item.updateLastKnownClientMutation(this.mostRecentValidMutation ?? Date.now());
            }
        }
    }
}
