import type { RepresentationData } from '../data/RepresentationData';

import type Representation from '../Representation';
import Element from '../Element';
import { deepCopy } from '../../utils/StoreUtils';

function findMatchingRepresentationData(
    target: Representation,
    candidates: RepresentationData[]
): RepresentationData | undefined {
    for (const candidate of candidates) {
        if (candidate.id === target.id) {
            return candidate;
        }

        if (candidate.children) {
            const result = findMatchingRepresentationData(target, candidate.children);

            if (result) {
                return result;
            }
        }
    }
}

export function replaceRepresentationsOnTarget(
    target: Representation | Element,
    newChildren: RepresentationData[]
): RepresentationData[] {
    if (target instanceof Element) {
        return newChildren;
    }

    const representations = deepCopy(target.element._childrenData);
    const targetData = findMatchingRepresentationData(target, representations);

    if (targetData) {
        targetData.children = newChildren;
    }

    return representations;
}
