import ImplicitAdobeAssetFilterBase from './ImplicitAdobeAssetFilterBase';
import type { IImplicitFilter } from '../core/ItemFilter';
import type AdobeAsset from './AdobeAsset';

export default class LocalAdobeAssetFilter extends ImplicitAdobeAssetFilterBase implements IImplicitFilter<AdobeAsset> {

    matches(item: AdobeAsset): boolean {
        // Only show assets that are local (i.e. are available offline).
        if (!item.isAvailableOffline) {
            return false;
        }

        return super.matches(item);
    }

}
