import SAMError, { SAMErrorCode } from '../SAMError';
import type { IHasKeyMap } from './key';
import { KeysProperty } from './key';

/**
 * The synchronized decorator ensures that only one caller can be executing the method at once,
 * similar to the synchronized keyword in Java for critical blocks. This only makes sense
 * to apply to asynchronous methods, since JavaScript is single-threaded.
 *
 * If an @synchronized method is called while another caller is already executing it, the second
 * caller will wait until the first caller finishes (regardless of whether the promise rejects or succeeds),
 * before executing.
 *
 * A parameter can be marked as @key, allowing multiple concurrent calls so long as the keys are different
 * (this is similar to passing a value to synchronized() in Java).
 */
export default (target: any, propertyKey: string, descriptor: PropertyDescriptor) => {
    const promisesMapProperty = Symbol(`@synchronized ${propertyKey}`);
    const method = descriptor.value;
    if (!method) {
        throw SAMError.create(SAMErrorCode.BAD_REQUEST, '@synchronized decorator can only be applied to a method');
    }
    descriptor.value = async function (this: IHasKeyMap & { [promisesMapProperty]: Map<string, ReturnType<typeof method>> }, ...args: any[]) {
        const keyIndex = this[KeysProperty]?.get(propertyKey);
        const key: string = keyIndex === undefined ? 'default' : args[keyIndex];

        const map = this[promisesMapProperty] || (this[promisesMapProperty] = new Map);

        let promise;
        do {
            promise = map.get(key);
            if (promise) {
                // Somebody else was already executing, so we wait for that to finish first
                try {
                    await promise;
                } catch (e) {
                    // Ignore any errors - we'll execute after the existing caller resolves or rejects
                }
            }
        } while (promise);

        // Now enter the critical block ourself - record the promise so others need to wait.
        // Note that we use different promise so that we ensure other callers continue only after
        // we've deleted the previous promise.
        // eslint-disable-next-line
        let outerResolve = (value: any) => {};
        map.set(key, new Promise(resolve => outerResolve = resolve));
        try {
            return await method.apply(this, args);
        } finally {
            // Always delete the promise even if we reject, to allow others to continue
            map.delete(key);
            outerResolve(undefined);
        }
    };
};
