import type { IExplicitFilter, IImplicitFilter } from '@sam-js-src/core/ItemFilter';
import { ModernSet } from '@sam-js-src/utils/ModernSet';
import type Resource from '../assets/Resource';

export function getMediaTypesFromFilters(implicitFilter?: IImplicitFilter<any>, explicitFilter?: IExplicitFilter<any>): string[] {
    const implicitFilterMediaTypes = getVariableFromObj('mediaTypes', implicitFilter);
    if (implicitFilterMediaTypes) {
        return [ ...<[]>implicitFilterMediaTypes ];
    }

    const explicitFilterMediaTypes = getVariableFromObj('mediaTypes', explicitFilter);
    if (explicitFilterMediaTypes) {
        return [ ...<[]>explicitFilterMediaTypes ];
    }

    return [];
}

export function getExcludeMediaTypesFromFilters(implicitFilter?: IImplicitFilter<any>, explicitFilter?: IExplicitFilter<any>): string[] {
    const implicitSet: ModernSet<string> = getVariableFromObj('excludeMediaTypes', implicitFilter) ?? new ModernSet([]);
    const explicitSet: ModernSet<string> = getVariableFromObj('excludeMediaTypes', explicitFilter) ?? new ModernSet([]);
    return [ ...implicitSet.union(explicitSet) ];
}

export function getVariableFromObj(variable: string, obj?: Record<string, any>): any {
    if (!obj || !(variable in obj)) {
        return undefined;
    }

    return obj[variable];
}

export function getMostRecentValidMutation(resource: Resource<any> | undefined, latency: number = 0): number {
    return (resource?.timestamp ?? Date.now()) - latency;
}
