    /**
     * Grants board access to multiple users at once
     * Automatically detects whether users are ambiguous or unambiguous based on provided information
     *
     * @param options - Options for granting board access
     * @param options.boardId - The ID of the board
     * @param options.users - Array of user objects with email and optional userId
     * @returns Promise that resolves when the access has been granted
     *
     * @example
     * await boardContext.grantBoardAccessToUsers({
     *   boardId: 'board-id',
     *   users: [
     *     { email: 'user1@example.com' },
     *     { email: 'user2@example.com', userId: 'BF44198F668D1EAE0A494021@af361967668d0331494131.e' }
     *   ]
     * });
     */
    @trace
    @synchronized
    async grantBoardAccessToUsers({ boardId, users }: GrantBoardAccessToUsersOptions): Promise<void> {
        const operations: BoardUserPatchOperation[] = users.map(user => {
            if (user.userId) {
                return {
                    op: 'grantAccessToPosts',
                    path: '/user',
                    value: {
                        id: user.userId,
                        type: 'imsUser',
                        email: user.email,
                    },
                };
            } else {
                return {
                    op: 'grantAccessToPosts',
                    path: '/user',
                    value: {
                        email: user.email,
                    },
                };
            }
        });
        await this._boardsInterface.patchBoardUsers(boardId, operations);
    }

