import type jsonpatch from 'json-patch';

import { default as SAMError, ProblemType, SAMErrorCode } from '../core/SAMError';
import { synchronized } from '../core/decorators';
import { isDeepEqual } from '../core/ObjectUtils';
import { SAMObjectEventEmitter } from '../core/SAMObjectEventEmitter';
import { default as ChangeEvent, CHANGE } from '../core/ChangeEvent';
import type { IEventMap } from '../core/ITypedEventEmitter';
import type { AssetProperties, ONSAssetLabel, ONSObjectProperties, ONSResourceType } from './ONSResource';
import type { ONSChangedAssetInfo } from './ONSEvent';
import { ONSAssetChangeEvent } from './ONSEvent';
import { getRetryAfterHeader, JSON_PATCH_MIME_TYPE, RelType, getURLFromLinks } from '../interface/LinkUtils';
import type { ONSContext, ONSDiscoveryDocument } from './ONSContext';

const ONS_SUBSCRIPTION_MIME_TYPE = 'application/vnd.adobecloud.subscription+json';
const ONS_SUBSCRIPTION_AUTH_HEADER = 'Authorization';
const MAX_RETRY_ATTEMPTS: number = 3;
const MIN_RETRY_INTERVAL_MS: number = 10; // 10 msec

// For test validation only, this event is emitted in _updateSubscriptionOnServer when it is
// completed so tests can tell when subscription updates are complete, even if _updateSubscriptionOnServer
// determines there is no work to do. This event was intentionally omitted from the public interface, as it
// is intended for testing only.
export const TEST_ONLY_SUB_CHANGED = 'test_only_sub_changed';
class SubChangeErrorEvent extends Event {
    constructor(readonly error: any) {
        super(TEST_ONLY_SUB_CHANGED);
    }
}

export type ONSObjectMap = Map<string, ONSObjectProperties>;

// If there's an error fetching config, we'll return {}, so using Partial<> here
export type SubscriptionConfig =  Partial<ONSDiscoveryDocument['config']['subscriptions']>;

export enum SubscriptionMonitoringStatus {
    Active,
    Inactive,
    Registering
}

type ONSCreateRequestObject = { id: string } & ONSObjectProperties;
type ONSCreateRequestObjects = ONSCreateRequestObject[];

export type ONSCreateRequestBody = {
    id?: string,
    objects: ONSCreateRequestObjects,
    device: {
        id: string
    },
    expiresAt: number
}

function createObjectsRequestBody(onsObjects: ONSObjectMap): ONSCreateRequestObjects {
    return [ ...onsObjects ].map(([ id, properties ]) => {
        return  { id, ...properties };
    });
}

export class ONSSubscriptionChangeEvent extends ChangeEvent {
    constructor(
        readonly fromCache: boolean
    ) {
        super();
    }
}

export interface ONSSubscriptionEventMap extends IEventMap {
    [CHANGE]: ONSSubscriptionChangeEvent;
}

export interface ONSCachedSubscription {
    id: string;
    href: string;
    onsObjects: { [id: string]: ONSObjectProperties };
    expiresAt?: number;
}

/**
* Interface to register ONS subscription and listen for change events.
*/
export class ONSSubscription extends SAMObjectEventEmitter<ONSSubscriptionEventMap> {
    private _lastError?: any;
    private _retryTimeout?: ReturnType<typeof setTimeout>;
    private _retryChangeLogTimeout?: ReturnType<typeof setTimeout>;
    private _nextChangeLogLinks?: any;
    private _pendingONSObjects: ONSObjectMap = new Map();
    private _watchedONSObjects: ONSObjectMap = new Map();
    private _initializedFromCache: boolean = false;
    private _subscriptionId?: string;
    private _subscriptionHref?: string;
    private _expiresAt?: number;
    private _continuationToken?: string;
    private _monitoringStatus: SubscriptionMonitoringStatus = SubscriptionMonitoringStatus.Inactive;

    // Default interval between retry attempts in seconds if no Retry-After header value is available.
    static DEFAULT_RETRY_INTERVAL_SEC = 0;

    constructor(
        private _onsContext: ONSContext,
        cachedSubscription?: ONSCachedSubscription
    ) {
        super(_onsContext._core);
        if (cachedSubscription) {
            const { id, href, onsObjects, expiresAt } = cachedSubscription;
            this._subscriptionId = id;
            this._subscriptionHref = href;
            this._expiresAt = expiresAt;
            this._watchedONSObjects = new Map(Object.entries(onsObjects || {}));

            // We check if we are given watchedAssetId's and this will
            // indicate that we are loading them from cache.
            this._initializedFromCache = this._watchedONSObjects.size > 0;
        }
    }

    get subscriptionId(): string | undefined {
        return this._subscriptionId;
    }
    get subscriptionHref(): string | undefined {
        return this._subscriptionHref;
    }
    get expiresAt(): number {
        return this._expiresAt ?? 0;
    }

    get lastError(): any {
        return this._lastError;
    }

    /**
     * The objects currently monitored by this subscription. Typically, this is only used to compare to
     * pendingONSObjects. If they differ, then the cloud subscription needs to be updated.
     */
    get watchedONSObjects(): ONSObjectMap {
        return this._watchedONSObjects;
    }

    get continuationToken(): string | undefined {
        return this._continuationToken;
    }

    set continuationToken(continuationToken: string | undefined) {
        this._continuationToken = continuationToken;
    }

    get monitoringStatus(): SubscriptionMonitoringStatus {
        return this._monitoringStatus;
    }

    set monitoringStatus(newStatus: SubscriptionMonitoringStatus) {
        this._monitoringStatus = newStatus;
    }

    public abort(): boolean {
        if (this._retryTimeout) {
            clearTimeout(this._retryTimeout);
            this._retryTimeout = undefined;
            this.logInfo(`Subscription ${this.subscriptionId} retry got aborted`);
            return true;
        }
        return false;
    }

    /**
     * The list of objects this subscription should be monitoring.
     */
    get pendingONSObjects(): ONSObjectMap { return this._pendingONSObjects; }

    /**
     * Modifies the pending objects for subscription and then updates the subscription on the
     * service.
     * @param pendingONSObjects
     */
    set pendingONSObjects(pendingONSObjects: ONSObjectMap | undefined) {
        // ONSWorker allocates more ONSSubscription instances than it uses. Each time it updates
        // subscriptions, it will pass undefined as pendingONSObjects when there are no objects for
        // this subscription. This either means the subscription no longer has any objects to monitor,
        // or that it continues to be an unused ONSSubscription instance.
        this._pendingONSObjects = new Map(pendingONSObjects);
        this._update();
    }

    @synchronized
    private async _update(tryAttempt: number = 0) {
        // Abort any retry attempts as we might need to remove, add
        // or update subscriptions which may cancel out previous
        // requests.
        this.abort();
        const ONSObjects = this._pendingONSObjects;

        //This makes a comparison of the "new" id's just added and the
        //previous assets that were added (watchedAssets);

        if (isDeepEqual(ONSObjects, this._watchedONSObjects)) {
            if (this._lastError) {
                // If we had an error creating or updating the subscription, but then we revert back to the
                // previous state, we need to clear the error otherwise we'll be stuck with an error!
                this._lastError = undefined;
                // Emit a change event to tell ONSInterface that we can begin
                // the longpoll request.
                this.emit(CHANGE);
            } else if (this._initializedFromCache) {
                // If we initialized the subscription with information
                // from the cache and the assets being added by the client
                // are exactly the same, we still want to notify the ONSInterface
                // that it can begin the longpoll request otherwise it wont.
                this.emit(CHANGE, new ONSSubscriptionChangeEvent(true));
            }
            // Do not notify when the subscription already has zero objects monitored. This is because
            // ONSWorker updates every ONSSubscriptions, even unused ones. Tests only care about
            // active subscriptions, whether or not they changed.
            if (this._watchedONSObjects.size > 0) {
                // Notify tests that the work needed to update this subscription has completed.
                this._onsContext.emit(TEST_ONLY_SUB_CHANGED);
            }
            return;
        }

        this.logInfo(`Setting ${ONSObjects.size} object Id(s) for ${this.subscriptionId || '<pending subscription id>'}`);

        try {
            if (ONSObjects.size === 0) {
                this.logInfo(`Deleting subscription ${this.subscriptionId} (requested objects no longer exist)`);
                this.monitoringStatus = SubscriptionMonitoringStatus.Inactive;
                await this._deleteSubscriptionFromServer();
            } else if (this._subscriptionHref) {
                this.logDebug(
                    `Updating subscription ${this.subscriptionId} on the server with objects`,
                    ONSObjects,
                );
                await this._updateSubscriptionOnServer(ONSObjects);
            } else {
                this.logDebug(
                    `Creating new subscription with objects`,
                    ONSObjects,
                );
                this.monitoringStatus = SubscriptionMonitoringStatus.Inactive;
                await this._createSubscriptionOnServer(ONSObjects);
            }
            // Add the new ids to the "old" ids list so we can track changes later on when even newer ids are added to this subscription.
            this._watchedONSObjects = ONSObjects;
            this._lastError = undefined;
            this.emit(CHANGE);
            // Notify tests that the work needed to update this subscription has completed
            this._onsContext.emit(TEST_ONLY_SUB_CHANGED);
        } catch (err) {
            this.logError(`Error updating subscription ${this.subscriptionId}:`, err);
            this._lastError = err;
            this.emit(CHANGE);
            // Notify tests that the attempt to update a subscription failed
            this._onsContext.emit(TEST_ONLY_SUB_CHANGED, new SubChangeErrorEvent(err));

            // Schedule a retry for later if there's an error
            if (tryAttempt < MAX_RETRY_ATTEMPTS) {
                let retryAfter = (getRetryAfterHeader((err as any).response?.headers) || ONSSubscription.DEFAULT_RETRY_INTERVAL_SEC) * 1000;
                retryAfter = Math.max(MIN_RETRY_INTERVAL_MS, retryAfter);
                this._retryTimeout = setTimeout(() => {
                    this._retryTimeout = undefined;
                    this._update(tryAttempt + 1);
                },
                retryAfter);
            }
        }
    }

    private async _parseSubscriptionResponse(operation: string, getResponse: () => Promise<Response>) {
        const response = await getResponse();

        if (response.status < 200 || response.status >= 300) {
            let errMsg = `operation ${operation} with http response.status: ${response.status}`;

            if (response.status === 403) {
                const jsonError = await response.json();
                if (jsonError.type === ProblemType.SUBSCRIPTION_COUNT) {
                    errMsg = `Maximum number of subscriptions per user per device exceeded (${jsonError.max})`;
                }
            }

            this.logError(errMsg);
            throw SAMError.createWithResponseAndDescription(response, errMsg);
        }

        const json = await response.json();

        if (!json.id || !json._links || !json._links.self || !json._links.self.href) {
            const errMsg = `No subscription ID or href was returned in subscribe response.`;
            this.logError(errMsg);
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, errMsg, { response });
        }

        this._subscriptionId   = json.id;
        this._subscriptionHref = json._links.self.href;

        if (json.expiresAt) {
            this._expiresAt = json.expiresAt;
        }
    }

    private async _createRequestBody(onsObjects?: ONSObjectMap): Promise<string> {
        const objects = createObjectsRequestBody(onsObjects ?? this.watchedONSObjects);
        const deviceId = await this._core._environment.getDeviceId();
        const requestBody: ONSCreateRequestBody = {
            id: this.subscriptionId,
            objects,
            device: { id: deviceId },
            expiresAt: Date.now() + this._core._environment.getValue('ONS_SUBSCRIPTION_TIME_TO_LIVE')
        };
        return JSON.stringify(requestBody);
    }

    private async _createSubscriptionOnServer(onsObjects: ONSObjectMap): Promise<void> {
        const href = await this._onsContext.getLink(RelType.SUBSCRIPTION_CREATE);
        const requestBody = await this._createRequestBody(onsObjects);
        return this._parseSubscriptionResponse('create',
            () => this._core._environment.fetch(href, {
                method: 'POST',
                body: requestBody,
                authHeader: ONS_SUBSCRIPTION_AUTH_HEADER,
                headers: {
                    'Content-Type': ONS_SUBSCRIPTION_MIME_TYPE
                }
            }));
    }

    private async _updateSubscriptionOnServer(onsObjects: ONSObjectMap): Promise<void> {
        const operations: jsonpatch.OpPatch[] = [];
        onsObjects.forEach((properties: ONSObjectProperties, id: string) => {
            if (!this._watchedONSObjects.has(id)) {
                const item: jsonpatch.AddPatch = { 'op': 'add', 'path': '/objects/-', 'value': { id, ...properties } };
                operations.push(item);
            }
        });

        this._watchedONSObjects.forEach((properties: ONSObjectProperties, id: string) => {
            const newProperties = onsObjects.get(id);
            if (newProperties) {
                if (properties.type === 'asset' && newProperties.type === 'asset') {
                    const oldProps = properties as AssetProperties;
                    const newProps = newProperties as AssetProperties;
                    if (oldProps.directoryLevel !== newProps.directoryLevel) {
                        const item: jsonpatch.ReplacePatch = { 'op': 'replace', 'path': `/objects/id=${id}/directoryLevel`, 'value': newProps.directoryLevel };
                        operations.push(item);
                    }
                }
            } else {
                const item: jsonpatch.RemovePatch = { 'op': 'remove', 'path': `/objects/id=${id}` };
                operations.push(item);
            }
        });

        const requestBody: string = JSON.stringify(operations);

        try {
            await this._parseSubscriptionResponse('update',
                () => this._core._environment.fetch(this._subscriptionHref!, {
                    method: 'PATCH',
                    body: requestBody,
                    authHeader: ONS_SUBSCRIPTION_AUTH_HEADER,
                    headers: {
                        'Content-Type': JSON_PATCH_MIME_TYPE
                    }
                }));
            this.logDebug(`Updated subscription ${this._subscriptionId} on the server.`);
        } catch (err) {
            this.logError(`Error updating subscription ${this._subscriptionId} on the server:`, err);
            // If we get a 404 updating a subscription, we should fall back to creating a new subscription instead
            if ((err as SAMError).code === SAMErrorCode.NOT_FOUND) {
                this.logWarn(`Subscription ${this._subscriptionId} no longer exists`);
                this.logDebug(`Creating a new subscription for objects(s):`, onsObjects);
                this.monitoringStatus = SubscriptionMonitoringStatus.Inactive;
                this._subscriptionHref = undefined;
                return this._createSubscriptionOnServer(onsObjects);
            }
            throw err;
        }
    }

    private async _deleteSubscriptionFromServer(): Promise<void> {
        this.logInfo(`Deleting subscription ${this._subscriptionId}`);

        try {
            // Note: There's no way to reach this point with _subscriptionHref undefined, so we assert that it's defined
            await this._core._environment.fetch(this._subscriptionHref!, {
                method: 'DELETE',
                authHeader: ONS_SUBSCRIPTION_AUTH_HEADER
            });
        } catch (error) {
            // We tried.
            this.logError(`Unable to delete subscription: ${this._subscriptionHref}`, error);
        }

        // We clear the subscription even if we fail to delete it - ONS will auto-delete orphaned subscriptions after some time anyway,
        // so we don't need to be aggressive about retrying
        this._subscriptionId = undefined;
        this._subscriptionHref = undefined;
        this._expiresAt = undefined;
        this.monitoringStatus = SubscriptionMonitoringStatus.Inactive;
    }

    async refreshSubscriptionExpiryDate(): Promise<void> {
        this.logDebug(`Refreshing expiry date on subscription ${this.subscriptionId}`);
        const requestBody = await this._createRequestBody();
        return this._parseSubscriptionResponse(
            'update',
            () => this._core._environment.fetch(
                this.subscriptionHref!,
                {
                    method: 'PUT',
                    body: requestBody,
                    authHeader: ONS_SUBSCRIPTION_AUTH_HEADER,
                    headers: {
                        'Content-Type': ONS_SUBSCRIPTION_MIME_TYPE
                    }
                }
            )
        )
            .catch(() => {
                // We tried to update the expiry date on the subscription and failed
                // Lets try and update
                return this._update();
            });
    }

    private async _fetchChangeLogPage(changedAssets: Map<string, ONSChangedAssetInfo>): Promise<boolean> {
        const options = { subscriptionId: this._subscriptionId! };

        const href = this._nextChangeLogLinks
            ? getURLFromLinks(this._nextChangeLogLinks, RelType.GENERIC_NEXT, options)
            : await this._onsContext.getLink(RelType.ONS_CHANGELOG, options);

        // Note: Unlike the other ONS calls, this uses the standard Authorization header (other ONS calls use X-User-Token)
        // This is confusing and error-prone, so I'd like them to standardize on the Authorization header for all calls, but
        // we have to live with this inconsistency for now.
        // ONS introduced a new directive header, all clients are expected to pass ons-repometa to
        // indicate they are ready to handle compact URI for repository metadata resource
        const response = await this._core._environment.fetch(href, { headers: { 'directive': 'ons-repometa' } });

        if (response.status !== 200) {
            let errMsg = `Unexpected response fetching change log: ${response.status}`;
            // In the case that it's 403 and the type is
            // ONS_PROBLEM_LIMIT_CHANGELOGRETENTION this should mean that the
            // the current Changelog Token is expired and the we should get
            // a new "next" link.
            if (response.status === 403) {
                const parsedResponse = await response.json();
                if (parsedResponse.type === ProblemType.LIMIT_CHANGELOGRETENTION) {
                    errMsg = `Changelog retention period expired, discarding "next" link and fetching changelog again.`;
                    // When we throw an error below, it will cause the caller
                    // to retry this call and by setting _nextChangeLogLinks to undefined
                    // it will then fetch a new "next" link above.
                    this._nextChangeLogLinks = undefined;
                }
            }

            this.logError(errMsg);
            throw SAMError.createWithResponseAndDescription(response, errMsg);
        }
        const json = await response.json();

        // From the response, determine which asset ids changed
        const changedSubscriptions = json['ons:changedSubscriptions'] ?? [];
        const changedSubscription = changedSubscriptions.find((subscriptionInfo: any) => subscriptionInfo['ons:subscriptionId'] === this._subscriptionId);
        const changes = changedSubscription?.['ons:changes'] ?? [];
        changes.forEach((assetInfo: any) => {
            const assetId = assetInfo['repo:assetId'];
            const onsResourceInfo = assetInfo['ons:resources'] ?? [];
            const onsResourcesChanged: ONSResourceType[] = [ ...Object.keys(onsResourceInfo) as ONSResourceType[] ];
            const parentAssetId = assetInfo['ons:subscribedDirectoryAssetId'];
            const annotationId: string | undefined = onsResourceInfo['api:annotation']?.['repo:resource']?.['annotation_id'];
            const plsAssetListId = assetInfo['ons:subscribedAssetListId'] ?? undefined;
            const labels = Object.keys(assetInfo['asset:labels'] ?? {}) as ONSAssetLabel[];
            if (assetId) {
                // If the asset is already in changedAssets, merge the next changed resource so we
                // don't lose any previous resources that were added here.
                if (changedAssets.has(assetId)) {
                    const existingAsset = changedAssets.get(assetId)!;
                    existingAsset.changedResources = [ ...new Set([ ...existingAsset.changedResources!, ...onsResourcesChanged ]) ];

                    if (annotationId) {
                        existingAsset.annotationIds = [ ...new Set([ ...(existingAsset.annotationIds || []), ...[ annotationId ] ]) ];
                    }

                    if (labels.length > 0) {
                        existingAsset.changedLabels = [
                            ...new Set([ ...(existingAsset.changedLabels || []), ...labels ])
                        ];
                    }
                    plsAssetListId && (existingAsset.plsAssetListId = plsAssetListId);
                    changedAssets.set(assetId, existingAsset);
                } else {
                    changedAssets.set(assetId, {
                        parentAssetId,
                        changedLabels: labels,
                        changedResources: onsResourcesChanged,
                        plsAssetListId,
                        ...(annotationId && { annotationIds: [ annotationId ] })
                    });
                }
            }
        });

        this._nextChangeLogLinks = json?._links;
        return this._nextChangeLogLinks?.next?.nextPage;
    }

    /**
     * Fetch the changed assets ids in the subscription, and emit a change event on the parent ONS Interface for any changed assets.
     * The reason this API emits events rather than just returning the changed assets is so we can have robust retry logic - if it fails
     * to fetch the change log it'll schedule a retry with an appropriate backoff, so it automatically recovers. The ONS Interface can
     * simply call fetchAndNotifyChanges on a subscription that it knows has changes, and the subscription will take responsibility for
     * eventually fetching and emitting notifications for these changes, even if it has to retry.
     *
     * This API is stateful, so if you call it when the subscription changed, it will emit a change event for those assets, but if you call it
     * again (and there are no further changes), it will not emit an event.
     */
    @synchronized
    async fetchAndNotifyChanges(attempt: number = 0): Promise<void> {
        this.logInfo(`Fetching ChangeLog for subscription ${this._subscriptionId}...`);

        // If we got another notification of a change, this causes us to retry immediately, and cancels any pending retry
        if (this._retryChangeLogTimeout) {
            clearTimeout(this._retryChangeLogTimeout);
        }

        const retry = (error: any) => {
            const retryAfter = getRetryAfterHeader(error.response?.headers) * 1000;
            const interval = Math.max(retryAfter, this._core._environment.getRetryInterval(attempt));

            this.logInfo(`Retrying change log fetch in ${interval}ms`);
            this._retryChangeLogTimeout = setTimeout(() => this.fetchAndNotifyChanges(attempt + 1), interval);
        };

        const changedAssets: Map<string, ONSChangedAssetInfo> = new Map();
        try {
            let hasMorePages = true;
            while (hasMorePages) {
                hasMorePages = await this._fetchChangeLogPage(changedAssets);
            }
        } catch (error) {
            this.logError(`Error fetching change log`, error);
            retry(error);
        }

        // Even if there's an error, we always notify of any changes we did manage to fetch - for example, if the
        // first page succeeded, but the second page didn't, when we retry we'll retry from the second page.
        if (changedAssets.size) {
            this.logDebug(`Changed asset(s):`, changedAssets);
            this._onsContext.emit(CHANGE, new ONSAssetChangeEvent(changedAssets));
        }
    }

    // This is called to check whether the subscription still exists on the server.
    // The ONS long poll will sometimes request the client to
    // validate its subscriptions. If the subscription was deleted, it'll recreate it.
    async validate() {
        if (!this._subscriptionHref) {
            // If we're requesting to watch at least one asset id, and don't have a subscription at all,
            // something must have gone wrong creating it - we attempt to create again.
            if (this._pendingONSObjects.size > 0) {
                this.logWarn(`Objects exist for subscription but no _subscriptionHref was found, trying to _update() again...`);
                return this._update();
            }
            this.logDebug(`Subscription has no assets and no _subscriptionHref set`);
            return;
        }

        let checkResponse;
        try {
            // ONS spec says to GET (vs HEAD). Why?
            checkResponse = await this._core._environment.fetch(this._subscriptionHref, {
                authHeader: ONS_SUBSCRIPTION_AUTH_HEADER
            });
            this.logInfo(`Subscription ${this._subscriptionId} exists on the server`);
        } catch (error) {
            this.logError(`Error checking ${this._subscriptionId}, it does not exist on the server`, error);
            return;
        }

        // If we can't find the subscription, we need to make a new one.
        if (![ 200, 201, 204 ].includes(checkResponse.status)) {
            this.logInfo(`ONS subscription has been invalidated. Creating new subscription...`);
            this.monitoringStatus = SubscriptionMonitoringStatus.Inactive;
            this._subscriptionHref = undefined;
            this._subscriptionId = undefined;
            this._watchedONSObjects = new Map();
            return this._update();
        }
    }

    /**
     * Logs a debug message.
     * @param message - Message to log.
     * @param optionalParams - Optional objects to stringify and log after the message.
     */
    logDebug(message: string, ...optionalParams: any[]) {
        this._onsContext.logger.logDebug(message, 'Subscription', ...optionalParams);
    }

    /**
     * Logs an info message.
     * @param message - Message to log.
     * @param optionalParams - Optional objects to stringify and log after the message.
     */
    logInfo(message: string, ...optionalParams: any[]) {
        this._onsContext.logger.logInfo(message, 'Subscription', ...optionalParams);
    }

    /**
     * Logs a warning message.
     * @param message - Message to log.
     * @param optionalParams - Optional objects to stringify and log after the message.
     */
    logWarn(message: string, ...optionalParams: any[]) {
        this._onsContext.logger.logWarn(message, 'Subscription', ...optionalParams);
    }

    /**
     * Logs an error message.
     * @param message - Message to log.
     * @param optionalParams - Optional objects to stringify and log after the message.
     * @remarks If the first optional parameter is an Error object, the message will be appended with the error message.
     */
    logError(message: string, ...optionalParams: any[]) {
        this._onsContext.logger.logError(message, 'Subscription', ...optionalParams);
    }
}
