import type {
    IComparatorMap
} from '../core/ItemOrder';
import {
    compareStrings,
    createItemOrderFactory
} from '../core/ItemOrder';
import type AddressBook from './AddressBook';

export type AddressBookOrderField = 'displayName';

const OrderFieldToComparator: IComparatorMap<AddressBook, AddressBookOrderField> = {
    displayName(a: AddressBook, b: AddressBook): number {
        return compareStrings(a.displayName, b.displayName);
    }
};

export default class AddressBookOrder extends createItemOrderFactory(OrderFieldToComparator) {
    static default = new AddressBookOrder('ascending', 'displayName');
}
