import type AdobeAsset from '../../assets/AdobeAsset';
import type {
    IItemLoader,
    IItemLoaderOptions,
    ILoadNextPage,
    ILoadedPage,
} from '../../core/ItemLoader';
import type ItemPool from '../../core/ItemPool';
import type { ISAMCorePrivate } from '../../indexPrivate';
import type LegacyCustomModelInterface from './LegacyCustomModelInterface';
import type LegacyCustomModel from './LegacyCustomModel';
import { LegacyCustomModelUpdater } from './LegacyCustomModel';
import type LegacyCustomModelFilter from './LegacyCustomModelFilter';
import { LegacyOrderFieldToCustomModelOrderBy } from './LegacyCustomModelOrder';
import type { LegacyCustomModelSearchConfig } from './LegacyCustomModelSource';

export default class CustomModelSearchLoader implements IItemLoader<LegacyCustomModelSearchConfig> {
    constructor(
        private _assetPool: ItemPool<LegacyCustomModel | AdobeAsset>,
        private _core: ISAMCorePrivate,
        private _customModelInterface: LegacyCustomModelInterface
    ) {}

    supportsFilter(filter?: LegacyCustomModelFilter): boolean {
        // If we don't provide a filter at all, then we cannot use the loader
        return filter !== undefined;
    }

    async loadPage(options: IItemLoaderOptions<LegacyCustomModelSearchConfig>) {
        return this._loadPage(options);
    }

    private async _loadPage(options: IItemLoaderOptions<LegacyCustomModelSearchConfig>, startIndex?: number): Promise<ILoadedPage<LegacyCustomModelSearchConfig>> {
        const { order, implicitFilter, filter } = options;
        const { limit } = options.loadOptions ?? {};
        const customModelSearchFilter = implicitFilter;
        const customModelFilter = filter as LegacyCustomModelFilter;
        const listingOptions = ('listingOptions' in customModelFilter && customModelFilter['listingOptions']) || [];

        const listOptions = {
            orderBy: LegacyOrderFieldToCustomModelOrderBy[order.field],
            limit,
            ...listingOptions,
            name: customModelSearchFilter.query
        };
        const result = await this._customModelInterface.getCustomModels(
            startIndex ? { ...listOptions, startIndex } : listOptions
        );
        const session = this._assetPool.createLoaderUpdateSession<LegacyCustomModel>(
            Date.now() - this._core._environment.getValue('USS_LIST_UPDATE_LATENCY')
        );
        const items = LegacyCustomModelUpdater.updateRemoteItems(session, result.items);
        session.commit();

        // Check if we have another page to load.
        let loadNextPage: ILoadNextPage<LegacyCustomModelSearchConfig> | undefined;
        const nextPageLink = result.nextPage?.startIndex;
        if (nextPageLink) {
            loadNextPage = (options: IItemLoaderOptions<LegacyCustomModelSearchConfig>) =>
                this._loadPage(options, nextPageLink);
        }

        implicitFilter!._matchingIDsFromSearch = new Set([
            // copy existing, if needed
            ...(implicitFilter!._matchingIDsFromSearch || []),
            ...(items.map(item => item.id)) ]);

        return {
            items,
            loadNextPage,
            total: result.total
        };
    }
}
