import type { SAM } from '@ccx-public/component-types';
import ItemUpdater from '../core/ItemUpdater';
import ItemBase from '../core/ItemBase';
import PropertyUpdater from '../core/PropertyUpdater';
import type { IGradientColorRGB, IGradientColorStop, IGradientComputedItemResponse } from '../interface/GradientModel';

export class Gradient extends ItemBase implements SAM.Gradient {
    private _isDefault: boolean = false;
    private _type: string = '';
    private _angle: number = 0;
    private _stops: IGradientColorStop[] = [];
    private _name: string = '';
    private _languageCode: string = '';
    private _gradientID: string = '';
    private _textAlpha: number = 1;
    private _textMode: string = 'RGB';
    private _textColorValue: IGradientColorRGB = { r: 0, g: 0, b: 0 };
    private _textType: string | 'process' = 'process';

    get isDefault() {
        return this._isDefault;
    }

    get type(): string {
        return this._type;
    }

    get angle(): number {
        return this._angle;
    }

    get stops(): IGradientColorStop[] {
        return this._stops;
    }

    get name(): string {
        return this._name;
    }

    get languageCode(): string {
        return this._languageCode;
    }

    /**
     * The original non-computed gradient ID to be used when
     * assigning a gradient to a Project.
     */
    get gradientID(): string {
        return this._gradientID;
    }

    get textAlpha(): number {
        return this._textAlpha;
    }

    get textMode(): string {
        return this._textMode;
    }

    get textColorValue(): IGradientColorRGB {
        return this._textColorValue;
    }

    get textType(): 'process' | string {
        return this._textType;
    }
}

export const GradientUpdater = new ItemUpdater<Gradient, Partial<IGradientComputedItemResponse>>({
    localItemType: Gradient,
    /**
     * The computedID is property that is computed based on the
     * gradientId from the service, and the language code from the service.
     * It typically looks something like. 'FUSCHIA-en-US'. This helps
     * us store and retrieve the gradients by not just id but also language to
     * make it more performant if the user switches languages during runtime.
     * IGradientComputedItemResponse extends IGradientItemResponse to include
     * the computedID property.
     */
    remoteIdProperty: 'computedID',
    propertyUpdater: new PropertyUpdater({
        '_isDefault': { name: 'project:gradientData.isDefault', format: 'boolean' },
        '_type': { name: 'project:gradientData.type', format: 'string' },
        '_angle': { name: 'project:gradientData.angle', format: 'string' },
        '_name': { name: 'project:gradientName', format: 'string' },
        '_stops': { name: 'project:gradientData.stops', format: 'object' },
        '_languageCode': { name: 'project:gradientData.languageCode', format: 'string' },
        '_gradientID': 'project:gradientId',
        '_textAlpha': { name: 'project:gradientTextColor.alpha', format: 'number' },
        '_textMode': { name: 'project:gradientTextColor.mode', format: 'string' },
        '_textColorValue': { name: 'project:gradientTextColor.value', format: 'object' },
        '_textType': { name: 'project:gradientTextColor.type', format: 'string' }
    })
});
