import type { MRUAdobeAssetConfig } from './MRUAdobeAssetSource';
import type { PLSListResponse } from '../graphql/models/PLSModels';
import type { AssetListFilter, PlsRecentsQuery } from '../graphql/generated/types';
import PLSListLoader from '../graphql/PLSListLoader';
import type Resource from './Resource';
import type { AdobeAssetUpdaterMetadata } from './AdobeAsset';

export default class PLSRecentAdobeAssetLoader extends PLSListLoader<PlsRecentsQuery, MRUAdobeAssetConfig> {
    async _getPLSData({ first, after, filter, resource }: {
        first: number;
        after?: string;
        filter: AssetListFilter;
        order: MRUAdobeAssetConfig['order'],
        resource?: Resource
    }, processIncrementalData: (incrementalData: PlsRecentsQuery) => void): Promise<PLSListResponse<AdobeAssetUpdaterMetadata>> {
        const gqlManager = await this._core._getGQLManager();
        return await gqlManager.recents({
            first,
            after,
            filter,
        }, resource, processIncrementalData);
    }

    getAssetNodesFromData(incrementalData: PlsRecentsQuery) {
        return incrementalData.recents.assetListConnection.edges.map(edge => {
            // The generated types for for the query are slightly overspecified by codegen, so a cast is needed here
            return edge.node as any;
        });
    }
}
