import type { RelType } from '../interface/LinkUtils';
import type ISAMCorePrivate from '../core/ISAMCorePrivate';
import type { ISAMObject } from '../core/ISAMObject';
import type {
    AccessControlPrivileges,
    IAccessControlPrincipal } from './AccessControlModel';
import {
    AccessControlInheritance,
    AccessControlModifier,
    RelTypePlatform
} from './AccessControlModel';
import SAMError, { SAMErrorCode } from '@sam-js-src/core/SAMError';

export default class AdobeACE implements ISAMObject {
    private __isDirty: boolean = false;
    private __isDeleted: boolean = false;
    constructor(
        public readonly _core: ISAMCorePrivate,
        /**
         * Corresponds to the index of the ACE in the ACL response array.
         */
        public readonly id: number,
        private _privileges: AccessControlPrivileges[],
        private _modifier: AccessControlModifier,
        private _inheritance: AccessControlInheritance,
        private _relations: RelType[],
        private _principal: IAccessControlPrincipal | string // @TODO this should be specific values for "special" principals instead of strings.
    ) {}

    private _checkIfDeleted(): void {
        if (this.__isDeleted) {
            throw SAMError.create(
                SAMErrorCode.BAD_REQUEST,
                'Cannot update a deleted ACE'
            );
        }
    }

    /**
     * Whether this ACE has been modified since it was last committed to the server.
     * @package - This property is intended for internal use only.
     */
    public get _isDirty(): boolean {
        return this.__isDirty;
    }

    /**
     * @package - This property is intended for internal use only.
     */
    public set _isDirty(value: boolean) {
        this.__isDirty = value;
    }

    /**
     * @package - This property is intended for internal use only.
     */
    public set _isDeleted(value: boolean) {
        this.__isDeleted = value;
    }

    /**
     * @package - This property is intended for internal use only.
     */
    public get _isDeleted(): boolean {
        return this.__isDeleted;
    }

    public get principal(): IAccessControlPrincipal | string {
        return this._principal;
    }

    public set principal(value: IAccessControlPrincipal | string) {
        this._checkIfDeleted();
        this._principal = value;
        this._isDirty = true;
    }

    public get privileges(): AccessControlPrivileges[] {
        return this._privileges;
    }

    public set privileges(value: AccessControlPrivileges[]) {
        this._checkIfDeleted();
        this._privileges = value;
        this._isDirty = true;
    }

    public get modifier(): AccessControlModifier {
        return this._modifier;
    }

    public set modifier(value: AccessControlModifier) {
        this._checkIfDeleted();
        this._modifier = value;
        this._isDirty = true;
    }

    public get inheritance(): AccessControlInheritance {
        return this._inheritance;
    }

    public set inheritance(value: AccessControlInheritance) {
        this._checkIfDeleted();
        this._inheritance = value;
        this._isDirty = true;
    }

    public get relations(): RelType[] {
        return this._relations;
    }

    public set relations(value: RelType[]) {
        this._checkIfDeleted();
        this._relations = value;
        this._isDirty = true;
    }

    public get isDeny(): boolean {
        return this._modifier === AccessControlModifier.DENY;
    }

    public get isGrant(): boolean {
        return this._modifier === AccessControlModifier.GRANT;
    }

    public get isDeepInheritance(): boolean {
        return this._inheritance === AccessControlInheritance.DEEP;
    }

    public get isSelfInheritance(): boolean {
        return this._inheritance === AccessControlInheritance.SELF;
    }

    public get isDeepOverrideInheritance(): boolean {
        return this._inheritance === AccessControlInheritance.DEEP_OVERRIDE;
    }

    public get isUserPrincipal(): boolean {
        if (typeof this._principal === 'string') {
            return false;
        }
        return this._principal['@type'] === RelTypePlatform.PRINCIPAL_TYPE_IMS_USER;
    }

    public get isGroupPrincipal(): boolean {
        if (typeof this._principal === 'string') {
            return false;
        }
        return this._principal['@type'] === RelTypePlatform.PRINCIPAL_TYPE_IMS_GROUP;
    }
}
