/**
 * BatchOperation
 * @packageDocumentation
 * @module BatchOperation
 * @internal
 */

import type { default as CloudDriver } from '../../drivers/CloudDriver';
import type { ElementData } from '../../models/data/ElementData';
import type { LibraryData } from '../../models/data/LibraryData';
import type { Action, UpdateAction, InsertAction, RemoveAction, AggregateAction } from '../../models/Action';

import type { ExecuteResult } from '../Operation';
import Operation, { validatesOperation } from '../Operation';
import type {
    ElementRequest,
    ElementMetadataRequest,
    LibraryRequest,
    GroupRequest
} from './utils/melvilleModelMappers';
import {
    mapLibraryDataToRequest,
    mapElementDataToElementMetadata,
    mapElementDataToRequest,
    mapGroupDataToRequest,
    mapResponseToLibraryData,
    mapResponseToElementData,
    mapResponseToGroupData
} from './utils/melvilleModelMappers';

import { extractElementId, extractGroupId } from '../../utils/PathUtils';
import { replacePlaceholders } from '../../utils/StoreUtils';
import type { MelvilleRESTOperation } from '../utils/operationUtils';
import { tokenizePlaceholders } from '../utils/operationUtils';
import LibraryError from '../../errors/LibraryError';
import { omitUndefined } from '../../drivers/utils/operationUtils';
import type { GroupData } from '../../models/data/GroupData';
import { trace, traceableAs } from '../../../core/decorators/trace';

const supportedActionNames = [
    'updateLibrary',
    'createElement',
    'updateElement',
    'removeElement',
    'restoreElement',
    'deleteElement',
    'createGroup',
    'removeGroup'
] as const;

type SupportedAction = Action & {
    name: (typeof supportedActionNames)[number];
};

function isSupportedAction(action: Action): action is SupportedAction {
    return supportedActionNames.includes(action.name as any);
}

function replaceData<T>(action: Action, data: T): Action {
    return { ...action, data, originalAction: action };
}

const RESPONSE_MAPPERS: {
    [s in (typeof supportedActionNames)[number]]: (action: Action, data?: any) => Action;
} = {
    updateLibrary: (action, data) => {
        // Melville does not return ACLs on patch response, so omit any data that is undefined/missing from response
        const responseData = omitUndefined(mapResponseToLibraryData(data, false, false), [
            'documentId',
            'documentType',
            'roles'
        ]);
        return replaceData(action, responseData);
    },
    createElement: (action, data) => replaceData(action, mapResponseToElementData(data.elements[0])),
    updateElement: (action, data) => replaceData(action, mapResponseToElementData(data.elements[0])),
    restoreElement: action => action,
    removeElement: action => action,
    deleteElement: action => action,
    createGroup: (action, data) => replaceData(action, mapResponseToGroupData(data)),
    removeGroup: action => action
};

@traceableAs('BatchOperation')
export default class BatchOperation extends Operation<CloudDriver> {
    private _baseLibraryOperationPath = `/api/v1/libraries/${this._library.assetId}`;
    private _actionMappers = {
        updateLibrary: (action: UpdateAction<LibraryData>): MelvilleRESTOperation<Partial<LibraryRequest>> => ({
            method: 'PUT',
            path: `metadata`,
            body: mapLibraryDataToRequest(action.data)
        }),
        createElement: (action: InsertAction<ElementData>): MelvilleRESTOperation<Partial<ElementRequest>> => ({
            method: 'POST',
            path: `elements`,
            body: mapElementDataToRequest(action.data, this._driver.getClientInfo())
        }),
        updateElement: (action: UpdateAction<ElementData>): MelvilleRESTOperation<ElementMetadataRequest> => ({
            method: 'PUT',
            path: `elements/metadata`,
            body: {
                elements: [
                    mapElementDataToElementMetadata({ id: extractElementId(action.path as string), ...action.data })
                ]
            }
        }),
        removeElement: (action: RemoveAction | AggregateAction): MelvilleRESTOperation<void> => ({
            method: 'DELETE',
            path: `elements/${extractElementId(action.path as string)}`
        }),
        restoreElement: (action: AggregateAction): MelvilleRESTOperation<{ elementIds: string[] }> => ({
            method: 'POST',
            path: `archive`,
            body: {
                elementIds: [ `${action.data.id}` ]
            }
        }),
        deleteElement: (action: RemoveAction | AggregateAction): MelvilleRESTOperation<void> => ({
            method: 'DELETE',
            path: `elements/${extractElementId(action.path as string)}`,
            query_params: { permanent: 'true' }
        }),
        createGroup: (action: InsertAction<GroupData>): MelvilleRESTOperation<GroupRequest> => ({
            method: 'POST',
            path: `groups`,
            body: mapGroupDataToRequest(action.data, this._driver.getClientInfo())
        }),
        removeGroup: (action: RemoveAction | AggregateAction): MelvilleRESTOperation<void> => ({
            method: 'DELETE',
            path: `groups/${extractGroupId(action.path as string)}`,
            query_params: action.flags?.includeElements ? { include_contents: 'true' } : undefined
        })
    };

    protected _actions: SupportedAction[] = [];

    @validatesOperation
    @trace
    async execute(): Promise<ExecuteResult> {
        const payload = this._actions.map(action => this._actionMappers[action.name](action as never));
        const tokenizedPayload = tokenizePlaceholders(payload);
        const response = await this._driver.fetch(this._baseLibraryOperationPath, {
            method: 'PATCH',
            headers: {
                'Content-Type': 'application/json',
                'If-Match': this._library.etag
            },
            body: JSON.stringify({
                requests: tokenizedPayload.map(r => ({
                    ...r,
                    path: `${this._baseLibraryOperationPath}/${r.path}`
                }))
            })
        });

        const { responses } = await response.json();

        // Response should be an array that's the same size as the number of actions in the batch
        if (!Array.isArray(responses) || responses.length !== this._actions.length) {
            throw new LibraryError('INVALID_RESPONSE', 'Malformed batch response.', this._library.id);
        }

        // Given the responses, map the actual response onto actions and return the new actions.
        let newActions = this._actions.map((action, index) => {
            return RESPONSE_MAPPERS[action.name](action, responses[index]);
        });

        // Replace any placeholders that might exist in the new actions
        newActions = replacePlaceholders(newActions);

        return { actions: newActions, etag: response.headers.get('ETag') as string };
    }

    supportsAction(action: Action) {
        return isSupportedAction(action);
    }
}
