import type { RequiredStudentAssignmentFilterOptions } from '../interface/StudentAssignmentModel';
import type AdobeAsset from '../assets/AdobeAsset';
import type { IImplicitFilter } from '../core/ItemFilter';
import type StudentAssignment from './StudentAssignment';

export default class ImplicitStudentAssignmentFilter implements IImplicitFilter<StudentAssignment> {
    public readonly assignmentCode: string;
    public readonly assignmentId: string;
    /**
     * @package -- only for use in SAM.js
     */
    public _monitoredFolder?: AdobeAsset;

    constructor(options: RequiredStudentAssignmentFilterOptions) {
        const { assignmentCode, assignmentId } = options || {};
        // default values for assignment code and id are empty strings, match for ensuring comparisons work correctly
        this.assignmentCode = assignmentCode || '';
        this.assignmentId = assignmentId || '';
    }
    matches(item: AdobeAsset | StudentAssignment): boolean {
        if (!this.assignmentId && !this.assignmentCode) {
            throw new Error('Getting StudentAssignments across Assignments is not supported at this time');
        }

        if (!item.isStudentAssignment) {
            return false;
        }

        const studentAssignmentItem = item as StudentAssignment;

        // either this.assignmentId or this.assignmentCode should be non-empty
        if (this.assignmentId && (this.assignmentId !== studentAssignmentItem.assignmentId)) {
            return false;
        }

        if (this.assignmentCode && (this.assignmentCode !== studentAssignmentItem.assignmentCode)) {
            return false;
        }

        return true;
    }
}
