import BaseError from '../errors/BaseError';
import type { UserData } from '../models/data/ConfigurationData';

export function sleep(time: number, signal?: AbortSignal) {
    return new Promise<void>((resolve, reject) => {
        const doReject = () => {
            clearTimeout(timeout);
            signal?.removeEventListener('abort', doReject);
            reject(new DOMException('Request aborted', 'AbortError'));
        };

        const timeout = setTimeout(() => {
            signal?.removeEventListener('abort', doReject);
            resolve();
        }, time);

        if (signal) {
            signal.addEventListener('abort', doReject);

            // Signal might already have been aborted
            if (signal.aborted) {
                doReject();
            }
        }
    });
}

function isUpperSnakeCase(value: string): boolean {
    return /^[A-Z_]*$/.test(value);
}

export function toLowerCamel(value: string): string {
    if (!isUpperSnakeCase(value)) {
        throw new BaseError('String must be upper snake case to convert');
    }

    return value.toLowerCase().replace(/_([a-z])/g, (match, backReference) => {
        return backReference.toUpperCase();
    });
}

export function debounceDecorator(wait: number) {
    let timeoutId: any;

    return function _debounceDecorator(target: any, key: string, descriptor: PropertyDescriptor) {
        const method = descriptor.value;
        descriptor.value = function debouncedMethod(...args: Array<any>) {
            clearTimeout(timeoutId);
            timeoutId = setTimeout(() => method.apply(this, args), wait);
        };
    };
}

export function getScopedStorageKey(user: UserData['user'], mode: 'local' | 'cloud') {
    return `CCLibraries_${user?.id}_${mode}`;
}

export enum SignalType {
    RESOLVE,
    REJECT
}
export function timoutFutureFactory(signal: SignalType, timeout: number) {
    let timeoutId: any;

    const future = new Promise<void>((...args) => {
        timeoutId = setTimeout(args[signal], timeout);
    });

    return { future, cancel: () => clearTimeout(timeoutId) };
}
