import type { IOrderDirection } from '../core/ItemOrder';
import InterfaceBase from './InterfaceBase';
import type { ISearchQuery, ISearchSortOrderDirection, USSResponse } from './USSModel';
import { SearchProps } from './USSModel';
import type { ISWYAdobeAssetOrderBy } from './AssetModel';
import { getUSSFetchFields } from './AssetModel';
import {
    updateAssetTypeForUSS
} from './USSUtils';
import { FOLDER_TYPE } from './AssetInterface';
import type Resource from '../assets/Resource';
import { excludeExpressArtifacts } from '../utils/excludeExpressArtifacts';

type IPageOptions = {
    limit: number;
    start?: number;
}

interface IListingOptions<IOrderField> extends IPageOptions {
    orderDirection: IOrderDirection;
    orderBy: IOrderField;
}

export interface SWYAssetsListingOptions extends IListingOptions<ISWYAdobeAssetOrderBy> {
    mediaTypes?: string[],
    excludeMediaTypes?: string[],
    embedPermissions?: boolean,
}

const DefaultSWYAssetsListingOptions: SWYAssetsListingOptions = {
    orderDirection: 'descending',
    orderBy: 'shared_date',
    start: 0,
    limit: 0,
    mediaTypes: [],
    excludeMediaTypes: [],
};

export function getDirectionValue(userOptions: Partial<SWYAssetsListingOptions>): ISearchSortOrderDirection {
    const directionFlag = userOptions.orderDirection === 'ascending' ? 'asc' : 'desc';
    return directionFlag;
}

export default class SWYInterface extends InterfaceBase {

    async getSWYAssets(options?: Partial<SWYAssetsListingOptions>, resource?: Resource): Promise<USSResponse> {
        options = { ...DefaultSWYAssetsListingOptions, ...options };
        updateAssetTypeForUSS(options.mediaTypes);
        options.excludeMediaTypes = [ ...new Set<string>(options.excludeMediaTypes!.concat(FOLDER_TYPE)) ];
        updateAssetTypeForUSS(options.excludeMediaTypes);
        const filters: ISearchQuery = {
            shared_via_invite: true,
            hints: {
                acp_platform_v2: true,
            },
            fetch_fields: { includes: getUSSFetchFields() },
            op_none_of: [
                {
                    op_field_exists: [
                        'app_metadata$$cc:inheritable$$cc:team$$repo:assetId',
                        // for excluding the older spaces and its children
                        // We would want to show project children, but not projects themselves in swy
                        'app_metadata$$cc:inherited$$cc:space$$repo:assetId',
                        'app_metadata$$cc:inheritable$$cc:space$$repo:assetId'
                    ],
                },
                {
                    [SearchProps.VISIBILITY]: [ 'hiddenSelf', 'hiddenRecursive' ],
                },
                {
                    [SearchProps.CREATIVE_CLOUD_TOPLEVEL_COLLECTION_NAME]: 'appdata',
                },
                {
                    [SearchProps.TYPE]: options.excludeMediaTypes || [],
                },
                {
                    [SearchProps.STORAGE_ASSIGNEE_ID]: this._core._environment.getValue('USER_ID'),
                },
                // SAMJS-773
                ...excludeExpressArtifacts(),
            ],
            [SearchProps.TYPE]: options.mediaTypes || [],
            sort_orderby: options.orderBy,
            sort_order: getDirectionValue(options),
            limit: options.limit,
            start_index: options.start,
        };

        if (options.embedPermissions) {
            filters.fetch_fields!.includes.push('_embedded');
        }

        const response = await this._core.hostAssetContext._ussInterface.getQueryResponse(filters, resource);
        return response;
    }
}
