/**
 * Group
 * @packageDocumentation
 * @module Group
 */

import type { GroupData } from './data/GroupData';
// @ts-expect-error R-TODO
import type Library from './Library';
import type Element from './Element';
import type { Action, ActionName } from './Action';

import observable from '../utils/observable';
import { requiresWrite } from './utils/AccessUtils';
import { createPlaceholderId } from './utils';
import PublishedModel from './PublishedModel';
import { mapAttributesToArray } from './utils/AttributeUtils';
import type { Optional } from '../types';

export default class Group extends PublishedModel<GroupData> {
    isGroup = true;

    private _isDeletedLocally = false;
    protected _updateAction: ActionName = 'updateGroup';

    // TODO-R: Temporarily avoids breaking code. When updating this file to use ItemUpdater Pattern, remove this.
    private _data: GroupData = {} as GroupData;
    get data(): GroupData {
        return this._data;
    }

    get classifierName(): string {
        return this.data.classifier;
    }

    @observable
    @requiresWrite
    get name(): string {
        return this.data.name;
    }

    set name(name: string) {
        this._actionDispatch({
            name: 'updateGroup',
            type: 'update',
            data: { name }
        });
    }

    @observable
    @requiresWrite
    get order(): string {
        return this.data.order;
    }

    set order(order: string) {
        this._actionDispatch({
            name: 'updateGroup',
            type: 'update',
            data: { order }
        });
    }

    @observable
    get modified(): number {
        return this.data.modifiedDate as number;
    }

    @observable
    get modifiedBy(): string {
        return this.data.modifiedBy as string;
    }

    @observable
    get modifiedContext(): any {
        return this.data.modifiedContext;
    }

    @observable
    get wasModifiedLocally(): boolean {
        return this.data.modifiedLocally as boolean;
    }

    @observable
    get created(): number {
        return this.data.createdDate as number;
    }

    @observable
    get createdBy(): string {
        return this.data.createdBy as string;
    }

    @observable
    get createdContext(): any {
        return this.data.createdContext;
    }

    @observable
    get wasCreatedLocally(): boolean {
        return this.data.createdLocally as boolean;
    }

    @observable
    getValue(namespace: string, key: string): any {
        return this.data.customData?.[`${namespace}#${key}`];
    }

    @observable
    getValues(): { namespace: string; key: string; value: any }[] {
        return mapAttributesToArray(this.data.customData as { [s: string]: any });
    }

    @observable
    get children() {
        // @ts-expect-error // TODO: Fix this
        return this.library.getGroups(this.classifierName).filter(group => group.parent && group.parent.id === this.id);
    }

    @observable
    getFilteredChildren(predicate: (group: Group) => boolean) {
        return this.children.filter(predicate);
    }

    @observable
    get elements(): Element[] {
        const elements: Element[] = [];
        const processElement = (element: Element) =>
            element.getOrderInGroup(this) !== undefined && elements.push(element);
        this.library.elements.forEach(processElement);
        this.library.documentationElements.forEach(processElement);
        return elements;
    }

    /**
     * Returns true if the group has no child groups and no elements associated
     */
    @observable
    isEmpty(): boolean {
        return this.elements.length === 0 && this.children.length === 0;
    }

    @requiresWrite
    setValue(namespace: string, key: string, value: any, _isMetadata?: boolean): void {
        this._actionDispatch({
            name: 'updateGroup',
            type: 'update',
            data: {
                customData: {
                    ...this.data.customData,
                    [`${namespace}#${key}`]: value
                }
            }
        });
    }

    @requiresWrite
    removeValue(namespace: string, key: string, isMetadata?: boolean): void {
        this.setValue(namespace, key, null, isMetadata);
    }

    /**
     * @deprecated
     */
    @observable
    get isDeletedLocally(): boolean {
        return this._isDeletedLocally;
    }

    set isDeletedLocally(isDeletedLocally) {
        this._isDeletedLocally = isDeletedLocally;
        this.emit('change');
    }

    get library(): Library {
        return this._parent as Library;
    }

    @observable
    getLocalizedName(locale: string = 'en_US'): string {
        return this.data.localizedNames?.[locale] as string;
    }

    @observable
    getLocalizedNames(): { [s: string]: string } {
        return this.data.localizedNames || {};
    }

    @requiresWrite
    setLocalizedName(locale: string, name: string): void {
        return this._actionDispatch({
            name: 'updateGroup',
            type: 'update',
            data: {
                localizedNames: {
                    ...this.data.localizedNames,
                    [locale]: name
                }
            }
        });
    }

    get parent(): Group | undefined {
        return this.library.getGroupById(this._data.parentId as string);
    }

    @requiresWrite
    @observable
    set parent(group: Group | undefined) {
        this._actionDispatch({
            name: 'updateGroup',
            type: 'update',
            data: { parentId: group?.id || null }
        });
    }

    /**
     * @package -- only for use in SAM.js
     */
    _createChild(name: string, order: string) {
        const id = createPlaceholderId();
        this._actionDispatch({
            name: 'createGroup',
            type: 'insert',
            data: { id, name, order, classifier: this.classifierName, parentId: this.id },
            path: '$.groups'
        });

        return this.library.getGroupById(id);
    }

    /**
     * @package -- only for use in SAM.js
     */
    _actionDispatch(action: Optional<Action, 'path'>): void {
        if (!action.path) {
            action.path = `$.groups[?(@.id == "${this.id}")]`;
        }

        this.library._actionDispatch(action);
    }
}
