import { gql } from '../generated/typed-gql';

export const favorites = gql(
    /* GraphQL */
    `
    query favorites(
      $first: Int!
      $after: String
      $filter: AssetListFilter
      $orderBy: FavoriteOrderByInput
    ) {
      favorites {
        assetListId
        assetListConnection(
          first: $first
          after: $after
          filter: $filter
          orderBy: $orderBy
        ) {
          pageInfo {
            hasNextPage
            endCursor
          }
          edges {
            cursor
            node {
              ... on Asset {
                labels {
                  favorite {
                    isFavorite
                  }
                }
                ...repoMetadata
                ...effectivePermissions
                ...applicationMetadata
              }
            }
          }
        }
      }
    }
  `
);
