import type { SAM } from '@ccx-public/component-types';
import type {
    BoardsIndexLinks,
    BoardsIndexResponse,
    CreateBoardOptions,
    RemoteBoard,
    UpdateBoardOptions,
    AddBoardPostOptions,
    CreateBoardPayload,
    GetBoardsResponse,
    GetBoardsOptions,
    RemoteTextPost,
    RemoteAssetLinkPost,
    BoardLinks,
    AddPostValuePayload,
    PublishBoardInterfaceOptions,
    PublishOptions,
    SetBoardThemeOptions,
    ReclassifyPostDescriptionOptions,
    ReclassifyTextPostOptions,
    PostModerationStatus,
    GetPostByBoardAndPostIdOptions,
    CopyBoardOptions,
    CopyBoardRequest,
    BoardUserPatchOperation,
} from './BoardModel';

import { BOARD_THEME_MODES, BOARDS_REQUIRED_INDEX_LINKS, PostType, PostTypeMap } from './BoardModel';
import { cache, key } from '../core/decorators';
import InterfaceBase from './InterfaceBase';
import { getURLFromLinks, JSON_MIME_TYPE, RelType, validateLinks } from './LinkUtils';
import type jsonpatch from 'json-patch';
import { getSAMVersionRequestHeader } from '../utils/classroomUtils';
import SAMError, { SAMErrorCode } from '../core/SAMError';


const headers = getSAMVersionRequestHeader();

function validateRequiredBoardLinks(links: any) {
    return validateLinks(links, BOARDS_REQUIRED_INDEX_LINKS);
}

function validateTheme(theme: SetBoardThemeOptions): void {
    switch (theme.mode) {
    case BOARD_THEME_MODES.COLOR:
        if (!theme.primaryColor) {
            throw new Error('Color theme requires primaryColor');
        }
        break;
    case BOARD_THEME_MODES.IMAGE:
        break;
    default:
        throw new Error(`Unsupported theme mode: ${(theme as any).mode}`);
    }
}

export default class BoardsInterface extends InterfaceBase {
    @cache(validateRequiredBoardLinks)
    private async _discoverLinks(@key rootHref: string): Promise<BoardsIndexLinks> {
        const response: BoardsIndexResponse = await this._getResponse(rootHref, { headers });
        return response._links;
    }

    private _getEndpointHref(endpoint: string): string {
        return `https://${this._core._environment.endpoints.ASSIGNMENTS_HOST}${endpoint}`;
    }

    /**
     * Uploads a background image for a board theme
     * The backend will set the theme mode to IMAGE when a background image is uploaded.
     * @param boardId - The ID of the board
     * @param backgroundImage - Image file (Blob) uploaded from device
     */
    async uploadBackgroundImage(boardId: string, backgroundImage: Blob): Promise<void> {
        // TODO [ACPCEDU-5888] - Use relational link instead of hardcoded endpoint.
        const url = this._getEndpointHref(`/api/v1/boards/${encodeURIComponent(boardId)}/:upload-background-image`);
        const formData = new FormData();
        formData.append('file', backgroundImage);

        await this._doPost(url, { ...headers }, formData as any, [ 204 ]);
    }

    /**
     * Discovers and retrieves the available board-related API links and endpoints
     */
    async discoverLinks(): Promise<BoardsIndexLinks> {
        return this._discoverLinks(this._getEndpointHref(`/api/v1/boards/index`));
    }

    /**
     * Creates a new board
     * Does not upload the background image or set the theme to IMAGE.
     * The background image must be uploaded separately using {@link uploadBackgroundImage}.
     */
    async createBoard(data: CreateBoardOptions): Promise<RemoteBoard> {
        const links = await this.discoverLinks();
        const { additionalData, description, name, posts, theme, type, areNewCommentsAllowed } = data;
        const dataToPost: CreateBoardPayload = {
            'repo:name': name,
            'dc:description': description,
            'additionalMetadata': additionalData,
        };

        if (areNewCommentsAllowed !== undefined) {
            dataToPost['board:newCommentsAllowed'] = areNewCommentsAllowed;
        }

        if (theme) {
            validateTheme(theme);

            if (theme.mode !== BOARD_THEME_MODES.IMAGE) {
                // Note that when uploading a background image, the backend will set the mode to IMAGE.
                // TODO: Once POST V2 is ready, we can send board:image directly in the payload and remove the separate upload call
                dataToPost['board:theme'] = theme;
            }
        }

        if (type) {
            dataToPost['board#type'] = type;
        }

        if (posts) {
            dataToPost.posts = await Promise.all(posts.map(post => this.mapPostCreationData(post)));
        }

        const url = getURLFromLinks(links, RelType.BOARDS_CREATE, {
            baseAssetId: data.baseAssetId,
            useBaseAssetDirectory: data.shouldCreateDirectlyInBaseAsset || false
        });
        const response = await this._doPost(url, {
            ...headers,
            'Content-Type': JSON_MIME_TYPE,
        },
        JSON.stringify(dataToPost),
        [ 201 ]
        );
        const createdBoard: RemoteBoard = await response.json();

        return createdBoard;
    }

    /**
     * Retrieves a specific board by its ID
     */
    async getBoard(boardId: string): Promise<RemoteBoard> {
        const links = await this.discoverLinks();
        const url = getURLFromLinks(links, RelType.BOARDS_PRIMARY, {  boardId  });
        const response = await this._doGet(url, { headers });
        return response.json();
    }

    /**
     * Retrieves the full-size background image for a board
     * Will use the browser cache if the component id and version are the same as the cached version.
     * @throws {SAMError} with code BAD_REQUEST if the component link is missing
     */
    async getBoardBackgroundImage({ links, componentId, componentVersion }: { links: BoardLinks, componentId: string, componentVersion: string }): Promise<Blob> {
        if (!links[RelType.COMPONENT]) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, `Component link is missing for this board`);
        }
        const url = getURLFromLinks(links, RelType.COMPONENT, { component_id: componentId, revision: componentVersion });
        // Platform calls do not need default SAM headers
        const response = await this._doGet(url);
        return response.blob();
    }

    /**
     * Retrieves all boards associated with a specific linked asset
     */
    async getBoards(options: GetBoardsOptions): Promise<RemoteBoard[]> {
        const { baseAssetId } = options;
        const links = await this.discoverLinks();
        const url = getURLFromLinks(links, RelType.BOARDS_COLLECTION, {
            baseAssetId,
            useBaseAssetDirectory: options.shouldGetDirectlyInBaseAsset || false
        });
        const response = await this._doGet(url, { headers });
        const data: GetBoardsResponse = await response.json();
        return data.children;
    }

    /** Transforms the data given to {@link updateBoard} for posts into the data expected by the API */
    private async mapPostCreationData(post: AddBoardPostOptions): Promise<AddPostValuePayload> {
        const { name, description, type, userId } = post;

        const remotePost: AddPostValuePayload = {
            name,
            'board#postDescription': description,
            type: PostTypeMap.toB(type),
        };

        if (userId) {
            remotePost.userId = userId;
        }

        if (type === PostType.Text) {
            (remotePost as RemoteTextPost)['board#postText'] = post.text;
            if (post.backgroundColor) {
                (remotePost as RemoteTextPost)['board#postBackgroundColor'] = post.backgroundColor;
            }
        }

        if (type === PostType.AssetLink) {
            // At this point assetId will be defined because it was provided or the user uploaded an asset
            const asset = await this._core.hostAssetContext.getAssetWithCloudID(post.assetId!);
            (remotePost as RemoteAssetLinkPost).link = {
                'repo:assetId': post.assetId!,
                'dc:format': asset.mediaType,
            };
        }

        return remotePost;
    }

    private async _patchBoard(boardId: string, patchData: jsonpatch.OpPatch[]): Promise<RemoteBoard | undefined> {
        if (patchData.length > 0) {
            const links = await this.discoverLinks();
            const url = getURLFromLinks(links, RelType.BOARDS_PRIMARY, {  boardId  });
            const response = await this._doPatch(url, {
                ...headers,
                'Content-Type': JSON_MIME_TYPE,
            }, JSON.stringify(patchData));
            return response.json();
        }
    }

    /**
     * Updates an existing board's properties, including description and posts
     */
    async updateBoard(data: UpdateBoardOptions): Promise<RemoteBoard | undefined> {
        const { displayName: newName, description: boardDescription, postsToAdd = [], postsToRemove, postsToUpdate, boardId, theme, areNewCommentsAllowed } = data;
        const patchData: jsonpatch.OpPatch[] = [];

        if (newName !== undefined) {
            patchData.push({
                op: 'replace',
                path: '/repo:name',
                value: newName
            });
        }

        if (boardDescription !== undefined) {
            patchData.push({
                op: 'replace',
                path: '/dc:description',
                value: boardDescription
            });
        }

        if (theme !== undefined) {
            validateTheme(theme);
            if (theme.mode !== BOARD_THEME_MODES.IMAGE) {
                patchData.push({
                    op: 'replace',
                    path: '/board:theme',
                    value: theme
                });
            }
            // If IMAGE, do nothing here. Upload handled by BoardContext.
        }

        if (areNewCommentsAllowed !== undefined) {
            patchData.push({
                op: 'replace',
                path: '/board:newCommentsAllowed',
                value: areNewCommentsAllowed
            });
        }

        for (const post of postsToAdd) {
            patchData.push({
                op: 'add',
                path: '/board#post',
                value: await this.mapPostCreationData(post),
            });
        }

        postsToRemove?.forEach((postId) => {
            patchData.push({
                op: 'remove',
                path: `/board#post/${postId}`
            });
        });

        // User is only allowed to update post description
        postsToUpdate?.forEach((post) => {
            patchData.push({
                op: 'replace',
                path: `/board#post/${post.id}/board#postDescription`,
                value: post.description
            });
        });

        return this._patchBoard(boardId, patchData);
    }

    /**
     * Patches board users by sending operations to the Boole service
     * This is a low-level method that allows callers to specify the exact operations to perform
     *
     * @param boardId - The ID of the board
     * @param operations - Array of board user patch operations
     * @returns Promise that resolves when the operations have been applied (204 response with no body)
     */
    async patchBoardUsers(boardId: string, operations: BoardUserPatchOperation[]): Promise<void> {
        const url = this._getEndpointHref(`/api/v1/boards/${encodeURIComponent(boardId)}/users`);

        await this._doPatch(
            url,
            {
                ...headers,
                'Content-Type': JSON_MIME_TYPE,
            },
            JSON.stringify(operations),
            [ 204 ]
        );
    }

    /**
     * Updates the visibility level of a board
     */
    async updateBoardVisibility({ boardId, links }: {boardId: string; links: BoardLinks}): Promise<void> {
        if (!links[RelType.BOARDS_UPDATE_VISIBILITY]) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, `Update visibility link is missing for this board ${boardId}`);
        }
        const url = getURLFromLinks(links, RelType.BOARDS_UPDATE_VISIBILITY, { boardId });
        await this._doPost(url, {
            ...headers,
            'Content-Type': JSON_MIME_TYPE,
        },
        undefined,
        [ 204 ]
        );
    }

    /**
     * Publishes a board, making it available for viewing
     */
    async publishBoard(options: PublishBoardInterfaceOptions): Promise<RemoteBoard> {
        const { boardId, links, boardTitle, boardSubTitle, showPosterName } = options;
        if (!links[RelType.BOARDS_PUBLISH]) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, `Publish link is missing for this board ${boardId}`);
        }
        const url = getURLFromLinks(links, RelType.BOARDS_PUBLISH, { boardId });
        const requestBody: PublishOptions = { boardTitle, boardSubTitle, showPosterName };
        const response = await this._doPost(
            url,
            {
                ...headers,
                'Content-Type': JSON_MIME_TYPE,
            },
            JSON.stringify(requestBody),
            [ 201 ]
        );
        return response.json();
    }

    /**
     * Unpublishes a specific board
     */
    async unpublishBoard({ boardId, links }: { boardId: string, links: BoardLinks }): Promise<void> {
        if (!links[RelType.BOARDS_UNPUBLISH]) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, `Unpublish link is missing for this board ${boardId}`);
        }
        const url = getURLFromLinks(links, RelType.BOARDS_UNPUBLISH, { boardId });
        await this._doPost(url, headers, undefined, [ 204 ]);
    }

    /** Triggers the reclassification of text through ACMP */
    async reclassifyPostDescription({ boardId, postId, description }: ReclassifyPostDescriptionOptions & { description: string }): Promise<RemoteBoard | undefined> {
        return this.updateBoard({ boardId, postsToUpdate: [ { id: postId, description } ] });
    }

    /**
     * Calls hume endpoint to classify text.  Used by the client to check text before saving.
     * @throws {SAMError} with code BAD_REQUEST if the classify text link is missing
     * */
    async classifyText({ boardId, links, bodyText }: SAM.ClassifyTextOptions & { links: BoardLinks }): Promise<SAM.ClassifyTextResponse> {
        if (!links[RelType.BOARDS_CLASSIFY_TEXT]) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, `Classify text link is missing for this board ${boardId}`);
        }
        const url = getURLFromLinks(links, RelType.BOARDS_CLASSIFY_TEXT, {  boardId  });
        const response = await this._doPost(url, {
            ...headers,
            'Content-Type': JSON_MIME_TYPE,
        }, JSON.stringify({ bodyText }), [ 200 ]);
        const apiResponse: { result: 'match' | 'noMatch' } = await response.json();
        return { flagged: apiResponse.result === 'match' };
    }

    /** Triggers the reclassification of text through ACMP */
    async reclassifyTextPost({ boardId, postId, text }: ReclassifyTextPostOptions & { text: string }): Promise<RemoteBoard | undefined> {
        // This does not use updateBoard() because the text of a TextPost is not modifiable
        return this._patchBoard(boardId, [ {
            op: 'replace',
            path: `/board#post/${postId}/board#postText`,
            value: text
        } ]);
    }

    /** Updates the descriptionStatus of the Post */
    async updatePostDescriptionStatus({ boardId, postId, descriptionStatus }: GetPostByBoardAndPostIdOptions & { descriptionStatus: PostModerationStatus }): Promise<RemoteBoard | undefined> {
        return this._patchBoard(boardId, [ {
            op: 'replace',
            path: `/board#post/${postId}/board#postDescriptionStatus`,
            value: descriptionStatus
        } ]);
    }

    /** Updates the textStatus of a TextPost */
    async updateTextPostTextStatus({ boardId, postId, textStatus }: GetPostByBoardAndPostIdOptions & { textStatus: PostModerationStatus }): Promise<RemoteBoard | undefined> {
        // This does not use updateBoard() because the text of a TextPost is not directly modifiable
        return this._patchBoard(boardId, [ {
            op: 'replace',
            path: `/board#post/${postId}/board#postTextStatus`,
            value: textStatus
        } ]);
    }

    /**
     * Copies a board
     * @param options The copy board options
     * @returns The newly copied board
     */
    async copyBoard({ boardId, targetAssetId, links, name }: CopyBoardOptions & { links: BoardLinks }): Promise<RemoteBoard> {
        if (!links[RelType.BOARDS_COPY]) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, `Copy link is missing for this board ${boardId}`);
        }
        const url = getURLFromLinks(links, RelType.BOARDS_COPY, { boardId });

        // Backend support for copiedBoardMetadata not on Stage (available 2/12/2026).
        const requestBody: CopyBoardRequest = {
            target: {
                'repo:assetId': targetAssetId,
            },
            ...(name && { copiedBoardMetadata: { 'repo:name': name } }),
        };

        const response = await this._doPost(
            url,
            {
                ...headers,
                'Content-Type': JSON_MIME_TYPE,
            },
            JSON.stringify(requestBody),
            [ 201 ]
        );
        return response.json();
    }
}
