import Logger from '../../utils/Logger';

// Fallback implementation of localStorage in case we're not running in a standard browser environment (e.g. node.js)
class InMemoryStorage implements Storage {
    private _data = new Map();

    get length() {
        return this._data.size;
    }

    key(index: number) {
        return Array.from(this._data.keys())[index];
    }
    getItem(key: string) {
        return this._data.get(key);
    }
    setItem(key: string, value: any) {
        this._data.set(key, value);
    }
    removeItem(key: string) {
        this._data.delete(key);
    }
    clear() {
        this._data.clear();
    }
}

/**
 * Local/Session Storage interface.
 * Allows getting and setting persistent settings that are local to the
 * current user session of the Libraries JS API.
 * Local Storage: Stores data to disk which is available across tabs/windows to the same user in the same browser.
 * Session Storage: Stores data to memory which is available only to the current tab.
 */
export class StorageInterface {
    _storage: Storage;
    _storageKey: string;
    _settings = new Map();

    constructor(storageKey: string, storage?: Storage) {
        this._storageKey = storageKey;
        this._storage = storage ?? (typeof window !== 'undefined' ? window.localStorage : new InMemoryStorage());
        // Restore any previous settings saved to this storage key.
        this._load();
    }

    // Expose the storage values
    entries() {
        return this._settings.entries();
    }

    setItem(key: string, value: any) {
        this._settings.set(key, value);
        // Write the current settings to storage.
        this._save();
    }

    getItem(key: string) {
        return this._settings.get(key);
    }

    _setItem(key: string, value: any) {
        this._storage.setItem(key, value);
    }

    _load() {
        const settingsStr = this._storage.getItem(this._storageKey);
        if (settingsStr) {
            try {
                this._settings = new Map(JSON.parse(settingsStr));
            } catch (e) {
                Logger.error('Error restoring previous settings.');
                // Remove the invalid settings.
                this._storage.removeItem(this._storageKey);
            }
        }
    }

    _save() {
        const settingsStr = JSON.stringify(Array.from(this._settings.entries()));
        this._setItem(this._storageKey, settingsStr);
    }
}
