export const combineSignals = (...signals: AbortSignal[]) => {
    const controller = new AbortController();
    const onAbort = () => {
        controller.abort();
        signals.forEach(signal => signal.removeEventListener('abort', onAbort));
    };
    if (signals.some(signal => signal.aborted)) {
        onAbort();
    } else {
        signals.forEach(signal => signal.addEventListener('abort', onAbort));
    }
    return controller.signal;
};

class AbortSignalReasons {
    private signalToReasonMap = new WeakMap<AbortSignal>();

    private getSignal(aborter: AbortSignal | AbortController): AbortSignal {
        return (aborter as any).signal ?? aborter;
    }

    reason(aborter: AbortSignal | AbortController) {
        return this.signalToReasonMap.get(this.getSignal(aborter));
    }

    give(aborter: AbortSignal | AbortController, reason: any) {
        this.signalToReasonMap.set(this.getSignal(aborter), reason);
    }
}

export const abortSignalReasons = new AbortSignalReasons();
