import { CustomModelOrderBy } from '../interface/CustomModelModel';
import type { IComparatorMap } from '../core/ItemOrder';
import { compareStrings, compareValues, createItemOrderFactory } from '../core/ItemOrder';

import type CustomModel from './CustomModel';
import type { ISearchSortOrderBy, ISearchQuery } from '../interface/USSModel';

export type CustomModelOrderField =
    | 'name'
    | 'created'
    | 'modified';

export const OrderFieldToCustomModelOrderBy: { [key in CustomModelOrderField]: CustomModelOrderBy} = {
    'name': CustomModelOrderBy.NAME,
    'created': CustomModelOrderBy.CREATE_DATE,
    'modified': CustomModelOrderBy.MODIFY_DATE
};

const OrderFieldToComparator: IComparatorMap<CustomModel, CustomModelOrderField> = {
    name(a: CustomModel, b: CustomModel): number {
        return compareStrings(a.name, b.name);
    },

    created(a: CustomModel, b: CustomModel): number {
        return compareValues(a.created, b.created);
    },

    modified(a: CustomModel, b: CustomModel): number {
        return compareValues(a.modified, b.modified);
    }
};

export default class CustomModelOrder extends createItemOrderFactory(OrderFieldToComparator) {
    static default = new CustomModelOrder('descending', 'modified');
}


export const customModelOrderToUSSOrder = (itemOrder: CustomModelOrder): Required<Pick<ISearchQuery, 'sort_order' | 'sort_orderby'>> => {
    const orderMap: { [key in CustomModelOrderField]: ISearchSortOrderBy } = {
        'name': 'asset_name',
        'created': 'create_date',
        'modified': 'modify_date'
    };

    return {
        sort_order: itemOrder.direction === 'ascending' ? 'asc' : 'desc',
        sort_orderby: orderMap[itemOrder.field]
    };
};
