import type AdobeAsset from '../assets/AdobeAsset';
import { SAMErrorCode } from '../core/SAMError';
import type AssetContext from '../assets/AssetContext';
import type LibraryInterface from '../interface/LibraryInterface';
import type Cache from '../core/Cache';
import { NotFound } from '../core/Cache';
import { EventEmitter } from 'events';

/**
 * Represents a location in the user storage which are required to exist for the LibraryContext to function properly.
 * It provides functions to ensure the existence of the location and to watch for changes in the location.
 */
export abstract class SubscriptionLocation extends EventEmitter {
    protected _cacheKey: string;
    protected _path: string;
    protected _asset: AdobeAsset | undefined = undefined;

    constructor(cacheKey: string, path: string) {
        super();
        this._cacheKey = cacheKey;
        this._path = path;
    }

    get cacheKey(): string { return this._cacheKey; }
    get path(): string { return this._path; }
    get asset(): AdobeAsset | undefined { return this._asset; }

    async ensureExistence(context: AssetContext, libraryInterface: LibraryInterface): Promise<AdobeAsset> {
        const environment = context._core._environment;
        const cache = environment.cache;
        const cacheKey = this._cacheKey;
        const assetId = await cache.getItem(cacheKey);
        try {
            const asset = assetId !== NotFound ? await context.getAssetWithCloudID(assetId) : await context.getAssetWithRepoPath(this._path);
            cache.setItem(cacheKey, asset.cloudID);
            return this._setAsset(asset, cache);
        } catch (e: any) {
            if (e.code === SAMErrorCode.NOT_FOUND) {
                environment.debug(`${this._path} not found, creating it now`);
                const asset = await this._create(context, libraryInterface);
                return this._setAsset(asset, cache);
            }
            throw e;
        }
    }

    protected _callback = () => {
        this.emit('change');
    };

    private async _setAsset(asset: AdobeAsset, cache: Cache): Promise<AdobeAsset> {
        this._asset = asset;
        await cache.setItem(this._cacheKey, asset.cloudID);
        this._setUpWatcher();
        return asset;
    }

    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    protected abstract _create(context: AssetContext, libraryInterface: LibraryInterface): Promise<AdobeAsset>;
    protected abstract _setUpWatcher(): void;
}

export class SyncGroupLocation extends SubscriptionLocation {
    constructor() {
        super('SYNC_GROUP_ID', '/assets/adobe-libraries');
    }

    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    protected async _create(context: AssetContext, libraryInterface: LibraryInterface): Promise<AdobeAsset> {
        return await (await context.getHomeFolder()).createFolder(this.path);
    }

    protected _setUpWatcher(): void {
        this._asset?.on('change', this._callback);
    }
}

class BookmarkLocation extends SubscriptionLocation {
    constructor(cacheKey: string, path: string) {
        super(cacheKey, path);
    }

    protected async _create(context: AssetContext, libraryInterface: LibraryInterface): Promise<AdobeAsset> {
        // call to Melville's GET /bookmarks endpoint ensures that the bookmarks are created
        await libraryInterface.getBookmarks();
        return context.getAssetWithRepoPath(this.path);
    }

    protected _setUpWatcher(): void {
        this._asset?.on('change', this._callback);
        this._asset?.appMetadata.on('change', this._callback);
    }
}

export class CollabBookmarkLocation extends BookmarkLocation {
    constructor() {
        super('COLLAB_BOOKMARKS_ID', '/sync/adobe-libraries/collab-bookmarks.json');
    }
}

export class PublicBookmarkLocation extends BookmarkLocation {
    constructor() {
        super('PUBLIC_BOOKMARKS_ID', '/sync/adobe-libraries/bookmarks.json');
    }
}
