// https://jira.corp.adobe.com/browse/UXP-19257
import 'abort-controller/polyfill';

import { getRetryAfterHeader, RelType } from '../interface/LinkUtils';
import {
    ONSFirstLongPollCompletedEvent,
    ONSFirstLongPollStartedEvent,
    ONSMonitoringStatusChangedEvent,
    ONS_FIRST_LONG_POLL_COMPLETED,
    ONS_FIRST_LONG_POLL_STARTED,
    ONS_MONITORING_STATUS_CHANGED,
    OnsMonitoringStatus,
} from './ONSEvent';
import type { ONSCachedSubscription, ONSObjectMap, ONSSubscriptionChangeEvent } from './ONSSubscription';
import { ONSSubscription } from './ONSSubscription';
import { synchronized, memoize } from '../core/decorators';
import { SAMObjectEventEmitter } from '../core/SAMObjectEventEmitter';
import type { ONSContext } from './ONSContext';
import type { ONSWorkerEventMap, ONSWorkerInterface } from './ONSWorker.interface';
import type { default as Cache } from '../core/Cache';
import { NotFound } from '../core/Cache';
import type { ONSObjectProperties } from './ONSResource';

// Set the x-poll-timeout request header value (in seconds) for ONS long poll requests
// This controls the frequency of the ONS server long poll responses.
const ONS_POLLTIMEOUT_SECONDS = 160;

export const cacheKey = 'ONS_SUBSCRIPTIONS';

const ONS_LONG_POLL_AUTH_HEADER = 'X-User-Token';

interface OnsLongPollWorkerEventMap extends ONSWorkerEventMap {
    [ONS_FIRST_LONG_POLL_STARTED]: ONSFirstLongPollStartedEvent;
    [ONS_FIRST_LONG_POLL_COMPLETED]: ONSFirstLongPollCompletedEvent;
}

/**
 * Interface to register ONS subscription and listen for change events.
 * Design notes:
 * Polling will only happen when the following three conditions are ALL met:
 *  1. start() has been called (and stop() has not been called).
 *  2. watch() has been called with a non-empty set of asset ids.
 *  3. The document is visible (document.visibilityState === 'visible').
 */
export class ONSLongPollWorker extends SAMObjectEventEmitter<OnsLongPollWorkerEventMap> implements ONSWorkerInterface {
    private _abortController?: AbortController;
    private _pollURL?: string;
    private _subscriptions: ONSSubscription[] = [];
    // Note: actual limit is determined in _ensureSubscriptions
    private _maxObjectsPerSubscription: number = 5;
    private _cachedSubscriptionsUsed: boolean = false;
    private _cache: Cache;
    private _watchedObjects: ONSObjectMap = new Map();

    constructor(
        readonly _onsContext: ONSContext,
    ) {
        super(_onsContext._core);
        this._cache = _onsContext._core._environment.cache;
    }

    get isActive() {
        return Boolean(this._abortController);
    }

    get subscriptions(): ONSSubscription[] {
        return this._subscriptions;
    }

    async ensureReady(): Promise<boolean> {
        return true;
    }

    async deinitialize(): Promise<boolean> {
        this.stop();
        return true;
    }

    /**
     * Start
     */
    async start(): Promise<void> {
        if (this.isActive) {
            this.logDebug(`ONS Long Poll worker is already started! Skipping this request!`);
            return;
        }
        this.logInfo(`Starting ONS Long Poll Worker...`);
        this._abortController = new AbortController();
        this._poll();
        this.emit(ONS_MONITORING_STATUS_CHANGED, new ONSMonitoringStatusChangedEvent(OnsMonitoringStatus.Active));
    }

    /**
     * Stop
     */
    stop() {
        if (!this.isActive) {
            this.logDebug(`ONS Long Poll worker is already stopped! Skipping this request!`);
            return;
        }

        this.logInfo(`Stopping ONS Long Poll Worker...`);
        this.subscriptions.forEach((sub: ONSSubscription) => sub.abort());
        const abortController = this._abortController;
        delete this._abortController;
        this._abortController = undefined;
        abortController?.abort();
        this.emit(ONS_MONITORING_STATUS_CHANGED, new ONSMonitoringStatusChangedEvent(OnsMonitoringStatus.Inactive));
    }

    @synchronized
    private async _restartMonitoring() {
        const activeSubscriptionIds: string[] = this._activeSubscriptionIds;

        // we don't want to create a bogus long pollURL if
        // there is no subscriptions...
        const newPollURL = activeSubscriptionIds.length === 0 ? undefined : await this._onsContext.getLink(RelType.NOTIFICATIONS_LONGPOLL, {
            includeJournal: 'false', subscriptionId: activeSubscriptionIds });

        const isUrlChanged: boolean = this._pollURL !== newPollURL;
        this._pollURL = newPollURL;
        if (this.isActive && isUrlChanged) {
            this.stop(); // Only stop if the URL has changed.
            this.start(); // Ensure polling is started.
        }
    }

    // This is used to notify the client that the initial long poll has been started along with the information
    // whether cached subscriptions were used or not. It can be used by the clients to avoid any refresh of its cached
    // data if cached subscriptions were used.
    @memoize
    private _notifyFirstLongPollStarted() {
        this.emit(ONS_FIRST_LONG_POLL_STARTED, new ONSFirstLongPollStartedEvent(this._cachedSubscriptionsUsed));
    }

    // This is used to notify the client that the initial long poll has been completed along with the information
    // whether they were expired or not. It can be used by the clients to avoid any refresh of its cached
    // data if cached subscriptions were used.
    @memoize
    private _notifyFirstLongPollCompleted(expired: boolean) {
        this.emit(ONS_FIRST_LONG_POLL_COMPLETED, new ONSFirstLongPollCompletedEvent(expired));
    }

    // ONS Subscriptions are more efficient if they are kept alive and updated so we check whether the subscription
    // is within 10% of its TTL and refresh as necessary
    private _validateAndUpdateSubscriptionExpiration() {
        const now = Date.now();

        // We calculate the remaining time to live being within a 10% zone of the current time based
        // on environment set TTL with a minimum time remaining being 5 mins.
        const ttl = Math.max(
            this._core._environment.getValue('ONS_SUBSCRIPTION_TIME_TO_LIVE') * 0.1,
            this._core._environment.getValue('ONS_SUBSCRIPTION_RENEW_TIME')
        );
        this.subscriptions
            .filter(sub => sub.watchedONSObjects.size && (sub.expiresAt - now) < ttl)
            .forEach(sub => sub.refreshSubscriptionExpiryDate());
    }

    private async _getAndParseCachedSubscriptions(): Promise<ONSCachedSubscription[]> {
        // @TODO SAM-2845 Prevent data from being retrieved from cache
        // until it is enabled again in the future.
        if (!this._onsContext.cacheEnabled) {return [];}

        const existingCreatedSubscriptions = await this._cache.getItem(cacheKey);
        if (existingCreatedSubscriptions !== NotFound) {
            try {
                return JSON.parse(existingCreatedSubscriptions)?.subscriptions || [];
            } catch (e) {
                this.logInfo('error parsing cached subscriptions');
            }
        }
        return [];
    }

    private get _activeSubscriptionIds(): string[] {
        return Array.from(this._subscriptions)
            .filter(sub => sub.subscriptionId && sub.watchedONSObjects.size > 0) // Note: watchedONSObjects not assets
            .map(sub => `${sub.subscriptionId}`)
            .sort();
    }

    private _onSubscriptionChange = (event?: ONSSubscriptionChangeEvent) => {
        // IF change are notified let's make sure to update the cache as well.
        if (!event?.fromCache) {
            this._cachedSubscriptionsUsed = false;
        }
        this._updateCachedSubscriptions()
            .finally(() => this._restartMonitoring())
            .catch((err) => this.logWarn('restartMonitoring failed upon subscription change', err));
    };

    @synchronized
    private async _updateCachedSubscriptions() {
        // @TODO SAM-2845 where this is defined for more information.
        // Prevent data from being written to cache
        // until it is enabled again in the future.
        if (!this._onsContext.cacheEnabled) { return; }

        const newCachedSubscriptions: ONSCachedSubscription[] = [];
        this._subscriptions.forEach((subscription) => {
            const { subscriptionId, subscriptionHref, pendingONSObjects, expiresAt } = subscription;
            // If the ONSSubscription doesn't have an ID or Href
            // that means it wasn't created on the server and
            // it doesn't have any information to cache.
            if (!subscriptionId || !subscriptionHref) {
                return;
            }

            const updatedCache: ONSCachedSubscription = {
                id: subscriptionId,
                href: subscriptionHref,
                onsObjects: Object.fromEntries(pendingONSObjects),
                expiresAt: expiresAt || Date.now() + this._core._environment.getValue('ONS_SUBSCRIPTION_TIME_TO_LIVE')
            };

            newCachedSubscriptions.push(updatedCache);
        });

        await this._cache.setItem(
            cacheKey,
            JSON.stringify({ subscriptions: newCachedSubscriptions }),

            // This ensures that the cached subscription will expire the same time
            // that the subscription expires on the server.
            this._core._environment.getValue('ONS_SUBSCRIPTION_TIME_TO_LIVE')
        );
    }

    private async _ensureSubscriptions() {
        // This will create and store instances of ONSSubscription
        // the number created will be the number of MAX_SUBSCRIPTIONS
        // set by SAM.js or service (we don't actually create subscriptions
        // on the server though, unless they have any assets to monitor)

        const subscriptionConfig = await this._onsContext.getSubscriptionConfig();
        const maxSubscriptions = subscriptionConfig.maxSubscriptionPerLongPoll || this._core._environment.getValue('ONS_DEFAULT_MAX_SUBSCRIPTIONS');
        this._maxObjectsPerSubscription = subscriptionConfig.maxAssetsPerRequest || this._core._environment.getValue('ONS_DEFAULT_MAX_ASSETS_PER_SUBSCRIPTION');

        if (maxSubscriptions > this._subscriptions.length) {
            // Just because we are creating an ONSSubscription does not mean
            // we are creating a subscription on the service. We actually
            // create the max number of local ONSSubscription allowed by ONS but only
            // create the subscription on the service if there are assets on that subscription.

            const parsedCachedSubscriptions = await this._getAndParseCachedSubscriptions();
            this._cachedSubscriptionsUsed = parsedCachedSubscriptions.length > 0;

            // Add new subscriptions
            for (let i = this._subscriptions.length; i < maxSubscriptions; ++i) {
                // If we have a corresponding cached subscription
                // pull the information from cache and construct
                // the ONSSubscription with data from the cache.
                // If the cached subscription information is out of date,
                // it will be handled inside the ONSSubscription.
                const sub = new ONSSubscription(
                    this._onsContext,
                    parsedCachedSubscriptions[i]
                );

                this._subscriptions.push(sub);
                sub.on('change', this._onSubscriptionChange);
            }
        } else if (maxSubscriptions < this._subscriptions.length) {
            // Remove subscriptions over the limit
            for (let i = maxSubscriptions; i < this._subscriptions.length; ++i) {
                const sub = this._subscriptions[i];
                sub.pendingONSObjects = new Map();
                sub.off('change', this._onSubscriptionChange);
            }
            this._subscriptions.length = maxSubscriptions; // Removes the overflow from the array
        }
    }

    private _truncateObjectsIfNeeded(objects: ONSObjectMap): ONSObjectMap {
        const maxObjects = this._maxObjectsPerSubscription * this._subscriptions.length;
        if (objects.size > maxObjects) {
            this.logWarn(`Max objects (${maxObjects} exceeded, removing ${objects.size - maxObjects} objects`);

            // Prioritize PLS lists and Folders over individual Assets
            const getPriority = (obj: ONSObjectProperties): number => {
                if (obj.type === 'assetList') { return 0; }
                if (obj.type === 'asset' && obj.directoryLevel === 'shallow') { return 1; }
                return 3;
            };

            return new Map([ ...objects.entries() ]
                .sort(([ _id1, obj1 ], [ _id2, obj2 ]) => {
                    return getPriority(obj1) - getPriority(obj2);
                })
                .slice(0, maxObjects));
        }
        return objects;
    }

    async watch(objects: ONSObjectMap) {
        await this._ensureSubscriptions();
        this._watchedObjects = this._truncateObjectsIfNeeded(objects);

        // Update subscriptions' pending objects, replacing existing objects with updated config.
        const handledObjectIds = new Set<string>();
        const subscriptionToOnsObjects: Map<string, ONSObjectProperties>[] = this._subscriptions.map(
            sub => {
                const onsObjects = new Map<string, ONSObjectProperties>();
                sub.pendingONSObjects.forEach((_properties, id) => {
                    if (this._watchedObjects.has(id) && handledObjectIds.add(id)) {
                        onsObjects.set(id, this._watchedObjects.get(id)!);
                    }
                });
                return onsObjects;
            }
        );

        // Fill up subscriptions, optimizing for minimal number of subscriptions
        let nextIndex = 0;
        this._watchedObjects.forEach((obj, id) => {
            if (handledObjectIds.has(id)) {return;}
            // find a subscription with space
            while (
                subscriptionToOnsObjects[nextIndex].size >= this._maxObjectsPerSubscription
            ) {
                nextIndex++;
            }
            subscriptionToOnsObjects[nextIndex].set(id, obj);
        });

        this._subscriptions.forEach((sub, index) => {
            // Note: this setter triggers updating subscription in the cloud
            sub.pendingONSObjects = subscriptionToOnsObjects[index];

            if (sub.pendingONSObjects.size > 0) {
                this.logDebug(
                    `Subscription #${index} (${sub.subscriptionId}) now has ${sub.pendingONSObjects.size} items.`
                );
            }
        });
    }

    /**
     * _poll sets up the longpoll request with retries if needed.
     *
     * @param attempt This tracks the number of attempts already made so we can back off in needed.
     * @returns void;
     */
    private async _poll(attempt: number = 0) {
        const retry = (error: any, interval: number = 0) => {
            interval = Math.max(this._core._environment.getRetryInterval(attempt), interval);

            const abortController = this._abortController;
            if (!abortController) {
                return;
            }

            this.logInfo(`Retrying long poll in ${interval}ms`);
            const timeout = setTimeout(() => this._poll(attempt + 1), interval);
            abortController.signal.addEventListener('abort', () => {
                if (abortController !== this._abortController) {
                    clearTimeout(timeout);
                }
            });
        };

        const abortController = this._abortController;
        if (!abortController) {
            this.logInfo(`No abort controller...`);
            return;
        }
        try {
            // this.pollURL can be undefined at start up when watch didn't have a time to build it yet,
            // also if we deleted all subscriptions calling watch with empty set.
            //
            // _pollURL is set by calling watch() which calls _ensureSubscriptions() which then sets
            // an event handler for a "change" event on each subscription created (ONSSubscription). The subscription
            // will emit a "change" event for various cases but mainly for when assetIds are updated on
            // the subscription. Once a change is emitted, the
            // the assigned _onSubscriptionChangeFun() is called and then calls _onSubScriptionChange().
            // then finally sets the URL. @TODO maybe we can streamline this process a bit more.
            if (this._pollURL === undefined) {
                this.logInfo(`Poll URL undefined...`);
                // just returning here because when pollUrl get populated it will call _stop(), _start()
                return;
            }
            // Go ahead and notify clients about first long poll.
            this._notifyFirstLongPollStarted();

            const href = this._pollURL as string;
            // Give the service a 20s buffer to respond on their end before terminating on our end
            const requestTimeoutMs = (ONS_POLLTIMEOUT_SECONDS + 20) * 1000;
            const response = await this._core._environment.fetch(href, {
                signal: abortController.signal,
                authHeader: ONS_LONG_POLL_AUTH_HEADER,
                headers: {
                    'x-poll-timeout': `${ ONS_POLLTIMEOUT_SECONDS }`
                },
                requestTimeoutMs
            });

            if ([ 200, 201, 204 ].includes(response.status)) {
                const json = await response.json();

                this._notifyFirstLongPollCompleted(false);
                this.logInfo(`Successful long poll for ${href}`);

                // Sometimes (frequently) we get a 20x response, and nothing has changed.
                if (json && json.subscriptions && json.subscriptions.length > 0) {
                    this.logInfo(`Subscriptions changed: ${json.subscriptions.join(', ')}`);

                    // Trigger the changed subscriptions to fetch changes via the changelog API:
                    // Note that ONS does not yet support a single changelog for multiple subscriptions, so we have
                    // to call the changelog separately for each subscription right now.
                    json.subscriptions.forEach((id: string) => {
                        const subscription = this.subscriptions.find(sub => sub.subscriptionId === id);
                        subscription?.fetchAndNotifyChanges();
                    });

                    // After a successful long poll we should do a quick check on the expire times on the
                    // active subscriptions.
                    this._validateAndUpdateSubscriptionExpiration();

                    // We don't really need this as part of the public API, but it makes the tests much easier,
                    // so we can abort the polling.
                    this.emit('notified');
                }

                // If ONS is worried that our subscription is invalid, verify it is still there. (ONS will do this
                // every few hours no matter what.)
                if (json && json.checkSubscriptions && json.checkSubscriptions.length > 0) {
                    this.logInfo(`Checking subscriptions for subscriptions to check ${json.checkSubscriptions.length}`);
                    json.checkSubscriptions.forEach((id: string) => {
                        const subscription = this.subscriptions.find(sub => sub.subscriptionId === id);
                        if (subscription) {
                            subscription.validate();
                        }
                    });
                }

                this._pollURL = json && json._links && json._links.next && json._links.next.href;
                this._poll();
            } else if (response.status === 404) {
                this._notifyFirstLongPollCompleted(true);
                this.logInfo(`404 Response long poll for ${href}, subscription missing or expired`);
                // If the response is a 404, we've somehow lost the subscriptions. Make a new one.
                this.subscriptions.forEach((subscription: ONSSubscription) => {
                    if (subscription.subscriptionId) {
                        subscription.validate();
                    }
                });
                // We need to retry here because if subscription will be validated on the server
                // then 'change' event will not be emitted and we will stop polling here.
                retry(undefined, this._core._environment.getValue('MAX_RETRY_INTERVAL'));
            } else {
                this.logInfo(`Unexpected response, trying again ${href}`);
                // Otherwise, follow the retry logic defined by the ONS team.
                retry(undefined, getRetryAfterHeader(response.headers) * 1000);
            }
        } catch (error) {
            // If we aborted this request, we don't want to retry.
            // But only if we aborted it locally. If it was aborted elsewhere, we want to retry.
            // (AbortController is used for timeouts in Proxy#fetch)
            if (abortController.signal.aborted && abortController !== this._abortController) {
                this.emit('aborted');
                this._notifyFirstLongPollCompleted(true);
                return;
            }
            this.logInfo(`Error trying to create long poll request`);
            retry(error);
        }
    }

    /**
     * Logs a debug message.
     * @param message - Message to log.
     * @param optionalParams - Optional objects to stringify and log after the message.
     */
    logDebug(message: string, ...optionalParams: any[]) {
        this._onsContext.logger.logDebug(message, 'Long Poll', ...optionalParams);
    }

    /**
     * Logs an info message.
     * @param message - Message to log.
     * @param optionalParams - Optional objects to stringify and log after the message.
     */
    logInfo(message: string, ...optionalParams: any[]) {
        this._onsContext.logger.logInfo(message, 'Long Poll', ...optionalParams);
    }

    /**
     * Logs a warning message.
     * @param message - Message to log.
     * @param optionalParams - Optional objects to stringify and log after the message.
     */
    logWarn(message: string, ...optionalParams: any[]) {
        this._onsContext.logger.logWarn(message, 'Long Poll', ...optionalParams);
    }

    /**
     * Logs an error message.
     * @param message - Message to log.
     * @param optionalParams - Optional objects to stringify and log after the message.
     * @remarks If the first optional parameter is an Error object, the message will be appended with the error message.
     */
    logError(message: string, ...optionalParams: any[]) {
        this._onsContext.logger.logError(message, 'Long Poll', ...optionalParams);
    }

}
