import type { SAM } from '@ccx-public/component-types';
import type { AdobeAssetUpdaterMetadata } from '../assets/AdobeAsset';
import AdobeAsset from '../assets/AdobeAsset';
import { memoize, observable, retry } from '../core/decorators';
import type {
    AssetClass,
    AssetLinks,
    RepositoryMetadata } from '../interface/RepositoryModel';
import {
    AssetStateChoices
} from '../interface/RepositoryModel';
import type { Permission } from '../interface/AssetModel';
import type {
    AssignmentLinks,
    AssignmentMember,
    IAssignmentPatchData,
    IRemoteAssignment } from '../interface/AssignmentModel';
import {
    AssignmentStatus
} from '../interface/AssignmentModel';
import ItemUpdater from '../core/ItemUpdater';
import PropertyUpdater from '../core/PropertyUpdater';
import AssignmentsInterface from '../interface/AssignmentsInterface';
import type { IRemoteStudentAssignment } from '../interface/StudentAssignmentModel';
import type StudentAssignment from './StudentAssignment';
import { StudentAssignmentUpdater } from './StudentAssignment';
import StudentAssignmentOrder from './StudentAssignmentOrder';
import type { Tutorial } from '../interface/TutorialModel';
import AssignmentAppMetadataResource from './AssignmentAppMetadataResource';
import type { StudentAssignmentSource } from './StudentAssignmentSource';
import type ISAMCorePrivate from '../core/ISAMCorePrivate';
import type { ISAMObject } from '../core/ISAMObject';
import ImplicitStudentAssignmentFilter from './ImplicitStudentAssignmentFilter';
import { RequestHeaders } from '../utils/classroomUtils';
import { RelType } from '../interface/LinkUtils';

export const AssignmentStatusChoices: AssignmentStatus[] = Object.values(AssignmentStatus);

export default class Assignment extends AdobeAsset implements SAM.Assignment {
    protected _assetClass: AssetClass = 'directory'; // this makes assignment a folder
    private _assignmentInterface = new AssignmentsInterface(this._core);
    private _canClassroomReadSubmissions: boolean = false;
    private _classroomId: string = '';
    private _code: string = '';
    private _dueDate?: Date; // due date is optional here otherwise the default value would be the current date
    private _externalTemplateIds: string[] = [];
    /**
     * This is the raw data from remote, we need to parse it to get the actual external tutorials.
     * Storing the raw data allows the property updater to know if the data has changed.
     * Both externalTemplateIds and externalTutorials are derived from this data.
     */
    private _externalTemplateIdsRemote: string[] = [];
    private _instructions: string = '';
    private _isAutoCreated: boolean = false;
    private _status!: AssignmentStatus;
    private _studentAssignments: StudentAssignment[] = [];
    private _tasks?: string[];
    private _templateIds?: string[];
    private _referenceIds?: string[];
    private _externalTutorials: Partial<Tutorial>[] = [];
    private _isExternalTutorialsDirty: boolean = false;
    private _assignmentAppMetadata: AssignmentAppMetadataResource;
    private _parentClassroomId: string = '';
    private _materialsAssetId: string = '';
    private _studentsAssetId: string = '';
    private _parentAssignmentsFolderAssetId: string = '';
    private _campaignId?: string;
    private _user?: AssignmentMember;

    constructor(
        readonly _core: ISAMCorePrivate,
        id: string,
        metadata?: {
            links?: AssetLinks;
        }
    ) {
        super(_core, id, metadata);
        this._assignmentAppMetadata = new AssignmentAppMetadataResource(_core, this);

        // Overridden property.
        // True to start with. If we have the metadata, we will update this.
        // Keep in mind that the assignment service does not include all Adobe
        // Asset metadata in its responses, hence why this is needed.
        this._needsRepoMetadata = true;
    }

    @observable
    get appMetadata(): AssignmentAppMetadataResource {
        return this._assignmentAppMetadata;
    }

    @observable
    get canClassroomReadSubmissions(): boolean {
        return this._canClassroomReadSubmissions;
    }

    @observable
    get campaignId(): string | undefined {
        return this._campaignId;
    }

    @observable
    get classroomId(): string {
        return this._classroomId;
    }

    /**
     * Overrides default AdobeAsset check
     * */
    @observable
    get isChildOfAssignment(): boolean {
        return false;
    }

    /**
     * Overrides default AdobeAsset check
     * */
    @observable
    get isChildOfAssignmentMaterials(): boolean {
        return false;
    }

    /**
     * Overrides default AdobeAsset check
     * */
    @observable
    get isChildOfClassroom(): boolean {
        return true;
    }

    /**
     * Overrides default AdobeAsset check
     * */
    @observable
    get isChildOfStudentAssignment(): boolean {
        return false;
    }

    /**
     * Gets all student assignments for this assignment
     * @package Only for use in SAM.js. Please use `getStudentAssignments()` instead.
     */
    @observable
    get studentAssignments(): StudentAssignment[] {
        return this._studentAssignments;
    }

    /**
     * Builds a StudentAssignmentFilter that is scoped to this Assignment ID
     * @package -- for use in SAM.js only
     */
    _getStudentAssignmentsFilter(): ImplicitStudentAssignmentFilter {
        return new ImplicitStudentAssignmentFilter({
            assignmentId: this.id,
        });
    }

    /**
     * Fetches the list of StudentAssignments for this Assignment
     * @example <caption>Get all student assignments for this assignment</caption>
     * const studentAssignments = assignment.getStudentAssignments().getList(StudentAssignmentOrder.default);
     *
     * @example <caption>Get all student assignments for this assignment that are in progress</caption>
     * const filter = assignment.getStudentAssignmentsFilter({ status: [StudentAssignmentStatus.IN_PROGRESS] });
     * const studentAssignments = assignment.getStudentAssignments().getList(StudentAssignmentOrder.default, filter);
     */
    @memoize
    getStudentAssignments(): StudentAssignmentSource {
        return this._core.classroomContext._getStudentAssignmentsSource(this._getStudentAssignmentsFilter());
    }

    @observable
    get code(): string {
        return this._code;
    }

    @observable
    get isAssignment(): boolean {
        return true;
    }

    @observable
    get instructions(): string {
        return this._instructions;
    }

    @observable
    get isAutoCreated(): boolean {
        return this._isAutoCreated;
    }

    @observable
    get dueDate(): Date | undefined {
        return this._dueDate;
    }

    @observable
    get status(): AssignmentStatus {
        return this._status;
    }

    @observable
    get tasks(): string[] {
        return this._tasks ?? [];
    }

    @observable
    get templateIds(): string[] {
        return this._templateIds ?? [];
    }

    @observable
    get parentClassroomId(): string {
        return this._parentClassroomId;
    }

    @observable
    get materialsAssetId(): string {
        return this._materialsAssetId;
    }

    @observable
    get studentsAssetId(): string {
        return this._studentsAssetId;
    }

    /**
     * @package -- for use in SAM.js only
     */
    get _parentAssignmentsAssetId(): string {
        return this._parentAssignmentsFolderAssetId;
    }

    @observable
    get externalTemplateIds(): string[] {
        if (this._isExternalTutorialsDirty) {
            this._externalTemplateIds = this._externalTemplateIdsRemote.filter((templateIdOrTutorial) => {
                try {
                    JSON.parse(templateIdOrTutorial);
                    // If it is an object then it is not a template ID, filter it out
                    return false;
                } catch {
                    return true;
                }
            });
        }

        return this._externalTemplateIds;
    }

    @observable
    get externalTutorials(): Partial<Tutorial>[] {
        if (this._isExternalTutorialsDirty) {
            this._externalTutorials = this._externalTemplateIdsRemote.reduce((acc, templateIdOrTutorial) => {
                try {
                    acc.push(JSON.parse(templateIdOrTutorial));
                } catch {
                    // Not a tutorial, ignore
                }

                return acc;
            }, [] as  Partial<Tutorial>[]);
        }

        return this._externalTutorials;
    }

    @observable
    get referenceIds(): string[] {
        return this._referenceIds ?? [];
    }

    @observable
    get membership(): AssignmentMember | undefined {
        return this._user;
    }

    /**
     * @package -- for use in SAM.js only
     * Will override any cached assignment with the latest data from the assignment service and R-API
     */
    @retry
    _loadWithRetry(): Promise<void> {
        return this._load();
    }

    /**
   * @param repoMetadata {RepositoryMetadata} If passed in, it will be used instead of loading from the service
   * @param appMetadata {any} If passed in, it will be used instead of loading from the service
   *
   * @package -- only for use in SAM.js
   */
    async _load({
        repoMetadata,
        appMetadata,
        effectivePermission,
    }: {
        repoMetadata?: RepositoryMetadata;
        appMetadata?: any;
        effectivePermission?: Permission;
    } = {}): Promise<void> {
        // Similar to what Project already has, first load the AdobeAsset so that once we get the assignment metadata we override any relevant
        // properties with the assignment metadata
        await super._load({ repoMetadata, appMetadata, effectivePermission });

        // The Assignment asset must have the assignment links from Hume to be considered complete
        // Only checking for a single link. If we have this one we can assume we have others
        const didLinksComeFromHume = this.links[RelType.ASSIGNMENTS_PRIMARY] !== undefined;

        // A majority of the Assignment model has already been set at this point using an AdobeAsset
        // However the AdobeAsset does not include the expected children array so
        // we need to call Hume to fetch this info to preserve existing behavior.
        // Once all clients have moved onto lazy loading studentAssignments this can be removed.
        const isPartialAssignment = this.studentAssignments.length === 0;
        // The assignment model is constructed of a mix of repo and app metadata, if either are missing, refetch the assignment
        const isStaleAssignment = !repoMetadata || !appMetadata;
        if (isStaleAssignment || isPartialAssignment || !didLinksComeFromHume) {
            // load the assignment metadata using the assignment service
            const assignmentMetadata = await this._assignmentInterface.getAssignment(
                this.id, undefined, { [RequestHeaders.PREFER_RAPI]: 'true' }
            );
            const session = this._core._getAssetPool().createMutationSession<Assignment>();
            AssignmentUpdater.updateRemoteItem(session, assignmentMetadata!);
            session.commit();
        }
    }

    /**
     * Updates the metadata for an assignment. If template IDs are provided then they
     * will be cloned to the assignment's working folder with new asset IDs
     */
    async updateAssignment(data: IAssignmentPatchData): Promise<void> {
        return this._core.classroomContext.updateAssignment(this.id, data);
    }

    /**
     * Clones the incoming assets to the assignment's working folder with new asset IDs
     * @param templateAssetIds - An array of asset IDs which will be used to copy the asset from the teacher to the assignment
     */
    async setTemplates(templateAssetIds: string[]): Promise<void> {
        return this._core.classroomContext.updateAssignment(this.id, { templateIds: templateAssetIds });
    }

    /**
     * Discards an assignment -- from discarded state, assignment can either be restored or permanently deleted.
     */
    async discard(): Promise<void> {
        if (this.isDiscarded) {
            return;
        }

        await this._assignmentInterface.discardAssignment(this.id, this.links);
        const assignmentPool = this._core._getAssetPool();
        const session = assignmentPool.createUpdateSession<Assignment>();
        AssignmentUpdater.updateLocalItem(session, this, { 'repo:state': AssetStateChoices[1] });
        session.commit();
    }

    /**
     * Restores an assignment from the discarded state
     */
    async restore(): Promise<void> {
        if (!this.isDiscarded) {
            return;
        }

        await this._assignmentInterface.restoreAssignment(this.id, this.links);
        const assignmentPool = this._core._getAssetPool();
        const session = assignmentPool.createUpdateSession<Assignment>();
        AssignmentUpdater.updateLocalItem(session, this, { 'repo:state': AssetStateChoices[0] });
        session.commit();
    }

    @observable
    get links(): AssignmentLinks {
        // Make a copy to avoid the client accidentally manipulating the links
        return Object.assign({}, this.__links as AssignmentLinks);
    }
}

export const AssignmentUpdater = new ItemUpdater<Assignment, Partial<IRemoteAssignment | AdobeAssetUpdaterMetadata>>({
    localItemType: Assignment,
    remoteIdProperty: 'repo:assetId',
    propertyUpdater: new PropertyUpdater({
        _campaignId: { name: 'assignment:campaignId', format: 'string' },
        _canClassroomReadSubmissions: { name: 'assignment:canClassroomReadSubmissions', format: 'boolean' },
        _name: { name: 'repo:name', format: 'string' },
        _created: { name: 'repo:createDate', format: 'date' },
        _parentClassroomAssetId: { name: 'classroom:context[classroom:classroomContext][classroom:classroomAssetId]', format: 'string' },
        _parentAssignmentsFolderAssetId: { name: 'classroom:context[classroom:assignmentsContext][classroom:assignmentsAssetId]', format: 'string' },
        _materialsAssetId: { name: 'classroom:context[assignment:materialsContext][assignment:materialsAssetId]', format: 'string' },
        _studentsAssetId: { name: 'classroom:context[assignment:studentsContext][assignment:studentsAssetId]', format: 'string' },
        _repositoryID: { name: 'repo:repositoryId', format: 'string' },
        __links: { name: '_links', format: 'object' },
        // things TBD from Assignment service are below
        _studentAssignments: {
            isArray: true,
            name: 'children',
            format: 'object',
            set: (studentAssignments: IRemoteStudentAssignment[], dest: ISAMObject) => {
                const assignment = dest as Assignment;

                // Clearing the collection in case this updater is called twice, to avoid duplicate student assignments.
                assignment.studentAssignments.length = 0;

                const session = assignment._core._getAssetPool().createMutationSession<StudentAssignment>();

                // Add computed values for each student assignment
                const studentAssignmentsWithComputedValues = studentAssignments.map(sa => ({
                    ...sa,
                    'computedAssignmentCode': assignment.code,
                    'classroom:context': {
                        'classroom:assignmentContext': {
                            'classroom:assignmentAssetId': assignment.id
                        },
                        'classroom:classroomContext': {
                            'classroom:classroomAssetId': assignment.parentClassroomId
                        },
                        'classroom:assignmentsContext': {
                            'classroom:assignmentsAssetId': assignment._parentAssignmentsAssetId
                        },
                        'assignment:materialsContext': {
                            'assignment:materialsAssetId': assignment.materialsAssetId
                        },
                        'assignment:studentsContext': {
                            'assignment:studentsAssetId': assignment.studentsAssetId
                        }
                    }
                }));

                const cachedStudentAssignments = StudentAssignmentUpdater.updateRemoteItems(
                    session,
                    studentAssignmentsWithComputedValues
                );
                session.commit();

                // cannot do assignment.studentAssignments = cachedStudentAssignments instead because it mentioned assignment.studentAssignments is read-only
                assignment.studentAssignments.push(...cachedStudentAssignments);

                const order = StudentAssignmentOrder.default;
                order.sortItems(assignment.studentAssignments);
            }
        },
        _tasks: { isArray: true, name: 'assignment:tasks' },
        _code: { name: 'assignment:code', format: 'string' },
        _classroomId: { name: 'assignment:classroomId', format: 'string' },
        _createdBy: { name: 'repo:createdBy', format: 'string' },
        _status: { name: 'assignment:status', format: 'string', choices: AssignmentStatusChoices },
        _dueDate: { name: 'assignment:dueDate', format: 'date' },
        _instructions: { name: 'assignment:instructions', format: 'string' },
        _templateIds: { name: 'assignment:templateIds', isArray: true },
        _externalTemplateIdsRemote: {
            name: 'assignment:externalTemplateIds',
            isArray: true,
            set: (externalTemplateIdsAndTutorials: string[], dest: ISAMObject) => {
                const assignment = dest as Assignment;
                assignment['_externalTemplateIdsRemote'] = externalTemplateIdsAndTutorials;
                assignment['_isExternalTutorialsDirty'] = true;
            }
        },
        _referenceIds: { name: 'assignment:referenceIds', isArray: true },
        _path: { name: 'repo:path', format: 'string' },
        _modifiedBy: { name: 'repo:modifiedBy', format: 'string' },
        _assetState: { name: 'repo:state', choices: AssetStateChoices },
        _isAutoCreated: { get: (source) => source['assignment:createdBy'] === 'adobe', format: 'boolean' },
        _user: {
            name: 'user',
            format: 'object',
            set: (remoteUser: { userId?: string } | undefined, dest: ISAMObject) => {
                const assignment = dest as Assignment;
                // Store the full user object
                // This pattern allows us to easily add more user fields in the future
                if (remoteUser?.userId) {
                    assignment['_user'] = { userId: remoteUser.userId };
                }
            }
        },
    }),
});
