import type ProjectInterface from '../interface/WorkspacesInterface';
import type Team from './Team';
import { TeamUpdater } from './Team';
import type { IItemLoader, IItemLoaderOptions, ILoadedPage, ILoadNextPage } from '../core/ItemLoader';
import type ItemPool from '../core/ItemPool';
import type { TeamConfig } from './TeamSource';
import { OrderFieldToIProjectsTeamsOrderBy } from './TeamOrder';
import type TeamFilter from './TeamFilter';

export default class TeamLoader implements IItemLoader<TeamConfig> {

    constructor(
        private _teamPool: ItemPool<Team>,
        private _projectInterface: ProjectInterface) {
    }

    async loadPage(options: IItemLoaderOptions<TeamConfig>): Promise<ILoadedPage<TeamConfig>> {
        return await this._loadPage(options);
    }

    private async _loadPage(options: IItemLoaderOptions<TeamConfig>, start?: number): Promise<ILoadedPage<TeamConfig>> {
        const { order, filter } = options;
        const { limit } = options.loadOptions ?? {};

        // We will ignore the update if we had local changes sooner than this timestamp.
        const latency = this._teamPool._core._environment.getValue('PROJECTS_LIST_UPDATE_LATENCY');
        const mostRecentValidMutation = Date.now() - latency;

        const result = await this._projectInterface.getTeams({
            orderBy: OrderFieldToIProjectsTeamsOrderBy[order.field],
            orderDirection: order.direction,
            start,
            limit,
            nameContains: (filter as TeamFilter)?.nameContains,
            state: (filter as TeamFilter)?.state
        });

        const session = this._teamPool.createLoaderUpdateSession(mostRecentValidMutation);
        const items = TeamUpdater.updateRemoteItems(session, result.teams);
        session.commit();

        // Check if we have another page to load.
        let loadNextPage: ILoadNextPage<TeamConfig> | undefined;

        // Note that it is important to skip the entire page size,
        // even if we didn't get any items back.
        // The service is based on USS which might filter out items
        // on the fly when they are retrieved instead of ahead of time
        // when the total limit is computed. As a result, some pages might
        // even come in empty.
        const nextStart = result.pageSpec.start + result.pageSpec.limit;
        if (nextStart < result.pageSpec.totalLimit) {
            loadNextPage = (options: IItemLoaderOptions<TeamConfig>) =>
                this._loadPage(options, nextStart);
        }

        return {
            items,
            total: result.pageSpec.totalLimit,
            loadNextPage,
            mostRecentValidMutation
        };
    }
}
