import { SAMError, SAMErrorCode, SAMErrorSubCode } from '../core/SAMError';
import InterfaceBase from './InterfaceBase';
import type {
    IInvitationShareBatchResponse,
    IInvitationShareResponse,
    IInvitationShareRequest,
    IInvitationSharePatchRequest,
    IPendingInvitation,
    IInvitationBulkPostResponse,
    IAddCollaboratorResult,
    IAccessRequestResult,
    IBulkAccessRequestResponse,
    IAccessRequestNotification,
    IAccessRequestPermissions,
    IAccessGrantOrRejectAccessRequestConfig,
    IInvitationServiceCapabilities,
    IAcceptInvitationByIdRequest,
    IInvitationBulkPatchResponseWithRequestId,
    CollaborationModel
} from './InvitationModel';
import type { AccessRequestOrderBy, IAccessRequestResponse, IGetAccessRequestResult } from '../collaboration/AccessRequest';
import setURLSearchParams from '@sam-js-src/utils/searchParams';

export default class InvitationInterface extends InterfaceBase {

    private _batchRequestLimit: number = 50;

    get batchRequestLimit() {
        return this._batchRequestLimit;
    }

    private _getUrl(endpoint: string): string {
        return `https://${this._core._environment.endpoints.INVITATIONS_HOST}${endpoint}`;
    }

    async getCollaborators(urn: string): Promise<IInvitationShareResponse> {
        // This allows piggybacking on a single request, so that we can support loading both the collaborators
        // and invitations at the same time, without making two separate requests (the data for both of these
        // is in the same response).
        return await this._getSharedResponse(this._getUrl(`/api/v4/share/${encodeURIComponent(urn)}?extraFeatures=direct_acl`));
    }

    /**
     * Get sharing data for a resource from the invitation service.
     *
     * @param urn - The URN of the resource
     * @param extraFeatures - Optional features: `direct_acl` (include direct ACL collaborators),
     *                        `legacy_role` (include legacy role for "all" collaborator)
     * @param descendants - Optional flag to include descendants
     * @returns Promise that resolves with the sharing response including collaborators, invitations, and metadata
     */
    async getSharingData(urn: string, extraFeatures?: string[], descendants?: boolean): Promise<IInvitationShareResponse> {
        const url = new URL(this._getUrl(`/api/v4/share/${encodeURIComponent(urn)}`));
        if (extraFeatures && extraFeatures.length > 0) {
            setURLSearchParams(url, { extraFeatures: extraFeatures.join(',') });
        }

        if (descendants) {
            setURLSearchParams(url, { descendants: 'true' });
        }
        const response = await this._doGet(url.toString(), { headers: { 'Content-Type': 'application/json' } });
        return await response.json() as IInvitationShareResponse;
    }

    async addCollaborators(urn: string, request: IInvitationShareRequest): Promise<IAddCollaboratorResult> {
        let response: Response | undefined = undefined;
        try {
            response = await this._doPost(
                this._getUrl(`/api/v4/share/${encodeURIComponent(urn)}`),
                {},
                JSON.stringify(request),
                [ 200 ]);
        } catch (error) {
            // This handles the case where the invitation service returns a 403.3 error code for an
            // invitation request originating from an account whose email address is unverified.
            const samError = error as SAMError;
            const responseWithError = await samError._additionalInfo?.response?.json();
            if (responseWithError?.errorCode === '403.3') {
                throw SAMError.create(SAMErrorCode.ACCESS_DENIED, responseWithError.statusText, samError._additionalInfo, SAMErrorSubCode.UNVERIFIED_EMAIL);
            }
            throw error;
        }
        const result: IInvitationBulkPostResponse = await response.json();

        const addResult: IAddCollaboratorResult = {
            addedCollaborators: [],
            failedCollaborators: []
        };

        for (const collaborator of result.collaborators) {
            if (collaborator.statusCode === 201) {
                addResult.addedCollaborators.push(collaborator.recipient);
                continue;
            }

            let errorCode = SAMErrorCode.BAD_REQUEST;
            let subCode: SAMErrorSubCode | undefined = undefined;

            switch (collaborator.statusCode) {
            case 403:
                errorCode = SAMErrorCode.ACCESS_DENIED;
                if (collaborator.errorCode && collaborator.errorCode === '403.3') {
                    subCode = SAMErrorSubCode.UNVERIFIED_EMAIL;
                }
                break;
            case 409:
                errorCode = SAMErrorCode.CONFLICT;
                break;
            case 500:
                errorCode = SAMErrorCode.INTERNAL_ERROR;
                break;
            }
            addResult.failedCollaborators.push({
                recipient: collaborator.recipient,
                error: SAMError.create(errorCode, collaborator.statusText, undefined, subCode),
                ...(collaborator.errorCode ? { statusSubcode: collaborator.errorCode } : {})
            });
        }

        return addResult;
    }

    async modifyCollaborators(urn: string, request: IInvitationSharePatchRequest): Promise<IInvitationBulkPatchResponseWithRequestId> {
        const response = await this._doPatch(
            // As per the invitation service API spec, mode (optional) If not specified, the API makes the effective ACL match
            // the specified role and permissions. If the value is "direct_acl", the API makes the direct ACL match the
            // specified role and permissions. Sharesheet is using this mode and we are expected to use it as well.
            this._getUrl(`/api/v4/share/${encodeURIComponent(urn)}?mode=direct_acl`),
            {},
            JSON.stringify(request),
            [ 200 ]);
        const json = await response.json() as IInvitationBulkPatchResponseWithRequestId;
        json._bulkRequestId = response.headers.get('x-request-id')!;
        return json;
    }

    async getCollaboratorListForUrns(urns: string[]): Promise<IInvitationShareBatchResponse> {
        // For single URN, call the single get share API directly instead bulkGetShares
        if (urns.length === 1) {
            const url = this._getUrl(`/api/v4/share/${encodeURIComponent(urns[0])}?extraFeatures=direct_acl,legacy_role`);
            try {
                const response = await this._doGet(url);
                const singleResponse = await response.json();
                // Wrap single response in batch format
                return {
                    jobStatus: 'completed',
                    operation: 'getBulkShares',
                    result: [
                        {
                            response: JSON.stringify(singleResponse),
                            statusCode: 200,
                            urn: urns[0]
                        }
                    ]
                };
            } catch (error) {
                // Return error in batch format to match bulk API behavior (which doesn't throw)
                const samError = error as SAMError;
                const statusCode = samError._additionalInfo?.response?.status || 500;

                // Read the actual response body from the server
                let responseBody: string;
                if (samError._additionalInfo?.response) {
                    try {
                        responseBody = await samError._additionalInfo.response.text();
                    } catch {
                        // If reading the response body fails, fall back to the error message
                        responseBody = samError.message;
                    }
                } else {
                    // If no response object is available, use the error message
                    responseBody = samError.message;
                }

                return {
                    jobStatus: 'completed',
                    operation: 'getBulkShares',
                    result: [
                        {
                            response: responseBody,
                            statusCode,
                            urn: urns[0]
                        }
                    ]
                };
            }
        }

        const request = {
            'operation': 'bulkGetShares',
            'parameters': {
                urns,
                'queryParams': {
                    'extraFeatures': 'direct_acl,legacy_role'
                }
            }
        };
        const response =  await this._doPost(
            this._getUrl(`/ops/v4/shares`),
            { 'Content-Type': 'application/json' },
            JSON.stringify(request),
            [ 200 ]);

        const result = await response.json();

        // response is 200, but result is not in proper format
        if (!result.result || !Array.isArray(result.result)) {
            throw SAMError.create(SAMErrorCode.UNKNOWN, 'Failed to parse response for Invitation Service bulk API.');
        }

        return result;
    }

    async confirmAccess(urn: string): Promise<void> {
        await this._doPost(
            this._getUrl(`/api/v4/invitations/urn/${encodeURIComponent(urn)}`),
            {},
            undefined,
            [ 200 ]);
    }

    // might be able to remove this after invitation service handles https://jira.corp.adobe.com/browse/CPX-7447
    _shouldRetryMonitorResponse(asyncResponse: Response, body: string): boolean {
        if (asyncResponse.status === 200) {
            const responseBody = JSON.parse(body);
            if (responseBody.jobStatus !== 'completed') {
                return true;
            }
        }
        return false;
    }

    async declineAccess(urn: string): Promise<void> {
        await this._doDelete(
            this._getUrl(`/api/v4/invitations/urn/${encodeURIComponent(urn)}`),
            {},
            [ 200 ]);
    }

    /**
     * Accept an invitation by invitation ID.
     *
     * Accepts a pending invitation for the calling user. The pending invitation will be converted
     * into appropriate sharing with corresponding ACL being set.
     *
     * @param invitationId - The ID of the invitation to accept
     * @param request - Optional request body with mountParent and notification
     * @returns Promise that resolves when the invitation is accepted
     *
     * @see https://git.corp.adobe.com/pages/acp-cs/CollabServices/invitations/#tag/Invitations/operation/AcceptInvitationsIDRouteV4
     */
    async acceptInvitationById(invitationId: string, request?: IAcceptInvitationByIdRequest): Promise<void> {
        await this._doPost(
            this._getUrl(`/api/v4/invitations/id/${encodeURIComponent(invitationId)}`),
            {},
            request ? JSON.stringify(request) : undefined,
            [ 200 ]);
    }

    /**
     * Delete/decline an invitation by invitation ID.
     *
     * This API can be called by the pending invitee to decline an invitation by id.
     * Collaborators with canShare permissions can also revoke an existing pending invitation.
     *
     * @param invitationId - The ID of the invitation to delete/decline
     * @returns Promise that resolves when the invitation is deleted
     *
     * @see https://git.corp.adobe.com/pages/acp-cs/CollabServices/invitations/#tag/Invitations/operation/DeleteInvitationRouteV4
     */
    async deleteInvitationById(invitationId: string): Promise<void> {
        await this._doDelete(
            this._getUrl(`/api/v4/invitations/${encodeURIComponent(invitationId)}`),
            {},
            [ 200 ]);
    }

    async getPendingInvitations(): Promise<IPendingInvitation> {
        const response = await this._doGet(
            this._getUrl('/api/v4/invitations'),
            { headers: { 'Content-Type': 'application/json' } }
        );
        return await response.json();
    }

    async createAccessRequest(
        assetIds: string[],
        notification: IAccessRequestNotification,
        requestedPermissions?: IAccessRequestPermissions,
        collaborationModel?: CollaborationModel
    ): Promise<IAccessRequestResult> {

        const request = {
            operation: 'bulkCreateAccessRequest',
            parameters: {
                urns: assetIds,
                requestBody: {
                    ...(collaborationModel ? { collaborationModel } : {}),
                    notification,
                    ...(requestedPermissions ? { requestedPermissions } : {})
                }
            }
        };

        const response = await this._doPost(
            this._getUrl('/ops/v4/shares'),
            { 'Content-Type': 'application/json' },
            JSON.stringify(request),
            [ 200 ]
        );

        const result: IBulkAccessRequestResponse = await response.json();

        const accessRequestResult: IAccessRequestResult = {
            successfulRequests: [],
            failedRequests: []
        };

        for (const item of result.result) {
            if (item.statusCode === 201) {
                accessRequestResult.successfulRequests.push(item.urn);
                continue;
            }

            let errorCode = SAMErrorCode.BAD_REQUEST;
            switch (item.statusCode) {
            case 403:
                errorCode = SAMErrorCode.ACCESS_DENIED;
                break;
            case 404:
                errorCode = SAMErrorCode.NOT_FOUND;
                break;
            }
            accessRequestResult.failedRequests.push({
                assetId: item.urn,
                error: SAMError.create(errorCode, item.response || 'Access request failed'),
                response: item.response
            });
        }

        return accessRequestResult;
    }

    async getAccessRequests(assetId: string, orderBy: AccessRequestOrderBy, limit?: number, start?: number, resourcesType?: string): Promise<IGetAccessRequestResult> {
        const url = new URL(this._getUrl(`/api/v4/accessrequests/${encodeURIComponent(assetId)}`));
        const queryParams: Record<string, string> = {
            orderBy
        };

        if (limit) {
            queryParams.limit = limit.toString();
        }

        if (start !== undefined) {
            queryParams.start = start.toString();
        }

        if (resourcesType) {
            queryParams.resourcesType = resourcesType;
        }

        setURLSearchParams(url, queryParams);

        const response = await this._doGet(url.toString(), { headers: { 'Content-Type': 'application/json' } });
        return await response.json();
    }

    async getNextPageAccessRequests(url: string): Promise<IGetAccessRequestResult> {
        const response = await this._doGet(url,  { headers: { 'Content-Type': 'application/json' } });
        return await response.json();
    }

    async grantOrRejectAccessRequest(config: IAccessGrantOrRejectAccessRequestConfig): Promise<void> {
        await this._doPost(
            this._getUrl('/api/v4/accessrequests/ops'),
            { 'Content-Type': 'application/json' },
            JSON.stringify(config),
            [ 200 ]
        );

        return;
    }

    async getAccessRequestStatus(assetId: string): Promise<IAccessRequestResponse> {
        const response = await this._doGet(
            this._getUrl(`/api/v4/user/accessrequests/${encodeURIComponent(assetId)}`),
            { headers: { 'Content-Type': 'application/json' } }
        );

        return await response.json();
    }

    /**
     * Get sharing capabilities for a single user on a resource.
     *
     * @param urn - The URN of the resource to get capabilities for
     * @param extraFeatures - Optional comma-separated list of extra features to include.
     *                       Use 'include_custom_collaborator_data' to include shareDate and notificationParameters.
     * @returns Promise that resolves with the capabilities for the resource
     */
    async getCapabilities(urn: string, extraFeatures?: string[]): Promise<IInvitationServiceCapabilities> {
        const url = new URL(this._getUrl(`/api/v4/capabilities/${encodeURIComponent(urn)}`));

        if (extraFeatures && extraFeatures.length > 0) {
            setURLSearchParams(url, { extraFeatures: extraFeatures.join(',') as string });
        }

        const response = await this._doGet(url.toString(), { headers: { 'Content-Type': 'application/json' } });
        return await response.json();
    }

    /**
     * Encodes a password for transmission to the Invitation Service.
     * Uses TextEncoder with base64 encoding, with fallback for older browsers.
     * @param password - The password to encode
     * @returns Base64-encoded password
     * @package -- for use in SAM.js only
     */
    _encodePassword(password: string): string {
        if (!password) {
            return btoa('');
        }

        try {
            const encoder = new TextEncoder();
            const encoded = encoder.encode(password);
            return btoa(String.fromCharCode(...Array.from(encoded)));
        } catch (e) {
            // Fallback for older browsers
            return btoa(password);
        }
    }

    /**
     * Gets the access URL and token for a shared resource (e.g., password-protected link).
     *
     * The Invitation Service handles both authenticated and unauthenticated requests to the same endpoint,
     * returning different access levels based on credentials provided.
     *
     * @param urn - The URN of the shared resource
     * @param password - The password to authenticate (can be empty string for public shares)
     * @param recaptchaToken - Optional recaptcha token for validation
     * @param excludeAuth - Optional flag to explicitly exclude auth header
     * @returns Response from the auth endpoint containing accessURL and accessToken
     * @package -- for use in SAM.js only
     */
    async getAccessUrlAndToken(
        urn: string,
        password: string,
        recaptchaToken?: string,
        excludeAuth?: boolean
    ): Promise<Response> {
        const url = `/api/v4/auth/${encodeURIComponent(urn)}?cdnAcceleration=true`;
        const encodedPassword = this._encodePassword(password);

        const headers: Record<string, string> = {
            'x-sharing-password': encodedPassword
        };

        // Add recaptcha headers if token is provided
        if (recaptchaToken) {
            headers['X-Feature-Override'] = 'validate_password_captcha';
            headers['Captcha-User-Response'] = recaptchaToken;
            // Note: Captcha-Site-Key can be added by the client application if required
            // by the Invitation Service configuration
        }

        return this._core._environment.fetch(
            this._getUrl(url),
            {
                method: 'GET',
                headers,
                excludeAuth // Pass through to Environment.fetch
            }
        );
    }
}
