import type WorkspaceInterface from '../interface/WorkspacesInterface';
import type { TeamRole } from './Space';
import type Space from './Space';
import { SpaceUpdater } from './Space';
import type { IItemLoader, IItemLoaderOptions, ILoadedPage, ILoadNextPage } from '../core/ItemLoader';
import type ItemPool from '../core/ItemPool';
import { OrderFieldToIProjectsSpaceOrderBy } from './SpaceOrder';
import type SpaceFilter from './SpaceFilter';
import type { SpaceConfig } from './SpaceSource';
import SAMError, { SAMErrorCode } from '../core/SAMError';
import { clearLastReloadError } from '../core/InternalProperties';

export type GetTeamRoleFn = (teamId: string) => TeamRole;
export type TeamRoleGetterFactory = () => Promise<GetTeamRoleFn>;

export default class SpaceLoader implements IItemLoader<SpaceConfig> {

    constructor(
        private _spacePool: ItemPool<Space>,
        private _workspaceInterface: WorkspaceInterface,
        private _teamRoleGetterFactory: TeamRoleGetterFactory) {
    }

    supportsFilter(filter?: SpaceFilter): boolean {
        // - only state === 'active' is supported.
        // - cannot handle teamRole === 'MEMBER' yet.
        if (!filter) {
            // If we don't provide a filter at all, then we cannot use the loader
            return false;
        }
        const { teamRole, state } = filter;
        return teamRole !== 'MEMBER' && state === 'active';
    }

    async loadPage(options: IItemLoaderOptions<SpaceConfig>): Promise<ILoadedPage<SpaceConfig>> {
        return await this._loadPage(options);
    }

    private async _loadPage(options: IItemLoaderOptions<SpaceConfig>, start?: number): Promise<ILoadedPage<SpaceConfig>> {
        const { order, filter } = options;
        const { limit } = options.loadOptions ?? {};
        const teamRole = (filter as SpaceFilter)?.teamRole;
        if (teamRole === 'MEMBER') {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Filtering only for spaces with reamRole MEMBER is not supported.');
        }

        // We will ignore the update if we had local changes sooner than this timestamp.
        const latency = this._spacePool._core._environment.getValue('PROJECTS_LIST_UPDATE_LATENCY');
        const mostRecentValidMutation = Date.now() - latency;

        const resultPromise = this._workspaceInterface.getSpaces({
            orderBy: OrderFieldToIProjectsSpaceOrderBy[order.field],
            orderDirection: order.direction,
            teamID: (filter as SpaceFilter)?.teamID,
            bookmarked: (filter as SpaceFilter)?.bookmarked,
            teamAccess: teamRole === 'NONE' ? false : undefined,
            start,
            limit
        });

        // If the teamRole was used in the request, then we trust the server resolved the correct value for the filter.
        // If we don't have teamRole in the filter, then we will lookup in the client side list of teams. If the teams are not
        // loaded yet, we will just fallback to 'NONE' until the teams are eventually loaded.
        // The team pool delegate in the space context will update the team role once the teams are known.
        const teamRoleFn = teamRole ? (() => teamRole) : await this._teamRoleGetterFactory();

        // Wait for the results after we start loading the role factory above. That will make the requests run in parallel when needed.
        const result = await resultPromise;

        const session = this._spacePool.createLoaderUpdateSession(mostRecentValidMutation);

        // Inject the teamRole in all the items that we load.
        const items = SpaceUpdater.updateRemoteItems(session, result.projects.map((item) => {
            return {
                ...item,
                teamRole: teamRoleFn(item.teamId),

                // The `/projects` listing endpoint doesn't add the state property,
                // but it only returns active spaces anyways. We can inject
                // the property automatically to make sure any restored space,
                // gets back into the correct lists.
                state: 'active'
            };
        }));

        // Make sure we ignore any reload errors now that we have refreshed the listing of the space.
        for (const item of items) {
            item[clearLastReloadError]();
        }

        session.commit();

        // Check if we have another page to load.
        let loadNextPage: ILoadNextPage<SpaceConfig> | undefined;

        // Note that it is important to skip the entire page size,
        // even if we didn't get any items back.
        // The service is based on USS which might filter out items
        // on the fly when they are retrieved instead of ahead of time
        // when the total limit is computed. As a result, some pages might
        // even come in empty.
        const nextStart = result.pageSpec.start + result.pageSpec.limit;
        if (nextStart < result.pageSpec.totalLimit) {
            loadNextPage = (options: IItemLoaderOptions<SpaceConfig>) =>
                this._loadPage(options, nextStart);
        }

        return {
            items,
            total: result.pageSpec.totalLimit,
            loadNextPage,
            mostRecentValidMutation
        };
    }

}
