/**
 * BatchOperation
 * @packageDocumentation
 * @module BatchOperation
 * @internal
 */

import type { ElementData } from '../../models/data/ElementData';
import type { GroupData } from '../../models/data/GroupData';
import type { LibraryData } from '../../models/data/LibraryData';
import type { Action, UpdateAction, InsertAction, RemoveAction, AggregateAction } from '../../models/Action';

import type { ExecuteResult } from '../Operation';
import Operation, { validatesOperation } from '../Operation';
import type {
    GroupResponse,
    ElementResponse,
    LibraryResponse
} from './utils/restAPIModelMappers';
import {
    mapLibraryDataToRequest,
    mapGroupDataToRequest,
    mapElementDataToRequest,
    mapResponseToLibraryData,
    mapResponseToElementData,
    mapResponseToGroupData
} from './utils/restAPIModelMappers';
import type { ProcessRESTOperation } from '../utils/operationUtils';
import { tokenizePlaceholders } from '../utils/operationUtils';

import { extractElementId, extractGroupId } from '../../utils/PathUtils';
import { replacePlaceholders } from '../../utils/StoreUtils';
import LibraryError from '../../errors/LibraryError';
import type LocalDriver from '.';

const supportedActionNames = [
    'updateLibrary',
    'createElement',
    'updateElement',
    'removeElement',
    'restoreElement',
    'deleteElement',
    'createGroup',
    'updateGroup',
    'removeGroup'
] as const;

type SupportedAction = Action & {
    name: (typeof supportedActionNames)[number];
};

function isSupportedAction(action: Action): action is SupportedAction {
    return supportedActionNames.includes(action.name as any);
}

function replaceData<T>(action: Action, data: T): Action {
    return { ...action, data, originalAction: action };
}

const RESPONSE_MAPPERS: {
    [s in (typeof supportedActionNames)[number]]: (action: Action, data?: any) => Action;
} = {
    updateLibrary: (action, data) => replaceData(action, mapResponseToLibraryData(data)),
    createElement: (action, data) => replaceData(action, mapResponseToElementData(data)),
    updateElement: (action, data) => replaceData(action, mapResponseToElementData(data)),
    restoreElement: (action, data) => replaceData(action, mapResponseToElementData(data)),
    removeElement: action => action,
    deleteElement: action => action,
    createGroup: (action, data) => replaceData(action, mapResponseToGroupData(data)),
    updateGroup: (action, data) => replaceData(action, mapResponseToGroupData(data)),
    removeGroup: action => action
};

export default class BatchOperation extends Operation<LocalDriver> {
    private _actionMappers = {
        updateLibrary: (action: UpdateAction<LibraryData>): ProcessRESTOperation<Partial<LibraryResponse>> => ({
            method: 'PUT',
            path: '',
            body: mapLibraryDataToRequest(action.data)
        }),
        createElement: (action: InsertAction<ElementData>): ProcessRESTOperation<Partial<ElementResponse>> => ({
            method: 'POST',
            path: 'elements',
            body: mapElementDataToRequest(action.data)
        }),
        updateElement: (action: UpdateAction<ElementData>): ProcessRESTOperation<Partial<ElementResponse>> => ({
            method: 'PUT',
            path: `elements/${extractElementId(action.path as string)}`,
            body: mapElementDataToRequest(action.data)
        }),
        removeElement: (action: RemoveAction | AggregateAction): ProcessRESTOperation<void> => ({
            method: 'DELETE',
            path: `elements/${extractElementId(action.path as string)}`
        }),
        restoreElement: (action: AggregateAction): ProcessRESTOperation => ({
            method: 'POST',
            path: `removed_elements/${action.data.id}/restore`
        }),
        deleteElement: (action: RemoveAction): ProcessRESTOperation => ({
            method: 'DELETE',
            path: `elements/${extractElementId(action.path as string)}?permanent=true`
        }),
        createGroup: (action: InsertAction<GroupData>): ProcessRESTOperation<Partial<GroupResponse>> => ({
            method: 'POST',
            path: 'groups',
            body: mapGroupDataToRequest(action.data)
        }),
        updateGroup: (action: UpdateAction<GroupData>): ProcessRESTOperation<Partial<GroupResponse>> => ({
            method: 'PUT',
            path: `groups/${extractGroupId(action.path as string)}`,
            body: mapGroupDataToRequest(action.data)
        }),
        removeGroup: (action: RemoveAction | AggregateAction): ProcessRESTOperation => ({
            method: 'DELETE',
            path: `groups/${extractGroupId(action.path as string)}${
                action.flags?.includeElements ? '?include_contents=true' : ''
            }`
        })
    };

    protected _actions: SupportedAction[] = [];

    @validatesOperation
    async execute(): Promise<ExecuteResult> {
        const payload = this._actions.map(action => this._actionMappers[action.name](action as never));
        const tokenizedPayload = tokenizePlaceholders(payload);

        const response = await this._driver.fetch(`/libraries/${this._library.id}`, {
            method: 'PATCH',
            headers: {
                'If-Match': this._library.etag
            },
            body: JSON.stringify(tokenizedPayload)
        });

        const json = await response.json();

        // Response should be an array that's the same size as the number of actions in the batch
        if (!Array.isArray(json) || json.length !== this._actions.length) {
            throw new LibraryError('INVALID_RESPONSE', 'Malformed batch response.', this._library.id);
        }

        // Given the responses, map the actual response onto actions and return the new actions.
        let newActions = this._actions.map((action, index) => {
            return RESPONSE_MAPPERS[action.name](action, json[index]);
        });

        // TODO: Bug here. Any placeholders that need to be replaced not in batch will be missed. We shouldn't do this here.
        // Replace any placeholders that might exist in the new actions
        newActions = replacePlaceholders(newActions);

        return { actions: newActions, etag: response.headers.get('ETag') as string };
    }

    supportsAction(action: Action) {
        return isSupportedAction(action);
    }
}
