import AppMetadataResource from '../assets/AppMetadataResource';
import type { ISAMCorePrivate } from '../indexPrivate';
import type StudentAssignmentFile from './StudentAssignmentFile';
import { StudentAssignmentFileUpdater } from './StudentAssignmentFile';

export default class StudentAssignmentFileAppMetadataResource extends AppMetadataResource {

    constructor(
        readonly _core: ISAMCorePrivate,
        readonly _parent: StudentAssignmentFile,
    ) {
        super(_core, _parent);
    }

    protected async _loadData() {
        // Directly fetches app metadata from R-API since there is a chance app metadata
        // has been fetched external to Hume, such as the case the StudentAssignmentFile was fetched
        // with AssetContext.getAssetWithCloudID.
        await super._loadData();
        // Updates the StudentAssignmentFile to include the latest app metadata
        const session = this._core._getAssetPool().createMutationSession<StudentAssignmentFile>(this.timestamp);
        StudentAssignmentFileUpdater.updateLocalItem(session, this._parent, this.data);
        session.commit();
    }
}
