import ShareableItem from '../collaboration/ShareableItem';
import { memoize, observable } from '../core/decorators';
import type { IProjectsSpace, IProjectsSpaceChild, IProjectsSpaceChildLinks, IProjectsSpaceChildName, IProjectsSpaceLinks, IProjectsSpaceState } from '../interface/WorkspacesModel';
import ItemUpdater from '../core/ItemUpdater';
import type { PropertyFormatType } from '../core/PropertyUpdater';
import PropertyUpdater from '../core/PropertyUpdater';
import { isDeepEqual } from '../core/ObjectUtils';
import type { ISpaceUpdate } from './SpaceContext';
import { SharedChangeEvent } from '../core/ChangeEvent';
import { clearLastReloadError, reloadSpace } from '../core/InternalProperties';
import { SAMError, assert, SAMErrorCode } from '../core/SAMError';
import ItemSource from '../core/ItemSource';
import type { SpaceSearchSource } from '../assets/SpaceSearchSource';
import SpaceSearchAssetLoader from '../assets/SpaceSearchAssetLoader';
import SpaceSearchAssetFilter from '../assets/SpaceSearchAssetFilter';
import type { AdobeAssetSource } from '../assets/AdobeAssetSource';

export type TeamRole = 'UNKNOWN' | 'NONE' | 'MEMBER';
const TeamRoles = [ 'UNKNOWN', 'NONE', 'MEMBER' ];

export type RGBColor = string;

export type SpaceAccess =
    | 'private'
    | 'team';

export type SpaceRole =
    | 'NONE'          // Has no access to the space
    | 'CONTRIBUTOR'   // Has access to all parts of the space and can edit the contents of a space
    | 'REVIEWER';     // Has read-only access to the artifacts in a space

const SpaceAccessChoices: SpaceAccess[] = [ 'private', 'team' ];
const SpaceRoleChoices: SpaceRole[]  = [ 'NONE', 'CONTRIBUTOR', 'REVIEWER' ];

export type SpaceState = IProjectsSpaceState;
const SpaceStates: SpaceState[] = [ 'active', 'archived', 'in_progress' ];

export type ISpaceChild = {
    id: string;
    _links: IProjectsSpaceChildLinks;
};

export type SpaceChildName = IProjectsSpaceChildName;

export type ISpaceReloadOptions = {
    refreshTimeout?: number;
};

type SpaceReload = {
    pending: boolean;
    promise: Promise<void>;
    generation: number;
    requestTime: number;
    inProgress: boolean;
    error?: any;
};

/// Represents the notion of a "space" where multiple Adobe account holders collaborate
export default class Space extends ShareableItem {

    private _name: string = '';
    private _repositoryID: string = '';
    private _repositoryName: string = '';
    private _pathName: string = '';
    private _created: Date = new Date();
    private _modified: Date = new Date();
    private _contributorCount: number = 0;
    private _role: SpaceRole = 'NONE';
    private _color: RGBColor = '';
    private _isBookmarked: boolean = false;
    private _teamID: string = '';
    private _teamName: string = '';
    private _description?: string;
    private _thumbnail: string = '';
    private _access: SpaceAccess = 'private';
    private _etag: string = '';
    private _children?: Map<SpaceChildName, ISpaceChild>;
    private _version: number = 0;
    private _state: SpaceState = 'active';
    private __links: IProjectsSpaceLinks | undefined;

    private _lastReload?: SpaceReload;
    private _loadedGeneration: number = 0;

    // Note that we maintain this flag based on where the item was loaded from.
    // Spaces loaded via the teamAccess=false API will have teamRole='NONE', all other
    // spaces will assume a 'UNKNOWN' role until they are updated with the correct role
    // on the client side.
    private _teamRole: TeamRole = 'UNKNOWN';

    /// The unique id that represents the space.
    get spaceID(): string {
        return this.id;
    }

    /// The user-visible name assigned to the space.
    @observable
    get name(): string {
        return this._name;
    }

    @observable
    get access(): SpaceAccess {
        return this._access;
    }

    @observable
    get etag(): string {
        return this._etag;
    }

    @observable
    get state(): SpaceState {
        return this._state;
    }

    /// The unique id of the repository that owns this space.
    @observable
    get repositoryID(): string {
        return this._repositoryID;
    }

    /// The user-visible name of the repository (i.e. the organization name) that owns this space.
    @observable
    get repositoryName(): string {
        return this._repositoryName;
    }

    /// The full path name for the space (e.g. "/content/assets/Everyone/Test Space").
    @observable
    get pathName(): string {
        return this._pathName;
    }

    /// The created date of the space, relative to 00:00:00 UTC on Jan 1, 1970.
    @observable
    get created(): Date {
        return this._created;
    }

    /// The modified date of the space, relative to 00:00:00 UTC on Jan 1, 1970.
    @observable
    get modified(): Date {
        return this._modified;
    }

    /// Total number of contributors for this space. Any groups that are added as a Contributor
    /// count as 1 toward this total.
    @observable
    get contributorCount(): number {
        return this._contributorCount;
    }

    /// Role on the space for the current user.
    @observable
    get role(): SpaceRole {
        return this._role;
    }

    /// The color assigned to the space.
    @observable
    get color(): RGBColor {
        return this._color;
    }

    /// Indicates whether the space is bookmarked (i.e. followed) by the current user.
    @observable
    get isBookmarked(): boolean {
        return this._isBookmarked;
    }

    /// The teamID of the parent team.
    @observable
    get teamID(): string {
        return this._teamID;
    }

    /// The user-visible name of the parent team.
    @observable
    get teamName(): string {
        return this._teamName;
    }

    /// Description of the space.
    @observable
    get description(): string | undefined {
        return this._description;
    }

    /// Thumbnail URL of the space.
    @observable
    get thumbnail(): string {
        return this._thumbnail;
    }

    @observable
    get version(): number {
        return this._version;
    }

    @observable
    get teamRole(): TeamRole {
        return this._teamRole;
    }

    @observable
    get _links(): IProjectsSpaceLinks | undefined {
        return this.__links;
    }

    async ensureDescription(): Promise<string> {
        if (this._description === undefined) {
            await this.load({ refreshTimeout: -1 });
        }
        return this.description ?? '';
    }

    async getChild(name: SpaceChildName): Promise<ISpaceChild | undefined> {
        if (!this._children) {
            // Retrieve the children of the space if needed.
            await this.load({ refreshTimeout: -1 });
        }
        return this._children?.get(name);
    }

    // Only used for 1-Off Invitees.
    // Memoized so the same Source and its Lists can be reused.
    @memoize
    async searchWorkingFiles(): Promise<SpaceSearchSource> {
        const { _assetPool, _ussInterface } = this._core.hostAssetContext;

        const workingFilesFolder = await this._core.hostAssetContext
            .getAssetWithRepoPath(`${this.pathName}/working_files`, this.repositoryID);

        const spaceSearchAssetLoader = new SpaceSearchAssetLoader(
            _assetPool,
            this._core,
            workingFilesFolder,
            _ussInterface,
            'excludeArtifacts',
            true // always include permissions for 1-off invitees
        );

        const implicitFilter = new SpaceSearchAssetFilter({
            asset: workingFilesFolder,
            artifactFilter: 'excludeArtifacts'
        });
        return new ItemSource(_assetPool, [ spaceSearchAssetLoader ], implicitFilter);
    }

    // All Space members should use `searchArtifacts(false)`, as the UI can assume the user has
    // full permissions. For 1-Off Invitees, use `searchArtifacts(true)`
    // Memoized so the same Source and its Lists can be reused -- note that this means you
    // cannot switch between embedPermissions = true and = false.
    @memoize
    async searchArtifacts(embedPermissions: boolean = false): Promise<SpaceSearchSource> {
        const { _assetPool, _ussInterface } = this._core.hostAssetContext;

        const spaceAdobeAsset = await this._core.hostAssetContext.getAssetWithCloudID(this.id);

        const spaceSearchAssetLoader = new SpaceSearchAssetLoader(
            _assetPool,
            this._core,
            spaceAdobeAsset,
            _ussInterface,
            'onlyArtifacts',
            embedPermissions
        );

        const implicitFilter = new SpaceSearchAssetFilter({
            asset: spaceAdobeAsset,
            artifactFilter: 'onlyArtifacts',
            // Some artifacts may be in hidden folders
            _includeHiddenRecursive: true
        });
        return new ItemSource(_assetPool, [ spaceSearchAssetLoader ], implicitFilter);
    }

    @memoize
    async getWorkingFiles(): Promise<AdobeAssetSource> {
        // Assuming repo path of working_files rather than getting it via discovery so it is compatible
        // with SAM.cpp AssetContext. When all of Spaces can be handled in SAM.cpp, this should switch back
        // to using discovery.
        // const workingFiles = await this.getChild('working_files');
        // if (!workingFiles) {
        //     throw SAMError.create(SAMErrorCode.NOT_FOUND, 'could not load working_files');
        // }
        // const folder = await this._core.hostAssetContext.getAssetWithCloudID(workingFiles.id);
        const folder = await this._core.hostAssetContext
            .getAssetWithRepoPath(`${this.pathName}/working_files`, this.repositoryID);
        return folder.children!;
    }

    async load(options?: ISpaceReloadOptions): Promise<void> {
        const refreshTimeout = options?.refreshTimeout;
        let lastReload = this._lastReload;
        const canReuseLastReload = lastReload && (
            // The previous load is still pending execution, so we could reuse the same call.
            lastReload.pending
            // Just wanted to do at least one load.
            || refreshTimeout === -1
            // Just in case the data didn't expire already.
            || (refreshTimeout && lastReload.requestTime + refreshTimeout > Date.now()));

        if (!canReuseLastReload) {
            // Otherwise let's load the space again.
            // Note that generation of reloads, we want to make sure that only the very last reload
            // gets a chance to update the space.
            lastReload = this._lastReload = {
                pending: true,
                inProgress: true,
                generation: (lastReload?.generation ?? this._loadedGeneration) + 1,
                requestTime: Date.now(),
                promise: new Promise((resolve, reject) => {
                    // Wait until the loop ends to avoid multiple queries on the same data.
                    setTimeout(() => this._executeReload(lastReload!).finally(() =>
                        lastReload!.error ? reject(lastReload!.error) : resolve()), 0);
                })
            };

            // Notify the users we have a new loading session.
            this.dispatch(SharedChangeEvent);
        }

        await lastReload!.promise;
    }

    private async _executeReload(reload: SpaceReload) {
        if (reload !== this._lastReload) {
            // The same reload will be used inside the load method up to the point when we actually execute the request.
            // However, there's a case when the `clearLastReloadError` was used while we were waiting. in the setTimeout above.
            // In that case we can just avoid fetching the request entirely.
            assert(!reload.pending, 'The pending flag must be false after the reload was cleared out.');
            return;
        }

        // Make a note that the request was executed.
        reload.pending = false;
        try {
            await this._core.spaceContext[reloadSpace](this);
        } catch (error: any) {
            reload.error = error;
        }
        // Check if the asset was removed. We will want to remove it from the lists.
        reload.inProgress = false;

        const lastReload = this._lastReload;
        if (lastReload !== reload && reload.generation <= this._loadedGeneration) {
            // This result is older than a newer request that was already applied to this object.
            // Ignore the results. This can happen if a particular request takes longer to execute
            // and a new reload was already good to go.
            return;
        }

        if (reload.error instanceof SAMError && reload.error.code === SAMErrorCode.NOT_FOUND) {
            const session = this._core.spaceContext.spacePool.createUpdateSession();
            session.queueDiscardedItem(this);
            session.commit();
        }

        // Notify about the end of the load sequence.
        this.dispatch(SharedChangeEvent);
    }

    /**
     * If the item gets updated through the listing API then we need to clear any errors from the previous reload.
     * This usually happens if the user gets re-invited to a space while the space is still in memory.
     * At that point, we need to clear the previous error when the listing API detects the new space.
     */
    [clearLastReloadError]() {
        const lastReload = this._lastReload;
        if (lastReload?.error) {
            lastReload.error = undefined;

            // Setting pending to false to be able to track it inside `_executeReload` above.
            lastReload.pending = false;

            this.dispatch(SharedChangeEvent);
        }
    }

    @observable
    get isReloading(): boolean {
        return this._lastReload?.inProgress ?? false;
    }

    @observable
    get lastReloadError(): any {
        return this._lastReload?.error;
    }

    async update(data: ISpaceUpdate) {
        await this._core.spaceContext.updateSpace(this, data);
    }

    async rename(newName: string) {
        await this._core.spaceContext.updateSpace(this, { name: newName });
    }

    async archive() {
        const resultItems = await this._core.spaceContext.archiveSpaces([ this ]);
        if (resultItems.failedResults.length) {
            throw  resultItems.failedResults[0].error;
        }
    }

    async restore(name?: string) {
        let nameMap: Map<Space, string> | undefined;
        if (name !== undefined) {
            nameMap = new Map();
            nameMap.set(this, name);
        }
        const resultItems = await this._core.spaceContext.restoreSpaces([ this ], nameMap);
        if (resultItems.failedResults.length) {
            throw  resultItems.failedResults[0].error;
        }
    }
}

const SpaceChildFormat: PropertyFormatType = {
    parse: (value: IProjectsSpaceChild): ISpaceChild => {
        return {
            id: value.id,
            _links: value._links
        };
    },
    isEqual: (a: ISpaceChild, b: ISpaceChild): boolean => {
        return a.id === b.id && isDeepEqual(a._links, b._links);
    }
};

export const SpaceUpdater = new ItemUpdater<Space, Partial<IProjectsSpace & { teamRole: TeamRole }>>({
    localItemType: Space,
    remoteIdProperty: 'id',
    propertyUpdater: new PropertyUpdater({
        '_name': 'name',
        '_access': { name: 'access', choices: SpaceAccessChoices },
        '_etag': 'etag',
        '_repositoryID': 'repositoryId',
        '_repositoryName': 'repositoryName',
        '_pathName': 'pathName',
        '_created': { name: 'createdDate', format: 'date' },
        '_modified': { name: 'modifiedDate', format: 'date' },
        '_contributorCount': { name: 'contributorCount', format: 'number' },
        '_role': { name: 'role', choices: SpaceRoleChoices },
        '_color': { name: 'color' },
        '_isBookmarked': { name: 'bookmarked', format: 'boolean' },
        '_teamID': 'teamId',
        '_teamName': 'teamName',
        '_description': 'description',
        '_thumbnail': 'thumbnail',
        '_children': { name: 'children', mapByKey: 'name', format: SpaceChildFormat },
        '_version': { name: 'version', format: 'number' },
        '_teamRole': { name: 'teamRole', choices: TeamRoles },
        '_state': { name: 'state', choices: SpaceStates },
        '__links': { name: '_links', format: 'object' }
    })
});
