import type { IComparatorMap } from '../core/ItemOrder';
import { createItemOrderFactory } from '../core/ItemOrder';
import type AccessRequestItem from './AccessRequestItem';

export type AccessRequestOrderField = 'createDate';

const OrderFieldToComparator: IComparatorMap<AccessRequestItem, AccessRequestOrderField> = {
    createDate(a: AccessRequestItem, b: AccessRequestItem): number {
        const aValue = a.createDate;
        const bValue = b.createDate;

        if (aValue < bValue) {
            return -1;
        }
        if (aValue > bValue) {
            return 1;
        }
        return 0;
    }
};

/**
 * Order for AccessRequestItem lists
 */
export default class AccessRequestOrder extends createItemOrderFactory(OrderFieldToComparator) {
    static default = new AccessRequestOrder('descending', 'createDate');
}
