import type ClassroomsInterface from '../interface/ClassroomsInterface';
import type { IItemLoader, IItemLoaderOptions, ILoadedPage } from '../core/ItemLoader';
import type ItemPool from '../core/ItemPool';
import type Classroom from './Classroom';
import { ClassroomUpdater } from './Classroom';
import type { ClassroomConfig } from './ClassroomSource';

export default class ClassroomListLoader implements IItemLoader<ClassroomConfig> {
    constructor(private _classroomPool: ItemPool<Classroom>, private _classroomsInterface: ClassroomsInterface) {}

    async loadPage(options: IItemLoaderOptions<ClassroomConfig>): Promise<ILoadedPage<ClassroomConfig>> {
        return await this._loadPage(options);
    }

    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    private async _loadPage(options: IItemLoaderOptions<ClassroomConfig>, start?: number): Promise<ILoadedPage<ClassroomConfig>> {
        const explicitFilter = options.filter;

        const profiles = explicitFilter?.profiles;
        const hasLastAccessed = explicitFilter?.hasLastAccessed;
        const hasTeachers = explicitFilter?.hasTeachers ?? false;

        const result = await this._classroomsInterface.getClassrooms({ profiles, hasLastAccessed, hasTeachers });
        const session = this._classroomPool.createLoaderUpdateSession(Date.now());
        const items = ClassroomUpdater.updateRemoteItems(session, result);
        session.commit();

        return {
            items,
            total: items.length,
            loadNextPage: undefined,
        };
    }
}
