export const isGenerationHistoryAsset = (asset: SAM.AdobeAsset): boolean => {
    return GENERATION_HISTORY_MEDIA_TYPES.includes(asset.mediaType);
};

export const isCopied = (asset: SAM.AdobeAsset): boolean => {
    // asset is not in the firefly-generations directory
    return !/^\/(?:users\/[^/]+\/)?appassets\/firefly-generations\//.test(asset.repoPath ?? '');
};

export const getHistoryAssetType = (asset: SAM.AdobeAsset): SAM.GenerationHistoryAssetType | undefined => {
    return MEDIA_TO_HISTORY_ASSET_TYPE[asset.mediaType];
};

export const makeComponentURL = async (componentData: { id: string, revision: string, length: number }, inputAsset: SAM.AdobeAsset, forceBlockDownload?: boolean): Promise<SAM.ComponentURL> => {
    const asset = inputAsset as AdobeAssetImplementation;
    await asset._ensureLink(RelType.COMPONENT);

    if (componentData.length < getBlockTransferThreshold(asset.links, DEFAULT_MAX_SINGLE_TRANSFER_SIZE) && !forceBlockDownload) {
        return {
            url: getURLFromLinks(asset.links, RelType.COMPONENT, { 'component_id': componentData.id, 'revision': componentData.revision }),
            isBlockDownload: false,
            componentId: componentData.id,
            filesize: componentData.length
        };
    }

    // Return block download URL for assets > BlockTransferThreshold, OR when client has requested to force a block download URL (this allow us to
    // return a presigned URL for assets < BlockTransferThreshold).
    await asset._ensureLink(RelType.DOWNLOAD);
    const downloadURL = getURLFromLinks(asset.links, RelType.DOWNLOAD, { resource: JSON.stringify({ 'component_id': componentData.id, 'revision': componentData.revision, reltype: RelType.COMPONENT }) });
    const assetInterface = await asset._getAssetInterface();
    return {
        url: await assetInterface.getBlockDownloadURL(downloadURL),
        isBlockDownload: true,
        componentId: componentData.id,
        filesize: componentData.length
    };
};

export const getGenerationModelDisplayName = (inputAsset: SAM.AdobeAsset): string | undefined => {
    const asset = inputAsset as AdobeAssetImplementation;
    return asset._getGenerationModelDisplayName();
};

