export const isUpscaled = (asset: SAM.AdobeAsset): boolean | undefined => {
    const { detailLevel } = asset.appMetadata.data?.firefly?.generationModel ?? {};
    if (!detailLevel) { return; }
    return detailLevel === 'full';
};

