/**
 * Returns the components that will be downloaded for this asset.
 * For legacy transparent videos (IMAGE_2_VIDEO/TEXT_2_VIDEO), returns both primary and auxiliary components.
 * For all other GHAs, returns only primary components.
 */
const getDownloadComponents = (asset: SAM.AdobeAsset): any[] => {
    // TODO: changing this to rely on the presence of firefly app metadata instead of isLoaded, as loading from the platform
    // doesn't seem to trigger `isLoaded = true` since it uses _mergeData instead of _setData
    if (!asset.appMetadata.data?.firefly) {
        return [];
    }

    const { outputComponents } = (asset.appMetadata.data as GenerationHistoryAssetAppMetadata)?.firefly || {};

    if (!outputComponents) {
        // provides a hint for anyone seeing errors for assets created before 2/3 as this data was not being populated
        // before then, and if this data is missing it will break the interface
        throw SAMError.create(SAMErrorCode.NOT_FOUND, `Resource for history asset ${asset.id} not found in app-metadata, asset is corrupt.`);
    }

    const module = getModule(asset);

    //backwards compatibility for transparent videos
    if (outputComponents.length === 2 && (module === SAM.GenerationHistoryModule.IMAGE_2_VIDEO || module === SAM.GenerationHistoryModule.TEXT_2_VIDEO)) {
        return outputComponents;
    }

    // Filter out auxiliary components for other modules, allow primary and rel type undefined components
    return outputComponents?.filter(component => component.rel !== 'auxiliary');
};

/**
 * Returns the number of components that will be downloaded for this asset.
 * For legacy transparent videos (IMAGE_2_VIDEO/TEXT_2_VIDEO), returns 2.
 */
export const numDownloadComponents = (asset: SAM.AdobeAsset): number => {
    return getDownloadComponents(asset).length || 0;
};


export const getOutputComponentURLs = async (asset: SAM.AdobeAsset, forceBlockDownload?: boolean): Promise<Record<string, SAM.ComponentURL>> => {
    const outputComponents = getDownloadComponents(asset);

    if (outputComponents.length === 0) {
        return Promise.resolve({});
    }

    const componentPromises = outputComponents.map(async (outputComponent: any) => {
        const componentURL = await makeComponentURL({ ...outputComponent, id: outputComponent.componentId }, asset, forceBlockDownload);
        return [
            outputComponent.componentId,
            {
                ...componentURL,
                rel: outputComponent.rel,
                name: outputComponent.name
            }
        ] as const;
    });

    return Object.fromEntries(await Promise.all(componentPromises));
};

export const getOutputComponentDownloadURLs = async (inputAsset: SAM.AdobeAsset, forceBlockDownload?: boolean): Promise<string[] | undefined> => {
    const asset = inputAsset as AdobeAssetImplementation;
    const outputComponentURLs = await getOutputComponentURLs(asset, forceBlockDownload);

    if (!outputComponentURLs) {
        return;
    }

    const generationHistoryInterface = asset._getGenerationHistoryInterface();

    return generationHistoryInterface.getOutputComponentDownloadURLs(outputComponentURLs);
};

const isLegacyTransparentVideo = (asset: SAM.AdobeAsset): boolean => {
    const { outputComponents } = (asset.appMetadata.data as GenerationHistoryAssetAppMetadata)?.firefly || {};
    return outputComponents?.length === 2;
};

const isTransparentVideo = (asset: SAM.AdobeAsset): boolean => {
    const { outputComponents } = (asset.appMetadata.data as GenerationHistoryAssetAppMetadata)?.firefly || {};
    return !!outputComponents && outputComponents.length > 1;
};

export const getRGBOutputComponentURL = async (asset: SAM.AdobeAsset): Promise<SAM.ComponentURL | undefined> => {
    if (!asset.appMetadata.data?.firefly) {
        return Promise.resolve(undefined);
    }

    const { outputComponents } = (asset.appMetadata.data as GenerationHistoryAssetAppMetadata)?.firefly || {};

    if (!outputComponents) {
        // provides a hint for anyone seeing errors for assets created before 2/3 as this data was not being populated
        // before then, and if this data is missing it will break the interface
        throw SAMError.create(SAMErrorCode.INTERNAL_ERROR, `Resource for history asset ${asset.id} not found in app-metadata, asset is corrupt.`);
    }

    let component: any | undefined = undefined;
    if (!isTransparentVideo(asset)) {
        component = outputComponents[0];
    } else if (isLegacyTransparentVideo(asset)) {
        component = outputComponents.find((component: any) => component.rel === 'primary');
    } else {
        // For newer transparent videos, the RGB component may not always be labeled as 'primary', so we look for the component with the color type 'RGB'
        component = outputComponents.find((component: any) => component['firefly#mediaProperties']?.video?.color === 'RGB');
    }

    if (!component) {
        return;
    }

    return makeComponentURL({ ...component, id: component.componentId }, asset, true);
};

export const getAlphaOutputComponentURL = (asset: SAM.AdobeAsset): Promise<SAM.ComponentURL | undefined> => {
    if (!asset.appMetadata.data?.firefly) {
        return Promise.resolve(undefined);
    }

    const { outputComponents } = (asset.appMetadata.data as GenerationHistoryAssetAppMetadata)?.firefly || {};

    if (!outputComponents) {
        // provides a hint for anyone seeing errors for assets created before 2/3 as this data was not being populated
        // before then, and if this data is missing it will break the interface
        throw SAMError.create(SAMErrorCode.INTERNAL_ERROR, `Resource for history asset ${asset.id} not found in app-metadata, asset is corrupt.`);
    }

    if (!isTransparentVideo(asset)) {
        return Promise.resolve(undefined);
    }

    const component = isLegacyTransparentVideo(asset)
        ? outputComponents.find((component: any) => component.rel === 'auxiliary')
        : outputComponents.find((component: any) => component['firefly#mediaProperties']?.video?.color === 'Alpha');

    if (!component) {
        return Promise.resolve(undefined);
    }

    return makeComponentURL({ ...component, id: component.componentId }, asset, true);
};

export const getProResOutputComponentURL = (asset: SAM.AdobeAsset): Promise<SAM.ComponentURL | undefined> => {
    if (!asset.appMetadata.data?.firefly) {
        return Promise.resolve(undefined);
    }

    const { outputComponents } = (asset.appMetadata.data as GenerationHistoryAssetAppMetadata)?.firefly || {};

    if (!outputComponents) {
        // provides a hint for anyone seeing errors for assets created before 2/3 as this data was not being populated
        // before then, and if this data is missing it will break the interface
        throw SAMError.create(SAMErrorCode.INTERNAL_ERROR, `Resource for history asset ${asset.id} not found in app-metadata, asset is corrupt.`);
    }

    if (!isTransparentVideo(asset)) {
        return Promise.resolve(undefined);
    }

    if (isLegacyTransparentVideo(asset)) {
        return Promise.resolve(undefined);
    }

    // For newer transparent videos, the RGBA component may not always be labeled as 'primary', so we look for the component with the color type 'RGBA'
    const component = outputComponents.find((component: any) => component['firefly#mediaProperties']?.video?.color === 'RGBA');
    if (!component) {
        return Promise.resolve(undefined);
    }

    return makeComponentURL({ ...component, id: component.componentId }, asset, true);
};

export const getOutputComponentURL = (asset: SAM.AdobeAsset, forceBlockDownload?: boolean) => {
    // TODO: changing this to rely on the presence of firefly app metadata instead of isLoaded, as loading from the platform
    // doesn't seem to trigger `isLoaded = true` since it uses _mergeData instead of _setData
    if (!asset.appMetadata.data?.firefly) {
        return;
    }

    const { outputComponents } = (asset.appMetadata.data as GenerationHistoryAssetAppMetadata)?.firefly || {};

    if (!outputComponents) {
        // provides a hint for anyone seeing errors for assets created before 2/3 as this data was not being populated
        // before then, and if this data is missing it will break the interface
        throw SAMError.create(SAMErrorCode.NOT_FOUND, `Resource for history asset ${asset.id} not found in app-metadata, asset is corrupt.`);
    }

    // There is only one output component for history assets for now
    // If this changes in the future we can update the return type to be Promise<Record<string, ComponentURL>>
    // to match getInputComponentURLs. We shouldn't do this now because app metadata does not contain the component name
    // which is what we'd want to use as a key for the response object
    const outputComponent = outputComponents[0];

    if (!outputComponent) {
        return;
    }

    // In the manifest the component id's key name is "id", but it is componentId in appMetadata to align with spec
    // schema definitions
    return makeComponentURL({ ...outputComponent, id: outputComponent.componentId }, asset, forceBlockDownload);
};

/**
 * @deprecated - use getOutputComponentDownloadURLs instead
 * Returns the download URL for the output component of a generation history asset.
 * @param inputAsset - The generation history asset to get the output component download URL for.
 * @param forceBlockDownload - Whether to force a block download URL for the output component.
 * @returns The download URL for the output component of the generation history asset.
 */
export const getOutputComponentDownloadURL = async (inputAsset: SAM.AdobeAsset, forceBlockDownload?: boolean) => {
    const asset = inputAsset as AdobeAssetImplementation;
    const outputComponentURL = await getOutputComponentURL(asset, forceBlockDownload);

    if (!outputComponentURL) {
        return;
    }

    const generationHistoryInterface = asset._getGenerationHistoryInterface();

    return generationHistoryInterface.getOutputComponentDownloadURL(outputComponentURL);
};

/******************** from manifest *************************/

/**
 * Given a manifest, return the input component data.
 */
const getInputComponent = async (asset: SAM.AdobeAsset) => {
    await (asset as AdobeAsset)._ensureLink(RelType.MANIFEST);

    if (!asset.manifest.isLoaded) {
        await asset.manifest.load();
    }

    return asset.manifest.data?.children?.find((c: any) => c.path === 'input');
};

/**
 * Returns the creation payload object FF used to generate this asset, can be found in inputComponent.request
 */
export const getGenerationInput = async (asset: SAM.AdobeAsset) => {
    const inputComponent = await getInputComponent(asset);

    // NOTE: this is intentionally left typed as any as we have no control/contract over the shape of this object
    // also the consumers (firefly) of this API are also the ones who create/manage the shape of it, this is just an
    // API to give it back to them for UI reconstruction purposes
    return inputComponent.request;
};

export const getInputComponentURLs = async (asset: SAM.AdobeAsset): Promise<Record<string, SAM.ComponentURL>> => {
    const inputComponent = await getInputComponent(asset);
    const response: Record<string, SAM.ComponentURL> = {};

    if (inputComponent.components) {
        for (const componentData of inputComponent.components as Array<{ id: string, version: string, name: string, length: number }>) {
            response[componentData.name] = await makeComponentURL({ ...componentData, revision: componentData.version }, asset);
        }
    }

    return response;
};

export const waitForSisterList = (
    sisterList: IItemList<GenerationHistoryAssetConfig>,
    maxSisters = 4
): Promise<void> => {
    let listChangeHandler: (() => void) | undefined;
    let statusChangeHandler: (() => void) | undefined;

    return new Promise<void>(resolve => {
        const cleanup = () => {
            if (listChangeHandler) {
                sisterList.off(LIST_CHANGED, listChangeHandler);
            }
            if (statusChangeHandler) {
                sisterList.off(STATE_CHANGED, statusChangeHandler);
            }
        };

        listChangeHandler = () => {
            if (sisterList.items.length === maxSisters) {
                cleanup();
                resolve();
            }
        };

        statusChangeHandler = () => {
            if (sisterList.status === AssetListStatus.ReadyFullyLoaded || sisterList.status === AssetListStatus.HadLoaderErrors) {
                cleanup();
                resolve();
            }
        };

        sisterList.on(LIST_CHANGED, listChangeHandler);
        sisterList.on(STATE_CHANGED, statusChangeHandler);

        // Check immediately
        listChangeHandler();
        statusChangeHandler();
    });
};
