import type ItemPool from '../core/ItemPool';
import type { ISAMCorePrivate } from '../indexPrivate';
import type { AdobeAsset, Library } from 'src';
import type {
    CustomModelConfig,
} from './CustomModelSource';
import type {
    IItemLoader,
    IItemLoaderOptions,
    ILoadedPage,
} from '../core/ItemLoader';
import type CustomModel from '../custom-models/CustomModel';
import { CustomModelUpdaterMelville } from '../custom-models/CustomModel';
import type { CustomModelInfoMelville } from '../interface/CustomModelModel';
import { getMostRecentValidMutation } from '../utils/loaderUtils';

export default class TrainingSetCustomModelLoader
implements IItemLoader<CustomModelConfig> {
    constructor(
        private _assetPool: ItemPool<CustomModel | AdobeAsset>,
        private _core: ISAMCorePrivate,
        private _libraryId: string
    ) {}

    async loadPage(options: IItemLoaderOptions<CustomModelConfig>): Promise<ILoadedPage<CustomModelConfig>> {
        return await this._loadPage(options);
    }

    private async _loadPage(options: IItemLoaderOptions<CustomModelConfig>): Promise<ILoadedPage<CustomModelConfig>> {
        // Fetch the training set library to make sure we have the latest list of custom models
        // and update the asset pool
        // Note: Libraries listings from Melville are considered "USS" sources (with the current exception of a public libraries-only listing),
        // and may have stale data. Which is why we use `createLoaderUpdateSession`, not `createLoaderMutationSession`.
        const libraryContext = await this._core.getLibraryContext();
        const trainingSetLibraryData = await libraryContext._libraryInterface.getLibraryData(this._libraryId);
        const latency = this._core._environment.getValue('USS_LIST_UPDATE_LATENCY');
        const mostRecentValidMutation = getMostRecentValidMutation(options.resource, latency);
        const session = this._assetPool.createLoaderUpdateSession<Library>(mostRecentValidMutation);
        libraryContext._libraryUpdater.updateRemoteItem(session, trainingSetLibraryData);
        session.commit();

        // Double check that we are dealing with a training set library
        // If so, update the asset pool with the custom models
        let items: CustomModel[] = [];
        if (trainingSetLibraryData.roles.some(role => role.type === 'cm_training_set')) {
            const customModels = trainingSetLibraryData.custom_models;
            if (!customModels) {
                return { items, total: 0 };
            }

            const cmSession = this._assetPool.createLoaderUpdateSession<CustomModel>(mostRecentValidMutation);

            items = CustomModelUpdaterMelville.updateRemoteItems(cmSession, customModels as CustomModelInfoMelville[]);

            cmSession.commit();
        }

        return {
            items,
            total: items.length
        };
    }
}
