import { LogLevel } from '../../index';
import { MessageLoggedEvent } from '@sam-js-src/core/SAMCoreEvents';
import type { EventEmitter } from 'events';

class Logger {
    static _loggerInstance: Logger;

    private _eventEmitter?: EventEmitter;

    static get instance(): Logger {
        if (!Logger._loggerInstance) {
            Logger._loggerInstance = new Logger();
        }
        return Logger._loggerInstance;
    }

    public setEventEmitter(eventEmitter: EventEmitter) {
        this._eventEmitter = eventEmitter;
    }

    private _loggerEvent(message: string, level: LogLevel) {
        this._eventEmitter?.emit('messageLogged', new MessageLoggedEvent(`[SAMJS LibraryContents] ${message}`, level));
    }

    log(message: string) {
        this._loggerEvent(message, LogLevel.Info);
    }

    warn(message: string) {
        this._loggerEvent(message, LogLevel.Warn);
    }

    error(message: string) {
        this._loggerEvent(message, LogLevel.Err);
    }

    info(message: string) {
        this._loggerEvent(message, LogLevel.Info);
    }

    debug(message: string) {
        this._loggerEvent(message, LogLevel.Debug);
    }
}

export default Logger.instance;
