import type { IItemLoader, IItemLoaderOptions, ILoadedPage } from '../core/ItemLoader';
import type { PostConfig } from './PostSource';
import type { ISAMCorePrivate } from '../indexPrivate';
import type Board from './Board';


export default class PostListLoader implements IItemLoader<PostConfig> {
    constructor(private _core: ISAMCorePrivate, private _board: Board) {}

    async loadPage(options: IItemLoaderOptions<PostConfig>): Promise<ILoadedPage<PostConfig>> {
        return await this._loadPage(options);
    }

    /** @note api does not support pagination */
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    private async _loadPage(options: IItemLoaderOptions<PostConfig>): Promise<ILoadedPage<PostConfig>> {

        const boardContext = await this._core.getBoardContext();
        const board = await boardContext.getBoardById(this._board.id);
        const posts = board._postPool.toArray();

        return {
            items: posts,
            total: posts.length,
            loadNextPage: undefined,
        };
    }
}
