import type { IImplicitFilter } from '../core/ItemFilter';
import type { default as Library } from './Library';
import ImplicitAdobeAssetFilterBase from '../assets/ImplicitAdobeAssetFilterBase';

interface ILibraryFilterOptions {
    query: string;
}

export default class LibrarySearchFilter extends ImplicitAdobeAssetFilterBase implements IImplicitFilter<Library> {
    readonly _query: string = '';
    /**
     * @package -- only for use by ILibraryFilterOptions/Loader
     */
    _matchingIDsFromSearch: Set<string> | undefined;

    constructor(options: Partial<ILibraryFilterOptions>) {
        super();
        this._query = options.query?.trim() ?? '';
    }

    get query(): string {
        return this._query;
    }

    matches(item: Library): boolean {

        if (!item.isLibrary) {
            return false;
        }

        // Check if the item's id is in the current filter's id list
        if (this._matchingIDsFromSearch && !this._matchingIDsFromSearch.has(item.id)) {
            return false;
        }

        // If the query exists but there's no id list, we probably haven't finished loading yet
        if ((this._query) && !this._matchingIDsFromSearch) {
            return false;
        }

        return super.matches(item);
    }
}
