import type {
    IItemLoader,
    IItemLoaderOptions,
    ILoadedPage
} from '../core/ItemLoader';
import type { AddressBookConfig } from './AddressBookSource';
import type AddressBook from './AddressBook';
import type ItemPool from '../core/ItemPool';
import type AddressBookInterface from '../interface/AddressBookInterface';
import type {
    IAddressBook,
    IAddressBookList
} from '../interface/AddressBookModel';
import type ItemUpdater from '../core/ItemUpdater';

export default class AddressBookLoader implements IItemLoader<AddressBookConfig> {

    constructor(
        private _addressBookPool: ItemPool<AddressBook>,
        private _addressBookInterface: AddressBookInterface,
        private _addressBookUpdater: ItemUpdater<AddressBook, IAddressBook>
    ) {}

    async loadPage(options?: IItemLoaderOptions<AddressBookConfig>): Promise<ILoadedPage<AddressBookConfig>> {
        const { limit = 100 } = options?.loadOptions || { limit: 100 };
        // Currently, pagination isn't supported because it is difficult to find a list of >1
        // AddressBooks to validate the pagination works
        const result: IAddressBookList = await this._addressBookInterface.getAddressBooks(limit);
        const session = this._addressBookPool.createLoaderMutationSession();
        const items = this._addressBookUpdater.updateRemoteItems(session, result._embedded.addressBooks);

        return { items, total: result.total };
    }
}
