import type { LibraryData } from '../data/LibraryData';
import { v4 as uuid } from 'uuid';
import { placeholderPrefix } from '../../config/constants';
import type { ResourceRef } from '../../CCLibraries';
import type { ItemId } from '../../../core/ItemBase';

const placeholderRegexString = `${placeholderPrefix}-[a-f0-9]{8}-(?:[a-f0-9]{4}-){3}[a-f0-9]{12}`;
const placeholderRegex = new RegExp(`^${placeholderRegexString}$`);
const containsPlaceholderRegex = new RegExp(`(${placeholderRegexString})`);

export type PlaceholderIdType = ItemId & `${typeof placeholderPrefix}-${string}`;

const getBaseLibraryData = (): Omit<LibraryData, 'id' | 'name'> => ({
    ownership: 'private',
    groups: [],
    elements: [],
    documentationElements: [],
    deletable: true,
    removedElements: [],
    areElementsLoaded: true,
    isLibraryLoaded: true,
    isWritable: true,
    isParentWritable: true,
    details: {
        elementCount: 0,
        documentationElementCount: 0,
        removedElementCount: 0
    },
    removeType: 'delete'
});

export const createPlaceholderId = () => `${placeholderPrefix}-${uuid()}`;

// @TODO - string.indexOf is much faster of a placeholder verification if we are willing to give up the safety of a complete id match.
// Cannot do this just now as modifying has the side effect of not completing actions...

/**
 * Check if a given id is a placeholder id
 * @param {string} id id to check
 * @returns {boolean} true if given id is a placeholder id
 */
export function isPlaceholder(id: string): id is PlaceholderIdType {
    return placeholderRegex.test(id);
}

export const extractPlaceholder = (path: string) => {
    const [ placeholder ] = containsPlaceholderRegex.exec(path) || [];
    return placeholder;
};

/**
 * Utility to create required data to create a library
 *
 * @param {Partial<LibraryData> & { id: string; name: string }} data Custom data to override base library data
 * @returns {LibraryData} Full data description for creating a library
 */
export const createLibraryData = (
    data: Partial<LibraryData> & { id: string; name: string; documentExtractionData?: ResourceRef[] }
): LibraryData => Object.assign(getBaseLibraryData(), data);
