import type Library from './Library';
import Element from './Element';
import { compareVersions } from '../utils/ActionUtils';
import LibraryError from '../errors/LibraryError';
import type { InstalledApp } from './data/ConfigurationData';

export type ActionType = 'edit' | 'openStock' | 'editInSource';
type IApplicationActionData = {
    minVersion: string;
    appCode: string;
    appName: string;
    action: string;
};

export default class ApplicationAction {
    constructor(private _item: Library | Element, private _applicationActionData: IApplicationActionData) {}

    get item() {
        return this._item;
    }

    get minVersion() {
        return this._applicationActionData.minVersion;
    }

    get appCode() {
        return this._applicationActionData.appCode;
    }

    get appName() {
        return this._applicationActionData.appName;
    }

    get action() {
        return this._applicationActionData.action;
    }

    get installedVersions() {
        const { installedApps } = this.item.apiRoot.driver.config;
        return installedApps
            .filter((app: InstalledApp) => app.code === this._applicationActionData.appCode)
            .map((app: InstalledApp) => app.version)
            .sort(compareVersions);
    }

    isCompatibleVersionInstalled() {
        return (
            this.installedVersions.length &&
            compareVersions(this._applicationActionData.minVersion, this.installedVersions[0]) >= 0
        );
    }

    async invoke() {
        if (!this.isCompatibleVersionInstalled()) {
            throw new LibraryError(
                'NOT_SUPPORTED',
                'A compatible version of the application is needed for this action',
                this.item instanceof Element ? this.item.library.id : this.item.id
            );
        }

        return this.item.apiRoot.driver.sendAction(this);
    }

    toJSON() {
        return JSON.stringify({
            ...this._applicationActionData,
            ...(this.item instanceof Element
                ? { libraryId: this.item.library.id, elementId: this.item.id }
                : { libraryId: this.item.id })
        });
    }
}

export function constructActions(
    item: Library | Element,
    action: ActionType,
    codes: string[],
    products: { [code: string]: IApplicationActionData }
) {
    return codes
        .map(code => {
            const currentAction = products[code];
            if (currentAction && (!action || action === currentAction.action)) {
                return new ApplicationAction(item, currentAction);
            }
            return undefined;
        })
        .filter(Boolean)
        .sort((a, b) => {
            if (a?.isCompatibleVersionInstalled && !b?.isCompatibleVersionInstalled) {
                return -1;
            } else if (!a?.isCompatibleVersionInstalled && b?.isCompatibleVersionInstalled) {
                return 1;
            }
            return 0;
        });
}
