import type { Project, Gradient } from '../../../../index';
import type { GradientData, TeamData } from '../../../models/Team';

export function mapProjectToTeamData(project: Project): TeamData {
    return {
        name: project.name,
        id: project.id,
        owner: project.storageAssignee,
        // This should always be defined now, but SAM.js typed it as optional for backward compatibility.
        ownerName: project.storageAssignee.displayName ?? '',
        // All project users can edit the project.
        isWritable: true
    };
}

export function mapGradientToGradientData(gradientData: Gradient): GradientData {
    return {
        type: gradientData.type,
        angle: gradientData.angle,
        stops: gradientData.stops
    };
}

