import type { ISAMObject } from '../ISAMObject';
import type IEvent from '../IEvent';
import { observableImpl } from './observable';
import type TypedEventEmitter from '../TypedEventEmitter';
import { BECOME_UNOBSERVED } from '../TypedEventEmitter';
import type { SAMObjectEventEmitter } from '../SAMObjectEventEmitter';
import { ManagedPromise } from '../../utils/ManagedPromise';

const $LAZY_LOAD_MANAGERS = Symbol('$LAZY_LOAD_MANAGERS');

type ILazyLoaded = ISAMObject & TypedEventEmitter<any> & {
    [$LAZY_LOAD_MANAGERS]: Map<IEvent, LazyLoadManager>;
}

export enum LoadStatus {
    NotLoaded = 1,
    Pending,
    Loading,
    Loaded,
    Error
}

interface ILazyLoadConfig {
    /**
     * The Event being used to notify lazy-loading state changes. This should be the shared instance
     * of the Event, so that ItemUpdater can use @lazyLoaded annotation to determine which event to
     * use automatically.
     */
    event: IEvent;
    /**
     * The callback that will fetch the lazily-loaded data. It should also update the cached property,
     * typically the private _property(ies) used for the getter(s).
     * @returns {Promise<void>}
     */
    fetchData: () => Promise<void>;
    /**
     * To prevent unnecessary fetching of data, the amount of ms to delay lazy-loading. Default is 50ms.
     * Especially helpful for cases where the user might scroll quickly through a list, where some items
     * will be off-screen before the lazy-loading starts.
     *
     * @note Use 0 when lazy-loading is managed by BatchOperationQueue, which has its own delay.
     * @note Use 0 when lazy-loading is required and shouldn't be cancelled
     */
    prefetchTimeout?: number;
    /**
     * If the {@link fetchData} throws an exception, LLM.status will be Error. If retryErrorTimeout is set,
     * it will wait that many ms before changing the status back to NotLoaded, which will notify clients to
     * check the lazy-loaded properties again, triggering another load. Since most lazy-loading is handled by
     * InterfaceBase descendents, which will already automatically retrying errors appropriately, this
     * property should be typically left unset. Misuse of this setting can cause cascading service outages if
     * the service is failing due to load, so use sparingly.
     */
    retryErrorTimeout?: number;
    /**
     * If a {@link fetchData} request is in-flight but can be cancelled, pass this callback. It should
     * return true if it was able to successfully cancel the request, false otherwise. This is useful
     * for BatchOperationQueue, to remove items from the queue before it makes the next batch call.
     * @returns {boolean}
     */
    cancelFetchData?: () => boolean;
}

type LLMConstructorConfig = ILazyLoadConfig & {
    target: ILazyLoaded;
}

const MAX_RETRIES = 5;
const FETCH_START_DELAY_MS = 100;

/**
 * For managing lazy loading of data throughout SAM.js in a consistent manner. This involves
 *
 * 1. A new custom event for the data that is lazily fetched should be created. While it can work with the default
 *    'change' event, using a custom event will allow SAM.js to track what lazy-loaded data is actively being
 *    monitored by clients so that it only fetches when necessary.
 * 2. The class that has lazy-loaded data should call static method LazyLoadManager.manageLazyLoading() to instantiate
 *    the LazyLoadManager(s) and annotate the getters for the lazy-loaded data with @lazyLoaded
 *
 * @package -- only for use in SAM.js
 */
export class LazyLoadManager {
    // config
    private readonly _target: ILazyLoaded;
    private _event: IEvent;
    private _loadStatus: LoadStatus = LoadStatus.NotLoaded;
    private _fetchData: () => Promise<void>;
    private _prefetchTimeout: number = FETCH_START_DELAY_MS;
    private _retryErrorTimeout: number = Number.POSITIVE_INFINITY;
    private _cancelFetchData?: () => boolean;

    // state
    private _prefetchResolve?: (cancelled: boolean) => void;
    private _retriesRemaining: number = MAX_RETRIES;
    private _pendingFetchPromise?: ManagedPromise<void>;


    constructor({
        target,
        event,
        fetchData,
        prefetchTimeout = FETCH_START_DELAY_MS,
        retryErrorTimeout = Number.POSITIVE_INFINITY,
        cancelFetchData,
    }: LLMConstructorConfig) {
        this._target = target;
        this._event = event;
        this._fetchData = fetchData;
        this._prefetchTimeout = prefetchTimeout;
        this._retryErrorTimeout = retryErrorTimeout;
        this._cancelFetchData = cancelFetchData;

        this._target.on(BECOME_UNOBSERVED, this._onBecomeUnobserved);
    }

    /**
     * Ideal way for client classes to instantiate LazyLoadManager(s)
     *
     * @example```ts
     * class MyClass extends SAMObjectEventEmitter {
     *    private _lazyLoadVal?: number;
     *
     *    constructor() {
     *        LazyLoadManager.manageLazyLoading(this, [{
     *            event: MyEventInstance,
     *            fetchData: this._fetchData
     *        }]);
     *    }
     *
     *    @lazyLoaded(MyEventInstance, '_lazyLoadVal')
     *    get lazyLoadVal(): number | undefined {
     *        return this._lazyLoadVal;
     *    }
     *
     *    private async _fetchData(): void {
     *        this._lazyLoadValue = await this._core.someContext.fetchData();
     *    }
     * }
     *```
     * @param {SAMObjectEventEmitter} target  the class instance that has lazy-loaded data to manage
     * @param {ILazyLoadConfig[]} configs the config for each LazyLoadManager
     */
    static manageLazyLoading(target: SAMObjectEventEmitter, configs: ILazyLoadConfig[]): void {
        const instance = target as unknown as ILazyLoaded;
        instance[$LAZY_LOAD_MANAGERS] = instance[$LAZY_LOAD_MANAGERS] || new Map();

        configs.forEach((cfg) => {
            const manager = new LazyLoadManager({
                target: instance,
                ...cfg
            });
            instance[$LAZY_LOAD_MANAGERS].set(cfg.event, manager);
        });
    }

    /**
     * Primarily for internal use/testing. Finds the relevant LazyLoadManager for a specific event (by name or
     * by shared SAMEvent instance).
     *
     * @param target {SAMObjectEventEmitter} the class instance that has lazy-loaded data to manage
     * @param event {IEvent|string} the SAMEvent instance or name
     */
    static getManager(target: SAMObjectEventEmitter, event: IEvent | string): LazyLoadManager {
        const map = (target as unknown as ILazyLoaded)[$LAZY_LOAD_MANAGERS];

        let foundEvent: IEvent | undefined;
        if (typeof event === 'string') {
            foundEvent = [ ...map.keys() ].find(e => e.type === event);
        } else {
            foundEvent = event;
        }

        const manager = map.get(foundEvent!);
        if (!manager) {
            throw new Error(`Target does not have a LazyLoadManager for event ${event}`);
        }

        return manager;
    }

    /**
     * For external code to check if a LazyLoadManager exists for a specific event.
     * @param target {SAMObjectEventEmitter} the class instance that has lazy-loaded data to manage
     * @param event {IEvent|string} the SAMEvent instance or name
     */
    static hasManager(target: SAMObjectEventEmitter, event: IEvent | string): boolean {
        try {
            return LazyLoadManager.getManager(target, event) !== undefined;
        } catch (e) {
            return false;
        }
    }

    /**
     * Used by code outside the _fetchData method that needs to modify the loadStatus.
     *
     * @param target {SAMObjectEventEmitter} the target instance that has lazy-loaded data
     * @param event {string | IEvent} the event name or instance tied to the lazy-loaded data
     * @param loadStatus {LoadStatus} the new LoadStatus
     */
    static setLoadStatus(target: SAMObjectEventEmitter, event: string | IEvent, loadStatus: LoadStatus): void {
        const manager = LazyLoadManager.getManager(target, event);
        manager.setLoadStatus(loadStatus);
    }

    /**
     * For external code to check load status.
     *
     * @param target {SAMObjectEventEmitter} the target instance that has lazy-loaded data
     * @param event {string | IEvent} the event name tied to the lazy-loaded data
     * @return LoadStatus
     */
    static getLoadStatus(target: SAMObjectEventEmitter, event: string | IEvent): LoadStatus {
        const manager = LazyLoadManager.getManager(target, event);
        return manager.loadStatus;
    }

    static fetchIfNeeded(target: SAMObjectEventEmitter, event: string | IEvent): Promise<void> {
        const manager = LazyLoadManager.getManager(target, event);
        return manager.fetchIfNeeded();
    }

    /**
     * For cases where code modifies the lazy-load data outside of fetching. Ensures the correct LoadStatus is set and
     * the appropriate event is fired.
     *
     * @param target {SAMObjectEventEmitter} the target instance that has lazy-loaded data
     * @param event {string | IEvent} the event name or instance tied to the lazy-loaded data
     */
    static updatedExternally(target: SAMObjectEventEmitter, event: string | IEvent): void {
        const manager = LazyLoadManager.getManager(target, event);
        manager.updatedExternally();
    }


    /**
     * For cases where an ItemUpdater is used where it is guaranteed that the lazy-loaded data is
     * now up-to-date, so only the load status needs updating, and no events need to be fired
     * because UpdateSession.commit() was just called or will soon be called.
     *
     * @param target {SAMObjectEventEmitter} the target instance that has lazy-loaded data
     * @param event {string | IEvent} the event name or instance tied to the lazy-loaded data
     */
    static updatedByItemUpdater(target: SAMObjectEventEmitter, event: string | IEvent): void {
        const manager = LazyLoadManager.getManager(target, event);
        manager.updatedByItemUpdater();
    }

    get loadStatus(): LoadStatus {
        return this._loadStatus;
    }

    private _onBecomeUnobserved = (eventName: string) => {
        if (eventName !== this._event.type) { return; }

        if (this._loadStatus === LoadStatus.Pending) {
            this._prefetchResolve!(true);
            return;
        }

        // Only cancel fetching if it is loading and there is a way to do it
        if (this._loadStatus === LoadStatus.Loading && this._cancelFetchData) {
            // _cancelFetchData returns true if cancel succeeds
            if (this._cancelFetchData.call(this._target)) {
                this.setLoadStatus(LoadStatus.NotLoaded);
            }
        }
    };

    private async _prefetchDelay(): Promise<boolean> {
        return new Promise((resolve) => {
            this._prefetchResolve = resolve;
            this.setLoadStatus(LoadStatus.Pending);
            setTimeout(() => {
                resolve(false);
                this._prefetchResolve = undefined;
            }, this._prefetchTimeout);
        });
    }

    onPropertyAccess(): void {
        this.fetchIfNeeded();
    }

    // Fetch data, set load status, and emit event
    async fetchIfNeeded(): Promise<void> {
        if (this._loadStatus === LoadStatus.NotLoaded) {
            this._pendingFetchPromise = new ManagedPromise();
            if (this._prefetchTimeout) {
                const cancelled = await this._prefetchDelay();
                if (cancelled) {
                    this.setLoadStatus(LoadStatus.NotLoaded);
                    this._pendingFetchPromise.resolve();
                    return;
                }
            }
            try {
                this._loadStatus = LoadStatus.Loading;

                // Note: uses `call` for better memory footprint. That way, the _fetchData implementation can be a
                // single instance of a function on the class prototype, rather than a method bound (via `=>` or
                // `.bind()`) on each instance of the class.
                await this._fetchData.call(this._target);
                // Don't transition to Loaded if it was cancelled
                if (this._loadStatus === LoadStatus.Loading) {
                    this.setLoadStatus(LoadStatus.Loaded);
                    this._pendingFetchPromise.resolve();
                }
            } catch (e) {
                this.setLoadStatus(LoadStatus.Error);
                // Rejecting here seems to cause an unhandled error that prevents tests from working,
                // but might cause runtime issues as well. For now, it's up to the client to check
                // for error status if they're expecting that the fetch succeeded.
                this._pendingFetchPromise.resolve();
            }
        }
        await this._pendingFetchPromise?.promise;
    }

    // Set load status and emit event
    setLoadStatus(loadStatus: LoadStatus) {
        if (this._loadStatus === loadStatus) { return; }

        this._loadStatus = loadStatus;
        // Transitioning to NotLoaded means the data still needs to be loaded, so listeners should be notified so
        // they can trigger lazy-loading if they want.
        if (loadStatus === LoadStatus.NotLoaded || loadStatus === LoadStatus.Loaded) {
            // Reset remaining retries on successful load
            if (loadStatus === LoadStatus.Loaded) {
                this._retriesRemaining = MAX_RETRIES;
            }

            this._target.dispatch(this._event);
        } else if (loadStatus === LoadStatus.Error
            && this._retryErrorTimeout < Number.POSITIVE_INFINITY
            && this._retriesRemaining > 0
        ) {
            // If retry-able, wait the designated time and then set back to NotLoaded, which will notify clients
            // so they can kick-off lazy loading again if desired
            setTimeout(() => {
                this._retriesRemaining--;
                if (this._loadStatus === LoadStatus.Error) {
                    this.setLoadStatus(LoadStatus.NotLoaded);
                }
            }, this._retryErrorTimeout);
        }
    }

    /**
     * For cases when something updates lazy-loaded data outside of a lazy-load fetch (such as mutating the value of a
     * field as part of a service operation), where the event must be fired and the loadStatus should be set to Loaded
     */
    updatedExternally() {
        if (this._loadStatus !== LoadStatus.Loaded) {
            // setLoadStatus will fire the event
            this.setLoadStatus(LoadStatus.Loaded);
        } else {
            this._target.dispatch(this._event);
        }
    }

    /**
     *  @see LazyLoadManager.updateByItemUpdater
     */
    updatedByItemUpdater() {
        if (this._loadStatus === LoadStatus.Pending) {
            this._prefetchResolve!(true); // cancel fetch
        }
        // It should now be safe to change to Loaded:
        // LoadStatus.Pending -- the prefetchDelay was cancelled above
        // LoadStatus.NotLoaded -- nothing is happening asynchronously
        // LoadStatus.Error -- if a retry timer is pending, it will not retry b/c the status
        //      will be Loaded
        // LoadStatus.Loading -- when the fetch completes, it will not fire a duplicate event
        //      b/c the status will already be Loaded
        this._loadStatus = LoadStatus.Loaded;
    }
}

/**
 * Annotation for marking a getter as the entry point for clients to access lazy-loaded fields, which
 * makes them observed and starts lazy-loading if needed.
 *
 * @param event {IEvent} the event instance that will be fired when the lazy-loaded data changes
 * @param privatePropNames {string[]} an array of the private property names that the annotated getter references.
 *        When ItemUpdater modifies one of these private fields, it will fire the event specified, rather than the
 *        default event for the ItemUpdater.
 */
export function lazyLoaded(event: IEvent, privatePropNames: string | string[]) {
    return function (target: SAMObjectEventEmitter, key: string, descriptor: PropertyDescriptor) {
        if (descriptor.get) {
            const getter = descriptor.get;
            descriptor.get = function (this: SAMObjectEventEmitter) {
                const manager = LazyLoadManager.getManager(this, event);
                if (!manager) {
                    throw new Error(`@lazyLoaded target is missing LazyLoadManager for event ${event.type}. Use`
                        + ' LazyLoadManager.manageLazyLoading() in constructor to configure');
                }
                manager.onPropertyAccess();
                return getter.call(this);
            };
        } else if (typeof descriptor.value === 'function') {
            const method = descriptor.value;
            const newMethod = function (this: SAMObjectEventEmitter, ...args: any[]): any {
                const manager = LazyLoadManager.getManager(this, event);
                if (!manager) {
                    throw new Error(`@lazyLoaded target is missing LazyLoadManager for event ${event.type}. Use`
                        + ' LazyLoadManager.manageLazyLoading() in constructor to configure');
                }
                manager.onPropertyAccess();
                return (method as any).apply(this, args);
            };
            descriptor.value = newMethod;
        } else {
            throw new Error('@lazyLoaded only works with getters and methods');
        }
        // layer @observable on top of @lazyLoaded
        privatePropNames = [].concat(privatePropNames as any);
        observableImpl(event, privatePropNames)(target, key, descriptor);
    };
}
