import InterfaceBase from './InterfaceBase';
import {
    updateAssetTypeForUSS
} from './USSUtils';
import type { ISearchQuery } from './USSModel';
import { OrderByToUSSOrderBy, SearchProps } from './USSModel';
import type { IOrderDirection } from '../core/ItemOrder';
import type { AdobeAssetOrderField } from '../assets/AdobeAssetOrder';
import type { IUSSFetchFieldType } from './AssetModel';
import { getUSSFetchFields } from './AssetModel';
import { RelType } from './LinkUtils';
import type Resource from '../assets/Resource';
import { excludeExpressArtifacts } from '../utils/excludeExpressArtifacts';

export interface DiscardedAssetsListingOptions {
    limit?: number;
    start?: number;
    orderDirection?: IOrderDirection;
    orderBy?: AdobeAssetOrderField;
    mediaTypes?: string[];
    excludeMediaTypes?: string[];
}

const DEFAULT_OPTIONS: DiscardedAssetsListingOptions = {
    limit: 50,
    start: 0,
    orderDirection: 'descending',
    orderBy: 'modified',
    mediaTypes: [],
    excludeMediaTypes: []
};

export const DISCARD_FETCH_FIELDS: IUSSFetchFieldType[] = [
    'creative_cloud_colortheme',
    'creative_cloud_gradient',
    '_embedded'
];

export const MOBILE_CREATIONS_MIMETYPES: string[] = [
    'application/vnd.adobe.draw.project+dcx',
    'application/vnd.adobe.sketch.project+dcx',
    'application/vnd.adobe.photoshop-mix.composition+dcx',
    'application/vnd.adobe.photoshop-fix.composition+dcx',
    'application/vnd.adobe.line.sketchbook+dcx',
    'application/vnd.adobe.layup.project+dcx',
    'application/vnd.adobe.comp.project+dcx',
    'application/vnd.adobe.clip.project+dcx',
    'application/vnd.adobe.clsproject+dcx',
    'image/vnd.adobe.cls+dcx'
];

export default class DiscardedInterface extends InterfaceBase {

    async getDiscardedAssets(options?: DiscardedAssetsListingOptions, resource?: Resource) {
        options = { ...DEFAULT_OPTIONS, ...options };
        updateAssetTypeForUSS(options.mediaTypes);
        updateAssetTypeForUSS(options.excludeMediaTypes);

        const sort_order = options.orderDirection === 'ascending' ? 'asc' : 'desc';
        const sort_orderby = OrderByToUSSOrderBy[options.orderBy || 'modified'];
        const userId = this._core._environment.getValue('USER_ID');

        const filters: ISearchQuery = {
            hints: { acp_platform_v2: true },
            creative_cloud_archive: true,
            creative_cloud_discarded_directly: true,
            [SearchProps.TYPE]: options.mediaTypes || [],
            fetch_fields: { includes: [
                ...getUSSFetchFields(),
                ...DISCARD_FETCH_FIELDS
            ] },
            // Asset must either be owned by the current user, or a Library (composite) that exists in /projects
            // and the current user has write access to it.
            op_or: [
                { [SearchProps.STORAGE_ASSIGNEE_ID]: userId },
                { op_and: [
                    { [SearchProps.STORAGE_ASSIGNEE_TYPE]: 'org' },
                    { [SearchProps.TYPE]: [ 'application/vnd.adobe.library+dcx' ] },
                    {
                        [SearchProps.REPO_ACL_MODIFIER]: 'grant',
                        [SearchProps.REPO_ACL_PRIVILEGES]: [ 'write' ],
                        [SearchProps.REPO_ACL_RELATIONS]: [ RelType.PRIMARY ]
                    }
                ] },
                {
                    // we just want the projects that are either owned by the current user
                    // or are in shared-storage
                    op_and: [
                        { op_or: [
                            { [SearchProps.STORAGE_ASSIGNEE_ID]: userId },
                            { [SearchProps.STORAGE_ASSIGNEE_TYPE]: 'org' }
                        ] },
                        { op_field_exists: [
                            'app_metadata$$cc:inheritable$$cc:team$$repo:assetId',
                            'app_metadata$$cc:inherited$$cc:team$$repo:assetId',
                        ] }
                    ]
                }
            ],
            op_none_of: [
                { [SearchProps.TYPE]: options.excludeMediaTypes || [] },
                { [SearchProps.VISIBILITY ]: [ 'hiddenSelf', 'hiddenRecursive' ] },
                { [SearchProps.FIELD_EXISTS]: [ 'app_metadata$$review:sourceAsset$$dc:format' ] },
                { [SearchProps.CREATIVE_CLOUD_TOPLEVEL_COLLECTION_NAME]: [ 'archive', 'files' ] },
                { [SearchProps.TYPE]: MOBILE_CREATIONS_MIMETYPES },
                // SAMJS-773
                ...excludeExpressArtifacts()
            ],
            sort_orderby,
            sort_order,
            limit: options.limit,
            start_index: options.start
        };

        return this._core.hostAssetContext._ussInterface.getQueryResponse(filters, resource);
    }
}
