import type { CustomModelPublishedState, CustomModelTrainingState } from '../interface/CustomModelModel';
import type { IExplicitFilter, ItemFilterRelation } from '../core/ItemFilter';
import { getDateRangeRelation, getMultiValueFilterRelation } from '../core/ItemFilter';
import type CustomModel from './CustomModel';
export interface ICustomModelListingOptions {
    publishedState?: CustomModelPublishedState;
    createDateMin?: Date;
    createDateMax?: Date;
    modifyDateMin?: Date;
    modifyDateMax?: Date;
    createdBy?: string;
    trainingSetId?: string;
    baseModelName?: string | string[];
    baseModelVersion?: string | string[];
    category?: string;
    inferenceReady?: boolean;
    trainingJobId?: string;
    trainingState?: CustomModelTrainingState;
    trainingSetVersion?: string;
}

export default class CustomModelFilter implements IExplicitFilter<CustomModel> {
    private _listingOptions: Partial<ICustomModelListingOptions> = {};

    constructor(listingOptions?: Partial<ICustomModelListingOptions>) {
        if (listingOptions) {
            this._listingOptions = listingOptions;
        }
    }

    get listingOptions() {
        return this._listingOptions;
    }

    get hash(): string {
        const o = this._listingOptions;
        return [
            o.publishedState !== undefined ? `publishedState:${o.publishedState}` : undefined,
            o.createDateMin ? `createDateMin:${o.createDateMin.getTime()}` : undefined,
            o.createDateMax ? `createDateMax:${o.createDateMax.getTime()}` : undefined,
            o.modifyDateMin ? `modifyDateMin:${o.modifyDateMin.getTime()}` : undefined,
            o.modifyDateMax ? `modifyDateMax:${o.modifyDateMax.getTime()}` : undefined,
            o.createdBy ? `createdBy:${o.createdBy}` : undefined,
            o.trainingSetId ? `trainingSetId:${o.trainingSetId}` : undefined,
            o.baseModelName ? `baseModelName:${Array.isArray(o.baseModelName) ? o.baseModelName.join(',') : o.baseModelName}` : undefined,
            o.baseModelVersion ? `baseModelVersion:${Array.isArray(o.baseModelVersion) ? o.baseModelVersion.join(',') : o.baseModelVersion}` : undefined,
            o.category ? `category:${o.category}` : undefined,
            o.inferenceReady !== undefined ? `inferenceReady:${o.inferenceReady}` : undefined,
            o.trainingJobId ? `trainingJobId:${o.trainingJobId}` : undefined,
            o.trainingState ? `trainingState:${o.trainingState}` : undefined,
            o.trainingSetVersion ? `trainingSetVersion:${o.trainingSetVersion}` : undefined,
        ].filter(x => x !== undefined).join(':');
    }

    matches(item: CustomModel) {
        if (this._listingOptions.publishedState !== undefined && item.publishedState !== this._listingOptions.publishedState) {
            return false;
        }
        if (this._listingOptions.createdBy !== undefined && item.createdBy !== this._listingOptions.createdBy) {
            return false;
        }
        if (this._listingOptions.createDateMin !== undefined && item.created < this._listingOptions.createDateMin) {
            return false;
        }
        if (this._listingOptions.createDateMax !== undefined && item.created > this._listingOptions.createDateMax) {
            return false;
        }
        if (this._listingOptions.modifyDateMin !== undefined && item.modified < this._listingOptions.modifyDateMin) {
            return false;
        }
        if (this._listingOptions.modifyDateMax !== undefined && item.modified > this._listingOptions.modifyDateMax) {
            return false;
        }
        if (this._listingOptions.trainingSetId !== undefined && item.trainingSetInfo.id !== this._listingOptions.trainingSetId) {
            return false;
        }
        if (this._listingOptions.baseModelName !== undefined) {
            const baseModelNames = Array.isArray(this._listingOptions.baseModelName)
                ? this._listingOptions.baseModelName
                : [ this._listingOptions.baseModelName ];
            if (!item.baseModelName || !baseModelNames.includes(item.baseModelName)) {
                return false;
            }
        }
        if (this._listingOptions.baseModelVersion !== undefined) {
            const baseModelVersions = Array.isArray(this._listingOptions.baseModelVersion)
                ? this._listingOptions.baseModelVersion
                : [ this._listingOptions.baseModelVersion ];
            if (!item.baseModelVersion || !baseModelVersions.includes(item.baseModelVersion)) {
                return false;
            }
        }
        if (this._listingOptions.category !== undefined && item.category !== this._listingOptions.category) {
            return false;
        }
        if (this._listingOptions.inferenceReady !== undefined && item.inferenceReady !== this._listingOptions.inferenceReady) {
            return false;
        }
        if (this._listingOptions.trainingJobId !== undefined && item.trainingInfo.jobId !== this._listingOptions.trainingJobId) {
            return false;
        }
        if (this._listingOptions.trainingState !== undefined && item.trainingInfo.trainingState !== this._listingOptions.trainingState) {
            return false;
        }
        if (this._listingOptions.trainingSetVersion !== undefined && item.trainingSetInfo.version !== this._listingOptions.trainingSetVersion) {
            return false;
        }
        return true;
    }

    /**
     * This method determines the commonality between the already present filter (other)
     * and the new filter to be applied (this). The point of this is to
     * see if the new filter (this) can build some, all, or none of it's items
     * from (other) filter.
     *
     * Subset: Means that ALL items for this filter can be built from other
     * Disjoint: No items for this filter can be built from other.
     * Unknown: Some items for this filter can be built from other.
     *
     * @note we should always determine disjoint cases first before other cases.
     * @note this = NEW FILTER, other = EXISTING FILTER
     *
     * @param other The existing filter that we are getting the relation to.
     * @returns { ItemFilterRelation }
     */
    getRelationToFilter(other: CustomModelFilter): ItemFilterRelation {
        // Simple parameters that can use the generic relation function
        const simpleParams: (keyof ICustomModelListingOptions)[] = [
            'publishedState',
            'createdBy',
            'trainingSetId',
            'baseModelName',
            'baseModelVersion',
            'category',
            'inferenceReady',
            'trainingJobId',
            'trainingState',
            'trainingSetVersion'
        ];

        const relationWrtCreatedAt: ItemFilterRelation = getDateRangeRelation(
            this._listingOptions.createDateMin,
            this._listingOptions.createDateMax,
            other._listingOptions.createDateMin,
            other._listingOptions.createDateMax);

        const relationWrtModifiedAt: ItemFilterRelation = getDateRangeRelation(
            this._listingOptions.modifyDateMin,
            this._listingOptions.modifyDateMax,
            other._listingOptions.modifyDateMin,
            other._listingOptions.modifyDateMax);

        const allRelations: ItemFilterRelation[] = [
            // Simple parameters using generic function
            ...simpleParams.map(param => this.getRelationForParam(other, param)),
            // Date range relations
            relationWrtCreatedAt,
            relationWrtModifiedAt
        ];

        //Check for any disjoint cases first
        if (allRelations.some(x => x === 'disjoint')) {
            return 'disjoint';
        }

        //Then check for any unknown cases
        if (allRelations.some(x => x === 'unknown')) {
            return 'unknown';
        }

        //All cases are subset
        return 'subset';
    }

    private getRelationForParam(
        other: CustomModelFilter,
        paramName: keyof ICustomModelListingOptions
    ): ItemFilterRelation {
        if (paramName === 'baseModelName' || paramName === 'baseModelVersion') {
            const thisValue = this._listingOptions[paramName];
            const otherValue = other._listingOptions[paramName];

            const thisArray = thisValue ? (Array.isArray(thisValue) ? thisValue : [ thisValue ]) : undefined;
            const otherArray = otherValue ? (Array.isArray(otherValue) ? otherValue : [ otherValue ]) : undefined;

            return getMultiValueFilterRelation(thisArray, otherArray);
        }

        if (this._listingOptions[paramName] === other._listingOptions[paramName]) {
            return 'subset';
        }

        if (!other._listingOptions[paramName]) {
            return 'subset';
        }

        if (!this._listingOptions[paramName]) {
            return 'unknown';
        }

        return 'disjoint';
    }


    getRelationPublishedState(other: CustomModelFilter): ItemFilterRelation {
        return this.getRelationForParam(other, 'publishedState');
    }

    getRelationCreatedBy(other: CustomModelFilter): ItemFilterRelation {
        return this.getRelationForParam(other, 'createdBy');
    }

    getRelationTrainingSetId(other: CustomModelFilter): ItemFilterRelation {
        return this.getRelationForParam(other, 'trainingSetId');
    }

    getRelationBaseModelName(other: CustomModelFilter): ItemFilterRelation {
        return this.getRelationForParam(other, 'baseModelName');
    }

    getRelationBaseModelVersion(other: CustomModelFilter): ItemFilterRelation {
        return this.getRelationForParam(other, 'baseModelVersion');
    }

    getRelationCategory(other: CustomModelFilter): ItemFilterRelation {
        return this.getRelationForParam(other, 'category');
    }

    getRelationInferenceReady(other: CustomModelFilter): ItemFilterRelation {
        return this.getRelationForParam(other, 'inferenceReady');
    }

    getRelationTrainingJobId(other: CustomModelFilter): ItemFilterRelation {
        return this.getRelationForParam(other, 'trainingJobId');
    }

    getRelationTrainingState(other: CustomModelFilter): ItemFilterRelation {
        return this.getRelationForParam(other, 'trainingState');
    }

    getRelationTrainingSetVersion(other: CustomModelFilter): ItemFilterRelation {
        return this.getRelationForParam(other, 'trainingSetVersion');
    }
}
