import type { SAM } from '@ccx-public/component-types';
import type { ISAMCorePrivate } from '../indexPrivate';
import type { AssetLinks } from '../interface/RepositoryModel';
import ItemUpdater from '../core/ItemUpdater';
import SAMError, { SAMErrorCode } from '../core/SAMError';
import { Permission } from '../interface/AssetModel';
import { NotFound } from '../core/PropertyUpdater';
import { parseEffectivePermissions } from '../interface/AssetModel';
import AdobeAsset from '../assets/AdobeAsset';
import type {
    CustomModelAppMetadataPatch,
    CustomModelInfoMelville,
    CustomModelRestrictedMetadataKey,
    CustomModelTrainingState,
    CustomModelUpdateInfoMelville } from '../interface/CustomModelModel';
import {
    CUSTOM_MODEL_RESTRICTED_METADATA_KEYS
} from '../interface/CustomModelModel';
import PropertyUpdater from '../core/PropertyUpdater';
