import { isStrictEqual } from '../core/ObjectUtils';
import type Library from '../libraries/Library';
import CustomModelInterface from '../interface/CustomModelInterface';
import { THUMBNAIL_SIZE } from '../utils/RenditionFetcher';

/**
 * Finds the last "." in a string and removes it and everything after.
 * Used to strip the file extension from repo:name on custom model.
 *
 * @example <caption>Trim "My Model.ffmodel"</caption>
 * trimRepoName("My Model.ffmodel"); // returns "My Model"
 *
 * @param s {string} name to be stripped
 * @return {string} name stripped of its' extension
 */
export const trimRepoName = (s: string): string => {
    const index = s.lastIndexOf('.');
    return s.slice(0, index);
};

export function isCustomModel(asset: AdobeAsset): asset is CustomModel {
    return asset.isCustomModel;
}

function getCustomModelPermission(value: Partial<CustomModelInfoMelville>): Permission | typeof NotFound {
    if (value.asset_acl !== undefined) {
        return parseEffectivePermissions(value.asset_acl);
    }
    // If asset_acl is not present then return NotFound
    return NotFound;
}

export default class CustomModel extends AdobeAsset implements SAM.CustomModel {
    public isCustomModel: boolean = true;

    private _displayName: string = '';
    private _conceptId: string = '';
    private _trainingMode: string = '';
    private _baseModelSuperclass: string | undefined;
    private _deltaWeightsID: string | undefined;
    private _contentType: string | undefined;
    private _compression: string = '';
    private _schemaVersion: string = '';

    private _customModelInterface = new CustomModelInterface(this._core);

    constructor(
        readonly _core: ISAMCorePrivate,
        id: string,
        metadata?: {
            links?: AssetLinks;
        }
    ) {
        super(_core, id, metadata);
    }

    @memoize
    @observable
    async trainingSet(): Promise<Library> {
        const libraryContext = await this._core.getLibraryContext();
        return await libraryContext.getLibraryByAssetId(this.trainingSetInfo.id);
    }

    /**
     * Deletes a custom model by its ID.
     * Will first check the local asset pool for the custom model to decide if we need to update the
     * local asset pool.
     */
    async permanentlyDelete(): Promise<void> {
        await this._customModelInterface.deleteCustomModel(this.id);

        const assetPool = this._core.hostAssetContext._assetPool;
        const session = assetPool.createUpdateSession<CustomModel>('Delete Custom Model');
        session.queueDiscardedItem(this);
        session.commit(); // fire notifications for tracked changes
        // The session doesn't actually remove the item from the pool
        assetPool.removeLocalItems([ this.id ]);
    }

    /**
     * Discard the custom model through melville.
     * This changes its repo:state to DISCARDED, but it can later be restored or permanently deleted.
     */
    async discard(): Promise<void> {
        if (this.isDiscarded) {
            throw SAMError.create(SAMErrorCode.INVALID_OPERATION, 'Asset is already discarded');
        }

        await this._customModelInterface.discardCustomModel(this.id);

        const customModelContext = await this._core.getCustomModelContext();
        const session = customModelContext._assetPool.createUpdateSession<CustomModel>('discard custom model'); // tracks changes to the asset

        // Update the local item with values from the remote item
        const assetContext = await this._core.getAssetContext();
        assetContext._adobeAssetUpdater.updateLocalItem(session, this, { 'repo:state': 'DISCARDED' });
        session.commit(); // fire notifications for tracked changes
    }

    async restore(): Promise<void> {
        if (!this.isDiscarded) {
            throw SAMError.create(SAMErrorCode.INVALID_OPERATION, 'Cannot restore an asset that is not discarded');
        }

        const assetContext = await this._core.getAssetContext();
        await this._customModelInterface.restoreCustomModel(this.id);
        const assetPool = this._core._getAssetPool();
        const session = assetPool.createUpdateSession<CustomModel>('restore custom model');
        assetContext._adobeAssetUpdater.updateLocalItem(session, this, { 'repo:state': 'ACTIVE' });
        session.commit();
    }

    async publish(): Promise<void> {
        if (this.publishedState === 'published') {
            return;
        }

        const customModelData = await this._customModelInterface.publish(this.id);
        const customModelContext = await this._core.getCustomModelContext();
        const session = customModelContext._assetPool.createUpdateSession<CustomModel>();

        customModelContext._customModelUpdaterMelville.updateRemoteItem(session, customModelData);
        session.commit();

        return;
    }

    async unpublish(): Promise<void> {
        if (this.publishedState === 'unpublished') {
            return;
        }

        const customModelData = await this._customModelInterface.unpublish(this.id);
        const customModelContext = await this._core.getCustomModelContext();
        const session = customModelContext._assetPool.createUpdateSession<CustomModel>();

        customModelContext._customModelUpdaterMelville.updateRemoteItem(session, customModelData);
        session.commit();

        return;
    }

    @observable
    get displayName() {
        return this._displayName;
    }

    @observable
    get inferenceReady() {
        return this.appMetadata.data['cme:inferenceReady'];
    }

    @observable
    get publishedState() {
        return this.appMetadata.data['cme:publishedState'];
    }

    @observable
    get category() {
        return this.appMetadata.data['cme:category'];
    }

    get signature(): string | undefined {
        return this.appMetadata.data['cme:signature'];
    }

    @observable
    get baseModelName(): string | undefined {
        return this.appMetadata.data['cme:baseModel']?.['name'];
    }

    @observable
    get baseModelVersion(): string | undefined {
        return this.appMetadata.data['cme:baseModel']?.['version'];
    }

    /**
   * Information related to the status of the training process for the Custom Model.
   */
    @observable
    get trainingInfo(): { trainingState: CustomModelTrainingState, progress: number, jobId: string, errorMessage: string | null, links: Record<string, any>, errorCode?: string } {
        return {
            trainingState: this.appMetadata.data['cme:training']['state'],
            progress: this.appMetadata.data['cme:training']['progress'],
            jobId: this.appMetadata.data['cme:training']['jobId'],
            errorMessage: this.appMetadata.data['cme:training']['errorMessage'],
            errorCode: this.appMetadata.data['cme:training']['errorCode'],
            links: this.appMetadata.data['cme:training']['links']
        };
    }

    /**
   * The ID and Version of the Training Set this Custom Model was trained from.
   */
    @observable
    get trainingSetInfo(): { id: string, version: string } {
        return { id: this.appMetadata.data['cme:trainingSet']['repo:assetId'], version: this.appMetadata.data['cme:trainingSet']['repo:version'] };
    }

    @observable
    get samplePrompt() {
        return this.appMetadata.data['cme:samplePrompt'];
    }

    @observable
    get renditionUrl(): string {
        return super.getRenditionURL(THUMBNAIL_SIZE);
    }

    @observable
    get conceptId() {
        return this._conceptId;
    }

    @observable
    get trainingMode() {
        return this._trainingMode;
    }

    get baseModelSuperclass(): string | undefined {
        return this._baseModelSuperclass;
    }

    @observable
    get deltaWeightsID(): string | undefined {
        return this._deltaWeightsID;
    }

    @observable
    get contentType(): string | undefined {
        return this._contentType;
    }

    @observable
    get compression(): string {
        return this._compression;
    }

    @observable
    get schemaVersion(): string {
        return this._schemaVersion;
    }


    /* This is a heuristic.  It does not definitively give information about who is or isn't a generator for this custom model
     * However, given the default way we assign permissions, it's correct until we start adding new features to custom models
     * So this is what we're using for the sake of performance until we come up with something better.
     * Used in the dashboard source to determine which models we should show.
     */
    /** @package -- for use in SAM.js only */
    get hasDefaultGeneratorPermissions(): boolean {
        return this.hasPermission(Permission.Read)
            && !this.hasPermission(Permission.Write)
            && !this.hasPermission(Permission.WriteComment);
    }

    /**
     * Updates the Custom Model with the provided options.
     *
     * @param options CustomModelUpdateInfoMelville
     * @throws {SAMErrorCode.UNSUPPORTED}
     * @returns Promise<void>
     */
    public async update(options: CustomModelUpdateInfoMelville) {
        const unsupportedKeys = Object.keys(options)
            .filter(key => CUSTOM_MODEL_RESTRICTED_METADATA_KEYS.includes(key as any));

        if (unsupportedKeys.length) {
            throw SAMError.create(
                SAMErrorCode.UNSUPPORTED,
                `Update keys are unsupported: [${unsupportedKeys}]. Use CustomModel.patchAppMetadata`
            );
        }

        const context = await this._core.getCustomModelContext();
        await context.updateCustomModel(this.id, options);
    }

    /**
     * For exceptions that CustomModel.update doesn't cover,
     * this method can be used to update the application metadata directly.
     *
     * @param patches CustomModelAppMetadataPatch[]
     * @throws {SAMErrorCode.UNSUPPORTED}
     * @returns Promise<void>
     */
    public patchAppMetadata(patches: CustomModelAppMetadataPatch[]): Promise<void> {
        const unsupportedPatches = patches.map(patch => patch.path)
            .filter((path) =>
                !CUSTOM_MODEL_RESTRICTED_METADATA_KEYS.includes(path.substring(1) as CustomModelRestrictedMetadataKey)
            );

        if (unsupportedPatches.length) {
            throw SAMError.create(
                SAMErrorCode.UNSUPPORTED,
                `Patch paths are unsupported: [${unsupportedPatches}]. Use "CustomModel.update"`,
            );
        }

        return super.patchAppMetadata(patches);
    }
}

export const CustomModelUpdaterMelville = new ItemUpdater<
CustomModel,
Partial<CustomModelInfoMelville>
>({
    localItemType: CustomModel,
    remoteIdProperty: 'repo:assetId',
    propertyUpdater: new PropertyUpdater({
        '_appMetadata._data': {
            name: 'application_metadata',
            format: 'object_subset',
            set: (parsedSource: any, dest: any) => {
                const asset = dest as AdobeAsset;
                asset.appMetadata._mergeData(parsedSource);
            }
        },
        '_displayName': { name: 'repo:name', format: { parse: trimRepoName, isEqual: isStrictEqual } },
        '_conceptId': { name: 'firefly#ffmodel', format: { parse: (ffmodel) => ffmodel.conceptId, isEqual: isStrictEqual } },
        '_contentType': { name: 'firefly#ffmodel', format: { parse: (ffmodel) => ffmodel.contentType, isEqual: isStrictEqual } },
        '_trainingMode': { name: 'firefly#ffmodel', format: { parse: (ffmodel) => ffmodel.trainingMode, isEqual: isStrictEqual } },
        '_baseModelSuperclass': { name: 'firefly#ffmodel', format: { parse: (ffmodel) => ffmodel.baseModelSuperclass, isEqual: isStrictEqual } },
        '_deltaWeightsID': { name: 'firefly#ffmodel', format: { parse: (ffmodel) => ffmodel.deltaWeightsID, isEqual: isStrictEqual } },
        '_compression': { name: 'firefly#ffmodel', format: { parse: (ffmodel) => ffmodel.compression, isEqual: isStrictEqual } },
        '_permissions': { get: getCustomModelPermission, format: 'number' },
        '_schemaVersion': { name: 'firefly#ffmodel', format: { parse: (ffmodel) => ffmodel.schemaVersion, isEqual: isStrictEqual } },
        __links: { name: '_links', format: 'object' },
        _type: 'type',
        _name: 'repo:name',
        _path: 'repo:path',
        _created: { name: 'repo:createDate', format: 'date_as_number' },
        _modified: { name: 'repo:modifyDate', format: 'date_as_number' },
        _createdBy: 'repo:createdBy',
        _version: 'version',
        _etag: 'repo:etag',
        _storageRegion: 'storage:region',
        _size: { name: 'repo:size', format: 'number' },
    }),
});
