import { NotFound } from '../core/Cache';
import type { ISAMCorePrivate, ISAMObject } from '../indexPrivate';
import type { CachedResponseData } from './CacheableResponse';
import CacheableResponse from './CacheableResponse';

export default class ResponseCache implements ISAMObject {

    constructor(public _core: ISAMCorePrivate) {
    }

    getCacheKey(key: string) {
        return `InterfaceBase-cache-${key}`;
    }

    async getCachedResponse(key: string): Promise<CacheableResponse | undefined> {
        const cachedResponseData = await this._core._environment.cache.getItem(this.getCacheKey(key));
        if (cachedResponseData === NotFound) {
            return undefined;
        }
        return CacheableResponse.deserialize(cachedResponseData as CachedResponseData);
    }

    async saveResponseToCache(key: string, response: CacheableResponse) {
        // If the value changed, save the new value to the cache and notify the caller.
        await this._core._environment.cache.setItem(this.getCacheKey(key), response.serialize());
    }

    async deleteCachedResponse(key: string) {
        await this._core._environment.cache.deleteItem(this.getCacheKey(key));
    }
}
