import type ItemBase from './ItemBase';
import type { IItemLoader, IItemLoaderOptions, ILoadedPage, ILoadNextPage } from './ItemLoader';
import type { IExplicitFilter, IImplicitFilter } from './ItemFilter';
import TypedEventEmitter from './TypedEventEmitter';
import type { IItemOrder } from './ItemOrder';
import type { IItemSourceConfig, ILoadOptions } from './ItemList';
import SAMEvent from './SAMEvent';
import Resource from '../assets/Resource';
import type ISAMCorePrivate from './ISAMCorePrivate';
import { ManagedPromise } from '../utils/ManagedPromise';
import type SAMError from './SAMError';
import { SAMErrorCode } from './SAMError';

// Must match GenericListStatus enum from SAM.cpp
export enum AssetListStatus {
    NotStarted = 1,
    HadLoaderErrors,
    Loading,
    ReadyHasMorePages,
    ReadyFullyLoaded
}

export const LOADER_STATE_CHANGED = 'loaderStateChanged';
export const LOADER_REFRESH_NEEDED = 'loaderRefreshNeeded';

export class ItemLoaderStateChangeEvent extends SAMEvent {
    constructor(readonly hasUpdatedItems: boolean = false) {
        super(LOADER_STATE_CHANGED);
    }
}

export class ItemLoaderRefreshNeededEvent extends SAMEvent {
    constructor(readonly revalidateAtPage = 0) {
        super(LOADER_REFRESH_NEEDED);
    }
}

const SharedEventWithoutItemChanges = new ItemLoaderStateChangeEvent(false);
const SharedEventWithItemChanges = new ItemLoaderStateChangeEvent(true);

/**
 * This is the structure of a page in memory.
 */
class ItemLoaderPage<LocalType extends ItemBase> {
    items?: LocalType[];
    startedGeneration: number = 0;
    loadedGeneration: number = 0;
    validatedPromise?: Promise<void>;

    // When a page refreshes it should load the same
    // page size as the first load.
    limit?: number;
}

type ItemLoaderStateEventMap = {
    /**
     * If the status of the loader changes, it will dispatch a 'change' event.
     */
    [LOADER_STATE_CHANGED]: ItemLoaderStateChangeEvent,
    [LOADER_REFRESH_NEEDED]: ItemLoaderRefreshNeededEvent
};

/**
 * A list can have multiple loaders that provide items.
 * The ItemLoaderState maintains the state of each loader attached in a list:
 * - The loaded pages and their items
 * - The error state if we had one
 * - The next available page if any
 *
 * The Loader can also refresh the items starting with page 0. The items
 * in the pre-loaded pages will only refresh once those pages are fully loaded again.
 *
 * If a previous pending request is finished after we start a refresh cycle, then
 * the items in that page will update if and only if the new cycle didn't fetch that page yet.
 */
export default class ItemLoaderState<ItemConfig extends IItemSourceConfig> extends TypedEventEmitter<ItemLoaderStateEventMap> {
    status: AssetListStatus = AssetListStatus.NotStarted;
    total: number | undefined;
    error: any;

    private _pages: ItemLoaderPage<ItemConfig['type']>[] = [];

    /**
     * Each new refresh of the pages increments the generation index.
     * We use this to differentiate between async network calls that
     * might end up providing content after a new refresh has already
     * been scheduled.
     */
    private _generation: number = 0;

    /**
     * Store the index and link of the next page. Once we reach
     * the last page, the callback will become null.
     */
    private _nextPageIndex: number = 0;
    private _nextPageCallback?: ILoadNextPage<ItemConfig>;

    /**
     * When a page load starts, we store the promise it generates,
     * so that the next calls to load will queue up to receive a notification
     * once the initial load is finished.
     */
    private _pendingLoad?: Promise<void>;

    private _mostRecentValidMutation: number | undefined;

    private _revalidateAtPage: number = 0;
    private _invalidateCache: boolean = false;

    private _assetListId?: string;

    constructor(
        public _core: ISAMCorePrivate,
        private _loader: IItemLoader<ItemConfig>,
        private _order: IItemOrder<ItemConfig['type']>,
        private _implicitFilter: IImplicitFilter<ItemConfig['type']>,
        private _filter: IExplicitFilter<ItemConfig['type']>,
    ) {
        super();
    }

    get mostRecentValidMutation(): number | undefined {
        return this._mostRecentValidMutation;
    }

    get assetListId(): string | undefined {
        return this._assetListId;
    }

    /**
     * Triggers a new generation of loading.
     * @param generation    The generation index. This number must always increment for new loads.
     * @param loadOptions The load options for this list, includes loadAllPages, limit, and refreshTimeout
     * @param revalidateAtPage (optional) revalidate pages starting at this index.
     * @param skipCache (optional) when true, skips the ResponseCache for this load operation
     * @returns Promise that can be used to know when the entire loading chain finished.
     */
    async load(generation: number, loadOptions?: ILoadOptions, revalidateAtPage: number = 0, skipCache?: boolean): Promise<void> {

        // If we were loading something before, we are aborting
        // that in favor of the new generation.

        // Reset the previous page token.
        this._generation = generation;
        this._nextPageCallback = undefined;
        this._nextPageIndex = 0;
        this._pendingLoad = undefined;
        this._revalidateAtPage = revalidateAtPage;
        this._invalidateCache = skipCache ?? false;

        await this._loadPage(loadOptions);
    }

    /**
     * Load the next page.
     * @returns Promise that can be used to know when the entire loading chain finished.
     */
    async loadNextPage(loadOptions?: ILoadOptions): Promise<void> {
        await this._loadPage(loadOptions);
    }

    /**
     * Load all the remaining pages.
     * @returns Promise that can be used to know when the entire loading chain finished.
     */
    async loadAllPages(loadOptions: ILoadOptions = {}): Promise<void> {
        loadOptions.loadAllPages = true;
        await this._loadPage(loadOptions);
    }

    /**
     * Pushes the items from all the loaded pages into the provided `dest` set.
     *
     * @param dest Set object that is populated with items from all the pages.
     */
    collectAllItems(dest: Set<ItemConfig['type']>) {
        for (const page of this._pages) {
            if (page && page.items) {
                for (const item of page.items) {
                    dest.add(item);
                }
            }
        }
    }

    /**
     * Loads or creates a page at the specified index.
     * @param pageIndex
     * @returns The page at index `pageIndex`.
     */
    private _ensurePage(pageIndex: number): ItemLoaderPage<ItemConfig['type']> {
        let page = this._pages[pageIndex];
        if (!page) {
            page = new ItemLoaderPage<ItemConfig['type']>();
            this._pages[pageIndex] = page;
        }
        return page;
    }

    /**
     * Handle only one page load at a time by storing the promise and waiting on the same
     * promise.
     *
     * Note that the promise chain can still be restarted via the `load()` method which
     * starts loading everything from the first page again.
     */
    private async _loadPage(loadOptions?: ILoadOptions) {
        // Check if there is a load already in progress. We wait on that one before making more loads.
        // This should prevent users from trying to load too many pages ahead of time.
        let pendingLoad = this._pendingLoad;
        if (!pendingLoad) {
            // We don't have anything in progress, we can go ahead and load the page.
            pendingLoad = this._loadPageImpl(loadOptions);

            // Store the pending load to make sure no requests are executed at the same time.
            this._pendingLoad = pendingLoad;
        }

        // Wait for this load to finish.
        await pendingLoad;

        if (this._pendingLoad === pendingLoad) {
            // If the load is still relevant for this generation of loading,
            // then we can go ahead and remove the promise. Note that we will
            // have to do this for all returning cases, even the paths that didn't
            // actually trigger a load above. That's because we don't know which path
            // continues the execution first and we want to make the caller can initiate
            // another call immediately.
            this._pendingLoad = undefined;
        }
    }

    /**
     * Loads the next page queued up for the loader.
     * It will also update the current page and recursively call
     * itself to load the next page if needed.
     */
    private async _loadPageImpl(loadOptions: ILoadOptions = {}) {
        const nextPageCallback = this._nextPageCallback;
        const pageIndex = this._nextPageIndex;

        // If this is not the first page and we don't have a callback, then we are out of pages to load.
        if (pageIndex && !nextPageCallback) {
            return;
        }

        // Ensure we have the next page in memory.
        const page = this._ensurePage(pageIndex);

        // Store the generation that we are in when the loading starts. If the results
        // come by the time we've already switched to a new generation, then we will
        // ignore the errors and keep the results only if no other newer generation has
        // finished loading the same page already.
        const startGeneration = this._generation;

        if (page.startedGeneration >= startGeneration) {
            // We've already loaded this or a newer generation in a different loading chain.
            return;
        }

        // Make sure the page knows we are about to reload content using the new generation.
        const previousPageGeneration = page.startedGeneration;
        page.startedGeneration = startGeneration;
        page.validatedPromise = undefined;

        // Remove the error state in case we had one before.
        this.error = null;

        // Update the status to loading state before we start loading.
        this._updateStatus(AssetListStatus.Loading);

        let result: ILoadedPage<ItemConfig> | undefined;
        let loaderError: any;
        let revalidationPromise: ManagedPromise<void> | undefined;

        try {
            loadOptions.limit ??= page.limit;
            const resource = new Resource<unknown>(this._core, {
                parseResponse: async (response) => response,
                // If we have already revalidated earlier pages, we don't want to revalidate them again
                // even if they change. Otherwise we could refresh pages infinitely if responses are not stable.
                skipRevalidation: () => pageIndex < this._revalidateAtPage,
                // Skip cache when _skipCache is true (e.g., when setNeedsRefresh is called)
                // When we fetch a page, if the cache is enabled, we may get a cached response immediately,
                // followed by a subsequent response _if_ the cache was outdated. For instance, we might have
                // loaded several pages, and one of the pages turns out to differ. If that happens, we want
                // the list to refresh itself from the beginning. The second time around, the list will quickly
                // resolve with the cached pages that still match, followed by a new fetch for the page that changed.
                // To ensure that we don't get stuck in a continuous loop refreshing the list,
                // we skip revalidating the pages we've already revalidated during this process.
                onChange: async (_value, flags) => {
                    if (flags?.loading) {
                        // We might get multiple loading updates, so only store revalidationPromise the first time.
                        if (!revalidationPromise) {
                            revalidationPromise = new ManagedPromise<void>();
                            page.validatedPromise = revalidationPromise.promise;
                        }
                    } else {
                        revalidationPromise?.resolve();
                        if (page.startedGeneration !== startGeneration) {
                            return;
                        }
                        // If the real response has changed after we already returned the results,
                        // we want to refresh the list from the beginning.
                        if (result && flags?.changed) {
                            // Start from the beginning. We should fetch the first page again.
                            // It will hit cache, which has been updated with this response.
                            // Then we wait for any more pages like normal.
                            this.dispatch(new ItemLoaderRefreshNeededEvent(pageIndex + 1));
                        }
                    }
                },
                // If an error occurs during the revalidation fetch:
                onError: async (error: any) => {
                    if (revalidationPromise) {
                        revalidationPromise.reject(error);
                    } else {
                        // If there wasn't a revalidationPromise during this error, we haven't pre-emptively
                        // returned a cached page, so we can let the promise-based exception-handling code handle the error.
                        return;
                    }
                    if (page.startedGeneration !== startGeneration) {
                        return;
                    }
                    // If we were loading other pages (e.g. later cached pages), we want to stop loading them.
                    this._nextPageCallback = undefined;
                    this.error = error;
                    this.status = AssetListStatus.HadLoaderErrors;

                    if ((error as SAMError).code === SAMErrorCode.NOT_FOUND) {
                        // Clear the list, as we would've been loading pages that are no longer valid.
                        this._pages = [];
                        this.dispatch(SharedEventWithItemChanges);
                    } else {
                        this.status = AssetListStatus.HadLoaderErrors;
                        this.dispatch(SharedEventWithoutItemChanges);
                    }
                },
            });
            // We don't want to use skipCache() here because the result will not be persisted in the cache.
            // therefore mark the resource as dirty to force a fresh fetch and persist the result in the cache.
            resource.isDirty = this._invalidateCache;
            const options: IItemLoaderOptions<ItemConfig> = {
                order: this._order,
                implicitFilter: this._implicitFilter,
                filter: this._filter,
                loadOptions,
                resource
            };
            if (nextPageCallback) {
                result = await nextPageCallback(options);

                // We delete the callback only after the page fully loaded.
                // That's so that we can retry the load if the first try fails.
                this._nextPageCallback = undefined;
            } else {
                // Load the first page.
                result = await this._loader.loadPage(options);

                // Update the asset list Id, which PLS loaders return.
                this._assetListId = result.assetListId;

                // We can update the window of valid changes at this point.
                // Note that we don't want to update the value for the rest of the pages
                // as we would still have items from the first page that might not be included yet.
                // For example, if a new asset is created and it shows up on the first page,
                // but the server didn't know about it just yet, then follow up pages
                // are not allowed to change this value until we do another reload cycle.
                this._mostRecentValidMutation = result.mostRecentValidMutation;
            }

            // Once the page is loaded, save the limit we've used for that particular page.
            // If we refresh the page we want to run it with the same page limit.
            page.limit = loadOptions.limit;
        } catch (err) {
            loaderError = err;
        }

        if (page.loadedGeneration >= startGeneration) {
            // Ignore the results as a newer loader generation already finished loading this page.
            return;
        }

        if (loaderError) {
            if (page.startedGeneration !== startGeneration) {
                // Note that we only revert if this load is still the most recent generation
                // that started the load. Otherwise, we let the newer loader handle it eventually.
                // Note that we return early in here to avoid bubbling up the error state while
                // the newer loader is still in progress.
                return;
            }

            // Revert the status of the page back to the original generation before we've started.
            // This is needed so that we can retry loading this page again next time.
            page.startedGeneration = previousPageGeneration;

        } else if (result) {
            // Note that we still use the results of the page even if the client started a new generation of loading.
            // If we've reached this point, it means that the newer generation of loading has not yet reached this page.
            // In that case, the result we just received is still new enough to considering it better than what we had before.

            page.items = result.items.filter(item => this._implicitFilter.matches(item) && this._filter.matches(item));
            this.total = result.total;
            page.loadedGeneration = startGeneration;
        }

        // Update the state before sending any events.
        const loadMorePages = await this._updateStatusAndLinkToNextPage(startGeneration, pageIndex, result, loadOptions, loaderError);

        // If we decided to load more pages, this is a good time to make that recursive async call.
        if (loadMorePages) {
            await this._loadPageImpl(loadOptions);
        }
    }

    /**
     * Checks if the loader result can be used to load the next page.
     * @param startGeneration   The generation that started this loader session.
     * @param pageIndex         The index of the loaded page.
     * @param result            The result received from the loader.
     * @param loadOptions       The options used to load this page
     * @param loaderError       The error caught during the execution of the loader, if any.
     * @returns true if the caller should continue loading the next page automatically.
     */
    private async _updateStatusAndLinkToNextPage(startGeneration: number, pageIndex: number,
        result: ILoadedPage<ItemConfig> | undefined, loadOptions: ILoadOptions, loaderError: any): Promise<boolean> {
        if (this._generation !== startGeneration || this._nextPageIndex !== pageIndex) {
            // If the result is from a previous generation, we cannot update the `next page` link because we
            // reserve the page chaining only to the current generation of the loader. We don't want to keep
            // loading pages using the previous generation anyway, so this is where we bail out
            // that previous generation.
            if (result) {
                // If we had a result and we got as far as this point, then we have new items
                // already injected. However, there's a newer load already in progress, so there's no actual
                // state change here. We only want to inform of the possibility of new items
                // being added to the page, so we dispatch an event to let the ItemList update its 'items' contents
                // to the most recent version loaded in this load chain.
                this.dispatch(SharedEventWithItemChanges);
            }
            return false;
        }

        if (!result) {
            // This page failed to load, so loading any other pages is compromised too.
            this.error = loaderError;
            this._updateStatus(AssetListStatus.HadLoaderErrors);
            return false;
        }

        // Increment the page index and store the link to the next page that we've received from the loader.
        this._nextPageIndex = pageIndex + 1;
        this._nextPageCallback = result.loadNextPage;

        if (result.loadNextPage) {
            // If we have a `loadNextPage` callback available then it means there are more pages to load.
            this._updateStatus(AssetListStatus.ReadyHasMorePages);
        } else {
            // There are no other pages left. If we had any pages beyond this point
            // before, this is a good time to remove them.
            this._pages.splice(this._nextPageIndex);

            try {
                // If any pages are waiting for validation, we want to wait for them to finish
                // before we're truly ReadyFullyLoaded. If we will be waiting, though, we should
                // emit SharedEventWithItemChanges so that the ItemList can update its items.
                // Otherwise we can skip right to ReadyFullyLoaded.
                // Some use cases call for waiting on a list to fully load in a multi-step process.
                // Before ResponseCache, that would mean the list is up-to-date with fresh info,
                // so to maintain backward-compatibility, the ReadyFullyLoaded state shouldn't
                // be broadcast until the cache is validated.
                const pagesAwaitingValidation = this._pages.map(page => page.validatedPromise).filter(Boolean);
                if (pagesAwaitingValidation.length) {
                    this.dispatch(SharedEventWithItemChanges);
                    await Promise.all(pagesAwaitingValidation);
                }
                this._updateStatus(AssetListStatus.ReadyFullyLoaded);
            } catch (error) {
                this.error = error;
                this._updateStatus(AssetListStatus.HadLoaderErrors);
                return false;
            }
        }

        // There are two cases when we want to automatically load the next pages:
        // 1) If the client requested to load all pages automatically via the `this._loadAllPages` flag.
        // 2) If the client already requested these pages before in a previous generation, we will keep reloading
        //    the pages automatically. This is the use-case when the client already scrolled past the first page and
        //    the client triggers a refresh of the list in the background. In that case the list must automatically
        //    update up-to the last scroll position. The pages will refresh one-by-one until all new items are available.

        // If the page was loaded before (case #2 above), then the page must be in the list of pages already.
        // That means the page index is lower than the size of the pages array.
        const didLoadNextPageBefore = this._nextPageIndex < this._pages.length;

        return loadOptions.loadAllPages || didLoadNextPageBefore;
    }

    /**
     * Triggers a status update event.
     * @param newStatus
     */

    private _updateStatus(newStatus: AssetListStatus) {
        // We always want to send an event when we have item changes,
        // so that the ItemList can update the item list even if the status didn't change.
        const hasItemChanges = newStatus === AssetListStatus.ReadyFullyLoaded || newStatus === AssetListStatus.ReadyHasMorePages;
        if (hasItemChanges || newStatus !== this.status) {
            this.status = newStatus;
            this.dispatch(hasItemChanges ? SharedEventWithItemChanges : SharedEventWithoutItemChanges);
        }
    }
}
