import { TypedDocumentNode as DocumentNode } from "@graphql-typed-document-node/core";
export type Maybe<T> = T | null;
export type InputMaybe<T> = Maybe<T>;
export type Exact<T extends { [key: string]: unknown }> = {
  [K in keyof T]: T[K];
};
export type MakeOptional<T, K extends keyof T> = Omit<T, K> & {
  [SubKey in K]?: Maybe<T[SubKey]>;
};
export type MakeMaybe<T, K extends keyof T> = Omit<T, K> & {
  [SubKey in K]: Maybe<T[SubKey]>;
};
export type MakeEmpty<
  T extends { [key: string]: unknown },
  K extends keyof T
> = { [_ in K]?: never };
export type Incremental<T> =
  | T
  | {
      [P in keyof T]?: P extends " $fragmentName" | "__typename" ? T[P] : never;
    };
/** All built-in and custom scalars, mapped to their actual values */
export type Scalars = {
  ID: { input: string; output: string };
  String: { input: string; output: string };
  Boolean: { input: boolean; output: boolean };
  Int: { input: number; output: number };
  Float: { input: number; output: number };
  DateTime: { input: string; output: string };
  JSON: { input: { [key: string]: any }; output: { [key: string]: any } };
  Long: { input: any; output: any };
  Url: { input: any; output: any };
};

export type AccessPrivilegeFilter = {
  privilege: Privilege;
};

export type AccessedInAppFilter = {
  in?: InputMaybe<Array<Scalars["String"]["input"]>>;
};

/** Input type for updating the accessedInApp property of an asset. */
export type AccessedInAppInput = {
  /** The appName that would be updated in accessedInApp label */
  appName: Scalars["String"]["input"];
};

/** It is used to provide additional information to distiguish between accessible themes */
export type AccessibilityData = {
  /** Indicating whether color theme is color blind safe or not */
  colorBlindSafe?: Maybe<Scalars["Boolean"]["output"]>;
  /** The WCAG conformance level for the color theme, indicating the degree to which contrast between colors meets accessibility requirements */
  wcagLevel?: Maybe<WcagLevel>;
};

export type AllAssetsList = AssetList & {
  assetListConnection: AssetListConnection;
  /**
   * Asset List id.
   * To be used in communication with ONS, to receive updates about this list.
   */
  assetListId: Scalars["ID"]["output"];
};

export type AllAssetsListAssetListConnectionArgs = {
  accessPrivilege?: InputMaybe<AccessPrivilegeFilter>;
  after?: InputMaybe<Scalars["String"]["input"]>;
  filter: AssetListFilter;
  first: Scalars["Int"]["input"];
  orderBy?: InputMaybe<AssetListOrderByInput>;
};

/** An alternative array of thumbnail images for a file, which can differ in characteristics such as size or image encoding. */
export type AlternativeArrayOfThumbnails = {
  _type: Scalars["String"]["output"];
  patternProperties?: Maybe<Scalars["JSON"]["output"]>;
};

/**
 * Information about an ancestor asset.
 * This is a partial view provided for select ancestors (e.g., project hierarchy).
 * Use repo_ancestors for the complete ordered ancestor chain and join by assetId.
 */
export type AncestorInfo = {
  /** The asset ID of the ancestor (one of repo_ancestors) */
  assetId: Scalars["ID"]["output"];
  /** The subtype of the ancestor asset (e.g., 'wfProject', 'ccProject') */
  assetSubType?: Maybe<Scalars["String"]["output"]>;
  /** The type of the ancestor asset (e.g., 'project') */
  assetType?: Maybe<Scalars["String"]["output"]>;
};

/** Filter type and what filter values apply to the asset */
export type ApplicableFilter = {
  /** Name of filter */
  name: Scalars["String"]["output"];
  /** Applicable values for this filter type */
  values: Array<Maybe<Scalars["String"]["output"]>>;
};

