export interface IProjectCreate {
    name: string;
    gradientID: string;
    workspaceID?: string;
}
export interface MoveCSCProjectOptions {
    /**
     * If true, name conflicts will be resolved by ACP.
     */
    renameOnConflict?: boolean;
}

/**
 * Provides all Project related functionality like getting
 * lists of projects among other features.
 *
 * @experimental This API is in an experimental phase so expect that
 * API"s will not be final and there will be breaking changes
 * without bumping the major version until this comment is removed.
 */
export default class ProjectContext implements ISAMObject, SAM.ProjectContext {
    private _projectInterface = new ProjectsInterface(this._core);
    private _gradientPool = new ItemPool<Gradient>(this._core, 'gradient');
    private _defaultGradient?: Gradient;
    private _canRestoreProjectCache: Map<string, boolean> = new Map();

    constructor(
        readonly _core: ISAMCorePrivate,
        /**
         * @package -- For use in SAM.js only
         */
        readonly _assetPool: ItemPool<Project | AdobeAsset>
    ) {
        // If the language configuration changes lets
        // just start refetching the gradients automatically.
        this._core.on(CONFIG_CHANGE,
            (
                event: IEvent,
                sender: any,
                payload: ConfigurationPayload
            ) => {
                if (payload.configurationKeyName === 'LOCALE') {
                    this._getGradients();
                }
            }
        );
    }

    /**
     * @package -- only for use in SAM.js
     * Updaters shouldn't be accessed directly.
     */
    readonly _projectUpdater =  ProjectUpdater;

    /**
     * @package -- only for use in SAM.js
     * @deprecated Will be removed on or after 10-01-2024.
     */
    get assetPool(): ItemPool<Project | AdobeAsset> {
        oneTimeWarning('ProjectContext._assetPool', 'This property is deprecated and will be removed on or after'
            + ' 10-01-2024. For internal use by SAM.js only.');
        return this._assetPool;
    }

    /**
     * @experimental API May change.
     *
     * @example
     * const projectContext = samCore.projectContext;
     * const projectsSource = projectsContext.projects;
     * const yourProjects = projectsSource.getList();
     *
     * @TODO SAM-2834
     */
    @memoize
    projects(): ProjectSource {
        // Trigger lazy-loading of the organizations if they haven't been loaded yet.
        this._core.hostAssetContext.organizations;
        const loader = new PLSProjectsLoader(this._core);
        return new ItemSource(this._assetPool as ItemPool<Project>, [ loader ], new ImplicitProjectFilter());
    }

    /**
     * Creates a new project with the specified name and gradient.
     *
     * @param data.name - The name of the project to create. Must be a valid platform repository name.
     * @param data.gradientID - The gradient ID to associate with the project. This is a computed ID that
     *                          includes the language code. The method resolves this to the original gradient
     *                          ID before sending it to the backend.
     * @param data.workspaceID - Optional workspace/organization ID. When provided, this value is passed
     *                           as the `organization:id` field in the create project request, associating
     *                           the project with a specific workspace. When omitted, the `organization:id`
     *                           field is excluded from the request.
     *
     * @experimental API May change.
     */
    @keepAlive
    async createProject(data: IProjectCreate) {
        const { name, gradientID, workspaceID } = data;
        if (!validatePlatformRepoName(name)) {
            // Validate the name here to avoid resolving the asset if the name is invalid.
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Invalid name provided for the rename operation.');
        }

        // Get the gradient and use the original gradient ID
        // provided by the services when creating a project.
        // The id for gradients is computed to include the language
        // code as well.
        const originalGradient = await this.getGradient(gradientID);
        const response = await this._projectInterface.createProject({
            [RelType.APP_METADATA]: {
                'project:rendition': {
                    'gradientId': originalGradient.gradientID
                }
            },
            'repo:name': name,
            ...(workspaceID && { 'organization:id': workspaceID })
        });
        const session = this._assetPool.createMutationSession<Project>();
        const project = this._projectUpdater.updateRemoteItem(session, { ...response, allowInLists: true } as Partial<IProject | ProjectUpdaterMetadata>);
        session.commit();
        return project;
    }

    /**
     * Resolves a given name to a Project, if one exists.
     * @param name name of the project to be resolved.
     * @returns a promise that resolves to the Project with the given name.
     */
    async resolveProjectByName(name: string): Promise<Project> {
        const projectMetadata: IProject = await this._projectInterface.resolveProjectByName(name);
        const id: string = projectMetadata['repo:assetId'];
        this._core.collaborationContext.confirmAccess(id);
        const session = this._assetPool.createMutationSession<Project>();
        const project = this._projectUpdater.updateRemoteItem(session, projectMetadata);
        session.commit();
        return project;
    }

    /**
     * Validates whether user can create a project with the provided name.
     *
     * This method supports three distinct use cases:
     * 1. **Project rename validation**: Pass the `project` instance. The `repositoryID` will be
     *    automatically extracted from the project to ensure validation is scoped to the correct repository.
     * 2. **Project creation with explicit repository scope**: Pass an explicit `repositoryID` (without a project).
     *    This is primarily used for testing/development to validate names in specific repositories.
     * 3. **Connected Enterprise validation**: Pass a `workspaceID` to validate names within an organization scope.
     *
     * Parameter priority: explicit `repositoryID` > project's `repositoryID` > `workspaceID`
     *
     * @param name Project name to validate.
     * @param project Optional existing project (for rename scenarios). If provided and no explicit
     *                `repositoryID` is given, the repositoryID will be extracted from this project.
     * @param repositoryID Optional explicit repo ID. Takes precedence over project's repositoryID.
     * @param workspaceID Optional workspace ID for Connected Enterprise validation scope.
     *                    Only used if no repositoryID is available.
     * @returns true if name is available, false if name conflicts.
     */
    async validateProjectNameForCreate(name: string, project?: Project, repositoryID?: string, workspaceID?: string): Promise<boolean> {
        // Extract repositoryID from project if not explicitly provided
        // This ensures rename validation is scoped to the correct repository
        const effectiveRepositoryID = repositoryID || (project?.repositoryID);

        // Build composite key matching the actual validation scope
        const cacheKey = effectiveRepositoryID ? `${name}|repoID:${effectiveRepositoryID}` : workspaceID ? `${name}|wsID:${workspaceID}` : name;
        return this._validateProjectNameForCreateCached(cacheKey, name, project, effectiveRepositoryID, workspaceID);
    }

    /**
     * Internal cached implementation for validateProjectNameForCreate.
     * Uses composite cacheKey to ensure different workspaces don't share cached results.
     */
    @consolidated
    private async _validateProjectNameForCreateCached(@key cacheKey: string, name: string, project?: Project, repositoryID?: string, workspaceID?: string): Promise<boolean> {
        if (!validatePlatformRepoName(name)) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Invalid project name.');
        }

        let updatedName = name;
        if (project) {
            updatedName = renameFileInPath(name, project);
        }

        try {
            const options = repositoryID ? { repositoryID } : workspaceID ? { workspaceID } : undefined;
            await this._projectInterface.validateProjectName(updatedName, options);
        } catch (e) {
            const samError = e as SAMError;
            if (samError.code === SAMErrorCode.NOT_FOUND) {
                return true;
            } else if (samError.code === SAMErrorCode.CONFLICT) {
                return false;
            }

            // At this point the error is something else entirely and
            // not related to the the availability of the name. Could
            // be a networking error or something similar.
            throw e;
        }
        return false;
    }

    /**
     * Gets a project with the given ID.
     *
     * @note This method will automatically determine if it should call
     * to confirm access with the invitations service.
     *
     * @param id ID of the project
     * @param confirmAccess Whether to confirm access with the invitations service. NOTE - only
     * to be used by services.
     * @returns a promise that resolves to the Project with the given ID
     */
    @keepAlive
    @synchronized
    async getProjectbyID(@key id: string, confirmAccess: boolean = true): Promise<Project> {
        let project = this._assetPool.getLocalItemById<Project>(id);
        if (project) {
            // Asynchronously confirm access since the user got here
            // from a list or confirmed it before since it's in the cache so
            // the call may not need to happen or may not affect the user.
            if (confirmAccess) {
                this._core.collaborationContext.confirmAccess(id);
            }
            return project;
        }

        if (confirmAccess) {
            await this._core.collaborationContext.confirmAccess(id);
        }
        const projectMetadata = await this._projectInterface.getProject(id);
        const session = this._assetPool.createMutationSession<Project>();
        project = this._projectUpdater.updateRemoteItem(session, projectMetadata);
        // [SHARED-3832] Read-only Org-owned Projects should not show on lists unless the user was invited
        // directly or invited via a group other than "Org Everybody". This is done in SAM.js rather than by Projects
        // Service so that the check can be done async so it does not block getting the Project for 1Up, badging.
        if (!project.hasPermission(Permission.Write) && project.repositoryOwner.type === 'org') {
            // Note: check is done async
            this._checkForInvite(project);
        } else {
            // otherwise, assume Project can be found on lists
            this._projectUpdater.updateLocalItem(session, project, { allowInLists: true });
        }
        session.commit();
        return project;
    }

    /**
     * [SHARED-3832] Checks if the Project is visible to the user due to invitation, whether by group or direct invite.
     * Uses USS rather than Invitation service because it is difficult to check if the user has access due to group
     * invite.
     *
     * @param {Project} project
     * @returns {Promise<void>}
     * @private
     */
    private async _checkForInvite(project: Project): Promise<void> {
        const ussInterface = new USSInterface(this._core);
        const response = await ussInterface.getQueryResponse({
            limit: 1,
            asset_id: project.id,
            [SearchProps.SHARED_VIA_INVITE]: true
        });
        // If there are any items, the user was invited to the Project
        if (response.result_sets[0].items.length) {
            const session = this._assetPool.createUpdateSession<Project>();
            this._projectUpdater.updateLocalItem(session, project, { allowInLists: true });
            session.commit();
        }
    }

    private async _getGradients(): Promise<Gradient[]> {
        const locale = this._core._environment.getValue('LOCALE')!;
        const gradientData = await this._projectInterface.getGradients(locale);
        const defaultGradientId = gradientData.default;
        const session = this._gradientPool.createUpdateSession();
        const computedGradients = computeGradients(gradientData.children, defaultGradientId, locale);
        const gradients: Gradient[] = GradientUpdater.updateRemoteItems(session, computedGradients);
        session.commit();
        return gradients;
    }

    /**
     * Returns the list of available gradients.
     */
    async getGradients(): Promise<Gradient[]> {
        return await this._getGradients();
    }

    /**
     * Gets a single gradient by ID if that gradient does not
     * locally we fetch all the gradients and if it still does not
     * exist then we return the default gradient provided.
     *
     * @param id
     * @returns
     */
    async getGradient(id: string): Promise<Gradient> {
        const gradient = this._gradientPool.getLocalItemById(id);
        const locale = this._core._environment.getValue('LOCALE');
        if (gradient && gradient.languageCode === locale) {
            return gradient;
        }

        await this._getGradients();
        const newGradient = this._gradientPool.getLocalItemById(id);

        if (!newGradient) {
            if (this._defaultGradient && this._defaultGradient.languageCode === locale) {
                return this._defaultGradient;
            }

            this._gradientPool.forEach((gradient: Gradient) => {
                if (gradient.isDefault) {
                    this._defaultGradient = gradient;
                }
            });

            if (this._defaultGradient) {
                return this._defaultGradient;
            }

            // There should always be a default gradient but in the case
            // where maybe it doesn't exist we should still throw an error
            throw SAMError.create(SAMErrorCode.UNKNOWN, `Gradient ID does not exist ${id}`);
        }

        return newGradient;
    }

    async updateProject(id: string, data: IProjectPatchData) {
        let newData = {};
        if (data.gradientID)  {
            const gradient = await this.getGradient(data.gradientID);
            const project = await this.getProjectbyID(id);
            const links = project.projectLinks!;
            newData = { ...newData, ...{ gradientID: gradient.gradientID } };
            await this._projectInterface.patchProject(links, newData);

            const session = this._assetPool.createMutationSession<Project>();
            this._projectUpdater.updateRemoteItem(session, {
                'repo:assetId': project.id,
                _embedded: {
                    [RelType.APP_METADATA]: {
                        'project:rendition': {
                            /**
                             * @note when updating the local model with
                             * "remote" data, we should use the raw gradientID
                             * instead of the computed one.
                             */
                            gradientId: gradient.gradientID
                        }
                    }
                }
            });
            session.commit();
        }
    }

    /**
     * Used to hide and show the create button for users who may or may not
     * have the required privileges to do so.
     * @note Does not throw errors, use canCreateProjectReason to determine the specific
     * reason behind why a user can or cannot create a project.
     *
     * @param repositoryID Optional repositoryID for admins for who have access to multiple repos.
     * @returns {boolean}
     */
    async canCreateProjects(repositoryID?: string): Promise<boolean> {
        try {
            await this._projectInterface.getCapability(ProjectCapabilities.CREATE, repositoryID);
            return true;
        } catch (e) {
            // If it's not a sam error then something else happened
            // and we should throw that error.
            if (!isSAMError(e)) {
                throw e;
            }

            return false;
        }
    }

    /**
     * @package for internal SAM.js use only.
     * @param repositoryID the repository id of the project
     * Restoring capability is same as the capability to create a project.
     */
    async _canRestoreProject(repositoryID: string): Promise<boolean> {
        if (this._canRestoreProjectCache.has(repositoryID)) {
            return this._canRestoreProjectCache.get(repositoryID)!;
        }
        const canRestore = await this.canCreateProjects(repositoryID);
        this._canRestoreProjectCache.set(repositoryID, canRestore);
        return canRestore;
    }

    /**
     * @package for internal SAM.js use only.
     * @param repositoryID the repository id of the project
     */
    _getCachedRestoreCapability(repositoryID: string): boolean {
        return this._canRestoreProjectCache.get(repositoryID) || false;
    }

    /**
     * @package for internal SAM.js use only.
     * @returns a promise that resolves to the index of the project.
     */
    @synchronized
    async _prefetchIndex() {
        await this._projectInterface._discoverProjectLinks();
    }

    /**
     * Used to determine the specific reasoning behind why a user can't
     * create projects. Returns unknown if the error is unrelated to
     * one of the "known" reasons.
     *
     * @param repositoryID
     * @returns
     */
    async canCreateProjectReason(repositoryID?: string): Promise<CanCreateProjectReason> {
        try {
            await this._projectInterface.getCapability(ProjectCapabilities.CREATE, repositoryID);
            return CanCreateProjectReason.ALLOWED;
        } catch (error) {
            if (!isSAMError(error)) {
                return CanCreateProjectReason.UNKNOWN;
            }
            switch (error.subCode) {
            case SAMErrorSubCode.PROJECTS_ADMIN_ONLY:
                return CanCreateProjectReason.ADMIN_DISABLED;
            case SAMErrorSubCode.PROJECTS_NO_HOME_REPOSITORY:
                return CanCreateProjectReason.NO_HOME_REPOSITORY;
            case SAMErrorSubCode.PROJECTS_INVALID_REPOSITORY:
                return CanCreateProjectReason.INVALID_REPOSITORY;
            default:
                return CanCreateProjectReason.UNKNOWN;
            }
        }
    }

    /**
     * Provides a AdobeAssetGlobalSearchFilter that goes directly to USS for search results
     *
     * @note all project related properties will be lazily fetched in this case.
     *
     * @TODO https://jira.corp.adobe.com/browse/SHARED-3489
     * @param {string} query Query string for search.
     * @returns {AdobeAssetGlobalSearchFilter}
     */
    getProjectsSearchSource(query: string): AdobeAssetGlobalSearchSource {
        const implicitFilter = new AdobeAssetGlobalSearchFilter({
            _query: query,
            _projectsOnly: true
        });
        const globalSearchLoader = new GlobalSearchLoader(
            this._core.hostAssetContext._assetPool,
            this._core,
            this._core.hostAssetContext._globalSearchInterfaceV3,
            implicitFilter
        );
        return new ItemSource(this._assetPool, [ globalSearchLoader ], implicitFilter);
    }

    /**
     * It has been reported that sometimes a Project asset is missing the parent project id in the inherited property
     * of the app metadata [SAM-3590]. This method is used to call the Context API [CCXB-20015] which was implemented
     * to address the issue in the following ways:
     * 1. Returns the parent project id so SAM.js can fix the inherited property of the local child asset.
     * 2. Fixes the inheritable property of the parent project if it is missing data.
     * 3. Fixes the inherited property of the child asset if it is missing data.
     * @param assetId
     * @param repoId
     * @package -- only for use in SAM.js
     */
    async _callContextAPI(assetId: string, repoId: string): Promise<IContextAPIResponse> {
        const discoveryLinks = await this._projectInterface._discoverProjectLinks();
        const href = discoveryLinks[RelType.PROJECTS_CONTEXT].href;
        return await this._projectInterface._issueContextAPIRequest(assetId, repoId, href);
    }

    /**
     * @experimental
     */
    getProjectOrder(direction: IOrderDirection = 'ascending', field: ProjectOrderField = 'name'): ProjectOrder {
        return new ProjectOrder(direction, field);
    }

    /**
     * @experimental
     */
    getProjectFilter(options?: SAM.IProjectFilterOptions): ProjectFilter {
        return new ProjectFilter(options);
    }

    /**
     * @experimental
     *
     * @internal This method requires Service Token Authentication
     * the associated IMS client ID must be allowlisted (Only the Workfront client ID
     * will be allowlisted for this API).
     * @param {string} name - The name of the project.
     * @param {CSCProjectDirectorySubtype} - The CSC Project SubType.
     * @param {string} path The path to be created relative to the Workfront top-level. Similar to RAPI create,
     * This does not represent the entire path, but only the directories that should be created
     * under the top-level "/workfront" directory returned by Index Workfront API.
     * This should include the Project name as the final segment of the path. If both
     * this parameter and the "repo:assetId" are provided or the provided "repo:path"
     * contains an existing Project, then an error will be returned (see Response).
     *
     * @param {string} orgId - The Organization ID that the Project will be created within.
     * @param {string} userId - The IMS User ID that the CSC Project creation is on behalf of. The "repo:createdBy"
     * will be set to this value when creating the CSC Project directory. The user will
     * also be given Editor permission to the CSC Project.
     *
     * @param {Record<string, any>} [appMetadata] - The app metadata to be set on the CSC Project.
     * @param {boolean} [renameOnConflict] - If true, the project will be created with a unique name if a project with the same name already exists.
     */
    async createCSCProjectByPath(
        name: string,
        subType: ProjectDirectorySubtype,
        path: string,
        orgId: string,
        userId?: string,
        appMetadata?: Record<string, any>,
        renameOnConflict?: boolean
    ): Promise<Project> {
        return this._createCSCProject({
            name,
            subType,
            path,
            orgId,
            userId,
            appMetadata,
            renameOnConflict: renameOnConflict ?? false
        });
    }

    /**
     * @experimental
     *
     * @internal This method requires Service Token Authentication
     * the associated IMS client ID must be allowlisted (Only the Workfront client ID
     * will be allowlisted for this API).
     *
     * @throws {SAMError.BAD_REQUEST} if the parent is not a WF_PORTFOLIO or WF_PROGRAM.
     *
     * @param {string} name - The name of the project.
     * @param {CSCProjectDirectorySubtype} - The CSC Project SubType.
     * @param {string} orgId - The Organization ID that the Project will be created within.
     * @param {string} parentAssetId  - The asset ID of the Project that the new Project should be created within.
     * The Project will be validated to ensure that it is of subType "wfPortolio" or "wfProgram".
     * If this parameter is not provided, then the Project will be created starting from the top-level.
     * If both this parameter and the "repo:path" are provided, then an error will be returned (see Response).
     *
     * @param {string|undefined} [userId] - The IMS User ID that the CSC Project creation is on behalf of. The "repo:createdBy"
     * will be set to this value when creating the CSC Project directory. The user will
     * also be given Editor permission to the CSC Project.
     *
     * @param {Record<string, any>} [appMetadata] - The app metadata to be set on the CSC Project.
     * @param {boolean} [renameOnConflict] - If true, the project will be created with a unique name if a project with the same name already exists.
     */
    async createCSCProjectInParent(
        name: string,
        subType: ProjectDirectorySubtype,
        parentAssetId: string,
        orgId: string,
        userId?: string,
        appMetadata?: Record<string, any>,
        renameOnConflict?: boolean
    ): Promise<Project> {
        return this._createCSCProject({
            name,
            subType,
            parentAssetId,
            orgId,
            userId,
            appMetadata,
            renameOnConflict: renameOnConflict ?? false
        });
    }

    /**
     * A move method designed only for CSC Projects to encapsulate some of the business logic
     * required to move a CSC Project to a new location.
     *
     * @service -- This method requires an allow listed Service Principal
     * @param sourceProjectId - The ID of the source CSC Project to be moved.
     * @param targetProjectId - The ID of the target CSC Project where the source project will be moved to.
     * @param options - Optional parameters for the move operation.
     * @param options.renameOnConflict - If true, the project will be renamed by ACP if a conflict occurs.
     * @returns A promise that resolves when the move operation is complete.
     */
    async moveCSCProject(
        sourceProjectId: string,
        targetProjectId: string,
        options?: MoveCSCProjectOptions): Promise<void> {
        const project = await this.getProjectbyID(sourceProjectId, false);

        if (project.directorySubtype === ProjectDirectorySubtype.CC_PROJECTS) {
            throw SAMError.create(SAMErrorCode.INVALID_OPERATION, 'Move is only supported for CSC Projects');
        }

        const sourceProjectLinks = project.projectLinks!;

        // Pass the target project ID and the source project links.
        await this._projectInterface.moveCSCProject(targetProjectId, sourceProjectLinks, options?.renameOnConflict);
        const assetContext = await this._core.getAssetContext();
        // Projects service does not return the new project metadata, so we need to fetch it again eventually.
        const newTargetMetadata = await this._projectInterface.getProject(sourceProjectId);
        const session = this._assetPool.createMutationSession<Project>();

        // Update any cached descendants of the source project.
        updateCachedDescendents({
            assetPool: this._assetPool,
            asset: project,
            session,
            operation: { type: 'move', newPath: newTargetMetadata['repo:path'] },
            assetContext
        });

        this._projectUpdater.updateRemoteItem(session, newTargetMetadata);
        session.commit();
    }

    /**
     *
     * The private implementation for the above public CSC Create* methods.
     *
     * @note Only accepts either a path or a parentAssetId, both will result in an error
     * from the services.
     */
    private async _createCSCProject(opts: {
        name: string;
        subType: ProjectDirectorySubtype;
        parentAssetId?: string;
        path?: string;
        orgId: string;
        renameOnConflict: boolean;
        userId?: string;
        appMetadata?: Record<string, any>;
    }) {
        const { name, subType, parentAssetId, path, orgId, userId, appMetadata, renameOnConflict } = opts;

        if (!validatePlatformRepoName(name)) {
            // Validate the name here to avoid resolving the asset if the name is invalid.
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Invalid name provided');
        }
        const baseCSCCreateOptions = {
            name,
            projectDirectorySubType: subType,
            ...(appMetadata ? {
                appMetadata: { ...appMetadata }
            } : {})
        };

        let createData;
        if (parentAssetId) {
            createData = {
                ...baseCSCCreateOptions,
                parentAssetId
            };
        } else {
            createData = {
                ...baseCSCCreateOptions,
                path: path!
            };
        }

        const cscProjectMetadata = await this._projectInterface.createCSCProject(
            createData,
            orgId,
            userId,
            renameOnConflict
        );

        const session = this._assetPool.createMutationSession<Project>();
        const cscProject = this._projectUpdater.updateRemoteItem(
            session,
            {
                ...cscProjectMetadata,
                allowInLists: true
            } as Partial<IProject | ProjectUpdaterMetadata>
        );
        session.commit();

        // Ensure links and repository metadata is presents since Projects API doesn't provide any links or metadata
        // we can't call _Load() because it calls into permissions, PUPA which the service token may not have
        // access to for the time being.
        const resource = new RepoMetadataResource(this._core, cscProject);
        await resource.load();
        await cscProject._handleResourceUpdates({
            repoMetadata: resource.data,
        });

        return cscProject;
    }
}
