import type Library from '../libraries/Library';
import { isLibrary } from '../libraries/Library';
import type CustomModel from './CustomModel';
import { isCustomModel } from './CustomModel';
import type { IImplicitFilter, IItemFilter } from '../core/ItemFilter';
import CustomModelFilter from './CustomModelFilter';
import TrainingSetFilter from './TrainingSetFilter';
import type AdobeAsset from '../assets/AdobeAsset';
import type LibraryFilter from '../libraries/LibraryFilter';

export interface ICustomModelDashboardFilterOptions {
    customModelFilter?: IItemFilter<CustomModel>
    trainingSetFilter?: IItemFilter<Library>
}

export default class ImplicitCustomModelDashboardFilter implements IImplicitFilter<CustomModel | Library> {
    private _customModelFilter?: IImplicitFilter<CustomModel>;
    private _trainingSetFilter?: IImplicitFilter<Library>;

    constructor(options: ICustomModelDashboardFilterOptions = {}) {
        this._customModelFilter = options.customModelFilter || new CustomModelFilter();
        this._trainingSetFilter = options.trainingSetFilter || new TrainingSetFilter();
    }

    get _owner() {
        return this._trainingSetFilter ? (this._trainingSetFilter as LibraryFilter)._owner : undefined;
    }

    get _roles() {
        return this._trainingSetFilter ? (this._trainingSetFilter as LibraryFilter)._roles : undefined;
    }

    matches(item: AdobeAsset): boolean {
        if (isCustomModel(item)) {
            return !!this._customModelFilter && this._customModelFilter.matches(item);
        }

        if (isLibrary(item)) {
            return !!this._trainingSetFilter && this._trainingSetFilter.matches(item);
        }

        return false;
    }
}
