import { isAssetAWebsiteTemplate } from '../utils/classroomUtils';
import type { IExplicitFilter, ItemFilterRelation } from '../core/ItemFilter';
import { FOLDER_TYPE } from '../interface/AssetInterface';
import type StudentAssignmentFile from './StudentAssignmentFile';

/**
 * @deprecated further filtering of files is not supported at this time
 */
export interface StudentAssignmentFileFilterOptions {
    /**
     * @deprecated This should only be used when filtering StudentAssignments, not StudentAssignmentFiles.
     * Regardless of whether this is true or false, files will be fetched for given StudentAssignment
     * This property will be removed on or after 2025-7-1 in ACPCEDU-3393
     */
    loadDocuments?: boolean;
}

export default class StudentAssignmentFileFilter implements IExplicitFilter<StudentAssignmentFile> {
    /**
     * @deprecated loadDocuments is not applicable at the StudentAssignmentFile-level. It only applies to StudentAssignments.
     * This property will be removed on or after 2025-7-1 in ACPCEDU-3393
     */
    public loadDocuments: boolean;

    /**
     *
     * @param studentAssignmentId The ID of the StudentAssignment that the files returned are associated with
     * @param options Deprecated, further filtering of files is not supported at this time. This argument will be removed on or after 2025-7-1 in ACPCEDU-3393
     */
    constructor(
        public studentAssignmentId: string,
        options?: StudentAssignmentFileFilterOptions
    ) {
        this.loadDocuments = options?.loadDocuments ?? true;
    }

    matches(item: StudentAssignmentFile): boolean {
        /**
         * Assets that are StudentAssignmentFiles may start out cached
         * as an AdobeAsset when the asset initially exists outside EDU assets.
         * Therefore this checks for SAFs using attributes that are also available through
         * the AdobeAsset interface.
         *
         * [ACPCEDU-3290] will introduce a longer-term approach for handling this behavior
         * to support other/future cases where the asset type changes over time
         * */

        return item.isChildOfStudentAssignment === true
            && item.studentAssignmentId === this.studentAssignmentId
            && !item.isFolder
            && item.mediaType !== FOLDER_TYPE // [ACPCEDU-3156]: Can be removed once hume is returning repo:assetClass
            && !isAssetAWebsiteTemplate(item);
    }

    getRelationToFilter(other: StudentAssignmentFileFilter): ItemFilterRelation {
        if (this.loadDocuments !== other.loadDocuments) {
            return 'disjoint';
        }

        return this.studentAssignmentId === other.studentAssignmentId
            ? 'subset' : 'disjoint';
    }

    get hash(): string {
        return `studentAssignmentId=${this.studentAssignmentId}&loadDocuments=${this.loadDocuments}`;
    }
}
