import type { INotificationEventSource } from './';

import Logger from '../../../utils/Logger';
import LibraryError from '../../../errors/LibraryError';
import EventEmitter from 'events';
import type { ErrorEvent, MessageEvent } from 'isomorphic-ws';
import WebSocket from 'isomorphic-ws';

export default class NodeWebsocketNotificationEventSource extends EventEmitter implements INotificationEventSource {
    private _ws: WebSocket;

    constructor(url: string) {
        super();
        // Make sure the url has right protocol for websocket connection.
        const wsUrl = url.replace(/http(s?):\/\//, 'ws$1://');
        this._ws = new WebSocket(wsUrl);

        this._ws.addEventListener('message', (event: MessageEvent) => {
            try {
                const { type, message } = JSON.parse(event.data as string) as {
                    type: string;
                    message: Record<string, any>;
                };
                Logger.log(`[NOTIFICATIONS] Received event: ${type}`);
                this.emit(type, message);
            } catch {
                this.emit('error', new LibraryError('INVALID_JSON', 'Received invalid JSON'));
            }
        });

        this._ws.addEventListener('error', (error: ErrorEvent) => {
            this.close();
            this.emit('error', error);
        });
    }

    get isOpen() {
        return this._ws.readyState === this._ws.OPEN;
    }

    close() {
        if (this.isOpen) {
            this.removeAllListeners();
            this._ws.close();
        }
    }
}
