export default class LibraryAbortController {
    private static libAbortControllerMap = new Map();

    public static getInstance(libraryId: string): AbortController {
        let instance = this.libAbortControllerMap.get(libraryId);
        if (!instance) {
            instance = new AbortController();
            this.libAbortControllerMap.set(libraryId, instance);
        }
        return instance;
    }

    public static removeInstance(libraryId: string) {
        return this.libAbortControllerMap.delete(libraryId);
    }
}
