import type EventEmitter from 'events';
import SSENotificationEventSource from './SSENotificationEventSource';
import WebsocketNotificationEventSource from './WebsocketNotificationEventSource';
import NodeWebsocketNotificationEventSource from './NodeWebsocketNotificationEventSource';

export interface INotificationEventSource extends EventEmitter {
    close(): void;
}

export default typeof window === 'undefined'
    ? NodeWebsocketNotificationEventSource
    : window?.navigator?.userAgent?.startsWith?.('Adobe UXP Runtime')
        ? WebsocketNotificationEventSource
        : SSENotificationEventSource;
