import { AvatarSizes } from '../collaboration/AvatarSizes';
import { type RemotePostOwner } from '../interface/BoardModel';
import type { SAM } from '@ccx-public/component-types';

class PostOwner implements SAM.PostOwner {
    private _userId: string;
    private _displayName: string | undefined = undefined;
    private _email: string | undefined = undefined;
    private _firstName: string | undefined = undefined;
    private _lastName: string | undefined = undefined;
    private _images: Record<string, string> | undefined = undefined;

    constructor(readonly data: RemotePostOwner) {
        this._userId = data.userId;
        this._displayName = data.displayName;
        this._email = data.email;
        this._firstName = data.firstName;
        this._lastName = data.lastName;
        this._images = data.images;
    }

    get userId(): string { return this._userId; }
    get displayName(): string | undefined { return this._displayName; }
    get email(): string | undefined { return this._email; }
    get firstName(): string | undefined { return this._firstName; }
    get lastName(): string | undefined { return this._lastName; }
    get avatarImageURLs(): Record<string, string> | undefined { return this._images; }
    get avatarUrl(): string | undefined {
        return this.avatarImageURLs?.[AvatarSizes.Size138];
    }
}

export { PostOwner };

