import ItemUpdater from '../core/ItemUpdater';
import PropertyUpdater from '../core/PropertyUpdater';

import type { IFrameioAssetResponse } from './FrameioInterface';
import FrameioAsset from './FrameioAsset';
import type { FrameioCommentParam } from './FrameioComment';
import type FrameioComment from './FrameioComment';
import { FrameioCommentUpdater } from './FrameioComment';

// See https://developer.frame.io/api/reference/operation/getAsset/
//  for schema of IFrameioAssetResponse. FrameioFile
//  encapsulates the data for assets of type="file".
//
// See FrameioFolder, FrameioVersionStack for other asset types.
export default class FrameioFile extends FrameioAsset {
    private _comments: Array<FrameioComment> | undefined;

    async createComment(param: FrameioCommentParam): Promise<FrameioComment> {
        const ctx = this.context;

        const response = await ctx._frameioInterface.createComment(this.id, param.text);
        const session = ctx._objectPool.createUpdateSession<FrameioComment>();
        const comment = FrameioCommentUpdater.updateRemoteItem(session, response);
        session.commit();

        this._comments = undefined; // force it to refresh the next time it's called.

        return comment;
    }

    // https://developer.frame.io/docs/workflows-projects/gather-all-comments-from-a-project
    //  implies that only a file can have comments, folders and version stacks should
    //  enumerate their children for files with comments
    async getComments(): Promise<Array<FrameioComment>> {
        let comments = this._comments;
        if (!comments) {
            const ctx = this.context;

            const response = await ctx._frameioInterface.getComments(this.id);
            const session = ctx._objectPool.createUpdateSession<FrameioComment>();
            comments = FrameioCommentUpdater.updateRemoteItems(session, response);
            session.commit();

            this._comments = comments;
        }

        return comments;
    }
}

export const FrameioFileUpdater = new ItemUpdater<FrameioFile, Partial<IFrameioAssetResponse>>({
    localItemType: FrameioFile,
    remoteIdProperty: 'id',
    propertyUpdater: new PropertyUpdater({
        '_commentCount': 'comment_count',
        '_insertedAt': { name: 'inserted_at', format: 'date' },
        '_name': 'name',
        '_parentId': 'parent_id',
        '_projectId': 'project_id',
        '_teamId': 'team_id',
        '_updatedAt': { name: 'updated_at', format: 'date' }
    })
});

