import path from 'path-browserify';
import type { IImplicitFilter } from '../core/ItemFilter';
import type { default as AdobeAsset } from './AdobeAsset';
import ImplicitAdobeAssetFilterBase from './ImplicitAdobeAssetFilterBase';

export interface IAdobeAssetSearchFilterOptions {
    readonly deepSearch?: boolean;
    readonly query?: string;
    readonly asset?: AdobeAsset;
}

export default class AdobeAssetSearchFilter extends ImplicitAdobeAssetFilterBase implements IImplicitFilter<AdobeAsset> {
    private _deepSearch?: boolean | undefined;
    private _asset?: AdobeAsset;
    _query?: string;

    constructor(options?: Partial<IAdobeAssetSearchFilterOptions>) {
        super();
        this._query = options?.query;
        this._deepSearch = options?.deepSearch;
        this._asset = options?.asset;
    }

    get deepSearch(): boolean | undefined {
        return this._deepSearch;
    }

    get asset(): AdobeAsset | undefined {
        return this._asset;
    }

    get query(): string | undefined {
        return this._query;
    }

    // The matching rules USS are deceptively complex, and could change over time. Attempting to
    // replicate here could result in items being incorrectly filtered out or incorrectly included.
    // Search Lists should not try to share items from Lists with similar queries, other
    // than treating the queries as case-insensitve.
    // TODO: Lists filtered with AdobeAssetSearchFilter currently take on unwanted items:
    // https://jira.corp.adobe.com/browse/SAM-3118
    matches(item: AdobeAsset): boolean {

        // USS does not give repository id of an item. So compare repository id
        // only when it is available on both assets
        if (this.asset && this.asset.repositoryID && item.repositoryID
            && this.asset.repositoryID !== item.repositoryID) {
            return false;
        }

        // If asset is set, check whether item should belong this search or not based on
        // deep search. If deep search is true this asset should be container for incoming
        // item else this asset should be immediate parent of incoming asset
        if (this.asset && this.asset.repoPath && item.repoPath) {
            const assetRepoPath = this.asset.repoPath;
            if (this.deepSearch) {
                if (!item.repoPath.startsWith(path.join(assetRepoPath, '/'))) {
                    return false;
                }
            } else if (assetRepoPath !== item.repoPath.substring(0, item.repoPath.lastIndexOf('/'))) {
                return false;
            }
        }

        return super.matches(item);
    }
}
