import type { IOrderDirection } from '../core/ItemOrder';
import type { USSAdobeAssetOrderField } from '../assets/USSAdobeAssetOrder';
import { OrderFieldToUSSv3OrderField } from '../assets/USSAdobeAssetOrder';
import InterfaceBase from './InterfaceBase';
import {
    excludeExpressArtifacts,
    type ISearchQueryEntryFilter,
    type USSResponse,
    USSv3DirectoryType,
    USSv3FilterField,
    USSv3Function,
    type USSv3InheritanceTypeField,
    USSv3OrderDir
} from './USSv3Model';
import type USSv3Interface from './USSv3Interface';
import { DEFAULT_MAX_LIMIT } from './USSv3Interface';
import type { ISAMCorePrivate } from '../indexPrivate';

export interface IGlobalSearchOpts {
    query: string;
    start: number;
    limit: number;
    order?: {
        direction: IOrderDirection;
        field: USSAdobeAssetOrderField;
    },
    mediaTypes?: string[];
    excludeMediaTypes?: string[];
    excludeInheritanceTypes?: USSv3InheritanceTypeField[];
    projectsOnly?: boolean;
    assetTypes?: string[];
    excludeAssetTypes?: string[];
    assetSubTypes?: string[];
}

export default class GlobalSearchInterface extends InterfaceBase {

    constructor(
        _core: ISAMCorePrivate,
        private _ussInterface: USSv3Interface
    ) {
        super(_core);
    }

    async globalSearch({
        query,
        start = 0,
        limit = DEFAULT_MAX_LIMIT,
        order,
        mediaTypes,
        excludeInheritanceTypes,
        projectsOnly,
        assetTypes,
        excludeAssetTypes,
        assetSubTypes
    }: IGlobalSearchOpts): Promise<USSResponse> {
        const { field = 'modified', direction = 'descending' } = order || {};

        const filters: ISearchQueryEntryFilter[] = [];
        if (projectsOnly) {
            // As per the recent discussions this is how the project:directoryType is defined as of now
            // The old spaces were identified with project:directoryType = project
            // The old workspaces were identified with project:directoryType = team
            // The new projects are now identified with project:directoryType = team
            filters.push({ [USSv3FilterField.DIRECTORY_TYPE]: [ USSv3DirectoryType.PROJECT ] });
        } else {
            if (mediaTypes?.length) {
                filters.push({
                    [USSv3FilterField.MEDIA_TYPE]: mediaTypes,
                });
            }

            if (excludeInheritanceTypes?.length) {
                filters.push({
                    [USSv3Function.MISSING]: {
                        funcParams: { fields: excludeInheritanceTypes! }
                    }
                });
            }
            if (excludeAssetTypes?.length) {
                filters.push({ [USSv3Function.NOT]: {
                    funcParams: { [USSv3FilterField.ASSET_TYPE]: excludeAssetTypes }
                } });
            } else if (assetTypes?.length) {
                filters.push({ [USSv3FilterField.ASSET_TYPE]: assetTypes });
            }
            if (assetSubTypes?.length) {
                filters.push({ [USSv3FilterField.ASSET_SUB_TYPE]: assetSubTypes });
            }

            // SAMJS-773
            filters.push(excludeExpressArtifacts());

        }

        return this._ussInterface.getQueryResponse({
            start,
            limit,
            textQuery: query,
            sorts: [ {
                sortOrderBy: OrderFieldToUSSv3OrderField[field],
                sortOrder: (direction === 'ascending' && field !== 'relevance') ? USSv3OrderDir.Ascending : USSv3OrderDir.Descending
            } ],
            filters
        });
    }
}
