import type { SAM } from '@ccx-public/component-types';
import type { ISWYAdobeAssetOrderBy } from '../interface/AssetModel';

import type { IComparatorMap } from '../core/ItemOrder';
import { compareStrings, compareValues, createItemOrderFactory } from '../core/ItemOrder';
import type AdobeAsset from './AdobeAsset';

export type SWYAdobeAssetOrderField =
     | 'name'
     | 'created'
     | 'modified'
     | 'shared'

export const OrderFieldToISWYAdobeAssetOrderBy: { [key in SWYAdobeAssetOrderField]: ISWYAdobeAssetOrderBy } = {
    'name': 'asset_name',
    'created': 'create_date',
    'modified': 'modify_date',
    'shared': 'shared_date',
};

const OrderFieldToComparator: IComparatorMap<AdobeAsset, SWYAdobeAssetOrderField> = {
    name(a: AdobeAsset, b: AdobeAsset): number {
        return compareStrings(a.name, b.name);
    },
    shared(a: AdobeAsset, b: AdobeAsset): number {
        return compareValues(a.shared, b.shared);
    },
    created(a: AdobeAsset, b: AdobeAsset): number {
        return compareValues(a.created, b.created);
    },
    modified(a: AdobeAsset, b: AdobeAsset): number {
        return compareValues(a.modified, b.modified);
    }
};

export default class SWYAdobeAssetOrder extends createItemOrderFactory(OrderFieldToComparator) implements SAM.SWYAdobeAssetOrder {
    static default = new SWYAdobeAssetOrder('descending', 'shared');
}
