import { compareStrings, compareValues, createItemOrderFactory } from '../../core/ItemOrder';
import type { IComparatorMap } from '../../core/ItemOrder';

import type Element from '../../library-contents/models/Element';

export enum ElementOrderBy {
    MODIFY_DATE = 'modifyDate',
    CREATE_DATE = 'createDate',
    NAME = 'name'
}

export type ElementOrderField =
    | 'name'
    // | 'created'
    | 'modified';

const OrderFieldToComparator: IComparatorMap<Element, ElementOrderField> = {
    name(a: Element, b: Element): number {
        return compareStrings(a.name, b.name);
    },
    //
    // created(a: Element, b: Element): number {
    //     return compareValues(a.created, b.created);
    // },

    modified(a: Element, b: Element): number {
        return compareValues(a.modified, b.modified);
    }
};

export default class ElementOrder extends createItemOrderFactory(OrderFieldToComparator) {
    static default = new ElementOrder('descending', 'modified');
}
