import { default as ChangeEvent } from '../core/ChangeEvent';
import type { ONSAssetLabel, ONSResourceType } from './ONSResource';

export const ONS_FIRST_LONG_POLL_STARTED = 'firstLongPollStarted';
export const ONS_FIRST_LONG_POLL_COMPLETED = 'firstLongPollCompleted';
export const ONS_MONITORING_STATUS_CHANGED = 'onsMonitoringStatusChanged';
/**
 * Status of the ONS Monitoring performed by the ONS Context.
 * @see ONSContext
 *
 */
export enum OnsMonitoringStatus {
    Unknown,
    Inactive,
    Restarting,
    Active,
    Error
}

// Additional information that comes with an ONS event
export interface ONSChangedAssetInfo {
    parentAssetId?: string;
    plsAssetListId?: string;
    changedLabels?: ONSAssetLabel[];
    changedResources?: ONSResourceType[];
    annotationIds?: string[];
}

export class ONSAssetChangeEvent extends ChangeEvent {
    constructor(
        readonly changedAssets: Map<string, ONSChangedAssetInfo>
    ) {
        super();
    }
}

export class ONSFirstLongPollStartedEvent extends Event {
    constructor(readonly cachedSubscriptionsUsed: boolean) {
        super(ONS_FIRST_LONG_POLL_STARTED);
    }
}

export class ONSFirstLongPollCompletedEvent extends Event {
    constructor(readonly expired: boolean) {
        super(ONS_FIRST_LONG_POLL_COMPLETED);
    }
}

export class ONSMonitoringStatusChangedEvent extends Event {
    constructor(readonly status: OnsMonitoringStatus) {
        super(ONS_MONITORING_STATUS_CHANGED);
    }
}
