import type { IUSSAdobeAssetOrderBy } from '../interface/AssetModel';
import type { IComparatorMap } from '../core/ItemOrder';
import { compareStrings, compareValues, createItemOrderFactory } from '../core/ItemOrder';
import type AdobeAsset from './AdobeAsset';
import { LastAccessedOrderField } from '../interface/USSModel';
import { USSv3OrderField } from '../interface/USSv3Model';
import type { ValueOf } from '../core/ObjectUtils';

export type USSAdobeAssetOrderField =
    | 'name'
    | 'created'
    | 'modified'
    | 'lastAccessed'
    | 'relevance';

export const OrderFieldToIUSSAdobeAssetOrderBy: { [key in USSAdobeAssetOrderField]: IUSSAdobeAssetOrderBy } = {
    'name': 'asset_name',
    'created': 'create_date',
    'modified': 'modify_date',
    'lastAccessed': LastAccessedOrderField,
    // Note: since USSv2 in SAM.js is deprecated and will be removed, relevance sorting is not implemented
    'relevance': 'modify_date'
};

export const OrderFieldToUSSv3OrderField: { [key in USSAdobeAssetOrderField]: ValueOf<typeof USSv3OrderField> } = {
    'name': USSv3OrderField.Name,
    'created': USSv3OrderField.Created,
    'modified': USSv3OrderField.Modified,
    'relevance': USSv3OrderField.Relevance,
    // TODO: update with correct field once V3 supports it
    'lastAccessed': USSv3OrderField.Modified,
};

const OrderFieldToComparator: IComparatorMap<AdobeAsset, USSAdobeAssetOrderField> = {
    name(a: AdobeAsset, b: AdobeAsset): number {
        return compareStrings(a.name, b.name);
    },
    created(a: AdobeAsset, b: AdobeAsset): number {
        return compareValues(a.created, b.created);
    },
    modified(a: AdobeAsset, b: AdobeAsset): number {
        return compareValues(a.modified, b.modified);
    },
    lastAccessed(a: AdobeAsset, b: AdobeAsset): number {
        return compareValues(a.lastAccessed, b.lastAccessed);
    },
    relevance(): number {
        // maintain server-side sort
        return 0;
    }
};

export default class USSAdobeAssetOrder extends createItemOrderFactory(OrderFieldToComparator) {
    static default = new USSAdobeAssetOrder('descending', 'modified');
}
