import type {
    Format,
    Assignee,
    AssetLinks,
    ShellVisibility,
    IAppMetadata,
    PermissionType,
    RepoResponseEmbeddedData,
    Representations
} from './RepositoryModel';
import type { AdobeAssetOrderField } from '../assets/AdobeAssetOrder';
import type { USSAdobeAssetOrderField } from '../assets/USSAdobeAssetOrder';
import type { IUSSFetchFieldType, IPerUserMetadata } from './AssetModel';
import type { RelType } from './LinkUtils';

export enum SearchProps {
    STORAGE_ASSIGNEE_TYPE = 'storage:assignee$$type',
    VISIBILITY = 'app_metadata$$shell:visibility',
    CREATIVE_CLOUD_TOPLEVEL_COLLECTION_NAME = 'creative_cloud_toplevel_collection_name',
    FIELD_EXISTS = 'op_field_exists',
    FIELD_MATCHES = 'op_field_matches',
    INCLUDES = 'includes',
    TYPE = 'type',
    STORAGE_ASSIGNEE_ID = 'storage:assignee$$id',
    SHARED_VIA_INVITE = 'shared_via_invite',
    OP_AND = 'op_and',
    OP_OR = 'op_or',
    REPO_ACL_MODIFIER = 'repo:acl$$repo:modifier',
    REPO_ACL_PRIVILEGES = 'repo:acl$$repo:privileges',
    REPO_ACL_RELATIONS = 'repo:acl$$repo:relations',
    CREATED_FROM_UPLOAD = 'app_metadata$$cc:createdFromUpload',
    CREATED_BY_CLIENT_ID = 'repo:createdByClientId'
}

export const USS_ARTIFACT_MEDIATYPE = 'app_metadata$$review:sourceAsset$$dc:format';

export const LastAccessedOrderField = 'api:metadata/peruser#mine$$shell:lastAccessDate';

export type IStorageAssigneeType =
    | 'user'
    | 'org';

export type ISearchSortOrderDirection =
    | 'asc'
    | 'desc';

export type ISearchSortOrderBy =
    | 'asset_name'
    | 'create_date'
    | 'modify_date'
    | 'shared_date'
    | typeof LastAccessedOrderField
    | 'relevance';

export type ISearchVisibility = ShellVisibility;

export const OrderByToUSSOrderBy: { [key in AdobeAssetOrderField | USSAdobeAssetOrderField]: ISearchSortOrderBy } = {
    name: 'asset_name',
    created: 'create_date',
    modified: 'modify_date',
    shared: 'shared_date',
    lastAccessed: LastAccessedOrderField,
    // Note: unsupported
    relevance: 'modify_date'
};

export interface IHintsACPPlatform {
    acp_platform_v2: boolean;
    creative_cloud_rendition_v2?: boolean;
}

export type IHint = IHintsACPPlatform;

type IncludeFields =
    | 'app_metadata'
    | 'collaboration_metadata'
    | '_embedded'
    | 'collab_metadata$$collaborators'
    | typeof LastAccessedOrderField
    | IUSSFetchFieldType;

export interface IFetchFieldsInclude {
    [SearchProps.INCLUDES]: IncludeFields[];
}

export interface IContainer {
    asset_id: string[];
}

// These are a subset of fields USS supports for `op_field_exists`
// Others are available.
type FieldExists =
    | 'app_metadata$$review:sourceAsset$$dc:format'
    | 'app_metadata$$cc:inheritable$$cc:team$$repo:assetId'
    | 'app_metadata$$cc:inherited$$cc:team$$repo:assetId'
    | 'app_metadata$$cc:inheritable$$cc:space$$repo:assetId'
    | 'app_metadata$$cc:inherited$$cc:space$$repo:assetId'
    | 'app_metadata$$cc:createdFromUpload'
    | typeof LastAccessedOrderField;

type FieldMatches = {
    'app_metadata$$project:directoryType'?: 'team';
    [USS_ARTIFACT_MEDIATYPE]?: string;
}

export interface IOpFieldExists {
    [SearchProps.FIELD_EXISTS]: FieldExists[];
}

export interface IOpFieldMatches {
    [SearchProps.FIELD_MATCHES]: FieldMatches;
}

export interface IOpAnd {
    [SearchProps.OP_AND]: IOp;
}

export interface IOpOr {
    [SearchProps.OP_OR]: IOp;
}

export interface IOpVisibility {
    [SearchProps.VISIBILITY]: ISearchVisibility | ISearchVisibility[];
}

// "assets" and "archive" = /assets and /archive folders, respectively
type TopLevelCollectionName = 'archive' | 'appdata' | 'assets' | 'cloud-content' | 'pubs' | 'files';
export interface IOpTopLevelCollection {
    [SearchProps.CREATIVE_CLOUD_TOPLEVEL_COLLECTION_NAME]: TopLevelCollectionName | TopLevelCollectionName[];
}

export interface IOpType {
    [SearchProps.TYPE]: string[];
}

export interface IOpStorageAssigneeId {
    [SearchProps.STORAGE_ASSIGNEE_ID]: string | string[];
}

export interface IOpStorageAssigneeType {
    [SearchProps.STORAGE_ASSIGNEE_TYPE]: IStorageAssigneeType;
}

export interface IOpCreatedFromUpload {
    [SearchProps.CREATED_FROM_UPLOAD]: boolean;
}

export interface IOpCreatedByClientId {
    [SearchProps.CREATED_BY_CLIENT_ID]: string;
}

export interface IOpHasPermission {
    [SearchProps.REPO_ACL_MODIFIER]: 'grant';
    [SearchProps.REPO_ACL_PRIVILEGES]: PermissionType[];
    [SearchProps.REPO_ACL_RELATIONS]: RelType[];
}

export interface IOpSharedViaInvite {
    [SearchProps.SHARED_VIA_INVITE]: boolean;
}

export type IOp = (
    | IOpFieldExists
    | IOpVisibility
    | IOpTopLevelCollection
    | IOpType
    | IOpStorageAssigneeId
    | IOpSharedViaInvite
    | IOpAnd
    | IOpOr
    | IOpStorageAssigneeType
    | IOpHasPermission
    | IOpCreatedFromUpload
    | IOpCreatedByClientId
    | IOpFieldMatches
)[];

/**
 * USS API Docs
 * https://git.corp.adobe.com/pages/adobesearch/search-services-docs/uss/cc/response/
 */
export interface ISearchQuery {
    [SearchProps.STORAGE_ASSIGNEE_TYPE]?: IStorageAssigneeType[];
    [SearchProps.CREATIVE_CLOUD_TOPLEVEL_COLLECTION_NAME]?: TopLevelCollectionName[];
    asset_id_opacity?: boolean;
    creative_cloud_archive?: boolean;
    creative_cloud_discarded_directly?: boolean;
    container?: IContainer;
    fetch_fields?: IFetchFieldsInclude;
    hints?: IHint | IHint[];
    limit?: number;
    op_and?: IOp;
    op_none_of?: IOp;
    op_or?: IOp;
    op_field_exists?: FieldExists[];
    op_field_matches?: FieldMatches;
    scope?: string[];
    shared_by_me?: boolean;
    parent_id?: string[];
    shared_via_invite?: boolean;
    sort_order?: ISearchSortOrderDirection;
    sort_orderby?: ISearchSortOrderBy;
    start_index?: number;
    [SearchProps.TYPE]?: string[];
    q?: string;
    [SearchProps.STORAGE_ASSIGNEE_ID]?: string | string[];
    creative_cloud_asset_type?: 'asset' | 'collection' | 'mount' | 'dcx';
    asset_name?: string,
    asset_id?: string,
    sync_created_date?: { range: { min?: string, max?: string } };
    sync_updated_date?: { range: { min?: string, max?: string } };
}

type USSResponseResultSet = {
    items: Partial<USSMetadata>[]
    total_items: number,
}

type USSResponseStatus = {
    scope: string;
    status: number;
}

export type USSResponse = {
    result_sets: USSResponseResultSet[];
    status: USSResponseStatus[];
}

type IUSSColaborationPermissions = 'canShare' | 'canComment';

interface IUSSCollaborationMetadata {
    collaborator_id: string;
    inviter_id: string;
    shared_date: number;
    role: 'viewer' | 'editor';
    permissions: IUSSColaborationPermissions[];
    type?: 'individual' | 'group';
    modified_date: number;
}

export interface IUSSApplicationMetadata {
    'cc:createdFromUpload'?: boolean;
}

export type USSMetadata = {
    type: Format,
    asset_name: string,
    asset_name_path: string,

    create_date: string,

    modify_date: string,

    // A globally unique identifier for this Asset.
    asset_id: string,

    // the etag equivalent for composites
    composite_manifest_etag: string,
    etag: { primary: string },

    // The Repository ID of the Repository storing this Asset.
    'repo:repositoryId': string

    // As per USS docs, this field is either 'composite' or 'element' when `creative_cloud_asset_type` is 'dcx'
    // https://git.corp.adobe.com/pages/adobesearch/search-services-docs/uss/cc/response/
    asset_sub_type: 'composite' | 'element',

    'collab_metadata#mine': IUSSCollaborationMetadata,

    // USS returns one of the following 4 values for this field
    creative_cloud_asset_type: 'asset' | 'collection' | 'mount' | 'dcx',

    // colortheme & gradient only apply to discarded Library Elements?
    creative_cloud_colortheme?: any;
    creative_cloud_gradient?: any;

    // Size of the Primary Resource in bytes. Not applicable for directories
    size: number,

    // IMS User Id of the user who created this Asset.
    creative_cloud_creator_id: string,

    // WARNING: do not use. This appears to be populated by the XMP metadata version from the MANIFEST,
    // not `repo:version` from repo metadata.
    // 'repo:version': string;

    // This field maps to the repo metadata repo:version field
    'asset_version_id': string;

    'storage:assignee': Assignee,

    region: string,

    collab_metadata: object,

    collaboration_metadata: IUSSCollaborationMetadata[],

    app_metadata: IAppMetadata,

    // assetId of asset's ancestors, root starts from index 0
    path: string[],

    _links: AssetLinks,

    // per user metadata
    'api:metadata/peruser': IPerUserMetadata[],
    'api:metadata/application': IUSSApplicationMetadata,

    // effective permissions
    _embedded: RepoResponseEmbeddedData

    // available asset representations
    'repo:representations': Representations
};
