import type AssignmentInterface from '../interface/AssignmentsInterface';
import type Assignment from './Assignment';
import { AssignmentUpdater } from './Assignment';
import type {
    IItemLoader,
    IItemLoaderOptions,
    ILoadedPage,
} from '../core/ItemLoader';
import type { AssignmentConfig } from './AssignmentSource';
import type { IServiceLink } from '../interface/LinkUtils';
import type { IAssignmentsResponse, IRemoteAssignment } from '../interface/AssignmentModel';
import type { ISAMCorePrivate } from '../indexPrivate';
import type AssignmentFilter from './AssignmentFilter';
import type AdobeAsset from '../assets/AdobeAsset';
import { getMostRecentValidMutation } from '../utils/loaderUtils';

export default class AssignmentsListLoader
implements IItemLoader<AssignmentConfig> {
    constructor(
        private _assignmentInterface: AssignmentInterface,
        private _core: ISAMCorePrivate,
    ) {}

    async loadPage(
        options: IItemLoaderOptions<AssignmentConfig>
    ): Promise<ILoadedPage<AssignmentConfig>> {
        return await this._loadPage(options);
    }

    /**
     * Observe Assignments folder to get enable automatic ONS updates for assignments page.
     * @param assignment - assignment, which contains parent folder ID
     * @returns promise that resolves to students adobe asset instance
     */
    private async observeAssignmentsFolder(assignment: IRemoteAssignment): Promise<AdobeAsset> {
        // Despite classroom:assignmentsContext being an optional field, it is guaranteed to be present for Assignments
        const assignmentsFolderId = assignment!['classroom:context']['classroom:assignmentsContext']!['classroom:assignmentsAssetId'];
        // This ticket [ACPCEDU-2563] will try to optimize this.
        return this._core.hostAssetContext.getAssetWithCloudID(assignmentsFolderId!);
    }

    private async _loadPage(
        options: IItemLoaderOptions<AssignmentConfig>,
        // TODO: https://jira.corp.adobe.com/browse/ACPCEDU-405 add support for paging or remove this
        // eslint-disable-next-line @typescript-eslint/no-unused-vars
        pageLink?: IServiceLink
    ): Promise<ILoadedPage<AssignmentConfig>> {
        const filter = options.filter as AssignmentFilter;
        const { classroomId, campaignId, submissions, profiles } = filter;
        const result: IAssignmentsResponse = await this._assignmentInterface.getAssignments({
            ...options,
            classroomId,
            campaignId,
            submissions: await this._core.classroomContext.validateStudentAssignmentsFilter(submissions, classroomId),
            profiles,
        });
        const mostRecentValidMutation = getMostRecentValidMutation(options.resource);

        // TBD: we probably want a "mutation" session here instead of "update" session
        // Details can be found in https://git.corp.adobe.com/torq/acpl-model/pull/3902#discussion_r7024503
        const session = this._core._getAssetPool().createLoaderUpdateSession<Assignment>(
            mostRecentValidMutation
        );
        const items = AssignmentUpdater.updateRemoteItems(session, result.children);
        session.commit();

        // All assignments will have the same parent folder ID, so we can observe the parent folder using just the first assignment
        // Skip folder observation for cross-profile queries since the current user won't have access to other users' assignment folders
        const currentUserId = this._core._environment.getUserId();
        const isCrossProfileQuery = profiles !== undefined && profiles !== currentUserId;
        if (result.children.length > 0 && !isCrossProfileQuery) {
            this.observeAssignmentsFolder(result.children[0]).then((folder) => {
                // pin this to memory so Garbage Collector does not remove it as long as the list is still kept in memory
                filter._monitoredFolder = folder;
            });
        }

        return {
            items,
            total: result.children.length,
            mostRecentValidMutation,
        };
    }
}
