export function parseProjectEffectivePermissions(permissions: IProjectsEffectivePermissions, projectPermissions?: AssetPermissions): Permission {
    // We get special permissions for projects which are present in the project primary relation
    const projectPrimary = permissions[RelType.PROJECTS_PRIMARY] || permissions['*'] || [];       // permissions on the project
    const primary = permissions[RelType.PRIMARY] || permissions['*'] || [];       // permissions on the folder representing the project
    const directory = permissions[RelType.DIRECTORY] || permissions['*'] || [];   // parent folder's permissions
    const annotations = permissions[RelType.ANNOTATIONS] || permissions['*'] || [];   // contains commenting permissions
    const policy = permissions[RelType.AC_POLICY] || permissions['*'] || [];      // contains "share" permission

    let mask = Permission.None;

    // We get special permissions from projectPermissions instead of [RelType.PROJECTS_PRIMARY] in case of GraphQL
    // When projectPermissions exist, ack/read are granted by default and other boolean fields are processed.
    if (projectPermissions) {
        mask |= Permission.Ack;
        mask |= Permission.Read;

        Object.entries(projectPermissions).forEach(([ permission, canPerform ]) => {
            if (canPerform) {
                switch (permission) {
                case 'canWrite':
                    mask |= Permission.Write;
                    break;
                case 'canRename':
                    mask |= Permission.Rename;
                    break;
                case 'canDiscard':
                    mask |= Permission.Discard;
                    break;
                case 'canRestore':
                    mask |= Permission.Restore;
                    break;
                case 'canDelete':
                    mask |= Permission.Delete;
                    break;
                }
            }
        });
    } else {
        // We get the 'ack', 'read', 'rename', 'discard', 'restore' permissions from the project primary relation in case of project service
        projectPrimary.forEach((perm: PermissionType) => {
            switch (perm) {
            case 'ack':
                mask |= Permission.Ack;
                break;
            case 'read':
                mask |= Permission.Read;
                break;
            case 'rename':
                mask |= Permission.Rename;
                break;
            case 'discard':
                mask |= Permission.Discard;
                break;
            case 'restore':
                mask |= Permission.Restore;
                break;
            }
        });
    }

    // We get the 'write' and 'delete' permissions from the folder representing the project and the parent folder
    primary.forEach((perm: PermissionType) => {
        switch (perm) {
        case 'write':
            mask |= Permission.Write;
            break;
        case 'delete':
            if (directory.includes('write')) {
                mask |= Permission.Delete;
            }
            break;
        }
    });

    if (policy.includes('write')) {
        mask |= Permission.Share;
    }

    if (annotations.includes('write')) {
        mask |= Permission.WriteComment;
    }

    return mask;
}

