import type AdobeAsset from '../assets/AdobeAsset';
import packageJSON from '../../package.json';
import type { HeaderMap } from '../interface/LinkUtils';
import type { USSMetadata } from '../interface/USSModel';
import SAMError, { SAMErrorCode } from '../core/SAMError';
import type Post from '../boards/Post';
import type TextPost from '../boards/TextPost';
import { PostType } from '../interface/BoardModel';

export enum RequestHeaders {
    PREFER_RAPI = 'X-Prefer-RAPI',
    SAM_VERSION = 'X-Shared-Asset-Model-Version'
}

export function getSAMVersionRequestHeader(): HeaderMap {
    return { [RequestHeaders.SAM_VERSION]: packageJSON.version };
}

type ValidationType = 'string' | 'date' | 'string[]' | 'enum' | 'blob' | 'object';

export interface ValidationMap<T> {
    key: keyof T;
    type: ValidationType;
    isRequired: boolean;
    ref?: any;
}

// This is susceptible to breaking if the nesting of EDU assets change
const assignmentPath = '.*/classrooms/[^/]+/assignments/[^/]+$';
const assignmentPathRegex = new RegExp(assignmentPath);

// [ACPCEDU-3811] will replace the need for this function
export function isAssignmentPath({ repoPath }: {repoPath: string}): boolean {
    return assignmentPathRegex.test(repoPath);
}

// This is susceptible to breaking if the nesting of EDU assets change
const materialsFilePath = assignmentPath.replace('$', '/materials/[^/]+$');
const materialsFilePathRegex = new RegExp(materialsFilePath);

// [ACPCEDU-3811] will replace the need for this function
export function isMaterialsFilePath({ repoPath }: {repoPath: string}): boolean {
    return materialsFilePathRegex.test(repoPath);
}

// This is susceptible to breaking if the nesting of EDU assets change
const studentAssignmentPath = assignmentPath.replace('$', '/students/[^/]+$');
const studentAssignmentPathRegex = new RegExp(studentAssignmentPath);

// [ACPCEDU-3811] will replace the need for this function
export function isStudentAssignmentPath({ repoPath }: {repoPath: string}): boolean {
    return studentAssignmentPathRegex.test(repoPath);
}

// [ACPCEDU-3811] will replace the need for this function
export function getClassroomNameFromSAFPath(repoPath: string): string {
    // Assumes [..., Classroom, Assignments, Assignment, Students, StudentAssignment, StudentAssignmentFile]
    // Example path: /content/assets/classrooms/${classroomName}/assignments/assignment-name/students/student-name/file-name
    if (!isStudentAssignmentFilePath({ repoPath })) {
        throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'repoPath provided is not a StudentAssignmentFile path');
    }
    // Verified expected length of repoPath array through the isStudentAssignmentFilePath check
    return repoPath.split('/').at(-6)!;
}

// [ACPCEDU-3811] will replace the need for this function
export function getClassroomNameFromMaterialsFilePath(repoPath: string): string {
    // Assumes [..., Classroom, Assignments, Assignment, Materials, Materials file]
    // Example path: /content/assets/classrooms/${classroomName}/assignments/assignment-name/materials/file-name
    if (!isMaterialsFilePath({ repoPath })) {
        throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'repoPath provided is not a MaterialsFile path');
    }
    // Verified expected length of repoPath array through the isMaterialsFilePath check
    return repoPath.split('/').at(-5)!;
}

// This is susceptible to breaking if the nesting of EDU assets change
const studentAssignmentFilePath = studentAssignmentPath.replace('$', '/[^/]+$');
const studentAssignmentFilePathRegex = new RegExp(studentAssignmentFilePath);

// [ACPCEDU-3811] will replace the need for this function
export function isStudentAssignmentFilePath({ repoPath }: {repoPath: string}): boolean {
    return studentAssignmentFilePathRegex.test(repoPath);
}

// [ACPCEDU-3811] will replace the need for this function
export function ussIsStudentAssignmentFilePath(item: USSMetadata): boolean {
    return studentAssignmentFilePathRegex.test(`${item.asset_name_path}/${item.asset_name}`);
}

export function isAssetAWebsiteTemplate(asset: AdobeAsset): boolean {
    const doesMediaTypeMatch = asset.mediaType === 'application/vnd.adobe.gneisswebpage.theme.document+dcx';
    const doesPathMatch = asset.name.endsWith('.webpagetheme');

    return doesMediaTypeMatch || doesPathMatch;
}

/**
 * Validates a string for type correctness and non-empty.
 * @param value The value to validate.
 * @param name The name of the value, only used when throwing errors.
 * @param shouldThrow True (default) if a specific error should be thrown; false to return a status.
 * @returns True if the value is a string and non-empty; false otherwise.
 */
export function validateString(value: any | any[], name: string, shouldThrow: boolean = true): boolean {
    let result: boolean = true;

    if (Array.isArray(value)) {
        for (let index = 0; index < value.length; index++) {
            result = validateString(value[index], name, shouldThrow);
            if (!result) {
                break;
            }
        }

        return result;
    }

    if (!validateType(value, 'string', true)) {
        result = false;

        if (shouldThrow) {
            throw Error(`${name} is not a valid string`);
        }
    }

    if (value as string === '') {
        result = false;

        if (shouldThrow) {
            throw Error(`${name} is an empty string`);
        }
    }

    return result;
}

/**
 * Validates that a given piece of data is of the correct type
 * @returns true if the data is of the correct type, false otherwise
 */
export function validateType(value: any, type: ValidationType, isRequired: boolean, ref?: any): boolean {
    if (!isRequired && (value === undefined || value === null)) {
        return true;
    }

    switch (type) {
    case 'string':
        return typeof value === 'string';
    case 'date':
        return typeof value === 'object' && (value as Date).toDateString !== undefined;
    case 'string[]':
        return Array.isArray(value) && value.every((item) => validateType(item, 'string', false));
    case 'enum':
        return Object.values(ref).some((enumValue) => enumValue === value);
    case 'blob':
        return value instanceof Blob;
    case 'object':
        return typeof value === 'object' && !Array.isArray(value) && value !== null;
    }

    // Not reachable through TS, but JS could hit this. Including for completeness.
    return false;
}

/**
 * Validates multiple pieces of data against a validation map
 * @returns an array of error messages for each piece of data that failed validation
 */
export function validateTypes<T extends any>(validationMap: ValidationMap<T>[], data: T): string[] {
    return validationMap.reduce((errors: string[], { key, type, ref, isRequired }) => {
        if (!validateType(data[key], type, isRequired, ref)) {
            const article = (type === 'enum' || type === 'object') ? 'an' : 'a';
            let errMsg = `${key.toString()} is not ${article} ${type}`;
            if (isRequired) {
                errMsg += ' or is missing';
            }
            errors.push(errMsg);
        }

        return errors;
    }, [] as string[]);
}

export function getMemberComputedKey(classroomId: string, userId: string) {
    return `${classroomId}-${userId}`;
}

export function isTextPost(post: Post): post is TextPost {
    return post.type === PostType.Text;
}
