import type { RelType } from '../interface/LinkUtils';

export enum AccessControlPrincipalType {
    USER =  'https://ns.adobe.com/adobeaemcloud/aem/user',
    GROUP = 'https://ns.adobe.com/adobeaemcloud/aem/group'
}

export interface IAccessControlListResponse {
    'repo:acl': IAccessControlEntryResponse[];
}

export enum AccessControlPrivileges {
    /**
     * The existence of a resource can be checked.
     */
    ACK = 'ack',
    /**
     * The resource can be retrieved via a GET request.
     */
    READ = 'read',
    /**
     * The resource can be updated via a PUT request; and PATCH request where applicable.
     */
    WRITE = 'write',
    /**
     * The resource can be deleted via a DELETE request.
     */
    DELETE = 'delete'

    /**
     * @note
     * COMPATIBILITY NOTE: FULL and MODIFY are deprecated aliases to combinations of privileges.
     * New clients SHOULD NOT use these. They MAY continue to be used by existing clients to update policies,
     * but will always be expanded to the individual non-aliased privileges when the policy is returned to clients.
     * MODIFY privilege is translated to READ and WRITE.
     * FULL privilege is translated to ACK, READ, WRITE, DELETE.
     */
}

export enum AccessControlModifier {
    GRANT = 'grant',
    DENY = 'deny'
}

export enum AccessControlInheritance {
    SELF = 'self',
    DEEP = 'deep',
    DEEP_OVERRIDE = 'deep_override'
}

export interface IAccessControlResponse {
    'etag': string;
    'repo:acl': IAccessControlEntryResponse[];
}

export interface IAccessControlEntryResponse {
    'repo:principal': IAccessControlPrincipal | string;
    'repo:privileges': AccessControlPrivileges[];
    'repo:modifier': AccessControlModifier;
    'repo:inheritance': AccessControlInheritance;
    'repo:relations': RelType[];
}

export enum RelTypePlatform {
    PRINCIPAL_TYPE_IMS_USER = 'https://ns.adobe.com/adobecloudplatform/ims/user',
    PRINCIPAL_TYPE_IMS_GROUP = 'https://ns.adobe.com/adobecloudplatform/ims/group'
}

export interface IAccessControlPrincipal {
    '@id': string;
    '@type': RelTypePlatform;
    'xdm:provider': IAccessControlProvider;
}

export interface IAccessControlProvider {
    '@id': 'https://ims-na1.adobelogin.com/' | string;
}

export const AccessControlProvider = {
    '@id': 'https://ims-na1.adobelogin.com/'
};

export interface AdobeACEMetadata {
    principal: IAccessControlPrincipal | string;
    privileges: AccessControlPrivileges[];
    modifier: AccessControlModifier;
    inheritance: AccessControlInheritance;
    relations?: RelType[];
}

export type Principal = IAccessControlPrincipal;
