import type { INotificationEventSource } from './';
import Logger from '../../../utils/Logger';
import LibraryError from '../../../errors/LibraryError';
import EventEmitter from 'events';

const MAX_SILENT_RETRIES = 3;

export default class SSENotificationEventSource extends EventEmitter implements INotificationEventSource {
    private _eventSource: EventSource;
    private _listenedEvents: Set<string> = new Set();
    private _errorCount = 0;

    constructor(url: string) {
        super();
        this._eventSource = new EventSource(url);
        this._eventSource.onopen = () => {
            this._errorCount = 0;
        };
        this._eventSource.onerror = (error: Event) => {
            this._errorCount += 1;

            if (this._errorCount >= MAX_SILENT_RETRIES) {
                this.close();
                this.emit('error', error);
            }
        };
    }

    on(eventName: string, callback: (...args: any[]) => void): this {
        super.on(eventName, callback);

        if (!this._listenedEvents.has(eventName)) {
            this._listenedEvents.add(eventName);

            // We should probably clean this up, but on the other hand ¯\_(ツ)_/¯
            this._eventSource.addEventListener(eventName, (message: MessageEvent) => {
                Logger.log(`[NOTIFICATIONS] Received event: ${eventName}`);
                try {
                    this.emit(eventName, JSON.parse(message.data));
                } catch {
                    if (!message.data) {
                        this.emit('error', new LibraryError('INVALID_RESPONSE', 'Received invalid response (no data)'));
                    } else {
                        this.emit('error', new LibraryError('INVALID_JSON', 'Received invalid JSON'));
                    }
                }
            });
        }

        return this;
    }

    close() {
        this.removeAllListeners();
        this._eventSource.close();
    }
}
