import { observable } from '../core/decorators';
import type { ISAMCorePrivate } from '../indexPrivate';
import { SAMObjectEventEmitter } from '../core/SAMObjectEventEmitter';
import type CacheableResponse from '../interface/CacheableResponse';
import type { ObservableQuery } from '@apollo/client';
import SAMError, { SAMErrorCode } from '../core/SAMError';

export interface ChangeDetails {
    /** If true, the response is from cache, and a subsequent response (or error) WILL follow. */
    loading?: boolean;
    /**
     * If true, the async response differed from the cache, and any lists that consumed the
     * previous response should be refreshed.
     * If false, the async response matched the cache, so no further action is required.
     * If undefined, the response cache was not used, so it behaves like a normal one-off response.
     */
    changed?: boolean;
    /** The etag of the object, having just been updated. (May not be present on all resource types.) */
    etag?: string | null;
    /**
     * The timestamp the data was originally fetched. For example, cached data should have an older
     * timestamp. If not provided, the current time will be used.
     */
    timestamp?: number;
}

export interface IResourceOptions<ParsedResponse> {
    /** An error callback, called when a request fails. */
    onError?: (error: any) => Promise<void>;
    /** Parse a response into this resource's data. */
    parseResponse?: (response: Response) => Promise<ParsedResponse>;
    /** Parse a response into this resource's data. */
    parseGraphQLResult?: (response: ObservableQuery.Result<any>) => Promise<ParsedResponse>;
    /**
     * Called when the resource changes, even if it is unloaded (note that the value may be undefined).
     * ResponseFlags indicate whether this response is still loading, and whether the data changed,
     * allowing consumers to know whether the previous response was stale.
     */
    onChange?: (value: ParsedResponse | undefined, details?: ChangeDetails) => Promise<void>;
    /**
     * Load the data for the resource. This callback should trigger a request and set the data,
     * typically by passing this Resource class as a parameter to fetch().
     * (The return value of this method is not used.)
     *
     * A subclass can override _loadData() to have the same effect.
     */
    loadData?: () => Promise<void>;
    /**
     * A resource should revalidate if it isn't sure if its value is outdated.
     * We'll use the cache, but check the server in the background. Typically
     * when resource is watched with ONS, we don't need to revalidate, because
     * we'll mark the resource dirty instead.
     */
    skipRevalidation?: () => boolean;
    skipCache?: () => boolean;
    getCacheKey?: (method: string, href: string, body?: BodyInit | null | undefined) => string;
}

export function isResponse(response: any): response is Response {
    return response && typeof response.json === 'function';
}

export function isGraphQLResult(response: any): response is ObservableQuery.Result<any> {
    return ('data' in response) || ('errors' in response);
}

/**
 * A resource wraps a response that can be loaded from the server. It can be observed for changes.
 * It can either be configured to fetch its own data (with `loadData`), or its data can be set
 * externally (with a fetch request, or via _setData).
 *
 * Resource works in tandem with the ResponseCache, if enabled, to support requests that may resolve
 * with more than one response:
 *
 *   (1) the initial response from cache
 *   (2) the updated response from the server, *if* it has changed.
 *
 * Consumers should use `.get()` to fetch the data, which will load it if necessary.
 */
export default class Resource<T = any> extends SAMObjectEventEmitter {

    private _isLoaded: boolean = false;
    private _parserOverride?: ((response: Response | ObservableQuery.Result<any>) => any) | undefined;
    private _data: T | undefined;
    protected _error: any;
    private _cacheKey: string | undefined;
    protected _etag: string = '';
    protected _timestamp: number = Date.now();

    constructor(
        /** @package */
        readonly _core: ISAMCorePrivate,
        private readonly _options: IResourceOptions<T> = {}
    ) {
        super(_core);
    }

    /**
     * A resource should be marked dirty if its value is _known_ to be outdated.
     * This will force the next load to fetch the data from the server, ignoring the cache.
     * The next successful response will mark the resource as clean.
     */
    public isDirty = false;

    protected async _loadData(): Promise<void> {
        // Resources could be loaded from an external source, via onResponse.
        // Subclasses might want to have a way to load data here.
        return this._options.loadData?.();
    }

    protected async _onChange(details?: ChangeDetails) {
        await this._options.onChange?.(this.data, details);
        this.emit('change');
    }

    /**
     * Load the resource, even if it has already been loaded.
     * If an error occurs right away, it will be thrown.
     */
    async load(): Promise<void> {
        await this._loadData();
    }

    /**
     * Get the data for the resource. The data will be fetched if one of the following is true:
     *   - it hasn't been loaded yet
     *   - it has been marked isDirty
     *   - forceRefresh is true
     */
    async get(options: { forceRefresh?: boolean }): Promise<T> {
        if (options.forceRefresh || !this.isLoaded || this.isDirty) {
            await this.load();
        }
        return this.data!;
    }

    /**
     * TODO_Deprecation: To be marked deprecated on or after 2025-03-01. When there are multiple
     * clients of a SAM instance, some wanting a Resource loaded and others wanting to unload, then that
     * creates an unresolvable conflict. SAM can use its lazy-loading pattern to ensures Resources are
     * only refreshed when there are clients that need it. For resources with large payloads, the data
     * should be stored as a WeakRef with `@keepAlive` decorator.
     */
    async unload() {
        this._data = undefined;
        this._etag = '';
        this._error = undefined;
        this._isLoaded = false;
        await this._onChange();
    }

    /**
     * Returns true if the data has been loaded. (Excludes updates from _mergeData.)
     */
    @observable
    get isLoaded(): boolean {
        return this._isLoaded;
    }

    /** The data for the resource. Accessing this does not fetch it; prefer .get() if needed. */
    @observable
    get data(): T {
        return this._data!;
    }

    /** The etag of the most recent Response (from its headers), otherwise an empty string. */
    @observable
    get etag(): string {
        return this._etag || '';
    }

    @observable
    get error(): any {
        return this._error;
    }

    /**
     * The timestamp the data was originally fetched. For example, cached data should have an older
     * timestamp. This is used to determine whether data in the cache is newer than the data
     * being merged in, to avoid overwriting newer data with older data.
     *
     * @package -- for use in SAM.js only
     */
    @observable
    get timestamp(): number {
        return this._timestamp;
    }

    /**
     * @package -- for use in SAM.js only
     */
    async _setData(data: T, details: ChangeDetails = {}): Promise<void> {
        this._data = data;
        this._etag = details.etag || '';
        this._timestamp = details.timestamp ?? Date.now();
        this._error = undefined;
        this._isLoaded = true;
        await this._onChange(details);
    }

    /**
     * Merge new data into existing. Supports cases where data sources might not include all fields,
     * such as for appMetadata in listings, typically called by ItemUpdaters. This does not affect the load
     * status or dirty status, because it's not known whether the data is stale after merging possibly incomplete data.
     * @package -- for use in SAM.js only
     */
    async _mergeData(data: any) {
        this._data = { ...(this._data || {}), ...(data || {}) };
        this._etag = ''; // Assume the etag is not valid if we've changed the data elsewhere
        await this._onChange();
    }

    /**
     * Parse the given response. If the parseResponse or parseGraphQLResult options are provided,
     * they will be used to parse the response. Otherwise, it will default to calling `response.json()`.
     * If the response is a GraphQL result, it will check for errors and throw a SAMError if any are present.
     *
     * @package -- for use in SAM.js only
     */
    async _parse(response: Response | ObservableQuery.Result<any>) {
        if (this._parserOverride) {
            return this._parserOverride(response);
        }

        if (isResponse(response)) {
            return this._options.parseResponse?.(response) ?? response.json();
        } else if (isGraphQLResult(response)) {
            return this._options.parseGraphQLResult?.(response) ?? response.data;
        } else {
            throw SAMError.create(SAMErrorCode.INTERNAL_ERROR, 'Resource.parse() received an unexpected response type: ' + response);
        }
    }

    /**
     * Used to override the default parser for the resource. This is useful for cases where we want custom parse logic which contains special error handling.
     *
     * @package -- for use in SAM.js only
     */
    public set parser(parser: (response: Response | ObservableQuery.Result<any>) => any) {
        this._parserOverride = parser;
    }

    /** @package */
    public get skipRevalidation(): boolean {
        return this._options.skipRevalidation?.() ?? false;
    }

    /** @package */
    public get skipCache(): boolean {
        return this._options.skipCache?.() ?? false;
    }

    /**
     * Complement to _setData() for internal SAM use; sets the error state on the resource,
     * calling the onError callback if provided.
     *
     * @package -- for use in SAM.js only
     */
    public async _setError(error: any): Promise<void> {
        try {
            // Set the error state on the resource first, whether or not we have an onError handler.
            // If the onError handler wants to treat this as a successful response,
            // it can call _setData() to clear the error on the resource.
            this._error = error;
            await this._options.onError?.(error);
        } catch (e) {
            // If the error handler throws an error, store that one as the resource's error.
            this._error = e;
        }
    }

    static getDefaultCacheKey(method: string, href: string, body?: BodyInit | null | undefined): string | undefined {
        if (body && typeof body !== 'string') {
            // Non-string bodies (such as Streams, if we ever use them) are not currently cacheable.
            return undefined;
        }
        return `${method}-${href}-${body ?? ''}`;
    }

    /**
     * Deletes the response from the cache.
     */
    async deleteCachedResponse(): Promise<void> {
        if (this._cacheKey) {
            const responseCache = this._core._environment._responseCache;
            if (responseCache) {
                await responseCache.deleteCachedResponse(this._cacheKey);
                this._cacheKey = undefined;
            }
        }
    }

    /** Track active revalidations to ensure we don't revalidate the same page concurrently. */
    private _activeRevalidations = new Map<string, Promise<any>>();

    /**
     * Perform a fetch request, intercepting the response to handle caching and revalidation.
     * If a cached response is available, it will be returned immediately. Unless the Resource
     * uses skipRevalidation(), the request will be revalidated in the background, and the Resource
     * will be updated with the new response when it arrives.
     *
     * @package
     */
    async _interceptFetch(
        method: string,
        href: string,
        body: BodyInit | null | undefined,
        performFetch: () => Promise<CacheableResponse>
    ): Promise<Response> {
        // NOTE: Environment._responseCache will be undefined if ResponseCache is disabled.
        const responseCache = this._core._environment._responseCache;
        let cachedResponse: CacheableResponse | undefined;
        if (!this._options.skipCache?.()) {
            this._cacheKey = this._options.getCacheKey?.(method, href, body) ?? Resource.getDefaultCacheKey(method, href, body);
            cachedResponse = (this.isDirty || !this._cacheKey) ? undefined : await responseCache?.getCachedResponse(this._cacheKey);
        }

        const subsequentResponseExpected = cachedResponse && !this._options.skipRevalidation?.();

        const performRevalidation = async (): Promise<Response> => {
            let response: CacheableResponse;
            try {
                response = await performFetch();
                // Save the response to the cache whether it matches or not, to ensure the TTL gets extended.
                if (this._cacheKey && responseCache) {
                    await responseCache?.saveResponseToCache(this._cacheKey, response);
                }
                const matches = await response.matches(cachedResponse);
                await this._setData(await this._parse(response), {
                    etag: response.headers.get('ETag') || '',
                    changed: subsequentResponseExpected && !matches,
                    timestamp: response.timestamp,
                    loading: false
                });
                return response;
            } catch (error) {
                await this._setError(error);
                // The error handler could have cleared the error (e.g. with `this._setData()`),
                // such as in cases where a 404 is expected and handled as a successful response.
                if (!this._error) {
                    // A fetch might've returned a SAMError but then been handled as a successful response.
                    return new Response();
                } else {
                    throw this._error;
                }
            }
        };

        // Track revalidations to prevent multiple concurrent revalidations for the same cache key.
        const revalidate = async () => {
            const existingPromise = this._cacheKey && this._activeRevalidations.get(this._cacheKey);
            if (existingPromise) {
                return await existingPromise;
            }
            try {
                const promise = performRevalidation();
                if (this._cacheKey) {
                    this._activeRevalidations.set(this._cacheKey, promise);
                }
                return await promise;
            } finally {
                if (this._cacheKey) {
                    this._activeRevalidations.delete(this._cacheKey);
                }
            }
        };

        if (cachedResponse) {
            // If we're going to revalidate, kick it off in the background, and return the cached response in the meantime.
            if (subsequentResponseExpected) {
                void revalidate();
            }
            await this._setData(await this._parse(cachedResponse), {
                etag: cachedResponse.headers.get('ETag') || '',
                changed: false, // The first cached response is not changed, for the purposes of list refreshing.
                timestamp: cachedResponse.timestamp,
                loading: subsequentResponseExpected
            });
            return cachedResponse;
        } else {
            return revalidate();
        }
    }
}

/**
 * A Passthrough Resource doesn't cache responses.
 * It is used for requests that do not provide their own Resource,
 * where we haven't explicitly set up a Resource to handle a cached response.
 * Providing a Resource allows us to handle requests with the same codepath whether attached to a Resource or not.
 */
export class PassthroughResource extends Resource<Response> {
    constructor(readonly _core: ISAMCorePrivate) {
        super(_core, {
            parseResponse: async (response: Response) => response,
            skipCache: () => true,
        });
    }
}
