import InterfaceBase from './InterfaceBase';
import {
    FetchFields,
    type ISearchQuery,
    type ISearchQueryEntry,
    type USSResponse,
} from './USSv3Model';

export const DEFAULT_MAX_LIMIT = 50;
export const USS_CONTENT_TYPE = 'application/vnd.adobe.search-request+json';
export const DEFAULT_EXPERIENCE_ID = 'Default-DMe-Search-Experience';

export default class USSv3Interface extends InterfaceBase {

    readonly queryPath: string = '/uss/v3/query';

    async getQueryResponse(queryEntry: ISearchQueryEntry): Promise<USSResponse> {
        const url = `https://${this._core._environment.endpoints.USSv3_HOST}${this.queryPath}`;
        const queryEntryWithDefaults: ISearchQueryEntry =  {
            // USS only allows specific query ids to be passed, 'dme-search-1' is the one USS team said SAM.js
            // should use.
            'id': 'dme-search-1',
            'scope': {
                'entities': [ 'DMeEnterpriseAsset' ]
            },
            'fetchFields': [
                FetchFields.SharedBy,
                FetchFields.ShellVisibility,
                // --- USS v3 includes these fields, and more, by default ---
                // am.shell:lastActivity.date
                // am.project:directoryType
                // am.cc:inheritable:*
                // am.cc:inherited:*
                // am.assignment:*
                // am.classroom:*
                // am.hz:documentMetadata.*,
                // --- end USS v3 default fields ---
                FetchFields.ReviewSourceAssetType,
                // --- Below are candidates for loadHints ---
                FetchFields.ConvertedTo,
                FetchFields.NonAutoMigratable,
                FetchFields.CopiedLegacySparkId,
                FetchFields.CreatedFromUpload
            ],
            ...queryEntry
        };
        const query: ISearchQuery = {
            experienceId: DEFAULT_EXPERIENCE_ID,
            queries: [ queryEntryWithDefaults ]
        };
        const response = await this._doPost(
            url,
            {
                'content-type': USS_CONTENT_TYPE,
                /**
                 * See {@link RepositoryInterface._getFetchOptionOverrides} for details
                 * about link-2023 and link-options.
                 */
                'directive': 'link-2023',
                'link-options': 'absolute-base,long-form-rel'
            },
            JSON.stringify(query),
            [ 200 ]
        );

        return response.json();
    }
}
