import ImplicitAdobeAssetFilterBase from './ImplicitAdobeAssetFilterBase';
import type { IImplicitFilter } from '../core/ItemFilter';
import type AdobeAsset from './AdobeAsset';

export interface ISpaceSearchAssetFilterOptions {
    // For Space.searchWorkingFiles and Space.searchArtifacts, it needs an implicit filter
    // so the two sources generate separate lists. Can't use the AdobeAsset of the Space or
    // the working_files folder, because it isn't known at the time the Source is constructed.
    readonly asset?: AdobeAsset;
    readonly artifactFilter?: 'onlyArtifacts' | 'excludeArtifacts';
    /**
     * @package -- for use in SAM.js only
     */
    readonly _includeHiddenRecursive?: boolean;
}

export default class SpaceSearchAssetFilter extends ImplicitAdobeAssetFilterBase implements IImplicitFilter<AdobeAsset> {
    static default = new SpaceSearchAssetFilter();
    private _asset?: AdobeAsset;
    readonly artifactFilter?: ISpaceSearchAssetFilterOptions['artifactFilter'];

    constructor(options?: ISpaceSearchAssetFilterOptions) {
        super({ _includeHiddenRecursive: options?._includeHiddenRecursive });
        this._asset = options?.asset;
        this.artifactFilter = options?.artifactFilter;
    }

    matches(item: AdobeAsset) {
        // check if item is a descendant of the space/working Files folder
        if (this._asset?.repoPath && !item.repoPath.startsWith(`${this._asset.repoPath}/`)) {
            return false;
        }

        // check item meets artifactFilter criteria
        if (item.isArtifact && this.artifactFilter === 'excludeArtifacts') {
            return false;
        }
        if (!item.isArtifact && this.artifactFilter === 'onlyArtifacts') {
            return false;
        }

        return super.matches(item);
    }
}
