import StudentAssignmentsInterface from '../interface/StudentAssignmentsInterface';
import AppMetadataResource from '../assets/AppMetadataResource';
import type { ISAMCorePrivate } from '../indexPrivate';
import type StudentAssignment from './StudentAssignment';
import { StudentAssignmentUpdater } from './StudentAssignment';
import { RequestHeaders } from '../utils/classroomUtils';

export default class StudentAssignmentAppMetadataResource extends AppMetadataResource {
    private _studentAssignmentsInterface;

    constructor(
        readonly _core: ISAMCorePrivate,
        readonly _parent: StudentAssignment,
    ) {
        super(_core, _parent);

        this._studentAssignmentsInterface = new StudentAssignmentsInterface(this._core);
    }

    protected async _loadData() {
        // Get the core links from RAPI
        const rapiLinks = await this._core.hostAssetContext._rapi.getAssetLinks(this._parent.id);

        // Application specific links are within the Hume response, we will merge these with the core links
        const studentAssignmentMetadata = await this._studentAssignmentsInterface.getStudentAssignment(this._parent.id, undefined, { [RequestHeaders.PREFER_RAPI]: 'true' });
        const { _links: humeLinks, ...rest } = studentAssignmentMetadata;
        await this._setData({
            ...rest,
            _links: {
                ...rapiLinks,
                ...humeLinks,
            }
        });

        // Updates the StudentAssignment to include the latest app metadata
        const session = this._core._getAssetPool().createMutationSession<StudentAssignment>(this.timestamp);
        StudentAssignmentUpdater.updateLocalItem(session, this._parent, this.data);
        session.commit();
    }
}
