import type { LinkReference } from '../../index';
import type { ElementReference, LibraryReference } from '../CCLibraries';
import type { Stringified } from '../types';

/**
 * Check if a reference is in the new link schema format (aka valid JSON string or object).
 * Returns the parsed object if it is, and undefined if not.
 * @param reference A string reference that may be serialized JSON
 */
export function parseNewLinkSchema(reference: ElementReference): LinkReference | undefined {
    try {
        // If reference is already an object, return the object.
        if (reference && typeof reference === 'object' && !Array.isArray(reference)) {
            return reference as LinkReference;
        }
        const obj = JSON.parse(reference as Stringified<LinkReference>);
        // Handle non-exception-throwing cases by checking if object: e.g. 'false', '123', false, 123, null
        // Note: typeof null === "object" but luckily null is falsey
        if (obj && typeof obj === 'object' && !Array.isArray(obj)) {
            return obj;
        }
    } catch (e) {
        return;
    }
}

/**
 * Check if a reference is in the new link schema format (aka valid JSON string or object).
 * Returns the serialized object if it is. Otherwise, parses the legacy reference into a partial new link schema
 * and returns the string that results from serializing that partial reference.
 * @param reference A serialized link reference object or a legacy link reference string.
 */
export function serializeLinkReference(
    reference: ElementReference | LibraryReference
): Stringified<LinkReference> | string {
    // Ensure we're working with an object.
    const linkRef = parseLinkReference(reference);
    if (!linkRef) {
        return '';
    }
    return JSON.stringify(linkRef, Object.keys(linkRef).sort()) as Stringified<LinkReference>;
}

const ELEMENT_REF_REGEXP = new RegExp('([^/]+);node=(.*)');

/**
 * Parse any element reference into an object, including legacy string-based references (though they will parse into partial references).
 * @param reference A link reference object or string.
 */
export function parseLinkReference(reference: ElementReference): LinkReference | Partial<LinkReference> | undefined {
    return parseNewLinkSchema(reference) || parseLegacyLinkSchema(reference as string);
}

export function parseLegacyLinkSchema(reference: string): Partial<LinkReference> | undefined {
    const matches = reference.match(ELEMENT_REF_REGEXP);
    if (!matches) {
        return;
    }

    const [ , libraryId, elementId ] = matches;
    return {
        'dc:format': 'application/vnd.adobe.library+dcx',
        'stRef:documentID': libraryId,
        'stRef:fromPart': `id=${elementId}`
    };
}

export function getAssetAndFragmentIdFromReference(
    reference: ElementReference
): { libraryAssetId: string; libraryId: string; elementId: string } | undefined {
    const linkRef = parseLinkReference(reference);
    if (!linkRef) {
        return;
    }
    // The library's assetId should always be available, except for legacy references.
    const libraryAssetId = linkRef['repo:assetId'] as string;
    const libraryId = linkRef['stRef:documentID'] as string;
    const elementId = (linkRef['stRef:fromPart'] as string)?.substring(3); // remove 'id='
    return { libraryAssetId, libraryId, elementId };
}
