// Memoize the value of a getter or method - this just caches the return value
// forever, so it doesn't get recomputed each time it's called
export default (target: any, propertyKey: string, descriptor: PropertyDescriptor) => {
    const memo = Symbol(`@memoize ${propertyKey}`);
    const property = descriptor.get ? 'get' : 'value';
    const method = descriptor[property];
    descriptor[property] = function (this: { [memo]: ReturnType<typeof method> }, ...args: any[]) {
        if (!Object.prototype.hasOwnProperty.call(this, memo)) {
            this[memo] = method.call(this, ...args);
        }
        return this[memo];
    };
};
