export type VulcanMessageInitializer = {
    type: string;
    scope?: string;
    appId?: string;
    appVersion?: string;
    data?: string;
};

export type VulcanCallback = (message: string) => void;
export type CCDVulcanCallback = (type: string, message: string) => void;
export type VulcanCallbacks = VulcanCallback | CCDVulcanCallback;

export interface IVulcanMessage extends Required<VulcanMessageInitializer> {
    // eslint-disable-next-line
    new (type: string): IVulcanMessage;
    initialize: (message: VulcanMessageInitializer) => void;
    xmlData: () => string;
    setPayload: (payload: string) => void;
    getPayload: () => string | null;
    toString: () => string;
}

export interface IVulcan {
    addMessageListener: (type: string, callback: VulcanCallbacks, obj?: {}) => void;
    removeMessageListener: (type: string, callback: VulcanCallbacks, obj?: {}) => void;
    dispatchMessage: (message: IVulcanMessage) => void;
    getPayload: (message: string) => string | null;
}

export abstract class VulcanInterface implements IVulcan {
    protected abstract get vulcanInterface(): IVulcan5 | IVulcan7;
    abstract addMessageListener(type: string, callback: VulcanCallbacks, obj?: {}): void;
    abstract removeMessageListener(type: string, callback: VulcanCallbacks, obj?: {}): void;
    abstract dispatchMessage(message: IVulcanMessage): void;
    abstract getPayload(message: string): string | null;
    abstract getTargetSpecifiers(): string[];
    abstract launchApp(focus?: boolean, cmdLine?: string): boolean;
    abstract isAppRunning(): boolean;
    abstract isAppInstalled(): boolean;
    abstract getAppPath(): string;
}

export interface IVulcan5 extends IVulcan {
    getTargetSpecifiers: () => string[];
    launchApp: (targetSpecifier: string, focus?: boolean, cmdLine?: string) => boolean;
    isAppRunning: (targetSpecifier: string) => boolean;
    isAppInstalled: (targetSpecifier: string) => boolean;
    getAppPath: (targetSpecifier: string) => string;
}

export interface IVulcan7 extends IVulcan {
    getTargetSpecifiersEx: () => string[];
    launchAppEx: (productSAPCodeSpecifier: string, focus: boolean, cmdLine: string) => boolean;
    isAppRunningEx: (productSAPCodeSpecifier: string) => boolean;
    isAppInstalledEx: (productSAPCodeSpecifier: string) => boolean;
    getAppPathEx: (productSAPCodeSpecifier: string) => string;
}

export type UXPInstalledApps = Array<{
    name: string;
    sapCode: string;
    launch: () => Promise<void>;
    isRunning: () => Promise<boolean>;
}>;

export interface IUXPVulcanMessage {
    payload: string;
}

export interface IUXPVulcanDispatcher {
    addEventListener: (type: string, callback: VulcanCallbacks) => void;
    removeEventListener: (type: string, callback: VulcanCallbacks) => void;
    broadcastMessage: (message: IUXPVulcanMessage) => void;
}

export interface IUXPVulcanControl {
    getInstalledApps: () => Promise<UXPInstalledApps>;
    getInstalledAppsEx?: () => Promise<UXPInstalledApps>;
}

export interface IUXPVulcan {
    message: new (type: string, data: string) => IUXPVulcanMessage;
    dispatcher: IUXPVulcanDispatcher;
    control: IUXPVulcanControl;
}
