import type {
    IImplicitAdobeAssetFilterBaseOptions
} from '../../assets/ImplicitAdobeAssetFilterBase';
import type LegacyCustomModel from './LegacyCustomModel';
import LegacyImplicitCustomModelFilter from './LegacyImplicitCustomModelFilter';

export interface ICustomModelSearchListingOptions {
    query: string
}

export default class CustomModelSearchFilter extends LegacyImplicitCustomModelFilter {
    readonly _query: string;
    _matchingIDsFromSearch: Set<string> | undefined;

    constructor(options: ICustomModelSearchListingOptions & Partial<IImplicitAdobeAssetFilterBaseOptions>) {
        const { query, ...superOptions } = options;
        super(superOptions);

        this._query = query.trim();
    }

    get query(): string {
        return this._query;
    }

    matches(item: LegacyCustomModel): boolean {
        // Check if the item's id is in the current filter's id list
        if (this._matchingIDsFromSearch && !this._matchingIDsFromSearch.has(item.id)) {
            return false;
        }

        // If the query exists but there's no id list, we probably haven't finished loading yet
        if ((this._query) && !this._matchingIDsFromSearch) {
            return false;
        }
        return super.matches(item);
    }
}
