import SAMError, { SAMErrorCode } from '../../src/core/SAMError';

/**
 * Returns the keys of an enum that are not numbers.
 *
 * @param e - The enum to get the keys of.
 * @returns The keys of the enum that are not numbers.
 */
function enumKeys<E extends object>(e: E): (keyof E)[] {
    return Object
        .keys(e)
        .filter(k => isNaN(Number(k))) as (keyof E)[];
}

/**
 * Creates a bi-directional map between two enums.
 *
 * @typeParam A - The "local" enum.
 * @typeParam B - The "remote" enum.
 * @typeParam TPair - The type of the array of pairs of values from the two enums.
 *
 * @param pairs - An array of pairs of values from the two enums.
 * @returns An object with methods to convert between the two enums.
 */
export function enumMap<
    TEnumA extends Record<string, unknown>,
    TEnumB extends Record<string, unknown>,
    TValueA extends TEnumA[keyof TEnumA],
    TValueB extends TEnumB[keyof TEnumB]
>(
    enumA: TEnumA,
    enumB: TEnumB,
    entries: ReadonlyArray<[TValueA, TValueB]>
): {
        toB(value: TValueA): TValueB;
        toA(value: TValueB): TValueA;
    } {
    // Gather the enum keys as the values to work with from the two enums.
    const valuesA = enumKeys(enumA).map(k => enumA[k]);
    const valuesB = enumKeys(enumB).map(k => enumB[k]);

    // The mapping must cover every value exactly once or there is likely a mismatch.
    if (entries.length !== valuesA.length || entries.length !== valuesB.length) {
        throw SAMError.create(SAMErrorCode.INTERNAL_ERROR,
            `Enum-to-enum map must have exactly ${valuesA.length} entries, got ${entries.length}`
        );
    }

    const aToB = new Map<TValueA, TValueB>();
    const bToA = new Map<TValueB, TValueA>();

    // Create the forward and reverse mappings, keeping track of which values have been seen to
    // catch duplicates.
    for (const [ valueA, valueB ] of entries) {
        if (!valuesA.includes(valueA)) {
            throw SAMError.create(SAMErrorCode.INTERNAL_ERROR,
                `Value ${valueA} not in enum A`
            );
        }
        if (!valuesB.includes(valueB)) {
            throw SAMError.create(SAMErrorCode.INTERNAL_ERROR,
                `Value ${valueB} not in enum B`
            );
        }
        if (aToB.has(valueA)) {
            throw SAMError.create(SAMErrorCode.INTERNAL_ERROR,
                `Duplicate mapping for A value ${valueA}`
            );
        }
        if (bToA.has(valueB)) {
            throw SAMError.create(SAMErrorCode.INTERNAL_ERROR,
                `Duplicate mapping for B value ${valueB}`
            );
        }

        aToB.set(valueA, valueB);  // Map A to B.
        bToA.set(valueB, valueA);  // Map B to A.
    }

    return {
        toB(value: TValueA): TValueB {
            const valueB = aToB.get(value);
            if (valueB === undefined) {
                throw SAMError.create(SAMErrorCode.INTERNAL_ERROR,
                    `No B-value mapped for A value ${value}`
                );
            }
            return valueB;
        },
        toA(value: TValueB): TValueA {
            const valueA = bToA.get(value);
            if (valueA === undefined) {
                throw SAMError.create(SAMErrorCode.INTERNAL_ERROR,
                    `No A-value mapped for B value ${value}`
                );
            }
            return valueA;
        }
    };
}
