import uuid from 'uuid';

import type { ONSContext } from './ONSContext';
import type { ONSHeaderMap, ONSWorkerEventMap, ONSWorkerInterface } from './ONSWorker.interface';
import type { AxonVirtualConnection } from '@ccx-public/axon-client';
import { synchronized } from '../core/decorators';
import { default as TypedEventEmitter } from '../core/TypedEventEmitter';
import type { ErrorMessage } from '@ccx-public/axon-client';
import type { AxonClient, Loggable } from '@ccx-public/axon-client';
import type { ONSCachedSubscription, ONSSubscriptionChangeEvent } from './ONSSubscription';
import { type ONSObjectMap, ONSSubscription, SubscriptionMonitoringStatus } from './ONSSubscription';
import { ONS_MONITORING_STATUS_CHANGED, OnsMonitoringStatus, ONSMonitoringStatusChangedEvent } from './ONSEvent';
import type { ONSObjectProperties } from './ONSResource';
import type { default as Cache } from '../core/Cache';
import { NotFound } from '../core/Cache';

export const cacheKey = 'ONS_SUBSCRIPTIONS';

interface Subscription {
    id: string;
    continuationToken?: string;
}

interface CheckSubscription {
    id: string;
}

interface Notification {
    subscriptions?: Subscription[];
    checkSubscriptions?: CheckSubscription[];
}

interface RegistrationRequest {
    subscriptions: Subscription[];
}

interface Message {
    operationName: string;
    operationId: string;
    body: Notification | RegistrationRequest;
}

export class ONSAxonWorker extends TypedEventEmitter<ONSWorkerEventMap> implements ONSWorkerInterface, Loggable {
    private _axonVc: AxonVirtualConnection | undefined;
    private _isActive: boolean = false;
    private _subscriptions: ONSSubscription[] = [];
    // Note: actual limit is determined in _ensureSubscriptions
    private _maxObjectsPerSubscription: number = 100;
    private _watchedObjects: ONSObjectMap = new Map();
    private _cache: Cache;
    private _registrationOperationIds: Set<string> = new Set();

    constructor(
        readonly _onsContext: ONSContext,
    ) {
        super();
        this._cache = _onsContext._core._environment.cache;
    }

    get isActive(): boolean {
        return this._isActive;
    }

    get subscriptions(): ONSSubscription[] {
        return this._subscriptions;
    }

    /**
     * Handles ONS Message event.
     * @param event - Message.
     */
    private _onVcMessage = (message: Message) => {
        switch (message.operationName) {
        case 'notification':
            this._handleNotification(message.body);
            break;
        case 'error':
            if (this._registrationOperationIds.has(message.operationId)) {
                this._registrationOperationIds.clear();
                this.logError('ONS Error received for a registration operation. Will close the ONS Virtual Connection.', message);
                this._closeAxonVc().then(() => {
                    this._restartMonitoring();
                });
                return;
            }
            this.logError('Unknown ONS Error received.', message);
            break;
        default:
            this.logWarn('Unknown Axon Message received', message);
            break;
        }
    };

    /**
     * Handles ONS Error event.
     * @param event - Message.
     */
    private _onVcError = (event: ErrorMessage) => {
        this.logError('Axon Error received', event);
    };

    /**
     * Handles Deleted VC event.
     */
    private _onVcDeleted = () => {
        this.logInfo('Axon Virtual Connection has been deleted');
        this.deinitialize();
        this.ensureReady();  // Re-create the Virtual Connection.
    };

    private _onVcSessionStatusChanged = () => {
        if (this._axonVc?.isActive()) {
            this.logDebug('Virtual Connection status changed to Active. Restarting ONS Monitoring...');
            this.emit(ONS_MONITORING_STATUS_CHANGED, new ONSMonitoringStatusChangedEvent(OnsMonitoringStatus.Restarting));
            this._restartMonitoring();
        } else {
            this.logDebug('Virtual Connection status changed to non-Active.');
            this.emit(ONS_MONITORING_STATUS_CHANGED, new ONSMonitoringStatusChangedEvent(OnsMonitoringStatus.Inactive));
        }
    };

    private _handleNotification(notification: Notification) {
        this.logDebug('Axon Notification received', notification);
        notification.subscriptions?.forEach((sub: Subscription) => {
            // Find subscription |sub| in the subscriptions array.
            const subscription = this.subscriptions.find(s => s.subscriptionId === sub.id);
            if (!subscription) {
                this.logWarn(`Subscription ${sub.id} not found in the subscriptions array. Skipping notification handling.`);
                return;
            }

            // Mark subscription as monitored.
            subscription.monitoringStatus = SubscriptionMonitoringStatus.Active;

            // Update subscription's continuation token.
            subscription.continuationToken = sub.continuationToken;

            // Trigger the changed subscription to fetch changes via the changelog API:
            // Note that ONS does not yet support a single changelog for multiple subscriptions, so we have
            // to call the changelog separately for each subscription right now.
            subscription.fetchAndNotifyChanges();
        });

        // Quick check on the expire times on the active subscriptions.
        this._validateAndUpdateSubscriptionExpiration();

        // If ONS is worried that our subscription is invalid, verify it is still there. (ONS will do this
        // every few hours no matter what.)
        notification.checkSubscriptions?.forEach((checkSub: CheckSubscription) => {
            const subscription = this.subscriptions.find(s => s.subscriptionId === checkSub.id);
            if (subscription) {
                subscription.validate();
            }
        });
    }

    private async _ensureAxonVc(): Promise<AxonVirtualConnection> {
        const axonClient = await this._onsContext._core._getAxonClient();
        if (!await axonClient.session.ensureEstablished()) {
            throw new Error('Axon Session could not be established!');
        }

        if (this._axonVc && await this._axonVc.ensureActive()) {
            return this._axonVc;
        }

        this.logDebug('ONS Virtual Connection is not active. Will create a new one...');
        this._deactivate();

        const onsSubscriptionConfig = await this._onsContext.getSubscriptionConfig();
        if (!onsSubscriptionConfig?.onsAxonServiceName?.length) {
            throw new Error('Failed to determine ONS Service Id');
        }

        const headers: ONSHeaderMap = {
            'x-api-key': this._onsContext._core._environment.getValue('CLIENT_ID'),
            'locale': axonClient.config.locale };
        this._axonVc = await axonClient.session.createVc(onsSubscriptionConfig.onsAxonServiceName, headers);
        this._axonVc.on('message', this._onVcMessage);
        this._axonVc.on('error', this._onVcError);
        this._axonVc.on('deleted', this._onVcDeleted);
        this._axonVc.on('session_status_changed', this._onVcSessionStatusChanged);
        return this._axonVc;
    }

    // ONS Subscriptions are more efficient if they are kept alive and updated so we check whether the subscription
    // is within 10% of its TTL and refresh as necessary
    private _validateAndUpdateSubscriptionExpiration() {
        const now = Date.now();

        // We calculate the remaining time to live being within a 10% zone of the current time based
        // on environment set TTL with a minimum time remaining being 5 mins.
        const ttl = Math.max(
            this._onsContext._core._environment.getValue('ONS_SUBSCRIPTION_TIME_TO_LIVE') * 0.1,
            this._onsContext._core._environment.getValue('ONS_SUBSCRIPTION_RENEW_TIME')
        );
        this.subscriptions
            .filter(sub => sub.watchedONSObjects.size && (sub.expiresAt - now) < ttl)
            .forEach(sub => sub.refreshSubscriptionExpiryDate());
    }

    private async _closeAxonVc() {
        if (this._axonVc?.isActive()) {
            const axonClient = await this._onsContext._core._getAxonClient();
            if (await axonClient.session.ensureEstablished()) {
                try {
                    if (!await axonClient.session.deleteVc(this._axonVc)) {
                        this.logWarn('Failed to delete ONS Virtual Connection');
                    }
                } catch (error) {
                    this.logWarn('Failed to delete ONS Virtual Connection', error);
                }
            }
        }
        this._deactivate();
    }

    private _deactivate() {
        this.subscriptions.forEach(sub => sub.monitoringStatus = SubscriptionMonitoringStatus.Inactive);
        if (!this._axonVc) { return; }
        this._axonVc.off('message', this._onVcMessage);
        this._axonVc.off('error', this._onVcError);
        this._axonVc.off('deleted', this._onVcDeleted);
        this._axonVc = undefined;
    }

    /**
     * Deinitializes the ONS Axon Worker and closes its underlying Virtual Connection to ONS.
     * @returns A promise that resolves to true if the worker is deinitialized, false otherwise.
     */
    @synchronized
    async deinitialize(): Promise<boolean> {
        this.emit(ONS_MONITORING_STATUS_CHANGED, new ONSMonitoringStatusChangedEvent(OnsMonitoringStatus.Inactive));
        if (!this._axonVc) { return true; }  // VC is already deinitialized.
        const vc = this._axonVc;
        this._deactivate();
        let axonClient: AxonClient;
        if (!vc.isActive()) { return true; }  // VC is inactive.
        try {
            axonClient = await this._onsContext._core._getAxonClient();
            if (!axonClient.isConnected()) {
                return true;  // Axon Client is already disconnected.
            }
            if (!await axonClient.session.ensureEstablished()) {
                throw new Error('Axon Session could not be established!');
            }
        } catch (error) {
            this.logWarn('ONS Virtual Connection deletion skipped', error);
            return true;
        }
        try {
            return await axonClient.session.deleteVc(vc);
        } catch (error) {
            this.logError('Failed to delete ONS Virtual Connection', error);
            return false;
        }
    }

    /**
     * Ensures that the ONS Virtual Connection is created and active.
     * @returns A promise that resolves to true if the ONS Virtual Connection is ready, false otherwise.
     */
    @synchronized
    async ensureReady(): Promise<boolean> {
        try {
            const vc = await this._ensureAxonVc();
            if (!await vc.ensureActive()) {
                this.logError('Failed to acquire an active ONS Virtual Connection!');
                this.emit(ONS_MONITORING_STATUS_CHANGED, new ONSMonitoringStatusChangedEvent(OnsMonitoringStatus.Error));
                return false;
            }
            return true;
        } catch (error) {
            this.logError('Failed to get the ONS Virtual Connection', error);
            this.emit(ONS_MONITORING_STATUS_CHANGED, new ONSMonitoringStatusChangedEvent(OnsMonitoringStatus.Error));
            return false;
        }
    }

    @synchronized
    async start(): Promise<void> {
        if (this.isActive) {
            this.logDebug('ONS Axon Worker is already active. Skipping this request!');
            return;
        }

        this.logDebug('Starting ONS Axon Worker...');
        this._isActive = true;
        this.emit(ONS_MONITORING_STATUS_CHANGED, new ONSMonitoringStatusChangedEvent(OnsMonitoringStatus.Active));

        if (!await this.ensureReady()) {
            this.logError(`Failed to acquire Axon virtual connection to the ONS! ONS Axon Worker will not be started.`);
            return;
        }

        if (!await this._monitorActiveSubscriptions()) {
            this.logError('Failed to start monitoring of active subscriptions!');
        }
    }

    stop() {
        if (!this.isActive) {
            this.logDebug(`ONS Axon Worker is already stopped! Skipping this request!`);
            return;
        }
        this.logDebug('Stopping ONS Axon Worker...');
        this.subscriptions.forEach((sub: ONSSubscription) => sub.abort());
        this._isActive = false;
        this.emit(ONS_MONITORING_STATUS_CHANGED, new ONSMonitoringStatusChangedEvent(OnsMonitoringStatus.Inactive));
    }

    @synchronized
    private async _restartMonitoring() {
        if (!this.isActive) {
            this.logDebug('ONS Axon Worker is not active. Skipping this request!');
            return;
        }
        this.logDebug(`Restarting ONS Monitoring over Axon for active subscriptions: [${this._activeSubscriptions.map(sub => sub.subscriptionId).join(',')}].`);
        this.stop();
        await this.start();
    }

    private async _getAndParseCachedSubscriptions(): Promise<ONSCachedSubscription[]> {
        // @TODO SAM-2845 Prevent data from being retrieved from cache
        // until it is enabled again in the future.
        if (!this._onsContext.cacheEnabled) {return [];}

        const existingCreatedSubscriptions = await this._cache.getItem(cacheKey);
        if (existingCreatedSubscriptions !== NotFound) {
            try {
                return JSON.parse(existingCreatedSubscriptions)?.subscriptions || [];
            } catch (e) {
                this.logInfo('error parsing cached subscriptions');
            }
        }
        return [];
    }

    @synchronized
    private async _updateCachedSubscriptions() {
        // @TODO SAM-2845 where this is defined for more information.
        // Prevent data from being written to cache
        // until it is enabled again in the future.
        if (!this._onsContext.cacheEnabled) { return; }

        const newCachedSubscriptions: ONSCachedSubscription[] = [];
        this._subscriptions.forEach((subscription) => {
            const { subscriptionId, subscriptionHref, pendingONSObjects, expiresAt } = subscription;
            // If the ONSSubscription doesn't have an ID or Href
            // that means it wasn't created on the server and
            // it doesn't have any information to cache.
            if (!subscriptionId || !subscriptionHref) {
                return;
            }

            const updatedCache: ONSCachedSubscription = {
                id: subscriptionId,
                href: subscriptionHref,
                onsObjects: Object.fromEntries(pendingONSObjects),
                expiresAt: expiresAt || Date.now() + this._onsContext._core._environment.getValue('ONS_SUBSCRIPTION_TIME_TO_LIVE')
            };

            newCachedSubscriptions.push(updatedCache);
        });

        await this._cache.setItem(
            cacheKey,
            JSON.stringify({ subscriptions: newCachedSubscriptions }),

            // This ensures that the cached subscription will expire the same time
            // that the subscription expires on the server.
            this._onsContext._core._environment.getValue('ONS_SUBSCRIPTION_TIME_TO_LIVE')
        );
    }

    private _onSubscriptionChange = (_event?: ONSSubscriptionChangeEvent) => {

        this.logDebug('Subscriptions changed!');
        this._updateCachedSubscriptions()
            .finally(() => this._restartMonitoring())
            .catch((err) => this.logWarn('restartMonitoring failed upon subscription change', err));
    };

    private get _subscriptionsWithAssets(): ONSSubscription[] {
        return Array.from(this._subscriptions)
            .filter(sub => sub.pendingONSObjects.size > 0);
    }

    private get _activeSubscriptions(): ONSSubscription[] {
        return this._subscriptionsWithAssets
            .filter(sub => sub.subscriptionId && sub.subscriptionHref) // Note: watchedAssets not assets
            .sort((a, b) => a.subscriptionId! <= b.subscriptionId! ? -1 : 1); // Sort by subscription ID.
    }

    private get _monitoredSubscriptions(): ONSSubscription[] {
        return this._activeSubscriptions.filter(sub => sub.monitoringStatus === SubscriptionMonitoringStatus.Active);
    }

    @synchronized
    private async _monitorActiveSubscriptions(): Promise<boolean> {
        let subscriptionsToMonitor = this._activeSubscriptions.filter(sub => sub.monitoringStatus === SubscriptionMonitoringStatus.Inactive);
        if (subscriptionsToMonitor.length === 0) {
            this.logDebug(`No new subscriptions to register for monitoring. Currently monitoring: [${this._monitoredSubscriptions.map(sub => sub.subscriptionId).join(',')}].`);
            return true;
        }

        if (!await this.ensureReady()) {
            this.logError(`Failed to acquire Axon connection to ONS!`);
            return false;
        }

        // Validate all subscriptions to be monitored.
        for (const sub of subscriptionsToMonitor) {
            await sub.validate();
        }

        // Only monitor subscriptions that have a subscriptionHref (presumed to be valid).
        subscriptionsToMonitor = subscriptionsToMonitor.filter(sub => sub.subscriptionHref);

        this.logDebug(`Registering monitoring for new active subscriptions: [${subscriptionsToMonitor.map(sub => sub.subscriptionId).join(',')}].`);
        try {
            const operationId = uuid();
            this._registrationOperationIds.add(operationId);
            const message: Message = {
                'operationName': 'register',
                operationId,
                'body': this._createMonitoringRegistrationRequest(subscriptionsToMonitor),
            };
            this.logDebug(`Sending subscription monitoring request over Axon`, message);
            this._axonVc!.sendMessage(JSON.stringify(message));
            subscriptionsToMonitor.forEach(sub => sub.monitoringStatus = SubscriptionMonitoringStatus.Registering);
            return true;
        } catch (error) {
            this.logError(`Failed to send subscription monitoring request over Axon`, error);
            return false;
        }
    }

    // Creates ONS Registration Request for the monitored subscriptions.
    private _createMonitoringRegistrationRequest(subscriptions: ONSSubscription[]): RegistrationRequest {

        const registerationRequest: RegistrationRequest = {
            'subscriptions': []
        };

        for (const sub of subscriptions) {
            if (!sub.subscriptionId) {
                continue;
            }
            const item: Subscription = {
                'id': sub.subscriptionId
            };
            if (sub.continuationToken) {
                item.continuationToken = sub.continuationToken;
            }
            registerationRequest.subscriptions.push(item);
        }

        return registerationRequest;
    }

    private async _ensureSubscriptions() {
        // This will create and store instances of ONSSubscription
        // the number created will be the number of MAX_SUBSCRIPTIONS
        // set by SAM.js or service (we don't actually create subscriptions
        // on the server though, unless they have any assets to monitor)

        const maxSubscriptions = this._onsContext._core._environment.getValue('ONS_DEFAULT_MAX_SUBSCRIPTIONS');
        this._maxObjectsPerSubscription = this._onsContext._core._environment.getValue('ONS_DEFAULT_MAX_ASSETS_PER_SUBSCRIPTION');
        if (maxSubscriptions > this._subscriptions.length) {
            // Just because we are creating an ONSSubscription does not mean
            // we are creating a subscription on the service. We actually
            // create the max number of local ONSSubscription allowed by ONS but only
            // create the subscription on the service if there are assets on that subscription.

            // Get cached subscriptions from cache if subscription caching is enabled.
            const parsedCachedSubscriptions = await this._getAndParseCachedSubscriptions();

            // Add new subscriptions
            for (let i = this._subscriptions.length; i < maxSubscriptions; ++i) {
                // If we have a corresponding cached subscription
                // pull the information from cache and construct
                // the ONSSubscription with data from the cache.
                // If the cached subscription information is out of date,
                // it will be handled inside the ONSSubscription.
                const sub = new ONSSubscription(this._onsContext, parsedCachedSubscriptions[i]);
                this._subscriptions.push(sub);
                sub.on('change', this._onSubscriptionChange);
            }
        } else if (maxSubscriptions < this._subscriptions.length) {
            // Remove subscriptions over the limit
            for (let i = maxSubscriptions; i < this._subscriptions.length; ++i) {
                const sub = this._subscriptions[i];
                sub.pendingONSObjects = new Map();
                sub.off('change', this._onSubscriptionChange);
            }
            this._subscriptions.length = maxSubscriptions; // Removes the overflow from the array.
        }
    }

    private _truncateObjectsIfNeeded(objects: ONSObjectMap): ONSObjectMap {
        const maxObjects = this._maxObjectsPerSubscription * this._subscriptions.length;
        if (objects.size > maxObjects) {
            this.logWarn(`Max objects (${maxObjects} exceeded, removing ${objects.size - maxObjects} objects`);

            // Prioritize PLS lists and Folders over individual Assets
            const getPriority = (obj: ONSObjectProperties): number => {
                if (obj.type === 'assetList') { return 0; }
                if (obj.type === 'asset' && obj.directoryLevel === 'shallow') { return 1; }
                return 3;
            };

            return new Map([ ...objects.entries() ]
                .sort(([ _id1, obj1 ], [ _id2, obj2 ]) => {
                    return getPriority(obj1) - getPriority(obj2);
                })
                .slice(0, maxObjects));
        }
        return objects;
    }

    async watch(objects: ONSObjectMap) {
        await this._ensureSubscriptions();
        this._watchedObjects = this._truncateObjectsIfNeeded(objects);

        // Update subscriptions' pending objects, replacing existing objects with updated config.
        const handledObjectIds = new Set<string>();
        const subscriptionToOnsObjects: Map<string, ONSObjectProperties>[] = this._subscriptions.map(
            sub => {
                const onsObjects = new Map<string, ONSObjectProperties>();
                sub.pendingONSObjects.forEach((_properties, id) => {
                    if (this._watchedObjects.has(id) && handledObjectIds.add(id)) {
                        onsObjects.set(id, this._watchedObjects.get(id)!);
                    }
                });
                return onsObjects;
            }
        );

        // Fill up subscriptions, optimizing for minimal number of subscriptions
        let nextIndex = 0;
        this._watchedObjects.forEach((obj, id) => {
            if (handledObjectIds.has(id)) {return;}
            // find a subscription with space
            while (subscriptionToOnsObjects[nextIndex].size >= this._maxObjectsPerSubscription) {
                nextIndex++;
            }
            subscriptionToOnsObjects[nextIndex].set(id, obj);
        });

        this._subscriptions.forEach((sub, index) => {
            // Note: this setter triggers updating subscription in the cloud
            sub.pendingONSObjects = subscriptionToOnsObjects[index];

            if (sub.pendingONSObjects.size > 0) {
                this.logDebug(
                    `Subscription #${index} (${sub.subscriptionId}) now has ${sub.pendingONSObjects.size} items.`
                );
            }
        });
    }

    /**
     * Logs a debug message.
     * @param message - Message to log.
     * @param optionalParams - Optional objects to stringify and log after the message.
     */
    logDebug(message: string, ...optionalParams: any[]) {
        this._onsContext.logger.logDebug(message, 'Axon', ...optionalParams);
    }

    /**
     * Logs an info message.
     * @param message - Message to log.
     * @param optionalParams - Optional objects to stringify and log after the message.
     */
    logInfo(message: string, ...optionalParams: any[]) {
        this._onsContext.logger.logInfo(message, 'Axon', ...optionalParams);
    }

    /**
     * Logs a warning message.
     * @param message - Message to log.
     * @param optionalParams - Optional objects to stringify and log after the message.
     */
    logWarn(message: string, ...optionalParams: any[]) {
        this._onsContext.logger.logWarn(message, 'Axon', ...optionalParams);
    }

    /**
     * Logs an error message.
     * @param message - Message to log.
     * @param optionalParams - Optional objects to stringify and log after the message.
     * @remarks If the first optional parameter is an Error object, the message will be appended with the error message.
     */
    logError(message: string, ...optionalParams: any[]) {
        this._onsContext.logger.logError(message, 'Axon', ...optionalParams);
    }

}
