import type { IImplicitFilter } from '../core/ItemFilter';
import type { default as AdobeAsset } from './AdobeAsset';
import { EXPRESS_ARTIFACT_TYPE } from '../utils/excludeExpressArtifacts';

export interface IImplicitAdobeAssetFilterBaseOptions {
    readonly _includeHiddenRecursive?: boolean;
    readonly _isDiscarded?: boolean;
    readonly _isPublished?: boolean;
    readonly _isSharedWithYou?: boolean;
}

/**
 * Class for handling common filtering for AdobeAsset ItemSources. All implicit filters for AdobeAsset
 * should extend this class.
 */

export default abstract class ImplicitAdobeAssetFilterBase implements IImplicitFilter<AdobeAsset> {
    private _isDiscarded: boolean = false;
    private _isPublished: boolean = false;
    private _isSharedWithYou: boolean = false;
    private _includeHiddenRecursive: boolean = false;

    constructor(options?: Partial<IImplicitAdobeAssetFilterBaseOptions>) {
        this._includeHiddenRecursive = !!(options?._includeHiddenRecursive);
        this._isDiscarded = !!(options?._isDiscarded);
        this._isPublished = !!(options?._isPublished);
        this._isSharedWithYou = !!(options?._isSharedWithYou);
    }

    matches(item: AdobeAsset): boolean {
        // If a Composite has zero size, it's probably an intermediate that is pending content, so
        // it should not be visible until the content is available. Client apps are responsible for cleaning
        // up Composites that never get content. There are two exceptions:
        //   1. New Libraries always have correct size from Melville, but sometimes the first ONS notification
        //      does not reflect the Library contents being written yet.
        //   2. Items populated by ACPL shouldn't be filtered out, because they're likely just in the process of uploading.
        // In both cases, we don't want the item to flicker in and out while it settles.
        if (item.isCompositePlaceholder && !item.isLibrary && !item.localID) {
            return false;
        }

        if (item.isDiscarded !== this._isDiscarded) {
            return false;
        }

        if ((item._isSWYAsset_NoLazyLoad) && item._isSWYAsset_NoLazyLoad !== this._isSharedWithYou) {
            return false;
        }

        // Do not include children of directly discarded Assets in isDiscarded
        if (this._isDiscarded && item['_assetState'] === 'DISCARDED_PARENT') {
            return false;
        }

        if (item.isPublished !== this._isPublished) {
            return false;
        }

        // ONS subscriptions may cause loading of /cloud-content-archive or /archive when monitoring discardSource list
        // items but these folders should never appear in any list.
        if (item.repoPath === '/cloud-content-archive' || item.repoPath === '/archive') {
            return false;
        }

        // SAMJS-773 Exclude Express artifacts by default. This will likely be temporary.
        if (item.reviewLinkSourceType === EXPRESS_ARTIFACT_TYPE) {
            return false;
        }

        // For all sources of AdobeAsset, the shellVisibility field dictates whether it can be seen in UI,
        // except for when items in hidden folders (hiddenRecursive) must be included.
        return !((item.shellVisibility === 'hiddenSelf' || (item.shellVisibility === 'hiddenRecursive' && !this._includeHiddenRecursive)));
    }
}
