import type { ISAMCorePrivate } from '../indexPrivate';
import type AdobeAsset from './AdobeAsset';
import type { IResourceOptions } from './Resource';
import Resource from './Resource';

/**
 * A Resource for a specific AdobeAsset, which only revalidates requests if ONS is inactive.
 * The resource's associated asset may be set after initialization.
 */
export default class AdobeAssetResource<T> extends Resource<T> {

    constructor(
        readonly _core: ISAMCorePrivate,
        protected _parent?: AdobeAsset,
        options: IResourceOptions<T> = {},
    ) {
        super(_core, {
            ...options,
            // If ONS is active and this resource is attached to a parent asset,
            // we can skip revalidation because ONS will notify us of any changes.
            // Any assets in the pool should either be monitored directly with ONS
            // or through the watch on their parent directory.
            skipRevalidation: () => Boolean(this._parent && this._core.hostAssetContext.onsContext?.isActive),
        });

        this._parent = _parent;
    }

    /** Set the parent asset for this resource. */
    setParent(parentAsset: AdobeAsset) {
        this._parent = parentAsset;
    }
}
