import ItemBase from '../core/ItemBase';
import PropertyUpdater from '../core/PropertyUpdater';
import ItemUpdater from '../core/ItemUpdater';

import type { CollaboratorRole, InheritanceType } from './Collaborator';
import { CollaboratorRoles, InheritanceTypes, RebacRoles } from './Collaborator';
import type { RebacRole } from '../interface/InvitationModel';
import type { IInvitation } from '../interface/InvitationModel';

export default class InvitedCollaborator extends ItemBase {

    private _email: string = '';
    private _role: CollaboratorRole = 'viewer';
    private _rebacRole?: RebacRole;
    private _canComment: boolean = false;
    private _canShare: boolean = false;
    private _acceptanceRequired: boolean = false;
    private _inheritance?: InheritanceType;
    private _created: Date = new Date;
    private _modified: Date = new Date;

    get invitationID(): string {
        return this.id;
    }

    // Invited email
    get email(): string {
        return this._email;
    }

    get role(): CollaboratorRole {
        return this._role;
    }

    get rebacRole(): RebacRole | undefined {
        return this._rebacRole;
    }

    get canComment(): boolean {
        return this._canComment;
    }

    get canShare(): boolean {
        return this._canShare;
    }

    get acceptanceRequired(): boolean {
        return this._acceptanceRequired;
    }

    get inheritance(): InheritanceType | undefined {
        return this._inheritance;
    }

    get created(): Date {
        return this._created;
    }

    /**
     * The timestamp when this invitation was last modified.
     * This can be used to track changes to invitation permissions or status.
     */
    get modified(): Date {
        return this._modified;
    }
}

export const InvitedCollaboratorUpdater = new ItemUpdater<InvitedCollaborator, Partial<IInvitation>>({
    localItemType: InvitedCollaborator,
    remoteIdProperty: 'id',
    propertyUpdater: new PropertyUpdater({
        '_email': 'email',
        '_role': { name: 'role', choices: CollaboratorRoles },
        '_rebacRole': { name: 'rebacRole', choices: RebacRoles },
        '_canComment': { name: 'canComment', format: 'boolean' },
        '_canShare': { name: 'canShare', format: 'boolean' },
        '_acceptanceRequired': { name: 'acceptanceRequired', format: 'boolean' },
        '_inheritance': { name: 'inheritance', choices: InheritanceTypes },
        '_created': { name: 'created', format: 'date_as_number' },
        '_modified': { name: 'modified', format: 'date_as_number' }
    })
});
