import type { SAM } from '@ccx-public/component-types';
import type ItemPool from '../core/ItemPool';
import type Library from './Library';
import { LibraryUpdater } from './Library';
import LibraryInterface  from '../interface/LibraryInterface';
import type { CreateLibraryOptions, CreatePersonalLibraryData, LibrarySelectors, BookmarkData } from '../interface/LibraryModel';
import { LibraryOwnerFilter } from '../interface/LibraryModel';
import type AdobeAsset from '../assets/AdobeAsset';
import { validatePlatformRepoName } from '../assets/AssetUtils';
import type { ISAMCorePrivate, ISAMObject } from '../indexPrivate';
import type { LibraryConfig, LibrarySource } from './LibrarySource';
import { memoize } from '../core/decorators';
import { keepAlive } from '../core/decorators/KeepAliveManager';
import ItemSource from '../core/ItemSource';
import ImplicitLibraryFilter from './ImplicitLibraryFilter';
import LibraryListLoader from './LibraryListLoader';
import { SAMError, SAMErrorCode } from '../core/SAMError';
import type { LibrarySearchSource } from './LibrarySearchSource';
import LibrarySearchLoader from './LibrarySearchLoader';
import ImplicitLibrarySearchFilter from './ImplicitLibrarySearchFilter';
import type { SubscriptionLocation } from './SubscriptionLocation';
import { SyncGroupLocation, PublicBookmarkLocation, CollabBookmarkLocation } from './SubscriptionLocation';
import type { IOrderDirection } from '../core/ItemOrder';
import { default as LibraryFilter, type  LibraryFilterOptions } from './LibraryFilter';
import { default as LibraryOrder, type  LibraryOrderField } from './LibraryOrder';
import { Env } from '../core/Environment';
import type ICCLibraries from '../library-contents/index';

/**
 * Provides all Library related functionality like getting
 * lists of libraries among other features.
 *
 * @experimental This API is in an experimental phase so expect that
 * APIs will not be final and there will be breaking changes
 * without bumping the major version until this comment is removed.
 */
export default class LibraryContext implements ISAMObject, SAM.LibraryContext {
    private _ccLibraries: ICCLibraries | undefined;
    constructor(
        readonly _core: ISAMCorePrivate,
        private __assetPool: ItemPool<Library | AdobeAsset>
    ) { }

    /**
     * @package -- only for use in SAM.js
     */
    readonly _libraryUpdater = LibraryUpdater;
    /**
     * @package -- only for use in SAM.js
     */
    readonly _libraryInterface: LibraryInterface = new LibraryInterface(this._core);
    /**
     * @package -- only for use in SAM.js
     */
    public _syncGroupLocation: SubscriptionLocation = new SyncGroupLocation();
    /**
     * @package -- only for use in SAM.js
     */
    public _publicBookmarkLocation: SubscriptionLocation = new PublicBookmarkLocation();
    /**
     * @package -- only for use in SAM.js
     */
    public _collabBookmarkLocation: SubscriptionLocation = new CollabBookmarkLocation();
    /**
     * @package -- for use in SAM.js only
     */
    get _assetPool(): ItemPool<Library | AdobeAsset> {
        return this.__assetPool;
    }

    /**
     * Returns the LibrarySource which will return a list of the user's libraries.
     * To request a different set of libraries, create a new LibraryFilter and pass it to the getList method.
     * @example
     * const libraryContext = await core.getLibraryContext();
     * const order = new LibraryOrder('ascending', 'modified');
     * const filter = LibraryFilter.AllLibraries; // If no filter is provided, will default to all of the user's libraries.
     * const libraryList = libraryContext.librariesSource.getList(order, filter, loadOptions);
     * libraryList.on(STATE_CHANGED, () => {
     *     if (libraryList.status !== AssetListStatus.Loading) { const libraries = libraryList.items; }
     * });
     * Note: loadOptions.limit will be ignored on public libraries, which are not currently paginated.
     */
    @memoize
    get librariesSource(): LibrarySource {
        const loader = new LibraryListLoader<LibraryConfig>(
            this._assetPool,
            this._libraryInterface,
            this._libraryUpdater,
            this._core
        );
        this._ensureSubscriptionLocationExistence()      // start listening for changes to subscription locations
            .then(() => {
                this._publicBookmarkLocation.on('change', this._onPublicBookmarksChanged.bind(this));
                this._collabBookmarkLocation.on('change', this._onCollabBookmarksChanged.bind(this));
            })
            .catch(error => {
                this._core._environment.error(`Error ensuring subscription location existence: ${error}`);
            });

        return new ItemSource<LibraryConfig>(this._assetPool as ItemPool<Library>, [ loader ], new ImplicitLibraryFilter());
    }

    private _onPublicBookmarksChanged() {
        for (const list of this.librariesSource._getLists()) {
            if (list.filter._owner?.has(LibraryOwnerFilter.Public)) {
                list.refresh();
            }
        }
    }

    private _onCollabBookmarksChanged() {
        for (const list of this.librariesSource._getLists()) {
            // Note: If LibraryOwnerFilter.Other is ever enabled, it should be included in this check.
            if (list.filter._owner?.has(LibraryOwnerFilter.Incoming)) {
                list.refresh();
            }
        }
    }

    /**
     * @package -- for use in SAM.js only
     */
    async _createLibrary(options: CreateLibraryOptions): Promise<Library> {
        if (!validatePlatformRepoName(options.name)) {
            // Validate the name here to avoid resolving the asset if the name is invalid.
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Invalid name provided for the createLibrary operation.');
        }

        const libraryData = await this._libraryInterface.createLibrary(options);
        const session = this._assetPool.createMutationSession<Library>();
        const library = this._libraryUpdater.updateRemoteItem(session, libraryData);
        library._setLibraryLoadState('LOADED');
        session.commit();
        return library;
    }

    /**
     * Provides the source to search for Libraries by a full or partial name.
     *
     * @param {string} query The full or partial Library name to search for.
     * @returns {LibrarySearchSource} The source on which getList() is called to get the list of libraries that match the query.
     * @example
     * const libraryContext = await core.getLibraryContext();
     * const librarySource = libraryContext.getLibrarySearchSource('full-or-partial-library-name');
     * const libraryList = librarySource.getList(LibraryOrder.default);
     */
    getLibrarySearchSource(query: string): LibrarySearchSource {
        const implicitFilter = new ImplicitLibrarySearchFilter({ query });
        const loader = new LibrarySearchLoader(
            this._assetPool,
            this._libraryInterface,
            this._libraryUpdater
        );
        return new ItemSource(this._assetPool as ItemPool<Library>, [ loader ], implicitFilter);
    }

    /**
     * Creates a personal library.
     *
     * @example
     * const libraryContext = await core.getLibraryContext();
     * const roles: LibraryRole[] = [{
     *      type: 'brand',
     *      usage: 'usage_brand',
     *      priority: 'priority_brand'
     * }];
     * const library = libraryContext.createLibrary({ name: 'test', roles });
     *
     */
    @keepAlive
    async createPersonalLibrary(data: CreatePersonalLibraryData): Promise<Library> {
        const options = { syncCreate: true, name: data.name, roles: data.roles };

        return this._createLibrary(options);
    }

    private async _getLibraryLocally(assetId: string): Promise<Library | undefined> {
        // Locate the library in the local pool
        const library = this._assetPool.getLocalItemById(assetId) as Library | undefined;
        if (!library) {
            // Library not found locally.
            return undefined;
        }

        // This will go to Melville only if the library is not fully loaded.
        await library._waitForLibraryLoad();
        return library;
    }

    /**
     * @package -- for use in SAM.js only
     */
    async _getLibraryRemotely(assetId: string, options?: { selectors?: LibrarySelectors[] }): Promise<Library | undefined> {
        // Load the library from Melville. There will be a network call here.
        const libraryData = await this._libraryInterface.getLibraryData(assetId, options);
        if (!libraryData) {
            return undefined;
        }

        const session = this._assetPool.createMutationSession<Library>();
        const updatedLibrary = this._libraryUpdater.updateRemoteItem(session, libraryData);
        session.commit();

        return updatedLibrary;
    }

    private _isValidURN(id: string): boolean {
        const urnRegex = /^urn:[a-zA-Z0-9][a-zA-Z0-9-]{0,31}:[a-zA-Z0-9()+,\-.:=@;$_!*'%/?#]+$/;
        return urnRegex.test(id);
    }

    // assetId can be LibraryAssetId or, currently, PublicLibraryId.
    // TODO: Once [CCXB-21655] is complete, this will support assetIDs for public libraries.
    // At that point, we can remove tryRemoteOnly.
    // TODO: This should actually be named getLibraryByID() per https://wiki.corp.adobe.com/display/ACPCSDK/SAM+and+CC+Libraries+Strategic+Direction
    @keepAlive
    async getLibraryByAssetId(assetId: string): Promise<Library> {
        const tryLocalThenRemote = async (id: string) => {
            let library = await this._getLibraryLocally(id);
            if (!library) {
                library = await this._getLibraryRemotely(id);
            }
            return library;
        };

        const tryRemoteOnly = async (id: string) => {
            return await this._getLibraryRemotely(id);
        };

        // For private libraries, we first try to get the library locally and then remotely using the asset id.
        // For public libraries, we only try to get the libraries remotely using the public library id.
        const library = this._isValidURN(assetId)
            ? await tryLocalThenRemote(assetId)
            : await tryRemoteOnly(assetId);

        if (!library) {
            throw SAMError.create(SAMErrorCode.NOT_FOUND, `Library not found for the given ID: ${assetId}`);
        }

        return library;
    }

    /**
     * Bookmarks multiple libraries in a single operation.
     * Both public and shared libraries are supported.
     * If a library has been previously bookmarked, it will be re-bookmarked with an updated timestamp.
     *
     * @param libraries: Library[] - Array of libraries to bookmark
     * @returns Promise<void> - resolves when all libraries are bookmarked
     *
     * @example
     * const libraryContext = await core.getLibraryContext();
     * const librariesToBookmark = [library1, library2, library3];
     * await libraryContext.bookmarkLibraries(librariesToBookmark);
     *
     */
    async bookmarkLibraries(libraries: Library[]): Promise<void> {

        if (!libraries || libraries.length === 0) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'No libraries provided to bookmark.');
        }

        // Build bookmark request payload
        const bookmarkData: Partial<BookmarkData>[] = libraries.map(library => ({
            id: library.libraryManifestId,
            type: 'collab',
            urn: library.cloudID
        }));

        const response = await this._libraryInterface.bookmarkLibraries(bookmarkData);

        // Melville will return all bookmarks in the response, including bookmarks previously created
        const bookmarksCreated = new Map<string, BookmarkData>();
        for (const bookmark of response.bookmarks) {
            bookmarksCreated.set(bookmark.id, bookmark);
        }

        const session = this._assetPool.createUpdateSession<Library>('bookmark libraries');

        // Update the local Library items for libraries that were in the request
        for (const library of libraries) {
            const bookmark = bookmarksCreated.get(library.libraryManifestId!);
            if (bookmark) {
                this._libraryUpdater.updateLocalItem(session, library, { bookmark });
            }
        }

        session.commit();
    }

    /**
     * should be called once the client is interested in libraries listing
     * @package -- for use in SAM.js only
     * @returns Promise<void> - resolves when the special library locations are ensured to exist
     */
    async _ensureSubscriptionLocationExistence(): Promise<void> {
        const assetContext = await this._core.getAssetContext();
        return Promise.allSettled([
            this._syncGroupLocation.ensureExistence(assetContext, this._libraryInterface),
            this._publicBookmarkLocation.ensureExistence(assetContext, this._libraryInterface),
            this._collabBookmarkLocation.ensureExistence(assetContext, this._libraryInterface)
        ]).then(results => {
            results.forEach(result => {
                if (result.status === 'rejected') {
                    throw result.reason;
                }
            });
            return;
        });
    }

    /**
     * @experimental
     */
    getLibraryOrder(direction: IOrderDirection = 'descending', field: LibraryOrderField = 'modified'): LibraryOrder {
        return new LibraryOrder(direction, field);
    }

    /**
     * @experimental
     */
    getLibraryFilter(options?: Partial<LibraryFilterOptions | undefined>): LibraryFilter {
        return new LibraryFilter(options);
    }

    /**
     * Called to obtain the CCLibraries instance.
     * @package -- for use in SAM.js only
     * @returns Promise<CCLibraries> - resolves with the CCLibraries instance.
     */
    async _getLibrariesModule(): Promise<ICCLibraries> {
        if (!this._ccLibraries) {
            // TODO: Switch to using a common component config per [ACPCSDK-3]
            try {
                const { default: CCLibraries, CloudDriver } = await import('../library-contents/index');
                const token = this._core._environment.getValue('ACCESS_TOKEN');
                const env = (this._core._environment.getValue('ENVIRONMENT') === Env.Production) ? 'production' : 'staging';
                const cloudDriver = new CloudDriver(this._core, async () => ({  env, token, options: {} }));
                await cloudDriver.init();
                const initializationOptions = { disableLocalFallthrough: true, skipConnectingOnInit: false, disablePreemptiveLibraryLoad: true };
                this._ccLibraries = new CCLibraries(this._core, this._assetPool, cloudDriver, initializationOptions);
            } catch (error) {
                this._core._environment.error(`Error loading CCLibraries module: ${error}`);
                throw error;
            }
        }
        return this._ccLibraries;
    }

    /**
     * Called to obtain the CCLibraries instance.
     * @package -- for use in SAM.js only
     * Use from within the CCLibraries Module code, where we know the instance is already available.
     */
    _getLibrariesModule_NoLoad(): ICCLibraries | undefined {
        return this._ccLibraries;
    }
}
