// Top-level application metadata fields that should be embedded in all R-API and USS listings
export const AppMetadataField = {
    SHELL_VISIBILITY: 'shell:visibility',       // for filtering out hidden files client-side
    CC_INHERITED: 'cc:inherited',               // project and workspace children
    REVIEW_SOURCE_ASSET: 'review:sourceAsset',  // artifact source info
    CONVERTED_TO: 'convertedTo',                // Project X (temporary support for legacy files)
    NON_AUTO_MIGRATABLE: 'ccx:nonAutoMigratableCopiedFromId',  // Project X (temporary support for legacy files)
    COPIED_IN_LEGACY_SPARK_TO: 'ccx:copiedLegacySparkId', // Project X (temporary support for legacy files)
    CC_INHERITABLE: 'cc:inheritable',            // specfic to projects and workspaces
    PROJECT_RENDITION: 'project:rendition',      // required for Projects showing up in USS listings,
    FIREFLY: 'firefly'                           // Firefly boards
} as const;

const RapiAppMetadataWildcardNamespaces = {
    CC: 'cc',
    CLASSROOM_ASSIGNMENTS: 'assignment',
    CCX: 'ccx',
    HZ: 'hz'
};

// This should be fix once https://jira.corp.adobe.com/browse/SEARCH-45142 is done
const NewFormatAppMetadataField = {
    HZ_DOCUMENT_METADATA: 'hz:documentMetadata',  // Express metadata
    CC_CREATED_FROM_UPLOAD: 'cc:createdFromUpload'
};

// The following fields must be escaped as-is to get all fields in the namespace
// See: https://wiki.corp.adobe.com/pages/viewpage.action?spaceKey=CA&title=Proposal%3A+Enhanced+Filtering+and+Embedding+Support+for+JSON+Resources#Proposal:EnhancedFilteringandEmbeddingSupportforJSONResources-Selectors
// eslint-disable-next-line no-useless-escape
const AppMetadataNamespacesRapiFormat = Object.values(RapiAppMetadataWildcardNamespaces).map((element) => `\"${element}:\"*`);

// Rapi and USS have different formats for these core AppMetadataFields
const EmbedAppMetadataFieldsRapiFormat = (Object.values(AppMetadataField) as string[])
    .concat(Object.values(NewFormatAppMetadataField))
    .filter((element) => {
        // Filter out all single field selectors that will be included by a wildcard selector
        const ns = element.split(':')[0];
        return !Object.values(RapiAppMetadataWildcardNamespaces).includes(ns);
    })
    .map((element) => '"' + element + '"')
    .concat(AppMetadataNamespacesRapiFormat);

const EmbedAppMetadataFieldsUSSFormat = Object.values(AppMetadataField).map((element) => {
    return ('app_metadata$$' + element);
}).concat(Object.values(NewFormatAppMetadataField).map((element) => {
    return ('api:metadata/application$$' + element);
}));

// Unified type for AppMetadataFields regardless of service origin eg. 'app_metadata$$shell:visibility' | '"shell:visibility"' | ...
export type IAppMetadataFieldTypeRapi = typeof EmbedAppMetadataFieldsRapiFormat[number];
export type IAppMetadataFieldTypeUSS = typeof EmbedAppMetadataFieldsUSSFormat[number];
export type IAppMetadataFieldType = IAppMetadataFieldTypeRapi | IAppMetadataFieldTypeUSS;

export function getRapiAppMetadataSelectors(): IAppMetadataFieldTypeRapi[] {
    return EmbedAppMetadataFieldsRapiFormat;
}

// USSFetchFields should be embedded in USS calls only
export const USSFetchField = {
    COLLABORATION_METADATA: 'collaboration_metadata',
    COLLABMETADATA_MINE: 'collab_metadata#mine',
    REPO_CREATED_BY_CLIENT_ID: 'repo:createdByClientId',
    CUSTOM_MODEL_METADATA: 'firefly#ffmodel'
} as const;

const USSFetchFields = Array.from(Object.values(USSFetchField));
export type IUSSFetchFieldType = typeof USSFetchFields[number] | IAppMetadataFieldTypeUSS;


// Include all fields from AppMetadataFields and FetchFields in USS search results.
export function getUSSFetchFields(): IUSSFetchFieldType[] {
    return [ ...EmbedAppMetadataFieldsUSSFormat, ...USSFetchFields ];
}


export type Permission = SAM.Permission;

// eslint-disable-next-line @typescript-eslint/no-redeclare
export const Permission = SAM.Permission;

// All permissions except Ack
export const PERMISSION_ALL = Object.entries(SAM.Permission).reduce(
    // Note: the keys that are the reverse-lookup entries for the values get accumulated, while the keys that are
    //           the enum keys do not, because `n | NaN` returns `n`.
    (acc, [ key ]) => (key === Permission.Ack.toString(10)) ? acc : acc | parseInt(key, 10),
    Permission.None
);


