export function parseEffectivePermissions(permissions: IEffectivePermissions): Permission {
    // https://git.corp.adobe.com/pages/caf/api-spec/chapters/concepts/access.html#privileges

    // Each permission type should look for its relevant key first, then fall back to "*" entry.
    const primary = permissions[RelType.PRIMARY] || permissions['*'] || [];       // permissions directly on this obj
    const policy = permissions[RelType.AC_POLICY] || permissions['*'] || [];      // contains "share" permission
    const directory = permissions[RelType.DIRECTORY] || permissions['*'] || [];   // parent folder's permissions
    const appMetadata = permissions[RelType.APP_METADATA] || permissions['*'] || []; // application metadata's permissions
    const annotations = permissions[RelType.ANNOTATIONS] || permissions['*'] || [];   // contains commenting permissions

    let mask = Permission.None;
    primary.forEach((perm: PermissionType) => {
        switch (perm) {
        case 'ack':
            mask |= Permission.Ack;
            break;
        case 'read':
            mask |= Permission.Read;
            if (directory.includes('write')) {
                // Can duplicate this file in its current directory
                mask |= Permission.Duplicate;
            }
            break;
        case 'write':
            // Clients need 'write' permission to edit the contents of a file, and they
            // need 'write' permission on the parent folder to rename, discard, or restore
            mask |= Permission.Write;
            if (directory.includes('write')) {
                mask |= Permission.Discard;
                mask |= Permission.Restore;
            }
            break;
        case 'delete':
            // Clients need Delete permission on the asset and Write permission on the
            // parent directory in order to delete an asset.
            if (directory.includes('write')) {
                mask |= Permission.Delete;
            }
            break;
        }
    });

    // synthetic permission
    if (policy.includes('write')) {
        mask |= Permission.Share;
    }

    // appmetadata permission
    if (appMetadata.includes('read')) {
        mask |= Permission.ReadAppMetadata;
    }

    if (annotations.includes('write')) {
        mask |= Permission.WriteComment;
    }

    if (directory.includes('write') && primary.includes('read') && primary.includes('write')) {
        mask |= Permission.Rename;      // Rename requires read and write permissions on primary and write permission on the parent directory
        if (primary.includes('delete')) {
            mask |= Permission.Move;    // Move requires read, write and delete permissions on primary and write permission on the parent directory
        }
    }

    return mask;
}

// NOTE: this isn't what Projects UI expects from XDCE service, but this is what it returns.
export interface IXDCEDocument {
    id: string;
    name: string;
    thumbnail: {
        assetID: string;
        format: string;
        scale: string;
        url: string;
    };
    publisher: {
        displayName: string;
    };
    artboardcount: number;
    artboards: {
        id: string;
        name: string;
        // A url like https://xdce-stage.adobe.io/v2/document/{urn}/artboard/{guid}?version=0
        resourceAPI: string;
        thumbnail: {
            assetID: string;
            format: string;
            scale: string;
            // A url like https://cdn-sharing-stage.adobecc.com/content/storage/id/{urn};revision=0?component_id={guid}&access_token={token}&api_key={key}
            url: string;
        };
        bounds: {
            x: number;
            y: number;
            width: number;
            height: number;
        };
        viewportBounds: {
            height: number;
        };
        triggers: any[];
        parent: {
            // A url like "https://xdce-stage.adobe.io/v2/document/{urn}?version=0"
            resourceAPI: string;
        }
    }[];
    homeArtboardId: string;
    version: {
        version: string;
        // A url like https://xdce-stage.adobe.io/v2/document/{urn}?version=0
        resourceAPI: string;
    };
    history: {
        version: string;
        // A url like https://xdce-stage.adobe.io/v2/document/{urn}?version=0
        resourceAPI: string;
    }[];
    assetID: string;
    includesDevelopmentData: boolean;
}

