// We wanted to make sure that the clients have a consistent way to get the listing data, so this mimics
// ItemSource.getList()
export type AssetListingHints = {
    /**
     * some fields like orderField.shared will be disregarded for now as they are not supported in the supergraph.
     */
    order: AdobeAssetOrder;
    /**
     * some fields like excludeMediaTypes will be disregarded for now as they are not supported in the supergraph.
     */
    filter?: AdobeAssetFilter;
    /**
     * only loadOptions.limit will be used for now.
     */
    loadOptions?: ILoadOptions;

    /**
     * BELOW FIELDS ARE IGNORED FOR CLIENTS RIGHT NOW.
     * They are used internally by SAM.js to optimize the query.
     */

    /**
     * effective permissions for the children.
     * we can set it to false internally in SAM.js for user storage folders where we know that user has all permissions.
     */
    effectivePermissions?: boolean;
};

/**
 * @experimental
 */
export type AssetLoadHints = {
    listingHints?: AssetListingHints[];

    /**
     * BELOW FIELDS ARE IGNORED FOR CLIENTS RIGHT NOW.
     * They are used internally by SAM.js to optimize the query.
     */

    /**
     * shell:visibilty will be part of repoMetadata. There is a proposal for it: https://jira.corp.adobe.com/browse/CA-1396.
     * isChildOfProject? Perhaps we can evaluate it from the asset repo:path?
     * undefined means load all the appMetadata fields that SAM.js requires eagerly for now (i.e. shell:visibility).
     * false means load no appMetadata fields in the query.
     * at least we can set it to false internally in SAM.js for top level folders.
     */
    appMetadata?: string[] | false;

    /**
     * we will just make effective permissions be deferred for now.
     * false means don't load the effective permissions in this query. They can be lazily loaded later by the clients. undefined is equal to false.
     * true means load the effective permissions deferred.
     * we can set it to false internally in SAM.js for user storage folders where we know that user has all permissions.
     */
    effectivePermissions?: boolean;

    /**
     * false means we don't load the per user specific metadata for this asset. Clients can lazily load it later. undefined is equal to false.
     * true means load the per user specific metadata deferred.
     * we can set it to false internally in SAM.js for top level folders where we know there won't be any per user specific metadata.
     */
    perUserMetadata?: boolean;
};
