import InterfaceBase from './InterfaceBase';
import { cache, key } from '../core/decorators';
import type {
    IServiceLink,
    LinkRequirements,
    HeaderMap } from './LinkUtils';
import {
    RelType,
    validateLinks,
    getURLFromLinks,
    JSON_MIME_TYPE
} from './LinkUtils';
import type AdobeAsset from '../assets/AdobeAsset';
import type { Either } from '../utils/either';

export type AssetReviewServiceData = {
    hasArtifacts: boolean;
}

const REVIEW_SERVICE_LINKS: LinkRequirements = {
    [RelType.REVIEW_SERVICE_PROVISION]: [
        'documentId',
        'assetRegion',
        'repositoryId'
    ],
    [RelType.REVIEW_SERVICE_DISCARD]: [ 'assetId', 'assetRegion', 'repositoryId' ],
    [RelType.REVIEW_SERVICE_OUTPUTS]: [
        'assetId',
        'assetRegion',
        'documentId',
        'embed',
        'limit',
        'orderBy',
        'outputType',
        'repositoryId',
        'start'
    ],
    [RelType.REVIEW_SERIVCE_HAS_OUTPUTS]: [ 'assetRegion' ]
};

interface IReviewServiceIndexLinks {
    [RelType.REVIEW_SERIVCE_HAS_OUTPUTS]: IServiceLink,
    [RelType.REVIEW_SERVICE_DISCARD]: IServiceLink,
    [RelType.REVIEW_SERVICE_OUTPUTS]: IServiceLink,
    [RelType.REVIEW_SERVICE_PROVISION]: IServiceLink
}

interface IReviewServiceIndexResponse {
    _links: IReviewServiceIndexLinks
}

export interface IReviewServiceAssetIdentifer {
    ['repo:assetId']: string;
    ['repo:repositoryId']: string;
}

export const mapAssetsToAssetIndentifier = function (assets: AdobeAsset[]): IReviewServiceAssetIdentifer[] {
    return assets.map((asset: AdobeAsset) => {
        return {
            'repo:assetId': asset.id,
            'repo:repositoryId': asset.repositoryID
        };
    });
};

function validateReviewServiceLinks(links: any) {
    return validateLinks(links, REVIEW_SERVICE_LINKS);
}

// See https://wiki.corp.adobe.com/pages/viewpage.action?spaceKey=CreativeCloudAssets&title=Proposal+v2%3A+CCARS+Frame+S4R+APIs
//  for schema of a response.
export interface IReviewServiceFrameLinkResponse {
    'repo:assetId': string;         /* a unique identifier for cloud source documents (cloud-id)*/
    'review:documentId': string;    /* a unique identifier for local source documents (xmpDocumentId) */
    'frameio:reviewLinkId': string; /* a Frame.io identifier for a review link */
    'frameio:artifactId': string;   /* a Frame.io identifier for an asset ( file or version_stack ) */
    'frameio:projectId': string;    /* a Frame.io identifier for the project containing the review link */
    'repo:createdDate': number;     /* Date Time when the review link was created */
    'repo:modifiedDate': number;    /* Date Time when the review link was updated */
    'repo:etag': string;            /* etag of the review link stored */
}

//--------------------------------------------------------------------
// Parameters for POST/GET/PUT/DELETE to frameLink endpoint
//
// The source document is either a local document, in which case
// you identify it only with documentId ( the XMP DocumentId ),
// or it's a cloud document, in which case, you provide it's
// cloud-id as assetId, and optionally provide an assetRegion.

type ReviewServiceCloudSource = {
    assetId: string;
    assetRegion?: string;
    repositoryId?: string;
};

type ReviewServiceLocalSource = {
    documentId: string;
};

// AssetReviewServiceInterface.createReviewLink() parameter
export type ReviewServiceCreateReviewLinkParam =  Either<ReviewServiceCloudSource, ReviewServiceLocalSource> & {
    reviewLinkId: string;
    artifactId: string;
    projectId: string;
};

// AssetReviewServiceInterface.getReviewLinks() parameter
export type ReviewServiceGetReviewLinksParam =  Either<ReviewServiceCloudSource, ReviewServiceLocalSource> & {
    reviewLinkId?: string;
};

// AssetReviewServiceInterface.updateReviewLink() parameter
export type ReviewServiceUpdateReviewLinkParam =  Either<ReviewServiceCloudSource, ReviewServiceLocalSource> & {
    reviewLinkId: string;
    artifactId: string;
    projectId: string;
    etag?: string;
};

//--------------------------------------------------------------------

// AssetReviewServiceInterface.deleteReviewLink() parameter
export type ReviewServiceDeleteReviewLinkParam =  Either<ReviewServiceCloudSource, ReviewServiceLocalSource> & {
    reviewLinkId: string;
    etag?: string;
};

//  end parameters for frameLink endpoint
//--------------------------------------------------------------------


export default class AssetReviewServiceInterface extends InterfaceBase {
    public readonly baseURL = `https://${this._core._environment.endpoints.REVIEW_SERVICE_HOST}`;
    public readonly baseEndpoint: string = '/api/v1';
    public readonly indexEndpoint = this.baseEndpoint + '/index';

    public getEndpointURL(endpoint: string): string {
        return `${this.baseURL}${endpoint}`;
    }

    @cache(validateReviewServiceLinks)
    private async _discoverLinks(@key rootHref: string): Promise<IReviewServiceIndexLinks> {
        const response: IReviewServiceIndexResponse = await this._getResponse(rootHref, this._getHeaders());
        return response._links;
    }

    private _getHeaders(contentType?: string): HeaderMap {
        const headers: HeaderMap = {};
        if (contentType) {
            headers['Content-Type'] = contentType;
        }
        return headers;
    }

    async discoverLinks(): Promise<IReviewServiceIndexLinks> {
        return this._discoverLinks(this.getEndpointURL(this.indexEndpoint));
    }

    public async discardOutputsForAsset(assetId: string, assetRegion?: string, repositoryID?: string): Promise<void> {
        const links = await this.discoverLinks();
        const url = getURLFromLinks(
            links,
            RelType.REVIEW_SERVICE_DISCARD,
            {
                assetId,
                ...(assetRegion && { assetRegion }),
                ...(repositoryID && { repositoryID }),
            }
        );
        await this._doPost(url, this._getHeaders(), undefined, [ 204 ]);
    }

    async hasOutputs(assets: IReviewServiceAssetIdentifer[], assetRegion?: string): Promise<IReviewServiceAssetIdentifer[]> {
        const links = await this.discoverLinks();
        const url = getURLFromLinks(
            links,
            RelType.REVIEW_SERIVCE_HAS_OUTPUTS,
            { ...(assetRegion && { assetRegion }) },
        );
        const response = await this._doPost(url, this._getHeaders(JSON_MIME_TYPE), JSON.stringify(assets), [ 200 ]);
        return await response.json();
    }

    private _createFrameLinkUrl(params: any) {
        const url = new URL(`${this.baseURL}/api/v1/frameioLink`);
        Object.entries(params).forEach(([ key, val ]) => url.searchParams.set(key, val as string));
        return url.toString();
    }

    /*
     * See https://wiki.corp.adobe.com/display/CreativeCloudAssets/Proposal+v2%3A+CCARS+Frame+S4R+APIs
     *
     * We use the frameLink endpoint for all four CRUD operations, we just change the method:
     *  POST -> associate a new review with source document
     */
    public async createReviewLink(param: ReviewServiceCreateReviewLinkParam): Promise<IReviewServiceFrameLinkResponse> {
        const { reviewLinkId, artifactId, projectId, ...query } = param;

        const response = await this._doPost(
            this._createFrameLinkUrl(query),
            { 'Content-Type': 'application/json' },
            JSON.stringify({
                reviewLinkId: `${reviewLinkId}`,
                artifactId: `${artifactId}`,
                projectId: `${projectId}`
            })
        );

        return await response.json();
    }

    /*
     * See https://wiki.corp.adobe.com/display/CreativeCloudAssets/Proposal+v2%3A+CCARS+Frame+S4R+APIs
     *
     * We use the frameLink endpoint for all four CRUD operations, we just change the method:
     *  GET -> return array of all reviews associated with source document
     */
    public async getReviewLinks(param: ReviewServiceGetReviewLinksParam): Promise<Array<IReviewServiceFrameLinkResponse>> {
        const response = await this._doGet(
            this._createFrameLinkUrl(param),
        );

        return await response.json();
    }

    /*
     * See https://wiki.corp.adobe.com/display/CreativeCloudAssets/Proposal+v2%3A+CCARS+Frame+S4R+APIs
     *
     * We use the frameLink endpoint for all four CRUD operations, we just change the method:
     *  PUT -> update an existing review associated with source document
     */
    public async updateReviewLink(param: ReviewServiceUpdateReviewLinkParam): Promise<IReviewServiceFrameLinkResponse> {
        const { artifactId, projectId, etag = '*', ...query } = param;

        const response = await this._doPut(
            this._createFrameLinkUrl(query),
            {
                'Content-Type': 'application/json',
                'If-Match': `${etag}`
            },
            JSON.stringify({
                artifactId: `${artifactId}`,
                projectId: `${projectId}`
            })
        );

        return await response.json();
    }

    /*
     * See https://wiki.corp.adobe.com/display/CreativeCloudAssets/Proposal+v2%3A+CCARS+Frame+S4R+APIs
     *
     * We use the frameLink endpoint for all four CRUD operations, we just change the method:
     *  DELETE -> update an existing review associated with source document
     */
    public async deleteReviewLink(param: ReviewServiceDeleteReviewLinkParam): Promise<void> {
        const { etag, ...query } = param;

        let headers: HeaderMap = {};

        if (etag) {
            headers = {
                'If-Match': `${etag}`
            };
        }

        // there is no reponse body to a DELETE returning status 204
        await this._doDelete(
            this._createFrameLinkUrl(query),
            headers,
            [ 204 ]
        );
    }
}
