import type Representation from '../models/Representation';
import type Element from '../models/Element';
// @ts-expect-error R-TODO
import type Library from '../models/Library';
import type { RepresentationData } from '../models/data/RepresentationData';
import type { RenditionTemplateData } from '../models/data/ElementData';
import { canComputeRenditionFromMimeType } from './MimeTypeUtils';
import uriTemplates from 'uri-templates';
import type { RenditionSize } from '../types';
import type { RenditionGrid } from '../models/data/LibraryData';
import { useEdge } from '../drivers/CloudDriver/utils';

export function canComputeRendition(reprensentation: Representation) {
    return canComputeRenditionFromMimeType(reprensentation.type);
}

export function getRenditionCandidate(representations: Array<RepresentationData> = []): RepresentationData {
    let candidate: RepresentationData | undefined;
    let candidateSize = 0;
    for (const representation of representations) {
        const representationSize = representation.isFullSize
            ? Number.POSITIVE_INFINITY
            : Math.max(representation.height || 0, representation.width || 0);
        const replacementCandidate =
            !candidate ||
            (representation.isPreferredThumbnail && !candidate.isPreferredThumbnail) ||
            (representation.relationship === 'primary' && candidate.relationship !== 'primary') ||
            (representation.relationship === 'rendition' &&
                ![ 'primary', 'rendition' ].includes(candidate?.relationship as string)) ||
            (representation.relationship === 'rendition' &&
                candidate.relationship === 'rendition' &&
                representationSize > candidateSize);

        if (replacementCandidate && canComputeRenditionFromMimeType(representation.type)) {
            candidate = representation;
            candidateSize = representationSize;
        }
    }

    return candidate as RepresentationData;
}

export function getRenditionUrl(element: Element, size: RenditionSize = 200): string | undefined {
    // @ts-expect-error TODO-R[SHARED-3961] element.data no longer exists.
    const { renditionUrl = {} as RenditionTemplateData } = element.data;
    const { template, substitutions = {} } =
        typeof renditionUrl === 'string' ? { template: renditionUrl } : renditionUrl;
    if (template) {
        const uriTemplate = uriTemplates(template);
        const populatedUrl = uriTemplate.fill({ ...substitutions, size: `${size}`, type: 'image/png' });

        // Upgrade provided thumbnail url to ACP Edge (switch on http/2)
        const { url } = useEdge(populatedUrl);
        return url;
    }
}

function getRenditionObject(element: Element) {
    // Make the renditions look like a Melville response
    let mapper;
    switch (element.type) {
    case 'application/vnd.adobe.element.color+dcx':
        mapper = (element: Element) => {
            const data = element.representations
                .map(representation => representation.getValue('color', 'data'))
                .find(data => data && data.mode === 'RGB');

            if (!data) {
                return;
            }

            return {
                id: element.elementId,
                type: 'application/vnd.adobe.element.color+dcx',
                rendition: {
                    swatches: [
                        [
                            {
                                alpha: data.alpha,
                                mode: data.mode,
                                type: data.type,
                                value: data.value
                            }
                        ]
                    ]
                }
            };
        };
        break;
    case 'application/vnd.adobe.element.colortheme+dcx':
        mapper = (element: Element) => {
            const representation = element.getPrimaryRepresentation();
            return (
                representation && {
                    id: element.elementId,
                    type: 'application/vnd.adobe.element.colortheme+dcx',
                    rendition: representation.getValue('colortheme', 'data')
                }
            );
        };
        break;
    case 'application/vnd.adobe.element.gradient+dcx':
        mapper = (element: Element) => {
            const representation = element.getPrimaryRepresentation();
            return (
                representation && {
                    id: element.elementId,
                    type: 'application/vnd.adobe.element.gradient+dcx',
                    rendition: representation.getValue('gradient', 'data')
                }
            );
        };
        break;
    default:
        mapper = (element: Element) => {
            let path: any = getRenditionUrl(element); // cloud driver has a remote url
            if (!path) {
                // just hard coding size for now
                path = element.getThumbnailURL(202); // local driver has a localhost url
            }

            if (path) {
                return {
                    id: element.elementId,
                    type: 'href',
                    rendition: path
                };
            }
        };
    }
    return mapper(element);
}

/**
 * Rules:
 *   Main Image:
 *     - first image added to library
 *     - if library has no images, most recently modified of any type in library
 *   Tile Images:
 *      - 3 most recently modified elements of any type
 * @param library
 * @returns {Object} Rendition Grid object
 */
export function getRenditionGrid(library: Library) {
    if (library.elements.length === 0) {
        return undefined;
    }

    // We want the first created, but the most recently modified, so the sort orders are opposite.
    const sortedByModified = [ ...library.elements ].sort((a, b) => b.modified - a.modified);
    const sortedByCreated = [ ...library.elements ].sort((a, b) => a.created - b.created);
    let firstImage = sortedByCreated.find(element => {
        // We only want to display the first Graphic, not just any image
        if (element.type !== 'application/vnd.adobe.element.image+dcx') {
            return;
        }
        const rendition = getRenditionObject(element);
        return rendition && rendition.type === 'href';
    });

    const renditionGrid: RenditionGrid = { gridGenerationEtag: library.etag };

    // Get first image
    if (firstImage) {
        renditionGrid.main = getRenditionObject(firstImage);
    }

    // If there isn't a Graphic element, get first created element of any type
    for (let i = 0; i < sortedByCreated.length && !renditionGrid.main; i++) {
        renditionGrid.main = getRenditionObject(sortedByCreated[i]) || undefined;
        firstImage = renditionGrid.main && sortedByCreated[i];
    }

    // Get tiles
    renditionGrid.tiles = [];
    for (let i = 0; i < sortedByModified.length && renditionGrid.tiles.length < 3; i++) {
        if (sortedByModified[i] === firstImage) {
            continue;
        }

        const renditionObject = getRenditionObject(sortedByModified[i]);
        if (renditionObject) {
            renditionGrid.tiles.push(renditionObject);
        }
    }

    return renditionGrid;
}
