import type LibraryContents from './LibraryContents';
import type SAMLibrary from '../../libraries/Library';

export type ActionName =
    | 'createLibrary'
    | 'removeLibrary'
    | 'permanentlyDeleteLibrary'
    | 'leaveLibrary'
    | 'unfollowLibrary'
    | 'copyLibrary'
    | 'moveLibrary'
    | 'updateLibrary'
    | 'createElement'
    | 'updateElement'
    // updateElementContent is used for setting representations... an operation that is not currently batchable.
    // It would be nice if we could make it batchable some day.
    | 'updateElementContent'
    | 'removeElement'
    | 'restoreElement'
    | 'deleteElement'
    | 'copyElement'
    | 'moveElement'
    | 'createGroup'
    | 'updateGroup'
    | 'removeGroup'
    | 'moveGroup'
    | 'copyGroup'
    // uploadComponent is used for uploading an un-referenced dcx component to a library.
    | 'uploadComponent'
    // A dependent action should block the execution queue, but does nothing.
    | 'dependent';

export type ActionType = 'no-op' | 'insert' | 'update' | 'remove' | 'aggregate';

export type Action = {
    name?: ActionName;
    type: ActionType;
    library?: SAMLibrary;
    libraryContents?: LibraryContents;
    path?: string;
    data?: any;
    baseData?: any;
    flags?: {
        includeElements?: boolean;
        permissionInheritance?: 'read' | 'all';
        lockNewLibraries?: boolean;
        source?: SAMLibrary;
        includeAppMetadata?: boolean;
    };
    actions?: Action[];
    link?: Action;
    originalAction?: Action;
};

export type InsertAction<T> = Action & {
    type: 'insert';
    data: T;
};

export type UpdateAction<T> = Action & {
    type: 'update';
    data: Partial<T>;
    baseData: T;
};

export type RemoveAction = Action & {
    type: 'remove';
    data: void;
    baseData: {
        modifiedDate: string;
    };
};

export type AggregateAction = Action & {
    type: 'aggregate';
    actions: Action[];
};

export function isInsertAction(action: any): action is InsertAction<any> {
    return action.type === 'insert';
}

export function isUpdateAction(action: any): action is UpdateAction<any> {
    return action.type === 'update';
}

export function isRemoveAction(action: any): action is RemoveAction {
    return action.type === 'remove';
}

export function isAggregateAction(action: any): action is AggregateAction {
    return action.type === 'aggregate';
}

export function isAnyRemoveLibraryAction(action: any): action is Action {
    return [ 'removeLibrary', 'unfollowLibrary', 'leaveLibrary', 'permanentlyDeleteLibrary' ].includes(action.name);
}
