// We want to refresh teams only if we didn't get the list in the past 5 minutes.
// This avoids loading teams again during auto-provisioning in case the client
// already fetched the teams.
const TEAM_REFRESH_TIMEOUT = 5 * 60 * 1000;

function createTeamRoleGetter(teams: IItemList<TeamConfig> | ItemList<TeamConfig>) {
    const map = new Set<string>(teams.items.map((team) => team.id));
    return (teamID: string) => map.has(teamID) ? 'MEMBER' : 'NONE';
}

function getLinks<LinkTypes>(item: { _links: LinkTypes }) {
    const links: LinkTypes = item._links;
    if (!links) {
        throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Object has not been loaded correctly, missing "_links" property.');
    }
    return links!;
}

export interface ISpaceUpdate {
    name?: string;
    description?: string;
    color?: string;
}

export interface ITeamUpdate {
    description?: string;
    name?: string;
}

export type IBatchOperationSpaceResult = IBatchOperationResult<Space>;

export default class SpaceContext implements ISAMObject {

    private _orgRepositoryPool = new ItemPool<OrgRepository>(this._core, 'orgRepository');
    private _teamPool = new ItemPool<Team>(this._core, 'team');
    private _spacePool = new ItemPool<Space>(this._core, 'space');

    private _projectInterface = new ProjectInterface(this._core);
    private _rapi = new RepositoryInterface(this._core);
    private _hostAssetContext = this._core.hostAssetContext;

    constructor(readonly _core: ISAMCorePrivate) {
        // Make sure we have a delegate to update all the teamRoles of the spaces once a new team is added.
        this._teamPool.addDelegate(this._teamPoolDelegate, 'context');
    }

    get projectInterface(): ProjectInterface {
        return this._projectInterface;
    }

    get orgRepositoryPool(): ItemPool<OrgRepository> {
        return this._orgRepositoryPool;
    }

    get teamPool(): ItemPool<Team> {
        return this._teamPool;
    }

    get spacePool(): ItemPool<Space> {
        return this._spacePool;
    }

    /**
     * Returns a cached list of links for the project service index route.
     */
    async discoverLinks(): Promise<IWorkspacesIndexLinks> {
        return await this._projectInterface.discoverLinks();
    }

    @memoize
    getOrgRepositories(): OrgRepositorySource {
        const loader = new OrgRepositoryLoader(this._orgRepositoryPool, this._projectInterface);
        return new ItemSource(this._orgRepositoryPool, [ loader ]);
    }

    @memoize
    getTeams(): TeamSource {
        const loader = new TeamLoader(this._teamPool, this._projectInterface);
        return new ItemSource(this._teamPool, [ loader ], new TeamFilter());
    }

    @memoize
    getSpaces(): SpaceSource {
        // Make sure that the space loader checks for team membership during load.
        const loader = new SpaceLoader(this._spacePool, this._projectInterface, this._teamRoleGetterFactory);
        return new ItemSource(this._spacePool, [ loader ], new SpaceFilter());
    }

    private _teamRoleGetterFactory: TeamRoleGetterFactory = async () => {
        const teams = await this._fetchTeams();
        return createTeamRoleGetter(teams);
    };

    private _teamPoolDelegate: IItemPoolDelegate<Team> = {
        onItemsUpdated: () => {
            // Iterate on all the known spaces and update their teamRole based on what we know from the list of Teams.
            // Note that this might update spaces that have been discarded, but that's alright as they might be restored
            // at some point in the future. Since `this.getSpaces().getList()` will trigger fetching the Teams, it is
            // expected that the Team list will typically already be loaded, so it should not use `getTeams().getList()`
            // since that will cause it to fetch the Teams list again. Fetching teams as a side-effect of unit tests that
            // manipulate Teams using the teamPool will unexpectedly cause the teams list to load without any Nock mock
            // to provide it.
            // NOTE: _getExistingList requires an explicit filter, but this Teams list should not be filtered, so it
            // must pass in an EverythingFilter, which is not allowed as an explicit filter in the public interface,
            // so casting to `any` because it should not put EverythingFilter in the public API.
            const teams = this.getTeams()._getExistingList(TeamOrder.default, new EverythingFilter<Team>() as any);
            // Teams List won't exist if manipulating the teamPool without loading the teams first.
            // Teams List will be empty when the TeamLoader converts the service response to Team models via
            // TeamUpdater.updateRemoteItems(), because it triggers ItemPool.onItemsUpdated() before it has actually
            // put the items in the List.
            if (!teams || !teams.items.length) {
                this._core._environment.debug('[SpaceContext._teamPoolDelegate] skipping update of Space.teamRole -- no teams');
                return;
            }
            const spacePool = this._spacePool;
            const getTeamRole = createTeamRoleGetter(teams);
            const spaceSession = spacePool.createUpdateSession('Updating teamRole across all spaces');
            this._spacePool.forEach((space: Space) => {
                const newTeamRole = getTeamRole(space.teamID);
                if (space.teamRole !== newTeamRole) {
                    SpaceUpdater.updateLocalItem(spaceSession, space, { teamRole: newTeamRole });
                }
            });
            spaceSession.commit();
        }
    };

    private async _fetchTeams(): Promise<IItemList<TeamConfig>> {
        // Get the list with refreshTimeOut so that it will not immediately refresh if the list already exists
        const teams = this.getTeams().getList(TeamOrder.default, undefined, { refreshTimeout: TEAM_REFRESH_TIMEOUT });
        await waitForListLoad(teams);
        return teams;
    }

    async provisionType1Team(): Promise<Team | undefined> {
        // Auto-provision a team for CCI user if the user is not currently sponsoring a team.
        if (this._core._environment.getValue('ACCOUNT_TYPE') !== 'type1') {
            return undefined;
        }

        const teams = await this._fetchTeams();

        const userId = this._core._environment.getValue('USER_ID');
        let team = teams.items.find((team: Team) => team.repositoryOwnerID === userId && team.repositoryOwnerType === 'user');
        if (!team) {
            // This should automatically add the team to the lists.
            const response = await this._projectInterface.provisionTeam();

            // The team might be just created, if we are refreshing the list of teams
            // it might not exist yet, so we have to keep it alive until USS is eventually consistent.
            const session = this._teamPool.createMutationSession();
            team = TeamUpdater.updateRemoteItem(session, response);
            session.commit();
        }

        return team;
    }

    async createTeam(orgRepository: OrgRepository, data: IProjectsTeamCreateData): Promise<Team> {
        const response = await this._projectInterface.createTeam({
            ...data,
            repositoryId: orgRepository.repositoryID
        });
        const session = this._teamPool.createMutationSession();
        const team = TeamUpdater.updateRemoteItem(session, response);
        session.commit();
        return team;
    }

    private async _renameAsset(id: string, newName: string): Promise<AdobeAsset> {
        if (!validatePlatformRepoName(newName)) {
            // Validate the name here to avoid resolving the asset if the name is invalid.
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Invalid name provided for the rename operation.');
        }

        // FIXME: `item._links[RelType.PRIMARY]` already has the resolved link for the asset.
        // We could reuse the link to avoid a separate resolve by id call.
        const asset = await this._hostAssetContext.getAssetWithCloudID(id);
        await asset.rename(newName);

        // Return the new name of the asset, just in case the server decided to change it.
        return asset;
    }

    private async _renameTeam(team: Team, update: ITeamUpdate) {
        const name = update.name;
        if (!name) {
            return;
        }

        if (!validatePlatformRepoName(name)) {
            // Validate the name here to avoid resolving the asset if the name is invalid.
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Invalid name provided for the rename operation.');
        }

        const links = getLinks(team);
        await this._projectInterface.renameTeam(links, name);

        // Since the client could have both an instance to a Team
        // and the underlying AdobeAsset we should check that if the
        // AdobeAsset exists in the AssetContext ItemPool and if it does
        // update it and it's descendents as well.
        const adobeAssetPool = this._core._getAssetPool();
        const localAdobeAsset = adobeAssetPool.getLocalItemById(team.id);
        const assetContext = await this._core.getAssetContext();
        if (localAdobeAsset) {
            const newPath = renameFileInPath(name, localAdobeAsset);
            const adobeAssetSession = adobeAssetPool.createUpdateSession();

            updateCachedDescendents({
                assetPool: adobeAssetPool,
                asset: localAdobeAsset,
                session: adobeAssetSession,
                operation: { type: 'rename', newPath },
                assetContext
            });

            this._hostAssetContext._adobeAssetUpdater.updateLocalItem(
                adobeAssetSession,
                localAdobeAsset,
                {
                    'repo:path': newPath,
                    'repo:name': name
                }
            );
            adobeAssetSession.commit();
        }

        const updateSession = this.teamPool.createMutationSession();
        TeamUpdater.updateLocalItem(updateSession, team, { name });
        updateSession.commit();
    }

    async renameTeam(team: Team, newName: string): Promise<void> {
        await this.updateTeam(team, { name: newName });
    }

    async restoreTeam(team: Team): Promise<void> {
        await ItemBase.runExclusiveTask('restore', [ team ], async () => {
            try {
                const links = getLinks(team);
                const updateSession = this.teamPool.createUpdateSession();
                await this._projectInterface.restoreTeam(links);
                TeamUpdater.updateLocalItem(updateSession, team, { state: 'active' });
                updateSession.commit();
            } catch (e) {
                // We want to avoid updating the pool if
                // there are errors like CONFLICT that could occur.
                throw SAMError.create(SAMErrorCode.UNKNOWN,
                    'An error occured restoring team',
                    { underlyingError: e }
                );
            }
        });
    }

    async archiveTeam(team: Team): Promise<void> {
        await ItemBase.runExclusiveTask('archive', [ team ], async () => {
            // TODO: should this be createMutationSession?
            const updateSession = this.teamPool.createUpdateSession();
            try {
                const links = getLinks(team);
                await this._projectInterface.archiveTeam(links);
            } catch (error) {
                const e = error as SAMError;
                // @TODO https://jira.corp.adobe.com/browse/SAM-2064
                // Temporary fallback, remove once M2 APIs are in prod
                if (e.code === SAMErrorCode.BAD_REQUEST) {
                    const asset = await this._hostAssetContext.getAssetWithCloudID(team.id);
                    await asset.discard();
                } else {
                    throw e;
                }
            }
            TeamUpdater.updateLocalItem(updateSession, team, { state: 'discarded' });
            updateSession.commit();
        });
    }

    /**
     * The Projects services accepts only
     * a string value with the length
     * less than or equal to 1000.
     */
    private _validateDescription(value: string) {
        return value.length <= 1000;
    }

    private _validateColor(value: string) {
        return /^#[A-Fa-f0-9]{6}$/.test(value);
    }

    private _getPatchOP(
        value: string,
        path: string,
        existingValue?: string,
        validator?: (value: string) => boolean
    ): jsonpatch.OpPatch {

        if (validator && !validator(value)) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, `Property ${path} has invalid value`);
        }

        // If there was a description and now there
        // is none, we should "remove".
        if (value.length === 0
            && existingValue && existingValue.length > 0) {
            return {
                op: 'remove',
                path
            };
        }

        return {
            op: existingValue ? 'replace' : 'add',
            value,
            path
        };
    }

    private async _patchTeam(team: Team, update: ITeamUpdate): Promise<void> {
        const  { description } = update;
        const bodyData: jsonpatch.OpPatch[] = [];
        const localUpdate: Partial<IProjectsTeam> = {};

        if (description !== undefined) {
            bodyData.push(this._getPatchOP(
                description,
                '/description',
                team.description,
                this._validateDescription
            ));
            localUpdate.description = description;
        }

        if (!bodyData.length) {
            return;
        }

        const links = getLinks(team);
        await this._projectInterface.patchTeam(links, bodyData);

        const updateSession = this.teamPool.createMutationSession();
        TeamUpdater.updateLocalItem(updateSession, team, localUpdate);
        updateSession.commit();
    }

    async updateTeam(team: Team, update: ITeamUpdate): Promise<void> {
        await ItemBase.runExclusiveTask('update', [ team ], async () => {
            const results = await Promise.allSettled([
                this._patchTeam(team, update),
                this._renameTeam(team, update)
            ]);

            // Checks for rejection and calls the handler
            // to delete the item because it has not been
            // found.
            this._checkForRejection(results, () => {
                const session = this.teamPool.createUpdateSession();
                session.queueDiscardedItem(team);
                session.commit();
            });
        });
    }

    async loadTeamProperties(team: Team): Promise<void> {
        const links = getLinks(team);
        const properties = await this._projectInterface.getTeamProperties(links);
        if (!properties || Object.keys(properties).length === 0) {
            return;
        }

        const updateSession = this.teamPool.createMutationSession();
        TeamUpdater.updateLocalItem(updateSession, team, { ...properties });
        updateSession.commit();
    }

    async permanentlyDeleteTeam(team: Team): Promise<void> {
        if (team.state === 'active') {
            throw SAMError.create(
                SAMErrorCode.UNSUPPORTED,
                'Teams that are not \'discarded\' cannot be permanently deleted.'
            );
        }

        const onItemsChanged = (event: ItemsChangedEvent<Team>) => {
            if (event.discardedItems) {
                const permDeleteTeamIDs: ItemId[] = event.discardedItems
                    .filter(item => item.id === team.id)
                    .map(item => item.id);
                if (permDeleteTeamIDs.length) {
                    this._teamPool.removeLocalItems(permDeleteTeamIDs);
                }
            }
        };

        this._teamPool.on(ITEMS_CHANGED, onItemsChanged);
        try {
            await ItemBase.runExclusiveTask('delete', [ team ], async () => {
                const links = getLinks(team);
                await this._projectInterface.permanentlyDeleteTeam(links);
                const updateSession = this.teamPool.createUpdateSession();
                updateSession.queueDiscardedItem(team);
                updateSession.commit();
            });
        } finally {
            this.teamPool.off(ITEMS_CHANGED, onItemsChanged);
        }
    }

    // Reload space is an implementation detail of the space context,
    // external projects should use space.load() instead.
    async [reloadSpace](space: Space): Promise<void> {
        const latency = this._core._environment.getValue('PROJECTS_ITEM_UPDATE_LATENCY');
        await space.waitForMutationPropagationIfNeeded(latency);

        const links = getLinks(space);
        const result = await this._projectInterface.reloadSpace(links, SPACE_FULL_SELECTOR);
        const session = this._spacePool.createUpdateSession();
        SpaceUpdater.updateLocalItem(session, space, result);
        session.commit();
    }

    /**
     * Internal helper method for moving spaces.
     * @param spaces spaces to be moved
     * @param team destination team where spaces are intended to be moved
     * @param assetRenameMap allows renaming of assets in the batch operation
     * @param retryOnConflict whether to retry the move op for failed spaces in case of conflict
     * @param assetConflictMap map to save the newName and count used for all assets in batch
     * @returns the result for batch operation after retrying for failed assets if asked.
     */
    private async _moveSpaces(
        spaces: Space[],
        team: Team,
        assetRenameMap: AssetRenameMap<Space> = new Map(),
        retryOnConflict: boolean = true,
        assetConflictMap?: NameConflictMap
    ): Promise<IBatchOperationSpaceResult> {
        let resultOps: IBatchOperationSpaceResult = { failedResults: [], newModels: [] };

        await ItemBase.runExclusiveTask('move', spaces, async () => {
            const targetAsset = await this._hostAssetContext.getAssetWithCloudID(team.id);
            if (assetConflictMap === undefined) {
                assetConflictMap = new Map() as NameConflictMap;
            }
            const spacesById = new Map<string, Space>();
            const ops = spaces.map((space) => {
                spacesById.set(space.id, space);
                let newPath = `${targetAsset.repoPath}/${getBatchRenamedAssetName(space, assetRenameMap)}`;

                newPath = batchFormatFileName(this._core, space.id, newPath, false, assetConflictMap!);
                return {
                    op: 'move',
                    id: space.id,
                    source: {
                        'repo:assetId': space.id,
                        'repo:repositoryId': space.repositoryID
                    },
                    target: {
                        'repo:path': newPath,
                        'repo:repositoryId': targetAsset.repositoryID
                    }
                } as IOperation;
            });

            resultOps = await this._runOperations(ops, spacesById, {
                teamId: team.id,
                teamName: team.name
            });
        });
        if (retryOnConflict) {
            return await retryFailedOpsDueToConflict(resultOps, team, assetRenameMap, assetConflictMap!, this._moveSpaces.bind(this));
        }
        return resultOps;
    }

    /**
     * Public method to move spaces to a team
     * @param spaces spaces to be moved
     * @param team destination team where spaces are intended to be moved
     * @returns the result for batch operation after retrying for failed assets.
     */
    async moveSpaces(spaces: Space[], team: Team): Promise<IBatchOperationSpaceResult> {
        return this._moveSpaces(spaces, team);
    }

    async archiveSpaces(spaces: Space[]): Promise<IBatchOperationSpaceResult> {
        return await ItemBase.runExclusiveTask('archive', spaces, async () => {
            const spacesById = new Map<string, Space>();
            const ops = spaces.map((space) => {
                spacesById.set(space.id, space);
                return {
                    op: 'discard',
                    id: space.id,
                    target: {
                        'repo:assetId': space.id,
                        'repo:repositoryId': space.repositoryID
                    },
                } as IOperation;
            });

            return await this._runOperations(ops, spacesById);
        });
    }

    async restoreSpaces(spaces: Space[], restoreNameMap?: Map<Space, string>): Promise<IBatchOperationSpaceResult> {
        return await ItemBase.runExclusiveTask('restore', spaces, async () => {
            const spacesById = new Map<string, Space>();
            const ops = spaces.map((space) => {
                spacesById.set(space.id, space);
                return {
                    op: 'restore',
                    id: space.id,
                    target: {
                        'repo:assetId': space.id,
                        'repo:repositoryId': space.repositoryID
                    },
                    name: restoreNameMap?.get(space)
                } as IOperation;
            });
            return await this._runOperations(ops, spacesById);
        });
    }

    async _runOperations(
        ops: IOperationQuery, spacesById: Map<string, Space>, additionalSpaceUpdates: Partial<IProjectsSpace> = {}
    ): Promise<IBatchOperationSpaceResult> {
        const assetContext = await this._core.getAssetContext();
        return await this._rapi.runOperationsForContext<Space>(
            ops,
            spacesById,
            this._spacePool,
            (session: IUpdateSession<Space>, space: Space, remoteItem?: RepositoryMetadata) => {
                if (!remoteItem) {
                    throw SAMError.create(SAMErrorCode.UNKNOWN, 'Missing metadata from asset bulk operation.');
                }
                // We want to update the repo:path of all the descendants of the space only in case of move/rename.
                const remoteRepoPath = remoteItem['repo:path'];
                if (space.pathName !== remoteRepoPath) {
                    const adobeAssetPool = this._core._getAssetPool();
                    const localAdobeAsset = adobeAssetPool.getLocalItemById(space.id);
                    const assetSession = adobeAssetPool.createUpdateSession();

                    if (localAdobeAsset) {
                        updateCachedDescendents({
                            assetPool: adobeAssetPool,
                            asset: localAdobeAsset,
                            session: assetSession,
                            operation: { type: 'rename', newPath: remoteRepoPath },
                            assetContext
                        });
                        assetContext._adobeAssetUpdater.updateLocalItem(
                            assetSession,
                            localAdobeAsset,
                            {
                                'repo:path': remoteRepoPath
                            }
                        );
                        assetSession.commit();
                    }
                }

                SpaceUpdater.updateLocalItem(session, space, {
                    state: remoteItem['repo:state'] === 'ACTIVE' ? 'active' : 'archived',
                    name: remoteItem['repo:name'],
                    pathName: remoteItem['repo:path'],
                    ...additionalSpaceUpdates
                });
                return undefined;
            },
            [
                {
                    // Refresh this space to make sure we have the latest version of it.
                    // Note that we cannot use 404 - NOT_FOUND as a sign that the space has been
                    // permanently deleted as we get that same error code when the space
                    // is still active, just that the user is not allowed to archive/restore it.
                    // It is better to just reload the space to validate we still have access to
                    match: (error: SAMError) => error.code === SAMErrorCode.ACCESS_DENIED || error.code === SAMErrorCode.NOT_FOUND,
                    action: async (space: Space) => {
                        return await space.load().catch((error: Error) => {
                            return { model: space, error: error as SAMError };
                        });
                    }
                }
            ]
        );
    }

    async createSpaceBookmarks(spaces: Space[]): Promise<void>  {
        return this._bookmarkSpaces('ADD', spaces);
    }

    async removeSpaceBookmarks(spaces: Space[]): Promise<void>  {
        return this._bookmarkSpaces('REMOVE', spaces);
    }

    private async _bookmarkSpaces(op: IProjectsBookmarkOpType, spaces: Space[]): Promise<void> {
        await ItemBase.runExclusiveTask('bookmark', spaces, async () => {
            const userId = this._core._environment.getValue('USER_ID');

            // Attempt to make the change ahead of time.
            const change: Partial<IProjectsSpace>  = {
                bookmarked: op === 'ADD'
            };
            const localSession = this.spacePool.createUpdateSession();

            const spaceById = new Map<string, { space: Space, wasBookmarked: boolean, status?: number }>();
            const items = spaces.map((space) => {
                spaceById.set(space.id, { space, wasBookmarked: space.isBookmarked });
                SpaceUpdater.updateLocalItem(localSession, space, change);
                return {
                    projectUrn: space.id,
                    userId
                };
            });
            localSession.commit();

            let response: IProjectsBookmarkBatchResponse | undefined;

            try {
                response = await this._projectInterface.bookmarkOp({ op, items });
            } finally {
                if (response) {
                    for (const item of response.responses) {
                        const info = spaceById.get(item.request?.projectUrn);
                        if (info) {
                            info.status = item.status;
                        }
                    }
                }

                // Revert all incomplete changes.
                const restoreSession = this.spacePool.createUpdateSession();
                const mutationSession = this.spacePool.createMutationSession();

                for (const { space, wasBookmarked, status } of spaceById.values()) {
                    if (status === 201) {
                        // Reapply the change, in case there was a different fetch in-between.
                        // This should also force the mutation timestamp to update on the space.
                        SpaceUpdater.updateLocalItem(mutationSession, space, change);
                    } else {
                        // Revert the local change.
                        SpaceUpdater.updateLocalItem(restoreSession, space, {
                            bookmarked: wasBookmarked
                        });

                        // Check if the item was removed on a different device
                        // and remove it from internal lists too.
                        if (status === 404) {
                            restoreSession.queueDiscardedItem(space);
                        }
                    }
                }
                restoreSession.commit();
                mutationSession.commit();
            }
        });
    }

    private _checkForRejection(
        results: PromiseSettledResult<void>[],
        onRemoveItem: () => void
    ) {
        for (const result of results) {
            if (result.status === 'rejected') {
                const error = result.reason;
                // Remove the item entirely
                if (error instanceof SAMError && error.code === SAMErrorCode.NOT_FOUND) {
                    onRemoveItem();
                }
                throw error;
            }
        }
    }

    async updateSpace(space: Space, update: ISpaceUpdate): Promise<void> {
        // Make both rename and patch go through the same exclusive task,
        // to allow them to execute in parallel.
        await ItemBase.runExclusiveTask('update', [ space ], async () => {
            const results = await Promise.allSettled([
                this._renameSpace(space, update),
                this._patchSpace(space, update)
            ]);

            this._checkForRejection(results, () => {
                const session = this.spacePool.createUpdateSession();
                session.queueDiscardedItem(space);
                session.commit();
            });
        });
    }

    private async _renameSpace(space: Space, update: ISpaceUpdate): Promise<void> {
        const  { name } = update;
        if (name === undefined) {
            return;
        }

        const asset = await this._renameAsset(space.id, name);
        const updateSession = this.spacePool.createMutationSession();
        SpaceUpdater.updateLocalItem(updateSession, space, {
            name: asset.name,
            pathName: asset.repoPath
        });
        updateSession.commit();
    }

    private async _patchSpace(space: Space, update: ISpaceUpdate): Promise<void> {
        const  { description, color } = update;
        const bodyData: jsonpatch.OpPatch[] = [];
        const localUpdate: Partial<IProjectsSpace> = {};

        if (description !== undefined) {
            bodyData.push(this._getPatchOP(
                description,
                `/description`,
                space.description,
                this._validateDescription
            ));
            localUpdate.description = description;
        }

        if (color !== undefined) {
            bodyData.push(this._getPatchOP(
                color,
                `/color`,
                space.color,
                this._validateColor
            ));
            localUpdate.color = color;
        }

        if (!bodyData.length) {
            return;
        }

        const links = getLinks(space);

        // Ideally, the patch would return the updated state, but that's not the case here.
        await this._projectInterface.patchSpace(links, bodyData);

        // We will have to assume that a successful change means the changed values are the latest ones.
        const updateSession = this.spacePool.createMutationSession();
        SpaceUpdater.updateLocalItem(updateSession, space, localUpdate);
        updateSession.commit();
    }

    async createSpace(team: Team, data: IProjectsCreateData): Promise<Space> {
        const links = getLinks(team);

        this._validateColor(data.color);
        this._validateDescription(data.description);
        validatePlatformRepoName(data.name);

        const response = await this._projectInterface.createSpace(links, {
            ...data,
            parentId: team.id
        });
        // A space might not show up until a few seconds later, so we must keep it alive during this time.
        const updateSession = this.spacePool.createMutationSession();
        const space = SpaceUpdater.updateRemoteItem(updateSession, {
            ...response,

            // Make sure the service injects the teamId.
            teamId: team.id
        });
        updateSession.commit();
        return space;
    }

    async getEnclosingSpace(assetId: string): Promise<Space | undefined> {
        const spaceMap = await this.getEnclosingSpaces([ assetId ]);
        return spaceMap.get(assetId);
    }

    async getEnclosingSpaces(assetIds: string[]): Promise<Map<string, Space>> {
        // The :context API uses the USS to lookup the enclosing space, so it suffers by the
        // same amount of latency as the listing APIs. We will ignore the info we get from this
        // API if the asset was mutated more recently than the maximum expected latency for USS.
        const latency = this._core._environment.getValue('PROJECTS_LIST_UPDATE_LATENCY');
        const mostRecentValidMutation = Date.now() - latency;  // We will ignore the update if we had local changes sooner than this timestamp.

        const result = await this._projectInterface.getEnclosingSpaces(assetIds.map((id) => ({ 'repo:assetId': id })));
        const map = new Map<string, Space>();
        const updateSession = this.spacePool.createUpdateSession('get enclosing spaces', mostRecentValidMutation);
        for (const item of result.responses) {
            if (item.status !== 200) {
                continue;
            }
            const id = item.request['repo:assetId'];
            const space = SpaceUpdater.updateRemoteItem(updateSession, item.body);
            map.set(id, space);
        }
        updateSession.commit();
        return map;
    }

    async lookupSpaceById(id: string): Promise<Space> {
        let space = this._spacePool.getLocalItemById(id);
        if (!space) {
            // Note that we don't have a local space, so we don't have to worry about eventual consistency on this item.
            const response = await this._projectInterface.getSpace(id, SPACE_FULL_SELECTOR);
            const session = this._spacePool.createUpdateSession();
            space = SpaceUpdater.updateRemoteItem(session, response);
            session.commit();
        }
        return space;
    }

    /**
     * This API is temporary and it is specifically for Projects UI to use with SS workflows.
     * It will eventually be deprecated in favor of using notifications
     * @param teamId
     */
    onUserLeftTeam(teamId: string): void {
        const team = this._teamPool.getLocalItemById(teamId);
        if (team) {
            const session = this._teamPool.createUpdateSession();
            session.queueDiscardedItem(team);
            session.commit();
        }
    }
}
