import ItemUpdater from '../core/ItemUpdater';
import PropertyUpdater from '../core/PropertyUpdater';

import type { IFrameioUserResponse } from './FrameioInterface';
import type FrameioAccount from './FrameioAccount';
import FrameioBase from './FrameioBase';

// See https://developer.frame.io/api/reference/operation/getAccount/
//  for schema of the data FrameioAccount encapsulates.
export default class FrameioUser extends FrameioBase {
    private _accountId: string = '';
    private _email: string = '';
    private _name: string = '';
    private _profileImage: string = '';
    private _userDefaultColor: string = '';

    private _account: FrameioAccount | undefined;

    get accountId(): string {
        return this._accountId;
    }

    get email(): string {
        return this._email;
    }

    get name(): string {
        return this._name;
    }

    get profileImage(): string {
        return this._profileImage;
    }

    get userDefaultColor(): string {
        return this._userDefaultColor;
    }

    async getAccount(): Promise<FrameioAccount> {
        if (!this._account) {
            this._account = await this.context.getAccount(this.accountId);
        }

        return this._account;
    }
}

export const FrameioUserUpdater = new ItemUpdater<FrameioUser, Partial<IFrameioUserResponse>>({
    localItemType: FrameioUser,
    remoteIdProperty: 'id',
    propertyUpdater: new PropertyUpdater({
        '_accountId': 'account_id',
        '_email': 'email',
        '_name': 'name',
        '_profileImage': 'profile_image',
        '_userDefaultColor': 'user_default_color'
    })
});

