import {
    gql
} from '@apollo/client';

export const sharedWithYouAssets = gql`query SharedWithYou(
  $first: Int!
  $after: String
  $filter: AssetListFilter
  $orderBy: SharedWithYouOrderByInput) {
  sharedWithYou {
    assetListId
    assetListConnection(
      first: $first
      after: $after
      filter: $filter
      orderBy: $orderBy) {
      edges {
        cursor
        node {
          ... on Asset {
            sharingInfo {
              sharedWithYou {
                shareTypes
                shareDate
                sharedBy {
                  id
                }
              }
            }
            repo_assetClass
            repo_assetType
            repo_assetSubType
            labels {
              lastAccessDate
            }
            #defer
            repository {
              repo_repositoryId
            }
            dc_format
            storage_deviceCreateDate
            storage_deviceModifyDate
            primary_etag
            effectivePermissions {
              aclPolicy
              annotations
              applicationMetadata
              default
              directory
              primary
            }
            primaryLink {
              href
            }
            blockUploadLink {
              href
            }
            repo_ancestors
            repo_ancestorInfo{
                assetId
                assetSubType
                assetType
            }
            repo_createDate
            repo_createdBy {
              id
            }
            repo_path
            repo_representations {
              composite
              directory
              file
            }
            repo_modifiedBy
            repo_modifyDate
            repo_name
            repo_state
            repo_assetId
            storage_region
            storage_assignee {
              id
              type
            }
            ... @defer {
              appMetadata {
                am: valueOf(key: "")
              }
            }
          }
          ... on Composite {
            repo_version
            repo_size
            blockDownloadLink {
              href
            }
            renditionLink {
              href
            }
            componentLink {
              href
            }
          }
          ... on File {
            repo_version
            repo_size
            blockDownloadLink {
              href
            }
            renditionLink {
              href
            }
            tiff_imageLength
            tiff_imageWidth
          }
        }
      }
      pageInfo {
        endCursor
        hasNextPage
      }
    }
  }
}
`;
