import { RelType } from '../interface/LinkUtils';
import type AdobeAsset from './AdobeAsset';
import type { ISAMCorePrivate } from '../indexPrivate';
import type { Permission } from '../interface/AssetModel';
import { parseEffectivePermissions } from '../interface/AssetModel';
import AdobeAssetResource from './AdobeAssetResource';

export default class EffectivePermissionsResource extends AdobeAssetResource<Permission> {

    constructor(
        readonly _core: ISAMCorePrivate,
        _parent?: AdobeAsset,
    ) {
        super(_core, _parent, {
            parseResponse: async (response) => parseEffectivePermissions(await response.json()),
            onChange: async (effectivePermission, { timestamp } = {}) => {
                await this._parent?._handleResourceUpdates({ timestamp, effectivePermission });
            },
            onError: async (error) => {
                await this._parent?._handleResourceUpdates({ error });
                this._error = undefined; // If we got this far, the error was a 404/403, which is not fatal for permissions.
            }
        });
    }

    protected async _loadData() {
        await this._parent?._ensureLink(RelType.AC_EFFECTIVE);
        const assetInterface = await this._parent?._getAssetInterface();
        await assetInterface?.getEffectivePermissions(this);
    }
}
