import type InvitationInterface from '../interface/InvitationInterface';
import type AccessRequestItem from './AccessRequestItem';
import { AccessRequestItemUpdater } from './AccessRequestItem';
import type { IItemLoader, IItemLoaderOptions, ILoadedPage, ILoadNextPage } from '../core/ItemLoader';
import type ItemPool from '../core/ItemPool';
import type { AccessRequestConfig } from './AccessRequestSource';
import type { AccessRequestOrderBy } from './AccessRequest';

export default class AccessRequestLoader implements IItemLoader<AccessRequestConfig> {
    /**
     * Directly copied from the CollabService (Invitations Service)
        const (
            DefaultPageSize               = 10
            MaxPageSize                   = 30
            OrderByParam                  = "orderBy"
            ResourceTypeParam             = "type"
            LimitParam                    = "limit"
            StartParam                    = "start"
            ErrMalformedRequestLimitRange = "Malformed request: limit value is out of range"
        )
     */
    private static readonly DEFAULT_MAX_PAGE_SIZE = 30;

    constructor(
        private _accessRequestPool: ItemPool<AccessRequestItem>,
        private _invitationInterface: InvitationInterface,
        private _assetId: string,
        private _resourcesType?: string
    ) {}

    async loadPage(options: IItemLoaderOptions<AccessRequestConfig>): Promise<ILoadedPage<AccessRequestConfig>> {
        return await this._loadPage(options);
    }

    private async _loadPage(
        options: IItemLoaderOptions<AccessRequestConfig>,
        nextPageHref?: string
    ): Promise<ILoadedPage<AccessRequestConfig>> {
        let result;

        if (nextPageHref) {
            // Load the next page using the provided href
            result = await this._invitationInterface.getNextPageAccessRequests(nextPageHref);
        } else {

            const { limit = AccessRequestLoader.DEFAULT_MAX_PAGE_SIZE } = options.loadOptions || { limit: AccessRequestLoader.DEFAULT_MAX_PAGE_SIZE };

            // Map the order field to the API's orderBy parameter
            let orderBy: AccessRequestOrderBy = '+requesttime';
            if (options.order) {
                const direction = options.order.direction === 'ascending' ? '+' : '-';
                orderBy = `${direction}requesttime` as AccessRequestOrderBy;
            }

            result = await this._invitationInterface.getAccessRequests(
                this._assetId,
                orderBy,
                limit,
                undefined,
                this._resourcesType
            );
        }

        // Update the access requests in the pool
        // Note: accessRequests can be null when there are no requests for the asset
        const accessRequestsArray = result._embedded.accessRequests || [];
        const updateSession = this._accessRequestPool.createLoaderUpdateSession(Date.now());
        const accessRequests = AccessRequestItemUpdater.updateRemoteItems(
            updateSession,
            accessRequestsArray
        );
        updateSession.commit();

        // Check if we have another page to load
        let loadNextPage: ILoadNextPage<AccessRequestConfig> | undefined;
        const nextLink = result._links?.next?.href;
        if (nextLink) {
            loadNextPage = (options: IItemLoaderOptions<AccessRequestConfig>) =>
                this._loadPage(options, nextLink);
        }

        return {
            items: accessRequests,
            total: accessRequestsArray.length,
            loadNextPage
        };
    }
}
