export type DateRange = {
    min?: string,
    max?: string
};

export const makeDateRange = (max?: Date, min?: Date): DateRange | undefined => {
    return ((max || min) ? { min: getDateString(min), max: getDateString(max) } as DateRange : undefined);
};

export const getDateString = (date?: Date): string | undefined => {
    return (date ? date.toISOString() : date);
};
