import ImplicitAdobeAssetFilterBase from './ImplicitAdobeAssetFilterBase';
import type { IImplicitFilter } from '../core/ItemFilter';
import type AdobeAsset from './AdobeAsset';
import { Permission } from '../interface/AssetModel';

export default class DiscardedAdobeAssetFilter extends ImplicitAdobeAssetFilterBase implements IImplicitFilter<AdobeAsset> {
    constructor() {
        super({
            _isDiscarded: true,
            _isSharedWithYou: true
        });
    }

    matches(item: AdobeAsset): boolean {

        if (this.isSyncedAsset(item) || this.isMobileCreation(item)) {
            return false;
        }

        // TODO: We should also handle this in the USS query when it's supported, but keep this check here for good measure.
        // https://jira.corp.adobe.com/browse/SEARCH-41079
        if (!item.hasPermission(Permission.Restore) && !item.hasPermission(Permission.Delete)) {
            return false;
        }

        return super.matches(item);
    }

    isSyncedAsset(item: AdobeAsset): boolean {
        return item.repoPath.startsWith('/files/');
    }

    isMobileCreation(item: AdobeAsset): boolean {
        return item.repoPath.startsWith('/assets/') && !item.repoPath.startsWith('/assets/adobe-libraries/');
    }
}
