import ItemBase from '../core/ItemBase';
import PropertyUpdater from '../core/PropertyUpdater';
import { ItemUpdaterBase } from '../core/ItemUpdater';
import type { IAccessRequestData, AccessRequestStatus, IRequestedPermissions, IAdditionalData } from './AccessRequest';
import { AccessRequestStatus as AccessRequestStatusEnum } from './AccessRequest';


/**
 * Represents an access request for an asset.
 */
export default class AccessRequestItem extends ItemBase {
    private _resourceUrn: string = '';
    private _canRequestAccess: boolean = false;
    private _collaborationModel: string = '';
    private _createDate: number = 0;
    private _requesterEmail: string = '';
    private _requesterId: string = '';
    private _requesterName: string = '';
    private _resourceName: string = '';
    private _resourceType: string = '';
    private _status: AccessRequestStatus = AccessRequestStatusEnum.PENDING;
    private _requestedPermissions?: IRequestedPermissions;
    private _additionalData?: IAdditionalData;

    get resourceUrn(): string {
        return this._resourceUrn;
    }

    get canRequestAccess(): boolean {
        return this._canRequestAccess;
    }

    get collaborationModel(): string {
        return this._collaborationModel;
    }

    get createDate(): number {
        return this._createDate;
    }

    get requesterEmail(): string {
        return this._requesterEmail;
    }

    get requesterId(): string {
        return this._requesterId;
    }

    get requesterName(): string {
        return this._requesterName;
    }

    get resourceName(): string {
        return this._resourceName;
    }

    get resourceType(): string {
        return this._resourceType;
    }

    get status(): AccessRequestStatus {
        return this._status;
    }

    get requestedPermissions(): IRequestedPermissions | undefined {
        return this._requestedPermissions;
    }

    get additionalData(): IAdditionalData | undefined {
        return this._additionalData;
    }

    public static getUniqueId(resourceUrn: string, requesterId: string): string {
        return `${resourceUrn}::${requesterId}`;
    }
}

/**
 * Custom format for parsing status string to AccessRequestStatus enum
 */
const statusFormat = {
    parse: (value: any): AccessRequestStatus => {
        if (value === null || value === undefined) {
            return AccessRequestStatusEnum.PENDING;
        }

        const statusStr = String(value).toLowerCase();

        switch (statusStr) {
        case 'pending':
            return AccessRequestStatusEnum.PENDING;
        case 'granted':
            return AccessRequestStatusEnum.GRANTED;
        case 'rejected':
            return AccessRequestStatusEnum.REJECTED;
        default:
            // Default to PENDING for unknown values
            return AccessRequestStatusEnum.PENDING;
        }
    },
    isEqual: (a: AccessRequestStatus, b: AccessRequestStatus) => a === b
};

/**
 * Updater for AccessRequestItem objects
 *
 * Note: The unique ID is a composite of resourceUrn + requesterId because
 * the same requester can request access to multiple different assets.
 */
export const AccessRequestItemUpdater = new ItemUpdaterBase<AccessRequestItem, IAccessRequestData>({
    localItemType: AccessRequestItem,
    getRemoteId: (remoteItem: IAccessRequestData) => {
        // Composite key: resourceUrn + requesterId
        // @note - the invitations service swagger docs say the requesterId is not
        // required in the response but it is so we should never return undefined here.
        if (!remoteItem.resourceUrn || !remoteItem.requesterId) {
            return undefined;
        }
        return AccessRequestItem.getUniqueId(remoteItem.resourceUrn, remoteItem.requesterId);
    },
    propertyUpdater: new PropertyUpdater({
        '_resourceUrn': { name: 'resourceUrn', format: 'string' },
        '_canRequestAccess': { name: 'canRequestAccess', format: 'boolean' },
        '_collaborationModel': { name: 'collaborationModel', format: 'string' },
        '_createDate': { name: 'createDate', format: 'number' },
        '_requesterEmail': { name: 'requesterEmail', format: 'string' },
        '_requesterId': { name: 'requesterId', format: 'string' },
        '_requesterName': { name: 'requesterName', format: 'string' },
        '_resourceName': { name: 'resourceName', format: 'string' },
        '_resourceType': { name: 'resourceType', format: 'string' },
        '_status': { name: 'status', format: statusFormat },
        '_requestedPermissions': { name: 'requestedPermissions', format: 'object' },
        '_additionalData': { name: 'additionalData', format: 'object' }
    })
});
