import type { IItemLoader, IItemLoaderOptions, ILoadedPage } from '../core/ItemLoader';
import type { BoardConfig } from './BoardSource';
import type { ISAMCorePrivate } from '../indexPrivate';
import type { default as Board } from './Board';

import BoardsInterface from '../interface/BoardsInterface';
import { BoardUpdater } from './Board';
import type AdobeAsset from '../assets/AdobeAsset';
import type { RemoteBoard } from '../interface/BoardModel';
import { getMostRecentValidMutation } from '../utils/loaderUtils';

export default class BoardListLoader implements IItemLoader<BoardConfig> {
    private _boardsInterface: BoardsInterface;
    private _core: ISAMCorePrivate;

    constructor(core: ISAMCorePrivate) {
        this._core = core;
        this._boardsInterface = new BoardsInterface(core);
    }

    private async observeBoardsFolder(remoteBoards: RemoteBoard[]): Promise<AdobeAsset> {
        // We fetched boards by the parent asset ID so each board will have the same boardsAssetId, just observe one of them
        const boardsAssetId = remoteBoards[0]['board:context']['boardsAssetId'];
        return this._core.hostAssetContext.getAssetWithCloudID(boardsAssetId);
    }

    async loadPage(options: IItemLoaderOptions<BoardConfig>): Promise<ILoadedPage<BoardConfig>> {
        return this._loadPage(options);
    }

    private async _loadPage(options: IItemLoaderOptions<BoardConfig>): Promise<ILoadedPage<BoardConfig>> {
        const { filter, implicitFilter } = options;
        const baseAssetId = implicitFilter.baseAssetId || filter.baseAssetId;
        const shouldGetDirectlyInBaseAsset = implicitFilter.shouldGetDirectlyInBaseAsset || filter.shouldGetDirectlyInBaseAsset || false;
        const remoteBoards = await this._boardsInterface.getBoards({ baseAssetId, shouldGetDirectlyInBaseAsset });

        const mostRecentValidMutation = getMostRecentValidMutation(options.resource);
        const session = this._core._getAssetPool().createLoaderUpdateSession<Board>(mostRecentValidMutation);
        const boards = BoardUpdater.updateRemoteItems(session, remoteBoards);
        session.commit();

        if (remoteBoards.length > 0) {
            this.observeBoardsFolder(remoteBoards).then((folder) => {
                // pin this to memory so Garbage Collector does not remove it as long as the list is still kept in memory
                implicitFilter._monitoredFolder = folder;
            });
        }

        return {
            items: boards,
            total: boards.length,
            mostRecentValidMutation
        };
    }
}
