import type {
    CreateTrainingSetOptions,
    CustomModelCreateOptions,
    CustomModelInfoMelville,
    CustomModelUpdateInfoMelville,
    CustomModelsResponseMelville,
    MelvilleCustomModelListParameters,
} from './CustomModelModel';
import InterfaceBase from './InterfaceBase';
import type { CreateLibraryOptions, MelvilleLink } from './LibraryModel';
import SAMError, { SAMErrorCode } from '../core/SAMError';
import type Library from '../libraries/Library';
import { moveUrlQueryParamsToHeaders } from './LibraryInterface';
import type { HeaderMap } from './LinkUtils';
import { fillURLTemplate } from './LinkUtils';
import type { ICustomModelListingOptions } from '../custom-models/CustomModelFilter';

export default class CustomModelInterface extends InterfaceBase {
    private _getMelvilleUrl(endpoint: string): string {
        return `https://${this._core._environment.endpoints.MELVILLE_HOST}${endpoint}`;
    }

    async searchCustomModelsUsingPageLink(
        body: ICustomModelListingOptions,
        pageLink: MelvilleLink
    ): Promise<CustomModelsResponseMelville> {

        const [ url, headerParams ] = moveUrlQueryParamsToHeaders(pageLink.href);

        const headers: HeaderMap = {
            'Cache-Control': 'no-cache, no-store, max-age=0',
            'Content-Type': 'application/json',
            ...headerParams
        };

        const finalUrl = this._getMelvilleUrl(url);

        const response = await this._doPost(
            finalUrl,
            headers,
            JSON.stringify(body),
            [ 200 ]
        );

        return await response.json();
    }


    async searchCustomModels(queryParams: MelvilleCustomModelListParameters, body: ICustomModelListingOptions): Promise<CustomModelsResponseMelville> {
        if (queryParams?.limit && queryParams?.start === undefined) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, '[Melville] If limit is provided, start must also be provided.');
        }
        queryParams = sortParameters(queryParams);
        const urlWithQueryParams = fillURLTemplate(
            this._getMelvilleUrl('/api/v1/search/custom-models'),
            queryParams
        );
        const [ url, headers ] = moveUrlQueryParamsToHeaders(urlWithQueryParams);
        const defaultHeaders: HeaderMap = {
            'Cache-Control': 'no-cache, no-store, max-age=0',
            'Content-Type': 'application/json'
        };
        const finalHeaders = { ...defaultHeaders, ...headers };
        const response = await this._doPost(
            url,
            finalHeaders,
            JSON.stringify(body), [ 200 ]);
        return await response.json();
    }


    /**
   * Fetches the list of custom models based on the options provided
   * @returns the list of custom models along with the page information and links to the next page
   */
    async getCustomModels(queryParams: MelvilleCustomModelListParameters): Promise<CustomModelsResponseMelville> {
        if (queryParams?.limit && queryParams?.start === undefined) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, '[Melville] If limit is provided, start must also be provided.');
        }
        queryParams = sortParameters(queryParams);
        const urlWithQueryParams = fillURLTemplate(
            this._getMelvilleUrl('/api/v1/custom-models'),
            queryParams
        );
        // Pass as many parameters as headers as we can, to avoid extra CORS preflight OPTIONS requests per url.
        const [ url, headers ] = moveUrlQueryParamsToHeaders(urlWithQueryParams);
        // Ensure browser doesn't automatically add If-None-Match, otherwise
        // service may respond with cached data for a library
        const defaultHeaders: HeaderMap = { ['Cache-Control']: 'no-cache, no-store, max-age=0' };
        const finalHeaders = { ...defaultHeaders, ...headers };

        return await this._getResponse(url, { headers: finalHeaders });
    }

    /**
     * Fetches one custom model by ID
     *
     * @param customModelId ID of custom model to be fetched
     * @returns the custom model
     */
    async getCustomModelById(customModelId: string): Promise<CustomModelInfoMelville> {
        return await this._getResponse<CustomModelInfoMelville>(
            this._getMelvilleUrl(`/api/v1/custom-models/${customModelId}`),
            { headers: { 'Content-Type': 'application/json' } }
        );
    }

    /**
   * @package -- only for use in SAM.js
   * Fetches the next page of custom models from Melville
   * @returns a list of custom models along with page information and links to the next page
   */
    async getCustomModelsUsingPageLink(pageLink: MelvilleLink): Promise<CustomModelsResponseMelville> {
        const [ url, headers ] = moveUrlQueryParamsToHeaders(this._getMelvilleUrl(pageLink.href));
        return this._getResponse(url, { headers });
    }

    /**
   * Create a training set to be used with a custom model. The training set is considered a child of the parent asset
   * specified by the parentAssetId.
   */
    async createTrainingSet(options: CreateTrainingSetOptions): Promise<Library> {
        // check for values under the deprecated firefly#ffmodel key
        const cmeOptions = options['firefly#cme'] || options['firefly#ffmodel'];
        if (!options.name) {
            throw SAMError.create(
                SAMErrorCode.BAD_REQUEST,
                'Invalid argument: missing required name'
            );
        }

        if (!options.projectId) {
            throw SAMError.create(
                SAMErrorCode.BAD_REQUEST,
                'Invalid argument: missing required projectId. The parent must be a project'
            );
        }

        if (!cmeOptions.schemaVersion) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Invalid argument: missing required schemaVersion.');
        }

        if (!cmeOptions.trainingMode) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, 'Invalid argument: missing required trainingMode.');
        }

        const creationOptions: CreateLibraryOptions = {
            name: options.name,
            parent_assetId: options.projectId,
            roles: [ {
                type: 'cm_training_set'
            } ],
            'library#description': options.description,
            'firefly#cme': {
                ...cmeOptions,
                // Melville is temporarily looking at version, but will soon switch to schemaVersion
                version: cmeOptions.schemaVersion
            }
        };

        const libraryContext = await this._core.getLibraryContext();
        return libraryContext._createLibrary(creationOptions);
    }

    async getTrainingSetById(assetId: string): Promise<Library | undefined> {
        const libraryContext = await this._core.getLibraryContext();
        return libraryContext._getLibraryRemotely(assetId, { selectors: [ 'details' ] });
    }

    async createCustomModel(options: CustomModelCreateOptions): Promise<CustomModelInfoMelville> {
        const endpoint: string = `/api/v1/custom-models`;

        const response = await this._doPost(
            this._getMelvilleUrl(endpoint),
            { 'Content-Type': 'application/json' },
            JSON.stringify(options),
            [ 201 ]);

        return response.json();
    }

    async updateCustomModel(assetId: string, options: CustomModelUpdateInfoMelville) {
        const endpoint: string = `/api/v1/custom-models/${assetId}`;

        await this._doPut(
            this._getMelvilleUrl(endpoint),
            { 'Content-Type': 'application/json' },
            JSON.stringify(options),
            [ 204, 201, 200 ]);
    }

    async deleteCustomModel(assetId: string): Promise<void> {
        const endpoint: string = `/api/v1/custom-models/${assetId}`;

        await this._doDelete(
            this._getMelvilleUrl(endpoint),
            { 'Content-Type': 'application/json' },
            [ 204 ]);
    }

    async discardCustomModel(assetId: string): Promise<void> {
        await this._doPost(
            this._getMelvilleUrl(`/api/v1/custom-models/${assetId}/discard`),
            { 'Content-Type': 'application/json' },
            '',
            [ 204 ]
        );
    }

    async restoreCustomModel(assetId: string): Promise<void> {
        await this._doPost(
            this._getMelvilleUrl(`/api/v1/custom-models/${assetId}/restore`),
            { 'Content-Type': 'application/json' },
            '',
            [ 204 ]
        );
    }

    async publish(assetID: string): Promise<CustomModelInfoMelville> {
        const endpoint: string = `/api/v1/custom-models/${assetID}/publish`;

        const response = await this._doPost(
            this._getMelvilleUrl(endpoint),
            undefined,
            undefined,
            [ 200 ]);

        return await response.json();
    }

    async unpublish(assetID: string): Promise<CustomModelInfoMelville> {
        const endpoint: string = `/api/v1/custom-models/${assetID}/unpublish`;

        const response = await this._doPost(
            this._getMelvilleUrl(endpoint),
            undefined,
            undefined,
            [ 200 ]);

        return await response.json();
    }
}

// Sort parameters so that the query string is stable, preventing unnecessary cache misses.
export const sortParameters = (parameters: MelvilleCustomModelListParameters): MelvilleCustomModelListParameters => {
    return Object.fromEntries(
        Object.entries(parameters)
            .map(([ key, value ]) => {
                if (Array.isArray(value)) {
                    return [ key, value.sort() ];
                }
                return [ key, value ];
            })
            .sort()
    );
};
