    // Methods related to using Adobe Single User Sign In (SUSI)
    public async getAdobeSusiInfo(): Promise<FrameioAdobeSusiInfo> {
        const respJson = await this._adobeSusiUserRequest();
        const susiInfo: FrameioAdobeSusiInfo = {
            userExists: respJson.exists,
            susiAvailable: (respJson.method === 'adobe'),
            restriction: respJson.restriction || undefined
        };
        return susiInfo;
    }

    public async authenticateAdobeSusi(): Promise<FrameioAuthenticationInfo> {
        const authInfo = await this._adobeSusiRequest();
        return authInfo;
    }

    private async _adobeSusiUserRequest(): Promise<IFrameioAdobeSusiUserResponse> {
        const response = await this._doPost(
            FRAMEIO_LINKS.ADOBE_SUSI_USER,
            { 'Content-Type': 'application/json' },
            JSON.stringify({ access_token: this.imsToken }),
            [ 200 ]
        );
        return response.json();
    }

    private async _adobeSusiRequest(): Promise<FrameioAuthenticationInfo> {
        const response = await this._doPost(
            FRAMEIO_LINKS.ADOBE_SUSI,
            { 'Content-Type': 'application/json' },
            JSON.stringify({ access_token: this.imsToken }),
            [ 200 ]
        );
        const respHeaders = response.headers;
        const respBody = await response.json();
        const token = respHeaders.get('authorization');
        const refreshToken = respHeaders.get('x-refresh-token');
        const tokenExpires = respHeaders.get('x-expires');
        const authInfo: FrameioAuthenticationInfo = {
            frameioToken: token ? token.replace('Bearer ', '') : '',
            frameioRefreshToken: refreshToken || undefined,
            frameioTokenExpires: tokenExpires || undefined,
            frameioUserId: respBody.id || undefined,
            frameioLastRefresh: Date.now().toString(),
            useAdobeSusi: true
        };
        return authInfo;
    }

    //----------------------------------------------------------------
    // InterfaceBase._fetch() lets subclasses adjust the fetch options
    // by calling _getFetchOptionOverrides().
    //
    // FrameioInterface specifies noOtherHeaders=true to block ACP
    // specific headers, such as _fetch() injecting it's own
    // ACP specific authorization token. Instead, we specify
    // the Frameio authorization token
    protected  async _getFetchOptionOverrides(
        href: string,
        fetchOptions: IFetchOptions
    ): Promise<{ href: string, options: IFetchOptions}> {
        const token = await this.getToken();
        return {
            href,
            options: {
                ...fetchOptions,
                headers: {
                    ...fetchOptions.headers,
                    // Override Environment.fetch default auth header
                    'authorization': `Bearer ${token}`,
                    'x-frameio-client': this.xFrameioClient
                },
                // Do not allow Environment.fetch to supply its default headers
                noOtherHeaders: true
            }
        };
    }

    // Frameio endpoints that return Array<>'s can be paginated:
    //   https://developer.frame.io/docs/getting-started/key-concepts#h2-section-pagination
    //   NOTE: The default page size is 50.
    //
    // _getMultiPageResponse() will read each page in the response,
    // and return the result of combining them into one large array.
    private async _getMultiPageResponse(href: string) {
        let result: any[] = [];

        const nextPageUri = (response: any) => {
            const linkHeader = response && response.headers && response.headers.get('Link');
            const link = linkHeader && LinkHeader.parse(linkHeader);
            const ref = link && link.has('rel', 'next') && link.get('rel', 'next');
            const uri = ref && ref[0] && ref[0].uri;

            // For some reason, the link headers are specifying http,
            // but our requests fail with 403 unless we use https.
            return uri && uri.replace('http:', 'https:');
        };

        const readPage = async (url: string): Promise<any> => {
            const response = await this._doGet(url);
            const json = await response.json();

            const next = nextPageUri(response);

            // Accumulate the pages in result
            result = result.concat(json);

            // Use tail recursion to read the next page, or return
            // the final result if there are no more pages.
            return next ? readPage(next) : result;
        };

        return readPage(href);
    }
