import ItemUpdater from '../core/ItemUpdater';
import PropertyUpdater from '../core/PropertyUpdater';
import FrameioBase from './FrameioBase';
import type { IFrameioCommentResponse, IFrameioUserResponse } from './FrameioInterface';
import type FrameioLike from './FrameioLike';
import { FrameioLikeUpdater } from './FrameioLike';
import type { ISAMObject } from '../core/ISAMObject';
import type FrameioUser from './FrameioUser';
import { FrameioUserUpdater } from './FrameioUser';

export type FrameioCommentParam = {
    text: string;
    mentions?: any; /* unimplemented, currently ignored */
    annotationData?: any; /* unimplemented, currently ignored */
};

// See https://developer.frame.io/api/reference/operation/getAsset/
//  for schema of IFrameioAssetResponse. FrameioFile
//  encapsulates the data for assets of type="file".
//
// See FrameioFolder, FrameioVersionStack for other asset types.
export default class FrameioComment extends FrameioBase {
    // Frame.io uses { myString : null } for unspecified
    // values, which causes our updater to set the string
    // property to undefined, but our getters substitute
    // '' for undefined, so our clients aren't exposed to this.

    private _assetId?: string;
    private _completed: boolean = false;
    private _completedAt?: Date;
    private _completerId?: string;
    private _deletedAt?: Date;
    private _hasReplies: boolean = false;
    private _insertedAt?: Date;
    private _likeCount: number = 0;
    private _owner?: FrameioUser;
    private _ownerId?: string;
    private _page?: string;
    private _parentId?: string;
    private _private: boolean = false;
    private _readCount: number = 0;
    private _reviewLinkId?: string;
    private _targetAssetId?: string;
    private _text?: string;
    private _textEditedAt?: Date;
    private _timestamp: number = 0;
    private _timestampMicroseconds: number = 0;
    private _updatedAt?: Date;

    get assetId(): string {
        return this._assetId || '';
    }

    get completed(): boolean {
        return this._completed;
    }

    get completedAt(): Date | undefined {
        return this._completedAt;
    }
    get completerId(): string {
        return this._completerId || '';
    }

    get deletedAt(): Date | undefined {
        return this._deletedAt;
    }

    get hasReplies(): boolean {
        return this._hasReplies;
    }

    get insertedAt(): Date | undefined {
        return this._insertedAt;
    }

    get likeCount(): number {
        return this._likeCount;
    }

    get owner(): FrameioUser | undefined {
        return this._owner;
    }

    get ownerId(): string {
        return this._ownerId || '';
    }

    get page(): string {
        return this._page || '';
    }

    get parentId(): string {
        return this._parentId || '';
    }

    get private(): boolean {
        return this._private;
    }

    get readCount(): number {
        return this._readCount;
    }

    get reviewLinkId(): string {
        return this._reviewLinkId || '';
    }

    get targetAssetId(): string {
        return this._targetAssetId || '';
    }

    get text(): string {
        return this._text || '';
    }

    get textEditedAt(): Date | undefined {
        return this._textEditedAt;
    }

    get timestamp(): number {
        return this._timestamp;
    }

    get timestampMicroseconds(): number {
        return this._timestampMicroseconds;
    }

    get updatedAt(): Date | undefined {
        return this._updatedAt;
    }

    async updateComment(param: FrameioCommentParam): Promise<FrameioComment> {
        const ctx = this.context;

        const response = await ctx._frameioInterface.updateComment(this.id, param.text);
        const session = ctx._objectPool.createUpdateSession<FrameioComment>();
        const comment = FrameioCommentUpdater.updateRemoteItem(session, response);
        session.commit();

        return comment;
    }

    async deleteComment(): Promise<FrameioComment> {
        const ctx = this.context;

        const response = await ctx._frameioInterface.deleteComment(this.id);
        const session = ctx._objectPool.createUpdateSession<FrameioComment>();
        const comment = FrameioCommentUpdater.updateRemoteItem(session, response);
        session.commit();

        return comment;
    }

    async createLike(): Promise<FrameioLike> {
        const ctx = this.context;

        const response = await ctx._frameioInterface.createLike(this.id);
        const session = ctx._objectPool.createUpdateSession<FrameioLike>();
        const like = FrameioLikeUpdater.updateRemoteItem(session, response);
        session.commit();

        return like;
    }

    async deleteLike(): Promise<FrameioLike> {
        const ctx = this.context;

        const response = await ctx._frameioInterface.deleteLike(this.id);
        const session = ctx._objectPool.createUpdateSession<FrameioLike>();
        const like = FrameioLikeUpdater.updateRemoteItem(session, response);
        session.commit();

        return like;
    }

    async createReply(param: FrameioCommentParam): Promise<FrameioComment> {
        const ctx = this.context;

        const response = await ctx._frameioInterface.createReply(this.id, param.text);
        const session = ctx._objectPool.createUpdateSession<FrameioComment>();
        const reply = FrameioCommentUpdater.updateRemoteItem(session, response);
        session.commit();

        return reply;
    }

    async getReplies(): Promise<Array<FrameioComment>> {
        const ctx = this.context;

        const response = await ctx._frameioInterface.getReplies(this.id);
        const session = ctx._objectPool.createUpdateSession<FrameioComment>();
        const replies = FrameioCommentUpdater.updateRemoteItems(session, response);
        session.commit();

        return replies;
    }

    async completeComment(): Promise<FrameioComment> {
        const ctx = this.context;

        const response = await ctx._frameioInterface.completeComment(this.id);
        const session = ctx._objectPool.createUpdateSession<FrameioComment>();
        const comment = FrameioCommentUpdater.updateRemoteItem(session, response);
        session.commit();

        return comment;
    }

    async uncompleteComment(): Promise<FrameioComment> {
        const ctx = this.context;

        const response = await ctx._frameioInterface.uncompleteComment(this.id);
        const session = ctx._objectPool.createUpdateSession<FrameioComment>();
        const comment = FrameioCommentUpdater.updateRemoteItem(session, response);
        session.commit();

        return comment;
    }


}

export const FrameioCommentUpdater = new ItemUpdater<FrameioComment, Partial<IFrameioCommentResponse>>({
    localItemType: FrameioComment,
    remoteIdProperty: 'id',
    propertyUpdater: new PropertyUpdater({


        '_assetId': 'asset_id',
        '_completed': { name: 'completed', format: 'boolean' },
        '_completedAt': { name: 'completed_at', format: 'date' },
        '_completerId': 'completer_id',
        '_deletedAt': { name: 'deleted_at', format: 'date' },
        '_hasReplies': { name: 'has_replies', format: 'boolean' },
        '_insertedAt': { name: 'inserted_at', format: 'date' },
        '_likeCount': { name: 'like_count', format: 'number' },
        '_owner': {
            // The owner property of an IFrameioComment is a nested
            // IFrameioUserResponse, so let's update it!
            set: (owner: IFrameioUserResponse, dest: ISAMObject) => {
                const comment = dest as FrameioComment;
                const context = comment.context;
                const pool = context._objectPool;

                const session = pool.createUpdateSession<FrameioUser>();
                comment['_owner'] = FrameioUserUpdater.updateRemoteItem(session, owner);
                session.commit();
            },
            name: 'owner',
            format: 'object'
        },
        '_ownerId': 'owner_id',
        '_page': 'page',
        '_parentId': 'parent_id',
        '_private': { name: 'private', format: 'boolean' },
        '_readCount': { name: 'read_count', format: 'number' },
        '_reviewLinkId': 'review_link_id',
        '_targetAssetId': 'target_asset_id',
        '_text': 'text',
        '_textEditedAt': { name: 'text_edited_at', format: 'date' },
        '_timestamp': { name: 'timestamp', format: 'number' },
        '_timestampMicroseconds': { name: 'timestamp_microseconds', format: 'number' },
        '_updatedAt': { name: 'updated_at', format: 'date' }
    })
});
