// `_fc` is short for "from cache". It signals whether or not the object is fetched from the Melville cache (true) or from the data source (false)
export type LibraryRenditionGridData = {
    main?: LibraryRenditionData;
    tiles?: LibraryRenditionData[];
    _fc?: boolean;
};
/**
 * DataRenditionMimeTypes is a union of the different possible non-image Library renditions.
 * The following are their respective schemas:
 * https://git.corp.adobe.com/caf/xcm/blob/main/schemas/cc/library/data/color/color.schema.json
 * https://git.corp.adobe.com/caf/xcm/blob/main/schemas/cc/library/data/color-theme/color-theme.schema.json
 * https://git.corp.adobe.com/caf/xcm/blob/main/schemas/cc/library/data/gradient/gradient.schema.json
 * https://git.corp.adobe.com/caf/xcm/blob/main/schemas/cc/library/data/noise-gradient/noise-gradient.schema.json
*/
export type DataRenditionMimeTypes =
    | 'application/vnd.adobe.color+json'
    | 'application/vnd.adobe.colortheme+json'
    | 'application/vnd.adobe.gradient+json'
    | 'application/vnd.adobe.gradient.noise+json';

/**
 * DataRenditionElementTypes is a union of the different possible non-image Library elements.
 * The following are their respective schemas:
 * https://git.corp.adobe.com/caf/xcm/tree/main/schemas/cc/library/element/color
 * https://git.corp.adobe.com/caf/xcm/tree/main/schemas/cc/library/element/color-theme
 * https://git.corp.adobe.com/caf/xcm/tree/main/schemas/cc/library/element/gradient
*/

export type DataElementTypes =
    | 'application/vnd.adobe.element.color+dcx'
    | 'application/vnd.adobe.element.colortheme+dcx'
    | 'application/vnd.adobe.element.gradient+dcx'

export type LibraryRenditionData = {
    // Shared property
    elementId: string;
} & ({
    // Only applies to type = 'href'
    type: 'href';
    rendition: string;
    templatedLink?: string;
    elementType: 'application/vnd.adobe.element.image+dcx';
} | {
    // Applies to all other types
    type: DataElementTypes;
    rendition: LibraryObjectRenditions;
    rendition_mimetype: DataRenditionMimeTypes;
    elementType: DataElementTypes;
});

type SwatchValue = {
    r: number;
    g: number;
    b: number;
};

type BaseSwatch = {
    mode: string;
    alpha: number;
    value: SwatchValue;
};

type ElementColorSwatchRendition = {
    swatches: (BaseSwatch & { library_rel: string; type: string })[][];
};

type ElementColorPaletteRendition = {
    swatches: BaseSwatch[][];
};

export type LibraryObjectRenditions = ElementColorSwatchRendition | ElementColorPaletteRendition;

/**
 * This field reflects legacy behavior from USS, so try to use storage:assignee, path, etc. if it is more applicable.
 * A few things to note:
 * 'private' is a library owned by the user and stored in the user's storage
 * 'incoming' is a bookmarked library in user or org storage, that is not owned by the session user and the user does not have read access to the directory
 * 'team' is a project library in either ESM or USM. Could by owned by session user, or not. Could be bookmarked, or not. (e.g. can be returned by the 'owner=incoming' or 'owner=other' filter.)
 * 'public' is any library owned by someone else that was shared publicly by link, and which the session user is following.
 * The rest, I am unsure if they are really returned. https://jira.corp.adobe.com/browse/CCXB-21079
 */
// https://git.corp.adobe.com/Stormcloud/melville/blob/integration/com.adobe.melville.core/src/main/java/com/adobe/melville/derivables/ownership/OwnershipDeriverImpl.java
// https://git.corp.adobe.com/Stormcloud/melville/blob/integration/com.adobe.melville.core/src/main/java/com/adobe/melville/dto/library/LibraryOwnershipScope.java#L45
export type Ownership = 'private' | 'public' | 'incoming' | 'outgoing' | 'team' | 'discovery' | 'other';

export type MelvilleCollaboration = {
    rootURN: string;
    ownerId: string;
    state: string;
    // role: 'owner' | 'viewer' | 'editor'; // ported from CCLibs Collaboration. Need to check if this is valid. [SHARED-4445]
    collaborators: MelvilleCollaborator[];
    invitations: MelvilleInvitation[];
    public: boolean;
    hasAdmin: boolean;
    _fc: boolean;
};

/**
 * SAM.js already defines class Collaborator to encapsulate a collaborator
 * returned by the Invitation Service, hence, MelvilleCollaborator.
 *
 * NOTE: Melville obtains the same collaborator data, but they process
 * it into a DbLibraryCollaboratorData before generating a
 * MelvilleCollaborator, omitting some of the original information,
 * so Collaborator and MelvilleCOllaborator are not interchangeable.
 *
 * You can find the response schema's on Melville's Swagger:
 * https://git.corp.adobe.com/pages/Stormcloud/apidocs/?urls.primaryName=melville#/Libraries/getLibrary
 */
export type MelvilleCollaborator = {
    email: string;
    displayName: string;
    collaborator: string;
    role: string;
    canComment: boolean;
    canShare: boolean;
    inheritanceType: 'DIRECT' | 'INHERITED';
    _fc?: boolean;
};

