// This is not part of Melville's response, but is added internally by SAM.js
// Melville only supplies a boolean `reference` property when a library is returned from a listing requested with the reference parameter for a specific project.
// This property is used to update the Library instance with the project ID that it is referenced by.
// see ProjectLibraryListLoader._decorateLibraryDataWithReferencedByProject for more details.
export type LibraryReferencedByProject = {
    projectId: string;
    reference?: boolean;
}

export type LibraryAssetId = string; // the urn used as the global asset identifier. This will be the id we use moving forwards.
// Legacy IDs:
export type LibraryManifestId = string; // the id of the dcx manifest, previously used as the library id (except on public libraries)
export type PublicLibraryId = string; // A special id for public libraries that looks like '1UIWQK2SZ5GWPJPLJMNVJS154OMEFF'
