type LibraryRemoteIdProperty = {
    library_urn: LibraryAssetId; // Equivalent to the asset id or cloudID. Required in the updater to identify or create the item in the pool.
};

// This data is always safe to pass to LibraryUpdater, as it will not overwrite RAPI data.
// These properties should be updated in Library > safePropertyUpdaterTypes.
export type LibrarySpecificData = LibraryRemoteIdProperty & {
    id: LibraryManifestId | PublicLibraryId;
    bookmark?: BookmarkData;
    name: string; // Gets saved to _displayName instead of _name so it does not overwrite RAPI data.
    ownership: Ownership;
    roles: LibraryRole[];
    'firefly#cme'?: CustomModelTrainingConfiguration;
    rendition_grid: LibraryRenditionGridData;
    thumbnail?: LibraryRenditionData; // This is the thumbnail
    referenced_by_project?: LibraryReferencedByProject;
    elements_count: number;
}

export type UpdateLibraryMetadataPayload = {
    name: string;
    roles: LibraryRole[];
    'firefly#cme'?: Partial<CustomModelTrainingConfiguration>;
    // id is intentionally commented out as we don't currently want to expose the ability to change the Library ID
    // id: string;
}

export type ParentAssetId = string;

// This captures the library level metadata in a Library response. The elements properties aren't returned here, as they are fetched separately by library.
export type LibraryData = LibrarySpecificData & {
    custom_models?: CustomModelInfoMelville[];
    toolkit_id?: string;
    storage_used?: number;
    document_id?: string;
    document_type?: string; // xd document type
    creator?: string;
    org_id?: string; // Equivalent to `storage_assignee?.type === 'org' && storage_assignee.id`. Only present on project libraries in ESM. EDIT: This will support the id of personal projects moving fowards as well.
    workspace_name?: string;
    workspace_urn?: ParentAssetId; // legacy property kept for backwards compatibility. Use the newer parent_assetId.
    application_metadata?: IAppMetadata; // seems to be returned on USM or ESM project libraries, regardless of the list selector
    created_date: number;
    modified_date: number;
    'repo:repositoryId': string;
    version: string;
    region?: string;
    storage_path?: string;
    elements_count: number;
    removed_elements_count: number;
    document_elements_count?: number;
    rendition_grid?: LibraryRenditionGridData;
    thumbnail?: LibraryRenditionData;
    collaboration?: MelvilleCollaboration;
    asset_acl: IEffectivePermissions;
    // Source: https://git.corp.adobe.com/Stormcloud/melville/blob/integration/com.adobe.melville.core/src/main/java/com/adobe/melville/db/dto/library/DbLibraryDetail.java
    details?: {
        manifest_id: LibraryManifestId; // Only place to find the manifest id on public libraries, but it is not used for anything.
        num_elements?: number;
        num_documentation_elements?: number;
        num_archived_elements?: number;
        types?: string[];
        element_type_counts?: { [key: string]: number };
        etag?: string;
        state?: string;
        manifest_format_version?: string;
        description?: string;
        'firefly#cme'?: CustomModelTrainingConfiguration;
        'brand#copyGuideLines'?: any;
    };
    groups?: GroupData[];
    _links: MelvilleLinks;
    searchable?: boolean;
    raw_name?: string;
    renditionGridMissing?: boolean;
    assetSubType?: string;
    _fc?: boolean;
    manifest_etag?: string; // This might not be present on older libraries
    is_searchable?: boolean;
    parent_assetId?: ParentAssetId; // any parent urn, whether project, sync group, or other folder. This should be mapped to the Asset's _ancestorIDs, but at the moment there is no client need to expose this.
    archived_date?: number;
    archived_by?: string;
    storage_assignee?: Assignee; // will not be present on public libraries
    created_by?: string;
    modified_by?: string;
    reference?: boolean; // whether the library is referenced by a project
    description?: string;
};

