/**
 * Enum for library owner filter
 * (If you update this list, also update LibraryFilter.matches/getRelationToFilter.)
 * @enum {string}
 */
export enum LibraryOwnerFilter {
    /**
     * Personal libraries created in User Storage that are specifically stored inside the sync group: `/assets/adobe-libraries`
     * Excludes CCI Project Libraries.
     */
    Personal = 'private',
    /**
     * Bookmarked public libraries.
     * Currently will be ignored if combined with other ownership types.
     */
    Public = 'public',
    /**
     * Bookmarked incoming libraries. This includes:
     * - Libraries shared directly with the user that the user has accepted the invite to
     * - CCI Project Libraries which live in User Storage (`/users/{userId}` in ESM, `/` in USM and for unified users)
     * - Project Libraries the user has followed (After SMU, these will all live in `/projects/{projectName}`)
     */
    Incoming = 'incoming',
    /**
     * Everything the user has acccess to that is not in User Storage, except public libraries.
     * Includes: Project libraries, Incoming libraries (except CCI Project Libraries since they are in User Storage)
     * Excludes: Public libraries, CCI Project Libraries, Private Libraries
     */
    Discovery = 'discovery',
    /**
     * A subset of 'discovery' that excludes already bookmarked libraries.
     */
    // Other = 'other',
    /**
     * All of the above except public libraries currently (until supported by USS).
     * If combined with other owner types, the others will be ignored.
     */
    All = 'all'
}

export enum LibraryProjectFilterEnum {
    /**
     * Include all project libraries.
     */
    All = 'all',
    /**
     * Do not include any project libraries.
     */
    None = 'none',
    /**
     * Include project libraries that the user is NOT a member of.
     */
    // Other = 'other'
}
/**
 * Project filter supports a project id or any value in the LibraryProjectFilterEnum
 */
export type LibraryProjectFilter = LibraryProjectFilterEnum | ProjectAssetId;

/**
 * @experimental API May change.
 *
 * Enum for library reference filter
 * This filter must be used in conjunction with a projectID via the LibraryProjectFilter.
 * @enum {string}
 */
export enum LibraryReferenceFilter {
    /**
     * Return all libraries beneath the project or referenced by the project
     */
    All = 'all',
    /**
     * Include only libraries referenced by the project
     */
    Only = 'only',
}

export enum LibraryRolesFilter {
    /**
     * Include libraries that have no roles
     */
    None = 'none',
    /**
     * Include libraries that have at least one role where role.type === 'brand'
     */
    Brand = 'brand',
    /**
     * Include training set libraries. Currently the default, as it is the only option.
     */
    TrainingSet = 'cm_training_set'
}

/**
 * This enum is used for filtering the library list view for brands specifically based on it's publishing related app metadata.
 * This filter is only usable if the brand role is true.
 *
 * There are three types of brands that exist in the data:
 * 1. Published brands -- These are the brands that have brand:publishedFrom in their app metadata.
 * Nobody is able to update these brands directly, they can only be updated by publishing changes from their draft brand counterpart (which is what brand:publishedFrom points to).
 *
 * 2. Draft brands with a published counterpart -- These are the brands that have brand:publishedTo in their app metadata.
 * These brands do NOT show up in the list of brands, but still can be accessed when a user goes to edit a published brand.
 * This is so we can maintain a "Draft" state for a published brand so brand creators can make revisions without updating the published copy that is currently in use.
 *
 * 3. Draft brands that are unpublished -- These are brands that are not part of a published brand in any way, and thus have neither brand:publishedFrom nor brand:publishedTo.
 * These brands are editable, and do show up in the brands listing view.
 */
export enum BrandPublishMetadataFilter {
    /**
     * Includes: Published brands
     *
     * Excludes: Unpublished draft brands, Draft brands with a published counterpart
     */
    PublishedBrands = 'publishedBrands',
    /**
     * Includes: Published brands, Unpublished draft brands
     *
     * Excludes: Draft brands with a published counterpart
     */
    AllBrands = 'allBrands',
    /**
     * Includes: Unpublished draft brands, Draft brands with a published counterpart
     *
     * Excludes: Published brands
     */
    AllEditableBrands = 'allEditableBrands'
}

type CommaDelimitedString = string;
/**
 * Selectors determine what data is returned in the libraries response. You may combine multiple in a comma delimited list.
 * default: only base data for a library (You do not need to specify this to get default data from the other selectors.)
 * rendition_grid: adds `rendition_grid` and `renditionGridMissing` to default data
 * collaboration: adds `collaboration` to default data
 * groups: adds `groups` to default data
 * details: adds `details` to the default data
 * app_metadata: <needs to be tested. `application_metadata` appears on team libraries without using this.>
 */
export type LibrarySelectors = 'default' | 'details' | 'collaboration' | 'groups' | 'rendition_grid' | 'app_metadata' | CommaDelimitedString;
export type OwnerParameters = LibraryOwnerFilter | CommaDelimitedString;
type ProjectAssetId = string; // urn of the project
type TeamParameters = LibraryProjectFilter;
type ReferenceParameters = LibraryReferenceFilter;
type LibraryCapabilities = 'write' | CommaDelimitedString;
export type RolesParameters = LibraryRolesFilter | CommaDelimitedString;
type ItemFilterParameters = BrandPublishMetadataFilter;
type ToolkitId = string;
type ToolkitParameter = 'all' | 'none' | ToolkitId | CommaDelimitedString;
type OrderBy = LibraryOrderBy.NAME | LibraryOrderBy.MODIFIED_DATE | LibraryOrderBy.CREATED_DATE | '-name' | '-created_date' | '-modified_date' | CommaDelimitedString; // Default: modified_date. Sorting is not available for public libraries.
/**
 * Query parameters from the GET /libraries endpoint via Melville's API
 * @see https://git.corp.adobe.com/pages/Stormcloud/apidocs/?urls.primaryName=melville#/Libraries/getLibraries
*/
export type LibraryListParameters = {
    owner?: OwnerParameters;
    team?: TeamParameters;
    roles?: RolesParameters;
    itemFilter?: ItemFilterParameters;
    toolkit?: ToolkitParameter;
    selector?: LibrarySelectors;
    capabilities?: LibraryCapabilities;
    workspace?: string;
    start?: number; // paging not available for public libraries. Default if undefined: 0. Required if there is a limit.
    limit?: number; // paging not available for public libraries. Default if undefined: 50. Limits greated than 50 will be capped at 50.
    orderBy?: OrderBy;
    references?: ReferenceParameters;
};


