import InterfaceBase from './InterfaceBase';
import type { IPolicyResponse, ITransferOfOwnershipPolicyValue } from './PolicyModel';

/**
 * Interface for interacting with the Adobe Policy service.
 * Handles policy evaluation and retrieval for organizations.
 */
export default class PolicyInterface extends InterfaceBase {
    /** Cache of in-flight or resolved Promise per org; at most one request per org at a time. */
    private _transferOfOwnershipDisabledCache = new Map<string, Promise<boolean>>();

    /**
     * Get the Policy service endpoint URL.
     *
     * @returns The base URL for the Policy service based on environment (stage or production)
     */
    private _getPolicyEndpoint(): string {
        const policyHost = this._core._environment.endpoints.POLICY_HOST;
        return `https://${policyHost}`;
    }

    /**
     * Retrieves policies for a given organization.
     *
     * @param orgId - The organization ID to retrieve policies for
     * @returns An array of policy objects for the organization
     * @throws {SAMError} when the HTTP request fails (thrown by InterfaceBase._fetch)
     * @throws {Error} when the response body is not valid JSON
     */
    async getPoliciesForOrganization(orgId: string): Promise<IPolicyResponse[]> {
        const href = `${this._getPolicyEndpoint()}/policy/organization/${encodeURIComponent(orgId)}`;

        const response = await this._fetch(href, {
            method: 'GET'
        });

        const data: any = await response.json();

        // The response shape is an array of entries, or a single entry
        const policies: IPolicyResponse[] = Array.isArray(data) ? data : (data ? [ data ] : []);
        return policies;
    }

    /**
     * Evaluates whether the transfer of ownership policy is disabled for an organization.
     * Results are cached per org (by Promise) so at most one request per org is in flight.
     *
     * Example response shape from policy API:
     * [
     *   {
     *     "name": "transferOfOwnership",
     *     "category": "security/content",
     *     "scope": "organization",
     *     "scopeId": "303A197C666341580A494119@AdobeOrg",
     *     "value": "{\"enabled\":false}"
     *   }
     * ]
     *
     * @param orgId - The organization ID to check the policy for
     * @returns true when transferOfOwnership is disabled, false otherwise (including when policy not found)
     * @throws {SAMError} when the HTTP request fails (thrown by InterfaceBase._fetch)
     */
    async isTransferOfOwnershipDisabled(orgId: string): Promise<boolean> {
        let promise = this._transferOfOwnershipDisabledCache.get(orgId);
        if (promise === undefined) {
            promise = this._fetchTransferOfOwnershipDisabled(orgId);
            this._transferOfOwnershipDisabledCache.set(orgId, promise);
            // On rejection, remove from cache so subsequent calls can retry (transient errors are not cached).
            promise.catch(() => {
                this._transferOfOwnershipDisabledCache.delete(orgId);
            });
        }
        return promise;
    }

    /**
     * Performs the policy request and parses the result. Used so we can cache the Promise per org.
     */
    private async _fetchTransferOfOwnershipDisabled(orgId: string): Promise<boolean> {
        const policies = await this.getPoliciesForOrganization(orgId);

        // Find the transferOfOwnership policy
        const policy = policies.find(p => p?.name === 'transferOfOwnership');
        if (policy && typeof policy.value === 'string') {
            try {
                const parsed: ITransferOfOwnershipPolicyValue = JSON.parse(policy.value);
                // Return true only if enabled is explicitly set to false
                // This ensures consistent behavior: missing/invalid enabled field is treated the same as unparseable JSON
                return parsed?.enabled === false;
            } catch {
                // If parsing fails, fall through and return false
            }
        }

        // Default: treat as not disabled when policy not found or cannot be parsed
        return false;
    }
}
