import type { CHANGE } from '../core/ChangeEvent';
import type { default as TypedEventEmitter, IEventMap } from '../core/TypedEventEmitter';
import type { ONS_MONITORING_STATUS_CHANGED, ONSAssetChangeEvent, ONSMonitoringStatusChangedEvent } from './ONSEvent';
import type { ONSObjectMap, ONSSubscription } from './ONSSubscription';

export type ONSHeaderKeys = 'x-api-key' | 'locale';
export type ONSHeaderMap = { [key in ONSHeaderKeys]?: string };

export const ONS_AUTH_HEADER = 'X-User-Token';

export interface ONSWorkerEventMap extends IEventMap {
    [CHANGE]: ONSAssetChangeEvent;
    [ONS_MONITORING_STATUS_CHANGED]: ONSMonitoringStatusChangedEvent;
}

export interface ONSWorkerInterface extends TypedEventEmitter<ONSWorkerEventMap> {
    get isActive(): boolean;
    get subscriptions(): ONSSubscription[];
    start(): Promise<void>;
    stop(): void;
    ensureReady(): Promise<boolean>;
    deinitialize(): Promise<boolean>;
    watch(objects: ONSObjectMap): Promise<void>;
}
