import type {
    IItemLoaderOptions,
    IItemLoader,
    ILoadedPage,
    ILoadNextPage,
} from '../core/ItemLoader';
import type { ISAMCorePrivate } from '../indexPrivate';
import { getMostRecentValidMutation } from '../utils/loaderUtils';
import type AdobeAsset from './AdobeAsset';
import { AdobeAssetUpdater } from './AdobeAsset';
import type AdobeAssetFilter from './AdobeAssetFilter';
import type { FavoriteAdobeAssetConfig } from './FavoriteAdobeAssetSource';

export default class FavoriteAdobeAssetLoader implements IItemLoader<FavoriteAdobeAssetConfig> {
    private _assetListId: string | undefined;
    constructor(private _core: ISAMCorePrivate) {}

    async loadPage(options: IItemLoaderOptions<FavoriteAdobeAssetConfig>) {
        return await this._loadPage(options);
    }

    get assetListId(): string | undefined {
        return this._assetListId;
    }

    // fetch a page of assets from the service
    // use the data to instantiate assets
    // build next page link and recursively call _loadPage if necessary
    // return ILoadedPage<FavoriteAdobeAssetConfig>
    private async _loadPage(
        options: IItemLoaderOptions<FavoriteAdobeAssetConfig>,
        after?: string
    ): Promise<ILoadedPage<FavoriteAdobeAssetConfig>> {
        const gqlManager = await this._core._getGQLManager();
        const { mediaTypes } = options.filter as AdobeAssetFilter;
        const { field, direction } = options.order;

        const { items: favorites, pageInfo, assetListId } = await gqlManager.getFavorites({
            first: options.loadOptions?.limit || 50,
            after,
            filter: mediaTypes ? { dc_format: [ ...mediaTypes ].sort() } : undefined,
            orderBy: {
                field: field === 'name' ? 'NAME' : 'CREATE_DATE',
                direction: direction === 'ascending' ? 'ASCENDING' : 'DESCENDING'
            }
        }, options.resource);
        if (assetListId) {
            this._assetListId = assetListId;
        }

        const latency = this._core._environment.getValue('GQL_LIST_UPDATE_LATENCY');
        const mostRecentValidMutation = getMostRecentValidMutation(options.resource, latency);
        const session = this._core
            ._getAssetPool()
            .createLoaderUpdateSession<AdobeAsset>(mostRecentValidMutation);
        const items = AdobeAssetUpdater.updateRemoteItems(
            session,
            favorites
        );

        session.commit();

        let loadNextPage: ILoadNextPage<FavoriteAdobeAssetConfig> | undefined;
        if (pageInfo.hasNextPage) {
            loadNextPage = (options: IItemLoaderOptions<FavoriteAdobeAssetConfig>) =>
                this._loadPage(options, pageInfo.endCursor!);
        }

        return {
            items,
            loadNextPage,
            assetListId,
            mostRecentValidMutation,
            // TODO: request total count come back as apart of AssetListConnection
            // total: data.total
        };
    }
}
