/**
 * SingleOperation
 * @packageDocumentation
 * @module SingleOperation
 * @internal
 */

import type { Action } from '../models/Action';

import type { ExecuteResult } from './Operation';
import Operation, { validatesOperation } from './Operation';

/**
 * SingleOperation
 *
 * An operation that can only contain one action.
 */
export default abstract class SingleOperation<T> extends Operation<T> {
    protected _actionMappers: { [s: string]: (action: Action) => Promise<Action> } = {};

    protected get action() {
        return this._actions[0];
    }

    @validatesOperation
    async execute(): Promise<ExecuteResult> {
        // TODO: Clean me up
        const action = await (this._actionMappers as any)[this.action.name || ''](this.action);
        return { actions: [ action ] };
    }

    addAction(action: Action) {
        if (this._actions.length === 1) {
            return false;
        }

        return super.addAction(action);
    }
}
