import type {
    IItemLoader,
    IItemLoaderOptions,
    ILoadedPage,
} from '../core/ItemLoader';
import type { IServiceLink } from '../interface/LinkUtils';
import type StudentAssignment from './StudentAssignment';
import type { StudentAssignmentFileConfig } from './StudentAssignmentFileSource';
import type { ISAMCorePrivate } from '../indexPrivate';
import type StudentAssignmentsInterface from '../interface/StudentAssignmentsInterface';
import type StudentAssignmentFile from './StudentAssignmentFile';
import { getMostRecentValidMutation } from '../utils/loaderUtils';

export default class StudentAssignmentFilesListLoader
implements IItemLoader<StudentAssignmentFileConfig> {
    private _core: ISAMCorePrivate;
    private _studentAssignmentsInterface: StudentAssignmentsInterface;

    constructor({ core, studentAssignmentsInterface }: {core: ISAMCorePrivate, studentAssignmentsInterface: StudentAssignmentsInterface}) {
        this._core = core;
        this._studentAssignmentsInterface = studentAssignmentsInterface;
    }

    async loadPage(
        options: IItemLoaderOptions<StudentAssignmentFileConfig>
    ): Promise<ILoadedPage<StudentAssignmentFileConfig>> {
        return await this._loadPage(options);
    }

    private async _loadPage(
        options: IItemLoaderOptions<StudentAssignmentFileConfig>,
        // eslint-disable-next-line @typescript-eslint/no-unused-vars -- TODO: https://jira.corp.adobe.com/browse/ACPCEDU-405 add support for paging or remove this
        pageLink?: IServiceLink
    ): Promise<ILoadedPage<StudentAssignmentFileConfig>> {
        const mostRecentValidMutation = getMostRecentValidMutation(options.resource);
        const { studentAssignmentId } = options.implicitFilter;
        const cachedStudentAssignment = this._core._getAssetPool().getLocalItemById<StudentAssignment>(studentAssignmentId);
        let studentAssignmentFiles = cachedStudentAssignment?.studentAssignmentFiles ?? [];

        let profileId: string | undefined;
        // The cached StudentAssignment may belong to another profile of
        // the user and to get the StudentAssignment across profiles,
        // we need to pass the profile ID to the API.
        if (cachedStudentAssignment) {
            profileId = cachedStudentAssignment.student.id;
        }

        if (cachedStudentAssignment && cachedStudentAssignment._hasLoadedChildren) {
            /**
             * If we already have loaded both the StudentAssignment and its files,
             * then we can just link them since they are all already in the pool.
             *
             * Includes any relevant SAFs that have been cached as AdobeAssets
             * which occurs if the file was cached prior to being moved into
             * a StudentAssignment.
             * [ACPCEDU-3290] will introduce a longer-term approach for handling this behavior
             * to support other/future cases where the asset type changes over time
             */
            studentAssignmentFiles = this._core._getAssetPool().toArray().filter(
                (item) => item.studentAssignmentId === studentAssignmentId
            ) as StudentAssignmentFile[];
        } else if (studentAssignmentFiles.length === 0) {
            // If the StudentAssignment was not yet loaded, or if it was loaded without
            // the files, then we need to fetch the files from the server.
            const studentAssignmentMetadata = await this._studentAssignmentsInterface.getStudentAssignment(studentAssignmentId, { loadDocuments: true, profileId });
            const assignmentId = studentAssignmentMetadata['classroom:context']['classroom:assignmentContext']['classroom:assignmentAssetId'];
            const classroomId = studentAssignmentMetadata['classroom:context']['classroom:classroomContext']['classroom:classroomAssetId'];
            const session = this._core._getAssetPool().createMutationSession<StudentAssignmentFile>();
            studentAssignmentFiles = this._core.classroomContext._updateStudentAssignmentFilesCache({ remoteStudentAssignmentFiles: studentAssignmentMetadata.children, session, assignmentId, classroomId, studentAssignmentId });
            if (cachedStudentAssignment) {
                cachedStudentAssignment._hasLoadedChildren = true;
            }
        }

        return {
            items: studentAssignmentFiles,
            total: studentAssignmentFiles.length,
            mostRecentValidMutation,
        };
    }
}
