// Defines the new APIs for CCLibraries that are currently in use.
// Note that though these are public methods on the class, this class is no longer exposed directly to the client,
// so there is no need to add this to component-types.
// When all APIs are supported and the rest deprecated, we could actually replace ICCLibraries with CCLibraries itself.
// Note: As you add APIs here, enable the respective tests.
export interface ICCLibraries {
    assetPool: ItemPool<SAMLibrary | AdobeAsset>;
    elementPool: ItemPool<Element, ElementPoolId>;
    elementUpdater: typeof ElementUpdater;
    apiRoot: ICCLibraries;
    driver: Driver;
    cloudDriver?: CloudDriver;
    getOption: (key: keyof typeof LibraryConstants) => any;
    getLibraryContents(library: SAMLibrary): LibraryContents;
}

export type CCLibrariesOptions = {
    elementTypes?: ('elements' | 'removedElements' | 'documentationElements')[];
    renditionSizes?: RenditionSizeConfig;
    fullRenditionConfig?: FullRenditionConfig;
    readOnly?: boolean;
    cloudDriver?: CloudDriver;
    disableLocalFallthrough?: boolean;
    disablePreemptiveLibraryLoad?: boolean;
    disableFallbackDefaultLibrary?: boolean;
    enableBrandLifecycleManagement?: boolean;
    includeApprovedBrandsInLibraries?: boolean;
    skipConnectingOnInit?: boolean;
    mobXCreateAtom?: CreateAtom;
    mobXTransaction?: Transaction;
    locale?: SupportedLocale;

    /**
     * An API key for Ingest for analytics reporting. This property is optional, but must be set if reporting metrics.
     */
    ingestApiKey?: string;

    /**
     * Information about the host application. This property is optional, but must be set if reporting metrics.
     *
     * @remarks
     * The code and version of the application is preferred. Example: "PHXS/1.2.3" for Photoshop.
     */
    product?: string;

    /**
     * Information about the client who is reporting metrics. This property is optional, but must be set if reporting metrics.
     *
     * @remarks
     * The name and version of the application is preferred. Example: "CCLibrariesPanel/1.2.3".
     */
    productLocation?: string;

    /**
     * Whether running on desktop, mobile. This property is optional. It is used when reporting metrics.
     */
    platform?: 'DESKTOP' | 'MOBILE';

    /**
     * Information about the IMS session. This property is optional. It is used when reporting metrics.
     */
    sessionGuid?: string;

    /**
     * The license state of the user. Examples: 'subscription', 'paid', 'expired', 'trial', 'team_trial', 'team_trial_expired'.
     * This property is optional. It is used when reporting metrics.
     */
    userAccountStatus?: string;

    /**
     * The set of WIP features to enable.
     */
    featureFlags?: {
        enableProjects?: boolean;
        enableGenStudioAPIs?: boolean;
    };

    /**
     * Optional caching system to use if IndexedDB is not available. CCLibraries will use IndexedDB for caching
     * when available. This option provides a way to read and write files, as well as a directory to store the
     * cache file in.
     *
     * Note: The directory should be a fully resolved path and end with a path separator.
     */
    fileSystemCache?: { fs: FileSystem; dir: string };
};

