import type { IPropertyTypeMap } from '../core/PropertyUpdater';
import PropertyUpdater from '../core/PropertyUpdater';
import ItemBase from '../core/ItemBase';
import { observable } from '../core/decorators';
import { PostModerationStatus, type PostType } from '../interface/BoardModel';
import type BoardContext from './BoardContext';
import { BoardMemberRole, PostRemoteType, type RemotePostOwner, PostTypeMap } from '../interface/BoardModel';
import type Board from './Board';
import type { ISAMCorePrivate, ISAMObject } from '../indexPrivate';
import { PostOwner } from './PostOwner';
import type { SAM } from '@ccx-public/component-types';
import SAMError, { SAMErrorCode } from '@sam-js-src/core/SAMError';

/** Represents a post for a Board */
class Post extends ItemBase implements SAM.Post {
    private _type!: PostRemoteType;
    private _name!: string;
    private _created!: Date;
    private _createdTimestamp!: string;
    private _modified!: Date;
    private _description: string | undefined = undefined;
    private _descriptionStatus: PostModerationStatus | undefined = undefined;
    private _boardId: string = '';
    private _owner!: PostOwner;
    private _boardContext: BoardContext | undefined = undefined;

    constructor(readonly _core: ISAMCorePrivate, id: string) {
        super(_core, id);

        this._core.getBoardContext().then((boardContext) => {
            this._boardContext = boardContext;
        });
    }

    /**
     * Ensures that the board context has been fetched before using it
     * @throws {SAMError} if the board context is not initialized
     * @package -- for SAM.js internal use only
     */
    protected _ensureBoardContext(): BoardContext {
        if (!this._boardContext) {
            throw SAMError.create(SAMErrorCode.INTERNAL_ERROR, 'Board context not initialized');
        }
        return this._boardContext;
    }

    /** The ID of the board that the post belongs to */
    @observable
    get boardId(): string { return this._boardId; }

    /** The type of the post */
    @observable
    get type(): PostType {
        return PostTypeMap.toA(this._type);
    }

    /** The name of the post */
    @observable
    get name(): string { return this._name; }

    /** The date the post was created */
    @observable
    get created(): Date { return this._created; }

    /**
     * The timestamp of when the post was created
     * @package -- for SAM.js internal use only
     */
    @observable
    get createdTimestamp(): string { return this._createdTimestamp; }

    /** The date the post was modified */
    @observable
    get modified(): Date { return this._modified; }

    /** The description of the post */
    @observable
    get description(): string | undefined { return this._description; }

    /** The owner of the post */
    @observable
    get owner(): PostOwner { return this._owner; }

    /** Returns whether the current post can be deleted */
    @observable
    get isDeletable(): boolean {
        const board = this._getBoard();
        // if the board is a published board (published from another board), then the post cannot be deleted
        // if the board is not found, then the post cannot be deleted
        if (board === undefined || board.isPublishedFromAnotherBoard) {
            return false;
        }
        // only board owner or the post owner can delete the post
        return this.isOwner || board.role === BoardMemberRole.OWNER;
    }

    /** Returns whether the current post can be edited */
    @observable
    get isEditable(): boolean {
        // the post is editable only if the current user is the owner of the post or the board
        // if the board is a published board (published from another board), then the post cannot be edited
        // this logic is the same as isDeletable
        return this.isDeletable;
    }

    /** Returns whether the current user is the owner of the post */
    @observable
    get isOwner(): boolean {
        return this._owner.userId === this._core._environment.getUserId();
    }

    /** Returns the board that the post belongs to */
    private _getBoard(): Board | undefined {
        return this._core._getAssetPool().getLocalItemById<Board>(this._boardId);
    }

    /** Returns the moderation status of the post description. Returns undefined if there is no description. */
    @observable
    get descriptionStatus(): PostModerationStatus | undefined {
        return this._descriptionStatus;
    }

    /**
     * Triggers the reclassification of the Post description through ACMP
     * @experimental Text moderation work is in progress
     */
    async reclassifyDescription(): Promise<void> {
        return this._ensureBoardContext().reclassifyPostDescription({ boardId: this.boardId, postId: this.id });
    }

    /**
     * Approves a Post's description/caption that has been flagged for review.
     * @experimental Text moderation work is in progress
     */
    approveDescription(): Promise<void> {
        return this._ensureBoardContext().approvePostDescription({ boardId: this.boardId, postId: this.id });
    }

    /**
     * Rejects a Post's description/caption that has been flagged for review.
     * @experimental Text moderation work is in progress
     */
    rejectDescription(): Promise<void> {
        return this._ensureBoardContext().rejectPostDescription({ boardId: this.boardId, postId: this.id });
    }
}

const getChildPostUpdater = (map: IPropertyTypeMap) =>  new PropertyUpdater({
    _boardId: { name: 'computedBoardId', format: 'string' },
    _name: { name: 'name', format: 'string' },
    _type: { name: 'type', format: 'string', choices: Object.values(PostRemoteType) },
    _description: { name: 'board#postDescription', format: 'string' },
    _modified: { name: 'modified', format: 'date' },
    _created: { name: 'created', format: 'date' },
    _createdTimestamp: { name: 'created', format: 'string' },
    _backgroundColor: { name: 'board#postBackgroundColor', format: 'string' },
    _descriptionStatus: { name: 'board#postDescriptionStatus', format: 'string', choices: Object.values(PostModerationStatus) },
    _owner: {
        name: 'postedBy',
        format: 'object',
        set: (parsedSource: RemotePostOwner, dest: ISAMObject) => {
            const post = dest as Post;
            const postOwner = new PostOwner(parsedSource);
            post['_owner'] = postOwner;
        }
    },
    ...map,
});

export default Post;
export { getChildPostUpdater };
