import type ISAMCorePrivate from '../core/ISAMCorePrivate';
import type { ISAMObject } from '../core/ISAMObject';
import AdobeACL from './AdobeACL';
import AdobeACE from './AdobeACE';
import type { IAccessControlEntryResponse } from './AccessControlModel';
import AssetInterface from '../interface/AssetInterface';
import { key, cache } from '../core/decorators';
export default class AccessControlContext implements ISAMObject {
    private _aclCache: Map<string, WeakRef<AdobeACL>> = new Map();
    constructor(
        public _core: ISAMCorePrivate
    ) {}

    private _getCachedACL(assetId: string): AdobeACL | undefined {
        const localACL = this._aclCache.get(assetId);
        if (localACL) {
            const aclDeref = localACL.deref();
            if (aclDeref) {
                return aclDeref;
            }
        }
        return undefined;
    }

    /**
     * Get the asset interface for the asset using memoize to increase session performance.
     * If the AssetId is found locally in the asset pool we can just get
     * the asset interface from that, otherwise let's construct just the asset
     * interface we need to get the access control list. This way we won't have to
     * use the full getAssetWithCloudID method (which fetches a lot of data). And we
     * can avoid only creating an AdobeAsset when we only have RepoMetadata.
     *
     * @param assetId - The ID of the asset to get the asset interface for.
     * @returns The asset interface for the asset.
     */
    @cache
    private async _getAssetInterface(@key assetId: string): Promise<AssetInterface> {
        // Get the asset interface for the asset
        const localAsset = this._core._getAssetPool().getLocalItemById(assetId);
        let assetInterface;
        if (localAsset) {
            assetInterface = await localAsset._getAssetInterface();
        } else {
            const assetContext = await this._core.getAssetContext();
            // Fetch a minimalist version of AdobeAsset if it doesn't exist already to
            // avoid fetching more data than we need.
            const assetRepoData = await assetContext._getAssetRepoDataWithCloudID(assetId);
            assetInterface = new AssetInterface(
                assetContext._rapi,
                assetId,
                assetRepoData.data._links,
                assetRepoData.data['repo:etag']
            );
        }
        return assetInterface;
    }

    /**
     * Get the access control list for an asset.
     *
     * @note An empty array returned means  ACEs have been set on the asset or this client-id user doesn't
     * have access to see the ACL.
     *
     * @param assetId - The ID of the asset to get the access control list.
     * @param forceRefresh - If true, the ACL and it's ACEs will be refreshed from the server and not pulled from the cache.
     * useful when the service returns a 200 response because the ACL was updated but the cache was not updated.
     *
     * @note with forceRefresh = true, local changes to ACE's will be overwritten without error.
     */
    async getACL(assetId: string, forceRefresh: boolean = false): Promise<AdobeACL> {
        const localACL = this._getCachedACL(assetId);
        if (localACL && !forceRefresh) {
            return localACL;
        }

        const assetInterface = await this._getAssetInterface(assetId);
        const aclResponse = await assetInterface.getAccessControlList();

        const mapACES = (ace: IAccessControlEntryResponse, index: number) => {
            return new AdobeACE(
                this._core,
                index,
                ace['repo:privileges'],
                ace['repo:modifier'],
                ace['repo:inheritance'],
                ace['repo:relations'],
                ace['repo:principal']
            );
        };

        // Clear the entire list of ACEs on the ACL if we are forcing a refresh
        // and after all the calls to the services have settled successfully this way we don't
        // prematurely remove local ACEs before we get new ones from the server.
        // We also set the _isDeleted property to true for each ACE so that clients
        // will get an error when they try to make any changes to a deleted ACE.
        if (localACL && forceRefresh) {
            localACL.aces.forEach((ace: AdobeACE) => {
                ace._isDeleted = true;
            });
            localACL.aces = [];
        }

        if (localACL) {
            localACL.aces = aclResponse['repo:acl'].map(mapACES);
            localACL.etag = aclResponse['etag'];
            return localACL;
        }

        // ACL doesn't exist in the cache, create a new one.
        // and return it to the caller.
        const acl = new AdobeACL(
            this._core,
            assetId,
            aclResponse['etag'],
            aclResponse['repo:acl'].map(mapACES),
            assetInterface
        );

        this._aclCache.set(
            assetId,
            new WeakRef(acl)
        );
        return acl;
    }
}
