import type InvitationInterface from '../interface/InvitationInterface';
import type InvitedCollaborator from './InvitedCollaborator';
import { InvitedCollaboratorUpdater } from './InvitedCollaborator';
import type { IItemLoader, ILoadedPage } from '../core/ItemLoader';
import type ItemPool from '../core/ItemPool';
import type { InvitedCollaboratorConfig } from './InvitedCollaboratorSource';

export default class InvitedCollaboratorLoader implements IItemLoader<InvitedCollaboratorConfig> {

    constructor(
        private _invitedCollaboratorPool: ItemPool<InvitedCollaborator>,
        private _invitationInterface: InvitationInterface,
        private _urn: string) {
    }

    async loadPage(): Promise<ILoadedPage<InvitedCollaboratorConfig>> {
        // FIXME: Implement latency tracker once we move more collaborator operations into SAM.JS.

        // Note, this request is piggy-backed, so if we load both the collaborators and invited collaborators at the same
        // time, it only results in one network call
        const result = await this._invitationInterface.getCollaborators(this._urn);

        // Update the pending invitations
        const invitedCollaboratorUpdateSession = this._invitedCollaboratorPool.createLoaderUpdateSession(Date.now());
        const invitedCollaborators = InvitedCollaboratorUpdater.updateRemoteItems(invitedCollaboratorUpdateSession, result.invitations);
        invitedCollaboratorUpdateSession.commit();

        return { items: invitedCollaborators };
    }
}
