import type { IExplicitFilter, ItemFilterRelation } from '../core/ItemFilter';
import type AdobeAsset from './AdobeAsset';

export enum IsSharedViewSelection { ALL, YOURS, SHARED_WITH_YOU/*, SHARED_VIA_PROJECT*/ }


export type IsSharedFilterOptions = {
    isSharedWithYou?: boolean;
    ownedBy?: string
}

export default class IsSharedFilter implements IExplicitFilter<AdobeAsset> {
    constructor(public options?: IsSharedFilterOptions) {}

    get hash(): string {
        return `isShared=${this.options?.isSharedWithYou ?? 'all'}:createdBy=${this.options?.ownedBy ?? 'any'}`;
    }

    getRelationToFilter(other: IsSharedFilter): ItemFilterRelation {
        // we're filtering both this and other, but not the same filter
        if ((this.options?.isSharedWithYou !== undefined) && (other.options?.isSharedWithYou !== undefined) && this.options.isSharedWithYou !== other.options.isSharedWithYou) {
            return 'disjoint';
        }

        if (this.options?.ownedBy && other.options?.ownedBy && (this.options.ownedBy !== other.options.ownedBy)) {
            return 'disjoint';
        }

        // we're filtering other, but not this, so we can partially seed from the other list but it won't have a full list
        if ((this.options?.isSharedWithYou === undefined) && (other.options?.isSharedWithYou !== undefined)) {
            return 'unknown';
        }

        if ((this.options?.ownedBy === undefined) && (other.options?.ownedBy !== undefined)) {
            return 'unknown';
        }

        // either the other filter has a full list or the filters are the same
        // either way, we can seed the new list completely from the other one
        return 'subset';
    }

    matches(item: AdobeAsset): boolean {
        if (this.options?.isSharedWithYou === undefined && this.options?.ownedBy === undefined) {
            return true; // no specific view filter, match all
        }

        // _isSharedWithYouAsset undefined means not loaded yet
        if (this.options?.isSharedWithYou && !item._isSWYAsset_NoLazyLoad) {
            return false;
        }

        if ((this.options?.isSharedWithYou === false) && (item._isSWYAsset_NoLazyLoad !== false)) {
            return false;
        }

        if (this.options?.ownedBy && (item._storageAssignee_NoLazyLoad?.id !== this.options.ownedBy)) {
            return false;
        }

        return true;
    }
}
