/**
 * Melville APIs for reading/writing Libraries data.
 * Warning: The libraries listings for non-public libraries returned from GET /libraries, and results for /search, may have stale data due to USS indexing delays.
 * However, Melville will always return the latest data from platform when fetching a specific library from GET /library/:id.
 */

import InterfaceBase from './InterfaceBase';
import { JSON_MIME_TYPE } from './LinkUtils';
import type { HeaderMap } from './LinkUtils';
import { fillURLTemplate } from './LinkUtils';
import type {
    AccessOption,
    BookmarkData,
    BookmarksResponse,
    CopyLibraryRequest,
    CreateLibraryOptions,
    LibraryData,
    MoveLibraryRequest,
    LibrariesResponse,
    LibraryListParameters,
    MelvilleLink,
    UpdateLibraryMetadataPayload,
    SearchLibraryRequest,
    LibrarySelectors
} from './LibraryModel';
import SAMError, { SAMErrorCode } from '../core/SAMError';

interface IMelvilleRestoreContextQuery {
    'self': {
        'id': string;
        'elements': string[];
    }
}

function parseLibraryAndElementID(libraryElementID: string): string[] {
    const parts = libraryElementID.split(':');
    const elementID = parts.pop() as string;
    const libraryID = parts.join(':');
    return [ elementID, libraryID ];
}

function getLibraryAccessOption(restrictEdit?: boolean): AccessOption | '' {
    if (restrictEdit === true) {
        return 'team_view';
    } else if (restrictEdit === false) {
        return 'team_edit';
    } else {
        return '';
    }
}

/**
 * Given a libraries or elements listing URL, move the supported query params to headers.
 * This avoids extra CORS preflight OPTIONS requests per unique url.
 * @param melvilleUrl - supports both full url and path only, with query params
 * @returns tuple of [path, headers], with the path truncated of the query params that were moved to headers
 */
export function moveUrlQueryParamsToHeaders(melvilleUrl: string): [string, HeaderMap] {
    // The below query params are supported as headers
    // Note: 'owner' is supported by libraries list, and 'type' and 'group' is supported for elements list
    const MelvilleParamsAsHeaders = [ 'start', 'limit', 'selector', 'type', 'orderBy', 'group', 'owner' ];

    const [ path, query ] = melvilleUrl.split('?');
    const urlParams = new URLSearchParams(query); // create obj from query and encode params if they aren't already
    const headers: HeaderMap = {};

    MelvilleParamsAsHeaders.forEach(paramAsHeader => {
        const value = urlParams.get(paramAsHeader);
        if (value) {
            headers[paramAsHeader] = value;
            urlParams.delete(paramAsHeader);
        }
    });
    const urlParamsString = `${urlParams}`;
    const url = urlParamsString.length > 0 ? `${path}?${urlParamsString}` : path;

    return [ url, headers ];
}

// Sort parameters so that the query string is stable, preventing unnecessary cache misses.
const sortParameters = (parameters: LibraryListParameters): LibraryListParameters => {
    return Object.fromEntries(
        Object.entries(parameters)
            .map(([ key, value ]) => {
                if (Array.isArray(value)) {
                    return [ key, value.sort() ];
                }
                return [ key, value ];
            })
            .sort()
    );
};

export default class LibraryInterface extends InterfaceBase {

    private _getUrl(endpoint: string): string {
        return `https://${this._core._environment.endpoints.MELVILLE_HOST}${endpoint}`;
    }

    private _getEdgeUrl(endpoint: string): string {
        return `https://${this._core._environment.endpoints.MELVILLE_EDGE_HOST}${endpoint}`;
    }

    async getLibraryData(libraryId: string, options?: { selectors?: LibrarySelectors[], isDiscarded?: boolean}): Promise<LibraryData> {
        const selectors = options?.selectors ? options.selectors : [];
        const isDiscarded = options?.isDiscarded || false;

        // dedupes, sorts, and ensures selectors contains rendition grid
        const sortedSelectors = Array.from(new Set([ 'rendition_grid', 'collaboration', ...selectors ])).sort().join(',');
        const url = isDiscarded ? this._getUrl(`/api/v1/archive/${libraryId}`) : this._getEdgeUrl(`/api/v1/libraries/${libraryId}`);

        return await this._getResponse(
            // Sort selectors so that the query string is stable, preventing unnecessary cache misses.
            `${url}?selector=${sortedSelectors}`,
            {
                // Ensure browser doesn't automatically add If-None-Match, otherwise
                // service may respond with cached data for a library
                headers: { ['Cache-Control']: 'no-cache, no-store, max-age=0' }
            }
        );
    }

    // Warning: the libraries listing returned from /libraries may have stale data due to USS indexing delays.
    // The exception to this is public libraries as those are fetched from platform, for now.
    // (Other calls, such as fetching library data by ID, will always return the latest data from platform.)
    // Update only LibrarySpecificData to avoid overwriting RAPI data if you are worried about this.
    async getLibraries(queryParams: LibraryListParameters): Promise<LibrariesResponse> {
        if (queryParams?.limit && queryParams?.start === undefined) {
            throw SAMError.create(SAMErrorCode.BAD_REQUEST, '[Melville] If limit is provided, start must also be provided.');
        }
        queryParams = sortParameters(queryParams);
        const urlWithQueryParams = fillURLTemplate(
            this._getEdgeUrl('/api/v1/libraries'),
            queryParams
        );
        // Pass as many parameters as headers as we can, to avoid extra CORS preflight OPTIONS requests per url.
        const [ url, headers ] = moveUrlQueryParamsToHeaders(urlWithQueryParams);
        // Ensure browser doesn't automatically add If-None-Match, otherwise
        // service may respond with cached data for a library
        const defaultHeaders: HeaderMap = {
            ['Cache-Control']: 'no-cache, no-store, max-age=0',
            // 'public-libraries-list-v2' is Melville's feature flag for durable links.
            // The main change for SAM.js is that a public library's ID will be the
            // manifest ID (UUID) instead of the legacy public library ID. This ID is
            // mapped to `_legacyLibraryId` in the SAM.js' Library asset.
            directive: 'public-libraries-list-v2'
        };
        const finalHeaders = { ...defaultHeaders, ...headers };

        return await this._getResponse(url, { headers: finalHeaders });
    }

    // TODO[SHARED-975]: This will need to return the json response for pagination.
    async getLibrariesForProject(projectId: string): Promise<LibraryData[]> {
        const response = await this.getLibraries({ team: projectId, selector: 'rendition_grid,collaboration,details' });
        return response.libraries;
    }

    async getLibrariesWithLink(pageLink: MelvilleLink): Promise<LibrariesResponse> {
        // The link will not include headers, so we will need switch query params to headers to reduce OPTIONS requests.
        const [ url, headers ] = moveUrlQueryParamsToHeaders(this._getEdgeUrl(pageLink.href));
        return await this._getResponse(url, { headers });
    }

    // The assetId's passed to restoreLibraryElement() and permanentlyDeleteLibraryElement() are in the
    // form 'LIBRARY_CLOUD_ID:ELEMENT_GUID', i.e:
    // 'urn:aaid:sc:us:2be71fea-f24b-4c10-a6a9-4f0926bda772:0fad1009-3bc1-4119-9227-5d1889ffcaf2'
    // I filed https://jira.corp.adobe.com/browse/SAM-2683 to support batch restore/permanentDelete operations which in
    // this workflow would allow us to make just one request to restore/permanentlyDelete multiple CCLibrary Elements that
    // belong to the same CCLibrary.

    async restoreLibraryElement(assetId: string): Promise<void> {
        const [ elementID, libraryID ] = parseLibraryAndElementID(assetId);
        const body: IMelvilleRestoreContextQuery = { self: { id: libraryID.toString(), elements: [ elementID ] } };
        await this._doPost(
            this._getEdgeUrl(`/api/v1/libraries/${libraryID}/archive`),
            { 'Content-Type': 'application/json' },
            JSON.stringify(body),
            [ 200 ]);
    }

    async permanentlyDeleteLibraryElement(assetId: string): Promise<void> {
        const [ elementID, libraryID ] = parseLibraryAndElementID(assetId);
        await this._doDelete(
            this._getEdgeUrl(`/api/v1/libraries/${libraryID}/archive/${elementID}`),
            { 'Content-Type': 'application/json' },
            [ 204 ]);
    }

    async discardLibrary(assetId: string): Promise<void> {
        await this._doDelete(
            this._getEdgeUrl(`/api/v1/libraries/${assetId}`),
            { 'Content-Type': 'application/json' },
            [ 204 ]);
    }

    async permanentlyDeleteLibrary(assetId: string): Promise<void> {
        await this._doDelete(
            this._getEdgeUrl(`/api/v1/libraries/${assetId}?permanent=true`),
            { 'Content-Type': 'application/json' },
            [ 204 ]);
    }

    async restoreLibrary(assetId: string): Promise<void> {
        const body: any = { self: `/api/v1/archive/${assetId}` };
        await this._doPost(
            this._getEdgeUrl(`/api/v1/libraries`),
            { 'Content-Type': 'application/json' },
            JSON.stringify(body),
            [ 201 ]);
    }

    async copyLibrary(assetId: string, destName?: string, parentAssetID?: string, restrictEdit?: boolean): Promise<LibraryData> {
        const accessString = getLibraryAccessOption(restrictEdit);
        const body: CopyLibraryRequest = {
            source: assetId,
            // unspecified optionals are omitted from the request body
            ...(destName && { name: destName }),
            ...(accessString && { access: accessString }),
            ...(parentAssetID && { parent_assetId: parentAssetID })
        };

        const response = await this._doPost(
            this._getEdgeUrl(`/api/v1/libraries`),
            { 'Content-Type': 'application/json' },
            JSON.stringify(body),
            [ 200, 201 ]);

        return await response.json();
    }

    async moveLibrary(assetId: string, parentAssetID: string, restrictEdit?: boolean): Promise<LibraryData> {
        const accessString = getLibraryAccessOption(restrictEdit);
        const body: MoveLibraryRequest = {
            self: assetId,
            parent_assetId: parentAssetID,
            'repo:manifestPatch': [ { 'op': 'replace', 'path': '/id', 'value': assetId } ]
        };
        if (accessString !== '') {
            body['access'] = accessString;
        }

        const headers: HeaderMap = {
            'Content-type': 'application/json'
        };

        // If the client has not set the 'enable-x-bucket-move' (deprecated) or 'enable-ops-2021-move' feature
        // flags to 'true', add the disable-x-bucket-move header to the request to ensure that cross bucket
        // moves are disabled in Melville.
        // Cross-bucket moves occur when the storage-assignee of the source and destination are different.
        if (!this._core._environment._getCrossBucketMoveEnabled()) {
            headers['disable-x-bucket-move'] = 'true';
        }

        const response = await  this._doPost(
            this._getEdgeUrl(`/api/v1/libraries`),
            headers,
            JSON.stringify(body),
            [ 200, 201 ]);

        return await response.json();
    }

    /**
     *
     * @param nameOrOptions - For backward compatability, this can be a string representing the name of the library to create.
     *                      If an object is passed, it should be a CreateLibraryOptions object.
     * @returns LibraryData - The created library data from the response. This will include the ID of the created library.
     */
    async createLibrary(nameOrOptions: string | CreateLibraryOptions): Promise<LibraryData> {
        let options: CreateLibraryOptions;
        let url: string = `/api/v1/libraries`;

        if (typeof nameOrOptions === 'string') {
            options = { name: nameOrOptions };
        } else if (typeof nameOrOptions === 'object') {
            options = nameOrOptions;
            url = options.syncCreate ? `/api/v1/libraries?invocation_mode=sync` : `/api/v1/libraries`;
        } else {
            throw new Error('Invalid arguments');
        }

        /* eslint-disable-next-line @typescript-eslint/no-unused-vars */
        const { syncCreate, ...requestOptions } = options;
        const response = await this._doPost(
            this._getEdgeUrl(url),
            { 'Content-Type': 'application/json' },
            JSON.stringify(requestOptions),
            [ 201, 200 ]);

        return await response.json();
    }

    /**
     * Follow aka bookmark one or more libraries.
     * @param bookmarks - array of BookmarkData objects
     * Required properties: In each bookmark, besides the id, you must include either urn for collaborated libraries or url for public libraries.
     * @returns BookmarksResponse - contains all the bookmarks for the user of the same type(s) that were created (public or collab or both)
     */
    async bookmarkLibraries(bookmarks: Partial<BookmarkData>[]): Promise<BookmarksResponse> {
        bookmarks = bookmarks.map(bookmark => {
            if (!bookmark.id || (!bookmark.urn && !bookmark.url) || (bookmark.type === 'collab' && !bookmark.urn) || (bookmark.type === 'public' && !bookmark.url)) {
                throw SAMError.create(SAMErrorCode.BAD_REQUEST, '[Melville] BookmarkData must include `id` and either `urn` for collaborated libraries or `url` for public libraries.');
            }

            bookmark.type = bookmark.type || (bookmark.url ? 'public' : 'collab');
            return bookmark;
        });

        const body = { bookmarks };

        // Will return 201 even if the library is already bookmarked
        const response = await this._doPost(
            this._getEdgeUrl(`/api/v1/libraries/bookmarks`),
            { 'Content-Type': 'application/json' },
            JSON.stringify(body),
            [ 200, 201 ]
        );

        return await response.json();
    }

    /**
     * Get all bookmarks for the user from Melville.
     */
    async getBookmarks(): Promise<BookmarkData[]> {
        const response = await this._getResponse<any>(
            this._getEdgeUrl(`/api/v1/libraries/bookmarks?useCache=false&ussCache=false`),
            { headers: { 'Content-Type': JSON_MIME_TYPE, 'Cache-Control': 'no-cache, no-store, max-age=0' } });

        return await response.bookmarks;
    }


    /**
     * Unfollow aka unbookmark the library. (User can always bookmark again as long as they maintain access.)
     */
    async unbookmarkLibrary(bookmarkId: BookmarkData['id']): Promise<void> {
        await this._doDelete(
            this._getEdgeUrl(`/api/v1/libraries/bookmarks/${bookmarkId}`),
            { 'Content-Type': 'application/json' },
            [ 204 ]);
    }

    /**
     * Set metadata on a library - eg setting roles, renaming, etc.
     */
    async updateMetadata(libraryId: string, body: Partial<UpdateLibraryMetadataPayload>) {
        await this._doPut(
            this._getEdgeUrl(`/api/v1/libraries/${libraryId}/metadata`),
            { 'Content-Type': 'application/json' },
            JSON.stringify(body),
            [ 204, 200 ]);
    }

    /**
     * Search for Libraries (excluding elements).
     */
    async searchLibraries(searchQuery: string): Promise<LibrariesResponse> {
        const body: SearchLibraryRequest = {
            query_string: searchQuery,
            asset_type: [ 'library' ],
            selector: 'rendition_grid,collaboration,details'
        };
        const response = await this._doPost(
            this._getEdgeUrl(`/api/v1/libraries/search`),
            { 'Content-Type': 'application/json' },
            JSON.stringify(body),
            [ 200 ]);

        return await response.json();
    }

    /**
     * Search for next page of Libraries using the page link (excluding elements).
     */
    async searchLibrariesWithLink(searchQuery: string, pageLink: MelvilleLink): Promise<LibrariesResponse> {
        // Move the query params to the body to avoid extra preflight requests.
        const [ url, params ] = moveUrlQueryParamsToHeaders(pageLink.href);
        const body: SearchLibraryRequest = {
            query_string: searchQuery,
            asset_type: [ 'library' ],
            selector: 'rendition_grid,collaboration,details',
            start: params['start'],
            limit: params['limit']
        };
        const response = await this._doPost(
            this._getEdgeUrl(url),
            { 'Content-Type': 'application/json' },
            JSON.stringify(body),
            [ 200 ]);

        return await response.json();
    }

    async getRenditionTileImage(renditionUrl: string): Promise<Blob> {
        const newURL = new URL(renditionUrl);
        const response = await this._doGet(newURL.toString());
        return await response.blob();
    }

    async unpublishBrand(libraryId: string): Promise<void> {
        await this._doPost(
            this._getUrl(`/api/v1/brands/${libraryId}/unpublish`),
            { 'Content-Type': 'application/json' },
            undefined,
            [ 200 ]);
    }
}
