import type { SAM } from '@ccx-public/component-types';
import type { IComparatorMap } from '../core/ItemOrder';
import { compareStrings, compareValues, createItemOrderFactory } from '../core/ItemOrder';
import type Classroom from './Classroom';

export type ClassroomOrderField =
    | 'name'
    | 'created'
    | 'lastAccessed';

const OrderFieldToComparator: IComparatorMap<Classroom, ClassroomOrderField> = {
    name(a: Classroom, b: Classroom): number {
        return compareStrings(a.name, b.name);
    },
    created(a: Classroom, b: Classroom): number {
        let value;
        if (!a.created && !b.created) {
            value  = 0;
        } else if (!a.created) {
            value = 1; // Undefined date should be sorted last in ascending order
        } else if (!b.created) {
            value = -1;
        } else {
            value = compareValues(a.created.getTime(), b.created.getTime());
        }
        if (value === 0) {
            // Within the same created, sort by name
            return compareStrings(a.name, b.name);
        }
        return value;
    },
    lastAccessed(a: Classroom, b: Classroom): number {
        const aDate = a.lastAccessed;
        const bDate = b.lastAccessed;
        let value;
        if (!aDate && !bDate) {
            value = 0;
        } else if (!aDate) {
            value = 1; // Undefined date should be sorted last in ascending order
        } else if (!bDate) {
            value = -1;
        } else {
            // Natural comparator orders most recent first
            value = compareValues(bDate.getTime(), aDate.getTime());
        }
        if (value === 0) {
            // Within the same lastAccessed, sort by name
            return compareStrings(a.name, b.name);
        }
        return value;
    },
};

export default class ClassroomOrder extends createItemOrderFactory(OrderFieldToComparator) implements SAM.ClassroomOrder {
    static default = new ClassroomOrder('ascending', 'name');
}
