import type ItemBase from '../core/ItemBase';
import type { IItemFilter, ItemFilterRelation } from '../core/ItemFilter';

/**
* A special filter used as a default to simplify logic around filtering rather than having special cases
* for filter being undefined.
*/

export default class EverythingFilter<Item extends ItemBase> implements IItemFilter<Item> {

    constructor() {
    }

    get hash(): string {
        return 'everything';
    }

    matches(item: Item): boolean {
        return item !== undefined;
    }

    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    getRelationToFilter(other: IItemFilter<Item>): ItemFilterRelation {
        return 'subset';
    }

}
