import type { default as Library } from '../../models/Library';
import type { ElementData } from '../../models/data/ElementData';

import { mapResponseToElementData } from './utils/melvilleModelMappers';
import MoveCopyElementOperation from '../MoveCopyElementOperation';
import type CloudDriver from '.';

/**
 * A transfer operation is an operation to move or copy elements or groups.
 * Due to the cross-library nature of these operations, these operations may
 * need to act on two different libraries multiple times.
 */
export default class CloudMoveCopyElementOperation extends MoveCopyElementOperation<CloudDriver> {
    protected async _doMoveCopyRequest(
        isMove: boolean,
        sourceLibrary: Library,
        targetLibrary: Library,
        elementIds: string[]
    ): Promise<{ elements: ElementData[]; etag: string | null; sourceEtag: string | null }> {
        const sourceAssetId = this._library.assetId;
        const targetAssetId = targetLibrary.assetId;

        const response = await this._driver.fetch(`/api/v1/libraries/${targetAssetId}/elements`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'If-Match': targetLibrary.etag
            },
            body: JSON.stringify({
                [isMove ? 'self' : 'source']: {
                    id: sourceAssetId,
                    elements: elementIds,
                    'if-match': this._library.etag
                }
            })
        });

        const json = await response.json();

        return {
            elements: json.elements.map(mapResponseToElementData),
            etag: response.headers.get('etag'),
            sourceEtag: response.headers.get('x-source-etag')
        };
    }
}
