import ItemBase from '../core/ItemBase';
import {
    observable
} from '../core/decorators';
import type ISAMCorePrivate from '../core/ISAMCorePrivate';
import type { IAddressBook } from '../interface/AddressBookModel';
import ItemUpdater from '../core/ItemUpdater';
import PropertyUpdater from '../core/PropertyUpdater';
import type AddressBookContact from './AddressBookContact';


export default class AddressBook extends ItemBase {
    private _displayName: string = '';
    private _ownerId: string = '';

    constructor(_core: ISAMCorePrivate, id: string) {
        super(_core, id);
    }

    @observable
    get ident(): string {
        return this.id;
    }

    @observable
    get displayName(): string {
        return this._displayName;
    }

    @observable
    get ownerId(): string {
        return this._ownerId;
    }

    async getContactInAddressBook(adobeId: string): Promise<AddressBookContact> {
        return this._core.collaborationContext.getContactInAddressBook(this.ident, adobeId);
    }
}

export const AddressBookUpdater = new ItemUpdater<AddressBook, IAddressBook>({
    localItemType: AddressBook,
    remoteIdProperty: 'ident',
    propertyUpdater: new PropertyUpdater({
        _displayName: 'displayName',
        _ownerId: 'ownerId'
    })
});
