/**
 * In UXP `url.searchParams` does not save parameters correctly.
 * This function applies the search parameters to the URL in a UXP-safe way.
 * @see https://jira.corp.adobe.com/browse/UXP-19246
 */
export default function setURLSearchParams(url: URL, params: Record<string, string>) {
    // UXP's .searchParams doesn't save when the URL points to an external resource,
    // but we can create URLSearchParams unattached to a URL, and then apply it.
    const searchParams = new URLSearchParams(url.search);
    for (const [ key, value ] of Object.entries(params)) {
        searchParams.set(key, value);
    }
    url.search = searchParams.toString();
    return url;
}
