import type ISAMCorePrivate from '../core/ISAMCorePrivate';
import type ItemPool from '../core/ItemPool';
import type AdobeAsset from '../assets/AdobeAsset';
import { COLLABORATOR_CHANGED } from '@sam-js-src/collaboration/CollaboratorEvents';
import type { IInvitationPatch } from '../interface/InvitationModel';
import type { SAM } from '@ccx-public/component-types';
import { LazyLoadManager } from '@sam-js-src/core/decorators/LazyLoadManager';
import SAMError, { SAMErrorCode } from '@sam-js-src/core/SAMError';
import { getPrincipalCollaborators } from '@sam-js-src/utils/sharingUtils';

type AccessOptions = {
    role: 'viewer' | 'editor';
    canShare: boolean;
    canComment: boolean;
    canDiscover?: boolean; // TODO: Collaborator.canDiscover is not supported in CollaborationContext yet.
    password?: string;
}

export type PredefinedPrincipal = 'all' | 'authenticated' | 'allWithPassword' | 'orgEverybody';

// AccessOptions is not required for private mode.
export type UpdateAccessRequest =
  | { mode: 'private' }
  | ({ mode: PredefinedPrincipal } & AccessOptions);

const isTargetMatchPredefinedPrincipal = (target: UpdateAccessRequest, existingPredefinedPrincipal: SAM.Collaborator) => {
    if (target.mode === 'private') {
        return !existingPredefinedPrincipal; // private mode matches with empty predefinedPrincipal
    }
    if (target.mode === existingPredefinedPrincipal.id) {
        const collaborator = existingPredefinedPrincipal;
        const isCommentPermissionMatch = target.canComment === collaborator.commentPermissions?.includes('write');
        const isCanDiscoverMatch = target.canDiscover === undefined || target.canDiscover === collaborator.canDiscover;
        return target.role === existingPredefinedPrincipal.role
            && target.canShare === existingPredefinedPrincipal.canShare
            && isCommentPermissionMatch
            && isCanDiscoverMatch;
    }
    return false;
};

/**
 * This class is used to house the api for sharing an asset through ShareSheet.
 * https://wiki.corp.adobe.com/display/ACPCSDK/Share+Sheet+Invitation+SDK+Integration+into+SAM.js#ShareSheetInvitationSDKIntegrationintoSAM.js-SharingContext
 *
/**
 * @package -- These APIs are currently meant to be used by ShareSheet only or by internal classes within SAM.js.
 */

export default class SharingContext implements SAM.SharingContext {
    constructor(
        public _core: ISAMCorePrivate,
        readonly _assetPool: ItemPool<AdobeAsset>
    ) {}

    private async _getAdobeAsset(assetId: string): Promise<AdobeAsset> {
        const localAsset = this._assetPool.getLocalItemById<AdobeAsset>(assetId) ?? await (await this._core.getAssetContext()).getAssetWithCloudID(assetId);
        // wait for collaborators to load if needed
        await LazyLoadManager.fetchIfNeeded(localAsset, COLLABORATOR_CHANGED);
        return localAsset;
    }

    /**
     * @package -- Only to be used within SAM.js and ShareSheet.
     * Assumes that an asset can only have one predefinedPrincipal, which is what ShareSheet currently supports.
     * This method will replace the existing predefinedPrincipal with the one passed in the request param.
     * This method can also be used to update an existing predefinedPrincipal with new roles or permissions.
     * TODO: Handle password protected links Epic: SHARED-996
     * TODO: Handle org/authenticated editors Epic: SHARED-996
     */
    async updateAccess(assetId: string, request: UpdateAccessRequest): Promise<SAM.UpdateAccessResult> {
        const existingPredefinedPrincipals = await getPrincipalCollaborators(await this._getAdobeAsset(assetId));
        const patchEntries = [];
        const postEntries = []; // There should only be one post entry, but we'll use an array for consistency.

        if (request.mode === 'private') {
            // if target is to make it private, remove all predefined principals
            existingPredefinedPrincipals?.forEach(p => patchEntries.push({ id: p.id, action: 'remove' }));
        } else {
            const { mode, ...accessOptions } = request;
            // Remove all existing predefinedPrincipals that are not the target.
            const patchesToRemoveExistingPPs = existingPredefinedPrincipals.filter((collaborator) => mode !== collaborator.id).map(p => ({ id: p.id, action: 'remove' }));
            // If target predefinedPrincipal already exists, update it
            const ppToUpdate = existingPredefinedPrincipals.find((collaborator) => mode === collaborator.id);
            const isTargetMatch = ppToUpdate ? isTargetMatchPredefinedPrincipal(request, ppToUpdate) : null;

            // If there is a predefinedPrincipal to update add it to the list of patchEntries.
            if (ppToUpdate && !isTargetMatch) {
                // SHARED-8450: When only canDiscover differs, send minimal payload like legacy ShareSheet.
                // Legacy sends { action: 'update', canDiscover, id: 'orgEverybody' } only.
                const collaborator = ppToUpdate;
                const isCommentMatch = request.canComment === collaborator.commentPermissions?.includes('write');
                const onlyCanDiscoverChanged =
                    request.canDiscover !== undefined &&
                    request.canDiscover !== collaborator.canDiscover &&
                    request.role === ppToUpdate.role &&
                    request.canShare === ppToUpdate.canShare &&
                    isCommentMatch;

                const patchPayload = onlyCanDiscoverChanged
                    ? { id: ppToUpdate.id, action: 'update', canDiscover: request.canDiscover }
                    : { id: ppToUpdate.id, action: 'update', ...accessOptions };

                patchEntries.push(patchPayload);
            }
            if (!ppToUpdate) {
                // If the target predefinedPrincipal does not exist, we need to add it via POST
                postEntries.push({
                    recipient: mode,
                    ...accessOptions
                });
            }
            // If there are predefinedPrincipals to remove, add them to the patchEntries.
            if (patchesToRemoveExistingPPs.length > 0) {
                patchEntries.push(...patchesToRemoveExistingPPs);
            }
        }

        const returnPromise = Promise.all([
            patchEntries.length > 0 ? this._core.collaborationContext._modifyCollaborators(assetId, patchEntries as IInvitationPatch[]) : Promise.resolve(undefined),
            postEntries.length > 0 ? this._core.collaborationContext._addCollaborators(assetId, postEntries) : Promise.resolve(undefined)
        ]).then(([ patchResult, postResult ]) => {
            const patchResultMap = patchResult?.collaborators?.map(r => ({
                action: 'update' as const, // Cannot differentiate between update and remove
                id: r.id,
                statusCode: r.statusCode,
                statusText: r.statusText,
                errorSubcode: r.errorSubcode
            })) || [];
            // No need to map `patchResult.invitations` because that is for pending invitations which will never happen for predefinedPrincipals.

            let postResultMap = postResult?.addedCollaborators?.map(r => ({
                action: 'add' as const,
                id: r,
            })) || [];

            if (postResult?.failedCollaborators) {
                postResultMap = postResultMap.concat(
                    postResult.failedCollaborators.map(r => ({
                        action: 'add' as const,
                        id: r.recipient,
                        error: r.error
                    }))
                );
            }

            const result = [ ...patchResultMap, ...postResultMap ];

            // SHARED-8450: Throw when any collaborator update or remove failed (4xx/5xx) so UI can revert.
            const failedPatch = patchResultMap.find(r => typeof r.statusCode === 'number' && r.statusCode >= 400);
            if (failedPatch) {
                throw SAMError.create(
                    SAMErrorCode.BAD_REQUEST,
                    failedPatch.statusText || 'Update failed'
                );
            }

            return result;
        });

        return returnPromise;
    }
}
