export function getBlockTransferThreshold(links: AssetLinks, preferredThreshold?: number): number {
    // Get min and max single transfer sizes from links to use as limits.
    const blockInitLink = links[RelType.BLOCK_INITIALIZE] ? getLink(links, RelType.BLOCK_INITIALIZE) as AssetLinks[RelType.BLOCK_INITIALIZE] : undefined;
    const lowerLimit = blockInitLink ? blockInitLink['repo:minsingletransfersize'] : DEFAULT_MIN_SINGLE_TRANSFER_SIZE;
    const upperLimit = blockInitLink ? blockInitLink['repo:maxsingletransfersize'] : DEFAULT_MAX_SINGLE_TRANSFER_SIZE;
    // If provided, clamp preferred size to platform-defined limits to ensure a valid transfer size,
    // else return platform-defined upper limit.
    return preferredThreshold ? clamp(preferredThreshold, lowerLimit, upperLimit) : upperLimit;
}

