const DefaultAssetsListingOptions: AssetsListingOptions = {
    orderDirection: 'descending',
    orderBy: 'storage:deviceModifyDate',
    start: '',
    limit: 0
};

const DefaultVersionsListingOptions: VersionsListingOptions = {
    orderDirection: 'descending',
    orderBy: 'created',
    start: '',
    limit: 0,
    version: ''
};

function createVersionTemplate(options?: Partial<VersionsListingOptions>) {
    const userOptions: Partial<VersionsListingOptions> = { ...DefaultVersionsListingOptions, ...options };
    const templateValues: any = createPageTemplate(userOptions);

    templateValues.orderBy = getDirectionValue(userOptions);
    templateValues.resource = RelType.VERSION;
    return templateValues;
}

function createPageTemplate(options: Partial<AssetsListingOptions | VersionsListingOptions>) {
    const templateValues: any = {};
    const { start, limit, version } = options;
    if (start) {
        templateValues.start = start;
    }
    if (limit) {
        templateValues.limit = limit;
    }
    if (version) {
        templateValues.version = version;
    }
    return templateValues;
}

export function getDirectionValue<IOrderField>(userOptions: Partial<IListingOptions<IOrderField>>) {
    const directionFlag = userOptions.orderDirection === 'ascending' ? '+' : '-';
    return directionFlag + userOptions.orderBy;
}

export function getAssetsListingURL(links: any, options?: Partial<AssetsListingOptions>): string {
    const userOptions: Partial<AssetsListingOptions> = { ...DefaultAssetsListingOptions, ...options };
    const templateValues: any = createPageTemplate(userOptions);
    templateValues.orderBy = getDirectionValue(userOptions);
    templateValues.type = userOptions.type;
    templateValues.embed = JSON.stringify(userOptions.embed);

    // Currently service can only support one filter. Where possible, it will use server-side filtering so long as it
    // is compatible with client-side filtering. USS/PLS should support multiple filters, and R-API might in the future.
    const { assetTypes, excludeAssetTypes, assetSubTypes } = userOptions.filters || {};
    // Note: Clients cannot provide both exclude and include assetTypes. Exclude filter matches the most items.
    if (excludeAssetTypes?.length) {
        // exclude the first item from the first result, any additional excludes will be handled client-side
        templateValues.filter = `"repo:assetType"!="${excludeAssetTypes[0]}"`;
    } else if (assetTypes?.length === 1) {
        // prefer assetType filter over assetSubType filter, as assetType is a superset of assetSubType
        templateValues.filter = `"repo:assetType"=="${assetTypes[0]}"`;
    } else if (!assetTypes?.length && assetSubTypes?.length === 1) {
        templateValues.filter = `"repo:assetSubType"=="${assetSubTypes[0]}"`;
    }

    return getURLFromLinks(links, RelType.PAGE, templateValues);
}

export function getAssetVersionsListingURL(links: any, options?: Partial<VersionsListingOptions>): string {
    const templateValues = createVersionTemplate(options);
    return getURLFromLinks(links, RelType.PAGE, templateValues);
}

export type AssetRGNRelType = RelType.PRIMARY | RelType.REPO_METADATA | RelType.APP_METADATA;

export class TransferURLExpiredError extends Error {}

export default class AssetInterface extends InterfaceBase {
    protected _useHighPriorityRequestsIfEnabled = true;

    constructor(
        private _rapi: RepositoryInterface,
        private _assetId: string,
        private _links: AssetLinks,
        private _etag: string,
        private _version?: string
    ) {
        super(_rapi._core);
    }

    get assetID(): string {
        return this._assetId;
    }

    get links(): AssetLinks {
        return this._links;
    }

    get etag(): string {
        return this._etag;
    }

    protected async _getFetchOptionOverrides(href: string, options: IFetchOptions): Promise<{
        href: string;
        options: IFetchOptions
    }> {
        const overrides = await super._getFetchOptionOverrides(href, options);

        // SAMJS-1134: link-2023 temporarily behind a feature flag until service bugs are fixed
        if (!this._core._environment.getValue('FEATURE_FLAGS')?.['enable-rapi-link-2023']) {
            return overrides;
        }

        /**
         * See notes in {@link RepositoryInterface._getFetchOptionOverrides} about
         * `link-2023` direcitve and `link-options` header.
         */
        overrides.options.headers ??= {};
        const directive = overrides.options.headers.directive || '';
        overrides.options.headers.directive = [ 'link-2023', ...directive.split(',') ]
            .filter(s => s).join(',');
        const linkOptions = overrides.options.headers['link-options'] || '';
        overrides.options.headers['link-options'] = [ 'absolute-base', 'long-form-rel', ...linkOptions.split(',') ]
            .filter(s => s).join(',');

        return overrides;
    }

    async getChildAssets(options?: Partial<AssetsListingOptions>, resource?: Resource<Response>): Promise<DirectoryListingRepoMetadata> {
        const href = getAssetsListingURL(this._links, options);
        const response = await this._doGet(href, {
            // Ensure browser doesn't automatically add If-None-Match, otherwise
            // service may respond with cached data FROM ANOTHER USER.
            // https://jira.corp.adobe.com/browse/ACPCSS-5544
            // Also causes SAM-1813, SAM-2066
            headers: { ['Cache-Control']: 'no-cache, no-store, max-age=0' },
            resource
        });

        return response.json();
    }

    async getRepoMetadata(resource: Resource<RepositoryMetadata>): Promise<void> {
        const href = getURLFromLinks(this._links, RelType.REPO_METADATA);
        await this._doGet(href, { resource });

        // Note: Do NOT use the ETag header in the repo metadata response, because that's the ETag for the repo metadata
        // resource, not the asset itself. The ETag of the asset itself is inside the repo metadata response:
        this._etag = resource.data['repo:etag'];
    }

    async getEmbeddedMetadata(resource: Resource<object>): Promise<void> {
        const href = this.getURLWithVersion(this._links, RelType.EMBEDDED_METADATA);
        // Embedded metadata is returned as application/rdf+xml by default - switch to JSON-LD
        await this._doGet(href, { headers: { Accept: JSON_MIME_TYPE }, resource });
    }

    async getAppMetadata(resource: Resource<IAppMetadata>): Promise<void> {
        const href = this.getURLWithVersion(this._links, RelType.APP_METADATA);
        await this._doGet(href, { resource });
    }

    async patchAppMetadata(body: jsonpatch.OpPatch[]): Promise<Response> {
        const href = getURLFromLinks(this._links, RelType.APP_METADATA);
        return await this._doPatch(
            href,
            {
                'Content-Type': JSON_PATCH_MIME_TYPE
            },
            JSON.stringify(body),
            [ 204 ]
        );
    }

    async getEffectivePermissions(resource: Resource<SAM.Permission>): Promise<void> {
        const href = getURLFromLinks(this._links, RelType.AC_EFFECTIVE);
        await this._doGet(href, { resource });
    }

    async getAssetPolicy(): Promise<Response> {
        const href = getURLFromLinks(this._links, RelType.AC_POLICY);
        return await this._doGet(href);
    }

    async getManifest(resource: Resource<any>): Promise<void> {
        const href = this.getURLWithVersion(this._links, RelType.MANIFEST);
        const headers: { [s: string]: string } = {};

        await this._doGet(href, {
            headers,
            resource
        });
    }

    async getVersions(options?: Partial<VersionsListingOptions>): Promise<IAssetVersionResponse> {
        const href = getAssetVersionsListingURL(this._links, options);
        const response = await this._doGet(href);
        return response.json();
    }

    async getPerUserMetadata(resource: PerUserMetadataResource): Promise<void> {
        const href = getURLFromLinks(this._links, RelType.PERUSER_METADATA);
        await this._doGet(href, { headers: { 'Content-Type': JSON_MIME_TYPE }, resource });
    }

    async restoreVersionManifest(versionManifestLink: string) {
        // first fetch the version manifest
        const response = await this._doGet(versionManifestLink, {});
        const versionManifest = await response.json();

        //doput to current asset manifest url
        const assetManifest = getURLFromLinks(this.links, RelType.MANIFEST);
        await this._doPut(assetManifest, {
            'Content-Type': 'application/vnd.adobe.dcx-manifest+json',
            'If-Match': '*'
        }, JSON.stringify(versionManifest), [ 204 ]);
    }

    async getVersion(versionId: string): Promise<IAssetVersionResponse> {
        const href = getAssetVersionsListingURL(this._links, { version: versionId });
        const response = await this._doGet(href);
        return response.json();
    }

    async patchVersion(body?: IVersionPatchOperation[]): Promise<Response> {
        const href = getURLFromLinks(this.links, RelType.VERSION);
        const response = await this._doPatch(href, {
            'Content-Type': JSON_PATCH_MIME_TYPE
        }, JSON.stringify(body), [ 204 ]);
        return response;
    }

    async createFolder(relativePath: string, renameOnConflict: boolean = false): Promise<RepositoryMetadata | undefined> {
        const href = getURLFromLinks(this._links, RelType.CREATE, {
            path: relativePath,
            intermediates: 'true',
            respondWith: RelType.REPO_METADATA,
            nameConflictPolicy: renameOnConflict ? NameConflictPolicy.RENAME : NameConflictPolicy.CANCEL
        });
        const response = await this._doPost(href, {
            'Content-Type': FOLDER_TYPE
        }, undefined, [ 200, 201 ]);

        // when 200 that means asset created, but error while fetching metadata
        return response.status === 201 ? await response.json() : undefined;
    }

    private async extendTransferUrls(extendLink: string, useBlockStore: boolean = false, signal?: AbortSignal): Promise<IBlockUploadInfo> {
        const headers: HeaderMap = {};
        if (useBlockStore) {
            headers['directive'] = 'use-block-store';
        }
        const response = await this._doPost(extendLink, headers, undefined, [ 200 ], false, undefined, signal);
        return await response.json();
    }

    private async _uploadIndividualBlock(href: string, file: Blob, start: number, end: number, useBlockStore?: boolean, signal?: AbortSignal): Promise<Response> {
        const headers: HeaderMap = {};
        return await this._doPut(href, headers, file.slice(start, end),
            useBlockStore ? [ 200, 412 ] : [ 200 ],
            true, {
                handleError: async (response) => {
                    if (response.status === 403) {
                        const errorText = await response.text();
                        if (errorText.includes('<Message>Request has expired</Message>')) {
                            // Throw a unique error to handle the expired transfer url in _blockUpload
                            throw new TransferURLExpiredError('Transfer URL has expired');
                        }
                    }
                },
                signal
            });
    }

    async _blockUpload(
        file: Blob,
        relativePath: string,
        mediaType: string,
        renameOnConflict: boolean = false,
        isUpdate: boolean,
        useBlockStore?: boolean,
        milestoneProperties?: MilestoneProperties,
        signal?: AbortSignal,
        onPhaseChange?: (phaseInfo: UploadPhaseInfo) => void
    ): Promise<RepositoryMetadata | undefined> {
        if (signal?.aborted) {
            const error = new Error('Upload aborted');
            error.name = 'AbortError';
            throw error;
        }

        // Notify that we're initializing the upload
        onPhaseChange?.({ phase: UploadPhase.INITIALIZING, canCancel: true });

        const uploadInfoResult = await this.getBlockUploadInfo(relativePath, file.size, isUpdate, mediaType, useBlockStore, renameOnConflict, milestoneProperties, signal);
        const blockSize = uploadInfoResult.initResponse['repo:blocksize'];
        const size = file.size;
        const totalBlocks = Math.ceil(size / blockSize);
        let blockIndex = 0;

        // Notify that we're starting the upload phase
        onPhaseChange?.({ phase: UploadPhase.UPLOADING, canCancel: true });

        // Only send a max of 3 blocks simultaneously, so the browser's request queue doesn't get
        // over-saturated, and intermittent outages (like wifi blips) will only cause up to 3 requests to
        // need retries.
        const MAX_SIMULTANEOUS_BLOCKS = 3;
        const MAX_RETRIES = 3; // Add maximum retry count
        let retryCount = 0;

        while (blockIndex < totalBlocks) {
            if (signal?.aborted) {
                const error = new Error('Upload aborted');
                error.name = 'AbortError';
                throw error;
            }
            try {
                // Calculate how many blocks to upload in this batch
                const blocksInBatch = Math.min(MAX_SIMULTANEOUS_BLOCKS, totalBlocks - blockIndex);

                // Create and execute promises for this batch of blocks
                const blockPromises = Array.from({ length: blocksInBatch }, (_, index) => {
                    const currentBlockIndex = blockIndex + index;
                    return this._uploadIndividualBlock(
                        uploadInfoResult.transferInfo[currentBlockIndex].url.href,
                        file,
                        currentBlockIndex * blockSize,
                        Math.min((currentBlockIndex + 1) * blockSize, size),
                        useBlockStore,
                        signal
                    );
                });

                // Wait for all blocks in this batch to complete
                await Promise.all(blockPromises);
                blockIndex += blocksInBatch;
                retryCount = 0; // Reset retry count on successful batch
            } catch (e) {
                // If any block in the batch failed due to expired URLs
                if (e instanceof TransferURLExpiredError) {
                    retryCount++;
                    if (retryCount > MAX_RETRIES) {
                        throw SAMError.create(SAMErrorCode.INTERNAL_ERROR, 'Maximum retry attempts exceeded for block upload');
                    }

                    // Get new URLs for all remaining blocks
                    const url = getURLFromLinks(uploadInfoResult.initResponse._links, RelType.BLOCK_EXTEND, { size: String(size) });
                    const newBlockInfo = await this.extendTransferUrls(url, useBlockStore, signal);

                    // Update the transfer info with new URLs
                    uploadInfoResult.transferInfo = newBlockInfo._links[RelType.BLOCK_TRANSFER].map((link, index) => {
                        const start = index * blockSize;
                        const end = Math.min(size, start + blockSize);
                        return { url: link, start, end };
                    });

                    // Resume the current batch with new URLs
                    continue;
                } else {
                    throw e;
                }
            }
        }

        if (signal?.aborted) {
            const error = new Error('Upload aborted');
            error.name = 'AbortError';
            throw error;
        }

        // Notify that we're entering the finalization phase (cannot be cancelled)
        onPhaseChange?.({ phase: UploadPhase.FINALIZING, canCancel: false });

        const result = await this.finalizeBlockUpload(uploadInfoResult.finalizeHref, uploadInfoResult.initResponse, isUpdate, useBlockStore);

        // Notify that upload is complete
        onPhaseChange?.({ phase: UploadPhase.COMPLETE, canCancel: false });

        return result;
    }

    /**
     * Imports a file into the repository.
     *
     * @param file - The file blob or URL to import
     * @param relativePath - The name to give the imported file
     * @param renameOnConflict - Specifies if name conflict resolution should be handled by ACP
     * @param mediaType - Optional media type of the file
     * @param preferredBlockTransferThreshold - Size threshold for block transfer (defaults to DEFAULT_MAX_SINGLE_TRANSFER_SIZE)
     * @param useBlockStore - If true, uses block store for upload
     * @param milestoneProperties - Optional milestone properties to set on the file
     * @param signal - Optional AbortSignal to cancel the upload
     * @param onPhaseChange - Optional callback to track upload phase changes
     * @returns Promise resolving to the repository metadata of the imported file
     */
    async importFile(
        file: Blob,
        relativePath: string,
        renameOnConflict: boolean,
        mediaType?: string,
        preferredBlockTransferThreshold: number = DEFAULT_MAX_SINGLE_TRANSFER_SIZE,
        useBlockStore?: boolean,
        milestoneProperties?: MilestoneProperties,
        signal?: AbortSignal,
        onPhaseChange?: (phaseInfo: UploadPhaseInfo) => void
    ): Promise<RepositoryMetadata | undefined> {
        // check if the size of the file to be imported is greater than maximum allowed transfer size.
        const blockUploadTransferThreshold = getBlockTransferThreshold(this._links, preferredBlockTransferThreshold);

        if (file.size >= blockUploadTransferThreshold) {
            // The platform requires a block upload for components greater than threshold.
            // See https://git.corp.adobe.com/pages/CAF/api-spec/#block-upload
            return this._blockUpload(file,
                relativePath,
                mediaType ?? file.type,
                renameOnConflict,
                false,
                useBlockStore,
                milestoneProperties,
                signal,
                onPhaseChange);
        }

        if (signal?.aborted) {
            const error = new Error('Upload aborted');
            error.name = 'AbortError';
            throw error;
        }

        // Notify that we're starting the upload phase (direct upload for small files).
        onPhaseChange?.({ phase: UploadPhase.UPLOADING, canCancel: true });

        const versionHistoryPatch = milestoneProperties ? {
            'milestone:label': milestoneProperties.label,
            ...(milestoneProperties.description ? { 'milestone:description': milestoneProperties.description } : {})
        } : {};

        const href = getURLFromLinks(this._links, RelType.CREATE, {
            path: relativePath,
            respondWith: RelType.REPO_METADATA,
            nameConflictPolicy: renameOnConflict ? NameConflictPolicy.RENAME : NameConflictPolicy.CANCEL,
            ...(milestoneProperties ? { versionHistoryPatch } : {})
        });

        // It should be noted, that defaulting to file.type is not always correct especially for certain file types.
        // For example, the file.type of a .psd is the empty string, and when the empty string is supplied as the
        // 'Content-Type' the upload will fail with the 400 status. We may be able to remove the 'Content-Type'
        // altogether after https://jira.corp.adobe.com/browse/ACPCSS-13879 is addressed.
        const headers: HeaderMap = {
            'Content-Type': mediaType ?? file.type,
            'directive': 'alt-primary'
        };

        if (signal?.aborted) {
            const error = new Error('Upload aborted');
            error.name = 'AbortError';
            throw error;
        }

        const response = await this._doPost(href, headers, file, [ 200, 201 ], false, undefined, signal);

        // Notify that upload is complete
        onPhaseChange?.({ phase: UploadPhase.COMPLETE, canCancel: false });

        // when 200 that means asset created, but error while fetching metadata
        return response.status === 201 ? await response.json() : undefined;
    }

    async updateFile(
        file: Blob,
        mediaType?: string,
        preferredBlockTransferThreshold: number = DEFAULT_MAX_SINGLE_TRANSFER_SIZE,
        useBlockStore: boolean = false
    ): Promise<RepositoryMetadata | undefined> {
        // check if the size of the file to be imported is greater than maximum allowed transfer size.
        const blockUploadTransferThreshold = getBlockTransferThreshold(this._links, preferredBlockTransferThreshold);

        if (file.size >= blockUploadTransferThreshold) {
            // The platform requires a block upload for components greater than threshold.
            // See https://git.corp.adobe.com/pages/CAF/api-spec/#block-upload
            return this._blockUpload(file, '', mediaType ?? file.type, false, true, useBlockStore);
        } else {
            const { metaData } = await this.commitFileChanges(file, this.etag);
            if (!metaData) {
                // If we didn't get metadata in the response, fetch it
                const href = getURLFromLinks(this._links, RelType.REPO_METADATA);
                const response = await this._doGet(href);
                return response.json();
            }
            return metaData;
        }
    }

    async getBlockUploadInfo(
        name: string,
        size: number,
        isUpdate: boolean,
        mediaType?: string,
        useBlockStore?: boolean,
        renameOnConflict?: boolean,
        /**
         * When included this file will be created with the latest version as a milestone.
         */
        milestoneProperties?: MilestoneProperties,
        signal?: AbortSignal
    ): Promise<IBlockUploadInfoResult> {
        const initialBlockUploadHref = getURLFromLinks(this._links, RelType.BLOCK_INITIALIZE);
        const initBody: any = {
            'repo:size': size,
            'repo:blocksize': BLOCK_SIZE,
            'repo:reltype': RelType.PRIMARY,
            'dc:format': mediaType // Required for updates, optional for new uploads
        };

        const headers: HeaderMap = {
            'Content-Type': BULK_TRANSFER_MIME_TYPE
        };

        if (useBlockStore) {

            // Remove the repo:blocksize prop when using block store, otherwise the service will throw an error.
            delete initBody['repo:blocksize'];
            headers['directive'] = 'use-block-store';
        }

        const initResponse = await this._doPost(initialBlockUploadHref, headers, JSON.stringify(initBody), [ 200 ], false, undefined, signal);
        const blockUploadInfo: IBlockUploadInfo = await initResponse.json();
        const { 'repo:blocksize': blockSize, _links } = blockUploadInfo;

        // Calculate the start and end of each block.
        const transferInfo = _links[RelType.BLOCK_TRANSFER].map((link, index) => {
            const start = index * (useBlockStore ? blockSize : BLOCK_SIZE);
            const end = Math.min(size, start + (useBlockStore ? blockSize : BLOCK_SIZE));
            return { url: link, start, end };
        });

        const versionHistoryPatch = milestoneProperties ? {
            'milestone:label': milestoneProperties.label,
            ...(milestoneProperties.description ? { 'milestone:description': milestoneProperties.description } : {})
        } : {};

        const finalizeHref = getURLFromLinks(_links, RelType.BLOCK_FINALIZE, {
            respondWith: RelType.REPO_METADATA,
            nameConflictPolicy: renameOnConflict ? NameConflictPolicy.RENAME : NameConflictPolicy.CANCEL,
            ...(!isUpdate ? { path: name } : {}),
            ...(milestoneProperties ? { versionHistoryPatch } : {})
        });

        return {
            transferInfo,
            finalizeHref,
            blockSize,
            initResponse: blockUploadInfo
        };
    }

    /**
     * Finalizes a block upload operation by sending the finalize request to the server.
     * This is an internal method used by _blockUpload to complete the upload process.
     *
     * @param finalizeHref - The URL to send the finalize request to
     * @param initResponse - The initial block upload info response containing block size and links
     * @param isUpdate - Whether this is an update operation (true) or a new file upload (false)
     * @param useBlockStore - If true, uses "block store" variant of block uploads and includes the use-block-store directive
     * @returns Promise resolving to the repository metadata of the uploaded file, or undefined for updates
     */
    async finalizeBlockUpload(finalizeHref: string, initResponse: IBlockUploadInfo, isUpdate: boolean, useBlockStore?: boolean): Promise<RepositoryMetadata | undefined> {
        const headers: HeaderMap = {
            'Content-Type': BULK_TRANSFER_MIME_TYPE
        };

        // Add directive when useBlockStore is true
        if (useBlockStore) {
            headers['directive'] = 'use-block-store,alt-primary';
        } else {
            headers['directive'] = 'alt-primary';
        }

        const response = await this._doPost(finalizeHref, headers, JSON.stringify(initResponse), [ 200, 201 ], false, undefined);
        return isUpdate ? undefined : response.json();
    }

    /**
     * Gets a presigned URL for downloading a block of the asset.
     * @param url - The URL to get the presigned URL from
     * @param presignedUrlExpirationSeconds - Time-to-live for the presigned URL in seconds. If not provided, uses service default.
     * @param convertToDesktop - Whether to convert the cloud asset to a desktop asset
     * @returns Promise resolving to the presigned URL
     */
    async getBlockDownloadURL(url: string, presignedUrlExpirationSeconds?: number, convertToDesktop?: boolean): Promise<string> {
        const headers: HeaderMap = {};
        if (presignedUrlExpirationSeconds !== undefined) {
            headers['Presigned-URL-TTL'] = presignedUrlExpirationSeconds.toString();
        }
        if (convertToDesktop) {
            headers['directive'] = 'alt-primary';
        }
        const response = await this._doGet(url, { headers });
        const json = await response.json();
        if (!json?.href) {
            throw SAMError.create(SAMErrorCode.INTERNAL_ERROR, 'Cannot get block download URL');
        }
        return json.href;
    }

    async getContent(resource: Resource<Blob>): Promise<void> {
        const href = this.getURLWithVersion(this._links, RelType.PRIMARY);
        await this._doGet(href, { resource });
    }

    async getResourceGenerationNumber(relType: AssetRGNRelType): Promise<string | undefined> {
        const href = getURLFromLinks(this._links, relType);
        const response = await this._doHead(href);
        return response.headers.get('resource-generation') ?? undefined;
    }

    async commitFileChanges(file: Blob, localETag?: string): Promise<{ metaData: RepositoryMetadata, eTag: string | null}> {
        const href = getURLFromLinks(this._links, RelType.PRIMARY);
        const headers: HeaderMap = {
            'Content-type': file.type
        };
        localETag && (headers['If-Match'] = localETag);
        const response = await this._doPut(href, headers, file, [ 200, 201, 204 ]);
        return { metaData: response.status === 201 ? await response.json() : undefined, eTag: response.headers.get('ETag') };
    }

    /**
     * Restore the asset - will rely on ACP's name conflict resolution to resolve any conflicts.
     * @param {string} _name - (deprecated) will be removed in the future, currently ignored
     */
    async restore(_name: string): Promise<RepositoryMetadata> {
        const operation: IRestoreOperation = {
            op: 'restore',
            target: { 'repo:assetId': this.assetID },
            nameConflictPolicy: NameConflictPolicy.RENAME
        };

        const repoMetadata = (await this.runOperation(operation)).asset!;
        return repoMetadata;
    }

    async discard(): Promise<RepositoryMetadata> {
        const operation: IDiscardOperation = {
            op: 'discard',
            target: { 'repo:assetId': this.assetID }
        };
        const { asset } = await this.runOperation(operation);
        return asset!;
    }

    async runOperation(op: IOperation): Promise<ISAMOperationResult> {
        const response = await this._rapi.runOperation(op);
        const { asset, error } = response[0];
        if (!(asset || error)) {
            throw SAMError.wrapErrorIfNeeded(SAMErrorCode.UNKNOWN, 'Missing Asset metadata in operation response', error);
        } else if (error) {
            throw error;
        }
        return response[0];
    }

    async runOperationWithEmptyResponse(op: IOperation): Promise<void> {
        await this._rapi.runOperation(op);
    }


    async getRendition(size: number, type: string, version: string, cacheBuster?: string): Promise<Blob> {
        const renditionURL = getURLFromLinks(
            this._links,
            RelType.RENDITION, {
                size: String(size),
                type,
                // Note: some links will not have a parameter token for version, and will instead
                // have a static version in the link. This is by design.
                version,
            }
        );

        const url = new URL(renditionURL);
        if (cacheBuster) {
            url.searchParams.set('_cacheBuster', cacheBuster);
        }

        // Since we have a version, the resource is supposed to be immutable, so specifying 'force-cache'
        // ensures that the browser will always use the cached version of the rendition if it exists.
        // The service specifies "max-age"/"immutable" in its cache-control headers, but some
        // browsers (perhaps older ones) don't appear to consistently respect those headers. See SAMJS-956.
        const response = await this._doGet(url.toString(), { cache: 'force-cache' });
        return response.blob();
    }

    /**
     * See {@link AdobeAsset#getCustomRendition} for full documentation.
     */
    async getCustomRendition({
        size = THUMBNAIL_SIZE,
        type = RenditionType.PNG,
        urlTemplateOptions = {},
        additionalHeaders
    }: {
        size?: number;
        type?: string;
        urlTemplateOptions?: ICustomRenditionURLTemplateOpts;
        additionalHeaders?: ICustomRenditionHeaders;
    }): Promise<Response> {
        const url = getURLFromLinks(
            this._links,
            RelType.RENDITION, {
                size: String(size),
                type,
                ...urlTemplateOptions
            }
        );
        return await this._doGet(url, { headers: additionalHeaders });
    }

    /**
     * See {@link AdobeAsset#getAllCustomRenditions} for full documentation.
     */
    async getAllCustomRenditions({
        type,
        urlTemplateOptions = {},
        additionalHeaders
    }: {
        type?: string;
        urlTemplateOptions?: ICustomRenditionURLTemplateOpts;
        additionalHeaders?: ICustomRenditionHeaders;
    }): Promise<Response> {
        const url = type ? getURLFromLinks(
            this._links,
            RelType.RENDITION, {
                type,
                ...urlTemplateOptions
            }
        ) : getURLFromLinks(this._links, RelType.RENDITION, { ...urlTemplateOptions });
        return await this._doGet(url, { headers: additionalHeaders });
    }

    async getAccessControlList(): Promise<IAccessControlResponse> {
        const accessControlHref = getURLFromLinks(this._links, RelType.AC_POLICY);
        const response = await this._doGet(accessControlHref, {
            headers: {
                'Content-Type': 'application/vnd.adobecloud.policy+json',
                'If-Match': '*'
            }
        });
        const responseJson = await response.json();
        const accessControlResponse: IAccessControlResponse = {
            'etag': response.headers.get('ETag') || '',
            'repo:acl': responseJson['repo:acl']
        };
        return accessControlResponse;
    }

    /**
     * @pacakge - used internally
     */
    public _getACPatchData(ace: AdobeACE | AdobeACEMetadata): {} {
        return {
            'repo:principal': ace.principal,
            'repo:privileges': ace.privileges,
            'repo:modifier': ace.modifier,
            'repo:inheritance': ace.inheritance,
            'repo:relations': ace.relations
        };
    }

    async addAccessControlEntries(aces: AdobeACEMetadata[], aclEtag: string): Promise<void> {
        const acesJSONPatch: jsonpatch.AddPatch[] = aces.map((ace: AdobeACEMetadata) => {
            return {
                op: 'add',
                path: `/repo:acl/-`,
                value: this._getACPatchData(ace)
            };
        });

        await this._patchACL(acesJSONPatch, aclEtag);
    }

    async updateAccessControlList(aces: AdobeACE[], aclEtag: string): Promise<void> {
        const acesJSONPatch: jsonpatch.ReplacePatch[]  = aces.map((ace: AdobeACE) => {
            return {
                op: 'replace',
                path: `/repo:acl/${ace.id}`,
                value: this._getACPatchData(ace)
            };
        });

        await this._patchACL(acesJSONPatch, aclEtag);
    }

    async deleteAccessControlEntries(aces: AdobeACE[], aclEtag: string): Promise<void> {
        const acesJSONPatch: jsonpatch.RemovePatch[] = aces.map((ace: AdobeACE) => {
            return {
                op: 'remove',
                path: `/repo:acl/${ace.id}`,
                value: this._getACPatchData(ace)
            };
        });

        await this._patchACL(acesJSONPatch, aclEtag);
    }

    async setEditingInheritanceRestricted(restrictEdit: boolean, addCurrentUserAsEditor?: boolean): Promise<void> {
        // API documentation: https://developers.corp.adobe.com/acp/acl-front-service/documentation/src/main/docs/swagger.json#operation/jsonPatchPolicy
        const userId = this._core._environment.getValue('USER_ID');
        if (restrictEdit) {
            // NOTE: attempting to add these ACEs when they are already set has no effect
            const addPatches: jsonpatch.AddPatch[] = [ {
                op: 'add',
                // Index for 'add' probably doesn't matter
                path: '/repo:acl/0',
                value: DENY_EDIT_ACE
            }, {
                op: 'add',
                path: '/repo:acl/1',
                value: DENY_SHARE_ACE
            } ];
            if (addCurrentUserAsEditor) {
                const userACEs = getRestrictEditUserGrantACEs(userId);
                addPatches.push({ op: 'add', path: '/repo:acl/2', value: userACEs[0] });
                addPatches.push({ op: 'add', path: '/repo:acl/3', value: userACEs[1] });
            }
            await this._patchACL(addPatches);
        } else {
            // Find the index of the deny ACEs. This is critical to ensure only the desired ACEs get removed.
            const { policyResponse, denyEditAceIndex, denyShareAceIndex } = await this._getEditingInheritanceRestrictedInfo();
            // If either or both ACE is missing, the toggle is not on
            if (denyEditAceIndex < 0 || denyShareAceIndex < 0) {
                return;
            }
            const removePatches: jsonpatch.RemovePatch[] = [ {
                op: 'remove',
                path: `/repo:acl/${denyShareAceIndex}`
            }, {
                op: 'remove',
                path: `/repo:acl/${denyEditAceIndex}`
            } ];
            // The patches must be sorted by index descending or else the wrong items will be removed, because they
            // are applied in order. If we have acl = [A, B, C] and try to remove index 0 before 1, it will first remove
            // A, making B be index 0; removing index 1 after that will erroneously remove C. Instead, removing 1 first
            // will result in [A, C] and then removing index 0 will leave the desired [C] remaining.
            removePatches.sort((ace1, ace2) => ace1.path < ace2.path ? 0 : -1);
            await this._patchACL(removePatches, policyResponse.headers.get('etag') || undefined);
        }
    }

    private async _patchACL(patches: jsonpatch.OpPatch[], etag?: string): Promise<void> {
        const url = getURLFromLinks(this._links, RelType.AC_POLICY);
        await this._doPatch(url,
            {
                'Content-Type': 'application/json-patch+json',
                'If-Match': etag
            },
            JSON.stringify(patches),
            [ 200 ]
        );
    }

    async getEditingInheritanceRestricted(): Promise<boolean> {
        const { denyEditAceIndex, denyShareAceIndex } = await this._getEditingInheritanceRestrictedInfo();
        // both must be present for the toggle to be on
        return denyEditAceIndex >= 0 && denyShareAceIndex >= 0;
    }

    private async _getEditingInheritanceRestrictedInfo() {
        const policyResponse = await this.getAssetPolicy();
        const acl = (await policyResponse.json() as IACPolicyResponse)['repo:acl'];
        // Note: array order does not matter. To count as being on, all properties in DENY_EDIT_ACE and DENY_SHARE_ACE
        // must be present, but additional properties can be present that are not in the constants.
        const denyEditAce = acl.find(ace => isDeepEqual(DENY_EDIT_ACE, ace, true, true));
        const denyShareAce = acl.find(ace => isDeepEqual(DENY_SHARE_ACE, ace, true, true));
        return {
            policyResponse,
            denyEditAceIndex: acl.indexOf(denyEditAce as any),
            denyShareAceIndex: acl.indexOf(denyShareAce as any)
        };
    }

    /**
     * Helper method to get URL from links with version parameter if available
     */
    private getURLWithVersion(links: any, key: RelType, params?: Parameters<typeof getURLFromLinks>[2]): string {
        return getURLFromLinks(links, key, {
            ...params,
            ...(this._version !== undefined ? { version: this._version } : {})
        });
    }

    // update last access date is taken care of by the PLS API
    // this is only used for clearing the last access date
    async removeLastAccessed(): Promise<Response> {
        const href = getURLFromLinks(this._links, RelType.PERUSER_METADATA);
        const bodyData: jsonpatch.OpPatch[] = [];
        bodyData.push({
            op: 'remove',
            path: '/shell:lastAccessDate'
        });

        return await this._doPatch(
            href,
            {
                'Content-Type': JSON_PATCH_MIME_TYPE,
                // Required for making future migration of these calls to Label Service smoother
                // https://wiki.corp.adobe.com/display/CSA/Proposal%3A+Personalized+Listing+Service+interaction+with+PUPA+Service
                // We need to notify clients to add the header in access-control-request-headers header
                'X-Metadata-Field': 'lastAccessDate'
            },
            JSON.stringify(bodyData),
            [ 204 ]);

    }
}
