import type ClassroomsInterface from '../interface/ClassroomsInterface';
import type { IItemLoader, IItemLoaderOptions, ILoadedPage } from '../core/ItemLoader';
import type { ISAMCorePrivate } from '../indexPrivate';
import type ClassroomMember from './ClassroomMember';
import type Classroom from '../classrooms/Classroom';
import { ClassroomMemberUpdater } from './ClassroomMember';
import type { ClassroomMemberConfig } from './ClassroomMemberSource';
import type ClassroomMemberFilter from '../classrooms/ClassroomMemberFilter';
import { ClassroomMemberRole } from '../interface/ClassroomMemberModel';

export default class ClassroomMemberListLoader implements IItemLoader<ClassroomMemberConfig> {
    private _core: ISAMCorePrivate;
    private _classroomsInterface: ClassroomsInterface;

    constructor({ core, classroomsInterface }: {core: ISAMCorePrivate, classroomsInterface: ClassroomsInterface}) {
        this._core = core;
        this._classroomsInterface = classroomsInterface;
    }
    async loadPage(options: IItemLoaderOptions<ClassroomMemberConfig>): Promise<ILoadedPage<ClassroomMemberConfig>> {
        return await this._loadPage(options);
    }

    private async _loadPage(options: IItemLoaderOptions<ClassroomMemberConfig>): Promise<ILoadedPage<ClassroomMemberConfig>> {
        const { filter } = options;
        const classroomMemberFilter = filter as ClassroomMemberFilter;
        let items: ClassroomMember[] = [];
        // Classroom service only supports returning teachers as part of classrooms for now.
        // All members and students can be lazy loaded separately.
        if (classroomMemberFilter.role === ClassroomMemberRole.TEACHER) {
            const cachedClassroom = this._core.classroomContext._classroomPool.toArray<Classroom>().find(
                (classroom) => classroom.id === classroomMemberFilter.classroomId
            );
            const cachedMembers = cachedClassroom?._cachedMembersList;
            if (cachedMembers?.length) {
                // Ensure teachers are only collected in the case the classroom service
                // does begin to include other members in the future
                items = cachedMembers.filter((member) => member.role === classroomMemberFilter.role);
            }
        }
        // The members for the current filter are not cached, fetch from theAPI
        if (!items || items.length === 0) {
            const result = await this._classroomsInterface.getClassroomMembers(classroomMemberFilter.classroomId, classroomMemberFilter.role);
            const session = this._core.classroomContext._classroomMemberPool.createLoaderUpdateSession<ClassroomMember>(Date.now());
            items = ClassroomMemberUpdater.updateRemoteItems(session, result);
            session.commit();
        }

        return {
            items,
            total: items.length,
            loadNextPage: undefined,
        };
    }
}
