import type { IImplicitFilter } from '../core/ItemFilter';
import type { default as AdobeAsset } from './AdobeAsset';
import type { IImplicitDirectoryListingFilterOptions } from './ImplicitDirectoryListingFilter';
import ImplicitDirectoryListingFilter from './ImplicitDirectoryListingFilter';
import type { IAdobeAssetFilterOptions } from './AdobeAssetFilter';
import AdobeAssetFilter from './AdobeAssetFilter';
import type { IImplicitAdobeAssetFilterBaseOptions } from './ImplicitAdobeAssetFilterBase';


export type IImplicitDirectoryListingAssetFilterOptions = IAdobeAssetFilterOptions & IImplicitDirectoryListingFilterOptions & IImplicitAdobeAssetFilterBaseOptions;

export default class ImplicitDirectoryListingAssetFilter implements IImplicitFilter<AdobeAsset> {
    private readonly _implicitDirectoryListingFilter?: ImplicitDirectoryListingFilter;
    private readonly _adobeAssetFilter?: AdobeAssetFilter;

    constructor(options: IImplicitDirectoryListingAssetFilterOptions) {
        const { asset, mediaTypes, excludeMediaTypes, ...baseOpts } = options;
        // ImplicitDirectoryListingFilter handles the ImplicitAdobeAssetFilterBase cases
        this._implicitDirectoryListingFilter = new ImplicitDirectoryListingFilter({ asset, ...baseOpts });
        if (mediaTypes || excludeMediaTypes) {
            this._adobeAssetFilter = new AdobeAssetFilter({
                mediaTypes,
                excludeMediaTypes
            });
        }
    }

    matches(item: AdobeAsset): boolean {
        if (this._adobeAssetFilter && !this._adobeAssetFilter.matches(item)) {
            return false;
        }

        if (this._implicitDirectoryListingFilter && !this._implicitDirectoryListingFilter.matches(item)) {
            return false;
        }

        // it matched both filters above
        return true;
    }

    get mediaTypes(): Set<string> | undefined {
        return this._adobeAssetFilter?.mediaTypes;
    }
}
